insert into public.languages (id, code, name, native_name, writing_direction, tts_locale, is_available) values ('eg', 'eg', 'Église copte', 'Église copte orthodoxe', 'ltr', 'fr-FR', true) on conflict (id) do update set name = excluded.name, native_name = excluded.native_name, writing_direction = excluded.writing_direction, tts_locale = excluded.tts_locale, is_available = excluded.is_available;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g01.pourquoi_histoire', 'eg', 'grammar', 'knowledge', 'Pourquoi étudier l''histoire de l''Église', 1, '{}'::text[], 1, '{"rule": {"summary": "L''histoire de l''Église éclaire le présent : elle explique pourquoi nous croyons ce que nous croyons, dans le décor de l''Empire romain, et elle va du premier au vingtième siècle.", "explanation": "Étudier l''histoire n''est pas apprendre des dates : c''est comprendre les causes. Les dogmes sont souvent nés d''une hérésie qui obligeait l''Église à préciser sa foi, et les schismes ne se comprennent qu''avec leur contexte politique, social et économique. Le repère de départ est la venue de Jésus-Christ, qui coupe l''histoire en deux (ère chrétienne). Le décor de départ est l''Empire romain : il occupe Jérusalem et relie tout le monde méditerranéen par ses routes et sa langue grecque.", "pattern": "Histoire → contexte → dogmes : on comprend la foi en sachant quand, qui et pourquoi.", "examples": [{"text": "Le calendrier compte avant et après Jésus-Christ.", "translation": "La venue du Christ partage le temps en deux époques."}, {"text": "Le dogme de la Trinité est précisé pour répondre à des erreurs.", "translation": "Beaucoup de dogmes répondent à une hérésie."}, {"text": "Jérusalem est occupée par les Romains au temps de Jésus.", "translation": "L''Empire romain est le décor des premiers siècles."}, {"text": "Les vingt siècles de l''Église sont découpés en grandes phases.", "translation": "La première phase couvre les trois premiers siècles."}], "commonErrors": [{"wrong": "L''histoire de l''Église, c''est apprendre des dates par cœur.", "right": "C''est comprendre pourquoi les événements ont eu lieu.", "why": "Le but est de relier les faits, pas de les réciter."}, {"wrong": "Une hérésie et un schisme, c''est la même chose.", "right": "L''hérésie touche la doctrine ; le schisme touche l''unité entre Églises.", "why": "On peut être séparé sans différer sur la foi, et l''inverse."}], "tip": "Quand tu rencontres un dogme, demande-toi : quelle erreur ou quelle crise l''a rendu nécessaire ?"}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g02.pentecote_communaute', 'eg', 'grammar', 'knowledge', 'La Pentecôte et la première communauté de Jérusalem', 1, array['eg.g01.pourquoi_histoire']::text[], 1, '{"rule": {"summary": "Après la croix, la Résurrection et l''Ascension, l''Esprit Saint descend à la Pentecôte (vers 30) : l''Église naît à Jérusalem et vit en communauté, dans la prière, le partage et la fraction du pain.", "explanation": "Au début des années 30, Jésus est crucifié sous Ponce Pilate et ses disciples se cachent. Il ressuscite le troisième jour, monte au ciel (Ascension) et leur confie la mission. Réunis dans la chambre haute (environ cent vingt personnes), ils reçoivent l''Esprit à la Pentecôte. Pierre prêche : trois mille personnes se convertissent. La première communauté de Jérusalem est fidèle à l''enseignement des apôtres, à la communion fraternelle, à la fraction du pain et à la prière, et met ses biens en commun.", "pattern": "Croix (début des années 30) → Résurrection → Ascension → Pentecôte (naissance de l''Église) → première communauté.", "examples": [{"text": "Jésus est crucifié sous Ponce Pilate, au début des années 30.", "translation": "La mort du Christ est un fait historique daté par Rome."}, {"text": "Environ cent vingt personnes prient dans la chambre haute.", "translation": "Le point de départ est un tout petit groupe."}, {"text": "À la Pentecôte, trois mille personnes se convertissent.", "translation": "La tradition place là les débuts de l''Église."}, {"text": "La communauté est fidèle à la fraction du pain.", "translation": "L''eucharistie est le cœur de la vie chrétienne dès l''origine."}], "commonErrors": [{"wrong": "L''Église naît à la naissance de Jésus.", "right": "La tradition place sa naissance à la Pentecôte.", "why": "C''est l''Esprit Saint reçu à la Pentecôte qui lance la mission des apôtres."}, {"wrong": "Les premiers chrétiens ont tout de suite quitté le judaïsme.", "right": "Ils sont juifs, et la séparation sera longue.", "why": "Le christianisme a mis longtemps à se séparer du judaïsme."}], "tip": "Retiens la suite : croix, Résurrection, Ascension, Pentecôte. Chaque étape ouvre la suivante."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g03.etienne_paul_missions', 'eg', 'grammar', 'knowledge', 'Étienne, saint Paul et les premières missions', 2, array['eg.g02.pentecote_communaute']::text[], 1, '{"rule": {"summary": "Après les premiers conflits et le martyre d''Étienne (vers 35), la persécution disperse les chrétiens. Saul, le persécuteur, devient Paul : avec Barnabé il annonce l''Évangile aux synagogues puis aux païens, à Antioche et jusqu''à Rome.", "explanation": "La première communauté connaît d''abord un conflit interne : les hellénistes se plaignent pour leurs veuves, et sept hommes sont choisis pour le service. L''un d''eux, Étienne, est lapidé vers 35 : c''est le premier martyr. La persécution disperse les chrétiens, et l''Évangile se répand hors de Jérusalem. Saul, pharisien zélé, rencontre le Christ sur la route de Damas et devient Paul. Avec Barnabé, il va d''abord dans les synagogues, est rejeté, puis se tourne vers les païens avec grand succès. À Antioche, les disciples sont appelés chrétiens pour la première fois.", "pattern": "Conflit des veuves → sept hommes → Étienne (vers 35) → dispersion → Paul (vers 35) → synagogues puis païens → Antioche.", "examples": [{"text": "Les hellénistes se plaignent que leurs veuves soient oubliées.", "translation": "Premier conflit interne, réglé en choisissant sept hommes."}, {"text": "Étienne est lapidé vers 35 : il est le premier martyr.", "translation": "Le mot martyr vient du grec « témoin »."}, {"text": "Sur la route de Damas, Saul devient Paul.", "translation": "Le persécuteur devient l''apôtre des nations."}, {"text": "À Antioche, on parle pour la première fois de chrétiens.", "translation": "Le nom naît à l''extérieur du judaïsme."}], "commonErrors": [{"wrong": "Paul fait partie des Douze.", "right": "Paul est apôtre, mais il n''est pas l''un des Douze.", "why": "Il est appelé par le Christ après la Résurrection, vers 35."}, {"wrong": "La persécution a étouffé l''Église.", "right": "Elle a dispersé les chrétiens, qui ont annoncé l''Évangile ailleurs.", "why": "Chaque persécution a étendu la mission."}, {"wrong": "Les chrétiens se sont appelés chrétiens dès la Pentecôte.", "right": "Le nom apparaît à Antioche.", "why": "Avant, on parle de disciples, de frères, de ceux de la Voie."}], "tip": "Étienne meurt, Paul se convertit : la mort d''un martyr sert de semence."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g04.concile_jerusalem', 'eg', 'grammar', 'knowledge', 'Le concile de Jérusalem', 2, array['eg.g03.etienne_paul_missions']::text[], 1, '{"rule": {"summary": "Vers 49, le concile de Jérusalem, premier concile de l''histoire, décide que la circoncision n''est pas obligatoire pour les païens convertis : c''est la première rupture avec le judaïsme et le modèle de tous les conciles.", "explanation": "À Antioche, des judéo-chrétiens venus de Jérusalem affirment que la circoncision est nécessaire au salut. Paul et Barnabé montent à Jérusalem. Après le débat, où Pierre rappelle que l''Esprit a été donné aux païens, Jacques conclut : la circoncision n''est plus obligatoire. On demande seulement de s''abstenir de la viande offerte aux idoles, du sang, des bêtes étouffées et de l''immoralité. L''enjeu est vital : le salut vient du Christ, pas de la Loi, et le christianisme est une foi pour tous.", "pattern": "Conflit à Antioche → Paul et Barnabé à Jérusalem → débat (Pierre, Paul, Jacques) → décision (vers 49) → lettre.", "examples": [{"text": "Des judéo-chrétiens disent à Antioche : sans circoncision, pas de salut.", "translation": "C''est la question qui déclenche le concile."}, {"text": "Pierre rappelle que Dieu a donné l''Esprit aux païens sans les circoncire.", "translation": "Son témoignage pèse lourd dans la décision."}, {"text": "Jacques, chef de l''Église de Jérusalem, conclut le débat.", "translation": "Il appuie la décision sur les prophètes."}, {"text": "Vers 49, la circoncision n''est plus obligatoire pour les païens.", "translation": "Première rupture avec la communauté juive."}], "commonErrors": [{"wrong": "Le concile de Jérusalem s''est tenu à Nicée.", "right": "Le concile de Jérusalem a lieu vers 49 ; Nicée est de 325.", "why": "Ce sont deux conciles très éloignés dans le temps."}, {"wrong": "Les païens convertis n''ont aucune règle à suivre.", "right": "On leur demande de s''abstenir de la viande offerte aux idoles, du sang, des bêtes étouffées et de l''immoralité.", "why": "Ces règles aident à vivre ensemble avec les judéo-chrétiens."}, {"wrong": "Jacques de Jérusalem est le frère de Jean.", "right": "Jacques, frère de Jean, est mort vers 44 ; Jacques de Jérusalem a conclu le concile.", "why": "Il y a deux Jacques parmi les apôtres."}], "tip": "Concile de Jérusalem = 49 = circoncision. Retiens l''idée : le salut vient du Christ, pas de la Loi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g05.persecutions_premier_siecle', 'eg', 'grammar', 'knowledge', 'Les persécutions du premier siècle', 2, array['eg.g04.concile_jerusalem']::text[], 1, '{"rule": {"summary": "Au premier siècle, l''Église est persécutée : d''abord par les autorités juives (Étienne, Jacques vers 44), puis par Rome (Néron en 64, Domitien à la fin du siècle), et la chute de Jérusalem en 70 bouleverse le monde juif et chrétien.", "explanation": "Vers 44, Hérode Agrippa fait décapiter Jacques, frère de Jean. En 62, Jacques, chef de l''Église de Jérusalem, est martyrisé. En 64, un grand incendie ravage Rome ; Néron accuse les chrétiens, qui sont torturés. Pierre et Paul sont martyrisés à Rome vers 67. En 66, les Juifs se révoltent contre Rome ; en 70, Titus prend Jérusalem et détruit le Temple. Sous Domitien (81-96), nouvelle persécution. Rome soupçonne les chrétiens parce qu''ils refusent d''adorer l''empereur.", "pattern": "44 Jacques (frère de Jean) → 62 Jacques de Jérusalem → 64 Néron → vers 67 Pierre et Paul → 70 chute de Jérusalem → Domitien.", "examples": [{"text": "Vers 44, Hérode Agrippa fait décapiter Jacques, frère de Jean.", "translation": "Il est le premier apôtre martyr."}, {"text": "En 64, Néron accuse les chrétiens de l''incendie de Rome.", "translation": "Première grande persécution romaine."}, {"text": "En 70, Titus détruit le Temple de Jérusalem.", "translation": "Les Juifs sont dispersés dans le monde."}, {"text": "Domitien règne de 81 à 96.", "translation": "Une nouvelle persécution touche les chrétiens."}], "commonErrors": [{"wrong": "Néron a persécuté tous les chrétiens de l''Empire.", "right": "La persécution de 64 touche surtout Rome.", "why": "Les grandes persécutions de tout l''Empire viendront au IIIe siècle."}, {"wrong": "Jacques, frère de Jean, est le chef de l''Église de Jérusalem.", "right": "Le chef de l''Église de Jérusalem est un autre Jacques, martyrisé en 62.", "why": "Il y a deux Jacques : l''un décapité vers 44, l''autre martyrisé en 62."}, {"wrong": "Les persécutions viennent uniquement de Rome.", "right": "Au début, elles viennent surtout des autorités juives.", "why": "Étienne et Jacques sont tués sous l''influence des autorités juives."}], "tip": "44, 62, 64, 67, 70 : cinq dates pour ne pas se perdre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g06.ecrits_heresies', 'eg', 'grammar', 'knowledge', 'Les écrits du premier siècle et les premières hérésies', 3, array['eg.g05.persecutions_premier_siecle']::text[], 1, '{"rule": {"summary": "Jésus n''a rien écrit : son enseignement passe d''abord par la tradition orale, puis est mis par écrit (épîtres, quatre évangiles) pour résister à de fausses doctrines : les judaïsants et le gnosticisme, auquel saint Jean répond.", "explanation": "Pendant une génération, l''enseignement est oral. Avec la mort des témoins, la dispersion des Églises et les faux docteurs, il est mis par écrit dans la seconde moitié du siècle : les épîtres de Paul (quatorze dans la tradition), les évangiles de Matthieu, Marc, Luc et Jean, les Actes. Vers la fin du siècle, le gnosticisme sépare le monde en deux et méprise le corps ; le docétisme en tire que Jésus n''a eu que l''apparence d''un homme. Jean répond : « Le Verbe s''est fait chair ».", "pattern": "Parole → écrit : épîtres, évangiles, Actes → réponse aux hérésies : judaïsants, gnose (Jean).", "examples": [{"text": "Jésus n''a laissé aucun écrit.", "translation": "Son enseignement est d''abord transmis oralement."}, {"text": "Les quatre évangiles sont Matthieu, Marc, Luc et Jean.", "translation": "Évangile signifie « bonne nouvelle »."}, {"text": "Les gnostiques croient que le corps est une prison.", "translation": "Pour eux, Dieu ne peut pas se faire homme."}, {"text": "Jean écrit : « Le Verbe s''est fait chair ».", "translation": "Il répond au docétisme."}], "commonErrors": [{"wrong": "Jésus a écrit un livre.", "right": "Jésus n''a laissé aucun écrit.", "why": "Ce sont les disciples qui ont écrit, après avoir transmis oralement."}, {"wrong": "Le gnosticisme est la foi des apôtres.", "right": "Le gnosticisme est une hérésie : il nie l''Incarnation.", "why": "Il ne peut pas admettre que Dieu se soit fait homme."}, {"wrong": "Les évangiles ont été écrits dans la même année.", "right": "Ils s''étalent dans la seconde moitié du premier siècle.", "why": "Matthieu, Marc et Luc d''abord, Jean à la fin du siècle."}], "tip": "Oral, puis écrit : et si on écrit, c''est pour garder fidèlement ce qu''on a reçu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g07.apotres_sieges', 'eg', 'grammar', 'knowledge', 'Les apôtres et les sièges apostoliques', 3, array['eg.g06.ecrits_heresies']::text[], 1, '{"rule": {"summary": "Après la Pentecôte, les apôtres se dispersent : Pierre, Paul et Jean vers l''Asie Mineure et Rome, André vers la Grèce, Thomas vers l''Inde, Matthieu vers l''Éthiopie, Barthélemy vers l''Arménie, Marc vers l''Égypte. Les Églises qu''ils fondent sont des sièges apostoliques, reliés aux apôtres par la succession apostolique.", "explanation": "Jésus a envoyé les apôtres vers toutes les nations. Selon la tradition, Pierre prêche en Asie Mineure puis à Rome ; Paul en Judée, Asie Mineure, Grèce et Rome ; Jean en Asie Mineure ; André en Grèce ; Thomas en Inde ; Matthieu en Éthiopie ; Barthélemy en Arménie ; Marc en Égypte. Jean, mort vers l''an 100, est le dernier apôtre vivant. Un siège apostolique est une Église fondée par un apôtre ou un de ses proches, avec des évêques qui lui succèdent par l''imposition des mains : la succession apostolique garantit que la foi enseignée est celle des origines.", "pattern": "Apôtre → pays → Église fondée → siège apostolique → évêques successeurs.", "examples": [{"text": "Thomas porte l''Évangile en Inde, selon la tradition.", "translation": "Les chrétiens de Malabar l''honorent comme fondateur."}, {"text": "Jean s''installe en Asie Mineure et meurt vers l''an 100.", "translation": "Il est le dernier apôtre vivant."}, {"text": "Rome est un siège apostolique : Pierre et Paul y ont été martyrisés.", "translation": "Le prestige du siège vient de ses fondateurs."}, {"text": "Alexandrie est un siège apostolique fondé par Marc.", "translation": "Le pape copte est son successeur."}], "commonErrors": [{"wrong": "Seule Rome est un siège apostolique.", "right": "Jérusalem, Antioche, Rome, Éphèse, Alexandrie le sont toutes.", "why": "Chacune a été fondée par un apôtre ou un de ses proches."}, {"wrong": "Toutes les traditions sur les voyages des apôtres sont certaines.", "right": "Beaucoup reposent sur la tradition, à prendre avec prudence.", "why": "Les sources écrites sont souvent tardives."}], "tip": "Siège = fauteuil de l''évêque ; apostolique = fondé par un apôtre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g08.marc_alexandrie', 'eg', 'grammar', 'knowledge', 'Saint Marc et l''Église d''Alexandrie', 3, array['eg.g07.apotres_sieges']::text[], 1, '{"rule": {"summary": "Saint Marc, évangéliste et disciple de Pierre, apporte l''Évangile à Alexandrie vers le milieu du siècle, y fonde l''Église, y est martyrisé vers 68 et en devient le premier pape : l''Église copte est apostolique.", "explanation": "Alexandrie, fondée par Alexandre le Grand, est une grande ville grecque où vit une forte communauté juive et où la Bible a été traduite en grec (Septante). Marc, cousin de Barnabé, compagnon de Paul puis de Pierre, y arrive vers 49-50 ; il guérit le cordonnier Anianus, qui devient son premier converti. Marc fonde l''Église, ordonne Anianus évêque, puis meurt martyr vers 68. Ses reliques sont emportées à Venise en 828 ; une partie revient au Caire en 1968. Copte signifie « égyptien » : l''Église copte est l''Église d''Égypte fondée par saint Marc.", "pattern": "Marc (cousin de Barnabé) → Alexandrie (vers 49-50) → Anianus → Église fondée → martyre (vers 68) → reliques : 828, 1968.", "examples": [{"text": "Marc guérit la main du cordonnier Anianus.", "translation": "Anianus est le premier converti d''Alexandrie."}, {"text": "Marc est traîné dans les rues d''Alexandrie vers 68.", "translation": "Il devient martyr et premier pape d''Alexandrie."}, {"text": "En 828, les reliques sont emportées à Venise.", "translation": "En 1968, une partie revient au Caire."}, {"text": "Copte vient du grec Aigyptios.", "translation": "L''Église copte est l''Église des Égyptiens."}], "commonErrors": [{"wrong": "Marc fait partie des Douze.", "right": "Marc est évangéliste, disciple des apôtres, que la tradition copte appelle aussi apôtre.", "why": "Il n''est pas dans la liste des Douze."}, {"wrong": "L''Église copte a été fondée par Constantin.", "right": "Elle a été fondée par saint Marc au Ier siècle.", "why": "Constantin ne règne qu''au IVe siècle."}, {"wrong": "Copte veut dire chrétien.", "right": "Copte veut dire égyptien.", "why": "Le mot vient du grec Aigyptios."}], "tip": "Marc → Anianus → Alexandrie : trois noms pour retenir la fondation."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g09.releve_des_apotres', 'eg', 'grammar', 'knowledge', 'La relève des apôtres et la défense de la foi', 2, '{}'::text[], 2, '{"rule": {"summary": "Quand les derniers apôtres meurent, l''Église protège la foi par les Écritures, la sainte tradition et la succession apostolique des évêques.", "explanation": "Au début du IIe siècle, plus aucun témoin direct du Christ n''est en vie, alors que l''Église grandit et que les interprétations se multiplient. Des hérésies apparaissent : gnosticisme, docétisme, marcionisme, montanisme. Pour garder la vérité, l''Église s''appuie sur trois choses : les Écritures, la tradition reçue des apôtres, et les évêques, qui en sont les successeurs. Les Écritures seules ne suffisent pas, car chacun peut citer un verset à sa façon.", "pattern": "Fin des apôtres → hérésies → Écritures + tradition + évêques successeurs des apôtres.", "examples": [{"text": "Début du IIe siècle : la génération des apôtres s''est éteinte.", "translation": "Il faut désormais transmettre la foi sans témoin direct."}, {"text": "Quatre hérésies dominent : gnosticisme, docétisme, marcionisme, montanisme.", "translation": "Chacune déforme un point essentiel de la foi."}, {"text": "Succession apostolique : une suite ininterrompue d''évêques depuis les apôtres.", "translation": "Elle garantit la continuité de l''enseignement."}], "commonErrors": [{"wrong": "Les Écritures suffisent à elles seules à trancher.", "right": "Elles s''accompagnent de la tradition et des évêques.", "why": "Les hérétiques citent aussi l''Écriture : il faut un enseignement vivant qui la lit comme les apôtres."}, {"wrong": "Une hérésie est une religion étrangère.", "right": "Une hérésie est une déformation de la foi chrétienne.", "why": "L''hérétique reste dans le vocabulaire chrétien mais change l''enseignement reçu."}], "tip": "Trois appuis : le Livre (Écritures), la voix (tradition), les gardiens (évêques)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g10.sieges_apostoliques', 'eg', 'grammar', 'knowledge', 'Les quatre sièges apostoliques', 2, array['eg.g09.releve_des_apotres']::text[], 2, '{"rule": {"summary": "Quatre sièges apostoliques font autorité sur la foi : Rome, Alexandrie, Antioche et Jérusalem, car leur chaîne d''évêques remonte à un apôtre.", "explanation": "Un siège apostolique est un siège dont le premier évêque est un apôtre. Comme la relève y a été assurée depuis la source, on lui reconnaît une autorité plus grande dans les questions de la foi. On en compte quatre : Rome (Pierre et Paul), Alexandrie (Marc), Antioche (Pierre) et Jérusalem (Jacques). Notre Église copte est l''Église d''Alexandrie, fondée par saint Marc.", "pattern": "Rome = Pierre et Paul ; Alexandrie = Marc ; Antioche = Pierre ; Jérusalem = Jacques.", "examples": [{"text": "Alexandrie est fondée par saint Marc.", "translation": "C''est le siège de l''Église copte."}, {"text": "Antioche : c''est là qu''on dit « chrétiens » pour la première fois.", "translation": "Le mot apparaît en Actes 11, 26."}, {"text": "Jérusalem : saint Jacques en est le premier évêque.", "translation": "C''est la première Église, née autour des apôtres."}], "commonErrors": [{"wrong": "Seule Rome est un siège apostolique.", "right": "Rome, Alexandrie, Antioche et Jérusalem le sont toutes.", "why": "Chacune a été fondée par un apôtre, donc chacune a une autorité apostolique."}, {"wrong": "Saint Marc a fondé l''Église d''Antioche.", "right": "Saint Marc a fondé l''Église d''Alexandrie.", "why": "Antioche est liée à Pierre."}], "tip": "Associe chaque ville à un nom : R-PP, A-M, An-P, J-J."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g11.peres_apostoliques', 'eg', 'grammar', 'knowledge', 'Les Pères apostoliques', 2, array['eg.g10.sieges_apostoliques']::text[], 2, '{"rule": {"summary": "Les Pères apostoliques (Clément de Rome, Ignace d''Antioche, Polycarpe de Smyrne) ont reçu la tradition des apôtres et l''ont transmise à l''Église par leurs lettres.", "explanation": "Après les apôtres viennent les Pères apostoliques, proches de la tradition apostolique qu''ils ont reçue directement. Ils écrivent à des chrétiens pour les enseigner et lutter contre les hérésies. Clément de Rome écrit aux Corinthiens vers 96, Ignace d''Antioche rédige sept lettres en route vers le martyre à Rome vers 110, Polycarpe de Smyrne est disciple de Jean et écrit aux Philippiens.", "pattern": "Clément (Rome, Corinthiens) ; Ignace (Antioche, sept lettres) ; Polycarpe (Smyrne, Philippiens).", "examples": [{"text": "Clément écrit aux Corinthiens vers 96.", "translation": "Il rappelle que les apôtres ont prévu la relève des évêques."}, {"text": "Ignace écrit sept lettres en route vers Rome.", "translation": "Il insiste sur l''unité et sur le vrai corps du Christ."}, {"text": "Polycarpe est disciple de Jean.", "translation": "Il relie l''âge des apôtres à celui d''Irénée."}], "commonErrors": [{"wrong": "Les Pères apostoliques écrivent aux païens.", "right": "Ils écrivent à des chrétiens.", "why": "Ce sont les apologistes qui s''adressent aux païens."}, {"wrong": "Ignace est évêque de Smyrne.", "right": "Ignace est évêque d''Antioche ; Polycarpe est évêque de Smyrne.", "why": "Associe chaque homme à sa ville."}], "tip": "Clément = Corinthiens ; Ignace = sept lettres ; Polycarpe = Philippiens."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g12.persecutions_ichthus', 'eg', 'grammar', 'knowledge', 'Les persécutions du IIe siècle et le poisson ICHTHYS', 2, array['eg.g11.peres_apostoliques']::text[], 2, '{"rule": {"summary": "Au IIe siècle, l''Empire persécute les chrétiens parce qu''ils refusent le culte de l''empereur ; ils se reconnaissent grâce au poisson ICHTHYS.", "explanation": "Les chrétiens refusent d''adorer l''empereur et les dieux de l''Empire, et on les accuse de crimes imaginaires. Selon la tradition, Trajan ordonne la 3e persécution, Marc Aurèle la 4e et Septime Sévère la 5e. Les martyrs, comme Polycarpe ou ceux de Lyon, préfèrent mourir plutôt que de renier le Christ. Pour se reconnaître, les chrétiens dessinent un poisson : en grec ICHTHYS, initiales de Jésus Christ, Fils de Dieu, Sauveur.", "pattern": "Trajan = 3e ; Marc Aurèle = 4e ; Septime Sévère = 5e ; ICHTHYS = Jésus Christ Fils de Dieu Sauveur.", "examples": [{"text": "Pline demande à Trajan comment traiter les chrétiens.", "translation": "Trajan répond de ne pas les rechercher, mais de punir ceux qui sont dénoncés."}, {"text": "Polycarpe : « Voilà 86 ans que je le sers. »", "translation": "Il refuse de renier le Christ."}, {"text": "Blandine, esclave, est martyre à Lyon en 177.", "translation": "La foi donne du courage aux plus humbles."}], "commonErrors": [{"wrong": "Les chrétiens sont persécutés parce qu''ils prient pour l''empereur.", "right": "Ils sont persécutés parce qu''ils refusent son culte.", "why": "Ils prient pour lui, mais refusent de l''adorer."}, {"wrong": "Le poisson est le signe de Pierre le pêcheur.", "right": "ICHTHYS est le sigle de Jésus Christ Fils de Dieu Sauveur.", "why": "Chaque lettre du mot grec est une initiale."}], "tip": "Trajan 3, Marc Aurèle 4, Septime Sévère 5 : l''ordre suit les empereurs."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g13.apologistes', 'eg', 'grammar', 'knowledge', 'Les apologistes : Justin et Tertullien', 2, array['eg.g12.persecutions_ichthus']::text[], 2, '{"rule": {"summary": "Les apologistes (Justin Martyr, Tertullien) défendent la foi chrétienne devant les païens, alors que les Pères apostoliques enseignent les chrétiens.", "explanation": "Face aux accusations des païens (athéisme, crimes secrets), les apologistes écrivent à ceux de l''extérieur. Justin, philosophe converti à Naplouse et martyr vers 165, montre que le Christ, Verbe de Dieu, est le couronnement de la quête des philosophes. Tertullien, juriste de Carthage, écrit l''Apologétique en 197 et le fameux « le sang des martyrs est une semence de chrétiens ».", "pattern": "Pères apostoliques → chrétiens ; apologistes → païens. Justin = semences du Verbe ; Tertullien = Apologétique.", "examples": [{"text": "Justin écrit des Apologies à l''empereur.", "translation": "Il plaide pour que les chrétiens ne soient pas condamnés sans jugement."}, {"text": "Tertullien écrit l''Apologétique en 197.", "translation": "Il y défend les chrétiens devant les magistrats."}, {"text": "« Le sang des martyrs est une semence de chrétiens. »", "translation": "Les persécutions font grandir l''Église au lieu de la détruire."}], "commonErrors": [{"wrong": "Les apologistes écrivent pour les chrétiens.", "right": "Ils écrivent pour les païens.", "why": "Apologia signifie défense devant les gens extérieurs."}, {"wrong": "Justin et Tertullien sont des Pères apostoliques.", "right": "Ils sont des apologistes.", "why": "Ils sont de la génération suivante, qui défend la foi au dehors."}], "tip": "Apostoliques : à la maison. Apologistes : à la place publique."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g14.gnosticisme_docetisme', 'eg', 'grammar', 'knowledge', 'Gnosticisme et docétisme', 3, array['eg.g13.apologistes']::text[], 2, '{"rule": {"summary": "Le gnosticisme sauve par une connaissance secrète et méprise la matière ; le docétisme en tire que le corps du Christ n''était qu''une apparence. L''Église répond : création bonne, Incarnation réelle.", "explanation": "Gnosis veut dire connaissance. Pour les gnostiques, la matière est mauvaise, le monde est l''œuvre d''un démiurge, et l''élite est sauvée par une connaissance secrète. De là vient le docétisme : le Christ n''aurait eu qu''un corps apparent. L''Église répond avec Ignace (le corps du Christ est réel) et Irénée de Lyon (enseignement public des évêques, reçu des apôtres).", "pattern": "Gnose : connaissance secrète + matière mauvaise → docétisme : corps apparent → réponse : Ignace, Irénée.", "examples": [{"text": "Valentin et Basilide enseignent à Alexandrie.", "translation": "Le gnosticisme concerne directement l''Église d''Égypte."}, {"text": "Docétisme vient de dokein, « sembler ».", "translation": "Le Christ aurait seulement semblé avoir un corps."}, {"text": "Irénée écrit Contre les hérésies vers 180.", "translation": "Il oppose l''enseignement public des évêques aux doctrines secrètes."}], "commonErrors": [{"wrong": "Les gnostiques sont une Église chrétienne séparée.", "right": "Le gnosticisme est un mélange de philosophies et de vocabulaire chrétien.", "why": "Il n''est pas une Église mais un courant qui déforme l''Évangile."}, {"wrong": "Le docétisme dit que le Christ n''est pas Dieu.", "right": "Le docétisme dit que le Christ n''a pas eu un vrai corps.", "why": "Il nie l''humanité réelle du Christ, pas sa divinité."}], "tip": "Gnose = savoir caché. Docète = corps fantôme."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g15.marcion_montan', 'eg', 'grammar', 'knowledge', 'Marcionisme et montanisme', 3, array['eg.g14.gnosticisme_docetisme']::text[], 2, '{"rule": {"summary": "Marcion oppose un Dieu de justice à un Dieu d''amour et rejette l''Ancien Testament ; Montanus annonce une nouvelle prophétie et la fin des temps. L''Église répond : un seul Dieu, une Révélation complète.", "explanation": "Marcion (Rome, vers 140) croit en deux dieux et ne garde que Luc et dix lettres de Paul. Montanus (Phrygie, vers 170) se dit organe du Paraclet et exige continence et martyre. L''Église condamne les deux : un seul Dieu est auteur des deux Testaments, et la Révélation est complète en Christ et les apôtres. Marcion pousse l''Église à préciser quels livres elle reçoit : le canon.", "pattern": "Marcion = deux dieux, rejet de l''Ancien Testament. Montan = nouvelle prophétie, Paraclet, fin des temps.", "examples": [{"text": "Marcion ne garde que Luc et dix lettres de Paul.", "translation": "Il force l''Église à préciser sa Bible."}, {"text": "Montanus se dit organe du Paraclet.", "translation": "Il prétend parler au nom de l''Esprit Saint."}, {"text": "Polycarpe à Marcion : « Premier-né de Satan. »", "translation": "Il refuse tout compromis sur la foi."}], "commonErrors": [{"wrong": "Marcion rejette le Nouveau Testament.", "right": "Marcion rejette l''Ancien Testament et presque tout le Nouveau.", "why": "Il garde seulement Luc et dix lettres de Paul."}, {"wrong": "Le montanisme est une hérésie sur le Christ.", "right": "Le montanisme est une hérésie sur l''Esprit et la prophétie.", "why": "Il prétend que l''Esprit donne de nouvelles révélations par Montanus."}], "tip": "Marcion = deux dieux. Montan = nouvelle prophétie."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g16.canon_regle_de_foi', 'eg', 'grammar', 'knowledge', 'Canon, règle de foi et Alexandrie de Démétrios', 3, array['eg.g15.marcion_montan']::text[], 2, '{"rule": {"summary": "L''Église fixe le canon des Écritures, s''appuie sur la règle de foi et la succession apostolique, et Alexandrie, sous Démétrios, organise les fêtes et l''école.", "explanation": "Face à Marcion et aux gnostiques, l''Église précise quels livres sont Écriture : le canon, selon l''origine apostolique, l''accord avec la foi, l''usage dans les Églises. Elle confesse la règle de foi, résumé de la foi du baptême qui deviendra le Credo. À Alexandrie, Démétrios (189) fixe le calendrier des fêtes, place le carême avant la semaine sainte et soutient l''école théologique.", "pattern": "Canon (Écritures) + règle de foi + succession apostolique ; Démétrios 189 : Pâques, carême, école d''Alexandrie.", "examples": [{"text": "Irénée défend les quatre Évangiles vers 180.", "translation": "Quatre comme les quatre vents."}, {"text": "367 : Athanase donne la liste des 27 livres du Nouveau Testament.", "translation": "Notre Église contribue à fixer le canon."}, {"text": "Démétrios met le carême juste avant la semaine sainte.", "translation": "Alexandrie fixe le calendrier de la foi."}], "commonErrors": [{"wrong": "Le canon est le choix de l''empereur.", "right": "Le canon est reconnu par l''Église selon l''origine apostolique, l''accord avec la foi et l''usage.", "why": "L''Église reçoit les livres, elle ne les invente pas."}, {"wrong": "La règle de foi remplace l''Écriture.", "right": "La règle de foi est la clé pour lire l''Écriture.", "why": "Elle donne le plan de la mosaïque."}], "tip": "Canon = règle des livres. Règle de foi = résumé de la foi. Démétrios = Pâques et école."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g17.chretiens_mal_vus', 'eg', 'grammar', 'knowledge', 'Pourquoi persécute-t-on les chrétiens ?', 1, '{}'::text[], 3, '{"rule": {"summary": "Au IIIe siècle, les chrétiens sont mal vus dans l''Empire : ils refusent le culte impérial, vivent en secret et subissent des rumeurs. Plusieurs empereurs publient des édits qui les menacent.", "explanation": "L''empereur voit dans le refus du culte impérial une perte d''autorité. Les chrétiens ne participent pas aux sacrifices publics, donc on les prend pour de mauvais citoyens. Leur foi pratiquée en secret renforce la méfiance, et la foule les soupçonne d''anthropophagie ou de meurtre rituel. Les philosophes les jugent athées. Des édits imposent de sacrifier, mais leur application varie selon les régions.", "pattern": "Refus du culte impérial → soupçon → secret → rumeurs → édits et persécutions.", "examples": [{"text": "Les chrétiens refusent de participer au culte impérial.", "translation": "C''est le point de départ de l''hostilité des autorités."}, {"text": "On les accuse d''anthropophagie et de meurtre rituel.", "translation": "Ces rumeurs sont nées du secret et de l''incompréhension."}, {"text": "Les philosophes les appellent athées.", "translation": "Ils rejettent les dieux de l''Empire."}, {"text": "Les édits sont plus ou moins appliqués au niveau local.", "translation": "Les persécutions arrivent donc par vagues."}], "commonErrors": [{"wrong": "Les chrétiens étaient persécutés parce qu''ils étaient en révolte armée.", "right": "Ils étaient persécutés surtout parce qu''ils refusaient le culte impérial.", "why": "Leur refus était religieux, pas militaire."}, {"wrong": "Tous les empereurs persécutaient partout de la même façon.", "right": "Les édits étaient plus ou moins appliqués selon les localités.", "why": "Seul Dioclétien mène des persécutions généralisées."}, {"wrong": "Les accusations d''anthropophagie étaient vraies.", "right": "Ce sont des rumeurs fausses.", "why": "Elles viennent d''un malentendu sur le corps et le sang du Christ."}], "tip": "Retiens la chaîne : refus du culte impérial → mauvais citoyens → secret → rumeurs."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g18.edits_de_maximin_a_valerien', 'eg', 'grammar', 'knowledge', 'Les persécutions de Maximin à Valérien', 2, array['eg.g17.chretiens_mal_vus']::text[], 3, '{"rule": {"summary": "Au IIIe siècle, trois empereurs lancent des persécutions : Maximin vers 235 (6e), Dèce vers 249 (7e, avec l''édit de 250) et Valérien vers 257 (8e), puis une neuvième vers 274.", "explanation": "Maximin vise les chefs de l''Église. Dèce rend le culte impérial obligatoire en 250 pour souder la population de l''empire contre les dangers extérieurs ; on reçoit un libellus après avoir sacrifié. Valérien interdit les assemblées et frappe le clergé. Ces édits sont appliqués de façon inégale. Les violences ont l''effet contraire : les martyrs provoquent des conversions.", "pattern": "Maximin (235, 6e) → Dèce (249, 7e) → Valérien (257, 8e) → neuvième persécution (vers 274).", "examples": [{"text": "Vers 235, Maximin ordonne la sixième persécution.", "translation": "Elle ouvre la série du siècle."}, {"text": "En 250, l''édit de Dèce rend le culte impérial obligatoire.", "translation": "Il vise à unir la population face aux dangers extérieurs."}, {"text": "Vers 257, Valérien ordonne la huitième persécution.", "translation": "Il interdit les assemblées et frappe le clergé."}, {"text": "Le sang des martyrs est semence de chrétiens.", "translation": "La persécution fait grandir l''Église."}], "commonErrors": [{"wrong": "Dèce est l''empereur de la dixième persécution.", "right": "Dèce ordonne la septième ; la dixième est celle de Dioclétien.", "why": "Le numéro suit l''ordre des vagues."}, {"wrong": "Les persécutions tuent l''Église.", "right": "Elles provoquent de nombreuses conversions.", "why": "Le courage des martyrs impressionne."}, {"wrong": "Les édits du IIIe siècle sont appliqués partout avec la même force.", "right": "Ils sont appliqués plus ou moins fort selon les régions.", "why": "Seul Dioclétien généralise les persécutions."}], "tip": "6-7-8 : Maximin, Dèce, Valérien, dans l''ordre du temps (235, 249, 257)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g19.diocletien_ere_des_martyrs', 'eg', 'grammar', 'knowledge', 'Dioclétien et l''ère des martyrs', 2, array['eg.g18.edits_de_maximin_a_valerien']::text[], 3, '{"rule": {"summary": "Dioclétien devient empereur en 284 ; sous lui, la persécution devient générale (grande persécution de 303). Les Coptes font de 284 l''an 1 de leur calendrier, l''ère des martyrs.", "explanation": "Avant Dioclétien, les persécutions sont locales et par vagues. Avec lui, elles frappent tout l''empire : églises détruites, livres brûlés, clergé emprisonné (303). Cette période a eu un effet profond chez les Coptes : ils font de 284 la première année de leur calendrier, pour garder la mémoire des martyrs. Le jour de l''an s''appelle le Nayrouz.", "pattern": "284 : Dioclétien et an 1 du calendrier copte ; 303 : la grande persécution ; dixième et dernière persécution.", "examples": [{"text": "Dioclétien devient empereur en 284.", "translation": "Date de départ du calendrier copte."}, {"text": "En 303, la grande persécution détruit les églises.", "translation": "C''est le sommet des persécutions."}, {"text": "Le calendrier copte s''appelle aussi l''ère des martyrs.", "translation": "Il honore leurs témoins."}, {"text": "Le Nayrouz est le jour de l''an copte.", "translation": "Il ouvre chaque année copte."}], "commonErrors": [{"wrong": "Le calendrier copte honore Dioclétien.", "right": "Il garde la mémoire des martyrs que Dioclétien a fait mourir.", "why": "Le nom est celui du persécuteur, la mémoire est celle des martyrs."}, {"wrong": "Les persécutions de Dioclétien touchent seulement l''Égypte.", "right": "Elles s''étendent dans tout l''empire.", "why": "Elles sont généralisées."}, {"wrong": "L''année copte est la même que l''année grégorienne.", "right": "Elle compte depuis 284 : on retire environ 283.", "why": "En 2026, après le Nayrouz : 1743."}], "tip": "284, c''est l''an 1 : année copte = année actuelle − 283 (après le Nayrouz)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g20.premiers_ermites', 'eg', 'grammar', 'knowledge', 'Les premiers ermites', 2, array['eg.g19.diocletien_ere_des_martyrs']::text[], 3, '{"rule": {"summary": "Vers 250, Paul de Thèbes fuit la persécution de Dèce et devient le premier des ermites ; vers 270, Antoine part au désert et devient le père des moines.", "explanation": "La persécution pousse des chrétiens à fuir au désert d''Égypte. Paul est le premier ermite. Antoine, touché par la parole « va, vends ce que tu possèdes », part vers 270. Ermite et anachorète désignent ceux qui vivent seuls pour Dieu. Ce que la fuite a commencé devient une vocation : le monachisme naît en Égypte.", "pattern": "Vers 250 : Paul, premier ermite. Vers 270 : Antoine, père des moines.", "examples": [{"text": "Paul de Thèbes fuit au désert vers 250.", "translation": "Il est le premier des ermites."}, {"text": "Antoine part au désert vers 270.", "translation": "Il entend « va, vends ce que tu possèdes »."}, {"text": "Un ermite vit seul.", "translation": "Du grec « eremos », désert."}, {"text": "Un anachorète se retire du monde.", "translation": "Du grec « anachôrein »."}], "commonErrors": [{"wrong": "Antoine est le premier ermite.", "right": "Paul de Thèbes est le premier ; Antoine est le père des moines.", "why": "Antoine rencontre Paul vers la fin de la vie de ce dernier."}, {"wrong": "Les ermites sont tous partis pour fuir la persécution.", "right": "Au début oui, ensuite c''est un choix de vie.", "why": "Le désert devient une vocation."}, {"wrong": "Le désert, c''est loin de tout.", "right": "Le désert d''Égypte est proche du Nil.", "why": "On y arrive en quelques jours depuis la vallée."}], "tip": "Paul d''abord (250), Antoine ensuite (270) : P avant A, comme l''alphabet à l''envers."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g21.erreurs_sur_la_trinite', 'eg', 'grammar', 'knowledge', 'Les erreurs sur la Trinité : Paul de Samosate et Sabellius', 3, array['eg.g20.premiers_ermites']::text[], 3, '{"rule": {"summary": "Deux erreurs sur la Trinité au IIIe siècle : Paul de Samosate, pour qui le Christ est un homme ordinaire (condamné à Antioche en 269), et Sabellius, pour qui le Père, le Fils et l''Esprit ne sont qu''un seul Dieu sous trois formes.", "explanation": "L''Église confesse trois personnes et une seule divinité. Paul de Samosate, évêque d''Antioche protégé par Zénobie, nie la Trinité et l''union de la divinité au Christ. Le pape Denys d''Alexandrie écrit une lettre qui précise la foi, et le concile d''Antioche l''excommunie en 269. Sabellius, évêque de Ptolémaïs, confond les personnes en parlant de manifestations successives d''un seul Dieu.", "pattern": "Paul : Christ homme ordinaire. Sabellius : un seul Dieu, trois masques. Foi : trois personnes, une seule divinité.", "examples": [{"text": "Paul de Samosate est excommunié en 269.", "translation": "Le concile d''Antioche le condamne."}, {"text": "Pour Paul, le Christ est un homme ordinaire.", "translation": "La divinité ne s''est pas unie à lui."}, {"text": "Denys écrit : trois personnes, une seule divinité.", "translation": "Il appuie la foi trinitaire."}, {"text": "Sabellius voit trois manifestations d''un seul Dieu.", "translation": "C''est le modalisme."}], "commonErrors": [{"wrong": "Paul de Samosate enseignait que le Christ est Dieu mais pas homme.", "right": "Il enseignait que le Christ est un homme ordinaire.", "why": "La divinité ne s''était pas unie à lui."}, {"wrong": "Sabellius niait l''existence de Dieu.", "right": "Il disait que le Père, le Fils et l''Esprit sont un seul Dieu.", "why": "Il confond les personnes."}, {"wrong": "Les deux hérésies disent la même chose.", "right": "Paul rabaisse le Christ ; Sabellius confond les personnes.", "why": "Opposées mais toutes deux contre la Trinité."}], "tip": "Paul rabaisse le Christ ; Sabellius change de masque."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g22.novatien_et_mani', 'eg', 'grammar', 'knowledge', 'Novatien et Mani', 3, array['eg.g21.erreurs_sur_la_trinite']::text[], 3, '{"rule": {"summary": "Deux dangers du IIIe siècle : Novatien, qui refuse de pardonner aux « tombés » et veut une Église pure, et Mani, dont le manichéisme oppose un Dieu bon à un démiurge mauvais.", "explanation": "Après Dèce, la question des tombés divise. Novatien, théologien romain consacré évêque de Rome en 251, veut une Église préservée dans sa pureté. L''Église répond qu''il faut recevoir les vrais pénitents ; Novatien est excommunié en 251, combattu par Denys d''Alexandrie et Cyprien. Mani, un Perse, fonde le manichéisme : deux principes, toutes les religions valides, réincarnation. Saint Augustin l''a suivi avant de se convertir.", "pattern": "Novatien : pas de pardon. L''Église : pénitence et retour. Mani : deux principes, un Dieu bon, un démiurge mauvais.", "examples": [{"text": "Novatien refuse de pardonner aux tombés.", "translation": "Il veut une Église pure."}, {"text": "Il faut recevoir les vrais pénitents.", "translation": "C''est la réponse de l''Église."}, {"text": "Mani est un Perse.", "translation": "Il fonde le manichéisme."}, {"text": "Augustin a été manichéen.", "translation": "Avant de se convertir."}], "commonErrors": [{"wrong": "Novatien est un hérétique païen.", "right": "C''est un théologien romain, chrétien, mais trop rigide.", "why": "Son erreur est un rigorisme."}, {"wrong": "Le manichéisme est une secte chrétienne.", "right": "C''est une doctrine perse influencée par la gnose.", "why": "Elle ne croit pas à l''Incarnation."}, {"wrong": "Les tombés sont définitivement exclus.", "right": "L''Église reçoit les vrais pénitents.", "why": "Elle ferme la porte à personne."}], "tip": "Novatien = porte fermée ; Église = porte ouverte à la pénitence."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g23.tradition_et_canon', 'eg', 'grammar', 'knowledge', 'La Tradition et le canon', 3, array['eg.g22.novatien_et_mani']::text[], 3, '{"rule": {"summary": "L''Église précède le Nouveau Testament : elle l''a écrit puis reconnu. Elle a trié les écrits selon l''approbation apostolique et quatre critères, en distinguant canoniques, honorables et apocryphes.", "explanation": "La Sainte Tradition est la parole confiée aux apôtres et gardée vivante par leurs successeurs. Pour fixer le canon, l''Église applique quatre critères : le caractère apostolique, la valeur spirituelle, la conformité à la doctrine, le consensus de toutes les Églises. Elle distingue les écrits canoniques, les écrits honorables non inspirés (Didachè, Pasteur d''Hermas) et les apocryphes.", "pattern": "Apostolicité + valeur spirituelle + conformité + consensus = canon.", "examples": [{"text": "La Didachè date d''environ 100.", "translation": "Écrit honorable mais non canonique."}, {"text": "La Tradition apostolique d''Hippolyte date d''environ 215.", "translation": "Elle décrit l''organisation de l''Église."}, {"text": "La Didascalie date d''environ 250.", "translation": "Enseignement des douze apôtres."}, {"text": "Le Pasteur d''Hermas n''entre pas dans le canon.", "translation": "Ses visions sont incontrôlables."}], "commonErrors": [{"wrong": "Le Nouveau Testament précède l''Église.", "right": "L''Église précède le Nouveau Testament.", "why": "Elle l''écrit puis le reconnaît."}, {"wrong": "Tous les écrits anciens sont canoniques.", "right": "Seuls ceux qui passent les quatre critères le sont.", "why": "Didachè et Hermas sont honorables, pas canoniques."}, {"wrong": "La Tradition est seulement un savoir à apprendre.", "right": "Elle est vivante dans la prière et la vie de l''Église.", "why": "Elle dépasse la transmission intellectuelle."}], "tip": "A-V-C-C : Apostolique, Valeur spirituelle, Conforme, Consensus."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g24.structure_de_l_eglise', 'eg', 'grammar', 'knowledge', 'La structure de l''Église', 3, array['eg.g23.tradition_et_canon']::text[], 3, '{"rule": {"summary": "Au IIIe siècle, l''Église s''organise en trois degrés : évêque, prêtre, diacre, avec la distinction clercs et laïcs. Le titre de pape d''Alexandrie date d''Héraclas.", "explanation": "Les premières communautés sont dirigées ensemble par les surveillants, les serviteurs et les anciens. Dès le IIe siècle, un unique évêque, successeur des apôtres, les dirige. Au IIIe siècle, la hiérarchie à trois degrés s''affirme et les confesseurs reçoivent un rôle spécial. Les prophètes disparaissent. Héraclas est le premier pape d''Alexandrie ; le titre de patriarche vient en 451.", "pattern": "Collégiale → un évêque (IIe) → trois degrés (IIIe) ; pape depuis Héraclas ; patriarche depuis 451.", "examples": [{"text": "Au IIIe siècle, la hiérarchie est : évêque, prêtre, diacre.", "translation": "Les mots reçoivent un nouveau sens."}, {"text": "Le confesseur dirige les offices sans imposition des mains.", "translation": "Il doit être ordonné pour devenir évêque."}, {"text": "Les prophètes ont disparu avec les temps apostoliques.", "translation": "L''Écriture prend le relais."}, {"text": "Héraclas est le premier appelé pape.", "translation": "Il est le 13e évêque d''Alexandrie."}], "commonErrors": [{"wrong": "Les confesseurs sont tous des évêques.", "right": "Ils ne sont évêques que s''ils sont ordonnés.", "why": "Ils ont un statut honoré, pas un ordre."}, {"wrong": "Le titre de patriarche existe depuis les apôtres.", "right": "Il n''apparaît qu''à partir de 451.", "why": "Le titre de pape vient d''Héraclas."}, {"wrong": "Il y a toujours eu un seul évêque à la tête de l''Église.", "right": "Au début, la direction est collégiale.", "why": "Un unique évêque apparaît au IIe siècle."}], "tip": "Étapes : à plusieurs → un évêque → trois degrés."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g25.grande_persecution', 'eg', 'grammar', 'knowledge', 'La grande persécution (303-311)', 2, '{}'::text[], 4, '{"rule": {"summary": "De 303 à 311, Dioclétien puis Galère mènent la plus dure persécution contre les chrétiens, avec une terrible force en Égypte, jusqu''à l''édit de tolérance de 311.", "explanation": "Dioclétien devient empereur en 284 et réorganise l''empire en se réservant l''Égypte et l''Orient. En 303, il publie quatre édits : églises rasées et livres brûlés, chefs emprisonnés, torturés s''ils refusent de sacrifier, puis tous les chrétiens visés. Galère lui succède en 305 et se montre encore plus cruel. Les martyrs sont innombrables en Égypte ; le pape Pierre (311) est appelé le sceau des martyrs. La même année, Galère signe un édit de tolérance. Le calendrier copte compte ses années depuis 284.", "pattern": "284 Dioclétien → 303 quatre édits → 305 Galère → 311 tolérance", "examples": [{"text": "303 : Dioclétien publie quatre édits contre les chrétiens.", "translation": "Églises rasées, livres brûlés, chefs emprisonnés."}, {"text": "311 : le pape Pierre meurt martyr ; Galère signe l''édit de tolérance.", "translation": "Le sceau des martyrs et la fin de l''épreuve."}, {"text": "Le calendrier copte part de 284.", "translation": "L''ère des martyrs honore ceux de cette époque."}], "commonErrors": [{"wrong": "La grande persécution date de Néron.", "right": "Néron lance la première persécution en 64 ; la grande persécution est celle de Dioclétien, de 303 à 311.", "why": "Il y a eu de nombreuses persécutions ; la dixième est la plus sanglante."}, {"wrong": "C''est Constantin qui persécute en 303.", "right": "Constantin n''est empereur que depuis 306 et sera l''empereur de la paix.", "why": "Le persécuteur est Dioclétien, puis Galère."}], "tip": "303 persécution, 311 tolérance, 313 paix : c''est la route vers Constantin."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g26.constantin', 'eg', 'grammar', 'knowledge', 'Constantin et l''édit de Milan (313)', 2, array['eg.g25.grande_persecution']::text[], 4, '{"rule": {"summary": "Constantin, empereur dès 306, bat Maxence en 312 sous le signe de la croix, signe avec Licinius l''édit de Milan en 313, puis fonde Constantinople en 330.", "explanation": "Le récit de l''Église dit que Constantin voit une croix lumineuse avant la bataille contre Maxence en 312. Il fait mettre la croix sur ses armes et gagne. En 313, l''édit de Milan met fin aux persécutions romaines et rend aux chrétiens leurs biens. Sa mère Hélène retrouve la Sainte Croix et bâtit des églises. Constantin fonde Constantinople en 330 et se présente comme l''évêque du dehors, ce qui rapproche dangereusement l''Église de l''État. Il meurt en 337.", "pattern": "306 empereur → 312 la croix → 313 Milan → 330 Constantinople → 337 mort", "examples": [{"text": "312 : « Avec ceci tu vaincras ».", "translation": "La croix devient le signe de son armée."}, {"text": "313 : Constantin et Licinius signent l''édit de Milan.", "translation": "Fin des persécutions romaines."}, {"text": "330 : Constantinople devient la capitale de l''Orient.", "translation": "Un nouveau centre du monde chrétien."}], "commonErrors": [{"wrong": "Constantin a déclaré le christianisme religion d''État en 313.", "right": "L''édit de Milan donne la liberté ; la religion d''État date de 380.", "why": "Tolérer n''est pas imposer."}, {"wrong": "L''édit de Milan a été signé par Dioclétien.", "right": "Il est signé par Constantin et Licinius.", "why": "Dioclétien est le persécuteur, il a abdiqué en 305."}], "tip": "Une croix en 312, la paix en 313, une ville en 330."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g27.arius', 'eg', 'grammar', 'knowledge', 'Arius et l''arianisme', 3, array['eg.g26.constantin']::text[], 4, '{"rule": {"summary": "Vers 318, le prêtre Arius enseigne que le Fils n''est pas de la même essence que le Père : l''Église défend la divinité du Christ, car seul Dieu peut sauver l''homme.", "explanation": "Arius est un prêtre libyen d''Alexandrie, éloquent, qui met sa doctrine en chansons. Il nie la divinité du Christ : pour lui, le Fils a été créé. Les ariens citent Jean 14:28 ; Athanase répond avec Jean 14:9 et 14:11. Trois positions s''affrontent : arienne (Fils créé), semi-arienne (substance similaire, homoiousios) et orthodoxe (même substance, homoousios). L''enjeu est le salut : si le Christ n''est pas Dieu, il ne peut pas sauver.", "pattern": "Arien : créé · Semi-arien : similaire · Orthodoxe : même substance", "examples": [{"text": "Vers 318, Arius enseigne que le Fils n''est pas de la même essence que le Père.", "translation": "Début de la crise arienne."}, {"text": "Athanase cite : « Qui m''a vu a vu le Père ».", "translation": "Jésus se présente comme Dieu incarné."}, {"text": "Homoousios contre homoiousios.", "translation": "Un iota sépare la foi des semi-ariens de celle de l''Église."}], "commonErrors": [{"wrong": "Arius nie que Jésus ait existé.", "right": "Arius reconnaît Jésus mais nie qu''il soit Dieu au même titre que le Père.", "why": "Le débat porte sur la nature du Fils, pas sur son existence."}, {"wrong": "Les semi-ariens sont orthodoxes.", "right": "Ils disent « substance similaire », pas « même substance ».", "why": "Un seul iota change tout le sens."}], "tip": "Arius : Fils créé. Athanase : Fils Dieu. Un iota de différence pour les semi-ariens."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g28.concile_de_nicee', 'eg', 'grammar', 'knowledge', 'Le concile de Nicée (325)', 3, array['eg.g27.arius']::text[], 4, '{"rule": {"summary": "Convoqué par Constantin en 325, le concile de Nicée réunit 318 évêques contre l''arianisme, rédige le credo (le Fils est homoousios) et vingt canons.", "explanation": "Le premier concile œcuménique est convoqué par l''empereur Constantin pour mettre fin à la querelle d''Arius. Selon la tradition copte, le pape Alexandre le préside avec son jeune diacre Athanase. 315 évêques sur 318 signent d''abord le credo et les anathèmes ; trois résistent, puis cèdent sous la pression de Constantin. Le concile excommunie Arius, établit le credo de Nicée et vingt canons. L''arianisme survit pourtant, comme un serpent de mer.", "pattern": "Nicée = Constantin, 325, 318 évêques, contre Arius, homoousios, 20 canons", "examples": [{"text": "325 : 318 évêques se réunissent à Nicée.", "translation": "Premier concile œcuménique."}, {"text": "Le credo dit que le Fils est homoousios au Père.", "translation": "Il est Dieu, de même substance."}, {"text": "Trois évêques refusent d''abord les anathèmes.", "translation": "L''arianisme n''est pas vaincu pour autant."}], "commonErrors": [{"wrong": "Nicée est le concile qui a défini les deux natures du Christ.", "right": "Nicée traite de la divinité du Fils ; la question des natures vient plus tard (Éphèse, Chalcédoine).", "why": "Chaque concile répond à une crise précise."}, {"wrong": "Constantin préside les débats de foi.", "right": "Il convoque ; les évêques décident.", "why": "L''empereur est « évêque du dehors »."}], "tip": "Nicée : Constantin convoque, Alexandre préside, Athanase défend, Arius est condamné."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g29.athanase', 'eg', 'grammar', 'knowledge', 'Saint Athanase (vers 298-373)', 3, array['eg.g28.concile_de_nicee']::text[], 4, '{"rule": {"summary": "Diacre d''Alexandre à Nicée, puis XXe patriarche d''Alexandrie, Athanase défend la divinité du Christ contre les ariens, malgré plusieurs exils.", "explanation": "Athanase naît vers 298 à Alexandrie et écrit très jeune « Sur l''incarnation du Verbe ». Formé par saint Antoine, il devient le diacre et secrétaire du pape Alexandre, puis son successeur. Les ariens, soutenus par des empereurs, l''exilent plusieurs fois, mais il revient toujours. Il écrit La Vie d''Antoine, donne en 367 la liste des 27 livres du Nouveau Testament et ordonne Frumentius premier évêque d''Éthiopie. Il meurt en 373.", "pattern": "298 naissance → 328 pape → exils → 367 canon → 373 mort", "examples": [{"text": "« Le monde est contre toi, Athanase. — Et je suis contre le monde. »", "translation": "Il tient la foi même seul."}, {"text": "367 : la lettre qui donne la liste des 27 livres.", "translation": "Athanase aide à fixer le Nouveau Testament."}, {"text": "Vers 341 : Frumentius, premier évêque d''Éthiopie.", "translation": "La mission passe par Alexandrie."}], "commonErrors": [{"wrong": "Athanase a rédigé tout le Nouveau Testament.", "right": "Il donne la liste officielle des 27 livres, il ne les écrit pas.", "why": "Le canon est une liste, pas un texte."}, {"wrong": "Athanase a été exilé une seule fois.", "right": "Il est exilé plusieurs fois, selon ton cours environ six.", "why": "Les ariens ont longtemps eu des appuis impériaux."}], "tip": "Athanase : jeune diacre à Nicée, pape pendant plus de quarante ans, défenseur de la foi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g30.peres_du_desert', 'eg', 'grammar', 'knowledge', 'Le monachisme égyptien', 3, array['eg.g29.athanase']::text[], 4, '{"rule": {"summary": "Le monachisme naît en Égypte au IVe siècle : saint Antoine (vie solitaire), saint Pacôme (vie en communauté), saint Macaire à Scété, puis saint Chénouté.", "explanation": "Quand les persécutions s''arrêtent et que l''Église se rapproche du pouvoir, beaucoup de chrétiens choisissent le désert. Le moine vit de prière, de jeûne et de solitude, avec trois principes : pauvreté, obéissance, chasteté. Antoine (251-356), un Copte de Haute-Égypte, est le père des moines. Pacôme fonde les premiers monastères cénobitiques, en communauté. Macaire (mort en 391) rassemble des disciples à Scété. Vers la fin du siècle, plusieurs milliers de moines vivent au désert, et l''Occident les découvre grâce à La Vie d''Antoine et à Jean Cassien.", "pattern": "Antoine = solitude · Pacôme = communauté · Macaire = Scété · Égypte = mère du monachisme", "examples": [{"text": "Antoine naît en 251 et meurt en 356.", "translation": "Le premier moine du monde est un Copte."}, {"text": "Pacôme fonde les premiers monastères cénobitiques.", "translation": "La vie en communauté a des règles."}, {"text": "Jean Cassien fait connaître les moines d''Égypte à l''Occident.", "translation": "La sagesse du désert voyage."}], "commonErrors": [{"wrong": "Pacôme est le premier moine du monde.", "right": "Le premier moine est Antoine ; Pacôme fonde les premiers monastères cénobitiques.", "why": "Ermite et cénobite ne sont pas la même vie."}, {"wrong": "Chénouté vit au IVe siècle comme Antoine.", "right": "Chénouté vient un peu plus tard, au siècle suivant.", "why": "Il est le troisième système, après Antoine et Pacôme."}], "tip": "Antoine seul, Pacôme ensemble, Macaire à Scété."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g31.concile_de_constantinople', 'eg', 'grammar', 'knowledge', 'Le concile de Constantinople (381)', 3, array['eg.g28.concile_de_nicee']::text[], 4, '{"rule": {"summary": "Convoqué par Théodose Ier en 381, le deuxième concile œcuménique réunit 150 évêques contre Apollinaire et Macédonius, complète le credo et établit sept canons.", "explanation": "Après Nicée, l''arianisme et les débats sur le Saint-Esprit continuent. En 380, le christianisme devient religion de l''État ; en 381, l''empereur Théodose Ier réunit 150 évêques à Constantinople. Le concile excommunie Apollinaire, qui nie l''âme humaine du Christ, et Macédonius, qui fait de l''Esprit Saint une créature. Il complète le credo de Nicée depuis « Je crois en l''Esprit Saint » et établit sept canons ; Alexandrie n''a pas accepté celui qui met Constantinople au deuxième rang.", "pattern": "Constantinople = Théodose Ier, 381, 150 évêques, Apollinaire et Macédonius, credo complété", "examples": [{"text": "381 : 150 évêques à Constantinople.", "translation": "Deuxième concile œcuménique."}, {"text": "Apollinaire : un corps humain mais sans son âme.", "translation": "Sans âme humaine, pas de salut pour l''homme entier."}, {"text": "Macédonius : le Saint-Esprit est créé.", "translation": "Le concile affirme sa divinité dans le credo."}], "commonErrors": [{"wrong": "Constantinople est le concile contre Arius.", "right": "Arius est condamné à Nicée ; Constantinople traite d''Apollinaire et de Macédonius.", "why": "Chaque concile répond à une crise précise."}, {"wrong": "Le credo de Nicée est identique à celui de la messe.", "right": "Le credo de la messe est celui de Nicée complété à Constantinople en 381.", "why": "La partie sur l''Esprit Saint est ajoutée en 381."}], "tip": "Nicée = Fils (Arius). Constantinople = âme du Christ (Apollinaire) et Esprit Saint (Macédonius)."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g32.bilan_du_siecle', 'eg', 'grammar', 'knowledge', 'Bilan du IVe siècle', 3, array['eg.g31.concile_de_constantinople']::text[], 4, '{"rule": {"summary": "Le IVe siècle va de la persécution à la religion d''État : Nicée (325) et Constantinople (381) fixent la foi, les moines d''Égypte fleurissent, et de grands saints marquent le siècle.", "explanation": "Les dates clés sont 303, 313, 325, 330, 367, 380 et 381. Nicée, convoqué par Constantin, condamne Arius ; Constantinople, convoqué par Théodose Ier, condamne Apollinaire et Macédonius et complète le credo. Les quatre erreurs touchent le Fils, l''âme du Christ et l''Esprit Saint. Les grands saints du siècle sont Nicolas, Éphrem, Basile, Ambroise, Jean Chrysostome et Augustin. Les trois liturgies de l''Église copte portent les noms de Basile, Grégoire et Cyrille.", "pattern": "Nicée 325 (Fils) → Constantinople 381 (âme du Christ, Esprit Saint) → Éphèse 431", "examples": [{"text": "Nicée : Constantin, 325, 318 évêques, Arius.", "translation": "Premier concile œcuménique."}, {"text": "Constantinople : Théodose Ier, 381, 150 évêques.", "translation": "Deuxième concile œcuménique."}, {"text": "Basile, Grégoire, Cyrille : trois liturgies.", "translation": "Les Pères sont présents dans ta messe."}], "commonErrors": [{"wrong": "Constantinople condamne Arius.", "right": "Arius est condamné à Nicée ; Constantinople condamne Apollinaire et Macédonius.", "why": "Chaque concile a sa crise."}, {"wrong": "Augustin est évêque de Milan.", "right": "Augustin est évêque d''Hippone ; Ambroise est évêque de Milan.", "why": "Ambroise a baptisé Augustin."}], "tip": "Nicée 325, Constantinople 381, Éphèse 431 : un siècle, trois conciles."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g33.cinq_sieges', 'eg', 'grammar', 'knowledge', 'L''Église unie et ses cinq sièges', 1, '{}'::text[], 5, '{"rule": {"summary": "Jusqu''au milieu du Ve siècle, l''Église est unie autour de cinq grands sièges (Jérusalem, Antioche, Alexandrie et Rome, apostoliques, et Constantinople, la capitale) et de trois conciles œcuméniques : Nicée (325), Constantinople (381) et Éphèse (431).", "explanation": "Chaque grande ville a son évêque important, le patriarche. Constantinople, capitale depuis 330, est le plus jeune siège mais le plus proche de l''empereur. Quand la foi est en danger, les évêques du monde entier se réunissent en concile œcuménique pour fixer la foi et voter des canons. Alexandrie y joue un rôle de chef de file (Athanase à Nicée, Cyrille à Éphèse), ce qui provoque des jalousies. Le canon 3 de 381, qui place Constantinople au deuxième rang après Rome, est refusé par Alexandrie.", "pattern": "5 sièges : Jérusalem, Antioche, Alexandrie, Rome, Constantinople. 3 conciles : 325, 381, 431.", "examples": [{"text": "En 330, Byzance devient Constantinople.", "translation": "L''empereur Constantin y installe sa capitale : c''est la « nouvelle Rome »."}, {"text": "En 325, le concile de Nicée condamne Arius.", "translation": "Saint Athanase d''Alexandrie est le grand défenseur de la foi."}, {"text": "En 381, le concile de Constantinople complète le credo.", "translation": "On y ajoute la partie sur le Saint-Esprit."}, {"text": "En 431, le concile d''Éphèse proclame Marie Théotokos.", "translation": "Nestorius y est condamné."}], "commonErrors": [{"wrong": "Constantinople est un siège apostolique depuis les apôtres.", "right": "C''est le plus jeune des cinq sièges : sa grandeur vient de la capitale de l''empire.", "why": "Les quatre autres sièges remontent aux origines de l''Église."}, {"wrong": "Le concile d''Éphèse est le deuxième concile œcuménique.", "right": "C''est le troisième, après Nicée (325) et Constantinople (381).", "why": "L''ordre des dates est la clé de l''ordre des conciles."}], "tip": "Les trois premiers conciles se retiennent en 325, 381, 431 : à chaque fois, environ cinquante ans d''écart."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g34.nestorius', 'eg', 'grammar', 'knowledge', 'Nestorius et le nestorianisme', 2, array['eg.g33.cinq_sieges']::text[], 5, '{"rule": {"summary": "Nestorius, patriarche de Constantinople en 428, refuse d''appeler Marie « Théotokos » (mère de Dieu) et sépare le Verbe de l''homme Jésus : cette doctrine, le nestorianisme, sera condamnée à Éphèse en 431.", "explanation": "Nestorius vient de l''école d''Antioche, qui distingue soigneusement le divin et l''humain en Jésus. Il craint qu''appeler Marie « mère de Dieu » fasse croire que Dieu a commencé d''exister dans son ventre, et propose « Christotokos », mère du Christ. Ses adversaires lui reprochent de séparer le Verbe de l''homme Jésus, comme si Dieu habitait en lui sans faire un seul Christ. Alors qui est né de Marie, qui est mort sur la croix ? Si ce n''est pas Dieu qui s''est incarné, le salut est en danger.", "pattern": "Nestorius (428) : refuse Théotokos, dit Christotokos, sépare le Verbe et l''homme Jésus.", "examples": [{"text": "En 428, Nestorius devient patriarche de Constantinople.", "translation": "Il est célèbre pour ses sermons."}, {"text": "Il préfère dire « Christotokos ».", "translation": "Pour lui, Marie est mère du Christ, pas mère de Dieu."}, {"text": "Ses adversaires disent : « Il sépare le Verbe de l''homme Jésus. »", "translation": "Cela revient à faire deux fils."}, {"text": "En Égypte, les moines apprennent ces sermons.", "translation": "Cyrille d''Alexandrie va répondre."}], "commonErrors": [{"wrong": "Nestorius niait que Jésus soit Dieu.", "right": "Il affirmait la divinité, mais séparait le Verbe de l''homme Jésus.", "why": "Le problème est l''unité du Christ, pas sa divinité."}, {"wrong": "Théotokos veut dire que Marie est avant Dieu.", "right": "Cela veut dire que celui qu''elle enfante est Dieu.", "why": "Le titre protège l''identité de Jésus, il ne dit rien d''une origine de Dieu."}], "tip": "Théotokos protège l''unité du Christ : un seul Jésus, qui est Dieu et homme à la fois."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g35.cyrille', 'eg', 'grammar', 'knowledge', 'Saint Cyrille d''Alexandrie et sa formule', 2, array['eg.g34.nestorius']::text[], 5, '{"rule": {"summary": "Saint Cyrille, 24e pape d''Alexandrie (412-444), surnommé le Pilier de la foi, défend le titre Théotokos et résume la foi en une formule : « une seule nature du Verbe incarné ».", "explanation": "Cyrille comprend que le titre Théotokos protège l''identité de Jésus : celui que Marie enfante est Dieu le Verbe fait chair. Il écrit aux moines d''Égypte puis à Nestorius, et joint à sa troisième lettre douze anathèmes qui condamnent les idées nestoriennes. Le pape de Rome, Célestin Ier, le soutient. Sa formule exprime l''unité du Christ : un seul Verbe incarné, Dieu et homme, comme l''âme et le corps font un seul homme sans cesser d''être âme et corps.", "pattern": "Cyrille = 24e pape, Pilier de la foi, 12 anathèmes, « une seule nature du Verbe incarné ».", "examples": [{"text": "Cyrille est le 24e pape d''Alexandrie (412-444).", "translation": "Le siège d''Alexandrie fondé par saint Marc a un chef théologien."}, {"text": "Il défend le titre Théotokos.", "translation": "Marie est mère de Dieu, car son fils est Dieu le Verbe."}, {"text": "Il envoie douze anathèmes à Nestorius.", "translation": "Chacun rejette une idée nestorienne."}, {"text": "Le pape de Rome, Célestin Ier, le soutient.", "translation": "Rome et Alexandrie sont alors d''accord contre Nestorius."}], "commonErrors": [{"wrong": "Cyrille dit que l''humanité du Christ disparaît.", "right": "Il affirme un Christ complètement Dieu et complètement homme.", "why": "La formule parle d''union, pas de disparition."}, {"wrong": "Cyrille est le 25e pape.", "right": "Il est le 24e. Le 25e est Dioscore.", "why": "Cyrille, 24 ; Dioscore, 25."}], "tip": "Cyrille = Pilier de la foi = 24e pape = Théotokos."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g36.ephese_431', 'eg', 'grammar', 'knowledge', 'Le concile d''Éphèse (431)', 3, array['eg.g35.cyrille']::text[], 5, '{"rule": {"summary": "Le concile d''Éphèse (431), troisième concile œcuménique, convoqué par Théodose II et présidé par Cyrille, proclame Marie Théotokos, condamne et dépose Nestorius et condamne l''enseignement de Pélage.", "explanation": "L''empereur Théodose II réunit environ deux cents évêques à Éphèse. Cyrille, qui représente Alexandrie et aussi Rome, préside. Nestorius refuse de comparaître et Jean d''Antioche, avec les évêques d''Orient, arrive en retard : le concile ouvre sans eux et condamne Nestorius. Les évêques d''Antioche tiennent alors un concile rival, et l''empereur doit trancher. Le concile confirme le credo de Nicée sans changement, proclame Théotokos et condamne Pélage. Nestorius est exilé en Haute-Égypte.", "pattern": "431, Éphèse, Théodose II convoque, Cyrille préside ; Nestorius condamné ; Marie Théotokos.", "examples": [{"text": "Théodose II convoque le concile à Éphèse en 431.", "translation": "L''empereur d''Orient réunit environ 200 évêques."}, {"text": "Cyrille préside l''assemblée.", "translation": "Il représente Alexandrie, avec l''appui de Rome."}, {"text": "Nestorius refuse de comparaître et est condamné.", "translation": "Il est déposé et anathématisé."}, {"text": "Marie est proclamée Théotokos.", "translation": "Le titre devient dogme de l''Église."}], "commonErrors": [{"wrong": "Éphèse a défini les deux natures du Christ.", "right": "Éphèse a surtout proclamé Théotokos et condamné Nestorius.", "why": "Les « deux natures » sont le langage de Chalcédoine."}, {"wrong": "Éphèse est le 4e concile œcuménique.", "right": "C''est le 3e, après Nicée et Constantinople.", "why": "325, 381, 431."}], "tip": "Éphèse = 431 = Théotokos = Nestorius condamné = Cyrille préside."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g37.apres_ephese', 'eg', 'grammar', 'knowledge', 'La paix fragile (431-446)', 3, array['eg.g36.ephese_431']::text[], 5, '{"rule": {"summary": "Après Éphèse, Cyrille et Jean d''Antioche se réconcilient par la formule d''union (433). La paix reste fragile : les partisans de Nestorius partent en Perse, Cyrille meurt en 444, Dioscore devient 25e pape et Flavien patriarche de Constantinople.", "explanation": "Les évêques d''Orient, fâchés contre Cyrille, sont réconciliés par un texte de compromis en 433. Jean d''Antioche accepte la déposition de Nestorius et le titre Théotokos ; Cyrille accepte un vocabulaire plus nuancé. La question « une ou deux natures ? » n''est pas réglée. Les partisans de Nestorius, chassés de l''Empire, vont en Perse où naît l''Église de l''Orient. Cyrille meurt en 444, Dioscore lui succède comme 25e pape, et Flavien devient patriarche de Constantinople en 446.", "pattern": "433 formule d''union ; 444 mort de Cyrille, Dioscore 25e pape ; Flavien patriarche (446).", "examples": [{"text": "En 433, Cyrille et Jean d''Antioche signent un compromis.", "translation": "Un texte accepté par les deux camps."}, {"text": "Les partisans de Nestorius gagnent la Perse.", "translation": "Ils fondent l''Église de l''Orient."}, {"text": "Cyrille meurt en 444.", "translation": "Après plus de 30 ans de pontificat."}, {"text": "Dioscore devient le 25e pape.", "translation": "Son règne sera court mais décisif."}], "commonErrors": [{"wrong": "La formule d''union règle définitivement la question des natures.", "right": "Elle apaise mais ne règle pas la question.", "why": "La dispute reviendra avec Eutychès."}, {"wrong": "Les partisans de Nestorius disparaissent après 431.", "right": "Ils vont en Perse où naît l''Église de l''Orient.", "why": "Le nestorianisme survit hors de l''Empire."}], "tip": "433 : paix. 444 : mort de Cyrille. 446 : Flavien. La crise suivante arrive."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g38.eutyches', 'eg', 'grammar', 'knowledge', 'Eutychès et le monophysisme', 3, array['eg.g37.apres_ephese']::text[], 5, '{"rule": {"summary": "Eutychès, archimandrite d''un monastère près de Constantinople, enseigne que la divinité absorbe l''humanité du Christ (le monophysisme) ; le patriarche Flavien le condamne en 448, et il fait appel à l''empereur Théodose II et à Dioscore.", "explanation": "Là où Nestorius sépare, Eutychès mélange. Il dit que Jésus n''a qu''une nature, la nature divine, car l''humanité est absorbée comme une goutte de miel dans la mer. Mais alors Jésus ne serait plus vraiment homme comme nous, et il ne nous sauverait pas. Le synode local de Constantinople (448) l''excommunie et le dégrade. Eutychès fait appel à l''empereur et à Dioscore ; Théodose II convoque un concile à Éphèse pour le 1er août 449.", "pattern": "Nestorius sépare ; Eutychès mélange. 448 : Flavien condamne Eutychès. 449 : Éphèse II.", "examples": [{"text": "Eutychès est archimandrite d''un monastère près de Constantinople.", "translation": "Un chef de monastère, donc un homme respecté."}, {"text": "Il compare l''humanité à une goutte de miel dans la mer.", "translation": "Elle disparaît dans la divinité."}, {"text": "En 448, Flavien le condamne.", "translation": "Il l''excommunie et le dégrade."}, {"text": "Il fait appel à Théodose II et à Dioscore.", "translation": "Cela déclenche Éphèse II."}], "commonErrors": [{"wrong": "Eutychès et Cyrille enseignent la même chose.", "right": "Cyrille affirme un Christ complètement Dieu et complètement homme.", "why": "Pour Eutychès l''humanité est absorbée."}, {"wrong": "Eutychès sépare les natures.", "right": "Il fait l''inverse : il les mélange.", "why": "Nestorius sépare, Eutychès mélange."}], "tip": "Nestorius sépare, Eutychès mélange : deux erreurs opposées."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g39.ephese_449', 'eg', 'grammar', 'knowledge', 'Le deuxième concile d''Éphèse (449)', 4, array['eg.g38.eutyches']::text[], 5, '{"rule": {"summary": "Le deuxième concile d''Éphèse (449), convoqué par Théodose II et présidé par Dioscore, réhabilite Eutychès et dépose Flavien, sans que le Tome de Léon soit lu ; Léon Ier le nomme « brigandage d''Éphèse ».", "explanation": "Léon Ier, évêque de Rome, ne peut venir mais envoie le Tome de Léon, une lettre dogmatique. À Éphèse, Eutychès cite Cyrille et signe ; Dioscore le réhabilite et dépose Flavien. Faute de temps, la séance se clôt par la lecture des lettres de l''empereur, sans le Tome. Furieux, Léon veut un nouveau concile, mais Théodose II refuse. À sa mort en 450, sa sœur Pulchérie épouse Marcien et le fait empereur : Léon obtient alors un nouveau concile, qui sera Chalcédoine.", "pattern": "449 Éphèse II : Dioscore préside ; Eutychès réhabilité ; Flavien déposé ; Tome non lu. 450 : Marcien.", "examples": [{"text": "Dioscore préside Éphèse II.", "translation": "L''empereur fait confiance à Alexandrie."}, {"text": "Flavien est déposé.", "translation": "Dioscore l''accuse d''avoir enfreint Nicée et Éphèse I."}, {"text": "Le Tome de Léon n''est pas lu.", "translation": "Faute de temps, selon le récit copte."}, {"text": "Léon parle du « brigandage d''Éphèse ».", "translation": "Ses adversaires nommeront ainsi ce concile."}], "commonErrors": [{"wrong": "Dioscore a refusé de lire le Tome par mépris.", "right": "La séance est close faute de temps par la lecture des lettres impériales.", "why": "Selon le récit copte, ce n''est pas un refus."}, {"wrong": "Éphèse II est un concile œcuménique reconnu par l''Église copte.", "right": "Les coptes reconnaissent trois conciles, mais défendent Dioscore.", "why": "Ce sont deux questions séparées."}], "tip": "449 : Dioscore préside, Flavien est déposé, le Tome n''est pas lu. 450 : Marcien."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g40.chalcedoine', 'eg', 'grammar', 'knowledge', 'Le concile de Chalcédoine (451)', 4, array['eg.g39.ephese_449']::text[], 5, '{"rule": {"summary": "Le concile de Chalcédoine (451), convoqué par Marcien à la demande de Léon, ratifie le Tome de Léon et définit le Christ « en deux natures » ; Dioscore est condamné et exilé. L''Église copte et d''autres Églises le refusent : c''est le premier schisme.", "explanation": "Marcien et Pulchérie réunissent des centaines d''évêques à Chalcédoine, en face de Constantinople ; Léon est absent mais ses légats sont là. Le Tome de Léon est lu puis ratifié : chaque nature garde ce qui lui est propre. Eutychès est anathématisé, Dioscore condamné et exilé, et le concile donne à Constantinople la seconde place après Rome (canon 28). Plusieurs évêques refusent « deux natures », y voyant du nestorianisme et une innovation : l''Église se divise entre l''Est non-chalcédonien (Alexandrie et Antioche) et l''Ouest chalcédonien (Rome et Constantinople).", "pattern": "451, Chalcédoine : Marcien convoque, Tome ratifié, « deux natures », Dioscore exilé, premier schisme.", "examples": [{"text": "Marcien et Pulchérie assistent au concile.", "translation": "Léon est absent, mais ses légats le représentent."}, {"text": "Le Tome de Léon est ratifié.", "translation": "Chaque nature garde ce qui lui est propre."}, {"text": "Dioscore est condamné et exilé.", "translation": "Il refuse de signer la définition."}, {"text": "L''Église copte rejette Chalcédoine.", "translation": "Elle ne reconnaît que trois conciles."}], "commonErrors": [{"wrong": "Chalcédoine a été rejeté parce que les coptes nient la divinité.", "right": "Les coptes confessent un Christ complètement Dieu et complètement homme.", "why": "Le désaccord porte sur « deux natures »."}, {"wrong": "Le schisme de 451 est celui de Rome contre Constantinople.", "right": "Ce schisme-là date de 1054. En 451, la rupture est entre Alexandrie et Antioche d''un côté, Rome et Constantinople de l''autre.", "why": "Deux schismes, deux dates."}], "tip": "451 : « deux natures » → Alexandrie et Antioche refusent → premier schisme."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g41.dioscore', 'eg', 'grammar', 'knowledge', 'Saint Dioscore d''Alexandrie', 4, array['eg.g40.chalcedoine']::text[], 5, '{"rule": {"summary": "Saint Dioscore, 25e pape d''Alexandrie (444-454), ancien archidiacre de Cyrille, est accusé de trois fautes dont la tradition copte conteste le bien-fondé ; condamné à Chalcédoine, exilé à Gangra, il est vénéré comme confesseur de la foi.", "explanation": "Dioscore est le fidèle disciple de Cyrille. Ses accusateurs lui reprochent d''avoir accepté l''erreur d''Eutychès, condamné Flavien sans raison et refusé de lire le Tome de Léon. La tradition copte répond : il enseigne que le Christ est UN, Flavien avait enfreint Nicée et Éphèse I, et le Tome n''a pas été lu faute de temps. Selon les actes de Chalcédoine, il est déposé pour sa conduite et pour avoir refusé de comparaître, non pour une hérésie. Exilé à Gangra, il y meurt en 454. L''Église copte le vénère comme confesseur.", "pattern": "Dioscore : 25e pape, trois accusations, exil à Gangra, mort en 454, confesseur.", "examples": [{"text": "Dioscore est l''archidiacre de Cyrille.", "translation": "Il connaît de près la foi de son maître."}, {"text": "On l''accuse de trois fautes.", "translation": "La tradition copte les conteste."}, {"text": "Il est exilé à Gangra.", "translation": "Il y meurt en 454."}, {"text": "L''Église copte le vénère comme confesseur.", "translation": "Il a souffert pour la foi sans mourir martyr."}], "commonErrors": [{"wrong": "Dioscore a été condamné pour hérésie.", "right": "Selon les actes de Chalcédoine, il est déposé pour sa conduite et son refus de comparaître.", "why": "Il n''est pas condamné pour une erreur de foi."}, {"wrong": "Dioscore est monophysite comme Eutychès.", "right": "Il enseigne que le Christ est UN, Dieu et homme.", "why": "Il suit Cyrille, pas Eutychès."}], "tip": "Dioscore = disciple de Cyrille, trois accusations, Gangra, 454, confesseur."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g42.miaphysisme', 'eg', 'grammar', 'knowledge', 'Le miaphysisme', 4, array['eg.g41.dioscore']::text[], 5, '{"rule": {"summary": "L''Église copte confesse le miaphysisme : une seule nature du Verbe incarné, pleinement humaine et pleinement divine, sans mélange ni division. Ce n''est ni le monophysisme d''Eutychès (humanité absorbée) ni le dyophysisme de Chalcédoine (deux natures).", "explanation": "Physis veut dire « nature ». Mono = un seul, dyo = deux, mia = une seule (unie). Le monophysisme d''Eutychès supprime l''humanité ; le dyophysisme de Chalcédoine distingue deux natures, chacune gardant son caractère ; le miaphysisme de Cyrille confesse une seule nature du Verbe incarné, où le divin et l''humain ne sont ni mélangés ni divisés. L''Église copte condamne Eutychès et refuse seulement l''expression « deux natures ».", "pattern": "Mono = Eutychès ; Dyo = Chalcédoine ; Mia = Cyrille et l''Église copte.", "examples": [{"text": "physis = nature en grec.", "translation": "Mono, dyo, mia se collent devant physis."}, {"text": "L''Église copte est miaphysite.", "translation": "Une seule nature du Verbe incarné."}, {"text": "Eutychès est monophysite.", "translation": "L''Église copte le condamne."}, {"text": "Chalcédoine est dyophysite.", "translation": "Deux natures, chacune gardant ses propriétés."}], "commonErrors": [{"wrong": "L''Église copte est monophysite.", "right": "Elle est miaphysite : elle condamne le monophysisme d''Eutychès.", "why": "Mono : humanité absorbée ; Mia : humanité complète."}, {"wrong": "Le miaphysisme nie l''humanité du Christ.", "right": "Il confesse un Christ pleinement humain et pleinement divin.", "why": "Aucun des deux éléments ne disparaît."}], "tip": "Mono supprime l''humanité, dyo distingue deux natures, mia unit sans mélange ni division."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g43.schisme_et_suites', 'eg', 'grammar', 'knowledge', 'Les suites du schisme (482-641)', 4, array['eg.g42.miaphysisme']::text[], 5, '{"rule": {"summary": "Après Chalcédoine, l''empereur Zénon tente l''apaisement par l''Hénotikon (482), puis Justinien persécute les non-chalcédoniens (à partir de 527) et nomme en 538 un patriarche chalcédonien d''Alexandrie : l''Égypte a dès lors deux patriarches, l''un melkite, l''autre copte.", "explanation": "Après 451, les empereurs cherchent la paix religieuse. En 482, Zénon publie l''Hénotikon, qui réaffirme Nicée et Constantinople, condamne Nestorius et Eutychès, mais interdit de soulever la question des natures. Le texte ne satisfait personne. Dès 527, des persécutions touchent les non-chalcédoniens, jusqu''à la conquête arabe de l''Égypte (vers 640). En 538, Justinien nomme le premier patriarche chalcédonien d''Alexandrie. Ses fidèles sont les melkites, ceux du roi (malka). Dès lors l''Égypte a deux patriarches d''Alexandrie.", "pattern": "482 Hénotikon ; 527 persécutions ; 538 Justinien nomme un patriarche chalcédonien ; deux papes.", "examples": [{"text": "L''empereur Zénon publie l''Hénotikon en 482.", "translation": "Il interdit de discuter des natures."}, {"text": "Justinien nomme un patriarche en 538.", "translation": "Il vient de Constantinople."}, {"text": "Les melkites sont les chrétiens fidèles à l''empereur.", "translation": "Du syriaque malka, « roi »."}, {"text": "Macaire d''Edkou est un martyr de ces persécutions.", "translation": "Un témoin de la fidélité copte."}], "commonErrors": [{"wrong": "L''Hénotikon règle la question des natures.", "right": "Il l''interdit sans la trancher.", "why": "Il ne satisfait personne."}, {"wrong": "Les melkites sont les coptes.", "right": "Les melkites ont accepté Chalcédoine.", "why": "Les coptes sont non-chalcédoniens."}], "tip": "482 Hénotikon, 538 Justinien, melkites = fidèles à l''empereur, deux patriarches à Alexandrie."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g44.deux_familles', 'eg', 'grammar', 'knowledge', 'Les familles orthodoxes et le dialogue', 4, array['eg.g43.schisme_et_suites']::text[], 5, '{"rule": {"summary": "Les Églises orthodoxes orientales (dont l''Église copte) reconnaissent trois conciles ; les Églises chalcédoniennes en reconnaissent sept. Six Églises sœurs sont en intercommunion et un dialogue, marqué par l''accord de 1989 à Amba Bichoï, a constaté la même christologie.", "explanation": "L''Église copte est en intercommunion avec cinq autres Églises non-chalcédoniennes : syriaque, éthiopienne, indienne, érythréenne et arménienne. Elles forment les Églises orthodoxes orientales. En face, les Églises chalcédoniennes (byzantines) acceptent les sept conciles. Au XXe siècle, de nombreux dialogues ont eu lieu ; en 1989, au monastère Amba Bichoï de Scété, des accords de foi ont été signés. Les deux familles ont convenu qu''elles ont la même christologie. Il ne reste plus que les anathèmes. Rome et Constantinople, elles, se sont séparées plus tard, en 1054.", "pattern": "3 conciles / 7 conciles ; 6 Églises sœurs ; 1989 : accord à Amba Bichoï ; même christologie.", "examples": [{"text": "L''Église copte est en intercommunion avec cinq autres Églises.", "translation": "Ce sont ses Églises sœurs."}, {"text": "Les Églises chalcédoniennes reconnaissent sept conciles.", "translation": "Les quatre derniers sont absents chez les coptes."}, {"text": "En 1989, un accord est signé à Amba Bichoï.", "translation": "Les deux familles disent avoir la même christologie."}, {"text": "En 1054, Rome et Constantinople se séparent.", "translation": "C''est le grand schisme, un autre événement."}], "commonErrors": [{"wrong": "Les Églises orthodoxes orientales sont les grecques orthodoxes.", "right": "Les orientales sont non-chalcédoniennes ; les grecques sont chalcédoniennes.", "why": "Deux familles distinctes."}, {"wrong": "Le schisme de 1054 est celui de Chalcédoine.", "right": "Il oppose Rome et Constantinople, 600 ans plus tard.", "why": "451 ≠ 1054."}], "tip": "Trois conciles, six Églises sœurs, 1989 à Amba Bichoï, 1054 = autre schisme."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g45.logique_des_conciles', 'eg', 'grammar', 'knowledge', 'La logique des conciles', 2, array['eg.g33.cinq_sieges']::text[], 6, '{"rule": {"summary": "Un concile est une assemblée d''évêques qui décide ensemble d''une question de foi (formule de foi, anathèmes) ou de discipline (canons). Il est œcuménique quand il réunit toute l''Église et qu''elle le reçoit ; l''Église copte en reconnaît trois : Nicée (325), Constantinople (381), Éphèse (431).", "explanation": "Le modèle est le concile de Jérusalem (vers 49) : on se réunit, on écoute, on s''appuie sur l''Écriture, on décide ensemble. À partir de Constantin, l''empereur convoque, mais ce sont les évêques qui disent la foi. Un synode est un concile local ; un concile œcuménique concerne toute l''Église. Presque toujours, une erreur provoque un concile, qui répond par une formule de foi.", "pattern": "Erreur → concile → formule de foi (+ anathèmes + canons) → réception.", "examples": [{"text": "Vers 49", "translation": "Le concile de Jérusalem sert de modèle à tous les autres."}, {"text": "325, 381, 431", "translation": "Les trois conciles reconnus par l''Église copte."}, {"text": "Synode ≠ concile œcuménique", "translation": "Un synode est local, un concile œcuménique est universel."}, {"text": "Anathème ≠ canon", "translation": "Le premier condamne l''erreur, le second règle la vie de l''Église."}], "commonErrors": [{"wrong": "Un synode local peut définir la foi de toute l''Église.", "right": "Seul un concile œcuménique engage toute l''Église.", "why": "Antioche 269 ou Constantinople 448 ne sont pas œcuméniques."}, {"wrong": "L''empereur décide de la foi.", "right": "L''empereur convoque ; les évêques disent la foi.", "why": "Quand il s''en mêle trop, les crises s''aggravent."}, {"wrong": "Les canons et les formules de foi, c''est la même chose.", "right": "Les canons règlent la vie de l''Église ; les formules de foi disent qui est Dieu et le Christ.", "why": "Le canon 3 de 381 est une règle de rang, pas une formule de foi."}], "tip": "Pour chaque concile, pose trois questions : quelle erreur ? quelle formule ? quels canons ?"}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g46.heresies_dieu_trinite', 'eg', 'grammar', 'knowledge', 'Les hérésies sur Dieu et la Trinité', 3, array['eg.g45.logique_des_conciles']::text[], 6, '{"rule": {"summary": "Les hérésies sur Dieu portent sur le Père, le Fils et l''Esprit. Les gnostiques et Marcion divisent Dieu en deux ; Montan prétend ajouter une révélation ; Paul de Samosate et Arius rabaissent le Fils ; Sabellius confond les trois personnes ; Macédonius nie la divinité de l''Esprit.", "explanation": "L''Église confesse la Sainte Trinité : trois personnes, une seule divinité. Toutes ces erreurs se rangent en deux familles : celles qui diminuent une personne (Paul, Arius, Macédonius) et celles qui confondent ou divisent (Sabellius, Marcion, les gnostiques). Chaque réponse s''appuie sur l''Écriture, la tradition et les évêques, puis sur des conciles : Antioche (269), Nicée (325), Constantinople (381).", "pattern": "Dieu est un : trois personnes, une seule divinité. Ni on divise Dieu, ni on rabaisse une personne, ni on confond les trois.", "examples": [{"text": "Vers 140 : Marcion", "translation": "Deux dieux, un Dieu de justice et un Dieu d''amour."}, {"text": "269 : Paul de Samosate", "translation": "Le Christ est un homme ordinaire ; il est excommunié à Antioche."}, {"text": "325 : Arius", "translation": "Le Fils est une créature ; Nicée répond homoousios."}, {"text": "381 : Macédonius", "translation": "L''Esprit serait créé ; Constantinople complète le credo."}], "commonErrors": [{"wrong": "Sabellius et Arius disent la même chose.", "right": "Sabellius confond les personnes ; Arius rabaisse le Fils.", "why": "Ce sont deux erreurs opposées."}, {"wrong": "Montan nie la divinité de l''Esprit.", "right": "Montan prétend parler au nom de l''Esprit et ajouter une prophétie.", "why": "Celui qui nie la divinité de l''Esprit, c''est Macédonius."}, {"wrong": "Le semi-arianisme est la foi de Nicée.", "right": "Les semi-ariens disent « substance similaire », Nicée dit « même substance ».", "why": "Entre homoiousios et homoousios, un iota fait toute la différence."}], "tip": "Fais trois paquets : Dieu (gnose, Marcion), le Fils (Paul, Arius), l''Esprit (Montan, Macédonius), et un intrus qui confond tout : Sabellius."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g47.heresies_christ', 'eg', 'grammar', 'knowledge', 'Les hérésies sur le Christ', 3, array['eg.g46.heresies_dieu_trinite']::text[], 6, '{"rule": {"summary": "Les erreurs sur le Christ vont dans tous les sens : les docètes lui retirent un vrai corps, Apollinaire une âme humaine, Nestorius sépare le Verbe de l''homme, Eutychès fait disparaître l''humanité dans la divinité. Saint Cyrille tient la foi juste : une seule nature du Verbe incarné, sans mélange ni division.", "explanation": "La foi de l''Église : le Christ est un seul Christ, pleinement Dieu et pleinement homme. Trois erreurs diminuent l''humanité (docétisme, apollinarisme, monophysisme) et une brise l''unité (nestorianisme). Chaque réponse défend le salut : seul un Dieu vraiment homme peut sauver l''homme. L''Église copte condamne Nestorius et Eutychès, et confesse le miaphysisme de Cyrille.", "pattern": "Nestorius sépare ; Eutychès mélange ; Cyrille garde l''unité sans mélange ni division.", "examples": [{"text": "Docétisme", "translation": "Corps apparent ; Jean et Ignace répondent."}, {"text": "Apollinaire, 381", "translation": "Pas d''âme humaine ; condamné à Constantinople."}, {"text": "Nestorius, 431", "translation": "Sépare le Verbe de l''homme ; condamné à Éphèse."}, {"text": "Eutychès, 448-449", "translation": "Humanité absorbée ; condamné à Constantinople (448) puis par l''Église copte."}], "commonErrors": [{"wrong": "Les coptes sont monophysites.", "right": "Les coptes sont miaphysites, comme Cyrille.", "why": "Ils condamnent Eutychès, le monophysite."}, {"wrong": "Nestorius et Eutychès disent la même chose.", "right": "Nestorius sépare, Eutychès mélange.", "why": "Ce sont deux erreurs opposées."}, {"wrong": "Apollinaire nie la divinité du Christ.", "right": "Apollinaire nie son âme humaine.", "why": "Il défendait Nicée, mais allait trop loin sur l''humanité."}], "tip": "Pour chaque erreur, demande : qu''est-ce qui manque au Christ ? Un vrai corps, une âme, l''unité ou l''humanité ?"}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g48.fiche_nicee', 'eg', 'grammar', 'knowledge', 'Nicée 325 en fiche', 3, array['eg.g28.concile_de_nicee']::text[], 6, '{"rule": {"summary": "Nicée (325) est le premier concile œcuménique : convoqué par Constantin, avec 318 évêques selon la tradition, il condamne Arius, proclame le Fils homoousios (consubstantiel) au Père, rédige le credo, des anathèmes et vingt canons. L''Église copte le reconnaît : Alexandrie y tient le premier rôle (Alexandre, Athanase).", "explanation": "Constantin veut un empire uni, et la querelle d''Arius le divise. Le concile se réunit à Nicée en 325. Le pape Alexandre préside selon la tradition copte, assisté du jeune diacre Athanase. Le credo affirme le mot homoousios ; 315 évêques sur 318 signent d''abord et trois refusent les anathèmes, avant de céder sous la pression de l''empereur. L''arianisme survivra, d''où le concile de 381.", "pattern": "Nicée : Constantin, 325, 318 évêques, contre Arius, homoousios.", "examples": [{"text": "325", "translation": "Premier concile œcuménique, à Nicée."}, {"text": "318 évêques", "translation": "Selon la tradition ; 315 signent d''abord."}, {"text": "Alexandre et Athanase", "translation": "Le pape préside, le diacre expose les erreurs d''Arius."}, {"text": "Homoousios", "translation": "Le Fils est de même substance que le Père."}], "commonErrors": [{"wrong": "Nicée a inventé la divinité du Christ.", "right": "Nicée la confesse avec un mot précis, pour répondre à Arius.", "why": "La foi des apôtres est la même, le mot est neuf."}, {"wrong": "Nicée a écrit tout le credo que nous récitons.", "right": "Nicée parle du Père et du Fils et finit par « et en l''Esprit Saint » ; 381 développe l''Esprit Saint et ajoute la suite.", "why": "D''où le nom credo de Nicée-Constantinople."}, {"wrong": "Eusèbe de Césarée et Eusèbe de Nicomédie sont le même homme.", "right": "L''un est l''historien (Césarée), l''autre le puissant défenseur d''Arius (Nicomédie).", "why": "Deux évêques, deux villes."}], "tip": "Nicée en un seul mot : homoousios. Nicée en cinq repères : Constantin, 325, 318, Arius, Athanase."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g49.fiches_381_431', 'eg', 'grammar', 'knowledge', 'Constantinople 381 et Éphèse 431 en fiches', 3, array['eg.g48.fiche_nicee']::text[], 6, '{"rule": {"summary": "Constantinople (381) : Théodose Ier, 150 évêques, contre Apollinaire et Macédonius ; le credo est complété sur le Saint-Esprit et sept canons sont votés. Éphèse (431) : Théodose II, environ deux cents évêques, présidé par Cyrille ; Nestorius est condamné et déposé, Marie est proclamée Théotokos, le credo est confirmé.", "explanation": "Les deux conciles complètent Nicée. 381 règle la question de l''Esprit Saint, que les pneumatomaques nient. 431 règle celle de l''unité du Christ : celui qui naît de Marie est Dieu le Verbe. À Constantinople, le canon 3 (deuxième place d''honneur) est refusé par Alexandrie. À Éphèse, Jean d''Antioche arrive en retard et tient un concile rival, avant la formule d''union de 433.", "pattern": "381 : l''Esprit Saint. 431 : Marie Théotokos. Même grille que Nicée.", "examples": [{"text": "381", "translation": "Théodose Ier, 150 évêques, Apollinaire et Macédonius condamnés, credo complété."}, {"text": "431", "translation": "Théodose II, environ deux cents évêques, Nestorius condamné, Théotokos."}, {"text": "Canon 3 (381)", "translation": "Constantinople, deuxième après Rome : refusé par Alexandrie."}, {"text": "Credo interdit", "translation": "Éphèse interdit d''en composer un autre."}], "commonErrors": [{"wrong": "Nestorius est condamné à Constantinople.", "right": "Il est condamné à Éphèse en 431.", "why": "Constantinople (381) condamne Apollinaire et Macédonius."}, {"wrong": "Cyrille est absent d''Éphèse.", "right": "Cyrille préside Éphèse, avec l''appui de Rome.", "why": "Nestorius, lui, refuse de comparaître."}, {"wrong": "Le credo de Nicée-Constantinople est l''œuvre de Nicée seul.", "right": "Nicée écrit la première partie, Constantinople ajoute la suite sur l''Esprit Saint.", "why": "Éphèse le confirme et interdit d''en composer un autre."}], "tip": "381 = l''Esprit, 431 = Marie. Cinquante ans d''écart environ, une question chaque fois."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g50.fiches_449_451', 'eg', 'grammar', 'knowledge', 'Éphèse II (449) et Chalcédoine (451) en fiches', 4, array['eg.g49.fiches_381_431']::text[], 6, '{"rule": {"summary": "Éphèse II (449) : convoqué par Théodose II et présidé par Dioscore, il réhabilite Eutychès et dépose Flavien ; Léon Ier le nomme « brigandage ». Chalcédoine (451) : convoqué par Marcien, il ratifie le Tome de Léon, définit un seul Christ en deux natures, dépose Dioscore et vote le canon 28 : c''est le premier schisme. L''Église copte ne le reçoit pas.", "explanation": "Après la mort de Théodose II en 450, Pulchérie épouse Marcien, qui convoque un concile pour annuler Éphèse II. À Chalcédoine, Léon est représenté par ses légats ; Dioscore est déposé pour sa conduite (selon les actes), non pour une hérésie, et exilé à Gangra, où il meurt en 454. Pour les coptes, « deux natures » sépare ce que Cyrille a uni et enfreint l''interdit d''Éphèse de changer le credo ; ils honorent Dioscore comme confesseur.", "pattern": "449 : Dioscore préside, Flavien déposé. 451 : Marcien, deux natures, Dioscore exilé, canon 28.", "examples": [{"text": "449", "translation": "Éphèse II : Théodose II, Dioscore préside, Eutychès réhabilité, Flavien déposé."}, {"text": "451", "translation": "Chalcédoine : Marcien, Tome de Léon ratifié, deux natures, Dioscore exilé."}, {"text": "Gangra", "translation": "Lieu de l''exil de Dioscore ; il y meurt en 454."}, {"text": "Canon 28", "translation": "Constantinople, seconde place après Rome ; Léon le refuse."}], "commonErrors": [{"wrong": "Éphèse II est le troisième concile œcuménique.", "right": "Le troisième est Éphèse I (431). Éphèse II (449) est annulé par Chalcédoine.", "why": "431 ≠ 449."}, {"wrong": "Dioscore est condamné à Chalcédoine pour hérésie.", "right": "Selon les actes, il est déposé pour sa conduite et son refus de comparaître.", "why": "L''Église copte le vénère comme confesseur."}, {"wrong": "Chalcédoine condamne Eutychès et les coptes sont d''accord avec toutes ses décisions.", "right": "Les coptes condamnent aussi Eutychès, mais refusent la formule « deux natures ».", "why": "Ce n''est pas un désaccord sur Eutychès."}], "tip": "Éphèse II = Dioscore préside ; Chalcédoine = Dioscore jugé. Les deux dates se suivent : 449, 451."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g51.frise_et_liens', 'eg', 'grammar', 'knowledge', 'Frise et liens : tout remettre en ordre', 3, array['eg.g50.fiches_449_451']::text[], 6, '{"rule": {"summary": "Les conciles et les hérésies s''enchaînent dans le temps : gnose et docétisme (Ier-IIe), Marcion (vers 140), Montan (vers 170), Novatien (251), Paul de Samosate (269), Arius (vers 318, Nicée 325), Macédonius et Apollinaire (381), Nestorius (431), Eutychès (448-449), Chalcédoine (451), Hénotikon (482).", "explanation": "Chaque erreur a son concile et son défenseur : Arius et Nicée avec Athanase, Macédonius et Apollinaire à Constantinople avec Timothée, Nestorius à Éphèse avec Cyrille, Eutychès avec Flavien puis Dioscore pour les coptes. Les erreurs vont souvent par paires opposées. D''autres crises ne touchent pas à la foi : Novatien (le pardon des tombés), la date de Pâques, les rangs entre sièges (canons 3 et 28).", "pattern": "Frise : 49, 140, 170, 251, 269, 318, 325, 381, 431, 449, 451, 482.", "examples": [{"text": "Vers 318 → 325", "translation": "Arius puis Nicée, Athanase défend."}, {"text": "428 → 431", "translation": "Nestorius puis Éphèse, Cyrille défend."}, {"text": "448 → 449 → 451", "translation": "Eutychès, Éphèse II, Chalcédoine."}, {"text": "482", "translation": "Hénotikon de Zénon : édit d''union, silence sur les natures."}], "commonErrors": [{"wrong": "Novatien est un hérétique sur la Trinité.", "right": "Novatien est en désaccord sur la discipline (le pardon des tombés).", "why": "Son Église des purs dure pourtant plusieurs siècles."}, {"wrong": "L''Hénotikon règle le désaccord de Chalcédoine.", "right": "Il interdit de poser la question et ne satisfait personne.", "why": "Le schisme demeure."}, {"wrong": "Les conciles viennent dans l''ordre des hérésies et sans lien.", "right": "Chaque concile répond à une erreur précise.", "why": "D''où l''intérêt de la frise."}], "tip": "Pour une date, demande-toi : quelle erreur, quel concile, quel défenseur ?"}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g52.bilan_formules_dates', 'eg', 'grammar', 'knowledge', 'Bilan : formules, dates et pièges', 4, array['eg.g51.frise_et_liens']::text[], 6, '{"rule": {"summary": "Trois formules à retenir : homoousios (Nicée, 325), Théotokos (Éphèse, 431) et « une seule nature du Verbe incarné » (saint Cyrille). Cinq dates : 325, 381, 431, 449, 451. Pièges : monophysisme ≠ miaphysisme ; Éphèse 431 ≠ Éphèse 449 ; concile de 381 ≠ synode de 448.", "explanation": "Toute la synthèse tient en trois formules et cinq dates. La première (homoousios) dit que le Fils est Dieu ; la deuxième (Théotokos) dit que celui qui naît de Marie est Dieu le Verbe ; la troisième (Cyrille) dit que le Christ est un, sans mélange ni division. Les coptes reconnaissent 325, 381 et 431, et refusent Chalcédoine (451) tout en condamnant Eutychès.", "pattern": "3 formules, 5 dates, 3 conciles reconnus, 1 schisme (451).", "examples": [{"text": "Homoousios", "translation": "Nicée, 325 : le Fils est consubstantiel au Père."}, {"text": "Théotokos", "translation": "Éphèse, 431 : Marie, mère de Dieu."}, {"text": "Une seule nature du Verbe incarné", "translation": "Cyrille : le miaphysisme de l''Église copte."}, {"text": "449 et 451", "translation": "Éphèse II et Chalcédoine : les deux conciles qui divisent."}], "commonErrors": [{"wrong": "Les coptes sont monophysites.", "right": "Les coptes sont miaphysites.", "why": "Ils condamnent Eutychès, qui est monophysite."}, {"wrong": "Éphèse, c''est un seul concile.", "right": "Éphèse I (431) et Éphèse II (449) sont deux conciles différents.", "why": "Seul le premier est reconnu."}, {"wrong": "Le schisme de 451 est le même que celui de 1054.", "right": "Ce sont deux schismes distincts.", "why": "451 sépare les deux familles orthodoxes ; 1054 sépare Rome et Constantinople."}], "tip": "Révise avec ce fil : 325 le Fils, 381 l''Esprit, 431 Marie, 449 Dioscore préside, 451 deux natures."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g53.familles_eglises', 'eg', 'grammar', 'knowledge', 'Les familles d''Églises aujourd''hui', 1, '{}'::text[], 7, '{"rule": {"summary": "Les chrétiens se répartissent en quatre grandes familles : les Églises orthodoxes orientales (dont la nôtre), les orthodoxes chalcédoniens, les catholiques et les protestants.", "explanation": "Trois questions suffisent pour s''y retrouver. Reçoit-on le concile de Chalcédoine (451) ? Reconnaît-on l''autorité du pape ? La Bible seule suffit-elle, ou faut-il aussi la Tradition ? Les Églises orthodoxes orientales répondent non, non, et « Bible et Tradition ». Les orthodoxes chalcédoniens reçoivent Chalcédoine mais pas le pape. Les catholiques reçoivent les deux. Les protestants viennent de la Réforme et s''appuient sur la Bible seule.", "pattern": "Chalcédoine ? Pape ? Bible seule ? → copte : non, non, non.", "examples": [{"text": "L''Église copte, l''Église arménienne et l''Église éthiopienne.", "translation": "Trois Églises orthodoxes orientales."}, {"text": "L''Église grecque et l''Église russe.", "translation": "Deux Églises orthodoxes chalcédoniennes."}, {"text": "L''Église catholique latine et l''Église catholique copte.", "translation": "Deux Églises en communion avec le pape."}, {"text": "Les luthériens, les presbytériens et les baptistes.", "translation": "Trois familles protestantes."}], "commonErrors": [{"wrong": "Les Coptes sont des orthodoxes grecs.", "right": "Les Coptes sont des orthodoxes orientaux.", "why": "Les orthodoxes grecs reçoivent Chalcédoine, pas les Coptes."}, {"wrong": "L''Église catholique copte est la même Église que la nôtre.", "right": "C''est une Église distincte, en communion avec le pape.", "why": "Elle a la liturgie copte mais obéit au pape."}, {"wrong": "Tous les protestants forment une seule Église.", "right": "Le protestantisme regroupe de nombreuses Églises.", "why": "Il n''a pas de chef unique."}], "tip": "Retiens les trois questions : Chalcédoine, pape, Bible seule."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g54.chalcedoine_orthodoxes', 'eg', 'grammar', 'knowledge', 'Les orthodoxes chalcédoniens et la christologie', 2, array['eg.g53.familles_eglises']::text[], 7, '{"rule": {"summary": "Les orthodoxes chalcédoniens reçoivent le concile de Chalcédoine (451) et parlent du Christ « en deux natures » ; nous gardons la formule de saint Cyrille : « une seule nature du Verbe incarné ».", "explanation": "Les deux familles confessent le même Christ, vrai Dieu et vrai homme, né de la Vierge Marie. Elles sont d''accord contre Nestorius, qui divise le Christ, et contre Eutychès, qui mélange divinité et humanité. La rupture vient de Chalcédoine (451), qui a déposé Dioscore d''Alexandrie et adopté une formule en deux natures que l''Église d''Alexandrie jugeait trop proche de Nestorius. Depuis 1989-1990, les dialogues constatent que la foi est la même et que le désaccord est en grande partie verbal.", "pattern": "Chalcédoine : « en deux natures » ; Cyrille : « une seule nature du Verbe incarné ».", "examples": [{"text": "Le Christ est un seul Seigneur, vrai Dieu et vrai homme.", "translation": "C''est la foi commune aux deux familles."}, {"text": "Dioscore est déposé en 451 et meurt en exil en 454.", "translation": "Nous le vénérons comme confesseur de la foi."}, {"text": "Les chalcédoniens reçoivent sept conciles, nous trois.", "translation": "Chalcédoine est le premier concile qui nous divise."}, {"text": "En 1989, des théologiens se réunissent à Anba Bishoy.", "translation": "Ils constatent qu''ils confessent la même foi."}], "commonErrors": [{"wrong": "Les Coptes sont monophysites comme Eutychès.", "right": "Les Coptes sont miaphysites, comme saint Cyrille.", "why": "Eutychès niait la pleine humanité du Christ ; l''Église copte le condamne aussi."}, {"wrong": "Chalcédoine a condamné Dioscore pour hérésie.", "right": "Dioscore a été déposé pour des raisons de procédure et de discipline.", "why": "Il a refusé de comparaître, mais n''a pas été condamné pour avoir enseigné l''erreur."}, {"wrong": "Les orthodoxes grecs adorent des saints à la place de Dieu.", "right": "Ils vénèrent les saints comme nous.", "why": "Les deux familles ont les mêmes sacrements et la même vénération."}], "tip": "Même Christ, deux formules : « en deux natures » ou « une seule nature du Verbe incarné »."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g55.papaute_filioque', 'eg', 'grammar', 'knowledge', 'La papauté, le Filioque et le schisme de 1054', 2, array['eg.g54.chalcedoine_orthodoxes']::text[], 7, '{"rule": {"summary": "Les catholiques reconnaissent la primauté et l''infaillibilité du pape et lisent le Credo avec le Filioque ; l''Église copte décide en concile et garde le Credo de 381 tel quel.", "explanation": "Pour les catholiques, le pape, successeur de Pierre, est le chef visible de l''Église ; Vatican I (1870) a défini son infaillibilité quand il enseigne ex cathedra. Pour nous, les évêques sont tous successeurs des apôtres et les grandes questions se règlent en concile. Le Filioque ajoute « et du Fils » au Credo de 381, sans concile : voilà ce que nous ne suivons pas. Ces différences ont conduit à la rupture de 1054 entre Rome et Constantinople. Aujourd''hui, le dialogue avance.", "pattern": "Pape chef + infaillible (Vatican I, 1870) ≠ évêques en concile ; Credo 381 + Filioque ≠ Credo 381.", "examples": [{"text": "En 1870, Vatican I définit l''infaillibilité du pape.", "translation": "C''est un dogme catholique, pas le nôtre."}, {"text": "Le Credo de 381 dit que l''Esprit procède du Père.", "translation": "Le Credo copte garde ce texte."}, {"text": "En 1054, Rome et Constantinople s''excommunient.", "translation": "C''est le grand schisme entre catholiques et orthodoxes."}, {"text": "En 1973, le pape Chenouda III visite Paul VI.", "translation": "Ils signent une déclaration commune sur le Christ."}], "commonErrors": [{"wrong": "L''infaillibilité veut dire que le pape ne peut pas pécher.", "right": "Elle concerne seulement l''enseignement solennel sur la foi et la morale.", "why": "Un pape peut pécher comme tout homme."}, {"wrong": "Les Coptes ont ajouté « et du Fils » au Credo.", "right": "L''Église copte dit seulement que l''Esprit procède du Père.", "why": "Le Filioque est un ajout de l''Occident."}, {"wrong": "Le schisme de 1054 sépare Rome des Coptes.", "right": "Il sépare Rome et Constantinople.", "why": "La séparation avec les Coptes date de 451."}], "tip": "Pape infaillible, Filioque, 1054 : trois points catholiques, trois points de dialogue."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g56.dogmes_usages_catholiques', 'eg', 'grammar', 'knowledge', 'Purgatoire, Immaculée Conception, azymes et célibat', 2, array['eg.g55.papaute_filioque']::text[], 7, '{"rule": {"summary": "Avec les catholiques, quatre points nous séparent : le purgatoire, l''Immaculée Conception, le pain sans levain et le célibat des prêtres ; nous partageons les sept sacrements, la vénération de Marie et des saints.", "explanation": "Les catholiques enseignent un purgatoire, dogme précisé en 1274, et l''Immaculée Conception de Marie, définie en 1854. L''Église copte prie pour les défunts, mais laisse le jugement à Dieu seul, et vénère Marie toute pure sans ce dogme. L''Église latine consacre du pain sans levain et demande le célibat des prêtres ; l''Église copte utilise du pain levé et ordonne des hommes mariés avant l''ordination. Ces points ne touchent ni la Trinité ni le Christ.", "pattern": "Purgatoire (1274), Immaculée Conception (1854), azymes, célibat : catholique ; nous : prière pour les défunts, pain levé, prêtres mariés possibles.", "examples": [{"text": "Le purgatoire est précisé au concile de Lyon II, en 1274.", "translation": "C''est un enseignement catholique."}, {"text": "L''Immaculée Conception est définie par Pie IX en 1854.", "translation": "Elle porte sur la conception de Marie."}, {"text": "Le qorban copte est un pain levé.", "translation": "L''hostie latine est un azyme."}, {"text": "Un prêtre copte peut être marié avant l''ordination.", "translation": "Un évêque est toujours moine."}], "commonErrors": [{"wrong": "L''Immaculée Conception, c''est la naissance virginale de Jésus.", "right": "C''est la conception de Marie sans péché originel.", "why": "La naissance virginale concerne Jésus, né de Marie sans père."}, {"wrong": "Les Coptes ne prient pas pour les défunts.", "right": "Les Coptes prient pour les défunts.", "why": "Ils les confient à la miséricorde de Dieu."}, {"wrong": "Tous les prêtres catholiques sont célibataires.", "right": "Dans l''Église latine en général ; les Églises catholiques orientales ordonnent aussi des hommes mariés.", "why": "La règle varie selon le rite."}], "tip": "Retiens : 1274, 1854, pain levé, prêtre marié."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g57.reforme_protestante', 'eg', 'grammar', 'knowledge', 'La Réforme : l''Écriture seule et la foi seule', 3, array['eg.g56.dogmes_usages_catholiques']::text[], 7, '{"rule": {"summary": "Les protestants naissent de la Réforme de 1517 et défendent l''Écriture seule et la foi seule ; l''Église copte garde l''Écriture et la Sainte Tradition, la foi et les œuvres.", "explanation": "En 1517 Luther dénonce la vente des indulgences et lance un mouvement de retour à la Bible : sola scriptura, sola fide. Calvin à Genève et les anglicans en Angleterre prolongent la Réforme. L''Église copte respecte l''amour des protestants pour la Bible, mais rappelle que l''Écriture est née dans l''Église et qu''elle s''accompagne de la Sainte Tradition. Elle garde aussi les livres deutérocanoniques de la Septante. Pour elle, le salut est un chemin : la grâce, la foi et les œuvres.", "pattern": "Réforme 1517 : Écriture seule + foi seule. Copte : Écriture + Tradition ; foi + œuvres.", "examples": [{"text": "En 1517, Luther proteste contre les indulgences.", "translation": "C''est le début de la Réforme."}, {"text": "Les protestants gardent 39 livres de l''Ancien Testament.", "translation": "Les Coptes en gardent davantage."}, {"text": "Jacques 2, 24 : l''homme est justifié par les œuvres et pas par la foi seulement.", "translation": "Les Coptes unissent foi et œuvres."}, {"text": "2 Thessaloniciens 2, 15 : « Gardez les traditions ».", "translation": "Paul demande de garder la parole et la lettre."}], "commonErrors": [{"wrong": "Les protestants ne croient pas en Jésus.", "right": "Les protestants confessent le Christ, vrai Dieu et vrai homme.", "why": "Ils partagent avec nous la foi en la Trinité."}, {"wrong": "Les Coptes pensent qu''on se sauve par ses œuvres seules.", "right": "Les Coptes croient que la grâce de Dieu précède tout.", "why": "Les œuvres répondent à la grâce, elles ne l''achètent pas."}, {"wrong": "Luther est le fondateur de l''Église anglicane.", "right": "Luther a fondé la Réforme allemande, les anglicans viennent de 1534.", "why": "Henri VIII rompt avec Rome."}], "tip": "1517, Écriture seule, foi seule ; nous : Écriture + Tradition, foi + œuvres."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g58.protestants_sacrements_saints', 'eg', 'grammar', 'knowledge', 'Sacrements, saints, icônes et succession apostolique', 3, array['eg.g57.reforme_protestante']::text[], 7, '{"rule": {"summary": "Nous avons sept sacrements, demandons la prière des saints, vénérons les icônes et gardons la succession apostolique ; la plupart des protestants ont deux sacrements, s''adressent à Dieu seul et n''ont pas d''icônes.", "explanation": "Pour nous, un sacrement est un signe visible par lequel Dieu donne sa grâce, et l''Église en compte sept. Les protestants gardent le baptême et la Cène. Nous demandons aux saints de prier pour nous, car ils sont vivants en Christ ; beaucoup de protestants citent 1 Timothée 2, 5 : un seul médiateur. Nous vénérons les icônes parce que Dieu s''est rendu visible en Jésus ; les réformés y voient un risque d''idolâtrie. Enfin nos évêques sont ordonnés en chaîne depuis les apôtres, tandis que les pasteurs protestants sont appelés par la communauté.", "pattern": "7 sacrements, saints, icônes, évêques en succession ≠ 2 sacrements, Dieu seul, peu d''images, pasteurs.", "examples": [{"text": "Baptême, chrismation, eucharistie, confession, onction, mariage, sacerdoce.", "translation": "Les sept sacrements de l''Église copte."}, {"text": "Marie dit : « Toutes les générations me diront bienheureuse » (Luc 1, 48).", "translation": "Nous la bénissons comme elle l''a annoncé."}, {"text": "Saint Basile : l''honneur rendu à l''image passe au modèle.", "translation": "C''est le principe de la vénération des icônes."}, {"text": "Tawadros II est le 118e successeur de saint Marc.", "translation": "La chaîne n''est pas interrompue."}], "commonErrors": [{"wrong": "Les Coptes adorent les saints et les icônes.", "right": "Les Coptes vénèrent les saints et les icônes, et n''adorent que Dieu.", "why": "L''honneur passe à celui qu''on représente."}, {"wrong": "Les protestants n''ont aucun sacrement.", "right": "La plupart en gardent deux : le baptême et la Cène.", "why": "Ils les prennent très au sérieux."}, {"wrong": "Les évêques coptes sont élus sans ordination.", "right": "Ils reçoivent l''imposition des mains d''autres évêques.", "why": "C''est la succession apostolique."}], "tip": "Compte : 7 contre 2, saints et icônes, évêques en chaîne."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g59.mormons_adventistes', 'eg', 'grammar', 'knowledge', 'Mormons et adventistes', 3, array['eg.g58.protestants_sacrements_saints']::text[], 7, '{"rule": {"summary": "Les mormons (1830) et les adventistes (1863) sont nés aux États-Unis au XIXe siècle ; les mormons ajoutent d''autres livres et ne croient pas à la Trinité, les adventistes gardent la Trinité mais ajoutent les écrits d''Ellen White, le samedi et le sommeil des morts.", "explanation": "Le XIXe siècle américain voit naître plusieurs mouvements qui se disent chrétiens. Les mormons suivent Joseph Smith, le Livre de Mormon et une doctrine où le Père, le Fils et l''Esprit sont trois êtres distincts. Les adventistes naissent de la prédiction ratée de William Miller en 1844 et de l''œuvre d''Ellen White. Pour l''Église copte, la foi a été « transmise aux saints une fois pour toutes » (Jude 3) : on n''y ajoute pas de nouveaux livres. Nous respectons les personnes et leur vie morale, tout en disant ce qui diffère.", "pattern": "Mormons : Joseph Smith, 1830, Livre de Mormon. Adventistes : Miller, 1844, Ellen White, samedi.", "examples": [{"text": "Le Livre de Mormon est publié en 1830.", "translation": "C''est le livre ajouté à la Bible par les mormons."}, {"text": "Le 22 octobre 1844, le Christ n''est pas revenu.", "translation": "C''est la Grande Déception."}, {"text": "Les adventistes observent le sabbat le samedi.", "translation": "L''Église copte célèbre le dimanche, jour de la Résurrection."}, {"text": "Les adventistes croient à la Trinité.", "translation": "Ils sont plus proches de nous que les mormons sur ce point."}], "commonErrors": [{"wrong": "Les adventistes ne croient pas à la Trinité.", "right": "Les adventistes croient à la Trinité.", "why": "Cette confusion est fréquente avec les témoins de Jéhovah."}, {"wrong": "Les mormons utilisent seulement la Bible.", "right": "Les mormons ajoutent le Livre de Mormon et d''autres textes.", "why": "C''est une différence centrale."}, {"wrong": "Miller a annoncé le retour du Christ en 1914.", "right": "Miller a annoncé 1843, puis le 22 octobre 1844.", "why": "1914 est une date des témoins de Jéhovah."}], "tip": "Mormons : 1830, Livre de Mormon. Adventistes : 1844, samedi."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g60.temoins_science_chretienne', 'eg', 'grammar', 'knowledge', 'Témoins de Jéhovah, Science chrétienne et points communs', 4, array['eg.g59.mormons_adventistes']::text[], 7, '{"rule": {"summary": "Les groupes récents nés aux États-Unis au XIXe siècle partagent des traits communs : un livre ou une autorité en plus de la Bible, un rejet de la Trinité (sauf les adventistes) et l''idée que la vraie foi serait à restaurer ; l''Église répond avec la Trinité, la Bible complète et la promesse du Christ.", "explanation": "Les témoins de Jéhovah (années 1870) disent que Jésus est le premier être créé et que l''Esprit est une force ; la Science chrétienne (1875, 1879) voit dans la matière et la maladie des illusions. Mormons, témoins de Jéhovah et scientistes rejettent la Trinité telle que Nicée l''a définie. Tous ont ajouté une autorité à la Bible. Nous répondons par la divinité du Christ (Jean 1, 1), par la personne du Saint-Esprit (Actes 5, 3-4), par la Bible complète (Jude 3) et par la promesse de Matthieu 16, 18. Nous parlons avec douceur et respect (1 Pierre 3, 15).", "pattern": "Autorité en plus de la Bible + Trinité niée + « restauration » ≠ Bible complète + Trinité + Église toujours fidèle.", "examples": [{"text": "Jean 1, 1 : « Le Verbe était Dieu ».", "translation": "Réponse à la thèse que Jésus est créé."}, {"text": "Actes 5, 3-4 : mentir à l''Esprit Saint, c''est mentir à Dieu.", "translation": "Réponse à la thèse d''une simple force."}, {"text": "Matthieu 16, 18 : les portes de l''enfer ne prévaudront pas.", "translation": "Réponse à l''idée d''une Église disparue."}, {"text": "1 Pierre 3, 15 : répondre avec douceur et respect.", "translation": "L''attitude à avoir avec chacun."}], "commonErrors": [{"wrong": "Les témoins de Jéhovah refusent tous les soins médicaux.", "right": "Ils refusent surtout les transfusions de sang.", "why": "Ils acceptent les médecins et les autres soins."}, {"wrong": "La Science chrétienne est la scientologie.", "right": "Ce sont deux mouvements différents, sans lien.", "why": "La scientologie est fondée dans les années 1950 par L. Ron Hubbard."}, {"wrong": "Tous les groupes récents rejettent la Trinité.", "right": "Les adventistes croient à la Trinité.", "why": "Les mormons, les témoins de Jéhovah et la Science chrétienne la rejettent."}], "tip": "Pour répondre : Jean 1, 1, Actes 5, 3-4, Jude 3, Matthieu 16, 18."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g61.origine_du_credo', 'eg', 'grammar', 'knowledge', 'Le Credo : d''où il vient', 1, '{}'::text[], 8, '{"rule": {"summary": "Le Credo est le résumé de la foi que l''Église confesse ; le nôtre, de Nicée-Constantinople, vient de deux conciles (325 et 381) et ne se modifie plus depuis Éphèse (431).", "explanation": "Credo veut dire « je crois » en latin. Les credos sont nés des confessions de foi des futurs baptisés. Le nôtre est le fruit de deux conciles : Nicée (325) pose l''essentiel sur le Fils, Constantinople (381) développe l''article sur l''Esprit Saint et achève le texte. Éphèse (431) interdit d''en composer un autre. L''Église copte le prie en disant « nous croyons », précédé d''une introduction à Marie, Mère de la vraie lumière.", "pattern": "Credo = Nicée (325) + Constantinople (381) ; Éphèse (431) : on n''y touche plus.", "examples": [{"text": "Credo : « je crois ».", "translation": "Le mot latin qui a donné son nom au texte."}, {"text": "Nicée (325) puis Constantinople (381).", "translation": "Les deux conciles qui ont écrit notre Credo."}, {"text": "Éphèse (431) interdit d''en composer un autre.", "translation": "Le texte reste le même depuis."}, {"text": "« En vérité, nous croyons… »", "translation": "L''ouverture copte du Credo."}], "commonErrors": [{"wrong": "Le Credo a été écrit en une fois à Nicée.", "right": "Il a été écrit en deux temps : Nicée (325) et Constantinople (381).", "why": "L''article sur l''Esprit Saint est développé en 381."}, {"wrong": "Chaque Église peut ajouter une phrase à son Credo.", "right": "Éphèse (431) interdit d''en composer un autre.", "why": "Le texte d''un concile œcuménique appartient à toute l''Église."}, {"wrong": "On dit « je crois » parce que la foi est personnelle.", "right": "On dit « nous croyons » : la foi est celle de toute l''Église.", "why": "Le texte des conciles et la prière copte sont au pluriel."}], "tip": "Credo = « je crois » ; 325 pour le Fils, 381 pour l''Esprit, 431 pour le verrou."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g62.pere_createur', 'eg', 'grammar', 'knowledge', 'Le Père, Pantocrator, créateur', 1, array['eg.g61.origine_du_credo']::text[], 8, '{"rule": {"summary": "Premier article : un seul Dieu, Dieu le Père, Pantocrator (Tout-Puissant), créateur du ciel et de la terre, des choses visibles et invisibles.", "explanation": "Le Credo commence par la source : Dieu le Père, seul Dieu, qui tient tout (Pantocrator). Il a créé le monde à partir de rien, et sa création est bonne. Les choses invisibles sont les anges, créatures spirituelles. Cet article écarte le paganisme, le dualisme, Marcion, les gnostiques et les manichéens, qui séparaient le Dieu créateur du Dieu sauveur ou jugeaient la matière mauvaise.", "pattern": "Un seul Dieu + Père + Pantocrator + créateur de tout, visible et invisible.", "examples": [{"text": "« Nous croyons en un seul Dieu, Dieu le Père. »", "translation": "Le Père est la source de la Trinité."}, {"text": "Pantocrator : Tout-Puissant, celui qui tient tout.", "translation": "Mot grec : pan (tout) et kratos (pouvoir)."}, {"text": "Créateur du ciel et de la terre.", "translation": "Dieu crée à partir de rien, et le monde est bon."}, {"text": "Les choses invisibles : les anges.", "translation": "Créatures spirituelles, pas des dieux."}], "commonErrors": [{"wrong": "Le monde est l''œuvre d''un dieu inférieur.", "right": "Le Dieu unique, Père de Jésus, a créé le monde.", "why": "Cela corrige les gnostiques et Marcion."}, {"wrong": "La matière est mauvaise.", "right": "Le monde que Dieu a créé est bon.", "why": "Dieu a vu que cela était très bon."}, {"wrong": "Les anges sont des dieux.", "right": "Les anges sont des créatures invisibles de Dieu.", "why": "Un seul Dieu : on adore Dieu seul."}], "tip": "Un seul Dieu, tout part de lui, tout est bon, tout est à lui."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g63.fils_consubstantiel', 'eg', 'grammar', 'knowledge', 'Le Fils, Lumière de Lumière', 2, array['eg.g62.pere_createur']::text[], 8, '{"rule": {"summary": "Deuxième article : un seul Seigneur Jésus-Christ, Fils unique, engendré du Père avant tous les siècles, vrai Dieu, consubstantiel au Père, par qui tout a été fait. Chaque mot répond à Arius.", "explanation": "Chaque expression de cet article ferme une porte à Arius. « Fils unique » et « engendré avant tous les siècles » : le Fils est éternel. « Lumière de Lumière, vrai Dieu de vrai Dieu » : il est Dieu au même titre que le Père. « Engendré non créé » : il n''est pas une créature. « Consubstantiel » (homoousios) : même substance que le Père. « Par qui tout a été fait » : il est le Créateur avec le Père.", "pattern": "Fils éternel + vrai Dieu + engendré non créé + consubstantiel = contre Arius.", "examples": [{"text": "« Engendré du Père avant tous les siècles. »", "translation": "Le Fils est éternel."}, {"text": "« Lumière de Lumière, vrai Dieu de vrai Dieu. »", "translation": "Même divinité que le Père."}, {"text": "« Engendré non créé. »", "translation": "Il n''est pas une créature."}, {"text": "« Consubstantiel au Père, par qui tout a été fait. »", "translation": "Même substance, et Créateur avec le Père."}], "commonErrors": [{"wrong": "Le Fils est la première créature de Dieu.", "right": "Le Fils est engendré, non créé.", "why": "Engendré = de même nature que le Père."}, {"wrong": "Il fut un temps où le Fils n''était pas.", "right": "Le Fils est engendré avant tous les siècles.", "why": "Il est éternel, hors du temps."}, {"wrong": "Consubstantiel veut dire « de substance semblable ».", "right": "Il veut dire de même substance (homoousios).", "why": "Semblable, c''est homoiousios : un iota change tout."}], "tip": "Engendré, non créé : un fils a la nature de son père, un objet fabriqué non."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g64.incarnation_credo', 'eg', 'grammar', 'knowledge', 'Il s''incarna et se fit homme', 2, array['eg.g63.fils_consubstantiel']::text[], 8, '{"rule": {"summary": "Troisième article : pour nous les hommes et pour notre salut, le Fils descendit du ciel, s''incarna de l''Esprit Saint et de la Vierge Marie, et se fit homme.", "explanation": "Le Fils éternel ne cesse pas d''être Dieu quand il prend notre humanité : il prend ce qu''il n''était pas sans perdre ce qu''il était. Il naît de la Vierge Marie par l''action de l''Esprit Saint ; Marie est Théotokos. « Se fit homme » : un corps réel et une âme humaine, contre le docétisme et Apollinaire. Un seul sujet, le Fils, descend, s''incarne et souffre : c''est la clé de la foi miaphysite.", "pattern": "Pour nous et pour notre salut + Esprit Saint + Vierge Marie + vrai homme + un seul sujet.", "examples": [{"text": "« Pour nous les hommes et pour notre salut. »", "translation": "La raison de l''incarnation."}, {"text": "« Il s''incarna de l''Esprit Saint et de la Vierge Marie. »", "translation": "Conception virginale et Théotokos."}, {"text": "« Et se fit homme. »", "translation": "Un corps réel et une âme humaine."}, {"text": "Un seul sujet : le Fils.", "translation": "C''est lui qui descend, s''incarne et souffre."}], "commonErrors": [{"wrong": "Le Christ n''a eu qu''un corps apparent.", "right": "Il s''est fait vraiment homme.", "why": "Docétisme : corps apparent, rejeté par le Credo."}, {"wrong": "Le Verbe a pris un corps sans âme humaine.", "right": "Il a pris un homme entier.", "why": "Apollinaire : condamné en 381."}, {"wrong": "Marie ne porte qu''un homme, Jésus.", "right": "Marie porte le Verbe fait chair : elle est Théotokos.", "why": "Celui qu''elle enfante est Dieu le Verbe."}], "tip": "Un seul « Il » dans tout le Credo : celui qui est Dieu est celui qui naît et qui souffre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g65.passion_et_gloire', 'eg', 'grammar', 'knowledge', 'Crucifié, ressuscité, il reviendra', 2, array['eg.g64.incarnation_credo']::text[], 8, '{"rule": {"summary": "Quatrième article : crucifié pour nous sous Ponce Pilate, il souffrit, fut enseveli, ressuscita le troisième jour selon les Écritures, monta aux cieux, siège à la droite du Père, reviendra juger les vivants et les morts ; son règne n''aura pas de fin.", "explanation": "Cet article raconte l''histoire du salut en sept verbes : crucifié, souffrit, enseveli, ressuscita, monta, s''assit, reviendra. Le nom de Pilate ancre la croix dans l''histoire. La résurrection, annoncée par les Écritures, est le fondement de la foi. L''ascension et la droite du Père disent que l''humanité du Christ est glorifiée. Il reviendra dans la gloire pour juger, et son règne n''aura pas de fin.", "pattern": "Crucifié → enseveli → ressuscité → monté → assis → reviendra → règne sans fin.", "examples": [{"text": "« Crucifié pour nous sous Ponce Pilate. »", "translation": "Un fait historique, accompli pour nous."}, {"text": "« Ressuscita le troisième jour selon les Écritures. »", "translation": "La résurrection annoncée par les prophètes."}, {"text": "« Il monta aux cieux, s''assit à la droite du Père. »", "translation": "Honneur et puissance, avec notre humanité."}, {"text": "« Son règne n''aura pas de fin. »", "translation": "Le Christ est Roi pour toujours."}], "commonErrors": [{"wrong": "Le Christ n''a souffert qu''en apparence.", "right": "Il a souffert, il est mort et il a été enseveli.", "why": "Docétisme : corps apparent, rejeté par le Credo."}, {"wrong": "La droite du Père est un endroit.", "right": "La droite du Père est l''honneur et la puissance.", "why": "Dieu n''a pas de côté droit : c''est une image."}, {"wrong": "Le Christ reviendra dans l''humilité.", "right": "Il reviendra dans la gloire pour juger.", "why": "Première venue : humilité ; seconde : gloire."}], "tip": "Sept verbes, dans l''ordre : crucifié, souffrit, enseveli, ressuscita, monta, s''assit, reviendra."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g66.saint_esprit', 'eg', 'grammar', 'knowledge', 'Le Saint-Esprit, Seigneur et vivificateur', 3, array['eg.g65.passion_et_gloire']::text[], 8, '{"rule": {"summary": "Cinquième article : l''Esprit Saint est Seigneur, il donne la vie, procède du Père, est adoré et glorifié avec le Père et le Fils, et a parlé par les prophètes. Développé en 381 contre Macédonius.", "explanation": "À Nicée, l''Esprit n''était que mentionné. Face à Macédonius et aux pneumatomaques, qui le disaient créé, Constantinople (381) affirme sa divinité : Seigneur, vivificateur, adoré avec le Père et le Fils. Il procède du Père, seule source de la Trinité. Il a inspiré les prophètes, donc toute l''Écriture. L''Occident a ajouté « et du Fils » (Filioque) ; l''Église copte garde le texte de 381.", "pattern": "Esprit = Seigneur, vivificateur, procède du Père, adoré avec le Père et le Fils.", "examples": [{"text": "« Seigneur qui donne la vie. »", "translation": "L''Esprit est Dieu et source de vie."}, {"text": "« Qui procède du Père. »", "translation": "Le Père est la seule source."}, {"text": "« Adoré et glorifié avec le Père et le Fils. »", "translation": "On n''adore que Dieu : donc l''Esprit est Dieu."}, {"text": "« Il a parlé par les prophètes. »", "translation": "L''Esprit inspire l''Écriture."}], "commonErrors": [{"wrong": "L''Esprit Saint est une créature.", "right": "L''Esprit est Seigneur, adoré avec le Père et le Fils.", "why": "Macédonius : condamné en 381."}, {"wrong": "L''Esprit Saint est une force sans personne.", "right": "L''Esprit est une personne divine.", "why": "On l''adore comme le Père et le Fils."}, {"wrong": "Le Credo de 381 dit « et du Fils ».", "right": "Le Credo de 381 dit : qui procède du Père.", "why": "« Et du Fils » (Filioque) est un ajout latin."}], "tip": "Trois verbes pour l''Esprit : il donne la vie, il procède, il a parlé."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g67.eglise_resurrection', 'eg', 'grammar', 'knowledge', 'L''Église, le baptême, la vie à venir', 2, array['eg.g66.saint_esprit']::text[], 8, '{"rule": {"summary": "Dernier article (381) : une seule Église, sainte, catholique et apostolique ; un seul baptême pour la rémission des péchés ; la résurrection des morts et la vie du siècle à venir. Amen.", "explanation": "Après les trois personnes, le Credo parle de l''Église, fruit de l''œuvre du Christ et de l''Esprit. Elle est une (un seul Corps), sainte (sanctifiée par le Christ et l''Esprit), catholique (universelle) et apostolique (fondée sur les apôtres, avec la succession des évêques). Un seul baptême donne le pardon des péchés. Enfin on attend la résurrection des morts et la vie du siècle à venir. Amen.", "pattern": "Église une, sainte, catholique, apostolique + un baptême + résurrection + vie à venir.", "examples": [{"text": "« Une seule Église, sainte, catholique et apostolique. »", "translation": "Les quatre marques de l''Église."}, {"text": "« Un seul baptême pour la rémission des péchés. »", "translation": "Il ne se répète pas ; il pardonne."}, {"text": "« La résurrection des morts. »", "translation": "L''homme tout entier, corps compris."}, {"text": "« Amen. »", "translation": "Ainsi soit-il : c''est vrai."}], "commonErrors": [{"wrong": "Catholique veut dire romaine.", "right": "Catholique veut dire universelle.", "why": "Du grec katholikos, « selon le tout »."}, {"wrong": "L''Église est sainte parce que ses membres sont parfaits.", "right": "Elle est sainte parce que le Christ et l''Esprit la sanctifient.", "why": "Novatien oubliait cela."}, {"wrong": "On ressuscite seulement en esprit.", "right": "On ressuscite avec son corps.", "why": "Les gnostiques méprisaient la chair."}], "tip": "Quatre mots pour l''Église : une, sainte, catholique, apostolique."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g68.bilan_du_credo', 'eg', 'grammar', 'knowledge', 'Le Credo en entier : bilan', 3, array['eg.g67.eglise_resurrection']::text[], 8, '{"rule": {"summary": "Le Credo de Nicée-Constantinople dans l''ordre : le Père, le Fils (incarnation, passion, gloire), l''Esprit Saint, l''Église. Chaque article répond à une erreur et se rattache à un concile.", "explanation": "Le Credo se retient en trois blocs plus l''Église. Le Père créateur répond aux gnostiques, à Marcion et aux manichéens. Le Fils consubstantiel répond à Arius (Nicée, 325). « Se fit homme » répond aux docètes et à Apollinaire (381). Théotokos et l''unité du Christ viennent d''Éphèse (431). L''Esprit vivificateur répond à Macédonius (381). La foi miaphysite n''ajoute rien : elle explique « il s''incarna ».", "pattern": "Père = gnostiques ; Fils = Arius ; homme = docètes, Apollinaire ; Esprit = Macédonius ; Église = Novatien.", "examples": [{"text": "Père créateur : contre les gnostiques et Marcion.", "translation": "Un seul Dieu, créateur de tout."}, {"text": "Consubstantiel : contre Arius, à Nicée (325).", "translation": "Le Fils est vrai Dieu."}, {"text": "Seigneur vivificateur : contre Macédonius, en 381.", "translation": "L''Esprit est Dieu."}, {"text": "Éphèse (431) : on ne change plus le Credo.", "translation": "Et Marie est Théotokos."}], "commonErrors": [{"wrong": "Le Credo a été écrit en une fois à Nicée.", "right": "325 : le Père et le Fils ; 381 : l''Esprit Saint et la suite.", "why": "Deux conciles, un seul texte."}, {"wrong": "Chaque phrase du Credo est de la poésie.", "right": "Chaque phrase répond à une erreur.", "why": "Credo = réponses aux hérésies."}, {"wrong": "Le Credo est une prière personnelle.", "right": "Le Credo est la confession de toute l''Église.", "why": "On dit « nous croyons »."}], "tip": "Père, Fils, Esprit, Église : quatre blocs, quatre erreurs, trois conciles."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g69.sacrement', 'eg', 'grammar', 'knowledge', 'Qu''est-ce qu''un sacrement ?', 1, array['eg.g58.protestants_sacrements_saints']::text[], 9, '{"rule": {"summary": "Un sacrement, ou mystère, est un signe visible par lequel Dieu donne une grâce invisible ; il est institué par le Christ et célébré par un prêtre. L''Église copte en compte sept.", "explanation": "Le Christ s''est fait homme, avec un corps : il continue d''agir par des réalités que l''on peut toucher, comme l''eau, l''huile, le pain ou l''imposition des mains. Chaque sacrement a un signe visible (la matière et le geste) et une grâce invisible (ce que Dieu donne). Aucun n''est une invention de l''Église : chacun repose sur le Christ ou sur la pratique des apôtres. Le prêtre le célèbre, mais c''est le Christ qui agit. Trois sacrements ne se répètent pas (baptême, confirmation, sacerdoce) ; les autres reviennent au fil de la vie.", "pattern": "Sacrement = signe visible + grâce invisible. Sept sacrements. Trois ne se répètent pas.", "examples": [{"text": "L''eau du baptême est le signe visible.", "translation": "La grâce invisible est la nouvelle naissance."}, {"text": "Le pain et le vin de la messe sont le signe visible.", "translation": "La grâce invisible est le Corps et le Sang du Christ."}, {"text": "L''huile du qandil est le signe visible.", "translation": "La grâce invisible est la guérison de l''âme et du corps."}, {"text": "L''imposition des mains est le signe visible du sacerdoce.", "translation": "La grâce invisible est le don du Saint-Esprit pour servir l''Église."}], "commonErrors": [{"wrong": "Un sacrement est seulement un symbole pour se souvenir.", "right": "Un sacrement donne vraiment une grâce.", "why": "Le signe n''est pas décoratif : Dieu agit par lui."}, {"wrong": "Le prêtre fabrique la grâce.", "right": "C''est le Christ qui donne la grâce ; le prêtre est son serviteur.", "why": "Le prêtre célèbre au nom du Christ, il n''en est pas la source."}, {"wrong": "Tous les sacrements se reçoivent plusieurs fois.", "right": "Le baptême, la confirmation et le sacerdoce ne se répètent pas.", "why": "Ils impriment une marque qui ne s''efface pas."}], "tip": "Visible + invisible : l''eau, l''huile, le pain, les mains que l''on voit, et la grâce que l''on ne voit pas."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g70.bapteme', 'eg', 'grammar', 'knowledge', 'Le baptême : naître d''eau et d''Esprit', 2, array['eg.g69.sacrement']::text[], 9, '{"rule": {"summary": "Le baptême est le premier sacrement : par la triple immersion au nom de la Trinité, on naît d''eau et d''Esprit et l''on entre dans l''Église. Il ne se reçoit qu''une fois.", "explanation": "Le Christ a ordonné de baptiser (Mt 28, 19) et il a dit qu''il faut naître d''eau et d''Esprit (Jn 3, 5). Dans l''Église copte, on plonge trois fois : une fois pour chaque Personne de la Trinité, et en souvenir des trois jours du Christ au tombeau (Rm 6, 3-4). Avant, le baptisé se tourne vers l''ouest pour renoncer à Satan, puis vers l''est pour confesser le Christ. Les bébés sont baptisés, le parrain répondant pour eux ; selon l''usage, le garçon vers le 40e jour et la fille vers le 80e, d''après Lv 12.", "pattern": "Eau + triple immersion + Trinité. Ouest : renoncer à Satan. Est : confesser le Christ. Garçon : 40e jour. Fille : 80e jour.", "examples": [{"text": "Le prêtre plonge l''enfant trois fois dans l''eau.", "translation": "Une immersion pour le Père, une pour le Fils, une pour le Saint-Esprit."}, {"text": "Le baptisé se tourne vers l''ouest pour renoncer à Satan.", "translation": "L''ouest est le côté où le soleil disparaît : les ténèbres."}, {"text": "Puis il se tourne vers l''est pour confesser le Christ.", "translation": "L''est est le côté où le soleil se lève : la lumière."}, {"text": "Le garçon est baptisé le 40e jour, la fille le 80e.", "translation": "C''est l''usage, fondé sur Lévitique 12."}], "commonErrors": [{"wrong": "On se contente de verser un peu d''eau sur le front.", "right": "Dans l''Église copte, on plonge le baptisé trois fois dans l''eau.", "why": "Baptizein veut dire plonger : l''eau est un tombeau et une naissance."}, {"wrong": "Le baptême se refait si l''on a péché gravement.", "right": "Le baptême ne se répète jamais ; le pardon se reçoit par la confession.", "why": "On ne naît qu''une fois ; ensuite, on a la confession."}, {"wrong": "On ne peut baptiser qu''un adulte qui choisit lui-même.", "right": "L''Église baptise aussi les bébés, avec la foi des parents et du parrain.", "why": "Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés."}], "tip": "Trois immersions, deux directions : l''ouest pour renoncer, l''est pour confesser."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g71.confirmation', 'eg', 'grammar', 'knowledge', 'La confirmation : le saint myron', 2, array['eg.g70.bapteme']::text[], 9, '{"rule": {"summary": "La confirmation, ou chrismation, donne au baptisé le sceau du Saint-Esprit par le saint myron : 36 onctions, aussitôt après le baptême. Elle ne se reçoit qu''une fois.", "explanation": "Dans les Actes, les apôtres imposent les mains aux baptisés pour qu''ils reçoivent l''Esprit (Ac 8, 14-17). Comme ils ne pouvaient pas aller vers chaque fidèle, l''Église a gardé ce don par le saint myron, une huile parfumée préparée et consacrée par le patriarche avec les évêques. Le prêtre trace 36 signes de croix sur le corps du baptisé juste après le baptême. L''enfant reçoit un habit blanc, et selon l''usage un zounnar à la taille.", "pattern": "Saint myron = huile parfumée consacrée par le patriarche. 36 onctions. Juste après le baptême. Une seule fois.", "examples": [{"text": "Pierre et Jean imposent les mains aux Samaritains baptisés (Ac 8, 14-17).", "translation": "Ils reçoivent l''Esprit : c''est l''origine de la confirmation."}, {"text": "Le prêtre trace 36 signes de croix avec le saint myron.", "translation": "Tout le corps est consacré."}, {"text": "Le patriarche prépare le myron avec les évêques.", "translation": "Il y ajoute un peu de l''ancien myron."}, {"text": "L''enfant reçoit un habit blanc.", "translation": "Il a revêtu l''homme nouveau."}], "commonErrors": [{"wrong": "La confirmation est une cérémonie de l''adolescence, par l''évêque.", "right": "Chez les Coptes, le prêtre confirme aussitôt après le baptême, même pour un bébé.", "why": "Le baptême et le myron forment un seul parcours d''initiation."}, {"wrong": "Le myron est une huile ordinaire.", "right": "C''est une huile d''olive mêlée de nombreux parfums, consacrée par le patriarche.", "why": "Elle est préparée de manière solennelle, d''après Ex 30."}, {"wrong": "On renouvelle la confirmation régulièrement.", "right": "Elle ne se reçoit qu''une fois.", "why": "Le sceau de l''Esprit ne s''efface pas."}], "tip": "Baptême : l''eau. Confirmation : l''huile. Le premier lave, le second scelle."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g72.eucharistie', 'eg', 'grammar', 'knowledge', 'L''eucharistie : le Corps et le Sang du Christ', 3, array['eg.g71.confirmation']::text[], 9, '{"rule": {"summary": "L''eucharistie, « action de grâce », est le sacrement où le pain et le vin deviennent vraiment le Corps et le Sang du Christ. On s''y prépare par la confession et par le jeûne.", "explanation": "Le soir de la dernière Cène, Jésus dit : « Prenez, mangez, ceci est mon corps » (Mt 26, 26). Il avait promis : « Qui mange ma chair et boit mon sang a la vie éternelle » (Jn 6, 54). Nous croyons à la présence réelle : le pain et le vin ne sont pas un simple souvenir. Le pain de la messe, le qorban, est un pain levé marqué d''une croix. Pour recevoir une telle grâce, on s''examine (1 Co 11, 28), on se confesse et on est à jeun.", "pattern": "Dernière Cène (Mt 26, 26). Présence réelle. Qorban = pain levé. Jeûne avant, confession avant.", "examples": [{"text": "Jésus prend le pain et dit : « Ceci est mon corps ».", "translation": "Il ne dit pas : « Ceci représente »."}, {"text": "Le qorban est un pain levé marqué d''une croix.", "translation": "Le levain évoque la vie, la Résurrection."}, {"text": "On reste à jeun avant la communion.", "translation": "Le Christ est la première nourriture de la journée."}, {"text": "On se confesse avant de communier.", "translation": "Paul demande que chacun s''examine soi-même."}], "commonErrors": [{"wrong": "L''eucharistie est seulement un souvenir de la dernière Cène.", "right": "Pour l''Église copte, c''est le vrai Corps et le vrai Sang du Christ.", "why": "Jésus a dit « ceci est », et non « ceci représente »."}, {"wrong": "Le pain de la messe est sans levain, comme chez les latins.", "right": "Le qorban est un pain levé.", "why": "Le pain levé est le pain vivant ; il rappelle la Résurrection."}, {"wrong": "On peut communier sans se préparer.", "right": "On s''examine, on se confesse et on jeûne avant.", "why": "Saint Paul avertit contre la communion indigne (1 Co 11, 27-29)."}], "tip": "Cène du Jeudi saint, qorban levé, jeûne et confession avant : la communion se prépare."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g73.confession', 'eg', 'grammar', 'knowledge', 'La confession : le pardon par le prêtre', 3, array['eg.g72.eucharistie']::text[], 9, '{"rule": {"summary": "La confession, ou pénitence, pardonne les péchés commis après le baptême : on les dit à un prêtre, le père de confession, qui prie l''absolution. Elle repose sur Jn 20, 22-23.", "explanation": "Après le baptême, nous péchons encore ; Dieu ne veut pas la mort du pécheur mais qu''il se convertisse. Le soir de la Résurrection, Jésus souffle sur les apôtres et leur donne le pouvoir de remettre ou de retenir les péchés (Jn 20, 22-23). Pour remettre ou retenir, il faut connaître : on dit donc ses péchés. Le prêtre est père, juge et enseignant. La repentance demande un regret sincère, la décision de changer, la confession et la confiance en Dieu. Dieu seul pardonne, mais par le ministère qu''il a confié aux apôtres.", "pattern": "Jn 20, 22-23. Regret + décision + confession + confiance. Le prêtre prie l''absolution. Secret absolu.", "examples": [{"text": "Jésus souffle sur les apôtres : « Recevez l''Esprit Saint ».", "translation": "Il leur donne le pouvoir de remettre les péchés."}, {"text": "Le fidèle dit ses péchés à son père de confession.", "translation": "Il se confie à un prêtre qui le connaît."}, {"text": "Le prêtre pose la croix sur la tête et prie l''absolution.", "translation": "Dieu pardonne par lui."}, {"text": "Le prêtre ne répète jamais ce qu''il entend.", "translation": "Le secret de la confession est absolu."}], "commonErrors": [{"wrong": "Le prêtre pardonne de lui-même.", "right": "Dieu pardonne par le ministère du prêtre.", "why": "Le prêtre est le serviteur de la réconciliation (2 Co 5, 18)."}, {"wrong": "Se repentir, c''est seulement dire « pardon » à voix haute.", "right": "C''est un regret sincère et la décision de changer.", "why": "La repentance est un changement du cœur."}, {"wrong": "On se confesse une fois dans la vie, comme le baptême.", "right": "On se confesse régulièrement, environ une fois par mois.", "why": "La confession se répète : on pèche encore."}], "tip": "Jn 20, 22-23 : remettre ou retenir. Pour remettre, il faut connaître : on dit ses péchés."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g74.onction_malades', 'eg', 'grammar', 'knowledge', 'L''onction des malades : le qandil', 3, array['eg.g73.confession']::text[], 9, '{"rule": {"summary": "L''onction des malades, ou qandil (la lampe), est le sacrement où des prêtres prient et oignent d''huile un malade pour la guérison de son âme et de son corps. Il repose sur Jc 5, 14-15.", "explanation": "L''apôtre Jacques écrit : « Quelqu''un parmi vous est-il malade ? Qu''il appelle les anciens de l''Église ; ils prieront pour lui et l''oindront d''huile au nom du Seigneur » (Jc 5, 14). L''Église le célèbre avec sept prières et sept mèches allumées d''où le nom de « lampe » (qandil). L''huile est le signe visible ; la grâce est le pardon et le soulagement, et la guérison du corps si Dieu le veut. Le sacrement se répète à chaque maladie ; une fois par an, selon l''usage, a lieu le qandil général.", "pattern": "Jc 5, 14-15. Huile + sept prières + sept mèches. Âme d''abord, corps selon la volonté de Dieu. Se répète. Qandil général : une fois par an.", "examples": [{"text": "Le prêtre trace une croix d''huile sur le front, la poitrine et les mains du malade.", "translation": "Le signe visible du sacrement."}, {"text": "On allume une mèche avant chacune des sept prières.", "translation": "D''où le nom de « lampe »."}, {"text": "Jc 5, 15 parle de pardon des péchés et de relèvement du malade.", "translation": "L''âme et le corps sont soignés ensemble."}, {"text": "Le qandil général a lieu une fois par an.", "translation": "Selon l''usage, avant la semaine de la Passion."}], "commonErrors": [{"wrong": "L''onction des malades est le sacrement des mourants.", "right": "C''est le sacrement des malades, pour les relever et les soulager.", "why": "Jacques dit : « le Seigneur le relèvera »."}, {"wrong": "Le qandil garantit la guérison du corps.", "right": "Il vise la guérison de l''âme, et du corps selon la volonté de Dieu.", "why": "Dieu guérit comme il veut ; la maladie n''est pas toujours une punition."}, {"wrong": "On ne peut recevoir l''onction des malades qu''une fois.", "right": "On peut la recevoir à chaque maladie.", "why": "C''est un sacrement qui se répète."}], "tip": "Qandil = lampe : sept mèches, sept prières, une huile et un malade."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g75.mariage_sacerdoce', 'eg', 'grammar', 'knowledge', 'Le mariage et le sacerdoce : deux vocations', 3, array['eg.g74.onction_malades']::text[], 9, '{"rule": {"summary": "Le mariage, ou couronnement, est un sacrement où Dieu unit un homme et une femme pour la vie. Le sacerdoce est le sacrement où l''évêque, par l''imposition des mains, ordonne diacres, prêtres et évêques dans la succession apostolique.", "explanation": "Saint Paul dit du mariage : « Ce mystère est grand » (Ép 5, 32) : l''amour des époux est l''image de l''amour du Christ pour son Église. Jésus a béni les noces de Cana (Jn 2) et rappelé : « Ce que Dieu a uni, que l''homme ne le sépare pas » (Mt 19, 6). Le prêtre couronne les époux. Le sacerdoce repose sur le choix des Douze (Lc 6, 13), l''Esprit qu''ils reçoivent (Jn 20, 22) et l''imposition des mains (Ac 6, 6 ; 2 Tm 1, 6). Les trois degrés (diacre, prêtre, évêque) seront vus en détail dans un module sur le clergé.", "pattern": "Mariage : Ép 5, 32, couronnes, indissoluble. Sacerdoce : imposition des mains, succession apostolique, trois degrés.", "examples": [{"text": "Le prêtre place des couronnes sur la tête des époux.", "translation": "Ils sont roi et reine de leur foyer."}, {"text": "Jésus bénit les noces de Cana.", "translation": "Il honore le mariage dès le début de son ministère."}, {"text": "L''évêque impose les mains au candidat.", "translation": "Il l''ordonne, comme à Actes 6, 6."}, {"text": "Un évêque est ordonné par plusieurs évêques, avec le patriarche.", "translation": "C''est la succession apostolique."}], "commonErrors": [{"wrong": "Le mariage n''est qu''un contrat civil béni par l''Église.", "right": "C''est un sacrement : Dieu unit les époux.", "why": "Paul parle d''un « grand mystère » (Ép 5, 32)."}, {"wrong": "Les fiançailles sont un sacrement.", "right": "Les fiançailles précèdent le mariage mais ne sont pas un sacrement.", "why": "Seul le couronnement est le sacrement."}, {"wrong": "N''importe quel chrétien peut ordonner un prêtre.", "right": "Seul un évêque ordonne.", "why": "L''ordination se fait par l''imposition des mains des évêques, dans la ligne des apôtres."}], "tip": "Mariage : les couronnes. Sacerdoce : les mains."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g76.bilan_sacrements', 'eg', 'grammar', 'knowledge', 'Les sept sacrements : le tableau d''ensemble', 3, array['eg.g75.mariage_sacerdoce']::text[], 9, '{"rule": {"summary": "Chaque sacrement a un signe visible, un fondement biblique et une grâce : baptême (eau), confirmation (myron), eucharistie (pain et vin), confession (absolution), onction des malades (huile), mariage (couronnes), sacerdoce (mains).", "explanation": "Pour s''y retrouver, on peut regrouper les sept sacrements : l''initiation (baptême, confirmation, eucharistie) pour devenir et rester chrétien, la guérison (confession, onction des malades) pour le pardon et le soulagement, et la vocation (mariage, sacerdoce) pour une mission. Les Coptes et les catholiques comptent sept sacrements, mais diffèrent sur le pain, le célibat et le moment de la confirmation. La plupart des protestants n''en gardent que deux, le baptême et la Cène.", "pattern": "Baptême : eau. Confirmation : myron. Eucharistie : pain et vin. Confession : absolution. Onction : huile. Mariage : couronnes. Sacerdoce : mains.", "examples": [{"text": "Baptême : l''eau et la triple immersion, Jn 3, 5.", "translation": "On naît d''eau et d''Esprit."}, {"text": "Eucharistie : le pain levé et le vin, Mt 26, 26-28.", "translation": "On reçoit le Corps et le Sang du Christ."}, {"text": "Confession : la croix sur la tête, Jn 20, 22-23.", "translation": "Le prêtre prie l''absolution."}, {"text": "Mariage : les couronnes, Ép 5, 32.", "translation": "Dieu unit les époux."}], "commonErrors": [{"wrong": "Les Coptes et les catholiques ont exactement les mêmes usages sacramentels.", "right": "Ils partagent les sept sacrements mais diffèrent sur le pain, le célibat des prêtres et la confirmation.", "why": "Nous utilisons un pain levé, le prêtre marié avant l''ordination est possible et le prêtre confirme tout de suite."}, {"wrong": "Les protestants n''ont aucun sacrement.", "right": "La plupart gardent deux sacrements, le baptême et la Cène.", "why": "Ils ne retiennent que ceux qu''ils jugent expressément ordonnés par le Christ."}, {"wrong": "Les sept sacrements se reçoivent tous plusieurs fois.", "right": "Baptême, confirmation et sacerdoce ne se répètent pas ; le mariage est à part.", "why": "Ces sacrements impriment une marque."}], "tip": "Eau, huile, pain, mains, couronnes : cinq signes pour sept sacrements."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g77.batiment_eglise', 'eg', 'grammar', 'knowledge', 'Le bâtiment : orienté vers l''est, en trois parties', 1, '{}'::text[], 10, '{"rule": {"summary": "Une église copte est tournée vers l''est, souvent en forme d''arche de Noé, et se divise en trois parties (narthex, nef, sanctuaire) qui rappellent les trois espaces du Tabernacle de Moïse.", "explanation": "L''église est orientée vers l''est parce que le Christ est le soleil de justice, que l''Éden est à l''orient et que le Christ reviendra de l''orient. Sa forme la plus courante est l''arche de Noé ; d''autres églises ont un plan en croix ou en cercle. On y avance de l''ouest vers l''est en traversant trois espaces, comme le parvis, le lieu saint et le saint des saints du Tabernacle.", "pattern": "Narthex = parvis ; nef = lieu saint ; sanctuaire = saint des saints.", "examples": [{"text": "Le sanctuaire est tout à l''est.", "translation": "On prie tourné vers le Christ, soleil de justice."}, {"text": "L''église a la forme d''une arche.", "translation": "Ceux qui sont dedans sont sauvés comme Noé."}, {"text": "Le narthex est l''entrée.", "translation": "Il correspond au parvis du Tabernacle."}, {"text": "Le sanctuaire est réservé au clergé.", "translation": "Comme le saint des saints l''était au grand prêtre."}], "commonErrors": [{"wrong": "L''église est tournée vers Jérusalem.", "right": "Elle est tournée vers l''est.", "why": "L''est, c''est la direction du soleil levant, symbole du Christ."}, {"wrong": "Toutes les églises ont exactement le même plan.", "right": "Le plan général est le même, mais les détails varient.", "why": "Nombre de coupoles, forme et place du baptistère changent selon les églises."}, {"wrong": "La nef correspond au saint des saints.", "right": "La nef correspond au lieu saint.", "why": "Le saint des saints correspond au sanctuaire."}], "tip": "Trois espaces, trois correspondances : parvis, lieu saint, saint des saints."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g78.sanctuaire_haikal', 'eg', 'grammar', 'knowledge', 'Le sanctuaire (haikal) et l''autel', 2, array['eg.g77.batiment_eglise']::text[], 10, '{"rule": {"summary": "Le haikal est le sanctuaire de l''église : on y entre déchaussé, il contient un autel consacré au myron, souvent sous un ciborium, avec les objets de la liturgie : calice, patène, astérisque, cuillère, coffret.", "explanation": "Le haikal est l''équivalent du saint des saints. L''autel, cube qui représente le tombeau du Christ, est consacré par l''évêque avec le myron. Une église a parfois trois autels, car chaque autel ne sert qu''à une liturgie par jour. On entre déchaussé comme Moïse sur une terre sainte. Au-dessus de l''autel, le ciborium rappelle le ciel. Les objets de l''autel portent chacun un sens.", "pattern": "Haikal = sanctuaire ; autel consacré au myron ; une liturgie par jour et par autel ; on entre déchaussé.", "examples": [{"text": "L''évêque consacre l''autel avec le myron.", "translation": "L''autel est alors mis à part pour Dieu."}, {"text": "Trois autels permettent trois liturgies le même jour.", "translation": "Un autel ne sert qu''une fois par jour."}, {"text": "On entre déchaussé dans le haikal.", "translation": "Comme Moïse, devant une terre sainte."}, {"text": "Le calice contient le vin mêlé d''eau.", "translation": "La patène porte le pain."}], "commonErrors": [{"wrong": "Toutes les églises coptes ont trois autels.", "right": "Beaucoup n''en ont qu''un seul.", "why": "Le nombre d''autels dépend du nombre de liturgies à célébrer."}, {"wrong": "L''autel est consacré avec de l''eau bénite.", "right": "Il est consacré avec le myron.", "why": "Le myron est l''huile sainte faite par le pape."}, {"wrong": "Tout le monde peut entrer dans le haikal.", "right": "Il est réservé au clergé et aux diacres qui servent.", "why": "C''est le saint des saints de l''église."}], "tip": "Haikal : on se déchausse, on consacre, on célèbre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g79.iconostase_icones', 'eg', 'grammar', 'knowledge', 'L''iconostase (higab), les icônes et les symboles', 2, array['eg.g78.sanctuaire_haikal']::text[], 10, '{"rule": {"summary": "L''iconostase (higab) sépare la nef et le haikal ; elle porte les icônes du Christ, de la Vierge, de Jean-Baptiste, la Cène au-dessus de la porte royale, et des objets symboliques : œuf d''autruche, lampes, encens.", "explanation": "L''iconostase est le mur d''icônes entre la nef et le haikal, ouvert par la porte royale. On y voit le Christ, la Vierge, Jean-Baptiste, des saints, les apôtres, la Cène et, en haut, la croix. L''œuf d''autruche, la lampe à huile et l''encens portent chacun un sens : la vigilance de Dieu et la résurrection, la lumière du Christ, les prières qui montent. Aux icônes, on rend la vénération ; l''adoration est due à Dieu seul.", "pattern": "Christ à droite, Marie à gauche, Cène au-dessus de la porte, apôtres de chaque côté, croix en haut.", "examples": [{"text": "La Cène est au-dessus de la porte royale.", "translation": "Elle domine le lieu où l''eucharistie est célébrée."}, {"text": "L''œuf d''autruche est suspendu devant l''iconostase.", "translation": "Il rappelle la vigilance de Dieu et la résurrection."}, {"text": "La fumée de l''encens monte.", "translation": "Elle représente les prières des fidèles."}, {"text": "On vénère l''icône, on adore Dieu seul.", "translation": "La vénération n''est pas l''adoration."}], "commonErrors": [{"wrong": "On adore les icônes.", "right": "On les vénère ; on adore Dieu seul.", "why": "L''honneur rendu à l''image passe à celui qu''elle représente."}, {"wrong": "L''iconostase coupe les fidèles de Dieu.", "right": "Elle sépare la nef et le haikal sans les couper : les rideaux s''ouvrent pendant la liturgie.", "why": "Elle évoque le voile du Temple, ouvert sur le ciel."}, {"wrong": "L''œuf d''autruche est un simple décor.", "right": "Il a un sens : Dieu veille sans cesse et la résurrection.", "why": "Dans l''église, presque tout est symbole."}], "tip": "Christ à droite, Marie à gauche, Cène au centre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g80.diaconat', 'eg', 'grammar', 'knowledge', 'Le diaconat : les cinq rangs', 2, array['eg.g24.structure_de_l_eglise']::text[], 10, '{"rule": {"summary": "Le diaconat copte compte cinq rangs : psalte, lecteur, sous-diacre, diacre et archidiacre. Ce sont des serviteurs de la liturgie, en tunique blanche, non des prêtres.", "explanation": "Le diaconat est une échelle de services. Le psalte (épsaltos) chante, le lecteur (anagnostès) lit la Bible, le sous-diacre (hypodiacre) garde les portes, le diacre prépare et sert la liturgie, l''archidiacre dirige tous les diacres. Ils servent en tunique blanche, souvent avec une étole. Le diaconat est un ministère de service : le diacre aide le prêtre mais ne consacre pas.", "pattern": "Psalte (chante) → lecteur (lit) → sous-diacre (garde) → diacre (sert) → archidiacre (dirige).", "examples": [{"text": "Le psalte chante les psaumes.", "translation": "C''est le premier rang."}, {"text": "Le lecteur lit la Bible.", "translation": "Anagnostès, en grec."}, {"text": "Le diacre prépare les vases et le pain.", "translation": "Il tient le calice pendant la liturgie."}, {"text": "Dioscore est l''archidiacre de Cyrille.", "translation": "Le chef des diacres auprès de l''évêque."}], "commonErrors": [{"wrong": "Le diacre peut célébrer l''eucharistie.", "right": "Il aide le prêtre mais ne consacre pas.", "why": "Son ministère est le service, pas le sacerdoce."}, {"wrong": "Le diaconat n''a qu''un seul rang.", "right": "Il en compte cinq.", "why": "Du psalte à l''archidiacre."}, {"wrong": "L''archidiacre est le premier des prêtres.", "right": "Il est le chef des diacres.", "why": "Il est dans le diaconat, pas dans le sacerdoce."}], "tip": "Chante, lit, garde, sert, dirige."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g81.pretres_eveques_pape', 'eg', 'grammar', 'knowledge', 'Le sacerdoce, l''épiscopat et le choix du pape', 3, array['eg.g80.diaconat']::text[], 10, '{"rule": {"summary": "Le prêtre célèbre les sacrements (marié avant l''ordination ou moine), l''évêque ordonne et est choisi parmi les moines, et le pape d''Alexandrie, patriarche, préside le saint-synode et est désigné par vote puis tirage au sort sur l''autel.", "explanation": "Le prêtre est le deuxième degré ; le qommos est un prêtre promu archiprêtre. L''évêque, toujours moine chez les coptes, dirige un diocèse et ordonne ; le métropolite est promu à la tête d''un grand diocèse. Le patriarche, pape d''Alexandrie, préside le saint-synode. Pour choisir un pape, les électeurs retiennent trois noms, puis un enfant aux yeux bandés en tire un sur l''autel : Dieu choisit. Tawadros II, tiré en 2012, est le 118e pape.", "pattern": "Prêtre (marié avant l''ordination) → évêque (moine) → métropolite → pape-patriarche. Le pape : vote (3 noms) puis tirage au sort sur l''autel.", "examples": [{"text": "Le prêtre se marie avant son ordination.", "translation": "Un prêtre veuf ne se remarie pas."}, {"text": "Les évêques sont choisis parmi les moines.", "translation": "Ils sont célibataires."}, {"text": "Un enfant tire un nom sur l''autel.", "translation": "C''est la qor''a haykaleya : Dieu choisit."}, {"text": "Tawadros II est le 118e pape.", "translation": "Il a été tiré au sort en 2012."}], "commonErrors": [{"wrong": "Un prêtre copte peut se marier après son ordination.", "right": "Il doit se marier avant.", "why": "Après l''ordination, il ne peut plus se marier."}, {"wrong": "Le pape est élu uniquement par vote.", "right": "Le vote retient trois noms, puis le sort désigne le pape.", "why": "Pour laisser Dieu choisir."}, {"wrong": "Tous les évêques sont mariés.", "right": "Ils sont choisis parmi les moines.", "why": "Un évêque copte est célibataire."}], "tip": "Prêtre : marié avant. Évêque : moine. Pape : vote puis sort."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g82.monachisme_bilan', 'eg', 'grammar', 'knowledge', 'Le monachisme aujourd''hui et le bilan du module', 3, array['eg.g81.pretres_eveques_pape']::text[], 10, '{"rule": {"summary": "Le monachisme copte continue : moines, abbés et ermites vivent dans les grands monastères (Saint-Antoine, Saint-Paul, et les quatre de Wadi Natroun), et les évêques et le pape viennent des moines.", "explanation": "Le moine prie, travaille et jeûne ; l''abbé dirige le monastère ; l''ermite vit seul au désert ; l''eskime est le grand habit des moines avancés. Saint-Antoine et Saint-Paul sont près de la mer Rouge. À Wadi Natroun, ancienne Scété, il reste quatre monastères : Saint-Macaire, Baramous, Anba Bishoy et celui des Syriens. Ces monastères fournissent les évêques et le pape.", "pattern": "Moine → abbé (dirige) ; ermite (seul) ; eskime (habit). Saint-Antoine et Saint-Paul : mer Rouge. Wadi Natroun : quatre monastères.", "examples": [{"text": "L''abbé dirige le monastère.", "translation": "Il est le père des moines."}, {"text": "Le monastère Saint-Antoine est près de la mer Rouge.", "translation": "On le dit le plus ancien monastère chrétien."}, {"text": "Wadi Natroun garde quatre monastères.", "translation": "Saint-Macaire, Baramous, Anba Bishoy, les Syriens."}, {"text": "Les évêques sont choisis parmi les moines.", "translation": "Le monastère nourrit la hiérarchie."}], "commonErrors": [{"wrong": "Les monastères de Wadi Natroun sont près de la mer Rouge.", "right": "Ils sont au nord-ouest du Caire ; Saint-Antoine et Saint-Paul sont près de la mer Rouge.", "why": "Deux régions : le désert oriental et Wadi Natroun."}, {"wrong": "L''ermite et l''abbé, c''est la même chose.", "right": "L''ermite vit seul ; l''abbé dirige un monastère.", "why": "Deux vocations différentes."}, {"wrong": "Le monastère des Syriens a été fondé en Syrie.", "right": "Il est à Wadi Natroun et doit son nom à des moines venus de Syrie.", "why": "Il est égyptien."}], "tip": "Mer Rouge : Antoine et Paul. Wadi Natroun : quatre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g83.prier_aux_heures', 'eg', 'grammar', 'knowledge', 'Prier aux heures : l''Agpeya', 1, '{}'::text[], 11, '{"rule": {"summary": "L''Église prie à des heures fixes, sept fois par jour, d''après le psaume 119, 164 ; le livre de ces prières est l''Agpeya, « le livre des heures ».", "explanation": "Saint Paul demande de prier sans cesse. Pour y arriver, l''Église donne des rendez-vous réguliers avec Dieu. Le psaume 119, 164 (« Sept fois le jour je te loue ») fonde les sept heures. Daniel et les apôtres priaient déjà à heures fixes. Chaque heure rappelle un moment de la vie du Christ, de l''incarnation à sa seconde venue.", "pattern": "Agpeya = heure = le livre des heures ; sept heures + la prière du voile.", "examples": [{"text": "Ps 119, 164 : « Sept fois le jour je te loue ».", "translation": "C''est le verset qui ouvre l''Agpeya et fonde les sept heures."}, {"text": "Daniel prie trois fois par jour, à genoux, vers Jérusalem.", "translation": "Un modèle de fidélité, même sous la menace."}, {"text": "Ac 3, 1 : Pierre et Jean montent au Temple à la neuvième heure.", "translation": "Les apôtres gardent les heures de prière."}, {"text": "Agpeya vient du copte agp, « heure ».", "translation": "C''est le livre des heures."}], "commonErrors": [{"wrong": "L''Agpeya est un livre de chants de la messe.", "right": "L''Agpeya est le livre des prières des heures.", "why": "La messe a ses propres livres ; l''Agpeya sert à prier dans la journée."}, {"wrong": "Il n''y a que les moines qui prient les heures.", "right": "Le livre est fait pour tous les fidèles.", "why": "Chacun peut prier à la maison ou à l''église."}], "tip": "Sept heures de prière pour sept louanges par jour : le verset du psaume donne le chiffre."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g84.prime_tierce_sexte', 'eg', 'grammar', 'knowledge', 'Prime, Tierce et Sexte', 2, '{}'::text[], 11, '{"rule": {"summary": "Prime (6 h) rappelle l''incarnation et la Résurrection, Tierce (9 h) le procès devant Pilate et la Pentecôte, Sexte (midi) la crucifixion.", "explanation": "Dans la Bible, le jour commence au lever du soleil, vers 6 h : la troisième heure est donc 9 h, la sixième heure est midi, la neuvième heure est 15 h. Les noms Prime, Tierce, Sexte et None viennent du latin : première, troisième, sixième, neuvième. Chaque heure fait revivre une scène du Christ, de la lumière du matin jusqu''à la croix.", "pattern": "Prime 6 h = lumière ; Tierce 9 h = Pilate et l''Esprit ; Sexte midi = la croix.", "examples": [{"text": "À 6 h, le soleil se lève.", "translation": "Prime : image du Christ ressuscité, lumière du monde."}, {"text": "À 9 h, le Christ est jugé par Pilate.", "translation": "Tierce rappelle ce procès et la Pentecôte."}, {"text": "À midi, les ténèbres couvrent la terre (Mt 27, 45).", "translation": "Sexte rappelle la crucifixion."}, {"text": "Tierce et Sexte se prient avant chaque messe.", "translation": "Elles préparent à la célébration."}], "commonErrors": [{"wrong": "Sexte rappelle la Résurrection.", "right": "Sexte rappelle la crucifixion.", "why": "À midi, le Christ est sur la croix ; la Résurrection est rappelée par Prime, à l''aube."}, {"wrong": "La troisième heure, c''est 3 h du matin.", "right": "La troisième heure, c''est 9 h.", "why": "Le jour biblique commence vers 6 h, au lever du soleil."}], "tip": "Le matin va de la lumière (Prime) au Pilate (Tierce) puis à la croix (Sexte) : trois heures, trois scènes."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g85.none_vepres_complies', 'eg', 'grammar', 'knowledge', 'None, Vêpres et Complies', 2, '{}'::text[], 11, '{"rule": {"summary": "La None (15 h) rappelle la mort du Christ, les Vêpres (coucher du soleil) la descente de la croix, les Complies (21 h) l''ensevelissement.", "explanation": "L''après-midi et le soir suivent la fin de la Passion. À la neuvième heure, Jésus rend l''esprit. Au soir, on descend son corps de la croix. Puis il est enseveli. Vêpres vient du latin vesper (« soir ») et Complies de completorium (« ce qui achève » la journée). Les Vêpres et les Complies se prient aussi à l''église pendant le Grand Carême et le jeûne de Ninive.", "pattern": "None 15 h = la mort ; Vêpres = la descente ; Complies 21 h = l''ensevelissement.", "examples": [{"text": "À 15 h, Jésus rend l''esprit.", "translation": "La None rappelle la mort du Christ sur la croix."}, {"text": "Au coucher du soleil, Joseph d''Arimathie demande le corps de Jésus.", "translation": "Vêpres : la descente de la croix."}, {"text": "Vers 21 h, avant de dormir.", "translation": "Complies : l''ensevelissement du Christ."}, {"text": "Carême : Vêpres et Complies à l''église.", "translation": "Le temps de pénitence demande plus de prière."}], "commonErrors": [{"wrong": "La None rappelle la crucifixion.", "right": "La None rappelle la mort du Christ ; Sexte rappelle la crucifixion.", "why": "Midi, c''est le Christ sur la croix ; 15 h, c''est sa mort."}, {"wrong": "Complies se prient à midi.", "right": "Complies se prient vers 21 h.", "why": "Ce sont les dernières prières avant de dormir."}], "tip": "Le soir suit l''ordre de l''Évangile : la mort, la descente, le tombeau."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g86.minuit_et_voile', 'eg', 'grammar', 'knowledge', 'Minuit et la prière du voile', 2, '{}'::text[], 11, '{"rule": {"summary": "Minuit rappelle la seconde venue du Christ (les dix vierges) et se prie en trois veilles, comme les trois prières du Christ à Gethsémani ; la prière du voile est une prière à part, un examen de conscience.", "explanation": "À minuit, tout dort et le croyant veille, comme les vierges sages qui attendent l''époux (Mt 25). La prière de minuit a trois parties, les trois veilles, en souvenir des trois prières du Christ à Gethsémani. C''est la source de la tasbeha, la louange de minuit. La prière du voile, à la fin de l''Agpeya, n''est pas une des sept heures : c''est un examen de conscience, surtout pour les évêques, les prêtres et les moines.", "pattern": "Minuit = veiller ; trois veilles ; dix vierges ; voile = examen de conscience.", "examples": [{"text": "Mt 25, 6 : « Voici l''époux ! » à minuit.", "translation": "Minuit rappelle la seconde venue du Christ."}, {"text": "Trois veilles, trois prières à Gethsémani.", "translation": "Le Christ prie trois fois et demande de veiller."}, {"text": "Ps 119, 62 : « À minuit je me lève pour te louer ».", "translation": "Le psalmiste veille la nuit."}, {"text": "La prière du voile est à part.", "translation": "Ce n''est pas l''une des sept heures."}], "commonErrors": [{"wrong": "La prière du voile est la huitième heure.", "right": "La prière du voile est une prière à part, hors des sept heures.", "why": "Elle sert d''examen de conscience, surtout au clergé et aux moines."}, {"wrong": "Minuit rappelle la crucifixion.", "right": "Minuit rappelle la seconde venue du Christ.", "why": "La crucifixion est rappelée par Sexte et la None."}], "tip": "Minuit veille, parce que l''époux peut venir à l''improviste."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g87.structure_et_gestes', 'eg', 'grammar', 'knowledge', 'La structure d''une heure et les gestes', 3, '{}'::text[], 11, '{"rule": {"summary": "Chaque heure suit le même plan en neuf étapes, dont 41 Kyrie eleison, et se prie debout, tourné vers l''est, après s''être préparé : mains et visage lavés, chaussures retirées, tête couverte pour les femmes.", "explanation": "Le même plan à chaque heure permet de prier sans se perdre. On commence par le Notre Père, on remercie, on demande pardon avec le psaume 50, puis on prie les psaumes de l''heure et l''Évangile. On termine par les litanies, les 41 Kyrie eleison, les prières avec l''absolution et la conclusion. Les gestes (debout, signe de croix, métanies) et la préparation (mains lavées, chaussures retirées, voile) disent le respect devant Dieu.", "pattern": "Notre Père → action de grâce → psaume 50 → psaumes → Évangile → litanies → 41 Kyrie → prières et absolution → conclusion.", "examples": [{"text": "Kyrie eleison, 41 fois.", "translation": "39 coups de fouet, la couronne d''épines et la lance."}, {"text": "Ps 50 : « Aie pitié de moi, ô Dieu ».", "translation": "La prière de repentance de David, à chaque heure."}, {"text": "Ex 3, 5 : « Retire tes sandales ».", "translation": "On retire ses chaussures comme Moïse devant le buisson."}, {"text": "1 Co 11, 5-6.", "translation": "Les femmes se couvrent la tête pour prier."}], "commonErrors": [{"wrong": "Le Kyrie eleison se dit 12 fois.", "right": "Le Kyrie eleison se dit 41 fois.", "why": "41 = 39 coups de fouet + la couronne d''épines + la lance."}, {"wrong": "Les gestes sont facultatifs et sans sens.", "right": "Chaque geste a un sens : respect, repentance, Trinité.", "why": "Le corps prie avec l''âme."}], "tip": "Neuf étapes : le Notre Père ouvre, l''absolution et la conclusion ferment."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g88.prier_vers_l_est', 'eg', 'grammar', 'knowledge', 'Prier vers l''est', 3, '{}'::text[], 11, '{"rule": {"summary": "On prie tourné vers l''est pour six raisons : le paradis perdu, la seconde venue, le Christ soleil de justice, l''étoile des mages, la croix et le baptême.", "explanation": "L''est est le côté du paradis (Gn 2, 8), de la lumière et du retour du Christ. Le soleil se lève à l''est, comme le salut. L''étoile des mages se lève à l''est et conduit au Christ. Sur la croix, le Christ regardait l''ouest : en regardant l''est, on se tient face à lui. Au baptême, on renie Satan tourné vers l''ouest et on confesse le Christ tourné vers l''est ; les églises sont bâties dans ce sens.", "pattern": "Six raisons : paradis, seconde venue, soleil de justice, étoile, croix, baptême.", "examples": [{"text": "Gn 2, 8 : « Dieu planta un jardin en Éden, à l''orient ».", "translation": "Le paradis perdu est à l''est : on désire y revenir."}, {"text": "Mt 24, 27 : « Comme l''éclair part de l''orient ».", "translation": "Le Christ revient de l''est."}, {"text": "Mt 2, 2 : « Nous avons vu son étoile à l''orient ».", "translation": "Les mages suivent l''étoile jusqu''au Christ."}, {"text": "Au baptême : ouest pour renier, est pour confesser.", "translation": "Les églises sont bâties tournées vers l''est."}], "commonErrors": [{"wrong": "On prie vers l''est parce que le soleil se lève, et c''est tout.", "right": "Il y a six raisons : paradis, seconde venue, soleil de justice, étoile, croix, baptême.", "why": "Le soleil est seulement l''une d''elles."}, {"wrong": "Le Christ regardait l''est sur la croix.", "right": "Selon la tradition, le Christ regardait l''ouest sur la croix.", "why": "En regardant l''est, on se tient face à lui."}], "tip": "Retiens l''idée : l''est est le côté de la lumière, du retour et du Christ."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g89.tasbeha_plan', 'eg', 'grammar', 'knowledge', 'La tasbeha : sens et plan général', 1, '{}'::text[], 12, '{"rule": {"summary": "La tasbeha (« louange » en arabe) est la louange de minuit : dans les monastères chaque nuit, en paroisse surtout la veille d''une messe. Son plan : Agpeya de minuit, Ten thino, quatre hoos, psali et théotokie, difnar, conclusion.", "explanation": "La tasbeha prolonge la prière de Minuit : l''Église veille et chante pour louer Dieu. Elle suit un plan fixe en six étapes. On commence par l''Agpeya de minuit, puis Ten thino appelle à se lever. Viennent les quatre hoos (avec les doxologies entre le 3e et le 4e), le psali et la théotokie du jour, le difnar qui rappelle le saint du jour, et la conclusion avec le Credo, le Trisagion et le Notre Père.", "pattern": "Agpeya de minuit → Ten thino → 4 hoos → psali et théotokie → difnar → conclusion.", "examples": [{"text": "Tasbeha, de l''arabe : « louange ».", "translation": "C''est la louange de minuit, une psalmodie."}, {"text": "Ten thino : « Levez-vous, fils de la lumière ».", "translation": "L''appel à se réveiller pour louer."}, {"text": "Le difnar rappelle le saint du jour.", "translation": "Même rôle que le synaxaire."}, {"text": "Trisagion : « trois fois saint ».", "translation": "Il clôt la tasbeha avec le Credo et le Notre Père."}], "commonErrors": [{"wrong": "La tasbeha se prie seulement à minuit pile.", "right": "En paroisse, on la prie surtout la veille d''une messe, sans attendre minuit.", "why": "Elle garde le nom de minuit, mais l''horaire s''adapte à la vie de la paroisse."}, {"wrong": "La tasbeha est un chant de la messe.", "right": "La tasbeha est une prière à part, la louange de minuit.", "why": "Elle se prie avant la messe, pas pendant."}], "tip": "Retiens les six étapes comme une petite histoire : réveil, louange, chants, saint du jour, conclusion."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g90.quatre_hoos', 'eg', 'grammar', 'knowledge', 'Les quatre hoos et les lobsh', 2, '{}'::text[], 12, '{"rule": {"summary": "La tasbeha chante quatre hoos : le cantique de Moïse (Ex 15), le psaume 135 (136), le cantique des trois jeunes gens (Dn 3) et les psaumes 148 à 150. Chacun est suivi d''un lobsh qui l''explique.", "explanation": "Un hoos est un cantique tiré de la Bible. Les quatre se suivent comme une histoire : on sort de l''esclavage du péché (mer Rouge), on rend grâce pour l''amour éternel de Dieu (psaume 135), toute la création loue Dieu avec les trois jeunes gens (Daniel 3), et on finit dans la joie et la victoire (psaumes 148 à 150). Après chaque hoos, le lobsh en donne le sens.", "pattern": "1er : mer Rouge (Ex 15) ; 2e : psaume 135 ; 3e : fournaise (Dn 3) ; 4e : psaumes 148 à 150.", "examples": [{"text": "1er hoos : Ex 15, la traversée de la mer Rouge.", "translation": "Il symbolise la sortie de l''esclavage du péché."}, {"text": "2e hoos : le psaume 135 (136).", "translation": "Une action de grâce : son amour est éternel."}, {"text": "3e hoos : Dn 3, les trois jeunes gens dans la fournaise.", "translation": "Toute la création est appelée à louer Dieu."}, {"text": "4e hoos : les psaumes 148, 149 et 150.", "translation": "Joie et victoire."}], "commonErrors": [{"wrong": "Le 4e hoos est le cantique de Moïse.", "right": "Le cantique de Moïse est le 1er hoos.", "why": "Il vient de la traversée de la mer Rouge, au début de l''histoire."}, {"wrong": "Le lobsh est un cantique biblique comme le hoos.", "right": "Le lobsh est une explication du hoos.", "why": "Il commente le cantique qui vient d''être chanté."}], "tip": "Quatre cantiques : liberté, amour, création, victoire."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g91.doxologies', 'eg', 'grammar', 'knowledge', 'Doxologies et commémoraison des saints', 2, '{}'::text[], 12, '{"rule": {"summary": "Entre le 3e et le 4e hoos, la commémoraison des saints et les doxologies (« chants de gloire ») glorifient la Vierge puis les saints.", "explanation": "Doxa est un mot grec qui veut dire « gloire » ; une doxologie est un chant de gloire. Dans la tasbeha, les doxologies viennent entre le 3e et le 4e hoos et glorifient la Vierge Marie, puis les saints. Louer les saints, c''est louer Dieu pour ce qu''il a fait en eux. La lettre aux Hébreux parle d''une « nuée de témoins » qui nous entoure, et on demande aux saints de prier pour nous.", "pattern": "Entre le 3e et le 4e hoos : doxologies. D''abord la Vierge, puis les saints.", "examples": [{"text": "Doxa, du grec : « gloire ».", "translation": "Une doxologie est un chant de gloire."}, {"text": "Les doxologies suivent le 3e hoos.", "translation": "Elles viennent avant les psaumes 148 à 150."}, {"text": "Lc 1, 28 : « Réjouis-toi, pleine de grâce ».", "translation": "La salutation de l''ange Gabriel inspire la doxologie de la Vierge."}, {"text": "He 12, 1 : une nuée de témoins.", "translation": "Les saints nous entourent."}], "commonErrors": [{"wrong": "Les doxologies adorent les saints.", "right": "Les doxologies glorifient les saints, mais on n''adore que Dieu.", "why": "On honore les saints, on adore Dieu seul."}, {"wrong": "Les doxologies viennent après le 4e hoos.", "right": "Elles viennent entre le 3e et le 4e hoos.", "why": "Le 4e hoos conclut la louange par les psaumes 148 à 150."}], "tip": "Doxa = gloire : on chante la gloire de Dieu à travers celle de ses saints."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g92.psali_theotokie', 'eg', 'grammar', 'knowledge', 'Psali et théotokie', 3, '{}'::text[], 12, '{"rule": {"summary": "Le psali est un chant au Christ, la théotokie une louange de la Vierge : il y en a un par jour, et la théotokie explique l''incarnation par des symboles de l''Ancien Testament (buisson ardent, arche, cruche d''or, chandelier).", "explanation": "Psali vient du grec « chanter des psaumes » et loue le Christ. Théotokie vient de Théotokos, « mère de Dieu », titre confirmé à Éphèse en 431 contre Nestorius. Il y a sept théotokies, une par jour. Chaque symbole de l''Ancien Testament montre ce que Marie porte : le buisson ardent, le feu de la divinité sans être consumée ; l''arche, le Verbe de Dieu ; la cruche d''or de la manne, le pain du ciel ; le chandelier, la vraie lumière.", "pattern": "Psali = chant au Christ ; théotokie = chant à la Vierge ; buisson, arche, cruche, chandelier.", "examples": [{"text": "Le buisson ardent brûle sans se consumer (Ex 3).", "translation": "Marie porte le feu de la divinité sans être consumée."}, {"text": "L''arche de l''alliance contient la Loi.", "translation": "Marie porte le Verbe de Dieu."}, {"text": "La cruche d''or contient la manne.", "translation": "Marie porte le pain du ciel, le Christ."}, {"text": "Le chandelier d''or porte la lumière.", "translation": "Marie porte la vraie lumière."}], "commonErrors": [{"wrong": "La théotokie loue le Christ.", "right": "La théotokie loue la Vierge ; le psali loue le Christ.", "why": "Le Fils et la Mère ont chacun leur chant."}, {"wrong": "On honore Marie à la place du Christ.", "right": "Louer Marie confesse que son Fils est Dieu.", "why": "Théotokos protège la foi en l''incarnation."}], "tip": "Les symboles disent tous la même chose : Marie porte Dieu."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g93.adam_watos', 'eg', 'grammar', 'knowledge', 'Les jours Adam et Watos', 3, '{}'::text[], 12, '{"rule": {"summary": "Les jours Adam sont dimanche, lundi et mardi, les jours Watos mercredi, jeudi, vendredi et samedi ; et comme le jour liturgique commence la veille au soir, le soir on prie déjà la théotokie du lendemain, sur l''air du lendemain.", "explanation": "Adam est le premier mot de la théotokie du lundi, qui raconte la chute d''Adam consolé par le Sauveur. Watos vient de Pibatos, premier mot de la théotokie du jeudi : le buisson de Moïse, image de la Vierge. Le jour liturgique commence la veille au soir, comme dans la Genèse (« il y eut un soir, il y eut un matin »). Donc samedi soir on prie la théotokie du dimanche, sur l''air Adam ; mardi soir, celle du mercredi, sur l''air Watos.", "pattern": "Adam : dimanche, lundi, mardi ; Watos : mercredi à samedi ; le soir = le lendemain.", "examples": [{"text": "Mardi, 20 h : la théotokie du mercredi, sur l''air Watos.", "translation": "Le jour liturgique du mercredi a déjà commencé."}, {"text": "Samedi, 20 h : la théotokie du dimanche, sur l''air Adam.", "translation": "Le dimanche a commencé le samedi soir."}, {"text": "Dimanche, 20 h : la théotokie du lundi, sur l''air Adam.", "translation": "Le lundi est un jour Adam."}, {"text": "Jeudi, 20 h : la théotokie du vendredi, sur l''air Watos.", "translation": "Le vendredi est un jour Watos."}], "commonErrors": [{"wrong": "Le samedi soir, on prie encore la théotokie du samedi.", "right": "Le samedi soir, on prie déjà la théotokie du dimanche, sur l''air Adam.", "why": "Le jour liturgique commence la veille au soir."}, {"wrong": "Mardi soir, on reste sur l''air Adam.", "right": "Mardi soir, on passe à la théotokie du mercredi, sur l''air Watos.", "why": "Le mercredi est un jour Watos, et il commence le mardi soir."}], "tip": "Pense au calendrier de l''Église : le jour commence au coucher du soleil, pas à minuit."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g94.kiahk_sept_et_quatre', 'eg', 'grammar', 'knowledge', 'Kiahk et la tasbeha « sept et quatre »', 3, '{}'::text[], 12, '{"rule": {"summary": "Kiahk, mois marial qui tombe pendant le jeûne de la Nativité, se prie avec la tasbeha « sept et quatre » : les 7 théotokies et les 4 hoos.", "explanation": "Kiahk est le quatrième mois copte, vers décembre : le mois de Marie, avant la naissance du Christ, car c''est par Marie que le Verbe se fait homme. La grande tasbeha « sept et quatre » y réunit les sept théotokies de la semaine et les quatre hoos. Autrefois elle durait toute la nuit du samedi au dimanche ; aujourd''hui on la prie souvent chaque soir. La règle du soir reste la même.", "pattern": "Kiahk = mois marial ; « sept et quatre » = 7 théotokies + 4 hoos.", "examples": [{"text": "Kiahk, mois marial.", "translation": "On loue Marie avant la Nativité."}, {"text": "Sept et quatre.", "translation": "Sept théotokies et quatre hoos."}, {"text": "Autrefois toute la nuit du samedi au dimanche.", "translation": "Aujourd''hui, souvent chaque soir."}, {"text": "Kiahk tombe pendant le jeûne de la Nativité.", "translation": "Il prépare à Noël."}], "commonErrors": [{"wrong": "Kiahk est le premier mois copte.", "right": "Kiahk est le quatrième mois copte.", "why": "Le calendrier copte commence en septembre, au Nayrouz."}, {"wrong": "« Sept et quatre » veut dire sept hoos et quatre théotokies.", "right": "« Sept et quatre » veut dire sept théotokies et quatre hoos.", "why": "Il y a sept jours, donc sept théotokies ; il y a quatre hoos."}], "tip": "Sept jours, sept théotokies ; quatre cantiques, quatre hoos : 7 et 4."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g95.calendrier_solaire', 'eg', 'grammar', 'knowledge', 'Le calendrier copte, héritier de l''Égypte ancienne', 1, '{}'::text[], 13, '{"rule": {"summary": "Le calendrier copte est solaire : 12 mois de 30 jours plus un petit mois de 5 jours (6 tous les quatre ans). Il commence le 1er Tout, vers le 11 septembre, et compte les années depuis 284, l''ère des martyrs.", "explanation": "Les anciens Égyptiens ont réglé leur année sur le soleil et sur la crue du Nil, avec trois saisons de quatre mois. Sous Auguste, Alexandrie y a ajouté un sixième jour tous les quatre ans : c''est le calendrier alexandrin, que les Coptes ont gardé. Ils ont changé le point de départ des années : 284, année de Dioclétien, pour garder la mémoire des martyrs. Pour passer de notre année à l''année copte, on retire 283 de septembre à décembre, 284 de janvier à août.", "pattern": "12 × 30 jours + 5 jours ; année copte = année grégorienne − 283 (sept.-déc.) ou − 284 (janv.-août).", "examples": [{"text": "Novembre 2026 : 2026 − 283 = 1743.", "translation": "On est en l''an 1743 de l''ère des martyrs."}, {"text": "Mars 2027 : 2027 − 284 = 1743.", "translation": "Toujours l''an 1743, car l''année copte change en septembre."}, {"text": "Le 1er Tout tombe le 11 septembre.", "translation": "C''est le Nayrouz, le jour de l''an copte."}, {"text": "Tous les quatre ans, Nasie compte six jours.", "translation": "Le Nayrouz tombe alors le 12 septembre."}], "commonErrors": [{"wrong": "L''année copte commence le 1er janvier.", "right": "Elle commence le 1er Tout, vers le 11 septembre.", "why": "Le calendrier copte suit le rythme du Nil, pas celui de l''année civile européenne."}, {"wrong": "Le calendrier copte compte depuis la naissance du Christ.", "right": "Il compte depuis 284, l''ère des martyrs.", "why": "Ce choix honore les martyrs de Dioclétien."}, {"wrong": "Il suffit toujours de retirer 283.", "right": "On retire 283 de septembre à décembre et 284 de janvier à août.", "why": "L''année copte change en septembre, pas en janvier."}], "tip": "L''année copte change en septembre : 283 en fin d''année, 284 au début."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g96.six_premiers_mois', 'eg', 'grammar', 'knowledge', 'Les six premiers mois : de Tout à Amshir', 2, array['eg.g95.calendrier_solaire']::text[], 13, '{"rule": {"summary": "Les six premiers mois, de septembre à début mars, sont Tout, Baba, Hatour, Kiahk, Touba et Amshir. Chacun compte 30 jours et commence vers le 10 d''un mois grégorien.", "explanation": "Tout porte le nom du dieu Thot et ouvre l''année avec le Nayrouz. Baba vient d''une fête égyptienne, Opet. Hatour porte le nom de la déesse Hathor ; c''est le temps des semailles. Kiahk, quatrième mois, est le mois marial, celui de Noël. Touba est le cœur de l''hiver et Amshir le mois des vents. Les dates valent pour une année ordinaire ; dans une année sur quatre, ces six mois commencent un jour plus tard.", "pattern": "Tout (11 sept.), Baba (11 oct.), Hatour (10 nov.), Kiahk (10 déc.), Touba (9 janv.), Amshir (8 févr.).", "examples": [{"text": "Tout commence vers le 11 septembre.", "translation": "C''est le premier mois et le mois de Thot."}, {"text": "Hatour est le troisième mois.", "translation": "Il porte le nom de la déesse Hathor."}, {"text": "Kiahk est le quatrième mois.", "translation": "C''est le mois marial."}, {"text": "Amshir est le sixième mois.", "translation": "C''est le mois des vents."}], "commonErrors": [{"wrong": "Kiahk est le premier mois.", "right": "Kiahk est le quatrième mois ; le premier est Tout.", "why": "L''ordre est Tout, Baba, Hatour, Kiahk, Touba, Amshir."}, {"wrong": "Hatour porte le nom de Thot.", "right": "Thot a donné Tout ; Hathor a donné Hatour.", "why": "Les deux noms se ressemblent, pas les dieux."}, {"wrong": "Touba est un mois d''été.", "right": "Touba commence vers le 9 janvier : c''est plein hiver.", "why": "Les mois coptes sont décalés par rapport à ceux de notre calendrier."}], "tip": "Le début d''un mois copte tombe toujours vers le 10 d''un mois grégorien."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g97.sept_derniers_mois', 'eg', 'grammar', 'knowledge', 'Les sept derniers mois, Nasie et le Nil', 2, array['eg.g96.six_premiers_mois']::text[], 13, '{"rule": {"summary": "Les sept derniers mois sont Baramhat, Baramouda, Bashans, Baouna, Abib, Misra et Nasie. Nasie, le petit mois, compte 5 jours, 6 dans l''année bissextile copte, tous les quatre ans.", "explanation": "Baramhat, Baramouda et Bashans sont les mois de la moisson. Baouna et Abib sont les mois de la chaleur, et le Nil commence à monter à la fin de Baouna. En Misra, la crue remplit les canaux. Nasie ferme l''année avec ses 5 jours, juste avant le Nayrouz. Les proverbes des paysans résument chaque mois : Touba rend la jeune fille toute recroquevillée de froid, Amshir apporte des rafales de vent.", "pattern": "Baramhat (10 mars), Baramouda (9 avril), Bashans (9 mai), Baouna (8 juin), Abib (8 juillet), Misra (7 août), Nasie (6 septembre).", "examples": [{"text": "Nasie est le petit mois.", "translation": "Il compte 5 jours, ou 6 tous les quatre ans."}, {"text": "Bashans يكنس الغيط كنس.", "translation": "Bashans balaie le champ : la moisson est finie."}, {"text": "Misra : la crue remplit les canaux.", "translation": "Le fleuve revient irriguer les terres."}, {"text": "Abib commence vers le 8 juillet.", "translation": "C''est le onzième mois, en pleine chaleur."}], "commonErrors": [{"wrong": "Nasie compte 30 jours comme les autres mois.", "right": "Nasie compte 5 jours, ou 6 dans l''année bissextile copte.", "why": "Il complète les 360 jours pour arriver à 365."}, {"wrong": "Misra est le dernier mois.", "right": "Misra est le douzième ; le treizième est Nasie.", "why": "Le petit mois vient après les douze grands."}, {"wrong": "Les proverbes des mois sont des règles de l''Église.", "right": "Ce sont des dictons de paysans égyptiens.", "why": "Ils viennent de la vie des champs, pas de la liturgie."}], "tip": "Douze grands mois de 30 jours, puis Nasie, le petit mois."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.g98.lire_une_date_copte', 'eg', 'grammar', 'knowledge', 'Lire une date copte : jeux et bilan', 3, array['eg.g97.sept_derniers_mois']::text[], 13, '{"rule": {"summary": "Pour lire une date copte, on retient l''ordre des treize mois, leur début approximatif (autour du 10 de chaque mois grégorien) et la règle de l''année : moins 283 de septembre à décembre, moins 284 de janvier à août.", "explanation": "Pour trouver le mois copte d''une date grégorienne, on repère le début de mois juste avant elle. Par exemple, Baramhat commence vers le 10 mars : le 20 mars est dans Baramhat. Mieux vaut prendre des dates au milieu du mois : près d''un début de mois, un jour d''écart est possible. Noël copte tombe le 29 Kiahk, vers le 7 janvier.", "pattern": "Mois copte = dernier début de mois avant la date ; année copte = année grégorienne − 283 ou − 284.", "examples": [{"text": "Le 20 mars tombe dans Baramhat.", "translation": "Baramhat commence vers le 10 mars."}, {"text": "Le 25 juillet tombe dans Abib.", "translation": "Abib commence vers le 8 juillet."}, {"text": "Noël copte est le 29 Kiahk.", "translation": "Cela tombe vers le 7 janvier."}, {"text": "Juillet 2030 : 2030 − 284 = 1746.", "translation": "On est avant le Nayrouz, donc on retire 284."}], "commonErrors": [{"wrong": "Le 20 mars est dans Amshir.", "right": "Le 20 mars est dans Baramhat.", "why": "Amshir se termine vers le 9 mars."}, {"wrong": "En janvier 2030, l''année copte est 2030 − 283.", "right": "En janvier, on retire 284.", "why": "Le Nayrouz n''est pas encore arrivé."}], "tip": "Prends le dernier début de mois avant ta date."}, "functionWords": []}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
