insert into public.learning_units (id, language_id, kind, category, title, difficulty, prerequisites, module, data, content_version, deprecated) values ('eg.v.empire_romain', 'eg', 'vocabulary', 'vocabulary', 'l''Empire romain', 1, '{}'::text[], 1, '{"translation": "puissance qui domine le monde connu au temps de Jésus", "partOfSpeech": "organization", "lessonId": "eg.l01", "dictionaryItemId": "eg.d.empire_romain"}'::jsonb, '1.0.0', false) on conflict (id) do update set kind = excluded.kind, category = excluded.category, title = excluded.title, difficulty = excluded.difficulty, prerequisites = excluded.prerequisites, module = excluded.module, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
