accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e19', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.premiere_communaute','eg.v.saint_pierre']::text[], 'match', 'lesson', 'Les chiffres de la première communauté', '{}'::text[], 'Le groupe grandit très vite : cent vingt, puis trois mille à la Pentecôte, puis environ cinq mille. Quatre piliers le structurent.', 3, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.premiere_communaute", "eg.v.saint_pierre"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les chiffres de la première communauté", "promptLanguage": "fr", "answer": "Cent vingt = le groupe de la chambre haute ; Trois mille = convertis le jour de la Pentecôte ; Cinq mille = croyants peu après ; Quatre = piliers de la vie commune", "acceptedAnswers": [], "explanation": "Le groupe grandit très vite : cent vingt, puis trois mille à la Pentecôte, puis environ cinq mille. Quatre piliers le structurent.", "tip": "120 → 3000 → 5000.", "pairs": [{"left": "Cent vingt", "right": "le groupe de la chambre haute"}, {"left": "Trois mille", "right": "convertis le jour de la Pentecôte"}, {"left": "Cinq mille", "right": "croyants peu après"}, {"left": "Quatre", "right": "piliers de la vie commune"}], "id": "eg.l02.e19", "pool": "lesson", "lessonId": "eg.l02", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e20', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute']::text[], 'reorder', 'lesson', 'Phrase-repère : la naissance de l''Église.', array['La Pentecôte marque la naissance de l''Église']::text[], 'La tradition chrétienne place à la Pentecôte les débuts de l''Église.', 1, '{"unitIds": ["eg.g02.pentecote_communaute"], "type": "reorder", "difficulty": 1, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la naissance de l''Église.", "promptLanguage": "fr", "answer": "La Pentecôte marque la naissance de l''Église", "acceptedAnswers": ["La Pentecôte marque la naissance de l''Église"], "explanation": "La tradition chrétienne place à la Pentecôte les débuts de l''Église.", "tip": "Pentecôte = naissance de l''Église.", "extraExample": {"text": "L''Esprit Saint descend sur les apôtres.", "translation": "Pierre prêche à la foule."}, "tokens": ["naissance", "de", "l''Église", "La", "Pentecôte", "marque", "la"], "id": "eg.l02.e20", "pool": "lesson", "lessonId": "eg.l02", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e21', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.pentecote']::text[], 'free_answer', 'lesson', 'Comment s''appelle la fête où l''Esprit Saint descend sur les apôtres, début de l''Église ?', array['la Pentecôte','Pentecôte','pentecote']::text[], 'C''est la Pentecôte, cinquante jours après la Résurrection.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.pentecote"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle la fête où l''Esprit Saint descend sur les apôtres, début de l''Église ?", "promptLanguage": "fr", "answer": "la Pentecôte", "acceptedAnswers": ["la Pentecôte", "Pentecôte", "pentecote"], "explanation": "C''est la Pentecôte, cinquante jours après la Résurrection.", "tip": "Cinquante jours après Pâques.", "extraExample": {"text": "Elle a lieu vers l''an 30.", "translation": "Pierre y prêche."}, "hint": "Son nom veut dire « cinquantième ».", "id": "eg.l02.e21", "pool": "lesson", "lessonId": "eg.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e22', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.fraction_du_pain']::text[], 'free_answer', 'lesson', 'Les premiers chrétiens célèbrent « la fraction du ___ ».', array['pain','la fraction du pain']::text[], 'La fraction du pain est le nom donné à l''eucharistie dans la première communauté.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.fraction_du_pain"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Les premiers chrétiens célèbrent « la fraction du ___ ».", "promptLanguage": "fr", "answer": "pain", "acceptedAnswers": ["pain", "la fraction du pain"], "explanation": "La fraction du pain est le nom donné à l''eucharistie dans la première communauté.", "tip": "Rompre le pain.", "extraExample": {"text": "Jésus rompt le pain à la dernière Cène.", "translation": "Les disciples l''imitent."}, "hint": "Un aliment de base.", "id": "eg.l02.e22", "pool": "lesson", "lessonId": "eg.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l02.e23', 'eg', 'eg.l02', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.saint_pierre','eg.v.pentecote']::text[], 'free_answer', 'lesson', 'Quel apôtre prêche en public le jour de la Pentecôte ?', array['Pierre','saint Pierre','St Pierre']::text[], 'Pierre, le chef des apôtres, prend la parole : trois mille personnes se convertissent.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.saint_pierre", "eg.v.pentecote"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel apôtre prêche en public le jour de la Pentecôte ?", "promptLanguage": "fr", "answer": "Pierre", "acceptedAnswers": ["Pierre", "saint Pierre", "St Pierre"], "explanation": "Pierre, le chef des apôtres, prend la parole : trois mille personnes se convertissent.", "tip": "Pierre porte la voix des Douze.", "extraExample": {"text": "Il sera martyrisé à Rome.", "translation": "Vers l''an 67."}, "hint": "Il a reçu ce nom de Jésus.", "id": "eg.l02.e23", "pool": "lesson", "lessonId": "eg.l02", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e01', 'eg', 'eg.l03', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.pentecote']::text[], 'mcq', 'lesson', 'Quelle fête marque la naissance de l''Église ?', array['la Pentecôte']::text[], 'À la Pentecôte, l''Esprit Saint descend sur les apôtres et l''Église naît à Jérusalem.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.pentecote"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle fête marque la naissance de l''Église ?", "promptLanguage": "fr", "answer": "la Pentecôte", "acceptedAnswers": ["la Pentecôte"], "explanation": "À la Pentecôte, l''Esprit Saint descend sur les apôtres et l''Église naît à Jérusalem.", "tip": "Cinquante jours après Pâques.", "extraExample": {"text": "Trois mille personnes se convertissent ce jour-là.", "translation": "Pierre est le prédicateur."}, "options": ["la Résurrection", "la Pentecôte", "l''Ascension"], "id": "eg.l03.e01", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e02', 'eg', 'eg.l03', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.fraction_du_pain']::text[], 'fill_blank', 'lesson', 'La première communauté est fidèle à la ___ du pain.', array['fraction']::text[], 'La fraction du pain est le nom de l''eucharistie chez les premiers chrétiens.', 2, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.fraction_du_pain"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "La première communauté est fidèle à la ___ du pain.", "promptLanguage": "fr", "answer": "fraction", "acceptedAnswers": ["fraction"], "explanation": "La fraction du pain est le nom de l''eucharistie chez les premiers chrétiens.", "tip": "Rompre le pain.", "extraExample": {"text": "Elle fait partie des quatre piliers.", "translation": "Enseignement, communion, fraction du pain, prières."}, "options": ["fraction", "bénédiction", "distribution"], "id": "eg.l03.e02", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e03', 'eg', 'eg.l03', 'eg.g01.pourquoi_histoire', array['eg.g01.pourquoi_histoire','eg.v.schisme']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on une rupture de communion entre des Églises ?', array['schisme','un schisme','le schisme']::text[], 'C''est un schisme : l''unité est rompue, même si la doctrine peut rester proche.', 2, '{"unitIds": ["eg.g01.pourquoi_histoire", "eg.v.schisme"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on une rupture de communion entre des Églises ?", "promptLanguage": "fr", "answer": "schisme", "acceptedAnswers": ["schisme", "un schisme", "le schisme"], "explanation": "C''est un schisme : l''unité est rompue, même si la doctrine peut rester proche.", "tip": "Schisme = séparation.", "extraExample": {"text": "Il se distingue de l''hérésie.", "translation": "L''hérésie touche la doctrine."}, "hint": "Elle commence par « sch ».", "id": "eg.l03.e03", "pool": "lesson", "lessonId": "eg.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e04', 'eg', 'eg.l03', 'eg.g02.pentecote_communaute', array['eg.g02.pentecote_communaute','eg.v.jerusalem']::text[], 'mcq', 'lesson', 'Dans quelle ville naît l''Église ?', array['Jérusalem']::text[], 'L''Église naît à Jérusalem, à la Pentecôte. Antioche et Rome viendront ensuite.', 1, '{"unitIds": ["eg.g02.pentecote_communaute", "eg.v.jerusalem"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quelle ville naît l''Église ?", "promptLanguage": "fr", "answer": "Jérusalem", "acceptedAnswers": ["Jérusalem"], "explanation": "L''Église naît à Jérusalem, à la Pentecôte. Antioche et Rome viendront ensuite.", "tip": "Tout commence à Jérusalem.", "extraExample": {"text": "Les apôtres y prêchent d''abord.", "translation": "Puis ils se dispersent."}, "options": ["Jérusalem", "Antioche", "Rome"], "id": "eg.l03.e04", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e05', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.helleniste']::text[], 'mcq', 'lesson', 'Qui sont les hellénistes ?', array['les chrétiens de langue grecque']::text[], 'Les hellénistes sont des chrétiens de langue grecque. Leurs veuves sont oubliées dans le service quotidien, ce qui provoque le premier conflit.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.helleniste"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les hellénistes ?", "promptLanguage": "fr", "answer": "les chrétiens de langue grecque", "acceptedAnswers": ["les chrétiens de langue grecque"], "explanation": "Les hellénistes sont des chrétiens de langue grecque. Leurs veuves sont oubliées dans le service quotidien, ce qui provoque le premier conflit.", "tip": "Hellène = grec.", "extraExample": {"text": "Le mot hellénique vient de Hellas, la Grèce.", "translation": "Ils parlent grec."}, "options": ["les chrétiens de langue grecque", "les chrétiens de langue hébraïque", "les prêtres du Temple"], "id": "eg.l03.e05", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e06', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.helleniste']::text[], 'fill_blank', 'lesson', 'Les hellénistes se plaignent que leurs ___ soient oubliées dans le service quotidien.', array['veuves']::text[], 'Le service quotidien oublie les veuves des hellénistes : ce premier conflit mène au choix de sept hommes.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.helleniste"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les hellénistes se plaignent que leurs ___ soient oubliées dans le service quotidien.", "promptLanguage": "fr", "answer": "veuves", "acceptedAnswers": ["veuves"], "explanation": "Le service quotidien oublie les veuves des hellénistes : ce premier conflit mène au choix de sept hommes.", "tip": "Veuves oubliées = conflit.", "extraExample": {"text": "Les apôtres ne peuvent tout faire.", "translation": "Ils délèguent."}, "options": ["veuves", "enfants", "prêtres"], "id": "eg.l03.e06", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e07', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions']::text[], 'mcq', 'lesson', 'Combien d''hommes sont choisis pour le service des tables ?', array['sept']::text[], 'Les apôtres, occupés par la prédication, font choisir sept hommes pour le service. Étienne est l''un d''eux.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''hommes sont choisis pour le service des tables ?", "promptLanguage": "fr", "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Les apôtres, occupés par la prédication, font choisir sept hommes pour le service. Étienne est l''un d''eux.", "tip": "Douze apôtres, sept pour le service.", "extraExample": {"text": "Le service est confié à d''autres.", "translation": "Pour libérer les apôtres."}, "options": ["trois", "sept", "douze"], "id": "eg.l03.e07", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e08', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_etienne']::text[], 'mcq', 'lesson', 'Qui est le premier martyr chrétien ?', array['Étienne']::text[], 'Étienne est lapidé à Jérusalem vers 35, après avoir témoigné devant les autorités. Il est le premier martyr de l''Église.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_etienne"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le premier martyr chrétien ?", "promptLanguage": "fr", "answer": "Étienne", "acceptedAnswers": ["Étienne"], "explanation": "Étienne est lapidé à Jérusalem vers 35, après avoir témoigné devant les autorités. Il est le premier martyr de l''Église.", "tip": "Étienne = premier.", "extraExample": {"text": "Jacques de Zébédée est martyrisé vers 44.", "translation": "Pierre vers 67."}, "options": ["Jacques", "Pierre", "Étienne"], "errorPatterns": [{"equals": "Jacques", "category": "word_confusion", "feedback": "Jacques de Zébédée meurt vers 44, après Étienne."}, {"equals": "Pierre", "category": "word_confusion", "feedback": "Pierre est martyrisé à Rome vers 67."}], "id": "eg.l03.e08", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e09', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_etienne']::text[], 'fill_blank', 'lesson', 'Étienne meurt ___ vers 35 : il est le premier martyr.', array['lapidé']::text[], 'Étienne est lapidé, c''est-à-dire tué à coups de pierres, vers 35.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_etienne"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Étienne meurt ___ vers 35 : il est le premier martyr.", "promptLanguage": "fr", "answer": "lapidé", "acceptedAnswers": ["lapidé"], "explanation": "Étienne est lapidé, c''est-à-dire tué à coups de pierres, vers 35.", "tip": "Lapidé = pierres.", "extraExample": {"text": "Jacques de Zébédée est décapité.", "translation": "Chaque martyr a sa mort."}, "options": ["crucifié", "lapidé", "décapité"], "id": "eg.l03.e09", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e10', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.martyr']::text[], 'free_answer', 'lesson', 'Quel mot, du grec « témoin », désigne celui qui meurt pour sa foi ?', array['martyr','un martyr','le martyr']::text[], 'Le martyr est un témoin du Christ jusqu''à la mort. Étienne est le premier.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.martyr"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel mot, du grec « témoin », désigne celui qui meurt pour sa foi ?", "promptLanguage": "fr", "answer": "martyr", "acceptedAnswers": ["martyr", "un martyr", "le martyr"], "explanation": "Le martyr est un témoin du Christ jusqu''à la mort. Étienne est le premier.", "tip": "Martyr = témoin.", "extraExample": {"text": "Marc sera martyr à Alexandrie.", "translation": "Le mot grec martys."}, "hint": "Il commence par « m ».", "id": "eg.l03.e10", "pool": "lesson", "lessonId": "eg.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e11', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions']::text[], 'mcq', 'lesson', 'Quel est l''effet de la persécution qui suit la mort d''Étienne ?', array['l''Évangile se répand']::text[], 'Les chrétiens se dispersent, mais ils annoncent l''Évangile là où ils vont. La persécution étend l''Église.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est l''effet de la persécution qui suit la mort d''Étienne ?", "promptLanguage": "fr", "answer": "l''Évangile se répand", "acceptedAnswers": ["l''Évangile se répand"], "explanation": "Les chrétiens se dispersent, mais ils annoncent l''Évangile là où ils vont. La persécution étend l''Église.", "tip": "Persécuter disperse, disperser sème.", "extraExample": {"text": "Antioche reçoit ainsi l''Évangile.", "translation": "Les Samaritains aussi."}, "options": ["l''Église disparaît", "les apôtres cessent de prêcher", "l''Évangile se répand"], "id": "eg.l03.e11", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e12', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_paul']::text[], 'mcq', 'lesson', 'Sur quelle route Saul rencontre-t-il le Christ vers l''an 35 ?', array['la route de Damas']::text[], 'Sur la route de Damas, le Christ apparaît à Saul le persécuteur : il devient Paul.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_paul"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Sur quelle route Saul rencontre-t-il le Christ vers l''an 35 ?", "promptLanguage": "fr", "answer": "la route de Damas", "acceptedAnswers": ["la route de Damas"], "explanation": "Sur la route de Damas, le Christ apparaît à Saul le persécuteur : il devient Paul.", "tip": "Damas = conversion.", "extraExample": {"text": "Il avait des lettres contre les chrétiens.", "translation": "Il est renversé."}, "options": ["la route de Rome", "la route d''Alexandrie", "la route de Damas"], "id": "eg.l03.e12", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e13', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.saint_paul']::text[], 'fill_blank', 'lesson', 'Saul, devenu ___, est l''apôtre des nations.', array['Paul']::text[], 'Saul change de vie et de nom d''usage : Paul est l''apôtre des nations.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.saint_paul"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Saul, devenu ___, est l''apôtre des nations.", "promptLanguage": "fr", "answer": "Paul", "acceptedAnswers": ["Paul"], "explanation": "Saul change de vie et de nom d''usage : Paul est l''apôtre des nations.", "tip": "Saul → Paul.", "extraExample": {"text": "Paul est aussi citoyen romain.", "translation": "Il écrit de nombreuses lettres."}, "options": ["Pierre", "Barnabé", "Paul"], "id": "eg.l03.e13", "pool": "lesson", "lessonId": "eg.l03", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e14', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.barnabe']::text[], 'free_answer', 'lesson', 'Comment s''appelle le compagnon de Paul dans ses premières missions ?', array['Barnabé','saint Barnabé','Barnabe']::text[], 'Barnabé accompagne Paul dans les synagogues puis chez les païens.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.barnabe"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle le compagnon de Paul dans ses premières missions ?", "promptLanguage": "fr", "answer": "Barnabé", "acceptedAnswers": ["Barnabé", "saint Barnabé", "Barnabe"], "explanation": "Barnabé accompagne Paul dans les synagogues puis chez les païens.", "tip": "Paul et Barnabé vont ensemble.", "extraExample": {"text": "Barnabé est le cousin de Marc.", "translation": "Il sera utile pour la suite."}, "hint": "Son nom commence par « B ».", "id": "eg.l03.e14", "pool": "lesson", "lessonId": "eg.l03", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e15', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.synagogue']::text[], 'mcq', 'lesson', 'Où Paul va-t-il d''abord dans chaque ville ?', array['la synagogue']::text[], 'Dans chaque ville, Paul va d''abord à la synagogue, pour convaincre les Juifs, qui connaissent déjà les Écritures.', 2, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.synagogue"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où Paul va-t-il d''abord dans chaque ville ?", "promptLanguage": "fr", "answer": "la synagogue", "acceptedAnswers": ["la synagogue"], "explanation": "Dans chaque ville, Paul va d''abord à la synagogue, pour convaincre les Juifs, qui connaissent déjà les Écritures.", "tip": "D''abord ses frères juifs.", "extraExample": {"text": "Les synagogues sont partout dans l''Empire.", "translation": "Elles servent de porte d''entrée."}, "options": ["le marché", "la synagogue", "le palais du gouverneur"], "id": "eg.l03.e15", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l03.e16', 'eg', 'eg.l03', 'eg.g03.etienne_paul_missions', array['eg.g03.etienne_paul_missions','eg.v.paiens']::text[], 'mcq', 'lesson', 'Comment appelle-t-on les non-juifs auxquels Paul annonce l''Évangile ?', array['les païens']::text[], 'Les païens sont les non-juifs. Quand les synagogues refusent, Paul se tourne vers eux et rencontre un grand succès.', 1, '{"unitIds": ["eg.g03.etienne_paul_missions", "eg.v.paiens"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on les non-juifs auxquels Paul annonce l''Évangile ?", "promptLanguage": "fr", "answer": "les païens", "acceptedAnswers": ["les païens"], "explanation": "Les païens sont les non-juifs. Quand les synagogues refusent, Paul se tourne vers eux et rencontre un grand succès.", "tip": "Païens = non-juifs.", "extraExample": {"text": "Beaucoup de Grecs accueillent l''Évangile.", "translation": "Sans devenir juifs."}, "options": ["les païens", "les hellénistes", "les pharisiens"], "id": "eg.l03.e16", "pool": "lesson", "lessonId": "eg.l03", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
