insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e04', 'eg', 'eg.l08', 'eg.g06.ecrits_heresies', array['eg.g06.ecrits_heresies','eg.v.gnosticisme']::text[], 'free_answer', 'lesson', 'Quelle hérésie du Ier siècle sépare le monde en un Dieu bon et un dieu mauvais ?', array['gnosticisme','le gnosticisme','la gnose','gnose']::text[], 'Le gnosticisme voit un Dieu bon et un dieu mauvais qui a créé le monde. Jean le combat.', 3, '{"unitIds": ["eg.g06.ecrits_heresies", "eg.v.gnosticisme"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quelle hérésie du Ier siècle sépare le monde en un Dieu bon et un dieu mauvais ?", "promptLanguage": "fr", "answer": "gnosticisme", "acceptedAnswers": ["gnosticisme", "le gnosticisme", "la gnose", "gnose"], "explanation": "Le gnosticisme voit un Dieu bon et un dieu mauvais qui a créé le monde. Jean le combat.", "tip": "Gnose = connaissance.", "extraExample": {"text": "Elle reviendra à Alexandrie au IIe siècle.", "translation": "Les Pères la combattront."}, "hint": "Du grec « connaissance ».", "id": "eg.l08.e04", "pool": "lesson", "lessonId": "eg.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e05', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.alexandrie']::text[], 'mcq', 'lesson', 'Qui a fondé Alexandrie en 331 av. J.-C. ?', array['Alexandre le Grand']::text[], 'Alexandre le Grand fonde Alexandrie en 331 av. J.-C. : la ville porte son nom.', 1, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.alexandrie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui a fondé Alexandrie en 331 av. J.-C. ?", "promptLanguage": "fr", "answer": "Alexandre le Grand", "acceptedAnswers": ["Alexandre le Grand"], "explanation": "Alexandre le Grand fonde Alexandrie en 331 av. J.-C. : la ville porte son nom.", "tip": "Alexandrie = Alexandre.", "extraExample": {"text": "Elle devient un grand port.", "translation": "Puis une capitale du savoir."}, "options": ["Alexandre le Grand", "Jules César", "Ptolémée Ier"], "id": "eg.l08.e05", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e06', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.alexandrie']::text[], 'fill_blank', 'lesson', 'Dans l''Alexandrie du Ier siècle, on parle surtout ___.', array['grec']::text[], 'Alexandrie est une ville grecque : les Juifs eux-mêmes y lisent la Bible en grec (Septante).', 1, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.alexandrie"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Dans l''Alexandrie du Ier siècle, on parle surtout ___.", "promptLanguage": "fr", "answer": "grec", "acceptedAnswers": ["grec"], "explanation": "Alexandrie est une ville grecque : les Juifs eux-mêmes y lisent la Bible en grec (Septante).", "tip": "Ville grecque d''Égypte.", "extraExample": {"text": "Le Nouveau Testament est écrit en grec.", "translation": "Cela facilite la mission."}, "options": ["araméen", "grec", "latin"], "id": "eg.l08.e06", "pool": "lesson", "lessonId": "eg.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e07', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.septante']::text[], 'mcq', 'lesson', 'Comment appelle-t-on la traduction grecque de la Bible faite à Alexandrie ?', array['la Septante']::text[], 'La Septante est la Bible hébraïque traduite en grec à Alexandrie. Les premiers chrétiens la citent.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.septante"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on la traduction grecque de la Bible faite à Alexandrie ?", "promptLanguage": "fr", "answer": "la Septante", "acceptedAnswers": ["la Septante"], "explanation": "La Septante est la Bible hébraïque traduite en grec à Alexandrie. Les premiers chrétiens la citent.", "tip": "Septante = Bible grecque.", "extraExample": {"text": "La Vulgate est en latin (IVe siècle).", "translation": "Le Talmud est juif."}, "options": ["la Vulgate", "le Talmud", "la Septante"], "id": "eg.l08.e07", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e08', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie']::text[], 'mcq', 'lesson', 'Quel prophète annonçait « un autel pour le Seigneur au milieu du pays d''Égypte » ?', array['Isaïe']::text[], 'Le prophète Isaïe (19, 19) annonce un autel pour le Seigneur au cœur de l''Égypte : l''Église copte y voit la promesse de sa mission.', 3, '{"unitIds": ["eg.g08.marc_alexandrie"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel prophète annonçait « un autel pour le Seigneur au milieu du pays d''Égypte » ?", "promptLanguage": "fr", "answer": "Isaïe", "acceptedAnswers": ["Isaïe"], "explanation": "Le prophète Isaïe (19, 19) annonce un autel pour le Seigneur au cœur de l''Égypte : l''Église copte y voit la promesse de sa mission.", "tip": "Isaïe 19, 19.", "extraExample": {"text": "Les Coptes aiment citer ce verset.", "translation": "Il prépare Marc."}, "options": ["Isaïe", "Jérémie", "Daniel"], "id": "eg.l08.e08", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e09', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.saint_marc']::text[], 'mcq', 'lesson', 'Où Marc est-il né, selon la tradition copte ?', array['à Cyrène']::text[], 'La tradition copte le dit né à Cyrène, en Libye actuelle, dans une famille juive de culture grecque.', 3, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.saint_marc"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Où Marc est-il né, selon la tradition copte ?", "promptLanguage": "fr", "answer": "à Cyrène", "acceptedAnswers": ["à Cyrène"], "explanation": "La tradition copte le dit né à Cyrène, en Libye actuelle, dans une famille juive de culture grecque.", "tip": "Marc de Cyrène.", "extraExample": {"text": "Cyrène était dans la Pentapole.", "translation": "Des gens de Cyrène sont à la Pentecôte."}, "options": ["à Cyrène", "à Alexandrie", "à Rome"], "id": "eg.l08.e09", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e10', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.saint_marc','eg.v.barnabe']::text[], 'mcq', 'lesson', 'Quel compagnon de Paul est le cousin de Marc ?', array['Barnabé']::text[], 'Marc est cousin de Barnabé (Col 4, 10). Il les accompagne, Paul et Barnabé, dans leur premier voyage.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.saint_marc", "eg.v.barnabe"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel compagnon de Paul est le cousin de Marc ?", "promptLanguage": "fr", "answer": "Barnabé", "acceptedAnswers": ["Barnabé"], "explanation": "Marc est cousin de Barnabé (Col 4, 10). Il les accompagne, Paul et Barnabé, dans leur premier voyage.", "tip": "Marc, cousin de Barnabé.", "extraExample": {"text": "Plus tard Marc suit Pierre.", "translation": "Ils se retrouvent à Rome."}, "options": ["Jean", "Barnabé", "Pierre"], "id": "eg.l08.e10", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e11', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.saint_marc']::text[], 'mcq', 'lesson', 'Quel apôtre appelle Marc « mon fils » ?', array['Pierre']::text[], 'Pierre écrit : « Marc, mon fils » (1 P 5, 13). Marc est son disciple et son interprète.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.saint_marc"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel apôtre appelle Marc « mon fils » ?", "promptLanguage": "fr", "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Pierre écrit : « Marc, mon fils » (1 P 5, 13). Marc est son disciple et son interprète.", "tip": "Marc = fils de Pierre.", "extraExample": {"text": "La tradition lie son évangile à la prédication de Pierre.", "translation": "Pierre est à Rome."}, "options": ["Paul", "Barthélemy", "Pierre"], "id": "eg.l08.e11", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e12', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.anianus']::text[], 'free_answer', 'lesson', 'Comment s''appelle le cordonnier d''Alexandrie, premier converti de Marc ?', array['Anianus','Hananiya','Ananias','Hananie']::text[], 'Anianus accueille Marc, est guéri, puis devient évêque après lui.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.anianus"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle le cordonnier d''Alexandrie, premier converti de Marc ?", "promptLanguage": "fr", "answer": "Anianus", "acceptedAnswers": ["Anianus", "Hananiya", "Ananias", "Hananie"], "explanation": "Anianus accueille Marc, est guéri, puis devient évêque après lui.", "tip": "Anianus = cordonnier.", "extraExample": {"text": "Il devient le deuxième évêque d''Alexandrie.", "translation": "En arabe, Hananiya."}, "hint": "Son nom commence par « A ».", "id": "eg.l08.e12", "pool": "lesson", "lessonId": "eg.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e13', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.saint_marc']::text[], 'fill_blank', 'lesson', 'Marc guérit la main d''Anianus au nom du ___.', array['Christ']::text[], 'Marc guérit Anianus au nom du Christ, ce qui conduit Anianus et sa famille à la foi.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.saint_marc"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Marc guérit la main d''Anianus au nom du ___.", "promptLanguage": "fr", "answer": "Christ", "acceptedAnswers": ["Christ"], "explanation": "Marc guérit Anianus au nom du Christ, ce qui conduit Anianus et sa famille à la foi.", "tip": "Guérison au nom du Christ.", "extraExample": {"text": "C''est le premier converti.", "translation": "Puis toute sa famille."}, "options": ["César", "Christ", "Temple"], "id": "eg.l08.e13", "pool": "lesson", "lessonId": "eg.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e14', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.eglise_d_alexandrie']::text[], 'mcq', 'lesson', 'Quelle charge Marc confie-t-il à Anianus après avoir fondé l''Église ?', array['évêque']::text[], 'Marc ordonne Anianus évêque : c''est la première étape de la succession apostolique à Alexandrie.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.eglise_d_alexandrie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle charge Marc confie-t-il à Anianus après avoir fondé l''Église ?", "promptLanguage": "fr", "answer": "évêque", "acceptedAnswers": ["évêque"], "explanation": "Marc ordonne Anianus évêque : c''est la première étape de la succession apostolique à Alexandrie.", "tip": "Marc ordonne Anianus.", "extraExample": {"text": "Anianus lui succède.", "translation": "La chaîne commence."}, "options": ["moine", "gouverneur", "évêque"], "id": "eg.l08.e14", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e15', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie']::text[], 'mcq', 'lesson', 'Vers quelle année Marc est-il martyrisé ?', array['vers l''an 68']::text[], 'Marc est martyrisé vers l''an 68, à Alexandrie, sous le règne de Néron.', 2, '{"unitIds": ["eg.g08.marc_alexandrie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quelle année Marc est-il martyrisé ?", "promptLanguage": "fr", "answer": "vers l''an 68", "acceptedAnswers": ["vers l''an 68"], "explanation": "Marc est martyrisé vers l''an 68, à Alexandrie, sous le règne de Néron.", "tip": "68 = Marc martyr.", "extraExample": {"text": "Il arrive vers 49-50.", "translation": "Jean meurt vers 100."}, "options": ["vers l''an 49", "vers l''an 100", "vers l''an 68"], "id": "eg.l08.e15", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e16', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie']::text[], 'mcq', 'lesson', 'Comment Marc meurt-il à Alexandrie ?', array['traîné dans les rues']::text[], 'Une foule païenne l''attache et le traîne dans les rues d''Alexandrie. Il est jeté en prison, puis meurt : il est martyr.', 3, '{"unitIds": ["eg.g08.marc_alexandrie"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Comment Marc meurt-il à Alexandrie ?", "promptLanguage": "fr", "answer": "traîné dans les rues", "acceptedAnswers": ["traîné dans les rues"], "explanation": "Une foule païenne l''attache et le traîne dans les rues d''Alexandrie. Il est jeté en prison, puis meurt : il est martyr.", "tip": "Traîné, puis martyr.", "extraExample": {"text": "Étienne a été lapidé.", "translation": "Marc, lui, est traîné."}, "options": ["mort de vieillesse", "traîné dans les rues", "lapidé à Jérusalem"], "id": "eg.l08.e16", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e17', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.saint_marc','eg.v.eglise_d_alexandrie']::text[], 'mcq', 'lesson', 'Quel titre porte Marc dans l''Église d''Alexandrie ?', array['premier pape d''Alexandrie']::text[], 'Marc est le premier pape d''Alexandrie : le pape copte actuel est son successeur dans la longue chaîne.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.saint_marc", "eg.v.eglise_d_alexandrie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre porte Marc dans l''Église d''Alexandrie ?", "promptLanguage": "fr", "answer": "premier pape d''Alexandrie", "acceptedAnswers": ["premier pape d''Alexandrie"], "explanation": "Marc est le premier pape d''Alexandrie : le pape copte actuel est son successeur dans la longue chaîne.", "tip": "Marc = premier pape.", "extraExample": {"text": "Anianus est le deuxième.", "translation": "La chaîne se poursuit encore."}, "options": ["premier pape d''Alexandrie", "premier empereur chrétien", "premier moine"], "id": "eg.l08.e17", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e18', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.reliques_de_saint_marc']::text[], 'fill_blank', 'lesson', 'En 828, des marchands vénitiens emportent les reliques de saint Marc à ___.', array['Venise']::text[], 'Le corps du saint est emporté à Venise en 828, où l''on construit la basilique Saint-Marc.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.reliques_de_saint_marc"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En 828, des marchands vénitiens emportent les reliques de saint Marc à ___.", "promptLanguage": "fr", "answer": "Venise", "acceptedAnswers": ["Venise"], "explanation": "Le corps du saint est emporté à Venise en 828, où l''on construit la basilique Saint-Marc.", "tip": "828 = Venise.", "extraExample": {"text": "Une partie revient en 1968.", "translation": "Au Caire."}, "options": ["Venise", "Rome", "Constantinople"], "id": "eg.l08.e18", "pool": "lesson", "lessonId": "eg.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e19', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.cathedrale_saint_marc']::text[], 'fill_blank', 'lesson', 'En 1968, une partie des reliques revient au Caire, sous le pape ___ VI.', array['Cyrille']::text[], 'En 1968, sous le pape Cyrille VI, une partie des reliques est rendue à l''Église copte et la cathédrale Saint-Marc est consacrée.', 3, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.cathedrale_saint_marc"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "En 1968, une partie des reliques revient au Caire, sous le pape ___ VI.", "promptLanguage": "fr", "answer": "Cyrille", "acceptedAnswers": ["Cyrille"], "explanation": "En 1968, sous le pape Cyrille VI, une partie des reliques est rendue à l''Église copte et la cathédrale Saint-Marc est consacrée.", "tip": "1968 = Cyrille VI.", "extraExample": {"text": "La cathédrale est à l''Abbassiya.", "translation": "Au Caire."}, "options": ["Shenouda", "Tawadros", "Cyrille"], "id": "eg.l08.e19", "pool": "lesson", "lessonId": "eg.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e20', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.saint_marc','eg.v.anianus','eg.v.alexandrie','eg.v.septante']::text[], 'match', 'lesson', 'Qui est qui ?', '{}'::text[], 'Alexandre fonde la ville, la Septante prépare les esprits, Marc fonde l''Église, Anianus en est le premier fruit.', 2, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.saint_marc", "eg.v.anianus", "eg.v.alexandrie", "eg.v.septante"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui est qui ?", "promptLanguage": "fr", "answer": "Alexandre le Grand = fondateur de la ville d''Alexandrie ; Anianus = cordonnier, premier converti de Marc ; Saint Marc = fondateur de l''Église d''Alexandrie ; La Septante = Bible hébraïque traduite en grec", "acceptedAnswers": [], "explanation": "Alexandre fonde la ville, la Septante prépare les esprits, Marc fonde l''Église, Anianus en est le premier fruit.", "tip": "Ville, Bible, fondateur, converti.", "pairs": [{"left": "Alexandre le Grand", "right": "fondateur de la ville d''Alexandrie"}, {"left": "Anianus", "right": "cordonnier, premier converti de Marc"}, {"left": "Saint Marc", "right": "fondateur de l''Église d''Alexandrie"}, {"left": "La Septante", "right": "Bible hébraïque traduite en grec"}], "id": "eg.l08.e20", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e21', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.reliques_de_saint_marc']::text[], 'match', 'lesson', 'Les dates de saint Marc', '{}'::text[], 'Quatre dates à retenir : 331 av. J.-C., 68, 828 et 1968.', 3, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.reliques_de_saint_marc"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les dates de saint Marc", "promptLanguage": "fr", "answer": "331 av. J.-C. = fondation d''Alexandrie ; vers 68 = martyre de saint Marc ; 828 = reliques emportées à Venise ; 1968 = retour d''une partie des reliques au Caire", "acceptedAnswers": [], "explanation": "Quatre dates à retenir : 331 av. J.-C., 68, 828 et 1968.", "tip": "Fondation, martyre, départ, retour.", "pairs": [{"left": "331 av. J.-C.", "right": "fondation d''Alexandrie"}, {"left": "vers 68", "right": "martyre de saint Marc"}, {"left": "828", "right": "reliques emportées à Venise"}, {"left": "1968", "right": "retour d''une partie des reliques au Caire"}], "id": "eg.l08.e21", "pool": "lesson", "lessonId": "eg.l08", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e22', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie']::text[], 'reorder', 'lesson', 'Phrase-repère : la fondation.', array['Saint Marc fonde l''Église d''Alexandrie et ordonne Anianus évêque']::text[], 'Marc fonde l''Église d''Alexandrie et ordonne Anianus évêque : c''est le début de la succession apostolique d''Égypte.', 2, '{"unitIds": ["eg.g08.marc_alexandrie"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la fondation.", "promptLanguage": "fr", "answer": "Saint Marc fonde l''Église d''Alexandrie et ordonne Anianus évêque", "acceptedAnswers": ["Saint Marc fonde l''Église d''Alexandrie et ordonne Anianus évêque"], "explanation": "Marc fonde l''Église d''Alexandrie et ordonne Anianus évêque : c''est le début de la succession apostolique d''Égypte.", "tip": "Marc → Anianus → Église d''Alexandrie.", "extraExample": {"text": "Le pape copte actuel est son successeur.", "translation": "La chaîne est ininterrompue."}, "tokens": ["l''Église", "d''Alexandrie", "et", "ordonne", "Anianus", "évêque", "Saint", "Marc", "fonde"], "id": "eg.l08.e22", "pool": "lesson", "lessonId": "eg.l08", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e23', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.copte']::text[], 'free_answer', 'lesson', 'Quel mot, du grec Aigyptios, désigne l''Église d''Égypte et veut dire « égyptien » ?', array['copte','coptes','les coptes']::text[], 'Copte vient du grec Aigyptios, « égyptien ». L''Église copte est l''Église d''Égypte.', 1, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.copte"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel mot, du grec Aigyptios, désigne l''Église d''Égypte et veut dire « égyptien » ?", "promptLanguage": "fr", "answer": "copte", "acceptedAnswers": ["copte", "coptes", "les coptes"], "explanation": "Copte vient du grec Aigyptios, « égyptien ». L''Église copte est l''Église d''Égypte.", "tip": "Copte = égyptien.", "extraExample": {"text": "En arabe, qibt.", "translation": "La langue copte aussi."}, "hint": "Il commence par « c ».", "id": "eg.l08.e23", "pool": "lesson", "lessonId": "eg.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l08.e24', 'eg', 'eg.l08', 'eg.g08.marc_alexandrie', array['eg.g08.marc_alexandrie','eg.v.saint_marc']::text[], 'free_answer', 'lesson', 'Dans quelle ville Marc est-il martyrisé vers 68 ?', array['Alexandrie','à Alexandrie']::text[], 'Marc est martyrisé à Alexandrie, où il avait fondé l''Église.', 1, '{"unitIds": ["eg.g08.marc_alexandrie", "eg.v.saint_marc"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Dans quelle ville Marc est-il martyrisé vers 68 ?", "promptLanguage": "fr", "answer": "Alexandrie", "acceptedAnswers": ["Alexandrie", "à Alexandrie"], "explanation": "Marc est martyrisé à Alexandrie, où il avait fondé l''Église.", "tip": "Marc = Alexandrie.", "extraExample": {"text": "Il arrive vers 49-50.", "translation": "Il y reste jusqu''à son martyre."}, "hint": "Elle porte le nom d''un roi macédonien.", "id": "eg.l08.e24", "pool": "lesson", "lessonId": "eg.l08", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e01', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'match', 'lesson', 'Quatre mots-clés de la leçon', '{}'::text[], 'Hérésie, succession, tradition, Écritures : les quatre notions qui expliquent comment l''Église garde sa foi.', 1, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quatre mots-clés de la leçon", "promptLanguage": "fr", "answer": "Hérésie = enseignement qui s''écarte de la foi transmise par les apôtres ; Succession apostolique = suite ininterrompue d''évêques depuis les apôtres ; Sainte tradition = le dépôt de la foi confié par les apôtres ; Les Écritures = premier appui de l''Église pour garder la vérité", "acceptedAnswers": [], "explanation": "Hérésie, succession, tradition, Écritures : les quatre notions qui expliquent comment l''Église garde sa foi.", "tip": "Une hérésie déforme ; les trois appuis protègent.", "pairs": [{"left": "Hérésie", "right": "enseignement qui s''écarte de la foi transmise par les apôtres"}, {"left": "Succession apostolique", "right": "suite ininterrompue d''évêques depuis les apôtres"}, {"left": "Sainte tradition", "right": "le dépôt de la foi confié par les apôtres"}, {"left": "Les Écritures", "right": "premier appui de l''Église pour garder la vérité"}], "id": "eg.l09.e01", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e02', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'mcq', 'lesson', 'Que s''est-il passé au début du IIe siècle ?', array['La génération des apôtres s''est éteinte']::text[], 'Plus aucun témoin direct du Christ n''est en vie : la foi doit se transmettre autrement.', 1, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que s''est-il passé au début du IIe siècle ?", "promptLanguage": "fr", "answer": "La génération des apôtres s''est éteinte", "acceptedAnswers": ["La génération des apôtres s''est éteinte"], "explanation": "Plus aucun témoin direct du Christ n''est en vie : la foi doit se transmettre autrement.", "tip": "Début du IIe siècle = plus de témoins directs.", "extraExample": {"text": "Jean, le dernier apôtre, meurt vers la fin du Ier siècle.", "translation": "Après lui, plus personne n''a connu Jésus en personne."}, "options": ["La dernière Écriture a été écrite", "La génération des apôtres s''est éteinte", "L''Église a cessé de grandir", "Les évêques ont disparu"], "id": "eg.l09.e02", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e03', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.doctrine']::text[], 'mcq', 'lesson', 'Pourquoi les interprétations du message chrétien se multiplient-elles ?', array['L''Église s''étend dans tout l''Empire romain']::text[], 'En grandissant, l''Église rencontre des cultures et des philosophies très différentes, qui interprètent la foi chacune à sa manière.', 1, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.doctrine"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi les interprétations du message chrétien se multiplient-elles ?", "promptLanguage": "fr", "answer": "L''Église s''étend dans tout l''Empire romain", "acceptedAnswers": ["L''Église s''étend dans tout l''Empire romain"], "explanation": "En grandissant, l''Église rencontre des cultures et des philosophies très différentes, qui interprètent la foi chacune à sa manière.", "tip": "Plus on grandit, plus les idées se mélangent.", "extraExample": {"text": "Un Grec nourri de philosophie ne comprend pas la foi comme un Juif de Galilée.", "translation": "Chaque culture pose ses propres questions."}, "options": ["Les évêques refusent d''enseigner", "L''Église est interdite de réunion", "L''Église s''étend dans tout l''Empire romain", "Les Évangiles ont disparu"], "id": "eg.l09.e03", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e04', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.heresie']::text[], 'mcq', 'lesson', 'Que veut dire le grec hairesis, d''où vient le mot « hérésie » ?', array['choix']::text[], 'L''hérétique choisit dans la foi ce qui lui plaît et laisse le reste, au lieu de recevoir l''ensemble transmis par les apôtres.', 2, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.heresie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le grec hairesis, d''où vient le mot « hérésie » ?", "promptLanguage": "fr", "answer": "choix", "acceptedAnswers": ["choix"], "explanation": "L''hérétique choisit dans la foi ce qui lui plaît et laisse le reste, au lieu de recevoir l''ensemble transmis par les apôtres.", "tip": "Hérésie = choix : on trie la foi.", "extraExample": {"text": "Dans la boutique de la foi, l''hérétique prend certains rayons seulement.", "translation": "Il garde une partie et rejette le reste."}, "options": ["secret", "sagesse", "loi", "choix"], "id": "eg.l09.e04", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e05', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'mcq', 'lesson', 'Laquelle de ces doctrines est une hérésie du IIe siècle ?', array['le montanisme']::text[], 'Les quatre hérésies du IIe siècle sont le gnosticisme, le docétisme, le marcionisme et le montanisme. Les trois autres sont des siècles suivants.', 2, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Laquelle de ces doctrines est une hérésie du IIe siècle ?", "promptLanguage": "fr", "answer": "le montanisme", "acceptedAnswers": ["le montanisme"], "explanation": "Les quatre hérésies du IIe siècle sont le gnosticisme, le docétisme, le marcionisme et le montanisme. Les trois autres sont des siècles suivants.", "tip": "IIe siècle = G, D, Ma, Mo.", "extraExample": {"text": "L''arianisme apparaît au IVe siècle.", "translation": "Il sera condamné à Nicée en 325."}, "options": ["le montanisme", "l''arianisme", "le nestorianisme", "l''eutychianisme"], "errorPatterns": [{"equals": "l''arianisme", "category": "word_confusion", "feedback": "L''arianisme date du IVe siècle (Arius, condamné à Nicée)."}, {"equals": "le nestorianisme", "category": "word_confusion", "feedback": "Le nestorianisme date du Ve siècle (Nestorius, Éphèse 431)."}], "id": "eg.l09.e05", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e06', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.succession_apostolique']::text[], 'mcq', 'lesson', 'Qu''est-ce que la succession apostolique ?', array['une suite ininterrompue d''évêques depuis les apôtres']::text[], 'Les apôtres ont établi des évêques qui en ont établi d''autres : la chaîne remonte jusqu''à la source.', 1, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.succession_apostolique"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce que la succession apostolique ?", "promptLanguage": "fr", "answer": "une suite ininterrompue d''évêques depuis les apôtres", "acceptedAnswers": ["une suite ininterrompue d''évêques depuis les apôtres"], "explanation": "Les apôtres ont établi des évêques qui en ont établi d''autres : la chaîne remonte jusqu''à la source.", "tip": "Succession = chaîne d''évêques.", "extraExample": {"text": "Chaque évêque peut remonter la liste de ses prédécesseurs jusqu''à un apôtre.", "translation": "C''est une généalogie de la foi."}, "options": ["la liste des livres du Nouveau Testament", "une suite ininterrompue d''évêques depuis les apôtres", "la suite des empereurs romains", "un concile réuni par les apôtres"], "id": "eg.l09.e06", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e07', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.succession_apostolique']::text[], 'mcq', 'lesson', 'Pourquoi la succession apostolique protège-t-elle la foi ?', array['la foi enseignée est celle des apôtres']::text[], 'Si la chaîne des évêques est ininterrompue, ce qu''ils enseignent a été reçu des apôtres sans rupture.', 2, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.succession_apostolique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi la succession apostolique protège-t-elle la foi ?", "promptLanguage": "fr", "answer": "la foi enseignée est celle des apôtres", "acceptedAnswers": ["la foi enseignée est celle des apôtres"], "explanation": "Si la chaîne des évêques est ininterrompue, ce qu''ils enseignent a été reçu des apôtres sans rupture.", "tip": "Chaîne ininterrompue = foi garantie.", "extraExample": {"text": "Comme un témoin passé de main en main, la foi n''est pas tombée en route.", "translation": "Chaque maillon tient le précédent."}, "options": ["l''absence de persécution", "l''élection des évêques par le peuple", "la foi enseignée est celle des apôtres", "la richesse de l''Église"], "id": "eg.l09.e07", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e08', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.ecritures']::text[], 'mcq', 'lesson', 'Pourquoi les Écritures seules ne suffisent-elles pas à trancher ?', array['chacun peut citer un verset à sa façon']::text[], 'Les hérétiques citent eux aussi l''Écriture. Il faut donc des gardiens vivants de l''enseignement reçu des apôtres : les évêques.', 2, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.ecritures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi les Écritures seules ne suffisent-elles pas à trancher ?", "promptLanguage": "fr", "answer": "chacun peut citer un verset à sa façon", "acceptedAnswers": ["chacun peut citer un verset à sa façon"], "explanation": "Les hérétiques citent eux aussi l''Écriture. Il faut donc des gardiens vivants de l''enseignement reçu des apôtres : les évêques.", "tip": "Un verset sorti de son contexte peut dire n''importe quoi.", "extraExample": {"text": "Deux personnes lisent le même verset et en tirent deux doctrines opposées.", "translation": "Il faut un arbitre : la tradition et les évêques."}, "options": ["elles ne sont pas encore écrites", "elles sont trop courtes", "personne ne sait les lire", "chacun peut citer un verset à sa façon"], "id": "eg.l09.e08", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e09', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.depot_de_la_foi']::text[], 'mcq', 'lesson', 'Comment appelle-t-on le trésor de la foi confié par les apôtres à l''Église ?', array['le dépôt de la foi']::text[], 'On parle de « dépôt » comme d''un trésor remis à un gardien : l''Église doit le garder intact, pas le modifier.', 2, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.depot_de_la_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on le trésor de la foi confié par les apôtres à l''Église ?", "promptLanguage": "fr", "answer": "le dépôt de la foi", "acceptedAnswers": ["le dépôt de la foi"], "explanation": "On parle de « dépôt » comme d''un trésor remis à un gardien : l''Église doit le garder intact, pas le modifier.", "tip": "Dépôt = on garde, on n''invente pas.", "extraExample": {"text": "Un gardien de musée ne repeint pas les tableaux qu''on lui confie.", "translation": "L''Église garde la foi telle qu''elle l''a reçue."}, "options": ["le dépôt de la foi", "le Credo", "le concile", "le sacrement"], "id": "eg.l09.e09", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e10', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'mcq', 'lesson', 'Quelles sont les deux grandes familles d''écrivains du IIe siècle ?', array['les Pères apostoliques et les apologistes']::text[], 'Les Pères apostoliques enseignent l''Église de l''intérieur ; les apologistes défendent la foi devant le monde païen.', 3, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles sont les deux grandes familles d''écrivains du IIe siècle ?", "promptLanguage": "fr", "answer": "les Pères apostoliques et les apologistes", "acceptedAnswers": ["les Pères apostoliques et les apologistes"], "explanation": "Les Pères apostoliques enseignent l''Église de l''intérieur ; les apologistes défendent la foi devant le monde païen.", "tip": "Apostoliques = dedans ; apologistes = dehors.", "extraExample": {"text": "Clément de Rome est un Père apostolique.", "translation": "Justin Martyr est un apologiste."}, "options": ["les prophètes et les rois", "les Pères apostoliques et les apologistes", "les scribes et les pharisiens", "les papes et les empereurs"], "id": "eg.l09.e10", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e11', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'mcq', 'lesson', 'Qui défendra la foi devant le monde païen ?', array['les apologistes']::text[], 'Le mot apologiste vient du grec apologia, « défense » : ils répondent aux accusations des païens.', 3, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui défendra la foi devant le monde païen ?", "promptLanguage": "fr", "answer": "les apologistes", "acceptedAnswers": ["les apologistes"], "explanation": "Le mot apologiste vient du grec apologia, « défense » : ils répondent aux accusations des païens.", "tip": "Apologiste = avocat de la foi.", "extraExample": {"text": "Justin écrit à l''empereur pour défendre les chrétiens.", "translation": "C''est une défense devant les gens de l''extérieur."}, "options": ["les Pères apostoliques", "les montanistes", "les apologistes", "les marcionites"], "id": "eg.l09.e11", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e12', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'fill_blank', 'lesson', 'Au début du IIe siècle, il ne reste plus aucun ___ direct du Christ.', array['témoin']::text[], 'Les apôtres sont morts : plus personne n''a vu et entendu Jésus en personne.', 1, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Au début du IIe siècle, il ne reste plus aucun ___ direct du Christ.", "promptLanguage": "fr", "answer": "témoin", "acceptedAnswers": ["témoin"], "explanation": "Les apôtres sont morts : plus personne n''a vu et entendu Jésus en personne.", "tip": "Témoin = quelqu''un qui a vu.", "extraExample": {"text": "Un témoin direct a vu les faits de ses propres yeux.", "translation": "À la fin du Ier siècle, il n''en reste plus."}, "options": ["témoin", "évêque", "empereur", "philosophe"], "id": "eg.l09.e12", "pool": "lesson", "lessonId": "eg.l09", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e13', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.succession_apostolique']::text[], 'fill_blank', 'lesson', 'La suite ininterrompue d''évêques depuis les apôtres s''appelle la succession ___.', array['apostolique']::text[], 'Elle est dite apostolique parce qu''elle remonte aux apôtres.', 2, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.succession_apostolique"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "La suite ininterrompue d''évêques depuis les apôtres s''appelle la succession ___.", "promptLanguage": "fr", "answer": "apostolique", "acceptedAnswers": ["apostolique"], "explanation": "Elle est dite apostolique parce qu''elle remonte aux apôtres.", "tip": "Apostolique = qui remonte aux apôtres.", "extraExample": {"text": "Un siège apostolique a un apôtre pour premier évêque.", "translation": "On le verra dans la leçon suivante."}, "options": ["impériale", "apostolique", "doctrinale", "païenne"], "id": "eg.l09.e13", "pool": "lesson", "lessonId": "eg.l09", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e14', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.eveque']::text[], 'fill_blank', 'lesson', 'L''Église s''appuie sur les Écritures, la tradition et les ___ successeurs des apôtres.', array['évêques']::text[], 'Les évêques sont les gardiens vivants de l''enseignement reçu des apôtres.', 2, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.eveque"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "L''Église s''appuie sur les Écritures, la tradition et les ___ successeurs des apôtres.", "promptLanguage": "fr", "answer": "évêques", "acceptedAnswers": ["évêques"], "explanation": "Les évêques sont les gardiens vivants de l''enseignement reçu des apôtres.", "tip": "Livre, voix, gardiens.", "extraExample": {"text": "Un évêque ordonne les prêtres et garde l''unité de son Église.", "translation": "Il est le maillon de la chaîne."}, "options": ["empereurs", "philosophes", "évêques", "scribes"], "id": "eg.l09.e14", "pool": "lesson", "lessonId": "eg.l09", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
