insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e16', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.succession_apostolique']::text[], 'reorder', 'lesson', 'Reconstitue la phrase-repère (eg.l09).', array['La succession apostolique garantit la foi des apôtres']::text[], 'La chaîne ininterrompue des évêques assure que la foi enseignée est celle reçue des apôtres.', 2, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.succession_apostolique"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Reconstitue la phrase-repère (eg.l09).", "promptLanguage": "fr", "answer": "La succession apostolique garantit la foi des apôtres", "acceptedAnswers": ["La succession apostolique garantit la foi des apôtres"], "explanation": "La chaîne ininterrompue des évêques assure que la foi enseignée est celle reçue des apôtres.", "tip": "Chaîne d''évêques = foi des apôtres.", "extraExample": {"text": "Chaque évêque transmet ce qu''il a reçu.", "translation": "La chaîne remonte jusqu''à la source."}, "tokens": ["apôtres", "apostolique", "des", "foi", "garantit", "succession", "La", "la"], "id": "eg.l09.e16", "pool": "lesson", "lessonId": "eg.l09", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e17', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'match', 'lesson', 'Les trois appuis de la foi', '{}'::text[], 'Le Livre, la voix, les gardiens : trois appuis qui se complètent.', 2, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les trois appuis de la foi", "promptLanguage": "fr", "answer": "Les Écritures = le livre lu dans les assemblées ; La tradition = ce que les apôtres ont transmis de vive voix et par la vie de l''Église ; Les évêques = successeurs des apôtres, gardiens de l''enseignement", "acceptedAnswers": [], "explanation": "Le Livre, la voix, les gardiens : trois appuis qui se complètent.", "tip": "Livre, voix, gardiens.", "pairs": [{"left": "Les Écritures", "right": "le livre lu dans les assemblées"}, {"left": "La tradition", "right": "ce que les apôtres ont transmis de vive voix et par la vie de l''Église"}, {"left": "Les évêques", "right": "successeurs des apôtres, gardiens de l''enseignement"}], "id": "eg.l09.e17", "pool": "lesson", "lessonId": "eg.l09", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e18', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.heresie']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on un enseignement qui s''écarte de la foi transmise par les apôtres ?', array['une hérésie','hérésie','l''hérésie','heresie','une heresie']::text[], 'Une hérésie déforme la foi reçue des apôtres.', 1, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.heresie"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on un enseignement qui s''écarte de la foi transmise par les apôtres ?", "promptLanguage": "fr", "answer": "une hérésie", "acceptedAnswers": ["une hérésie", "hérésie", "l''hérésie", "heresie", "une heresie"], "explanation": "Une hérésie déforme la foi reçue des apôtres.", "tip": "Hérésie = choix dans la foi.", "extraExample": {"text": "Le gnosticisme est une hérésie.", "translation": "Il prétend sauver par une connaissance secrète."}, "id": "eg.l09.e18", "pool": "lesson", "lessonId": "eg.l09", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e19', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres']::text[], 'free_answer', 'lesson', 'Combien d''hérésies principales dominent le IIe siècle ?', array['quatre','4']::text[], 'Gnosticisme, docétisme, marcionisme, montanisme.', 2, '{"unitIds": ["eg.g09.releve_des_apotres"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Combien d''hérésies principales dominent le IIe siècle ?", "promptLanguage": "fr", "answer": "quatre", "acceptedAnswers": ["quatre", "4"], "explanation": "Gnosticisme, docétisme, marcionisme, montanisme.", "tip": "Quatre hérésies, quatre leçons.", "extraExample": {"text": "Les hérésies du IIe siècle seront suivies par celles des siècles suivants.", "translation": "Chaque siècle a ses défis."}, "id": "eg.l09.e19", "pool": "lesson", "lessonId": "eg.l09", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l09.e20', 'eg', 'eg.l09', 'eg.g09.releve_des_apotres', array['eg.g09.releve_des_apotres','eg.v.sainte_tradition']::text[], 'free_answer', 'lesson', 'Quel mot désigne ce que les apôtres ont transmis de vive voix, par la prière et la vie de l''Église ?', array['la sainte tradition','la tradition','tradition','sainte tradition','la tradition apostolique']::text[], 'La tradition est l''enseignement vivant transmis avec les Écritures.', 3, '{"unitIds": ["eg.g09.releve_des_apotres", "eg.v.sainte_tradition"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel mot désigne ce que les apôtres ont transmis de vive voix, par la prière et la vie de l''Église ?", "promptLanguage": "fr", "answer": "la sainte tradition", "acceptedAnswers": ["la sainte tradition", "la tradition", "tradition", "sainte tradition", "la tradition apostolique"], "explanation": "La tradition est l''enseignement vivant transmis avec les Écritures.", "tip": "Tradition = transmission.", "extraExample": {"text": "La façon de célébrer la liturgie relève de la tradition.", "translation": "Elle ne s''invente pas."}, "id": "eg.l09.e20", "pool": "lesson", "lessonId": "eg.l09", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e01', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques']::text[], 'match', 'lesson', 'Chaque siège et son fondateur', '{}'::text[], 'Chaque siège apostolique remonte à un apôtre : c''est ce qui fait son autorité.', 1, '{"unitIds": ["eg.g10.sieges_apostoliques"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque siège et son fondateur", "promptLanguage": "fr", "answer": "Rome = Pierre et Paul ; Alexandrie = saint Marc ; Antioche = Pierre ; Jérusalem = saint Jacques", "acceptedAnswers": [], "explanation": "Chaque siège apostolique remonte à un apôtre : c''est ce qui fait son autorité.", "tip": "Un siège, un fondateur.", "pairs": [{"left": "Rome", "right": "Pierre et Paul"}, {"left": "Alexandrie", "right": "saint Marc"}, {"left": "Antioche", "right": "Pierre"}, {"left": "Jérusalem", "right": "saint Jacques"}], "id": "eg.l10.e01", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e02', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.siege_apostolique']::text[], 'mcq', 'lesson', 'Un siège apostolique, c''est quoi exactement ?', array['un siège dont le premier évêque est un apôtre']::text[], 'Le mot siège désigne la « chaise » de l''évêque dans sa ville. Apostolique signifie que la chaîne remonte à un apôtre.', 1, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.siege_apostolique"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Un siège apostolique, c''est quoi exactement ?", "promptLanguage": "fr", "answer": "un siège dont le premier évêque est un apôtre", "acceptedAnswers": ["un siège dont le premier évêque est un apôtre"], "explanation": "Le mot siège désigne la « chaise » de l''évêque dans sa ville. Apostolique signifie que la chaîne remonte à un apôtre.", "tip": "Apostolique = qui remonte à un apôtre.", "extraExample": {"text": "Si ton évêque peut remonter la liste de ses prédécesseurs jusqu''à un apôtre, son siège est apostolique.", "translation": "Seules quelques villes le peuvent."}, "options": ["un siège fondé par un empereur", "un siège dont le premier évêque est un apôtre", "une ville où les apôtres sont nés", "un tribunal romain"], "id": "eg.l10.e02", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e03', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques']::text[], 'mcq', 'lesson', 'Pourquoi l''autorité des Églises apostoliques est-elle plus grande en matière de foi ?', array['la relève y a été assurée depuis la source']::text[], 'Ces Églises ont reçu la foi directement d''un apôtre et l''ont transmise sans rupture : on est proche de la source.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''autorité des Églises apostoliques est-elle plus grande en matière de foi ?", "promptLanguage": "fr", "answer": "la relève y a été assurée depuis la source", "acceptedAnswers": ["la relève y a été assurée depuis la source"], "explanation": "Ces Églises ont reçu la foi directement d''un apôtre et l''ont transmise sans rupture : on est proche de la source.", "tip": "Plus on est près de la source, plus l''eau est pure.", "extraExample": {"text": "Un ruisseau près de sa source est plus limpide qu''à l''embouchure.", "translation": "Même idée pour la foi."}, "options": ["elles sont plus riches", "elles sont plus grandes", "la relève y a été assurée depuis la source", "elles sont plus anciennes que les Évangiles"], "id": "eg.l10.e03", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e04', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques']::text[], 'mcq', 'lesson', 'Quels sont les quatre sièges apostoliques ?', array['Rome, Alexandrie, Antioche et Jérusalem']::text[], 'Chacune des quatre villes a été fondée par un ou plusieurs apôtres.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quels sont les quatre sièges apostoliques ?", "promptLanguage": "fr", "answer": "Rome, Alexandrie, Antioche et Jérusalem", "acceptedAnswers": ["Rome, Alexandrie, Antioche et Jérusalem"], "explanation": "Chacune des quatre villes a été fondée par un ou plusieurs apôtres.", "tip": "R-A-A-J.", "extraExample": {"text": "Constantinople n''existe pas encore comme grande Église au IIe siècle.", "translation": "Elle sera fondée comme capitale au IVe siècle."}, "options": ["Rome, Alexandrie, Constantinople et Carthage", "Rome, Athènes, Antioche et Éphèse", "Alexandrie, Corinthe, Smyrne et Jérusalem", "Rome, Alexandrie, Antioche et Jérusalem"], "id": "eg.l10.e04", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e05', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.saint_marc']::text[], 'mcq', 'lesson', 'Qui a fondé l''Église d''Alexandrie ?', array['saint Marc']::text[], 'Marc l''évangéliste prêche en Égypte au Ier siècle et devient le premier évêque d''Alexandrie.', 1, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.saint_marc"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui a fondé l''Église d''Alexandrie ?", "promptLanguage": "fr", "answer": "saint Marc", "acceptedAnswers": ["saint Marc"], "explanation": "Marc l''évangéliste prêche en Égypte au Ier siècle et devient le premier évêque d''Alexandrie.", "tip": "Marc = Alexandrie.", "extraExample": {"text": "L''Évangile selon saint Marc est lié à l''Église copte.", "translation": "Marc l''a écrit avant de venir en Égypte."}, "options": ["saint Marc", "saint Pierre", "saint Paul", "saint Jean"], "errorPatterns": [{"equals": "saint Pierre", "category": "word_confusion", "feedback": "Pierre est lié à Rome et à Antioche, pas à Alexandrie."}], "id": "eg.l10.e05", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e06', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.siege_d_antioche']::text[], 'mcq', 'lesson', 'Où les disciples ont-ils été appelés « chrétiens » pour la première fois ?', array['à Antioche']::text[], 'Le livre des Actes (11, 26) le raconte : à Antioche, les disciples sont appelés chrétiens.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.siege_d_antioche"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où les disciples ont-ils été appelés « chrétiens » pour la première fois ?", "promptLanguage": "fr", "answer": "à Antioche", "acceptedAnswers": ["à Antioche"], "explanation": "Le livre des Actes (11, 26) le raconte : à Antioche, les disciples sont appelés chrétiens.", "tip": "Antioche = premiers « chrétiens ».", "extraExample": {"text": "Le mot « chrétien » vient de « Christ ».", "translation": "Il est d''abord un surnom donné aux disciples de Jésus."}, "options": ["à Rome", "à Antioche", "à Alexandrie", "à Jérusalem"], "id": "eg.l10.e06", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e07', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.jacques_de_jerusalem','eg.v.siege_de_jerusalem']::text[], 'mcq', 'lesson', 'Qui est le premier évêque de Jérusalem ?', array['saint Jacques']::text[], 'Jacques, le « frère du Seigneur », dirige la première Église et préside l''assemblée des Actes 15.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.jacques_de_jerusalem", "eg.v.siege_de_jerusalem"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le premier évêque de Jérusalem ?", "promptLanguage": "fr", "answer": "saint Jacques", "acceptedAnswers": ["saint Jacques"], "explanation": "Jacques, le « frère du Seigneur », dirige la première Église et préside l''assemblée des Actes 15.", "tip": "Jérusalem = Jacques.", "extraExample": {"text": "Jacques parle en dernier à l''assemblée des apôtres.", "translation": "Sa parole tranche."}, "options": ["saint Marc", "saint Polycarpe", "saint Jacques", "saint Ignace"], "id": "eg.l10.e07", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e08', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.siege_de_rome']::text[], 'mcq', 'lesson', 'Qui sont les fondateurs du siège de Rome ?', array['Pierre et Paul']::text[], 'Pierre et Paul sont tous deux morts martyrs à Rome au temps de Néron, d''où le rôle de ces deux apôtres pour cette Église.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.siege_de_rome"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les fondateurs du siège de Rome ?", "promptLanguage": "fr", "answer": "Pierre et Paul", "acceptedAnswers": ["Pierre et Paul"], "explanation": "Pierre et Paul sont tous deux morts martyrs à Rome au temps de Néron, d''où le rôle de ces deux apôtres pour cette Église.", "tip": "Rome = les deux piliers.", "extraExample": {"text": "On fête Pierre et Paul ensemble.", "translation": "Ils sont tenus pour les deux colonnes de l''Église romaine."}, "options": ["Marc et Jacques", "Jean et André", "Ignace et Clément", "Pierre et Paul"], "id": "eg.l10.e08", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e09', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.pape_d_alexandrie']::text[], 'mcq', 'lesson', 'Comment appelle-t-on le chef de l''Église d''Alexandrie ?', array['le pape d''Alexandrie']::text[], 'Chez les Coptes, l''évêque d''Alexandrie porte le titre de pape, successeur de saint Marc.', 1, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.pape_d_alexandrie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on le chef de l''Église d''Alexandrie ?", "promptLanguage": "fr", "answer": "le pape d''Alexandrie", "acceptedAnswers": ["le pape d''Alexandrie"], "explanation": "Chez les Coptes, l''évêque d''Alexandrie porte le titre de pape, successeur de saint Marc.", "tip": "Pape = père.", "extraExample": {"text": "Saint Démétrios est le XIIe pape d''Alexandrie.", "translation": "Il est élu en 189."}, "options": ["le pape d''Alexandrie", "le patriarche de Constantinople", "l''évêque de Rome", "le grand prêtre"], "id": "eg.l10.e09", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e10', 'eg', 'eg.l10', 'eg.v.succession_apostolique', array['eg.v.succession_apostolique']::text[], 'mcq', 'lesson', 'Comment s''appelle une suite ininterrompue d''évêques depuis les apôtres ?', array['la succession apostolique']::text[], 'C''est la chaîne qui garantit la continuité de la foi : on l''a vue dans la leçon précédente.', 2, '{"unitIds": ["eg.v.succession_apostolique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''appelle une suite ininterrompue d''évêques depuis les apôtres ?", "promptLanguage": "fr", "answer": "la succession apostolique", "acceptedAnswers": ["la succession apostolique"], "explanation": "C''est la chaîne qui garantit la continuité de la foi : on l''a vue dans la leçon précédente.", "tip": "Succession = chaîne.", "extraExample": {"text": "Chaque siège apostolique a sa propre liste d''évêques.", "translation": "Chacune remonte à un apôtre."}, "options": ["la tradition orale", "la succession apostolique", "le dépôt de la foi", "le canon"], "id": "eg.l10.e10", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e11', 'eg', 'eg.l10', 'eg.v.depot_de_la_foi', array['eg.v.depot_de_la_foi']::text[], 'mcq', 'lesson', 'Parmi ces trois éléments, lequel est le trésor de la foi confié par les apôtres ?', array['le dépôt de la foi']::text[], 'Les sièges apostoliques sont des gardiens de ce dépôt : ils doivent le transmettre sans l''altérer.', 2, '{"unitIds": ["eg.v.depot_de_la_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Parmi ces trois éléments, lequel est le trésor de la foi confié par les apôtres ?", "promptLanguage": "fr", "answer": "le dépôt de la foi", "acceptedAnswers": ["le dépôt de la foi"], "explanation": "Les sièges apostoliques sont des gardiens de ce dépôt : ils doivent le transmettre sans l''altérer.", "tip": "Dépôt = trésor à garder.", "extraExample": {"text": "Un évêque est gardien du dépôt de la foi.", "translation": "Il ne le modifie pas."}, "options": ["le siège de Rome", "le pape d''Alexandrie", "le dépôt de la foi", "la succession des empereurs"], "id": "eg.l10.e11", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e12', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.siege_d_alexandrie']::text[], 'fill_blank', 'lesson', 'Le siège de saint Marc est le siège d''___.', array['Alexandrie']::text[], 'Notre Église copte est l''Église d''Alexandrie, fondée par saint Marc.', 1, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.siege_d_alexandrie"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le siège de saint Marc est le siège d''___.", "promptLanguage": "fr", "answer": "Alexandrie", "acceptedAnswers": ["Alexandrie"], "explanation": "Notre Église copte est l''Église d''Alexandrie, fondée par saint Marc.", "tip": "Marc = Alexandrie.", "extraExample": {"text": "Le pape d''Alexandrie est le successeur de saint Marc.", "translation": "Il siège sur le trône de saint Marc."}, "options": ["Alexandrie", "Antioche", "Rome", "Jérusalem"], "id": "eg.l10.e12", "pool": "lesson", "lessonId": "eg.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e13', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.jacques_de_jerusalem']::text[], 'fill_blank', 'lesson', 'À Jérusalem, le premier évêque est saint ___.', array['Jacques']::text[], 'Jacques, frère du Seigneur, dirige l''Église-mère.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.jacques_de_jerusalem"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "À Jérusalem, le premier évêque est saint ___.", "promptLanguage": "fr", "answer": "Jacques", "acceptedAnswers": ["Jacques"], "explanation": "Jacques, frère du Seigneur, dirige l''Église-mère.", "tip": "Jérusalem = Jacques.", "extraExample": {"text": "Jacques écrit une lettre qui porte son nom.", "translation": "Elle est dans le Nouveau Testament."}, "options": ["Pierre", "Jacques", "Marc", "Paul"], "id": "eg.l10.e13", "pool": "lesson", "lessonId": "eg.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e14', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.siege_d_antioche']::text[], 'fill_blank', 'lesson', 'Le siège d''Antioche est rattaché à l''apôtre ___.', array['Pierre']::text[], 'Pierre est lié à Antioche et à Rome.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.siege_d_antioche"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le siège d''Antioche est rattaché à l''apôtre ___.", "promptLanguage": "fr", "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Pierre est lié à Antioche et à Rome.", "tip": "Antioche = Pierre.", "extraExample": {"text": "Pierre est aussi lié à Rome.", "translation": "Il y meurt martyr."}, "options": ["Marc", "Jacques", "Pierre", "André"], "id": "eg.l10.e14", "pool": "lesson", "lessonId": "eg.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e15', 'eg', 'eg.l10', 'eg.v.heresie', array['eg.v.heresie']::text[], 'fill_blank', 'lesson', 'Un enseignement qui s''écarte de la foi des apôtres est une ___.', array['hérésie']::text[], 'Rappel de la leçon précédente : l''hérésie déforme la foi reçue des apôtres.', 2, '{"unitIds": ["eg.v.heresie"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Un enseignement qui s''écarte de la foi des apôtres est une ___.", "promptLanguage": "fr", "answer": "hérésie", "acceptedAnswers": ["hérésie"], "explanation": "Rappel de la leçon précédente : l''hérésie déforme la foi reçue des apôtres.", "tip": "Hérésie = choix.", "extraExample": {"text": "Le gnosticisme, le docétisme, le marcionisme, le montanisme sont des hérésies.", "translation": "Ce sont celles du IIe siècle."}, "options": ["tradition", "liturgie", "succession", "hérésie"], "id": "eg.l10.e15", "pool": "lesson", "lessonId": "eg.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e16', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.saint_marc']::text[], 'reorder', 'lesson', 'Reconstitue la phrase-repère (eg.l10).', array['Saint Marc fonde l''Église d''Alexandrie']::text[], 'Notre Église remonte à saint Marc, qui l''a fondée au Ier siècle.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.saint_marc"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Reconstitue la phrase-repère (eg.l10).", "promptLanguage": "fr", "answer": "Saint Marc fonde l''Église d''Alexandrie", "acceptedAnswers": ["Saint Marc fonde l''Église d''Alexandrie"], "explanation": "Notre Église remonte à saint Marc, qui l''a fondée au Ier siècle.", "tip": "Marc, Alexandrie, Coptes.", "extraExample": {"text": "Marc est l''auteur du deuxième Évangile.", "translation": "Il vient en Égypte prêcher l''Évangile."}, "tokens": ["Marc", "d''Alexandrie", "Saint", "fonde", "l''Église"], "id": "eg.l10.e16", "pool": "lesson", "lessonId": "eg.l10", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e17', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques']::text[], 'match', 'lesson', 'Trois sièges et leurs particularités', '{}'::text[], 'Chaque siège a son trait distinctif.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Trois sièges et leurs particularités", "promptLanguage": "fr", "answer": "Antioche = là où les disciples sont appelés chrétiens ; Jérusalem = la première Église, avec saint Jacques ; Alexandrie = le siège de saint Marc, Église copte", "acceptedAnswers": [], "explanation": "Chaque siège a son trait distinctif.", "tip": "Un siège, un souvenir.", "pairs": [{"left": "Antioche", "right": "là où les disciples sont appelés chrétiens"}, {"left": "Jérusalem", "right": "la première Église, avec saint Jacques"}, {"left": "Alexandrie", "right": "le siège de saint Marc, Église copte"}], "id": "eg.l10.e17", "pool": "lesson", "lessonId": "eg.l10", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e18', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques','eg.v.siege_d_alexandrie']::text[], 'free_answer', 'lesson', 'Quelle ville est le siège de saint Marc ?', array['Alexandrie','le siège d''Alexandrie']::text[], 'Saint Marc fonde l''Église d''Alexandrie.', 2, '{"unitIds": ["eg.g10.sieges_apostoliques", "eg.v.siege_d_alexandrie"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quelle ville est le siège de saint Marc ?", "promptLanguage": "fr", "answer": "Alexandrie", "acceptedAnswers": ["Alexandrie", "le siège d''Alexandrie"], "explanation": "Saint Marc fonde l''Église d''Alexandrie.", "tip": "Marc → Alexandrie.", "extraExample": {"text": "Alexandrie est en Égypte.", "translation": "Elle est un grand centre intellectuel."}, "id": "eg.l10.e18", "pool": "lesson", "lessonId": "eg.l10", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e19', 'eg', 'eg.l10', 'eg.v.heresie', array['eg.v.heresie']::text[], 'free_answer', 'lesson', 'Cite une des quatre hérésies du IIe siècle.', array['le gnosticisme','gnosticisme','le docétisme','docétisme','docetisme','le marcionisme','marcionisme','le montanisme','montanisme']::text[], 'Rappel : gnosticisme, docétisme, marcionisme, montanisme.', 3, '{"unitIds": ["eg.v.heresie"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Cite une des quatre hérésies du IIe siècle.", "promptLanguage": "fr", "answer": "le gnosticisme", "acceptedAnswers": ["le gnosticisme", "gnosticisme", "le docétisme", "docétisme", "docetisme", "le marcionisme", "marcionisme", "le montanisme", "montanisme"], "explanation": "Rappel : gnosticisme, docétisme, marcionisme, montanisme.", "tip": "G-D-Ma-Mo.", "extraExample": {"text": "Chaque hérésie sera expliquée en détail.", "translation": "Tu les découvriras une à une."}, "id": "eg.l10.e19", "pool": "lesson", "lessonId": "eg.l10", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l10.e20', 'eg', 'eg.l10', 'eg.g10.sieges_apostoliques', array['eg.g10.sieges_apostoliques']::text[], 'free_answer', 'lesson', 'Combien de sièges apostoliques le IIe siècle reconnaît-il ?', array['quatre','4']::text[], 'Rome, Alexandrie, Antioche, Jérusalem.', 3, '{"unitIds": ["eg.g10.sieges_apostoliques"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Combien de sièges apostoliques le IIe siècle reconnaît-il ?", "promptLanguage": "fr", "answer": "quatre", "acceptedAnswers": ["quatre", "4"], "explanation": "Rome, Alexandrie, Antioche, Jérusalem.", "tip": "Quatre sièges, quatre villes.", "extraExample": {"text": "La liste est stable.", "translation": "On y ajoutera Constantinople plus tard, mais ce n''est pas un siège apostolique."}, "id": "eg.l10.e20", "pool": "lesson", "lessonId": "eg.l10", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e01', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques']::text[], 'match', 'lesson', 'Qui a écrit quoi ?', '{}'::text[], 'Chacun des trois a une marque distinctive.', 1, '{"unitIds": ["eg.g11.peres_apostoliques"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui a écrit quoi ?", "promptLanguage": "fr", "answer": "Clément de Rome = la lettre aux Corinthiens ; Ignace d''Antioche = sept lettres écrites en route vers Rome ; Polycarpe de Smyrne = disciple direct de l''apôtre Jean ; Les Pères apostoliques = écrivent pour enseigner l''Église", "acceptedAnswers": [], "explanation": "Chacun des trois a une marque distinctive.", "tip": "Clément C-C, Ignace sept, Polycarpe Jean.", "pairs": [{"left": "Clément de Rome", "right": "la lettre aux Corinthiens"}, {"left": "Ignace d''Antioche", "right": "sept lettres écrites en route vers Rome"}, {"left": "Polycarpe de Smyrne", "right": "disciple direct de l''apôtre Jean"}, {"left": "Les Pères apostoliques", "right": "écrivent pour enseigner l''Église"}], "id": "eg.l11.e01", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e02', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.smyrne']::text[], 'match', 'lesson', 'Chaque évêque et sa ville', '{}'::text[], 'Le trio vient de trois grandes villes de l''Empire.', 1, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.smyrne"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque évêque et sa ville", "promptLanguage": "fr", "answer": "Rome = Clément ; Antioche = Ignace ; Smyrne = Polycarpe", "acceptedAnswers": [], "explanation": "Le trio vient de trois grandes villes de l''Empire.", "tip": "R-C, A-I, S-P.", "pairs": [{"left": "Rome", "right": "Clément"}, {"left": "Antioche", "right": "Ignace"}, {"left": "Smyrne", "right": "Polycarpe"}], "id": "eg.l11.e02", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e03', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.peres_apostoliques']::text[], 'mcq', 'lesson', 'Pourquoi appelle-t-on ces Pères « apostoliques » ?', array['à cause de leur proximité avec la tradition apostolique']::text[], 'Ils n''étaient pas apôtres, mais ils ont reçu la tradition directement des apôtres ou de leurs disciples.', 1, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.peres_apostoliques"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi appelle-t-on ces Pères « apostoliques » ?", "promptLanguage": "fr", "answer": "à cause de leur proximité avec la tradition apostolique", "acceptedAnswers": ["à cause de leur proximité avec la tradition apostolique"], "explanation": "Ils n''étaient pas apôtres, mais ils ont reçu la tradition directement des apôtres ou de leurs disciples.", "tip": "Apostolique = proche des apôtres.", "extraExample": {"text": "Un élève de Jean est plus proche des apôtres qu''un chrétien de la 3e génération.", "translation": "D''où le nom."}, "options": ["parce qu''ils étaient apôtres", "parce qu''ils vivaient à Rome", "à cause de leur proximité avec la tradition apostolique", "parce qu''ils ont écrit l''Évangile"], "id": "eg.l11.e03", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e04', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.peres_apostoliques']::text[], 'mcq', 'lesson', 'Pour qui écrivent les Pères apostoliques ?', array['pour des chrétiens']::text[], 'Ce sont des lettres de pasteurs à leurs communautés. Les apologistes écriront, eux, pour ceux de l''extérieur.', 1, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.peres_apostoliques"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pour qui écrivent les Pères apostoliques ?", "promptLanguage": "fr", "answer": "pour des chrétiens", "acceptedAnswers": ["pour des chrétiens"], "explanation": "Ce sont des lettres de pasteurs à leurs communautés. Les apologistes écriront, eux, pour ceux de l''extérieur.", "tip": "Apostoliques = dedans.", "extraExample": {"text": "La lettre aux Corinthiens est adressée à une Église.", "translation": "Pas à un empereur."}, "options": ["pour des empereurs", "pour des philosophes païens", "pour des Juifs seulement", "pour des chrétiens"], "id": "eg.l11.e04", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e05', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.clement_de_rome']::text[], 'mcq', 'lesson', 'À qui Clément de Rome écrit-il vers 96 ?', array['aux chrétiens de Corinthe']::text[], 'L''Église de Corinthe est divisée ; Clément écrit pour rétablir l''ordre et la paix.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.clement_de_rome"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À qui Clément de Rome écrit-il vers 96 ?", "promptLanguage": "fr", "answer": "aux chrétiens de Corinthe", "acceptedAnswers": ["aux chrétiens de Corinthe"], "explanation": "L''Église de Corinthe est divisée ; Clément écrit pour rétablir l''ordre et la paix.", "tip": "Clément → Corinthe.", "extraExample": {"text": "Paul avait déjà écrit deux lettres aux Corinthiens.", "translation": "Clément écrit une lettre de plus pour les ramener à la paix."}, "options": ["aux chrétiens de Corinthe", "aux chrétiens d''Alexandrie", "à l''empereur Trajan", "aux chrétiens de Philippes"], "id": "eg.l11.e05", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e06', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.lettre_aux_philippiens']::text[], 'mcq', 'lesson', 'À qui Polycarpe écrit-il ?', array['aux chrétiens de Philippes']::text[], 'La lettre de Polycarpe aux Philippiens rappelle l''enseignement reçu des apôtres ; elle est reconnue dans la tradition de l''Église.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.lettre_aux_philippiens"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À qui Polycarpe écrit-il ?", "promptLanguage": "fr", "answer": "aux chrétiens de Philippes", "acceptedAnswers": ["aux chrétiens de Philippes"], "explanation": "La lettre de Polycarpe aux Philippiens rappelle l''enseignement reçu des apôtres ; elle est reconnue dans la tradition de l''Église.", "tip": "Polycarpe → Philippes.", "extraExample": {"text": "Paul avait déjà écrit aux Philippiens.", "translation": "Polycarpe leur écrit ensuite pour les affermir."}, "options": ["aux chrétiens de Corinthe", "aux chrétiens de Philippes", "à l''empereur Marc Aurèle", "aux chrétiens de Lyon"], "id": "eg.l11.e06", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e07', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.ignace_d_antioche']::text[], 'mcq', 'lesson', 'Quel Père apostolique est arrêté sous Trajan et conduit à Rome pour y être livré aux bêtes ?', array['Ignace d''Antioche']::text[], 'Ignace voyage enchaîné vers Rome et écrit sept lettres en chemin. Il meurt martyr vers 110.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.ignace_d_antioche"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel Père apostolique est arrêté sous Trajan et conduit à Rome pour y être livré aux bêtes ?", "promptLanguage": "fr", "answer": "Ignace d''Antioche", "acceptedAnswers": ["Ignace d''Antioche"], "explanation": "Ignace voyage enchaîné vers Rome et écrit sept lettres en chemin. Il meurt martyr vers 110.", "tip": "Ignace = voyage + lettres + bêtes.", "extraExample": {"text": "Ignace dit désirer le martyre pour imiter le Christ.", "translation": "Il supplie les chrétiens de Rome de ne pas empêcher son sacrifice."}, "options": ["Clément de Rome", "Polycarpe de Smyrne", "Ignace d''Antioche", "Justin Martyr"], "id": "eg.l11.e07", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e08', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.sept_lettres_d_ignace']::text[], 'mcq', 'lesson', 'Qu''affirme Ignace contre les docètes ?', array['la réalité du corps du Christ']::text[], 'Pour Ignace, le Christ est réellement né, a réellement souffert et est réellement ressuscité : son corps n''est pas une apparence.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.sept_lettres_d_ignace"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''affirme Ignace contre les docètes ?", "promptLanguage": "fr", "answer": "la réalité du corps du Christ", "acceptedAnswers": ["la réalité du corps du Christ"], "explanation": "Pour Ignace, le Christ est réellement né, a réellement souffert et est réellement ressuscité : son corps n''est pas une apparence.", "tip": "Ignace : « vraiment » un corps.", "extraExample": {"text": "Si le Christ n''avait pas de vrai corps, sa mort ne sauverait personne.", "translation": "Ignace insiste sur le vrai sang et la vraie chair."}, "options": ["l''inexistence de la matière", "le salut par une connaissance secrète", "la fin du monde imminente", "la réalité du corps du Christ"], "id": "eg.l11.e08", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e09', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.catholique_sens']::text[], 'mcq', 'lesson', 'Que veut dire « catholique » au sens premier du mot ?', array['universelle']::text[], 'Du grec katholikos, « selon le tout » : l''Église n''est pas locale, elle est pour toute la terre. Ignace emploie ce mot le premier.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.catholique_sens"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « catholique » au sens premier du mot ?", "promptLanguage": "fr", "answer": "universelle", "acceptedAnswers": ["universelle"], "explanation": "Du grec katholikos, « selon le tout » : l''Église n''est pas locale, elle est pour toute la terre. Ignace emploie ce mot le premier.", "tip": "Catholique = universelle.", "extraExample": {"text": "Le Credo dit : « une Église sainte, catholique et apostolique ».", "translation": "Catholique ici signifie universelle."}, "options": ["universelle", "romaine", "ancienne", "obligatoire"], "id": "eg.l11.e09", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e10', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.polycarpe_de_smyrne']::text[], 'mcq', 'lesson', 'Quel Père apostolique est disciple direct de l''apôtre Jean ?', array['Polycarpe de Smyrne']::text[], 'Polycarpe a connu Jean : il fait le lien entre l''âge des apôtres et celui d''Irénée.', 1, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.polycarpe_de_smyrne"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel Père apostolique est disciple direct de l''apôtre Jean ?", "promptLanguage": "fr", "answer": "Polycarpe de Smyrne", "acceptedAnswers": ["Polycarpe de Smyrne"], "explanation": "Polycarpe a connu Jean : il fait le lien entre l''âge des apôtres et celui d''Irénée.", "tip": "Polycarpe = élève de Jean.", "extraExample": {"text": "Irénée raconte avoir entendu Polycarpe parler de Jean.", "translation": "Le lien est direct."}, "options": ["Clément de Rome", "Polycarpe de Smyrne", "Ignace d''Antioche", "Tertullien"], "id": "eg.l11.e10", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e11', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques']::text[], 'mcq', 'lesson', 'Qui forme Irénée, futur évêque de Lyon ?', array['Polycarpe']::text[], 'Jean forme Polycarpe, qui forme Irénée : trois maillons relient le IIe siècle à Jésus.', 3, '{"unitIds": ["eg.g11.peres_apostoliques"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui forme Irénée, futur évêque de Lyon ?", "promptLanguage": "fr", "answer": "Polycarpe", "acceptedAnswers": ["Polycarpe"], "explanation": "Jean forme Polycarpe, qui forme Irénée : trois maillons relient le IIe siècle à Jésus.", "tip": "Jean → Polycarpe → Irénée.", "extraExample": {"text": "Irénée est un maillon de la chaîne apostolique.", "translation": "Il la décrit dans son livre contre les hérésies."}, "options": ["Ignace", "Clément", "Polycarpe", "Justin"], "id": "eg.l11.e11", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e12', 'eg', 'eg.l11', 'eg.v.saint_marc', array['eg.v.saint_marc']::text[], 'mcq', 'lesson', 'Quel apôtre est lié à l''Église d''Alexandrie ?', array['saint Marc']::text[], 'Rappel de la leçon précédente : Marc fonde l''Église d''Alexandrie, notre Église.', 2, '{"unitIds": ["eg.v.saint_marc"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel apôtre est lié à l''Église d''Alexandrie ?", "promptLanguage": "fr", "answer": "saint Marc", "acceptedAnswers": ["saint Marc"], "explanation": "Rappel de la leçon précédente : Marc fonde l''Église d''Alexandrie, notre Église.", "tip": "Marc = Alexandrie.", "extraExample": {"text": "Le pape d''Alexandrie est son successeur.", "translation": "Le siège porte son nom."}, "options": ["saint Jacques", "saint Pierre", "saint Jean", "saint Marc"], "id": "eg.l11.e12", "pool": "lesson", "lessonId": "eg.l11", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e13', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.lettre_aux_corinthiens']::text[], 'fill_blank', 'lesson', 'Clément de Rome écrit aux ___ vers 96.', array['Corinthiens']::text[], 'Sa lettre aux Corinthiens rappelle l''ordre établi par les apôtres.', 1, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.lettre_aux_corinthiens"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Clément de Rome écrit aux ___ vers 96.", "promptLanguage": "fr", "answer": "Corinthiens", "acceptedAnswers": ["Corinthiens"], "explanation": "Sa lettre aux Corinthiens rappelle l''ordre établi par les apôtres.", "tip": "C-C.", "extraExample": {"text": "Paul a aussi écrit aux Corinthiens.", "translation": "Mais la lettre de Clément est un écrit à part."}, "options": ["Philippiens", "Corinthiens", "Éphésiens", "Romains"], "id": "eg.l11.e13", "pool": "lesson", "lessonId": "eg.l11", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e14', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.ignace_d_antioche']::text[], 'fill_blank', 'lesson', 'Ignace est évêque d''___.', array['Antioche']::text[], 'Ignace est évêque d''Antioche ; il meurt à Rome.', 1, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.ignace_d_antioche"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Ignace est évêque d''___.", "promptLanguage": "fr", "answer": "Antioche", "acceptedAnswers": ["Antioche"], "explanation": "Ignace est évêque d''Antioche ; il meurt à Rome.", "tip": "Ignace = Antioche.", "extraExample": {"text": "Antioche est le siège où l''on dit « chrétiens » pour la première fois.", "translation": "Ignace en est l''un des premiers évêques."}, "options": ["Alexandrie", "Smyrne", "Antioche", "Jérusalem"], "id": "eg.l11.e14", "pool": "lesson", "lessonId": "eg.l11", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e15', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.smyrne']::text[], 'fill_blank', 'lesson', 'Polycarpe est évêque de ___, aujourd''hui Izmir.', array['Smyrne']::text[], 'Smyrne est en Turquie actuelle.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.smyrne"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Polycarpe est évêque de ___, aujourd''hui Izmir.", "promptLanguage": "fr", "answer": "Smyrne", "acceptedAnswers": ["Smyrne"], "explanation": "Smyrne est en Turquie actuelle.", "tip": "Polycarpe = Smyrne.", "extraExample": {"text": "Smyrne est l''une des sept Églises de l''Apocalypse.", "translation": "Polycarpe en est l''ange."}, "options": ["Corinthe", "Éphèse", "Antioche", "Smyrne"], "id": "eg.l11.e15", "pool": "lesson", "lessonId": "eg.l11", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
