insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e17', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.polycarpe_de_smyrne']::text[], 'reorder', 'lesson', 'Reconstitue la phrase-repère (eg.l11).', array['Polycarpe est un disciple direct de l''apôtre Jean']::text[], 'Polycarpe a connu Jean : il est le maillon entre l''âge des apôtres et celui d''Irénée.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.polycarpe_de_smyrne"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Reconstitue la phrase-repère (eg.l11).", "promptLanguage": "fr", "answer": "Polycarpe est un disciple direct de l''apôtre Jean", "acceptedAnswers": ["Polycarpe est un disciple direct de l''apôtre Jean"], "explanation": "Polycarpe a connu Jean : il est le maillon entre l''âge des apôtres et celui d''Irénée.", "tip": "Polycarpe-Jean.", "extraExample": {"text": "Irénée est le disciple de Polycarpe.", "translation": "La chaîne continue."}, "tokens": ["Jean", "un", "de", "direct", "est", "disciple", "Polycarpe", "l''apôtre"], "id": "eg.l11.e17", "pool": "lesson", "lessonId": "eg.l11", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e18', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.sept_lettres_d_ignace']::text[], 'free_answer', 'lesson', 'Quel Père apostolique a écrit sept lettres en route vers le martyre ?', array['Ignace d''Antioche','Ignace','saint Ignace','Ignace d Antioche']::text[], 'Ignace écrit à des Églises pendant son voyage vers Rome, avant son martyre.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.sept_lettres_d_ignace"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel Père apostolique a écrit sept lettres en route vers le martyre ?", "promptLanguage": "fr", "answer": "Ignace d''Antioche", "acceptedAnswers": ["Ignace d''Antioche", "Ignace", "saint Ignace", "Ignace d Antioche"], "explanation": "Ignace écrit à des Églises pendant son voyage vers Rome, avant son martyre.", "tip": "Sept lettres = Ignace.", "extraExample": {"text": "Ses lettres sont parmi les plus anciens textes chrétiens après le Nouveau Testament.", "translation": "Elles sont encore lues."}, "id": "eg.l11.e18", "pool": "lesson", "lessonId": "eg.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e19', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.clement_de_rome']::text[], 'free_answer', 'lesson', 'Quel Père apostolique a écrit aux Corinthiens vers 96 ?', array['Clément de Rome','Clément','saint Clément','Clément Rome']::text[], 'Clément, évêque de Rome, écrit pour rétablir la paix à Corinthe.', 2, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.clement_de_rome"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel Père apostolique a écrit aux Corinthiens vers 96 ?", "promptLanguage": "fr", "answer": "Clément de Rome", "acceptedAnswers": ["Clément de Rome", "Clément", "saint Clément", "Clément Rome"], "explanation": "Clément, évêque de Rome, écrit pour rétablir la paix à Corinthe.", "tip": "Clément-Corinthiens.", "extraExample": {"text": "Paul avait déjà écrit aux Corinthiens.", "translation": "Clément y revient quarante ans plus tard."}, "id": "eg.l11.e19", "pool": "lesson", "lessonId": "eg.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e20', 'eg', 'eg.l11', 'eg.g11.peres_apostoliques', array['eg.g11.peres_apostoliques','eg.v.smyrne']::text[], 'free_answer', 'lesson', 'Comment s''appelle l''actuelle ville turque qui correspond à l''ancienne Smyrne ?', array['Izmir','İzmir']::text[], 'Smyrne s''appelle aujourd''hui Izmir.', 3, '{"unitIds": ["eg.g11.peres_apostoliques", "eg.v.smyrne"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle l''actuelle ville turque qui correspond à l''ancienne Smyrne ?", "promptLanguage": "fr", "answer": "Izmir", "acceptedAnswers": ["Izmir", "İzmir"], "explanation": "Smyrne s''appelle aujourd''hui Izmir.", "tip": "Smyrne = Izmir.", "extraExample": {"text": "Polycarpe en est l''évêque.", "translation": "La ville est sur la mer Égée."}, "id": "eg.l11.e20", "pool": "lesson", "lessonId": "eg.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l11.e21', 'eg', 'eg.l11', 'eg.v.succession_apostolique', array['eg.v.succession_apostolique']::text[], 'free_answer', 'lesson', 'Comment s''appelle la suite ininterrompue d''évêques depuis les apôtres ?', array['la succession apostolique','succession apostolique']::text[], 'Rappel : la chaîne de la foi, de Jean à Polycarpe à Irénée en est l''illustration.', 2, '{"unitIds": ["eg.v.succession_apostolique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle la suite ininterrompue d''évêques depuis les apôtres ?", "promptLanguage": "fr", "answer": "la succession apostolique", "acceptedAnswers": ["la succession apostolique", "succession apostolique"], "explanation": "Rappel : la chaîne de la foi, de Jean à Polycarpe à Irénée en est l''illustration.", "tip": "Chaîne.", "extraExample": {"text": "Chaque évêque tient son rang d''un autre évêque.", "translation": "Et ainsi jusqu''aux apôtres."}, "id": "eg.l11.e21", "pool": "lesson", "lessonId": "eg.l11", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e01', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus']::text[], 'match', 'lesson', 'Qui a ordonné quelle persécution ?', '{}'::text[], 'Selon la tradition, on numérote les persécutions en suivant les empereurs.', 1, '{"unitIds": ["eg.g12.persecutions_ichthus"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui a ordonné quelle persécution ?", "promptLanguage": "fr", "answer": "Trajan = troisième persécution ; Marc Aurèle = quatrième persécution ; Septime Sévère = cinquième persécution ; Pline le Jeune = gouverneur de Bithynie qui interroge Trajan", "acceptedAnswers": [], "explanation": "Selon la tradition, on numérote les persécutions en suivant les empereurs.", "tip": "3-4-5.", "pairs": [{"left": "Trajan", "right": "troisième persécution"}, {"left": "Marc Aurèle", "right": "quatrième persécution"}, {"left": "Septime Sévère", "right": "cinquième persécution"}, {"left": "Pline le Jeune", "right": "gouverneur de Bithynie qui interroge Trajan"}], "id": "eg.l12.e01", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e02', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.ichthys']::text[], 'match', 'lesson', 'Les lettres de ICHTHYS', '{}'::text[], 'Chaque lettre du mot grec ICHTHYS est la première lettre d''un mot de la confession de foi.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.ichthys"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les lettres de ICHTHYS", "promptLanguage": "fr", "answer": "Jésus = I ; Christ = X ; de Dieu = Θ ; Fils = Υ ; Sauveur = Σ", "acceptedAnswers": [], "explanation": "Chaque lettre du mot grec ICHTHYS est la première lettre d''un mot de la confession de foi.", "tip": "I-X-Θ-Υ-Σ.", "pairs": [{"left": "Jésus", "right": "I"}, {"left": "Christ", "right": "X"}, {"left": "de Dieu", "right": "Θ"}, {"left": "Fils", "right": "Υ"}, {"left": "Sauveur", "right": "Σ"}], "id": "eg.l12.e02", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e03', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.culte_de_l_empereur']::text[], 'mcq', 'lesson', 'Pourquoi l''Empire romain se méfie-t-il des chrétiens ?', array['ils refusent le culte de l''empereur']::text[], 'L''Empire repose sur le culte public. Les chrétiens ne l''acceptent pas, ce qui paraît une menace pour l''unité.', 1, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.culte_de_l_empereur"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Empire romain se méfie-t-il des chrétiens ?", "promptLanguage": "fr", "answer": "ils refusent le culte de l''empereur", "acceptedAnswers": ["ils refusent le culte de l''empereur"], "explanation": "L''Empire repose sur le culte public. Les chrétiens ne l''acceptent pas, ce qui paraît une menace pour l''unité.", "tip": "Refus du culte = menace.", "extraExample": {"text": "Offrir de l''encens à l''empereur est un acte de loyauté.", "translation": "Les chrétiens ne peuvent pas le faire."}, "options": ["ils refusent de payer l''impôt", "ils attaquent l''armée", "ils refusent le culte de l''empereur", "ils parlent une langue inconnue"], "id": "eg.l12.e03", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e04', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.persecution_romaine']::text[], 'mcq', 'lesson', 'Quelle rumeur absurde circule sur les chrétiens ?', array['ils mangent de la chair humaine']::text[], 'C''est une déformation de l''eucharistie, que les chrétiens célèbrent à huis clos.', 1, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.persecution_romaine"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle rumeur absurde circule sur les chrétiens ?", "promptLanguage": "fr", "answer": "ils mangent de la chair humaine", "acceptedAnswers": ["ils mangent de la chair humaine"], "explanation": "C''est une déformation de l''eucharistie, que les chrétiens célèbrent à huis clos.", "tip": "Rumeur = eucharistie mal comprise.", "extraExample": {"text": "On ne connaît des chrétiens que ce qu''on entend à leur sujet.", "translation": "Les mots « corps » et « sang » ont nourri la rumeur."}, "options": ["ils adorent le soleil", "ils pillent les temples", "ils refusent de se marier", "ils mangent de la chair humaine"], "id": "eg.l12.e04", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e05', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.trajan']::text[], 'mcq', 'lesson', 'Que répond Trajan à Pline le Jeune ?', array['de ne pas rechercher les chrétiens']::text[], 'Trajan ne veut pas de chasse systématique, mais punit ceux qui sont dénoncés et refusent de sacrifier.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.trajan"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond Trajan à Pline le Jeune ?", "promptLanguage": "fr", "answer": "de ne pas rechercher les chrétiens", "acceptedAnswers": ["de ne pas rechercher les chrétiens"], "explanation": "Trajan ne veut pas de chasse systématique, mais punit ceux qui sont dénoncés et refusent de sacrifier.", "tip": "Ne pas chercher, mais punir.", "extraExample": {"text": "Un chrétien dénoncé peut sauver sa vie en reniant le Christ.", "translation": "Beaucoup refusent."}, "options": ["de ne pas rechercher les chrétiens", "de tuer tous les chrétiens", "d''ignorer toute dénonciation", "de donner la liberté de culte"], "id": "eg.l12.e05", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e06', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.marc_aurele']::text[], 'mcq', 'lesson', 'Quelle persécution est ordonnée sous Marc Aurèle ?', array['la quatrième']::text[], 'Selon la tradition, Trajan est le troisième, Marc Aurèle le quatrième et Septime Sévère le cinquième.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.marc_aurele"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle persécution est ordonnée sous Marc Aurèle ?", "promptLanguage": "fr", "answer": "la quatrième", "acceptedAnswers": ["la quatrième"], "explanation": "Selon la tradition, Trajan est le troisième, Marc Aurèle le quatrième et Septime Sévère le cinquième.", "tip": "Trajan 3, Marc Aurèle 4.", "extraExample": {"text": "Néron compte comme la première.", "translation": "La liste suit les empereurs."}, "options": ["la troisième", "la quatrième", "la cinquième", "la première"], "id": "eg.l12.e06", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e07', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.martyrs_de_lyon']::text[], 'mcq', 'lesson', 'Qui est Blandine ?', array['une jeune esclave']::text[], 'En 177, à Lyon, une jeune esclave nommée Blandine résiste jusqu''au bout et meurt martyre.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.martyrs_de_lyon"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est Blandine ?", "promptLanguage": "fr", "answer": "une jeune esclave", "acceptedAnswers": ["une jeune esclave"], "explanation": "En 177, à Lyon, une jeune esclave nommée Blandine résiste jusqu''au bout et meurt martyre.", "tip": "Blandine = Lyon.", "extraExample": {"text": "Pothin, évêque de Lyon, meurt la même année.", "translation": "Irénée lui succède."}, "options": ["une prophétesse montaniste", "la mère de Polycarpe", "une jeune esclave", "une fille de l''empereur"], "id": "eg.l12.e07", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e08', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus']::text[], 'mcq', 'lesson', 'Depuis combien d''années Polycarpe dit-il servir le Christ ?', array['86 ans']::text[], 'Devant le proconsul, il répond : voilà 86 ans que je le sers et il ne m''a fait aucun mal.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Depuis combien d''années Polycarpe dit-il servir le Christ ?", "promptLanguage": "fr", "answer": "86 ans", "acceptedAnswers": ["86 ans"], "explanation": "Devant le proconsul, il répond : voilà 86 ans que je le sers et il ne m''a fait aucun mal.", "tip": "86 ans = toute une vie.", "extraExample": {"text": "Il serait né vers 69-70 selon ce calcul.", "translation": "Il aurait connu Jean dans sa jeunesse."}, "options": ["40 ans", "70 ans", "100 ans", "86 ans"], "id": "eg.l12.e08", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e09', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.septime_severe']::text[], 'mcq', 'lesson', 'Quelle ville est durement frappée sous Septime Sévère ?', array['Alexandrie']::text[], 'Le père d''Origène, Léonidas, meurt martyr à Alexandrie en 202.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.septime_severe"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle ville est durement frappée sous Septime Sévère ?", "promptLanguage": "fr", "answer": "Alexandrie", "acceptedAnswers": ["Alexandrie"], "explanation": "Le père d''Origène, Léonidas, meurt martyr à Alexandrie en 202.", "tip": "Sévère = Alexandrie.", "extraExample": {"text": "Notre Église paie un lourd prix dès ses débuts.", "translation": "On y reviendra au IIIe siècle."}, "options": ["Alexandrie", "Lyon", "Smyrne", "Corinthe"], "id": "eg.l12.e09", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e10', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.ichthys']::text[], 'mcq', 'lesson', 'Quel est le symbole secret des chrétiens ?', array['un poisson']::text[], 'Le mot grec ICHTHYS signifie poisson ; ses lettres sont les initiales de Jésus Christ Fils de Dieu Sauveur.', 1, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.ichthys"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le symbole secret des chrétiens ?", "promptLanguage": "fr", "answer": "un poisson", "acceptedAnswers": ["un poisson"], "explanation": "Le mot grec ICHTHYS signifie poisson ; ses lettres sont les initiales de Jésus Christ Fils de Dieu Sauveur.", "tip": "Poisson = ICHTHYS.", "extraExample": {"text": "Un trait dans le sable suffit à se faire reconnaître.", "translation": "Un second trait complète le poisson."}, "options": ["une colombe", "un poisson", "une couronne", "un soleil"], "id": "eg.l12.e10", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e11', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.ichthys']::text[], 'mcq', 'lesson', 'Que signifient les lettres du mot ICHTHYS ?', array['Jésus Christ, Fils de Dieu, Sauveur']::text[], 'I (Jésus), X (Christ), Θ (de Dieu), Υ (Fils), Σ (Sauveur).', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.ichthys"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifient les lettres du mot ICHTHYS ?", "promptLanguage": "fr", "answer": "Jésus Christ, Fils de Dieu, Sauveur", "acceptedAnswers": ["Jésus Christ, Fils de Dieu, Sauveur"], "explanation": "I (Jésus), X (Christ), Θ (de Dieu), Υ (Fils), Σ (Sauveur).", "tip": "Cinq initiales = une confession.", "extraExample": {"text": "Le poisson est donc une profession de foi cachée.", "translation": "On la dessine sur les murs."}, "options": ["Jésus Christ, Roi du monde", "Jérusalem Christ Homme Témoin", "Jésus Christ, Fils de Dieu, Sauveur", "Je crois, Seigneur"], "id": "eg.l12.e11", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e12', 'eg', 'eg.l12', 'eg.v.ignace_d_antioche', array['eg.v.ignace_d_antioche']::text[], 'mcq', 'lesson', 'Quel évêque d''Antioche est arrêté sous Trajan et écrit sept lettres avant son martyre ?', array['Ignace d''Antioche']::text[], 'Rappel de la leçon précédente : Ignace est arrêté sous Trajan, écrit sept lettres et meurt à Rome vers 110.', 3, '{"unitIds": ["eg.v.ignace_d_antioche"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel évêque d''Antioche est arrêté sous Trajan et écrit sept lettres avant son martyre ?", "promptLanguage": "fr", "answer": "Ignace d''Antioche", "acceptedAnswers": ["Ignace d''Antioche"], "explanation": "Rappel de la leçon précédente : Ignace est arrêté sous Trajan, écrit sept lettres et meurt à Rome vers 110.", "tip": "Ignace = Trajan.", "extraExample": {"text": "La persécution de Trajan est la troisième.", "translation": "Ignace en est une figure."}, "options": ["Clément de Rome", "Polycarpe de Smyrne", "Justin Martyr", "Ignace d''Antioche"], "id": "eg.l12.e12", "pool": "lesson", "lessonId": "eg.l12", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e13', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.ichthys']::text[], 'fill_blank', 'lesson', 'Les chrétiens se reconnaissent grâce au symbole du ___.', array['poisson']::text[], 'ICHTHYS signifie poisson en grec.', 1, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.ichthys"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Les chrétiens se reconnaissent grâce au symbole du ___.", "promptLanguage": "fr", "answer": "poisson", "acceptedAnswers": ["poisson"], "explanation": "ICHTHYS signifie poisson en grec.", "tip": "Poisson = ICHTHYS.", "extraExample": {"text": "Un poisson dessiné sur un mur indiquait un lieu de réunion.", "translation": "Seuls les chrétiens le comprenaient."}, "options": ["agneau", "poisson", "pain", "serpent"], "id": "eg.l12.e13", "pool": "lesson", "lessonId": "eg.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e14', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.pline_le_jeune']::text[], 'fill_blank', 'lesson', 'Pline le Jeune est gouverneur de ___.', array['Bithynie']::text[], 'La Bithynie est une province du nord-ouest de l''Asie Mineure.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.pline_le_jeune"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Pline le Jeune est gouverneur de ___.", "promptLanguage": "fr", "answer": "Bithynie", "acceptedAnswers": ["Bithynie"], "explanation": "La Bithynie est une province du nord-ouest de l''Asie Mineure.", "tip": "Pline = Bithynie.", "extraExample": {"text": "Sa lettre à Trajan date de vers 112.", "translation": "Elle est l''un des plus anciens témoignages romains sur les chrétiens."}, "options": ["Smyrne", "Lyon", "Bithynie", "Alexandrie"], "id": "eg.l12.e14", "pool": "lesson", "lessonId": "eg.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e15', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.ichthys']::text[], 'fill_blank', 'lesson', 'ICHTHYS veut dire Jésus Christ, Fils de Dieu, ___.', array['Sauveur']::text[], 'La dernière lettre, Σ, est l''initiale du grec Sôtêr, Sauveur.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.ichthys"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "ICHTHYS veut dire Jésus Christ, Fils de Dieu, ___.", "promptLanguage": "fr", "answer": "Sauveur", "acceptedAnswers": ["Sauveur"], "explanation": "La dernière lettre, Σ, est l''initiale du grec Sôtêr, Sauveur.", "tip": "Σ = Sauveur.", "extraExample": {"text": "Le Christ est le Sauveur du monde.", "translation": "Cette confession est courte et complète."}, "options": ["Roi", "Prophète", "Maître", "Sauveur"], "id": "eg.l12.e15", "pool": "lesson", "lessonId": "eg.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e16', 'eg', 'eg.l12', 'eg.v.polycarpe_de_smyrne', array['eg.v.polycarpe_de_smyrne']::text[], 'fill_blank', 'lesson', 'Polycarpe était disciple de l''apôtre ___.', array['Jean']::text[], 'Polycarpe a connu Jean : c''est le maillon avec Irénée.', 2, '{"unitIds": ["eg.v.polycarpe_de_smyrne"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Polycarpe était disciple de l''apôtre ___.", "promptLanguage": "fr", "answer": "Jean", "acceptedAnswers": ["Jean"], "explanation": "Polycarpe a connu Jean : c''est le maillon avec Irénée.", "tip": "Polycarpe = Jean.", "extraExample": {"text": "Irénée est le disciple de Polycarpe.", "translation": "La chaîne continue."}, "options": ["Jean", "Pierre", "Paul", "Marc"], "id": "eg.l12.e16", "pool": "lesson", "lessonId": "eg.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e17', 'eg', 'eg.l12', 'eg.v.siege_de_rome', array['eg.v.siege_de_rome']::text[], 'fill_blank', 'lesson', 'Rome est le siège fondé par les apôtres Pierre et ___.', array['Paul']::text[], 'Rappel de la leçon sur les sièges apostoliques.', 2, '{"unitIds": ["eg.v.siege_de_rome"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Rome est le siège fondé par les apôtres Pierre et ___.", "promptLanguage": "fr", "answer": "Paul", "acceptedAnswers": ["Paul"], "explanation": "Rappel de la leçon sur les sièges apostoliques.", "tip": "Rome = Pierre et Paul.", "extraExample": {"text": "Ils sont tous deux morts à Rome.", "translation": "Au temps de Néron."}, "options": ["Marc", "Paul", "Jacques", "Jean"], "id": "eg.l12.e17", "pool": "lesson", "lessonId": "eg.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e18', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.culte_de_l_empereur']::text[], 'reorder', 'lesson', 'Reconstitue la phrase-repère (eg.l12).', array['Les chrétiens refusent le culte de l''empereur']::text[], 'Ce refus est la cause profonde des persécutions.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.culte_de_l_empereur"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Reconstitue la phrase-repère (eg.l12).", "promptLanguage": "fr", "answer": "Les chrétiens refusent le culte de l''empereur", "acceptedAnswers": ["Les chrétiens refusent le culte de l''empereur"], "explanation": "Ce refus est la cause profonde des persécutions.", "tip": "Refus du culte = persécution.", "extraExample": {"text": "Offrir de l''encens à l''empereur est un acte religieux.", "translation": "Les chrétiens ne le font pas."}, "tokens": ["culte", "de", "l''empereur", "refusent", "Les", "le", "chrétiens"], "id": "eg.l12.e18", "pool": "lesson", "lessonId": "eg.l12", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e19', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.ichthys']::text[], 'free_answer', 'lesson', 'Quel mot grec, qui veut dire poisson, sert de symbole aux chrétiens ?', array['ICHTHYS','ichthus','Ichtus']::text[], 'ICHTHYS est aussi un sigle : Jésus Christ Fils de Dieu Sauveur.', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.ichthys"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot grec, qui veut dire poisson, sert de symbole aux chrétiens ?", "promptLanguage": "fr", "answer": "ICHTHYS", "acceptedAnswers": ["ICHTHYS", "ichthus", "Ichtus"], "explanation": "ICHTHYS est aussi un sigle : Jésus Christ Fils de Dieu Sauveur.", "tip": "Poisson = ICHTHYS.", "extraExample": {"text": "Chaque lettre est une initiale.", "translation": "Le tout forme une confession de foi."}, "id": "eg.l12.e19", "pool": "lesson", "lessonId": "eg.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e20', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.martyr']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on un chrétien qui meurt plutôt que de renier le Christ ?', array['un martyr','martyr','le martyr','une martyre','martyre']::text[], 'Du grec martys, « témoin ».', 2, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.martyr"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on un chrétien qui meurt plutôt que de renier le Christ ?", "promptLanguage": "fr", "answer": "un martyr", "acceptedAnswers": ["un martyr", "martyr", "le martyr", "une martyre", "martyre"], "explanation": "Du grec martys, « témoin ».", "tip": "Martyr = témoin.", "extraExample": {"text": "Polycarpe est un martyr.", "translation": "Blandine aussi."}, "id": "eg.l12.e20", "pool": "lesson", "lessonId": "eg.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l12.e21', 'eg', 'eg.l12', 'eg.g12.persecutions_ichthus', array['eg.g12.persecutions_ichthus','eg.v.trajan']::text[], 'free_answer', 'lesson', 'Quel empereur est le troisième à persécuter les chrétiens selon la tradition ?', array['Trajan','l''empereur Trajan']::text[], 'Trajan est suivi par Marc Aurèle (4e) et Septime Sévère (5e).', 3, '{"unitIds": ["eg.g12.persecutions_ichthus", "eg.v.trajan"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel empereur est le troisième à persécuter les chrétiens selon la tradition ?", "promptLanguage": "fr", "answer": "Trajan", "acceptedAnswers": ["Trajan", "l''empereur Trajan"], "explanation": "Trajan est suivi par Marc Aurèle (4e) et Septime Sévère (5e).", "tip": "Trajan = 3.", "extraExample": {"text": "Pline lui écrit pour savoir quoi faire.", "translation": "Sa réponse devient une règle."}, "id": "eg.l12.e21", "pool": "lesson", "lessonId": "eg.l12", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e01', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes']::text[], 'match', 'lesson', 'Deux familles d''écrivains', '{}'::text[], 'Deux publics différents : les chrétiens (apostoliques) et les païens (apologistes).', 1, '{"unitIds": ["eg.g13.apologistes"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Deux familles d''écrivains", "promptLanguage": "fr", "answer": "Pères apostoliques = écrivent aux chrétiens pour les enseigner ; Apologistes = écrivent aux païens pour défendre la foi ; Justin Martyr = philosophe converti, martyr à Rome vers 165 ; Tertullien = juriste de Carthage, premier grand auteur latin", "acceptedAnswers": [], "explanation": "Deux publics différents : les chrétiens (apostoliques) et les païens (apologistes).", "tip": "Dedans / dehors.", "pairs": [{"left": "Pères apostoliques", "right": "écrivent aux chrétiens pour les enseigner"}, {"left": "Apologistes", "right": "écrivent aux païens pour défendre la foi"}, {"left": "Justin Martyr", "right": "philosophe converti, martyr à Rome vers 165"}, {"left": "Tertullien", "right": "juriste de Carthage, premier grand auteur latin"}], "id": "eg.l13.e01", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e02', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.dialogue_avec_tryphon','eg.v.apologetique']::text[], 'match', 'lesson', 'Quelle œuvre pour quel auteur ?', '{}'::text[], 'Chaque auteur a ses œuvres à retenir.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.dialogue_avec_tryphon", "eg.v.apologetique"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle œuvre pour quel auteur ?", "promptLanguage": "fr", "answer": "Justin = Dialogue avec Tryphon ; Tertullien = Apologétique ; Polycarpe = lettre aux Philippiens", "acceptedAnswers": [], "explanation": "Chaque auteur a ses œuvres à retenir.", "tip": "Justin-Tryphon, Tertullien-Apologétique.", "pairs": [{"left": "Justin", "right": "Dialogue avec Tryphon"}, {"left": "Tertullien", "right": "Apologétique"}, {"left": "Polycarpe", "right": "lettre aux Philippiens"}], "id": "eg.l13.e02", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e03', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologiste']::text[], 'mcq', 'lesson', 'Que signifie le mot grec apologia ?', array['défense']::text[], 'Les apologistes défendent la foi devant ceux de l''extérieur.', 1, '{"unitIds": ["eg.g13.apologistes", "eg.v.apologiste"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie le mot grec apologia ?", "promptLanguage": "fr", "answer": "défense", "acceptedAnswers": ["défense"], "explanation": "Les apologistes défendent la foi devant ceux de l''extérieur.", "tip": "Apologie = défense.", "extraExample": {"text": "Une apologie n''est pas une excuse mais une défense argumentée.", "translation": "Elle répond à des accusations."}, "options": ["prière", "louange", "défense", "enseignement"], "id": "eg.l13.e03", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e04', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologiste']::text[], 'mcq', 'lesson', 'À qui s''adressent les apologistes ?', array['à des gens extérieurs à la communauté chrétienne']::text[], 'Ils écrivent aux empereurs, aux magistrats, aux philosophes, c''est-à-dire à ceux qui ne sont pas chrétiens.', 1, '{"unitIds": ["eg.g13.apologistes", "eg.v.apologiste"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "À qui s''adressent les apologistes ?", "promptLanguage": "fr", "answer": "à des gens extérieurs à la communauté chrétienne", "acceptedAnswers": ["à des gens extérieurs à la communauté chrétienne"], "explanation": "Ils écrivent aux empereurs, aux magistrats, aux philosophes, c''est-à-dire à ceux qui ne sont pas chrétiens.", "tip": "Apologistes = au dehors.", "extraExample": {"text": "Justin écrit à l''empereur.", "translation": "Tertullien écrit aux magistrats."}, "options": ["uniquement aux évêques", "aux chrétiens de leur ville", "aux seuls disciples des apôtres", "à des gens extérieurs à la communauté chrétienne"], "id": "eg.l13.e04", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e05', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.paganisme']::text[], 'mcq', 'lesson', 'De quoi les païens accusent-ils les chrétiens ?', array['d''être athées']::text[], 'Les chrétiens n''adorent pas les dieux de l''Empire : les païens les prennent pour des athées.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.paganisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "De quoi les païens accusent-ils les chrétiens ?", "promptLanguage": "fr", "answer": "d''être athées", "acceptedAnswers": ["d''être athées"], "explanation": "Les chrétiens n''adorent pas les dieux de l''Empire : les païens les prennent pour des athées.", "tip": "Athées = sans dieux (aux yeux des païens).", "extraExample": {"text": "Les chrétiens répondent qu''ils adorent le seul vrai Dieu.", "translation": "Ils ne sont donc pas athées."}, "options": ["d''être athées", "d''adorer trop de dieux", "de refuser la prière", "de piller les temples"], "id": "eg.l13.e05", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e06', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.culte_de_l_empereur']::text[], 'mcq', 'lesson', 'Que répondent les apologistes à propos de l''empereur ?', array['nous prions pour l''empereur sans l''adorer']::text[], 'Les chrétiens sont de bons citoyens : ils prient pour l''empereur, mais l''adoration est réservée à Dieu.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.culte_de_l_empereur"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répondent les apologistes à propos de l''empereur ?", "promptLanguage": "fr", "answer": "nous prions pour l''empereur sans l''adorer", "acceptedAnswers": ["nous prions pour l''empereur sans l''adorer"], "explanation": "Les chrétiens sont de bons citoyens : ils prient pour l''empereur, mais l''adoration est réservée à Dieu.", "tip": "Prier pour ≠ adorer.", "extraExample": {"text": "Un chrétien paie l''impôt et prie pour l''empereur.", "translation": "Mais il ne lui rend pas un culte."}, "options": ["nous l''adorons comme un dieu", "nous prions pour l''empereur sans l''adorer", "nous le refusons comme chef", "nous ne le connaissons pas"], "id": "eg.l13.e06", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e07', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.justin_martyr']::text[], 'mcq', 'lesson', 'D''où vient Justin Martyr ?', array['Naplouse, en Palestine']::text[], 'Justin naît dans une famille païenne de Naplouse. Il cherche la vérité chez les philosophes avant de se convertir.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.justin_martyr"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "D''où vient Justin Martyr ?", "promptLanguage": "fr", "answer": "Naplouse, en Palestine", "acceptedAnswers": ["Naplouse, en Palestine"], "explanation": "Justin naît dans une famille païenne de Naplouse. Il cherche la vérité chez les philosophes avant de se convertir.", "tip": "Justin = Naplouse.", "extraExample": {"text": "Il enseigne ensuite à Rome.", "translation": "Il y meurt martyr vers 165."}, "options": ["Carthage", "Smyrne", "Naplouse, en Palestine", "Alexandrie"], "id": "eg.l13.e07", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e08', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.semences_du_verbe']::text[], 'mcq', 'lesson', 'Que sont les « semences du Verbe » pour Justin ?', array['des parts de vérité']::text[], 'Le Verbe éclaire tout homme : les philosophes ont donc entrevu des parts de vérité, que le Christ révèle en entier.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.semences_du_verbe"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que sont les « semences du Verbe » pour Justin ?", "promptLanguage": "fr", "answer": "des parts de vérité", "acceptedAnswers": ["des parts de vérité"], "explanation": "Le Verbe éclaire tout homme : les philosophes ont donc entrevu des parts de vérité, que le Christ révèle en entier.", "tip": "Semences = graines de vérité.", "extraExample": {"text": "Socrate cherchait la vérité, selon Justin.", "translation": "Le Christ la donne en plénitude."}, "options": ["des livres cachés des apôtres", "des prophéties de Montanus", "des miracles des martyrs", "des parts de vérité"], "id": "eg.l13.e08", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e09', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.tertullien']::text[], 'mcq', 'lesson', 'Où vit Tertullien ?', array['à Carthage']::text[], 'Carthage est en Afrique du Nord. Tertullien y écrit en latin, ce qui en fait le premier grand auteur chrétien latin.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.tertullien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où vit Tertullien ?", "promptLanguage": "fr", "answer": "à Carthage", "acceptedAnswers": ["à Carthage"], "explanation": "Carthage est en Afrique du Nord. Tertullien y écrit en latin, ce qui en fait le premier grand auteur chrétien latin.", "tip": "Tertullien = Carthage.", "extraExample": {"text": "Carthage est dans l''actuelle Tunisie.", "translation": "Elle est proche de l''Égypte en Afrique du Nord."}, "options": ["à Carthage", "à Antioche", "à Lyon", "à Jérusalem"], "id": "eg.l13.e09", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e10', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.sang_des_martyrs']::text[], 'mcq', 'lesson', 'Quelle phrase célèbre écrit Tertullien ?', array['le sang des martyrs est une semence de chrétiens']::text[], 'Plus on persécute, plus le courage des martyrs interroge et convainc : de nouveaux chrétiens naissent.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.sang_des_martyrs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle phrase célèbre écrit Tertullien ?", "promptLanguage": "fr", "answer": "le sang des martyrs est une semence de chrétiens", "acceptedAnswers": ["le sang des martyrs est une semence de chrétiens"], "explanation": "Plus on persécute, plus le courage des martyrs interroge et convainc : de nouveaux chrétiens naissent.", "tip": "Sang des martyrs = semence.", "extraExample": {"text": "Les persécutions n''ont pas détruit l''Église.", "translation": "Elles l''ont fait grandir."}, "options": ["la foi déplace les montagnes", "le sang des martyrs est une semence de chrétiens", "l''Église est une mère", "le Christ est le Verbe"], "id": "eg.l13.e10", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e11', 'eg', 'eg.l13', 'eg.v.marc_aurele', array['eg.v.marc_aurele']::text[], 'mcq', 'lesson', 'Quel empereur ordonne la quatrième persécution, pendant la vie de Justin ?', array['Marc Aurèle']::text[], 'Rappel de la leçon précédente : Marc Aurèle (161-180) ; Justin est martyrisé à Rome vers 165.', 3, '{"unitIds": ["eg.v.marc_aurele"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur ordonne la quatrième persécution, pendant la vie de Justin ?", "promptLanguage": "fr", "answer": "Marc Aurèle", "acceptedAnswers": ["Marc Aurèle"], "explanation": "Rappel de la leçon précédente : Marc Aurèle (161-180) ; Justin est martyrisé à Rome vers 165.", "tip": "Marc Aurèle = 4e.", "extraExample": {"text": "Trajan est le troisième.", "translation": "Septime Sévère est le cinquième."}, "options": ["Trajan", "Septime Sévère", "Marc Aurèle", "Néron"], "id": "eg.l13.e11", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e12', 'eg', 'eg.l13', 'eg.v.polycarpe_de_smyrne', array['eg.v.polycarpe_de_smyrne']::text[], 'mcq', 'lesson', 'Quel Père apostolique est lié à l''apôtre Jean ?', array['Polycarpe de Smyrne']::text[], 'Rappel de la leçon sur les Pères apostoliques : Polycarpe est disciple direct de Jean.', 3, '{"unitIds": ["eg.v.polycarpe_de_smyrne"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel Père apostolique est lié à l''apôtre Jean ?", "promptLanguage": "fr", "answer": "Polycarpe de Smyrne", "acceptedAnswers": ["Polycarpe de Smyrne"], "explanation": "Rappel de la leçon sur les Pères apostoliques : Polycarpe est disciple direct de Jean.", "tip": "Polycarpe = Jean.", "extraExample": {"text": "Irénée est son disciple.", "translation": "La chaîne se prolonge."}, "options": ["Clément de Rome", "Ignace d''Antioche", "Justin Martyr", "Polycarpe de Smyrne"], "id": "eg.l13.e12", "pool": "lesson", "lessonId": "eg.l13", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e13', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.paganisme']::text[], 'fill_blank', 'lesson', 'Les apologistes défendent la foi devant les ___.', array['païens']::text[], 'Ils parlent à ceux qui ne sont pas chrétiens.', 1, '{"unitIds": ["eg.g13.apologistes", "eg.v.paganisme"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Les apologistes défendent la foi devant les ___.", "promptLanguage": "fr", "answer": "païens", "acceptedAnswers": ["païens"], "explanation": "Ils parlent à ceux qui ne sont pas chrétiens.", "tip": "Apologistes = païens.", "extraExample": {"text": "Les Pères apostoliques parlent aux chrétiens.", "translation": "Les apologistes, aux païens."}, "options": ["évêques", "païens", "prophètes", "disciples"], "id": "eg.l13.e13", "pool": "lesson", "lessonId": "eg.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e14', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologetique']::text[], 'fill_blank', 'lesson', 'Tertullien écrit l''Apologétique en ___.', array['197']::text[], 'Une date à retenir : 197, la fin du IIe siècle.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.apologetique"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Tertullien écrit l''Apologétique en ___.", "promptLanguage": "fr", "answer": "197", "acceptedAnswers": ["197"], "explanation": "Une date à retenir : 197, la fin du IIe siècle.", "tip": "197 = Apologétique.", "extraExample": {"text": "En 313, Constantin donne l''édit de Milan.", "translation": "Rien à voir avec 197."}, "options": ["155", "251", "197", "313"], "id": "eg.l13.e14", "pool": "lesson", "lessonId": "eg.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e15', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.justin_martyr']::text[], 'fill_blank', 'lesson', 'Justin est martyrisé à ___ vers 165.', array['Rome']::text[], 'Justin enseigne à Rome et y meurt martyr.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.justin_martyr"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Justin est martyrisé à ___ vers 165.", "promptLanguage": "fr", "answer": "Rome", "acceptedAnswers": ["Rome"], "explanation": "Justin enseigne à Rome et y meurt martyr.", "tip": "Justin = Rome.", "extraExample": {"text": "Clément est aussi évêque de Rome.", "translation": "Rome est un grand foyer chrétien."}, "options": ["Lyon", "Carthage", "Smyrne", "Rome"], "id": "eg.l13.e15", "pool": "lesson", "lessonId": "eg.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e16', 'eg', 'eg.l13', 'eg.v.sept_lettres_d_ignace', array['eg.v.sept_lettres_d_ignace']::text[], 'fill_blank', 'lesson', 'Ignace d''Antioche écrit ___ lettres en route vers Rome.', array['sept']::text[], 'Rappel de la leçon sur les Pères apostoliques : sept lettres, avant son martyre vers 110.', 2, '{"unitIds": ["eg.v.sept_lettres_d_ignace"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Ignace d''Antioche écrit ___ lettres en route vers Rome.", "promptLanguage": "fr", "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Rappel de la leçon sur les Pères apostoliques : sept lettres, avant son martyre vers 110.", "tip": "Ignace = sept lettres.", "extraExample": {"text": "Ses lettres combattent le docétisme.", "translation": "Elles insistent sur le vrai corps du Christ."}, "options": ["sept", "trois", "douze", "quatre"], "id": "eg.l13.e16", "pool": "lesson", "lessonId": "eg.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e17', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.apologiste']::text[], 'reorder', 'lesson', 'Reconstitue la phrase-repère (eg.l13).', array['Les apologistes défendent la foi devant les païens']::text[], 'Apologia veut dire défense : leur public est celui de l''extérieur.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.apologiste"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre.", "prompt": "Reconstitue la phrase-repère (eg.l13).", "promptLanguage": "fr", "answer": "Les apologistes défendent la foi devant les païens", "acceptedAnswers": ["Les apologistes défendent la foi devant les païens"], "explanation": "Apologia veut dire défense : leur public est celui de l''extérieur.", "tip": "Défense devant les païens.", "extraExample": {"text": "Justin écrit à l''empereur.", "translation": "C''est une défense publique."}, "tokens": ["devant", "Les", "apologistes", "les", "païens", "foi", "la", "défendent"], "id": "eg.l13.e17", "pool": "lesson", "lessonId": "eg.l13", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e18', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.justin_martyr']::text[], 'free_answer', 'lesson', 'Quel apologiste est surnommé Martyr ?', array['Justin','Justin Martyr','saint Justin']::text[], 'Justin est mort martyr à Rome vers 165, d''où son surnom.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.justin_martyr"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel apologiste est surnommé Martyr ?", "promptLanguage": "fr", "answer": "Justin", "acceptedAnswers": ["Justin", "Justin Martyr", "saint Justin"], "explanation": "Justin est mort martyr à Rome vers 165, d''où son surnom.", "tip": "Justin = Martyr.", "extraExample": {"text": "Polycarpe est aussi un martyr.", "translation": "Justin est l''apologiste."}, "id": "eg.l13.e18", "pool": "lesson", "lessonId": "eg.l13", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e19', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.tertullien']::text[], 'free_answer', 'lesson', 'Quel auteur de Carthage écrit l''Apologétique ?', array['Tertullien','Tertulien']::text[], 'Tertullien, juriste de Carthage, premier grand auteur chrétien latin.', 2, '{"unitIds": ["eg.g13.apologistes", "eg.v.tertullien"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel auteur de Carthage écrit l''Apologétique ?", "promptLanguage": "fr", "answer": "Tertullien", "acceptedAnswers": ["Tertullien", "Tertulien"], "explanation": "Tertullien, juriste de Carthage, premier grand auteur chrétien latin.", "tip": "Apologétique = Tertullien.", "extraExample": {"text": "Il écrit aussi Contre Marcion.", "translation": "Il écrit en latin."}, "id": "eg.l13.e19", "pool": "lesson", "lessonId": "eg.l13", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l13.e20', 'eg', 'eg.l13', 'eg.g13.apologistes', array['eg.g13.apologistes','eg.v.semences_du_verbe']::text[], 'free_answer', 'lesson', 'Comment s''appelle l''idée de Justin selon laquelle les philosophes ont entrevu une part de vérité ?', array['les semences du Verbe','semences du Verbe']::text[], 'Le Verbe éclaire tout homme, les philosophes en ont entrevu des semences.', 3, '{"unitIds": ["eg.g13.apologistes", "eg.v.semences_du_verbe"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle l''idée de Justin selon laquelle les philosophes ont entrevu une part de vérité ?", "promptLanguage": "fr", "answer": "les semences du Verbe", "acceptedAnswers": ["les semences du Verbe", "semences du Verbe"], "explanation": "Le Verbe éclaire tout homme, les philosophes en ont entrevu des semences.", "tip": "Semences du Verbe.", "extraExample": {"text": "Le Christ est le couronnement de leur quête.", "translation": "Il révèle la vérité en entier."}, "id": "eg.l13.e20", "pool": "lesson", "lessonId": "eg.l13", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e01', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme']::text[], 'match', 'lesson', 'Définitions', '{}'::text[], 'Quatre mots qui résument la leçon.', 1, '{"unitIds": ["eg.g14.gnosticisme_docetisme"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Définitions", "promptLanguage": "fr", "answer": "Gnose = connaissance secrète qui sauverait une élite ; Docétisme = le Christ n''aurait eu qu''un corps apparent ; Démiurge = dieu inférieur qui aurait créé le monde ; Irénée de Lyon = évêque, auteur de Contre les hérésies", "acceptedAnswers": [], "explanation": "Quatre mots qui résument la leçon.", "tip": "Gnose = savoir ; docète = apparence.", "pairs": [{"left": "Gnose", "right": "connaissance secrète qui sauverait une élite"}, {"left": "Docétisme", "right": "le Christ n''aurait eu qu''un corps apparent"}, {"left": "Démiurge", "right": "dieu inférieur qui aurait créé le monde"}, {"left": "Irénée de Lyon", "right": "évêque, auteur de Contre les hérésies"}], "id": "eg.l14.e01", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e02', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.valentin','eg.v.basilide','eg.v.nag_hammadi']::text[], 'match', 'lesson', 'Gnostiques et adversaires : qui est qui ?', '{}'::text[], 'Deux maîtres gnostiques égyptiens, un défenseur, un lieu.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.valentin", "eg.v.basilide", "eg.v.nag_hammadi"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Gnostiques et adversaires : qui est qui ?", "promptLanguage": "fr", "answer": "Valentin = maître gnostique d''Alexandrie et de Rome ; Basilide = maître gnostique d''Alexandrie ; Ignace d''Antioche = combat le docétisme ; Nag Hammadi = bibliothèque gnostique retrouvée en 1945", "acceptedAnswers": [], "explanation": "Deux maîtres gnostiques égyptiens, un défenseur, un lieu.", "tip": "V-B-I-N.", "pairs": [{"left": "Valentin", "right": "maître gnostique d''Alexandrie et de Rome"}, {"left": "Basilide", "right": "maître gnostique d''Alexandrie"}, {"left": "Ignace d''Antioche", "right": "combat le docétisme"}, {"left": "Nag Hammadi", "right": "bibliothèque gnostique retrouvée en 1945"}], "id": "eg.l14.e02", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e03', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.gnose']::text[], 'mcq', 'lesson', 'Que veut dire gnosis en grec ?', array['connaissance']::text[], 'Gnosticisme vient de gnosis : le salut serait par une connaissance secrète.', 1, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.gnose"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire gnosis en grec ?", "promptLanguage": "fr", "answer": "connaissance", "acceptedAnswers": ["connaissance"], "explanation": "Gnosticisme vient de gnosis : le salut serait par une connaissance secrète.", "tip": "Gnose = connaissance.", "extraExample": {"text": "Agnostique vient aussi de gnosis (« sans connaissance »).", "translation": "Même racine grecque."}, "options": ["secret", "foi", "connaissance", "esprit"], "id": "eg.l14.e03", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e04', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.gnosticisme']::text[], 'mcq', 'lesson', 'Selon les gnostiques, comment est-on sauvé ?', array['par une connaissance secrète']::text[], 'Le salut serait réservé à une élite d''initiés qui reçoit la gnose.', 1, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.gnosticisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Selon les gnostiques, comment est-on sauvé ?", "promptLanguage": "fr", "answer": "par une connaissance secrète", "acceptedAnswers": ["par une connaissance secrète"], "explanation": "Le salut serait réservé à une élite d''initiés qui reçoit la gnose.", "tip": "Salut par la gnose.", "extraExample": {"text": "L''Église, elle, offre le salut à tous.", "translation": "Par la foi et les sacrements."}, "options": ["par la foi simple de tous", "par les sacrements seuls", "par le martyre seulement", "par une connaissance secrète"], "id": "eg.l14.e04", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e05', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.gnosticisme']::text[], 'mcq', 'lesson', 'Pour les gnostiques, la matière est...', array['mauvaise']::text[], 'Pour eux, seul l''esprit est bon. D''où le mépris du corps et la négation de la résurrection de la chair.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.gnosticisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pour les gnostiques, la matière est...", "promptLanguage": "fr", "answer": "mauvaise", "acceptedAnswers": ["mauvaise"], "explanation": "Pour eux, seul l''esprit est bon. D''où le mépris du corps et la négation de la résurrection de la chair.", "tip": "Matière = mauvaise (pour eux).", "extraExample": {"text": "L''Église répond : Dieu vit que cela était très bon.", "translation": "Genèse 1."}, "options": ["mauvaise", "très bonne", "neutre", "divine"], "id": "eg.l14.e05", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e06', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.demiurge']::text[], 'mcq', 'lesson', 'Qui a créé le monde selon les gnostiques ?', array['un dieu inférieur, le démiurge']::text[], 'Le monde matériel serait l''œuvre d''un dieu inférieur, et non du vrai Dieu.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.demiurge"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui a créé le monde selon les gnostiques ?", "promptLanguage": "fr", "answer": "un dieu inférieur, le démiurge", "acceptedAnswers": ["un dieu inférieur, le démiurge"], "explanation": "Le monde matériel serait l''œuvre d''un dieu inférieur, et non du vrai Dieu.", "tip": "Démiurge = artisan.", "extraExample": {"text": "L''Église confesse un seul Dieu, créateur de toutes choses.", "translation": "Rien n''échappe à sa bonté."}, "options": ["le Dieu unique", "un dieu inférieur, le démiurge", "les anges", "les apôtres"], "id": "eg.l14.e06", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e07', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.valentin']::text[], 'mcq', 'lesson', 'Où enseignent Valentin et Basilide ?', array['à Alexandrie']::text[], 'Les deux maîtres gnostiques enseignent à Alexandrie : le gnosticisme concerne donc l''Église d''Égypte.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.valentin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où enseignent Valentin et Basilide ?", "promptLanguage": "fr", "answer": "à Alexandrie", "acceptedAnswers": ["à Alexandrie"], "explanation": "Les deux maîtres gnostiques enseignent à Alexandrie : le gnosticisme concerne donc l''Église d''Égypte.", "tip": "Gnostiques = aussi chez nous.", "extraExample": {"text": "Valentin passera ensuite à Rome.", "translation": "Basilide reste en Égypte."}, "options": ["à Lyon", "à Carthage", "à Alexandrie", "à Smyrne"], "id": "eg.l14.e07", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e08', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.docetisme']::text[], 'mcq', 'lesson', 'Que veut dire le mot docétisme (dokein) ?', array['sembler']::text[], 'Selon les docètes, le Christ aurait seulement semblé avoir un corps.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.docetisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le mot docétisme (dokein) ?", "promptLanguage": "fr", "answer": "sembler", "acceptedAnswers": ["sembler"], "explanation": "Selon les docètes, le Christ aurait seulement semblé avoir un corps.", "tip": "Dokein = sembler.", "extraExample": {"text": "Un fantôme semble avoir un corps, sans en avoir.", "translation": "Voilà l''idée des docètes."}, "options": ["croire", "connaître", "enseigner", "sembler"], "id": "eg.l14.e08", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e09', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.docetisme']::text[], 'mcq', 'lesson', 'Pourquoi le docétisme détruit-il le salut ?', array['sans vrai corps, pas de vraie passion']::text[], 'Si le Christ n''a pas souffert vraiment, sa mort ne sauve personne. L''Évangile dit : « Le Verbe s''est fait chair ».', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.docetisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi le docétisme détruit-il le salut ?", "promptLanguage": "fr", "answer": "sans vrai corps, pas de vraie passion", "acceptedAnswers": ["sans vrai corps, pas de vraie passion"], "explanation": "Si le Christ n''a pas souffert vraiment, sa mort ne sauve personne. L''Évangile dit : « Le Verbe s''est fait chair ».", "tip": "Pas de corps = pas de salut.", "extraExample": {"text": "Un fantôme ne peut pas souffrir.", "translation": "Donc rien n''est racheté."}, "options": ["sans vrai corps, pas de vraie passion", "il supprime les sacrements", "il interdit l''Écriture", "il nie les miracles"], "id": "eg.l14.e09", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e10', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.ignace_d_antioche']::text[], 'mcq', 'lesson', 'Qui combat le docétisme parmi les Pères apostoliques ?', array['Ignace d''Antioche']::text[], 'Dans ses lettres, Ignace insiste : le Christ est vraiment né, vraiment mort, vraiment ressuscité.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.ignace_d_antioche"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui combat le docétisme parmi les Pères apostoliques ?", "promptLanguage": "fr", "answer": "Ignace d''Antioche", "acceptedAnswers": ["Ignace d''Antioche"], "explanation": "Dans ses lettres, Ignace insiste : le Christ est vraiment né, vraiment mort, vraiment ressuscité.", "tip": "Ignace = corps réel.", "extraExample": {"text": "Il écrit ses lettres en route vers le martyre.", "translation": "Il ne veut pas que le Christ soit un fantôme."}, "options": ["Clément de Rome", "Ignace d''Antioche", "Tertullien", "Justin Martyr"], "id": "eg.l14.e10", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e11', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.contre_les_heresies']::text[], 'mcq', 'lesson', 'Qui écrit Contre les hérésies vers 180 ?', array['Irénée de Lyon']::text[], 'Irénée, disciple de Polycarpe, réfute le gnosticisme en opposant l''enseignement public des évêques aux doctrines secrètes.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.contre_les_heresies"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui écrit Contre les hérésies vers 180 ?", "promptLanguage": "fr", "answer": "Irénée de Lyon", "acceptedAnswers": ["Irénée de Lyon"], "explanation": "Irénée, disciple de Polycarpe, réfute le gnosticisme en opposant l''enseignement public des évêques aux doctrines secrètes.", "tip": "Irénée = Contre les hérésies.", "extraExample": {"text": "Irénée devient évêque de Lyon après Pothin.", "translation": "Il est un maillon de la chaîne apostolique."}, "options": ["Polycarpe de Smyrne", "Tertullien", "Irénée de Lyon", "Marcion"], "id": "eg.l14.e11", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e12', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.nag_hammadi']::text[], 'mcq', 'lesson', 'Où est retrouvée en 1945 une bibliothèque de textes gnostiques ?', array['à Nag Hammadi']::text[], 'Nag Hammadi est en Haute-Égypte : on y a retrouvé des textes gnostiques en copte.', 3, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.nag_hammadi"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Où est retrouvée en 1945 une bibliothèque de textes gnostiques ?", "promptLanguage": "fr", "answer": "à Nag Hammadi", "acceptedAnswers": ["à Nag Hammadi"], "explanation": "Nag Hammadi est en Haute-Égypte : on y a retrouvé des textes gnostiques en copte.", "tip": "Nag Hammadi = Égypte.", "extraExample": {"text": "Les textes étaient cachés dans des jarres.", "translation": "Ils sont aujourd''hui étudiés."}, "options": ["à Smyrne", "à Antioche", "à Carthage", "à Nag Hammadi"], "id": "eg.l14.e12", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e13', 'eg', 'eg.l14', 'eg.v.culte_de_l_empereur', array['eg.v.culte_de_l_empereur']::text[], 'mcq', 'lesson', 'Quelle est la cause profonde des persécutions romaines ?', array['Ils refusent le culte de l''empereur']::text[], 'Rappel : les chrétiens refusent le culte de l''empereur, ce que l''Empire prend pour une menace.', 3, '{"unitIds": ["eg.v.culte_de_l_empereur"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la cause profonde des persécutions romaines ?", "promptLanguage": "fr", "answer": "Ils refusent le culte de l''empereur", "acceptedAnswers": ["Ils refusent le culte de l''empereur"], "explanation": "Rappel : les chrétiens refusent le culte de l''empereur, ce que l''Empire prend pour une menace.", "tip": "Refus du culte.", "extraExample": {"text": "Ils prient pour l''empereur sans l''adorer.", "translation": "C''est insuffisant pour Rome."}, "options": ["Ils refusent le culte de l''empereur", "Ils refusent de payer l''impôt", "Ils sont trop riches", "Ils parlent grec"], "id": "eg.l14.e13", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e14', 'eg', 'eg.l14', 'eg.v.apologetique', array['eg.v.apologetique']::text[], 'mcq', 'lesson', 'Comment s''appelle l''écrivain de Carthage qui défend les chrétiens dans l''Apologétique ?', array['Tertullien']::text[], 'Rappel de la leçon sur les apologistes : Tertullien écrit l''Apologétique en 197.', 3, '{"unitIds": ["eg.v.apologetique"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''appelle l''écrivain de Carthage qui défend les chrétiens dans l''Apologétique ?", "promptLanguage": "fr", "answer": "Tertullien", "acceptedAnswers": ["Tertullien"], "explanation": "Rappel de la leçon sur les apologistes : Tertullien écrit l''Apologétique en 197.", "tip": "Apologétique = Tertullien.", "extraExample": {"text": "Justin écrit des Apologies.", "translation": "Tertullien, une Apologétique."}, "options": ["Justin", "Tertullien", "Ignace", "Irénée"], "id": "eg.l14.e14", "pool": "lesson", "lessonId": "eg.l14", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e15', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.gnose']::text[], 'fill_blank', 'lesson', 'Gnosis veut dire ___.', array['connaissance']::text[], 'Le gnosticisme vient de ce mot.', 1, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.gnose"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Gnosis veut dire ___.", "promptLanguage": "fr", "answer": "connaissance", "acceptedAnswers": ["connaissance"], "explanation": "Le gnosticisme vient de ce mot.", "tip": "Gnose = savoir.", "extraExample": {"text": "Agnostique = sans savoir.", "translation": "Même racine."}, "options": ["prière", "silence", "justice", "connaissance"], "id": "eg.l14.e15", "pool": "lesson", "lessonId": "eg.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e16', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.demiurge']::text[], 'fill_blank', 'lesson', 'Selon les gnostiques, le monde a été créé par le ___.', array['démiurge']::text[], 'Un dieu inférieur, artisan du monde matériel.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.demiurge"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Selon les gnostiques, le monde a été créé par le ___.", "promptLanguage": "fr", "answer": "démiurge", "acceptedAnswers": ["démiurge"], "explanation": "Un dieu inférieur, artisan du monde matériel.", "tip": "Démiurge = artisan.", "extraExample": {"text": "Demiourgos signifie artisan.", "translation": "Un artisan imparfait pour les gnostiques."}, "options": ["démiurge", "Verbe", "Paraclet", "prophète"], "id": "eg.l14.e16", "pool": "lesson", "lessonId": "eg.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e17', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.docetisme']::text[], 'fill_blank', 'lesson', 'Les docètes disent que le Christ n''avait qu''un corps ___.', array['apparent']::text[], 'Un corps seulement apparent, comme un fantôme.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.docetisme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les docètes disent que le Christ n''avait qu''un corps ___.", "promptLanguage": "fr", "answer": "apparent", "acceptedAnswers": ["apparent"], "explanation": "Un corps seulement apparent, comme un fantôme.", "tip": "Apparent = en apparence.", "extraExample": {"text": "Le Christ a un vrai corps.", "translation": "Il ressuscite avec ce corps."}, "options": ["glorieux", "apparent", "céleste", "double"], "id": "eg.l14.e17", "pool": "lesson", "lessonId": "eg.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e18', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.irenee_de_lyon']::text[], 'fill_blank', 'lesson', 'Irénée est évêque de ___.', array['Lyon']::text[], 'Irénée, disciple de Polycarpe, devient évêque de Lyon après Pothin.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.irenee_de_lyon"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Irénée est évêque de ___.", "promptLanguage": "fr", "answer": "Lyon", "acceptedAnswers": ["Lyon"], "explanation": "Irénée, disciple de Polycarpe, devient évêque de Lyon après Pothin.", "tip": "Irénée = Lyon.", "extraExample": {"text": "Lyon est une ville de Gaule.", "translation": "Les martyrs de Lyon meurent en 177."}, "options": ["Rome", "Smyrne", "Lyon", "Carthage"], "id": "eg.l14.e18", "pool": "lesson", "lessonId": "eg.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e19', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.docetisme']::text[], 'reorder', 'lesson', 'Reconstitue la phrase-repère (eg.l14).', array['Le Christ a eu un corps réel']::text[], 'C''est la réponse de l''Église au docétisme.', 3, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.docetisme"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre.", "prompt": "Reconstitue la phrase-repère (eg.l14).", "promptLanguage": "fr", "answer": "Le Christ a eu un corps réel", "acceptedAnswers": ["Le Christ a eu un corps réel"], "explanation": "C''est la réponse de l''Église au docétisme.", "tip": "Corps réel.", "extraExample": {"text": "Ignace insiste sur le vrai corps du Christ.", "translation": "Contre les docètes."}, "tokens": ["a", "eu", "un", "Le", "Christ", "corps", "réel"], "id": "eg.l14.e19", "pool": "lesson", "lessonId": "eg.l14", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e20', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.docetisme']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on l''erreur selon laquelle le corps du Christ n''était qu''apparent ?', array['le docétisme','docétisme','docetisme','le docetisme']::text[], 'Du grec dokein, « sembler ».', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.docetisme"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on l''erreur selon laquelle le corps du Christ n''était qu''apparent ?", "promptLanguage": "fr", "answer": "le docétisme", "acceptedAnswers": ["le docétisme", "docétisme", "docetisme", "le docetisme"], "explanation": "Du grec dokein, « sembler ».", "tip": "Docétisme = corps apparent.", "extraExample": {"text": "Ignace le combat.", "translation": "Il écrit sept lettres."}, "id": "eg.l14.e20", "pool": "lesson", "lessonId": "eg.l14", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e21', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.gnose']::text[], 'free_answer', 'lesson', 'Quel mot grec signifie « connaissance » et donne gnosticisme ?', array['gnosis','gnose','la gnose','la gnosis']::text[], 'Le gnosticisme est la doctrine du salut par la gnose.', 2, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.gnose"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot grec signifie « connaissance » et donne gnosticisme ?", "promptLanguage": "fr", "answer": "gnosis", "acceptedAnswers": ["gnosis", "gnose", "la gnose", "la gnosis"], "explanation": "Le gnosticisme est la doctrine du salut par la gnose.", "tip": "Gnosis = connaissance.", "extraExample": {"text": "Les gnostiques sont des « connaisseurs ».", "translation": "Ils se croient une élite."}, "id": "eg.l14.e21", "pool": "lesson", "lessonId": "eg.l14", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l14.e22', 'eg', 'eg.l14', 'eg.g14.gnosticisme_docetisme', array['eg.g14.gnosticisme_docetisme','eg.v.irenee_de_lyon']::text[], 'free_answer', 'lesson', 'Qui est l''évêque de Lyon, disciple de Polycarpe, qui réfute les gnostiques ?', array['Irénée','Irénée de Lyon','saint Irénée','Irenee']::text[], 'Irénée écrit Contre les hérésies vers 180.', 3, '{"unitIds": ["eg.g14.gnosticisme_docetisme", "eg.v.irenee_de_lyon"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Qui est l''évêque de Lyon, disciple de Polycarpe, qui réfute les gnostiques ?", "promptLanguage": "fr", "answer": "Irénée", "acceptedAnswers": ["Irénée", "Irénée de Lyon", "saint Irénée", "Irenee"], "explanation": "Irénée écrit Contre les hérésies vers 180.", "tip": "Irénée = Lyon.", "extraExample": {"text": "Il succède à Pothin.", "translation": "Il est maillon de la chaîne apostolique."}, "id": "eg.l14.e22", "pool": "lesson", "lessonId": "eg.l14", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e01', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan']::text[], 'match', 'lesson', 'Marcion ou Montan ?', '{}'::text[], 'Chaque hérésie a ses acteurs et ses idées.', 1, '{"unitIds": ["eg.g15.marcion_montan"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Marcion ou Montan ?", "promptLanguage": "fr", "answer": "Marcion = oppose le Dieu de justice au Dieu d''amour ; Montanus = se dit organe du Paraclet ; Priscilla et Maximilla = prophétesses qui accompagnent Montanus ; Le Paraclet = l''Esprit Saint, Consolateur", "acceptedAnswers": [], "explanation": "Chaque hérésie a ses acteurs et ses idées.", "tip": "Marcion = dieux ; Montan = Esprit.", "pairs": [{"left": "Marcion", "right": "oppose le Dieu de justice au Dieu d''amour"}, {"left": "Montanus", "right": "se dit organe du Paraclet"}, {"left": "Priscilla et Maximilla", "right": "prophétesses qui accompagnent Montanus"}, {"left": "Le Paraclet", "right": "l''Esprit Saint, Consolateur"}], "id": "eg.l15.e01", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e02', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.gnosticisme','eg.v.docetisme','eg.v.marcionisme','eg.v.montanisme']::text[], 'match', 'lesson', 'Quelle est l''erreur ?', '{}'::text[], 'Récapitulatif des quatre hérésies du siècle.', 2, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.gnosticisme", "eg.v.docetisme", "eg.v.marcionisme", "eg.v.montanisme"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle est l''erreur ?", "promptLanguage": "fr", "answer": "Gnosticisme = salut par une connaissance secrète ; Docétisme = le Christ n''a qu''un corps apparent ; Marcionisme = deux dieux, rejet de l''Ancien Testament ; Montanisme = nouvelle prophétie et fin des temps", "acceptedAnswers": [], "explanation": "Récapitulatif des quatre hérésies du siècle.", "tip": "G-D-Ma-Mo.", "pairs": [{"left": "Gnosticisme", "right": "salut par une connaissance secrète"}, {"left": "Docétisme", "right": "le Christ n''a qu''un corps apparent"}, {"left": "Marcionisme", "right": "deux dieux, rejet de l''Ancien Testament"}, {"left": "Montanisme", "right": "nouvelle prophétie et fin des temps"}], "id": "eg.l15.e02", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e03', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.marcion']::text[], 'mcq', 'lesson', 'Quel est le métier de Marcion avant de venir à Rome ?', array['armateur']::text[], 'Marcion, né à Sinope sur la mer Noire, est un riche armateur.', 1, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.marcion"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le métier de Marcion avant de venir à Rome ?", "promptLanguage": "fr", "answer": "armateur", "acceptedAnswers": ["armateur"], "explanation": "Marcion, né à Sinope sur la mer Noire, est un riche armateur.", "tip": "Marcion = armateur.", "extraExample": {"text": "Il donne de l''argent à l''Église de Rome.", "translation": "L''Église le lui rend en l''excluant."}, "options": ["prêtre", "soldat", "armateur", "médecin"], "id": "eg.l15.e03", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e04', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.marcionisme']::text[], 'mcq', 'lesson', 'Que croit Marcion à propos de Dieu ?', array['un Dieu de justice et un Dieu d''amour']::text[], 'Il sépare le Dieu créateur de l''Ancien Testament, juste et sévère, du Dieu d''amour du Nouveau Testament, Père de Jésus.', 2, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.marcionisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que croit Marcion à propos de Dieu ?", "promptLanguage": "fr", "answer": "un Dieu de justice et un Dieu d''amour", "acceptedAnswers": ["un Dieu de justice et un Dieu d''amour"], "explanation": "Il sépare le Dieu créateur de l''Ancien Testament, juste et sévère, du Dieu d''amour du Nouveau Testament, Père de Jésus.", "tip": "Marcion = deux dieux.", "extraExample": {"text": "Pour l''Église, c''est le même Dieu.", "translation": "Il est juste et bon."}, "options": ["un seul Dieu en trois personnes", "aucun dieu", "un dieu pour chaque peuple", "un Dieu de justice et un Dieu d''amour"], "id": "eg.l15.e04", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e05', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.marcionisme']::text[], 'mcq', 'lesson', 'Quels textes Marcion garde-t-il ?', array['Luc et dix lettres de Paul']::text[], 'Il retire tout le reste : l''Ancien Testament et presque tout le Nouveau Testament.', 2, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.marcionisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quels textes Marcion garde-t-il ?", "promptLanguage": "fr", "answer": "Luc et dix lettres de Paul", "acceptedAnswers": ["Luc et dix lettres de Paul"], "explanation": "Il retire tout le reste : l''Ancien Testament et presque tout le Nouveau Testament.", "tip": "Marcion = Luc + Paul.", "extraExample": {"text": "Marcion corrige aussi l''évangile de Luc.", "translation": "Il en retire ce qui rappelle l''Ancien Testament."}, "options": ["Luc et dix lettres de Paul", "Matthieu et Jean", "tout l''Ancien Testament", "les quatre Évangiles"], "id": "eg.l15.e05", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e06', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.tertullien']::text[], 'mcq', 'lesson', 'Qui écrit Contre Marcion ?', array['Tertullien']::text[], 'Tertullien consacre cinq livres à réfuter Marcion et à défendre l''unité des deux Testaments.', 2, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.tertullien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui écrit Contre Marcion ?", "promptLanguage": "fr", "answer": "Tertullien", "acceptedAnswers": ["Tertullien"], "explanation": "Tertullien consacre cinq livres à réfuter Marcion et à défendre l''unité des deux Testaments.", "tip": "Tertullien contre Marcion.", "extraExample": {"text": "Polycarpe le traite de premier-né de Satan.", "translation": "Les deux le combattent."}, "options": ["Polycarpe", "Tertullien", "Ignace", "Clément"], "id": "eg.l15.e06", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e07', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.montanus']::text[], 'mcq', 'lesson', 'Où Montanus prophétise-t-il vers 170 ?', array['en Phrygie']::text[], 'La Phrygie est une région d''Asie Mineure, dans l''actuelle Turquie.', 2, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.montanus"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où Montanus prophétise-t-il vers 170 ?", "promptLanguage": "fr", "answer": "en Phrygie", "acceptedAnswers": ["en Phrygie"], "explanation": "La Phrygie est une région d''Asie Mineure, dans l''actuelle Turquie.", "tip": "Montan = Phrygie.", "extraExample": {"text": "Smyrne est aussi en Asie Mineure.", "translation": "Les Églises voisines condamnent Montan."}, "options": ["à Rome", "en Égypte", "en Phrygie", "en Gaule"], "id": "eg.l15.e07", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e08', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.paraclet']::text[], 'mcq', 'lesson', 'Qui est le Paraclet ?', array['l''Esprit Saint']::text[], 'Le Paraclet est le Consolateur promis par Jésus (Jean 14, 26) : l''Esprit Saint.', 2, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.paraclet"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le Paraclet ?", "promptLanguage": "fr", "answer": "l''Esprit Saint", "acceptedAnswers": ["l''Esprit Saint"], "explanation": "Le Paraclet est le Consolateur promis par Jésus (Jean 14, 26) : l''Esprit Saint.", "tip": "Paraclet = Esprit.", "extraExample": {"text": "Montanus se dit son porte-parole.", "translation": "L''Église dénonce cette prétention."}, "options": ["l''empereur", "un apôtre", "un évêque", "l''Esprit Saint"], "id": "eg.l15.e08", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e09', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.millenarisme']::text[], 'mcq', 'lesson', 'Que croit le millénarisme ?', array['un règne du Christ de mille ans avec les élus']::text[], 'Les montanistes attendent la fin des temps et un règne de mille ans.', 2, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.millenarisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que croit le millénarisme ?", "promptLanguage": "fr", "answer": "un règne du Christ de mille ans avec les élus", "acceptedAnswers": ["un règne du Christ de mille ans avec les élus"], "explanation": "Les montanistes attendent la fin des temps et un règne de mille ans.", "tip": "Millénium = mille ans.", "extraExample": {"text": "L''Église ne rejette pas la fin des temps.", "translation": "Elle rejette les dates et les prétentions."}, "options": ["un règne du Christ de mille ans avec les élus", "la fin de toute persécution", "le retour de Moïse", "la fin de l''Église"], "id": "eg.l15.e09", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l15.e10', 'eg', 'eg.l15', 'eg.g15.marcion_montan', array['eg.g15.marcion_montan','eg.v.montanisme']::text[], 'mcq', 'lesson', 'Pourquoi l''Église refuse-t-elle les « nouvelles prophéties » de Montan ?', array['la Révélation est complète en Christ et les apôtres']::text[], 'L''Esprit ne donne pas une révélation supérieure à celle des apôtres ; il aide à comprendre ce qui est déjà donné.', 3, '{"unitIds": ["eg.g15.marcion_montan", "eg.v.montanisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Église refuse-t-elle les « nouvelles prophéties » de Montan ?", "promptLanguage": "fr", "answer": "la Révélation est complète en Christ et les apôtres", "acceptedAnswers": ["la Révélation est complète en Christ et les apôtres"], "explanation": "L''Esprit ne donne pas une révélation supérieure à celle des apôtres ; il aide à comprendre ce qui est déjà donné.", "tip": "Révélation complète.", "extraExample": {"text": "L''Église reconnaît la prophétie, mais pas une révélation nouvelle.", "translation": "Elle teste les prophètes."}, "options": ["l''Esprit Saint n''existe pas", "la Révélation est complète en Christ et les apôtres", "les femmes ne peuvent pas prier", "la prophétie est interdite"], "id": "eg.l15.e10", "pool": "lesson", "lessonId": "eg.l15", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = exclud