insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e03', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.canon_des_ecritures']::text[], 'mcq', 'lesson', 'Que signifie le mot grec kanôn ?', array['règle']::text[], 'Le canon est la règle des livres reconnus par l''Église.', 1, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.canon_des_ecritures"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie le mot grec kanôn ?", "promptLanguage": "fr", "answer": "règle", "acceptedAnswers": ["règle"], "explanation": "Le canon est la règle des livres reconnus par l''Église.", "tip": "Canon = règle.", "extraExample": {"text": "Le mot « canon » est aussi utilisé pour les règles de l''Église.", "translation": "Canon veut dire mesure."}, "options": ["livre", "évêque", "règle", "chant"], "id": "eg.l16.e03", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e04', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.canon_des_ecritures']::text[], 'mcq', 'lesson', 'Qui pousse l''Église à préciser la liste de ses livres saints ?', array['Marcion']::text[], 'Marcion propose sa liste réduite (Luc et dix lettres de Paul) : l''Église doit dire clairement quels livres elle reçoit.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.canon_des_ecritures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui pousse l''Église à préciser la liste de ses livres saints ?", "promptLanguage": "fr", "answer": "Marcion", "acceptedAnswers": ["Marcion"], "explanation": "Marcion propose sa liste réduite (Luc et dix lettres de Paul) : l''Église doit dire clairement quels livres elle reçoit.", "tip": "Marcion = liste.", "extraExample": {"text": "Les gnostiques inventent aussi des évangiles.", "translation": "L''Église doit trier."}, "options": ["Justin", "Ignace", "Clément", "Marcion"], "id": "eg.l16.e04", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e05', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.canon_des_ecritures']::text[], 'mcq', 'lesson', 'Quel critère retient l''Église pour un livre du canon ?', array['l''origine apostolique']::text[], 'Un livre doit venir d''un apôtre ou d''un proche, être conforme à la foi et être lu dans les Églises.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.canon_des_ecritures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel critère retient l''Église pour un livre du canon ?", "promptLanguage": "fr", "answer": "l''origine apostolique", "acceptedAnswers": ["l''origine apostolique"], "explanation": "Un livre doit venir d''un apôtre ou d''un proche, être conforme à la foi et être lu dans les Églises.", "tip": "Apostolique, conforme, utilisé.", "extraExample": {"text": "Un texte tardif ne peut être reçu comme apostolique.", "translation": "Même s''il est beau."}, "options": ["l''origine apostolique", "la beauté du style", "la richesse de l''auteur", "la décision de l''empereur"], "id": "eg.l16.e05", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e06', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.canon_des_ecritures']::text[], 'mcq', 'lesson', 'Combien d''Évangiles Irénée défend-il ?', array['quatre']::text[], 'Pour Irénée, ni plus ni moins que quatre, comme les quatre vents et les quatre coins de la terre.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.canon_des_ecritures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''Évangiles Irénée défend-il ?", "promptLanguage": "fr", "answer": "quatre", "acceptedAnswers": ["quatre"], "explanation": "Pour Irénée, ni plus ni moins que quatre, comme les quatre vents et les quatre coins de la terre.", "tip": "Quatre Évangiles.", "extraExample": {"text": "Les gnostiques en inventent d''autres.", "translation": "L''Église n''en reçoit que quatre."}, "options": ["trois", "quatre", "cinq", "douze"], "id": "eg.l16.e06", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e07', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.fragment_de_muratori']::text[], 'mcq', 'lesson', 'De quelle ville vient le Fragment de Muratori, une des plus anciennes listes du Nouveau Testament ?', array['Rome']::text[], 'Le Fragment de Muratori (vers 170-200) vient de Rome : il montre que les Évangiles y étaient déjà reçus.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.fragment_de_muratori"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "De quelle ville vient le Fragment de Muratori, une des plus anciennes listes du Nouveau Testament ?", "promptLanguage": "fr", "answer": "Rome", "acceptedAnswers": ["Rome"], "explanation": "Le Fragment de Muratori (vers 170-200) vient de Rome : il montre que les Évangiles y étaient déjà reçus.", "tip": "Muratori = Rome.", "extraExample": {"text": "Le canon se précise peu à peu.", "translation": "Le Fragment est un jalon."}, "options": ["Alexandrie", "Antioche", "Rome", "Carthage"], "id": "eg.l16.e07", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e08', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.canon_des_ecritures']::text[], 'mcq', 'lesson', 'Qui donne la liste des 27 livres du Nouveau Testament en 367 ?', array['saint Athanase']::text[], 'Athanase, patriarche d''Alexandrie, la donne dans sa lettre pascale de 367.', 3, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.canon_des_ecritures"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui donne la liste des 27 livres du Nouveau Testament en 367 ?", "promptLanguage": "fr", "answer": "saint Athanase", "acceptedAnswers": ["saint Athanase"], "explanation": "Athanase, patriarche d''Alexandrie, la donne dans sa lettre pascale de 367.", "tip": "Athanase = 27 livres.", "extraExample": {"text": "Athanase est aussi le défenseur de Nicée.", "translation": "Tu le retrouveras au IVe siècle."}, "options": ["saint Marc", "saint Démétrios", "saint Polycarpe", "saint Athanase"], "id": "eg.l16.e08", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e09', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.regle_de_foi']::text[], 'mcq', 'lesson', 'Qu''est-ce que la règle de foi ?', array['un résumé de la foi reçue au baptême']::text[], 'Un seul Dieu Père, le Christ vraiment homme, mort et ressuscité, l''Esprit Saint : elle est la racine du Credo.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.regle_de_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce que la règle de foi ?", "promptLanguage": "fr", "answer": "un résumé de la foi reçue au baptême", "acceptedAnswers": ["un résumé de la foi reçue au baptême"], "explanation": "Un seul Dieu Père, le Christ vraiment homme, mort et ressuscité, l''Esprit Saint : elle est la racine du Credo.", "tip": "Règle de foi → Credo.", "extraExample": {"text": "Elle est confessée par les baptisés.", "translation": "Elle précède le Credo écrit."}, "options": ["un résumé de la foi reçue au baptême", "une loi de l''empereur", "la liste des évêques", "une prière du soir"], "id": "eg.l16.e09", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e10', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.regle_de_foi']::text[], 'mcq', 'lesson', 'Qu''obtiennent les hérétiques en déplaçant les pierres de la mosaïque d''Irénée ?', array['un renard']::text[], 'Les hérétiques déplacent les pierres de l''Écriture. La règle de foi est le plan du roi.', 3, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.regle_de_foi"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''obtiennent les hérétiques en déplaçant les pierres de la mosaïque d''Irénée ?", "promptLanguage": "fr", "answer": "un renard", "acceptedAnswers": ["un renard"], "explanation": "Les hérétiques déplacent les pierres de l''Écriture. La règle de foi est le plan du roi.", "tip": "Mosaïque = Écriture.", "extraExample": {"text": "Les mêmes versets peuvent former deux images.", "translation": "Il faut le plan."}, "options": ["un roi", "un renard", "une croix", "un navire"], "id": "eg.l16.e10", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e11', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.saint_demetrios']::text[], 'mcq', 'lesson', 'Pourquoi Démétrios est-il surnommé le vigneron ?', array['une grappe de raisin hors saison']::text[], 'Le pape Julien avait été prévenu par un ange : un homme viendrait avec une grappe de raisin hors saison.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.saint_demetrios"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Démétrios est-il surnommé le vigneron ?", "promptLanguage": "fr", "answer": "une grappe de raisin hors saison", "acceptedAnswers": ["une grappe de raisin hors saison"], "explanation": "Le pape Julien avait été prévenu par un ange : un homme viendrait avec une grappe de raisin hors saison.", "tip": "Raisin = vigneron.", "extraExample": {"text": "Selon la tradition, Démétrios était un simple paysan.", "translation": "Dieu l''a instruit."}, "options": ["il possédait une grande vigne", "il a planté la première vigne en Égypte", "une grappe de raisin hors saison", "il fabriquait le vin de la messe"], "id": "eg.l16.e11", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e12', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.date_de_paques']::text[], 'mcq', 'lesson', 'Quels sont les deux usages pour la date de Pâques ?', array['le 14 Nisan ou le dimanche suivant']::text[], 'Les Églises d''Asie Mineure fêtent le 14 Nisan, d''autres le dimanche suivant.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.date_de_paques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quels sont les deux usages pour la date de Pâques ?", "promptLanguage": "fr", "answer": "le 14 Nisan ou le dimanche suivant", "acceptedAnswers": ["le 14 Nisan ou le dimanche suivant"], "explanation": "Les Églises d''Asie Mineure fêtent le 14 Nisan, d''autres le dimanche suivant.", "tip": "14 Nisan / dimanche.", "extraExample": {"text": "Rome et Alexandrie fêtent le dimanche.", "translation": "Polycarpe suit le 14 Nisan."}, "options": ["le samedi ou le lundi", "le 1er janvier ou le 25 décembre", "le jour de la Pentecôte ou de l''Ascension", "le 14 Nisan ou le dimanche suivant"], "id": "eg.l16.e12", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e13', 'eg', 'eg.l16', 'eg.v.saint_marc', array['eg.v.saint_marc']::text[], 'mcq', 'lesson', 'Qui a fondé, selon la tradition, l''école théologique d''Alexandrie ?', array['saint Marc']::text[], 'La tradition attribue la fondation de l''école à saint Marc ; elle renaît vers 190 sous Démétrios.', 3, '{"unitIds": ["eg.v.saint_marc"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui a fondé, selon la tradition, l''école théologique d''Alexandrie ?", "promptLanguage": "fr", "answer": "saint Marc", "acceptedAnswers": ["saint Marc"], "explanation": "La tradition attribue la fondation de l''école à saint Marc ; elle renaît vers 190 sous Démétrios.", "tip": "Marc fonde, Démétrios relance.", "extraExample": {"text": "Pantène, Clément et Origène l''illustrent.", "translation": "Elle sera au cœur du module suivant."}, "options": ["saint Marc", "saint Démétrios", "saint Athanase", "saint Polycarpe"], "id": "eg.l16.e13", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e14', 'eg', 'eg.l16', 'eg.v.docetisme', array['eg.v.docetisme']::text[], 'mcq', 'lesson', 'Quelle hérésie nie l''humanité réelle du Christ ?', array['le docétisme']::text[], 'Rappel : le docétisme dit que le Christ n''avait qu''un corps apparent.', 3, '{"unitIds": ["eg.v.docetisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle hérésie nie l''humanité réelle du Christ ?", "promptLanguage": "fr", "answer": "le docétisme", "acceptedAnswers": ["le docétisme"], "explanation": "Rappel : le docétisme dit que le Christ n''avait qu''un corps apparent.", "tip": "Docète = fantôme.", "extraExample": {"text": "Ignace le combat.", "translation": "Le Christ a eu un vrai corps."}, "options": ["le marcionisme", "le docétisme", "le montanisme", "l''arianisme"], "id": "eg.l16.e14", "pool": "lesson", "lessonId": "eg.l16", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
