insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e16', 'eg', 'eg.l16', 'eg.g16.canon_regle_de_foi', array['eg.g16.canon_regle_de_foi','eg.v.saint_demetrios']::text[], 'fill_blank', 'lesson', 'Démétrios devient évêque d''Alexandrie en ___.', array['189']::text[], '189 est la date à retenir pour Démétrios, XIIe pape.', 2, '{"unitIds": ["eg.g16.canon_regle_de_foi", "eg.v.saint_demetrios"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Démétrios devient évêque d''Alexandrie en ___.", "promptLanguage": "fr", "answer": "189", "acceptedAnswers": ["189"], "explanation": "189 est la date à retenir pour Démétrios, XIIe pape.", "tip": "189 = Démétrios.", "extraExample": {"text": "197 est l''Apologétique de Tertullien.", "translation": "367 est la lettre d''Athanase."}, "options": ["189", "155", "197", "367"], "id": "eg.l16.e16", "pool": "lesson", "lessonId": "eg.l16", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
