insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l16.e18', 'eg', 'eg.l16', 'eg.v.montanisme', array['eg.v.montanisme']::text[], 'fill_blank', 'lesson', 'Les quatre hérésies sont gnosticisme, docétisme, marcionisme et ___.', array['montanisme']::text[], 'Rappel de toutes les leçons précédentes.', 2, '{"unitIds": ["eg.v.montanisme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les quatre hérésies sont gnosticisme, docétisme, marcionisme et ___.", "promptLanguage": "fr", "answer": "montanisme", "acceptedAnswers": ["montanisme"], "explanation": "Rappel de toutes les leçons précédentes.", "tip": "G-D-Ma-Mo.", "extraExample": {"text": "Chaque hérésie touche un point essentiel.", "translation": "Salut, Christ, Dieu, Esprit."}, "options": ["arianisme", "nestorianisme", "montanisme", "pélagianisme"], "id": "eg.l16.e18", "pool": "lesson", "lessonId": "eg.l16", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
