insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l18.e07', 'eg', 'eg.l18', 'eg.g18.edits_de_maximin_a_valerien', array['eg.g18.edits_de_maximin_a_valerien','eg.v.edit_de_dece']::text[], 'mcq', 'lesson', 'Pourquoi Dèce rend-il le culte impérial obligatoire en 250 ?', array['Souder la population de l''empire contre les dangers extérieurs']::text[], 'L''Empire est menacé : en obligeant tout le monde à sacrifier, Dèce veut unir la population.', 3, '{"id": "eg.l18.e07", "unitIds": ["eg.g18.edits_de_maximin_a_valerien", "eg.v.edit_de_dece"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Dèce rend-il le culte impérial obligatoire en 250 ?", "promptLanguage": "fr", "answer": "Souder la population de l''empire contre les dangers extérieurs", "acceptedAnswers": ["Souder la population de l''empire contre les dangers extérieurs"], "explanation": "L''Empire est menacé : en obligeant tout le monde à sacrifier, Dèce veut unir la population.", "tip": "Obligation de sacrifier = union face aux dangers.", "extraExample": {"text": "Un peuple uni par un même culte est plus facile à rassembler.", "translation": "C''est la logique de l''édit."}, "options": ["Souder la population de l''empire contre les dangers extérieurs", "Punir les évêques d''Alexandrie", "Remplacer les dieux romains", "Lever un nouvel impôt"], "pool": "lesson", "lessonId": "eg.l18", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l18.e08', 'eg', 'eg.l18', 'eg.g18.edits_de_maximin_a_valerien', array['eg.g18.edits_de_maximin_a_valerien','eg.v.libellus']::text[], 'mcq', 'lesson', 'Comment s''appelle le certificat reçu après un sacrifice sous Dèce ?', array['Le libellus']::text[], 'Le libellus est la preuve écrite qu''on a sacrifié.', 2, '{"id": "eg.l18.e08", "unitIds": ["eg.g18.edits_de_maximin_a_valerien", "eg.v.libellus"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''appelle le certificat reçu après un sacrifice sous Dèce ?", "promptLanguage": "fr", "answer": "Le libellus", "acceptedAnswers": ["Le libellus"], "explanation": "Le libellus est la preuve écrite qu''on a sacrifié.", "tip": "Libellus = petit livret certificat.", "extraExample": {"text": "Certains en achètent de faux.", "translation": "L''Église devra décider quoi faire des « tombés »."}, "options": ["Le synaxaire", "Le canon", "L''édit", "Le libellus"], "pool": "lesson", "lessonId": "eg.l18", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l18.e09', 'eg', 'eg.l18', 'eg.g18.edits_de_maximin_a_valerien', array['eg.g18.edits_de_maximin_a_valerien','eg.v.semence_de_chretiens']::text[], 'mcq', 'lesson', 'Quelle est la conséquence du courage des martyrs sur les spectateurs ?', array['De nombreuses conversions']::text[], 'Le courage des martyrs impressionne les spectateurs et entraîne de nombreuses conversions.', 2, '{"id": "eg.l18.e09", "unitIds": ["eg.g18.edits_de_maximin_a_valerien", "eg.v.semence_de_chretiens"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la conséquence du courage des martyrs sur les spectateurs ?", "promptLanguage": "fr", "answer": "De nombreuses conversions", "acceptedAnswers": ["De nombreuses conversions"], "explanation": "Le courage des martyrs impressionne les spectateurs et entraîne de nombreuses conversions.", "tip": "Martyrs → conversions.", "extraExample": {"text": "Tertullien parle de semence de chrétiens.", "translation": "La persécution fait grandir l''Église."}, "options": ["L''abandon de la foi", "Des révoltes armées", "De nombreuses conversions", "Une haine accrue"], "pool": "lesson", "lessonId": "eg.l18", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
