insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e01', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.diocletien','eg.v.grande_persecution_303']::text[], 'match', 'lesson', 'Les dates de Dioclétien', '{}'::text[], '284 : début du règne de Dioclétien ; 303 : sommet de la persécution ; les autres dates sont celles des vagues précédentes.', 1, '{"id": "eg.l19.e01", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.diocletien", "eg.v.grande_persecution_303"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les dates de Dioclétien", "promptLanguage": "fr", "pairs": [{"left": "284", "right": "accession de Dioclétien et an 1 du calendrier copte"}, {"left": "303", "right": "grande persécution"}, {"left": "vers 274", "right": "neuvième persécution"}, {"left": "250", "right": "édit de Dèce"}], "answer": "284 = accession de Dioclétien et an 1 du calendrier copte ; 303 = grande persécution ; vers 274 = neuvième persécution ; 250 = édit de Dèce", "acceptedAnswers": [], "explanation": "284 : début du règne de Dioclétien ; 303 : sommet de la persécution ; les autres dates sont celles des vagues précédentes.", "tip": "284 = début, 303 = sommet.", "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e02', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.ere_des_martyrs','eg.v.nayrouz','eg.v.dixieme_persecution']::text[], 'match', 'lesson', 'Notions coptes liées à Dioclétien', '{}'::text[], 'Le calendrier, la fête du nouvel an et la dixième persécution tournent tous autour de Dioclétien et des martyrs.', 2, '{"id": "eg.l19.e02", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.ere_des_martyrs", "eg.v.nayrouz", "eg.v.dixieme_persecution"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Notions coptes liées à Dioclétien", "promptLanguage": "fr", "pairs": [{"left": "L''ère des martyrs", "right": "le calendrier copte"}, {"left": "Le Nayrouz", "right": "le jour de l''an copte"}, {"left": "La dixième persécution", "right": "celle de Dioclétien"}, {"left": "La grande persécution", "right": "en 303"}], "answer": "L''ère des martyrs = le calendrier copte ; Le Nayrouz = le jour de l''an copte ; La dixième persécution = celle de Dioclétien ; La grande persécution = en 303", "acceptedAnswers": [], "explanation": "Le calendrier, la fête du nouvel an et la dixième persécution tournent tous autour de Dioclétien et des martyrs.", "tip": "Calendrier + jour de l''an = mémoire des martyrs.", "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e03', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.diocletien']::text[], 'mcq', 'lesson', 'En quelle année Dioclétien devient-il empereur ?', array['284']::text[], 'Dioclétien devient empereur en 284, année qui ouvre le calendrier copte.', 1, '{"id": "eg.l19.e03", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.diocletien"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Dioclétien devient-il empereur ?", "promptLanguage": "fr", "answer": "284", "acceptedAnswers": ["284"], "explanation": "Dioclétien devient empereur en 284, année qui ouvre le calendrier copte.", "tip": "284 = an 1 copte.", "extraExample": {"text": "303 est la date de la grande persécution.", "translation": "284 est son accession."}, "options": ["284", "235", "249", "303"], "errorPatterns": [{"equals": "303", "category": "word_confusion", "feedback": "303 est la grande persécution, pas l''accession."}], "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e04', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.calendrier_copte']::text[], 'mcq', 'lesson', 'Quel événement marque le début du calendrier copte ?', array['L''accession de Dioclétien']::text[], 'Les Coptes ont fait de l''année d''accession de Dioclétien (284) la première année de leur calendrier.', 2, '{"id": "eg.l19.e04", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.calendrier_copte"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel événement marque le début du calendrier copte ?", "promptLanguage": "fr", "answer": "L''accession de Dioclétien", "acceptedAnswers": ["L''accession de Dioclétien"], "explanation": "Les Coptes ont fait de l''année d''accession de Dioclétien (284) la première année de leur calendrier.", "tip": "An 1 copte = 284.", "extraExample": {"text": "Le concile de Nicée a lieu en 325.", "translation": "L''édit de Dèce date de 250."}, "options": ["La mort de saint Marc", "L''édit de Dèce", "Le concile de Nicée", "L''accession de Dioclétien"], "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e05', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.ere_des_martyrs']::text[], 'mcq', 'lesson', 'Comment appelle-t-on aussi le calendrier copte ?', array['L''ère des martyrs']::text[], 'Il garde la mémoire des martyrs de la persécution de Dioclétien.', 2, '{"id": "eg.l19.e05", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.ere_des_martyrs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on aussi le calendrier copte ?", "promptLanguage": "fr", "answer": "L''ère des martyrs", "acceptedAnswers": ["L''ère des martyrs"], "explanation": "Il garde la mémoire des martyrs de la persécution de Dioclétien.", "tip": "Ère des martyrs = calendrier copte.", "extraExample": {"text": "On dit « l''an 1743 de l''ère des martyrs ».", "translation": "Cela remplace « de notre ère »."}, "options": ["L''ère des conciles", "L''ère de Constantin", "L''ère des martyrs", "L''ère de Marc"], "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e06', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.calendrier_copte']::text[], 'mcq', 'lesson', 'Pourquoi l''Église copte a-t-elle choisi 284 comme point de départ ?', array['Pour garder la mémoire des martyrs']::text[], 'On ne célèbre pas le persécuteur mais ceux qui sont morts pour la foi.', 3, '{"id": "eg.l19.e06", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.calendrier_copte"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Église copte a-t-elle choisi 284 comme point de départ ?", "promptLanguage": "fr", "answer": "Pour garder la mémoire des martyrs", "acceptedAnswers": ["Pour garder la mémoire des martyrs"], "explanation": "On ne célèbre pas le persécuteur mais ceux qui sont morts pour la foi.", "tip": "Calendrier = mémoire, pas gloire.", "extraExample": {"text": "Le nom de l''empereur ne sert que de repère.", "translation": "Le sens est celui du témoignage."}, "options": ["Pour commémorer le baptême de Jésus", "Pour garder la mémoire des martyrs", "Pour honorer Dioclétien", "Pour fêter la fin de Rome"], "errorPatterns": [{"equals": "Pour honorer Dioclétien", "category": "word_confusion", "feedback": "Non : le calendrier honore les martyrs, pas leur persécuteur."}], "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e07', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.dixieme_persecution']::text[], 'mcq', 'lesson', 'Quel numéro porte la persécution de Dioclétien ?', array['La dixième']::text[], 'Elle clôt la liste des dix persécutions comptées par la tradition.', 2, '{"id": "eg.l19.e07", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.dixieme_persecution"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel numéro porte la persécution de Dioclétien ?", "promptLanguage": "fr", "answer": "La dixième", "acceptedAnswers": ["La dixième"], "explanation": "Elle clôt la liste des dix persécutions comptées par la tradition.", "tip": "Dioclétien = dixième.", "extraExample": {"text": "Dèce = septième.", "translation": "Valérien = huitième."}, "options": ["La dixième", "La septième", "La huitième", "La neuvième"], "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l19.e08', 'eg', 'eg.l19', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.grande_persecution_303']::text[], 'mcq', 'lesson', 'Quand éclate la grande persécution de Dioclétien ?', array['303']::text[], 'En 303, l''empereur publie les édits les plus durs : églises détruites, livres brûlés, clergé emprisonné.', 2, '{"id": "eg.l19.e08", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.grande_persecution_303"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quand éclate la grande persécution de Dioclétien ?", "promptLanguage": "fr", "answer": "303", "acceptedAnswers": ["303"], "explanation": "En 303, l''empereur publie les édits les plus durs : églises détruites, livres brûlés, clergé emprisonné.", "tip": "303 = grande persécution.", "extraExample": {"text": "284 est l''accession.", "translation": "250 est l''édit de Dèce."}, "options": ["250", "274", "284", "303"], "errorPatterns": [{"equals": "284", "category": "word_confusion", "feedback": "284 est l''accession de Dioclétien ; la grande persécution éclate en 303."}], "pool": "lesson", "lessonId": "eg.l19", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
