insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l20.e01', 'eg', 'eg.l20', 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.paul_de_thebes','eg.v.antoine']::text[], 'match', 'lesson', 'Les premiers moines : qui est qui ?', '{}'::text[], 'Paul ouvre la voie, Antoine l''élargit. Ermite et anachorète décrivent le genre de vie.', 1, '{"id": "eg.l20.e01", "unitIds": ["eg.g20.premiers_ermites", "eg.v.paul_de_thebes", "eg.v.antoine"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les premiers moines : qui est qui ?", "promptLanguage": "fr", "pairs": [{"left": "Saint Paul de Thèbes", "right": "le premier des ermites"}, {"left": "Saint Antoine", "right": "le père des moines"}, {"left": "L''ermite", "right": "celui qui vit seul au désert"}, {"left": "L''anachorète", "right": "celui qui se retire du monde"}], "answer": "Saint Paul de Thèbes = le premier des ermites ; Saint Antoine = le père des moines ; L''ermite = celui qui vit seul au désert ; L''anachorète = celui qui se retire du monde", "acceptedAnswers": [], "explanation": "Paul ouvre la voie, Antoine l''élargit. Ermite et anachorète décrivent le genre de vie.", "tip": "Paul = premier ; Antoine = père des moines.", "pool": "lesson", "lessonId": "eg.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l20.e02', 'eg', 'eg.l20', 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.fuite_au_desert','eg.v.antoine','eg.v.paul_de_thebes']::text[], 'match', 'lesson', 'Dates et événements', '{}'::text[], 'Dans l''ordre : Paul (250), Antoine (270), puis l''accession de Dioclétien (284) et la grande persécution (303).', 2, '{"id": "eg.l20.e02", "unitIds": ["eg.g20.premiers_ermites", "eg.v.fuite_au_desert", "eg.v.antoine", "eg.v.paul_de_thebes"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Dates et événements", "promptLanguage": "fr", "pairs": [{"left": "vers 250", "right": "Paul fuit au désert"}, {"left": "vers 270", "right": "Antoine part au désert"}, {"left": "284", "right": "Dioclétien devient empereur"}, {"left": "303", "right": "grande persécution"}], "answer": "vers 250 = Paul fuit au désert ; vers 270 = Antoine part au désert ; 284 = Dioclétien devient empereur ; 303 = grande persécution", "acceptedAnswers": [], "explanation": "Dans l''ordre : Paul (250), Antoine (270), puis l''accession de Dioclétien (284) et la grande persécution (303).", "tip": "250, 270, 284, 303 : une suite de 20 à 30 ans.", "pool": "lesson", "lessonId": "eg.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l20.e03', 'eg', 'eg.l20', 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.paul_de_thebes']::text[], 'mcq', 'lesson', 'Qui est le premier des ermites au désert ?', array['saint Paul de Thèbes']::text[], 'La tradition tient Paul de Thèbes pour le premier ermite, vers 250.', 1, '{"id": "eg.l20.e03", "unitIds": ["eg.g20.premiers_ermites", "eg.v.paul_de_thebes"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le premier des ermites au désert ?", "promptLanguage": "fr", "answer": "saint Paul de Thèbes", "acceptedAnswers": ["saint Paul de Thèbes"], "explanation": "La tradition tient Paul de Thèbes pour le premier ermite, vers 250.", "tip": "Paul = premier ermite.", "extraExample": {"text": "Antoine le rencontre plus tard.", "translation": "Antoine est le père des moines."}, "options": ["saint Paul de Thèbes", "saint Antoine", "saint Marc", "saint Cyprien"], "errorPatterns": [{"equals": "saint Antoine", "category": "word_confusion", "feedback": "Antoine est le père des moines, mais Paul l''a précédé au désert."}], "pool": "lesson", "lessonId": "eg.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l20.e04', 'eg', 'eg.l20', 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.fuite_au_desert']::text[], 'mcq', 'lesson', 'Pourquoi Paul quitte-t-il la ville vers 250 ? À cause de...', array['la persécution de Dèce']::text[], 'Sous Dèce, qui oblige à sacrifier, Paul fuit au désert.', 1, '{"id": "eg.l20.e04", "unitIds": ["eg.g20.premiers_ermites", "eg.v.fuite_au_desert"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Paul quitte-t-il la ville vers 250 ? À cause de...", "promptLanguage": "fr", "answer": "la persécution de Dèce", "acceptedAnswers": ["la persécution de Dèce"], "explanation": "Sous Dèce, qui oblige à sacrifier, Paul fuit au désert.", "tip": "Fuite = persécution de Dèce.", "extraExample": {"text": "Dèce est le septième persécuteur.", "translation": "Paul n''a pas voulu sacrifier."}, "options": ["un concile", "une famine", "un tremblement de terre", "la persécution de Dèce"], "pool": "lesson", "lessonId": "eg.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
