insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l20.e06', 'eg', 'eg.l20', 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.antoine']::text[], 'mcq', 'lesson', 'Vers quelle année Antoine part-il au désert ?', array['270']::text[], 'Antoine part au désert vers 270, après avoir entendu l''Évangile.', 2, '{"id": "eg.l20.e06", "unitIds": ["eg.g20.premiers_ermites", "eg.v.antoine"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quelle année Antoine part-il au désert ?", "promptLanguage": "fr", "answer": "270", "acceptedAnswers": ["270"], "explanation": "Antoine part au désert vers 270, après avoir entendu l''Évangile.", "tip": "270 = Antoine.", "extraExample": {"text": "250 est l''année de Paul.", "translation": "284 est Dioclétien."}, "options": ["303", "270", "250", "284"], "pool": "lesson", "lessonId": "eg.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l20.e07', 'eg', 'eg.l20', 'eg.g20.premiers_ermites', array['eg.g20.premiers_ermites','eg.v.antoine']::text[], 'mcq', 'lesson', 'Quelle parole de l''Évangile touche Antoine ?', array['« Va, vends ce que tu possèdes »']::text[], 'Antoine l''entend à l''église (Mt 19, 21) et la prend comme un ordre adressé à lui.', 2, '{"id": "eg.l20.e07", "unitIds": ["eg.g20.premiers_ermites", "eg.v.antoine"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle parole de l''Évangile touche Antoine ?", "promptLanguage": "fr", "answer": "« Va, vends ce que tu possèdes »", "acceptedAnswers": ["« Va, vends ce que tu possèdes »"], "explanation": "Antoine l''entend à l''église (Mt 19, 21) et la prend comme un ordre adressé à lui.", "tip": "Parole = va, vends.", "extraExample": {"text": "Il donne ses biens aux pauvres.", "translation": "Puis il part au désert."}, "options": ["« Va, vends ce que tu possèdes »", "« Rendez à César ce qui est à César »", "« Tu es Pierre »", "« Aimez-vous les uns les autres »"], "pool": "lesson", "lessonId": "eg.l20", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
