insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l22.e20', 'eg', 'eg.l22', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.tombes']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on les chrétiens qui ont renié la foi pendant la persécution ? (deux mots)', array['les tombés','tombés','tombes','les lapsi','lapsi']::text[], 'On les appelle les tombés.', 3, '{"id": "eg.l22.e20", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.tombes"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse.", "prompt": "Comment appelle-t-on les chrétiens qui ont renié la foi pendant la persécution ? (deux mots)", "promptLanguage": "fr", "answer": "les tombés", "acceptedAnswers": ["les tombés", "tombés", "tombes", "les lapsi", "lapsi"], "explanation": "On les appelle les tombés.", "tip": "Tombés = ont cédé.", "extraExample": {"text": "Leur retour fait débat.", "translation": "L''Église les reçoit s''ils sont pénitents."}, "pool": "lesson", "lessonId": "eg.l22", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
