insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l23.e01', 'eg', 'eg.l23', 'eg.g23.tradition_et_canon', array['eg.g23.tradition_et_canon','eg.v.didache','eg.v.tradition_apostolique_d_hippolyte','eg.v.didascalie']::text[], 'match', 'lesson', 'Écrits de la Tradition et leur date', '{}'::text[], 'Du Ier au IVe siècle, ces écrits suivent la vie de l''Église.', 1, '{"id": "eg.l23.e01", "unitIds": ["eg.g23.tradition_et_canon", "eg.v.didache", "eg.v.tradition_apostolique_d_hippolyte", "eg.v.didascalie"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Écrits de la Tradition et leur date", "promptLanguage": "fr", "pairs": [{"left": "La Didachè", "right": "vers 100"}, {"left": "La Tradition apostolique d''Hippolyte", "right": "vers 215"}, {"left": "La Didascalie syriaque", "right": "vers 250"}, {"left": "Les Constitutions apostoliques", "right": "vers 380"}], "answer": "La Didachè = vers 100 ; La Tradition apostolique d''Hippolyte = vers 215 ; La Didascalie syriaque = vers 250 ; Les Constitutions apostoliques = vers 380", "acceptedAnswers": [], "explanation": "Du Ier au IVe siècle, ces écrits suivent la vie de l''Église.", "tip": "100, 215, 250, 380 : de plus en plus récents.", "pool": "lesson", "lessonId": "eg.l23", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l23.e02', 'eg', 'eg.l23', 'eg.g23.tradition_et_canon', array['eg.g23.tradition_et_canon','eg.v.canon_du_nouveau_testament']::text[], 'match', 'lesson', 'Les quatre critères du canon', '{}'::text[], 'Chaque critère répond à une question : qui l''a écrit, que dit-il, est-il cohérent, qui le reçoit ?', 2, '{"id": "eg.l23.e02", "unitIds": ["eg.g23.tradition_et_canon", "eg.v.canon_du_nouveau_testament"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les quatre critères du canon", "promptLanguage": "fr", "pairs": [{"left": "Caractère apostolique", "right": "écrit par les apôtres ou sous leur contrôle"}, {"left": "Valeur spirituelle", "right": "montre l''amour du Père, pas des miracles gratuits"}, {"left": "Conformité à la doctrine", "right": "aucune contradiction avec les écrits inspirés"}, {"left": "Consensus des Églises", "right": "lu partout dans la quasi-totalité des Églises"}], "answer": "Caractère apostolique = écrit par les apôtres ou sous leur contrôle ; Valeur spirituelle = montre l''amour du Père, pas des miracles gratuits ; Conformité à la doctrine = aucune contradiction avec les écrits inspirés ; Consensus des Églises = lu partout dans la quasi-totalité des Églises", "acceptedAnswers": [], "explanation": "Chaque critère répond à une question : qui l''a écrit, que dit-il, est-il cohérent, qui le reçoit ?", "tip": "Qui ? Quoi ? Cohérent ? Accepté partout ?", "pool": "lesson", "lessonId": "eg.l23", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l23.e03', 'eg', 'eg.l23', 'eg.g23.tradition_et_canon', array['eg.g23.tradition_et_canon','eg.v.tradition_ecrite']::text[], 'mcq', 'lesson', 'Qui précède l''autre : l''Église ou le Nouveau Testament ?', array['L''Église précède le Nouveau Testament']::text[], 'Les apôtres prêchaient avant que les évangiles soient écrits.', 1, '{"id": "eg.l23.e03", "unitIds": ["eg.g23.tradition_et_canon", "eg.v.tradition_ecrite"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui précède l''autre : l''Église ou le Nouveau Testament ?", "promptLanguage": "fr", "answer": "L''Église précède le Nouveau Testament", "acceptedAnswers": ["L''Église précède le Nouveau Testament"], "explanation": "Les apôtres prêchaient avant que les évangiles soient écrits.", "tip": "L''Église d''abord, les livres ensuite.", "extraExample": {"text": "Les textes sont écrits à l''époque apostolique.", "translation": "L''Église les reconnaît ensuite."}, "options": ["L''Église précède le Nouveau Testament", "Le Nouveau Testament précède l''Église", "Ils naissent le même jour", "Le Nouveau Testament est écrit avant les apôtres"], "pool": "lesson", "lessonId": "eg.l23", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
