insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l23.e11', 'eg', 'eg.l23', 'eg.g22.novatien_et_mani', array['eg.g22.novatien_et_mani','eg.v.mani']::text[], 'mcq', 'lesson', 'Révision : quels sont les deux principes du manichéisme ?', array['Un Dieu bon et un démiurge mauvais']::text[], 'Dieu bon : les esprits. Démiurge mauvais : les corps. (Leçon 22.)', 2, '{"id": "eg.l23.e11", "unitIds": ["eg.g22.novatien_et_mani", "eg.v.mani"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision : quels sont les deux principes du manichéisme ?", "promptLanguage": "fr", "answer": "Un Dieu bon et un démiurge mauvais", "acceptedAnswers": ["Un Dieu bon et un démiurge mauvais"], "explanation": "Dieu bon : les esprits. Démiurge mauvais : les corps. (Leçon 22.)", "tip": "Bon / mauvais.", "extraExample": {"text": "Mani est un Perse.", "translation": "Augustin l''a suivi."}, "options": ["Un Dieu bon et un démiurge mauvais", "Le Père et le Fils", "L''Église et l''empire", "L''Ancien et le Nouveau Testament"], "pool": "lesson", "lessonId": "eg.l23", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
