insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l23.e19', 'eg', 'eg.l23', 'eg.g23.tradition_et_canon', array['eg.g23.tradition_et_canon','eg.v.didache']::text[], 'free_answer', 'lesson', 'Quel écrit très ancien, vers 100, retombe dans le légalisme ? (un mot)', array['Didachè','la Didachè','Didache','la Didache']::text[], 'La Didachè date d''environ 100 et retombe dans le légalisme.', 3, '{"id": "eg.l23.e19", "unitIds": ["eg.g23.tradition_et_canon", "eg.v.didache"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse.", "prompt": "Quel écrit très ancien, vers 100, retombe dans le légalisme ? (un mot)", "promptLanguage": "fr", "answer": "Didachè", "acceptedAnswers": ["Didachè", "la Didachè", "Didache", "la Didache"], "explanation": "La Didachè date d''environ 100 et retombe dans le légalisme.", "tip": "Didachè = 100, légalisme.", "extraExample": {"text": "C''est un écrit honorable.", "translation": "Il n''est pas canonique."}, "pool": "lesson", "lessonId": "eg.l23", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
