insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e05', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.hierarchie_a_trois_degres']::text[], 'mcq', 'lesson', 'Quelle est la hiérarchie au IIIe siècle ?', array['évêque, prêtre et diacre']::text[], 'Trois degrés qui s''affirment au IIIe siècle.', 2, '{"id": "eg.l24.e05", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.hierarchie_a_trois_degres"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la hiérarchie au IIIe siècle ?", "promptLanguage": "fr", "answer": "évêque, prêtre et diacre", "acceptedAnswers": ["évêque, prêtre et diacre"], "explanation": "Trois degrés qui s''affirment au IIIe siècle.", "tip": "3 degrés.", "extraExample": {"text": "Ils reprennent les anciens mots grecs.", "translation": "Épiscope, presbytre, diacre."}, "options": ["apôtre, prophète et docteur", "moine, ermite et confesseur", "évêque, prêtre et diacre", "pape, roi et soldat"], "pool": "lesson", "lessonId": "eg.l24", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
