insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e16', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.heraclas']::text[], 'fill_blank', 'lesson', 'Héraclas est le ___ évêque d''Alexandrie.', array['treizième']::text[], 'Héraclas est le 13e évêque d''Alexandrie, premier appelé pape.', 2, '{"id": "eg.l24.e16", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.heraclas"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Héraclas est le ___ évêque d''Alexandrie.", "promptLanguage": "fr", "answer": "treizième", "acceptedAnswers": ["treizième"], "explanation": "Héraclas est le 13e évêque d''Alexandrie, premier appelé pape.", "tip": "Héraclas = 13e.", "extraExample": {"text": "Denys est le 14e.", "translation": "Marc est le premier."}, "options": ["dixième", "quinzième", "treizième", "premier"], "pool": "lesson", "lessonId": "eg.l24", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
