insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e20', 'eg', 'eg.l24', 'eg.g24.structure_de_l_eglise', array['eg.g24.structure_de_l_eglise','eg.v.confesseur']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on celui qui a souffert pour sa foi sans mourir martyr ? (un mot)', array['confesseur','le confesseur']::text[], 'Le confesseur survit à la persécution.', 3, '{"id": "eg.l24.e20", "unitIds": ["eg.g24.structure_de_l_eglise", "eg.v.confesseur"], "type": "free_answer", "difficulty": 3, "instruction": "Écris la réponse.", "prompt": "Comment appelle-t-on celui qui a souffert pour sa foi sans mourir martyr ? (un mot)", "promptLanguage": "fr", "answer": "confesseur", "acceptedAnswers": ["confesseur", "le confesseur"], "explanation": "Le confesseur survit à la persécution.", "tip": "Confesseur = survivant.", "extraExample": {"text": "Le martyr meurt.", "translation": "Le confesseur est honoré."}, "pool": "lesson", "lessonId": "eg.l24", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l24.e21', 'eg', 'eg.l24', 'eg.g21.erreurs_sur_la_trinite', array['eg.g21.erreurs_sur_la_trinite','eg.v.denys_d_alexandrie']::text[], 'free_answer', 'lesson', 'Révision : quel patriarche d''Alexandrie (le 14e) écrit au concile d''Antioche ? (un prénom)', array['Denys','pape Denys','Denys d''Alexandrie']::text[], 'Denys, 14e patriarche d''Alexandrie, écrit au concile d''Antioche. (Leçon 21.)', 2, '{"id": "eg.l24.e21", "unitIds": ["eg.g21.erreurs_sur_la_trinite", "eg.v.denys_d_alexandrie"], "type": "free_answer", "difficulty": 2, "instruction": "Écris la réponse.", "prompt": "Révision : quel patriarche d''Alexandrie (le 14e) écrit au concile d''Antioche ? (un prénom)", "promptLanguage": "fr", "answer": "Denys", "acceptedAnswers": ["Denys", "pape Denys", "Denys d''Alexandrie"], "explanation": "Denys, 14e patriarche d''Alexandrie, écrit au concile d''Antioche. (Leçon 21.)", "tip": "Denys = 14e.", "extraExample": {"text": "Il combat Sabellius et Novatien.", "translation": "Il est trop âgé pour voyager."}, "pool": "lesson", "lessonId": "eg.l24", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e01', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien','eg.v.galere','eg.v.pierre_sceau_des_martyrs']::text[], 'match', 'lesson', 'Qui est qui dans la grande persécution ?', '{}'::text[], 'Dioclétien lance la persécution, Galère la poursuit, Pierre la clôt par son martyre, et Eusèbe la raconte.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien", "eg.v.galere", "eg.v.pierre_sceau_des_martyrs"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui est qui dans la grande persécution ?", "promptLanguage": "fr", "pairs": [{"left": "Dioclétien", "right": "l''empereur qui publie les quatre édits en 303"}, {"left": "Galère", "right": "son second, qui lui succède en 305"}, {"left": "Pierre d''Alexandrie", "right": "le pape « sceau des martyrs »"}, {"left": "Eusèbe de Césarée", "right": "l''historien qui décrit les martyrs d''Égypte"}], "answer": "Dioclétien = l''empereur qui publie les quatre édits en 303 ; Galère = son second, qui lui succède en 305 ; Pierre d''Alexandrie = le pape « sceau des martyrs » ; Eusèbe de Césarée = l''historien qui décrit les martyrs d''Égypte", "acceptedAnswers": [], "explanation": "Dioclétien lance la persécution, Galère la poursuit, Pierre la clôt par son martyre, et Eusèbe la raconte.", "tip": "Le trio : Dioclétien commence, Galère aggrave, Pierre clôt.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "id": "eg.l25.e01", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e02', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien','eg.v.quatre_edits']::text[], 'mcq', 'lesson', 'Quel empereur publie en 303 les quatre édits contre les chrétiens ?', array['Dioclétien']::text[], 'C''est Dioclétien qui, en 303, publie quatre édits pour éradiquer le christianisme. Néron et Dèce sont d''autres persécuteurs, plus anciens.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien", "eg.v.quatre_edits"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur publie en 303 les quatre édits contre les chrétiens ?", "promptLanguage": "fr", "options": ["Dioclétien", "Constantin", "Néron", "Dèce"], "answer": "Dioclétien", "acceptedAnswers": ["Dioclétien"], "explanation": "C''est Dioclétien qui, en 303, publie quatre édits pour éradiquer le christianisme. Néron et Dèce sont d''autres persécuteurs, plus anciens.", "tip": "303 = quatre édits = Dioclétien.", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "errorPatterns": [{"equals": "Constantin", "category": "word_confusion", "feedback": "Constantin sera au contraire l''empereur de la paix, à partir de 313."}, {"equals": "Néron", "category": "word_confusion", "feedback": "Néron lance la toute première persécution, en 64."}, {"equals": "Dèce", "category": "word_confusion", "feedback": "Dèce lance la première persécution générale, vers 250."}], "id": "eg.l25.e02", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e03', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.grande_persecution_303']::text[], 'mcq', 'lesson', 'Quelles sont les dates de la grande persécution ?', array['de 303 à 311']::text[], 'La grande persécution commence avec les édits de 303 et s''arrête avec l''édit de tolérance de Galère en 311.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.grande_persecution_303"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles sont les dates de la grande persécution ?", "promptLanguage": "fr", "options": ["de 303 à 311", "de 250 à 260", "de 313 à 325", "de 284 à 303"], "answer": "de 303 à 311", "acceptedAnswers": ["de 303 à 311"], "explanation": "La grande persécution commence avec les édits de 303 et s''arrête avec l''édit de tolérance de Galère en 311.", "tip": "Édits en 303, tolérance en 311.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "errorPatterns": [{"equals": "de 313 à 325", "category": "word_confusion", "feedback": "313 est l''édit de Milan et 325 le concile de Nicée : c''est la paix, pas la persécution."}, {"equals": "de 250 à 260", "category": "word_confusion", "feedback": "C''est l''époque de Dèce et de Valérien, plus tôt dans le IIIe siècle."}], "id": "eg.l25.e03", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e04', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien']::text[], 'mcq', 'lesson', 'Quelles régions Dioclétien se réserve-t-il en divisant l''empire ?', array['L''Égypte et l''Orient']::text[], 'Dioclétien garde pour lui l''Égypte et l''Orient. C''est pourquoi l''Église d''Alexandrie le sent de très près.', 1, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles régions Dioclétien se réserve-t-il en divisant l''empire ?", "promptLanguage": "fr", "options": ["L''Égypte et l''Orient", "La Gaule et la Bretagne", "L''Italie et l''Afrique du Nord", "La Grèce et l''Espagne"], "answer": "L''Égypte et l''Orient", "acceptedAnswers": ["L''Égypte et l''Orient"], "explanation": "Dioclétien garde pour lui l''Égypte et l''Orient. C''est pourquoi l''Église d''Alexandrie le sent de très près.", "tip": "Dioclétien = Égypte et Orient : c''est chez nous.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "id": "eg.l25.e04", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e05', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.galere']::text[], 'mcq', 'lesson', 'Qui Dioclétien choisit-il comme second ?', array['Galère']::text[], 'Dioclétien associe Galère au pouvoir, avec le titre d''Auguste. Galère lui succède en 305 et se montre encore plus cruel.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.galere"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui Dioclétien choisit-il comme second ?", "promptLanguage": "fr", "options": ["Galère", "Constantin", "Licinius", "Maxence"], "answer": "Galère", "acceptedAnswers": ["Galère"], "explanation": "Dioclétien associe Galère au pouvoir, avec le titre d''Auguste. Galère lui succède en 305 et se montre encore plus cruel.", "tip": "Galère = second, puis successeur.", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "errorPatterns": [{"equals": "Constantin", "category": "word_confusion", "feedback": "Constantin devient empereur en 306, à l''autre bout de l''empire."}], "id": "eg.l25.e05", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e06', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.quatre_edits']::text[], 'fill_blank', 'lesson', 'En ___, Dioclétien publie quatre édits pour éradiquer le christianisme.', array['303']::text[], 'Les quatre édits datent de 303 : ils marquent le début de la grande persécution.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.quatre_edits"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En ___, Dioclétien publie quatre édits pour éradiquer le christianisme.", "promptLanguage": "fr", "options": ["303", "284", "313", "325"], "answer": "303", "acceptedAnswers": ["303"], "explanation": "Les quatre édits datent de 303 : ils marquent le début de la grande persécution.", "tip": "303 = trois, zéro, trois : le début de la grande épreuve.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "errorPatterns": [{"equals": "284", "category": "word_confusion", "feedback": "284 est l''année où Dioclétien devient empereur."}, {"equals": "313", "category": "word_confusion", "feedback": "313 est l''édit de Milan, qui ouvre la paix."}], "id": "eg.l25.e06", "pool": "lesson", "lessonId": "eg.l25", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e07', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.quatre_edits']::text[], 'mcq', 'lesson', 'Que prévoit le premier édit de 303 ?', array['Les églises sont rasées et les livres saints brûlés']::text[], 'Le premier édit s''attaque aux lieux et aux livres : les églises sont rasées, les livres saints brûlés. Les chefs de l''Église ne sont visés qu''aux édits suivants.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.quatre_edits"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que prévoit le premier édit de 303 ?", "promptLanguage": "fr", "options": ["Les églises sont rasées et les livres saints brûlés", "Les chefs de l''Église seront exilés à vie", "Tous les chrétiens seront baptisés de force", "L''Église aura des biens en plus"], "answer": "Les églises sont rasées et les livres saints brûlés", "acceptedAnswers": ["Les églises sont rasées et les livres saints brûlés"], "explanation": "Le premier édit s''attaque aux lieux et aux livres : les églises sont rasées, les livres saints brûlés. Les chefs de l''Église ne sont visés qu''aux édits suivants.", "tip": "Premier édit : on détruit les églises et les livres.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "id": "eg.l25.e07", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e08', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.quatre_edits']::text[], 'mcq', 'lesson', 'Qui est visé par les deuxième et troisième édits ?', array['Les chefs de l''Église']::text[], 'Le deuxième édit jette les chefs de l''Église en prison, le troisième les torture s''ils refusent de sacrifier aux dieux. Le quatrième étend ces mesures à tous les chrétiens.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.quatre_edits"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est visé par les deuxième et troisième édits ?", "promptLanguage": "fr", "options": ["Les chefs de l''Église", "Les seuls esclaves", "Les soldats", "Les marchands"], "answer": "Les chefs de l''Église", "acceptedAnswers": ["Les chefs de l''Église"], "explanation": "Le deuxième édit jette les chefs de l''Église en prison, le troisième les torture s''ils refusent de sacrifier aux dieux. Le quatrième étend ces mesures à tous les chrétiens.", "tip": "Deux et trois : les chefs. Quatre : tout le monde.", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "id": "eg.l25.e08", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e09', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.galere']::text[], 'fill_blank', 'lesson', 'Galère invente régulièrement de nouvelles ___.', array['tortures','des tortures']::text[], 'La cruauté de Galère dépasse celle de ses prédécesseurs : il invente sans cesse de nouvelles tortures.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.galere"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Galère invente régulièrement de nouvelles ___.", "promptLanguage": "fr", "options": ["tortures", "lois", "églises", "provinces"], "answer": "tortures", "acceptedAnswers": ["tortures", "des tortures"], "explanation": "La cruauté de Galère dépasse celle de ses prédécesseurs : il invente sans cesse de nouvelles tortures.", "tip": "Galère = tortures inventées.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "id": "eg.l25.e09", "pool": "lesson", "lessonId": "eg.l25", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e10', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.pierre_sceau_des_martyrs']::text[], 'mcq', 'lesson', 'Quel pape d''Alexandrie, martyrisé en 311, est appelé « le sceau des martyrs » ?', array['Pierre']::text[], 'Le pape Pierre meurt martyr en 311, à la fin de la grande persécution : on l''appelle le sceau des martyrs parce qu''il clôt cette liste.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.pierre_sceau_des_martyrs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape d''Alexandrie, martyrisé en 311, est appelé « le sceau des martyrs » ?", "promptLanguage": "fr", "options": ["Pierre", "Alexandre", "Athanase", "Marc"], "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Le pape Pierre meurt martyr en 311, à la fin de la grande persécution : on l''appelle le sceau des martyrs parce qu''il clôt cette liste.", "tip": "Un sceau ferme une lettre : Pierre ferme la liste des martyrs.", "extraExample": {"text": "Le calendrier copte compte les années à partir de 284, début du règne de Dioclétien.", "translation": "Chaque année copte rappelle les martyrs : c''est l''« ère des martyrs »."}, "errorPatterns": [{"equals": "Alexandre", "category": "word_confusion", "feedback": "Alexandre sera pape après lui et affrontera Arius."}, {"equals": "Marc", "category": "word_confusion", "feedback": "Marc est le fondateur de l''Église d''Alexandrie, au Ier siècle."}], "id": "eg.l25.e10", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e11', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.saint_mina']::text[], 'mcq', 'lesson', 'En quelle année saint Mina est-il martyrisé ?', array['Vers 309']::text[], 'Saint Mina meurt vers 309. Georges (303), Catherine (305), Barbara (306) et le pape Pierre (311) sont les autres noms que la tradition retient.', 3, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.saint_mina"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année saint Mina est-il martyrisé ?", "promptLanguage": "fr", "options": ["Vers 309", "Vers 303", "Vers 305", "Vers 311"], "answer": "Vers 309", "acceptedAnswers": ["Vers 309"], "explanation": "Saint Mina meurt vers 309. Georges (303), Catherine (305), Barbara (306) et le pape Pierre (311) sont les autres noms que la tradition retient.", "tip": "Georges ouvre (303), Mina arrive vers la fin (309).", "extraExample": {"text": "Eusèbe de Césarée a décrit de ses yeux les martyrs d''Égypte.", "translation": "Son récit est un témoignage d''époque, pas une légende tardive."}, "errorPatterns": [{"equals": "Vers 303", "category": "word_confusion", "feedback": "303, c''est Georges."}, {"equals": "Vers 311", "category": "word_confusion", "feedback": "311, c''est le pape Pierre."}], "id": "eg.l25.e11", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l25.e12', 'eg', 'eg.l25', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.saint_georges','eg.v.saint_mina']::text[], 'match', 'lesson', 'Associe chaque martyr à son année.', '{}'::text[], 'La tradition place ces martyrs à différents moments de la grande persécution, entre 303 et 311.', 3, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.saint_georges", "eg.v.saint_mina"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque martyr à son année.", "promptLanguage": "fr", "pairs": [{"left": "Saint Georges", "right": "vers 303"}, {"left": "Sainte Catherine", "right": "305"}, {"left": "Sainte Barbara", "right": "306"}, {"left": "Saint Mina", "right": "vers 309"}], "answer": "Saint Georges = vers 303 ; Sainte Catherine = 305 ; Sainte Barbara = 306 ; Saint Mina = vers 309", "acceptedAnswers": [], "explanation": "La tradition place ces martyrs à différents moments de la grande persécution, entre 303 et 311.", "tip": "Georges 303, Catherine 305, Barbara 306, Mina 309.", "extraExample": {"text": "Galère, malade, signe l''édit de 311 peu avant sa mort.", "translation": "La violence n''a pas éteint la foi : même le persécuteur finit par le reconnaître."}, "id": "eg.l25.e12", "pool": "lesson", "lessonId": "eg.l25", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated 