insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e16', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.edit_de_milan']::text[], 'reorder', 'lesson', 'Phrase-repère : la paix des chrétiens.', array['L''édit de Milan met fin aux persécutions en 313','En 313 l''édit de Milan met fin aux persécutions']::text[], '313 est la date de la paix.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.edit_de_milan"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la paix des chrétiens.", "promptLanguage": "fr", "tokens": ["L''édit", "313", "en", "Milan", "persécutions", "fin", "met", "de", "aux"], "answer": "L''édit de Milan met fin aux persécutions en 313", "acceptedAnswers": ["L''édit de Milan met fin aux persécutions en 313", "En 313 l''édit de Milan met fin aux persécutions"], "explanation": "313 est la date de la paix.", "tip": "313 : Milan, la paix.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "id": "eg.l26.e16", "pool": "lesson", "lessonId": "eg.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e17', 'eg', 'eg.l26', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien','eg.v.diocletien']::text[], 'mcq', 'lesson', 'Quel empereur publie les quatre édits de 303 ?', array['Dioclétien']::text[], 'Les quatre édits sont l''œuvre de Dioclétien. Galère lui succède en 305.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien", "eg.v.diocletien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur publie les quatre édits de 303 ?", "promptLanguage": "fr", "options": ["Dioclétien", "Constantin", "Licinius", "Galère"], "answer": "Dioclétien", "acceptedAnswers": ["Dioclétien"], "explanation": "Les quatre édits sont l''œuvre de Dioclétien. Galère lui succède en 305.", "tip": "303 = Dioclétien.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "La ville porte la trace de Constantin depuis plus de seize siècles."}, "id": "eg.l26.e17", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e18', 'eg', 'eg.l26', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.edit_de_tolerance_311','eg.v.edit_de_tolerance_311']::text[], 'fill_blank', 'lesson', 'Galère signe l''édit de tolérance en ___.', array['311']::text[], 'L''édit de 311 est une première tolérance. Il précède de deux ans l''édit de Milan.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.edit_de_tolerance_311", "eg.v.edit_de_tolerance_311"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Galère signe l''édit de tolérance en ___.", "promptLanguage": "fr", "options": ["311", "303", "313", "325"], "answer": "311", "acceptedAnswers": ["311"], "explanation": "L''édit de 311 est une première tolérance. Il précède de deux ans l''édit de Milan.", "tip": "311 puis 313.", "extraExample": {"text": "L''Arménie adopte le christianisme comme religion d''État dès 301.", "translation": "Elle le fait avant l''Empire romain lui-même."}, "id": "eg.l26.e18", "pool": "lesson", "lessonId": "eg.l26", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e19', 'eg', 'eg.l26', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.diocletien','eg.v.diocletien']::text[], 'free_answer', 'lesson', 'Depuis quelle année le calendrier copte compte-t-il ses années ?', array['284','en 284','l''an 284']::text[], 'Le calendrier copte commence en 284, avec l''avènement de Dioclétien : c''est l''ère des martyrs.', 3, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.diocletien", "eg.v.diocletien"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Depuis quelle année le calendrier copte compte-t-il ses années ?", "promptLanguage": "fr", "answer": "284", "acceptedAnswers": ["284", "en 284", "l''an 284"], "explanation": "Le calendrier copte commence en 284, avec l''avènement de Dioclétien : c''est l''ère des martyrs.", "tip": "284, l''ère des martyrs.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "id": "eg.l26.e19", "pool": "lesson", "lessonId": "eg.l26", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e20', 'eg', 'eg.l26', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.pierre_sceau_des_martyrs','eg.v.pierre_sceau_des_martyrs']::text[], 'mcq', 'lesson', 'Quel pape d''Alexandrie, martyr en 311, est le « sceau des martyrs » ?', array['Pierre']::text[], 'Le pape Pierre ferme la liste des martyrs de la grande persécution, deux ans avant l''édit de Milan.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.pierre_sceau_des_martyrs", "eg.v.pierre_sceau_des_martyrs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape d''Alexandrie, martyr en 311, est le « sceau des martyrs » ?", "promptLanguage": "fr", "options": ["Pierre", "Alexandre", "Athanase", "Cyrille"], "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Le pape Pierre ferme la liste des martyrs de la grande persécution, deux ans avant l''édit de Milan.", "tip": "Pierre, sceau des martyrs.", "extraExample": {"text": "Constantinople est aujourd''hui Istanbul.", "translation": "La ville porte la trace de Constantin depuis plus de seize siècles."}, "id": "eg.l26.e20", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e21', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantinople']::text[], 'free_answer', 'lesson', 'Quel est le nom de la nouvelle capitale fondée par Constantin en 330 ?', array['Constantinople']::text[], 'Constantinople, c''est « la ville de Constantin », capitale de l''empire d''Orient dès 330.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantinople"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel est le nom de la nouvelle capitale fondée par Constantin en 330 ?", "promptLanguage": "fr", "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "Constantinople, c''est « la ville de Constantin », capitale de l''empire d''Orient dès 330.", "tip": "330 : Constantinople.", "extraExample": {"text": "L''Arménie adopte le christianisme comme religion d''État dès 301.", "translation": "Elle le fait avant l''Empire romain lui-même."}, "id": "eg.l26.e21", "pool": "lesson", "lessonId": "eg.l26", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l26.e22', 'eg', 'eg.l26', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.armenie','eg.v.edit_de_milan','eg.v.constantinople']::text[], 'match', 'lesson', 'Les dates du début du siècle.', '{}'::text[], 'Quatre repères pour situer le règne de Constantin : 301 l''Arménie, 313 Milan, 321 le dimanche, 330 Constantinople.', 3, '{"unitIds": ["eg.g26.constantin", "eg.v.armenie", "eg.v.edit_de_milan", "eg.v.constantinople"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les dates du début du siècle.", "promptLanguage": "fr", "pairs": [{"left": "301", "right": "l''Arménie devient chrétienne"}, {"left": "313", "right": "l''édit de Milan"}, {"left": "321", "right": "le dimanche, jour de repos"}, {"left": "330", "right": "la fondation de Constantinople"}], "answer": "301 = l''Arménie devient chrétienne ; 313 = l''édit de Milan ; 321 = le dimanche, jour de repos ; 330 = la fondation de Constantinople", "acceptedAnswers": [], "explanation": "Quatre repères pour situer le règne de Constantin : 301 l''Arménie, 313 Milan, 321 le dimanche, 330 Constantinople.", "tip": "301, 313, 321, 330.", "extraExample": {"text": "Constantin meurt en 337, baptisé tard, peu avant sa mort.", "translation": "Il protège l''Église, mais il reste un empereur avec ses calculs politiques."}, "id": "eg.l26.e22", "pool": "lesson", "lessonId": "eg.l26", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e01', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arius','eg.v.alexandre_d_alexandrie','eg.v.eusebe_de_nicomedie','eg.v.homoousios']::text[], 'match', 'lesson', 'Qui est qui dans la querelle d''Arius ?', '{}'::text[], 'Arius nie, Alexandre résiste, Eusèbe de Nicomédie soutient Arius, et le mot homoousios résume la foi de l''Église.', 1, '{"unitIds": ["eg.g27.arius", "eg.v.arius", "eg.v.alexandre_d_alexandrie", "eg.v.eusebe_de_nicomedie", "eg.v.homoousios"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui est qui dans la querelle d''Arius ?", "promptLanguage": "fr", "pairs": [{"left": "Arius", "right": "nie la divinité du Christ"}, {"left": "Le pape Alexandre", "right": "pape d''Alexandrie, adversaire d''Arius"}, {"left": "Eusèbe de Nicomédie", "right": "évêque séduit par Arius"}, {"left": "homoousios", "right": "de même substance que le Père"}], "answer": "Arius = nie la divinité du Christ ; Le pape Alexandre = pape d''Alexandrie, adversaire d''Arius ; Eusèbe de Nicomédie = évêque séduit par Arius ; homoousios = de même substance que le Père", "acceptedAnswers": [], "explanation": "Arius nie, Alexandre résiste, Eusèbe de Nicomédie soutient Arius, et le mot homoousios résume la foi de l''Église.", "tip": "Arius contre Alexandre ; le mot-clé : homoousios.", "extraExample": {"text": "Arius répétait : « il fut un temps où le Fils n''était pas ».", "translation": "Si le Fils a un commencement, il n''est pas Dieu comme le Père."}, "id": "eg.l27.e01", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e02', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arius']::text[], 'mcq', 'lesson', 'Quelle est l''origine d''Arius ?', array['Prêtre libyen d''origine berbère']::text[], 'Arius est un prêtre libyen d''origine berbère de l''Église d''Alexandrie, ordonné diacre puis prêtre. Ce n''est pas un étranger à l''Église.', 1, '{"unitIds": ["eg.g27.arius", "eg.v.arius"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est l''origine d''Arius ?", "promptLanguage": "fr", "options": ["Prêtre libyen d''origine berbère", "Moine égyptien", "Évêque de Rome", "Soldat romain"], "answer": "Prêtre libyen d''origine berbère", "acceptedAnswers": ["Prêtre libyen d''origine berbère"], "explanation": "Arius est un prêtre libyen d''origine berbère de l''Église d''Alexandrie, ordonné diacre puis prêtre. Ce n''est pas un étranger à l''Église.", "tip": "Libyen, berbère, prêtre.", "extraExample": {"text": "Un seul iota sépare homoousios et homoiousios.", "translation": "Une lettre, mais toute la foi : même substance ou substance seulement semblable."}, "errorPatterns": [{"equals": "Moine égyptien", "category": "word_confusion", "feedback": "Arius est prêtre, pas moine, et libyen d''origine."}], "id": "eg.l27.e02", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e03', 'eg', 'eg.l27', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.pierre_sceau_des_martyrs','eg.v.arius','eg.v.pierre_sceau_des_martyrs']::text[], 'mcq', 'lesson', 'Qui a ordonné Arius diacre en 311 ?', array['Le pape Pierre']::text[], 'Arius est ordonné diacre en 311 par le pape Pierre, le sceau des martyrs, puis prêtre par Achillas.', 2, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.pierre_sceau_des_martyrs", "eg.v.arius", "eg.v.pierre_sceau_des_martyrs"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui a ordonné Arius diacre en 311 ?", "promptLanguage": "fr", "options": ["Le pape Pierre", "Le pape Alexandre", "Athanase", "Constantin"], "answer": "Le pape Pierre", "acceptedAnswers": ["Le pape Pierre"], "explanation": "Arius est ordonné diacre en 311 par le pape Pierre, le sceau des martyrs, puis prêtre par Achillas.", "tip": "Pierre l''ordonne, Achillas le fait prêtre.", "extraExample": {"text": "Les chansons d''Arius circulaient dans les rues et les ports d''Alexandrie.", "translation": "Une idée chantée se retient mieux qu''un raisonnement."}, "id": "eg.l27.e03", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e04', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arius']::text[], 'mcq', 'lesson', 'Vers quelle date Arius commence-t-il à répandre son enseignement ?', array['Vers 318']::text[], 'Arius commence à enseigner vers 318, sept ans avant le concile de Nicée. 303 est la persécution, 381 est le deuxième concile.', 1, '{"unitIds": ["eg.g27.arius", "eg.v.arius"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quelle date Arius commence-t-il à répandre son enseignement ?", "promptLanguage": "fr", "options": ["Vers 318", "Vers 250", "Vers 303", "Vers 381"], "answer": "Vers 318", "acceptedAnswers": ["Vers 318"], "explanation": "Arius commence à enseigner vers 318, sept ans avant le concile de Nicée. 303 est la persécution, 381 est le deuxième concile.", "tip": "318, sept ans avant Nicée (325).", "extraExample": {"text": "Arius répétait : « il fut un temps où le Fils n''était pas ».", "translation": "Si le Fils a un commencement, il n''est pas Dieu comme le Père."}, "errorPatterns": [{"equals": "Vers 303", "category": "word_confusion", "feedback": "303 est le début de la grande persécution."}, {"equals": "Vers 381", "category": "word_confusion", "feedback": "381 est l''année du concile de Constantinople."}], "id": "eg.l27.e04", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e05', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arius','eg.v.arianisme']::text[], 'mcq', 'lesson', 'Que dit Arius du Fils ?', array['Le Fils n''est pas de la même essence que le Père']::text[], 'Pour Arius, le Fils a été créé : il n''est donc pas de la même essence que le Père. C''est cette phrase que l''Église condamne.', 1, '{"unitIds": ["eg.g27.arius", "eg.v.arius", "eg.v.arianisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit Arius du Fils ?", "promptLanguage": "fr", "options": ["Le Fils n''est pas de la même essence que le Père", "Le Fils est le Père lui-même", "Le Fils est de même nature que l''Esprit seulement", "Le Fils est un ange"], "answer": "Le Fils n''est pas de la même essence que le Père", "acceptedAnswers": ["Le Fils n''est pas de la même essence que le Père"], "explanation": "Pour Arius, le Fils a été créé : il n''est donc pas de la même essence que le Père. C''est cette phrase que l''Église condamne.", "tip": "Arius : pas la même essence.", "extraExample": {"text": "Un seul iota sépare homoousios et homoiousios.", "translation": "Une lettre, mais toute la foi : même substance ou substance seulement semblable."}, "errorPatterns": [{"equals": "Le Fils est le Père lui-même", "category": "word_confusion", "feedback": "Dire que le Père et le Fils sont une même personne est une autre erreur, ancienne."}], "id": "eg.l27.e05", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e06', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arius']::text[], 'fill_blank', 'lesson', 'Arius met ses idées en ___ pour qu''on les retienne facilement.', array['chansons','hymnes','des chansons']::text[], 'Arius utilise des chansons et des hymnes : une mélodie se retient bien plus vite qu''un raisonnement.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.arius"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Arius met ses idées en ___ pour qu''on les retienne facilement.", "promptLanguage": "fr", "options": ["chansons", "livres", "lettres", "lois"], "answer": "chansons", "acceptedAnswers": ["chansons", "hymnes", "des chansons"], "explanation": "Arius utilise des chansons et des hymnes : une mélodie se retient bien plus vite qu''un raisonnement.", "tip": "Arius chante sa doctrine.", "extraExample": {"text": "Les chansons d''Arius circulaient dans les rues et les ports d''Alexandrie.", "translation": "Une idée chantée se retient mieux qu''un raisonnement."}, "id": "eg.l27.e06", "pool": "lesson", "lessonId": "eg.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e07', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arianisme']::text[], 'mcq', 'lesson', 'Quel verset les ariens citent-ils pour dire que Jésus est inférieur au Père ?', array['« le Père est plus grand que moi »']::text[], 'Les ariens s''appuient sur Jean 14:28. Athanase répond que le Christ parle ici en tant que Dieu incarné, dans son humanité.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.arianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset les ariens citent-ils pour dire que Jésus est inférieur au Père ?", "promptLanguage": "fr", "options": ["« le Père est plus grand que moi »", "« Qui m''a vu a vu le Père »", "« Je suis dans le Père »", "« Aimez-vous les uns les autres »"], "answer": "« le Père est plus grand que moi »", "acceptedAnswers": ["« le Père est plus grand que moi »"], "explanation": "Les ariens s''appuient sur Jean 14:28. Athanase répond que le Christ parle ici en tant que Dieu incarné, dans son humanité.", "tip": "Jean 14:28 pour les ariens.", "extraExample": {"text": "Arius répétait : « il fut un temps où le Fils n''était pas ».", "translation": "Si le Fils a un commencement, il n''est pas Dieu comme le Père."}, "errorPatterns": [{"equals": "« Qui m''a vu a vu le Père »", "category": "word_confusion", "feedback": "C''est un verset qu''Athanase utilise contre les ariens (Jean 14:9)."}], "id": "eg.l27.e07", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e08', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.divinite_du_christ']::text[], 'mcq', 'lesson', 'Quelle parole de Jésus Athanase cite-t-il pour répondre à Arius ?', array['« Qui m''a vu a vu le Père »']::text[], 'Jean 14:9 : Jésus se montre comme Dieu incarné. Voir le Fils, c''est voir le Père. « Il fut un temps où il n''était pas » est une phrase d''Arius.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.divinite_du_christ"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle parole de Jésus Athanase cite-t-il pour répondre à Arius ?", "promptLanguage": "fr", "options": ["« Qui m''a vu a vu le Père »", "« Il fut un temps où il n''était pas »", "« Le Père est plus grand que moi »", "« Mon royaume n''est pas de ce monde »"], "answer": "« Qui m''a vu a vu le Père »", "acceptedAnswers": ["« Qui m''a vu a vu le Père »"], "explanation": "Jean 14:9 : Jésus se montre comme Dieu incarné. Voir le Fils, c''est voir le Père. « Il fut un temps où il n''était pas » est une phrase d''Arius.", "tip": "Athanase : « Qui m''a vu a vu le Père ».", "extraExample": {"text": "Un seul iota sépare homoousios et homoiousios.", "translation": "Une lettre, mais toute la foi : même substance ou substance seulement semblable."}, "id": "eg.l27.e08", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e09', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.homoousios']::text[], 'fill_blank', 'lesson', 'Homoousios signifie « de même ___ que le Père ».', array['substance','essence']::text[], 'Homoousios veut dire consubstantiel : de même substance que le Père. C''est le mot-clé de la foi de Nicée.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.homoousios"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Homoousios signifie « de même ___ que le Père ».", "promptLanguage": "fr", "options": ["substance", "taille", "âge", "voix"], "answer": "substance", "acceptedAnswers": ["substance", "essence"], "explanation": "Homoousios veut dire consubstantiel : de même substance que le Père. C''est le mot-clé de la foi de Nicée.", "tip": "Homoousios = même substance.", "extraExample": {"text": "Les chansons d''Arius circulaient dans les rues et les ports d''Alexandrie.", "translation": "Une idée chantée se retient mieux qu''un raisonnement."}, "id": "eg.l27.e09", "pool": "lesson", "lessonId": "eg.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e10', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.semi_arianisme']::text[], 'mcq', 'lesson', 'Que croient les semi-ariens à propos du Fils ?', array['Il a une substance similaire à celle du Père']::text[], 'Les semi-ariens disent « substance similaire » (homoiousios) mais pas la même substance. L''Église orthodoxe dit « même substance » (homoousios).', 3, '{"unitIds": ["eg.g27.arius", "eg.v.semi_arianisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que croient les semi-ariens à propos du Fils ?", "promptLanguage": "fr", "options": ["Il a une substance similaire à celle du Père", "Il est de même substance que le Père", "Il est un simple homme", "Il est créé de rien"], "answer": "Il a une substance similaire à celle du Père", "acceptedAnswers": ["Il a une substance similaire à celle du Père"], "explanation": "Les semi-ariens disent « substance similaire » (homoiousios) mais pas la même substance. L''Église orthodoxe dit « même substance » (homoousios).", "tip": "Similaire n''est pas identique.", "extraExample": {"text": "Arius répétait : « il fut un temps où le Fils n''était pas ».", "translation": "Si le Fils a un commencement, il n''est pas Dieu comme le Père."}, "errorPatterns": [{"equals": "Il est de même substance que le Père", "category": "word_confusion", "feedback": "C''est la foi orthodoxe (homoousios), pas celle des semi-ariens."}], "id": "eg.l27.e10", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e11', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.divinite_du_christ']::text[], 'mcq', 'lesson', 'Pourquoi la divinité du Christ est-elle essentielle ?', array['Seul Dieu peut sauver l''homme']::text[], 'Si le Christ n''était qu''une créature, il ne pourrait pas nous sauver. L''enjeu est donc le salut lui-même, pas un détail de vocabulaire.', 3, '{"unitIds": ["eg.g27.arius", "eg.v.divinite_du_christ"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi la divinité du Christ est-elle essentielle ?", "promptLanguage": "fr", "options": ["Seul Dieu peut sauver l''homme", "Parce que c''est une tradition ancienne", "Parce que l''empereur le veut", "Parce que les évêques l''ont voté"], "answer": "Seul Dieu peut sauver l''homme", "acceptedAnswers": ["Seul Dieu peut sauver l''homme"], "explanation": "Si le Christ n''était qu''une créature, il ne pourrait pas nous sauver. L''enjeu est donc le salut lui-même, pas un détail de vocabulaire.", "tip": "Sauveur = Dieu.", "extraExample": {"text": "Un seul iota sépare homoousios et homoiousios.", "translation": "Une lettre, mais toute la foi : même substance ou substance seulement semblable."}, "id": "eg.l27.e11", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e12', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arianisme','eg.v.semi_arianisme','eg.v.homoousios']::text[], 'match', 'lesson', 'Les trois positions du IVe siècle.', '{}'::text[], 'Ces trois camps s''affrontent sur le Christ : créature, semblable à Dieu, ou vrai Dieu de même substance.', 3, '{"unitIds": ["eg.g27.arius", "eg.v.arianisme", "eg.v.semi_arianisme", "eg.v.homoousios"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les trois positions du IVe siècle.", "promptLanguage": "fr", "pairs": [{"left": "Arien", "right": "le Fils est créé, il n''est pas Dieu comme le Père"}, {"left": "Semi-arien", "right": "substance similaire (homoiousios)"}, {"left": "Orthodoxe", "right": "même substance (homoousios)"}], "answer": "Arien = le Fils est créé, il n''est pas Dieu comme le Père ; Semi-arien = substance similaire (homoiousios) ; Orthodoxe = même substance (homoousios)", "acceptedAnswers": [], "explanation": "Ces trois camps s''affrontent sur le Christ : créature, semblable à Dieu, ou vrai Dieu de même substance.", "tip": "Créé, semblable, ou de même substance.", "extraExample": {"text": "Les chansons d''Arius circulaient dans les rues et les ports d''Alexandrie.", "translation": "Une idée chantée se retient mieux qu''un raisonnement."}, "id": "eg.l27.e12", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e13', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arianisme']::text[], 'free_answer', 'lesson', 'Comment s''appelle l''hérésie d''Arius ?', array['L''arianisme','arianisme']::text[], 'L''hérésie d''Arius porte son nom : l''arianisme. Elle nie la divinité du Christ.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.arianisme"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle l''hérésie d''Arius ?", "promptLanguage": "fr", "answer": "L''arianisme", "acceptedAnswers": ["L''arianisme", "arianisme"], "explanation": "L''hérésie d''Arius porte son nom : l''arianisme. Elle nie la divinité du Christ.", "tip": "Arius → arianisme.", "extraExample": {"text": "Arius répétait : « il fut un temps où le Fils n''était pas ».", "translation": "Si le Fils a un commencement, il n''est pas Dieu comme le Père."}, "hint": "Un nom qui vient de celui d''Arius.", "id": "eg.l27.e13", "pool": "lesson", "lessonId": "eg.l27", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e14', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.homoousios']::text[], 'free_answer', 'lesson', 'Quel mot grec dit que le Fils est de même substance que le Père ?', array['homoousios','homoousis','homoousion']::text[], 'Homoousios est le mot de Nicée. Avec un iota de plus, homoiousios devient « substance semblable », et c''est la position semi-arienne.', 3, '{"unitIds": ["eg.g27.arius", "eg.v.homoousios"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel mot grec dit que le Fils est de même substance que le Père ?", "promptLanguage": "fr", "answer": "homoousios", "acceptedAnswers": ["homoousios", "homoousis", "homoousion"], "explanation": "Homoousios est le mot de Nicée. Avec un iota de plus, homoiousios devient « substance semblable », et c''est la position semi-arienne.", "tip": "Homoousios : même.", "extraExample": {"text": "Un seul iota sépare homoousios et homoiousios.", "translation": "Une lettre, mais toute la foi : même substance ou substance seulement semblable."}, "id": "eg.l27.e14", "pool": "lesson", "lessonId": "eg.l27", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e15', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.arius']::text[], 'reorder', 'lesson', 'Phrase-repère : l''erreur d''Arius.', array['Arius nie la divinité du Christ']::text[], 'Arius soutient que le Christ est une créature : il nie donc sa divinité.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.arius"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : l''erreur d''Arius.", "promptLanguage": "fr", "tokens": ["la", "du", "nie", "Christ", "divinité", "Arius"], "answer": "Arius nie la divinité du Christ", "acceptedAnswers": ["Arius nie la divinité du Christ"], "explanation": "Arius soutient que le Christ est une créature : il nie donc sa divinité.", "tip": "Arius = divinité niée.", "extraExample": {"text": "Les chansons d''Arius circulaient dans les rues et les ports d''Alexandrie.", "translation": "Une idée chantée se retient mieux qu''un raisonnement."}, "id": "eg.l27.e15", "pool": "lesson", "lessonId": "eg.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e16', 'eg', 'eg.l27', 'eg.g27.arius', array['eg.g27.arius','eg.v.eusebe_de_nicomedie']::text[], 'mcq', 'lesson', 'Quel évêque puissant est séduit par Arius et le protège ?', array['Eusèbe de Nicomédie']::text[], 'Eusèbe de Nicomédie est conquis par l''éloquence d''Arius. Il est proche de la cour, ce qui donnera une portée politique à l''arianisme.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.eusebe_de_nicomedie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel évêque puissant est séduit par Arius et le protège ?", "promptLanguage": "fr", "options": ["Eusèbe de Nicomédie", "Alexandre", "Athanase", "Pierre"], "answer": "Eusèbe de Nicomédie", "acceptedAnswers": ["Eusèbe de Nicomédie"], "explanation": "Eusèbe de Nicomédie est conquis par l''éloquence d''Arius. Il est proche de la cour, ce qui donnera une portée politique à l''arianisme.", "tip": "Eusèbe de Nicomédie : l''allié d''Arius.", "extraExample": {"text": "Arius répétait : « il fut un temps où le Fils n''était pas ».", "translation": "Si le Fils a un commencement, il n''est pas Dieu comme le Père."}, "id": "eg.l27.e16", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e17', 'eg', 'eg.l27', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantin','eg.v.constantin']::text[], 'mcq', 'lesson', 'Qui décide de convoquer un concile pour régler la querelle ?', array['Constantin']::text[], 'Constantin veut l''unité de l''empire et décide de convoquer un concile à Nicée : l''évêque du dehors intervient.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantin", "eg.v.constantin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui décide de convoquer un concile pour régler la querelle ?", "promptLanguage": "fr", "options": ["Constantin", "Le pape Alexandre", "Arius", "Licinius"], "answer": "Constantin", "acceptedAnswers": ["Constantin"], "explanation": "Constantin veut l''unité de l''empire et décide de convoquer un concile à Nicée : l''évêque du dehors intervient.", "tip": "Constantin convoque Nicée.", "extraExample": {"text": "Un seul iota sépare homoousios et homoiousios.", "translation": "Une lettre, mais toute la foi : même substance ou substance seulement semblable."}, "id": "eg.l27.e17", "pool": "lesson", "lessonId": "eg.l27", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e18', 'eg', 'eg.l27', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.eveque_du_dehors','eg.v.eveque_du_dehors']::text[], 'fill_blank', 'lesson', 'Constantin se présente comme l''évêque du ___.', array['dehors']::text[], 'Constantin se dit « évêque du dehors » : il s''occupe des affaires extérieures de l''Église, mais s''engage aussi dans les débats comme celui d''Arius.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.eveque_du_dehors", "eg.v.eveque_du_dehors"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Constantin se présente comme l''évêque du ___.", "promptLanguage": "fr", "options": ["dehors", "dedans", "désert", "palais"], "answer": "dehors", "acceptedAnswers": ["dehors"], "explanation": "Constantin se dit « évêque du dehors » : il s''occupe des affaires extérieures de l''Église, mais s''engage aussi dans les débats comme celui d''Arius.", "tip": "Évêque du dehors.", "extraExample": {"text": "Les chansons d''Arius circulaient dans les rues et les ports d''Alexandrie.", "translation": "Une idée chantée se retient mieux qu''un raisonnement."}, "id": "eg.l27.e18", "pool": "lesson", "lessonId": "eg.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e19', 'eg', 'eg.l27', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.edit_de_milan','eg.v.edit_de_milan']::text[], 'fill_blank', 'lesson', 'L''édit de Milan, qui met fin aux persécutions, est de ___.', array['313']::text[], 'Milan (313) ouvre la paix qui permet à l''Église de débattre en liberté. C''est dans ce climat qu''éclate la querelle d''Arius, quelques années plus tard.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.edit_de_milan", "eg.v.edit_de_milan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "L''édit de Milan, qui met fin aux persécutions, est de ___.", "promptLanguage": "fr", "options": ["313", "325", "311", "330"], "answer": "313", "acceptedAnswers": ["313"], "explanation": "Milan (313) ouvre la paix qui permet à l''Église de débattre en liberté. C''est dans ce climat qu''éclate la querelle d''Arius, quelques années plus tard.", "tip": "313, Milan.", "extraExample": {"text": "Arius répétait : « il fut un temps où le Fils n''était pas ».", "translation": "Si le Fils a un commencement, il n''est pas Dieu comme le Père."}, "id": "eg.l27.e19", "pool": "lesson", "lessonId": "eg.l27", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l27.e20', 'eg', 'eg.l27', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantinople','eg.v.constantinople']::text[], 'free_answer', 'lesson', 'Comment s''appelle la ville fondée par Constantin en 330 ?', array['Constantinople']::text[], 'Constantinople, « la ville de Constantin », capitale de l''empire d''Orient.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantinople", "eg.v.constantinople"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle la ville fondée par Constantin en 330 ?", "promptLanguage": "fr", "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "Constantinople, « la ville de Constantin », capitale de l''empire d''Orient.", "tip": "Constantin + ville.", "extraExample": {"text": "Un seul iota sépare homoousios et homoiousios.", "translation": "Une lettre, mais toute la foi : même substance ou substance seulement semblable."}, "id": "eg.l27.e20", "pool": "lesson", "lessonId": "eg.l27", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e01', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee','eg.v.eusebe_de_cesaree']::text[], 'match', 'lesson', 'Qui a fait quoi à Nicée ?', '{}'::text[], 'Constantin convoque, Alexandre préside, Athanase argumente et Eusèbe de Césarée écrit l''histoire.', 1, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee", "eg.v.eusebe_de_cesaree"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui a fait quoi à Nicée ?", "promptLanguage": "fr", "pairs": [{"left": "Constantin", "right": "convoque le concile"}, {"left": "Le pape Alexandre", "right": "préside, selon la tradition copte"}, {"left": "Athanase", "right": "expose les erreurs d''Arius"}, {"left": "Eusèbe de Césarée", "right": "père de l''histoire ecclésiastique"}], "answer": "Constantin = convoque le concile ; Le pape Alexandre = préside, selon la tradition copte ; Athanase = expose les erreurs d''Arius ; Eusèbe de Césarée = père de l''histoire ecclésiastique", "acceptedAnswers": [], "explanation": "Constantin convoque, Alexandre préside, Athanase argumente et Eusèbe de Césarée écrit l''histoire.", "tip": "Constantin convoque, Alexandre préside, Athanase défend.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "id": "eg.l28.e01", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e02', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'mcq', 'lesson', 'Qui convoque le concile de Nicée ?', array['L''empereur Constantin']::text[], 'C''est Constantin, l''évêque du dehors, qui convoque Nicée pour rétablir l''unité de l''empire. Théodose Ier convoquera Constantinople, en 381.', 1, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui convoque le concile de Nicée ?", "promptLanguage": "fr", "options": ["L''empereur Constantin", "Le pape Alexandre", "Arius", "L''empereur Théodose Ier"], "answer": "L''empereur Constantin", "acceptedAnswers": ["L''empereur Constantin"], "explanation": "C''est Constantin, l''évêque du dehors, qui convoque Nicée pour rétablir l''unité de l''empire. Théodose Ier convoquera Constantinople, en 381.", "tip": "Nicée = Constantin.", "extraExample": {"text": "Le credo de Nicée est la base du Credo que tu récites à la messe.", "translation": "Le texte a été complété à Constantinople en 381, c''est la prochaine étape."}, "errorPatterns": [{"equals": "L''empereur Théodose Ier", "category": "word_confusion", "feedback": "Théodose Ier convoque le concile de Constantinople, en 381."}], "id": "eg.l28.e02", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e03', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.nicee']::text[], 'mcq', 'lesson', 'Dans quelle ville se tient le premier concile œcuménique ?', array['Nicée']::text[], 'Le premier concile se tient à Nicée. Constantinople accueillera le deuxième, Éphèse le troisième.', 1, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.nicee"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quelle ville se tient le premier concile œcuménique ?", "promptLanguage": "fr", "options": ["Nicée", "Constantinople", "Éphèse", "Alexandrie"], "answer": "Nicée", "acceptedAnswers": ["Nicée"], "explanation": "Le premier concile se tient à Nicée. Constantinople accueillera le deuxième, Éphèse le troisième.", "tip": "Premier = Nicée.", "extraExample": {"text": "Athanase n''a pas encore 30 ans quand il suit Alexandre à Nicée.", "translation": "Un jeune diacre devient la voix de la foi : c''est son premier grand rôle."}, "errorPatterns": [{"equals": "Constantinople", "category": "word_confusion", "feedback": "C''est le deuxième concile (381)."}, {"equals": "Éphèse", "category": "word_confusion", "feedback": "C''est le troisième concile (431)."}], "id": "eg.l28.e03", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e04', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'fill_blank', 'lesson', 'Le concile de Nicée se tient en ___.', array['325']::text[], '325 est l''année du premier concile œcuménique. 381 est celle du deuxième, 431 celle du troisième.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le concile de Nicée se tient en ___.", "promptLanguage": "fr", "options": ["325", "313", "381", "431"], "answer": "325", "acceptedAnswers": ["325"], "explanation": "325 est l''année du premier concile œcuménique. 381 est celle du deuxième, 431 celle du troisième.", "tip": "325, premier.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "errorPatterns": [{"equals": "381", "category": "word_confusion", "feedback": "381 est Constantinople."}, {"equals": "313", "category": "word_confusion", "feedback": "313 est l''édit de Milan."}], "id": "eg.l28.e04", "pool": "lesson", "lessonId": "eg.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e05', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.les_318_eveques']::text[], 'mcq', 'lesson', 'Combien d''évêques sont réunis à Nicée, selon la tradition ?', array['318']::text[], 'La tradition retient 318 évêques à Nicée. 150 évêques se réuniront à Constantinople et 200 à Éphèse.', 1, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.les_318_eveques"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''évêques sont réunis à Nicée, selon la tradition ?", "promptLanguage": "fr", "options": ["318", "150", "200", "12"], "answer": "318", "acceptedAnswers": ["318"], "explanation": "La tradition retient 318 évêques à Nicée. 150 évêques se réuniront à Constantinople et 200 à Éphèse.", "tip": "318 à Nicée.", "extraExample": {"text": "Le credo de Nicée est la base du Credo que tu récites à la messe.", "translation": "Le texte a été complété à Constantinople en 381, c''est la prochaine étape."}, "errorPatterns": [{"equals": "150", "category": "word_confusion", "feedback": "150 évêques sont à Constantinople, en 381."}, {"equals": "200", "category": "word_confusion", "feedback": "200 évêques sont à Éphèse, en 431."}], "id": "eg.l28.e05", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e06', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.les_318_eveques']::text[], 'mcq', 'lesson', 'Par qui l''évêque de Rome est-il représenté à Nicée ?', array['Par deux prêtres']::text[], 'Sylvestre, évêque de Rome, est trop âgé : il envoie deux prêtres pour le représenter.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.les_318_eveques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Par qui l''évêque de Rome est-il représenté à Nicée ?", "promptLanguage": "fr", "options": ["Par deux prêtres", "Par un diacre", "Par l''empereur", "Il est présent en personne"], "answer": "Par deux prêtres", "acceptedAnswers": ["Par deux prêtres"], "explanation": "Sylvestre, évêque de Rome, est trop âgé : il envoie deux prêtres pour le représenter.", "tip": "Rome envoie deux prêtres.", "extraExample": {"text": "Athanase n''a pas encore 30 ans quand il suit Alexandre à Nicée.", "translation": "Un jeune diacre devient la voix de la foi : c''est son premier grand rôle."}, "id": "eg.l28.e06", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e07', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee','eg.v.alexandre_d_alexandrie']::text[], 'mcq', 'lesson', 'Qui préside le concile, selon la tradition copte ?', array['Le pape Alexandre']::text[], 'Selon ton cours, le pape copte Alexandre préside le concile : l''Église d''Alexandrie est en première ligne.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee", "eg.v.alexandre_d_alexandrie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui préside le concile, selon la tradition copte ?", "promptLanguage": "fr", "options": ["Le pape Alexandre", "Le pape Pierre", "Eusèbe de Césarée", "Constantin"], "answer": "Le pape Alexandre", "acceptedAnswers": ["Le pape Alexandre"], "explanation": "Selon ton cours, le pape copte Alexandre préside le concile : l''Église d''Alexandrie est en première ligne.", "tip": "Alexandre préside.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "errorPatterns": [{"equals": "Constantin", "category": "word_confusion", "feedback": "Constantin convoque, mais il n''est pas évêque : il ne préside pas la doctrine."}], "id": "eg.l28.e07", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e08', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'mcq', 'lesson', 'Quel est le rôle d''Athanase à Nicée ?', array['Il expose les erreurs d''Arius']::text[], 'Le jeune diacre Athanase expose les erreurs d''Arius et convainc les évêques de l''excommunier.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le rôle d''Athanase à Nicée ?", "promptLanguage": "fr", "options": ["Il expose les erreurs d''Arius", "Il rédige les ordres de l''empereur", "Il défend Arius", "Il quitte le concile"], "answer": "Il expose les erreurs d''Arius", "acceptedAnswers": ["Il expose les erreurs d''Arius"], "explanation": "Le jeune diacre Athanase expose les erreurs d''Arius et convainc les évêques de l''excommunier.", "tip": "Athanase = accusateur de l''erreur.", "extraExample": {"text": "Le credo de Nicée est la base du Credo que tu récites à la messe.", "translation": "Le texte a été complété à Constantinople en 381, c''est la prochaine étape."}, "id": "eg.l28.e08", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e09', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_oecumenique']::text[], 'mcq', 'lesson', 'Que veut dire « œcuménique » ?', array['De toute la terre habitée']::text[], 'Un concile œcuménique réunit les évêques de toute l''Église, pas d''un seul pays. Nicée est le premier.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_oecumenique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « œcuménique » ?", "promptLanguage": "fr", "options": ["De toute la terre habitée", "Réservé aux évêques", "Très ancien", "Interdit au peuple"], "answer": "De toute la terre habitée", "acceptedAnswers": ["De toute la terre habitée"], "explanation": "Un concile œcuménique réunit les évêques de toute l''Église, pas d''un seul pays. Nicée est le premier.", "tip": "Œcuménique = universel.", "extraExample": {"text": "Athanase n''a pas encore 30 ans quand il suit Alexandre à Nicée.", "translation": "Un jeune diacre devient la voix de la foi : c''est son premier grand rôle."}, "id": "eg.l28.e09", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e10', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'fill_blank', 'lesson', 'Le concile de Nicée ___ Arius.', array['excommunie']::text[], 'Nicée condamne Arius et l''excommunie : il est exclu de l''Église tant qu''il ne renonce pas à ses erreurs.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le concile de Nicée ___ Arius.", "promptLanguage": "fr", "options": ["excommunie", "exile à Rome", "nomme évêque", "bénit"], "answer": "excommunie", "acceptedAnswers": ["excommunie"], "explanation": "Nicée condamne Arius et l''excommunie : il est exclu de l''Église tant qu''il ne renonce pas à ses erreurs.", "tip": "Nicée = excommunication d''Arius.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "errorPatterns": [{"equals": "nomme évêque", "category": "word_confusion", "feedback": "Au contraire : Arius est condamné."}], "id": "eg.l28.e10", "pool": "lesson", "lessonId": "eg.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e11', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.anathemes']::text[], 'fill_blank', 'lesson', 'Avec le credo, les pères de Nicée rédigent des ___ qui condamnent l''enseignement d''Arius.', array['anathèmes','anathemes']::text[], 'Les anathèmes sont les condamnations de l''arianisme annexées au credo.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.anathemes"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Avec le credo, les pères de Nicée rédigent des ___ qui condamnent l''enseignement d''Arius.", "promptLanguage": "fr", "options": ["anathèmes", "chansons", "miracles", "dogmes de paix"], "answer": "anathèmes", "acceptedAnswers": ["anathèmes", "anathemes"], "explanation": "Les anathèmes sont les condamnations de l''arianisme annexées au credo.", "tip": "Anathème = condamnation.", "extraExample": {"text": "Le credo de Nicée est la base du Credo que tu récites à la messe.", "translation": "Le texte a été complété à Constantinople en 381, c''est la prochaine étape."}, "id": "eg.l28.e11", "pool": "lesson", "lessonId": "eg.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e12', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.credo_de_nicee']::text[], 'mcq', 'lesson', 'Combien d''évêques sur 318 signent d''abord le credo et les anathèmes ?', array['315']::text[], '315 évêques signent. Trois résistent aux anathèmes puis cèdent sous la pression de Constantin.', 3, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.credo_de_nicee"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''évêques sur 318 signent d''abord le credo et les anathèmes ?", "promptLanguage": "fr", "options": ["315", "300", "150", "318"], "answer": "315", "acceptedAnswers": ["315"], "explanation": "315 évêques signent. Trois résistent aux anathèmes puis cèdent sous la pression de Constantin.", "tip": "315 + 3 = 318.", "extraExample": {"text": "Athanase n''a pas encore 30 ans quand il suit Alexandre à Nicée.", "translation": "Un jeune diacre devient la voix de la foi : c''est son premier grand rôle."}, "id": "eg.l28.e12", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e13', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.credo_de_nicee','eg.v.eusebe_de_nicomedie']::text[], 'mcq', 'lesson', 'Quels trois évêques refusent d''abord de signer les anathèmes ?', array['Eusèbe de Nicomédie, Théognis de Nicée et Maris de Chalcédoine']::text[], 'Ces trois évêques signent le credo mais pas les anathèmes. Ils propageront ensuite la doctrine arienne.', 3, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.credo_de_nicee", "eg.v.eusebe_de_nicomedie"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quels trois évêques refusent d''abord de signer les anathèmes ?", "promptLanguage": "fr", "options": ["Eusèbe de Nicomédie, Théognis de Nicée et Maris de Chalcédoine", "Alexandre, Athanase et Léonce", "Eustathe, Macaire et Sylvestre", "Arius, Alexandre et Eusèbe de Césarée"], "answer": "Eusèbe de Nicomédie, Théognis de Nicée et Maris de Chalcédoine", "acceptedAnswers": ["Eusèbe de Nicomédie, Théognis de Nicée et Maris de Chalcédoine"], "explanation": "Ces trois évêques signent le credo mais pas les anathèmes. Ils propageront ensuite la doctrine arienne.", "tip": "Un Eusèbe, un Théognis, un Maris.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "id": "eg.l28.e13", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e14', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee','eg.v.homoousios']::text[], 'match', 'lesson', 'Nicée en bref.', '{}'::text[], 'Constantin convoque en 325 contre l''arianisme, et le mot-clé est homoousios.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee", "eg.v.homoousios"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Nicée en bref.", "promptLanguage": "fr", "pairs": [{"left": "Qui convoque ?", "right": "Constantin"}, {"left": "Quand ?", "right": "325"}, {"left": "Contre qui ?", "right": "l''arianisme"}, {"left": "Quel mot-clé ?", "right": "homoousios"}], "answer": "Qui convoque ? = Constantin ; Quand ? = 325 ; Contre qui ? = l''arianisme ; Quel mot-clé ? = homoousios", "acceptedAnswers": [], "explanation": "Constantin convoque en 325 contre l''arianisme, et le mot-clé est homoousios.", "tip": "Constantin, 325, arianisme, homoousios.", "extraExample": {"text": "Le credo de Nicée est la base du Credo que tu récites à la messe.", "translation": "Le texte a été complété à Constantinople en 381, c''est la prochaine étape."}, "id": "eg.l28.e14", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e15', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'free_answer', 'lesson', 'Combien de canons Nicée établit-il ?', array['20','vingt','20 canons','vingt canons']::text[], 'Nicée établit vingt canons : ce sont des règles pratiques pour la vie de l''Église, en plus du credo.', 3, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Combien de canons Nicée établit-il ?", "promptLanguage": "fr", "answer": "20", "acceptedAnswers": ["20", "vingt", "20 canons", "vingt canons"], "explanation": "Nicée établit vingt canons : ce sont des règles pratiques pour la vie de l''Église, en plus du credo.", "tip": "20 canons.", "extraExample": {"text": "Athanase n''a pas encore 30 ans quand il suit Alexandre à Nicée.", "translation": "Un jeune diacre devient la voix de la foi : c''est son premier grand rôle."}, "id": "eg.l28.e15", "pool": "lesson", "lessonId": "eg.l28", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e16', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.eusebe_de_cesaree']::text[], 'free_answer', 'lesson', 'Quel évêque, ami de Constantin, est appelé le père de l''histoire ecclésiastique ?', array['Eusèbe de Césarée','Eusèbe']::text[], 'Eusèbe de Césarée a laissé une Histoire ecclésiastique, précieuse pour connaître les premiers siècles.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.eusebe_de_cesaree"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel évêque, ami de Constantin, est appelé le père de l''histoire ecclésiastique ?", "promptLanguage": "fr", "answer": "Eusèbe de Césarée", "acceptedAnswers": ["Eusèbe de Césarée", "Eusèbe"], "explanation": "Eusèbe de Césarée a laissé une Histoire ecclésiastique, précieuse pour connaître les premiers siècles.", "tip": "Eusèbe de Césarée = historien.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "id": "eg.l28.e16", "pool": "lesson", "lessonId": "eg.l28", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e17', 'eg', 'eg.l28', 'eg.g27.arius', array['eg.g27.arius','eg.v.arianisme','eg.v.concile_de_nicee','eg.v.arianisme']::text[], 'free_answer', 'lesson', 'Contre quelle hérésie le concile de Nicée est-il réuni ?', array['L''arianisme','arianisme','l''hérésie arienne']::text[], 'Nicée est réuni contre l''arianisme, qui nie la divinité du Christ.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.arianisme", "eg.v.concile_de_nicee", "eg.v.arianisme"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Contre quelle hérésie le concile de Nicée est-il réuni ?", "promptLanguage": "fr", "answer": "L''arianisme", "acceptedAnswers": ["L''arianisme", "arianisme", "l''hérésie arienne"], "explanation": "Nicée est réuni contre l''arianisme, qui nie la divinité du Christ.", "tip": "Nicée = arianisme.", "extraExample": {"text": "Le credo de Nicée est la base du Credo que tu récites à la messe.", "translation": "Le texte a été complété à Constantinople en 381, c''est la prochaine étape."}, "id": "eg.l28.e17", "pool": "lesson", "lessonId": "eg.l28", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e18', 'eg', 'eg.l28', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'reorder', 'lesson', 'Phrase-repère : Nicée.', array['Le concile de Nicée condamne Arius en 325','En 325 le concile de Nicée condamne Arius']::text[], 'Nicée est la première décision de l''Église entière contre Arius.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : Nicée.", "promptLanguage": "fr", "tokens": ["Le", "condamne", "325", "Nicée", "Arius", "concile", "de", "en"], "answer": "Le concile de Nicée condamne Arius en 325", "acceptedAnswers": ["Le concile de Nicée condamne Arius en 325", "En 325 le concile de Nicée condamne Arius"], "explanation": "Nicée est la première décision de l''Église entière contre Arius.", "tip": "Nicée 325 = Arius condamné.", "extraExample": {"text": "Athanase n''a pas encore 30 ans quand il suit Alexandre à Nicée.", "translation": "Un jeune diacre devient la voix de la foi : c''est son premier grand rôle."}, "id": "eg.l28.e18", "pool": "lesson", "lessonId": "eg.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e19', 'eg', 'eg.l28', 'eg.g27.arius', array['eg.g27.arius','eg.v.semi_arianisme','eg.v.semi_arianisme']::text[], 'mcq', 'lesson', 'Quelle position pense que le Fils a une substance similaire à celle du Père ?', array['Le semi-arianisme']::text[], 'Le semi-arianisme dit « substance similaire » (homoiousios). L''orthodoxie dit « même substance » (homoousios).', 3, '{"unitIds": ["eg.g27.arius", "eg.v.semi_arianisme", "eg.v.semi_arianisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle position pense que le Fils a une substance similaire à celle du Père ?", "promptLanguage": "fr", "options": ["Le semi-arianisme", "L''arianisme", "L''orthodoxie", "L''apollinarisme"], "answer": "Le semi-arianisme", "acceptedAnswers": ["Le semi-arianisme"], "explanation": "Le semi-arianisme dit « substance similaire » (homoiousios). L''orthodoxie dit « même substance » (homoousios).", "tip": "Similaire = semi-arien.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "id": "eg.l28.e19", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e20', 'eg', 'eg.l28', 'eg.g27.arius', array['eg.g27.arius','eg.v.arius','eg.v.arius']::text[], 'fill_blank', 'lesson', 'Arius commence à enseigner vers ___.', array['318']::text[], 'Vers 318, Arius répand son enseignement à Alexandrie, sept ans avant Nicée.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.arius", "eg.v.arius"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Arius commence à enseigner vers ___.", "promptLanguage": "fr", "options": ["318", "250", "303", "381"], "answer": "318", "acceptedAnswers": ["318"], "explanation": "Vers 318, Arius répand son enseignement à Alexandrie, sept ans avant Nicée.", "tip": "318 puis 325.", "extraExample": {"text": "Le credo de Nicée est la base du Credo que tu récites à la messe.", "translation": "Le texte a été complété à Constantinople en 381, c''est la prochaine étape."}, "id": "eg.l28.e20", "pool": "lesson", "lessonId": "eg.l28", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e21', 'eg', 'eg.l28', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.armenie','eg.v.armenie']::text[], 'mcq', 'lesson', 'Quelle nation précède l''Empire romain en devenant chrétienne dès 301 ?', array['L''Arménie']::text[], 'L''Arménie devient chrétienne comme religion d''État en 301, avant même Constantin.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.armenie", "eg.v.armenie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle nation précède l''Empire romain en devenant chrétienne dès 301 ?", "promptLanguage": "fr", "options": ["L''Arménie", "L''Égypte", "La Perse", "La Grèce"], "answer": "L''Arménie", "acceptedAnswers": ["L''Arménie"], "explanation": "L''Arménie devient chrétienne comme religion d''État en 301, avant même Constantin.", "tip": "301 = Arménie.", "extraExample": {"text": "Athanase n''a pas encore 30 ans quand il suit Alexandre à Nicée.", "translation": "Un jeune diacre devient la voix de la foi : c''est son premier grand rôle."}, "id": "eg.l28.e21", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l28.e22', 'eg', 'eg.l28', 'eg.g25.grande_persecution', array['eg.g25.grande_persecution','eg.v.pierre_sceau_des_martyrs','eg.v.pierre_sceau_des_martyrs']::text[], 'mcq', 'lesson', 'Quel pape copte est le « sceau des martyrs » ?', array['Pierre']::text[], 'Le pape Pierre meurt en 311. Alexandre, qui préside Nicée, vient après lui comme pape d''Alexandrie.', 3, '{"unitIds": ["eg.g25.grande_persecution", "eg.v.pierre_sceau_des_martyrs", "eg.v.pierre_sceau_des_martyrs"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape copte est le « sceau des martyrs » ?", "promptLanguage": "fr", "options": ["Pierre", "Alexandre", "Athanase", "Marc"], "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Le pape Pierre meurt en 311. Alexandre, qui préside Nicée, vient après lui comme pape d''Alexandrie.", "tip": "Pierre précède Alexandre.", "extraExample": {"text": "Nicée est aujourd''hui İznik, en Turquie.", "translation": "La ville était alors tout près de la résidence impériale de Nicomédie."}, "id": "eg.l28.e22", "pool": "lesson", "lessonId": "eg.l28", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e01', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.defenseur_de_la_foi','eg.v.vie_d_antoine','eg.v.frumentius','eg.v.sur_l_incarnation_du_verbe']::text[], 'match', 'lesson', 'Athanase en quatre mots.', '{}'::text[], 'Athanase est défenseur de la foi, auteur de livres, et missionnaire par Frumentius.', 1, '{"unitIds": ["eg.g29.athanase", "eg.v.defenseur_de_la_foi", "eg.v.vie_d_antoine", "eg.v.frumentius", "eg.v.sur_l_incarnation_du_verbe"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Athanase en quatre mots.", "promptLanguage": "fr", "pairs": [{"left": "Défenseur de la foi", "right": "le surnom d''Athanase"}, {"left": "La Vie d''Antoine", "right": "livre qui fait connaître le monachisme à Rome"}, {"left": "Frumentius", "right": "premier évêque d''Éthiopie"}, {"left": "Sur l''incarnation du Verbe", "right": "écrit de jeunesse : le Christ est Dieu et homme"}], "answer": "Défenseur de la foi = le surnom d''Athanase ; La Vie d''Antoine = livre qui fait connaître le monachisme à Rome ; Frumentius = premier évêque d''Éthiopie ; Sur l''incarnation du Verbe = écrit de jeunesse : le Christ est Dieu et homme", "acceptedAnswers": [], "explanation": "Athanase est défenseur de la foi, auteur de livres, et missionnaire par Frumentius.", "tip": "Un surnom, deux livres, un missionnaire.", "extraExample": {"text": "Athanase aurait dit : « le monde est contre moi, et je suis contre le monde ».", "translation": "Pour lui, tenir la vérité compte plus que d''avoir la foule avec soi."}, "id": "eg.l29.e01", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e02', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.sur_l_incarnation_du_verbe']::text[], 'mcq', 'lesson', 'À quel âge Athanase écrit-il « Sur l''incarnation du Verbe » ?', array['Avant l''âge de 20 ans']::text[], 'Athanase écrit ce livre dès sa jeunesse. Il y explique déjà ce qu''il défendra toute sa vie.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.sur_l_incarnation_du_verbe"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À quel âge Athanase écrit-il « Sur l''incarnation du Verbe » ?", "promptLanguage": "fr", "options": ["Avant l''âge de 20 ans", "Vers 50 ans", "Après son premier exil", "À la fin de sa vie"], "answer": "Avant l''âge de 20 ans", "acceptedAnswers": ["Avant l''âge de 20 ans"], "explanation": "Athanase écrit ce livre dès sa jeunesse. Il y explique déjà ce qu''il défendra toute sa vie.", "tip": "Un livre avant 20 ans.", "extraExample": {"text": "Athanase reste patriarche plus de quarante ans, malgré les exils.", "translation": "Toute une vie donnée à une seule question : Jésus est-il Dieu ?"}, "id": "eg.l29.e02", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e03', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.sur_l_incarnation_du_verbe']::text[], 'mcq', 'lesson', 'Que dit « Sur l''incarnation du Verbe » du Christ ?', array['Parfaitement Dieu et parfaitement homme']::text[], 'Le Christ est Dieu et homme, sans division de sa personne. Cela s''oppose à Arius, qui lui retire la divinité.', 1, '{"unitIds": ["eg.g29.athanase", "eg.v.sur_l_incarnation_du_verbe"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit « Sur l''incarnation du Verbe » du Christ ?", "promptLanguage": "fr", "options": ["Parfaitement Dieu et parfaitement homme", "Un ange", "Un homme adopté par Dieu", "Dieu sans corps"], "answer": "Parfaitement Dieu et parfaitement homme", "acceptedAnswers": ["Parfaitement Dieu et parfaitement homme"], "explanation": "Le Christ est Dieu et homme, sans division de sa personne. Cela s''oppose à Arius, qui lui retire la divinité.", "tip": "Dieu parfait, homme parfait.", "extraExample": {"text": "La liste de 27 livres d''Athanase est celle de toutes nos Bibles chrétiennes d''aujourd''hui.", "translation": "Un évêque d''Alexandrie a donc aidé à fixer notre Nouveau Testament."}, "errorPatterns": [{"equals": "Un ange", "category": "word_confusion", "feedback": "Le Christ n''est pas un ange : il est Dieu fait homme."}], "id": "eg.l29.e03", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e04', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.athanase']::text[], 'mcq', 'lesson', 'Auprès de quel saint Athanase se forme-t-il au désert ?', array['Saint Antoine']::text[], 'Athanase apprend auprès d''Antoine les commandements et l''amour de Dieu. Il écrira plus tard sa vie.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.athanase"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Auprès de quel saint Athanase se forme-t-il au désert ?", "promptLanguage": "fr", "options": ["Saint Antoine", "Saint Pacôme", "Saint Macaire", "Saint Georges"], "answer": "Saint Antoine", "acceptedAnswers": ["Saint Antoine"], "explanation": "Athanase apprend auprès d''Antoine les commandements et l''amour de Dieu. Il écrira plus tard sa vie.", "tip": "Antoine, maître d''Athanase.", "extraExample": {"text": "Athanase aurait dit : « le monde est contre moi, et je suis contre le monde ».", "translation": "Pour lui, tenir la vérité compte plus que d''avoir la foule avec soi."}, "id": "eg.l29.e04", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e05', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.athanase','eg.v.alexandre_d_alexandrie']::text[], 'mcq', 'lesson', 'Qui ordonne Athanase diacre et fait de lui son secrétaire privé ?', array['Le pape Alexandre']::text[], 'Alexandre rappelle Athanase du désert, l''ordonne diacre et en fait son secrétaire. Athanase le suit ensuite à Nicée.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.athanase", "eg.v.alexandre_d_alexandrie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui ordonne Athanase diacre et fait de lui son secrétaire privé ?", "promptLanguage": "fr", "options": ["Le pape Alexandre", "Le pape Pierre", "Constantin", "Antoine"], "answer": "Le pape Alexandre", "acceptedAnswers": ["Le pape Alexandre"], "explanation": "Alexandre rappelle Athanase du désert, l''ordonne diacre et en fait son secrétaire. Athanase le suit ensuite à Nicée.", "tip": "Alexandre forme son successeur.", "extraExample": {"text": "Athanase reste patriarche plus de quarante ans, malgré les exils.", "translation": "Toute une vie donnée à une seule question : Jésus est-il Dieu ?"}, "id": "eg.l29.e05", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e06', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.athanase']::text[], 'fill_blank', 'lesson', 'Athanase devient le XXe patriarche du siège de saint ___.', array['Marc']::text[], 'L''Église d''Alexandrie a été fondée par saint Marc. Son siège est le siège de saint Marc.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.athanase"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Athanase devient le XXe patriarche du siège de saint ___.", "promptLanguage": "fr", "options": ["Marc", "Pierre", "Antoine", "Paul"], "answer": "Marc", "acceptedAnswers": ["Marc"], "explanation": "L''Église d''Alexandrie a été fondée par saint Marc. Son siège est le siège de saint Marc.", "tip": "Marc fonde, Athanase le continue.", "extraExample": {"text": "La liste de 27 livres d''Athanase est celle de toutes nos Bibles chrétiennes d''aujourd''hui.", "translation": "Un évêque d''Alexandrie a donc aidé à fixer notre Nouveau Testament."}, "errorPatterns": [{"equals": "Pierre", "category": "word_confusion", "feedback": "Pierre est le pape-martyr de 311, pas le fondateur."}], "id": "eg.l29.e06", "pool": "lesson", "lessonId": "eg.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e07', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.defenseur_de_la_foi']::text[], 'mcq', 'lesson', 'Que répond Athanase quand on lui dit « le monde est contre toi » ?', array['« Et je suis contre le monde »']::text[], 'Athanase tient la foi contre tous ceux qui s''y opposent. Il préfère être seul avec la vérité que nombreux dans l''erreur.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.defenseur_de_la_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond Athanase quand on lui dit « le monde est contre toi » ?", "promptLanguage": "fr", "options": ["« Et je suis contre le monde »", "« Je cède »", "« Dieu m''a abandonné »", "« Je pars en exil »"], "answer": "« Et je suis contre le monde »", "acceptedAnswers": ["« Et je suis contre le monde »"], "explanation": "Athanase tient la foi contre tous ceux qui s''y opposent. Il préfère être seul avec la vérité que nombreux dans l''erreur.", "tip": "Athanase contre le monde.", "extraExample": {"text": "Athanase aurait dit : « le monde est contre moi, et je suis contre le monde ».", "translation": "Pour lui, tenir la vérité compte plus que d''avoir la foule avec soi."}, "id": "eg.l29.e07", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e08', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.defenseur_de_la_foi']::text[], 'mcq', 'lesson', 'Pourquoi dit-on que l''Église doit tant à Athanase ?', array['Sans lui, le monde entier aurait suivi Arius']::text[], 'Son courage a empêché l''arianisme de devenir la foi de tous. D''où son surnom de défenseur de la foi.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.defenseur_de_la_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi dit-on que l''Église doit tant à Athanase ?", "promptLanguage": "fr", "options": ["Sans lui, le monde entier aurait suivi Arius", "Il a construit Constantinople", "Il a converti Constantin", "Il a fondé la première église"], "answer": "Sans lui, le monde entier aurait suivi Arius", "acceptedAnswers": ["Sans lui, le monde entier aurait suivi Arius"], "explanation": "Son courage a empêché l''arianisme de devenir la foi de tous. D''où son surnom de défenseur de la foi.", "tip": "Sans Athanase, Arius gagnait.", "extraExample": {"text": "Athanase reste patriarche plus de quarante ans, malgré les exils.", "translation": "Toute une vie donnée à une seule question : Jésus est-il Dieu ?"}, "id": "eg.l29.e08", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e09', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.exils_d_athanase']::text[], 'fill_blank', 'lesson', 'Pendant ses exils, Athanase se cache parfois chez les ___ du désert.', array['moines']::text[], 'Les moines du désert protègent Athanase. Leur foi et la sienne se rejoignent.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.exils_d_athanase"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Pendant ses exils, Athanase se cache parfois chez les ___ du désert.", "promptLanguage": "fr", "options": ["moines", "empereurs", "soldats", "marchands"], "answer": "moines", "acceptedAnswers": ["moines"], "explanation": "Les moines du désert protègent Athanase. Leur foi et la sienne se rejoignent.", "tip": "Athanase se réfugie chez les moines.", "extraExample": {"text": "La liste de 27 livres d''Athanase est celle de toutes nos Bibles chrétiennes d''aujourd''hui.", "translation": "Un évêque d''Alexandrie a donc aidé à fixer notre Nouveau Testament."}, "id": "eg.l29.e09", "pool": "lesson", "lessonId": "eg.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e10', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.vie_d_antoine']::text[], 'mcq', 'lesson', 'Quel livre d''Athanase est envoyé à Rome et diffuse le monachisme ?', array['La Vie d''Antoine']::text[], 'La Vie d''Antoine raconte la vocation du père des moines. Elle aide à répandre le monachisme en Occident. L''Histoire ecclésiastique est d''Eusèbe de Césarée.', 1, '{"unitIds": ["eg.g29.athanase", "eg.v.vie_d_antoine"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel livre d''Athanase est envoyé à Rome et diffuse le monachisme ?", "promptLanguage": "fr", "options": ["La Vie d''Antoine", "Sur l''incarnation du Verbe", "Le credo de Nicée", "L''Histoire ecclésiastique"], "answer": "La Vie d''Antoine", "acceptedAnswers": ["La Vie d''Antoine"], "explanation": "La Vie d''Antoine raconte la vocation du père des moines. Elle aide à répandre le monachisme en Occident. L''Histoire ecclésiastique est d''Eusèbe de Césarée.", "tip": "Athanase raconte Antoine.", "extraExample": {"text": "Athanase aurait dit : « le monde est contre moi, et je suis contre le monde ».", "translation": "Pour lui, tenir la vérité compte plus que d''avoir la foule avec soi."}, "errorPatterns": [{"equals": "L''Histoire ecclésiastique", "category": "word_confusion", "feedback": "C''est l''œuvre d''Eusèbe de Césarée."}], "id": "eg.l29.e10", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e11', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.canon_du_nouveau_testament']::text[], 'mcq', 'lesson', 'Que contient la lettre d''Athanase de 367 ?', array['La liste des 27 livres du Nouveau Testament']::text[], 'En 367, Athanase donne la liste officielle (le canon) du Nouveau Testament. Ce sont les mêmes 27 livres que nous lisons.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.canon_du_nouveau_testament"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que contient la lettre d''Athanase de 367 ?", "promptLanguage": "fr", "options": ["La liste des 27 livres du Nouveau Testament", "Le credo de Nicée", "La condamnation d''Apollinaire", "Les vingt canons"], "answer": "La liste des 27 livres du Nouveau Testament", "acceptedAnswers": ["La liste des 27 livres du Nouveau Testament"], "explanation": "En 367, Athanase donne la liste officielle (le canon) du Nouveau Testament. Ce sont les mêmes 27 livres que nous lisons.", "tip": "367 = le canon.", "extraExample": {"text": "Athanase reste patriarche plus de quarante ans, malgré les exils.", "translation": "Toute une vie donnée à une seule question : Jésus est-il Dieu ?"}, "id": "eg.l29.e11", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e12', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.canon_du_nouveau_testament']::text[], 'fill_blank', 'lesson', 'Le Nouveau Testament compte ___ livres.', array['27']::text[], 'Le canon du Nouveau Testament compte 27 livres : Athanase en donne la liste en 367.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.canon_du_nouveau_testament"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le Nouveau Testament compte ___ livres.", "promptLanguage": "fr", "options": ["27", "12", "22", "66"], "answer": "27", "acceptedAnswers": ["27"], "explanation": "Le canon du Nouveau Testament compte 27 livres : Athanase en donne la liste en 367.", "tip": "27 livres.", "extraExample": {"text": "La liste de 27 livres d''Athanase est celle de toutes nos Bibles chrétiennes d''aujourd''hui.", "translation": "Un évêque d''Alexandrie a donc aidé à fixer notre Nouveau Testament."}, "id": "eg.l29.e12", "pool": "lesson", "lessonId": "eg.l29", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e13', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.canon_du_nouveau_testament']::text[], 'mcq', 'lesson', 'Quel synode confirme à son tour ces 27 livres en 397 ?', array['Le synode de Carthage']::text[], 'En 397, le synode de Carthage reconnaît les 27 livres. Athanase l''avait fait trente ans plus tôt, en 367.', 3, '{"unitIds": ["eg.g29.athanase", "eg.v.canon_du_nouveau_testament"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel synode confirme à son tour ces 27 livres en 397 ?", "promptLanguage": "fr", "options": ["Le synode de Carthage", "Le concile de Nicée", "Le concile d''Éphèse", "Le synode d''Antioche"], "answer": "Le synode de Carthage", "acceptedAnswers": ["Le synode de Carthage"], "explanation": "En 397, le synode de Carthage reconnaît les 27 livres. Athanase l''avait fait trente ans plus tôt, en 367.", "tip": "367 Athanase, 397 Carthage.", "extraExample": {"text": "Athanase aurait dit : « le monde est contre moi, et je suis contre le monde ».", "translation": "Pour lui, tenir la vérité compte plus que d''avoir la foule avec soi."}, "id": "eg.l29.e13", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e14', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.frumentius']::text[], 'mcq', 'lesson', 'Qui Athanase ordonne-t-il premier évêque d''Éthiopie ?', array['Frumentius']::text[], 'Athanase envoie la foi jusqu''en Éthiopie en ordonnant Frumentius vers 341.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.frumentius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui Athanase ordonne-t-il premier évêque d''Éthiopie ?", "promptLanguage": "fr", "options": ["Frumentius", "Antoine", "Arius", "Macaire"], "answer": "Frumentius", "acceptedAnswers": ["Frumentius"], "explanation": "Athanase envoie la foi jusqu''en Éthiopie en ordonnant Frumentius vers 341.", "tip": "Frumentius = Éthiopie.", "extraExample": {"text": "Athanase reste patriarche plus de quarante ans, malgré les exils.", "translation": "Toute une vie donnée à une seule question : Jésus est-il Dieu ?"}, "id": "eg.l29.e14", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l29.e15', 'eg', 'eg.l29', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.athanase','eg.v.frumentius','eg.v.canon_du_nouveau_testament']::text[], 'match', 'lesson', 'Quatre dates d''Athanase.', '{}'::text[], 'Ces quatre repères suffisent pour situer Athanase.', 3, '{"unitIds": ["eg.g29.athanase", "eg.v.athanase", "eg.v.frumentius", "eg.v.canon_du_nouveau_testament"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quatre dates d''Athanase.", "promptLanguage": "fr", "pairs": [{"left": "Vers 298", "right": "naissance d''Athanase"}, {"left": "Vers 341", "right": "Frumentius, premier évêque d''Éthiopie"}, {"left": "367", "right": "la liste des 27 livres"}, {"left": "373", "right": "mort d''Athanase"}], "answer": "Vers 298 = naissance d''Athanase ; Vers 341 = Frumentius, premier évêque d''Éthiopie ; 367 = la liste des 27 livres ; 373 = mort d''Athanase", "acceptedAnswers": [], "explanation": "Ces quatre repères suffisent pour situer Athanase.", "tip": "298, 341, 367, 373.", "extraExample": {"text": "La liste de 27 livres d''Athanase est celle de toutes nos Bibles chrétiennes d''aujourd''hui.", "translation": "Un évêque d''Alexandrie a donc aidé à fixer notre Nouveau Testament."}, "id": "eg.l29.e15", "pool": "lesson", "lessonId": "eg.l29", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecate