insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e19', 'eg', 'eg.l30', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.les_318_eveques','eg.v.les_318_eveques']::text[], 'fill_blank', 'lesson', 'Le concile de Nicée réunit, selon la tradition, ___ évêques.', array['318']::text[], 'Le nombre traditionnel des évêques de Nicée est 318.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.les_318_eveques", "eg.v.les_318_eveques"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le concile de Nicée réunit, selon la tradition, ___ évêques.", "promptLanguage": "fr", "options": ["318", "150", "200", "12"], "answer": "318", "acceptedAnswers": ["318"], "explanation": "Le nombre traditionnel des évêques de Nicée est 318.", "tip": "318 à Nicée.", "extraExample": {"text": "Aujourd''hui encore, des moines vivent dans le désert de Wadi Natroun, là où vécut saint Macaire.", "translation": "La tradition n''a jamais été interrompue depuis le IVe siècle."}, "id": "eg.l30.e19", "pool": "lesson", "lessonId": "eg.l30", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e20', 'eg', 'eg.l30', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.constantin','eg.v.constantin']::text[], 'mcq', 'lesson', 'Quel empereur fonde Constantinople en 330 ?', array['Constantin']::text[], 'Constantin fait de Byzance une ville chrétienne et lui donne son nom.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.constantin", "eg.v.constantin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur fonde Constantinople en 330 ?", "promptLanguage": "fr", "options": ["Constantin", "Théodose Ier", "Licinius", "Dioclétien"], "answer": "Constantin", "acceptedAnswers": ["Constantin"], "explanation": "Constantin fait de Byzance une ville chrétienne et lui donne son nom.", "tip": "Constantin → Constantinople.", "extraExample": {"text": "Le monastère de saint Antoine, près de la mer Rouge, est l''un des plus anciens monastères du monde.", "translation": "Il garde le souvenir du père des moines."}, "id": "eg.l30.e20", "pool": "lesson", "lessonId": "eg.l30", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l30.e21', 'eg', 'eg.l30', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.frumentius','eg.v.frumentius']::text[], 'free_answer', 'lesson', 'Dans quel pays Athanase envoie-t-il Frumentius comme premier évêque ?', array['L''Éthiopie','Éthiopie','ethiopie']::text[], 'Athanase ordonne Frumentius premier évêque d''Éthiopie vers 341.', 3, '{"unitIds": ["eg.g29.athanase", "eg.v.frumentius", "eg.v.frumentius"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Dans quel pays Athanase envoie-t-il Frumentius comme premier évêque ?", "promptLanguage": "fr", "answer": "L''Éthiopie", "acceptedAnswers": ["L''Éthiopie", "Éthiopie", "ethiopie"], "explanation": "Athanase ordonne Frumentius premier évêque d''Éthiopie vers 341.", "tip": "Frumentius → Éthiopie.", "extraExample": {"text": "Saint Benoît (VIe siècle) a rédigé sa règle de 73 chapitres pour le Mont-Cassin.", "translation": "La vie communautaire d''Égypte a inspiré les moines d''Occident."}, "id": "eg.l30.e21", "pool": "lesson", "lessonId": "eg.l30", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e01', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.theodose_ier','eg.v.apollinaire','eg.v.macedonius','eg.v.pape_timothee']::text[], 'match', 'lesson', 'Qui est qui au concile de 381 ?', '{}'::text[], 'Théodose convoque, Timothée défend la foi, et Apollinaire et Macédonius sont condamnés.', 1, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.theodose_ier", "eg.v.apollinaire", "eg.v.macedonius", "eg.v.pape_timothee"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui est qui au concile de 381 ?", "promptLanguage": "fr", "pairs": [{"left": "Théodose Ier", "right": "convoque le concile"}, {"left": "Apollinaire", "right": "nie l''âme humaine du Christ"}, {"left": "Macédonius", "right": "dit que l''Esprit Saint est créé"}, {"left": "Le pape Timothée", "right": "pape d''Alexandrie présent au concile"}], "answer": "Théodose Ier = convoque le concile ; Apollinaire = nie l''âme humaine du Christ ; Macédonius = dit que l''Esprit Saint est créé ; Le pape Timothée = pape d''Alexandrie présent au concile", "acceptedAnswers": [], "explanation": "Théodose convoque, Timothée défend la foi, et Apollinaire et Macédonius sont condamnés.", "tip": "Théodose convoque, Timothée répond, deux hérétiques condamnés.", "extraExample": {"text": "Le Credo que tu récites à la messe est celui de Nicée complété à Constantinople.", "translation": "Les 318 pères de Nicée et les 150 de Constantinople sont donc présents dans ta prière."}, "id": "eg.l31.e01", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e02', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.theodose_ier']::text[], 'mcq', 'lesson', 'Qui convoque le concile de Constantinople ?', array['L''empereur Théodose Ier']::text[], 'Théodose Ier convoque le deuxième concile en 381. Constantin avait convoqué Nicée en 325 ; Théodose II convoquera Éphèse en 431.', 1, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.theodose_ier"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui convoque le concile de Constantinople ?", "promptLanguage": "fr", "options": ["L''empereur Théodose Ier", "L''empereur Constantin", "Le pape Alexandre", "L''empereur Théodose II"], "answer": "L''empereur Théodose Ier", "acceptedAnswers": ["L''empereur Théodose Ier"], "explanation": "Théodose Ier convoque le deuxième concile en 381. Constantin avait convoqué Nicée en 325 ; Théodose II convoquera Éphèse en 431.", "tip": "Théodose Ier = 381.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "errorPatterns": [{"equals": "L''empereur Constantin", "category": "word_confusion", "feedback": "Constantin convoque le premier concile, Nicée."}, {"equals": "L''empereur Théodose II", "category": "word_confusion", "feedback": "Théodose II convoquera Éphèse, plus tard."}], "id": "eg.l31.e02", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e03', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'mcq', 'lesson', 'Combien d''évêques se réunissent à Constantinople ?', array['150']::text[], '150 évêques à Constantinople, contre 318 à Nicée et 200 à Éphèse.', 1, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''évêques se réunissent à Constantinople ?", "promptLanguage": "fr", "options": ["150", "318", "200", "12"], "answer": "150", "acceptedAnswers": ["150"], "explanation": "150 évêques à Constantinople, contre 318 à Nicée et 200 à Éphèse.", "tip": "150 à Constantinople.", "extraExample": {"text": "En 381, Constantinople n''a que cinquante ans d''existence.", "translation": "Une ville toute neuve accueille déjà un concile œcuménique."}, "errorPatterns": [{"equals": "318", "category": "word_confusion", "feedback": "318, c''est Nicée."}, {"equals": "200", "category": "word_confusion", "feedback": "200, c''est Éphèse."}], "id": "eg.l31.e03", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e04', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'fill_blank', 'lesson', 'Le concile de Constantinople se tient en ___.', array['381']::text[], '381 est l''année du deuxième concile œcuménique.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le concile de Constantinople se tient en ___.", "promptLanguage": "fr", "options": ["381", "325", "431", "313"], "answer": "381", "acceptedAnswers": ["381"], "explanation": "381 est l''année du deuxième concile œcuménique.", "tip": "Nicée 325, Constantinople 381.", "extraExample": {"text": "Le Credo que tu récites à la messe est celui de Nicée complété à Constantinople.", "translation": "Les 318 pères de Nicée et les 150 de Constantinople sont donc présents dans ta prière."}, "errorPatterns": [{"equals": "325", "category": "word_confusion", "feedback": "325, c''est Nicée."}, {"equals": "431", "category": "word_confusion", "feedback": "431, c''est Éphèse."}], "id": "eg.l31.e04", "pool": "lesson", "lessonId": "eg.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e05', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'mcq', 'lesson', 'Quelle ville s''ajoute aux quatre sièges principaux, à Constantinople ?', array['Constantinople']::text[], 'Les quatre sièges sont Alexandrie, Antioche, Rome et Jérusalem. Après sa fondation, Constantinople devient le cinquième.', 3, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle ville s''ajoute aux quatre sièges principaux, à Constantinople ?", "promptLanguage": "fr", "options": ["Constantinople", "Éphèse", "Nicée", "Carthage"], "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "Les quatre sièges sont Alexandrie, Antioche, Rome et Jérusalem. Après sa fondation, Constantinople devient le cinquième.", "tip": "4 sièges + Constantinople = 5.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "id": "eg.l31.e05", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e06', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.religion_d_etat_380']::text[], 'mcq', 'lesson', 'Que se passe-t-il en 380 ?', array['Le christianisme est proclamé religion de l''État']::text[], 'En 380, sous Théodose Ier, le christianisme devient la religion de l''État. L''édit de Milan (313) avait seulement donné la liberté.', 1, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.religion_d_etat_380"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que se passe-t-il en 380 ?", "promptLanguage": "fr", "options": ["Le christianisme est proclamé religion de l''État", "Le concile de Nicée", "L''édit de Milan", "La mort de Constantin"], "answer": "Le christianisme est proclamé religion de l''État", "acceptedAnswers": ["Le christianisme est proclamé religion de l''État"], "explanation": "En 380, sous Théodose Ier, le christianisme devient la religion de l''État. L''édit de Milan (313) avait seulement donné la liberté.", "tip": "380 = religion de l''État.", "extraExample": {"text": "En 381, Constantinople n''a que cinquante ans d''existence.", "translation": "Une ville toute neuve accueille déjà un concile œcuménique."}, "errorPatterns": [{"equals": "L''édit de Milan", "category": "word_confusion", "feedback": "C''est 313, la liberté de culte."}], "id": "eg.l31.e06", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e07', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.apollinaire']::text[], 'mcq', 'lesson', 'Que soutient Apollinaire de Laodicée ?', array['Un corps humain mais sans son âme']::text[], 'Pour Apollinaire, la divinité du Verbe tient lieu d''âme et d''esprit : le Christ n''aurait pas d''âme humaine.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.apollinaire"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que soutient Apollinaire de Laodicée ?", "promptLanguage": "fr", "options": ["Un corps humain mais sans son âme", "Une âme humaine mais sans corps", "Deux personnes dans le Christ", "Un Christ créé"], "answer": "Un corps humain mais sans son âme", "acceptedAnswers": ["Un corps humain mais sans son âme"], "explanation": "Pour Apollinaire, la divinité du Verbe tient lieu d''âme et d''esprit : le Christ n''aurait pas d''âme humaine.", "tip": "Corps oui, âme non.", "extraExample": {"text": "Le Credo que tu récites à la messe est celui de Nicée complété à Constantinople.", "translation": "Les 318 pères de Nicée et les 150 de Constantinople sont donc présents dans ta prière."}, "errorPatterns": [{"equals": "Un Christ créé", "category": "word_confusion", "feedback": "C''est la position d''Arius."}], "id": "eg.l31.e07", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e08', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.apollinaire','eg.v.pape_timothee']::text[], 'mcq', 'lesson', 'Que répond le pape Timothée à Apollinaire ?', array['Il n''a pas sauvé les hommes mais les animaux']::text[], 'Si le Verbe n''avait pris qu''un corps animal, il aurait sauvé des animaux. Mais l''homme a une âme et une intelligence : le Verbe se fait homme tout entier.', 3, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.apollinaire", "eg.v.pape_timothee"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond le pape Timothée à Apollinaire ?", "promptLanguage": "fr", "options": ["Il n''a pas sauvé les hommes mais les animaux", "Il a sauvé les anges", "Il a seulement sauvé les chrétiens", "Il n''a sauvé personne"], "answer": "Il n''a pas sauvé les hommes mais les animaux", "acceptedAnswers": ["Il n''a pas sauvé les hommes mais les animaux"], "explanation": "Si le Verbe n''avait pris qu''un corps animal, il aurait sauvé des animaux. Mais l''homme a une âme et une intelligence : le Verbe se fait homme tout entier.", "tip": "Sans âme humaine, pas de salut humain.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "id": "eg.l31.e08", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e09', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.macedonius']::text[], 'mcq', 'lesson', 'Que soutient Macédonius à propos du Saint-Esprit ?', array['Le Saint-Esprit a été créé']::text[], 'Macédonius nie la divinité de l''Esprit Saint, comme Arius celle du Fils. Le concile affirme l''Esprit Seigneur et vivifiant.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.macedonius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que soutient Macédonius à propos du Saint-Esprit ?", "promptLanguage": "fr", "options": ["Le Saint-Esprit a été créé", "Le Saint-Esprit est le Père", "Le Saint-Esprit n''existe pas", "Le Saint-Esprit est un ange"], "answer": "Le Saint-Esprit a été créé", "acceptedAnswers": ["Le Saint-Esprit a été créé"], "explanation": "Macédonius nie la divinité de l''Esprit Saint, comme Arius celle du Fils. Le concile affirme l''Esprit Seigneur et vivifiant.", "tip": "Arius touche le Fils, Macédonius l''Esprit.", "extraExample": {"text": "En 381, Constantinople n''a que cinquante ans d''existence.", "translation": "Une ville toute neuve accueille déjà un concile œcuménique."}, "id": "eg.l31.e09", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e10', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.credo_de_nicee_constantinople']::text[], 'fill_blank', 'lesson', 'Les pères complètent le credo à partir de « Je crois en l''___ ».', array['Esprit Saint']::text[], 'Nicée finissait par « et en l''Esprit Saint ». Constantinople développe l''article sur l''Esprit Saint et ajoute la suite.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.credo_de_nicee_constantinople"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les pères complètent le credo à partir de « Je crois en l''___ ».", "promptLanguage": "fr", "options": ["Esprit Saint", "Église catholique", "Fils unique", "Père tout-puissant"], "answer": "Esprit Saint", "acceptedAnswers": ["Esprit Saint"], "explanation": "Nicée finissait par « et en l''Esprit Saint ». Constantinople développe l''article sur l''Esprit Saint et ajoute la suite.", "tip": "Constantinople complète sur l''Esprit.", "extraExample": {"text": "Le Credo que tu récites à la messe est celui de Nicée complété à Constantinople.", "translation": "Les 318 pères de Nicée et les 150 de Constantinople sont donc présents dans ta prière."}, "id": "eg.l31.e10", "pool": "lesson", "lessonId": "eg.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e11', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'free_answer', 'lesson', 'Combien de canons le concile de Constantinople établit-il ?', array['7','sept','7 canons','sept canons']::text[], 'Constantinople établit sept canons, dont celui sur le rang de Constantinople.', 3, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Combien de canons le concile de Constantinople établit-il ?", "promptLanguage": "fr", "answer": "7", "acceptedAnswers": ["7", "sept", "7 canons", "sept canons"], "explanation": "Constantinople établit sept canons, dont celui sur le rang de Constantinople.", "tip": "7 canons.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "id": "eg.l31.e11", "pool": "lesson", "lessonId": "eg.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e12', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'mcq', 'lesson', 'Quel canon de Constantinople le siège d''Alexandrie n''a-t-il pas accepté ?', array['Constantinople est le deuxième siège après celui de Rome']::text[], 'Alexandrie ne reconnaît pas ce rang : elle occupait la deuxième place depuis Nicée, et ne veut pas qu''un siège gagne en rang parce que la ville est capitale.', 3, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel canon de Constantinople le siège d''Alexandrie n''a-t-il pas accepté ?", "promptLanguage": "fr", "options": ["Constantinople est le deuxième siège après celui de Rome", "Les évêques doivent se marier", "Le credo est supprimé", "Alexandrie perd son pape"], "answer": "Constantinople est le deuxième siège après celui de Rome", "acceptedAnswers": ["Constantinople est le deuxième siège après celui de Rome"], "explanation": "Alexandrie ne reconnaît pas ce rang : elle occupait la deuxième place depuis Nicée, et ne veut pas qu''un siège gagne en rang parce que la ville est capitale.", "tip": "Alexandrie refuse la « nouvelle Rome ».", "extraExample": {"text": "En 381, Constantinople n''a que cinquante ans d''existence.", "translation": "Une ville toute neuve accueille déjà un concile œcuménique."}, "id": "eg.l31.e12", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
