insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e17', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.macedonius']::text[], 'free_answer', 'lesson', 'Quel patriarche de Constantinople dit que le Saint-Esprit est créé ?', array['Macédonius','macedonius']::text[], 'Macédonius nie la divinité du Saint-Esprit. Le concile de 381 le condamne.', 3, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.macedonius"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel patriarche de Constantinople dit que le Saint-Esprit est créé ?", "promptLanguage": "fr", "answer": "Macédonius", "acceptedAnswers": ["Macédonius", "macedonius"], "explanation": "Macédonius nie la divinité du Saint-Esprit. Le concile de 381 le condamne.", "tip": "Macédonius = Esprit créé.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "id": "eg.l31.e17", "pool": "lesson", "lessonId": "eg.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
