insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e19', 'eg', 'eg.l31', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.concile_de_constantinople']::text[], 'reorder', 'lesson', 'Phrase-repère : le deuxième concile.', array['Le concile de Constantinople se tient en 381','En 381 le concile de Constantinople se tient']::text[], 'Théodose Ier, 150 évêques, contre Apollinaire et Macédonius.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.concile_de_constantinople"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le deuxième concile.", "promptLanguage": "fr", "tokens": ["de", "tient", "Constantinople", "concile", "Le", "381", "se", "en"], "answer": "Le concile de Constantinople se tient en 381", "acceptedAnswers": ["Le concile de Constantinople se tient en 381", "En 381 le concile de Constantinople se tient"], "explanation": "Théodose Ier, 150 évêques, contre Apollinaire et Macédonius.", "tip": "Constantinople 381.", "extraExample": {"text": "Le Credo que tu récites à la messe est celui de Nicée complété à Constantinople.", "translation": "Les 318 pères de Nicée et les 150 de Constantinople sont donc présents dans ta prière."}, "id": "eg.l31.e19", "pool": "lesson", "lessonId": "eg.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e20', 'eg', 'eg.l31', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.concile_de_nicee','eg.v.concile_de_nicee']::text[], 'fill_blank', 'lesson', 'Le premier concile œcuménique se tient à ___.', array['Nicée']::text[], 'Nicée (325) précède Constantinople (381).', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.concile_de_nicee", "eg.v.concile_de_nicee"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le premier concile œcuménique se tient à ___.", "promptLanguage": "fr", "options": ["Nicée", "Constantinople", "Éphèse", "Antioche"], "answer": "Nicée", "acceptedAnswers": ["Nicée"], "explanation": "Nicée (325) précède Constantinople (381).", "tip": "Nicée d''abord.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "id": "eg.l31.e20", "pool": "lesson", "lessonId": "eg.l31", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e21', 'eg', 'eg.l31', 'eg.g29.athanase', array['eg.g29.athanase','eg.v.defenseur_de_la_foi','eg.v.defenseur_de_la_foi']::text[], 'mcq', 'lesson', 'Qui a répondu « et je suis contre le monde » ?', array['Athanase']::text[], 'Athanase défend la foi de Nicée contre le monde entier : c''est le défenseur de la foi.', 2, '{"unitIds": ["eg.g29.athanase", "eg.v.defenseur_de_la_foi", "eg.v.defenseur_de_la_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui a répondu « et je suis contre le monde » ?", "promptLanguage": "fr", "options": ["Athanase", "Arius", "Pacôme", "Grégoire"], "answer": "Athanase", "acceptedAnswers": ["Athanase"], "explanation": "Athanase défend la foi de Nicée contre le monde entier : c''est le défenseur de la foi.", "tip": "Athanase contre le monde.", "extraExample": {"text": "En 381, Constantinople n''a que cinquante ans d''existence.", "translation": "Une ville toute neuve accueille déjà un concile œcuménique."}, "id": "eg.l31.e21", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e22', 'eg', 'eg.l31', 'eg.g27.arius', array['eg.g27.arius','eg.v.arianisme','eg.v.arianisme']::text[], 'mcq', 'lesson', 'Quelle doctrine dit que le Fils est créé ?', array['L''arianisme']::text[], 'Pour l''arianisme, le Fils est un être créé. Apollinaire concerne l''âme du Christ, Macédonius l''Esprit Saint.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.arianisme", "eg.v.arianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle doctrine dit que le Fils est créé ?", "promptLanguage": "fr", "options": ["L''arianisme", "L''apollinarisme", "Le semi-arianisme", "L''orthodoxie"], "answer": "L''arianisme", "acceptedAnswers": ["L''arianisme"], "explanation": "Pour l''arianisme, le Fils est un être créé. Apollinaire concerne l''âme du Christ, Macédonius l''Esprit Saint.", "tip": "Arius = Fils créé.", "extraExample": {"text": "Le Credo que tu récites à la messe est celui de Nicée complété à Constantinople.", "translation": "Les 318 pères de Nicée et les 150 de Constantinople sont donc présents dans ta prière."}, "id": "eg.l31.e22", "pool": "lesson", "lessonId": "eg.l31", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l31.e23', 'eg', 'eg.l31', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.scete','eg.v.scete']::text[], 'free_answer', 'lesson', 'Dans quel désert saint Macaire le Grand rassemble-t-il ses disciples ?', array['Scété','le désert de Scété','scete']::text[], 'Macaire vit à Scété, où des moines se rassemblent autour de lui.', 2, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.scete", "eg.v.scete"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Dans quel désert saint Macaire le Grand rassemble-t-il ses disciples ?", "promptLanguage": "fr", "answer": "Scété", "acceptedAnswers": ["Scété", "le désert de Scété", "scete"], "explanation": "Macaire vit à Scété, où des moines se rassemblent autour de lui.", "tip": "Macaire = Scété.", "extraExample": {"text": "Grégoire de Nazianze disait : ce que le Christ n''a pas pris, il ne l''a pas guéri.", "translation": "Si le Christ n''avait pas d''âme humaine, notre âme ne serait pas sauvée."}, "id": "eg.l31.e23", "pool": "lesson", "lessonId": "eg.l31", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e01', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.concile_de_nicee','eg.v.concile_de_constantinople','eg.v.edit_de_milan']::text[], 'match', 'lesson', 'Les dates du siècle.', '{}'::text[], 'Quatre dates charnières : persécution (303), paix (313), Nicée (325), Constantinople (381).', 2, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.concile_de_nicee", "eg.v.concile_de_constantinople", "eg.v.edit_de_milan"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les dates du siècle.", "promptLanguage": "fr", "pairs": [{"left": "303", "right": "les quatre édits de Dioclétien"}, {"left": "313", "right": "l''édit de Milan"}, {"left": "325", "right": "le concile de Nicée"}, {"left": "381", "right": "le concile de Constantinople"}], "answer": "303 = les quatre édits de Dioclétien ; 313 = l''édit de Milan ; 325 = le concile de Nicée ; 381 = le concile de Constantinople", "acceptedAnswers": [], "explanation": "Quatre dates charnières : persécution (303), paix (313), Nicée (325), Constantinople (381).", "tip": "303, 313, 325, 381.", "extraExample": {"text": "Basile, Grégoire et Cyrille : trois noms de liturgies que l''on entend dans l''Église copte.", "translation": "Ces saints ne sont pas seulement dans les livres : leurs prières sont dans ta messe."}, "id": "eg.l32.e01", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e02', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.arius','eg.v.apollinaire','eg.v.macedonius','eg.v.semi_arianisme']::text[], 'match', 'lesson', 'Quelle erreur pour quel hérétique ?', '{}'::text[], 'Chaque erreur touche un point du salut : le Fils, l''âme du Christ, l''Esprit.', 3, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.arius", "eg.v.apollinaire", "eg.v.macedonius", "eg.v.semi_arianisme"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle erreur pour quel hérétique ?", "promptLanguage": "fr", "pairs": [{"left": "Arius", "right": "le Fils est créé"}, {"left": "Apollinaire", "right": "le Christ n''a pas d''âme humaine"}, {"left": "Macédonius", "right": "le Saint-Esprit est créé"}, {"left": "Les semi-ariens", "right": "substance similaire"}], "answer": "Arius = le Fils est créé ; Apollinaire = le Christ n''a pas d''âme humaine ; Macédonius = le Saint-Esprit est créé ; Les semi-ariens = substance similaire", "acceptedAnswers": [], "explanation": "Chaque erreur touche un point du salut : le Fils, l''âme du Christ, l''Esprit.", "tip": "Fils, âme, Esprit.", "extraExample": {"text": "Augustin devient chrétien grâce à la prédication d''Ambroise à Milan.", "translation": "Un évêque convaincant peut changer la vie d''un des plus grands penseurs chrétiens."}, "id": "eg.l32.e02", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e03', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_nicolas_de_myre','eg.v.saint_ephrem_le_syrien','eg.v.saint_basile_le_grand','eg.v.saint_ambroise_de_milan']::text[], 'match', 'lesson', 'Les grands saints et leur année de mort.', '{}'::text[], 'Ces quatre saints rythment le IVe siècle.', 3, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.saint_nicolas_de_myre", "eg.v.saint_ephrem_le_syrien", "eg.v.saint_basile_le_grand", "eg.v.saint_ambroise_de_milan"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les grands saints et leur année de mort.", "promptLanguage": "fr", "pairs": [{"left": "Nicolas de Myre", "right": "343"}, {"left": "Éphrem le Syrien", "right": "373"}, {"left": "Basile le Grand", "right": "379"}, {"left": "Ambroise de Milan", "right": "397"}], "answer": "Nicolas de Myre = 343 ; Éphrem le Syrien = 373 ; Basile le Grand = 379 ; Ambroise de Milan = 397", "acceptedAnswers": [], "explanation": "Ces quatre saints rythment le IVe siècle.", "tip": "343, 373, 379, 397.", "extraExample": {"text": "Entre 301 et 381, l''Église passe de la persécution à la religion de l''État.", "translation": "Quatre-vingts ans pour tout changer : c''est le siècle de tous les basculements."}, "id": "eg.l32.e03", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e04', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_jean_chrysostome']::text[], 'mcq', 'lesson', 'Quel saint est surnommé « bouche d''or » ?', array['Jean Chrysostome']::text[], 'Chrysostome vient du grec et veut dire « bouche d''or », en l''honneur de sa parole.', 1, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.saint_jean_chrysostome"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel saint est surnommé « bouche d''or » ?", "promptLanguage": "fr", "options": ["Jean Chrysostome", "Basile le Grand", "Augustin", "Ambroise"], "answer": "Jean Chrysostome", "acceptedAnswers": ["Jean Chrysostome"], "explanation": "Chrysostome vient du grec et veut dire « bouche d''or », en l''honneur de sa parole.", "tip": "Chrysostome = bouche d''or.", "extraExample": {"text": "Basile, Grégoire et Cyrille : trois noms de liturgies que l''on entend dans l''Église copte.", "translation": "Ces saints ne sont pas seulement dans les livres : leurs prières sont dans ta messe."}, "errorPatterns": [{"equals": "Augustin", "category": "word_confusion", "feedback": "Augustin est évêque d''Hippone."}], "id": "eg.l32.e04", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e05', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_augustin_d_hippone']::text[], 'mcq', 'lesson', 'De quelle ville saint Augustin est-il évêque ?', array['Hippone']::text[], 'Augustin est évêque d''Hippone, en Afrique du Nord. Il écrit les Confessions et meurt en 430.', 1, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.saint_augustin_d_hippone"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "De quelle ville saint Augustin est-il évêque ?", "promptLanguage": "fr", "options": ["Hippone", "Milan", "Alexandrie", "Constantinople"], "answer": "Hippone", "acceptedAnswers": ["Hippone"], "explanation": "Augustin est évêque d''Hippone, en Afrique du Nord. Il écrit les Confessions et meurt en 430.", "tip": "Augustin = Hippone.", "extraExample": {"text": "Augustin devient chrétien grâce à la prédication d''Ambroise à Milan.", "translation": "Un évêque convaincant peut changer la vie d''un des plus grands penseurs chrétiens."}, "errorPatterns": [{"equals": "Milan", "category": "word_confusion", "feedback": "Milan est la ville d''Ambroise."}], "id": "eg.l32.e05", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e06', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_ephrem_le_syrien']::text[], 'mcq', 'lesson', 'Qui est saint Éphrem le Syrien ?', array['Diacre syrien et poète']::text[], 'Éphrem est un diacre syrien et poète, auteur d''hymnes. Il meurt en 373.', 2, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.saint_ephrem_le_syrien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est saint Éphrem le Syrien ?", "promptLanguage": "fr", "options": ["Diacre syrien et poète", "Pape d''Alexandrie", "Évêque de Milan", "Empereur romain"], "answer": "Diacre syrien et poète", "acceptedAnswers": ["Diacre syrien et poète"], "explanation": "Éphrem est un diacre syrien et poète, auteur d''hymnes. Il meurt en 373.", "tip": "Éphrem le poète.", "extraExample": {"text": "Entre 301 et 381, l''Église passe de la persécution à la religion de l''État.", "translation": "Quatre-vingts ans pour tout changer : c''est le siècle de tous les basculements."}, "id": "eg.l32.e06", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e07', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_basile_le_grand']::text[], 'mcq', 'lesson', 'Quel saint, évêque de Césarée de Cappadoce, est ami de Grégoire de Nazianze ?', array['Basile le Grand']::text[], 'Basile est évêque de Césarée de Cappadoce. Sa liturgie est célébrée dans l''Église copte.', 2, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.saint_basile_le_grand"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel saint, évêque de Césarée de Cappadoce, est ami de Grégoire de Nazianze ?", "promptLanguage": "fr", "options": ["Basile le Grand", "Ambroise", "Nicolas de Myre", "Augustin"], "answer": "Basile le Grand", "acceptedAnswers": ["Basile le Grand"], "explanation": "Basile est évêque de Césarée de Cappadoce. Sa liturgie est célébrée dans l''Église copte.", "tip": "Basile et Grégoire, amis.", "extraExample": {"text": "Basile, Grégoire et Cyrille : trois noms de liturgies que l''on entend dans l''Église copte.", "translation": "Ces saints ne sont pas seulement dans les livres : leurs prières sont dans ta messe."}, "id": "eg.l32.e07", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e08', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.saint_basile_le_grand','eg.v.saint_gregoire_le_theologien']::text[], 'mcq', 'lesson', 'Quelles sont les trois liturgies divines de l''Église copte ?', array['Basile le Grand, Grégoire le Théologien et Cyrille']::text[], 'Ces trois noms désignent les liturgies que tu entends à la messe. Basile et Grégoire sont des Pères du IVe siècle.', 2, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.saint_basile_le_grand", "eg.v.saint_gregoire_le_theologien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles sont les trois liturgies divines de l''Église copte ?", "promptLanguage": "fr", "options": ["Basile le Grand, Grégoire le Théologien et Cyrille", "Antoine, Pacôme et Macaire", "Athanase, Alexandre et Pierre", "Ambroise, Augustin et Éphrem"], "answer": "Basile le Grand, Grégoire le Théologien et Cyrille", "acceptedAnswers": ["Basile le Grand, Grégoire le Théologien et Cyrille"], "explanation": "Ces trois noms désignent les liturgies que tu entends à la messe. Basile et Grégoire sont des Pères du IVe siècle.", "tip": "Basile, Grégoire, Cyrille.", "extraExample": {"text": "Augustin devient chrétien grâce à la prédication d''Ambroise à Milan.", "translation": "Un évêque convaincant peut changer la vie d''un des plus grands penseurs chrétiens."}, "id": "eg.l32.e08", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e09', 'eg', 'eg.l32', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.credo_de_nicee_constantinople','eg.v.credo_de_nicee_constantinople']::text[], 'mcq', 'lesson', 'Quel concile a complété le credo de Nicée sur le Saint-Esprit ?', array['Le concile de Constantinople']::text[], 'En 381, Constantinople ajoute toute la suite à partir de « Je crois en l''Esprit Saint ».', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.credo_de_nicee_constantinople", "eg.v.credo_de_nicee_constantinople"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile a complété le credo de Nicée sur le Saint-Esprit ?", "promptLanguage": "fr", "options": ["Le concile de Constantinople", "Le concile d''Éphèse", "Le concile de Chalcédoine", "Le concile de Carthage"], "answer": "Le concile de Constantinople", "acceptedAnswers": ["Le concile de Constantinople"], "explanation": "En 381, Constantinople ajoute toute la suite à partir de « Je crois en l''Esprit Saint ».", "tip": "381 = credo complété.", "extraExample": {"text": "Entre 301 et 381, l''Église passe de la persécution à la religion de l''État.", "translation": "Quatre-vingts ans pour tout changer : c''est le siècle de tous les basculements."}, "id": "eg.l32.e09", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e10', 'eg', 'eg.l32', 'eg.g28.concile_de_nicee', array['eg.g28.concile_de_nicee','eg.v.homoousios','eg.v.concile_de_nicee','eg.v.homoousios']::text[], 'mcq', 'lesson', 'Que définit le concile de Nicée à propos du Fils ?', array['Il a la même substance que le Père']::text[], 'Nicée affirme que le Fils est de même substance que le Père. Les autres formules sont des positions ariennes ou semi-ariennes.', 2, '{"unitIds": ["eg.g28.concile_de_nicee", "eg.v.homoousios", "eg.v.concile_de_nicee", "eg.v.homoousios"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que définit le concile de Nicée à propos du Fils ?", "promptLanguage": "fr", "options": ["Il a la même substance que le Père", "Il a une substance créée", "Il a une substance similaire à celle du Père", "Il est inférieur au Père"], "answer": "Il a la même substance que le Père", "acceptedAnswers": ["Il a la même substance que le Père"], "explanation": "Nicée affirme que le Fils est de même substance que le Père. Les autres formules sont des positions ariennes ou semi-ariennes.", "tip": "Nicée = homoousios.", "extraExample": {"text": "Basile, Grégoire et Cyrille : trois noms de liturgies que l''on entend dans l''Église copte.", "translation": "Ces saints ne sont pas seulement dans les livres : leurs prières sont dans ta messe."}, "id": "eg.l32.e10", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e11', 'eg', 'eg.l32', 'eg.g31.concile_de_constantinople', array['eg.g31.concile_de_constantinople','eg.v.religion_d_etat_380','eg.v.religion_d_etat_380']::text[], 'mcq', 'lesson', 'Quel événement marque l''année 380 ?', array['Le christianisme est proclamé religion de l''État']::text[], '380 : religion de l''État, sous Théodose Ier. Milan (313) avait donné seulement la liberté.', 2, '{"unitIds": ["eg.g31.concile_de_constantinople", "eg.v.religion_d_etat_380", "eg.v.religion_d_etat_380"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel événement marque l''année 380 ?", "promptLanguage": "fr", "options": ["Le christianisme est proclamé religion de l''État", "L''édit de Milan est signé", "Constantinople est fondée", "Arius est exilé"], "answer": "Le christianisme est proclamé religion de l''État", "acceptedAnswers": ["Le christianisme est proclamé religion de l''État"], "explanation": "380 : religion de l''État, sous Théodose Ier. Milan (313) avait donné seulement la liberté.", "tip": "380 = religion d''État.", "extraExample": {"text": "Augustin devient chrétien grâce à la prédication d''Ambroise à Milan.", "translation": "Un évêque convaincant peut changer la vie d''un des plus grands penseurs chrétiens."}, "id": "eg.l32.e11", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version