insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e12', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.concile_de_constantinople']::text[], 'mcq', 'lesson', 'Quel concile suit celui de Constantinople ?', array['Éphèse']::text[], 'Le troisième concile œcuménique est celui d''Éphèse, en 431, contre Nestorius.', 3, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.concile_de_constantinople"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile suit celui de Constantinople ?", "promptLanguage": "fr", "options": ["Éphèse", "Nicée", "Chalcédoine", "Jérusalem"], "answer": "Éphèse", "acceptedAnswers": ["Éphèse"], "explanation": "Le troisième concile œcuménique est celui d''Éphèse, en 431, contre Nestorius.", "tip": "381 puis 431 : Éphèse.", "extraExample": {"text": "Entre 301 et 381, l''Église passe de la persécution à la religion de l''État.", "translation": "Quatre-vingts ans pour tout changer : c''est le siècle de tous les basculements."}, "id": "eg.l32.e12", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e13', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.apollinaire']::text[], 'mcq', 'lesson', 'Quelle hérésie, condamnée à Constantinople, retire l''âme humaine au Christ ?', array['L''apollinarisme']::text[], 'L''apollinarisme est l''erreur d''Apollinaire de Laodicée : un Christ sans âme humaine.', 3, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.apollinaire"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle hérésie, condamnée à Constantinople, retire l''âme humaine au Christ ?", "promptLanguage": "fr", "options": ["L''apollinarisme", "L''arianisme", "Le macédonianisme", "Le semi-arianisme"], "answer": "L''apollinarisme", "acceptedAnswers": ["L''apollinarisme"], "explanation": "L''apollinarisme est l''erreur d''Apollinaire de Laodicée : un Christ sans âme humaine.", "tip": "Apollinaire → apollinarisme.", "extraExample": {"text": "Basile, Grégoire et Cyrille : trois noms de liturgies que l''on entend dans l''Église copte.", "translation": "Ces saints ne sont pas seulement dans les livres : leurs prières sont dans ta messe."}, "id": "eg.l32.e13", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e14', 'eg', 'eg.l32', 'eg.g27.arius', array['eg.g27.arius','eg.v.homoousios','eg.v.homoousios']::text[], 'fill_blank', 'lesson', 'Le credo de Nicée-Constantinople dit que le Fils est ___ au Père, de même substance.', array['consubstantiel']::text[], 'Consubstantiel traduit homoousios : de même substance que le Père.', 2, '{"unitIds": ["eg.g27.arius", "eg.v.homoousios", "eg.v.homoousios"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le credo de Nicée-Constantinople dit que le Fils est ___ au Père, de même substance.", "promptLanguage": "fr", "options": ["consubstantiel", "inférieur", "semblable", "créé"], "answer": "consubstantiel", "acceptedAnswers": ["consubstantiel"], "explanation": "Consubstantiel traduit homoousios : de même substance que le Père.", "tip": "Consubstantiel = même substance.", "extraExample": {"text": "Augustin devient chrétien grâce à la prédication d''Ambroise à Milan.", "translation": "Un évêque convaincant peut changer la vie d''un des plus grands penseurs chrétiens."}, "id": "eg.l32.e14", "pool": "lesson", "lessonId": "eg.l32", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e15', 'eg', 'eg.l32', 'eg.g26.constantin', array['eg.g26.constantin','eg.v.armenie','eg.v.armenie']::text[], 'fill_blank', 'lesson', 'En 301, ___ est le premier pays du monde à adopter le christianisme comme religion d''État.', array['l''Arménie']::text[], 'L''Arménie précède Rome de presque quatre-vingts ans.', 2, '{"unitIds": ["eg.g26.constantin", "eg.v.armenie", "eg.v.armenie"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En 301, ___ est le premier pays du monde à adopter le christianisme comme religion d''État.", "promptLanguage": "fr", "options": ["l''Arménie", "l''Égypte", "la Grèce", "Rome"], "answer": "l''Arménie", "acceptedAnswers": ["l''Arménie"], "explanation": "L''Arménie précède Rome de presque quatre-vingts ans.", "tip": "301 = Arménie.", "extraExample": {"text": "Entre 301 et 381, l''Église passe de la persécution à la religion de l''État.", "translation": "Quatre-vingts ans pour tout changer : c''est le siècle de tous les basculements."}, "id": "eg.l32.e15", "pool": "lesson", "lessonId": "eg.l32", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
