insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e21', 'eg', 'eg.l32', 'eg.g32.bilan_du_siecle', array['eg.g32.bilan_du_siecle','eg.v.concile_de_nicee','eg.v.concile_de_constantinople']::text[], 'reorder', 'lesson', 'Phrase-repère : les deux conciles.', array['Nicée en 325 puis Constantinople en 381']::text[], 'Nicée (325) définit le Fils ; Constantinople (381) complète le credo sur l''Esprit.', 2, '{"unitIds": ["eg.g32.bilan_du_siecle", "eg.v.concile_de_nicee", "eg.v.concile_de_constantinople"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : les deux conciles.", "promptLanguage": "fr", "tokens": ["381", "en", "Constantinople", "Nicée", "puis", "325", "en"], "answer": "Nicée en 325 puis Constantinople en 381", "acceptedAnswers": ["Nicée en 325 puis Constantinople en 381"], "explanation": "Nicée (325) définit le Fils ; Constantinople (381) complète le credo sur l''Esprit.", "tip": "325 puis 381.", "extraExample": {"text": "Entre 301 et 381, l''Église passe de la persécution à la religion de l''État.", "translation": "Quatre-vingts ans pour tout changer : c''est le siècle de tous les basculements."}, "id": "eg.l32.e21", "pool": "lesson", "lessonId": "eg.l32", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l32.e22', 'eg', 'eg.l32', 'eg.g30.peres_du_desert', array['eg.g30.peres_du_desert','eg.v.saint_pacome','eg.v.saint_pacome']::text[], 'mcq', 'lesson', 'Quel saint organise la vie communautaire dans les monastères de Haute-Égypte ?', array['Saint Pacôme']::text[], 'Pacôme organise la vie en communauté avec une règle.', 2, '{"unitIds": ["eg.g30.peres_du_desert", "eg.v.saint_pacome", "eg.v.saint_pacome"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel saint organise la vie communautaire dans les monastères de Haute-Égypte ?", "promptLanguage": "fr", "options": ["Saint Pacôme", "Saint Antoine", "Saint Macaire", "Saint Paul"], "answer": "Saint Pacôme", "acceptedAnswers": ["Saint Pacôme"], "explanation": "Pacôme organise la vie en communauté avec une règle.", "tip": "Pacôme = cénobite.", "extraExample": {"text": "Basile, Grégoire et Cyrille : trois noms de liturgies que l''on entend dans l''Église copte.", "translation": "Ces saints ne sont pas seulement dans les livres : leurs prières sont dans ta messe."}, "id": "eg.l32.e22", "pool": "lesson", "lessonId": "eg.l32", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e01', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.siege_apostolique']::text[], 'mcq', 'lesson', 'Combien de sièges apostoliques compte l''Église au début du Ve siècle ?', array['Cinq']::text[], 'L''Église est organisée autour de cinq grands sièges : Jérusalem, Antioche, Alexandrie, Rome et Constantinople.', 1, '{"id": "eg.l33.e01", "unitIds": ["eg.g33.cinq_sieges", "eg.v.siege_apostolique"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de sièges apostoliques compte l''Église au début du Ve siècle ?", "promptLanguage": "fr", "options": ["Trois", "Quatre", "Cinq", "Sept"], "answer": "Cinq", "acceptedAnswers": ["Cinq"], "explanation": "L''Église est organisée autour de cinq grands sièges : Jérusalem, Antioche, Alexandrie, Rome et Constantinople.", "tip": "Cinq villes, cinq sièges.", "extraExample": {"text": "Alexandrie est l''un des cinq.", "translation": "Son évêque est le pape d''Alexandrie."}, "errorPatterns": [{"equals": "Sept", "category": "word_confusion", "feedback": "Sept est le nombre de conciles reconnus par les Églises chalcédoniennes, pas de sièges."}, {"equals": "Trois", "category": "word_confusion", "feedback": "Trois est le nombre de conciles reconnus par l''Église copte, pas de sièges."}], "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e02', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.nouvelle_rome']::text[], 'mcq', 'lesson', 'Quel est le plus jeune des cinq grands sièges ?', array['Constantinople']::text[], 'La ville n''existe sous ce nom que depuis 330 : son rang vient de la capitale, pas d''un apôtre. Les autres sièges remontent aux apôtres.', 1, '{"id": "eg.l33.e02", "unitIds": ["eg.g33.cinq_sieges", "eg.v.nouvelle_rome"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le plus jeune des cinq grands sièges ?", "promptLanguage": "fr", "options": ["Antioche", "Constantinople", "Jérusalem", "Alexandrie"], "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "La ville n''existe sous ce nom que depuis 330 : son rang vient de la capitale, pas d''un apôtre. Les autres sièges remontent aux apôtres.", "tip": "Plus jeune = plus proche de l''empereur.", "extraExample": {"text": "Constantinople est aussi appelée la nouvelle Rome.", "translation": "Son rang vient de la capitale."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e03', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.nouvelle_rome']::text[], 'mcq', 'lesson', 'En quelle année Byzance devient-elle Constantinople ?', array['330']::text[], 'En 330, l''empereur Constantin fait de Byzance sa capitale.', 1, '{"id": "eg.l33.e03", "unitIds": ["eg.g33.cinq_sieges", "eg.v.nouvelle_rome"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Byzance devient-elle Constantinople ?", "promptLanguage": "fr", "options": ["330", "381", "431", "451"], "answer": "330", "acceptedAnswers": ["330"], "explanation": "En 330, l''empereur Constantin fait de Byzance sa capitale.", "tip": "330, Constantin, Constantinople : trois « C ».", "extraExample": {"text": "Théodose Ier la fixe comme capitale à la fin du IVe siècle.", "translation": "Elle ne quitte plus ce rôle."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e04', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.concile_oecumenique']::text[], 'mcq', 'lesson', 'Un concile « œcuménique » : ce mot veut dire…', array['de toute la terre habitée']::text[], 'Un concile œcuménique réunit les évêques du monde entier, pas ceux d''une seule région.', 1, '{"id": "eg.l33.e04", "unitIds": ["eg.g33.cinq_sieges", "eg.v.concile_oecumenique"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Un concile « œcuménique » : ce mot veut dire…", "promptLanguage": "fr", "options": ["de toute la terre habitée", "réservé aux évêques d''Égypte", "secret", "d''une seule ville"], "answer": "de toute la terre habitée", "acceptedAnswers": ["de toute la terre habitée"], "explanation": "Un concile œcuménique réunit les évêques du monde entier, pas ceux d''une seule région.", "tip": "Œcuménique = universel.", "extraExample": {"text": "Nicée a réuni des évêques de tout l''Empire.", "translation": "C''est ce qui lui donne son autorité."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e05', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.canon_ecclesiastique']::text[], 'mcq', 'lesson', 'Que sont les canons votés par un concile ?', array['des règles d''organisation de l''Église']::text[], 'Les canons règlent la vie de l''Église (rangs, discipline), à côté des décisions sur la foi.', 2, '{"id": "eg.l33.e05", "unitIds": ["eg.g33.cinq_sieges", "eg.v.canon_ecclesiastique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que sont les canons votés par un concile ?", "promptLanguage": "fr", "options": ["des règles d''organisation de l''Église", "des psaumes", "des hérésies", "des prières de la messe"], "answer": "des règles d''organisation de l''Église", "acceptedAnswers": ["des règles d''organisation de l''Église"], "explanation": "Les canons règlent la vie de l''Église (rangs, discipline), à côté des décisions sur la foi.", "tip": "Canon = règle.", "extraExample": {"text": "Le canon 3 de 381 fixe un rang d''honneur.", "translation": "Il ne touche pas au credo."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e06', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.canon_3_de_381']::text[], 'mcq', 'lesson', 'Pourquoi Alexandrie refuse-t-elle le canon 3 de 381 ?', array['Le rang d''une Église ne doit pas dépendre de la capitale de l''empereur']::text[], 'Pour Alexandrie, l''importance d''une Église vient de la foi et de l''histoire, pas de la politique.', 3, '{"id": "eg.l33.e06", "unitIds": ["eg.g33.cinq_sieges", "eg.v.canon_3_de_381"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Alexandrie refuse-t-elle le canon 3 de 381 ?", "promptLanguage": "fr", "options": ["Le rang d''une Église ne doit pas dépendre de la capitale de l''empereur", "Elle refuse le credo", "Elle veut quitter l''Empire", "Elle n''a pas été invitée"], "answer": "Le rang d''une Église ne doit pas dépendre de la capitale de l''empereur", "acceptedAnswers": ["Le rang d''une Église ne doit pas dépendre de la capitale de l''empereur"], "explanation": "Pour Alexandrie, l''importance d''une Église vient de la foi et de l''histoire, pas de la politique.", "tip": "Foi d''abord, politique ensuite.", "extraExample": {"text": "Alexandrie est fondée par saint Marc.", "translation": "Son rang vient des apôtres."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e07', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.trois_premiers_conciles']::text[], 'mcq', 'lesson', 'Quel concile a condamné Arius en 325 ?', array['Nicée']::text[], 'Nicée (325) condamne Arius et rédige la première partie du credo, sur le Père et le Fils. Rappel du module précédent.', 2, '{"id": "eg.l33.e07", "unitIds": ["eg.g33.cinq_sieges", "eg.v.trois_premiers_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile a condamné Arius en 325 ?", "promptLanguage": "fr", "options": ["Nicée", "Constantinople", "Éphèse", "Chalcédoine"], "answer": "Nicée", "acceptedAnswers": ["Nicée"], "explanation": "Nicée (325) condamne Arius et rédige la première partie du credo, sur le Père et le Fils. Rappel du module précédent.", "tip": "Nicée = Arius = 325.", "extraExample": {"text": "Athanase y défend la divinité du Christ.", "translation": "Le credo en sort."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e08', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.trois_premiers_conciles']::text[], 'mcq', 'lesson', 'Quel concile ajoute au credo la partie sur le Saint-Esprit ?', array['Constantinople']::text[], 'En 381, Constantinople confirme que le Saint-Esprit est consubstantiel au Père et au Fils.', 2, '{"id": "eg.l33.e08", "unitIds": ["eg.g33.cinq_sieges", "eg.v.trois_premiers_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile ajoute au credo la partie sur le Saint-Esprit ?", "promptLanguage": "fr", "options": ["Constantinople", "Nicée", "Éphèse", "Chalcédoine"], "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "En 381, Constantinople confirme que le Saint-Esprit est consubstantiel au Père et au Fils.", "tip": "381 = Saint-Esprit.", "extraExample": {"text": "Le credo de Nicée s''arrêtait au Fils.", "translation": "Constantinople le complète."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e09', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.patriarche']::text[], 'mcq', 'lesson', 'Qui est le grand défenseur de la foi contre Arius à Nicée ?', array['Saint Athanase d''Alexandrie']::text[], 'Athanase d''Alexandrie est le chef de file du combat contre Arius, preuve du rôle de leader d''Alexandrie.', 2, '{"id": "eg.l33.e09", "unitIds": ["eg.g33.cinq_sieges", "eg.v.patriarche"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le grand défenseur de la foi contre Arius à Nicée ?", "promptLanguage": "fr", "options": ["Saint Athanase d''Alexandrie", "Saint Cyrille", "Nestorius", "Dioscore"], "answer": "Saint Athanase d''Alexandrie", "acceptedAnswers": ["Saint Athanase d''Alexandrie"], "explanation": "Athanase d''Alexandrie est le chef de file du combat contre Arius, preuve du rôle de leader d''Alexandrie.", "tip": "Athanase = Nicée ; Cyrille = Éphèse.", "extraExample": {"text": "Cyrille mènera le combat d''Éphèse un siècle plus tard.", "translation": "Deux géants d''Alexandrie."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e10', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.nouvelle_rome']::text[], 'fill_blank', 'lesson', 'Constantinople est aussi appelée la ___ Rome.', array['nouvelle']::text[], 'L''empereur y siège comme à Rome autrefois.', 1, '{"id": "eg.l33.e10", "unitIds": ["eg.g33.cinq_sieges", "eg.v.nouvelle_rome"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Constantinople est aussi appelée la ___ Rome.", "promptLanguage": "fr", "options": ["nouvelle", "petite", "deuxième"], "answer": "nouvelle", "acceptedAnswers": ["nouvelle"], "explanation": "L''empereur y siège comme à Rome autrefois.", "tip": "La nouvelle Rome.", "extraExample": {"text": "Le canon 3 lui donne la deuxième place d''honneur.", "translation": "Après Rome."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e11', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.trois_premiers_conciles']::text[], 'fill_blank', 'lesson', 'Le concile d''Éphèse a lieu en ___.', array['431']::text[], 'Éphèse est le troisième des trois premiers conciles.', 2, '{"id": "eg.l33.e11", "unitIds": ["eg.g33.cinq_sieges", "eg.v.trois_premiers_conciles"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le concile d''Éphèse a lieu en ___.", "promptLanguage": "fr", "options": ["431", "381", "451"], "answer": "431", "acceptedAnswers": ["431"], "explanation": "Éphèse est le troisième des trois premiers conciles.", "tip": "325, 381, 431.", "extraExample": {"text": "Il condamne Nestorius.", "translation": "C''est la leçon suivante."}, "errorPatterns": [{"equals": "451", "category": "word_confusion", "feedback": "451 est la date de Chalcédoine, que l''Église copte rejette."}, {"equals": "381", "category": "word_confusion", "feedback": "381 est la date de Constantinople."}], "pool": "lesson", "lessonId": "eg.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e12', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.patriarche']::text[], 'fill_blank', 'lesson', 'L''évêque de Rome porte le titre de ___.', array['pape']::text[], 'À Rome comme à Alexandrie, le patriarche est aussi appelé pape.', 1, '{"id": "eg.l33.e12", "unitIds": ["eg.g33.cinq_sieges", "eg.v.patriarche"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "L''évêque de Rome porte le titre de ___.", "promptLanguage": "fr", "options": ["pape", "empereur", "moine"], "answer": "pape", "acceptedAnswers": ["pape"], "explanation": "À Rome comme à Alexandrie, le patriarche est aussi appelé pape.", "tip": "Pape = père.", "extraExample": {"text": "Le pape d''Alexandrie est le chef de l''Église copte.", "translation": "Le titre est ancien en Égypte."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e13', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.canon_3_de_381']::text[], 'fill_blank', 'lesson', 'Le canon 3 de 381 donne à Constantinople la deuxième place, juste après ___.', array['Rome']::text[], 'Constantinople est classée après Rome, avant Alexandrie : c''est ce que refuse Alexandrie.', 3, '{"id": "eg.l33.e13", "unitIds": ["eg.g33.cinq_sieges", "eg.v.canon_3_de_381"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Le canon 3 de 381 donne à Constantinople la deuxième place, juste après ___.", "promptLanguage": "fr", "options": ["Rome", "Alexandrie", "Jérusalem"], "answer": "Rome", "acceptedAnswers": ["Rome"], "explanation": "Constantinople est classée après Rome, avant Alexandrie : c''est ce que refuse Alexandrie.", "tip": "Après Rome, pas avant.", "extraExample": {"text": "Rome garde la première place d''honneur.", "translation": "Alexandrie descend d''un rang."}, "errorPatterns": [{"equals": "Alexandrie", "category": "word_confusion", "feedback": "Justement : Alexandrie se retrouve derrière Constantinople, et c''est ce qu''elle refuse."}], "pool": "lesson", "lessonId": "eg.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e14', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.trois_premiers_conciles']::text[], 'match', 'lesson', 'Les trois premiers conciles', '{}'::text[], 'Chaque concile répond à une hérésie : Arius, puis les attaques contre le Saint-Esprit, puis Nestorius.', 2, '{"id": "eg.l33.e14", "unitIds": ["eg.g33.cinq_sieges", "eg.v.trois_premiers_conciles"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les trois premiers conciles", "promptLanguage": "fr", "pairs": [{"left": "Nicée (325)", "right": "condamne Arius"}, {"left": "Constantinople (381)", "right": "complète le credo sur le Saint-Esprit"}, {"left": "Éphèse (431)", "right": "proclame Marie Théotokos"}], "answer": "Nicée (325) = condamne Arius ; Constantinople (381) = complète le credo sur le Saint-Esprit ; Éphèse (431) = proclame Marie Théotokos", "acceptedAnswers": [], "explanation": "Chaque concile répond à une hérésie : Arius, puis les attaques contre le Saint-Esprit, puis Nestorius.", "tip": "Une date, une hérésie, une décision.", "extraExample": {"text": "Les conciles se répondent d''un siècle à l''autre.", "translation": "Chacun complète la foi."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e15', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.siege_apostolique']::text[], 'match', 'lesson', 'Des sièges et leur particularité', '{}'::text[], 'Chaque siège a son histoire : Alexandrie remonte à saint Marc, Constantinople à la capitale de 330.', 2, '{"id": "eg.l33.e15", "unitIds": ["eg.g33.cinq_sieges", "eg.v.siege_apostolique"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Des sièges et leur particularité", "promptLanguage": "fr", "pairs": [{"left": "Alexandrie", "right": "fondée par saint Marc"}, {"left": "Constantinople", "right": "la nouvelle Rome"}, {"left": "Rome", "right": "siège du pape de Rome"}], "answer": "Alexandrie = fondée par saint Marc ; Constantinople = la nouvelle Rome ; Rome = siège du pape de Rome", "acceptedAnswers": [], "explanation": "Chaque siège a son histoire : Alexandrie remonte à saint Marc, Constantinople à la capitale de 330.", "tip": "Marc, Alexandrie ; Constantin, Constantinople.", "extraExample": {"text": "Chaque siège défend son rang.", "translation": "La rivalité commence."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e16', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges']::text[], 'reorder', 'lesson', 'Phrase-repère : l''organisation de l''Église.', array['L''Église a cinq grands sièges']::text[], 'Le repère à retenir : cinq grands sièges, dont quatre fondés par des apôtres.', 1, '{"id": "eg.l33.e16", "unitIds": ["eg.g33.cinq_sieges"], "type": "reorder", "difficulty": 1, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : l''organisation de l''Église.", "promptLanguage": "fr", "tokens": ["a", "grands", "sièges", "L''Église", "cinq"], "answer": "L''Église a cinq grands sièges", "acceptedAnswers": ["L''Église a cinq grands sièges"], "explanation": "Le repère à retenir : cinq grands sièges, dont quatre fondés par des apôtres.", "tip": "Cinq villes, cinq sièges.", "extraExample": {"text": "Le cinquième est Constantinople.", "translation": "Le plus jeune."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e17', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.concile_oecumenique']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on un concile qui réunit les évêques de toute l''Église ?', array['œcuménique','oecuménique','oecumenique','un concile œcuménique']::text[], 'Un concile qui réunit les évêques de toute l''Église est œcuménique.', 2, '{"id": "eg.l33.e17", "unitIds": ["eg.g33.cinq_sieges", "eg.v.concile_oecumenique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on un concile qui réunit les évêques de toute l''Église ?", "promptLanguage": "fr", "answer": "œcuménique", "acceptedAnswers": ["œcuménique", "oecuménique", "oecumenique", "un concile œcuménique"], "explanation": "Un concile qui réunit les évêques de toute l''Église est œcuménique.", "tip": "Œcuménique = universel.", "extraExample": {"text": "Nicée est œcuménique.", "translation": "Il touche toute la chrétienté."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e18', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.canon_ecclesiastique']::text[], 'free_answer', 'lesson', 'Comment s''appellent les règles d''organisation votées par un concile ?', array['canons','les canons','canon','un canon']::text[], 'Ce sont les canons.', 2, '{"id": "eg.l33.e18", "unitIds": ["eg.g33.cinq_sieges", "eg.v.canon_ecclesiastique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appellent les règles d''organisation votées par un concile ?", "promptLanguage": "fr", "answer": "canons", "acceptedAnswers": ["canons", "les canons", "canon", "un canon"], "explanation": "Ce sont les canons.", "tip": "Canon = règle.", "extraExample": {"text": "Le canon 3 de 381 est l''un d''eux.", "translation": "Il parle du rang."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l33.e19', 'eg', 'eg.l33', 'eg.g33.cinq_sieges', array['eg.g33.cinq_sieges','eg.v.nouvelle_rome']::text[], 'free_answer', 'lesson', 'Quel empereur fait de Byzance sa capitale en 330 ?', array['Constantin','Constantin Ier','Constantin le Grand']::text[], 'C''est l''empereur Constantin, qui donne son nom à Constantinople.', 2, '{"id": "eg.l33.e19", "unitIds": ["eg.g33.cinq_sieges", "eg.v.nouvelle_rome"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel empereur fait de Byzance sa capitale en 330 ?", "promptLanguage": "fr", "answer": "Constantin", "acceptedAnswers": ["Constantin", "Constantin Ier", "Constantin le Grand"], "explanation": "C''est l''empereur Constantin, qui donne son nom à Constantinople.", "tip": "Constantin → Constantinople.", "extraExample": {"text": "Théodose Ier la fixe comme capitale ensuite.", "translation": "Elle devient incontournable."}, "pool": "lesson", "lessonId": "eg.l33", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e01', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.nestorius']::text[], 'mcq', 'lesson', 'En quelle année Nestorius devient-il patriarche de Constantinople ?', array['428']::text[], 'L''empereur le nomme en 428, trois ans avant le concile d''Éphèse.', 1, '{"id": "eg.l34.e01", "unitIds": ["eg.g34.nestorius", "eg.v.nestorius"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Nestorius devient-il patriarche de Constantinople ?", "promptLanguage": "fr", "options": ["428", "325", "431", "451"], "answer": "428", "acceptedAnswers": ["428"], "explanation": "L''empereur le nomme en 428, trois ans avant le concile d''Éphèse.", "tip": "428 puis 431 : trois ans.", "extraExample": {"text": "Il est condamné à Éphèse.", "translation": "En 431."}, "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e02', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.ecole_d_antioche']::text[], 'mcq', 'lesson', 'De quelle école théologique vient Nestorius ?', array['L''école d''Antioche']::text[], 'Elle distingue soigneusement le divin et l''humain en Jésus, ce qui prépare sa position.', 1, '{"id": "eg.l34.e02", "unitIds": ["eg.g34.nestorius", "eg.v.ecole_d_antioche"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "De quelle école théologique vient Nestorius ?", "promptLanguage": "fr", "options": ["L''école d''Antioche", "L''école d''Alexandrie", "L''école de Rome", "L''école de Jérusalem"], "answer": "L''école d''Antioche", "acceptedAnswers": ["L''école d''Antioche"], "explanation": "Elle distingue soigneusement le divin et l''humain en Jésus, ce qui prépare sa position.", "tip": "Nestorius = Antioche.", "extraExample": {"text": "Alexandrie insiste sur l''unité du Christ.", "translation": "Deux sensibilités."}, "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e03', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.theotokos']::text[], 'mcq', 'lesson', 'Que signifie le titre Théotokos ?', array['mère de Dieu']::text[], 'Théotokos veut dire « celle qui enfante Dieu ».', 1, '{"id": "eg.l34.e03", "unitIds": ["eg.g34.nestorius", "eg.v.theotokos"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie le titre Théotokos ?", "promptLanguage": "fr", "options": ["mère de Dieu", "mère du Christ", "servante de Dieu", "reine du ciel"], "answer": "mère de Dieu", "acceptedAnswers": ["mère de Dieu"], "explanation": "Théotokos veut dire « celle qui enfante Dieu ».", "tip": "Théo = Dieu, tokos = enfantement.", "extraExample": {"text": "L''Église copte chante Marie comme Théotokos.", "translation": "Le titre est liturgique."}, "errorPatterns": [{"equals": "mère du Christ", "category": "word_confusion", "feedback": "C''est Christotokos, le titre préféré de Nestorius."}], "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e04', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.christotokos']::text[], 'mcq', 'lesson', 'Quel titre Nestorius préfère-t-il pour Marie ?', array['Christotokos']::text[], 'Il propose « mère du Christ », plus prudent à ses yeux.', 1, '{"id": "eg.l34.e04", "unitIds": ["eg.g34.nestorius", "eg.v.christotokos"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre Nestorius préfère-t-il pour Marie ?", "promptLanguage": "fr", "options": ["Christotokos", "Théotokos", "Hodigitria", "Orante"], "answer": "Christotokos", "acceptedAnswers": ["Christotokos"], "explanation": "Il propose « mère du Christ », plus prudent à ses yeux.", "tip": "Christo = Christ.", "extraExample": {"text": "Théotokos est le titre que l''Église défend.", "translation": "C''est tout l''enjeu."}, "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e05', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.nestorius']::text[], 'mcq', 'lesson', 'Que craint Nestorius quand on appelle Marie « mère de Dieu » ?', array['que Dieu ait commencé d''exister dans le ventre de Marie']::text[], 'Pour lui, Dieu est éternel : il ne peut pas être « né » de Marie. Il oublie que c''est le Verbe éternel qui prend chair.', 2, '{"id": "eg.l34.e05", "unitIds": ["eg.g34.nestorius", "eg.v.nestorius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que craint Nestorius quand on appelle Marie « mère de Dieu » ?", "promptLanguage": "fr", "options": ["que Dieu ait commencé d''exister dans le ventre de Marie", "que Marie soit adorée", "que l''empereur se fâche", "que le Christ n''ait pas d''âme"], "answer": "que Dieu ait commencé d''exister dans le ventre de Marie", "acceptedAnswers": ["que Dieu ait commencé d''exister dans le ventre de Marie"], "explanation": "Pour lui, Dieu est éternel : il ne peut pas être « né » de Marie. Il oublie que c''est le Verbe éternel qui prend chair.", "tip": "Il confond naissance de la chair et origine de Dieu.", "extraExample": {"text": "Le Verbe est éternel.", "translation": "Il prend chair en Marie."}, "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e06', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.nestorianisme']::text[], 'mcq', 'lesson', 'Que reproche-t-on à Nestorius ?', array['de séparer le Verbe de l''homme Jésus']::text[], 'Ses adversaires disent que Dieu habiterait en Jésus comme dans un temple, sans former un seul Christ.', 2, '{"id": "eg.l34.e06", "unitIds": ["eg.g34.nestorius", "eg.v.nestorianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que reproche-t-on à Nestorius ?", "promptLanguage": "fr", "options": ["de séparer le Verbe de l''homme Jésus", "de nier la Trinité", "d''adorer Marie", "de mélanger les natures"], "answer": "de séparer le Verbe de l''homme Jésus", "acceptedAnswers": ["de séparer le Verbe de l''homme Jésus"], "explanation": "Ses adversaires disent que Dieu habiterait en Jésus comme dans un temple, sans former un seul Christ.", "tip": "Séparer, pas mélanger.", "extraExample": {"text": "Mélanger sera l''erreur d''Eutychès.", "translation": "Deux excès opposés."}, "errorPatterns": [{"equals": "de mélanger les natures", "category": "word_confusion", "feedback": "Mélanger est l''erreur inverse, celle d''Eutychès."}], "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e07', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.incarnation','eg.v.le_verbe']::text[], 'mcq', 'lesson', 'Que désigne l''incarnation ?', array['le moment où le Verbe de Dieu se fait homme']::text[], '« Le Verbe s''est fait chair » : le Fils de Dieu devient vraiment homme en Marie.', 2, '{"id": "eg.l34.e07", "unitIds": ["eg.g34.nestorius", "eg.v.incarnation", "eg.v.le_verbe"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que désigne l''incarnation ?", "promptLanguage": "fr", "options": ["le moment où le Verbe de Dieu se fait homme", "la naissance de Marie", "la mort du Christ", "le baptême de Jésus"], "answer": "le moment où le Verbe de Dieu se fait homme", "acceptedAnswers": ["le moment où le Verbe de Dieu se fait homme"], "explanation": "« Le Verbe s''est fait chair » : le Fils de Dieu devient vraiment homme en Marie.", "tip": "Incarnation = entrer dans la chair.", "extraExample": {"text": "Le Verbe est éternel.", "translation": "Il prend chair en Marie."}, "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l34.e08', 'eg', 'eg.l34', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.nestorianisme']::text[], 'mcq', 'lesson', 'Pourquoi la question de Nestorius est-elle si grave ?', array['Sans l''unité du Christ, ce n''est plus Dieu qui est né, a souffert et est mort pour nous']::text[], 'Si Jésus n''est pas Dieu en personne, la croix ne sauve plus. Le salut dépend de l''unité du Christ.', 3, '{"id": "eg.l34.e08", "unitIds": ["eg.g34.nestorius", "eg.v.nestorianisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi la question de Nestorius est-elle si grave ?", "promptLanguage": "fr", "options": ["Sans l''unité du Christ, ce n''est plus Dieu qui est né, a souffert et est mort pour nous", "Parce qu''il est empereur", "Parce qu''il change le credo de Nicée", "Parce qu''il interdit les icônes"], "answer": "Sans l''unité du Christ, ce n''est plus Dieu qui est né, a souffert et est mort pour nous", "acceptedAnswers": ["Sans l''unité du Christ, ce n''est plus Dieu qui est né, a souffert et est mort pour nous"], "explanation": "Si Jésus n''est pas Dieu en personne, la croix ne sauve plus. Le salut dépend de l''unité du Christ.", "tip": "Pas d''unité, pas de salut.", "extraExample": {"text": "Le titre Théotokos protège l''unité du Christ.", "translation": "Ce n''est pas un détail."}, "pool": "lesson", "lessonId": "eg.l34", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.d