insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e01', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.cyrille_d_alexandrie']::text[], 'mcq', 'lesson', 'Quel numéro porte Cyrille dans la liste des papes d''Alexandrie ?', array['24e']::text[], 'Cyrille est le 24e pape d''Alexandrie, de 412 à 444. Le 25e sera Dioscore.', 1, '{"id": "eg.l35.e01", "unitIds": ["eg.g35.cyrille", "eg.v.cyrille_d_alexandrie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel numéro porte Cyrille dans la liste des papes d''Alexandrie ?", "promptLanguage": "fr", "options": ["24e", "25e", "22e", "27e"], "answer": "24e", "acceptedAnswers": ["24e"], "explanation": "Cyrille est le 24e pape d''Alexandrie, de 412 à 444. Le 25e sera Dioscore.", "tip": "Cyrille 24, Dioscore 25.", "extraExample": {"text": "Il est pape pendant plus de 30 ans.", "translation": "412-444."}, "errorPatterns": [{"equals": "25e", "category": "word_confusion", "feedback": "Le 25e pape est Dioscore, le successeur de Cyrille."}], "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e02', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.pilier_de_la_foi']::text[], 'mcq', 'lesson', 'Quel surnom l''Église copte donne-t-elle à Cyrille ?', array['le Pilier de la foi']::text[], 'Il a soutenu la foi en un seul Christ, comme un pilier soutient un édifice.', 1, '{"id": "eg.l35.e02", "unitIds": ["eg.g35.cyrille", "eg.v.pilier_de_la_foi"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel surnom l''Église copte donne-t-elle à Cyrille ?", "promptLanguage": "fr", "options": ["le Pilier de la foi", "le Bouche d''or", "le Grand", "le Théologien"], "answer": "le Pilier de la foi", "acceptedAnswers": ["le Pilier de la foi"], "explanation": "Il a soutenu la foi en un seul Christ, comme un pilier soutient un édifice.", "tip": "Pilier = soutien.", "extraExample": {"text": "Une de ses trois liturgies porte son nom.", "translation": "Basile, Grégoire, Cyrille."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e03', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.theotokos']::text[], 'mcq', 'lesson', 'Pourquoi Marie est-elle Théotokos, selon Cyrille ?', array['Parce que celui qu''elle enfante est Dieu le Verbe fait chair']::text[], 'Le titre dit qui est l''enfant, pas d''où vient Dieu.', 2, '{"id": "eg.l35.e03", "unitIds": ["eg.g35.cyrille", "eg.v.theotokos"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Marie est-elle Théotokos, selon Cyrille ?", "promptLanguage": "fr", "options": ["Parce que celui qu''elle enfante est Dieu le Verbe fait chair", "Parce qu''elle est plus ancienne que Dieu", "Parce que l''empereur l''a décidé", "Parce qu''elle est née sans péché"], "answer": "Parce que celui qu''elle enfante est Dieu le Verbe fait chair", "acceptedAnswers": ["Parce que celui qu''elle enfante est Dieu le Verbe fait chair"], "explanation": "Le titre dit qui est l''enfant, pas d''où vient Dieu.", "tip": "Théotokos parle de Jésus avant de parler de Marie.", "extraExample": {"text": "Le titre protège l''identité de Jésus.", "translation": "C''est un titre sur le Christ."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e04', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.formule_de_cyrille']::text[], 'mcq', 'lesson', 'Quelle est la célèbre formule de Cyrille ?', array['une seule nature du Verbe incarné']::text[], 'Le Verbe fait chair est l''unique sujet de toute l''action du Christ.', 2, '{"id": "eg.l35.e04", "unitIds": ["eg.g35.cyrille", "eg.v.formule_de_cyrille"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la célèbre formule de Cyrille ?", "promptLanguage": "fr", "options": ["une seule nature du Verbe incarné", "deux natures en une personne", "trois personnes, une essence", "le Christ est seulement homme"], "answer": "une seule nature du Verbe incarné", "acceptedAnswers": ["une seule nature du Verbe incarné"], "explanation": "Le Verbe fait chair est l''unique sujet de toute l''action du Christ.", "tip": "Un Verbe, un Christ.", "extraExample": {"text": "L''Église copte la confesse encore.", "translation": "Elle la dit miaphysite."}, "errorPatterns": [{"equals": "deux natures en une personne", "category": "word_confusion", "feedback": "C''est le langage de Chalcédoine (451), que l''Église copte ne reprend pas."}], "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e05', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.unite_du_christ']::text[], 'mcq', 'lesson', 'Quelle image Cyrille utilise-t-il pour expliquer l''union du Verbe et de la chair ?', array['l''âme et le corps']::text[], 'L''âme et le corps sont différents mais ne font qu''un seul homme.', 2, '{"id": "eg.l35.e05", "unitIds": ["eg.g35.cyrille", "eg.v.unite_du_christ"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle image Cyrille utilise-t-il pour expliquer l''union du Verbe et de la chair ?", "promptLanguage": "fr", "options": ["l''âme et le corps", "l''eau et le vin", "le soleil et la lune", "le père et le fils"], "answer": "l''âme et le corps", "acceptedAnswers": ["l''âme et le corps"], "explanation": "L''âme et le corps sont différents mais ne font qu''un seul homme.", "tip": "Âme + corps = un homme. Verbe + chair = un Christ.", "extraExample": {"text": "L''unité n''efface pas la différence.", "translation": "Elle la tient ensemble."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e06', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.douze_anathemes']::text[], 'mcq', 'lesson', 'Combien d''anathèmes Cyrille joint-il à sa lettre à Nestorius ?', array['Douze']::text[], 'Les douze anathèmes de 430 condamnent douze propositions nestoriennes.', 1, '{"id": "eg.l35.e06", "unitIds": ["eg.g35.cyrille", "eg.v.douze_anathemes"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''anathèmes Cyrille joint-il à sa lettre à Nestorius ?", "promptLanguage": "fr", "options": ["Douze", "Sept", "Trois", "Quarante"], "answer": "Douze", "acceptedAnswers": ["Douze"], "explanation": "Les douze anathèmes de 430 condamnent douze propositions nestoriennes.", "tip": "12 anathèmes en 430.", "extraExample": {"text": "L''école d''Antioche les juge trop durs.", "translation": "Les tensions montent."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e07', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.celestin_ier']::text[], 'mcq', 'lesson', 'Quel pape de Rome soutient Cyrille contre Nestorius ?', array['Célestin Ier']::text[], 'Célestin Ier condamne Nestorius et charge Cyrille de faire appliquer sa décision.', 2, '{"id": "eg.l35.e07", "unitIds": ["eg.g35.cyrille", "eg.v.celestin_ier"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape de Rome soutient Cyrille contre Nestorius ?", "promptLanguage": "fr", "options": ["Célestin Ier", "Léon Ier", "Pierre", "Jean"], "answer": "Célestin Ier", "acceptedAnswers": ["Célestin Ier"], "explanation": "Célestin Ier condamne Nestorius et charge Cyrille de faire appliquer sa décision.", "tip": "Célestin avec Cyrille ; Léon viendra plus tard.", "extraExample": {"text": "Léon Ier écrira le Tome en 449.", "translation": "Plus tard."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e08', 'eg', 'eg.l35', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.theotokos']::text[], 'mcq', 'lesson', 'Quel titre Cyrille défend-il, que Nestorius refuse ?', array['Théotokos']::text[], 'Rappel : Nestorius préfère Christotokos.', 1, '{"id": "eg.l35.e08", "unitIds": ["eg.g34.nestorius", "eg.v.theotokos"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre Cyrille défend-il, que Nestorius refuse ?", "promptLanguage": "fr", "options": ["Théotokos", "Christotokos", "Patriarche", "Verbe"], "answer": "Théotokos", "acceptedAnswers": ["Théotokos"], "explanation": "Rappel : Nestorius préfère Christotokos.", "tip": "Cyrille : Théotokos ; Nestorius : Christotokos.", "extraExample": {"text": "Le concile d''Éphèse tranchera.", "translation": "431."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e09', 'eg', 'eg.l35', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.ecole_d_antioche']::text[], 'mcq', 'lesson', 'Quelle école trouve les douze anathèmes trop durs ?', array['l''école d''Antioche']::text[], 'Antioche distingue les natures et craint que Cyrille les mélange.', 3, '{"id": "eg.l35.e09", "unitIds": ["eg.g34.nestorius", "eg.v.ecole_d_antioche"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle école trouve les douze anathèmes trop durs ?", "promptLanguage": "fr", "options": ["l''école d''Antioche", "l''école d''Alexandrie", "l''école de Rome", "les moines d''Égypte"], "answer": "l''école d''Antioche", "acceptedAnswers": ["l''école d''Antioche"], "explanation": "Antioche distingue les natures et craint que Cyrille les mélange.", "tip": "Antioche = distinction.", "extraExample": {"text": "Alexandrie = unité.", "translation": "Deux sensibilités."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
