insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e11', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.unite_du_christ']::text[], 'fill_blank', 'lesson', 'Cyrille compare l''union du Verbe et de la chair à celle de l''âme et du ___.', array['corps']::text[], 'L''âme et le corps font un seul homme sans cesser d''être âme et corps.', 2, '{"id": "eg.l35.e11", "unitIds": ["eg.g35.cyrille", "eg.v.unite_du_christ"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Cyrille compare l''union du Verbe et de la chair à celle de l''âme et du ___.", "promptLanguage": "fr", "options": ["corps", "cœur", "esprit"], "answer": "corps", "acceptedAnswers": ["corps"], "explanation": "L''âme et le corps font un seul homme sans cesser d''être âme et corps.", "tip": "Âme et corps : une image de l''unité.", "extraExample": {"text": "Le Christ est un.", "translation": "Dieu et homme."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e12', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.douze_anathemes']::text[], 'fill_blank', 'lesson', 'À sa troisième lettre, Cyrille joint douze ___.', array['anathèmes']::text[], 'Ce sont douze condamnations des idées nestoriennes.', 2, '{"id": "eg.l35.e12", "unitIds": ["eg.g35.cyrille", "eg.v.douze_anathemes"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "À sa troisième lettre, Cyrille joint douze ___.", "promptLanguage": "fr", "options": ["anathèmes", "psaumes", "canons"], "answer": "anathèmes", "acceptedAnswers": ["anathèmes"], "explanation": "Ce sont douze condamnations des idées nestoriennes.", "tip": "12 anathèmes, 430.", "extraExample": {"text": "Antioche les trouve durs.", "translation": "Ambiance tendue."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e13', 'eg', 'eg.l35', 'eg.g34.nestorius', array['eg.g34.nestorius','eg.v.incarnation']::text[], 'fill_blank', 'lesson', 'Le Verbe se fait homme : c''est l''___.', array['incarnation']::text[], 'Rappel : l''incarnation est le moment où le Verbe de Dieu se fait homme.', 2, '{"id": "eg.l35.e13", "unitIds": ["eg.g34.nestorius", "eg.v.incarnation"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le Verbe se fait homme : c''est l''___.", "promptLanguage": "fr", "options": ["incarnation", "ascension", "résurrection"], "answer": "incarnation", "acceptedAnswers": ["incarnation"], "explanation": "Rappel : l''incarnation est le moment où le Verbe de Dieu se fait homme.", "tip": "In-carnation : dans la chair.", "extraExample": {"text": "Cyrille parle du Verbe incarné.", "translation": "Le Verbe fait chair."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e14', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.cyrille_d_alexandrie']::text[], 'match', 'lesson', 'Autour de saint Cyrille : qui est qui ?', '{}'::text[], 'Cyrille et Célestin vont ensemble contre Nestorius.', 2, '{"id": "eg.l35.e14", "unitIds": ["eg.g35.cyrille", "eg.v.cyrille_d_alexandrie"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Autour de saint Cyrille : qui est qui ?", "promptLanguage": "fr", "pairs": [{"left": "Cyrille", "right": "24e pape d''Alexandrie"}, {"left": "Célestin Ier", "right": "pape de Rome qui soutient Cyrille"}, {"left": "Nestorius", "right": "patriarche de Constantinople en 428"}, {"left": "le Pilier de la foi", "right": "surnom de Cyrille"}], "answer": "Cyrille = 24e pape d''Alexandrie ; Célestin Ier = pape de Rome qui soutient Cyrille ; Nestorius = patriarche de Constantinople en 428 ; le Pilier de la foi = surnom de Cyrille", "acceptedAnswers": [], "explanation": "Cyrille et Célestin vont ensemble contre Nestorius.", "tip": "Pilier = Cyrille.", "extraExample": {"text": "Deux grands sièges sont d''accord.", "translation": "Rome et Alexandrie."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e15', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.formule_de_cyrille']::text[], 'match', 'lesson', 'Expressions clés', '{}'::text[], 'Chaque expression résume une partie du combat de Cyrille.', 2, '{"id": "eg.l35.e15", "unitIds": ["eg.g35.cyrille", "eg.v.formule_de_cyrille"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Expressions clés", "promptLanguage": "fr", "pairs": [{"left": "la formule de Cyrille", "right": "une seule nature du Verbe incarné"}, {"left": "les douze anathèmes", "right": "condamnent les idées nestoriennes"}, {"left": "l''âme et le corps", "right": "image de l''unité du Christ"}], "answer": "la formule de Cyrille = une seule nature du Verbe incarné ; les douze anathèmes = condamnent les idées nestoriennes ; l''âme et le corps = image de l''unité du Christ", "acceptedAnswers": [], "explanation": "Chaque expression résume une partie du combat de Cyrille.", "tip": "Formule, anathèmes, image.", "extraExample": {"text": "Cyrille a tout dit en peu de mots.", "translation": "Un pilier."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e16', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille']::text[], 'reorder', 'lesson', 'Phrase-repère : la formule de Cyrille.', array['Le Christ est une seule nature du Verbe incarné']::text[], 'La formule de Cyrille, en une phrase.', 3, '{"id": "eg.l35.e16", "unitIds": ["eg.g35.cyrille"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la formule de Cyrille.", "promptLanguage": "fr", "tokens": ["une", "incarné", "Verbe", "seule", "Christ", "nature", "est", "Le", "du"], "answer": "Le Christ est une seule nature du Verbe incarné", "acceptedAnswers": ["Le Christ est une seule nature du Verbe incarné"], "explanation": "La formule de Cyrille, en une phrase.", "tip": "Un seul Verbe incarné.", "extraExample": {"text": "Il est complètement Dieu et complètement homme.", "translation": "Unité sans mélange."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e17', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.pilier_de_la_foi']::text[], 'free_answer', 'lesson', 'Quel surnom porte Cyrille dans l''Église copte ?', array['le Pilier de la foi','Pilier de la foi']::text[], 'On l''appelle le Pilier de la foi.', 2, '{"id": "eg.l35.e17", "unitIds": ["eg.g35.cyrille", "eg.v.pilier_de_la_foi"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel surnom porte Cyrille dans l''Église copte ?", "promptLanguage": "fr", "answer": "le Pilier de la foi", "acceptedAnswers": ["le Pilier de la foi", "Pilier de la foi"], "explanation": "On l''appelle le Pilier de la foi.", "tip": "Pilier = Cyrille.", "extraExample": {"text": "Il a soutenu la foi.", "translation": "Contre Nestorius."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e18', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.celestin_ier']::text[], 'free_answer', 'lesson', 'Quel pape de Rome soutient Cyrille ?', array['Célestin Ier','Célestin','Celestin']::text[], 'C''est Célestin Ier.', 3, '{"id": "eg.l35.e18", "unitIds": ["eg.g35.cyrille", "eg.v.celestin_ier"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel pape de Rome soutient Cyrille ?", "promptLanguage": "fr", "answer": "Célestin Ier", "acceptedAnswers": ["Célestin Ier", "Célestin", "Celestin"], "explanation": "C''est Célestin Ier.", "tip": "Célestin = soutien de Cyrille.", "extraExample": {"text": "Léon Ier viendra en 449.", "translation": "Plus tard."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l35.e19', 'eg', 'eg.l35', 'eg.g35.cyrille', array['eg.g35.cyrille','eg.v.formule_de_cyrille']::text[], 'free_answer', 'lesson', 'Complète la formule de Cyrille : « une seule nature du Verbe ... »', array['incarné','Verbe incarné','Dieu le Verbe incarné']::text[], 'La formule de Cyrille est « une seule nature du Verbe incarné ».', 3, '{"id": "eg.l35.e19", "unitIds": ["eg.g35.cyrille", "eg.v.formule_de_cyrille"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Complète la formule de Cyrille : « une seule nature du Verbe ... »", "promptLanguage": "fr", "answer": "incarné", "acceptedAnswers": ["incarné", "Verbe incarné", "Dieu le Verbe incarné"], "explanation": "La formule de Cyrille est « une seule nature du Verbe incarné ».", "tip": "Incarné = fait chair.", "extraExample": {"text": "Le Verbe devient chair.", "translation": "Incarnation."}, "pool": "lesson", "lessonId": "eg.l35", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e01', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.concile_ephese_431','eg.v.ephese']::text[], 'mcq', 'lesson', 'En quelle année se tient le concile d''Éphèse ?', array['431']::text[], 'Éphèse est le troisième concile œcuménique, en 431.', 1, '{"id": "eg.l36.e01", "unitIds": ["eg.g36.ephese_431", "eg.v.concile_ephese_431", "eg.v.ephese"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année se tient le concile d''Éphèse ?", "promptLanguage": "fr", "options": ["431", "325", "381", "451"], "answer": "431", "acceptedAnswers": ["431"], "explanation": "Éphèse est le troisième concile œcuménique, en 431.", "tip": "325, 381, 431.", "extraExample": {"text": "Chalcédoine suit en 451.", "translation": "Vingt ans plus tard."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e02', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.theodose_ii']::text[], 'mcq', 'lesson', 'Quel empereur convoque le concile d''Éphèse ?', array['Théodose II']::text[], 'Théodose II, petit-fils de Théodose Ier, réunit les évêques à Éphèse. Marcien conviendra Chalcédoine.', 1, '{"id": "eg.l36.e02", "unitIds": ["eg.g36.ephese_431", "eg.v.theodose_ii"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur convoque le concile d''Éphèse ?", "promptLanguage": "fr", "options": ["Théodose II", "Constantin", "Marcien", "Zénon"], "answer": "Théodose II", "acceptedAnswers": ["Théodose II"], "explanation": "Théodose II, petit-fils de Théodose Ier, réunit les évêques à Éphèse. Marcien conviendra Chalcédoine.", "tip": "Théodose II : Éphèse ; Marcien : Chalcédoine.", "extraExample": {"text": "Il convoquera aussi Éphèse II en 449.", "translation": "Deux Éphèse sous un même empereur."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e03', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.cyrille_d_alexandrie']::text[], 'mcq', 'lesson', 'Qui préside le concile d''Éphèse ?', array['Cyrille d''Alexandrie']::text[], 'Cyrille préside, avec l''appui de Rome.', 1, '{"id": "eg.l36.e03", "unitIds": ["eg.g36.ephese_431", "eg.v.cyrille_d_alexandrie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui préside le concile d''Éphèse ?", "promptLanguage": "fr", "options": ["Cyrille d''Alexandrie", "Nestorius", "Jean d''Antioche", "Flavien"], "answer": "Cyrille d''Alexandrie", "acceptedAnswers": ["Cyrille d''Alexandrie"], "explanation": "Cyrille préside, avec l''appui de Rome.", "tip": "Cyrille = Éphèse.", "extraExample": {"text": "Alexandrie est chef de file.", "translation": "Comme à Nicée."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e04', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.nestorius']::text[], 'mcq', 'lesson', 'Pourquoi Nestorius est-il condamné sans être entendu au concile ?', array['Il refuse de comparaître']::text[], 'Nestorius ne vient pas devant les évêques qui le jugent.', 2, '{"id": "eg.l36.e04", "unitIds": ["eg.g36.ephese_431", "eg.v.nestorius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Nestorius est-il condamné sans être entendu au concile ?", "promptLanguage": "fr", "options": ["Il refuse de comparaître", "Il est déjà mort", "Il est empereur", "Il n''a pas été invité"], "answer": "Il refuse de comparaître", "acceptedAnswers": ["Il refuse de comparaître"], "explanation": "Nestorius ne vient pas devant les évêques qui le jugent.", "tip": "Il refuse, ils jugent.", "extraExample": {"text": "Il est donc condamné.", "translation": "Et déposé."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e05', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.jean_d_antioche']::text[], 'mcq', 'lesson', 'Qui arrive en retard à Éphèse, après l''ouverture du concile ?', array['Jean d''Antioche']::text[], 'Jean et les évêques d''Orient arrivent après la condamnation de Nestorius.', 2, '{"id": "eg.l36.e05", "unitIds": ["eg.g36.ephese_431", "eg.v.jean_d_antioche"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui arrive en retard à Éphèse, après l''ouverture du concile ?", "promptLanguage": "fr", "options": ["Jean d''Antioche", "Célestin Ier", "Dioscore", "Pélage"], "answer": "Jean d''Antioche", "acceptedAnswers": ["Jean d''Antioche"], "explanation": "Jean et les évêques d''Orient arrivent après la condamnation de Nestorius.", "tip": "Retard = Antioche.", "extraExample": {"text": "Ils tiennent un concile rival.", "translation": "L''empereur doit trancher."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e06', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.theotokos']::text[], 'mcq', 'lesson', 'Quel titre est proclamé pour la Vierge Marie à Éphèse ?', array['Théotokos']::text[], 'Le concile confirme que Marie est Théotokos, mère de Dieu.', 1, '{"id": "eg.l36.e06", "unitIds": ["eg.g36.ephese_431", "eg.v.theotokos"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre est proclamé pour la Vierge Marie à Éphèse ?", "promptLanguage": "fr", "options": ["Théotokos", "Christotokos", "Panagia", "Orante"], "answer": "Théotokos", "acceptedAnswers": ["Théotokos"], "explanation": "Le concile confirme que Marie est Théotokos, mère de Dieu.", "tip": "Éphèse = Théotokos.", "extraExample": {"text": "Tu la chantes dans la tasbeha.", "translation": "La foi d''Éphèse."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e07', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.concile_ephese_431']::text[], 'mcq', 'lesson', 'Que devient le credo de Nicée à Éphèse ?', array['Il est confirmé, et il est interdit d''en composer un autre']::text[], 'Le credo de Nicée est confirmé sans changement.', 3, '{"id": "eg.l36.e07", "unitIds": ["eg.g36.ephese_431", "eg.v.concile_ephese_431"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que devient le credo de Nicée à Éphèse ?", "promptLanguage": "fr", "options": ["Il est confirmé, et il est interdit d''en composer un autre", "Il est remplacé", "Il reçoit l''ajout des deux natures", "Il est supprimé"], "answer": "Il est confirmé, et il est interdit d''en composer un autre", "acceptedAnswers": ["Il est confirmé, et il est interdit d''en composer un autre"], "explanation": "Le credo de Nicée est confirmé sans changement.", "tip": "Le credo ne bouge pas.", "extraExample": {"text": "Chalcédoine ajoutera sa propre définition.", "translation": "Plus tard."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e08', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.pelagianisme']::text[], 'mcq', 'lesson', 'Que prétend le pélagianisme ?', array['que l''homme peut atteindre la sainteté par ses propres forces']::text[], 'Le pélagianisme nie le besoin de la grâce de Dieu.', 3, '{"id": "eg.l36.e08", "unitIds": ["eg.g36.ephese_431", "eg.v.pelagianisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que prétend le pélagianisme ?", "promptLanguage": "fr", "options": ["que l''homme peut atteindre la sainteté par ses propres forces", "que le Christ n''a qu''une nature", "que Marie n''est pas la mère de Dieu", "que le Saint-Esprit procède du Fils"], "answer": "que l''homme peut atteindre la sainteté par ses propres forces", "acceptedAnswers": ["que l''homme peut atteindre la sainteté par ses propres forces"], "explanation": "Le pélagianisme nie le besoin de la grâce de Dieu.", "tip": "Pélage = sans la grâce.", "extraExample": {"text": "L''homme a besoin de la grâce.", "translation": "Éphèse le rappelle."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
