insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e15', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.concile_ephese_431']::text[], 'match', 'lesson', 'Les personnages d''Éphèse', '{}'::text[], 'Quatre acteurs, quatre rôles.', 2, '{"id": "eg.l36.e15", "unitIds": ["eg.g36.ephese_431", "eg.v.concile_ephese_431"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les personnages d''Éphèse", "promptLanguage": "fr", "pairs": [{"left": "Théodose II", "right": "convoque le concile"}, {"left": "Cyrille", "right": "préside le concile"}, {"left": "Nestorius", "right": "refuse de comparaître"}, {"left": "Jean d''Antioche", "right": "arrive en retard"}], "answer": "Théodose II = convoque le concile ; Cyrille = préside le concile ; Nestorius = refuse de comparaître ; Jean d''Antioche = arrive en retard", "acceptedAnswers": [], "explanation": "Quatre acteurs, quatre rôles.", "tip": "Convoque, préside, refuse, retard.", "extraExample": {"text": "Chaque rôle explique l''événement.", "translation": "Une histoire de pouvoir et de foi."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l36.e16', 'eg', 'eg.l36', 'eg.g36.ephese_431', array['eg.g36.ephese_431','eg.v.theotokos']::text[], 'match', 'lesson', 'Les décisions d''Éphèse', '{}'::text[], 'Éphèse condamne deux erreurs et confirme deux vérités.', 2, '{"id": "eg.l36.e16", "unitIds": ["eg.g36.ephese_431", "eg.v.theotokos"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les décisions d''Éphèse", "promptLanguage": "fr", "pairs": [{"left": "Nestorius", "right": "anathématisé et déposé"}, {"left": "Marie", "right": "proclamée Théotokos"}, {"left": "le credo de Nicée", "right": "confirmé, jamais changé"}, {"left": "Pélage", "right": "enseignement condamné"}], "answer": "Nestorius = anathématisé et déposé ; Marie = proclamée Théotokos ; le credo de Nicée = confirmé, jamais changé ; Pélage = enseignement condamné", "acceptedAnswers": [], "explanation": "Éphèse condamne deux erreurs et confirme deux vérités.", "tip": "Deux condamnations, deux confirmations.", "extraExample": {"text": "Le concile fixe la foi.", "translation": "Elle ne change plus."}, "pool": "lesson", "lessonId": "eg.l36", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
