insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l38.e20', 'eg', 'eg.l38', 'eg.g38.eutyches', array['eg.g38.eutyches','eg.v.synode_de_constantinople_448']::text[], 'free_answer', 'lesson', 'Quel patriarche de Constantinople condamne Eutychès en 448 ?', array['Flavien']::text[], 'C''est Flavien.', 2, '{"id": "eg.l38.e20", "unitIds": ["eg.g38.eutyches", "eg.v.synode_de_constantinople_448"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel patriarche de Constantinople condamne Eutychès en 448 ?", "promptLanguage": "fr", "answer": "Flavien", "acceptedAnswers": ["Flavien"], "explanation": "C''est Flavien.", "tip": "Flavien = 448.", "extraExample": {"text": "Il est déposé en 449.", "translation": "À Éphèse II."}, "pool": "lesson", "lessonId": "eg.l38", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
