insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e14', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.accusations_contre_dioscore']::text[], 'fill_blank', 'lesson', 'On accuse Dioscore d''avoir condamné Flavien sans ___.', array['raison']::text[], 'La tradition copte répond que Flavien avait enfreint Nicée et Éphèse I.', 3, '{"id": "eg.l41.e14", "unitIds": ["eg.g41.dioscore", "eg.v.accusations_contre_dioscore"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "On accuse Dioscore d''avoir condamné Flavien sans ___.", "promptLanguage": "fr", "options": ["raison", "preuve de foi", "autorisation papale"], "answer": "raison", "acceptedAnswers": ["raison"], "explanation": "La tradition copte répond que Flavien avait enfreint Nicée et Éphèse I.", "tip": "Sans raison ≠ avec raison.", "extraExample": {"text": "Deuxième accusation.", "translation": "Réponse : Nicée et Éphèse I."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
