insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e16', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.accusations_contre_dioscore']::text[], 'match', 'lesson', 'Les accusations et les réponses', '{}'::text[], 'À chaque accusation, une réponse.', 3, '{"id": "eg.l41.e16", "unitIds": ["eg.g41.dioscore", "eg.v.accusations_contre_dioscore"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les accusations et les réponses", "promptLanguage": "fr", "pairs": [{"left": "Eutychès accepté ?", "right": "le Christ est UN"}, {"left": "Flavien condamné sans raison ?", "right": "avait enfreint Nicée et Éphèse I"}, {"left": "Tome non lu ?", "right": "Faute de temps"}], "answer": "Eutychès accepté ? = le Christ est UN ; Flavien condamné sans raison ? = avait enfreint Nicée et Éphèse I ; Tome non lu ? = Faute de temps", "acceptedAnswers": [], "explanation": "À chaque accusation, une réponse.", "tip": "Trois accusations, trois réponses.", "extraExample": {"text": "La tradition copte les détaille.", "translation": "Cela montre sa bonne foi."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e17', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.gangra']::text[], 'match', 'lesson', 'Pour retenir Dioscore', '{}'::text[], 'Quatre repères sur Dioscore.', 2, '{"id": "eg.l41.e17", "unitIds": ["eg.g41.dioscore", "eg.v.gangra"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Pour retenir Dioscore", "promptLanguage": "fr", "pairs": [{"left": "Gangra", "right": "lieu de son exil"}, {"left": "454", "right": "mort de Dioscore"}, {"left": "confesseur", "right": "souffre pour sa foi sans mourir martyr"}, {"left": "archidiacre", "right": "premier assistant de Cyrille"}], "answer": "Gangra = lieu de son exil ; 454 = mort de Dioscore ; confesseur = souffre pour sa foi sans mourir martyr ; archidiacre = premier assistant de Cyrille", "acceptedAnswers": [], "explanation": "Quatre repères sur Dioscore.", "tip": "Gangra, 454, confesseur, archidiacre.", "extraExample": {"text": "Retiens ces quatre mots.", "translation": "Ils résument sa vie."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
