insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e19', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.confesseur']::text[], 'free_answer', 'lesson', 'Quel pape d''Alexandrie, exilé à Gangra, l''Église copte vénère-t-elle comme confesseur ?', array['Dioscore','saint Dioscore']::text[], 'C''est saint Dioscore.', 2, '{"id": "eg.l41.e19", "unitIds": ["eg.g41.dioscore", "eg.v.confesseur"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel pape d''Alexandrie, exilé à Gangra, l''Église copte vénère-t-elle comme confesseur ?", "promptLanguage": "fr", "answer": "Dioscore", "acceptedAnswers": ["Dioscore", "saint Dioscore"], "explanation": "C''est saint Dioscore.", "tip": "Dioscore = confesseur.", "extraExample": {"text": "Il est le 25e pape.", "translation": "Il meurt en 454."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e20', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.gangra']::text[], 'free_answer', 'lesson', 'En quelle année Dioscore meurt-il en exil ?', array['454']::text[], 'En 454.', 2, '{"id": "eg.l41.e20", "unitIds": ["eg.g41.dioscore", "eg.v.gangra"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "En quelle année Dioscore meurt-il en exil ?", "promptLanguage": "fr", "answer": "454", "acceptedAnswers": ["454"], "explanation": "En 454.", "tip": "444 puis 454.", "extraExample": {"text": "Dix ans de pontificat.", "translation": "Dont trois d''exil."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l41.e21', 'eg', 'eg.l41', 'eg.g41.dioscore', array['eg.g41.dioscore','eg.v.archidiacre']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on le premier assistant d''un évêque, comme Dioscore auprès de Cyrille ?', array['archidiacre','l''archidiacre']::text[], 'C''est l''archidiacre.', 2, '{"id": "eg.l41.e21", "unitIds": ["eg.g41.dioscore", "eg.v.archidiacre"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on le premier assistant d''un évêque, comme Dioscore auprès de Cyrille ?", "promptLanguage": "fr", "answer": "archidiacre", "acceptedAnswers": ["archidiacre", "l''archidiacre"], "explanation": "C''est l''archidiacre.", "tip": "Archidiacre.", "extraExample": {"text": "Il prépare la succession.", "translation": "Souvent."}, "pool": "lesson", "lessonId": "eg.l41", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l42.e01', 'eg', 'eg.l42', 'eg.g42.miaphysisme', array['eg.g42.miaphysisme','eg.v.physis']::text[], 'mcq', 'lesson', 'Que veut dire le mot grec physis ?', array['nature']::text[], 'Physis = nature. Monophysisme = une seule nature.', 1, '{"id": "eg.l42.e01", "unitIds": ["eg.g42.miaphysisme", "eg.v.physis"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le mot grec physis ?", "promptLanguage": "fr", "options": ["nature", "personne", "volonté", "corps"], "answer": "nature", "acceptedAnswers": ["nature"], "explanation": "Physis = nature. Monophysisme = une seule nature.", "tip": "Physique, physis : nature.", "extraExample": {"text": "On le retrouve dans trois mots.", "translation": "Mono, dyo, mia."}, "pool": "lesson", "lessonId": "eg.l42", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
