insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l44.e02', 'eg', 'eg.l44', 'eg.g44.deux_familles', array['eg.g44.deux_familles','eg.v.eglises_soeurs']::text[], 'mcq', 'lesson', 'Laquelle de ces Églises n''est pas une Église sœur de l''Église copte ?', array['l''Église de l''Orient']::text[], 'Rappel : l''Église de l''Orient, née en Perse, est liée à Nestorius.', 3, '{"id": "eg.l44.e02", "unitIds": ["eg.g44.deux_familles", "eg.v.eglises_soeurs"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Laquelle de ces Églises n''est pas une Église sœur de l''Église copte ?", "promptLanguage": "fr", "options": ["l''Église de l''Orient", "l''Église arménienne", "l''Église éthiopienne", "l''Église syriaque"], "answer": "l''Église de l''Orient", "acceptedAnswers": ["l''Église de l''Orient"], "explanation": "Rappel : l''Église de l''Orient, née en Perse, est liée à Nestorius.", "tip": "Perse ≠ sœurs.", "extraExample": {"text": "Elle ne reconnaît pas Éphèse.", "translation": "Autre histoire."}, "pool": "lesson", "lessonId": "eg.l44", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l44.e03', 'eg', 'eg.l44', 'eg.g44.deux_familles', array['eg.g44.deux_familles','eg.v.intercommunion']::text[], 'mcq', 'lesson', 'Que signifie l''intercommunion ?', array['communion pleine entre Églises, y compris le mariage entre leurs fidèles']::text[], 'Les Églises sœurs se reconnaissent mutuellement.', 2, '{"id": "eg.l44.e03", "unitIds": ["eg.g44.deux_familles", "eg.v.intercommunion"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie l''intercommunion ?", "promptLanguage": "fr", "options": ["communion pleine entre Églises, y compris le mariage entre leurs fidèles", "un concile commun", "une même liturgie", "une même langue"], "answer": "communion pleine entre Églises, y compris le mariage entre leurs fidèles", "acceptedAnswers": ["communion pleine entre Églises, y compris le mariage entre leurs fidèles"], "explanation": "Les Églises sœurs se reconnaissent mutuellement.", "tip": "Inter = entre.", "extraExample": {"text": "Elle existe entre les six.", "translation": "Pas avec les chalcédoniennes."}, "pool": "lesson", "lessonId": "eg.l44", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
