insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e15', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.symbole_de_foi']::text[], 'fill_blank', 'lesson', 'Le credo s''appelle aussi le ___ de foi.', array['symbole']::text[], 'Le credo est la formule de foi, appelée aussi symbole de foi (carte 4).', 2, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.symbole_de_foi"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le credo s''appelle aussi le ___ de foi.", "options": ["symbole", "canon", "synode"], "answer": "symbole", "acceptedAnswers": ["symbole"], "explanation": "Le credo est la formule de foi, appelée aussi symbole de foi (carte 4).", "tip": "Symbole de foi = credo.", "extraExample": {"text": "Le symbole de foi résume la foi.", "translation": "On le récite à la messe."}, "id": "eg.l45.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e16', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'match', 'lesson', 'Qui convoque quel concile ?', '{}'::text[], 'Chaque concile a son empereur (carte 3).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui convoque quel concile ?", "pairs": [{"left": "Nicée (325)", "right": "Constantin"}, {"left": "Constantinople (381)", "right": "Théodose Ier"}, {"left": "Éphèse (431)", "right": "Théodose II"}, {"left": "Chalcédoine (451)", "right": "Marcien"}], "answer": "Nicée (325) = Constantin ; Constantinople (381) = Théodose Ier ; Éphèse (431) = Théodose II ; Chalcédoine (451) = Marcien", "acceptedAnswers": [], "explanation": "Chaque concile a son empereur (carte 3).", "tip": "Constantin, deux Théodose, Marcien.", "id": "eg.l45.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e17', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'match', 'lesson', 'Ce que produit un concile', '{}'::text[], 'Formule de foi, anathèmes, canons : trois produits différents (carte 4).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Ce que produit un concile", "pairs": [{"left": "un anathème", "right": "une condamnation solennelle de l''erreur"}, {"left": "un canon", "right": "des règles pour la vie de l''Église"}, {"left": "un credo", "right": "une formule de foi"}, {"left": "un synode", "right": "un concile local"}], "answer": "un anathème = une condamnation solennelle de l''erreur ; un canon = des règles pour la vie de l''Église ; un credo = une formule de foi ; un synode = un concile local", "acceptedAnswers": [], "explanation": "Formule de foi, anathèmes, canons : trois produits différents (carte 4).", "tip": "Foi, condamnation, règle.", "id": "eg.l45.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e18', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles']::text[], 'reorder', 'lesson', 'Phrase-repère : le concile œcuménique.', array['Un concile œcuménique réunit les évêques de toute l''Église']::text[], 'Œcuménique veut dire « de toute la terre habitée » (carte 2).', 2, '{"unitIds": ["eg.g45.logique_des_conciles"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le concile œcuménique.", "tokens": ["l''Église", "de", "Un", "toute", "évêques", "réunit", "œcuménique", "les", "concile"], "answer": "Un concile œcuménique réunit les évêques de toute l''Église", "acceptedAnswers": ["Un concile œcuménique réunit les évêques de toute l''Église"], "explanation": "Œcuménique veut dire « de toute la terre habitée » (carte 2).", "tip": "Œcuménique = toute l''Église.", "extraExample": {"text": "Un synode réunit les évêques d''une région.", "translation": "C''est la différence."}, "id": "eg.l45.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e19', 'eg', 'eg.l45', 'eg.g45.logique_des_conciles', array['eg.g45.logique_des_conciles','eg.v.reception_d_un_concile']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on l''acceptation d''un concile par toute l''Église ?', array['la réception','réception','reception','la reception']::text[], 'C''est la réception : un concile n''est œcuménique que s''il est reçu par l''ensemble de l''Église (carte 5).', 3, '{"unitIds": ["eg.g45.logique_des_conciles", "eg.v.reception_d_un_concile"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on l''acceptation d''un concile par toute l''Église ?", "answer": "la réception", "acceptedAnswers": ["la réception", "réception", "reception", "la reception"], "explanation": "C''est la réception : un concile n''est œcuménique que s''il est reçu par l''ensemble de l''Église (carte 5).", "tip": "Réception = acceptation.", "extraExample": {"text": "Chalcédoine n''est pas reçu par les coptes.", "translation": "Nicée l''est."}, "id": "eg.l45.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e20', 'eg', 'eg.l45', 'eg.v.concile_de_nicee', array['eg.v.concile_de_nicee','eg.g45.logique_des_conciles']::text[], 'free_answer', 'lesson', 'Quel empereur a convoqué le concile de Nicée ?', array['Constantin','l''empereur Constantin']::text[], 'Constantin convoque Nicée en 325, pour rétablir l''unité de l''empire (carte 3).', 1, '{"unitIds": ["eg.v.concile_de_nicee", "eg.g45.logique_des_conciles"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel empereur a convoqué le concile de Nicée ?", "answer": "Constantin", "acceptedAnswers": ["Constantin", "l''empereur Constantin"], "explanation": "Constantin convoque Nicée en 325, pour rétablir l''unité de l''empire (carte 3).", "tip": "Nicée = Constantin.", "extraExample": {"text": "Il convoque Nicée en 325.", "translation": "Il veut un empire uni."}, "id": "eg.l45.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l45.e21', 'eg', 'eg.l45', 'eg.v.concile_d_antioche_269', array['eg.v.concile_d_antioche_269','eg.g45.logique_des_conciles']::text[], 'free_answer', 'lesson', 'Dans quelle ville se tient le synode de 269 qui condamne Paul de Samosate ?', array['Antioche','à Antioche']::text[], 'Le synode d''Antioche de 269 est un concile local (carte 2).', 3, '{"unitIds": ["eg.v.concile_d_antioche_269", "eg.g45.logique_des_conciles"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Dans quelle ville se tient le synode de 269 qui condamne Paul de Samosate ?", "answer": "Antioche", "acceptedAnswers": ["Antioche", "à Antioche"], "explanation": "Le synode d''Antioche de 269 est un concile local (carte 2).", "tip": "Antioche 269 = synode.", "extraExample": {"text": "Paul est évêque d''Antioche.", "translation": "Il y est excommunié."}, "id": "eg.l45.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l45", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e01', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.dualisme']::text[], 'mcq', 'lesson', 'Comment appelle-t-on la croyance en deux principes, un bon et un mauvais ?', array['le dualisme']::text[], 'Gnostiques, Marcion et Mani croient à deux principes opposés : c''est le dualisme (carte 2).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.dualisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on la croyance en deux principes, un bon et un mauvais ?", "options": ["le dualisme", "le modalisme", "l''adoptianisme", "le millénarisme"], "answer": "le dualisme", "acceptedAnswers": ["le dualisme"], "explanation": "Gnostiques, Marcion et Mani croient à deux principes opposés : c''est le dualisme (carte 2).", "tip": "Dualisme = deux principes.", "extraExample": {"text": "Les gnostiques opposent un esprit bon à une matière mauvaise.", "translation": "Deux mondes."}, "errorPatterns": [{"equals": "le modalisme", "category": "word_confusion", "feedback": "Le modalisme est l''erreur de Sabellius sur les trois personnes, pas la croyance en deux principes."}], "id": "eg.l46.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e02', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.marcionisme']::text[], 'mcq', 'lesson', 'Combien de dieux Marcion croit-il y avoir ?', array['deux dieux']::text[], 'Marcion oppose le Dieu de justice de l''Ancien Testament au Dieu d''amour du Nouveau (carte 3).', 1, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.marcionisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de dieux Marcion croit-il y avoir ?", "options": ["deux dieux", "un seul Dieu en trois personnes", "trois dieux", "aucun dieu"], "answer": "deux dieux", "acceptedAnswers": ["deux dieux"], "explanation": "Marcion oppose le Dieu de justice de l''Ancien Testament au Dieu d''amour du Nouveau (carte 3).", "tip": "Marcion = deux dieux.", "extraExample": {"text": "Il garde Luc et dix lettres de Paul.", "translation": "Il rejette le reste."}, "id": "eg.l46.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e03', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.marcion']::text[], 'mcq', 'lesson', 'Que garde Marcion du Nouveau Testament ?', array['Luc et dix lettres de Paul']::text[], 'Marcion ne garde que l''évangile de Luc et dix lettres de Paul (carte 3). Cela oblige l''Église à définir son canon.', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.marcion"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que garde Marcion du Nouveau Testament ?", "options": ["Luc et dix lettres de Paul", "Matthieu et Jean", "les quatre évangiles", "uniquement les Actes"], "answer": "Luc et dix lettres de Paul", "acceptedAnswers": ["Luc et dix lettres de Paul"], "explanation": "Marcion ne garde que l''évangile de Luc et dix lettres de Paul (carte 3). Cela oblige l''Église à définir son canon.", "tip": "Marcion : Luc et dix lettres de Paul.", "extraExample": {"text": "Irénée défend les quatre évangiles.", "translation": "Ni plus ni moins."}, "id": "eg.l46.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e04', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.montanisme']::text[], 'mcq', 'lesson', 'Au nom de qui Montanus prétend-il parler ?', array['le Paraclet']::text[], 'Montanus se dit l''organe du Paraclet, l''Esprit Saint (carte 4). L''Église répond que la Révélation est complète.', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.montanisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Au nom de qui Montanus prétend-il parler ?", "options": ["le Paraclet", "le démiurge", "l''empereur", "Sabellius"], "answer": "le Paraclet", "acceptedAnswers": ["le Paraclet"], "explanation": "Montanus se dit l''organe du Paraclet, l''Esprit Saint (carte 4). L''Église répond que la Révélation est complète.", "tip": "Montan = Paraclet.", "extraExample": {"text": "Priscilla et Maximilla le suivent.", "translation": "Elles prophétisent en transe."}, "id": "eg.l46.e04", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e05', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.modalisme']::text[], 'mcq', 'lesson', 'Quelle image résume le modalisme de Sabellius ?', array['un acteur qui change de masque']::text[], 'Pour Sabellius, Père, Fils et Esprit sont le même Dieu sous trois masques (carte 5).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.modalisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle image résume le modalisme de Sabellius ?", "options": ["un acteur qui change de masque", "un soleil à trois rayons indépendants", "un maître et ses deux serviteurs", "trois dieux dans un temple"], "answer": "un acteur qui change de masque", "acceptedAnswers": ["un acteur qui change de masque"], "explanation": "Pour Sabellius, Père, Fils et Esprit sont le même Dieu sous trois masques (carte 5).", "tip": "Modalisme = masques.", "extraExample": {"text": "Père pour la création, Fils pour la Rédemption.", "translation": "Esprit pour la grâce."}, "errorPatterns": [{"equals": "trois dieux dans un temple", "category": "word_confusion", "feedback": "Ce serait plutôt trois dieux : le modalisme dit au contraire qu''il n''y a qu''un acteur."}], "id": "eg.l46.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e06', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.paul_de_samosate']::text[], 'mcq', 'lesson', 'Pour Paul de Samosate, que serait le Christ ?', array['un homme ordinaire']::text[], 'Paul enseigne que le Christ est un homme ordinaire choisi par Dieu (carte 6). Le fantôme, c''est le docétisme.', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.paul_de_samosate"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pour Paul de Samosate, que serait le Christ ?", "options": ["un homme ordinaire", "une créature divine", "un ange", "un fantôme"], "answer": "un homme ordinaire", "acceptedAnswers": ["un homme ordinaire"], "explanation": "Paul enseigne que le Christ est un homme ordinaire choisi par Dieu (carte 6). Le fantôme, c''est le docétisme.", "tip": "Paul : homme ordinaire.", "extraExample": {"text": "Dieu l''aurait seulement accompagné.", "translation": "Il n''y a pas d''union."}, "errorPatterns": [{"equals": "un fantôme", "category": "word_confusion", "feedback": "Le Christ fantôme, c''est le docétisme. Paul fait du Christ un simple homme."}], "id": "eg.l46.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e07', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.adoptianisme']::text[], 'mcq', 'lesson', 'Comment appelle-t-on l''idée que le Christ est un homme « adopté » par Dieu ?', array['l''adoptianisme']::text[], 'Adoptianisme : le Christ n''est pas Dieu par nature, mais adopté. C''est l''erreur de Paul de Samosate (carte 6).', 3, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.adoptianisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on l''idée que le Christ est un homme « adopté » par Dieu ?", "options": ["l''adoptianisme", "le nestorianisme", "le docétisme", "le millénarisme"], "answer": "l''adoptianisme", "acceptedAnswers": ["l''adoptianisme"], "explanation": "Adoptianisme : le Christ n''est pas Dieu par nature, mais adopté. C''est l''erreur de Paul de Samosate (carte 6).", "tip": "Adopté = adoptianisme.", "extraExample": {"text": "Le Fils est Dieu de toute éternité.", "translation": "Il n''est pas adopté."}, "id": "eg.l46.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e08', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.arianisme']::text[], 'mcq', 'lesson', 'Selon Arius, qu''est-ce que le Fils ?', array['Le Fils est une créature']::text[], 'Pour Arius, le Fils a été créé : « il fut un temps où il n''était pas » (carte 7).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.arianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Selon Arius, qu''est-ce que le Fils ?", "options": ["Le Fils est une créature", "Le Fils est identique au Père", "Le Fils n''a pas de corps", "Le Fils est un homme ordinaire"], "answer": "Le Fils est une créature", "acceptedAnswers": ["Le Fils est une créature"], "explanation": "Pour Arius, le Fils a été créé : « il fut un temps où il n''était pas » (carte 7).", "tip": "Arius : créature.", "extraExample": {"text": "Une créature ne peut pas nous sauver.", "translation": "Seul Dieu sauve."}, "errorPatterns": [{"equals": "Le Fils est un homme ordinaire", "category": "word_confusion", "feedback": "C''est l''erreur de Paul de Samosate. Arius fait du Fils une créature, plus haute que l''homme."}], "id": "eg.l46.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e09', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.macedonius']::text[], 'mcq', 'lesson', 'Que nie Macédonius ?', array['la divinité du Saint-Esprit']::text[], 'Macédonius nie la divinité de l''Esprit, comme Arius celle du Fils (carte 8).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.macedonius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que nie Macédonius ?", "options": ["la divinité du Saint-Esprit", "la divinité du Fils", "la résurrection", "l''existence de Marie"], "answer": "la divinité du Saint-Esprit", "acceptedAnswers": ["la divinité du Saint-Esprit"], "explanation": "Macédonius nie la divinité de l''Esprit, comme Arius celle du Fils (carte 8).", "tip": "Arius = Fils ; Macédonius = Esprit.", "extraExample": {"text": "Il est destitué en 381.", "translation": "Le credo est complété."}, "errorPatterns": [{"equals": "la divinité du Fils", "category": "word_confusion", "feedback": "C''est Arius qui nie la divinité du Fils. Macédonius nie celle de l''Esprit."}], "id": "eg.l46.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e10', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.pneumatomaques']::text[], 'mcq', 'lesson', 'Que veut dire « pneumatomaques » ?', array['ceux qui combattent l''Esprit']::text[], 'Pneuma = esprit, machê = combat : ils combattent la divinité de l''Esprit (carte 8).', 3, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.pneumatomaques"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « pneumatomaques » ?", "options": ["ceux qui combattent l''Esprit", "ceux qui aiment la sagesse", "ceux qui refusent la croix", "ceux qui prient sans cesse"], "answer": "ceux qui combattent l''Esprit", "acceptedAnswers": ["ceux qui combattent l''Esprit"], "explanation": "Pneuma = esprit, machê = combat : ils combattent la divinité de l''Esprit (carte 8).", "tip": "Pneuma = Esprit.", "extraExample": {"text": "Macédonius est leur chef.", "translation": "Constantinople les condamne."}, "id": "eg.l46.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e11', 'eg', 'eg.l46', 'eg.v.denys_d_alexandrie', array['eg.v.denys_d_alexandrie','eg.g46.heresies_dieu_trinite']::text[], 'mcq', 'lesson', 'Quel pape d''Alexandrie écrit une lettre contre l''erreur de Paul de Samosate ?', array['Denys']::text[], 'Le pape Denys écrit la lettre lue au synode d''Antioche en 269 (carte 6).', 2, '{"unitIds": ["eg.v.denys_d_alexandrie", "eg.g46.heresies_dieu_trinite"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape d''Alexandrie écrit une lettre contre l''erreur de Paul de Samosate ?", "options": ["Denys", "Athanase", "Cyrille", "Dioscore"], "answer": "Denys", "acceptedAnswers": ["Denys"], "explanation": "Le pape Denys écrit la lettre lue au synode d''Antioche en 269 (carte 6).", "tip": "Denys : 269.", "extraExample": {"text": "Athanase vient au IVe siècle.", "translation": "Cyrille au Ve."}, "id": "eg.l46.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e12', 'eg', 'eg.l46', 'eg.v.irenee_de_lyon', array['eg.v.irenee_de_lyon','eg.g46.heresies_dieu_trinite']::text[], 'mcq', 'lesson', 'Qui écrit « Contre les hérésies » vers 180 pour répondre aux gnostiques ?', array['Irénée de Lyon']::text[], 'Irénée, disciple de Polycarpe, écrit Contre les hérésies (carte 2).', 2, '{"unitIds": ["eg.v.irenee_de_lyon", "eg.g46.heresies_dieu_trinite"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui écrit « Contre les hérésies » vers 180 pour répondre aux gnostiques ?", "options": ["Irénée de Lyon", "Tertullien", "Justin Martyr", "Cyprien de Carthage"], "answer": "Irénée de Lyon", "acceptedAnswers": ["Irénée de Lyon"], "explanation": "Irénée, disciple de Polycarpe, écrit Contre les hérésies (carte 2).", "tip": "Irénée contre la gnose.", "extraExample": {"text": "Tertullien écrit Contre Marcion.", "translation": "Chacun son adversaire."}, "id": "eg.l46.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e13', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.sabellius']::text[], 'fill_blank', 'lesson', 'Le modalisme est l''erreur de ___.', array['Sabellius']::text[], 'Sabellius voit en Père, Fils et Esprit trois masques d''un seul Dieu (carte 5).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.sabellius"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le modalisme est l''erreur de ___.", "options": ["Sabellius", "Arius", "Marcion"], "answer": "Sabellius", "acceptedAnswers": ["Sabellius"], "explanation": "Sabellius voit en Père, Fils et Esprit trois masques d''un seul Dieu (carte 5).", "tip": "Sabellius = masques.", "extraExample": {"text": "Arius rabaisse le Fils.", "translation": "Il fait autre chose."}, "id": "eg.l46.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e14', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.consubstantiel','eg.v.homoousios']::text[], 'fill_blank', 'lesson', 'Homoousios veut dire ___ : de même substance que le Père.', array['consubstantiel']::text[], 'Le Fils est consubstantiel au Père : même substance divine (carte 7).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.consubstantiel", "eg.v.homoousios"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Homoousios veut dire ___ : de même substance que le Père.", "options": ["consubstantiel", "créé", "similaire"], "answer": "consubstantiel", "acceptedAnswers": ["consubstantiel"], "explanation": "Le Fils est consubstantiel au Père : même substance divine (carte 7).", "tip": "Homoousios = consubstantiel.", "extraExample": {"text": "Le Saint-Esprit aussi est consubstantiel.", "translation": "381 le confirme."}, "id": "eg.l46.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e15', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.semi_arianisme']::text[], 'fill_blank', 'lesson', 'Les semi-ariens disent que le Fils a une substance ___ à celle du Père.', array['similaire']::text[], 'Homoiousios = substance similaire, homoousios = même substance (carte 7).', 3, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.semi_arianisme"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Les semi-ariens disent que le Fils a une substance ___ à celle du Père.", "options": ["similaire", "identique", "opposée"], "answer": "similaire", "acceptedAnswers": ["similaire"], "explanation": "Homoiousios = substance similaire, homoousios = même substance (carte 7).", "tip": "Similaire ≠ identique.", "extraExample": {"text": "Un seul iota sépare les deux mots.", "translation": "Mais tout change."}, "id": "eg.l46.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e16', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite']::text[], 'match', 'lesson', 'Quelle idée pour quelle hérésie ?', '{}'::text[], 'Une idée, une hérésie (cartes 2 à 7).', 3, '{"unitIds": ["eg.g46.heresies_dieu_trinite"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle idée pour quelle hérésie ?", "pairs": [{"left": "le gnosticisme", "right": "le salut par une connaissance secrète"}, {"left": "le marcionisme", "right": "deux dieux"}, {"left": "le modalisme", "right": "un acteur qui change de masque"}, {"left": "l''arianisme", "right": "le Fils est une créature"}], "answer": "le gnosticisme = le salut par une connaissance secrète ; le marcionisme = deux dieux ; le modalisme = un acteur qui change de masque ; l''arianisme = le Fils est une créature", "acceptedAnswers": [], "explanation": "Une idée, une hérésie (cartes 2 à 7).", "tip": "Une phrase par hérésie.", "id": "eg.l46.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e17', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite']::text[], 'match', 'lesson', 'Qui répond à quelle erreur ?', '{}'::text[], 'Chaque erreur rencontre sa réponse (cartes 2 à 7).', 3, '{"unitIds": ["eg.g46.heresies_dieu_trinite"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui répond à quelle erreur ?", "pairs": [{"left": "Arius", "right": "Athanase"}, {"left": "les gnostiques", "right": "Irénée de Lyon"}, {"left": "Marcion", "right": "Tertullien"}, {"left": "Sabellius", "right": "Denys d''Alexandrie"}, {"left": "Paul de Samosate", "right": "le synode d''Antioche (269)"}], "answer": "Arius = Athanase ; les gnostiques = Irénée de Lyon ; Marcion = Tertullien ; Sabellius = Denys d''Alexandrie ; Paul de Samosate = le synode d''Antioche (269)", "acceptedAnswers": [], "explanation": "Chaque erreur rencontre sa réponse (cartes 2 à 7).", "tip": "Un adversaire, un défenseur.", "id": "eg.l46.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e18', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite']::text[], 'reorder', 'lesson', 'Phrase-repère : la foi trinitaire.', array['L''Église confesse trois personnes et une seule divinité']::text[], 'Trois personnes, une seule divinité : la foi trinitaire (carte 1).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la foi trinitaire.", "tokens": ["trois", "et", "confesse", "seule", "personnes", "une", "divinité", "L''Église"], "answer": "L''Église confesse trois personnes et une seule divinité", "acceptedAnswers": ["L''Église confesse trois personnes et une seule divinité"], "explanation": "Trois personnes, une seule divinité : la foi trinitaire (carte 1).", "tip": "Trois personnes, un seul Dieu.", "extraExample": {"text": "Le Père, le Fils et l''Esprit sont un seul Dieu.", "translation": "Sans masque."}, "id": "eg.l46.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e19', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.pneumatomaques']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on les disciples de Macédonius qui nient la divinité de l''Esprit ?', array['les pneumatomaques','pneumatomaques']::text[], 'Pneumatomaques : « ceux qui combattent l''Esprit » (carte 8).', 3, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.pneumatomaques"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on les disciples de Macédonius qui nient la divinité de l''Esprit ?", "answer": "les pneumatomaques", "acceptedAnswers": ["les pneumatomaques", "pneumatomaques"], "explanation": "Pneumatomaques : « ceux qui combattent l''Esprit » (carte 8).", "tip": "Pneuma = Esprit.", "extraExample": {"text": "Ils sont condamnés en 381.", "translation": "À Constantinople."}, "id": "eg.l46.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e20', 'eg', 'eg.l46', 'eg.g46.heresies_dieu_trinite', array['eg.g46.heresies_dieu_trinite','eg.v.homoousios']::text[], 'free_answer', 'lesson', 'Quel mot grec exprime la consubstantialité du Fils avec le Père ?', array['homoousios','l''homoousios']::text[], 'Homoousios, adopté à Nicée en 325, répond à Arius (carte 7).', 2, '{"unitIds": ["eg.g46.heresies_dieu_trinite", "eg.v.homoousios"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot grec exprime la consubstantialité du Fils avec le Père ?", "answer": "homoousios", "acceptedAnswers": ["homoousios", "l''homoousios"], "explanation": "Homoousios, adopté à Nicée en 325, répond à Arius (carte 7).", "tip": "Homoousios = même substance.", "extraExample": {"text": "Homoiousios est le mot semi-arien.", "translation": "Un iota de plus."}, "id": "eg.l46.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l46.e21', 'eg', 'eg.l46', 'eg.v.zenobie', array['eg.v.zenobie','eg.g46.heresies_dieu_trinite']::text[], 'free_answer', 'lesson', 'Quelle reine protège Paul de Samosate ?', array['Zénobie','Zenobie','la reine Zénobie']::text[], 'Zénobie, reine de Palmyre, protège Paul de Samosate (carte 6).', 3, '{"unitIds": ["eg.v.zenobie", "eg.g46.heresies_dieu_trinite"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quelle reine protège Paul de Samosate ?", "answer": "Zénobie", "acceptedAnswers": ["Zénobie", "Zenobie", "la reine Zénobie"], "explanation": "Zénobie, reine de Palmyre, protège Paul de Samosate (carte 6).", "tip": "Zénobie = Palmyre.", "extraExample": {"text": "Elle gouverne une région d''Orient.", "translation": "Paul est donc puissant."}, "id": "eg.l46.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l46", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e01', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.docetisme']::text[], 'mcq', 'lesson', 'Que dit le docétisme du corps du Christ ?', array['un corps apparent']::text[], 'Docétisme vient de dokein, « sembler » : le Christ n''aurait eu qu''un corps apparent (carte 2).', 1, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.docetisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit le docétisme du corps du Christ ?", "options": ["un corps apparent", "un corps réel sans âme", "un corps divin sans humanité", "deux corps distincts"], "answer": "un corps apparent", "acceptedAnswers": ["un corps apparent"], "explanation": "Docétisme vient de dokein, « sembler » : le Christ n''aurait eu qu''un corps apparent (carte 2).", "tip": "Docétisme = apparence.", "extraExample": {"text": "Un fantôme ne souffre pas.", "translation": "Il n''y aurait pas de salut réel."}, "errorPatterns": [{"equals": "un corps réel sans âme", "category": "word_confusion", "feedback": "Le corps réel sans âme humaine, c''est l''apollinarisme, pas le docétisme."}], "id": "eg.l47.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e02', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.saint_jean']::text[], 'mcq', 'lesson', 'Qui répond au docétisme par « Le Verbe s''est fait chair » ?', array['saint Jean']::text[], 'Dans son évangile, saint Jean affirme que le Verbe s''est fait chair, ce qui contredit les docètes (carte 2).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.saint_jean"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui répond au docétisme par « Le Verbe s''est fait chair » ?", "options": ["saint Jean", "saint Marc", "saint Paul de Thèbes", "saint Barnabé"], "answer": "saint Jean", "acceptedAnswers": ["saint Jean"], "explanation": "Dans son évangile, saint Jean affirme que le Verbe s''est fait chair, ce qui contredit les docètes (carte 2).", "tip": "Jean contre la gnose.", "extraExample": {"text": "Jean 1, 14.", "translation": "Le Verbe s''est fait chair."}, "id": "eg.l47.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e03', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.apollinarisme']::text[], 'mcq', 'lesson', 'Que manque-t-il au Christ selon Apollinaire ?', array['une âme humaine']::text[], 'Selon Apollinaire, la divinité du Verbe prendrait la place de l''âme : le Christ ne serait pas homme en entier (carte 3).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.apollinarisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que manque-t-il au Christ selon Apollinaire ?", "options": ["une âme humaine", "un corps", "sa divinité", "une mère"], "answer": "une âme humaine", "acceptedAnswers": ["une âme humaine"], "explanation": "Selon Apollinaire, la divinité du Verbe prendrait la place de l''âme : le Christ ne serait pas homme en entier (carte 3).", "tip": "Apollinaire : pas d''âme.", "extraExample": {"text": "Le pape Timothée le réfute.", "translation": "L''homme doit être sauvé tout entier."}, "errorPatterns": [{"equals": "un corps", "category": "word_confusion", "feedback": "Apollinaire admet un corps humain. C''est l''âme humaine qui manque."}], "id": "eg.l47.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e04', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.apollinaire']::text[], 'mcq', 'lesson', 'Quel concile condamne Apollinaire ?', array['Constantinople (381)']::text[], 'Constantinople (381) condamne Apollinaire et Macédonius (carte 3).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.apollinaire"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile condamne Apollinaire ?", "options": ["Constantinople (381)", "Nicée (325)", "Éphèse (431)", "Chalcédoine (451)"], "answer": "Constantinople (381)", "acceptedAnswers": ["Constantinople (381)"], "explanation": "Constantinople (381) condamne Apollinaire et Macédonius (carte 3).", "tip": "381 : Apollinaire et Macédonius.", "extraExample": {"text": "Nicée condamne Arius.", "translation": "Éphèse condamne Nestorius."}, "id": "eg.l47.e04", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e05', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.nestorianisme']::text[], 'mcq', 'lesson', 'Quel est le reproche fait à Nestorius ?', array['de séparer le Verbe de l''homme Jésus']::text[], 'Nestorius sépare le Verbe et l''homme au point d''en faire presque deux personnes (carte 4).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.nestorianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le reproche fait à Nestorius ?", "options": ["de séparer le Verbe de l''homme Jésus", "de nier le corps du Christ", "de mélanger les natures", "de nier la Trinité"], "answer": "de séparer le Verbe de l''homme Jésus", "acceptedAnswers": ["de séparer le Verbe de l''homme Jésus"], "explanation": "Nestorius sépare le Verbe et l''homme au point d''en faire presque deux personnes (carte 4).", "tip": "Nestorius sépare.", "extraExample": {"text": "Dieu y habiterait comme dans un temple.", "translation": "Il n''y aurait plus un seul Christ."}, "errorPatterns": [{"equals": "de mélanger les natures", "category": "word_confusion", "feedback": "Mélanger, c''est l''erreur d''Eutychès. Nestorius, lui, sépare."}], "id": "eg.l47.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e06', 'eg', 'eg.l47', 'eg.v.christotokos', array['eg.v.christotokos','eg.g47.heresies_christ']::text[], 'mcq', 'lesson', 'Quel titre de Marie Nestorius préfère-t-il à Théotokos ?', array['Christotokos']::text[], 'Nestorius préfère Christotokos, « mère du Christ » (carte 4).', 2, '{"unitIds": ["eg.v.christotokos", "eg.g47.heresies_christ"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre de Marie Nestorius préfère-t-il à Théotokos ?", "options": ["Christotokos", "Theophoros", "Panagia", "Orante"], "answer": "Christotokos", "acceptedAnswers": ["Christotokos"], "explanation": "Nestorius préfère Christotokos, « mère du Christ » (carte 4).", "tip": "Christotokos = mère du Christ.", "extraExample": {"text": "Théotokos = mère de Dieu.", "translation": "Éphèse le proclame."}, "id": "eg.l47.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e07', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.monophysisme']::text[], 'mcq', 'lesson', 'Que devient l''humanité du Christ selon Eutychès ?', array['absorbée par la divinité']::text[], 'Pour Eutychès, la nature divine absorbe l''humanité après l''union (carte 5).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.monophysisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que devient l''humanité du Christ selon Eutychès ?", "options": ["absorbée par la divinité", "séparée de la divinité", "supérieure à la divinité", "égale à la divinité"], "answer": "absorbée par la divinité", "acceptedAnswers": ["absorbée par la divinité"], "explanation": "Pour Eutychès, la nature divine absorbe l''humanité après l''union (carte 5).", "tip": "Absorbée = disparue.", "extraExample": {"text": "Une goutte de miel dans la mer.", "translation": "Elle disparaît."}, "id": "eg.l47.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e08', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.eutyches']::text[], 'mcq', 'lesson', 'Quelle image illustre le monophysisme d''Eutychès ?', array['une goutte de miel dans la mer']::text[], 'La goutte de miel disparaît dans la mer : l''humanité disparaît dans la divinité (carte 5). Le fer et le feu, c''est l''image de Cyrille.', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.eutyches"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle image illustre le monophysisme d''Eutychès ?", "options": ["une goutte de miel dans la mer", "le fer chauffé dans le feu", "l''âme et le corps", "un temple et son habitant"], "answer": "une goutte de miel dans la mer", "acceptedAnswers": ["une goutte de miel dans la mer"], "explanation": "La goutte de miel disparaît dans la mer : l''humanité disparaît dans la divinité (carte 5). Le fer et le feu, c''est l''image de Cyrille.", "tip": "Miel = Eutychès ; fer et feu = Cyrille.", "extraExample": {"text": "L''âme et le corps font un seul homme.", "translation": "C''est l''image de Cyrille."}, "errorPatterns": [{"equals": "le fer chauffé dans le feu", "category": "word_confusion", "feedback": "Cette image est celle de Cyrille : le fer reste du fer et brille comme le feu."}], "id": "eg.l47.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e09', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.formule_de_cyrille']::text[], 'mcq', 'lesson', 'Quelle est la formule de saint Cyrille ?', array['une seule nature du Verbe incarné']::text[], 'Cyrille résume la foi : une seule nature du Verbe incarné (carte 6).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.formule_de_cyrille"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la formule de saint Cyrille ?", "options": ["une seule nature du Verbe incarné", "deux natures sans mélange", "le Christ est créé", "une nature divine seulement"], "answer": "une seule nature du Verbe incarné", "acceptedAnswers": ["une seule nature du Verbe incarné"], "explanation": "Cyrille résume la foi : une seule nature du Verbe incarné (carte 6).", "tip": "Cyrille : une nature du Verbe incarné.", "extraExample": {"text": "Le Verbe incarné est l''unique sujet.", "translation": "Il naît de Marie."}, "id": "eg.l47.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e10', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.miaphysisme']::text[], 'mcq', 'lesson', 'Comment s''appelle la foi de l''Église copte sur la nature du Christ ?', array['le miaphysisme']::text[], 'Le miaphysisme est la foi de Cyrille et de l''Église copte (carte 6). Le monophysisme est celui d''Eutychès.', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.miaphysisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''appelle la foi de l''Église copte sur la nature du Christ ?", "options": ["le miaphysisme", "le monophysisme", "le dyophysisme", "le nestorianisme"], "answer": "le miaphysisme", "acceptedAnswers": ["le miaphysisme"], "explanation": "Le miaphysisme est la foi de Cyrille et de l''Église copte (carte 6). Le monophysisme est celui d''Eutychès.", "tip": "Mia = unie ; mono = seule.", "extraExample": {"text": "Une nature unie, sans mélange.", "translation": "L''humanité est complète."}, "errorPatterns": [{"equals": "le monophysisme", "category": "word_confusion", "feedback": "Le monophysisme est celui d''Eutychès, que l''Église copte condamne aussi."}], "id": "eg.l47.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e11', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ']::text[], 'mcq', 'lesson', 'Quelle phrase résume l''opposition de Nestorius et d''Eutychès ?', array['Nestorius sépare, Eutychès mélange']::text[], 'Ce sont deux erreurs opposées : Nestorius sépare le Verbe de l''homme, Eutychès fait disparaître l''humanité (carte 7).', 3, '{"unitIds": ["eg.g47.heresies_christ"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle phrase résume l''opposition de Nestorius et d''Eutychès ?", "options": ["Nestorius sépare, Eutychès mélange", "Nestorius mélange, Eutychès sépare", "Tous deux séparent", "Tous deux nient le corps"], "answer": "Nestorius sépare, Eutychès mélange", "acceptedAnswers": ["Nestorius sépare, Eutychès mélange"], "explanation": "Ce sont deux erreurs opposées : Nestorius sépare le Verbe de l''homme, Eutychès fait disparaître l''humanité (carte 7).", "tip": "Sépare / mélange.", "extraExample": {"text": "Cyrille garde l''unité.", "translation": "Sans rien perdre."}, "id": "eg.l47.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e12', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.docetisme']::text[], 'fill_blank', 'lesson', 'Le docétisme vient du grec dokein, « ___ ».', array['sembler']::text[], 'Dokein veut dire « sembler » : le Christ ne semblait qu''avoir un corps (carte 2).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.docetisme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le docétisme vient du grec dokein, « ___ ».", "options": ["sembler", "aimer", "croire"], "answer": "sembler", "acceptedAnswers": ["sembler"], "explanation": "Dokein veut dire « sembler » : le Christ ne semblait qu''avoir un corps (carte 2).", "tip": "Docétisme = sembler.", "extraExample": {"text": "Un corps qui semble réel.", "translation": "Mais n''est qu''apparent."}, "id": "eg.l47.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e13', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.nestorianisme']::text[], 'fill_blank', 'lesson', 'Après Nestorius, qui sépare, l''erreur inverse est celle d''___, qui mélange.', array['Eutychès']::text[], 'L''erreur inverse de Nestorius est celle d''Eutychès (cartes 4 et 5).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.nestorianisme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Après Nestorius, qui sépare, l''erreur inverse est celle d''___, qui mélange.", "options": ["Eutychès", "Arius", "Marcion"], "answer": "Eutychès", "acceptedAnswers": ["Eutychès"], "explanation": "L''erreur inverse de Nestorius est celle d''Eutychès (cartes 4 et 5).", "tip": "Sépare, puis mélange.", "extraExample": {"text": "Eutychès se réclame de Cyrille.", "translation": "Mais il va trop loin."}, "id": "eg.l47.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e14', 'eg', 'eg.l47', 'eg.v.synode_de_constantinople_448', array['eg.v.synode_de_constantinople_448','eg.g47.heresies_christ']::text[], 'fill_blank', 'lesson', 'Le synode de Constantinople de ___ condamne Eutychès.', array['448']::text[], 'Le synode local de 448, sous Flavien, condamne Eutychès (carte 5). Ne le confonds pas avec le concile de 381.', 3, '{"unitIds": ["eg.v.synode_de_constantinople_448", "eg.g47.heresies_christ"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Le synode de Constantinople de ___ condamne Eutychès.", "options": ["448", "381", "451"], "answer": "448", "acceptedAnswers": ["448"], "explanation": "Le synode local de 448, sous Flavien, condamne Eutychès (carte 5). Ne le confonds pas avec le concile de 381.", "tip": "448 = Eutychès ; 381 = Apollinaire.", "extraExample": {"text": "Flavien l''excommunie.", "translation": "Eutychès fait appel à l''empereur."}, "errorPatterns": [{"equals": "381", "category": "word_confusion", "feedback": "Le concile de 381 condamne Apollinaire et Macédonius, pas Eutychès."}], "id": "eg.l47.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e15', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.pleine_humanite']::text[], 'fill_blank', 'lesson', 'Le Christ a une pleine ___ : il est vraiment homme, avec corps et âme.', array['humanité']::text[], 'La pleine humanité du Christ s''oppose aux docètes, à Apollinaire et à Eutychès (cartes 1 à 5).', 2, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.pleine_humanite"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le Christ a une pleine ___ : il est vraiment homme, avec corps et âme.", "options": ["humanité", "divinité", "nature"], "answer": "humanité", "acceptedAnswers": ["humanité"], "explanation": "La pleine humanité du Christ s''oppose aux docètes, à Apollinaire et à Eutychès (cartes 1 à 5).", "tip": "Pleine humanité, pleine divinité.", "extraExample": {"text": "Il prend ce qu''il veut sauver.", "translation": "L''homme tout entier."}, "id": "eg.l47.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e16', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ']::text[], 'match', 'lesson', 'Quelle erreur, quelle idée ?', '{}'::text[], 'Quatre erreurs, quatre façons de défaire l''unité ou l''humanité du Christ (cartes 2 à 5).', 3, '{"unitIds": ["eg.g47.heresies_christ"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle erreur, quelle idée ?", "pairs": [{"left": "le docétisme", "right": "un corps apparent"}, {"left": "l''apollinarisme", "right": "pas d''âme humaine"}, {"left": "le nestorianisme", "right": "le Verbe séparé de l''homme"}, {"left": "le monophysisme", "right": "l''humanité absorbée"}], "answer": "le docétisme = un corps apparent ; l''apollinarisme = pas d''âme humaine ; le nestorianisme = le Verbe séparé de l''homme ; le monophysisme = l''humanité absorbée", "acceptedAnswers": [], "explanation": "Quatre erreurs, quatre façons de défaire l''unité ou l''humanité du Christ (cartes 2 à 5).", "tip": "Apparent, sans âme, séparé, absorbé.", "id": "eg.l47.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e17', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ']::text[], 'match', 'lesson', 'Qui défend la foi contre quelle erreur ?', '{}'::text[], 'Chaque erreur a son défenseur (cartes 2 à 5).', 3, '{"unitIds": ["eg.g47.heresies_christ"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui défend la foi contre quelle erreur ?", "pairs": [{"left": "le docétisme", "right": "saint Jean"}, {"left": "l''apollinarisme", "right": "le pape Timothée"}, {"left": "le nestorianisme", "right": "saint Cyrille"}, {"left": "le monophysisme", "right": "Flavien"}], "answer": "le docétisme = saint Jean ; l''apollinarisme = le pape Timothée ; le nestorianisme = saint Cyrille ; le monophysisme = Flavien", "acceptedAnswers": [], "explanation": "Chaque erreur a son défenseur (cartes 2 à 5).", "tip": "Jean, Timothée, Cyrille, Flavien.", "id": "eg.l47.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e18', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ']::text[], 'reorder', 'lesson', 'Phrase-repère : la foi sur le Christ.', array['Le Christ est pleinement Dieu et pleinement homme']::text[], 'C''est la foi de l''Église face à toutes ces erreurs (carte 1).', 2, '{"unitIds": ["eg.g47.heresies_christ"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la foi sur le Christ.", "tokens": ["homme", "Christ", "Le", "pleinement", "pleinement", "Dieu", "et", "est"], "answer": "Le Christ est pleinement Dieu et pleinement homme", "acceptedAnswers": ["Le Christ est pleinement Dieu et pleinement homme"], "explanation": "C''est la foi de l''Église face à toutes ces erreurs (carte 1).", "tip": "Pleinement Dieu, pleinement homme.", "extraExample": {"text": "Un seul Christ.", "translation": "Ni séparé ni mélangé."}, "id": "eg.l47.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e19', 'eg', 'eg.l47', 'eg.v.physis', array['eg.v.physis','eg.g47.heresies_christ']::text[], 'free_answer', 'lesson', 'Quel terme grec veut dire « nature » ?', array['physis','la physis']::text[], 'Physis veut dire nature : monophysisme, miaphysisme, dyophysisme (carte 6).', 2, '{"unitIds": ["eg.v.physis", "eg.g47.heresies_christ"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel terme grec veut dire « nature » ?", "answer": "physis", "acceptedAnswers": ["physis", "la physis"], "explanation": "Physis veut dire nature : monophysisme, miaphysisme, dyophysisme (carte 6).", "tip": "Physis = nature.", "extraExample": {"text": "Mono, mia, dyo.", "translation": "Un, unie, deux."}, "id": "eg.l47.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e20', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.miaphysisme']::text[], 'free_answer', 'lesson', 'Les coptes sont-ils monophysites ou miaphysites ?', array['miaphysites','miaphysite','ils sont miaphysites','les coptes sont miaphysites']::text[], 'Les coptes sont miaphysites, comme Cyrille. Ils condamnent le monophysisme d''Eutychès (cartes 5 et 6).', 3, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.miaphysisme"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Les coptes sont-ils monophysites ou miaphysites ?", "answer": "miaphysites", "acceptedAnswers": ["miaphysites", "miaphysite", "ils sont miaphysites", "les coptes sont miaphysites"], "explanation": "Les coptes sont miaphysites, comme Cyrille. Ils condamnent le monophysisme d''Eutychès (cartes 5 et 6).", "tip": "Mia, pas mono.", "extraExample": {"text": "Mia veut dire une seule, unie.", "translation": "Mono veut dire un seul."}, "errorPatterns": [{"equals": "monophysites", "category": "word_confusion", "feedback": "Le monophysisme est celui d''Eutychès. L''Église copte est miaphysite."}], "id": "eg.l47.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l47.e21', 'eg', 'eg.l47', 'eg.g47.heresies_christ', array['eg.g47.heresies_christ','eg.v.eutychianisme']::text[], 'free_answer', 'lesson', 'Quel autre nom donne-t-on au monophysisme d''Eutychès ?', array['l''eutychianisme','eutychianisme']::text[], 'On dit eutychianisme ou monophysisme pour la même erreur (carte 5).', 3, '{"unitIds": ["eg.g47.heresies_christ", "eg.v.eutychianisme"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel autre nom donne-t-on au monophysisme d''Eutychès ?", "answer": "l''eutychianisme", "acceptedAnswers": ["l''eutychianisme", "eutychianisme"], "explanation": "On dit eutychianisme ou monophysisme pour la même erreur (carte 5).", "tip": "Eutychès → eutychianisme.", "extraExample": {"text": "Le nom vient d''Eutychès.", "translation": "Comme nestorianisme vient de Nestorius."}, "id": "eg.l47.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l47", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e01', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.fiche_de_concile']::text[], 'mcq', 'lesson', 'Que contient la « fiche » d''un concile ?', array['qui convoque, où, quand, combien d''évêques, contre quelle erreur']::text[], 'La fiche pose toujours les mêmes questions (carte 1) : cela évite les confusions.', 2, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.fiche_de_concile"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que contient la « fiche » d''un concile ?", "options": ["qui convoque, où, quand, combien d''évêques, contre quelle erreur", "seulement la date", "la liste des fêtes de l''année", "le menu des évêques"], "answer": "qui convoque, où, quand, combien d''évêques, contre quelle erreur", "acceptedAnswers": ["qui convoque, où, quand, combien d''évêques, contre quelle erreur"], "explanation": "La fiche pose toujours les mêmes questions (carte 1) : cela évite les confusions.", "tip": "Même grille pour tous.", "extraExample": {"text": "La fiche de Chalcédoine : Marcien, 451.", "translation": "Mêmes questions."}, "id": "eg.l48.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e02', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.concile_de_nicee']::text[], 'mcq', 'lesson', 'Quel empereur convoque le concile de Nicée ?', array['Constantin']::text[], 'Constantin convoque Nicée en 325 pour rétablir l''unité de l''empire (carte 2).', 1, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.concile_de_nicee"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur convoque le concile de Nicée ?", "options": ["Constantin", "Théodose Ier", "Théodose II", "Marcien"], "answer": "Constantin", "acceptedAnswers": ["Constantin"], "explanation": "Constantin convoque Nicée en 325 pour rétablir l''unité de l''empire (carte 2).", "tip": "Nicée = Constantin.", "extraExample": {"text": "Il veut un empire uni.", "translation": "La querelle d''Arius le gêne."}, "id": "eg.l48.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e03', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.nicee']::text[], 'mcq', 'lesson', 'Quelle place Nicée occupe-t-il parmi les conciles œcuméniques ?', array['le premier']::text[], 'Nicée (325) est le premier concile œcuménique (carte 2). Constantinople est le deuxième, Éphèse le troisième.', 1, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.nicee"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle place Nicée occupe-t-il parmi les conciles œcuméniques ?", "options": ["le premier", "le deuxième", "le troisième", "le dernier"], "answer": "le premier", "acceptedAnswers": ["le premier"], "explanation": "Nicée (325) est le premier concile œcuménique (carte 2). Constantinople est le deuxième, Éphèse le troisième.", "tip": "325 est le premier.", "extraExample": {"text": "Constantinople : le deuxième.", "translation": "Éphèse : le troisième."}, "id": "eg.l48.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e04', 'eg', 'eg.l48', 'eg.v.les_318_eveques', array['eg.v.les_318_eveques','eg.g48.fiche_nicee']::text[], 'mcq', 'lesson', 'Selon la tradition, combien d''évêques se retrouvent à Nicée ?', array['318']::text[], 'La tradition parle de 318 évêques (carte 2). Le chiffre 315 est celui des premiers signataires.', 1, '{"unitIds": ["eg.v.les_318_eveques", "eg.g48.fiche_nicee"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Selon la tradition, combien d''évêques se retrouvent à Nicée ?", "options": ["318", "150", "200", "315"], "answer": "318", "acceptedAnswers": ["318"], "explanation": "La tradition parle de 318 évêques (carte 2). Le chiffre 315 est celui des premiers signataires.", "tip": "318 à Nicée.", "extraExample": {"text": "150 à Constantinople.", "translation": "Environ 200 à Éphèse."}, "errorPatterns": [{"equals": "315", "category": "word_confusion", "feedback": "315 est le nombre d''évêques qui signent d''abord ; il y a 318 évêques en tout."}], "id": "eg.l48.e04", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e05', 'eg', 'eg.l48', 'eg.v.arianisme', array['eg.v.arianisme','eg.g48.fiche_nicee']::text[], 'mcq', 'lesson', 'Quelle hérésie Nicée condamne-t-il ?', array['l''arianisme']::text[], 'Nicée condamne Arius et l''arianisme (carte 2). Nestorius est condamné à Éphèse, Eutychès par Dioscore puis Chalcédoine.', 1, '{"unitIds": ["eg.v.arianisme", "eg.g48.fiche_nicee"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle hérésie Nicée condamne-t-il ?", "options": ["l''arianisme", "le nestorianisme", "le monophysisme", "le gnosticisme"], "answer": "l''arianisme", "acceptedAnswers": ["l''arianisme"], "explanation": "Nicée condamne Arius et l''arianisme (carte 2). Nestorius est condamné à Éphèse, Eutychès par Dioscore puis Chalcédoine.", "tip": "Nicée = Arius.", "extraExample": {"text": "Éphèse = Nestorius.", "translation": "Constantinople = Macédonius."}, "id": "eg.l48.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e06', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.homoousios']::text[], 'mcq', 'lesson', 'Qu''est-ce qui sépare homoousios de homoiousios ?', array['un seul iota']::text[], 'Entre les deux mots grecs, un petit iota change tout : même substance ou substance similaire (carte 3).', 3, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.homoousios"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qui sépare homoousios de homoiousios ?", "options": ["un seul iota", "une seule lettre alpha", "un siècle entier", "un concile"], "answer": "un seul iota", "acceptedAnswers": ["un seul iota"], "explanation": "Entre les deux mots grecs, un petit iota change tout : même substance ou substance similaire (carte 3).", "tip": "Un iota, tout le salut.", "extraExample": {"text": "Même substance : orthodoxe.", "translation": "Substance similaire : semi-arien."}, "id": "eg.l48.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e07', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.presidence_du_concile']::text[], 'mcq', 'lesson', 'Qui préside Nicée, selon la tradition copte ?', array['le pape Alexandre']::text[], 'Le pape Alexandre d''Alexandrie préside, assisté d''Athanase (carte 4).', 3, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.presidence_du_concile"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui préside Nicée, selon la tradition copte ?", "options": ["le pape Alexandre", "Eusèbe de Nicomédie", "Constantin lui-même", "l''évêque de Rome en personne"], "answer": "le pape Alexandre", "acceptedAnswers": ["le pape Alexandre"], "explanation": "Le pape Alexandre d''Alexandrie préside, assisté d''Athanase (carte 4).", "tip": "Alexandre préside.", "extraExample": {"text": "Alexandre est le prédécesseur d''Athanase.", "translation": "Il meurt vers 328."}, "errorPatterns": [{"equals": "l''évêque de Rome en personne", "category": "word_confusion", "feedback": "Rome est représentée par deux prêtres : l''évêque de Rome n''est pas venu."}], "id": "eg.l48.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e08', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.athanase']::text[], 'mcq', 'lesson', 'Quel jeune diacre expose les erreurs d''Arius à Nicée ?', array['Athanase']::text[], 'Athanase, diacre et secrétaire du pape Alexandre, expose les erreurs d''Arius (carte 4).', 2, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.athanase"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel jeune diacre expose les erreurs d''Arius à Nicée ?", "options": ["Athanase", "Cyrille", "Dioscore", "Basile"], "answer": "Athanase", "acceptedAnswers": ["Athanase"], "explanation": "Athanase, diacre et secrétaire du pape Alexandre, expose les erreurs d''Arius (carte 4).", "tip": "Athanase : diacre à Nicée.", "extraExample": {"text": "Il sera le XXe pape.", "translation": "Il est le défenseur de la foi."}, "id": "eg.l48.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e09', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee']::text[], 'mcq', 'lesson', 'Combien d''évêques signent d''abord le credo et les anathèmes ?', array['315']::text[], '315 des 318 évêques signent d''abord (carte 6). Trois refusent les anathèmes, puis cèdent.', 3, '{"unitIds": ["eg.g48.fiche_nicee"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''évêques signent d''abord le credo et les anathèmes ?", "options": ["315", "318", "150", "20"], "answer": "315", "acceptedAnswers": ["315"], "explanation": "315 des 318 évêques signent d''abord (carte 6). Trois refusent les anathèmes, puis cèdent.", "tip": "318 − 3 = 315.", "extraExample": {"text": "Trois refusent.", "translation": "Sous la pression de Constantin."}, "id": "eg.l48.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e10', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.eusebe_de_nicomedie']::text[], 'mcq', 'lesson', 'Lequel de ces évêques refuse d''abord les anathèmes contre Arius ?', array['Eusèbe de Nicomédie']::text[], 'Eusèbe de Nicomédie, avec Théognis et Maris, refuse d''abord de condamner Arius (carte 6).', 3, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.eusebe_de_nicomedie"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Lequel de ces évêques refuse d''abord les anathèmes contre Arius ?", "options": ["Eusèbe de Nicomédie", "Alexandre", "Macaire de Jérusalem", "Eustathe d''Antioche"], "answer": "Eusèbe de Nicomédie", "acceptedAnswers": ["Eusèbe de Nicomédie"], "explanation": "Eusèbe de Nicomédie, avec Théognis et Maris, refuse d''abord de condamner Arius (carte 6).", "tip": "Nicomédie = pro-Arius.", "extraExample": {"text": "Eusèbe de Césarée est l''historien.", "translation": "Ne les confonds pas."}, "id": "eg.l48.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e11', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee']::text[], 'mcq', 'lesson', 'Quel est le nombre de canons de Nicée ?', array['vingt']::text[], 'Nicée établit vingt canons (carte 5). Constantinople en établit sept.', 2, '{"unitIds": ["eg.g48.fiche_nicee"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le nombre de canons de Nicée ?", "options": ["vingt", "sept", "douze", "quarante"], "answer": "vingt", "acceptedAnswers": ["vingt"], "explanation": "Nicée établit vingt canons (carte 5). Constantinople en établit sept.", "tip": "Nicée 20, Constantinople 7.", "extraExample": {"text": "Clergé, discipline, date de Pâques.", "translation": "Des règles, pas la foi."}, "errorPatterns": [{"equals": "sept", "category": "word_confusion", "feedback": "Sept est le nombre de canons de Constantinople (381), pas de Nicée."}], "id": "eg.l48.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e12', 'eg', 'eg.l48', 'eg.v.sur_l_incarnation_du_verbe', array['eg.v.sur_l_incarnation_du_verbe','eg.g48.fiche_nicee']::text[], 'mcq', 'lesson', 'Qui écrit « Sur l''incarnation du Verbe » avant l''âge de vingt ans ?', array['Athanase']::text[], 'Avant l''âge de vingt ans, Athanase écrit ce petit livre qui répond déjà à l''arianisme (rappel du module 4).', 3, '{"unitIds": ["eg.v.sur_l_incarnation_du_verbe", "eg.g48.fiche_nicee"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui écrit « Sur l''incarnation du Verbe » avant l''âge de vingt ans ?", "options": ["Athanase", "Arius", "Alexandre", "Eusèbe de Césarée"], "answer": "Athanase", "acceptedAnswers": ["Athanase"], "explanation": "Avant l''âge de vingt ans, Athanase écrit ce petit livre qui répond déjà à l''arianisme (rappel du module 4).", "tip": "Athanase écrit tôt.", "extraExample": {"text": "Il a été formé auprès d''Antoine.", "translation": "Puis il sert le pape Alexandre."}, "id": "eg.l48.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e13', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.nicee']::text[], 'fill_blank', 'lesson', 'Nicée condamne ___, prêtre d''Alexandrie.', array['Arius']::text[], 'Arius est excommunié à Nicée (cartes 2 et 5).', 1, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.nicee"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Nicée condamne ___, prêtre d''Alexandrie.", "options": ["Arius", "Nestorius", "Eutychès"], "answer": "Arius", "acceptedAnswers": ["Arius"], "explanation": "Arius est excommunié à Nicée (cartes 2 et 5).", "tip": "Nicée = Arius.", "extraExample": {"text": "Nestorius est condamné à Éphèse.", "translation": "Eutychès au Ve siècle."}, "id": "eg.l48.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e14', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.credo_de_nicee']::text[], 'fill_blank', 'lesson', 'Le credo de Nicée affirme que le Fils est de même ___ que le Père.', array['substance']::text[], 'Homoousios : de même substance que le Père (carte 3).', 2, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.credo_de_nicee"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le credo de Nicée affirme que le Fils est de même ___ que le Père.", "options": ["substance", "âge", "nom"], "answer": "substance", "acceptedAnswers": ["substance"], "explanation": "Homoousios : de même substance que le Père (carte 3).", "tip": "Même substance.", "extraExample": {"text": "Consubstantiel veut dire de même substance.", "translation": "Le Fils est Dieu."}, "id": "eg.l48.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e15', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.legat']::text[], 'fill_blank', 'lesson', 'Un ___ est un envoyé qui parle au nom d''un évêque absent.', array['légat']::text[], 'Rome, à Nicée, est représentée par deux prêtres qui sont des légats (carte 2).', 3, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.legat"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Un ___ est un envoyé qui parle au nom d''un évêque absent.", "options": ["légat", "diacre", "archimandrite"], "answer": "légat", "acceptedAnswers": ["légat"], "explanation": "Rome, à Nicée, est représentée par deux prêtres qui sont des légats (carte 2).", "tip": "Légat = envoyé.", "extraExample": {"text": "Les légats de Léon à Chalcédoine.", "translation": "Léon est absent."}, "id": "eg.l48.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e16', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee']::text[], 'match', 'lesson', 'La fiche de Nicée', '{}'::text[], 'Quatre réponses à retenir pour Nicée (carte 2).', 2, '{"unitIds": ["eg.g48.fiche_nicee"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "La fiche de Nicée", "pairs": [{"left": "Convoqué par", "right": "Constantin"}, {"left": "Année", "right": "325"}, {"left": "Évêques (selon la tradition)", "right": "318"}, {"left": "Erreur condamnée", "right": "l''arianisme"}], "answer": "Convoqué par = Constantin ; Année = 325 ; Évêques (selon la tradition) = 318 ; Erreur condamnée = l''arianisme", "acceptedAnswers": [], "explanation": "Quatre réponses à retenir pour Nicée (carte 2).", "tip": "Constantin, 325, 318, Arius.", "id": "eg.l48.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e17', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee']::text[], 'match', 'lesson', 'Les figures de Nicée', '{}'::text[], 'Chaque figure joue son rôle (carte 4).', 3, '{"unitIds": ["eg.g48.fiche_nicee"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les figures de Nicée", "pairs": [{"left": "le pape Alexandre", "right": "préside, selon la tradition copte"}, {"left": "Athanase", "right": "jeune diacre qui expose les erreurs d''Arius"}, {"left": "Eusèbe de Nicomédie", "right": "évêque puissant favorable à Arius"}, {"left": "Eusèbe de Césarée", "right": "père de l''histoire ecclésiastique"}], "answer": "le pape Alexandre = préside, selon la tradition copte ; Athanase = jeune diacre qui expose les erreurs d''Arius ; Eusèbe de Nicomédie = évêque puissant favorable à Arius ; Eusèbe de Césarée = père de l''histoire ecclésiastique", "acceptedAnswers": [], "explanation": "Chaque figure joue son rôle (carte 4).", "tip": "Alexandre, Athanase, deux Eusèbe.", "id": "eg.l48.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e18', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee']::text[], 'reorder', 'lesson', 'Phrase-repère : ce que fait Nicée.', array['Nicée condamne Arius et proclame le Fils consubstantiel au Père']::text[], 'Voilà Nicée en une phrase (cartes 2 et 3).', 2, '{"unitIds": ["eg.g48.fiche_nicee"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : ce que fait Nicée.", "tokens": ["Fils", "consubstantiel", "au", "proclame", "Nicée", "Arius", "Père", "le", "condamne", "et"], "answer": "Nicée condamne Arius et proclame le Fils consubstantiel au Père", "acceptedAnswers": ["Nicée condamne Arius et proclame le Fils consubstantiel au Père"], "explanation": "Voilà Nicée en une phrase (cartes 2 et 3).", "tip": "Nicée = Arius + consubstantiel.", "extraExample": {"text": "Constantinople complète sur l''Esprit.", "translation": "Éphèse sur Marie."}, "id": "eg.l48.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e19', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.nicee']::text[], 'free_answer', 'lesson', 'Quelle ville a donné son nom au premier concile œcuménique ?', array['Nicée','à Nicée','nicee']::text[], 'Le premier concile œcuménique se tient à Nicée en 325 (carte 2).', 1, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.nicee"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quelle ville a donné son nom au premier concile œcuménique ?", "answer": "Nicée", "acceptedAnswers": ["Nicée", "à Nicée", "nicee"], "explanation": "Le premier concile œcuménique se tient à Nicée en 325 (carte 2).", "tip": "Nicée = 325.", "extraExample": {"text": "Nicée donne son nom au credo.", "translation": "Credo de Nicée."}, "id": "eg.l48.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e20', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.athanase']::text[], 'free_answer', 'lesson', 'Quel jeune diacre d''Alexandrie accompagne le pape Alexandre à Nicée ?', array['Athanase','saint Athanase']::text[], 'Athanase, futur XXe pape, expose les erreurs d''Arius (carte 4).', 2, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.athanase"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel jeune diacre d''Alexandrie accompagne le pape Alexandre à Nicée ?", "answer": "Athanase", "acceptedAnswers": ["Athanase", "saint Athanase"], "explanation": "Athanase, futur XXe pape, expose les erreurs d''Arius (carte 4).", "tip": "Athanase = Nicée.", "extraExample": {"text": "Il est le défenseur de la foi.", "translation": "Il est exilé plusieurs fois."}, "id": "eg.l48.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l48.e21', 'eg', 'eg.l48', 'eg.g48.fiche_nicee', array['eg.g48.fiche_nicee','eg.v.concile_de_nicee']::text[], 'free_answer', 'lesson', 'En quelle année se tient le concile de Nicée ?', array['325']::text[], 'Nicée a lieu en 325 (carte 2).', 1, '{"unitIds": ["eg.g48.fiche_nicee", "eg.v.concile_de_nicee"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "En quelle année se tient le concile de Nicée ?", "answer": "325", "acceptedAnswers": ["325"], "explanation": "Nicée a lieu en 325 (carte 2).", "tip": "325 : trois conciles à environ cinquante ans d''écart.", "extraExample": {"text": "381 : Constantinople.", "translation": "431 : Éphèse."}, "id": "eg.l48.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l48", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e01', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.concile_de_constantinople']::text[], 'mcq', 'lesson', 'Quel empereur convoque le concile de Constantinople de 381 ?', array['Théodose Ier']::text[], 'Théodose Ier, empereur depuis 379, convoque le concile (carte 1).', 1, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.concile_de_constantinople"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur convoque le concile de Constantinople de 381 ?", "options": ["Théodose Ier", "Constantin", "Théodose II", "Marcien"], "answer": "Théodose Ier", "acceptedAnswers": ["Théodose Ier"], "explanation": "Théodose Ier, empereur depuis 379, convoque le concile (carte 1).", "tip": "381 = Théodose Ier.", "extraExample": {"text": "Théodose II convoque Éphèse.", "translation": "Petit-fils du premier."}, "id": "eg.l49.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e02', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.theodose_ier']::text[], 'mcq', 'lesson', 'Combien d''évêques sont réunis à Constantinople en 381 ?', array['150']::text[], '150 évêques se réunissent en 381 (carte 1).', 1, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.theodose_ier"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''évêques sont réunis à Constantinople en 381 ?", "options": ["150", "318", "200", "20"], "answer": "150", "acceptedAnswers": ["150"], "explanation": "150 évêques se réunissent en 381 (carte 1).", "tip": "150 en 381, 318 en 325.", "extraExample": {"text": "Environ 200 à Éphèse.", "translation": "318 à Nicée."}, "errorPatterns": [{"equals": "318", "category": "word_confusion", "feedback": "318 est le nombre d''évêques de Nicée (325)."}], "id": "eg.l49.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e03', 'eg', 'eg.l49', 'eg.v.apollinaire', array['eg.v.apollinaire','eg.g49.fiches_381_431']::text[], 'mcq', 'lesson', 'Quels hommes sont excommuniés à Constantinople en 381 ?', array['Apollinaire et Macédonius']::text[], 'Le concile de 381 excommunie Apollinaire et Macédonius (carte 2).', 2, '{"unitIds": ["eg.v.apollinaire", "eg.g49.fiches_381_431"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quels hommes sont excommuniés à Constantinople en 381 ?", "options": ["Apollinaire et Macédonius", "Arius et Eusèbe", "Nestorius et Eutychès", "Marcion et Montan"], "answer": "Apollinaire et Macédonius", "acceptedAnswers": ["Apollinaire et Macédonius"], "explanation": "Le concile de 381 excommunie Apollinaire et Macédonius (carte 2).", "tip": "381 : Apollinaire + Macédonius.", "extraExample": {"text": "Arius : Nicée.", "translation": "Nestorius : Éphèse."}, "id": "eg.l49.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
