insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e05', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431']::text[], 'mcq', 'lesson', 'Quel est le nombre de canons de Constantinople (381) ?', array['sept']::text[], 'Constantinople établit sept canons (carte 2). Nicée en établit vingt.', 2, '{"unitIds": ["eg.g49.fiches_381_431"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le nombre de canons de Constantinople (381) ?", "options": ["sept", "vingt", "douze", "trois"], "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Constantinople établit sept canons (carte 2). Nicée en établit vingt.", "tip": "Nicée 20, Constantinople 7.", "extraExample": {"text": "Le canon 3 est l''un d''eux.", "translation": "Alexandrie le refuse."}, "id": "eg.l49.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e06', 'eg', 'eg.l49', 'eg.v.canon_3_de_381', array['eg.v.canon_3_de_381','eg.g49.fiches_381_431']::text[], 'mcq', 'lesson', 'Quel canon de 381 Alexandrie refuse-t-elle ?', array['le canon 3']::text[], 'Le canon 3 place Constantinople deuxième après Rome ; Alexandrie le refuse (carte 3). Le canon 28 est celui de Chalcédoine.', 2, '{"unitIds": ["eg.v.canon_3_de_381", "eg.g49.fiches_381_431"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel canon de 381 Alexandrie refuse-t-elle ?", "options": ["le canon 3", "le canon 1", "le canon 7", "le canon 28"], "answer": "le canon 3", "acceptedAnswers": ["le canon 3"], "explanation": "Le canon 3 place Constantinople deuxième après Rome ; Alexandrie le refuse (carte 3). Le canon 28 est celui de Chalcédoine.", "tip": "Canon 3 = 381 ; canon 28 = 451.", "extraExample": {"text": "Le canon 28 répète l''idée.", "translation": "En 451."}, "errorPatterns": [{"equals": "le canon 28", "category": "word_confusion", "feedback": "Le canon 28 appartient à Chalcédoine (451). Celui de 381 est le canon 3."}], "id": "eg.l49.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e07', 'eg', 'eg.l49', 'eg.v.pape_timothee', array['eg.v.pape_timothee','eg.g49.fiches_381_431']::text[], 'mcq', 'lesson', 'Quel pape d''Alexandrie participe au concile de 381 ?', array['Timothée']::text[], 'Le pape Timothée représente Alexandrie à Constantinople (carte 1).', 2, '{"unitIds": ["eg.v.pape_timothee", "eg.g49.fiches_381_431"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape d''Alexandrie participe au concile de 381 ?", "options": ["Timothée", "Cyrille", "Dioscore", "Athanase"], "answer": "Timothée", "acceptedAnswers": ["Timothée"], "explanation": "Le pape Timothée représente Alexandrie à Constantinople (carte 1).", "tip": "Timothée : 381.", "extraExample": {"text": "Athanase est mort en 373.", "translation": "Cyrille vient au Ve siècle."}, "id": "eg.l49.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e08', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.concile_ephese_431']::text[], 'mcq', 'lesson', 'Quel pape d''Alexandrie préside le concile d''Éphèse de 431 ?', array['Cyrille']::text[], 'Cyrille préside Éphèse, avec l''appui de Rome (carte 4).', 1, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.concile_ephese_431"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape d''Alexandrie préside le concile d''Éphèse de 431 ?", "options": ["Cyrille", "Timothée", "Dioscore", "Athanase"], "answer": "Cyrille", "acceptedAnswers": ["Cyrille"], "explanation": "Cyrille préside Éphèse, avec l''appui de Rome (carte 4).", "tip": "Éphèse : Cyrille.", "extraExample": {"text": "Dioscore préside Éphèse II.", "translation": "En 449."}, "id": "eg.l49.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e09', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.ephese']::text[], 'mcq', 'lesson', 'Environ combien d''évêques viennent à Éphèse en 431 ?', array['deux cents']::text[], 'Environ deux cents évêques viennent à Éphèse (carte 4).', 2, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.ephese"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Environ combien d''évêques viennent à Éphèse en 431 ?", "options": ["deux cents", "cent cinquante", "trois cent dix-huit", "vingt"], "answer": "deux cents", "acceptedAnswers": ["deux cents"], "explanation": "Environ deux cents évêques viennent à Éphèse (carte 4).", "tip": "200 à Éphèse.", "extraExample": {"text": "150 à Constantinople.", "translation": "318 à Nicée."}, "id": "eg.l49.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e10', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.jean_d_antioche']::text[], 'mcq', 'lesson', 'Comment Jean d''Antioche arrive-t-il à Éphèse ?', array['en retard']::text[], 'Jean d''Antioche arrive en retard ; Cyrille ne veut plus attendre (carte 5).', 2, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.jean_d_antioche"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment Jean d''Antioche arrive-t-il à Éphèse ?", "options": ["en retard", "à l''heure", "avant tout le monde", "il ne vient pas"], "answer": "en retard", "acceptedAnswers": ["en retard"], "explanation": "Jean d''Antioche arrive en retard ; Cyrille ne veut plus attendre (carte 5).", "tip": "Retard = concile rival.", "extraExample": {"text": "Il tient ensuite un concile rival.", "translation": "Il dépose Cyrille."}, "id": "eg.l49.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e11', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.interdit_de_changer_le_credo']::text[], 'mcq', 'lesson', 'Que décide Éphèse à propos du credo de Nicée ?', array['il est interdit d''en composer un autre']::text[], 'Éphèse confirme le credo et interdit d''en composer un autre (carte 6). C''est un argument copte contre Chalcédoine.', 3, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.interdit_de_changer_le_credo"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que décide Éphèse à propos du credo de Nicée ?", "options": ["il est interdit d''en composer un autre", "il faut le réécrire", "on le remplace", "on le traduit en copte"], "answer": "il est interdit d''en composer un autre", "acceptedAnswers": ["il est interdit d''en composer un autre"], "explanation": "Éphèse confirme le credo et interdit d''en composer un autre (carte 6). C''est un argument copte contre Chalcédoine.", "tip": "Un seul credo.", "extraExample": {"text": "Chalcédoine ajoute une définition.", "translation": "Pour les coptes, c''est une nouveauté."}, "id": "eg.l49.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e12', 'eg', 'eg.l49', 'eg.v.pelagianisme', array['eg.v.pelagianisme','eg.g49.fiches_381_431']::text[], 'mcq', 'lesson', 'Quelle autre doctrine Éphèse condamne-t-il en 431 ?', array['le pélagianisme']::text[], 'Le concile condamne aussi le pélagianisme : l''homme ne se sauve pas seul (carte 6).', 3, '{"unitIds": ["eg.v.pelagianisme", "eg.g49.fiches_381_431"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle autre doctrine Éphèse condamne-t-il en 431 ?", "options": ["le pélagianisme", "le manichéisme", "le montanisme", "le sabellianisme"], "answer": "le pélagianisme", "acceptedAnswers": ["le pélagianisme"], "explanation": "Le concile condamne aussi le pélagianisme : l''homme ne se sauve pas seul (carte 6).", "tip": "Pélage : sans la grâce.", "extraExample": {"text": "La grâce est nécessaire au salut.", "translation": "Même 431."}, "id": "eg.l49.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e13', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.concile_de_constantinople']::text[], 'fill_blank', 'lesson', 'Le concile de 381 est le ___ concile œcuménique.', array['deuxième']::text[], 'Nicée (325), Constantinople (381), Éphèse (431) : 381 est le deuxième (carte 1).', 1, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.concile_de_constantinople"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le concile de 381 est le ___ concile œcuménique.", "options": ["deuxième", "premier", "troisième"], "answer": "deuxième", "acceptedAnswers": ["deuxième"], "explanation": "Nicée (325), Constantinople (381), Éphèse (431) : 381 est le deuxième (carte 1).", "tip": "325, 381, 431.", "extraExample": {"text": "Éphèse est le troisième.", "translation": "Nicée le premier."}, "id": "eg.l49.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e14', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.theotokos']::text[], 'fill_blank', 'lesson', 'Éphèse proclame que Marie est ___.', array['Théotokos']::text[], 'Théotokos : mère de Dieu. Le titre protège l''identité de Jésus (carte 6).', 1, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.theotokos"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Éphèse proclame que Marie est ___.", "options": ["Théotokos", "Christotokos", "Panagia"], "answer": "Théotokos", "acceptedAnswers": ["Théotokos"], "explanation": "Théotokos : mère de Dieu. Le titre protège l''identité de Jésus (carte 6).", "tip": "Théotokos = mère de Dieu.", "extraExample": {"text": "Christotokos est le titre de Nestorius.", "translation": "Il est rejeté."}, "id": "eg.l49.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e15', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.deposition']::text[], 'fill_blank', 'lesson', 'Le concile prononce la ___ de Nestorius : il perd son siège.', array['déposition']::text[], 'Déposer un évêque, c''est le priver de son siège (carte 6).', 2, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.deposition"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le concile prononce la ___ de Nestorius : il perd son siège.", "options": ["déposition", "présidence", "réception"], "answer": "déposition", "acceptedAnswers": ["déposition"], "explanation": "Déposer un évêque, c''est le priver de son siège (carte 6).", "tip": "Déposition = perte du siège.", "extraExample": {"text": "Flavien est déposé en 449.", "translation": "Dioscore en 451."}, "id": "eg.l49.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e16', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.concile_rival']::text[], 'fill_blank', 'lesson', 'Les évêques d''Orient tiennent un concile ___ et déposent Cyrille.', array['rival']::text[], 'Jean d''Antioche et ses amis tiennent un concile rival (carte 5).', 2, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.concile_rival"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les évêques d''Orient tiennent un concile ___ et déposent Cyrille.", "options": ["rival", "œcuménique", "secret"], "answer": "rival", "acceptedAnswers": ["rival"], "explanation": "Jean d''Antioche et ses amis tiennent un concile rival (carte 5).", "tip": "Rival = contre le concile.", "extraExample": {"text": "L''empereur doit trancher.", "translation": "La paix vient en 433."}, "id": "eg.l49.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e17', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431']::text[], 'match', 'lesson', 'Les figures de 381', '{}'::text[], 'Chaque figure de Constantinople (cartes 1 à 3).', 3, '{"unitIds": ["eg.g49.fiches_381_431"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les figures de 381", "pairs": [{"left": "Timothée", "right": "pape d''Alexandrie présent au concile"}, {"left": "Grégoire le Théologien", "right": "champion de la foi de Nicée"}, {"left": "Cyrille de Jérusalem", "right": "père des catéchumènes"}, {"left": "Macédonius", "right": "dit que l''Esprit est créé"}], "answer": "Timothée = pape d''Alexandrie présent au concile ; Grégoire le Théologien = champion de la foi de Nicée ; Cyrille de Jérusalem = père des catéchumènes ; Macédonius = dit que l''Esprit est créé", "acceptedAnswers": [], "explanation": "Chaque figure de Constantinople (cartes 1 à 3).", "tip": "Timothée, Grégoire, Cyrille, Macédonius.", "id": "eg.l49.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e18', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431']::text[], 'match', 'lesson', 'Les figures d''Éphèse', '{}'::text[], 'Chaque figure d''Éphèse (cartes 4 et 5).', 3, '{"unitIds": ["eg.g49.fiches_381_431"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les figures d''Éphèse", "pairs": [{"left": "Cyrille", "right": "préside le concile"}, {"left": "Nestorius", "right": "refuse de comparaître"}, {"left": "Jean d''Antioche", "right": "arrive en retard"}, {"left": "Célestin Ier", "right": "pape de Rome qui soutient Cyrille"}], "answer": "Cyrille = préside le concile ; Nestorius = refuse de comparaître ; Jean d''Antioche = arrive en retard ; Célestin Ier = pape de Rome qui soutient Cyrille", "acceptedAnswers": [], "explanation": "Chaque figure d''Éphèse (cartes 4 et 5).", "tip": "Cyrille, Nestorius, Jean, Célestin.", "id": "eg.l49.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e19', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431']::text[], 'reorder', 'lesson', 'Phrase-repère : le credo complété.', array['Constantinople complète le credo de Nicée sur le Saint-Esprit']::text[], '381 ajoute la partie sur l''Esprit Saint (carte 2).', 3, '{"unitIds": ["eg.g49.fiches_381_431"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le credo complété.", "tokens": ["le", "sur", "Saint-Esprit", "complète", "de", "Nicée", "Constantinople", "credo", "le"], "answer": "Constantinople complète le credo de Nicée sur le Saint-Esprit", "acceptedAnswers": ["Constantinople complète le credo de Nicée sur le Saint-Esprit"], "explanation": "381 ajoute la partie sur l''Esprit Saint (carte 2).", "tip": "381 = l''Esprit.", "extraExample": {"text": "Éphèse confirme ensuite ce credo.", "translation": "Et interdit d''en composer un autre."}, "id": "eg.l49.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e20', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.theotokos']::text[], 'free_answer', 'lesson', 'Quel titre Éphèse donne-t-il à Marie ?', array['Théotokos','Theotokos','mère de Dieu']::text[], 'Marie est proclamée Théotokos, « mère de Dieu » (carte 6).', 1, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.theotokos"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel titre Éphèse donne-t-il à Marie ?", "answer": "Théotokos", "acceptedAnswers": ["Théotokos", "Theotokos", "mère de Dieu"], "explanation": "Marie est proclamée Théotokos, « mère de Dieu » (carte 6).", "tip": "Théotokos = mère de Dieu.", "extraExample": {"text": "Celle qui enfante Dieu.", "translation": "Le Verbe fait chair."}, "id": "eg.l49.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e21', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.theodose_ier']::text[], 'free_answer', 'lesson', 'Quel empereur convoque le concile de 381 ?', array['Théodose Ier','Theodose Ier','Théodose 1er','Théodose I']::text[], 'Théodose Ier convoque Constantinople (carte 1).', 2, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.theodose_ier"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel empereur convoque le concile de 381 ?", "answer": "Théodose Ier", "acceptedAnswers": ["Théodose Ier", "Theodose Ier", "Théodose 1er", "Théodose I"], "explanation": "Théodose Ier convoque Constantinople (carte 1).", "tip": "381 = Théodose Ier.", "extraExample": {"text": "Constantin convoque Nicée.", "translation": "Théodose II : Éphèse."}, "id": "eg.l49.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l49.e22', 'eg', 'eg.l49', 'eg.g49.fiches_381_431', array['eg.g49.fiches_381_431','eg.v.nestorius']::text[], 'free_answer', 'lesson', 'Dans quelle région Nestorius est-il exilé ?', array['la Haute-Égypte','Haute-Égypte','haute egypte','en Haute-Égypte','Akhmim']::text[], 'Nestorius est exilé en Haute-Égypte, où il meurt (carte 6).', 2, '{"unitIds": ["eg.g49.fiches_381_431", "eg.v.nestorius"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Dans quelle région Nestorius est-il exilé ?", "answer": "la Haute-Égypte", "acceptedAnswers": ["la Haute-Égypte", "Haute-Égypte", "haute egypte", "en Haute-Égypte", "Akhmim"], "explanation": "Nestorius est exilé en Haute-Égypte, où il meurt (carte 6).", "tip": "Exilé en Égypte, terre de Cyrille.", "extraExample": {"text": "Son exil est en Haute-Égypte.", "translation": "C''est ironique."}, "id": "eg.l49.e22", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l49", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e01', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.concile_ephese_449']::text[], 'mcq', 'lesson', 'Quel empereur convoque le deuxième concile d''Éphèse ?', array['Théodose II']::text[], 'Théodose II convoque Éphèse II pour le 1er août 449 (carte 1). Marcien convoque Chalcédoine.', 1, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.concile_ephese_449"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur convoque le deuxième concile d''Éphèse ?", "options": ["Théodose II", "Marcien", "Constantin", "Théodose Ier"], "answer": "Théodose II", "acceptedAnswers": ["Théodose II"], "explanation": "Théodose II convoque Éphèse II pour le 1er août 449 (carte 1). Marcien convoque Chalcédoine.", "tip": "449 = Théodose II.", "extraExample": {"text": "Marcien convoque 451.", "translation": "Après la mort de Théodose II."}, "id": "eg.l50.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e02', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.dioscore']::text[], 'mcq', 'lesson', 'Qui préside Éphèse II ?', array['Dioscore']::text[], 'Théodose II confie la présidence à Dioscore, 25e pape d''Alexandrie (carte 1).', 1, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.dioscore"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui préside Éphèse II ?", "options": ["Dioscore", "Cyrille", "Flavien", "Léon Ier"], "answer": "Dioscore", "acceptedAnswers": ["Dioscore"], "explanation": "Théodose II confie la présidence à Dioscore, 25e pape d''Alexandrie (carte 1).", "tip": "Cyrille : 431 ; Dioscore : 449.", "extraExample": {"text": "Cyrille préside Éphèse I.", "translation": "Léon n''est pas venu."}, "errorPatterns": [{"equals": "Cyrille", "category": "word_confusion", "feedback": "Cyrille préside Éphèse I (431). Éphèse II (449) est présidé par Dioscore, son successeur."}], "id": "eg.l50.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e03', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.ephese_i_et_ii']::text[], 'mcq', 'lesson', 'Quelle est la date d''Éphèse II ?', array['449']::text[], 'Éphèse II se tient en 449. Éphèse I est de 431 (carte 1). 448 est le synode de Constantinople.', 2, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.ephese_i_et_ii"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la date d''Éphèse II ?", "options": ["449", "431", "451", "448"], "answer": "449", "acceptedAnswers": ["449"], "explanation": "Éphèse II se tient en 449. Éphèse I est de 431 (carte 1). 448 est le synode de Constantinople.", "tip": "431 ≠ 449.", "extraExample": {"text": "451 : Chalcédoine.", "translation": "448 : le synode contre Eutychès."}, "errorPatterns": [{"equals": "431", "category": "word_confusion", "feedback": "431 est Éphèse I, le troisième concile œcuménique, qui condamne Nestorius."}], "id": "eg.l50.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e04', 'eg', 'eg.l50', 'eg.v.leon_ier', array['eg.v.leon_ier','eg.g50.fiches_449_451']::text[], 'mcq', 'lesson', 'Quel pape de Rome envoie des légats et le Tome à Éphèse II ?', array['Léon Ier']::text[], 'Léon Ier envoie des légats avec le Tome de Léon (carte 1).', 2, '{"unitIds": ["eg.v.leon_ier", "eg.g50.fiches_449_451"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pape de Rome envoie des légats et le Tome à Éphèse II ?", "options": ["Léon Ier", "Célestin Ier", "Sylvestre", "Timothée"], "answer": "Léon Ier", "acceptedAnswers": ["Léon Ier"], "explanation": "Léon Ier envoie des légats avec le Tome de Léon (carte 1).", "tip": "Léon, Tome.", "extraExample": {"text": "Célestin soutient Cyrille en 430.", "translation": "Sylvestre est à Nicée."}, "id": "eg.l50.e04", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e05', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.tome_de_leon']::text[], 'mcq', 'lesson', 'Pour quelle raison le Tome de Léon reste-t-il non lu à Éphèse II ?', array['faute de temps']::text[], 'Selon la tradition copte, la séance se clôt sans le Tome, faute de temps (carte 2).', 3, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.tome_de_leon"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pour quelle raison le Tome de Léon reste-t-il non lu à Éphèse II ?", "options": ["faute de temps", "il est brûlé", "Dioscore le refuse par décret", "l''empereur l''interdit"], "answer": "faute de temps", "acceptedAnswers": ["faute de temps"], "explanation": "Selon la tradition copte, la séance se clôt sans le Tome, faute de temps (carte 2).", "tip": "Faute de temps, pas par refus.", "extraExample": {"text": "On lit d''abord les lettres de l''empereur.", "translation": "Puis la séance finit."}, "id": "eg.l50.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e06', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.brigandage_d_ephese']::text[], 'mcq', 'lesson', 'Comment Léon Ier surnomme-t-il Éphèse II ?', array['le brigandage d''Éphèse']::text[], 'Furieux, Léon appelle ce concile le brigandage d''Éphèse (carte 2).', 2, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.brigandage_d_ephese"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment Léon Ier surnomme-t-il Éphèse II ?", "options": ["le brigandage d''Éphèse", "le concile de la paix", "le credo d''Éphèse", "la formule d''union"], "answer": "le brigandage d''Éphèse", "acceptedAnswers": ["le brigandage d''Éphèse"], "explanation": "Furieux, Léon appelle ce concile le brigandage d''Éphèse (carte 2).", "tip": "Brigandage = nom donné par Léon.", "extraExample": {"text": "L''Église copte conteste ce jugement.", "translation": "Dioscore reste vénéré."}, "id": "eg.l50.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e07', 'eg', 'eg.l50', 'eg.v.flavien', array['eg.v.flavien','eg.g50.fiches_449_451']::text[], 'mcq', 'lesson', 'Quel évêque Dioscore dépose-t-il à Éphèse II ?', array['Flavien']::text[], 'Dioscore dépose Flavien, patriarche de Constantinople (carte 2). Nestorius a été déposé en 431.', 2, '{"unitIds": ["eg.v.flavien", "eg.g50.fiches_449_451"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel évêque Dioscore dépose-t-il à Éphèse II ?", "options": ["Flavien", "Nestorius", "Cyrille", "Eutychès"], "answer": "Flavien", "acceptedAnswers": ["Flavien"], "explanation": "Dioscore dépose Flavien, patriarche de Constantinople (carte 2). Nestorius a été déposé en 431.", "tip": "449 : Flavien ; 431 : Nestorius.", "extraExample": {"text": "Eutychès est réhabilité.", "translation": "Flavien l''avait condamné."}, "id": "eg.l50.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e08', 'eg', 'eg.l50', 'eg.v.marcien', array['eg.v.marcien','eg.g50.fiches_449_451']::text[], 'mcq', 'lesson', 'Quel empereur réunit les évêques à Chalcédoine ?', array['Marcien']::text[], 'Marcien, époux de Pulchérie, convoque Chalcédoine en 451 (carte 5).', 1, '{"unitIds": ["eg.v.marcien", "eg.g50.fiches_449_451"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel empereur réunit les évêques à Chalcédoine ?", "options": ["Marcien", "Théodose II", "Constantin", "Zénon"], "answer": "Marcien", "acceptedAnswers": ["Marcien"], "explanation": "Marcien, époux de Pulchérie, convoque Chalcédoine en 451 (carte 5).", "tip": "451 = Marcien.", "extraExample": {"text": "Zénon publie l''Hénotikon en 482.", "translation": "Plus tard."}, "id": "eg.l50.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e09', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.definition_de_chalcedoine']::text[], 'mcq', 'lesson', 'Que dit la définition de Chalcédoine ?', array['un seul Christ en deux natures']::text[], 'La définition parle de deux natures, sans confusion ni séparation (carte 6). « Une seule nature du Verbe incarné » est la formule de Cyrille.', 2, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.definition_de_chalcedoine"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit la définition de Chalcédoine ?", "options": ["un seul Christ en deux natures", "une seule nature du Verbe incarné", "le Christ est une créature", "la nature divine absorbe l''humanité"], "answer": "un seul Christ en deux natures", "acceptedAnswers": ["un seul Christ en deux natures"], "explanation": "La définition parle de deux natures, sans confusion ni séparation (carte 6). « Une seule nature du Verbe incarné » est la formule de Cyrille.", "tip": "Chalcédoine = deux natures ; Cyrille = une nature du Verbe incarné.", "extraExample": {"text": "Les coptes y voient du nestorianisme.", "translation": "Les mots diffèrent."}, "errorPatterns": [{"equals": "une seule nature du Verbe incarné", "category": "word_confusion", "feedback": "C''est la formule de Cyrille, miaphysite. Chalcédoine parle de deux natures."}], "id": "eg.l50.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e10', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.canon_28']::text[], 'mcq', 'lesson', 'Quelle place le canon 28 de Chalcédoine donne-t-il à Constantinople ?', array['la seconde place, juste après Rome']::text[], 'Le canon 28 donne à Constantinople la seconde place, juste après Rome (carte 6). Léon le refuse ; Alexandrie perd un rang.', 3, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.canon_28"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle place le canon 28 de Chalcédoine donne-t-il à Constantinople ?", "options": ["la seconde place, juste après Rome", "la première place, avant Rome", "la dernière place", "aucune place"], "answer": "la seconde place, juste après Rome", "acceptedAnswers": ["la seconde place, juste après Rome"], "explanation": "Le canon 28 donne à Constantinople la seconde place, juste après Rome (carte 6). Léon le refuse ; Alexandrie perd un rang.", "tip": "Canon 3 : 381 ; canon 28 : 451.", "extraExample": {"text": "C''est la suite du canon 3.", "translation": "Alexandrie recule d''un rang."}, "id": "eg.l50.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e11', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.actes_du_concile']::text[], 'mcq', 'lesson', 'Selon les actes de Chalcédoine, pourquoi Dioscore est-il déposé ?', array['pour sa conduite']::text[], 'Les actes parlent de fautes de conduite et d''un refus de comparaître, non d''hérésie (carte 6).', 3, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.actes_du_concile"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Selon les actes de Chalcédoine, pourquoi Dioscore est-il déposé ?", "options": ["pour sa conduite", "pour hérésie", "pour avoir présidé Nicée", "pour avoir converti l''empereur"], "answer": "pour sa conduite", "acceptedAnswers": ["pour sa conduite"], "explanation": "Les actes parlent de fautes de conduite et d''un refus de comparaître, non d''hérésie (carte 6).", "tip": "Conduite, pas hérésie.", "extraExample": {"text": "L''Église copte le rappelle volontiers.", "translation": "Il est confesseur."}, "errorPatterns": [{"equals": "pour hérésie", "category": "word_confusion", "feedback": "Selon les actes, Dioscore est déposé pour sa conduite, non pour une hérésie."}], "id": "eg.l50.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e12', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.annulation_d_un_concile']::text[], 'mcq', 'lesson', 'Que demande Léon Ier à l''empereur Marcien en 450 ?', array['l''annulation d''Éphèse II']::text[], 'Léon veut un concile qui annule Éphèse II (carte 4).', 3, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.annulation_d_un_concile"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que demande Léon Ier à l''empereur Marcien en 450 ?", "options": ["l''annulation d''Éphèse II", "la fin du credo", "la fondation d''Alexandrie", "l''exil de Cyrille"], "answer": "l''annulation d''Éphèse II", "acceptedAnswers": ["l''annulation d''Éphèse II"], "explanation": "Léon veut un concile qui annule Éphèse II (carte 4).", "tip": "Annulation = casser.", "extraExample": {"text": "Marcien convoque Chalcédoine.", "translation": "En 451."}, "id": "eg.l50.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e13', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.concile_ephese_449']::text[], 'fill_blank', 'lesson', 'À Éphèse II, Dioscore ___ Eutychès après sa confession qui cite Cyrille.', array['réhabilite']::text[], 'Dioscore réhabilite Eutychès à partir de sa confession (carte 2).', 2, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.concile_ephese_449"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "À Éphèse II, Dioscore ___ Eutychès après sa confession qui cite Cyrille.", "options": ["réhabilite", "condamne", "exile"], "answer": "réhabilite", "acceptedAnswers": ["réhabilite"], "explanation": "Dioscore réhabilite Eutychès à partir de sa confession (carte 2).", "tip": "Réhabiliter = rendre la communion.", "extraExample": {"text": "Flavien l''avait condamné en 448.", "translation": "Il est déposé."}, "id": "eg.l50.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e14', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.concile_chalcedoine']::text[], 'fill_blank', 'lesson', 'Chalcédoine ratifie le ___ de Léon.', array['Tome']::text[], 'Le Tome de Léon est lu et ratifié à Chalcédoine (carte 6).', 2, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.concile_chalcedoine"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Chalcédoine ratifie le ___ de Léon.", "options": ["Tome", "Credo", "Canon"], "answer": "Tome", "acceptedAnswers": ["Tome"], "explanation": "Le Tome de Léon est lu et ratifié à Chalcédoine (carte 6).", "tip": "Éphèse II ne l''a pas lu.", "extraExample": {"text": "Il parle de deux natures.", "translation": "Les coptes le refusent."}, "id": "eg.l50.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e15', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.eutyches']::text[], 'fill_blank', 'lesson', 'À Chalcédoine, Eutychès est ___.', array['anathématisé']::text[], 'Chalcédoine anathématise Eutychès : l''Église copte le condamne aussi (carte 6).', 2, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.eutyches"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "À Chalcédoine, Eutychès est ___.", "options": ["anathématisé", "réhabilité", "nommé évêque"], "answer": "anathématisé", "acceptedAnswers": ["anathématisé"], "explanation": "Chalcédoine anathématise Eutychès : l''Église copte le condamne aussi (carte 6).", "tip": "Eutychès condamné en 448 et en 451.", "extraExample": {"text": "Dioscore ne le défend pas pour son erreur.", "translation": "Il le défend sur sa confession."}, "id": "eg.l50.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e16', 'eg', 'eg.l50', 'eg.v.legat', array['eg.v.legat','eg.g50.fiches_449_451']::text[], 'fill_blank', 'lesson', 'Léon Ier est absent à Chalcédoine : ses ___ le représentent.', array['légats']::text[], 'Léon est représenté par ses légats (carte 5).', 2, '{"unitIds": ["eg.v.legat", "eg.g50.fiches_449_451"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Léon Ier est absent à Chalcédoine : ses ___ le représentent.", "options": ["légats", "diacres", "moines"], "answer": "légats", "acceptedAnswers": ["légats"], "explanation": "Léon est représenté par ses légats (carte 5).", "tip": "Légat = envoyé.", "extraExample": {"text": "Rome, à Nicée, envoie deux prêtres.", "translation": "Même principe."}, "id": "eg.l50.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e17', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.nestorianisme']::text[], 'fill_blank', 'lesson', 'Pour les coptes, la formule « deux natures » ressemble au ___.', array['nestorianisme']::text[], 'Les coptes y voient une formule qui sépare ce que Cyrille a uni (carte 7).', 3, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.nestorianisme"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Pour les coptes, la formule « deux natures » ressemble au ___.", "options": ["nestorianisme", "monophysisme", "arianisme"], "answer": "nestorianisme", "acceptedAnswers": ["nestorianisme"], "explanation": "Les coptes y voient une formule qui sépare ce que Cyrille a uni (carte 7).", "tip": "Deux natures séparées = Nestorius.", "extraExample": {"text": "Eutychès mélange.", "translation": "Les coptes le condamnent aussi."}, "id": "eg.l50.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e18', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451']::text[], 'match', 'lesson', 'Trois conciles, trois présidents ou convocateurs', '{}'::text[], 'Éphèse I, Éphèse II et Chalcédoine ont des figures différentes (cartes 1 à 6).', 3, '{"unitIds": ["eg.g50.fiches_449_451"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Trois conciles, trois présidents ou convocateurs", "pairs": [{"left": "le concile d''Éphèse (431)", "right": "Cyrille préside ; Nestorius est déposé"}, {"left": "le deuxième concile d''Éphèse (449)", "right": "Dioscore préside ; Flavien est déposé"}, {"left": "le concile de Chalcédoine (451)", "right": "Marcien convoque ; Dioscore est déposé"}], "answer": "le concile d''Éphèse (431) = Cyrille préside ; Nestorius est déposé ; le deuxième concile d''Éphèse (449) = Dioscore préside ; Flavien est déposé ; le concile de Chalcédoine (451) = Marcien convoque ; Dioscore est déposé", "acceptedAnswers": [], "explanation": "Éphèse I, Éphèse II et Chalcédoine ont des figures différentes (cartes 1 à 6).", "tip": "431 Cyrille, 449 Dioscore, 451 Marcien.", "id": "eg.l50.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e19', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451']::text[], 'match', 'lesson', 'Les figures de 449-451', '{}'::text[], 'Chacun joue son rôle (cartes 1 à 6).', 3, '{"unitIds": ["eg.g50.fiches_449_451"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les figures de 449-451", "pairs": [{"left": "Pulchérie", "right": "épouse Marcien"}, {"left": "Léon Ier", "right": "auteur du Tome"}, {"left": "Flavien", "right": "patriarche de Constantinople, déposé en 449"}, {"left": "Dioscore", "right": "exilé à Gangra"}], "answer": "Pulchérie = épouse Marcien ; Léon Ier = auteur du Tome ; Flavien = patriarche de Constantinople, déposé en 449 ; Dioscore = exilé à Gangra", "acceptedAnswers": [], "explanation": "Chacun joue son rôle (cartes 1 à 6).", "tip": "Pulchérie, Léon, Flavien, Dioscore.", "id": "eg.l50.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e20', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451']::text[], 'reorder', 'lesson', 'Phrase-repère : ce que définit Chalcédoine.', array['Chalcédoine définit un seul Christ en deux natures']::text[], 'C''est la définition de Chalcédoine (carte 6) ; les coptes confessent une seule nature du Verbe incarné.', 3, '{"unitIds": ["eg.g50.fiches_449_451"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : ce que définit Chalcédoine.", "tokens": ["seul", "Christ", "natures", "un", "deux", "en", "Chalcédoine", "définit"], "answer": "Chalcédoine définit un seul Christ en deux natures", "acceptedAnswers": ["Chalcédoine définit un seul Christ en deux natures"], "explanation": "C''est la définition de Chalcédoine (carte 6) ; les coptes confessent une seule nature du Verbe incarné.", "tip": "Chalcédoine = deux natures.", "extraExample": {"text": "Cyrille : une nature du Verbe incarné.", "translation": "Les mots diffèrent."}, "id": "eg.l50.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e21', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.gangra']::text[], 'free_answer', 'lesson', 'Dans quelle ville Dioscore est-il exilé ?', array['Gangra','à Gangra']::text[], 'L''empereur Marcien exile Dioscore à Gangra, en Asie Mineure, où il meurt en 454 (carte 6).', 2, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.gangra"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Dans quelle ville Dioscore est-il exilé ?", "answer": "Gangra", "acceptedAnswers": ["Gangra", "à Gangra"], "explanation": "L''empereur Marcien exile Dioscore à Gangra, en Asie Mineure, où il meurt en 454 (carte 6).", "tip": "Gangra = exil de Dioscore.", "extraExample": {"text": "Nestorius est exilé en Haute-Égypte.", "translation": "Chacun son exil."}, "id": "eg.l50.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e22', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.tome_de_leon']::text[], 'free_answer', 'lesson', 'Comment s''appelle la lettre de Léon Ier sur les deux natures, ratifiée à Chalcédoine ?', array['le Tome de Léon','Tome de Léon','le Tome','tome de leon']::text[], 'Le Tome de Léon est la lettre dogmatique de Léon Ier (cartes 1 et 6).', 3, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.tome_de_leon"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle la lettre de Léon Ier sur les deux natures, ratifiée à Chalcédoine ?", "answer": "le Tome de Léon", "acceptedAnswers": ["le Tome de Léon", "Tome de Léon", "le Tome", "tome de leon"], "explanation": "Le Tome de Léon est la lettre dogmatique de Léon Ier (cartes 1 et 6).", "tip": "Tome = lettre dogmatique.", "extraExample": {"text": "Éphèse II ne l''a pas lu.", "translation": "Chalcédoine l''a ratifié."}, "id": "eg.l50.e22", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l50.e23', 'eg', 'eg.l50', 'eg.g50.fiches_449_451', array['eg.g50.fiches_449_451','eg.v.concile_chalcedoine']::text[], 'free_answer', 'lesson', 'Quelle est l''année du concile de Chalcédoine ?', array['451']::text[], 'Chalcédoine se tient en octobre 451 (carte 5).', 1, '{"unitIds": ["eg.g50.fiches_449_451", "eg.v.concile_chalcedoine"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quelle est l''année du concile de Chalcédoine ?", "answer": "451", "acceptedAnswers": ["451"], "explanation": "Chalcédoine se tient en octobre 451 (carte 5).", "tip": "451 = premier schisme.", "extraExample": {"text": "449 : Éphèse II.", "translation": "431 : Éphèse I."}, "id": "eg.l50.e23", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l50", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e01', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.gnosticisme']::text[], 'mcq', 'lesson', 'Laquelle de ces hérésies est la plus ancienne ?', array['le gnosticisme']::text[], 'Le gnosticisme apparaît dès les Ier et IIe siècles (carte 1). L''arianisme date du IVe, le nestorianisme et le monophysisme du Ve.', 1, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.gnosticisme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Laquelle de ces hérésies est la plus ancienne ?", "options": ["le gnosticisme", "l''arianisme", "le nestorianisme", "le monophysisme"], "answer": "le gnosticisme", "acceptedAnswers": ["le gnosticisme"], "explanation": "Le gnosticisme apparaît dès les Ier et IIe siècles (carte 1). L''arianisme date du IVe, le nestorianisme et le monophysisme du Ve.", "tip": "Gnose : Ier-IIe siècle.", "extraExample": {"text": "Arius : IVe siècle.", "translation": "Nestorius : Ve siècle."}, "id": "eg.l51.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e02', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.macedonius']::text[], 'mcq', 'lesson', 'Quel concile condamne Macédonius ?', array['Constantinople (381)']::text[], 'Constantinople (381) condamne Apollinaire et Macédonius (carte 4).', 2, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.macedonius"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile condamne Macédonius ?", "options": ["Constantinople (381)", "Nicée (325)", "Éphèse (431)", "Chalcédoine (451)"], "answer": "Constantinople (381)", "acceptedAnswers": ["Constantinople (381)"], "explanation": "Constantinople (381) condamne Apollinaire et Macédonius (carte 4).", "tip": "381 = Esprit Saint.", "extraExample": {"text": "Nicée : Arius.", "translation": "Éphèse : Nestorius."}, "id": "eg.l51.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e03', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.cyrille_d_alexandrie']::text[], 'mcq', 'lesson', 'Quel défenseur d''Alexandrie est associé à la condamnation de Nestorius ?', array['Cyrille']::text[], 'Cyrille combat Nestorius et préside Éphèse en 431 (carte 4).', 1, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.cyrille_d_alexandrie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel défenseur d''Alexandrie est associé à la condamnation de Nestorius ?", "options": ["Cyrille", "Athanase", "Timothée", "Denys"], "answer": "Cyrille", "acceptedAnswers": ["Cyrille"], "explanation": "Cyrille combat Nestorius et préside Éphèse en 431 (carte 4).", "tip": "Cyrille = Nestorius.", "extraExample": {"text": "Athanase = Arius.", "translation": "Timothée = 381."}, "id": "eg.l51.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e04', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.monophysisme']::text[], 'mcq', 'lesson', 'Quelle erreur s''oppose à celle de Nestorius ?', array['le monophysisme d''Eutychès']::text[], 'Nestorius sépare, Eutychès mélange : erreurs opposées (carte 5).', 2, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.monophysisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle erreur s''oppose à celle de Nestorius ?", "options": ["le monophysisme d''Eutychès", "l''arianisme", "le sabellianisme", "le docétisme"], "answer": "le monophysisme d''Eutychès", "acceptedAnswers": ["le monophysisme d''Eutychès"], "explanation": "Nestorius sépare, Eutychès mélange : erreurs opposées (carte 5).", "tip": "Sépare / mélange.", "extraExample": {"text": "Cyrille garde l''unité.", "translation": "Sans mélange ni division."}, "id": "eg.l51.e04", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e05', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.modalisme']::text[], 'mcq', 'lesson', 'Quel personnage porte l''erreur inverse de celle de Sabellius ?', array['Paul de Samosate']::text[], 'Paul fait du Christ un homme ; Sabellius confond les personnes : erreurs opposées (carte 5).', 3, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.modalisme"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel personnage porte l''erreur inverse de celle de Sabellius ?", "options": ["Paul de Samosate", "Marcion", "Nestorius", "Apollinaire"], "answer": "Paul de Samosate", "acceptedAnswers": ["Paul de Samosate"], "explanation": "Paul fait du Christ un homme ; Sabellius confond les personnes : erreurs opposées (carte 5).", "tip": "Paul rabaisse, Sabellius confond.", "extraExample": {"text": "Deux pièges sur la Trinité.", "translation": "L''Église évite les deux."}, "id": "eg.l51.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e06', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.novatianisme']::text[], 'mcq', 'lesson', 'Quelle question divise l''Église au temps de Novatien ?', array['le pardon des tombés']::text[], 'Novatien refuse de pardonner aux tombés (carte 7).', 2, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.novatianisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle question divise l''Église au temps de Novatien ?", "options": ["le pardon des tombés", "la divinité du Fils", "la date de Pâques", "les deux natures"], "answer": "le pardon des tombés", "acceptedAnswers": ["le pardon des tombés"], "explanation": "Novatien refuse de pardonner aux tombés (carte 7).", "tip": "Novatien = tombés.", "extraExample": {"text": "Les tombés ont renié sous Dèce.", "translation": "Les vrais pénitents sont reçus."}, "id": "eg.l51.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e07', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.crise_de_discipline']::text[], 'mcq', 'lesson', 'Le novatianisme est avant tout une crise de…', array['discipline']::text[], 'Novatien a une querelle de discipline, sur le pardon des tombés ; elle coupe pourtant l''Église (carte 7).', 3, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.crise_de_discipline"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Le novatianisme est avant tout une crise de…", "options": ["discipline", "foi trinitaire", "calendrier", "langue"], "answer": "discipline", "acceptedAnswers": ["discipline"], "explanation": "Novatien a une querelle de discipline, sur le pardon des tombés ; elle coupe pourtant l''Église (carte 7).", "tip": "Discipline ≠ doctrine.", "extraExample": {"text": "La date de Pâques aussi est une affaire de discipline.", "translation": "Sans rupture."}, "id": "eg.l51.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e08', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.henotikon']::text[], 'mcq', 'lesson', 'L''Hénotikon de Zénon (482) sur la question des natures :', array['interdit de poser la question']::text[], 'L''Hénotikon réaffirme Nicée et Constantinople, condamne Nestorius et Eutychès, mais interdit de poser la question (carte 7). Il ne satisfait personne.', 3, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.henotikon"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "L''Hénotikon de Zénon (482) sur la question des natures :", "options": ["interdit de poser la question", "impose deux natures", "impose une seule nature", "condamne Cyrille"], "answer": "interdit de poser la question", "acceptedAnswers": ["interdit de poser la question"], "explanation": "L''Hénotikon réaffirme Nicée et Constantinople, condamne Nestorius et Eutychès, mais interdit de poser la question (carte 7). Il ne satisfait personne.", "tip": "Hénotikon = silence imposé.", "extraExample": {"text": "Édit d''union de 482.", "translation": "Le schisme demeure."}, "id": "eg.l51.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e09', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.cycle_heresie_concile']::text[], 'mcq', 'lesson', 'Après la réponse d''un concile, que se produit-il souvent ?', array['une erreur dans l''autre sens']::text[], 'La formule de foi peut faire naître l''erreur inverse : Nestorius puis Eutychès (carte 6).', 2, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.cycle_heresie_concile"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Après la réponse d''un concile, que se produit-il souvent ?", "options": ["une erreur dans l''autre sens", "la fin de toutes les hérésies", "un nouveau credo chaque année", "le retour de l''empereur à Rome"], "answer": "une erreur dans l''autre sens", "acceptedAnswers": ["une erreur dans l''autre sens"], "explanation": "La formule de foi peut faire naître l''erreur inverse : Nestorius puis Eutychès (carte 6).", "tip": "Pendule : un excès, puis l''autre.", "extraExample": {"text": "Arius puis le semi-arianisme.", "translation": "Nestorius puis Eutychès."}, "id": "eg.l51.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e10', 'eg', 'eg.l51', 'eg.v.novatien', array['eg.v.novatien','eg.g51.frise_et_liens']::text[], 'mcq', 'lesson', 'En quelle année Novatien est-il excommunié par les conciles de Rome et de Carthage ?', array['251']::text[], 'En 251, Novatien se fait consacrer évêque de Rome et est excommunié (carte 1).', 2, '{"unitIds": ["eg.v.novatien", "eg.g51.frise_et_liens"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Novatien est-il excommunié par les conciles de Rome et de Carthage ?", "options": ["251", "269", "325", "381"], "answer": "251", "acceptedAnswers": ["251"], "explanation": "En 251, Novatien se fait consacrer évêque de Rome et est excommunié (carte 1).", "tip": "251 : tombés.", "extraExample": {"text": "269 : Paul de Samosate.", "translation": "Dèce : 250."}, "id": "eg.l51.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e11', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.concile_oecumenique']::text[], 'fill_blank', 'lesson', 'Nicée en 325, Constantinople en 381, Éphèse en ___.', array['431']::text[], 'Les trois conciles reconnus par l''Église copte : 325, 381, 431 (cartes 1 à 3).', 1, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.concile_oecumenique"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Nicée en 325, Constantinople en 381, Éphèse en ___.", "options": ["431", "449", "451"], "answer": "431", "acceptedAnswers": ["431"], "explanation": "Les trois conciles reconnus par l''Église copte : 325, 381, 431 (cartes 1 à 3).", "tip": "Environ cinquante ans d''écart.", "extraExample": {"text": "449 est Éphèse II.", "translation": "451 est Chalcédoine."}, "errorPatterns": [{"equals": "449", "category": "word_confusion", "feedback": "449 est Éphèse II, qui n''est pas parmi les trois conciles reconnus."}], "id": "eg.l51.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e12', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.concile_d_antioche_269']::text[], 'fill_blank', 'lesson', 'Le synode d''Antioche de 269 condamne Paul de ___.', array['Samosate']::text[], 'Paul de Samosate, évêque d''Antioche, est excommunié en 269 (carte 1).', 2, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.concile_d_antioche_269"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le synode d''Antioche de 269 condamne Paul de ___.", "options": ["Samosate", "Tarse", "Smyrne"], "answer": "Samosate", "acceptedAnswers": ["Samosate"], "explanation": "Paul de Samosate, évêque d''Antioche, est excommunié en 269 (carte 1).", "tip": "Samosate = Paul.", "extraExample": {"text": "Il est protégé par Zénobie.", "translation": "Denys écrit la lettre."}, "id": "eg.l51.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e13', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.henotikon']::text[], 'fill_blank', 'lesson', 'L''Hénotikon est publié en ___ par l''empereur Zénon.', array['482']::text[], 'L''édit d''union de Zénon date de 482 (carte 3).', 2, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.henotikon"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "L''Hénotikon est publié en ___ par l''empereur Zénon.", "options": ["482", "451", "538"], "answer": "482", "acceptedAnswers": ["482"], "explanation": "L''édit d''union de Zénon date de 482 (carte 3).", "tip": "482 = Hénotikon.", "extraExample": {"text": "Justinien : 538.", "translation": "Chalcédoine : 451."}, "id": "eg.l51.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e14', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.frise_chronologique']::text[], 'fill_blank', 'lesson', 'Une ___ chronologique range les événements dans l''ordre du temps.', array['frise']::text[], 'Une frise place les événements sur une ligne du temps (cartes 1 à 3).', 1, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.frise_chronologique"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Une ___ chronologique range les événements dans l''ordre du temps.", "options": ["frise", "canon", "règle"], "answer": "frise", "acceptedAnswers": ["frise"], "explanation": "Une frise place les événements sur une ligne du temps (cartes 1 à 3).", "tip": "Frise = ligne du temps.", "extraExample": {"text": "Elle montre qui répond à quoi.", "translation": "Erreur puis concile."}, "id": "eg.l51.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e15', 'eg', 'eg.l51', 'eg.v.justinien', array['eg.v.justinien','eg.g51.frise_et_liens']::text[], 'fill_blank', 'lesson', 'En 538, ___ nomme le premier patriarche chalcédonien d''Alexandrie.', array['Justinien']::text[], 'Justinien nomme en 538 le premier patriarche chalcédonien d''Alexandrie (carte 3).', 3, '{"unitIds": ["eg.v.justinien", "eg.g51.frise_et_liens"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "En 538, ___ nomme le premier patriarche chalcédonien d''Alexandrie.", "options": ["Justinien", "Zénon", "Marcien"], "answer": "Justinien", "acceptedAnswers": ["Justinien"], "explanation": "Justinien nomme en 538 le premier patriarche chalcédonien d''Alexandrie (carte 3).", "tip": "538 = deux patriarches.", "extraExample": {"text": "Zénon : 482.", "translation": "Marcien : 451."}, "id": "eg.l51.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e16', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens']::text[], 'match', 'lesson', 'Erreur et concile qui y répond', '{}'::text[], 'Chaque erreur de la frise a son concile (cartes 1 à 4).', 3, '{"unitIds": ["eg.g51.frise_et_liens"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Erreur et concile qui y répond", "pairs": [{"left": "Paul de Samosate", "right": "le synode d''Antioche (269)"}, {"left": "Arius", "right": "Nicée (325)"}, {"left": "Macédonius", "right": "Constantinople (381)"}, {"left": "Nestorius", "right": "Éphèse (431)"}, {"left": "Eutychès", "right": "le synode de Constantinople (448)"}], "answer": "Paul de Samosate = le synode d''Antioche (269) ; Arius = Nicée (325) ; Macédonius = Constantinople (381) ; Nestorius = Éphèse (431) ; Eutychès = le synode de Constantinople (448)", "acceptedAnswers": [], "explanation": "Chaque erreur de la frise a son concile (cartes 1 à 4).", "tip": "Un concile par erreur.", "id": "eg.l51.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e17', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens']::text[], 'match', 'lesson', 'Défenseur et cause', '{}'::text[], 'Chacun défend la foi à son époque (carte 4).', 3, '{"unitIds": ["eg.g51.frise_et_liens"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Défenseur et cause", "pairs": [{"left": "Irénée", "right": "les gnostiques"}, {"left": "Athanase", "right": "Arius"}, {"left": "Timothée", "right": "Apollinaire et Macédonius"}, {"left": "Cyrille", "right": "Nestorius"}, {"left": "Dioscore", "right": "un Christ UN"}], "answer": "Irénée = les gnostiques ; Athanase = Arius ; Timothée = Apollinaire et Macédonius ; Cyrille = Nestorius ; Dioscore = un Christ UN", "acceptedAnswers": [], "explanation": "Chacun défend la foi à son époque (carte 4).", "tip": "Un défenseur par siècle.", "id": "eg.l51.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e18', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens']::text[], 'reorder', 'lesson', 'Phrase-repère : les trois conciles dans l''ordre.', array['Nicée en 325 puis Constantinople en 381 puis Éphèse en 431']::text[], 'Les trois conciles reconnus par l''Église copte, dans l''ordre (cartes 1 à 3).', 2, '{"unitIds": ["eg.g51.frise_et_liens"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : les trois conciles dans l''ordre.", "tokens": ["puis", "381", "puis", "Constantinople", "325", "en", "Nicée", "Éphèse", "431", "en", "en"], "answer": "Nicée en 325 puis Constantinople en 381 puis Éphèse en 431", "acceptedAnswers": ["Nicée en 325 puis Constantinople en 381 puis Éphèse en 431"], "explanation": "Les trois conciles reconnus par l''Église copte, dans l''ordre (cartes 1 à 3).", "tip": "325, 381, 431.", "extraExample": {"text": "Chalcédoine vient après, en 451.", "translation": "Mais il n''est pas reconnu."}, "id": "eg.l51.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e19', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens']::text[], 'reorder', 'lesson', 'Phrase-repère : le pendule du Ve siècle.', array['Nestorius sépare et Eutychès mélange']::text[], 'Les deux erreurs opposées du Ve siècle (carte 5).', 3, '{"unitIds": ["eg.g51.frise_et_liens"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le pendule du Ve siècle.", "tokens": ["et", "Nestorius", "mélange", "Eutychès", "sépare"], "answer": "Nestorius sépare et Eutychès mélange", "acceptedAnswers": ["Nestorius sépare et Eutychès mélange"], "explanation": "Les deux erreurs opposées du Ve siècle (carte 5).", "tip": "Sépare / mélange.", "extraExample": {"text": "Cyrille garde l''unité.", "translation": "Sans mélange ni division."}, "id": "eg.l51.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e20', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.concile_ephese_431']::text[], 'free_answer', 'lesson', 'Quel concile répond à Nestorius ?', array['Éphèse','Ephèse','Ephese','Éphèse (431)','le concile d''Éphèse','Éphèse en 431']::text[], 'Éphèse (431) condamne Nestorius et proclame Marie Théotokos (carte 4).', 2, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.concile_ephese_431"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel concile répond à Nestorius ?", "answer": "Éphèse", "acceptedAnswers": ["Éphèse", "Ephèse", "Ephese", "Éphèse (431)", "le concile d''Éphèse", "Éphèse en 431"], "explanation": "Éphèse (431) condamne Nestorius et proclame Marie Théotokos (carte 4).", "tip": "Nestorius = Éphèse.", "extraExample": {"text": "Arius = Nicée.", "translation": "Macédonius = Constantinople."}, "id": "eg.l51.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e21', 'eg', 'eg.l51', 'eg.g51.frise_et_liens', array['eg.g51.frise_et_liens','eg.v.zenon']::text[], 'free_answer', 'lesson', 'Quel empereur publie l''Hénotikon en 482 ?', array['Zénon','Zenon','l''empereur Zénon']::text[], 'L''empereur Zénon publie l''Hénotikon, avec le patriarche Acace (carte 7).', 3, '{"unitIds": ["eg.g51.frise_et_liens", "eg.v.zenon"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel empereur publie l''Hénotikon en 482 ?", "answer": "Zénon", "acceptedAnswers": ["Zénon", "Zenon", "l''empereur Zénon"], "explanation": "L''empereur Zénon publie l''Hénotikon, avec le patriarche Acace (carte 7).", "tip": "Zénon = Hénotikon.", "extraExample": {"text": "Justinien : 538.", "translation": "Marcien : 451."}, "id": "eg.l51.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l51.e22', 'eg', 'eg.l51', 'eg.v.tombes', array['eg.v.tombes','eg.g51.frise_et_liens']::text[], 'free_answer', 'lesson', 'Quel mot désigne les chrétiens qui ont renié la foi pendant la persécution ?', array['les tombés','tombés','les lapsi','lapsi','tombes']::text[], 'Les « tombés » sont les chrétiens qui ont renié la foi ; leur retour divise l''Église au temps de Novatien (carte 7).', 2, '{"unitIds": ["eg.v.tombes", "eg.g51.frise_et_liens"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot désigne les chrétiens qui ont renié la foi pendant la persécution ?", "answer": "les tombés", "acceptedAnswers": ["les tombés", "tombés", "les lapsi", "lapsi", "tombes"], "explanation": "Les « tombés » sont les chrétiens qui ont renié la foi ; leur retour divise l''Église au temps de Novatien (carte 7).", "tip": "Tombés = pardon difficile.", "extraExample": {"text": "Dèce exigeait un sacrifice.", "translation": "Certains ont cédé."}, "id": "eg.l51.e22", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l51", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e01', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.formule_de_foi']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''une formule de foi ?', array['une phrase précise qui dit la foi face à une erreur']::text[], 'Homoousios, Théotokos, une seule nature du Verbe incarné sont des formules de foi (carte 1).', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.formule_de_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''une formule de foi ?", "options": ["une phrase précise qui dit la foi face à une erreur", "une prière de la messe", "une règle de discipline", "le nom d''un évêque"], "answer": "une phrase précise qui dit la foi face à une erreur", "acceptedAnswers": ["une phrase précise qui dit la foi face à une erreur"], "explanation": "Homoousios, Théotokos, une seule nature du Verbe incarné sont des formules de foi (carte 1).", "tip": "Formule = phrase-clé.", "extraExample": {"text": "Elle répond à une erreur précise.", "translation": "Arius, Nestorius."}, "id": "eg.l52.e01", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e02', 'eg', 'eg.l52', 'eg.v.homoousios', array['eg.v.homoousios','eg.g52.bilan_formules_dates']::text[], 'mcq', 'lesson', 'Quel mot grec de Nicée dit que le Fils est Dieu comme le Père ?', array['homoousios']::text[], 'Homoousios, c''est-à-dire consubstantiel : même substance que le Père (carte 1).', 1, '{"unitIds": ["eg.v.homoousios", "eg.g52.bilan_formules_dates"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel mot grec de Nicée dit que le Fils est Dieu comme le Père ?", "options": ["homoousios", "Théotokos", "physis", "Christotokos"], "answer": "homoousios", "acceptedAnswers": ["homoousios"], "explanation": "Homoousios, c''est-à-dire consubstantiel : même substance que le Père (carte 1).", "tip": "Homoousios = Nicée.", "extraExample": {"text": "Théotokos = Éphèse.", "translation": "Physis = nature."}, "id": "eg.l52.e02", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e03', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.theotokos']::text[], 'mcq', 'lesson', 'Quel titre d''Éphèse protège l''identité de Jésus, Dieu fait chair ?', array['Théotokos']::text[], 'Théotokos, « mère de Dieu » : celle qui enfante Dieu le Verbe fait chair (carte 1).', 1, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.theotokos"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre d''Éphèse protège l''identité de Jésus, Dieu fait chair ?", "options": ["Théotokos", "Homoousios", "Paraclet", "Christotokos"], "answer": "Théotokos", "acceptedAnswers": ["Théotokos"], "explanation": "Théotokos, « mère de Dieu » : celle qui enfante Dieu le Verbe fait chair (carte 1).", "tip": "Théotokos = Éphèse.", "extraExample": {"text": "Christotokos est le titre de Nestorius.", "translation": "Rejeté en 431."}, "errorPatterns": [{"equals": "Christotokos", "category": "word_confusion", "feedback": "Christotokos est le titre préféré de Nestorius. Éphèse choisit Théotokos."}], "id": "eg.l52.e03", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e04', 'eg', 'eg.l52', 'eg.v.formule_de_cyrille', array['eg.v.formule_de_cyrille','eg.g52.bilan_formules_dates']::text[], 'mcq', 'lesson', 'Qui prononce la formule « une seule nature du Verbe incarné » ?', array['saint Cyrille d''Alexandrie']::text[], 'C''est la formule de saint Cyrille, base du miaphysisme (carte 1). Eutychès la cite mais en change le sens.', 2, '{"unitIds": ["eg.v.formule_de_cyrille", "eg.g52.bilan_formules_dates"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui prononce la formule « une seule nature du Verbe incarné » ?", "options": ["saint Cyrille d''Alexandrie", "Eutychès", "Nestorius", "le pape Léon Ier"], "answer": "saint Cyrille d''Alexandrie", "acceptedAnswers": ["saint Cyrille d''Alexandrie"], "explanation": "C''est la formule de saint Cyrille, base du miaphysisme (carte 1). Eutychès la cite mais en change le sens.", "tip": "Cyrille = une nature du Verbe incarné.", "extraExample": {"text": "Eutychès cite Cyrille.", "translation": "Il en change le sens."}, "id": "eg.l52.e04", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e05', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.les_cinq_dates']::text[], 'mcq', 'lesson', 'Quelle date correspond à Éphèse II ?', array['449']::text[], 'Éphèse II se tient en 449 (carte 2). 431 est Éphèse I.', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.les_cinq_dates"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle date correspond à Éphèse II ?", "options": ["449", "431", "451", "381"], "answer": "449", "acceptedAnswers": ["449"], "explanation": "Éphèse II se tient en 449 (carte 2). 431 est Éphèse I.", "tip": "449 : Dioscore préside.", "extraExample": {"text": "431 : Cyrille préside.", "translation": "451 : Chalcédoine."}, "id": "eg.l52.e05", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e06', 'eg', 'eg.l52', 'eg.v.concile_de_constantinople', array['eg.v.concile_de_constantinople','eg.g52.bilan_formules_dates']::text[], 'mcq', 'lesson', 'Quel concile se tient en 381 ?', array['Constantinople']::text[], 'Constantinople (381) est le deuxième concile œcuménique (carte 2).', 1, '{"unitIds": ["eg.v.concile_de_constantinople", "eg.g52.bilan_formules_dates"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile se tient en 381 ?", "options": ["Constantinople", "Nicée", "Éphèse", "Chalcédoine"], "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "Constantinople (381) est le deuxième concile œcuménique (carte 2).", "tip": "381 = Constantinople.", "extraExample": {"text": "325 : Nicée.", "translation": "431 : Éphèse."}, "id": "eg.l52.e06", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e07', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.apollinarisme']::text[], 'mcq', 'lesson', 'Quelle erreur retire au Christ son âme humaine ?', array['l''apollinarisme']::text[], 'Apollinaire dit que la divinité du Verbe tient lieu d''âme (carte 6).', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.apollinarisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle erreur retire au Christ son âme humaine ?", "options": ["l''apollinarisme", "le nestorianisme", "le monophysisme", "l''arianisme"], "answer": "l''apollinarisme", "acceptedAnswers": ["l''apollinarisme"], "explanation": "Apollinaire dit que la divinité du Verbe tient lieu d''âme (carte 6).", "tip": "Apollinaire : âme.", "extraExample": {"text": "Nestorius : unité.", "translation": "Eutychès : humanité."}, "id": "eg.l52.e07", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e08', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.pneumatomaques']::text[], 'mcq', 'lesson', 'Qui nie la divinité du Saint-Esprit ?', array['Macédonius']::text[], 'Macédonius et les pneumatomaques nient la divinité du Saint-Esprit (carte 6). Arius nie celle du Fils.', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.pneumatomaques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui nie la divinité du Saint-Esprit ?", "options": ["Macédonius", "Arius", "Nestorius", "Marcion"], "answer": "Macédonius", "acceptedAnswers": ["Macédonius"], "explanation": "Macédonius et les pneumatomaques nient la divinité du Saint-Esprit (carte 6). Arius nie celle du Fils.", "tip": "Macédonius : Esprit.", "extraExample": {"text": "Arius : Fils.", "translation": "381 les condamne."}, "errorPatterns": [{"equals": "Arius", "category": "word_confusion", "feedback": "Arius nie la divinité du Fils. Macédonius nie celle de l''Esprit."}], "id": "eg.l52.e08", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e09', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.miaphysisme']::text[], 'mcq', 'lesson', 'Que veut dire « mia » dans miaphysisme ?', array['une seule, unie']::text[], 'Mia veut dire une seule, unie : une nature du Verbe incarné, ni mélangée ni divisée (carte 3).', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.miaphysisme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « mia » dans miaphysisme ?", "options": ["une seule, unie", "deux", "aucune", "trois"], "answer": "une seule, unie", "acceptedAnswers": ["une seule, unie"], "explanation": "Mia veut dire une seule, unie : une nature du Verbe incarné, ni mélangée ni divisée (carte 3).", "tip": "Mia = unie ; mono = un seul.", "extraExample": {"text": "Dyo = deux.", "translation": "Dyophysisme = Chalcédoine."}, "id": "eg.l52.e09", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e10', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.piege_de_confusion']::text[], 'mcq', 'lesson', 'Quel est le piège entre les deux conciles d''Éphèse ?', array['Éphèse 431 et Éphèse 449 sont deux conciles différents']::text[], 'Même ville, deux conciles : Cyrille en 431, Dioscore en 449 (carte 4).', 3, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.piege_de_confusion"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel est le piège entre les deux conciles d''Éphèse ?", "options": ["Éphèse 431 et Éphèse 449 sont deux conciles différents", "Ils ont eu lieu la même année", "Cyrille préside les deux", "Ils condamnent tous deux Nestorius"], "answer": "Éphèse 431 et Éphèse 449 sont deux conciles différents", "acceptedAnswers": ["Éphèse 431 et Éphèse 449 sont deux conciles différents"], "explanation": "Même ville, deux conciles : Cyrille en 431, Dioscore en 449 (carte 4).", "tip": "431 ≠ 449.", "extraExample": {"text": "Seul 431 est reconnu.", "translation": "449 est annulé en 451."}, "id": "eg.l52.e10", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e11', 'eg', 'eg.l52', 'eg.v.synode_de_constantinople_448', array['eg.v.synode_de_constantinople_448','eg.g52.bilan_formules_dates']::text[], 'mcq', 'lesson', 'Le synode de Constantinople de 448 est…', array['un concile local']::text[], 'En 448, Flavien réunit un synode local ; il ne faut pas le confondre avec le concile de 381 (carte 5).', 3, '{"unitIds": ["eg.v.synode_de_constantinople_448", "eg.g52.bilan_formules_dates"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Le synode de Constantinople de 448 est…", "options": ["un concile local", "le deuxième concile œcuménique", "le troisième concile œcuménique", "un concile impérial de 381"], "answer": "un concile local", "acceptedAnswers": ["un concile local"], "explanation": "En 448, Flavien réunit un synode local ; il ne faut pas le confondre avec le concile de 381 (carte 5).", "tip": "448 local ; 381 œcuménique.", "extraExample": {"text": "Antioche 269 est aussi local.", "translation": "Seuls 325, 381, 431 sont reconnus."}, "id": "eg.l52.e11", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e12', 'eg', 'eg.l52', 'eg.v.dioscore', array['eg.v.dioscore','eg.g52.bilan_formules_dates']::text[], 'mcq', 'lesson', 'Comment l''Église copte vénère-t-elle saint Dioscore ?', array['comme confesseur']::text[], 'Dioscore souffre l''exil pour sa foi sans mourir martyr : il est confesseur (carte 7).', 2, '{"unitIds": ["eg.v.dioscore", "eg.g52.bilan_formules_dates"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment l''Église copte vénère-t-elle saint Dioscore ?", "options": ["comme confesseur", "comme martyr", "comme hérétique repenti", "comme premier pape"], "answer": "comme confesseur", "acceptedAnswers": ["comme confesseur"], "explanation": "Dioscore souffre l''exil pour sa foi sans mourir martyr : il est confesseur (carte 7).", "tip": "Confesseur = souffre sans mourir martyr.", "extraExample": {"text": "Il meurt exilé à Gangra en 454.", "translation": "Fidèle à Cyrille."}, "id": "eg.l52.e12", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e13', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.credo_de_nicee_constantinople']::text[], 'fill_blank', 'lesson', 'Nicée (325) condamne Arius ; Constantinople (381) ___ le credo.', array['complète']::text[], 'En 381, on complète le credo de Nicée par la partie sur le Saint-Esprit (carte 1).', 1, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.credo_de_nicee_constantinople"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Nicée (325) condamne Arius ; Constantinople (381) ___ le credo.", "options": ["complète", "supprime", "traduit"], "answer": "complète", "acceptedAnswers": ["complète"], "explanation": "En 381, on complète le credo de Nicée par la partie sur le Saint-Esprit (carte 1).", "tip": "381 complète.", "extraExample": {"text": "431 confirme.", "translation": "Et interdit d''en composer un autre."}, "id": "eg.l52.e13", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e14', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.chalcedoine']::text[], 'fill_blank', 'lesson', 'Chalcédoine n''est pas reçu par l''Église ___.', array['copte']::text[], 'L''Église copte ne reconnaît que trois conciles et rejette Chalcédoine (cartes 2 et 3). Les Églises chalcédoniennes, elles, le reçoivent.', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.chalcedoine"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Chalcédoine n''est pas reçu par l''Église ___.", "options": ["copte", "catholique", "arménienne"], "answer": "copte", "acceptedAnswers": ["copte"], "explanation": "L''Église copte ne reconnaît que trois conciles et rejette Chalcédoine (cartes 2 et 3). Les Églises chalcédoniennes, elles, le reçoivent.", "tip": "Trois conciles pour les coptes.", "extraExample": {"text": "L''Église arménienne refuse aussi Chalcédoine.", "translation": "Comme les Églises sœurs."}, "id": "eg.l52.e14", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e15', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.monophysisme']::text[], 'fill_blank', 'lesson', 'Le monophysisme est celui d''___ ; le miaphysisme celui de Cyrille.', array['Eutychès']::text[], 'Mono = Eutychès (humanité absorbée) ; mia = Cyrille (carte 3).', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.monophysisme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le monophysisme est celui d''___ ; le miaphysisme celui de Cyrille.", "options": ["Eutychès", "Arius", "Marcion"], "answer": "Eutychès", "acceptedAnswers": ["Eutychès"], "explanation": "Mono = Eutychès (humanité absorbée) ; mia = Cyrille (carte 3).", "tip": "Mono contre mia.", "extraExample": {"text": "L''Église copte condamne le monophysisme.", "translation": "Elle est miaphysite."}, "id": "eg.l52.e15", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e16', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.premier_schisme']::text[], 'fill_blank', 'lesson', 'Le grand schisme de 1054 est distinct du premier schisme de ___.', array['451']::text[], '451 sépare les deux familles orthodoxes ; 1054 sépare Rome et Constantinople (carte 7).', 3, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.premier_schisme"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Le grand schisme de 1054 est distinct du premier schisme de ___.", "options": ["451", "325", "1989"], "answer": "451", "acceptedAnswers": ["451"], "explanation": "451 sépare les deux familles orthodoxes ; 1054 sépare Rome et Constantinople (carte 7).", "tip": "451 ≠ 1054.", "extraExample": {"text": "1989 : l''accord de foi.", "translation": "1054 : le Filioque."}, "id": "eg.l52.e16", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e17', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.les_cinq_dates']::text[], 'match', 'lesson', 'Les cinq dates', '{}'::text[], 'Cinq dates, cinq faits (carte 2).', 3, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.les_cinq_dates"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les cinq dates", "pairs": [{"left": "325", "right": "Nicée : Arius condamné"}, {"left": "381", "right": "Constantinople : credo complété"}, {"left": "431", "right": "Éphèse : Théotokos"}, {"left": "449", "right": "Éphèse II : Dioscore préside"}, {"left": "451", "right": "Chalcédoine : deux natures"}], "answer": "325 = Nicée : Arius condamné ; 381 = Constantinople : credo complété ; 431 = Éphèse : Théotokos ; 449 = Éphèse II : Dioscore préside ; 451 = Chalcédoine : deux natures", "acceptedAnswers": [], "explanation": "Cinq dates, cinq faits (carte 2).", "tip": "Le Fils, l''Esprit, Marie, Dioscore, deux natures.", "id": "eg.l52.e17", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e18', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates']::text[], 'match', 'lesson', 'Formules et origines', '{}'::text[], 'Chaque formule a son auteur ou son concile (cartes 1 à 3).', 3, '{"unitIds": ["eg.g52.bilan_formules_dates"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Formules et origines", "pairs": [{"left": "homoousios", "right": "Nicée (325)"}, {"left": "Théotokos", "right": "Éphèse (431)"}, {"left": "une seule nature du Verbe incarné", "right": "saint Cyrille"}, {"left": "un seul Christ en deux natures", "right": "Chalcédoine (451)"}], "answer": "homoousios = Nicée (325) ; Théotokos = Éphèse (431) ; une seule nature du Verbe incarné = saint Cyrille ; un seul Christ en deux natures = Chalcédoine (451)", "acceptedAnswers": [], "explanation": "Chaque formule a son auteur ou son concile (cartes 1 à 3).", "tip": "Trois formules coptes, une formule de Chalcédoine.", "id": "eg.l52.e18", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e19', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates']::text[], 'reorder', 'lesson', 'Phrase-repère : le premier piège.', array['Le monophysisme n''est pas le miaphysisme']::text[], 'Mono (Eutychès) s''oppose à mia (Cyrille) (carte 3).', 2, '{"unitIds": ["eg.g52.bilan_formules_dates"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le premier piège.", "tokens": ["monophysisme", "miaphysisme", "n''est", "pas", "le", "Le"], "answer": "Le monophysisme n''est pas le miaphysisme", "acceptedAnswers": ["Le monophysisme n''est pas le miaphysisme"], "explanation": "Mono (Eutychès) s''oppose à mia (Cyrille) (carte 3).", "tip": "Mono ≠ mia.", "extraExample": {"text": "Les coptes sont miaphysites.", "translation": "Ils condamnent Eutychès."}, "id": "eg.l52.e19", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e20', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates']::text[], 'reorder', 'lesson', 'Phrase-repère : le deuxième piège.', array['Éphèse en 431 n''est pas Éphèse en 449']::text[], 'Deux conciles différents dans la même ville (carte 4).', 3, '{"unitIds": ["eg.g52.bilan_formules_dates"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le deuxième piège.", "tokens": ["Éphèse", "pas", "Éphèse", "n''est", "431", "en", "449", "en"], "answer": "Éphèse en 431 n''est pas Éphèse en 449", "acceptedAnswers": ["Éphèse en 431 n''est pas Éphèse en 449"], "explanation": "Deux conciles différents dans la même ville (carte 4).", "tip": "431 ≠ 449.", "extraExample": {"text": "Cyrille préside le premier.", "translation": "Dioscore le second."}, "id": "eg.l52.e20", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e21', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.formule_de_cyrille']::text[], 'free_answer', 'lesson', 'Quelle formule de Cyrille résume le miaphysisme ?', array['une seule nature du Verbe incarné','une nature du Verbe incarné']::text[], 'La formule de Cyrille : une seule nature du Verbe incarné (carte 1).', 3, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.formule_de_cyrille"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quelle formule de Cyrille résume le miaphysisme ?", "answer": "une seule nature du Verbe incarné", "acceptedAnswers": ["une seule nature du Verbe incarné", "une nature du Verbe incarné"], "explanation": "La formule de Cyrille : une seule nature du Verbe incarné (carte 1).", "tip": "Une nature du Verbe incarné.", "extraExample": {"text": "Sans mélange ni division.", "translation": "L''humanité n''est pas absorbée."}, "id": "eg.l52.e21", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e22', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.trois_premiers_conciles']::text[], 'free_answer', 'lesson', 'Quelles sont les trois dates des conciles reconnus par l''Église copte ?', array['325, 381, 431','325 381 431','325, 381 et 431','325 381 et 431']::text[], 'Nicée 325, Constantinople 381, Éphèse 431 : les trois conciles de l''Église copte (carte 2).', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.trois_premiers_conciles"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quelles sont les trois dates des conciles reconnus par l''Église copte ?", "answer": "325, 381, 431", "acceptedAnswers": ["325, 381, 431", "325 381 431", "325, 381 et 431", "325 381 et 431"], "explanation": "Nicée 325, Constantinople 381, Éphèse 431 : les trois conciles de l''Église copte (carte 2).", "tip": "325, 381, 431.", "extraExample": {"text": "Chalcédoine : 451, non reconnu.", "translation": "Éphèse II : 449, non reconnu."}, "id": "eg.l52.e22", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l52.e23', 'eg', 'eg.l52', 'eg.g52.bilan_formules_dates', array['eg.g52.bilan_formules_dates','eg.v.concile_chalcedoine']::text[], 'free_answer', 'lesson', 'Quel concile de 451 l''Église copte ne reconnaît-elle pas ?', array['Chalcédoine','chalcedoine','le concile de Chalcédoine','Chalcédoine (451)']::text[], 'L''Église copte rejette Chalcédoine (451) et ne reconnaît que trois conciles (carte 2).', 2, '{"unitIds": ["eg.g52.bilan_formules_dates", "eg.v.concile_chalcedoine"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel concile de 451 l''Église copte ne reconnaît-elle pas ?", "answer": "Chalcédoine", "acceptedAnswers": ["Chalcédoine", "chalcedoine", "le concile de Chalcédoine", "Chalcédoine (451)"], "explanation": "L''Église copte rejette Chalcédoine (451) et ne reconnaît que trois conciles (carte 2).", "tip": "Pas de 451 chez les coptes.", "extraExample": {"text": "Elle condamne aussi Eutychès.", "translation": "Ce n''est pas un désaccord sur lui."}, "id": "eg.l52.e23", "promptLanguage": "fr", "pool": "lesson", "lessonId": "eg.l52", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e01', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales','eg.v.eglise_orthodoxe_chalcedonienne']::text[], 'match', 'lesson', 'Chaque famille et son exemple', '{}'::text[], 'Quatre familles : les orthodoxes orientales (dont la nôtre), les chalcédoniennes, les catholiques et les protestants.', 1, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales", "eg.v.eglise_orthodoxe_chalcedonienne"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque famille et son exemple", "promptLanguage": "fr", "pairs": [{"left": "Églises orthodoxes orientales", "right": "copte, syriaque, arménienne, éthiopienne"}, {"left": "Église orthodoxe chalcédonienne", "right": "grecque, russe, serbe, roumaine"}, {"left": "Église catholique", "right": "dirigée par le pape à Rome"}, {"left": "Protestantisme", "right": "né de la Réforme au XVIe siècle"}], "answer": "Églises orthodoxes orientales = copte, syriaque, arménienne, éthiopienne ; Église orthodoxe chalcédonienne = grecque, russe, serbe, roumaine ; Église catholique = dirigée par le pape à Rome ; Protestantisme = né de la Réforme au XVIe siècle", "acceptedAnswers": [], "explanation": "Quatre familles : les orthodoxes orientales (dont la nôtre), les chalcédoniennes, les catholiques et les protestants.", "tip": "Orientales = sans Chalcédoine ; chalcédoniennes = avec.", "id": "eg.l53.e01", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e02', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Combien y a-t-il de grandes familles de chrétiens ?', array['Quatre']::text[], 'On distingue les Églises orthodoxes orientales, les orthodoxes chalcédoniens, les catholiques et les protestants.', 1, '{"unitIds": ["eg.g53.familles_eglises"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien y a-t-il de grandes familles de chrétiens ?", "promptLanguage": "fr", "options": ["Quatre", "Deux", "Six", "Douze"], "answer": "Quatre", "acceptedAnswers": ["Quatre"], "explanation": "On distingue les Églises orthodoxes orientales, les orthodoxes chalcédoniens, les catholiques et les protestants.", "tip": "Quatre familles, trois questions.", "extraExample": {"text": "Les Églises ont de nombreuses divisions.", "translation": "Mais ces quatre familles servent de repères."}, "id": "eg.l53.e02", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e03', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales']::text[], 'mcq', 'lesson', 'À quelle famille appartient l''Église copte orthodoxe ?', array['Les Églises orthodoxes orientales']::text[], 'Comme les Églises arménienne, syriaque, éthiopienne et malankare, l''Église copte n''a pas reçu Chalcédoine.', 1, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "À quelle famille appartient l''Église copte orthodoxe ?", "promptLanguage": "fr", "options": ["Les Églises orthodoxes orientales", "L''Église orthodoxe chalcédonienne", "Le protestantisme", "L''Église catholique"], "answer": "Les Églises orthodoxes orientales", "acceptedAnswers": ["Les Églises orthodoxes orientales"], "explanation": "Comme les Églises arménienne, syriaque, éthiopienne et malankare, l''Église copte n''a pas reçu Chalcédoine.", "tip": "Orientale ne veut pas dire grecque.", "extraExample": {"text": "Un orthodoxe grec n''est pas un orthodoxe oriental.", "translation": "Les grecs reçoivent Chalcédoine."}, "errorPatterns": [{"equals": "L''Église orthodoxe chalcédonienne", "category": "word_confusion", "feedback": "Les orthodoxes grecs ou russes reçoivent Chalcédoine ; nous, non."}], "id": "eg.l53.e03", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e04', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales']::text[], 'mcq', 'lesson', 'Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?', array['Chalcédoine (451)']::text[], 'Elles gardent les trois premiers conciles (Nicée, Constantinople, Éphèse) mais refusent Chalcédoine en 451.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?", "promptLanguage": "fr", "options": ["Chalcédoine (451)", "Nicée (325)", "Constantinople (381)", "Éphèse (431)"], "answer": "Chalcédoine (451)", "acceptedAnswers": ["Chalcédoine (451)"], "explanation": "Elles gardent les trois premiers conciles (Nicée, Constantinople, Éphèse) mais refusent Chalcédoine en 451.", "tip": "Trois conciles reçus, Chalcédoine refusé.", "extraExample": {"text": "Nicée, Constantinople et Éphèse sont reçus par tous.", "translation": "Seul Chalcédoine divise."}, "errorPatterns": [{"equals": "Éphèse (431)", "category": "word_confusion", "feedback": "Éphèse (431) est reçu par les orthodoxes orientaux, qui lui doivent le titre de Mère de Dieu."}], "id": "eg.l53.e04", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e05', 'eg', 'eg.l53', 'eg.v.eglise_malankare', array['eg.v.eglise_malankare','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Quelle Église orthodoxe orientale rattache ses origines à l''apôtre Thomas ?', array['L''Église malankare']::text[], 'Les chrétiens du Kerala, en Inde, disent descendre de ceux que Thomas a évangélisés.', 2, '{"unitIds": ["eg.v.eglise_malankare", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle Église orthodoxe orientale rattache ses origines à l''apôtre Thomas ?", "promptLanguage": "fr", "options": ["L''Église malankare", "L''Église arménienne", "L''Église tewahedo", "L''Église syriaque"], "answer": "L''Église malankare", "acceptedAnswers": ["L''Église malankare"], "explanation": "Les chrétiens du Kerala, en Inde, disent descendre de ceux que Thomas a évangélisés.", "tip": "Thomas va en Inde, comme Marc va à Alexandrie.", "extraExample": {"text": "Thomas est l''apôtre de l''Inde.", "translation": "Marc est l''apôtre de l''Égypte."}, "id": "eg.l53.e05", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e06', 'eg', 'eg.l53', 'eg.v.eglise_armenienne_apostolique', array['eg.v.eglise_armenienne_apostolique','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Quel royaume est le premier à adopter le christianisme comme religion d''État vers 301 ?', array['L''Arménie']::text[], 'Saint Grégoire l''Illuminateur convertit le roi d''Arménie vers 301, avant que Constantin ne protège les chrétiens.', 2, '{"unitIds": ["eg.v.eglise_armenienne_apostolique", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel royaume est le premier à adopter le christianisme comme religion d''État vers 301 ?", "promptLanguage": "fr", "options": ["L''Arménie", "L''Éthiopie", "L''Égypte", "L''Empire romain"], "answer": "L''Arménie", "acceptedAnswers": ["L''Arménie"], "explanation": "Saint Grégoire l''Illuminateur convertit le roi d''Arménie vers 301, avant que Constantin ne protège les chrétiens.", "tip": "Arménie : 301.", "extraExample": {"text": "Rome ne devient officiellement chrétienne qu''avec Théodose, en 380.", "translation": "L''Arménie l''a précédée."}, "errorPatterns": [{"equals": "L''Empire romain", "category": "word_confusion", "feedback": "L''Arménie devance Rome : son roi se convertit vers 301."}], "id": "eg.l53.e06", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e07', 'eg', 'eg.l53', 'eg.v.eglise_tewahedo', array['eg.v.eglise_tewahedo','eg.g53.familles_eglises']::text[], 'fill_blank', 'lesson', 'Jusqu''en 1959, l''abouna d''Éthiopie était envoyé depuis ___.', array['Alexandrie']::text[], 'L''Église éthiopienne dépendait de l''Église copte : le premier évêque, Frumence, fut consacré par saint Athanase.', 2, '{"unitIds": ["eg.v.eglise_tewahedo", "eg.g53.familles_eglises"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Jusqu''en 1959, l''abouna d''Éthiopie était envoyé depuis ___.", "promptLanguage": "fr", "options": ["Alexandrie", "Rome", "Antioche", "Constantinople"], "answer": "Alexandrie", "acceptedAnswers": ["Alexandrie"], "explanation": "L''Église éthiopienne dépendait de l''Église copte : le premier évêque, Frumence, fut consacré par saint Athanase.", "tip": "Éthiopie = fille d''Alexandrie.", "extraExample": {"text": "L''Église éthiopienne a eu son propre patriarche à partir de 1959.", "translation": "Le pape copte a alors consacré le premier patriarche éthiopien."}, "id": "eg.l53.e07", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e08', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_catholique']::text[], 'mcq', 'lesson', 'Qui est le chef de l''Église catholique ?', array['Le pape, évêque de Rome']::text[], 'Les catholiques reconnaissent le pape comme chef. C''est le point central qui les distingue des orthodoxes.', 1, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_catholique"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est le chef de l''Église catholique ?", "promptLanguage": "fr", "options": ["Le pape, évêque de Rome", "Le patriarche de Constantinople", "Le pape d''Alexandrie", "Le roi d''Angleterre"], "answer": "Le pape, évêque de Rome", "acceptedAnswers": ["Le pape, évêque de Rome"], "explanation": "Les catholiques reconnaissent le pape comme chef. C''est le point central qui les distingue des orthodoxes.", "tip": "Catholique = en communion avec le pape.", "extraExample": {"text": "Notre pape est évêque d''Alexandrie.", "translation": "Le pape de Rome est celui des catholiques."}, "errorPatterns": [{"equals": "Le pape d''Alexandrie", "category": "word_confusion", "feedback": "Le pape d''Alexandrie est le chef de l''Église copte orthodoxe."}], "id": "eg.l53.e08", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e09', 'eg', 'eg.l53', 'eg.v.eglise_catholique', array['eg.v.eglise_catholique','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Que signifie « Église catholique copte » ?', array['Elle garde la liturgie copte mais reconnaît le pape']::text[], 'Elle garde la liturgie copte mais reconnaît le pape. Elle est distincte de l''Église copte orthodoxe.', 3, '{"unitIds": ["eg.v.eglise_catholique", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie « Église catholique copte » ?", "promptLanguage": "fr", "options": ["Elle garde la liturgie copte mais reconnaît le pape", "Une autre appellation de l''Église copte orthodoxe", "Une Église protestante d''Égypte", "L''Église des Coptes de Rome"], "answer": "Elle garde la liturgie copte mais reconnaît le pape", "acceptedAnswers": ["Elle garde la liturgie copte mais reconnaît le pape"], "explanation": "Elle garde la liturgie copte mais reconnaît le pape. Elle est distincte de l''Église copte orthodoxe.", "tip": "Copte par le rite, catholique par la communion.", "extraExample": {"text": "L''Église catholique compte 23 Églises orientales.", "translation": "La copte est l''une d''elles."}, "errorPatterns": [{"equals": "Une autre appellation de l''Église copte orthodoxe", "category": "word_confusion", "feedback": "Non : ce sont deux Églises différentes, l''une reconnaît le pape, l''autre pas."}], "id": "eg.l53.e09", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e10', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_orthodoxe_chalcedonienne']::text[], 'fill_blank', 'lesson', 'Les orthodoxes chalcédoniens reçoivent ___ conciles.', array['sept']::text[], 'Ils reçoivent sept conciles, dont Chalcédoine. Nous en gardons trois.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_orthodoxe_chalcedonienne"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les orthodoxes chalcédoniens reçoivent ___ conciles.", "promptLanguage": "fr", "options": ["sept", "trois", "neuf", "quinze"], "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Ils reçoivent sept conciles, dont Chalcédoine. Nous en gardons trois.", "tip": "7 contre 3.", "extraExample": {"text": "Le septième concile est Nicée II.", "translation": "Il porte sur les icônes."}, "id": "eg.l53.e10", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e11', 'eg', 'eg.l53', 'eg.v.protestantisme', array['eg.v.protestantisme','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'De quel grand mouvement du XVIe siècle les protestants sont-ils nés ?', array['la Réforme','Réforme']::text[], 'La Réforme commence en 1517 avec Luther. Elle donne naissance aux Églises protestantes.', 2, '{"unitIds": ["eg.v.protestantisme", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "De quel grand mouvement du XVIe siècle les protestants sont-ils nés ?", "promptLanguage": "fr", "hint": "Elle commence en 1517.", "answer": "la Réforme", "acceptedAnswers": ["la Réforme", "Réforme"], "explanation": "La Réforme commence en 1517 avec Luther. Elle donne naissance aux Églises protestantes.", "tip": "Protestant = fils de la Réforme.", "extraExample": {"text": "Luther affiche ses 95 thèses en 1517.", "translation": "C''est la date de départ."}, "id": "eg.l53.e11", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e12', 'eg', 'eg.l53', 'eg.v.eglise_tewahedo', array['eg.v.eglise_tewahedo','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'Quel mot, qui veut dire « rendu un », désigne les Églises d''Éthiopie et d''Érythrée ?', array['tewahedo','Église tewahedo']::text[], 'Tewahedo exprime l''union du divin et de l''humain en Christ, c''est-à-dire la foi miaphysite.', 3, '{"unitIds": ["eg.v.eglise_tewahedo", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel mot, qui veut dire « rendu un », désigne les Églises d''Éthiopie et d''Érythrée ?", "promptLanguage": "fr", "hint": "Pense à « rendu un ».", "answer": "tewahedo", "acceptedAnswers": ["tewahedo", "Église tewahedo"], "explanation": "Tewahedo exprime l''union du divin et de l''humain en Christ, c''est-à-dire la foi miaphysite.", "tip": "Tewahedo = rendu un.", "extraExample": {"text": "L''Église éthiopienne se dit « tewahedo ».", "translation": "L''Église érythréenne aussi."}, "id": "eg.l53.e12", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e13', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'reorder', 'lesson', 'Phrase-repère : notre famille d''Églises.', array['Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine']::text[], 'Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine, mais gardent Nicée, Constantinople et Éphèse.', 2, '{"unitIds": ["eg.g53.familles_eglises"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : notre famille d''Églises.", "promptLanguage": "fr", "tokens": ["orthodoxes", "reçu", "Les", "Chalcédoine", "pas", "Églises", "n''ont", "orientales"], "answer": "Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine", "acceptedAnswers": ["Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine"], "explanation": "Les Églises orthodoxes orientales n''ont pas reçu Chalcédoine, mais gardent Nicée, Constantinople et Éphèse.", "tip": "Orientales = sans Chalcédoine.", "extraExample": {"text": "Les orthodoxes chalcédoniens reçoivent Chalcédoine.", "translation": "La différence est dans le nom."}, "id": "eg.l53.e13", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e14', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Quelle question sépare surtout les protestants de toutes les autres familles ?', array['La Bible seule suffit-elle ?']::text[], 'Les protestants s''appuient sur la Bible seule ; les autres ajoutent la Tradition.', 3, '{"unitIds": ["eg.g53.familles_eglises"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle question sépare surtout les protestants de toutes les autres familles ?", "promptLanguage": "fr", "options": ["La Bible seule suffit-elle ?", "Reçoit-on Chalcédoine ?", "Parle-t-on grec ?", "Prie-t-on en copte ?"], "answer": "La Bible seule suffit-elle ?", "acceptedAnswers": ["La Bible seule suffit-elle ?"], "explanation": "Les protestants s''appuient sur la Bible seule ; les autres ajoutent la Tradition.", "tip": "Bible seule = signature protestante.", "extraExample": {"text": "Les orthodoxes disent : Écriture et Tradition.", "translation": "Les catholiques aussi."}, "id": "eg.l53.e14", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e15', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_syriaque_orthodoxe','eg.v.eglise_tewahedo','eg.v.eglise_malankare']::text[], 'match', 'lesson', 'Chaque Église et son pays', '{}'::text[], 'Ces quatre Églises sont orthodoxes orientales, comme la nôtre.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_syriaque_orthodoxe", "eg.v.eglise_tewahedo", "eg.v.eglise_malankare"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque Église et son pays", "promptLanguage": "fr", "pairs": [{"left": "Église syriaque orthodoxe", "right": "patriarcat d''Antioche"}, {"left": "Église arménienne apostolique", "right": "Arménie"}, {"left": "Église tewahedo", "right": "Éthiopie et Érythrée"}, {"left": "Église malankare", "right": "Kerala, en Inde"}], "answer": "Église syriaque orthodoxe = patriarcat d''Antioche ; Église arménienne apostolique = Arménie ; Église tewahedo = Éthiopie et Érythrée ; Église malankare = Kerala, en Inde", "acceptedAnswers": [], "explanation": "Ces quatre Églises sont orthodoxes orientales, comme la nôtre.", "tip": "Antioche, Arménie, Éthiopie, Kerala.", "id": "eg.l53.e15", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e16', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_catholique']::text[], 'mcq', 'lesson', 'Quelle est la plus grande famille chrétienne ?', array['L''Église catholique']::text[], 'L''Église catholique compte environ 1,4 milliard de fidèles.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_catholique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la plus grande famille chrétienne ?", "promptLanguage": "fr", "options": ["L''Église catholique", "Les orthodoxes orientaux", "Les orthodoxes chalcédoniens", "Les anglicans"], "answer": "L''Église catholique", "acceptedAnswers": ["L''Église catholique"], "explanation": "L''Église catholique compte environ 1,4 milliard de fidèles.", "tip": "Un chrétien sur deux est catholique ou presque.", "extraExample": {"text": "Les orthodoxes chalcédoniens dépassent 200 millions.", "translation": "Ils sont loin derrière."}, "id": "eg.l53.e16", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e17', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_armenienne_apostolique']::text[], 'fill_blank', 'lesson', 'L''Église arménienne est dite « ___ » car elle remonte aux apôtres.', array['apostolique']::text[], 'Elle fait remonter ses origines aux apôtres Thaddée et Barthélemy.', 3, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_armenienne_apostolique"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "L''Église arménienne est dite « ___ » car elle remonte aux apôtres.", "promptLanguage": "fr", "options": ["apostolique", "évangélique", "byzantine"], "answer": "apostolique", "acceptedAnswers": ["apostolique"], "explanation": "Elle fait remonter ses origines aux apôtres Thaddée et Barthélemy.", "tip": "Apostolique = qui remonte aux apôtres.", "extraExample": {"text": "Notre Église aussi est apostolique.", "translation": "Elle remonte à saint Marc."}, "id": "eg.l53.e17", "pool": "lesson", "lessonId": "eg.l53", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e18', 'eg', 'eg.l53', 'eg.v.eglise_malankare', array['eg.v.eglise_malankare','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'Dans quel pays se trouve l''Église malankare ?', array['l''Inde','Inde','Inde (Kerala)','au Kerala','Kerala']::text[], 'L''Église malankare est celle du Kerala, dans le sud-ouest de l''Inde.', 2, '{"unitIds": ["eg.v.eglise_malankare", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Dans quel pays se trouve l''Église malankare ?", "promptLanguage": "fr", "hint": "Elle remonte à l''apôtre Thomas.", "answer": "l''Inde", "acceptedAnswers": ["l''Inde", "Inde", "Inde (Kerala)", "au Kerala", "Kerala"], "explanation": "L''Église malankare est celle du Kerala, dans le sud-ouest de l''Inde.", "tip": "Malankare = Inde.", "extraExample": {"text": "Le Kerala est au sud-ouest de l''Inde.", "translation": "Thomas y serait venu."}, "id": "eg.l53.e18", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e19', 'eg', 'eg.l53', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Un orthodoxe grec est :', array['Un orthodoxe chalcédonien']::text[], 'Les orthodoxes grecs, russes, serbes… reçoivent Chalcédoine : on les appelle chalcédoniens.', 3, '{"unitIds": ["eg.g53.familles_eglises"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Un orthodoxe grec est :", "promptLanguage": "fr", "options": ["Un orthodoxe chalcédonien", "Un orthodoxe oriental", "Un protestant", "Un catholique copte"], "answer": "Un orthodoxe chalcédonien", "acceptedAnswers": ["Un orthodoxe chalcédonien"], "explanation": "Les orthodoxes grecs, russes, serbes… reçoivent Chalcédoine : on les appelle chalcédoniens.", "tip": "Grec, russe, serbe = chalcédoniens.", "extraExample": {"text": "Le patriarche de Constantinople est de cette famille.", "translation": "Il reçoit sept conciles."}, "errorPatterns": [{"equals": "Un orthodoxe oriental", "category": "word_confusion", "feedback": "Nous sommes les orthodoxes orientaux ; les Grecs sont chalcédoniens."}], "id": "eg.l53.e19", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e20', 'eg', 'eg.l53', 'eg.v.saint_marc', array['eg.v.saint_marc','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Révision — Quel apôtre a fondé l''Église d''Alexandrie ?', array['Saint Marc']::text[], 'Saint Marc a fondé l''Église d''Alexandrie, dont notre pape est le successeur.', 1, '{"unitIds": ["eg.v.saint_marc", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Quel apôtre a fondé l''Église d''Alexandrie ?", "promptLanguage": "fr", "options": ["Saint Marc", "Saint Pierre", "Saint Thomas", "Saint Paul"], "answer": "Saint Marc", "acceptedAnswers": ["Saint Marc"], "explanation": "Saint Marc a fondé l''Église d''Alexandrie, dont notre pape est le successeur.", "tip": "Marc : Alexandrie.", "extraExample": {"text": "Thomas est l''apôtre de l''Inde.", "translation": "Pierre est l''apôtre de Rome."}, "errorPatterns": [{"equals": "Saint Thomas", "category": "word_confusion", "feedback": "Thomas est lié à l''Inde, donc à l''Église malankare."}], "id": "eg.l53.e20", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e21', 'eg', 'eg.l53', 'eg.v.concile_de_nicee', array['eg.v.concile_de_nicee','eg.g53.familles_eglises']::text[], 'mcq', 'lesson', 'Révision — En quelle année se tient le concile de Nicée ?', array['325']::text[], 'Le premier concile œcuménique se tient à Nicée en 325. Il est reçu par toutes les familles d''Églises.', 2, '{"unitIds": ["eg.v.concile_de_nicee", "eg.g53.familles_eglises"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — En quelle année se tient le concile de Nicée ?", "promptLanguage": "fr", "options": ["325", "381", "431", "451"], "answer": "325", "acceptedAnswers": ["325"], "explanation": "Le premier concile œcuménique se tient à Nicée en 325. Il est reçu par toutes les familles d''Églises.", "tip": "Nicée : 325.", "extraExample": {"text": "Constantinople vient en 381.", "translation": "Éphèse en 431."}, "errorPatterns": [{"equals": "451", "category": "word_confusion", "feedback": "451 est Chalcédoine, que nous n''avons pas reçu."}], "id": "eg.l53.e21", "pool": "lesson", "lessonId": "eg.l53", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l53.e22', 'eg', 'eg.l53', 'eg.v.arius', array['eg.v.arius','eg.g53.familles_eglises']::text[], 'free_answer', 'lesson', 'Révision — Quel prêtre d''Alexandrie niait que le Fils soit Dieu, au début du IVe siècle ?', array['Arius']::text[], 'Arius, prêtre d''Alexandrie, est condamné à Nicée.', 2, '{"unitIds": ["eg.v.arius", "eg.g53.familles_eglises"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Révision — Quel prêtre d''Alexandrie niait que le Fils soit Dieu, au début du IVe siècle ?", "promptLanguage": "fr", "hint": "Son nom commence par A.", "answer": "Arius", "acceptedAnswers": ["Arius"], "explanation": "Arius, prêtre d''Alexandrie, est condamné à Nicée.", "tip": "Arius : le Fils créé.", "extraExample": {"text": "Les témoins de Jéhovah reprennent une idée voisine.", "translation": "Nicée l''a condamnée."}, "id": "eg.l53.e22", "pool": "lesson", "lessonId": "eg.l53", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e01', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'match', 'lesson', 'Qui a fait quoi à Chalcédoine ?', '{}'::text[], 'Marcien réunit le concile, qui reçoit la lettre de Léon, dépose Dioscore et condamne Eutychès.', 1, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Qui a fait quoi à Chalcédoine ?", "promptLanguage": "fr", "pairs": [{"left": "Marcien", "right": "l''empereur qui réunit le concile"}, {"left": "Léon", "right": "évêque de Rome, auteur du Tome"}, {"left": "Dioscore", "right": "patriarche d''Alexandrie déposé"}, {"left": "Eutychès", "right": "condamné par le concile"}], "answer": "Marcien = l''empereur qui réunit le concile ; Léon = évêque de Rome, auteur du Tome ; Dioscore = patriarche d''Alexandrie déposé ; Eutychès = condamné par le concile", "acceptedAnswers": [], "explanation": "Marcien réunit le concile, qui reçoit la lettre de Léon, dépose Dioscore et condamne Eutychès.", "tip": "Quatre noms de 451.", "id": "eg.l54.e01", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e02', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'En quelle année se tient le concile de Chalcédoine ?', array['451']::text[], 'Chalcédoine se tient en 451, vingt ans après Éphèse (431).', 1, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année se tient le concile de Chalcédoine ?", "promptLanguage": "fr", "options": ["451", "325", "431", "381"], "answer": "451", "acceptedAnswers": ["451"], "explanation": "Chalcédoine se tient en 451, vingt ans après Éphèse (431).", "tip": "451 : Chalcédoine ; 431 : Éphèse.", "extraExample": {"text": "Nicée est en 325, Constantinople en 381.", "translation": "Chalcédoine est le quatrième concile."}, "errorPatterns": [{"equals": "431", "category": "word_confusion", "feedback": "431 est l''année d''Éphèse."}, {"equals": "325", "category": "word_confusion", "feedback": "325 est l''année de Nicée."}], "id": "eg.l54.e02", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e03', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.deux_natures']::text[], 'mcq', 'lesson', 'Quelle formule est celle du concile de Chalcédoine ?', array['Un seul Christ reconnu en deux natures']::text[], 'La formule de Chalcédoine confesse un Christ reconnu en deux natures, divine et humaine, sans confusion ni séparation.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.deux_natures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle formule est celle du concile de Chalcédoine ?", "promptLanguage": "fr", "options": ["Un seul Christ reconnu en deux natures", "Une seule nature du Verbe incarné", "Le Christ n''a qu''une apparence humaine", "Le Christ est deux personnes"], "answer": "Un seul Christ reconnu en deux natures", "acceptedAnswers": ["Un seul Christ reconnu en deux natures"], "explanation": "La formule de Chalcédoine confesse un Christ reconnu en deux natures, divine et humaine, sans confusion ni séparation.", "tip": "Chalcédoine : deux natures.", "extraExample": {"text": "Nestorius parlait de deux personnes.", "translation": "Chalcédoine le rejette aussi."}, "errorPatterns": [{"equals": "Une seule nature du Verbe incarné", "category": "word_confusion", "feedback": "C''est la formule de saint Cyrille, que garde l''Église copte."}], "id": "eg.l54.e03", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e04', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Quelle formule de saint Cyrille garde l''Église copte ?', array['Une seule nature du Verbe incarné']::text[], 'Cyrille parle d''une seule nature du Verbe incarné : divinité et humanité unies sans mélange.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle formule de saint Cyrille garde l''Église copte ?", "promptLanguage": "fr", "options": ["Une seule nature du Verbe incarné", "Un seul Christ reconnu en deux natures", "Le Fils est inférieur au Père", "Deux Christs unis par amour"], "answer": "Une seule nature du Verbe incarné", "acceptedAnswers": ["Une seule nature du Verbe incarné"], "explanation": "Cyrille parle d''une seule nature du Verbe incarné : divinité et humanité unies sans mélange.", "tip": "Cyrille : une seule nature.", "extraExample": {"text": "Cyrille est patriarche d''Alexandrie de 412 à 444.", "translation": "Il combat Nestorius à Éphèse."}, "errorPatterns": [{"equals": "Le Fils est inférieur au Père", "category": "word_confusion", "feedback": "C''est la thèse d''Arius, condamnée à Nicée."}], "id": "eg.l54.e04", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e05', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'fill_blank', 'lesson', 'L''Église copte est miaphysite : « mia » veut dire ___.', array['une']::text[], 'Miaphysite vient du grec mia (une) et physis (nature).', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "L''Église copte est miaphysite : « mia » veut dire ___.", "promptLanguage": "fr", "options": ["une", "deux", "trois", "nature"], "answer": "une", "acceptedAnswers": ["une"], "explanation": "Miaphysite vient du grec mia (une) et physis (nature).", "tip": "Mia = une.", "extraExample": {"text": "Monophysite vient aussi de « une nature ».", "translation": "Mais le sens d''Eutychès est condamné."}, "id": "eg.l54.e05", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e06', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.deux_natures']::text[], 'mcq', 'lesson', 'Pourquoi l''Église d''Alexandrie a-t-elle refusé « en deux natures » ?', array['Elle craignait de diviser le Christ']::text[], 'Dire « en deux natures » après l''union semblait séparer Dieu et l''homme en deux personnes. Alexandrie préfère « de deux natures ».', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.deux_natures"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Église d''Alexandrie a-t-elle refusé « en deux natures » ?", "promptLanguage": "fr", "options": ["Elle craignait de diviser le Christ", "Elle niait que le Christ soit homme", "Elle refusait les icônes", "Elle voulait un pape à Alexandrie"], "answer": "Elle craignait de diviser le Christ", "acceptedAnswers": ["Elle craignait de diviser le Christ"], "explanation": "Dire « en deux natures » après l''union semblait séparer Dieu et l''homme en deux personnes. Alexandrie préfère « de deux natures ».", "tip": "Alexandrie veut défendre l''unité du Christ.", "extraExample": {"text": "L''Église copte confesse la pleine humanité du Christ.", "translation": "Elle condamne Eutychès."}, "errorPatterns": [{"equals": "Elle niait que le Christ soit homme", "category": "word_confusion", "feedback": "Au contraire : l''Église copte confesse le Christ vrai homme et condamne Eutychès."}], "id": "eg.l54.e06", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e07', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Que reproche-t-on au monophysisme d''Eutychès ?', array['Il absorbait l''humanité du Christ dans sa divinité']::text[], 'Eutychès disait que l''humanité disparaît dans la divinité. L''Église copte le condamne aussi : le Christ est vraiment homme.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que reproche-t-on au monophysisme d''Eutychès ?", "promptLanguage": "fr", "options": ["Il absorbait l''humanité du Christ dans sa divinité", "Il divisait le Christ en deux personnes", "Il niait la Trinité", "Il refusait l''Ancien Testament"], "answer": "Il absorbait l''humanité du Christ dans sa divinité", "acceptedAnswers": ["Il absorbait l''humanité du Christ dans sa divinité"], "explanation": "Eutychès disait que l''humanité disparaît dans la divinité. L''Église copte le condamne aussi : le Christ est vraiment homme.", "tip": "Eutychès mélange ; Nestorius divise.", "extraExample": {"text": "Miaphysite n''est pas monophysite.", "translation": "La différence est capitale."}, "errorPatterns": [{"equals": "Il divisait le Christ en deux personnes", "category": "word_confusion", "feedback": "C''est le reproche fait à Nestorius."}], "id": "eg.l54.e07", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e08', 'eg', 'eg.l54', 'eg.v.tome_de_leon', array['eg.v.tome_de_leon','eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Le Tome de Léon, qu''est-ce que c''était ?', array['Une lettre du pape de Rome']::text[], 'Léon, évêque de Rome, y expose deux natures dans le Christ. Chalcédoine la reçoit ; Alexandrie la refuse.', 2, '{"unitIds": ["eg.v.tome_de_leon", "eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Le Tome de Léon, qu''est-ce que c''était ?", "promptLanguage": "fr", "options": ["Une lettre du pape de Rome", "Un livre de saint Athanase", "Une règle de saint Pacôme", "Un canon de Nicée"], "answer": "Une lettre du pape de Rome", "acceptedAnswers": ["Une lettre du pape de Rome"], "explanation": "Léon, évêque de Rome, y expose deux natures dans le Christ. Chalcédoine la reçoit ; Alexandrie la refuse.", "tip": "Tome de Léon = lettre de Rome.", "extraExample": {"text": "Le mot « tome » signifie ici un texte long.", "translation": "C''est une lettre à Flavien."}, "id": "eg.l54.e08", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e09', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'free_answer', 'lesson', 'Quel patriarche d''Alexandrie a été déposé à Chalcédoine ?', array['Dioscore','saint Dioscore','Dioscore d''Alexandrie','Dioscore Ier']::text[], 'Dioscore est déposé en 451, exilé à Gangra et meurt en 454. L''Église copte le vénère comme confesseur.', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel patriarche d''Alexandrie a été déposé à Chalcédoine ?", "promptLanguage": "fr", "hint": "Il succède à Cyrille.", "answer": "Dioscore", "acceptedAnswers": ["Dioscore", "saint Dioscore", "Dioscore d''Alexandrie", "Dioscore Ier"], "explanation": "Dioscore est déposé en 451, exilé à Gangra et meurt en 454. L''Église copte le vénère comme confesseur.", "tip": "Dioscore = confesseur de la foi.", "extraExample": {"text": "Dioscore succède à saint Cyrille en 444.", "translation": "Il fut patriarche dix ans."}, "id": "eg.l54.e09", "pool": "lesson", "lessonId": "eg.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e10', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.melkites']::text[], 'free_answer', 'lesson', 'Comment les Égyptiens appellent-ils les chrétiens du parti de l''empereur, restés chalcédoniens ?', array['melkites','les melkites','melkite']::text[], 'Melkite vient du mot « roi » : le patriarche de l''empereur.', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.melkites"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment les Égyptiens appellent-ils les chrétiens du parti de l''empereur, restés chalcédoniens ?", "promptLanguage": "fr", "hint": "Le mot veut dire « roi ».", "answer": "melkites", "acceptedAnswers": ["melkites", "les melkites", "melkite"], "explanation": "Melkite vient du mot « roi » : le patriarche de l''empereur.", "tip": "Melkite = royal.", "extraExample": {"text": "Le patriarche grec d''Alexandrie descend des melkites.", "translation": "Il n''est pas notre pape."}, "id": "eg.l54.e10", "pool": "lesson", "lessonId": "eg.l54", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e11', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.sept_conciles']::text[], 'mcq', 'lesson', 'Combien de conciles les orthodoxes chalcédoniens reçoivent-ils ?', array['Sept']::text[], 'Ils vont jusqu''à Nicée II, en 787. Nous en gardons trois.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.sept_conciles"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de conciles les orthodoxes chalcédoniens reçoivent-ils ?", "promptLanguage": "fr", "options": ["Sept", "Trois", "Quatre", "Neuf"], "answer": "Sept", "acceptedAnswers": ["Sept"], "explanation": "Ils vont jusqu''à Nicée II, en 787. Nous en gardons trois.", "tip": "7 contre 3.", "extraExample": {"text": "Nicée II traite des icônes.", "translation": "Il est reçu par les chalcédoniens."}, "errorPatterns": [{"equals": "Trois", "category": "word_confusion", "feedback": "Trois est le nombre des conciles reçus par les orthodoxes orientaux."}], "id": "eg.l54.e11", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e12', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.trois_conciles']::text[], 'fill_blank', 'lesson', 'Les orthodoxes orientaux reçoivent Nicée, Constantinople et ___.', array['Éphèse']::text[], 'Éphèse (431) proclame Marie Mère de Dieu et condamne Nestorius.', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.trois_conciles"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les orthodoxes orientaux reçoivent Nicée, Constantinople et ___.", "promptLanguage": "fr", "options": ["Éphèse", "Chalcédoine", "Latran", "Nicée II"], "answer": "Éphèse", "acceptedAnswers": ["Éphèse"], "explanation": "Éphèse (431) proclame Marie Mère de Dieu et condamne Nestorius.", "tip": "Nicée, Constantinople, Éphèse.", "extraExample": {"text": "Éphèse précède Chalcédoine de vingt ans.", "translation": "Il est reçu par tous les orthodoxes."}, "id": "eg.l54.e12", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e13', 'eg', 'eg.l54', 'eg.v.patriarcat_grec_d_alexandrie', array['eg.v.patriarcat_grec_d_alexandrie','eg.g54.chalcedoine_orthodoxes']::text[], 'mcq', 'lesson', 'Qui sont les deux patriarches d''Alexandrie depuis 451 ?', array['L''un copte, l''autre grec']::text[], 'L''empereur a imposé un patriarche chalcédonien ; les Égyptiens ont gardé Dioscore. Les deux lignes existent encore.', 3, '{"unitIds": ["eg.v.patriarcat_grec_d_alexandrie", "eg.g54.chalcedoine_orthodoxes"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui sont les deux patriarches d''Alexandrie depuis 451 ?", "promptLanguage": "fr", "options": ["L''un copte, l''autre grec", "L''un copte, l''autre catholique", "L''un grec, l''autre russe", "L''un syriaque, l''autre arménien"], "answer": "L''un copte, l''autre grec", "acceptedAnswers": ["L''un copte, l''autre grec"], "explanation": "L''empereur a imposé un patriarche chalcédonien ; les Égyptiens ont gardé Dioscore. Les deux lignes existent encore.", "tip": "Deux lignes, copte et grecque.", "extraExample": {"text": "Le patriarche grec est en communion avec Constantinople.", "translation": "Notre pape est en communion avec les Églises orientales."}, "id": "eg.l54.e13", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e14', 'eg', 'eg.l54', 'eg.v.dialogue_chambesy', array['eg.v.dialogue_chambesy','eg.g54.chalcedoine_orthodoxes']::text[], 'fill_blank', 'lesson', 'En 1989 puis 1990, des théologiens ont constaté à Wadi Natroun et à Chambésy que les deux familles ont la même ___.', array['foi']::text[], 'Les commissions mixtes ont déclaré que les deux familles confessent la même foi dans le Christ.', 3, '{"unitIds": ["eg.v.dialogue_chambesy", "eg.g54.chalcedoine_orthodoxes"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "En 1989 puis 1990, des théologiens ont constaté à Wadi Natroun et à Chambésy que les deux familles ont la même ___.", "promptLanguage": "fr", "options": ["foi", "liturgie", "langue", "date de Pâques"], "answer": "foi", "acceptedAnswers": ["foi"], "explanation": "Les commissions mixtes ont déclaré que les deux familles confessent la même foi dans le Christ.", "tip": "Même foi, mots différents.", "extraExample": {"text": "Il reste à régler la réception des conciles.", "translation": "Le chemin est encore long."}, "id": "eg.l54.e14", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e15', 'eg', 'eg.l54', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes']::text[], 'reorder', 'lesson', 'Phrase-repère : la formule de saint Cyrille.', array['Une seule nature du Verbe incarné']::text[], 'La formule de saint Cyrille est « une seule nature du Verbe incarné ».', 2, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : la formule de saint Cyrille.", "promptLanguage": "fr", "tokens": ["nature", "seule", "incarné", "du", "Verbe", "Une"], "answer": "Une seule nature du Verbe incarné", "acceptedAnswers": ["Une seule nature du Verbe incarné"], "explanation": "La formule de saint Cyrille est « une seule nature du Verbe incarné ».", "tip": "Une seule nature, sans mélange.", "extraExample": {"text": "La formule se dit « miaphysite ».", "translation": "Mia veut dire une."}, "id": "eg.l54.e15", "pool": "lesson", "lessonId": "eg.l54", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e16', 'eg', 'eg.l54', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglises_orthodoxes_orientales']::text[], 'mcq', 'lesson', 'Révision — Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?', array['Chalcédoine']::text[], 'Les Églises orthodoxes orientales gardent les trois premiers conciles et refusent Chalcédoine.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglises_orthodoxes_orientales"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Quel concile les Églises orthodoxes orientales n''ont-elles pas reçu ?", "promptLanguage": "fr", "options": ["Chalcédoine", "Nicée", "Constantinople", "Éphèse"], "answer": "Chalcédoine", "acceptedAnswers": ["Chalcédoine"], "explanation": "Les Églises orthodoxes orientales gardent les trois premiers conciles et refusent Chalcédoine.", "tip": "Orientales = sans Chalcédoine.", "extraExample": {"text": "Le refus date de 451.", "translation": "Il dure depuis plus de 1500 ans."}, "id": "eg.l54.e16", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l54.e17', 'eg', 'eg.l54', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_orthodoxe_chalcedonienne']::text[], 'mcq', 'lesson', 'Révision — Un orthodoxe grec est :', array['Un orthodoxe chalcédonien']::text[], 'Les orthodoxes grecs, russes ou serbes reçoivent Chalcédoine : ils sont chalcédoniens.', 2, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_orthodoxe_chalcedonienne"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Un orthodoxe grec est :", "promptLanguage": "fr", "options": ["Un orthodoxe chalcédonien", "Un orthodoxe oriental", "Un protestant", "Un catholique"], "answer": "Un orthodoxe chalcédonien", "acceptedAnswers": ["Un orthodoxe chalcédonien"], "explanation": "Les orthodoxes grecs, russes ou serbes reçoivent Chalcédoine : ils sont chalcédoniens.", "tip": "Grec, russe, serbe = chalcédoniens.", "extraExample": {"text": "Le patriarche de Constantinople en est le premier en honneur.", "translation": "Il n''a pas le pouvoir d''un pape."}, "id": "eg.l54.e17", "pool": "lesson", "lessonId": "eg.l54", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
