insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e04', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.purgatoire']::text[], 'mcq', 'lesson', 'Qui juge les défunts selon l''Église copte ?', array['Dieu seul juge']::text[], 'Nous prions pour les défunts et laissons le jugement à Dieu seul.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.purgatoire"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui juge les défunts selon l''Église copte ?", "promptLanguage": "fr", "options": ["Dieu seul juge", "Le pape", "L''évêque", "La famille"], "answer": "Dieu seul juge", "acceptedAnswers": ["Dieu seul juge"], "explanation": "Nous prions pour les défunts et laissons le jugement à Dieu seul.", "tip": "Dieu seul juge.", "extraExample": {"text": "Le jugement dernier aura lieu au retour du Christ.", "translation": "Nous n''en décrivons pas le détail."}, "errorPatterns": [{"equals": "Le pape", "category": "word_confusion", "feedback": "Même un pape ne juge pas les défunts."}], "id": "eg.l56.e04", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e05', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.purgatoire']::text[], 'fill_blank', 'lesson', 'Le purgatoire est précisé au concile de ___ en 1274.', array['Lyon II','Lyon']::text[], 'Lyon II, en 1274, précise la doctrine du purgatoire.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.purgatoire"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le purgatoire est précisé au concile de ___ en 1274.", "promptLanguage": "fr", "options": ["Lyon II", "Nicée", "Éphèse", "Trente"], "answer": "Lyon II", "acceptedAnswers": ["Lyon II", "Lyon"], "explanation": "Lyon II, en 1274, précise la doctrine du purgatoire.", "tip": "1274 : Lyon II.", "extraExample": {"text": "Trente reprend l''enseignement au XVIe siècle.", "translation": "Mais c''est Lyon II qui le précise."}, "id": "eg.l56.e05", "pool": "lesson", "lessonId": "eg.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e06', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'mcq', 'lesson', 'En quelle année l''Immaculée Conception est-elle définie ?', array['1854']::text[], 'Le 8 décembre 1854, Pie IX proclame le dogme.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année l''Immaculée Conception est-elle définie ?", "promptLanguage": "fr", "options": ["1854", "1870", "1054", "1950"], "answer": "1854", "acceptedAnswers": ["1854"], "explanation": "Le 8 décembre 1854, Pie IX proclame le dogme.", "tip": "1854 : Marie.", "extraExample": {"text": "1870 : infaillibilité.", "translation": "1950 : Assomption."}, "errorPatterns": [{"equals": "1870", "category": "word_confusion", "feedback": "1870 est la date de l''infaillibilité du pape."}, {"equals": "1950", "category": "word_confusion", "feedback": "1950 est l''Assomption de Marie."}], "id": "eg.l56.e06", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e07', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'fill_blank', 'lesson', 'L''Immaculée Conception est définie par le pape ___ en 1854.', array['Pie IX']::text[], 'Pie IX proclame le dogme en 1854 ; le même pape convoque Vatican I.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "L''Immaculée Conception est définie par le pape ___ en 1854.", "promptLanguage": "fr", "options": ["Pie IX", "Léon", "Jean-Paul II", "Grégoire"], "answer": "Pie IX", "acceptedAnswers": ["Pie IX"], "explanation": "Pie IX proclame le dogme en 1854 ; le même pape convoque Vatican I.", "tip": "Pie IX : 1854, puis 1870.", "extraExample": {"text": "Il convoque aussi Vatican I.", "translation": "Deux dogmes sous un même pape."}, "id": "eg.l56.e07", "pool": "lesson", "lessonId": "eg.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e08', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'mcq', 'lesson', 'Que signifie l''Immaculée Conception ?', array['Marie a été conçue sans péché originel']::text[], 'Elle concerne la conception de Marie. La naissance virginale concerne Jésus.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie l''Immaculée Conception ?", "promptLanguage": "fr", "options": ["Marie a été conçue sans péché originel", "Jésus est né d''une vierge", "Marie est montée au ciel", "Jésus n''a pas de père"], "answer": "Marie a été conçue sans péché originel", "acceptedAnswers": ["Marie a été conçue sans péché originel"], "explanation": "Elle concerne la conception de Marie. La naissance virginale concerne Jésus.", "tip": "Immaculée = Marie.", "extraExample": {"text": "L''Assomption est un autre dogme.", "translation": "Elle est définie en 1950."}, "errorPatterns": [{"equals": "Jésus est né d''une vierge", "category": "word_confusion", "feedback": "C''est la naissance virginale, différente de l''Immaculée Conception."}, {"equals": "Marie est montée au ciel", "category": "word_confusion", "feedback": "C''est l''Assomption, un autre dogme."}], "id": "eg.l56.e08", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e09', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.peche_originel']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on la faute d''Adam transmise à tout homme, selon saint Augustin ?', array['péché originel','le péché originel','peche originel']::text[], 'Pour Augustin, le péché originel se transmet à la naissance. Les orthodoxes y voient plutôt un héritage de mortalité.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.peche_originel"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on la faute d''Adam transmise à tout homme, selon saint Augustin ?", "promptLanguage": "fr", "hint": "Deux mots, le deuxième commence par o.", "answer": "péché originel", "acceptedAnswers": ["péché originel", "le péché originel", "peche originel"], "explanation": "Pour Augustin, le péché originel se transmet à la naissance. Les orthodoxes y voient plutôt un héritage de mortalité.", "tip": "Originel : dès l''origine.", "extraExample": {"text": "Le baptême en guérit les conséquences.", "translation": "Il ne s''agit pas de culpabilité héritée pour les orthodoxes."}, "id": "eg.l56.e09", "pool": "lesson", "lessonId": "eg.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e10', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques']::text[], 'mcq', 'lesson', 'Quel verset montre que Marie reconnaît avoir un Sauveur ?', array['« Mon esprit se réjouit en Dieu, mon Sauveur »']::text[], 'Luc 1, 47 : Marie loue Dieu comme son Sauveur. C''est pourquoi nous croyons que Marie a besoin d''un Sauveur, comme tous.', 3, '{"unitIds": ["eg.g56.dogmes_usages_catholiques"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset montre que Marie reconnaît avoir un Sauveur ?", "promptLanguage": "fr", "options": ["« Mon esprit se réjouit en Dieu, mon Sauveur »", "« Tu es Pierre »", "« Que ta volonté soit faite »", "« Au commencement était le Verbe »"], "answer": "« Mon esprit se réjouit en Dieu, mon Sauveur »", "acceptedAnswers": ["« Mon esprit se réjouit en Dieu, mon Sauveur »"], "explanation": "Luc 1, 47 : Marie loue Dieu comme son Sauveur. C''est pourquoi nous croyons que Marie a besoin d''un Sauveur, comme tous.", "tip": "Marie a un Sauveur.", "extraExample": {"text": "Elle le dit dans le Magnificat.", "translation": "Nous le chantons dans la liturgie."}, "errorPatterns": [{"equals": "« Tu es Pierre »", "category": "word_confusion", "feedback": "C''est la parole de Jésus à Pierre (Matthieu 16, 18)."}], "id": "eg.l56.e10", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e11', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.azymes']::text[], 'mcq', 'lesson', 'Quel pain les catholiques latins utilisent-ils pour l''Eucharistie ?', array['Du pain azyme, sans levain']::text[], 'L''hostie latine est un pain azyme : sans levain, mince et ronde.', 1, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.azymes"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel pain les catholiques latins utilisent-ils pour l''Eucharistie ?", "promptLanguage": "fr", "options": ["Du pain azyme, sans levain", "Du pain levé", "Du pain d''orge", "Du pain de maïs"], "answer": "Du pain azyme, sans levain", "acceptedAnswers": ["Du pain azyme, sans levain"], "explanation": "L''hostie latine est un pain azyme : sans levain, mince et ronde.", "tip": "Azyme = a-zymê : sans levain.", "extraExample": {"text": "Les Arméniens utilisent aussi des azymes.", "translation": "Ils sont pourtant orthodoxes orientaux."}, "errorPatterns": [{"equals": "Du pain levé", "category": "word_confusion", "feedback": "Le pain levé est celui de l''Église copte."}], "id": "eg.l56.e11", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e12', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.pain_leve']::text[], 'fill_blank', 'lesson', 'L''Église copte utilise un pain ___ pour l''Eucharistie.', array['levé','pain levé']::text[], 'Notre pain est levé, comme celui des orthodoxes grecs.', 1, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.pain_leve"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "L''Église copte utilise un pain ___ pour l''Eucharistie.", "promptLanguage": "fr", "options": ["levé", "azyme", "sec"], "answer": "levé", "acceptedAnswers": ["levé", "pain levé"], "explanation": "Notre pain est levé, comme celui des orthodoxes grecs.", "tip": "Pain levé = pain vivant.", "extraExample": {"text": "L''offrande est estampillée d''une croix.", "translation": "On l''appelle qorban."}, "id": "eg.l56.e12", "pool": "lesson", "lessonId": "eg.l56", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e13', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.pain_leve']::text[], 'mcq', 'lesson', 'Que symbolise le pain levé pour l''Église copte ?', array['Il est vivant : il évoque la Résurrection']::text[], 'Le pain levé est vivant. Il évoque la Résurrection. L''Église d''Orient l''utilise depuis les origines.', 3, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.pain_leve"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que symbolise le pain levé pour l''Église copte ?", "promptLanguage": "fr", "options": ["Il est vivant : il évoque la Résurrection", "Il est pauvre", "Il est réservé aux fêtes", "Il vient d''Égypte ancienne"], "answer": "Il est vivant : il évoque la Résurrection", "acceptedAnswers": ["Il est vivant : il évoque la Résurrection"], "explanation": "Le pain levé est vivant. Il évoque la Résurrection. L''Église d''Orient l''utilise depuis les origines.", "tip": "Levé : vivant.", "extraExample": {"text": "Le levain fait monter la pâte.", "translation": "La Résurrection fait monter l''homme à la vie."}, "id": "eg.l56.e13", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e14', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.celibat_des_pretres']::text[], 'mcq', 'lesson', 'Dans l''Église latine, les prêtres sont en général :', array['Célibataires']::text[], 'La règle du célibat est affermie au XIIe siècle dans l''Église latine.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.celibat_des_pretres"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans l''Église latine, les prêtres sont en général :", "promptLanguage": "fr", "options": ["Célibataires", "Mariés", "Veufs", "Moines"], "answer": "Célibataires", "acceptedAnswers": ["Célibataires"], "explanation": "La règle du célibat est affermie au XIIe siècle dans l''Église latine.", "tip": "Latin : célibat.", "extraExample": {"text": "Certaines Églises catholiques orientales ordonnent des hommes mariés.", "translation": "Le célibat n''est pas un dogme."}, "errorPatterns": [{"equals": "Mariés", "category": "word_confusion", "feedback": "C''est le cas chez les Coptes, pas la règle générale latine."}], "id": "eg.l56.e14", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e15', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.celibat_des_pretres']::text[], 'mcq', 'lesson', 'Quand un homme marié peut-il devenir prêtre dans l''Église copte ?', array['S''il est marié avant l''ordination']::text[], 'Un homme marié avant l''ordination peut devenir prêtre. Il ne se marie pas après.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.celibat_des_pretres"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quand un homme marié peut-il devenir prêtre dans l''Église copte ?", "promptLanguage": "fr", "options": ["S''il est marié avant l''ordination", "Jamais", "Seulement après avoir divorcé", "Seulement s''il se marie après"], "answer": "S''il est marié avant l''ordination", "acceptedAnswers": ["S''il est marié avant l''ordination"], "explanation": "Un homme marié avant l''ordination peut devenir prêtre. Il ne se marie pas après.", "tip": "Marié avant, jamais après.", "extraExample": {"text": "Saint Pierre était marié.", "translation": "Sa belle-mère est guérie en Matthieu 8, 14."}, "errorPatterns": [{"equals": "Jamais", "category": "word_confusion", "feedback": "Chez les Coptes, la tradition ancienne autorise l''ordination d''hommes mariés."}], "id": "eg.l56.e15", "pool": "lesson", "lessonId": "eg.l56", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.co