insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l56.e16', 'eg', 'eg.l56', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.celibat_des_pretres']::text[], 'free_answer', 'lesson', 'Parmi qui les évêques coptes sont-ils choisis ?', array['les moines','des moines','moines','parmi les moines']::text[], 'Les évêques sont choisis parmi les moines, donc célibataires.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.celibat_des_pretres"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Parmi qui les évêques coptes sont-ils choisis ?", "promptLanguage": "fr", "hint": "Ils vivent dans les monastères.", "answer": "les moines", "acceptedAnswers": ["les moines", "des moines", "moines", "parmi les moines"], "explanation": "Les évêques sont choisis parmi les moines, donc célibataires.", "tip": "Évêque = moine.", "extraExample": {"text": "Le pape est choisi parmi eux.", "translation": "Le monastère forme les évêques."}, "id": "eg.l56.e16", "pool": "lesson", "lessonId": "eg.l56", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
