insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e05', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.jean_calvin']::text[], 'mcq', 'lesson', 'Dans quelle ville Jean Calvin organise-t-il une Église réformée ?', array['Genève']::text[], 'Calvin s''établit à Genève et publie en 1536 l''Institution de la religion chrétienne.', 2, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.jean_calvin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans quelle ville Jean Calvin organise-t-il une Église réformée ?", "promptLanguage": "fr", "options": ["Genève", "Wittenberg", "Londres", "Rome"], "answer": "Genève", "acceptedAnswers": ["Genève"], "explanation": "Calvin s''établit à Genève et publie en 1536 l''Institution de la religion chrétienne.", "tip": "Calvin : Genève.", "extraExample": {"text": "Luther était à Wittenberg.", "translation": "Henri VIII régnait à Londres."}, "errorPatterns": [{"equals": "Wittenberg", "category": "word_confusion", "feedback": "Wittenberg est la ville de Luther."}], "id": "eg.l57.e05", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e06', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.reforme']::text[], 'fill_blank', 'lesson', 'En 1534, le roi ___ rompt avec Rome : c''est l''origine des anglicans.', array['Henri VIII']::text[], 'Henri VIII rompt avec Rome en 1534. L''Église d''Angleterre naît de là.', 2, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.reforme"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "En 1534, le roi ___ rompt avec Rome : c''est l''origine des anglicans.", "promptLanguage": "fr", "options": ["Henri VIII", "Louis XIV", "Charles Quint", "Constantin"], "answer": "Henri VIII", "acceptedAnswers": ["Henri VIII"], "explanation": "Henri VIII rompt avec Rome en 1534. L''Église d''Angleterre naît de là.", "tip": "Henri VIII : 1534.", "extraExample": {"text": "Charles Quint était empereur à l''époque.", "translation": "Il combat Luther."}, "id": "eg.l57.e06", "pool": "lesson", "lessonId": "eg.l57", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e07', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.sola_scriptura']::text[], 'mcq', 'lesson', 'Que veut dire sola scriptura ?', array['L''Écriture seule']::text[], 'Sola scriptura, « l''Écriture seule » : la Bible est la seule autorité pour les protestants.', 1, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.sola_scriptura"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire sola scriptura ?", "promptLanguage": "fr", "options": ["L''Écriture seule", "La foi seule", "La grâce seule", "La Tradition seule"], "answer": "L''Écriture seule", "acceptedAnswers": ["L''Écriture seule"], "explanation": "Sola scriptura, « l''Écriture seule » : la Bible est la seule autorité pour les protestants.", "tip": "Scriptura : écriture.", "extraExample": {"text": "Sola fide veut dire « par la foi seule ».", "translation": "Ce sont deux principes différents."}, "errorPatterns": [{"equals": "La foi seule", "category": "word_confusion", "feedback": "C''est sola fide."}], "id": "eg.l57.e07", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e08', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.sainte_tradition']::text[], 'mcq', 'lesson', 'Sur quoi l''Église copte s''appuie-t-elle ?', array['L''Écriture et la Sainte Tradition']::text[], 'La Bible est née dans l''Église, qui en a reconnu les livres. Écriture et Tradition viennent du même Esprit.', 2, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.sainte_tradition"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Sur quoi l''Église copte s''appuie-t-elle ?", "promptLanguage": "fr", "options": ["L''Écriture et la Sainte Tradition", "L''Écriture seule", "La Tradition seule", "Le pape de Rome"], "answer": "L''Écriture et la Sainte Tradition", "acceptedAnswers": ["L''Écriture et la Sainte Tradition"], "explanation": "La Bible est née dans l''Église, qui en a reconnu les livres. Écriture et Tradition viennent du même Esprit.", "tip": "Copte : les deux.", "extraExample": {"text": "Paul parle de la parole et de la lettre.", "translation": "2 Thessaloniciens 2, 15."}, "errorPatterns": [{"equals": "L''Écriture seule", "category": "word_confusion", "feedback": "C''est le principe protestant, pas le nôtre."}], "id": "eg.l57.e08", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e09', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.sainte_tradition']::text[], 'mcq', 'lesson', 'Quel passage de Paul demande de garder les traditions reçues ?', array['2 Thessaloniciens 2, 15']::text[], 'Paul écrit : gardez les traditions que vous avez reçues, par la parole ou par une lettre.', 3, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.sainte_tradition"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel passage de Paul demande de garder les traditions reçues ?", "promptLanguage": "fr", "options": ["2 Thessaloniciens 2, 15", "Romains 3, 28", "Jacques 2, 24", "Matthieu 16, 18"], "answer": "2 Thessaloniciens 2, 15", "acceptedAnswers": ["2 Thessaloniciens 2, 15"], "explanation": "Paul écrit : gardez les traditions que vous avez reçues, par la parole ou par une lettre.", "tip": "2 Thessaloniciens 2, 15.", "extraExample": {"text": "Romains 3, 28 est le verset de Luther.", "translation": "Jacques 2, 24 est celui qui unit foi et œuvres."}, "errorPatterns": [{"equals": "Romains 3, 28", "category": "word_confusion", "feedback": "C''est le verset de Luther sur la foi."}], "id": "eg.l57.e09", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e10', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.deuterocanoniques']::text[], 'free_answer', 'lesson', 'Combien de livres comporte l''Ancien Testament de la Bible protestante ?', array['39','trente-neuf','39 livres']::text[], 'Les protestants gardent les 39 livres de la Bible hébraïque ; les Coptes gardent aussi les deutérocanoniques.', 3, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.deuterocanoniques"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Combien de livres comporte l''Ancien Testament de la Bible protestante ?", "promptLanguage": "fr", "hint": "C''est un nombre entre 30 et 40.", "answer": "39", "acceptedAnswers": ["39", "trente-neuf", "39 livres"], "explanation": "Les protestants gardent les 39 livres de la Bible hébraïque ; les Coptes gardent aussi les deutérocanoniques.", "tip": "39 livres.", "extraExample": {"text": "Le Nouveau Testament compte 27 livres pour tous les chrétiens.", "translation": "Aucune Église ne le change."}, "id": "eg.l57.e10", "pool": "lesson", "lessonId": "eg.l57", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e11', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.deuterocanoniques']::text[], 'mcq', 'lesson', 'Quels livres l''Église copte garde-t-elle en plus des protestants ?', array['Tobie, Judith, la Sagesse']::text[], 'Les deutérocanoniques (Tobie, Judith, Sagesse, Siracide, Baruch, Maccabées) viennent de la Septante.', 2, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.deuterocanoniques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quels livres l''Église copte garde-t-elle en plus des protestants ?", "promptLanguage": "fr", "options": ["Tobie, Judith, la Sagesse", "Le Cantique des cantiques", "Les Psaumes", "L''Apocalypse"], "answer": "Tobie, Judith, la Sagesse", "acceptedAnswers": ["Tobie, Judith, la Sagesse"], "explanation": "Les deutérocanoniques (Tobie, Judith, Sagesse, Siracide, Baruch, Maccabées) viennent de la Septante.", "tip": "Deutéro : second.", "extraExample": {"text": "Le Cantique et les Psaumes sont dans toutes les Bibles.", "translation": "L''Apocalypse aussi."}, "errorPatterns": [{"equals": "Les Psaumes", "category": "word_confusion", "feedback": "Les Psaumes sont dans toutes les Bibles chrétiennes."}], "id": "eg.l57.e11", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e12', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.deuterocanoniques']::text[], 'mcq', 'lesson', 'Quelle Bible grecque, traduite à Alexandrie, contient ces livres ?', array['La Septante']::text[], 'La Septante, traduite à Alexandrie, contient les deutérocanoniques. Elle est la Bible des premiers chrétiens grecs.', 2, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.deuterocanoniques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle Bible grecque, traduite à Alexandrie, contient ces livres ?", "promptLanguage": "fr", "options": ["La Septante", "La Vulgate", "La Bible de Luther", "La Peshitta"], "answer": "La Septante", "acceptedAnswers": ["La Septante"], "explanation": "La Septante, traduite à Alexandrie, contient les deutérocanoniques. Elle est la Bible des premiers chrétiens grecs.", "tip": "Septante = Alexandrie.", "extraExample": {"text": "La Vulgate est la Bible latine de saint Jérôme.", "translation": "La Peshitta est la Bible syriaque."}, "errorPatterns": [{"equals": "La Vulgate", "category": "word_confusion", "feedback": "La Vulgate est la traduction latine de saint Jérôme."}], "id": "eg.l57.e12", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e13', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.sola_fide']::text[], 'mcq', 'lesson', 'Que veut dire sola fide ?', array['Le salut par la foi seule']::text[], 'Sola fide, « par la foi seule » : c''est le cœur du protestantisme selon Luther (Romains 3, 28).', 2, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.sola_fide"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire sola fide ?", "promptLanguage": "fr", "options": ["Le salut par la foi seule", "L''Écriture seule", "La Tradition seule", "Les œuvres seules"], "answer": "Le salut par la foi seule", "acceptedAnswers": ["Le salut par la foi seule"], "explanation": "Sola fide, « par la foi seule » : c''est le cœur du protestantisme selon Luther (Romains 3, 28).", "tip": "Fide : foi.", "extraExample": {"text": "Luther cite Romains 3, 28.", "translation": "Il refuse qu''on achète le salut."}, "errorPatterns": [{"equals": "Les œuvres seules", "category": "word_confusion", "feedback": "Personne ne soutient cela, ni nous ni les protestants."}], "id": "eg.l57.e13", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e14', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.sola_fide']::text[], 'mcq', 'lesson', 'Quel verset l''Église copte cite-t-elle pour unir foi et œuvres ?', array['Jacques 2, 24']::text[], 'Jacques 2, 24 : l''homme est justifié par les œuvres et non par la foi seulement.', 3, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.sola_fide"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset l''Église copte cite-t-elle pour unir foi et œuvres ?", "promptLanguage": "fr", "options": ["Jacques 2, 24", "Romains 3, 28", "Luc 1, 47", "Jean 15, 26"], "answer": "Jacques 2, 24", "acceptedAnswers": ["Jacques 2, 24"], "explanation": "Jacques 2, 24 : l''homme est justifié par les œuvres et non par la foi seulement.", "tip": "Jacques = œuvres.", "extraExample": {"text": "Jacques 2, 17 : la foi sans les œuvres est morte.", "translation": "Les œuvres sont le fruit de la grâce."}, "errorPatterns": [{"equals": "Romains 3, 28", "category": "word_confusion", "feedback": "Romains 3, 28 est le verset de Luther."}], "id": "eg.l57.e14", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e15', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.sola_fide']::text[], 'fill_blank', 'lesson', 'Pour les Coptes, la foi et les ___ vont ensemble.', array['œuvres','oeuvres','les œuvres']::text[], 'Les œuvres de charité sont le fruit de la grâce et de la foi.', 3, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.sola_fide"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Pour les Coptes, la foi et les ___ vont ensemble.", "promptLanguage": "fr", "options": ["œuvres", "indulgences", "thèses"], "answer": "œuvres", "acceptedAnswers": ["œuvres", "oeuvres", "les œuvres"], "explanation": "Les œuvres de charité sont le fruit de la grâce et de la foi.", "tip": "Foi + œuvres.", "extraExample": {"text": "Le salut est un chemin.", "translation": "La grâce vient d''abord."}, "id": "eg.l57.e15", "pool": "lesson", "lessonId": "eg.l57", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e16', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante']::text[], 'free_answer', 'lesson', 'Quelle Église protestante ne baptise que les adultes qui croient ?', array['baptistes','les baptistes','baptiste','l''Église baptiste']::text[], 'Les baptistes ne baptisent que les adultes qui croient, alors que les luthériens et les anglicans baptisent les enfants.', 2, '{"unitIds": ["eg.g57.reforme_protestante"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quelle Église protestante ne baptise que les adultes qui croient ?", "promptLanguage": "fr", "hint": "Son nom vient du baptême.", "answer": "baptistes", "acceptedAnswers": ["baptistes", "les baptistes", "baptiste", "l''Église baptiste"], "explanation": "Les baptistes ne baptisent que les adultes qui croient, alors que les luthériens et les anglicans baptisent les enfants.", "tip": "Baptiste : baptême des croyants.", "extraExample": {"text": "Les Coptes baptisent les enfants.", "translation": "Souvent à 40 jours pour un garçon."}, "id": "eg.l57.e16", "pool": "lesson", "lessonId": "eg.l57", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e17', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante']::text[], 'reorder', 'lesson', 'Phrase-repère : la foi copte.', array['Pour les Coptes la Bible et la Tradition vont ensemble']::text[], 'Pour les Coptes, la Bible et la Tradition vont ensemble.', 2, '{"unitIds": ["eg.g57.reforme_protestante"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : la foi copte.", "promptLanguage": "fr", "tokens": ["les", "la", "Pour", "vont", "Bible", "Coptes", "la", "et", "ensemble", "Tradition"], "answer": "Pour les Coptes la Bible et la Tradition vont ensemble", "acceptedAnswers": ["Pour les Coptes la Bible et la Tradition vont ensemble"], "explanation": "Pour les Coptes, la Bible et la Tradition vont ensemble.", "tip": "Bible + Tradition.", "extraExample": {"text": "Les protestants disent : la Bible seule.", "translation": "Voilà la différence."}, "id": "eg.l57.e17", "pool": "lesson", "lessonId": "eg.l57", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e18', 'eg', 'eg.l57', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante']::text[], 'match', 'lesson', 'Chaque personnage et sa ville ou son pays', '{}'::text[], 'Luther à Wittenberg, Calvin à Genève, Henri VIII en Angleterre, la Septante à Alexandrie.', 2, '{"unitIds": ["eg.g57.reforme_protestante"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque personnage et sa ville ou son pays", "promptLanguage": "fr", "pairs": [{"left": "Luther", "right": "Wittenberg"}, {"left": "Calvin", "right": "Genève"}, {"left": "Henri VIII", "right": "Angleterre"}, {"left": "la Septante", "right": "Alexandrie"}], "answer": "Luther = Wittenberg ; Calvin = Genève ; Henri VIII = Angleterre ; la Septante = Alexandrie", "acceptedAnswers": [], "explanation": "Luther à Wittenberg, Calvin à Genève, Henri VIII en Angleterre, la Septante à Alexandrie.", "tip": "Quatre lieux, quatre noms.", "id": "eg.l57.e18", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e19', 'eg', 'eg.l57', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'mcq', 'lesson', 'Révision — En quelle année Pie IX définit-il l''Immaculée Conception ?', array['1854']::text[], 'Pie IX proclame l''Immaculée Conception de Marie le 8 décembre 1854.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — En quelle année Pie IX définit-il l''Immaculée Conception ?", "promptLanguage": "fr", "options": ["1854", "1870", "1950", "1274"], "answer": "1854", "acceptedAnswers": ["1854"], "explanation": "Pie IX proclame l''Immaculée Conception de Marie le 8 décembre 1854.", "tip": "1854 : Marie.", "extraExample": {"text": "1950 est l''Assomption.", "translation": "1870 est l''infaillibilité."}, "errorPatterns": [{"equals": "1870", "category": "word_confusion", "feedback": "1870 est l''infaillibilité du pape."}], "id": "eg.l57.e19", "pool": "lesson", "lessonId": "eg.l57", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e20', 'eg', 'eg.l57', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.schisme_de_1054']::text[], 'fill_blank', 'lesson', 'Révision — Les excommunications de 1054 opposent Rome et ___.', array['Constantinople']::text[], 'En 1054, le légat du pape et le patriarche de Constantinople s''excommunient.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.schisme_de_1054"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Révision — Les excommunications de 1054 opposent Rome et ___.", "promptLanguage": "fr", "options": ["Constantinople", "Alexandrie", "Genève", "Wittenberg"], "answer": "Constantinople", "acceptedAnswers": ["Constantinople"], "explanation": "En 1054, le légat du pape et le patriarche de Constantinople s''excommunient.", "tip": "1054 : Rome et Constantinople.", "extraExample": {"text": "Elles sont levées en 1965.", "translation": "Paul VI et Athénagoras."}, "id": "eg.l57.e20", "pool": "lesson", "lessonId": "eg.l57", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l57.e21', 'eg', 'eg.l57', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.melkites']::text[], 'free_answer', 'lesson', 'Révision — Comment appelle-t-on, depuis 451, les chrétiens d''Égypte du parti de l''empereur ?', array['melkites','les melkites','melkite']::text[], 'Melkite vient du mot « roi » : le parti de l''empereur, fidèle à Chalcédoine.', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.melkites"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Révision — Comment appelle-t-on, depuis 451, les chrétiens d''Égypte du parti de l''empereur ?", "promptLanguage": "fr", "hint": "Le mot veut dire « roi ».", "answer": "melkites", "acceptedAnswers": ["melkites", "les melkites", "melkite"], "explanation": "Melkite vient du mot « roi » : le parti de l''empereur, fidèle à Chalcédoine.", "tip": "Melkite = royal.", "extraExample": {"text": "Le patriarche grec d''Alexandrie en descend.", "translation": "Notre pape descend de Dioscore."}, "id": "eg.l57.e21", "pool": "lesson", "lessonId": "eg.l57", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e01', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.sept_sacrements','eg.v.deux_sacrements','eg.v.icone','eg.v.succession_apostolique']::text[], 'match', 'lesson', 'Les mots-clés de la leçon', '{}'::text[], 'Ces quatre repères résument la leçon.', 1, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.sept_sacrements", "eg.v.deux_sacrements", "eg.v.icone", "eg.v.succession_apostolique"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les mots-clés de la leçon", "promptLanguage": "fr", "pairs": [{"left": "sept sacrements", "right": "baptême, chrismation, eucharistie, confession, onction, mariage, sacerdoce"}, {"left": "deux sacrements", "right": "le baptême et la Cène"}, {"left": "vénérer", "right": "honorer sans adorer"}, {"left": "succession apostolique", "right": "ordinations en chaîne depuis les apôtres"}], "answer": "sept sacrements = baptême, chrismation, eucharistie, confession, onction, mariage, sacerdoce ; deux sacrements = le baptême et la Cène ; vénérer = honorer sans adorer ; succession apostolique = ordinations en chaîne depuis les apôtres", "acceptedAnswers": [], "explanation": "Ces quatre repères résument la leçon.", "tip": "7 contre 2.", "id": "eg.l58.e01", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e02', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.sept_sacrements']::text[], 'mcq', 'lesson', 'Combien de sacrements compte l''Église copte ?', array['Sept']::text[], 'Baptême, chrismation, eucharistie, confession, onction des malades, mariage et sacerdoce.', 1, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.sept_sacrements"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de sacrements compte l''Église copte ?", "promptLanguage": "fr", "options": ["Sept", "Deux", "Trois", "Douze"], "answer": "Sept", "acceptedAnswers": ["Sept"], "explanation": "Baptême, chrismation, eucharistie, confession, onction des malades, mariage et sacerdoce.", "tip": "Sept sacrements.", "extraExample": {"text": "Les catholiques et les orthodoxes grecs aussi.", "translation": "Les protestants en gardent généralement deux."}, "errorPatterns": [{"equals": "Deux", "category": "word_confusion", "feedback": "Deux est le nombre retenu par la plupart des protestants."}], "id": "eg.l58.e02", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e03', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.deux_sacrements']::text[], 'mcq', 'lesson', 'Quels sacrements retiennent la plupart des protestants ?', array['Le baptême et la Cène']::text[], 'La plupart des protestants gardent le baptême et la Cène, les deux actes que Jésus a institués explicitement.', 1, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.deux_sacrements"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quels sacrements retiennent la plupart des protestants ?", "promptLanguage": "fr", "options": ["Le baptême et la Cène", "La confession et le mariage", "Le sacerdoce et l''onction", "La chrismation et l''eucharistie"], "answer": "Le baptême et la Cène", "acceptedAnswers": ["Le baptême et la Cène"], "explanation": "La plupart des protestants gardent le baptême et la Cène, les deux actes que Jésus a institués explicitement.", "tip": "Baptême + Cène.", "extraExample": {"text": "La Cène est le mot protestant pour l''eucharistie.", "translation": "Luther y voit une présence réelle."}, "errorPatterns": [{"equals": "La confession et le mariage", "category": "word_confusion", "feedback": "Ces actes sont honorés par les protestants, mais ne sont pas des sacrements pour eux."}], "id": "eg.l58.e03", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e04', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.sept_sacrements']::text[], 'fill_blank', 'lesson', 'Les sept sacrements sont : baptême, chrismation, eucharistie, confession, onction des malades, mariage et ___.', array['sacerdoce','le sacerdoce']::text[], 'Le sacerdoce (ordination) est le septième sacrement. Il donne à des hommes la charge de l''Église.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.sept_sacrements"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les sept sacrements sont : baptême, chrismation, eucharistie, confession, onction des malades, mariage et ___.", "promptLanguage": "fr", "options": ["sacerdoce", "pèlerinage", "jeûne", "Cène"], "answer": "sacerdoce", "acceptedAnswers": ["sacerdoce", "le sacerdoce"], "explanation": "Le sacerdoce (ordination) est le septième sacrement. Il donne à des hommes la charge de l''Église.", "tip": "Sept : le dernier est le sacerdoce.", "extraExample": {"text": "Les évêques et les prêtres le reçoivent.", "translation": "Les diacres aussi, à leur degré."}, "id": "eg.l58.e04", "pool": "lesson", "lessonId": "eg.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e05', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.intercession_des_saints']::text[], 'mcq', 'lesson', 'Quel verset protestant cite-t-on pour un seul médiateur ?', array['1 Timothée 2, 5']::text[], 'Les protestants citent 1 Timothée 2, 5. Nous le croyons aussi : le Christ est le seul médiateur, et les saints prient avec nous.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.intercession_des_saints"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset protestant cite-t-on pour un seul médiateur ?", "promptLanguage": "fr", "options": ["1 Timothée 2, 5", "Luc 20, 38", "Jacques 2, 24", "Exode 25, 18"], "answer": "1 Timothée 2, 5", "acceptedAnswers": ["1 Timothée 2, 5"], "explanation": "Les protestants citent 1 Timothée 2, 5. Nous le croyons aussi : le Christ est le seul médiateur, et les saints prient avec nous.", "tip": "Un médiateur : Christ.", "extraExample": {"text": "Les saints prient comme des frères.", "translation": "Ils ne remplacent pas le Christ."}, "errorPatterns": [{"equals": "Luc 20, 38", "category": "word_confusion", "feedback": "Luc 20, 38 est le verset sur les vivants, que nous citons pour les saints."}], "id": "eg.l58.e05", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e06', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.intercession_des_saints']::text[], 'mcq', 'lesson', 'Pourquoi les Coptes demandent-ils la prière des saints ?', array['Les saints sont vivants en Christ']::text[], 'Dieu est le Dieu des vivants : les saints, vivants en Christ, prient pour nous comme des frères.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.intercession_des_saints"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi les Coptes demandent-ils la prière des saints ?", "promptLanguage": "fr", "options": ["Les saints sont vivants en Christ", "Les saints sont plus puissants que Dieu", "Le Christ est absent", "La Bible l''interdit"], "answer": "Les saints sont vivants en Christ", "acceptedAnswers": ["Les saints sont vivants en Christ"], "explanation": "Dieu est le Dieu des vivants : les saints, vivants en Christ, prient pour nous comme des frères.", "tip": "Vivants en Christ.", "extraExample": {"text": "Nous prions les uns pour les autres sur la terre.", "translation": "Au ciel, la prière continue."}, "errorPatterns": [{"equals": "Les saints sont plus puissants que Dieu", "category": "word_confusion", "feedback": "Aucun saint n''est plus puissant que Dieu : ils intercèdent."}], "id": "eg.l58.e06", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, 