insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e07', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.intercession_des_saints']::text[], 'mcq', 'lesson', 'Quel verset de Jésus dit que Dieu est le Dieu des vivants ?', array['Luc 20, 38']::text[], 'Luc 20, 38 : Dieu n''est pas le Dieu des morts, mais des vivants.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.intercession_des_saints"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset de Jésus dit que Dieu est le Dieu des vivants ?", "promptLanguage": "fr", "options": ["Luc 20, 38", "Luc 1, 48", "Exode 20, 4", "Romains 13, 7"], "answer": "Luc 20, 38", "acceptedAnswers": ["Luc 20, 38"], "explanation": "Luc 20, 38 : Dieu n''est pas le Dieu des morts, mais des vivants.", "tip": "20, 38 : vivants.", "extraExample": {"text": "Luc 1, 48 est la bénédiction de Marie.", "translation": "Elle précède de peu la naissance de Jésus."}, "errorPatterns": [{"equals": "Luc 1, 48", "category": "word_confusion", "feedback": "Luc 1, 48 est la bénédiction de Marie."}], "id": "eg.l58.e07", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e08', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.veneration']::text[], 'mcq', 'lesson', 'À qui l''adoration est-elle due ?', array['À Dieu seul']::text[], 'Nous adorons Dieu seul. Nous vénérons les saints et les icônes.', 1, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.veneration"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "À qui l''adoration est-elle due ?", "promptLanguage": "fr", "options": ["À Dieu seul", "Aux saints", "Aux icônes", "Aux évêques"], "answer": "À Dieu seul", "acceptedAnswers": ["À Dieu seul"], "explanation": "Nous adorons Dieu seul. Nous vénérons les saints et les icônes.", "tip": "Adorer : Dieu.", "extraExample": {"text": "La vénération est un honneur.", "translation": "Elle n''est pas une adoration."}, "errorPatterns": [{"equals": "Aux saints", "category": "word_confusion", "feedback": "On honore les saints, mais on n''adore pas."}], "id": "eg.l58.e08", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e09', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.veneration']::text[], 'fill_blank', 'lesson', 'Les Coptes ___ les saints mais n''adorent que Dieu.', array['vénèrent','vénérons','vénère']::text[], 'Nous vénérons les saints : nous les honorons, comme Paul le demande.', 1, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.veneration"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Les Coptes ___ les saints mais n''adorent que Dieu.", "promptLanguage": "fr", "options": ["vénèrent", "adorent", "ignorent"], "answer": "vénèrent", "acceptedAnswers": ["vénèrent", "vénérons", "vénère"], "explanation": "Nous vénérons les saints : nous les honorons, comme Paul le demande.", "tip": "Vénérer ≠ adorer.", "extraExample": {"text": "Honneur à qui l''honneur (Romains 13, 7).", "translation": "Cela concerne aussi les saints."}, "id": "eg.l58.e09", "pool": "lesson", "lessonId": "eg.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e10', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.icone']::text[], 'mcq', 'lesson', 'Pourquoi l''Église copte a-t-elle des icônes ?', array['Dieu s''est rendu visible en Jésus-Christ']::text[], 'Dieu s''est fait visible en Jésus-Christ. C''est le fondement des icônes.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.icone"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Église copte a-t-elle des icônes ?", "promptLanguage": "fr", "options": ["Dieu s''est rendu visible en Jésus-Christ", "La Bible l''ordonne partout", "On adore les images", "Rome l''impose"], "answer": "Dieu s''est rendu visible en Jésus-Christ", "acceptedAnswers": ["Dieu s''est rendu visible en Jésus-Christ"], "explanation": "Dieu s''est fait visible en Jésus-Christ. C''est le fondement des icônes.", "tip": "Incarnation = icônes.", "extraExample": {"text": "Jean 1, 14 : le Verbe s''est fait chair.", "translation": "Colossiens 1, 15 : il est l''image du Dieu invisible."}, "errorPatterns": [{"equals": "On adore les images", "category": "word_confusion", "feedback": "Nous n''adorons pas les icônes : l''honneur passe à celui qu''elles représentent."}], "id": "eg.l58.e10", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e11', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.icone']::text[], 'mcq', 'lesson', 'Quel passage de la Bible les réformés citent-ils contre les images ?', array['Exode 20, 4']::text[], 'Exode 20, 4 interdit de se faire des idoles. Nous répondons par Exode 25, 18 et par l''Incarnation.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.icone"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel passage de la Bible les réformés citent-ils contre les images ?", "promptLanguage": "fr", "options": ["Exode 20, 4", "Exode 25, 18", "Jean 1, 14", "Luc 1, 47"], "answer": "Exode 20, 4", "acceptedAnswers": ["Exode 20, 4"], "explanation": "Exode 20, 4 interdit de se faire des idoles. Nous répondons par Exode 25, 18 et par l''Incarnation.", "tip": "20, 4 : interdit ; 25, 18 : chérubins.", "extraExample": {"text": "Dieu demande des chérubins sculptés pour l''arche.", "translation": "Exode 25, 18."}, "errorPatterns": [{"equals": "Exode 25, 18", "category": "word_confusion", "feedback": "Exode 25, 18 est le texte que nous citons : Dieu demande des chérubins sculptés."}], "id": "eg.l58.e11", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e12', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.icone']::text[], 'free_answer', 'lesson', 'Quel saint Père dit que l''honneur rendu à l''image passe au modèle ?', array['Basile','saint Basile','Basile de Césarée']::text[], 'Saint Basile dit : l''honneur rendu à l''image passe au modèle. C''est le principe de la vénération des icônes.', 3, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.icone"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel saint Père dit que l''honneur rendu à l''image passe au modèle ?", "promptLanguage": "fr", "hint": "Son nom commence par B.", "answer": "Basile", "acceptedAnswers": ["Basile", "saint Basile", "Basile de Césarée"], "explanation": "Saint Basile dit : l''honneur rendu à l''image passe au modèle. C''est le principe de la vénération des icônes.", "tip": "Basile : image → modèle.", "extraExample": {"text": "Basile de Césarée est un Père du IVe siècle.", "translation": "La liturgie copte porte aussi son nom."}, "id": "eg.l58.e12", "pool": "lesson", "lessonId": "eg.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e13', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.succession_apostolique']::text[], 'mcq', 'lesson', 'Le pape Tawadros II est le successeur de saint Marc, numéro :', array['118']::text[], 'Tawadros II est le 118e successeur de saint Marc.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.succession_apostolique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Le pape Tawadros II est le successeur de saint Marc, numéro :", "promptLanguage": "fr", "options": ["118", "58", "12", "260"], "answer": "118", "acceptedAnswers": ["118"], "explanation": "Tawadros II est le 118e successeur de saint Marc.", "tip": "118e successeur.", "extraExample": {"text": "La liste commence avec saint Marc, vers 60.", "translation": "La chaîne n''est pas interrompue."}, "errorPatterns": [{"equals": "58", "category": "word_confusion", "feedback": "Le numéro est 118."}], "id": "eg.l58.e13", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e14', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.succession_apostolique']::text[], 'fill_blank', 'lesson', 'Les évêques coptes sont ordonnés par imposition des ___.', array['mains','des mains']::text[], 'L''imposition des mains transmet la grâce du sacerdoce, comme Paul le rappelle à Timothée (2 Timothée 1, 6).', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.succession_apostolique"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les évêques coptes sont ordonnés par imposition des ___.", "promptLanguage": "fr", "options": ["mains", "noms", "pieds"], "answer": "mains", "acceptedAnswers": ["mains", "des mains"], "explanation": "L''imposition des mains transmet la grâce du sacerdoce, comme Paul le rappelle à Timothée (2 Timothée 1, 6).", "tip": "Mains = ordination.", "extraExample": {"text": "Paul rappelle à Timothée le don reçu par l''imposition des mains.", "translation": "C''est un geste biblique."}, "id": "eg.l58.e14", "pool": "lesson", "lessonId": "eg.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e15', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.pasteur']::text[], 'mcq', 'lesson', 'Comment appelle-t-on le ministre d''une Église protestante ?', array['Un pasteur']::text[], 'Le pasteur prêche et dirige le culte. Il est appelé par la communauté.', 1, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.pasteur"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on le ministre d''une Église protestante ?", "promptLanguage": "fr", "options": ["Un pasteur", "Un évêque", "Un abouna", "Un diacre"], "answer": "Un pasteur", "acceptedAnswers": ["Un pasteur"], "explanation": "Le pasteur prêche et dirige le culte. Il est appelé par la communauté.", "tip": "Pasteur = berger.", "extraExample": {"text": "Le pasteur peut être marié.", "translation": "Le prêtre copte aussi, avant l''ordination."}, "errorPatterns": [{"equals": "Un abouna", "category": "word_confusion", "feedback": "Abouna est le nom du prêtre copte."}], "id": "eg.l58.e15", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e16', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.eglise_evangelique_d_egypte']::text[], 'free_answer', 'lesson', 'En quelle année la mission presbytérienne américaine s''installe-t-elle en Égypte ?', array['1854','en 1854']::text[], 'La mission arrive en 1854 et ouvre des écoles et des hôpitaux. L''Église évangélique en est née.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.eglise_evangelique_d_egypte"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "En quelle année la mission presbytérienne américaine s''installe-t-elle en Égypte ?", "promptLanguage": "fr", "hint": "C''est au XIXe siècle.", "answer": "1854", "acceptedAnswers": ["1854", "en 1854"], "explanation": "La mission arrive en 1854 et ouvre des écoles et des hôpitaux. L''Église évangélique en est née.", "tip": "1854 : mission presbytérienne.", "extraExample": {"text": "L''Église évangélique d''Égypte est presbytérienne.", "translation": "Elle suit la tradition de Calvin."}, "id": "eg.l58.e16", "pool": "lesson", "lessonId": "eg.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e17', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints']::text[], 'reorder', 'lesson', 'Phrase-repère : sacrements, saints et icônes.', array['Les saints prient pour nous comme des frères']::text[], 'Les saints prient pour nous comme des frères.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : sacrements, saints et icônes.", "promptLanguage": "fr", "tokens": ["pour", "frères", "nous", "Les", "des", "prient", "saints", "comme"], "answer": "Les saints prient pour nous comme des frères", "acceptedAnswers": ["Les saints prient pour nous comme des frères"], "explanation": "Les saints prient pour nous comme des frères.", "tip": "Intercéder : prier pour.", "extraExample": {"text": "Nous demandons aussi aux vivants de prier pour nous.", "translation": "La prière est un lien."}, "id": "eg.l58.e17", "pool": "lesson", "lessonId": "eg.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e18', 'eg', 'eg.l58', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.g57.reforme_protestante']::text[], 'match', 'lesson', 'Coptes ou protestants ?', '{}'::text[], 'Ces quatre couples résument la différence.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.g57.reforme_protestante"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Coptes ou protestants ?", "promptLanguage": "fr", "pairs": [{"left": "Écriture seule", "right": "principe protestant"}, {"left": "Écriture et Tradition", "right": "principe copte"}, {"left": "Sept sacrements", "right": "choix copte"}, {"left": "Deux sacrements", "right": "choix protestant"}], "answer": "Écriture seule = principe protestant ; Écriture et Tradition = principe copte ; Sept sacrements = choix copte ; Deux sacrements = choix protestant", "acceptedAnswers": [], "explanation": "Ces quatre couples résument la différence.", "tip": "Chaque camp, deux repères.", "id": "eg.l58.e18", "pool": "lesson", "lessonId": "eg.l58", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e19', 'eg', 'eg.l58', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.jean_calvin']::text[], 'free_answer', 'lesson', 'Révision — Quel réformateur français a organisé l''Église de Genève ?', array['Calvin','Jean Calvin']::text[], 'Jean Calvin s''établit à Genève et publie l''Institution de la religion chrétienne en 1536.', 2, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.jean_calvin"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Révision — Quel réformateur français a organisé l''Église de Genève ?", "promptLanguage": "fr", "hint": "Son prénom est Jean.", "answer": "Calvin", "acceptedAnswers": ["Calvin", "Jean Calvin"], "explanation": "Jean Calvin s''établit à Genève et publie l''Institution de la religion chrétienne en 1536.", "tip": "Calvin : Genève.", "extraExample": {"text": "Les presbytériens en descendent.", "translation": "L''Église évangélique d''Égypte aussi."}, "id": "eg.l58.e19", "pool": "lesson", "lessonId": "eg.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e20', 'eg', 'eg.l58', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.azymes']::text[], 'fill_blank', 'lesson', 'Révision — L''hostie des catholiques latins est un pain ___.', array['azyme','azymes','sans levain']::text[], 'Les latins consacrent du pain azyme, sans levain.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.azymes"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Révision — L''hostie des catholiques latins est un pain ___.", "promptLanguage": "fr", "options": ["azyme", "levé", "d''orge"], "answer": "azyme", "acceptedAnswers": ["azyme", "azymes", "sans levain"], "explanation": "Les latins consacrent du pain azyme, sans levain.", "tip": "Azyme : sans levain.", "extraExample": {"text": "L''Église copte utilise du pain levé.", "translation": "Ce point a pesé en 1054."}, "id": "eg.l58.e20", "pool": "lesson", "lessonId": "eg.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e21', 'eg', 'eg.l58', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.ex_cathedra']::text[], 'fill_blank', 'lesson', 'Révision — Pour les catholiques, le pape est infaillible quand il enseigne ___.', array['ex cathedra']::text[], 'L''infaillibilité vaut seulement pour l''enseignement solennel, ex cathedra.', 2, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.ex_cathedra"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Révision — Pour les catholiques, le pape est infaillible quand il enseigne ___.", "promptLanguage": "fr", "options": ["ex cathedra", "en privé", "en voyage"], "answer": "ex cathedra", "acceptedAnswers": ["ex cathedra"], "explanation": "L''infaillibilité vaut seulement pour l''enseignement solennel, ex cathedra.", "tip": "Ex cathedra : solennel.", "extraExample": {"text": "Ce dogme date de 1870.", "translation": "Il concerne la foi et la morale."}, "id": "eg.l58.e21", "pool": "lesson", "lessonId": "eg.l58", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l58.e22', 'eg', 'eg.l58', 'eg.g53.familles_eglises', array['eg.g53.familles_eglises','eg.v.eglise_malankare']::text[], 'free_answer', 'lesson', 'Révision — Quelle Église orthodoxe orientale de l''Inde rattache ses origines à l''apôtre Thomas ?', array['malankare','Église malankare','l''Église malankare']::text[], 'L''Église malankare est celle du Kerala, en Inde.', 3, '{"unitIds": ["eg.g53.familles_eglises", "eg.v.eglise_malankare"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Révision — Quelle Église orthodoxe orientale de l''Inde rattache ses origines à l''apôtre Thomas ?", "promptLanguage": "fr", "hint": "Son nom commence par M.", "answer": "malankare", "acceptedAnswers": ["malankare", "Église malankare", "l''Église malankare"], "explanation": "L''Église malankare est celle du Kerala, en Inde.", "tip": "Thomas, Inde, malankare.", "extraExample": {"text": "Elle est en communion avec le patriarcat d''Antioche.", "translation": "Elle partage la même foi que la nôtre."}, "id": "eg.l58.e22", "pool": "lesson", "lessonId": "eg.l58", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e01', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.joseph_smith','eg.v.william_miller','eg.v.ellen_white','eg.v.moroni']::text[], 'match', 'lesson', 'Mormons et adventistes : qui est qui ?', '{}'::text[], 'Deux noms pour les mormons, deux pour les adventistes.', 1, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.joseph_smith", "eg.v.william_miller", "eg.v.ellen_white", "eg.v.moroni"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Mormons et adventistes : qui est qui ?", "promptLanguage": "fr", "pairs": [{"left": "Joseph Smith", "right": "fondateur des mormons"}, {"left": "Moroni", "right": "l''ange des plaques d''or"}, {"left": "William Miller", "right": "annonce le retour du Christ en 1844"}, {"left": "Ellen White", "right": "prophétesse adventiste"}], "answer": "Joseph Smith = fondateur des mormons ; Moroni = l''ange des plaques d''or ; William Miller = annonce le retour du Christ en 1844 ; Ellen White = prophétesse adventiste", "acceptedAnswers": [], "explanation": "Deux noms pour les mormons, deux pour les adventistes.", "tip": "Smith, Moroni / Miller, White.", "id": "eg.l59.e01", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e02', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.mormons']::text[], 'mcq', 'lesson', 'En quelle année Joseph Smith publie-t-il le Livre de Mormon et fonde-t-il l''Église ?', array['1830']::text[], 'Le Livre de Mormon est publié et l''Église est fondée en 1830, dans l''État de New York.', 1, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.mormons"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Joseph Smith publie-t-il le Livre de Mormon et fonde-t-il l''Église ?", "promptLanguage": "fr", "options": ["1830", "1844", "1863", "1890"], "answer": "1830", "acceptedAnswers": ["1830"], "explanation": "Le Livre de Mormon est publié et l''Église est fondée en 1830, dans l''État de New York.", "tip": "1830 : mormons.", "extraExample": {"text": "1844 : Grande Déception.", "translation": "1863 : Église adventiste."}, "errorPatterns": [{"equals": "1844", "category": "word_confusion", "feedback": "1844 est la Grande Déception des adventistes."}, {"equals": "1863", "category": "word_confusion", "feedback": "1863 est l''organisation de l''Église adventiste."}], "id": "eg.l59.e02", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e03', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.livre_de_mormon']::text[], 'mcq', 'lesson', 'Quel livre les mormons ajoutent-ils à la Bible ?', array['Le Livre de Mormon']::text[], 'Les mormons y voient une autre Écriture. Pour nous, la Bible est complète.', 1, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.livre_de_mormon"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel livre les mormons ajoutent-ils à la Bible ?", "promptLanguage": "fr", "options": ["Le Livre de Mormon", "Le Coran", "Le Livre d''Hénoch", "Les 95 thèses"], "answer": "Le Livre de Mormon", "acceptedAnswers": ["Le Livre de Mormon"], "explanation": "Les mormons y voient une autre Écriture. Pour nous, la Bible est complète.", "tip": "Mormon : un livre de plus.", "extraExample": {"text": "Ils ont aussi Doctrine et Alliances.", "translation": "Et la Perle de grand prix."}, "errorPatterns": [{"equals": "Les 95 thèses", "category": "word_confusion", "feedback": "Les 95 thèses sont de Luther."}], "id": "eg.l59.e03", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e04', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.moroni']::text[], 'free_answer', 'lesson', 'Quel ange aurait indiqué les plaques d''or à Joseph Smith ?', array['Moroni','l''ange Moroni']::text[], 'Selon Joseph Smith, l''ange Moroni lui apparaît en 1823.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.moroni"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel ange aurait indiqué les plaques d''or à Joseph Smith ?", "promptLanguage": "fr", "hint": "Son nom commence par M.", "answer": "Moroni", "acceptedAnswers": ["Moroni", "l''ange Moroni"], "explanation": "Selon Joseph Smith, l''ange Moroni lui apparaît en 1823.", "tip": "Moroni : plaques d''or.", "extraExample": {"text": "Une statue de Moroni orne les temples mormons.", "translation": "Elle tient une trompette."}, "id": "eg.l59.e04", "pool": "lesson", "lessonId": "eg.l59", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e05', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.mormons']::text[], 'mcq', 'lesson', 'Que croient les mormons sur Dieu ?', array['Le Père, le Fils et le Saint-Esprit sont trois êtres distincts']::text[], 'Les mormons parlent de trois êtres distincts. Nous croyons à un seul Dieu en trois personnes de même nature.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.mormons"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que croient les mormons sur Dieu ?", "promptLanguage": "fr", "options": ["Le Père, le Fils et le Saint-Esprit sont trois êtres distincts", "Dieu est un seul être en trois personnes de même nature", "Dieu est seulement une force", "Le Fils est inférieur au Père et créé"], "answer": "Le Père, le Fils et le Saint-Esprit sont trois êtres distincts", "acceptedAnswers": ["Le Père, le Fils et le Saint-Esprit sont trois êtres distincts"], "explanation": "Les mormons parlent de trois êtres distincts. Nous croyons à un seul Dieu en trois personnes de même nature.", "tip": "Trois êtres ≠ une essence.", "extraExample": {"text": "Nicée affirme la consubstantialité.", "translation": "C''est le mot clé de 325."}, "errorPatterns": [{"equals": "Dieu est un seul être en trois personnes de même nature", "category": "word_confusion", "feedback": "C''est la foi de l''Église copte, pas celle des mormons."}], "id": "eg.l59.e05", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e06', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.mormons']::text[], 'mcq', 'lesson', 'Quelle est la foi de l''Église copte sur Dieu ?', array['Un seul Dieu en trois personnes de même nature']::text[], 'La Trinité : un seul Dieu, trois personnes de même nature.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.mormons"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle est la foi de l''Église copte sur Dieu ?", "promptLanguage": "fr", "options": ["Un seul Dieu en trois personnes de même nature", "Trois êtres distincts", "Un seul Dieu en une personne", "Deux dieux"], "answer": "Un seul Dieu en trois personnes de même nature", "acceptedAnswers": ["Un seul Dieu en trois personnes de même nature"], "explanation": "La Trinité : un seul Dieu, trois personnes de même nature.", "tip": "Trinité : 1 Dieu, 3 personnes.", "extraExample": {"text": "C''est la foi de Nicée.", "translation": "Elle est dans le Credo."}, "errorPatterns": [{"equals": "Trois êtres distincts", "category": "word_confusion", "feedback": "C''est la doctrine mormone."}], "id": "eg.l59.e06", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e07', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.livre_de_mormon']::text[], 'fill_blank', 'lesson', 'Les mormons ajoutent à la Bible le Livre de ___.', array['Mormon']::text[], 'Le Livre de Mormon est leur écriture propre.', 1, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.livre_de_mormon"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Les mormons ajoutent à la Bible le Livre de ___.", "promptLanguage": "fr", "options": ["Mormon", "Moroni", "Daniel", "Hénoch"], "answer": "Mormon", "acceptedAnswers": ["Mormon"], "explanation": "Le Livre de Mormon est leur écriture propre.", "tip": "Mormon : le livre.", "extraExample": {"text": "Moroni est l''ange.", "translation": "Mormon est le nom du livre."}, "errorPatterns": [{"equals": "Moroni", "category": "word_confusion", "feedback": "Moroni est l''ange, non le livre."}], "id": "eg.l59.e07", "pool": "lesson", "lessonId": "eg.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e08', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.mormons']::text[], 'mcq', 'lesson', 'Jusqu''en quelle année la polygamie a-t-elle été pratiquée par les mormons ?', array['1890']::text[], 'La polygamie, pratiquée au XIXe siècle, a été abandonnée en 1890.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.mormons"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Jusqu''en quelle année la polygamie a-t-elle été pratiquée par les mormons ?", "promptLanguage": "fr", "options": ["1890", "1830", "1844", "1950"], "answer": "1890", "acceptedAnswers": ["1890"], "explanation": "La polygamie, pratiquée au XIXe siècle, a été abandonnée en 1890.", "tip": "1890 : fin de la polygamie.", "extraExample": {"text": "Elle n''est plus pratiquée par l''Église.", "translation": "Quelques groupes séparés la continuent."}, "errorPatterns": [{"equals": "1830", "category": "word_confusion", "feedback": "1830 est la fondation de l''Église."}], "id": "eg.l59.e08", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e09', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.grande_deception']::text[], 'fill_blank', 'lesson', 'La Grande Déception a lieu en ___.', array['1844']::text[], 'Le 22 octobre 1844, le Christ n''est pas venu comme Miller l''annonçait.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.grande_deception"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "La Grande Déception a lieu en ___.", "promptLanguage": "fr", "options": ["1844", "1830", "1863", "1914"], "answer": "1844", "acceptedAnswers": ["1844"], "explanation": "Le 22 octobre 1844, le Christ n''est pas venu comme Miller l''annonçait.", "tip": "1844 : déception.", "extraExample": {"text": "1914 est une date des témoins de Jéhovah.", "translation": "Ne pas confondre."}, "errorPatterns": [{"equals": "1863", "category": "word_confusion", "feedback": "1863 est l''Église adventiste."}], "id": "eg.l59.e09", "pool": "lesson", "lessonId": "eg.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e10', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.william_miller']::text[], 'mcq', 'lesson', 'Quel verset de Jésus dit que nul ne connaît le jour ni l''heure ?', array['Matthieu 24, 36']::text[], 'Jésus dit : « Quant à ce jour et à cette heure, personne ne les connaît » (Matthieu 24, 36).', 3, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.william_miller"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset de Jésus dit que nul ne connaît le jour ni l''heure ?", "promptLanguage": "fr", "options": ["Matthieu 24, 36", "Luc 23, 43", "Jude 3", "Actes 20, 7"], "answer": "Matthieu 24, 36", "acceptedAnswers": ["Matthieu 24, 36"], "explanation": "Jésus dit : « Quant à ce jour et à cette heure, personne ne les connaît » (Matthieu 24, 36).", "tip": "24, 36 : pas de date.", "extraExample": {"text": "Miller a pourtant annoncé une date.", "translation": "L''échec a prouvé la parole de Jésus."}, "errorPatterns": [{"equals": "Luc 23, 43", "category": "word_confusion", "feedback": "Luc 23, 43 est la parole au bon larron."}], "id": "eg.l59.e10", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e11', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.grande_deception']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on l''échec de la prédiction de 1844 ?', array['la Grande Déception','Grande Déception']::text[], 'Le 22 octobre 1844, des milliers d''adventistes attendaient le retour du Christ.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.grande_deception"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on l''échec de la prédiction de 1844 ?", "promptLanguage": "fr", "hint": "Deux mots, le premier commence par G.", "answer": "la Grande Déception", "acceptedAnswers": ["la Grande Déception", "Grande Déception"], "explanation": "Le 22 octobre 1844, des milliers d''adventistes attendaient le retour du Christ.", "tip": "Grande Déception : 1844.", "extraExample": {"text": "On parle aussi de Great Disappointment.", "translation": "Ellen White apparaît après."}, "id": "eg.l59.e11", "pool": "lesson", "lessonId": "eg.l59", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e12', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.ellen_white']::text[], 'mcq', 'lesson', 'Qui est Ellen White ?', array['Prophétesse et cofondatrice de l''Église adventiste']::text[], 'Ellen White (1827-1915) dit avoir reçu des visions et guide l''Église adventiste.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.ellen_white"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est Ellen White ?", "promptLanguage": "fr", "options": ["Prophétesse et cofondatrice de l''Église adventiste", "La fondatrice des mormons", "Une sainte copte", "La fondatrice de la Science chrétienne"], "answer": "Prophétesse et cofondatrice de l''Église adventiste", "acceptedAnswers": ["Prophétesse et cofondatrice de l''Église adventiste"], "explanation": "Ellen White (1827-1915) dit avoir reçu des visions et guide l''Église adventiste.", "tip": "White : adventistes.", "extraExample": {"text": "Eddy est la fondatrice de la Science chrétienne.", "translation": "Smith celui des mormons."}, "errorPatterns": [{"equals": "La fondatrice de la Science chrétienne", "category": "word_confusion", "feedback": "La fondatrice est Mary Baker Eddy."}], "id": "eg.l59.e12", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e13', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.adventistes']::text[], 'mcq', 'lesson', 'En quelle année l''Église adventiste du septième jour est-elle organisée ?', array['1863']::text[], 'L''Église adventiste est organisée en 1863 à Battle Creek.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.adventistes"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année l''Église adventiste du septième jour est-elle organisée ?", "promptLanguage": "fr", "options": ["1863", "1830", "1844", "1875"], "answer": "1863", "acceptedAnswers": ["1863"], "explanation": "L''Église adventiste est organisée en 1863 à Battle Creek.", "tip": "1863 : adventistes.", "extraExample": {"text": "1844 est la déception.", "translation": "1875 est la publication de Science et Santé."}, "errorPatterns": [{"equals": "1844", "category": "word_confusion", "feedback": "1844 est la Grande Déception, avant l''organisation de l''Église."}], "id": "eg.l59.e13", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e14', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.sabbat_du_samedi']::text[], 'mcq', 'lesson', 'Quel jour les adventistes observent-ils le sabbat ?', array['Le samedi']::text[], 'Les adventistes du septième jour observent le samedi comme jour de repos.', 1, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.sabbat_du_samedi"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel jour les adventistes observent-ils le sabbat ?", "promptLanguage": "fr", "options": ["Le samedi", "Le dimanche", "Le vendredi", "Le lundi"], "answer": "Le samedi", "acceptedAnswers": ["Le samedi"], "explanation": "Les adventistes du septième jour observent le samedi comme jour de repos.", "tip": "Septième jour = samedi.", "extraExample": {"text": "L''Église copte célèbre le dimanche.", "translation": "Jour de la Résurrection."}, "errorPatterns": [{"equals": "Le dimanche", "category": "word_confusion", "feedback": "C''est le jour chrétien traditionnel, celui de l''Église copte."}], "id": "eg.l59.e14", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e15', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.adventistes']::text[], 'mcq', 'lesson', 'Que croient les adventistes sur les morts ?', array['Les morts dorment jusqu''à la résurrection']::text[], 'Pour les adventistes, il n''y a pas de vie consciente entre la mort et la résurrection.', 3, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.adventistes"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que croient les adventistes sur les morts ?", "promptLanguage": "fr", "options": ["Les morts dorment jusqu''à la résurrection", "Les morts vont au purgatoire", "Les morts se réincarnent", "Les morts intercèdent"], "answer": "Les morts dorment jusqu''à la résurrection", "acceptedAnswers": ["Les morts dorment jusqu''à la résurrection"], "explanation": "Pour les adventistes, il n''y a pas de vie consciente entre la mort et la résurrection.", "tip": "Mort = sommeil.", "extraExample": {"text": "Ils rejettent aussi l''enfer éternel.", "translation": "Nous croyons à la vie des saints dès maintenant."}, "errorPatterns": [{"equals": "Les morts vont au purgatoire", "category": "word_confusion", "feedback": "C''est la doctrine catholique, non adventiste."}], "id": "eg.l59.e15", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e16', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.sabbat_du_samedi']::text[], 'fill_blank', 'lesson', 'Les Coptes célèbrent le jour du Seigneur le ___.', array['dimanche']::text[], 'Le dimanche, jour de la Résurrection (Actes 20, 7).', 1, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.sabbat_du_samedi"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Les Coptes célèbrent le jour du Seigneur le ___.", "promptLanguage": "fr", "options": ["dimanche", "samedi", "vendredi"], "answer": "dimanche", "acceptedAnswers": ["dimanche"], "explanation": "Le dimanche, jour de la Résurrection (Actes 20, 7).", "tip": "Dimanche : Résurrection.", "extraExample": {"text": "Les premiers chrétiens se réunissaient le premier jour de la semaine.", "translation": "Actes 20, 7."}, "id": "eg.l59.e16", "pool": "lesson", "lessonId": "eg.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e17', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes']::text[], 'mcq', 'lesson', 'Quelle parole de Jésus montre que les saints sont déjà avec lui ?', array['« Aujourd''hui tu seras avec moi dans le paradis »']::text[], 'Luc 23, 43 : Jésus promet au bon larron le paradis le jour même.', 3, '{"unitIds": ["eg.g59.mormons_adventistes"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle parole de Jésus montre que les saints sont déjà avec lui ?", "promptLanguage": "fr", "options": ["« Aujourd''hui tu seras avec moi dans le paradis »", "« Tu es Pierre »", "« Laissez venir à moi les petits enfants »", "« Je suis le chemin »"], "answer": "« Aujourd''hui tu seras avec moi dans le paradis »", "acceptedAnswers": ["« Aujourd''hui tu seras avec moi dans le paradis »"], "explanation": "Luc 23, 43 : Jésus promet au bon larron le paradis le jour même.", "tip": "Aujourd''hui = tout de suite.", "extraExample": {"text": "Les adventistes lisent autrement ce verset.", "translation": "La virgule change le sens."}, "errorPatterns": [{"equals": "« Tu es Pierre »", "category": "word_confusion", "feedback": "Cette parole concerne Pierre, non les morts."}], "id": "eg.l59.e17", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e18', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes']::text[], 'reorder', 'lesson', 'Phrase-repère : les groupes américains.', array['Les mormons et les adventistes sont nés aux États-Unis au XIXe siècle']::text[], 'Les mormons et les adventistes sont nés aux États-Unis au XIXe siècle.', 2, '{"unitIds": ["eg.g59.mormons_adventistes"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : les groupes américains.", "promptLanguage": "fr", "tokens": ["adventistes", "nés", "États-Unis", "au", "mormons", "et", "les", "siècle", "sont", "aux", "XIXe", "Les"], "answer": "Les mormons et les adventistes sont nés aux États-Unis au XIXe siècle", "acceptedAnswers": ["Les mormons et les adventistes sont nés aux États-Unis au XIXe siècle"], "explanation": "Les mormons et les adventistes sont nés aux États-Unis au XIXe siècle.", "tip": "XIXe, États-Unis.", "extraExample": {"text": "Les témoins de Jéhovah aussi.", "translation": "Et la Science chrétienne."}, "id": "eg.l59.e18", "pool": "lesson", "lessonId": "eg.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e19', 'eg', 'eg.l59', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes']::text[], 'match', 'lesson', 'Les dates des groupes américains', '{}'::text[], 'Quatre dates à retenir.', 2, '{"unitIds": ["eg.g59.mormons_adventistes"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les dates des groupes américains", "promptLanguage": "fr", "pairs": [{"left": "1830", "right": "fondation de l''Église mormone"}, {"left": "1844", "right": "la Grande Déception"}, {"left": "1863", "right": "l''Église adventiste est organisée"}, {"left": "1890", "right": "fin de la polygamie mormone"}], "answer": "1830 = fondation de l''Église mormone ; 1844 = la Grande Déception ; 1863 = l''Église adventiste est organisée ; 1890 = fin de la polygamie mormone", "acceptedAnswers": [], "explanation": "Quatre dates à retenir.", "tip": "1830, 1844, 1863, 1890.", "id": "eg.l59.e19", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e20', 'eg', 'eg.l59', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.deux_sacrements']::text[], 'mcq', 'lesson', 'Révision — Combien de sacrements la plupart des protestants gardent-ils ?', array['Deux']::text[], 'La plupart des protestants gardent le baptême et la Cène.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.deux_sacrements"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Révision — Combien de sacrements la plupart des protestants gardent-ils ?", "promptLanguage": "fr", "options": ["Deux", "Sept", "Trois", "Aucun"], "answer": "Deux", "acceptedAnswers": ["Deux"], "explanation": "La plupart des protestants gardent le baptême et la Cène.", "tip": "2 contre 7.", "extraExample": {"text": "Les Coptes en ont sept.", "translation": "Les catholiques aussi."}, "errorPatterns": [{"equals": "Sept", "category": "word_confusion", "feedback": "Sept est le nombre des Coptes et des catholiques."}], "id": "eg.l59.e20", "pool": "lesson", "lessonId": "eg.l59", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e21', 'eg', 'eg.l59', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.reforme']::text[], 'fill_blank', 'lesson', 'Révision — La Réforme commence en ___ avec Luther.', array['1517']::text[], 'Luther affiche ses 95 thèses en 1517 : début de la Réforme.', 1, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.reforme"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Révision — La Réforme commence en ___ avec Luther.", "promptLanguage": "fr", "options": ["1517", "1054", "1830", "1870"], "answer": "1517", "acceptedAnswers": ["1517"], "explanation": "Luther affiche ses 95 thèses en 1517 : début de la Réforme.", "tip": "1517 : Luther.", "extraExample": {"text": "Le mot « protestant » vient de Spire, en 1529.", "translation": "La Réforme se répand vite."}, "id": "eg.l59.e21", "pool": "lesson", "lessonId": "eg.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e22', 'eg', 'eg.l59', 'eg.g56.dogmes_usages_catholiques', array['eg.g56.dogmes_usages_catholiques','eg.v.immaculee_conception']::text[], 'free_answer', 'lesson', 'Révision — Quel dogme sur Marie Pie IX définit-il en 1854 ?', array['Immaculée Conception','l''Immaculée Conception']::text[], 'Pie IX définit l''Immaculée Conception de Marie en 1854.', 2, '{"unitIds": ["eg.g56.dogmes_usages_catholiques", "eg.v.immaculee_conception"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Révision — Quel dogme sur Marie Pie IX définit-il en 1854 ?", "promptLanguage": "fr", "hint": "Elle commence par I.", "answer": "Immaculée Conception", "acceptedAnswers": ["Immaculée Conception", "l''Immaculée Conception"], "explanation": "Pie IX définit l''Immaculée Conception de Marie en 1854.", "tip": "1854 : Marie.", "extraExample": {"text": "Elle concerne la conception de Marie.", "translation": "Jésus est né d''une vierge."}, "id": "eg.l59.e22", "pool": "lesson", "lessonId": "eg.l59", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l59.e23', 'eg', 'eg.l59', 'eg.g55.papaute_filioque', array['eg.g55.papaute_filioque','eg.v.pape']::text[], 'fill_blank', 'lesson', 'Révision — Pour les catholiques, le pape est le successeur de saint ___.', array['Pierre']::text[], 'Le pape de Rome est le successeur de saint Pierre ; le pape d''Alexandrie, de saint Marc.', 1, '{"unitIds": ["eg.g55.papaute_filioque", "eg.v.pape"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Révision — Pour les catholiques, le pape est le successeur de saint ___.", "promptLanguage": "fr", "options": ["Pierre", "Marc", "Paul", "Jean"], "answer": "Pierre", "acceptedAnswers": ["Pierre"], "explanation": "Le pape de Rome est le successeur de saint Pierre ; le pape d''Alexandrie, de saint Marc.", "tip": "Pierre → Rome ; Marc → Alexandrie.", "extraExample": {"text": "Matthieu 16, 18.", "translation": "« Tu es Pierre »."}, "errorPatterns": [{"equals": "Marc", "category": "word_confusion", "feedback": "Saint Marc est à l''origine de l''Église d''Alexandrie."}], "id": "eg.l59.e23", "pool": "lesson", "lessonId": "eg.l59", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e01', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.temoins_de_jehovah','eg.v.science_chretienne','eg.v.mary_baker_eddy','eg.v.charles_taze_russell']::text[], 'match', 'lesson', 'Chaque mouvement et son fondateur', '{}'::text[], 'Quatre mouvements, cinq noms à retenir.', 1, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.temoins_de_jehovah", "eg.v.science_chretienne", "eg.v.mary_baker_eddy", "eg.v.charles_taze_russell"], "type": "match", "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Chaque mouvement et son fondateur", "promptLanguage": "fr", "pairs": [{"left": "témoins de Jéhovah", "right": "Charles Taze Russell"}, {"left": "Science chrétienne", "right": "Mary Baker Eddy"}, {"left": "mormons", "right": "Joseph Smith"}, {"left": "adventistes", "right": "William Miller et Ellen White"}], "answer": "témoins de Jéhovah = Charles Taze Russell ; Science chrétienne = Mary Baker Eddy ; mormons = Joseph Smith ; adventistes = William Miller et Ellen White", "acceptedAnswers": [], "explanation": "Quatre mouvements, cinq noms à retenir.", "tip": "Un mouvement, un nom.", "id": "eg.l60.e01", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e02', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.charles_taze_russell']::text[], 'mcq', 'lesson', 'Qui est Charles Taze Russell ?', array['Fondateur de la Watch Tower et des témoins de Jéhovah']::text[], 'Russell, de Pittsburgh, fonde le groupe d''étude biblique qui devient les témoins de Jéhovah.', 1, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.charles_taze_russell"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est Charles Taze Russell ?", "promptLanguage": "fr", "options": ["Fondateur de la Watch Tower et des témoins de Jéhovah", "Fondateur des mormons", "Fondatrice de la Science chrétienne", "Réformateur du XVIe siècle"], "answer": "Fondateur de la Watch Tower et des témoins de Jéhovah", "acceptedAnswers": ["Fondateur de la Watch Tower et des témoins de Jéhovah"], "explanation": "Russell, de Pittsburgh, fonde le groupe d''étude biblique qui devient les témoins de Jéhovah.", "tip": "Russell : Watch Tower.", "extraExample": {"text": "Il publie Zion''s Watch Tower en 1879.", "translation": "Le nom actuel date de 1931."}, "errorPatterns": [{"equals": "Fondateur des mormons", "category": "word_confusion", "feedback": "Le fondateur des mormons est Joseph Smith."}], "id": "eg.l60.e02", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e03', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.temoins_de_jehovah']::text[], 'mcq', 'lesson', 'Que croient les témoins de Jéhovah sur Jésus ?', array['Le premier être créé par Jéhovah']::text[], 'Pour eux, Jésus est créé et inférieur au Père. Nous confessons qu''il est vrai Dieu de même nature que le Père.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.temoins_de_jehovah"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que croient les témoins de Jéhovah sur Jésus ?", "promptLanguage": "fr", "options": ["Le premier être créé par Jéhovah", "Dieu, de même nature que le Père", "Un simple prophète", "Un ange sans corps"], "answer": "Le premier être créé par Jéhovah", "acceptedAnswers": ["Le premier être créé par Jéhovah"], "explanation": "Pour eux, Jésus est créé et inférieur au Père. Nous confessons qu''il est vrai Dieu de même nature que le Père.", "tip": "Créé ≠ de même nature.", "extraExample": {"text": "C''est la thèse d''Arius, condamnée à Nicée.", "translation": "Les témoins la reprennent."}, "errorPatterns": [{"equals": "Dieu, de même nature que le Père", "category": "word_confusion", "feedback": "C''est la foi de l''Église copte, non celle des témoins de Jéhovah."}], "id": "eg.l60.e03", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e04', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.temoins_de_jehovah']::text[], 'mcq', 'lesson', 'Que pensent les témoins de Jéhovah du Saint-Esprit ?', array['Une force active']::text[], 'Pour eux, le Saint-Esprit est une force, non une personne. Nous croyons qu''il est Dieu (Actes 5, 3-4).', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.temoins_de_jehovah"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que pensent les témoins de Jéhovah du Saint-Esprit ?", "promptLanguage": "fr", "options": ["Une force active", "Une personne divine", "Un ange", "Le Fils"], "answer": "Une force active", "acceptedAnswers": ["Une force active"], "explanation": "Pour eux, le Saint-Esprit est une force, non une personne. Nous croyons qu''il est Dieu (Actes 5, 3-4).", "tip": "Force ≠ personne.", "extraExample": {"text": "Actes 5, 3-4 : mentir à l''Esprit, c''est mentir à Dieu.", "translation": "Un mensonge ne se fait pas à une force."}, "errorPatterns": [{"equals": "Une personne divine", "category": "word_confusion", "feedback": "C''est notre foi, pas la leur."}], "id": "eg.l60.e04", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e05', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.cent_quarante_quatre_mille']::text[], 'fill_blank', 'lesson', 'Selon les témoins de Jéhovah, ___ fidèles vivent au ciel avec le Christ.', array['144 000','144000','144.000']::text[], 'Ils lisent Apocalypse 7, 4 au sens propre. Nous y voyons un nombre symbolique de plénitude.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.cent_quarante_quatre_mille"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Selon les témoins de Jéhovah, ___ fidèles vivent au ciel avec le Christ.", "promptLanguage": "fr", "options": ["144 000", "12 000", "1 000", "7 000"], "answer": "144 000", "acceptedAnswers": ["144 000", "144000", "144.000"], "explanation": "Ils lisent Apocalypse 7, 4 au sens propre. Nous y voyons un nombre symbolique de plénitude.", "tip": "12 × 12 × 1000.", "extraExample": {"text": "Apocalypse 7, 4 compte 144 000.", "translation": "Le nombre est symbolique."}, "id": "eg.l60.e05", "pool": "lesson", "lessonId": "eg.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e06', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.refus_des_transfusions']::text[], 'mcq', 'lesson', 'Que refusent les témoins de Jéhovah au nom d''Actes 15, 20 ?', array['La transfusion sanguine']::text[], 'Ils refusent le sang (Actes 15, 20) mais acceptent les autres soins. La vie est un don de Dieu : nous sauvons une vie.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.refus_des_transfusions"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que refusent les témoins de Jéhovah au nom d''Actes 15, 20 ?", "promptLanguage": "fr", "options": ["La transfusion sanguine", "Tout médecin", "Le baptême", "La prière"], "answer": "La transfusion sanguine", "acceptedAnswers": ["La transfusion sanguine"], "explanation": "Ils refusent le sang (Actes 15, 20) mais acceptent les autres soins. La vie est un don de Dieu : nous sauvons une vie.", "tip": "Sang refusé, médecins acceptés.", "extraExample": {"text": "Actes 15, 20 parle de s''abstenir du sang.", "translation": "Ils lisent ce verset au sens littéral."}, "errorPatterns": [{"equals": "Tout médecin", "category": "word_confusion", "feedback": "Ils acceptent les médecins ; c''est une erreur fréquente."}], "id": "eg.l60.e06", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e07', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.traduction_du_monde_nouveau']::text[], 'mcq', 'lesson', 'Quel verset répond à la thèse que Jésus est créé ?', array['Jean 1, 1']::text[], 'Jean 1, 1 : « le Verbe était Dieu ». La Traduction du monde nouveau le rend par « un dieu », mais le grec ne le permet pas.', 3, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.traduction_du_monde_nouveau"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset répond à la thèse que Jésus est créé ?", "promptLanguage": "fr", "options": ["Jean 1, 1", "Apocalypse 7, 4", "Actes 15, 20", "Matthieu 9, 12"], "answer": "Jean 1, 1", "acceptedAnswers": ["Jean 1, 1"], "explanation": "Jean 1, 1 : « le Verbe était Dieu ». La Traduction du monde nouveau le rend par « un dieu », mais le grec ne le permet pas.", "tip": "Jean 1, 1 : Verbe = Dieu.", "extraExample": {"text": "Jean 20, 28 : « mon Seigneur et mon Dieu ».", "translation": "Thomas n''est pas repris."}, "errorPatterns": [{"equals": "Apocalypse 7, 4", "category": "word_confusion", "feedback": "Ce verset parle des 144 000, non de la nature du Christ."}], "id": "eg.l60.e07", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e08', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.temoins_de_jehovah']::text[], 'mcq', 'lesson', 'Quel verset montre que le Saint-Esprit est Dieu ?', array['Actes 5, 3-4']::text[], 'Pierre dit : mentir à l''Esprit Saint, c''est mentir à Dieu.', 3, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.temoins_de_jehovah"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset montre que le Saint-Esprit est Dieu ?", "promptLanguage": "fr", "options": ["Actes 5, 3-4", "Apocalypse 7, 4", "Actes 15, 20", "Matthieu 28, 20"], "answer": "Actes 5, 3-4", "acceptedAnswers": ["Actes 5, 3-4"], "explanation": "Pierre dit : mentir à l''Esprit Saint, c''est mentir à Dieu.", "tip": "Actes 5 : Esprit = Dieu.", "extraExample": {"text": "Dans la Trinité, l''Esprit est une personne.", "translation": "Il est de même nature."}, "errorPatterns": [{"equals": "Actes 15, 20", "category": "word_confusion", "feedback": "Ce verset concerne le sang."}], "id": "eg.l60.e08", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e09', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.traduction_du_monde_nouveau']::text[], 'free_answer', 'lesson', 'Comment s''appelle la Bible des témoins de Jéhovah ?', array['Traduction du monde nouveau','la Traduction du monde nouveau']::text[], 'La Traduction du monde nouveau est publiée en 1961.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.traduction_du_monde_nouveau"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle la Bible des témoins de Jéhovah ?", "promptLanguage": "fr", "hint": "Elle contient « monde ».", "answer": "Traduction du monde nouveau", "acceptedAnswers": ["Traduction du monde nouveau", "la Traduction du monde nouveau"], "explanation": "La Traduction du monde nouveau est publiée en 1961.", "tip": "Monde nouveau.", "extraExample": {"text": "Elle traduit Jean 1, 1 par « un dieu ».", "translation": "Le grec dit « Dieu »."}, "id": "eg.l60.e09", "pool": "lesson", "lessonId": "eg.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e10', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.science_et_sante']::text[], 'mcq', 'lesson', 'En quelle année Mary Baker Eddy publie-t-elle Science et Santé ?', array['1875']::text[], 'Science et Santé est publié en 1875 ; l''Église est fondée à Boston en 1879.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.science_et_sante"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année Mary Baker Eddy publie-t-elle Science et Santé ?", "promptLanguage": "fr", "options": ["1875", "1830", "1863", "1931"], "answer": "1875", "acceptedAnswers": ["1875"], "explanation": "Science et Santé est publié en 1875 ; l''Église est fondée à Boston en 1879.", "tip": "1875 : livre ; 1879 : Église.", "extraExample": {"text": "1863 est l''Église adventiste.", "translation": "1931 est le nom des témoins de Jéhovah."}, "errorPatterns": [{"equals": "1863", "category": "word_confusion", "feedback": "1863 est l''Église adventiste."}], "id": "eg.l60.e10", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e11', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.science_chretienne']::text[], 'mcq', 'lesson', 'Que sont la matière, le péché et la maladie pour la Science chrétienne ?', array['Des illusions']::text[], 'La Science chrétienne affirme que la matière, la maladie et la mort sont des illusions. Nous répondons que la maladie est réelle : le Christ a guéri des malades.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.science_chretienne"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que sont la matière, le péché et la maladie pour la Science chrétienne ?", "promptLanguage": "fr", "options": ["Des illusions", "Des punitions de Dieu", "Des sacrements", "Des vertus"], "answer": "Des illusions", "acceptedAnswers": ["Des illusions"], "explanation": "La Science chrétienne affirme que la matière, la maladie et la mort sont des illusions. Nous répondons que la maladie est réelle : le Christ a guéri des malades.", "tip": "Illusion ≠ réalité.", "extraExample": {"text": "Le Christ a guéri de vrais malades.", "translation": "Saint Luc était médecin."}, "errorPatterns": [{"equals": "Des punitions de Dieu", "category": "word_confusion", "feedback": "Ce n''est pas la thèse de la Science chrétienne."}], "id": "eg.l60.e11", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e12', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.science_chretienne']::text[], 'mcq', 'lesson', 'Quel mouvement n''a aucun rapport avec la Science chrétienne ?', array['La scientologie']::text[], 'La scientologie a été créée dans les années 1950, la Science chrétienne en 1879. Elles n''ont aucun rapport.', 3, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.science_chretienne"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel mouvement n''a aucun rapport avec la Science chrétienne ?", "promptLanguage": "fr", "options": ["La scientologie", "Les adventistes", "Les mormons", "L''Église évangélique"], "answer": "La scientologie", "acceptedAnswers": ["La scientologie"], "explanation": "La scientologie a été créée dans les années 1950, la Science chrétienne en 1879. Elles n''ont aucun rapport.", "tip": "Science chrétienne ≠ scientologie.", "extraExample": {"text": "Les deux noms se ressemblent.", "translation": "Mais les deux mouvements sont distincts."}, "errorPatterns": [{"equals": "Les adventistes", "category": "word_confusion", "feedback": "Les adventistes sont un autre mouvement, sans rapport direct."}], "id": "eg.l60.e12", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e13', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne']::text[], 'free_answer', 'lesson', 'Quel évangéliste était médecin ?', array['Luc','saint Luc','Luc l''évangéliste']::text[], 'Saint Luc, médecin, nous rappelle que soigner est un acte de charité et que la maladie est réelle.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel évangéliste était médecin ?", "promptLanguage": "fr", "hint": "Il a aussi écrit les Actes.", "answer": "Luc", "acceptedAnswers": ["Luc", "saint Luc", "Luc l''évangéliste"], "explanation": "Saint Luc, médecin, nous rappelle que soigner est un acte de charité et que la maladie est réelle.", "tip": "Luc : médecin.", "extraExample": {"text": "Paul l''appelle « le médecin bien-aimé ».", "translation": "Colossiens 4, 14."}, "id": "eg.l60.e13", "pool": "lesson", "lessonId": "eg.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e14', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne']::text[], 'mcq', 'lesson', 'Quel trait commun à plusieurs groupes récents est signalé dans le cours ?', array['Chacun ajoute une autorité à la Bible']::text[], 'Livre de Mormon, écrits d''Ellen White, Traduction du monde nouveau, Science et Santé : chacun ajoute une autorité à la Bible.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel trait commun à plusieurs groupes récents est signalé dans le cours ?", "promptLanguage": "fr", "options": ["Chacun ajoute une autorité à la Bible", "Chacun est né en Europe", "Chacun reconnaît le pape", "Chacun a des icônes"], "answer": "Chacun ajoute une autorité à la Bible", "acceptedAnswers": ["Chacun ajoute une autorité à la Bible"], "explanation": "Livre de Mormon, écrits d''Ellen White, Traduction du monde nouveau, Science et Santé : chacun ajoute une autorité à la Bible.", "tip": "Plus qu''un livre.", "extraExample": {"text": "Jude 3 : la foi a été transmise une fois pour toutes.", "translation": "Nous n''ajoutons pas de nouveau livre."}, "errorPatterns": [{"equals": "Chacun est né en Europe", "category": "word_confusion", "feedback": "Tous sont nés aux États-Unis."}], "id": "eg.l60.e14", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e15', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.grande_apostasie']::text[], 'mcq', 'lesson', 'Quelle promesse du Christ répond à l''idée d''une Église disparue ?', array['Les portes du séjour des morts ne prévaudront point']::text[], 'Matthieu 16, 18 : l''Église ne disparaît pas ; le Christ reste avec elle jusqu''à la fin des temps.', 3, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.grande_apostasie"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle promesse du Christ répond à l''idée d''une Église disparue ?", "promptLanguage": "fr", "options": ["Les portes du séjour des morts ne prévaudront point", "Tu seras avec moi dans le paradis", "Le Verbe s''est fait chair", "Mon esprit se réjouit en Dieu"], "answer": "Les portes du séjour des morts ne prévaudront point", "acceptedAnswers": ["Les portes du séjour des morts ne prévaudront point"], "explanation": "Matthieu 16, 18 : l''Église ne disparaît pas ; le Christ reste avec elle jusqu''à la fin des temps.", "tip": "Pas d''apostasie totale.", "extraExample": {"text": "Matthieu 28, 20 : « je suis avec vous tous les jours ».", "translation": "La chaîne de saint Marc est continue."}, "errorPatterns": [{"equals": "Tu seras avec moi dans le paradis", "category": "word_confusion", "feedback": "C''est Luc 23, 43, la parole au bon larron."}], "id": "eg.l60.e15", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e16', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne','eg.v.grande_apostasie']::text[], 'fill_blank', 'lesson', '« Je suis avec vous tous les ___ jusqu''à la fin du monde » (Matthieu 28, 20).', array['jours']::text[], 'Le Christ promet sa présence à l''Église tous les jours.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne", "eg.v.grande_apostasie"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "« Je suis avec vous tous les ___ jusqu''à la fin du monde » (Matthieu 28, 20).", "promptLanguage": "fr", "options": ["jours", "ans", "siècles"], "answer": "jours", "acceptedAnswers": ["jours"], "explanation": "Le Christ promet sa présence à l''Église tous les jours.", "tip": "28, 20 : tous les jours.", "extraExample": {"text": "C''est la dernière phrase de l''évangile selon Matthieu.", "translation": "Elle suit l''envoi en mission."}, "id": "eg.l60.e16", "pool": "lesson", "lessonId": "eg.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e17', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne']::text[], 'reorder', 'lesson', 'Phrase-repère : notre attitude.', array['Nous répondons avec douceur et respect']::text[], 'Nous répondons avec douceur et respect, comme Pierre le demande.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase.", "prompt": "Phrase-repère : notre attitude.", "promptLanguage": "fr", "tokens": ["Nous", "avec", "douceur", "répondons", "respect", "et"], "answer": "Nous répondons avec douceur et respect", "acceptedAnswers": ["Nous répondons avec douceur et respect"], "explanation": "Nous répondons avec douceur et respect, comme Pierre le demande.", "tip": "1 Pierre 3, 15.", "extraExample": {"text": "On aime la personne, on dit la vérité.", "translation": "La douceur ouvre la porte."}, "id": "eg.l60.e17", "pool": "lesson", "lessonId": "eg.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e18', 'eg', 'eg.l60', 'eg.g60.temoins_science_chretienne', array['eg.g60.temoins_science_chretienne']::text[], 'match', 'lesson', 'Quelle date pour quel mouvement ?', '{}'::text[], 'Les quatre groupes naissent entre 1830 et 1879.', 2, '{"unitIds": ["eg.g60.temoins_science_chretienne"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Quelle date pour quel mouvement ?", "promptLanguage": "fr", "pairs": [{"left": "1830", "right": "mormons"}, {"left": "1863", "right": "adventistes"}, {"left": "1875", "right": "Science et Santé"}, {"left": "1879", "right": "Zion''s Watch Tower"}], "answer": "1830 = mormons ; 1863 = adventistes ; 1875 = Science et Santé ; 1879 = Zion''s Watch Tower", "acceptedAnswers": [], "explanation": "Les quatre groupes naissent entre 1830 et 1879.", "tip": "XIXe siècle, États-Unis.", "id": "eg.l60.e18", "pool": "lesson", "lessonId": "eg.l60", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e19', 'eg', 'eg.l60', 'eg.g59.mormons_adventistes', array['eg.g59.mormons_adventistes','eg.v.grande_deception']::text[], 'free_answer', 'lesson', 'Révision — Quel mouvement est né après la Grande Déception de 1844 ?', array['adventistes','les adventistes','adventiste','Église adventiste']::text[], 'Après 1844, un petit groupe fidèle à Miller forme l''Église adventiste.', 2, '{"unitIds": ["eg.g59.mormons_adventistes", "eg.v.grande_deception"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Révision — Quel mouvement est né après la Grande Déception de 1844 ?", "promptLanguage": "fr", "hint": "Son nom parle de la venue du Christ.", "answer": "adventistes", "acceptedAnswers": ["adventistes", "les adventistes", "adventiste", "Église adventiste"], "explanation": "Après 1844, un petit groupe fidèle à Miller forme l''Église adventiste.", "tip": "1844 → adventistes.", "extraExample": {"text": "L''Église est organisée en 1863.", "translation": "Ellen White en est la figure."}, "id": "eg.l60.e19", "pool": "lesson", "lessonId": "eg.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e20', 'eg', 'eg.l60', 'eg.g58.protestants_sacrements_saints', array['eg.g58.protestants_sacrements_saints','eg.v.icone']::text[], 'fill_blank', 'lesson', 'Révision — Les icônes s''appuient sur l''Incarnation : Dieu s''est rendu visible en ___.', array['Jésus-Christ']::text[], 'Dieu s''est rendu visible en Jésus-Christ : c''est le fondement des icônes.', 2, '{"unitIds": ["eg.g58.protestants_sacrements_saints", "eg.v.icone"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Révision — Les icônes s''appuient sur l''Incarnation : Dieu s''est rendu visible en ___.", "promptLanguage": "fr", "options": ["Jésus-Christ", "Moïse", "Marie", "Adam"], "answer": "Jésus-Christ", "acceptedAnswers": ["Jésus-Christ"], "explanation": "Dieu s''est rendu visible en Jésus-Christ : c''est le fondement des icônes.", "tip": "Incarnation → icônes.", "extraExample": {"text": "Saint Basile : l''honneur passe au modèle.", "translation": "L''icône n''est jamais adorée."}, "id": "eg.l60.e20", "pool": "lesson", "lessonId": "eg.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e21', 'eg', 'eg.l60', 'eg.g57.reforme_protestante', array['eg.g57.reforme_protestante','eg.v.deuterocanoniques']::text[], 'fill_blank', 'lesson', 'Révision — Les protestants ne gardent pas les livres ___ de la Septante.', array['deutérocanoniques']::text[], 'Tobie, Judith, la Sagesse, etc. viennent de la Septante. Les Coptes les gardent.', 3, '{"unitIds": ["eg.g57.reforme_protestante", "eg.v.deuterocanoniques"], "type": "fill_blank", "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Révision — Les protestants ne gardent pas les livres ___ de la Septante.", "promptLanguage": "fr", "options": ["deutérocanoniques", "prophétiques", "historiques"], "answer": "deutérocanoniques", "acceptedAnswers": ["deutérocanoniques"], "explanation": "Tobie, Judith, la Sagesse, etc. viennent de la Septante. Les Coptes les gardent.", "tip": "Deutéro : second.", "extraExample": {"text": "La Septante est née à Alexandrie.", "translation": "Un héritage de notre ville."}, "id": "eg.l60.e21", "pool": "lesson", "lessonId": "eg.l60", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l60.e22', 'eg', 'eg.l60', 'eg.g54.chalcedoine_orthodoxes', array['eg.g54.chalcedoine_orthodoxes','eg.v.melkites']::text[], 'free_answer', 'lesson', 'Révision — Quel patriarche d''Alexandrie, mort en exil en 454, est vénéré par les Coptes ?', array['Dioscore','saint Dioscore','Dioscore d''Alexandrie']::text[], 'Dioscore est déposé en 451, exilé à Gangra et meurt en 454.', 3, '{"unitIds": ["eg.g54.chalcedoine_orthodoxes", "eg.v.melkites"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Révision — Quel patriarche d''Alexandrie, mort en exil en 454, est vénéré par les Coptes ?", "promptLanguage": "fr", "hint": "Son nom commence par D.", "answer": "Dioscore", "acceptedAnswers": ["Dioscore", "saint Dioscore", "Dioscore d''Alexandrie"], "explanation": "Dioscore est déposé en 451, exilé à Gangra et meurt en 454.", "tip": "Dioscore : confesseur.", "extraExample": {"text": "Il succède à Cyrille.", "translation": "L''Église copte le fête."}, "id": "eg.l60.e22", "pool": "lesson", "lessonId": "eg.l60", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e01', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.credo']::text[], 'mcq', 'lesson', 'Que veut dire le mot latin « credo » ?', array['je crois']::text[], 'Credo est la première personne du verbe croire en latin : « je crois ». D''où le nom du texte.', 1, '{"id": "eg.l61.e01", "type": "mcq", "unitIds": ["eg.g61.origine_du_credo", "eg.v.credo"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le mot latin « credo » ?", "promptLanguage": "fr", "options": ["je crois", "je prie", "je confesse", "j''espère"], "answer": "je crois", "acceptedAnswers": ["je crois"], "explanation": "Credo est la première personne du verbe croire en latin : « je crois ». D''où le nom du texte.", "tip": "Credo = je crois.", "extraExample": {"text": "Credo in unum Deum.", "translation": "Je crois en un seul Dieu."}, "errorPatterns": [{"equals": "je prie", "category": "word_confusion", "feedback": "Le Credo n''est pas une demande : c''est une affirmation de foi."}, {"equals": "j''espère", "category": "word_confusion", "feedback": "On espère la vie du siècle à venir, mais credo veut dire « je crois »."}], "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e02', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.credo']::text[], 'mcq', 'lesson', 'En grec, que désigne le mot symbole (symbolon) ?', array['un signe de reconnaissance']::text[], 'Les chrétiens se reconnaissaient en récitant le symbole de foi.', 1, '{"id": "eg.l61.e02", "type": "mcq", "unitIds": ["eg.g61.origine_du_credo", "eg.v.credo"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En grec, que désigne le mot symbole (symbolon) ?", "promptLanguage": "fr", "options": ["un signe de reconnaissance", "une loi", "une prière chantée", "un nom de concile"], "answer": "un signe de reconnaissance", "acceptedAnswers": ["un signe de reconnaissance"], "explanation": "Les chrétiens se reconnaissaient en récitant le symbole de foi.", "tip": "Symbole = signe de reconnaissance.", "extraExample": {"text": "Un symbole de foi est un résumé de la foi.", "translation": "Il fonctionne comme une carte d''identité."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e03', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.catechumene']::text[], 'mcq', 'lesson', 'Comment appelle-t-on celui qui apprend la foi avant d''être baptisé ?', array['le catéchumène']::text[], 'Le catéchumène apprend la foi puis la confesse avant son baptême ; de ces confessions sont nés les credos.', 1, '{"id": "eg.l61.e03", "type": "mcq", "unitIds": ["eg.g61.origine_du_credo", "eg.v.catechumene"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on celui qui apprend la foi avant d''être baptisé ?", "promptLanguage": "fr", "options": ["le catéchumène", "le diacre", "le confesseur", "l''ermite"], "answer": "le catéchumène", "acceptedAnswers": ["le catéchumène"], "explanation": "Le catéchumène apprend la foi puis la confesse avant son baptême ; de ces confessions sont nés les credos.", "tip": "Catéchumène = futur baptisé.", "extraExample": {"text": "Saint Cyrille de Jérusalem instruisait les catéchumènes.", "translation": "Il est leur père."}, "errorPatterns": [{"equals": "le confesseur", "category": "word_confusion", "feedback": "Le confesseur est un chrétien qui a souffert pour sa foi sans mourir."}, {"equals": "le diacre", "category": "word_confusion", "feedback": "Le diacre est un ministre de l''Église, pas un futur baptisé."}], "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e04', 'eg', 'eg.l61', 'eg.v.concile_de_nicee', array['eg.v.concile_de_nicee','eg.g61.origine_du_credo']::text[], 'mcq', 'lesson', 'Quel concile de 325 affirme surtout la divinité du Fils contre Arius ?', array['Nicée']::text[], 'À Nicée, les évêques affirment que le Fils est de même substance que le Père.', 1, '{"id": "eg.l61.e04", "type": "mcq", "unitIds": ["eg.v.concile_de_nicee", "eg.g61.origine_du_credo"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel concile de 325 affirme surtout la divinité du Fils contre Arius ?", "promptLanguage": "fr", "options": ["Nicée", "Constantinople", "Éphèse", "Chalcédoine"], "answer": "Nicée", "acceptedAnswers": ["Nicée"], "explanation": "À Nicée, les évêques affirment que le Fils est de même substance que le Père.", "tip": "325 = Nicée = le Fils.", "extraExample": {"text": "Nicée a lieu en 325.", "translation": "Il est convoqué par Constantin."}, "errorPatterns": [{"equals": "Constantinople", "category": "word_confusion", "feedback": "Constantinople (381) développe l''article sur l''Esprit Saint."}], "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e05', 'eg', 'eg.l61', 'eg.v.macedonius', array['eg.v.macedonius','eg.g61.origine_du_credo']::text[], 'mcq', 'lesson', 'Selon Macédonius, que faut-il croire de l''Esprit Saint ?', array['le Saint-Esprit a été créé']::text[], 'Macédonius disait que l''Esprit Saint est une créature : Constantinople (381) lui répond dans le Credo.', 3, '{"id": "eg.l61.e05", "type": "mcq", "unitIds": ["eg.v.macedonius", "eg.g61.origine_du_credo"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Selon Macédonius, que faut-il croire de l''Esprit Saint ?", "promptLanguage": "fr", "options": ["le Saint-Esprit a été créé", "le Saint-Esprit est le Père", "le Saint-Esprit n''existe pas", "le Saint-Esprit est un ange du Christ"], "answer": "le Saint-Esprit a été créé", "acceptedAnswers": ["le Saint-Esprit a été créé"], "explanation": "Macédonius disait que l''Esprit Saint est une créature : Constantinople (381) lui répond dans le Credo.", "tip": "Macédonius : l''Esprit créé.", "extraExample": {"text": "Constantinople excommunie Macédonius.", "translation": "Il est aussi destitué."}, "errorPatterns": [{"equals": "le Saint-Esprit est le Père", "category": "word_confusion", "feedback": "Confondre les personnes est l''erreur de Sabellius, pas celle de Macédonius."}], "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e06', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.concile_ephese_431']::text[], 'mcq', 'lesson', 'Que fait le concile d''Éphèse (431) à propos du credo ?', array['Il interdit d''en composer un autre']::text[], 'Éphèse confirme le credo de Nicée et verrouille le texte.', 2, '{"id": "eg.l61.e06", "type": "mcq", "unitIds": ["eg.g61.origine_du_credo", "eg.v.concile_ephese_431"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que fait le concile d''Éphèse (431) à propos du credo ?", "promptLanguage": "fr", "options": ["Il interdit d''en composer un autre", "Il y ajoute l''article sur l''Esprit Saint", "Il le supprime", "Il le remplace par le symbole des apôtres"], "answer": "Il interdit d''en composer un autre", "acceptedAnswers": ["Il interdit d''en composer un autre"], "explanation": "Éphèse confirme le credo de Nicée et verrouille le texte.", "tip": "Éphèse = verrou.", "extraExample": {"text": "Aucune Église ne peut ajouter une phrase.", "translation": "Le texte vient d''un concile œcuménique."}, "errorPatterns": [{"equals": "Il y ajoute l''article sur l''Esprit Saint", "category": "word_confusion", "feedback": "C''est Constantinople (381) qui développe l''article sur l''Esprit Saint."}], "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e07', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.en_verite_nous_croyons']::text[], 'mcq', 'lesson', 'Comment s''ouvre le Credo dans la liturgie copte ?', array['En vérité, nous croyons']::text[], 'Le Credo copte commence par « En vérité, nous croyons » : on affirme que ces paroles sont vraies.', 1, '{"id": "eg.l61.e07", "type": "mcq", "unitIds": ["eg.g61.origine_du_credo", "eg.v.en_verite_nous_croyons"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment s''ouvre le Credo dans la liturgie copte ?", "promptLanguage": "fr", "options": ["En vérité, nous croyons", "Je crois en un seul Dieu", "Gloire au Père", "Seigneur, aie pitié"], "answer": "En vérité, nous croyons", "acceptedAnswers": ["En vérité, nous croyons"], "explanation": "Le Credo copte commence par « En vérité, nous croyons » : on affirme que ces paroles sont vraies.", "tip": "En vérité + nous.", "extraExample": {"text": "« En vérité, nous croyons en un seul Dieu. »", "translation": "Début de la prière."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e08', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.nous_croyons']::text[], 'mcq', 'lesson', 'Pourquoi dit-on « nous croyons » plutôt que « je crois » ?', array['Parce que c''est la foi de toute l''Église']::text[], 'La foi n''est pas une opinion personnelle : on la reçoit et on la confesse ensemble.', 2, '{"id": "eg.l61.e08", "type": "mcq", "unitIds": ["eg.g61.origine_du_credo", "eg.v.nous_croyons"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi dit-on « nous croyons » plutôt que « je crois » ?", "promptLanguage": "fr", "options": ["Parce que c''est la foi de toute l''Église", "Parce que le texte est trop long pour un seul", "Parce que les prêtres seuls croient", "Parce que le latin l''impose"], "answer": "Parce que c''est la foi de toute l''Église", "acceptedAnswers": ["Parce que c''est la foi de toute l''Église"], "explanation": "La foi n''est pas une opinion personnelle : on la reçoit et on la confesse ensemble.", "tip": "Nous = toute l''Église.", "extraExample": {"text": "Tu confesses avec les martyrs et les Pères.", "translation": "Le « nous » les rassemble."}, "errorPatterns": [{"equals": "Parce que le latin l''impose", "category": "word_confusion", "feedback": "Au contraire : en latin on dit « je crois »."}], "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e09', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.introduction_du_credo']::text[], 'mcq', 'lesson', 'À quel concile la tradition rattache-t-elle l''introduction « Nous t''exaltons, Mère de la vraie lumière » ?', array['Éphèse (431)']::text[], 'Éphèse proclame Marie Théotokos ; l''introduction du Credo célèbre cette Mère de la vraie lumière.', 2, '{"id": "eg.l61.e09", "type": "mcq", "unitIds": ["eg.g61.origine_du_credo", "eg.v.introduction_du_credo"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À quel concile la tradition rattache-t-elle l''introduction « Nous t''exaltons, Mère de la vraie lumière » ?", "promptLanguage": "fr", "options": ["Éphèse (431)", "Nicée (325)", "Constantinople (381)", "Chalcédoine (451)"], "answer": "Éphèse (431)", "acceptedAnswers": ["Éphèse (431)"], "explanation": "Éphèse proclame Marie Théotokos ; l''introduction du Credo célèbre cette Mère de la vraie lumière.", "tip": "Marie + Éphèse.", "extraExample": {"text": "Marie est Mère de la vraie lumière.", "translation": "Elle a enfanté la Lumière."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e10', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.concile_de_nicee']::text[], 'fill_blank', 'lesson', 'Le Credo de ___-Constantinople est celui que tu récites à la messe.', array['Nicée']::text[], 'Il s''appelle Credo de Nicée-Constantinople car il vient des deux conciles.', 1, '{"id": "eg.l61.e10", "type": "fill_blank", "unitIds": ["eg.g61.origine_du_credo", "eg.v.concile_de_nicee"], "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le Credo de ___-Constantinople est celui que tu récites à la messe.", "promptLanguage": "fr", "options": ["Nicée", "Éphèse", "Antioche", "Alexandrie"], "answer": "Nicée", "acceptedAnswers": ["Nicée"], "explanation": "Il s''appelle Credo de Nicée-Constantinople car il vient des deux conciles.", "tip": "Nicée + Constantinople.", "extraExample": {"text": "Nicée : 325.", "translation": "Constantinople : 381."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e11', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.mere_de_la_vraie_lumiere']::text[], 'fill_blank', 'lesson', 'Nous t''exaltons, Mère de la vraie ___.', array['lumière']::text[], 'Marie a enfanté le Christ, la Lumière venue du Père.', 1, '{"id": "eg.l61.e11", "type": "fill_blank", "unitIds": ["eg.g61.origine_du_credo", "eg.v.mere_de_la_vraie_lumiere"], "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Nous t''exaltons, Mère de la vraie ___.", "promptLanguage": "fr", "options": ["lumière", "grâce", "sagesse", "gloire"], "answer": "lumière", "acceptedAnswers": ["lumière"], "explanation": "Marie a enfanté le Christ, la Lumière venue du Père.", "tip": "Mère de la lumière.", "extraExample": {"text": "Le Credo dit « Lumière de Lumière ».", "translation": "Même thème."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e12', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.en_verite_nous_croyons']::text[], 'fill_blank', 'lesson', 'Le Credo s''ouvre par « En ___, nous croyons ».', array['vérité']::text[], 'L''ouverture copte souligne que ce qu''on va dire est vrai.', 1, '{"id": "eg.l61.e12", "type": "fill_blank", "unitIds": ["eg.g61.origine_du_credo", "eg.v.en_verite_nous_croyons"], "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le Credo s''ouvre par « En ___, nous croyons ».", "promptLanguage": "fr", "options": ["vérité", "paix", "amour", "Dieu"], "answer": "vérité", "acceptedAnswers": ["vérité"], "explanation": "L''ouverture copte souligne que ce qu''on va dire est vrai.", "tip": "En vérité.", "extraExample": {"text": "« En vérité, nous croyons ».", "translation": "Début du Credo."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e13', 'eg', 'eg.l61', 'eg.v.theotokos', array['eg.v.theotokos','eg.g61.origine_du_credo']::text[], 'fill_blank', 'lesson', 'Marie est proclamée ___, « celle qui enfante Dieu », au concile d''Éphèse.', array['Théotokos']::text[], 'Théotokos est le titre défendu par Cyrille contre Nestorius, et rappelé dans l''introduction du Credo.', 2, '{"id": "eg.l61.e13", "type": "fill_blank", "unitIds": ["eg.v.theotokos", "eg.g61.origine_du_credo"], "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Marie est proclamée ___, « celle qui enfante Dieu », au concile d''Éphèse.", "promptLanguage": "fr", "options": ["Théotokos", "Christotokos", "Catéchumène", "Anathème"], "answer": "Théotokos", "acceptedAnswers": ["Théotokos"], "explanation": "Théotokos est le titre défendu par Cyrille contre Nestorius, et rappelé dans l''introduction du Credo.", "tip": "Théotokos = mère de Dieu.", "extraExample": {"text": "Nestorius préférait Christotokos.", "translation": "Éphèse choisit Théotokos."}, "errorPatterns": [{"equals": "Christotokos", "category": "word_confusion", "feedback": "Christotokos est le titre préféré de Nestorius, que le concile n''a pas retenu."}], "pool": "lesson", "lessonId": "eg.l61", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e14', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.credo','eg.v.symbole_des_apotres']::text[], 'match', 'lesson', 'Associe le mot à son sens.', '{}'::text[], 'Credo vient du latin, symbolon du grec ; le catéchumène confesse sa foi avant le baptême.', 1, '{"id": "eg.l61.e14", "type": "match", "unitIds": ["eg.g61.origine_du_credo", "eg.v.credo", "eg.v.symbole_des_apotres"], "difficulty": 1, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe le mot à son sens.", "promptLanguage": "fr", "pairs": [{"left": "credo", "right": "je crois"}, {"left": "symbolon", "right": "signe de reconnaissance"}, {"left": "catéchumène", "right": "futur baptisé"}, {"left": "symbole des apôtres", "right": "credo court de l''Occident"}], "answer": "credo = je crois ; symbolon = signe de reconnaissance ; catéchumène = futur baptisé ; symbole des apôtres = credo court de l''Occident", "acceptedAnswers": [], "explanation": "Credo vient du latin, symbolon du grec ; le catéchumène confesse sa foi avant le baptême.", "tip": "Credo = je crois.", "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e15', 'eg', 'eg.l61', 'eg.v.concile_de_nicee', array['eg.v.concile_de_nicee','eg.v.concile_de_constantinople','eg.v.concile_ephese_431']::text[], 'match', 'lesson', 'Associe chaque concile à l''erreur qu''il condamne (révision).', '{}'::text[], 'Chaque concile répond à une erreur : Arius à Nicée, Macédonius à Constantinople, Nestorius à Éphèse.', 2, '{"id": "eg.l61.e15", "type": "match", "unitIds": ["eg.v.concile_de_nicee", "eg.v.concile_de_constantinople", "eg.v.concile_ephese_431"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque concile à l''erreur qu''il condamne (révision).", "promptLanguage": "fr", "pairs": [{"left": "Nicée (325)", "right": "Arius"}, {"left": "Constantinople (381)", "right": "Macédonius"}, {"left": "Éphèse (431)", "right": "Nestorius"}], "answer": "Nicée (325) = Arius ; Constantinople (381) = Macédonius ; Éphèse (431) = Nestorius", "acceptedAnswers": [], "explanation": "Chaque concile répond à une erreur : Arius à Nicée, Macédonius à Constantinople, Nestorius à Éphèse.", "tip": "Un concile, une erreur.", "pool": "lesson", "lessonId": "eg.l61", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e16', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.article_de_foi']::text[], 'reorder', 'lesson', 'Phrase-repère : le Credo s''ouvre ainsi.', array['Nous croyons en un seul Dieu']::text[], 'C''est le premier article du Credo, que tu verras dans la leçon suivante.', 2, '{"id": "eg.l61.e16", "type": "reorder", "unitIds": ["eg.g61.origine_du_credo", "eg.v.article_de_foi"], "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le Credo s''ouvre ainsi.", "promptLanguage": "fr", "tokens": ["croyons", "en", "Nous", "seul", "Dieu", "un"], "answer": "Nous croyons en un seul Dieu", "acceptedAnswers": ["Nous croyons en un seul Dieu"], "explanation": "C''est le premier article du Credo, que tu verras dans la leçon suivante.", "tip": "Nous + croyons + un seul Dieu.", "extraExample": {"text": "« Nous croyons en un seul Dieu »", "translation": "Début de l''article sur le Père."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
