insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e19', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.concile_de_constantinople']::text[], 'free_answer', 'lesson', 'En quelle année le concile de Constantinople achève-t-il le Credo ?', array['381']::text[], 'Constantinople se tient en 381 sous Théodose Ier.', 2, '{"id": "eg.l61.e19", "type": "free_answer", "unitIds": ["eg.g61.origine_du_credo", "eg.v.concile_de_constantinople"], "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "En quelle année le concile de Constantinople achève-t-il le Credo ?", "promptLanguage": "fr", "answer": "381", "acceptedAnswers": ["381"], "explanation": "Constantinople se tient en 381 sous Théodose Ier.", "tip": "381 = Esprit Saint.", "extraExample": {"text": "Éphèse est en 431.", "translation": "Nicée en 325."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l61.e20', 'eg', 'eg.l61', 'eg.g61.origine_du_credo', array['eg.g61.origine_du_credo','eg.v.mere_de_la_vraie_lumiere']::text[], 'free_answer', 'lesson', 'Quel titre de Marie ouvre l''introduction du Credo copte ?', array['Mère de la vraie lumière','la Mère de la vraie lumière']::text[], '« Nous t''exaltons, Mère de la vraie lumière » est le début de l''introduction.', 2, '{"id": "eg.l61.e20", "type": "free_answer", "unitIds": ["eg.g61.origine_du_credo", "eg.v.mere_de_la_vraie_lumiere"], "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel titre de Marie ouvre l''introduction du Credo copte ?", "promptLanguage": "fr", "answer": "Mère de la vraie lumière", "acceptedAnswers": ["Mère de la vraie lumière", "la Mère de la vraie lumière"], "explanation": "« Nous t''exaltons, Mère de la vraie lumière » est le début de l''introduction.", "tip": "Marie = Mère de la vraie lumière.", "extraExample": {"text": "Marie est aussi Théotokos.", "translation": "Les deux titres vont ensemble."}, "pool": "lesson", "lessonId": "eg.l61", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e01', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.pantocrator']::text[], 'mcq', 'lesson', 'Que veut dire Pantocrator ?', array['Tout-Puissant']::text[], 'Pantocrator vient de pan (tout) et kratos (pouvoir) : celui qui tient tout.', 1, '{"id": "eg.l62.e01", "type": "mcq", "unitIds": ["eg.g62.pere_createur", "eg.v.pantocrator"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire Pantocrator ?", "promptLanguage": "fr", "options": ["Tout-Puissant", "Créateur du ciel", "Père éternel", "Roi des rois"], "answer": "Tout-Puissant", "acceptedAnswers": ["Tout-Puissant"], "explanation": "Pantocrator vient de pan (tout) et kratos (pouvoir) : celui qui tient tout.", "tip": "Pan = tout.", "extraExample": {"text": "Le Père est Pantocrator.", "translation": "Tout est tenu par lui."}, "errorPatterns": [{"equals": "Créateur du ciel", "category": "word_confusion", "feedback": "« Créateur du ciel et de la terre » est un autre mot du Credo ; Pantocrator veut dire Tout-Puissant."}], "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e02', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.dieu_le_pere']::text[], 'mcq', 'lesson', 'Pourquoi Dieu est-il d''abord appelé Père ?', array['Parce qu''il a de toute éternité un Fils']::text[], 'Dieu est Père de toute éternité, avant la création.', 2, '{"id": "eg.l62.e02", "type": "mcq", "unitIds": ["eg.g62.pere_createur", "eg.v.dieu_le_pere"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi Dieu est-il d''abord appelé Père ?", "promptLanguage": "fr", "options": ["Parce qu''il a de toute éternité un Fils", "Parce qu''il a créé le monde", "Parce qu''il est plus ancien que le Fils", "Parce qu''il gouverne les anges"], "answer": "Parce qu''il a de toute éternité un Fils", "acceptedAnswers": ["Parce qu''il a de toute éternité un Fils"], "explanation": "Dieu est Père de toute éternité, avant la création.", "tip": "Père, car Fils.", "extraExample": {"text": "Le Fils est engendré avant tous les siècles.", "translation": "Leçon suivante."}, "errorPatterns": [{"equals": "Parce qu''il a créé le monde", "category": "word_confusion", "feedback": "Il est aussi Créateur, mais il est Père d''abord parce qu''il a un Fils depuis toujours."}, {"equals": "Parce qu''il est plus ancien que le Fils", "category": "word_confusion", "feedback": "Le Fils est éternel comme le Père : il n''y a pas de « avant »."}], "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e03', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.source_de_la_trinite']::text[], 'mcq', 'lesson', 'Dans la Trinité, qui est la source du Fils et de l''Esprit ?', array['le Père']::text[], 'Le Fils est engendré du Père et l''Esprit procède du Père.', 2, '{"id": "eg.l62.e03", "type": "mcq", "unitIds": ["eg.g62.pere_createur", "eg.v.source_de_la_trinite"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Dans la Trinité, qui est la source du Fils et de l''Esprit ?", "promptLanguage": "fr", "options": ["le Père", "le Fils", "l''Esprit Saint", "les anges"], "answer": "le Père", "acceptedAnswers": ["le Père"], "explanation": "Le Fils est engendré du Père et l''Esprit procède du Père.", "tip": "Père = source.", "extraExample": {"text": "Le Credo commence par le Père.", "translation": "Il est la source."}, "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e04', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.creation_a_partir_de_rien']::text[], 'mcq', 'lesson', 'Comment Dieu a-t-il créé le ciel et la terre ?', array['à partir de rien']::text[], 'Dieu crée par sa parole, sans matière préexistante.', 2, '{"id": "eg.l62.e04", "type": "mcq", "unitIds": ["eg.g62.pere_createur", "eg.v.creation_a_partir_de_rien"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Comment Dieu a-t-il créé le ciel et la terre ?", "promptLanguage": "fr", "options": ["à partir de rien", "à partir d''une matière éternelle", "en la tirant de son propre corps", "en la confiant à un démiurge"], "answer": "à partir de rien", "acceptedAnswers": ["à partir de rien"], "explanation": "Dieu crée par sa parole, sans matière préexistante.", "tip": "Création = à partir de rien.", "extraExample": {"text": "Le monde dépend de Dieu.", "translation": "Il n''est pas éternel."}, "errorPatterns": [{"equals": "en la confiant à un démiurge", "category": "word_confusion", "feedback": "Le démiurge est l''idée des gnostiques, que l''Église rejette."}], "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e05', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.choses_visibles_et_invisibles','eg.v.ange']::text[], 'mcq', 'lesson', 'Que sont les « choses invisibles » du Credo ?', array['les anges']::text[], 'Les invisibles sont les créatures spirituelles créées par Dieu : les anges.', 1, '{"id": "eg.l62.e05", "type": "mcq", "unitIds": ["eg.g62.pere_createur", "eg.v.choses_visibles_et_invisibles", "eg.v.ange"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que sont les « choses invisibles » du Credo ?", "promptLanguage": "fr", "options": ["les anges", "les démons seuls", "les idées humaines", "les étoiles lointaines"], "answer": "les anges", "acceptedAnswers": ["les anges"], "explanation": "Les invisibles sont les créatures spirituelles créées par Dieu : les anges.", "tip": "Invisibles = anges.", "extraExample": {"text": "Les anges adorent Dieu.", "translation": "Ils sont créés."}, "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e06', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur']::text[], 'mcq', 'lesson', 'Que répond le premier article à ceux qui disent que la matière est mauvaise ?', array['Le monde que Dieu a créé est bon']::text[], 'Dieu a vu que cela était très bon : la création n''est pas mauvaise.', 2, '{"id": "eg.l62.e06", "type": "mcq", "unitIds": ["eg.g62.pere_createur"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que répond le premier article à ceux qui disent que la matière est mauvaise ?", "promptLanguage": "fr", "options": ["Le monde que Dieu a créé est bon", "La matière est neutre", "Seul l''esprit est créé", "Le corps est une prison"], "answer": "Le monde que Dieu a créé est bon", "acceptedAnswers": ["Le monde que Dieu a créé est bon"], "explanation": "Dieu a vu que cela était très bon : la création n''est pas mauvaise.", "tip": "Création = bonne.", "extraExample": {"text": "Le corps ressuscitera.", "translation": "Il n''est pas une prison."}, "errorPatterns": [{"equals": "Le corps est une prison", "category": "word_confusion", "feedback": "C''est l''idée des gnostiques, pas celle de l''Église."}], "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e07', 'eg', 'eg.l62', 'eg.v.marcionisme', array['eg.v.marcionisme','eg.g62.pere_createur']::text[], 'mcq', 'lesson', 'Quelle erreur du IIe siècle opposait un Dieu de justice à un Dieu d''amour ?', array['le marcionisme']::text[], 'Marcion séparait le Dieu créateur de l''Ancien Testament du Père de Jésus. Le premier article affirme un seul Dieu.', 2, '{"id": "eg.l62.e07", "type": "mcq", "unitIds": ["eg.v.marcionisme", "eg.g62.pere_createur"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle erreur du IIe siècle opposait un Dieu de justice à un Dieu d''amour ?", "promptLanguage": "fr", "options": ["le marcionisme", "le montanisme", "l''arianisme", "le modalisme"], "answer": "le marcionisme", "acceptedAnswers": ["le marcionisme"], "explanation": "Marcion séparait le Dieu créateur de l''Ancien Testament du Père de Jésus. Le premier article affirme un seul Dieu.", "tip": "Marcion = deux dieux.", "extraExample": {"text": "Marcion est exclu de Rome vers 144.", "translation": "Tertullien l''a combattu."}, "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e08', 'eg', 'eg.l62', 'eg.v.demiurge', array['eg.v.demiurge','eg.g62.pere_createur']::text[], 'mcq', 'lesson', 'Pour les gnostiques, qui a créé le monde ?', array['un dieu inférieur, le démiurge']::text[], 'Les gnostiques mettaient un dieu inférieur entre Dieu et la matière. Le Credo dit : le Père est créateur.', 2, '{"id": "eg.l62.e08", "type": "mcq", "unitIds": ["eg.v.demiurge", "eg.g62.pere_createur"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pour les gnostiques, qui a créé le monde ?", "promptLanguage": "fr", "options": ["un dieu inférieur, le démiurge", "le vrai Dieu seul", "les anges de Dieu", "le Fils de Dieu"], "answer": "un dieu inférieur, le démiurge", "acceptedAnswers": ["un dieu inférieur, le démiurge"], "explanation": "Les gnostiques mettaient un dieu inférieur entre Dieu et la matière. Le Credo dit : le Père est créateur.", "tip": "Gnose = démiurge.", "extraExample": {"text": "Le démiurge est une invention gnostique.", "translation": "L''Église répond : un seul Créateur."}, "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
