insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e10', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.pantocrator']::text[], 'fill_blank', 'lesson', 'Dieu le Père, ___, créateur du ciel et de la terre.', array['Pantocrator']::text[], 'Pantocrator est le titre du Père dans le Credo.', 1, '{"id": "eg.l62.e10", "type": "fill_blank", "unitIds": ["eg.g62.pere_createur", "eg.v.pantocrator"], "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Dieu le Père, ___, créateur du ciel et de la terre.", "promptLanguage": "fr", "options": ["Pantocrator", "Théotokos", "Homoousios", "Paraclet"], "answer": "Pantocrator", "acceptedAnswers": ["Pantocrator"], "explanation": "Pantocrator est le titre du Père dans le Credo.", "tip": "Pantocrator.", "extraExample": {"text": "Pan = tout.", "translation": "Kratos = pouvoir."}, "errorPatterns": [{"equals": "Théotokos", "category": "word_confusion", "feedback": "Théotokos est le titre de Marie."}], "pool": "lesson", "lessonId": "eg.l62", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
