insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e12', 'eg', 'eg.l62', 'eg.v.manicheisme', array['eg.v.manicheisme','eg.g62.pere_createur']::text[], 'fill_blank', 'lesson', 'Le ___ de Mani suppose un Dieu bon et un démiurge mauvais.', array['manichéisme']::text[], 'Mani oppose un principe bon à un principe mauvais, ce que le premier article rejette.', 3, '{"id": "eg.l62.e12", "type": "fill_blank", "unitIds": ["eg.v.manicheisme", "eg.g62.pere_createur"], "difficulty": 3, "instruction": "Complète la phrase.", "prompt": "Le ___ de Mani suppose un Dieu bon et un démiurge mauvais.", "promptLanguage": "fr", "options": ["manichéisme", "marcionisme", "montanisme", "modalisme"], "answer": "manichéisme", "acceptedAnswers": ["manichéisme"], "explanation": "Mani oppose un principe bon à un principe mauvais, ce que le premier article rejette.", "tip": "Mani = deux principes.", "extraExample": {"text": "Saint Augustin a été manichéen.", "translation": "Puis il s''est converti."}, "pool": "lesson", "lessonId": "eg.l62", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e13', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.pantocrator']::text[], 'match', 'lesson', 'Associe chaque mot du premier article à son sens.', '{}'::text[], 'Chaque mot du premier article a un sens précis.', 2, '{"id": "eg.l62.e13", "type": "match", "unitIds": ["eg.g62.pere_createur", "eg.v.pantocrator"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque mot du premier article à son sens.", "promptLanguage": "fr", "pairs": [{"left": "Pantocrator", "right": "Tout-Puissant"}, {"left": "choses invisibles", "right": "les anges"}, {"left": "création à partir de rien", "right": "sans matière préexistante"}, {"left": "Dieu le Père", "right": "source de la Trinité"}], "answer": "Pantocrator = Tout-Puissant ; choses invisibles = les anges ; création à partir de rien = sans matière préexistante ; Dieu le Père = source de la Trinité", "acceptedAnswers": [], "explanation": "Chaque mot du premier article a un sens précis.", "tip": "Un mot, un sens.", "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e14', 'eg', 'eg.l62', 'eg.v.dualisme', array['eg.v.dualisme','eg.v.marcion','eg.v.gnosticisme','eg.g62.pere_createur']::text[], 'match', 'lesson', 'Associe chaque erreur à ce qu''elle dit de Dieu ou du monde (révision).', '{}'::text[], 'Le premier article répond à chacune par : un seul Dieu, créateur de tout.', 3, '{"id": "eg.l62.e14", "type": "match", "unitIds": ["eg.v.dualisme", "eg.v.marcion", "eg.v.gnosticisme", "eg.g62.pere_createur"], "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque erreur à ce qu''elle dit de Dieu ou du monde (révision).", "promptLanguage": "fr", "pairs": [{"left": "gnosticisme", "right": "un démiurge crée le monde"}, {"left": "marcionisme", "right": "un Dieu de justice et un Dieu d''amour"}, {"left": "dualisme", "right": "deux principes opposés, un bon et un mauvais"}, {"left": "monothéisme", "right": "un seul Dieu"}], "answer": "gnosticisme = un démiurge crée le monde ; marcionisme = un Dieu de justice et un Dieu d''amour ; dualisme = deux principes opposés, un bon et un mauvais ; monothéisme = un seul Dieu", "acceptedAnswers": [], "explanation": "Le premier article répond à chacune par : un seul Dieu, créateur de tout.", "tip": "Une erreur, deux dieux ou plus.", "pool": "lesson", "lessonId": "eg.l62", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
