insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l62.e17', 'eg', 'eg.l62', 'eg.g62.pere_createur', array['eg.g62.pere_createur','eg.v.pantocrator']::text[], 'free_answer', 'lesson', 'Quel mot grec, dans le Credo, signifie Tout-Puissant ?', array['Pantocrator']::text[], 'Pantocrator = pan (tout) + kratos (pouvoir).', 1, '{"id": "eg.l62.e17", "type": "free_answer", "unitIds": ["eg.g62.pere_createur", "eg.v.pantocrator"], "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel mot grec, dans le Credo, signifie Tout-Puissant ?", "promptLanguage": "fr", "answer": "Pantocrator", "acceptedAnswers": ["Pantocrator"], "explanation": "Pantocrator = pan (tout) + kratos (pouvoir).", "tip": "Pantocrator.", "extraExample": {"text": "Tout-Puissant en grec.", "translation": "Titre du Père."}, "pool": "lesson", "lessonId": "eg.l62", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
