insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e02', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.avant_tous_les_siecles']::text[], 'mcq', 'lesson', 'Que signifie « engendré du Père avant tous les siècles » ?', array['de toute éternité']::text[], 'Le Fils est hors du temps : il n''y a jamais eu de moment où le Père était sans Fils.', 2, '{"id": "eg.l63.e02", "type": "mcq", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.avant_tous_les_siecles"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie « engendré du Père avant tous les siècles » ?", "promptLanguage": "fr", "options": ["de toute éternité", "vers l''an 325", "au commencement de la création", "à la naissance de Jésus"], "answer": "de toute éternité", "acceptedAnswers": ["de toute éternité"], "explanation": "Le Fils est hors du temps : il n''y a jamais eu de moment où le Père était sans Fils.", "tip": "Avant tous les siècles = éternel.", "extraExample": {"text": "Le temps est créé.", "translation": "Le Fils est avant."}, "errorPatterns": [{"equals": "au commencement de la création", "category": "word_confusion", "feedback": "Le Fils est avant la création : le Credo dit « avant tous les siècles »."}], "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e03', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.lumiere_de_lumiere']::text[], 'mcq', 'lesson', 'Quelle image des Pères illustre « Lumière de Lumière » ?', array['une flamme allumée à une autre flamme']::text[], 'Allumer une flamme à une autre ne diminue pas la première et donne la même lumière.', 1, '{"id": "eg.l63.e03", "type": "mcq", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.lumiere_de_lumiere"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle image des Pères illustre « Lumière de Lumière » ?", "promptLanguage": "fr", "options": ["une flamme allumée à une autre flamme", "un potier et son vase", "un arbre et ses fruits", "un roi et son messager"], "answer": "une flamme allumée à une autre flamme", "acceptedAnswers": ["une flamme allumée à une autre flamme"], "explanation": "Allumer une flamme à une autre ne diminue pas la première et donne la même lumière.", "tip": "Même lumière, sans division.", "extraExample": {"text": "Le Fils vient du Père sans le diviser.", "translation": "Même divinité."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e04', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.engendre_non_cree']::text[], 'mcq', 'lesson', 'Quelle différence y a-t-il entre engendrer et créer ?', array['Ce qui est engendré est de même nature que celui qui engendre']::text[], 'Un homme engendre un homme ; un menuisier fabrique une table. Le Fils est de même nature que le Père.', 2, '{"id": "eg.l63.e04", "type": "mcq", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.engendre_non_cree"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle différence y a-t-il entre engendrer et créer ?", "promptLanguage": "fr", "options": ["Ce qui est engendré est de même nature que celui qui engendre", "Ce qui est engendré est plus petit", "Ce qui est créé est de même nature que le créateur", "Il n''y en a aucune"], "answer": "Ce qui est engendré est de même nature que celui qui engendre", "acceptedAnswers": ["Ce qui est engendré est de même nature que celui qui engendre"], "explanation": "Un homme engendre un homme ; un menuisier fabrique une table. Le Fils est de même nature que le Père.", "tip": "Engendré = même nature.", "extraExample": {"text": "Un menuisier fait une table.", "translation": "Elle n''est pas menuisier."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e05', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.consubstantiel']::text[], 'mcq', 'lesson', 'Que veut dire « consubstantiel au Père » ?', array['de même substance que le Père']::text[], 'Consubstantiel : de même substance. Semblable serait homoiousios, le mot des semi-ariens.', 2, '{"id": "eg.l63.e05", "type": "mcq", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.consubstantiel"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « consubstantiel au Père » ?", "promptLanguage": "fr", "options": ["de même substance que le Père", "de substance semblable à celle du Père", "né après le Père", "fait par le Père"], "answer": "de même substance que le Père", "acceptedAnswers": ["de même substance que le Père"], "explanation": "Consubstantiel : de même substance. Semblable serait homoiousios, le mot des semi-ariens.", "tip": "Même substance.", "extraExample": {"text": "Homoousios en grec.", "translation": "Défendu par Athanase."}, "errorPatterns": [{"equals": "de substance semblable à celle du Père", "category": "word_confusion", "feedback": "Semblable, c''est homoiousios, le mot des semi-ariens : un iota change tout."}], "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e06', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.par_qui_tout_a_ete_fait']::text[], 'mcq', 'lesson', 'Quelle expression du Credo montre que le Fils est Créateur ?', array['par qui tout a été fait']::text[], 'Si tout a été fait par le Fils, il n''est pas une créature.', 2, '{"id": "eg.l63.e06", "type": "mcq", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.par_qui_tout_a_ete_fait"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle expression du Credo montre que le Fils est Créateur ?", "promptLanguage": "fr", "options": ["par qui tout a été fait", "engendré non créé", "Fils unique", "Lumière de Lumière"], "answer": "par qui tout a été fait", "acceptedAnswers": ["par qui tout a été fait"], "explanation": "Si tout a été fait par le Fils, il n''est pas une créature.", "tip": "Par lui, tout.", "extraExample": {"text": "Jean 1, 3.", "translation": "Tout a été fait par lui."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e07', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.divinite_du_christ']::text[], 'mcq', 'lesson', 'Pourquoi le Christ doit-il être vrai Dieu pour nous sauver ?', array['Seul Dieu peut sauver l''homme']::text[], 'Une créature ne peut pas sauver une autre créature : seul Dieu sauve.', 2, '{"id": "eg.l63.e07", "type": "mcq", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.divinite_du_christ"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi le Christ doit-il être vrai Dieu pour nous sauver ?", "promptLanguage": "fr", "options": ["Seul Dieu peut sauver l''homme", "Parce qu''il est plus puissant que les anges", "Parce qu''il vient du ciel", "Parce qu''il a fait des miracles"], "answer": "Seul Dieu peut sauver l''homme", "acceptedAnswers": ["Seul Dieu peut sauver l''homme"], "explanation": "Une créature ne peut pas sauver une autre créature : seul Dieu sauve.", "tip": "Sauveur = Dieu.", "extraExample": {"text": "Sans la divinité du Christ, il n''y a plus de salut.", "translation": "C''est le cœur de Nicée."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e08', 'eg', 'eg.l63', 'eg.v.homoousios', array['eg.v.homoousios','eg.g63.fils_consubstantiel']::text[], 'mcq', 'lesson', 'Quel mot grec veut dire « de même substance » ?', array['homoousios']::text[], 'Homoousios est le mot de Nicée ; homoiousios (avec un iota de plus) veut dire « substance similaire ».', 3, '{"id": "eg.l63.e08", "type": "mcq", "unitIds": ["eg.v.homoousios", "eg.g63.fils_consubstantiel"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quel mot grec veut dire « de même substance » ?", "promptLanguage": "fr", "options": ["homoousios", "homoiousios", "Pantocrator", "physis"], "answer": "homoousios", "acceptedAnswers": ["homoousios"], "explanation": "Homoousios est le mot de Nicée ; homoiousios (avec un iota de plus) veut dire « substance similaire ».", "tip": "Homo = même.", "extraExample": {"text": "Athanase défend homoousios.", "translation": "Les semi-ariens disent homoiousios."}, "errorPatterns": [{"equals": "homoiousios", "category": "word_confusion", "feedback": "Ce mot a un iota de plus et veut dire « substance similaire ». Ce n''est pas le mot de Nicée."}], "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
