insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e14', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.engendre_non_cree']::text[], 'match', 'lesson', 'Associe chaque expression sur le Fils à son sens.', '{}'::text[], 'Chaque expression écarte une erreur d''Arius.', 2, '{"id": "eg.l63.e14", "type": "match", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.engendre_non_cree"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque expression sur le Fils à son sens.", "promptLanguage": "fr", "pairs": [{"left": "Fils unique", "right": "seul Fils par nature"}, {"left": "avant tous les siècles", "right": "de toute éternité"}, {"left": "engendré non créé", "right": "pas une créature"}, {"left": "par qui tout a été fait", "right": "Créateur avec le Père"}], "answer": "Fils unique = seul Fils par nature ; avant tous les siècles = de toute éternité ; engendré non créé = pas une créature ; par qui tout a été fait = Créateur avec le Père", "acceptedAnswers": [], "explanation": "Chaque expression écarte une erreur d''Arius.", "tip": "Une phrase, un sens.", "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e15', 'eg', 'eg.l63', 'eg.v.arius', array['eg.v.arius','eg.v.semi_arianisme','eg.g63.fils_consubstantiel']::text[], 'match', 'lesson', 'Associe chaque camp à sa position sur le Fils (révision).', '{}'::text[], 'Trois camps à Nicée : divinité niée, substance similaire, même substance.', 3, '{"id": "eg.l63.e15", "type": "match", "unitIds": ["eg.v.arius", "eg.v.semi_arianisme", "eg.g63.fils_consubstantiel"], "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque camp à sa position sur le Fils (révision).", "promptLanguage": "fr", "pairs": [{"left": "Arius", "right": "le Fils est une créature"}, {"left": "semi-ariens", "right": "substance similaire"}, {"left": "Athanase", "right": "même substance : homoousios"}], "answer": "Arius = le Fils est une créature ; semi-ariens = substance similaire ; Athanase = même substance : homoousios", "acceptedAnswers": [], "explanation": "Trois camps à Nicée : divinité niée, substance similaire, même substance.", "tip": "Un camp, un mot.", "pool": "lesson", "lessonId": "eg.l63", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e16', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.lumiere_de_lumiere']::text[], 'reorder', 'lesson', 'Phrase-repère : Lumière et Dieu.', array['Lumière de Lumière vrai Dieu de vrai Dieu']::text[], 'Le Fils est lumière et Dieu, comme le Père.', 2, '{"id": "eg.l63.e16", "type": "reorder", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.lumiere_de_lumiere"], "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : Lumière et Dieu.", "promptLanguage": "fr", "tokens": ["Lumière", "de", "Dieu", "Lumière", "vrai", "de", "vrai", "Dieu"], "answer": "Lumière de Lumière vrai Dieu de vrai Dieu", "acceptedAnswers": ["Lumière de Lumière vrai Dieu de vrai Dieu"], "explanation": "Le Fils est lumière et Dieu, comme le Père.", "tip": "Deux fois « de ».", "extraExample": {"text": "Une flamme allumée à une autre.", "translation": "Même nature."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e17', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.consubstantiel']::text[], 'reorder', 'lesson', 'Phrase-repère : la formule de Nicée.', array['engendré non créé consubstantiel au Père par qui tout a été fait']::text[], 'La fin de l''article sur le Fils, contre Arius.', 3, '{"id": "eg.l63.e17", "type": "reorder", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.consubstantiel"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la formule de Nicée.", "promptLanguage": "fr", "tokens": ["tout", "créé", "non", "été", "fait", "consubstantiel", "a", "Père", "par", "engendré", "qui", "au"], "answer": "engendré non créé consubstantiel au Père par qui tout a été fait", "acceptedAnswers": ["engendré non créé consubstantiel au Père par qui tout a été fait"], "explanation": "La fin de l''article sur le Fils, contre Arius.", "tip": "Engendré, consubstantiel, créateur.", "extraExample": {"text": "Il est éternel.", "translation": "Il est Dieu."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e18', 'eg', 'eg.l63', 'eg.g63.fils_consubstantiel', array['eg.g63.fils_consubstantiel','eg.v.homoousios']::text[], 'free_answer', 'lesson', 'Quel mot grec dit « consubstantiel » ?', array['homoousios']::text[], 'Homoousios est le mot de Nicée.', 2, '{"id": "eg.l63.e18", "type": "free_answer", "unitIds": ["eg.g63.fils_consubstantiel", "eg.v.homoousios"], "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot grec dit « consubstantiel » ?", "promptLanguage": "fr", "answer": "homoousios", "acceptedAnswers": ["homoousios"], "explanation": "Homoousios est le mot de Nicée.", "tip": "Homo = même.", "extraExample": {"text": "Il s''oppose à homoiousios.", "translation": "Un iota."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l63.e19', 'eg', 'eg.l63', 'eg.v.arius', array['eg.v.arius','eg.g63.fils_consubstantiel']::text[], 'free_answer', 'lesson', 'Quel prêtre d''Alexandrie disait « il fut un temps où il n''était pas » ?', array['Arius']::text[], 'Arius enseignait que le Fils est une créature. Le Credo répond « engendré avant tous les siècles ».', 2, '{"id": "eg.l63.e19", "type": "free_answer", "unitIds": ["eg.v.arius", "eg.g63.fils_consubstantiel"], "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel prêtre d''Alexandrie disait « il fut un temps où il n''était pas » ?", "promptLanguage": "fr", "answer": "Arius", "acceptedAnswers": ["Arius"], "explanation": "Arius enseignait que le Fils est une créature. Le Credo répond « engendré avant tous les siècles ».", "tip": "Arius = Fils créé.", "extraExample": {"text": "Nicée le condamne.", "translation": "En 325."}, "pool": "lesson", "lessonId": "eg.l63", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e01', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.pour_notre_salut']::text[], 'mcq', 'lesson', 'Pourquoi le Fils est-il descendu du ciel, selon le Credo ?', array['pour nous les hommes et pour notre salut']::text[], 'Le Credo donne la raison : sauver l''homme.', 1, '{"id": "eg.l64.e01", "type": "mcq", "unitIds": ["eg.g64.incarnation_credo", "eg.v.pour_notre_salut"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi le Fils est-il descendu du ciel, selon le Credo ?", "promptLanguage": "fr", "options": ["pour nous les hommes et pour notre salut", "pour juger le monde", "pour fonder un empire", "pour punir les pécheurs"], "answer": "pour nous les hommes et pour notre salut", "acceptedAnswers": ["pour nous les hommes et pour notre salut"], "explanation": "Le Credo donne la raison : sauver l''homme.", "tip": "Pour nous.", "extraExample": {"text": "Seul Dieu peut sauver.", "translation": "Le Christ est Dieu et homme."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e02', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.descente_du_ciel']::text[], 'mcq', 'lesson', 'Que veut dire « il descendit du ciel » ?', array['le Fils prend notre condition sans cesser d''être Dieu']::text[], 'Il s''abaisse, mais il reste Dieu : il prend ce qu''il n''était pas, sans perdre ce qu''il était.', 2, '{"id": "eg.l64.e02", "type": "mcq", "unitIds": ["eg.g64.incarnation_credo", "eg.v.descente_du_ciel"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « il descendit du ciel » ?", "promptLanguage": "fr", "options": ["le Fils prend notre condition sans cesser d''être Dieu", "le Fils quitte la divinité", "le Fils change de nature", "le Fils devient un ange"], "answer": "le Fils prend notre condition sans cesser d''être Dieu", "acceptedAnswers": ["le Fils prend notre condition sans cesser d''être Dieu"], "explanation": "Il s''abaisse, mais il reste Dieu : il prend ce qu''il n''était pas, sans perdre ce qu''il était.", "tip": "Descendre = s''abaisser.", "extraExample": {"text": "Philippiens 2, 7.", "translation": "Il prend la condition de serviteur."}, "errorPatterns": [{"equals": "le Fils quitte la divinité", "category": "word_confusion", "feedback": "Le Fils ne cesse jamais d''être Dieu : il prend l''humanité en plus."}], "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e03', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.vierge_marie']::text[], 'mcq', 'lesson', 'De qui le Fils s''incarne-t-il, selon le Credo ?', array['de l''Esprit Saint et de la Vierge Marie']::text[], 'Le Fils s''incarne par l''Esprit Saint, de la Vierge Marie.', 1, '{"id": "eg.l64.e03", "type": "mcq", "unitIds": ["eg.g64.incarnation_credo", "eg.v.vierge_marie"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "De qui le Fils s''incarne-t-il, selon le Credo ?", "promptLanguage": "fr", "options": ["de l''Esprit Saint et de la Vierge Marie", "du Père et de la Vierge Marie", "de l''Esprit Saint et de Joseph", "d''un ange et de Marie"], "answer": "de l''Esprit Saint et de la Vierge Marie", "acceptedAnswers": ["de l''Esprit Saint et de la Vierge Marie"], "explanation": "Le Fils s''incarne par l''Esprit Saint, de la Vierge Marie.", "tip": "Esprit Saint + Vierge Marie.", "extraExample": {"text": "Luc 1, 35.", "translation": "L''ange à Marie."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e04', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.conception_virginale']::text[], 'mcq', 'lesson', 'Comment appelle-t-on la conception de Jésus sans père humain ?', array['la conception virginale']::text[], 'Jésus est conçu de l''Esprit Saint, sans père humain.', 1, '{"id": "eg.l64.e04", "type": "mcq", "unitIds": ["eg.g64.incarnation_credo", "eg.v.conception_virginale"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Comment appelle-t-on la conception de Jésus sans père humain ?", "promptLanguage": "fr", "options": ["la conception virginale", "la divinisation", "la consubstantialité", "la réception"], "answer": "la conception virginale", "acceptedAnswers": ["la conception virginale"], "explanation": "Jésus est conçu de l''Esprit Saint, sans père humain.", "tip": "Virginale = sans père humain.", "extraExample": {"text": "Luc 1, 35.", "translation": "Marie reste vierge."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e05', 'eg', 'eg.l64', 'eg.v.theotokos', array['eg.v.theotokos','eg.g64.incarnation_credo']::text[], 'mcq', 'lesson', 'Quel titre de Marie découle de « s''incarna de la Vierge Marie » ?', array['Théotokos']::text[], 'Celui qu''elle enfante est Dieu le Verbe : elle est mère de Dieu.', 2, '{"id": "eg.l64.e05", "type": "mcq", "unitIds": ["eg.v.theotokos", "eg.g64.incarnation_credo"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel titre de Marie découle de « s''incarna de la Vierge Marie » ?", "promptLanguage": "fr", "options": ["Théotokos", "Christotokos", "Paraclet", "Pantocrator"], "answer": "Théotokos", "acceptedAnswers": ["Théotokos"], "explanation": "Celui qu''elle enfante est Dieu le Verbe : elle est mère de Dieu.", "tip": "Théotokos = enfante Dieu.", "extraExample": {"text": "Éphèse (431).", "translation": "Nestorius refusait ce titre."}, "errorPatterns": [{"equals": "Christotokos", "category": "word_confusion", "feedback": "C''est le titre préféré de Nestorius ; Éphèse l''écarte."}], "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e06', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.docetisme']::text[], 'mcq', 'lesson', 'Que dit « se fit homme » contre le docétisme ?', array['Le Christ a eu un vrai corps']::text[], 'Pour les docètes, le corps était apparent. Le Credo affirme un vrai corps.', 2, '{"id": "eg.l64.e06", "type": "mcq", "unitIds": ["eg.g64.incarnation_credo", "eg.v.docetisme"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit « se fit homme » contre le docétisme ?", "promptLanguage": "fr", "options": ["Le Christ a eu un vrai corps", "Le Christ a eu seulement l''apparence d''un corps", "Le Christ n''a pas eu d''âme", "Le Christ est devenu un ange"], "answer": "Le Christ a eu un vrai corps", "acceptedAnswers": ["Le Christ a eu un vrai corps"], "explanation": "Pour les docètes, le corps était apparent. Le Credo affirme un vrai corps.", "tip": "Se fit homme = vrai corps.", "extraExample": {"text": "Jean : le Verbe s''est fait chair.", "translation": "Ignace d''Antioche."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e07', 'eg', 'eg.l64', 'eg.v.apollinarisme', array['eg.v.apollinarisme','eg.g64.incarnation_credo']::text[], 'mcq', 'lesson', 'Selon l''apollinarisme, que manque-t-il au Christ ?', array['l''apollinarisme']::text[], 'Apollinaire disait que la divinité du Verbe tenait lieu d''âme. Constantinople (381) le condamne.', 3, '{"id": "eg.l64.e07", "type": "mcq", "unitIds": ["eg.v.apollinarisme", "eg.g64.incarnation_credo"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Selon l''apollinarisme, que manque-t-il au Christ ?", "promptLanguage": "fr", "options": ["l''apollinarisme", "le nestorianisme", "le docétisme", "le modalisme"], "answer": "l''apollinarisme", "acceptedAnswers": ["l''apollinarisme"], "explanation": "Apollinaire disait que la divinité du Verbe tenait lieu d''âme. Constantinople (381) le condamne.", "tip": "Apollinaire = sans âme.", "extraExample": {"text": "Le Verbe prend l''homme entier.", "translation": "Condamné en 381."}, "errorPatterns": [{"equals": "le docétisme", "category": "word_confusion", "feedback": "Le docétisme nie le corps réel ; Apollinaire nie l''âme humaine."}], "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e08', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.un_seul_sujet']::text[], 'mcq', 'lesson', 'Dans le Credo, qui est le sujet de « descendit », « s''incarna » et « fut crucifié » ?', array['le Fils, unique sujet']::text[], 'C''est toujours le Fils : il n''y a pas deux personnes dans le Christ.', 3, '{"id": "eg.l64.e08", "type": "mcq", "unitIds": ["eg.g64.incarnation_credo", "eg.v.un_seul_sujet"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Dans le Credo, qui est le sujet de « descendit », « s''incarna » et « fut crucifié » ?", "promptLanguage": "fr", "options": ["le Fils, unique sujet", "deux personnes : le Verbe et Jésus", "le Père", "l''Esprit Saint"], "answer": "le Fils, unique sujet", "acceptedAnswers": ["le Fils, unique sujet"], "explanation": "C''est toujours le Fils : il n''y a pas deux personnes dans le Christ.", "tip": "Un seul Il.", "extraExample": {"text": "Cyrille : le Verbe incarné.", "translation": "Contre Nestorius."}, "errorPatterns": [{"equals": "deux personnes : le Verbe et Jésus", "category": "word_confusion", "feedback": "C''est l''erreur de Nestorius : séparer deux sujets."}], "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e09', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.divinisation']::text[], 'mcq', 'lesson', 'Selon Athanase, pourquoi Dieu s''est-il fait homme ?', array['pour que l''homme participe à la vie divine']::text[], 'La divinisation est un don de grâce : l''homme reçoit la vie de Dieu.', 3, '{"id": "eg.l64.e09", "type": "mcq", "unitIds": ["eg.g64.incarnation_credo", "eg.v.divinisation"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Selon Athanase, pourquoi Dieu s''est-il fait homme ?", "promptLanguage": "fr", "options": ["pour que l''homme participe à la vie divine", "pour devenir un roi terrestre", "pour effacer l''Ancien Testament", "pour changer la nature des anges"], "answer": "pour que l''homme participe à la vie divine", "acceptedAnswers": ["pour que l''homme participe à la vie divine"], "explanation": "La divinisation est un don de grâce : l''homme reçoit la vie de Dieu.", "tip": "Dieu homme, homme participant.", "extraExample": {"text": "Fer et feu.", "translation": "Le fer reste du fer."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
