insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e13', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.pleine_humanite']::text[], 'fill_blank', 'lesson', 'Le Credo dit : et se fit ___.', array['homme']::text[], 'Le Verbe s''est fait homme, un homme entier.', 1, '{"id": "eg.l64.e13", "type": "fill_blank", "unitIds": ["eg.g64.incarnation_credo", "eg.v.pleine_humanite"], "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Le Credo dit : et se fit ___.", "promptLanguage": "fr", "options": ["homme", "ange", "roi", "prophète"], "answer": "homme", "acceptedAnswers": ["homme"], "explanation": "Le Verbe s''est fait homme, un homme entier.", "tip": "Se fit homme.", "extraExample": {"text": "Jean 1, 14.", "translation": "Le Verbe s''est fait chair."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e14', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.vierge_marie']::text[], 'match', 'lesson', 'Associe chaque expression sur l''incarnation à son sens.', '{}'::text[], 'Chaque expression de l''article dit quelque chose de l''incarnation.', 2, '{"id": "eg.l64.e14", "type": "match", "unitIds": ["eg.g64.incarnation_credo", "eg.v.vierge_marie"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque expression sur l''incarnation à son sens.", "promptLanguage": "fr", "pairs": [{"left": "pour notre salut", "right": "la raison de l''incarnation"}, {"left": "il descendit du ciel", "right": "il s''abaisse en restant Dieu"}, {"left": "de la Vierge Marie", "right": "Marie est mère de Dieu : Théotokos"}, {"left": "se fit homme", "right": "un vrai corps et une âme humaine"}], "answer": "pour notre salut = la raison de l''incarnation ; il descendit du ciel = il s''abaisse en restant Dieu ; de la Vierge Marie = Marie est mère de Dieu : Théotokos ; se fit homme = un vrai corps et une âme humaine", "acceptedAnswers": [], "explanation": "Chaque expression de l''article dit quelque chose de l''incarnation.", "tip": "Une expression, un sens.", "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e15', 'eg', 'eg.l64', 'eg.v.docetisme', array['eg.v.docetisme','eg.v.apollinarisme','eg.v.nestorianisme','eg.v.monophysisme']::text[], 'match', 'lesson', 'Associe chaque erreur à ce qu''elle dit du Christ (révision).', '{}'::text[], 'Quatre erreurs sur l''incarnation, quatre mots du Credo qui y répondent.', 3, '{"id": "eg.l64.e15", "type": "match", "unitIds": ["eg.v.docetisme", "eg.v.apollinarisme", "eg.v.nestorianisme", "eg.v.monophysisme"], "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque erreur à ce qu''elle dit du Christ (révision).", "promptLanguage": "fr", "pairs": [{"left": "docétisme", "right": "un corps apparent"}, {"left": "apollinarisme", "right": "pas d''âme humaine"}, {"left": "nestorianisme", "right": "séparer le Verbe de l''homme Jésus"}, {"left": "monophysisme", "right": "l''humanité absorbée"}], "answer": "docétisme = un corps apparent ; apollinarisme = pas d''âme humaine ; nestorianisme = séparer le Verbe de l''homme Jésus ; monophysisme = l''humanité absorbée", "acceptedAnswers": [], "explanation": "Quatre erreurs sur l''incarnation, quatre mots du Credo qui y répondent.", "tip": "Corps, âme, séparation, absorption.", "pool": "lesson", "lessonId": "eg.l64", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e16', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.pour_notre_salut']::text[], 'reorder', 'lesson', 'Phrase-repère : la raison de l''incarnation.', array['pour nous les hommes et pour notre salut']::text[], 'Le Credo dit pourquoi le Fils s''incarne.', 2, '{"id": "eg.l64.e16", "type": "reorder", "unitIds": ["eg.g64.incarnation_credo", "eg.v.pour_notre_salut"], "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la raison de l''incarnation.", "promptLanguage": "fr", "tokens": ["les", "nous", "pour", "salut", "notre", "pour", "hommes", "et"], "answer": "pour nous les hommes et pour notre salut", "acceptedAnswers": ["pour nous les hommes et pour notre salut"], "explanation": "Le Credo dit pourquoi le Fils s''incarne.", "tip": "Pour nous, pour notre salut.", "extraExample": {"text": "Salut = être sauvé.", "translation": "Seul Dieu sauve."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
