insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e19', 'eg', 'eg.l64', 'eg.v.formule_de_cyrille', array['eg.v.formule_de_cyrille','eg.g64.incarnation_credo']::text[], 'free_answer', 'lesson', 'Quelle est la formule de Cyrille sur le Christ ?', array['une seule nature du Verbe incarné']::text[], 'Cyrille résume la foi : un seul sujet, le Verbe incarné.', 3, '{"id": "eg.l64.e19", "type": "free_answer", "unitIds": ["eg.v.formule_de_cyrille", "eg.g64.incarnation_credo"], "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quelle est la formule de Cyrille sur le Christ ?", "promptLanguage": "fr", "answer": "une seule nature du Verbe incarné", "acceptedAnswers": ["une seule nature du Verbe incarné"], "explanation": "Cyrille résume la foi : un seul sujet, le Verbe incarné.", "tip": "Une seule nature du Verbe incarné.", "extraExample": {"text": "Miaphysisme.", "translation": "Sans mélange ni division."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l64.e20', 'eg', 'eg.l64', 'eg.g64.incarnation_credo', array['eg.g64.incarnation_credo','eg.v.divinisation']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on le don par lequel l''homme participe à la vie divine, selon Athanase ?', array['la divinisation','divinisation']::text[], 'Athanase : Dieu s''est fait homme pour que l''homme participe à la vie divine.', 3, '{"id": "eg.l64.e20", "type": "free_answer", "unitIds": ["eg.g64.incarnation_credo", "eg.v.divinisation"], "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on le don par lequel l''homme participe à la vie divine, selon Athanase ?", "promptLanguage": "fr", "answer": "la divinisation", "acceptedAnswers": ["la divinisation", "divinisation"], "explanation": "Athanase : Dieu s''est fait homme pour que l''homme participe à la vie divine.", "tip": "Divinisation.", "extraExample": {"text": "Un don de grâce.", "translation": "Fer et feu."}, "pool": "lesson", "lessonId": "eg.l64", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e01', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.crucifie_pour_nous']::text[], 'mcq', 'lesson', 'Pourquoi le Credo nomme-t-il Ponce Pilate ?', array['pour ancrer la croix dans l''histoire']::text[], 'Pilate est un homme réel, gouverneur de Judée : la croix est un fait daté, pas un mythe.', 1, '{"id": "eg.l65.e01", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.crucifie_pour_nous"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi le Credo nomme-t-il Ponce Pilate ?", "promptLanguage": "fr", "options": ["pour ancrer la croix dans l''histoire", "pour accuser les Romains", "pour désigner le coupable", "pour dater la naissance de Jésus"], "answer": "pour ancrer la croix dans l''histoire", "acceptedAnswers": ["pour ancrer la croix dans l''histoire"], "explanation": "Pilate est un homme réel, gouverneur de Judée : la croix est un fait daté, pas un mythe.", "tip": "Pilate = repère historique.", "extraExample": {"text": "Il gouverne la Judée.", "translation": "Vers l''an 30."}, "errorPatterns": [{"equals": "pour accuser les Romains", "category": "word_confusion", "feedback": "Le Credo ne cherche pas un coupable : il situe l''événement dans l''histoire."}], "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e02', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.crucifie_pour_nous']::text[], 'mcq', 'lesson', 'Qui souffre sur la croix, selon la foi de l''Église ?', array['le Verbe, dans la chair']::text[], 'Le Fils est l''unique sujet : c''est lui qui souffre dans sa chair. D''où la valeur infinie de la croix.', 3, '{"id": "eg.l65.e02", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.crucifie_pour_nous"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qui souffre sur la croix, selon la foi de l''Église ?", "promptLanguage": "fr", "options": ["le Verbe, dans la chair", "seulement l''apparence d''un corps", "un autre homme à la place", "le Père"], "answer": "le Verbe, dans la chair", "acceptedAnswers": ["le Verbe, dans la chair"], "explanation": "Le Fils est l''unique sujet : c''est lui qui souffre dans sa chair. D''où la valeur infinie de la croix.", "tip": "Le Verbe souffre en la chair.", "extraExample": {"text": "Cyrille : le Verbe incarné.", "translation": "Un seul sujet."}, "errorPatterns": [{"equals": "seulement l''apparence d''un corps", "category": "word_confusion", "feedback": "C''est le docétisme, rejeté par le Credo."}], "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e03', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.troisieme_jour']::text[], 'mcq', 'lesson', 'Quand le Christ ressuscite-t-il ?', array['le troisième jour']::text[], 'Il ressuscite le troisième jour après sa mort. Le quarantième jour, c''est l''Ascension ; le cinquantième, la Pentecôte.', 1, '{"id": "eg.l65.e03", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.troisieme_jour"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quand le Christ ressuscite-t-il ?", "promptLanguage": "fr", "options": ["le troisième jour", "le septième jour", "le quarantième jour", "le cinquantième jour"], "answer": "le troisième jour", "acceptedAnswers": ["le troisième jour"], "explanation": "Il ressuscite le troisième jour après sa mort. Le quarantième jour, c''est l''Ascension ; le cinquantième, la Pentecôte.", "tip": "Résurrection = troisième jour.", "extraExample": {"text": "Quarante jours : Ascension.", "translation": "Cinquante jours : Pentecôte."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e04', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.selon_les_ecritures']::text[], 'mcq', 'lesson', 'Que veut dire « selon les Écritures » ?', array['elle était annoncée par les prophètes']::text[], 'La résurrection accomplit ce que les prophètes avaient annoncé.', 2, '{"id": "eg.l65.e04", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.selon_les_ecritures"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « selon les Écritures » ?", "promptLanguage": "fr", "options": ["elle était annoncée par les prophètes", "elle est racontée dans les évangiles", "elle a eu lieu à Jérusalem", "elle a été vue par Pilate"], "answer": "elle était annoncée par les prophètes", "acceptedAnswers": ["elle était annoncée par les prophètes"], "explanation": "La résurrection accomplit ce que les prophètes avaient annoncé.", "tip": "Écritures = prophètes.", "extraExample": {"text": "Jonas, trois jours.", "translation": "Image annoncée."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e05', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.droite_du_pere']::text[], 'mcq', 'lesson', 'Que signifie « il s''assit à la droite du Père » ?', array['il reçoit l''honneur et la puissance']::text[], 'La droite est l''image de l''honneur et de la puissance, pas d''un endroit.', 2, '{"id": "eg.l65.e05", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.droite_du_pere"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie « il s''assit à la droite du Père » ?", "promptLanguage": "fr", "options": ["il reçoit l''honneur et la puissance", "il se tient à côté du Père dans le ciel", "il remplace le Père", "il quitte la terre pour toujours"], "answer": "il reçoit l''honneur et la puissance", "acceptedAnswers": ["il reçoit l''honneur et la puissance"], "explanation": "La droite est l''image de l''honneur et de la puissance, pas d''un endroit.", "tip": "Droite = honneur.", "extraExample": {"text": "Dieu n''a pas de côté.", "translation": "C''est une image."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e06', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.seconde_venue']::text[], 'mcq', 'lesson', 'De quelle manière le Christ reviendra-t-il ?', array['dans la gloire']::text[], 'La première venue est humble, la seconde sera glorieuse.', 1, '{"id": "eg.l65.e06", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.seconde_venue"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "De quelle manière le Christ reviendra-t-il ?", "promptLanguage": "fr", "options": ["dans la gloire", "dans l''humilité", "en secret", "comme un enfant"], "answer": "dans la gloire", "acceptedAnswers": ["dans la gloire"], "explanation": "La première venue est humble, la seconde sera glorieuse.", "tip": "Première : humilité. Seconde : gloire.", "extraExample": {"text": "Pour juger.", "translation": "Nul ne sait le jour."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e07', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.jugement_des_vivants_et_des_morts']::text[], 'mcq', 'lesson', 'Qui le Christ jugera-t-il à son retour ?', array['les vivants et les morts']::text[], 'Tous les hommes seront jugés, vivants et morts.', 1, '{"id": "eg.l65.e07", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.jugement_des_vivants_et_des_morts"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qui le Christ jugera-t-il à son retour ?", "promptLanguage": "fr", "options": ["les vivants et les morts", "seulement les pécheurs", "seulement les chrétiens", "seulement les anges"], "answer": "les vivants et les morts", "acceptedAnswers": ["les vivants et les morts"], "explanation": "Tous les hommes seront jugés, vivants et morts.", "tip": "Tous, sans exception.", "extraExample": {"text": "Matthieu 25.", "translation": "L''amour donné aux petits."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e08', 'eg', 'eg.l65', 'eg.v.gnosticisme', array['eg.v.gnosticisme','eg.g65.passion_et_gloire']::text[], 'mcq', 'lesson', 'Quelle erreur méprise le corps et la résurrection de la chair ?', array['le gnosticisme']::text[], 'Pour les gnostiques, la matière est mauvaise : ils méprisent la résurrection de la chair. Le Credo affirme que le Christ ressuscite vraiment.', 3, '{"id": "eg.l65.e08", "type": "mcq", "unitIds": ["eg.v.gnosticisme", "eg.g65.passion_et_gloire"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle erreur méprise le corps et la résurrection de la chair ?", "promptLanguage": "fr", "options": ["le gnosticisme", "l''arianisme", "le montanisme", "le sabellianisme"], "answer": "le gnosticisme", "acceptedAnswers": ["le gnosticisme"], "explanation": "Pour les gnostiques, la matière est mauvaise : ils méprisent la résurrection de la chair. Le Credo affirme que le Christ ressuscite vraiment.", "tip": "Gnose = méprise la chair.", "extraExample": {"text": "Le Christ ressuscite avec un vrai corps.", "translation": "Nous aussi."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e09', 'eg', 'eg.l65', 'eg.v.ascension', array['eg.v.ascension','eg.g65.passion_et_gloire']::text[], 'mcq', 'lesson', 'Combien de jours après la Résurrection Jésus monte-t-il au ciel ?', array['quarante jours']::text[], 'L''Ascension a lieu quarante jours après la Résurrection ; la Pentecôte, cinquante.', 2, '{"id": "eg.l65.e09", "type": "mcq", "unitIds": ["eg.v.ascension", "eg.g65.passion_et_gloire"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de jours après la Résurrection Jésus monte-t-il au ciel ?", "promptLanguage": "fr", "options": ["quarante jours", "trois jours", "sept jours", "cinquante jours"], "answer": "quarante jours", "acceptedAnswers": ["quarante jours"], "explanation": "L''Ascension a lieu quarante jours après la Résurrection ; la Pentecôte, cinquante.", "tip": "40 = Ascension.", "extraExample": {"text": "50 = Pentecôte.", "translation": "3 = résurrection."}, "errorPatterns": [{"equals": "cinquante jours", "category": "word_confusion", "feedback": "Cinquante jours après la Résurrection, c''est la Pentecôte."}], "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e10', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.regne_sans_fin']::text[], 'mcq', 'lesson', 'Que dit la dernière phrase de l''article : « son règne n''aura pas de fin » ?', array['le Christ est Roi pour toujours']::text[], 'La phrase affirme l''éternité du règne du Christ.', 2, '{"id": "eg.l65.e10", "type": "mcq", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.regne_sans_fin"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que dit la dernière phrase de l''article : « son règne n''aura pas de fin » ?", "promptLanguage": "fr", "options": ["le Christ est Roi pour toujours", "le Christ régnera mille ans", "le Christ cessera de régner", "le Père régnera seul"], "answer": "le Christ est Roi pour toujours", "acceptedAnswers": ["le Christ est Roi pour toujours"], "explanation": "La phrase affirme l''éternité du règne du Christ.", "tip": "Roi pour toujours.", "extraExample": {"text": "Luc 1, 33.", "translation": "Son règne est éternel."}, "errorPatterns": [{"equals": "le Christ cessera de régner", "category": "word_confusion", "feedback": "Le Credo affirme exactement le contraire."}], "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
