insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e14', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.regne_sans_fin']::text[], 'fill_blank', 'lesson', 'Son ___ n''aura pas de fin.', array['règne']::text[], 'Dernière phrase de l''article sur le Fils.', 1, '{"id": "eg.l65.e14", "type": "fill_blank", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.regne_sans_fin"], "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Son ___ n''aura pas de fin.", "promptLanguage": "fr", "options": ["règne", "royaume", "temps", "nom"], "answer": "règne", "acceptedAnswers": ["règne"], "explanation": "Dernière phrase de l''article sur le Fils.", "tip": "Règne sans fin.", "extraExample": {"text": "Le Christ est Roi.", "translation": "Pour toujours."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e15', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.troisieme_jour']::text[], 'match', 'lesson', 'Associe chaque expression sur la passion et la gloire à son sens.', '{}'::text[], 'Chaque expression dit quelque chose du Christ.', 2, '{"id": "eg.l65.e15", "type": "match", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.troisieme_jour"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque expression sur la passion et la gloire à son sens.", "promptLanguage": "fr", "pairs": [{"left": "crucifié pour nous", "right": "il meurt pour nous sauver"}, {"left": "selon les Écritures", "right": "annoncée par les prophètes"}, {"left": "à la droite du Père", "right": "honneur et puissance"}, {"left": "son règne n''aura pas de fin", "right": "Roi pour toujours"}], "answer": "crucifié pour nous = il meurt pour nous sauver ; selon les Écritures = annoncée par les prophètes ; à la droite du Père = honneur et puissance ; son règne n''aura pas de fin = Roi pour toujours", "acceptedAnswers": [], "explanation": "Chaque expression dit quelque chose du Christ.", "tip": "Une expression, un sens.", "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e16', 'eg', 'eg.l65', 'eg.v.ascension', array['eg.v.ascension','eg.v.pentecote','eg.v.ponce_pilate']::text[], 'match', 'lesson', 'Associe chaque nom à son rôle dans l''histoire du salut (révision).', '{}'::text[], 'Pilate, l''Ascension et la Pentecôte sont des repères.', 2, '{"id": "eg.l65.e16", "type": "match", "unitIds": ["eg.v.ascension", "eg.v.pentecote", "eg.v.ponce_pilate"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque nom à son rôle dans l''histoire du salut (révision).", "promptLanguage": "fr", "pairs": [{"left": "Ponce Pilate", "right": "gouverneur romain de Judée"}, {"left": "Ascension", "right": "quarante jours après la Résurrection"}, {"left": "Pentecôte", "right": "cinquante jours après la Résurrection"}], "answer": "Ponce Pilate = gouverneur romain de Judée ; Ascension = quarante jours après la Résurrection ; Pentecôte = cinquante jours après la Résurrection", "acceptedAnswers": [], "explanation": "Pilate, l''Ascension et la Pentecôte sont des repères.", "tip": "40 et 50.", "pool": "lesson", "lessonId": "eg.l65", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
