insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l65.e19', 'eg', 'eg.l65', 'eg.g65.passion_et_gloire', array['eg.g65.passion_et_gloire','eg.v.regne_sans_fin']::text[], 'free_answer', 'lesson', 'Que dit le Credo de la durée du règne du Christ ?', array['son règne n''aura pas de fin','n''aura pas de fin','pas de fin','il n''aura pas de fin']::text[], 'Le règne du Christ est éternel.', 2, '{"id": "eg.l65.e19", "type": "free_answer", "unitIds": ["eg.g65.passion_et_gloire", "eg.v.regne_sans_fin"], "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Que dit le Credo de la durée du règne du Christ ?", "promptLanguage": "fr", "answer": "son règne n''aura pas de fin", "acceptedAnswers": ["son règne n''aura pas de fin", "n''aura pas de fin", "pas de fin", "il n''aura pas de fin"], "explanation": "Le règne du Christ est éternel.", "tip": "Pas de fin.", "extraExample": {"text": "Luc 1, 33.", "translation": "Roi pour toujours."}, "pool": "lesson", "lessonId": "eg.l65", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
