insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e03', 'eg', 'eg.l66', 'eg.g66.saint_esprit', array['eg.g66.saint_esprit','eg.v.divinite_de_l_esprit']::text[], 'mcq', 'lesson', 'Pourquoi appeler l''Esprit « Seigneur » ?', array['Seigneur est le titre de Dieu']::text[], 'Dire Seigneur, c''est dire Dieu : l''Esprit n''est pas une créature.', 2, '{"id": "eg.l66.e03", "type": "mcq", "unitIds": ["eg.g66.saint_esprit", "eg.v.divinite_de_l_esprit"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi appeler l''Esprit « Seigneur » ?", "promptLanguage": "fr", "options": ["Seigneur est le titre de Dieu", "Seigneur veut dire serviteur", "Seigneur est un titre des anges", "Seigneur est un titre humain"], "answer": "Seigneur est le titre de Dieu", "acceptedAnswers": ["Seigneur est le titre de Dieu"], "explanation": "Dire Seigneur, c''est dire Dieu : l''Esprit n''est pas une créature.", "tip": "Seigneur = Dieu.", "extraExample": {"text": "Jésus aussi est Seigneur.", "translation": "Kyrios."}, "pool": "lesson", "lessonId": "eg.l66", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e04', 'eg', 'eg.l66', 'eg.g66.saint_esprit', array['eg.g66.saint_esprit','eg.v.vivificateur']::text[], 'mcq', 'lesson', 'Que veut dire « vivificateur » ?', array['qui donne la vie']::text[], 'L''Esprit donne la vie : seul Dieu peut le faire.', 1, '{"id": "eg.l66.e04", "type": "mcq", "unitIds": ["eg.g66.saint_esprit", "eg.v.vivificateur"], "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « vivificateur » ?", "promptLanguage": "fr", "options": ["qui donne la vie", "qui juge les vivants", "qui parle aux prophètes", "qui crée les anges"], "answer": "qui donne la vie", "acceptedAnswers": ["qui donne la vie"], "explanation": "L''Esprit donne la vie : seul Dieu peut le faire.", "tip": "Vivi = vie.", "extraExample": {"text": "Baptême, résurrection.", "translation": "Il donne la vie."}, "pool": "lesson", "lessonId": "eg.l66", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e05', 'eg', 'eg.l66', 'eg.g66.saint_esprit', array['eg.g66.saint_esprit','eg.v.procession_du_pere']::text[], 'mcq', 'lesson', 'Que signifie « qui procède du Père » ?', array['il vient éternellement du Père']::text[], 'Procéder dit que l''Esprit a le Père pour source, sans commencement.', 2, '{"id": "eg.l66.e05", "type": "mcq", "unitIds": ["eg.g66.saint_esprit", "eg.v.procession_du_pere"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que signifie « qui procède du Père » ?", "promptLanguage": "fr", "options": ["il vient éternellement du Père", "il est né de Marie", "il a été créé par le Père", "il vient du Père et du Fils"], "answer": "il vient éternellement du Père", "acceptedAnswers": ["il vient éternellement du Père"], "explanation": "Procéder dit que l''Esprit a le Père pour source, sans commencement.", "tip": "Procède = vient du Père.", "extraExample": {"text": "Jean 15, 26.", "translation": "Le Père est la source."}, "errorPatterns": [{"equals": "il vient du Père et du Fils", "category": "word_confusion", "feedback": "C''est la formule latine du Filioque ; le Credo de 381 dit « du Père »."}], "pool": "lesson", "lessonId": "eg.l66", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e06', 'eg', 'eg.l66', 'eg.g66.saint_esprit', array['eg.g66.saint_esprit','eg.v.source_de_la_trinite']::text[], 'mcq', 'lesson', 'Quelle différence entre le Fils et l''Esprit dans la Trinité ?', array['le Fils est engendré, l''Esprit procède']::text[], 'Deux manières d''avoir le Père pour source.', 3, '{"id": "eg.l66.e06", "type": "mcq", "unitIds": ["eg.g66.saint_esprit", "eg.v.source_de_la_trinite"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle différence entre le Fils et l''Esprit dans la Trinité ?", "promptLanguage": "fr", "options": ["le Fils est engendré, l''Esprit procède", "le Fils est créé, l''Esprit est engendré", "le Fils procède, l''Esprit est engendré", "il n''y en a aucune"], "answer": "le Fils est engendré, l''Esprit procède", "acceptedAnswers": ["le Fils est engendré, l''Esprit procède"], "explanation": "Deux manières d''avoir le Père pour source.", "tip": "Engendré / procède.", "extraExample": {"text": "Le Père est la source.", "translation": "Pas de comment."}, "pool": "lesson", "lessonId": "eg.l66", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e07', 'eg', 'eg.l66', 'eg.g66.saint_esprit', array['eg.g66.saint_esprit','eg.v.adore_avec_le_pere_et_le_fils']::text[], 'mcq', 'lesson', 'Que prouve le fait d''adorer l''Esprit avec le Père et le Fils ?', array['qu''il est Dieu']::text[], 'On n''adore que Dieu : l''adorer avec le Père et le Fils prouve sa divinité.', 2, '{"id": "eg.l66.e07", "type": "mcq", "unitIds": ["eg.g66.saint_esprit", "eg.v.adore_avec_le_pere_et_le_fils"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que prouve le fait d''adorer l''Esprit avec le Père et le Fils ?", "promptLanguage": "fr", "options": ["qu''il est Dieu", "qu''il est un ange élevé", "qu''il est inférieur au Fils", "qu''il est un prophète"], "answer": "qu''il est Dieu", "acceptedAnswers": ["qu''il est Dieu"], "explanation": "On n''adore que Dieu : l''adorer avec le Père et le Fils prouve sa divinité.", "tip": "Adoré = Dieu.", "extraExample": {"text": "Baptême : un seul nom.", "translation": "Trois personnes."}, "pool": "lesson", "lessonId": "eg.l66", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e08', 'eg', 'eg.l66', 'eg.v.montanisme', array['eg.v.montanisme','eg.g66.saint_esprit']::text[], 'mcq', 'lesson', 'Quelle erreur du IIe siècle prétendait parler au nom du Paraclet, l''Esprit Saint ?', array['le montanisme']::text[], 'Montan et ses prophétesses annoncent une « nouvelle prophétie » ; l''Église répond que la Révélation est complète.', 3, '{"id": "eg.l66.e08", "type": "mcq", "unitIds": ["eg.v.montanisme", "eg.g66.saint_esprit"], "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle erreur du IIe siècle prétendait parler au nom du Paraclet, l''Esprit Saint ?", "promptLanguage": "fr", "options": ["le montanisme", "le marcionisme", "le gnosticisme", "l''arianisme"], "answer": "le montanisme", "acceptedAnswers": ["le montanisme"], "explanation": "Montan et ses prophétesses annoncent une « nouvelle prophétie » ; l''Église répond que la Révélation est complète.", "tip": "Montan = Paraclet.", "extraExample": {"text": "Priscilla et Maximilla.", "translation": "Vers 170."}, "pool": "lesson", "lessonId": "eg.l66", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
