insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e15', 'eg', 'eg.l66', 'eg.g66.saint_esprit', array['eg.g66.saint_esprit','eg.v.divinite_de_l_esprit']::text[], 'match', 'lesson', 'Associe chaque expression sur l''Esprit à son sens.', '{}'::text[], 'Chaque expression dit un trait de l''Esprit.', 2, '{"id": "eg.l66.e15", "type": "match", "unitIds": ["eg.g66.saint_esprit", "eg.v.divinite_de_l_esprit"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque expression sur l''Esprit à son sens.", "promptLanguage": "fr", "pairs": [{"left": "Seigneur", "right": "l''Esprit est Dieu"}, {"left": "vivificateur", "right": "qui donne la vie"}, {"left": "procède du Père", "right": "le Père est la seule source"}, {"left": "adoré avec le Père et le Fils", "right": "même gloire"}], "answer": "Seigneur = l''Esprit est Dieu ; vivificateur = qui donne la vie ; procède du Père = le Père est la seule source ; adoré avec le Père et le Fils = même gloire", "acceptedAnswers": [], "explanation": "Chaque expression dit un trait de l''Esprit.", "tip": "Une expression, un sens.", "pool": "lesson", "lessonId": "eg.l66", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
