insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l66.e17', 'eg', 'eg.l66', 'eg.g66.saint_esprit', array['eg.g66.saint_esprit','eg.v.adore_avec_le_pere_et_le_fils']::text[], 'reorder', 'lesson', 'Phrase-repère : l''adoration de l''Esprit.', array['qui avec le Père et le Fils est adoré et glorifié']::text[], 'L''Esprit est adoré avec les deux autres personnes.', 2, '{"id": "eg.l66.e17", "type": "reorder", "unitIds": ["eg.g66.saint_esprit", "eg.v.adore_avec_le_pere_et_le_fils"], "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : l''adoration de l''Esprit.", "promptLanguage": "fr", "tokens": ["le", "et", "et", "qui", "est", "le", "Fils", "adoré", "avec", "glorifié", "Père"], "answer": "qui avec le Père et le Fils est adoré et glorifié", "acceptedAnswers": ["qui avec le Père et le Fils est adoré et glorifié"], "explanation": "L''Esprit est adoré avec les deux autres personnes.", "tip": "Avec le Père et le Fils.", "extraExample": {"text": "Même gloire.", "translation": "Même rang."}, "pool": "lesson", "lessonId": "eg.l66", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
