insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l67.e02', 'eg', 'eg.l67', 'eg.g67.eglise_resurrection', array['eg.g67.eglise_resurrection','eg.v.eglise_sainte']::text[], 'mcq', 'lesson', 'Pourquoi l''Église est-elle sainte ?', array['parce que le Christ et l''Esprit la sanctifient']::text[], 'Sa sainteté vient du Christ et de l''Esprit, non de la perfection de ses membres.', 2, '{"id": "eg.l67.e02", "type": "mcq", "unitIds": ["eg.g67.eglise_resurrection", "eg.v.eglise_sainte"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''Église est-elle sainte ?", "promptLanguage": "fr", "options": ["parce que le Christ et l''Esprit la sanctifient", "parce que tous ses membres sont parfaits", "parce qu''elle est ancienne", "parce qu''elle a des martyrs"], "answer": "parce que le Christ et l''Esprit la sanctifient", "acceptedAnswers": ["parce que le Christ et l''Esprit la sanctifient"], "explanation": "Sa sainteté vient du Christ et de l''Esprit, non de la perfection de ses membres.", "tip": "Sainte par grâce.", "extraExample": {"text": "Elle reçoit les pénitents.", "translation": "Contre Novatien."}, "errorPatterns": [{"equals": "parce que tous ses membres sont parfaits", "category": "word_confusion", "feedback": "Ses membres sont pécheurs ; c''est la grâce qui sanctifie."}], "pool": "lesson", "lessonId": "eg.l67", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = exclud