insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l67.e03', 'eg', 'eg.l67', 'eg.v.novatien', array['eg.v.novatien','eg.g67.eglise_resurrection']::text[], 'mcq', 'lesson', 'Qui voulait une Église de purs, sans pardon pour les tombés ?', array['Novatien']::text[], 'Novatien refuse de pardonner aux tombés ; l''Église le contredit en recevant les pénitents.', 2, '{"id": "eg.l67.e03", "type": "mcq", "unitIds": ["eg.v.novatien", "eg.g67.eglise_resurrection"], "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui voulait une Église de purs, sans pardon pour les tombés ?", "promptLanguage": "fr", "options": ["Novatien", "Arius", "Montan", "Marcion"], "answer": "Novatien", "acceptedAnswers": ["Novatien"], "explanation": "Novatien refuse de pardonner aux tombés ; l''Église le contredit en recevant les pénitents.", "tip": "Novatien = purs.", "extraExample": {"text": "Excommunié en 251.", "translation": "Combattu par Cyprien."}, "pool": "lesson", "lessonId": "eg.l67", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
