insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l68.e14', 'eg', 'eg.l68', 'eg.g68.bilan_du_credo', array['eg.g68.bilan_du_credo','eg.v.arius']::text[], 'match', 'lesson', 'Associe chaque article du Credo à l''erreur qu''il combat.', '{}'::text[], 'Chaque article répond à une erreur.', 3, '{"id": "eg.l68.e14", "type": "match", "unitIds": ["eg.g68.bilan_du_credo", "eg.v.arius"], "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque article du Credo à l''erreur qu''il combat.", "promptLanguage": "fr", "pairs": [{"left": "Dieu créateur de tout", "right": "gnostiques et Marcion"}, {"left": "consubstantiel au Père", "right": "Arius"}, {"left": "et se fit homme", "right": "docètes et Apollinaire"}, {"left": "Seigneur et vivificateur", "right": "Macédonius"}, {"left": "Église sainte", "right": "Novatien"}], "answer": "Dieu créateur de tout = gnostiques et Marcion ; consubstantiel au Père = Arius ; et se fit homme = docètes et Apollinaire ; Seigneur et vivificateur = Macédonius ; Église sainte = Novatien", "acceptedAnswers": [], "explanation": "Chaque article répond à une erreur.", "tip": "Un article, une erreur.", "pool": "lesson", "lessonId": "eg.l68", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l68.e15', 'eg', 'eg.l68', 'eg.g68.bilan_du_credo', array['eg.g68.bilan_du_credo','eg.v.concile_de_nicee','eg.v.concile_ephese_431']::text[], 'match', 'lesson', 'Associe chaque concile à ce qu''il apporte au Credo.', '{}'::text[], 'Trois conciles, un seul texte.', 2, '{"id": "eg.l68.e15", "type": "match", "unitIds": ["eg.g68.bilan_du_credo", "eg.v.concile_de_nicee", "eg.v.concile_ephese_431"], "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque concile à ce qu''il apporte au Credo.", "promptLanguage": "fr", "pairs": [{"left": "Nicée (325)", "right": "le Père et le Fils"}, {"left": "Constantinople (381)", "right": "l''Esprit Saint et la suite"}, {"left": "Éphèse (431)", "right": "on n''y touche plus"}], "answer": "Nicée (325) = le Père et le Fils ; Constantinople (381) = l''Esprit Saint et la suite ; Éphèse (431) = on n''y touche plus", "acceptedAnswers": [], "explanation": "Trois conciles, un seul texte.", "tip": "325, 381, 431.", "pool": "lesson", "lessonId": "eg.l68", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l68.e16', 'eg', 'eg.l68', 'eg.g68.bilan_du_credo', array['eg.g68.bilan_du_credo','eg.v.trois_blocs_du_credo']::text[], 'reorder', 'lesson', 'Remets les articles du Credo dans l''ordre.', array['Père Fils Incarnation Passion Résurrection Ascension Esprit Église']::text[], 'Le Père, le Fils (incarnation, passion, résurrection, ascension), l''Esprit Saint, l''Église.', 3, '{"id": "eg.l68.e16", "type": "reorder", "unitIds": ["eg.g68.bilan_du_credo", "eg.v.trois_blocs_du_credo"], "difficulty": 3, "instruction": "Remets les articles du Credo dans l''ordre.", "prompt": "Remets les articles du Credo dans l''ordre.", "promptLanguage": "fr", "tokens": ["Église", "Passion", "Esprit", "Résurrection", "Fils", "Incarnation", "Ascension", "Père"], "answer": "Père Fils Incarnation Passion Résurrection Ascension Esprit Église", "acceptedAnswers": ["Père Fils Incarnation Passion Résurrection Ascension Esprit Église"], "explanation": "Le Père, le Fils (incarnation, passion, résurrection, ascension), l''Esprit Saint, l''Église.", "tip": "Père, Fils, Esprit, Église.", "extraExample": {"text": "Trois blocs.", "translation": "Puis l''Église."}, "pool": "lesson", "lessonId": "eg.l68", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l68.e17', 'eg', 'eg.l68', 'eg.g68.bilan_du_credo', array['eg.g68.bilan_du_credo','eg.v.lumiere_de_lumiere']::text[], 'reorder', 'lesson', 'Remets la phrase du Credo dans l''ordre.', array['Lumière de Lumière vrai Dieu de vrai Dieu engendré non créé']::text[], 'Contre Arius : vrai Dieu, non créature.', 3, '{"id": "eg.l68.e17", "type": "reorder", "unitIds": ["eg.g68.bilan_du_credo", "eg.v.lumiere_de_lumiere"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Remets la phrase du Credo dans l''ordre.", "promptLanguage": "fr", "tokens": ["de", "créé", "Dieu", "non", "vrai", "vrai", "de", "Lumière", "Lumière", "Dieu", "engendré"], "answer": "Lumière de Lumière vrai Dieu de vrai Dieu engendré non créé", "acceptedAnswers": ["Lumière de Lumière vrai Dieu de vrai Dieu engendré non créé"], "explanation": "Contre Arius : vrai Dieu, non créature.", "tip": "Lumière, vrai Dieu, non créé.", "extraExample": {"text": "Consubstantiel.", "translation": "Nicée."}, "pool": "lesson", "lessonId": "eg.l68", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l68.e18', 'eg', 'eg.l68', 'eg.g68.bilan_du_credo', array['eg.g68.bilan_du_credo','eg.v.chaine_des_verbes']::text[], 'reorder', 'lesson', 'Remets la fin de l''article sur le Fils dans l''ordre.', array['Il monta aux cieux et s''assit à la droite de son Père']::text[], 'Ascension puis droite du Père.', 3, '{"id": "eg.l68.e18", "type": "reorder", "unitIds": ["eg.g68.bilan_du_credo", "eg.v.chaine_des_verbes"], "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Remets la fin de l''article sur le Fils dans l''ordre.", "promptLanguage": "fr", "tokens": ["monta", "s''assit", "de", "et", "son", "Il", "la", "cieux", "aux", "à", "Père", "droite"], "answer": "Il monta aux cieux et s''assit à la droite de son Père", "acceptedAnswers": ["Il monta aux cieux et s''assit à la droite de son Père"], "explanation": "Ascension puis droite du Père.", "tip": "Monter puis s''asseoir.", "extraExample": {"text": "Il reviendra.", "translation": "Dans la gloire."}, "pool": "lesson", "lessonId": "eg.l68", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l68.e19', 'eg', 'eg.l68', 'eg.g68.bilan_du_credo', array['eg.g68.bilan_du_credo','eg.v.arius']::text[], 'free_answer', 'lesson', 'Quel hérétique est visé par « consubstantiel au Père » ?', array['Arius','l''arianisme','arianisme']::text[], 'Arius disait que le Fils est une créature.', 2, '{"id": "eg.l68.e19", "type": "free_answer", "unitIds": ["eg.g68.bilan_du_credo", "eg.v.arius"], "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel hérétique est visé par « consubstantiel au Père » ?", "promptLanguage": "fr", "answer": "Arius", "acceptedAnswers": ["Arius", "l''arianisme", "arianisme"], "explanation": "Arius disait que le Fils est une créature.", "tip": "Consubstantiel = Arius.", "extraExample": {"text": "Nicée, 325.", "translation": "Athanase."}, "pool": "lesson", "lessonId": "eg.l68", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l68.e20', 'eg', 'eg.l68', 'eg.g68.bilan_du_credo', array['eg.g68.bilan_du_credo','eg.v.amen']::text[], 'free_answer', 'lesson', 'Quel mot termine le Credo ?', array['Amen']::text[], 'Amen : ainsi soit-il.', 1, '{"id": "eg.l68.e20", "type": "free_answer", "unitIds": ["eg.g68.bilan_du_credo", "eg.v.amen"], "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel mot termine le Credo ?", "promptLanguage": "fr", "answer": "Amen", "acceptedAnswers": ["Amen"], "explanation": "Amen : ainsi soit-il.", "tip": "Amen.", "extraExample": {"text": "Tu signes le Credo.", "translation": "C''est vrai."}, "pool": "lesson", "lessonId": "eg.l68", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e01', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrement']::text[], 'mcq', 'lesson', 'Qu''est-ce qu''un sacrement, ou mystère ?', array['un signe visible par lequel Dieu donne une grâce invisible']::text[], 'Le sacrement associe un signe que l''on voit (eau, huile, pain) à une grâce que l''on ne voit pas, donnée par Dieu.', 1, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''est-ce qu''un sacrement, ou mystère ?", "promptLanguage": "fr", "answer": "un signe visible par lequel Dieu donne une grâce invisible", "acceptedAnswers": ["un signe visible par lequel Dieu donne une grâce invisible"], "explanation": "Le sacrement associe un signe que l''on voit (eau, huile, pain) à une grâce que l''on ne voit pas, donnée par Dieu.", "tip": "Signe visible + grâce invisible.", "extraExample": {"text": "Le pain et le vin sont visibles.", "translation": "Ce que Dieu donne par eux ne se voit pas."}, "errorPatterns": [{"equals": "une simple cérémonie pour se souvenir d''un événement", "category": "word_confusion", "feedback": "Un sacrement n''est pas un simple souvenir : Dieu y donne vraiment sa grâce."}], "options": ["une simple cérémonie pour se souvenir d''un événement", "un signe visible par lequel Dieu donne une grâce invisible", "un enseignement du prêtre sur la Bible", "une prière récitée par toute l''assemblée"], "id": "eg.l69.e01", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e02', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrement']::text[], 'mcq', 'lesson', 'Quel autre mot l''Église copte utilise-t-elle pour dire « sacrement » ?', array['mystère']::text[], 'On dit « mystère » parce que Dieu y agit d''une manière que l''on ne voit pas entièrement.', 1, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrement"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel autre mot l''Église copte utilise-t-elle pour dire « sacrement » ?", "promptLanguage": "fr", "answer": "mystère", "acceptedAnswers": ["mystère"], "explanation": "On dit « mystère » parce que Dieu y agit d''une manière que l''on ne voit pas entièrement.", "tip": "Sacrement = mystère.", "extraExample": {"text": "On parle des sept mystères de l''Église.", "translation": "C''est le même mot que sacrement."}, "errorPatterns": [{"equals": "canon", "category": "word_confusion", "feedback": "Un canon est une règle d''un concile, pas un sacrement."}], "options": ["canon", "miracle", "mémorial", "mystère"], "id": "eg.l69.e02", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e03', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.institution_par_le_christ']::text[], 'mcq', 'lesson', 'Sur quoi repose chaque sacrement ?', array['sur un geste ou une parole du Christ, ou sur la pratique des apôtres']::text[], 'Aucun sacrement n''est une invention de l''Église : on trouve son fondement dans le Nouveau Testament.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.institution_par_le_christ"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Sur quoi repose chaque sacrement ?", "promptLanguage": "fr", "answer": "sur un geste ou une parole du Christ, ou sur la pratique des apôtres", "acceptedAnswers": ["sur un geste ou une parole du Christ, ou sur la pratique des apôtres"], "explanation": "Aucun sacrement n''est une invention de l''Église : on trouve son fondement dans le Nouveau Testament.", "tip": "Le Christ ou les apôtres.", "extraExample": {"text": "Mt 28, 19 institue le baptême.", "translation": "C''est la parole du Christ."}, "options": ["sur une décision des évêques au Moyen Âge", "sur la coutume de chaque pays", "sur un geste ou une parole du Christ, ou sur la pratique des apôtres", "sur le choix du patriarche"], "id": "eg.l69.e03", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e04', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.signe_visible','eg.v.grace']::text[], 'mcq', 'lesson', 'Que montre le signe visible d''un sacrement ?', array['ce que Dieu fait vraiment']::text[], 'Le signe n''est pas décoratif : il montre et porte la grâce que Dieu donne.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.signe_visible", "eg.v.grace"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que montre le signe visible d''un sacrement ?", "promptLanguage": "fr", "answer": "ce que Dieu fait vraiment", "acceptedAnswers": ["ce que Dieu fait vraiment"], "explanation": "Le signe n''est pas décoratif : il montre et porte la grâce que Dieu donne.", "tip": "Le signe dit ce que Dieu fait.", "extraExample": {"text": "L''eau montre la nouvelle naissance.", "translation": "Dieu la donne vraiment."}, "errorPatterns": [{"equals": "un simple symbole sans effet", "category": "word_confusion", "feedback": "Pour nous, le signe agit : par lui, Dieu donne sa grâce."}], "options": ["ce que le prêtre pense", "ce que l''Église a décidé au dernier concile", "un simple symbole sans effet", "ce que Dieu fait vraiment"], "id": "eg.l69.e04", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e05', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.ministre_du_sacrement']::text[], 'mcq', 'lesson', 'Qui est la source de la grâce dans un sacrement ?', array['le Christ']::text[], 'Le prêtre célèbre, mais c''est le Christ qui agit ; le prêtre est son serviteur.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.ministre_du_sacrement"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui est la source de la grâce dans un sacrement ?", "promptLanguage": "fr", "answer": "le Christ", "acceptedAnswers": ["le Christ"], "explanation": "Le prêtre célèbre, mais c''est le Christ qui agit ; le prêtre est son serviteur.", "tip": "Prêtre = serviteur, Christ = source.", "extraExample": {"text": "Au baptême, le prêtre prie.", "translation": "C''est le Christ qui renouvelle."}, "errorPatterns": [{"equals": "le prêtre", "category": "word_confusion", "feedback": "Le prêtre est le ministre du sacrement, mais la grâce vient du Christ."}], "options": ["l''évêque", "le Christ", "le prêtre", "l''assemblée des fidèles"], "id": "eg.l69.e05", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e06', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrements_uniques']::text[], 'mcq', 'lesson', 'Lequel de ces sacrements ne se répète pas ?', array['le baptême']::text[], 'Le baptême est une naissance : on ne naît qu''une fois. L''eucharistie, la confession et l''onction des malades reviennent au fil de la vie.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrements_uniques"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Lequel de ces sacrements ne se répète pas ?", "promptLanguage": "fr", "answer": "le baptême", "acceptedAnswers": ["le baptême"], "explanation": "Le baptême est une naissance : on ne naît qu''une fois. L''eucharistie, la confession et l''onction des malades reviennent au fil de la vie.", "tip": "Naissance = une fois.", "extraExample": {"text": "La confirmation ne se répète pas non plus.", "translation": "Le sacerdoce non plus."}, "options": ["la confession", "l''eucharistie", "l''onction des malades", "le baptême"], "id": "eg.l69.e06", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e07', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrements_uniques']::text[], 'mcq', 'lesson', 'Qu''impriment le baptême, la confirmation et le sacerdoce, ce qui explique qu''on ne les répète pas ?', array['une marque qui ne s''efface pas']::text[], 'Une marque qui ne s''efface pas n''a pas besoin d''être refaite.', 3, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrements_uniques"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''impriment le baptême, la confirmation et le sacerdoce, ce qui explique qu''on ne les répète pas ?", "promptLanguage": "fr", "answer": "une marque qui ne s''efface pas", "acceptedAnswers": ["une marque qui ne s''efface pas"], "explanation": "Une marque qui ne s''efface pas n''a pas besoin d''être refaite.", "tip": "Marque = une fois.", "extraExample": {"text": "On est scellé par l''Esprit une seule fois.", "translation": "La marque reste."}, "options": ["une marque qui ne s''efface pas", "un sceau que le prêtre peut effacer", "une dette envers l''Église", "un simple souvenir"], "id": "eg.l69.e07", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e08', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrements_repetables']::text[], 'mcq', 'lesson', 'Pourquoi l''eucharistie, la confession et l''onction des malades se répètent-elles ?', array['on a besoin de nourriture, de pardon et de guérison tout au long de la vie']::text[], 'Ces trois sacrements répondent à des besoins qui reviennent : se nourrir, être pardonné, être guéri.', 3, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrements_repetables"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi l''eucharistie, la confession et l''onction des malades se répètent-elles ?", "promptLanguage": "fr", "answer": "on a besoin de nourriture, de pardon et de guérison tout au long de la vie", "acceptedAnswers": ["on a besoin de nourriture, de pardon et de guérison tout au long de la vie"], "explanation": "Ces trois sacrements répondent à des besoins qui reviennent : se nourrir, être pardonné, être guéri.", "tip": "Besoins qui reviennent = sacrements qui reviennent.", "extraExample": {"text": "On a faim tous les jours.", "translation": "On a besoin du Christ tous les jours."}, "options": ["le prêtre change souvent", "l''Église veut en augmenter le nombre", "on a besoin de nourriture, de pardon et de guérison tout au long de la vie", "on les oublie vite"], "id": "eg.l69.e08", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e09', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.signe_visible']::text[], 'fill_blank', 'lesson', 'Un sacrement est un signe ___ qui donne une grâce invisible.', array['visible']::text[], 'Le signe est la partie que l''on voit : eau, huile, pain, geste.', 1, '{"unitIds": ["eg.g69.sacrement", "eg.v.signe_visible"], "type": "fill_blank", "difficulty": 1, "instruction": "Complète la phrase.", "prompt": "Un sacrement est un signe ___ qui donne une grâce invisible.", "promptLanguage": "fr", "answer": "visible", "acceptedAnswers": ["visible"], "explanation": "Le signe est la partie que l''on voit : eau, huile, pain, geste.", "tip": "Visible + invisible.", "extraExample": {"text": "L''huile est visible.", "translation": "La guérison ne l''est pas."}, "options": ["lointain", "visible", "secret", "écrit"], "id": "eg.l69.e09", "pool": "lesson", "lessonId": "eg.l69", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e10', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrements_uniques']::text[], 'fill_blank', 'lesson', 'Le baptême, la confirmation et le ___ ne se répètent pas.', array['sacerdoce']::text[], 'Ces trois sacrements impriment une marque qui ne s''efface pas.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrements_uniques"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le baptême, la confirmation et le ___ ne se répètent pas.", "promptLanguage": "fr", "answer": "sacerdoce", "acceptedAnswers": ["sacerdoce"], "explanation": "Ces trois sacrements impriment une marque qui ne s''efface pas.", "tip": "Trois sacrements uniques.", "extraExample": {"text": "Le sacerdoce se donne une fois par degré.", "translation": "Diacre, prêtre, évêque."}, "errorPatterns": [{"equals": "mariage", "category": "word_confusion", "feedback": "Le mariage est à part : une fois pour la vie des deux époux, mais ce n''est pas l''un des trois qui impriment une marque."}], "options": ["eucharistie", "mariage", "confession", "sacerdoce"], "id": "eg.l69.e10", "pool": "lesson", "lessonId": "eg.l69", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e11', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.ministre_du_sacrement']::text[], 'fill_blank', 'lesson', 'Le prêtre célèbre, mais c''est le ___ qui agit.', array['Christ']::text[], 'Le prêtre est le serviteur : l''action vient du Christ.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.ministre_du_sacrement"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le prêtre célèbre, mais c''est le ___ qui agit.", "promptLanguage": "fr", "answer": "Christ", "acceptedAnswers": ["Christ"], "explanation": "Le prêtre est le serviteur : l''action vient du Christ.", "tip": "Le Christ agit.", "extraExample": {"text": "Le prêtre prie.", "translation": "Le Christ pardonne."}, "options": ["parrain", "patriarche", "diacre", "Christ"], "id": "eg.l69.e11", "pool": "lesson", "lessonId": "eg.l69", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e12', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrement','eg.v.sacrements_repetables']::text[], 'match', 'lesson', 'Se répète ou non ?', '{}'::text[], 'Trois sacrements sont uniques, trois se répètent, et le mariage est à part.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrement", "eg.v.sacrements_repetables"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Se répète ou non ?", "promptLanguage": "fr", "explanation": "Trois sacrements sont uniques, trois se répètent, et le mariage est à part.", "tip": "3 uniques, 3 qui reviennent, 1 à part.", "pairs": [{"left": "Baptême, confirmation, sacerdoce", "right": "ne se répètent pas"}, {"left": "Eucharistie, confession, onction des malades", "right": "se répètent"}, {"left": "Mariage", "right": "une fois, pour la vie des deux époux"}], "answer": "Baptême, confirmation, sacerdoce = ne se répètent pas ; Eucharistie, confession, onction des malades = se répètent ; Mariage = une fois, pour la vie des deux époux", "acceptedAnswers": [], "id": "eg.l69.e12", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e13', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrement','eg.v.ministre_du_sacrement']::text[], 'match', 'lesson', 'Les éléments d''un sacrement', '{}'::text[], 'Un sacrement associe un signe, une grâce, un ministre et une origine dans le Christ.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrement", "eg.v.ministre_du_sacrement"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les éléments d''un sacrement", "promptLanguage": "fr", "explanation": "Un sacrement associe un signe, une grâce, un ministre et une origine dans le Christ.", "tip": "Signe, grâce, ministre, Christ.", "pairs": [{"left": "Le signe", "right": "ce qu''on voit : eau, huile, pain"}, {"left": "La grâce", "right": "le don invisible de Dieu"}, {"left": "Le ministre", "right": "le prêtre ou l''évêque"}, {"left": "L''institution", "right": "le Christ ou les apôtres"}], "answer": "Le signe = ce qu''on voit : eau, huile, pain ; La grâce = le don invisible de Dieu ; Le ministre = le prêtre ou l''évêque ; L''institution = le Christ ou les apôtres", "acceptedAnswers": [], "id": "eg.l69.e13", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e14', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrement']::text[], 'reorder', 'lesson', 'Phrase-repère : la définition.', array['Un sacrement est un signe visible d''une grâce invisible']::text[], 'C''est la définition à retenir : on voit le signe, on ne voit pas la grâce.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrement"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : la définition.", "promptLanguage": "fr", "answer": "Un sacrement est un signe visible d''une grâce invisible", "acceptedAnswers": ["Un sacrement est un signe visible d''une grâce invisible"], "explanation": "C''est la définition à retenir : on voit le signe, on ne voit pas la grâce.", "tip": "Visible, invisible.", "extraExample": {"text": "Le qandil est un signe visible.", "translation": "Il donne la guérison."}, "tokens": ["Un", "est", "invisible", "un", "visible", "signe", "grâce", "sacrement", "d''une"], "id": "eg.l69.e14", "pool": "lesson", "lessonId": "eg.l69", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e15', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrement']::text[], 'free_answer', 'lesson', 'Quel mot, dans l''Église copte, veut aussi dire « sacrement » ?', array['mystère','mystere','un mystère','le mystère','mystères']::text[], 'On parle des sept mystères de l''Église.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrement"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot, dans l''Église copte, veut aussi dire « sacrement » ?", "promptLanguage": "fr", "answer": "mystère", "acceptedAnswers": ["mystère", "mystere", "un mystère", "le mystère", "mystères"], "explanation": "On parle des sept mystères de l''Église.", "tip": "Mystère = sacrement.", "extraExample": {"text": "Le baptême est un mystère.", "translation": "Un sacrement."}, "id": "eg.l69.e15", "pool": "lesson", "lessonId": "eg.l69", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e16', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrement']::text[], 'free_answer', 'lesson', 'Combien y a-t-il de sacrements dans l''Église copte ?', array['sept','7','7 sacrements','sept sacrements']::text[], 'Baptême, confirmation, eucharistie, confession, onction des malades, mariage et sacerdoce.', 2, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrement"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Combien y a-t-il de sacrements dans l''Église copte ?", "promptLanguage": "fr", "answer": "sept", "acceptedAnswers": ["sept", "7", "7 sacrements", "sept sacrements"], "explanation": "Baptême, confirmation, eucharistie, confession, onction des malades, mariage et sacerdoce.", "tip": "Sept.", "extraExample": {"text": "Les catholiques en comptent aussi sept.", "translation": "Les protestants deux."}, "id": "eg.l69.e16", "pool": "lesson", "lessonId": "eg.l69", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e17', 'eg', 'eg.l69', 'eg.g69.sacrement', array['eg.g69.sacrement','eg.v.sacrements_repetables']::text[], 'free_answer', 'lesson', 'Cite un sacrement qui se répète.', array['l''eucharistie','eucharistie','la communion','communion','la confession','confession','l''onction des malades','onction des malades','la pénitence','le qandil']::text[], 'L''eucharistie, la confession et l''onction des malades reviennent au fil de la vie.', 3, '{"unitIds": ["eg.g69.sacrement", "eg.v.sacrements_repetables"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Cite un sacrement qui se répète.", "promptLanguage": "fr", "answer": "l''eucharistie", "acceptedAnswers": ["l''eucharistie", "eucharistie", "la communion", "communion", "la confession", "confession", "l''onction des malades", "onction des malades", "la pénitence", "le qandil"], "explanation": "L''eucharistie, la confession et l''onction des malades reviennent au fil de la vie.", "tip": "Nourriture, pardon, guérison.", "extraExample": {"text": "On communie souvent.", "translation": "On se confesse régulièrement."}, "id": "eg.l69.e17", "pool": "lesson", "lessonId": "eg.l69", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e18', 'eg', 'eg.l69', 'eg.v.deux_sacrements', array['eg.v.deux_sacrements']::text[], 'mcq', 'lesson', 'Quels sont les deux sacrements que garde la plupart des protestants ?', array['le baptême et la Cène']::text[], 'Rappel de la comparaison avec les protestants : deux sacrements, le baptême et la Cène.', 1, '{"unitIds": ["eg.v.deux_sacrements"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quels sont les deux sacrements que garde la plupart des protestants ?", "promptLanguage": "fr", "answer": "le baptême et la Cène", "acceptedAnswers": ["le baptême et la Cène"], "explanation": "Rappel de la comparaison avec les protestants : deux sacrements, le baptême et la Cène.", "tip": "Deux = baptême + Cène.", "extraExample": {"text": "Les Coptes en gardent sept.", "translation": "Les catholiques aussi."}, "options": ["la confirmation et l''onction", "la confession et le mariage", "l''eucharistie et le sacerdoce", "le baptême et la Cène"], "id": "eg.l69.e18", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e19', 'eg', 'eg.l69', 'eg.v.sept_sacrements', array['eg.v.sept_sacrements']::text[], 'mcq', 'lesson', 'Combien de sacrements les catholiques et les Coptes partagent-ils ?', array['sept']::text[], 'Rappel : sept sacrements des deux côtés, contre deux chez la plupart des protestants.', 1, '{"unitIds": ["eg.v.sept_sacrements"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de sacrements les catholiques et les Coptes partagent-ils ?", "promptLanguage": "fr", "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Rappel : sept sacrements des deux côtés, contre deux chez la plupart des protestants.", "tip": "Sept des deux côtés.", "extraExample": {"text": "Coptes : sept.", "translation": "Catholiques : sept."}, "options": ["sept", "douze", "trois", "deux"], "id": "eg.l69.e19", "pool": "lesson", "lessonId": "eg.l69", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e20', 'eg', 'eg.l69', 'eg.v.pain_leve', array['eg.v.pain_leve']::text[], 'fill_blank', 'lesson', 'Pour l''eucharistie, l''Église copte utilise du pain ___.', array['levé']::text[], 'Rappel : l''Église copte consacre du pain levé, les catholiques latins du pain azyme.', 2, '{"unitIds": ["eg.v.pain_leve"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Pour l''eucharistie, l''Église copte utilise du pain ___.", "promptLanguage": "fr", "answer": "levé", "acceptedAnswers": ["levé"], "explanation": "Rappel : l''Église copte consacre du pain levé, les catholiques latins du pain azyme.", "tip": "Levé chez nous.", "extraExample": {"text": "Le pain levé rappelle la Résurrection.", "translation": "Il est marqué d''une croix."}, "options": ["levé", "azyme", "grillé", "sans eau"], "id": "eg.l69.e20", "pool": "lesson", "lessonId": "eg.l69", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l69.e21', 'eg', 'eg.l69', 'eg.v.succession_apostolique', array['eg.v.succession_apostolique']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on la suite des évêques ordonnés l''un par l''autre jusqu''aux apôtres ?', array['succession apostolique','la succession apostolique','successions apostoliques']::text[], 'Rappel : chaque évêque est ordonné par d''autres, jusqu''aux apôtres.', 2, '{"unitIds": ["eg.v.succession_apostolique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on la suite des évêques ordonnés l''un par l''autre jusqu''aux apôtres ?", "promptLanguage": "fr", "answer": "succession apostolique", "acceptedAnswers": ["succession apostolique", "la succession apostolique", "successions apostoliques"], "explanation": "Rappel : chaque évêque est ordonné par d''autres, jusqu''aux apôtres.", "tip": "Succession = continuité.", "extraExample": {"text": "Tawadros II est le 118e successeur de saint Marc.", "translation": "Il est dans cette suite."}, "id": "eg.l69.e21", "pool": "lesson", "lessonId": "eg.l69", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e01', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.bapteme']::text[], 'mcq', 'lesson', 'Pourquoi appelle-t-on le baptême la porte de l''Église ?', array['sans lui, on ne reçoit pas les autres']::text[], 'Le baptême est le premier : on ne peut recevoir les autres qu''après lui.', 1, '{"unitIds": ["eg.g70.bapteme", "eg.v.bapteme"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi appelle-t-on le baptême la porte de l''Église ?", "promptLanguage": "fr", "answer": "sans lui, on ne reçoit pas les autres", "acceptedAnswers": ["sans lui, on ne reçoit pas les autres"], "explanation": "Le baptême est le premier : on ne peut recevoir les autres qu''après lui.", "tip": "Première porte.", "extraExample": {"text": "On est baptisé avant de communier.", "translation": "On est baptisé avant de se marier."}, "options": ["il est le plus long des sacrements", "sans lui, on ne reçoit pas les autres", "il est célébré à la porte de l''église", "il remplace la messe"], "id": "eg.l70.e01", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e02', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.bapteme']::text[], 'mcq', 'lesson', 'Quelle parole du Christ fonde le baptême ?', array['Baptisez-les au nom du Père, du Fils et du Saint-Esprit']::text[], 'Mt 28, 19 est l''ordre de baptiser au nom de la Trinité.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.bapteme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle parole du Christ fonde le baptême ?", "promptLanguage": "fr", "answer": "Baptisez-les au nom du Père, du Fils et du Saint-Esprit", "acceptedAnswers": ["Baptisez-les au nom du Père, du Fils et du Saint-Esprit"], "explanation": "Mt 28, 19 est l''ordre de baptiser au nom de la Trinité.", "tip": "Mt 28, 19.", "extraExample": {"text": "Jn 3, 5 parle de naître d''eau et d''Esprit.", "translation": "C''est le second fondement."}, "errorPatterns": [{"equals": "Prenez, mangez, ceci est mon corps", "category": "word_confusion", "feedback": "Cette parole fonde l''eucharistie, pas le baptême."}], "options": ["Recevez l''Esprit Saint", "Baptisez-les au nom du Père, du Fils et du Saint-Esprit", "Ce que Dieu a uni, que l''homme ne le sépare pas", "Prenez, mangez, ceci est mon corps"], "id": "eg.l70.e02", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e03', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.triple_immersion']::text[], 'mcq', 'lesson', 'Combien de fois plonge-t-on le baptisé dans l''eau ?', array['trois fois']::text[], 'Une immersion pour chaque Personne de la Trinité.', 1, '{"unitIds": ["eg.g70.bapteme", "eg.v.triple_immersion"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de fois plonge-t-on le baptisé dans l''eau ?", "promptLanguage": "fr", "answer": "trois fois", "acceptedAnswers": ["trois fois"], "explanation": "Une immersion pour chaque Personne de la Trinité.", "tip": "Trois : le Père, le Fils, le Saint-Esprit.", "extraExample": {"text": "Le prêtre dit chaque nom.", "translation": "On est plongé à chaque nom."}, "options": ["une fois", "trois fois", "deux fois", "sept fois"], "id": "eg.l70.e03", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e04', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.triple_immersion']::text[], 'mcq', 'lesson', 'Que rappellent les trois immersions, en plus de la Trinité ?', array['les trois jours du Christ au tombeau']::text[], 'On descend dans l''eau comme on est enseveli, on en remonte comme le Christ ressuscité (Rm 6, 3-4).', 3, '{"unitIds": ["eg.g70.bapteme", "eg.v.triple_immersion"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que rappellent les trois immersions, en plus de la Trinité ?", "promptLanguage": "fr", "answer": "les trois jours du Christ au tombeau", "acceptedAnswers": ["les trois jours du Christ au tombeau"], "explanation": "On descend dans l''eau comme on est enseveli, on en remonte comme le Christ ressuscité (Rm 6, 3-4).", "tip": "Trois jours, trois immersions.", "extraExample": {"text": "L''eau est un tombeau.", "translation": "Et un lieu de naissance."}, "options": ["les trois Rois mages", "les trois jours du Christ au tombeau", "les trois jeûnes de l''année", "les trois premiers conciles"], "id": "eg.l70.e04", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e05', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.bapteme']::text[], 'mcq', 'lesson', 'Que veut dire le mot grec baptizein ?', array['plonger']::text[], 'On plonge vraiment le baptisé : l''eau est un tombeau et une naissance.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.bapteme"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le mot grec baptizein ?", "promptLanguage": "fr", "answer": "plonger", "acceptedAnswers": ["plonger"], "explanation": "On plonge vraiment le baptisé : l''eau est un tombeau et une naissance.", "tip": "Baptizein = plonger.", "extraExample": {"text": "Le baptême est une immersion.", "translation": "Pas une aspersion."}, "options": ["bénir", "oindre", "plonger", "laver du bout des doigts"], "id": "eg.l70.e05", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e06', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.renoncement_a_satan']::text[], 'mcq', 'lesson', 'Vers où se tourne le baptisé pour renoncer à Satan ?', array['vers l''ouest']::text[], 'L''ouest, où le soleil disparaît, est l''image des ténèbres et de l''exil loin de Dieu.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.renoncement_a_satan"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Vers où se tourne le baptisé pour renoncer à Satan ?", "promptLanguage": "fr", "answer": "vers l''ouest", "acceptedAnswers": ["vers l''ouest"], "explanation": "L''ouest, où le soleil disparaît, est l''image des ténèbres et de l''exil loin de Dieu.", "tip": "Ouest = ténèbres.", "extraExample": {"text": "On rejette Satan vers l''ouest.", "translation": "On confesse le Christ vers l''est."}, "errorPatterns": [{"equals": "vers l''est", "category": "word_confusion", "feedback": "L''est est le côté où l''on confesse le Christ, pas celui où l''on renonce à Satan."}], "options": ["vers le nord", "vers l''est", "vers le prêtre", "vers l''ouest"], "id": "eg.l70.e06", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e07', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.profession_de_foi']::text[], 'mcq', 'lesson', 'Pourquoi se tourne-t-on vers l''est pour confesser le Christ ?', array['là où le soleil se lève']::text[], 'L''est est l''image du Christ, lumière du monde, et de la nouvelle naissance.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.profession_de_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi se tourne-t-on vers l''est pour confesser le Christ ?", "promptLanguage": "fr", "answer": "là où le soleil se lève", "acceptedAnswers": ["là où le soleil se lève"], "explanation": "L''est est l''image du Christ, lumière du monde, et de la nouvelle naissance.", "tip": "Est = lumière.", "extraExample": {"text": "Le soleil se lève à l''est.", "translation": "Le Christ est la lumière du monde."}, "options": ["là où le soleil se lève", "parce que l''église est toujours à l''est", "pour regarder le parrain", "parce que le prêtre l''exige"], "id": "eg.l70.e07", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e08', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.quarante_quatre_vingts_jours']::text[], 'mcq', 'lesson', 'D''où vient la différence entre 40 et 80 jours ?', array['du Lévitique 12']::text[], 'Le Lévitique 12 fixe 40 jours de purification de la mère après un garçon, 80 après une fille.', 3, '{"unitIds": ["eg.g70.bapteme", "eg.v.quarante_quatre_vingts_jours"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "D''où vient la différence entre 40 et 80 jours ?", "promptLanguage": "fr", "answer": "du Lévitique 12", "acceptedAnswers": ["du Lévitique 12"], "explanation": "Le Lévitique 12 fixe 40 jours de purification de la mère après un garçon, 80 après une fille.", "tip": "Lv 12.", "extraExample": {"text": "Le Nouveau Testament n''explique pas la différence.", "translation": "C''est un usage ancien."}, "options": ["de l''Évangile de Jean", "du Lévitique 12", "d''une décision du patriarche", "du concile de Nicée"], "id": "eg.l70.e08", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e09', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.bapteme_des_enfants']::text[], 'mcq', 'lesson', 'Pour saint Paul, quel rite le baptême remplace-t-il (Col 2, 11-12) ?', array['la circoncision']::text[], 'Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés : on peut donc baptiser les bébés.', 3, '{"unitIds": ["eg.g70.bapteme", "eg.v.bapteme_des_enfants"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pour saint Paul, quel rite le baptême remplace-t-il (Col 2, 11-12) ?", "promptLanguage": "fr", "answer": "la circoncision", "acceptedAnswers": ["la circoncision"], "explanation": "Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés : on peut donc baptiser les bébés.", "tip": "Circoncision = baptême.", "extraExample": {"text": "Les maisons entières sont baptisées.", "translation": "Cela inclut les enfants."}, "options": ["la circoncision", "la Pâque juive", "le sacrifice d''animaux", "le jeûne"], "id": "eg.l70.e09", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e10', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.nouvelle_naissance']::text[], 'mcq', 'lesson', 'Que donne le baptême, en plus du pardon des péchés ?', array['une nouvelle naissance']::text[], 'Le baptême pardonne le péché originel et les péchés personnels, et fait naître de nouveau.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.nouvelle_naissance"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que donne le baptême, en plus du pardon des péchés ?", "promptLanguage": "fr", "answer": "une nouvelle naissance", "acceptedAnswers": ["une nouvelle naissance"], "explanation": "Le baptême pardonne le péché originel et les péchés personnels, et fait naître de nouveau.", "tip": "Pardon + naissance.", "extraExample": {"text": "Il ouvre la porte des autres sacrements.", "translation": "On ne le refait jamais."}, "options": ["la guérison de toutes les maladies", "le droit de célébrer la messe", "la couronne du mariage", "une nouvelle naissance"], "id": "eg.l70.e10", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
