insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e12', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.quarante_quatre_vingts_jours']::text[], 'fill_blank', 'lesson', 'Le garçon est baptisé vers le 40e jour, la fille vers le ___ jour.', array['80e']::text[], 'La fille attend 80 jours, comme le fixe Lv 12.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.quarante_quatre_vingts_jours"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le garçon est baptisé vers le 40e jour, la fille vers le ___ jour.", "promptLanguage": "fr", "answer": "80e", "acceptedAnswers": ["80e"], "explanation": "La fille attend 80 jours, comme le fixe Lv 12.", "tip": "40 pour le garçon, 80 pour la fille.", "extraExample": {"text": "C''est l''usage de l''Église copte.", "translation": "Il vient du Lévitique 12."}, "options": ["100e", "80e", "7e", "8e"], "id": "eg.l70.e12", "pool": "lesson", "lessonId": "eg.l70", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e13', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.renoncement_a_satan']::text[], 'fill_blank', 'lesson', 'On renonce à Satan en se tournant vers l''___.', array['ouest']::text[], 'L''ouest est le côté des ténèbres.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.renoncement_a_satan"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "On renonce à Satan en se tournant vers l''___.", "promptLanguage": "fr", "answer": "ouest", "acceptedAnswers": ["ouest"], "explanation": "L''ouest est le côté des ténèbres.", "tip": "Ouest : on rejette.", "extraExample": {"text": "L''est est le côté de la lumière.", "translation": "On y confesse le Christ."}, "options": ["est", "sud", "nord", "ouest"], "id": "eg.l70.e13", "pool": "lesson", "lessonId": "eg.l70", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e14', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.parrain']::text[], 'fill_blank', 'lesson', 'Le parrain s''engage à élever l''enfant dans la ___.', array['foi']::text[], 'Il est comme un second père dans l''Église.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.parrain"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Le parrain s''engage à élever l''enfant dans la ___.", "promptLanguage": "fr", "answer": "foi", "acceptedAnswers": ["foi"], "explanation": "Il est comme un second père dans l''Église.", "tip": "Parrain = foi.", "extraExample": {"text": "Il l''accompagne ensuite.", "translation": "Il prie pour lui."}, "options": ["mode", "richesse", "foi", "crainte"], "id": "eg.l70.e14", "pool": "lesson", "lessonId": "eg.l70", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e15', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.renoncement_a_satan','eg.v.profession_de_foi']::text[], 'match', 'lesson', 'Les deux directions du baptisé', '{}'::text[], 'L''ouest et l''est ont chacun un sens ; les 40 et 80 jours viennent de Lv 12.', 2, '{"unitIds": ["eg.g70.bapteme", "eg.v.renoncement_a_satan", "eg.v.profession_de_foi"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les deux directions du baptisé", "promptLanguage": "fr", "explanation": "L''ouest et l''est ont chacun un sens ; les 40 et 80 jours viennent de Lv 12.", "tip": "Ouest : rejeter. Est : choisir.", "pairs": [{"left": "Vers l''ouest", "right": "renoncer à Satan"}, {"left": "Vers l''est", "right": "confesser le Christ"}, {"left": "Garçon", "right": "40e jour"}, {"left": "Fille", "right": "80e jour"}], "answer": "Vers l''ouest = renoncer à Satan ; Vers l''est = confesser le Christ ; Garçon = 40e jour ; Fille = 80e jour", "acceptedAnswers": [], "id": "eg.l70.e15", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e16', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.bapteme']::text[], 'match', 'lesson', 'Les versets du baptême', '{}'::text[], 'Chaque verset éclaire un aspect : l''ordre, la naissance, la mort et la résurrection, la circoncision.', 3, '{"unitIds": ["eg.g70.bapteme", "eg.v.bapteme"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les versets du baptême", "promptLanguage": "fr", "explanation": "Chaque verset éclaire un aspect : l''ordre, la naissance, la mort et la résurrection, la circoncision.", "tip": "Quatre versets, quatre idées.", "pairs": [{"left": "Mt 28, 19", "right": "l''ordre de baptiser au nom de la Trinité"}, {"left": "Jn 3, 5", "right": "naître d''eau et d''Esprit"}, {"left": "Rm 6, 3-4", "right": "ensevelis avec le Christ"}, {"left": "Col 2, 11-12", "right": "le baptême prend la place de la circoncision"}], "answer": "Mt 28, 19 = l''ordre de baptiser au nom de la Trinité ; Jn 3, 5 = naître d''eau et d''Esprit ; Rm 6, 3-4 = ensevelis avec le Christ ; Col 2, 11-12 = le baptême prend la place de la circoncision", "acceptedAnswers": [], "id": "eg.l70.e16", "pool": "lesson", "lessonId": "eg.l70", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e17', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.renoncement_a_satan','eg.v.profession_de_foi']::text[], 'reorder', 'lesson', 'Phrase-repère : les deux directions.', array['On renonce à Satan vers l''ouest puis on confesse le Christ vers l''est']::text[], 'On rejette d''abord le mal, puis on choisit le Christ.', 3, '{"unitIds": ["eg.g70.bapteme", "eg.v.renoncement_a_satan", "eg.v.profession_de_foi"], "type": "reorder", "difficulty": 3, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : les deux directions.", "promptLanguage": "fr", "answer": "On renonce à Satan vers l''ouest puis on confesse le Christ vers l''est", "acceptedAnswers": ["On renonce à Satan vers l''ouest puis on confesse le Christ vers l''est"], "explanation": "On rejette d''abord le mal, puis on choisit le Christ.", "tip": "Ouest puis est.", "extraExample": {"text": "Le soleil disparaît à l''ouest.", "translation": "Il se lève à l''est."}, "tokens": ["vers", "confesse", "puis", "l''est", "à", "Satan", "l''ouest", "renonce", "on", "Christ", "vers", "On", "le"], "id": "eg.l70.e17", "pool": "lesson", "lessonId": "eg.l70", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l70.e18', 'eg', 'eg.l70', 'eg.g70.bapteme', array['eg.g70.bapteme','eg.v.parrain']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on celui qui répond à la place de l''enfant au baptême ?', array['le parrain','parrain','la marraine','marraine','un parrain']::text[], 'Le parrain ou la marraine répond pour le bébé.', 1, '{"unitIds": ["eg.g70.bapteme", "eg.v.parrain"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on celui qui répond à la place de l''enfant au baptême ?", "promptLanguage": "fr", "answer": "le parrain", "acceptedAnswers": ["le parrain", "parrain", "la marraine", "marraine", "un parrain"], "explanation": "Le parrain ou la marraine répond pour le bébé.", "tip": "Parrain = voix du bébé.", "extraExample": {"text": "Il renonce à Satan pour lui.", "translation": "Il confesse le Christ pour lui."}, "id": "eg.l70.e18", "pool": "lesson", "lessonId": "eg.l70", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
