insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l71.e07', 'eg', 'eg.l71', 'eg.g71.confirmation', array['eg.g71.confirmation','eg.v.preparation_du_myron']::text[], 'mcq', 'lesson', 'Qu''ajoute-t-on au nouveau myron à chaque préparation ?', array['un peu de l''ancien myron']::text[], 'Cela montre la continuité : c''est la même huile depuis les apôtres.', 3, '{"unitIds": ["eg.g71.confirmation", "eg.v.preparation_du_myron"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Qu''ajoute-t-on au nouveau myron à chaque préparation ?", "promptLanguage": "fr", "answer": "un peu de l''ancien myron", "acceptedAnswers": ["un peu de l''ancien myron"], "explanation": "Cela montre la continuité : c''est la même huile depuis les apôtres.", "tip": "Même huile, génération après génération.", "extraExample": {"text": "Un peu d''ancien myron.", "translation": "Le lien avec les apôtres."}, "options": ["des cheveux du baptisé", "de la cendre", "un peu d''eau du Nil", "un peu de l''ancien myron"], "id": "eg.l71.e07", "pool": "lesson", "lessonId": "eg.l71", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
