insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l71.e09', 'eg', 'eg.l71', 'eg.g71.confirmation', array['eg.g71.confirmation','eg.v.confirmation']::text[], 'mcq', 'lesson', 'Qui donne la confirmation chez les Coptes, même aux bébés ?', array['le prêtre']::text[], 'Contrairement aux Latins, qui confirment plus tard par l''évêque, le prêtre confirme aussitôt après le baptême.', 2, '{"unitIds": ["eg.g71.confirmation", "eg.v.confirmation"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui donne la confirmation chez les Coptes, même aux bébés ?", "promptLanguage": "fr", "answer": "le prêtre", "acceptedAnswers": ["le prêtre"], "explanation": "Contrairement aux Latins, qui confirment plus tard par l''évêque, le prêtre confirme aussitôt après le baptême.", "tip": "Prêtre, tout de suite.", "extraExample": {"text": "Le myron est consacré par le patriarche.", "translation": "Le prêtre l''utilise."}, "errorPatterns": [{"equals": "l''évêque seulement", "category": "word_confusion", "feedback": "Chez les Coptes, c''est le prêtre qui administre la confirmation ; l''évêque (le patriarche) consacre le myron."}], "options": ["l''évêque seulement", "le diacre", "le parrain", "le prêtre"], "id": "eg.l71.e09", "pool": "lesson", "lessonId": "eg.l71", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
