insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l71.e20', 'eg', 'eg.l71', 'eg.g71.confirmation', array['eg.g71.confirmation','eg.v.confirmation']::text[], 'free_answer', 'lesson', 'Quel sacrement donne le sceau du Saint-Esprit ?', array['la confirmation','confirmation','chrismation','la chrismation','le saint myron','myron']::text[], 'C''est la confirmation, par le saint myron.', 2, '{"unitIds": ["eg.g71.confirmation", "eg.v.confirmation"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel sacrement donne le sceau du Saint-Esprit ?", "promptLanguage": "fr", "answer": "la confirmation", "acceptedAnswers": ["la confirmation", "confirmation", "chrismation", "la chrismation", "le saint myron", "myron"], "explanation": "C''est la confirmation, par le saint myron.", "tip": "Sceau = confirmation.", "extraExample": {"text": "Chrismation est le même mot.", "translation": "Elle suit le baptême."}, "id": "eg.l71.e20", "pool": "lesson", "lessonId": "eg.l71", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l71.e21', 'eg', 'eg.l71', 'eg.v.profession_de_foi', array['eg.v.profession_de_foi']::text[], 'mcq', 'lesson', 'Vers quel point cardinal se tourne-t-on pour confesser le Christ ?', array['vers l''est']::text[], 'Rappel : l''est, là où se lève le soleil, est le côté de la lumière.', 2, '{"unitIds": ["eg.v.profession_de_foi"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quel point cardinal se tourne-t-on pour confesser le Christ ?", "promptLanguage": "fr", "answer": "vers l''est", "acceptedAnswers": ["vers l''est"], "explanation": "Rappel : l''est, là où se lève le soleil, est le côté de la lumière.", "tip": "Est = confession.", "extraExample": {"text": "L''ouest est pour renoncer.", "translation": "L''est pour confesser."}, "options": ["vers l''est", "vers l''ouest", "vers le sud", "vers le nord"], "id": "eg.l71.e21", "pool": "lesson", "lessonId": "eg.l71", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l71.e22', 'eg', 'eg.l71', 'eg.v.quarante_quatre_vingts_jours', array['eg.v.quarante_quatre_vingts_jours']::text[], 'fill_blank', 'lesson', 'Selon l''usage, le garçon est baptisé le 40e jour, mais la fille le ___ jour.', array['80e']::text[], 'Rappel : la règle vient de Lv 12.', 2, '{"unitIds": ["eg.v.quarante_quatre_vingts_jours"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Selon l''usage, le garçon est baptisé le 40e jour, mais la fille le ___ jour.", "promptLanguage": "fr", "answer": "80e", "acceptedAnswers": ["80e"], "explanation": "Rappel : la règle vient de Lv 12.", "tip": "40 pour le garçon, 80 pour la fille.", "extraExample": {"text": "C''est l''usage.", "translation": "Le Nouveau Testament n''explique pas."}, "options": ["7e", "8e", "80e", "100e"], "id": "eg.l71.e22", "pool": "lesson", "lessonId": "eg.l71", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l71.e23', 'eg', 'eg.l71', 'eg.v.parrain', array['eg.v.parrain']::text[], 'free_answer', 'lesson', 'Comment s''appelle celui qui répond à la place de l''enfant au baptême ?', array['le parrain','parrain','la marraine','marraine']::text[], 'Rappel : le parrain renonce à Satan et confesse le Christ pour l''enfant.', 1, '{"unitIds": ["eg.v.parrain"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle celui qui répond à la place de l''enfant au baptême ?", "promptLanguage": "fr", "answer": "le parrain", "acceptedAnswers": ["le parrain", "parrain", "la marraine", "marraine"], "explanation": "Rappel : le parrain renonce à Satan et confesse le Christ pour l''enfant.", "tip": "Parrain = voix du bébé.", "extraExample": {"text": "Il s''engage à l''éduquer.", "translation": "Il tient l''enfant."}, "id": "eg.l71.e23", "pool": "lesson", "lessonId": "eg.l71", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l71.e24', 'eg', 'eg.l71', 'eg.v.sacrements_uniques', array['eg.v.sacrements_uniques']::text[], 'mcq', 'lesson', 'Comme le baptême, la confirmation imprime quoi dans l''âme, ce qui empêche de la répéter ?', array['une marque qui ne s''efface pas']::text[], 'Rappel : baptême, confirmation et sacerdoce impriment une marque qui ne s''efface pas.', 3, '{"unitIds": ["eg.v.sacrements_uniques"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Comme le baptême, la confirmation imprime quoi dans l''âme, ce qui empêche de la répéter ?", "promptLanguage": "fr", "answer": "une marque qui ne s''efface pas", "acceptedAnswers": ["une marque qui ne s''efface pas"], "explanation": "Rappel : baptême, confirmation et sacerdoce impriment une marque qui ne s''efface pas.", "tip": "Marque = une fois.", "extraExample": {"text": "Le sceau est unique.", "translation": "On ne le refait jamais."}, "options": ["un sceau que le prêtre peut effacer", "une dette envers l''Église", "un simple souvenir", "une marque qui ne s''efface pas"], "id": "eg.l71.e24", "pool": "lesson", "lessonId": "eg.l71", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l72.e01', 'eg', 'eg.l72', 'eg.g72.eucharistie', array['eg.g72.eucharistie','eg.v.eucharistie']::text[], 'mcq', 'lesson', 'Que veut dire « eucharistie » en grec ?', array['action de grâce']::text[], 'On remercie Dieu en recevant le Corps et le Sang du Christ.', 1, '{"unitIds": ["eg.g72.eucharistie", "eg.v.eucharistie"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire « eucharistie » en grec ?", "promptLanguage": "fr", "answer": "action de grâce", "acceptedAnswers": ["action de grâce"], "explanation": "On remercie Dieu en recevant le Corps et le Sang du Christ.", "tip": "Eucharistie = merci.", "extraExample": {"text": "On dit merci à Dieu.", "translation": "Chaque messe."}, "options": ["action de grâce", "pain béni", "prière du matin", "repas de fête"], "id": "eg.l72.e01", "pool": "lesson", "lessonId": "eg.l72", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l72.e02', 'eg', 'eg.l72', 'eg.g72.eucharistie', array['eg.g72.eucharistie','eg.v.derniere_cene']::text[], 'mcq', 'lesson', 'Quelle parole de Jésus fonde l''eucharistie ?', array['Prenez, mangez, ceci est mon corps']::text[], 'Mt 26, 26 : Jésus donne le pain comme son corps.', 2, '{"unitIds": ["eg.g72.eucharistie", "eg.v.derniere_cene"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle parole de Jésus fonde l''eucharistie ?", "promptLanguage": "fr", "answer": "Prenez, mangez, ceci est mon corps", "acceptedAnswers": ["Prenez, mangez, ceci est mon corps"], "explanation": "Mt 26, 26 : Jésus donne le pain comme son corps.", "tip": "Mt 26, 26.", "extraExample": {"text": "Il ajoute : « Faites ceci en mémoire de moi ».", "translation": "C''est Lc 22, 19."}, "errorPatterns": [{"equals": "Baptisez-les au nom du Père", "category": "word_confusion", "feedback": "Cette parole fonde le baptême, pas l''eucharistie."}], "options": ["Baptisez-les au nom du Père", "Recevez l''Esprit Saint", "Prenez, mangez, ceci est mon corps", "Qu''il appelle les anciens de l''Église"], "id": "eg.l72.e02", "pool": "lesson", "lessonId": "eg.l72", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l72.e03', 'eg', 'eg.l72', 'eg.g72.eucharistie', array['eg.g72.eucharistie','eg.v.presence_reelle']::text[], 'mcq', 'lesson', 'Que deviennent le pain et le vin consacrés pour l''Église copte ?', array['vraiment le Corps et le Sang du Christ']::text[], 'C''est la présence réelle : le Christ est vraiment là.', 2, '{"unitIds": ["eg.g72.eucharistie", "eg.v.presence_reelle"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que deviennent le pain et le vin consacrés pour l''Église copte ?", "promptLanguage": "fr", "answer": "vraiment le Corps et le Sang du Christ", "acceptedAnswers": ["vraiment le Corps et le Sang du Christ"], "explanation": "C''est la présence réelle : le Christ est vraiment là.", "tip": "Présence réelle.", "extraExample": {"text": "Les catholiques le croient aussi.", "translation": "Beaucoup de protestants parlent de mémorial."}, "errorPatterns": [{"equals": "un simple souvenir de la dernière Cène", "category": "word_confusion", "feedback": "Un simple souvenir (mémorial) est la position de beaucoup de protestants, pas celle de l''Église copte."}], "options": ["une image de l''Église", "un simple souvenir de la dernière Cène", "du pain béni sans changement", "vraiment le Corps et le Sang du Christ"], "id": "eg.l72.e03", "pool": "lesson", "lessonId": "eg.l72", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l72.e04', 'eg', 'eg.l72', 'eg.g72.eucharistie', array['eg.g72.eucharistie','eg.v.presence_reelle']::text[], 'mcq', 'lesson', 'Pourquoi croyons-nous à la présence réelle ?', array['Jésus a dit « ceci est », pas « ceci représente »']::text[], 'Nous suivons les paroles de Jésus à la lettre (Mt 26, 26 et Jn 6, 54).', 3, '{"unitIds": ["eg.g72.eucharistie", "eg.v.presence_reelle"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pourquoi croyons-nous à la présence réelle ?", "promptLanguage": "fr", "answer": "Jésus a dit « ceci est », pas « ceci représente »", "acceptedAnswers": ["Jésus a dit « ceci est », pas « ceci représente »"], "explanation": "Nous suivons les paroles de Jésus à la lettre (Mt 26, 26 et Jn 6, 54).", "tip": "« Ceci est ».", "extraExample": {"text": "Jn 6, 54 est très fort.", "translation": "« Qui mange ma chair »."}, "options": ["parce que le pain est beau", "Jésus a dit « ceci est », pas « ceci représente »", "parce que les premiers conciles l''ont voulu", "parce que le prêtre est saint"], "id": "eg.l72.e04", "pool": "lesson", "lessonId": "eg.l72", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l72.e05', 'eg', 'eg.l72', 'eg.g72.eucharistie', array['eg.g72.eucharistie','eg.v.qorban']::text[], 'mcq', 'lesson', 'Parmi ces mots, lequel désigne le pain de la messe ?', array['le qorban']::text[], 'Le qorban veut dire « offrande ».', 1, '{"unitIds": ["eg.g72.eucharistie", "eg.v.qorban"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Parmi ces mots, lequel désigne le pain de la messe ?", "promptLanguage": "fr", "answer": "le qorban", "acceptedAnswers": ["le qorban"], "explanation": "Le qorban veut dire « offrande ».", "tip": "Qorban = pain de la messe.", "extraExample": {"text": "Le zounnar est une ceinture.", "translation": "Le qandil est une lampe."}, "options": ["le qandil", "le zounnar", "le myron", "le qorban"], "id": "eg.l72.e05", "pool": "lesson", "lessonId": "eg.l72", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l72.e06', 'eg', 'eg.l72', 'eg.g72.eucharistie', array['eg.g72.eucharistie','eg.v.jeune_eucharistique']::text[], 'mcq', 'lesson', 'Que veut dire le jeûne eucharistique ?', array['ni nourriture ni boisson avant la communion']::text[], 'On veut que le Christ soit la première nourriture de la journée.', 2, '{"unitIds": ["eg.g72.eucharistie", "eg.v.jeune_eucharistique"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le jeûne eucharistique ?", "promptLanguage": "fr", "answer": "ni nourriture ni boisson avant la communion", "acceptedAnswers": ["ni nourriture ni boisson avant la communion"], "explanation": "On veut que le Christ soit la première nourriture de la journée.", "tip": "À jeun avant de communier.", "extraExample": {"text": "Au moins neuf heures pour un adulte.", "translation": "Selon l''usage."}, "options": ["jeûner tout le Carême", "ni nourriture ni boisson avant la communion", "ne pas parler avant la messe", "manger du poisson seulement"], "id": "eg.l72.e06", "pool": "lesson", "lessonId": "eg.l72", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
