insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l73.e08', 'eg', 'eg.l73', 'eg.g73.confession', array['eg.g73.confession','eg.v.absolution']::text[], 'mcq', 'lesson', 'Que fait le prêtre pendant l''absolution ?', array['pose la croix sur la tête du pénitent et prie']::text[], 'Le prêtre prie, mais c''est Dieu qui pardonne.', 2, '{"unitIds": ["eg.g73.confession", "eg.v.absolution"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que fait le prêtre pendant l''absolution ?", "promptLanguage": "fr", "answer": "pose la croix sur la tête du pénitent et prie", "acceptedAnswers": ["pose la croix sur la tête du pénitent et prie"], "explanation": "Le prêtre prie, mais c''est Dieu qui pardonne.", "tip": "Croix sur la tête.", "extraExample": {"text": "Le pénitent est à genoux.", "translation": "Il embrasse la croix."}, "options": ["verse de l''eau sur sa tête", "pose la croix sur la tête du pénitent et prie", "lui donne le pain béni", "lui impose le zounnar"], "id": "eg.l73.e08", "pool": "lesson", "lessonId": "eg.l73", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l73.e09', 'eg', 'eg.l73', 'eg.g73.confession', array['eg.g73.confession','eg.v.confession']::text[], 'mcq', 'lesson', 'Quelle expression de Paul (2 Co 5, 18) répond à « Dieu seul pardonne » ?', array['le ministère de la réconciliation']::text[], 'Dieu seul pardonne, mais par le ministère qu''il a confié aux apôtres.', 3, '{"unitIds": ["eg.g73.confession", "eg.v.confession"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle expression de Paul (2 Co 5, 18) répond à « Dieu seul pardonne » ?", "promptLanguage": "fr", "answer": "le ministère de la réconciliation", "acceptedAnswers": ["le ministère de la réconciliation"], "explanation": "Dieu seul pardonne, mais par le ministère qu''il a confié aux apôtres.", "tip": "Ministère de la réconciliation.", "extraExample": {"text": "Jc 5, 16.", "translation": "Confessez vos péchés les uns aux autres."}, "options": ["le sceau du Saint-Esprit", "les noces de Cana", "le ministère de la réconciliation", "le grand mystère"], "id": "eg.l73.e09", "pool": "lesson", "lessonId": "eg.l73", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l73.e10', 'eg', 'eg.l73', 'eg.g73.confession', array['eg.g73.confession','eg.v.confession']::text[], 'mcq', 'lesson', 'À quelle fréquence se confesse-t-on, selon l''usage ?', array['environ une fois par mois']::text[], 'Le temps fait oublier : on ne laisse pas passer trop de temps.', 2, '{"unitIds": ["eg.g73.confession", "eg.v.confession"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À quelle fréquence se confesse-t-on, selon l''usage ?", "promptLanguage": "fr", "answer": "environ une fois par mois", "acceptedAnswers": ["environ une fois par mois"], "explanation": "Le temps fait oublier : on ne laisse pas passer trop de temps.", "tip": "Environ une fois par mois.", "extraExample": {"text": "Et avant de communier.", "translation": "Absolution puis communion."}, "options": ["seulement à Pâques", "environ une fois par mois", "une seule fois dans la vie", "chaque jour"], "id": "eg.l73.e10", "pool": "lesson", "lessonId": "eg.l73", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
