insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l73.e20', 'eg', 'eg.l73', 'eg.g73.confession', array['eg.g73.confession','eg.v.lier_et_delier']::text[], 'free_answer', 'lesson', 'Quel passage de l''Évangile de Jean fonde la confession ?', array['Jean 20, 22-23','Jn 20, 22-23','Jean 20 22 23','Jean 20, 23','Jn 20, 23','20, 22-23']::text[], 'Le soir de la Résurrection, Jésus donne le pouvoir de remettre les péchés.', 3, '{"unitIds": ["eg.g73.confession", "eg.v.lier_et_delier"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quel passage de l''Évangile de Jean fonde la confession ?", "promptLanguage": "fr", "answer": "Jean 20, 22-23", "acceptedAnswers": ["Jean 20, 22-23", "Jn 20, 22-23", "Jean 20 22 23", "Jean 20, 23", "Jn 20, 23", "20, 22-23"], "explanation": "Le soir de la Résurrection, Jésus donne le pouvoir de remettre les péchés.", "tip": "Jean 20.", "extraExample": {"text": "Mt 18, 18.", "translation": "Lier et délier."}, "id": "eg.l73.e20", "pool": "lesson", "lessonId": "eg.l73", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l73.e21', 'eg', 'eg.l73', 'eg.v.communion', array['eg.v.communion']::text[], 'mcq', 'lesson', 'Quelle préparation précède la communion ?', array['on s''examine, on se confesse, on se réconcilie']::text[], 'Rappel : saint Paul demande que chacun s''examine soi-même (1 Co 11, 28).', 2, '{"unitIds": ["eg.v.communion"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle préparation précède la communion ?", "promptLanguage": "fr", "answer": "on s''examine, on se confesse, on se réconcilie", "acceptedAnswers": ["on s''examine, on se confesse, on se réconcilie"], "explanation": "Rappel : saint Paul demande que chacun s''examine soi-même (1 Co 11, 28).", "tip": "Examen d''abord.", "extraExample": {"text": "Le qorban vient ensuite.", "translation": "On est à jeun."}, "options": ["on reçoit le saint myron", "on s''examine, on se confesse, on se réconcilie", "on se fait baptiser une seconde fois", "on récite le Credo une fois"], "id": "eg.l73.e21", "pool": "lesson", "lessonId": "eg.l73", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l73.e22', 'eg', 'eg.l73', 'eg.v.trente_six_onctions', array['eg.v.trente_six_onctions']::text[], 'mcq', 'lesson', 'Combien d''onctions fait-on avec le saint myron ?', array['36']::text[], 'Rappel : 36 signes de croix juste après le baptême.', 2, '{"unitIds": ["eg.v.trente_six_onctions"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''onctions fait-on avec le saint myron ?", "promptLanguage": "fr", "answer": "36", "acceptedAnswers": ["36"], "explanation": "Rappel : 36 signes de croix juste après le baptême.", "tip": "Trente-six.", "extraExample": {"text": "Sur les sens et les articulations.", "translation": "Tout le corps."}, "options": ["7", "12", "36", "40"], "id": "eg.l73.e22", "pool": "lesson", "lessonId": "eg.l73", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l73.e23', 'eg', 'eg.l73', 'eg.v.sacrements_repetables', array['eg.v.sacrements_repetables']::text[], 'free_answer', 'lesson', 'Cite un sacrement, autre que la confession, qui se répète.', array['l''eucharistie','eucharistie','la communion','communion','l''onction des malades','onction des malades']::text[], 'Rappel : eucharistie, confession et onction des malades se répètent.', 3, '{"unitIds": ["eg.v.sacrements_repetables"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Cite un sacrement, autre que la confession, qui se répète.", "promptLanguage": "fr", "answer": "l''eucharistie", "acceptedAnswers": ["l''eucharistie", "eucharistie", "la communion", "communion", "l''onction des malades", "onction des malades"], "explanation": "Rappel : eucharistie, confession et onction des malades se répètent.", "tip": "Nourriture, pardon, guérison.", "extraExample": {"text": "On communie souvent.", "translation": "On se confesse régulièrement."}, "id": "eg.l73.e23", "pool": "lesson", "lessonId": "eg.l73", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e01', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.onction_des_malades']::text[], 'mcq', 'lesson', 'Quel sacrement s''appelle aussi le qandil ?', array['l''onction des malades']::text[], 'Qandil veut dire « lampe » : le sacrement des sept mèches.', 1, '{"unitIds": ["eg.g74.onction_malades", "eg.v.onction_des_malades"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel sacrement s''appelle aussi le qandil ?", "promptLanguage": "fr", "answer": "l''onction des malades", "acceptedAnswers": ["l''onction des malades"], "explanation": "Qandil veut dire « lampe » : le sacrement des sept mèches.", "tip": "Qandil = onction.", "extraExample": {"text": "Jc 5, 14-15.", "translation": "Huile et sept mèches."}, "options": ["la confession", "l''onction des malades", "la confirmation", "le mariage"], "id": "eg.l74.e01", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e02', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.onction_des_malades']::text[], 'mcq', 'lesson', 'Quel passage fonde l''onction des malades ?', array['Jacques 5, 14-15']::text[], 'Jacques demande d''appeler les anciens pour prier et oindre le malade.', 2, '{"unitIds": ["eg.g74.onction_malades", "eg.v.onction_des_malades"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel passage fonde l''onction des malades ?", "promptLanguage": "fr", "answer": "Jacques 5, 14-15", "acceptedAnswers": ["Jacques 5, 14-15"], "explanation": "Jacques demande d''appeler les anciens pour prier et oindre le malade.", "tip": "Jc 5.", "extraExample": {"text": "Mc 6, 13 va dans le même sens.", "translation": "Les disciples oignent."}, "options": ["Jean 20, 22-23", "Matthieu 28, 19", "Actes 8, 14-17", "Jacques 5, 14-15"], "id": "eg.l74.e02", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e03', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.anciens_de_l_eglise']::text[], 'mcq', 'lesson', 'Qui Jacques demande-t-il d''appeler auprès du malade ?', array['les anciens de l''Église']::text[], 'Les « anciens » sont les prêtres.', 2, '{"unitIds": ["eg.g74.onction_malades", "eg.v.anciens_de_l_eglise"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui Jacques demande-t-il d''appeler auprès du malade ?", "promptLanguage": "fr", "answer": "les anciens de l''Église", "acceptedAnswers": ["les anciens de l''Église"], "explanation": "Les « anciens » sont les prêtres.", "tip": "Presbyteroi = prêtres.", "extraExample": {"text": "Le mot a donné « prêtre ».", "translation": "Ils prient et oignent."}, "options": ["les diacres seulement", "les parrains", "les médecins", "les anciens de l''Église"], "id": "eg.l74.e03", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e04', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.huile_benie']::text[], 'mcq', 'lesson', 'Avec quoi le prêtre oint-il le malade ?', array['l''huile bénie']::text[], 'L''huile du qandil est une huile pure, de préférence d''olive. Le saint myron est réservé à la confirmation.', 2, '{"unitIds": ["eg.g74.onction_malades", "eg.v.huile_benie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Avec quoi le prêtre oint-il le malade ?", "promptLanguage": "fr", "answer": "l''huile bénie", "acceptedAnswers": ["l''huile bénie"], "explanation": "L''huile du qandil est une huile pure, de préférence d''olive. Le saint myron est réservé à la confirmation.", "tip": "Huile = qandil.", "extraExample": {"text": "Croix sur le front, la poitrine, les mains.", "translation": "Signe visible."}, "errorPatterns": [{"equals": "le saint myron", "category": "word_confusion", "feedback": "Le myron sert à la confirmation. Pour le qandil, on utilise de l''huile pure bénie."}], "options": ["le vin de la messe", "le saint myron", "l''eau du baptême", "l''huile bénie"], "id": "eg.l74.e04", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e05', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.huile_benie']::text[], 'mcq', 'lesson', 'Où le prêtre trace-t-il la croix d''huile ?', array['sur le front, la poitrine et les mains']::text[], 'Trois endroits : front, poitrine, mains. Les 36 onctions sont celles du myron.', 2, '{"unitIds": ["eg.g74.onction_malades", "eg.v.huile_benie"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Où le prêtre trace-t-il la croix d''huile ?", "promptLanguage": "fr", "answer": "sur le front, la poitrine et les mains", "acceptedAnswers": ["sur le front, la poitrine et les mains"], "explanation": "Trois endroits : front, poitrine, mains. Les 36 onctions sont celles du myron.", "tip": "Trois croix d''huile.", "extraExample": {"text": "Le myron fait 36 onctions.", "translation": "Le qandil trois."}, "errorPatterns": [{"equals": "sur 36 endroits du corps", "category": "word_confusion", "feedback": "Les 36 onctions sont celles du saint myron à la confirmation."}], "options": ["sur le front, la poitrine et les mains", "sur le vêtement blanc", "sur les pieds seulement", "sur 36 endroits du corps"], "id": "eg.l74.e05", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e06', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.guerison_de_l_ame_et_du_corps']::text[], 'mcq', 'lesson', 'Que vise le qandil ?', array['la guérison de l''âme et du corps']::text[], 'Jacques parle de relever le malade et de lui pardonner ses péchés.', 2, '{"unitIds": ["eg.g74.onction_malades", "eg.v.guerison_de_l_ame_et_du_corps"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que vise le qandil ?", "promptLanguage": "fr", "answer": "la guérison de l''âme et du corps", "acceptedAnswers": ["la guérison de l''âme et du corps"], "explanation": "Jacques parle de relever le malade et de lui pardonner ses péchés.", "tip": "Âme + corps.", "extraExample": {"text": "Selon la volonté de Dieu.", "translation": "Pas garanti."}, "errorPatterns": [{"equals": "la préparation à mourir", "category": "word_confusion", "feedback": "Ce n''est pas l''extrême-onction : le qandil sert à relever le malade."}], "options": ["la préparation à mourir", "la guérison de l''âme et du corps", "la guérison du corps seulement", "le pardon du péché originel"], "id": "eg.l74.e06", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e07', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.guerison_de_l_ame_et_du_corps']::text[], 'mcq', 'lesson', 'Que fait le malade avant le qandil, si possible ?', array['se confesse d''abord et communie ensuite']::text[], 'L''âme est soignée avec le corps : la confession d''abord, la communion ensuite.', 3, '{"unitIds": ["eg.g74.onction_malades", "eg.v.guerison_de_l_ame_et_du_corps"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Que fait le malade avant le qandil, si possible ?", "promptLanguage": "fr", "answer": "se confesse d''abord et communie ensuite", "acceptedAnswers": ["se confesse d''abord et communie ensuite"], "explanation": "L''âme est soignée avec le corps : la confession d''abord, la communion ensuite.", "tip": "Confession puis communion.", "extraExample": {"text": "Pardon + relèvement.", "translation": "Jc 5, 15."}, "options": ["se confesse d''abord et communie ensuite", "jeûne trois jours entiers", "se fait baptiser", "reçoit le saint myron"], "id": "eg.l74.e07", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e08', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.onction_des_malades']::text[], 'mcq', 'lesson', 'Quand peut-on recevoir l''onction des malades ?', array['à chaque maladie']::text[], 'C''est un sacrement qui se répète.', 2, '{"unitIds": ["eg.g74.onction_malades", "eg.v.onction_des_malades"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quand peut-on recevoir l''onction des malades ?", "promptLanguage": "fr", "answer": "à chaque maladie", "acceptedAnswers": ["à chaque maladie"], "explanation": "C''est un sacrement qui se répète.", "tip": "À chaque maladie.", "extraExample": {"text": "Chez soi, à l''hôpital, à l''église.", "translation": "Pas seulement les mourants."}, "options": ["seulement à Pâques", "une seule fois dans la vie", "à chaque maladie", "seulement à l''agonie"], "id": "eg.l74.e08", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
