insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e14', 'eg', 'eg.l74', 'eg.g74.onction_malades', array['eg.g74.onction_malades','eg.v.onction_des_malades','eg.v.qandil','eg.v.sept_meches']::text[], 'match', 'lesson', 'Les repères du qandil', '{}'::text[], 'Chaque repère éclaire le sacrement : versets, nom et nombre.', 3, '{"unitIds": ["eg.g74.onction_malades", "eg.v.onction_des_malades", "eg.v.qandil", "eg.v.sept_meches"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les repères du qandil", "promptLanguage": "fr", "explanation": "Chaque repère éclaire le sacrement : versets, nom et nombre.", "tip": "Jacques, Marc, lampe, sept.", "pairs": [{"left": "Jacques 5, 14-15", "right": "les anciens oignent le malade"}, {"left": "Marc 6, 13", "right": "les disciples oignent d''huile des malades"}, {"left": "Qandil", "right": "la lampe"}, {"left": "Sept mèches", "right": "sept prières"}], "answer": "Jacques 5, 14-15 = les anciens oignent le malade ; Marc 6, 13 = les disciples oignent d''huile des malades ; Qandil = la lampe ; Sept mèches = sept prières", "acceptedAnswers": [], "id": "eg.l74.e14", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
