insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l74.e23', 'eg', 'eg.l74', 'eg.v.triple_immersion', array['eg.v.triple_immersion']::text[], 'mcq', 'lesson', 'Que rappellent les trois immersions du baptême, en plus de la Trinité ?', array['les trois jours du Christ au tombeau']::text[], 'Rappel : on descend dans l''eau comme on est enseveli, on remonte comme le Christ ressuscité (Rm 6, 3-4).', 2, '{"unitIds": ["eg.v.triple_immersion"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que rappellent les trois immersions du baptême, en plus de la Trinité ?", "promptLanguage": "fr", "answer": "les trois jours du Christ au tombeau", "acceptedAnswers": ["les trois jours du Christ au tombeau"], "explanation": "Rappel : on descend dans l''eau comme on est enseveli, on remonte comme le Christ ressuscité (Rm 6, 3-4).", "tip": "Trois jours, trois immersions.", "extraExample": {"text": "L''eau est un tombeau.", "translation": "Et un lieu de naissance."}, "options": ["les trois jeûnes de l''année", "les trois jours du Christ au tombeau", "les trois Rois mages", "les trois premiers conciles"], "id": "eg.l74.e23", "pool": "lesson", "lessonId": "eg.l74", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
