insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l75.e13', 'eg', 'eg.l75', 'eg.g75.mariage_sacerdoce', array['eg.g75.mariage_sacerdoce','eg.v.sacerdoce']::text[], 'fill_blank', 'lesson', 'Les trois degrés du sacerdoce sont : diacre, prêtre et ___.', array['évêque']::text[], 'Le détail des degrés sera vu dans un module sur le clergé.', 2, '{"unitIds": ["eg.g75.mariage_sacerdoce", "eg.v.sacerdoce"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Les trois degrés du sacerdoce sont : diacre, prêtre et ___.", "promptLanguage": "fr", "answer": "évêque", "acceptedAnswers": ["évêque"], "explanation": "Le détail des degrés sera vu dans un module sur le clergé.", "tip": "Diacre, prêtre, évêque.", "extraExample": {"text": "Évêque = chef d''un diocèse.", "translation": "Le patriarche aussi est évêque."}, "options": ["évêque", "parrain", "pasteur", "pape"], "id": "eg.l75.e13", "pool": "lesson", "lessonId": "eg.l75", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l75.e14', 'eg', 'eg.l75', 'eg.g75.mariage_sacerdoce', array['eg.g75.mariage_sacerdoce','eg.v.grand_mystere','eg.v.noces_de_cana','eg.v.indissolubilite']::text[], 'match', 'lesson', 'Les versets du mariage et du sacerdoce', '{}'::text[], 'Les versets fondent le mariage et le sacerdoce.', 3, '{"unitIds": ["eg.g75.mariage_sacerdoce", "eg.v.grand_mystere", "eg.v.noces_de_cana", "eg.v.indissolubilite"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Les versets du mariage et du sacerdoce", "promptLanguage": "fr", "explanation": "Les versets fondent le mariage et le sacerdoce.", "tip": "Mystère, Dieu a uni, Cana, mains.", "pairs": [{"left": "Ép 5, 32", "right": "ce mystère est grand"}, {"left": "Mt 19, 6", "right": "ce que Dieu a uni, que l''homme ne le sépare pas"}, {"left": "Jn 2", "right": "les noces de Cana"}, {"left": "Actes 6, 6", "right": "les premiers diacres, par l''imposition des mains"}], "answer": "Ép 5, 32 = ce mystère est grand ; Mt 19, 6 = ce que Dieu a uni, que l''homme ne le sépare pas ; Jn 2 = les noces de Cana ; Actes 6, 6 = les premiers diacres, par l''imposition des mains", "acceptedAnswers": [], "id": "eg.l75.e14", "pool": "lesson", "lessonId": "eg.l75", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
