insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l76.e14', 'eg', 'eg.l76', 'eg.g76.bilan_sacrements', array['eg.g76.bilan_sacrements','eg.v.sacrements_d_initiation','eg.v.sacrements_de_guerison','eg.v.sacrements_de_vocation']::text[], 'match', 'lesson', 'Un sacrement, son fondement', '{}'::text[], 'Chaque sacrement repose sur un passage du Nouveau Testament.', 3, '{"unitIds": ["eg.g76.bilan_sacrements", "eg.v.sacrements_d_initiation", "eg.v.sacrements_de_guerison", "eg.v.sacrements_de_vocation"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Un sacrement, son fondement", "promptLanguage": "fr", "explanation": "Chaque sacrement repose sur un passage du Nouveau Testament.", "tip": "Un sacrement, un verset.", "pairs": [{"left": "Baptême", "right": "Jn 3, 5 : naître d''eau et d''Esprit"}, {"left": "Confession", "right": "Jn 20, 22-23 : remettre les péchés"}, {"left": "Onction des malades", "right": "Jc 5, 14-15 : les anciens oignent"}, {"left": "Mariage", "right": "Ép 5, 32 : ce mystère est grand"}, {"left": "Eucharistie", "right": "Mt 26, 26-28 : ceci est mon corps"}], "answer": "Baptême = Jn 3, 5 : naître d''eau et d''Esprit ; Confession = Jn 20, 22-23 : remettre les péchés ; Onction des malades = Jc 5, 14-15 : les anciens oignent ; Mariage = Ép 5, 32 : ce mystère est grand ; Eucharistie = Mt 26, 26-28 : ceci est mon corps", "acceptedAnswers": [], "id": "eg.l76.e14", "pool": "lesson", "lessonId": "eg.l76", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l76.e15', 'eg', 'eg.l76', 'eg.g76.bilan_sacrements', array['eg.g76.bilan_sacrements','eg.v.sacrements_d_initiation']::text[], 'reorder', 'lesson', 'Phrase-repère : les signes.', array['Chaque sacrement a un signe visible et une grâce invisible']::text[], 'C''est la définition apprise dans la première leçon.', 2, '{"unitIds": ["eg.g76.bilan_sacrements", "eg.v.sacrements_d_initiation"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : les signes.", "promptLanguage": "fr", "answer": "Chaque sacrement a un signe visible et une grâce invisible", "acceptedAnswers": ["Chaque sacrement a un signe visible et une grâce invisible"], "explanation": "C''est la définition apprise dans la première leçon.", "tip": "Visible + invisible.", "extraExample": {"text": "Eau, huile, pain.", "translation": "Mains, couronnes."}, "tokens": ["sacrement", "a", "Chaque", "signe", "une", "et", "visible", "grâce", "un", "invisible"], "id": "eg.l76.e15", "pool": "lesson", "lessonId": "eg.l76", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
