insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l76.e19', 'eg', 'eg.l76', 'eg.v.azymes', array['eg.v.azymes','eg.v.pain_leve','eg.v.sept_sacrements','eg.v.deux_sacrements']::text[], 'match', 'lesson', 'Sacrements et signes : qui est qui ?', '{}'::text[], 'Rappel des comparaisons faites avec les catholiques et les protestants.', 3, '{"unitIds": ["eg.v.azymes", "eg.v.pain_leve", "eg.v.sept_sacrements", "eg.v.deux_sacrements"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Sacrements et signes : qui est qui ?", "promptLanguage": "fr", "explanation": "Rappel des comparaisons faites avec les catholiques et les protestants.", "tip": "Azyme : latins. Levé : Coptes.", "pairs": [{"left": "Pain azyme", "right": "Église latine"}, {"left": "Pain levé", "right": "Église copte"}, {"left": "Deux sacrements", "right": "la plupart des protestants"}, {"left": "Sept sacrements", "right": "Coptes et catholiques"}], "answer": "Pain azyme = Église latine ; Pain levé = Église copte ; Deux sacrements = la plupart des protestants ; Sept sacrements = Coptes et catholiques", "acceptedAnswers": [], "id": "eg.l76.e19", "pool": "lesson", "lessonId": "eg.l76", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
