insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l76.e21', 'eg', 'eg.l76', 'eg.v.celibat_des_pretres', array['eg.v.celibat_des_pretres']::text[], 'mcq', 'lesson', 'Chez les Coptes, un prêtre peut être...', array['marié avant l''ordination']::text[], 'Rappel : un homme marié avant l''ordination peut devenir prêtre ; les évêques sont choisis parmi les moines.', 2, '{"unitIds": ["eg.v.celibat_des_pretres"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Chez les Coptes, un prêtre peut être...", "promptLanguage": "fr", "answer": "marié avant l''ordination", "acceptedAnswers": ["marié avant l''ordination"], "explanation": "Rappel : un homme marié avant l''ordination peut devenir prêtre ; les évêques sont choisis parmi les moines.", "tip": "Marié avant, pas après.", "extraExample": {"text": "Pierre était marié.", "translation": "Mt 8, 14."}, "options": ["toujours moine", "marié après l''ordination", "marié avant l''ordination", "jamais marié"], "id": "eg.l76.e21", "pool": "lesson", "lessonId": "eg.l76", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l76.e22', 'eg', 'eg.l76', 'eg.v.succession_apostolique', array['eg.v.succession_apostolique']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on la suite des évêques ordonnés jusqu''aux apôtres ?', array['succession apostolique','la succession apostolique','successions apostoliques']::text[], 'Rappel : chaque évêque est ordonné par d''autres, jusqu''aux apôtres.', 2, '{"unitIds": ["eg.v.succession_apostolique"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment appelle-t-on la suite des évêques ordonnés jusqu''aux apôtres ?", "promptLanguage": "fr", "answer": "succession apostolique", "acceptedAnswers": ["succession apostolique", "la succession apostolique", "successions apostoliques"], "explanation": "Rappel : chaque évêque est ordonné par d''autres, jusqu''aux apôtres.", "tip": "Succession = continuité.", "extraExample": {"text": "Tawadros II est le 118e successeur de saint Marc.", "translation": "Dans cette suite."}, "id": "eg.l76.e22", "pool": "lesson", "lessonId": "eg.l76", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e01', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.orientation_vers_l_est']::text[], 'mcq', 'lesson', 'Vers quelle direction une église copte est-elle orientée ?', array['l''est']::text[], 'Le sanctuaire est à l''est, et on prie tourné vers lui (carte « Pourquoi l''église regarde l''est »).', 1, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.orientation_vers_l_est"], "type": "mcq", "difficulty": 1, "prompt": "Vers quelle direction une église copte est-elle orientée ?", "options": ["l''ouest", "l''est", "le nord", "le sud"], "answer": "l''est", "acceptedAnswers": ["l''est"], "explanation": "Le sanctuaire est à l''est, et on prie tourné vers lui (carte « Pourquoi l''église regarde l''est »).", "tip": "Soleil levant, c''est l''est.", "extraExample": {"text": "On prie tourné vers l''est.", "translation": "Vers le soleil levant."}, "errorPatterns": [{"equals": "l''ouest", "category": "word_confusion", "feedback": "L''ouest est le côté de l''entrée, pas du sanctuaire."}], "id": "eg.l77.e01", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e02', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.orientation_vers_l_est']::text[], 'mcq', 'lesson', 'Comment le prophète Malachie appelle-t-il le Christ, ce qui explique l''orientation vers l''est ?', array['le soleil de justice']::text[], 'Le soleil se lève à l''est : l''église regarde vers le Christ, soleil de justice.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.orientation_vers_l_est"], "type": "mcq", "difficulty": 2, "prompt": "Comment le prophète Malachie appelle-t-il le Christ, ce qui explique l''orientation vers l''est ?", "options": ["le soleil de justice", "la lumière du Sinaï", "l''étoile de Noé", "le jardin d''Éden"], "answer": "le soleil de justice", "acceptedAnswers": ["le soleil de justice"], "explanation": "Le soleil se lève à l''est : l''église regarde vers le Christ, soleil de justice.", "tip": "Soleil = est = Christ.", "extraExample": {"text": "Le Christ est la lumière du monde.", "translation": "Il se lève à l''est."}, "id": "eg.l77.e02", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e03', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.arche_de_noe']::text[], 'mcq', 'lesson', 'Quelle est la forme la plus courante d''une église copte ?', array['l''arche de Noé']::text[], 'Un bâtiment allongé comme un navire : ceux qui sont dedans sont sauvés comme Noé.', 1, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.arche_de_noe"], "type": "mcq", "difficulty": 1, "prompt": "Quelle est la forme la plus courante d''une église copte ?", "options": ["l''arche de Noé", "le cercle", "le triangle", "la tente de Moïse"], "answer": "l''arche de Noé", "acceptedAnswers": ["l''arche de Noé"], "explanation": "Un bâtiment allongé comme un navire : ceux qui sont dedans sont sauvés comme Noé.", "tip": "Église = navire.", "extraExample": {"text": "La nef est le pont du bateau.", "translation": "L''arche sauve du déluge."}, "errorPatterns": [{"equals": "le cercle", "category": "word_confusion", "feedback": "Le cercle existe, mais il est plus rare ; il parle de l''éternité."}], "id": "eg.l77.e03", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e04', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.nef']::text[], 'mcq', 'lesson', 'De quel mot latin vient « nef » ?', array['navis, le navire']::text[], 'La nef est la grande salle des fidèles, comme le pont d''un navire : l''église est une arche.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.nef"], "type": "mcq", "difficulty": 2, "prompt": "De quel mot latin vient « nef » ?", "options": ["navis, le navire", "nefas, le malheur", "nebula, le nuage", "nova, la nouveauté"], "answer": "navis, le navire", "acceptedAnswers": ["navis, le navire"], "explanation": "La nef est la grande salle des fidèles, comme le pont d''un navire : l''église est une arche.", "tip": "Nef = navire.", "extraExample": {"text": "Le mot « navigation » vient aussi de navis.", "translation": "Même famille de mots."}, "id": "eg.l77.e04", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e05', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise']::text[], 'mcq', 'lesson', 'Combien de parties compte une église copte, de l''entrée au sanctuaire ?', array['trois']::text[], 'Narthex, nef et sanctuaire : trois parties, comme les trois espaces du Tabernacle.', 1, '{"unitIds": ["eg.g77.batiment_eglise"], "type": "mcq", "difficulty": 1, "prompt": "Combien de parties compte une église copte, de l''entrée au sanctuaire ?", "options": ["deux", "trois", "quatre", "sept"], "answer": "trois", "acceptedAnswers": ["trois"], "explanation": "Narthex, nef et sanctuaire : trois parties, comme les trois espaces du Tabernacle.", "tip": "Trois parties, trois espaces.", "extraExample": {"text": "Parvis, lieu saint, saint des saints.", "translation": "Même nombre."}, "id": "eg.l77.e05", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e06', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.narthex']::text[], 'mcq', 'lesson', 'Qui se tenait autrefois au narthex pendant la liturgie ?', array['les catéchumènes']::text[], 'Les catéchumènes se préparent au baptême ; ils n''entraient pas encore dans la nef.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.narthex"], "type": "mcq", "difficulty": 2, "prompt": "Qui se tenait autrefois au narthex pendant la liturgie ?", "options": ["les catéchumènes", "le grand prêtre", "les évêques", "les diacres"], "answer": "les catéchumènes", "acceptedAnswers": ["les catéchumènes"], "explanation": "Les catéchumènes se préparent au baptême ; ils n''entraient pas encore dans la nef.", "tip": "Narthex = entrée = futurs baptisés.", "extraExample": {"text": "Un catéchumène apprend la foi avant son baptême.", "translation": "Il est encore à l''entrée."}, "id": "eg.l77.e06", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e07', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.tabernacle_de_moise','eg.v.lieu_saint']::text[], 'mcq', 'lesson', 'À quelle partie du Tabernacle correspond la nef ?', array['le lieu saint']::text[], 'La nef est au milieu, comme le lieu saint entre le parvis et le saint des saints.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.tabernacle_de_moise", "eg.v.lieu_saint"], "type": "mcq", "difficulty": 2, "prompt": "À quelle partie du Tabernacle correspond la nef ?", "options": ["le lieu saint", "le parvis", "le saint des saints", "le mont Sinaï"], "answer": "le lieu saint", "acceptedAnswers": ["le lieu saint"], "explanation": "La nef est au milieu, comme le lieu saint entre le parvis et le saint des saints.", "tip": "Milieu = milieu.", "extraExample": {"text": "Le narthex est au parvis.", "translation": "Le sanctuaire est au saint des saints."}, "errorPatterns": [{"equals": "le parvis", "category": "word_confusion", "feedback": "Le parvis correspond au narthex, l''entrée."}], "id": "eg.l77.e07", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e08', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.saint_des_saints']::text[], 'mcq', 'lesson', 'Qui pouvait entrer dans le saint des saints du Tabernacle, une fois par an ?', array['le grand prêtre']::text[], 'Le lieu le plus sacré était réservé au grand prêtre, comme le sanctuaire l''est au clergé.', 3, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.saint_des_saints"], "type": "mcq", "difficulty": 3, "prompt": "Qui pouvait entrer dans le saint des saints du Tabernacle, une fois par an ?", "options": ["le grand prêtre", "tout le peuple", "les catéchumènes", "les lévites seulement"], "answer": "le grand prêtre", "acceptedAnswers": ["le grand prêtre"], "explanation": "Le lieu le plus sacré était réservé au grand prêtre, comme le sanctuaire l''est au clergé.", "tip": "Un lieu, une personne, un jour.", "extraExample": {"text": "Le sanctuaire est réservé au clergé.", "translation": "Les fidèles prient dans la nef."}, "id": "eg.l77.e08", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e09', 'eg', 'eg.l77', 'eg.v.saint_marc', array['eg.v.saint_marc']::text[], 'mcq', 'lesson', 'L''Église d''Alexandrie a été fondée par…', array['saint Marc']::text[], 'Révision du module 1 : saint Marc, évangéliste, fonde l''Église d''Alexandrie.', 1, '{"unitIds": ["eg.v.saint_marc"], "type": "mcq", "difficulty": 1, "prompt": "L''Église d''Alexandrie a été fondée par…", "options": ["saint Marc", "saint Pierre", "saint Paul", "saint Athanase"], "answer": "saint Marc", "acceptedAnswers": ["saint Marc"], "explanation": "Révision du module 1 : saint Marc, évangéliste, fonde l''Église d''Alexandrie.", "tip": "Marc = Alexandrie.", "extraExample": {"text": "Marc est mort martyr vers 68.", "translation": "Ses reliques sont au Caire."}, "id": "eg.l77.e09", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e10', 'eg', 'eg.l77', 'eg.v.copte', array['eg.v.copte']::text[], 'mcq', 'lesson', 'Que veut dire « copte » ?', array['égyptien']::text[], 'Révision du module 1 : « copte » est le nom de l''Église d''Égypte, du grec Aigyptios.', 1, '{"unitIds": ["eg.v.copte"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire « copte » ?", "options": ["égyptien", "orthodoxe", "grec", "ancien"], "answer": "égyptien", "acceptedAnswers": ["égyptien"], "explanation": "Révision du module 1 : « copte » est le nom de l''Église d''Égypte, du grec Aigyptios.", "tip": "Copte = égyptien.", "extraExample": {"text": "La langue copte vient de l''égyptien ancien.", "translation": "Le nom est le même."}, "id": "eg.l77.e10", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e11', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.orientation_vers_l_est']::text[], 'fill_blank', 'lesson', 'Une église copte est tournée vers l''___.', array['est']::text[], 'Le sanctuaire est à l''est, vers le soleil levant, symbole du Christ.', 1, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.orientation_vers_l_est"], "type": "fill_blank", "difficulty": 1, "prompt": "Une église copte est tournée vers l''___.", "options": ["est", "ouest", "nord"], "answer": "est", "acceptedAnswers": ["est"], "explanation": "Le sanctuaire est à l''est, vers le soleil levant, symbole du Christ.", "tip": "L''est, comme le soleil levant.", "extraExample": {"text": "Le sanctuaire est à l''est.", "translation": "L''entrée est à l''ouest."}, "errorPatterns": [{"equals": "ouest", "category": "word_confusion", "feedback": "L''entrée est à l''ouest ; le sanctuaire est du côté opposé, à l''est."}], "id": "eg.l77.e11", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e12', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.parvis']::text[], 'fill_blank', 'lesson', 'Le narthex correspond au ___ du Tabernacle.', array['parvis']::text[], 'Le parvis est la cour d''entrée, comme le narthex.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.parvis"], "type": "fill_blank", "difficulty": 2, "prompt": "Le narthex correspond au ___ du Tabernacle.", "options": ["parvis", "lieu saint", "saint des saints"], "answer": "parvis", "acceptedAnswers": ["parvis"], "explanation": "Le parvis est la cour d''entrée, comme le narthex.", "tip": "Entrée = parvis.", "extraExample": {"text": "Le parvis est en plein air.", "translation": "Le narthex est couvert."}, "errorPatterns": [{"equals": "lieu saint", "category": "word_confusion", "feedback": "Le lieu saint correspond à la nef."}], "id": "eg.l77.e12", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e13', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise']::text[], 'fill_blank', 'lesson', 'Une coupole représente le Christ ; trois coupoles représentent la ___.', array['Trinité']::text[], 'Trois coupoles rappellent les trois personnes de la Trinité (selon l''usage de l''église).', 2, '{"unitIds": ["eg.g77.batiment_eglise"], "type": "fill_blank", "difficulty": 2, "prompt": "Une coupole représente le Christ ; trois coupoles représentent la ___.", "options": ["Trinité", "Pentecôte", "Création"], "answer": "Trinité", "acceptedAnswers": ["Trinité"], "explanation": "Trois coupoles rappellent les trois personnes de la Trinité (selon l''usage de l''église).", "tip": "Trois coupoles = Trinité.", "extraExample": {"text": "Cinq coupoles : le Christ et quatre évangélistes.", "translation": "Autre nombre, autre symbole."}, "id": "eg.l77.e13", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e14', 'eg', 'eg.l77', 'eg.v.hierarchie_a_trois_degres', array['eg.v.hierarchie_a_trois_degres']::text[], 'fill_blank', 'lesson', 'Les trois degrés du clergé sont l''évêque, le prêtre et le ___.', array['diacre']::text[], 'Révision du module 3 : évêque, prêtre, diacre. Dans ce module, tu vas les retrouver autour de l''autel.', 2, '{"unitIds": ["eg.v.hierarchie_a_trois_degres"], "type": "fill_blank", "difficulty": 2, "prompt": "Les trois degrés du clergé sont l''évêque, le prêtre et le ___.", "options": ["diacre", "moine", "confesseur"], "answer": "diacre", "acceptedAnswers": ["diacre"], "explanation": "Révision du module 3 : évêque, prêtre, diacre. Dans ce module, tu vas les retrouver autour de l''autel.", "tip": "Trois degrés : évêque, prêtre, diacre.", "extraExample": {"text": "Le diacre est le serviteur.", "translation": "Il aide l''évêque."}, "id": "eg.l77.e14", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e15', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.tabernacle_de_moise']::text[], 'match', 'lesson', 'Les trois parties de l''église et le Tabernacle', '{}'::text[], 'Chaque partie de l''église a son modèle dans le Tabernacle.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.tabernacle_de_moise"], "type": "match", "difficulty": 2, "prompt": "Les trois parties de l''église et le Tabernacle", "pairs": [{"left": "le narthex", "right": "le parvis"}, {"left": "la nef", "right": "le lieu saint"}, {"left": "le sanctuaire", "right": "le saint des saints"}], "answer": "le narthex = le parvis ; la nef = le lieu saint ; le sanctuaire = le saint des saints", "acceptedAnswers": [], "explanation": "Chaque partie de l''église a son modèle dans le Tabernacle.", "tip": "De l''entrée au fond : parvis, lieu saint, saint des saints.", "id": "eg.l77.e15", "promptLanguage": "fr", "instruction": "Associe chaque élément de gauche à celui de droite.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e16', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise']::text[], 'match', 'lesson', 'Les coupoles et leur sens', '{}'::text[], 'Le nombre de coupoles porte un sens.', 3, '{"unitIds": ["eg.g77.batiment_eglise"], "type": "match", "difficulty": 3, "prompt": "Les coupoles et leur sens", "pairs": [{"left": "une coupole", "right": "le Christ"}, {"left": "trois coupoles", "right": "la Trinité"}, {"left": "cinq coupoles", "right": "le Christ et les quatre évangélistes"}], "answer": "une coupole = le Christ ; trois coupoles = la Trinité ; cinq coupoles = le Christ et les quatre évangélistes", "acceptedAnswers": [], "explanation": "Le nombre de coupoles porte un sens.", "tip": "1 = Christ ; 3 = Trinité ; 5 = Christ et quatre évangélistes.", "id": "eg.l77.e16", "promptLanguage": "fr", "instruction": "Associe chaque élément de gauche à celui de droite.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e17', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.orientation_vers_l_est']::text[], 'reorder', 'lesson', 'Phrase-repère : l''orientation de l''église.', array['L''église est tournée vers l''est']::text[], 'Le repère à retenir : on prie vers l''est.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.orientation_vers_l_est"], "type": "reorder", "difficulty": 2, "prompt": "Phrase-repère : l''orientation de l''église.", "tokens": ["est", "vers", "L''église", "tournée", "l''est"], "answer": "L''église est tournée vers l''est", "acceptedAnswers": ["L''église est tournée vers l''est"], "explanation": "Le repère à retenir : on prie vers l''est.", "tip": "L''église regarde l''est.", "extraExample": {"text": "On prie vers l''est.", "translation": "Comme le soleil levant."}, "id": "eg.l77.e17", "promptLanguage": "fr", "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "pool": "lesson", "lessonId": "eg.l77", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e18', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.arche_de_noe']::text[], 'free_answer', 'lesson', 'Quel personnage de l''Ancien Testament a construit l''arche dont l''église rappelle la forme ?', array['Noé','Noe']::text[], 'C''est Noé : l''église est une arche qui sauve.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.arche_de_noe"], "type": "free_answer", "difficulty": 2, "prompt": "Quel personnage de l''Ancien Testament a construit l''arche dont l''église rappelle la forme ?", "answer": "Noé", "acceptedAnswers": ["Noé", "Noe"], "explanation": "C''est Noé : l''église est une arche qui sauve.", "tip": "Noé, l''arche.", "extraExample": {"text": "L''arche a sauvé Noé et sa famille.", "translation": "L''église sauve ceux qui y entrent."}, "id": "eg.l77.e18", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e19', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.narthex']::text[], 'free_answer', 'lesson', 'Comment s''appelle l''entrée de l''église, où se tenaient autrefois les catéchumènes ?', array['le narthex','narthex']::text[], 'Le narthex est la première partie de l''église.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.narthex"], "type": "free_answer", "difficulty": 2, "prompt": "Comment s''appelle l''entrée de l''église, où se tenaient autrefois les catéchumènes ?", "answer": "le narthex", "acceptedAnswers": ["le narthex", "narthex"], "explanation": "Le narthex est la première partie de l''église.", "tip": "Narthex = entrée.", "extraExample": {"text": "Le narthex correspond au parvis.", "translation": "C''est la partie à l''ouest."}, "id": "eg.l77.e19", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l77.e20', 'eg', 'eg.l77', 'eg.g77.batiment_eglise', array['eg.g77.batiment_eglise','eg.v.nef']::text[], 'free_answer', 'lesson', 'Comment s''appelle la grande salle de l''église où se tiennent les fidèles ?', array['la nef','nef']::text[], 'La nef est la partie centrale, entre le narthex et le sanctuaire.', 2, '{"unitIds": ["eg.g77.batiment_eglise", "eg.v.nef"], "type": "free_answer", "difficulty": 2, "prompt": "Comment s''appelle la grande salle de l''église où se tiennent les fidèles ?", "answer": "la nef", "acceptedAnswers": ["la nef", "nef"], "explanation": "La nef est la partie centrale, entre le narthex et le sanctuaire.", "tip": "Nef = navire.", "extraExample": {"text": "La nef correspond au lieu saint.", "translation": "Elle est au milieu."}, "id": "eg.l77.e20", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l77", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e01', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.haikal']::text[], 'mcq', 'lesson', 'Quel mot désigne le sanctuaire de l''église copte ?', array['le haikal']::text[], 'Le haikal est la partie la plus sainte, tout à l''est, derrière l''iconostase.', 1, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.haikal"], "type": "mcq", "difficulty": 1, "prompt": "Quel mot désigne le sanctuaire de l''église copte ?", "options": ["le haikal", "le narthex", "la nef", "le parvis"], "answer": "le haikal", "acceptedAnswers": ["le haikal"], "explanation": "Le haikal est la partie la plus sainte, tout à l''est, derrière l''iconostase.", "tip": "Haikal = sanctuaire.", "extraExample": {"text": "Le haikal correspond au saint des saints.", "translation": "Il est derrière l''iconostase."}, "errorPatterns": [{"equals": "le narthex", "category": "word_confusion", "feedback": "Le narthex est l''entrée, à l''ouest."}], "id": "eg.l78.e01", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e02', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.autel']::text[], 'mcq', 'lesson', 'Quelle est la forme de l''autel copte ?', array['un cube']::text[], 'L''autel est un cube de pierre ou de bois, détaché du mur.', 1, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.autel"], "type": "mcq", "difficulty": 1, "prompt": "Quelle est la forme de l''autel copte ?", "options": ["un cube", "une sphère", "un triangle", "un cylindre"], "answer": "un cube", "acceptedAnswers": ["un cube"], "explanation": "L''autel est un cube de pierre ou de bois, détaché du mur.", "tip": "Cube = tombeau.", "extraExample": {"text": "On peut tourner autour de l''autel.", "translation": "Il est au centre du haikal."}, "id": "eg.l78.e02", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e03', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.autel']::text[], 'mcq', 'lesson', 'Que représente l''autel ?', array['le tombeau du Christ']::text[], 'L''autel rappelle le tombeau d''où vient la vie, et la table où le Christ se donne.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.autel"], "type": "mcq", "difficulty": 2, "prompt": "Que représente l''autel ?", "options": ["le tombeau du Christ", "le Sinaï", "l''arche de Noé", "le parvis"], "answer": "le tombeau du Christ", "acceptedAnswers": ["le tombeau du Christ"], "explanation": "L''autel rappelle le tombeau d''où vient la vie, et la table où le Christ se donne.", "tip": "Autel = tombeau.", "extraExample": {"text": "Le Christ est ressuscité du tombeau.", "translation": "L''autel porte la vie."}, "errorPatterns": [{"equals": "l''arche de Noé", "category": "word_confusion", "feedback": "L''arche de Noé est la forme de l''église, pas de l''autel."}], "id": "eg.l78.e03", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e04', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.myron']::text[], 'mcq', 'lesson', 'Avec quelle huile l''évêque consacre-t-il l''autel ?', array['le myron']::text[], 'L''évêque oint l''autel avec le myron, huile sainte que fait le pape d''Alexandrie.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.myron"], "type": "mcq", "difficulty": 2, "prompt": "Avec quelle huile l''évêque consacre-t-il l''autel ?", "options": ["le myron", "l''huile de la lampe", "l''huile d''olive ordinaire", "l''eau bénite"], "answer": "le myron", "acceptedAnswers": ["le myron"], "explanation": "L''évêque oint l''autel avec le myron, huile sainte que fait le pape d''Alexandrie.", "tip": "Myron = huile sainte.", "extraExample": {"text": "Le myron sert aussi à d''autres sacrements.", "translation": "Seul le pape le fait."}, "errorPatterns": [{"equals": "l''eau bénite", "category": "word_confusion", "feedback": "L''eau bénite n''est pas du tout une huile."}], "id": "eg.l78.e04", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e05', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal']::text[], 'mcq', 'lesson', 'Combien de liturgies célèbre-t-on sur un même autel le même jour ?', array['une seule liturgie']::text[], 'Un autel ne sert qu''à une liturgie par jour.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal"], "type": "mcq", "difficulty": 2, "prompt": "Combien de liturgies célèbre-t-on sur un même autel le même jour ?", "options": ["une seule liturgie", "deux liturgies", "trois liturgies", "autant qu''on veut"], "answer": "une seule liturgie", "acceptedAnswers": ["une seule liturgie"], "explanation": "Un autel ne sert qu''à une liturgie par jour.", "tip": "Un autel, une liturgie par jour.", "extraExample": {"text": "Trois autels, trois liturgies possibles.", "translation": "Le dimanche, par exemple."}, "id": "eg.l78.e05", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e06', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal']::text[], 'mcq', 'lesson', 'Pourquoi certaines églises ont-elles trois autels ?', array['pour célébrer plusieurs liturgies le même jour']::text[], 'Chaque autel ne sert qu''une fois par jour : trois autels permettent plusieurs liturgies.', 3, '{"unitIds": ["eg.g78.sanctuaire_haikal"], "type": "mcq", "difficulty": 3, "prompt": "Pourquoi certaines églises ont-elles trois autels ?", "options": ["pour célébrer plusieurs liturgies le même jour", "pour séparer les hommes et les femmes", "parce que chaque évangéliste en a un", "pour garder trois reliques"], "answer": "pour célébrer plusieurs liturgies le même jour", "acceptedAnswers": ["pour célébrer plusieurs liturgies le même jour"], "explanation": "Chaque autel ne sert qu''une fois par jour : trois autels permettent plusieurs liturgies.", "tip": "Plus d''autels, plus de liturgies.", "extraExample": {"text": "Les grandes églises en ont souvent plusieurs.", "translation": "Les petites n''en ont qu''un."}, "id": "eg.l78.e06", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e07', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.entrer_dechausse']::text[], 'mcq', 'lesson', 'Pourquoi entre-t-on déchaussé dans le haikal ?', array['une terre sainte']::text[], 'Dieu dit à Moïse d''ôter ses sandales, car le lieu est une terre sainte ; le haikal est un lieu semblable.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.entrer_dechausse"], "type": "mcq", "difficulty": 2, "prompt": "Pourquoi entre-t-on déchaussé dans le haikal ?", "options": ["une terre sainte", "pour ne pas salir le sol", "pour marcher sans bruit", "par tradition égyptienne"], "answer": "une terre sainte", "acceptedAnswers": ["une terre sainte"], "explanation": "Dieu dit à Moïse d''ôter ses sandales, car le lieu est une terre sainte ; le haikal est un lieu semblable.", "tip": "Terre sainte = pieds nus.", "extraExample": {"text": "Moïse devant le buisson ardent.", "translation": "Humilité."}, "errorPatterns": [{"equals": "pour ne pas salir le sol", "category": "word_confusion", "feedback": "La raison est religieuse, pas la propreté."}], "id": "eg.l78.e07", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e08', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.ciborium']::text[], 'mcq', 'lesson', 'Comment s''appelle la coupole sur quatre piliers au-dessus de l''autel ?', array['le ciborium']::text[], 'Le ciborium couvre l''autel comme le ciel couvre la terre.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.ciborium"], "type": "mcq", "difficulty": 2, "prompt": "Comment s''appelle la coupole sur quatre piliers au-dessus de l''autel ?", "options": ["le ciborium", "le baptistère", "l''iconostase", "le narthex"], "answer": "le ciborium", "acceptedAnswers": ["le ciborium"], "explanation": "Le ciborium couvre l''autel comme le ciel couvre la terre.", "tip": "Ciborium = ciel sur l''autel.", "extraExample": {"text": "Les évangélistes sont peints sur les piliers.", "translation": "La croix est au sommet."}, "id": "eg.l78.e08", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e09', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.patene']::text[], 'mcq', 'lesson', 'Quel objet est le petit plateau rond qui porte le pain ?', array['la patène']::text[], 'La patène porte le pain devenu le corps du Christ.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.patene"], "type": "mcq", "difficulty": 2, "prompt": "Quel objet est le petit plateau rond qui porte le pain ?", "options": ["la patène", "le calice", "la cuillère", "l''astérisque"], "answer": "la patène", "acceptedAnswers": ["la patène"], "explanation": "La patène porte le pain devenu le corps du Christ.", "tip": "Patène = pain ; calice = vin.", "extraExample": {"text": "Elle rappelle la crèche et le tombeau.", "translation": "Elle est ronde."}, "errorPatterns": [{"equals": "le calice", "category": "word_confusion", "feedback": "Le calice est la coupe qui contient le vin."}], "id": "eg.l78.e09", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
