insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e17', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.haikal','eg.v.ciborium','eg.v.myron']::text[], 'match', 'lesson', 'Mots du sanctuaire', '{}'::text[], 'Quatre mots essentiels du sanctuaire.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.haikal", "eg.v.ciborium", "eg.v.myron"], "type": "match", "difficulty": 2, "prompt": "Mots du sanctuaire", "pairs": [{"left": "le haikal", "right": "le sanctuaire"}, {"left": "le myron", "right": "l''huile sainte"}, {"left": "le ciborium", "right": "la coupole sur quatre piliers"}, {"left": "l''autel", "right": "un cube qui représente le tombeau"}], "answer": "le haikal = le sanctuaire ; le myron = l''huile sainte ; le ciborium = la coupole sur quatre piliers ; l''autel = un cube qui représente le tombeau", "acceptedAnswers": [], "explanation": "Quatre mots essentiels du sanctuaire.", "tip": "Haikal, myron, ciborium, autel.", "id": "eg.l78.e17", "promptLanguage": "fr", "instruction": "Associe chaque élément de gauche à celui de droite.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e18', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.myron']::text[], 'reorder', 'lesson', 'Phrase-repère : la consécration de l''autel.', array['L''évêque consacre l''autel avec le myron']::text[], 'Le repère à retenir : le myron consacre l''autel.', 2, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.myron"], "type": "reorder", "difficulty": 2, "prompt": "Phrase-repère : la consécration de l''autel.", "tokens": ["myron", "le", "avec", "l''autel", "consacre", "L''évêque"], "answer": "L''évêque consacre l''autel avec le myron", "acceptedAnswers": ["L''évêque consacre l''autel avec le myron"], "explanation": "Le repère à retenir : le myron consacre l''autel.", "tip": "L''évêque, l''autel, le myron.", "extraExample": {"text": "L''autel est mis à part pour Dieu.", "translation": "C''est la consécration."}, "id": "eg.l78.e18", "promptLanguage": "fr", "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "pool": "lesson", "lessonId": "eg.l78", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e19', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.cuillere']::text[], 'free_answer', 'lesson', 'Quel objet sert à donner aux fidèles le sang du Christ à la communion ?', array['la cuillère','cuillère','cuiller','la cuiller']::text[], 'La cuillère de communion donne aux fidèles le sang du Christ.', 3, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.cuillere"], "type": "free_answer", "difficulty": 3, "prompt": "Quel objet sert à donner aux fidèles le sang du Christ à la communion ?", "answer": "la cuillère", "acceptedAnswers": ["la cuillère", "cuillère", "cuiller", "la cuiller"], "explanation": "La cuillère de communion donne aux fidèles le sang du Christ.", "tip": "Cuillère = communion.", "extraExample": {"text": "Le prêtre la tient.", "translation": "Elle est petite."}, "id": "eg.l78.e19", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e20', 'eg', 'eg.l78', 'eg.g78.sanctuaire_haikal', array['eg.g78.sanctuaire_haikal','eg.v.asterisque']::text[], 'free_answer', 'lesson', 'Comment s''appelle l''objet formé de deux bandes croisées, posé sur la patène, qui rappelle l''étoile des mages ?', array['l''astérisque','astérisque','asterisque','étoile','l''étoile']::text[], 'L''astérisque, ou étoile, soutient le voile au-dessus du pain.', 3, '{"unitIds": ["eg.g78.sanctuaire_haikal", "eg.v.asterisque"], "type": "free_answer", "difficulty": 3, "prompt": "Comment s''appelle l''objet formé de deux bandes croisées, posé sur la patène, qui rappelle l''étoile des mages ?", "answer": "l''astérisque", "acceptedAnswers": ["l''astérisque", "astérisque", "asterisque", "étoile", "l''étoile"], "explanation": "L''astérisque, ou étoile, soutient le voile au-dessus du pain.", "tip": "Astérisque = étoile.", "extraExample": {"text": "Il est sur la patène.", "translation": "Il soutient le voile."}, "id": "eg.l78.e20", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l78.e21', 'eg', 'eg.l78', 'eg.v.tabernacle_de_moise', array['eg.v.tabernacle_de_moise']::text[], 'free_answer', 'lesson', 'Qui a reçu de Dieu le modèle du Tabernacle, au Sinaï ?', array['Moïse','Moise']::text[], 'Révision de la leçon 77 : Dieu montre à Moïse le modèle du Tabernacle ; Moïse est aussi celui qui se déchausse devant le buisson ardent.', 2, '{"unitIds": ["eg.v.tabernacle_de_moise"], "type": "free_answer", "difficulty": 2, "prompt": "Qui a reçu de Dieu le modèle du Tabernacle, au Sinaï ?", "answer": "Moïse", "acceptedAnswers": ["Moïse", "Moise"], "explanation": "Révision de la leçon 77 : Dieu montre à Moïse le modèle du Tabernacle ; Moïse est aussi celui qui se déchausse devant le buisson ardent.", "tip": "Moïse, Tabernacle, sandales.", "extraExample": {"text": "Moïse ôte ses sandales.", "translation": "Dieu lui parle."}, "id": "eg.l78.e21", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l78", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e01', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.iconostase']::text[], 'mcq', 'lesson', 'Quel mot arabe désigne l''iconostase ?', array['le higab']::text[], 'Le higab, le « voile », est la cloison couverte d''icônes entre la nef et le haikal.', 1, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.iconostase"], "type": "mcq", "difficulty": 1, "prompt": "Quel mot arabe désigne l''iconostase ?", "options": ["le higab", "le haikal", "le narthex", "le ciborium"], "answer": "le higab", "acceptedAnswers": ["le higab"], "explanation": "Le higab, le « voile », est la cloison couverte d''icônes entre la nef et le haikal.", "tip": "Higab = voile.", "extraExample": {"text": "Le higab est un mur d''icônes.", "translation": "Il a trois portes."}, "errorPatterns": [{"equals": "le haikal", "category": "word_confusion", "feedback": "Le haikal est le sanctuaire, derrière l''iconostase."}], "id": "eg.l79.e01", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e02', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.iconostase']::text[], 'mcq', 'lesson', 'Qu''est-ce que l''iconostase sépare ?', array['la nef et le haikal']::text[], 'Elle est entre la salle des fidèles et le sanctuaire.', 1, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.iconostase"], "type": "mcq", "difficulty": 1, "prompt": "Qu''est-ce que l''iconostase sépare ?", "options": ["la nef et le haikal", "le narthex et la rue", "l''autel et le ciborium", "les hommes et les femmes"], "answer": "la nef et le haikal", "acceptedAnswers": ["la nef et le haikal"], "explanation": "Elle est entre la salle des fidèles et le sanctuaire.", "tip": "Iconostase = entre nef et haikal.", "extraExample": {"text": "Elle est couverte d''icônes.", "translation": "Ses rideaux s''ouvrent pendant la liturgie."}, "id": "eg.l79.e02", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e03', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.cene']::text[], 'mcq', 'lesson', 'Quelle icône trouve-t-on au-dessus de la porte royale ?', array['la Cène']::text[], 'La Cène est juste au-dessus du haikal, où l''on célèbre l''eucharistie qu''elle a instituée.', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.cene"], "type": "mcq", "difficulty": 2, "prompt": "Quelle icône trouve-t-on au-dessus de la porte royale ?", "options": ["la Cène", "le baptême du Christ", "l''arche de Noé", "le Jugement dernier"], "answer": "la Cène", "acceptedAnswers": ["la Cène"], "explanation": "La Cène est juste au-dessus du haikal, où l''on célèbre l''eucharistie qu''elle a instituée.", "tip": "Cène en haut de la porte.", "extraExample": {"text": "Les apôtres sont de chaque côté.", "translation": "La croix est tout en haut."}, "errorPatterns": [{"equals": "le baptême du Christ", "category": "word_confusion", "feedback": "L''icône du baptême est plutôt auprès du baptistère."}], "id": "eg.l79.e03", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e04', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.saint_jean_baptiste']::text[], 'mcq', 'lesson', 'Quel saint, surnommé le Précurseur, est souvent peint près du Christ ?', array['saint Jean-Baptiste']::text[], 'Jean-Baptiste a préparé la venue du Christ : on dit qu''il est son Précurseur.', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.saint_jean_baptiste"], "type": "mcq", "difficulty": 2, "prompt": "Quel saint, surnommé le Précurseur, est souvent peint près du Christ ?", "options": ["saint Jean-Baptiste", "saint Marc", "saint Pierre", "saint Athanase"], "answer": "saint Jean-Baptiste", "acceptedAnswers": ["saint Jean-Baptiste"], "explanation": "Jean-Baptiste a préparé la venue du Christ : on dit qu''il est son Précurseur.", "tip": "Précurseur = Jean-Baptiste.", "extraExample": {"text": "Il baptise Jésus.", "translation": "Il est prophète."}, "id": "eg.l79.e04", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e05', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.oeuf_d_autruche']::text[], 'mcq', 'lesson', 'Que symbolise l''œuf d''autruche, en plus de la vigilance de Dieu ?', array['la résurrection']::text[], 'Une coquille qui paraît morte mais contient la vie rappelle la résurrection.', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.oeuf_d_autruche"], "type": "mcq", "difficulty": 2, "prompt": "Que symbolise l''œuf d''autruche, en plus de la vigilance de Dieu ?", "options": ["la résurrection", "la création du monde", "le déluge", "la Pentecôte"], "answer": "la résurrection", "acceptedAnswers": ["la résurrection"], "explanation": "Une coquille qui paraît morte mais contient la vie rappelle la résurrection.", "tip": "Œuf = vie qui sort du tombeau.", "extraExample": {"text": "Le Christ sort du tombeau.", "translation": "La vie est dans la coquille."}, "id": "eg.l79.e05", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e06', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.lampe_a_huile']::text[], 'mcq', 'lesson', 'Que représente la lampe à huile allumée devant l''icône ?', array['la lumière du Christ']::text[], 'Le Christ dit : « Je suis la lumière du monde ».', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.lampe_a_huile"], "type": "mcq", "difficulty": 2, "prompt": "Que représente la lampe à huile allumée devant l''icône ?", "options": ["la lumière du Christ", "la fumée des prières", "le feu du buisson", "la chaleur du soleil"], "answer": "la lumière du Christ", "acceptedAnswers": ["la lumière du Christ"], "explanation": "Le Christ dit : « Je suis la lumière du monde ».", "tip": "Lampe = lumière du Christ.", "extraExample": {"text": "Les vierges sages gardent leur lampe.", "translation": "Une flamme qui veille."}, "id": "eg.l79.e06", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e07', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.encens']::text[], 'mcq', 'lesson', 'Que représente la fumée de l''encens qui monte ?', array['les prières']::text[], 'La fumée qui s''élève représente les prières des fidèles qui montent vers Dieu (Ps 141, 2).', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.encens"], "type": "mcq", "difficulty": 2, "prompt": "Que représente la fumée de l''encens qui monte ?", "options": ["les prières", "les péchés", "le nuage du Sinaï", "le feu de l''enfer"], "answer": "les prières", "acceptedAnswers": ["les prières"], "explanation": "La fumée qui s''élève représente les prières des fidèles qui montent vers Dieu (Ps 141, 2).", "tip": "Fumée = prières.", "extraExample": {"text": "Une prière monte vers Dieu.", "translation": "Parfum = vie agréable à Dieu."}, "id": "eg.l79.e07", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e08', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.veneration','eg.v.icone']::text[], 'mcq', 'lesson', 'Que rend-on aux icônes ?', array['la vénération']::text[], 'On honore l''icône en s''inclinant et en l''embrassant ; l''honneur passe à celui qu''elle représente.', 3, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.veneration", "eg.v.icone"], "type": "mcq", "difficulty": 3, "prompt": "Que rend-on aux icônes ?", "options": ["la vénération", "l''adoration", "le sacrifice", "la confession"], "answer": "la vénération", "acceptedAnswers": ["la vénération"], "explanation": "On honore l''icône en s''inclinant et en l''embrassant ; l''honneur passe à celui qu''elle représente.", "tip": "Icône : vénération.", "extraExample": {"text": "L''adoration est pour Dieu seul.", "translation": "Saint Basile : l''honneur passe au modèle."}, "errorPatterns": [{"equals": "l''adoration", "category": "word_confusion", "feedback": "L''adoration est due à Dieu seul, jamais à une icône."}], "id": "eg.l79.e08", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e09', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.adoration']::text[], 'mcq', 'lesson', 'L''adoration, on la doit à qui ?', array['à Dieu seul']::text[], 'Seul Dieu est adoré. Les saints et les icônes reçoivent la vénération.', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.adoration"], "type": "mcq", "difficulty": 2, "prompt": "L''adoration, on la doit à qui ?", "options": ["à Dieu seul", "aux saints", "aux icônes", "aux évêques"], "answer": "à Dieu seul", "acceptedAnswers": ["à Dieu seul"], "explanation": "Seul Dieu est adoré. Les saints et les icônes reçoivent la vénération.", "tip": "Adorer : Dieu seul.", "extraExample": {"text": "On vénère les saints.", "translation": "On adore la Trinité."}, "id": "eg.l79.e09", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e10', 'eg', 'eg.l79', 'eg.v.haikal', array['eg.v.haikal']::text[], 'mcq', 'lesson', 'Comment s''appelle le sanctuaire situé derrière l''iconostase ?', array['le haikal']::text[], 'Révision de la leçon 78 : le haikal est derrière l''iconostase, avec l''autel.', 1, '{"unitIds": ["eg.v.haikal"], "type": "mcq", "difficulty": 1, "prompt": "Comment s''appelle le sanctuaire situé derrière l''iconostase ?", "options": ["le haikal", "le narthex", "le parvis", "la nef"], "answer": "le haikal", "acceptedAnswers": ["le haikal"], "explanation": "Révision de la leçon 78 : le haikal est derrière l''iconostase, avec l''autel.", "tip": "Haikal = sanctuaire.", "extraExample": {"text": "L''autel est dans le haikal.", "translation": "On y entre déchaussé."}, "id": "eg.l79.e10", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e11', 'eg', 'eg.l79', 'eg.v.autel', array['eg.v.autel']::text[], 'mcq', 'lesson', 'Qu''est-ce que l''autel représente ?', array['le tombeau du Christ']::text[], 'Révision de la leçon 78 : l''autel est un cube qui rappelle le tombeau du Christ.', 2, '{"unitIds": ["eg.v.autel"], "type": "mcq", "difficulty": 2, "prompt": "Qu''est-ce que l''autel représente ?", "options": ["le tombeau du Christ", "le lieu saint", "le Sinaï", "l''arche de Noé"], "answer": "le tombeau du Christ", "acceptedAnswers": ["le tombeau du Christ"], "explanation": "Révision de la leçon 78 : l''autel est un cube qui rappelle le tombeau du Christ.", "tip": "Autel = tombeau du Christ.", "extraExample": {"text": "Il est consacré au myron.", "translation": "Il est au centre du haikal."}, "id": "eg.l79.e11", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e12', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.porte_royale']::text[], 'fill_blank', 'lesson', 'Au centre de l''iconostase s''ouvre la grande porte appelée la porte ___.', array['royale']::text[], 'C''est par la porte royale que le Christ, le Roi, vient à nous.', 1, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.porte_royale"], "type": "fill_blank", "difficulty": 1, "prompt": "Au centre de l''iconostase s''ouvre la grande porte appelée la porte ___.", "options": ["royale", "latérale", "dorée"], "answer": "royale", "acceptedAnswers": ["royale"], "explanation": "C''est par la porte royale que le Christ, le Roi, vient à nous.", "tip": "Porte royale = porte du Roi.", "extraExample": {"text": "Elle est plus grande que les autres.", "translation": "La Cène est au-dessus."}, "id": "eg.l79.e12", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e13', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.oeuf_d_autruche']::text[], 'fill_blank', 'lesson', 'Selon la tradition, l''œuf d''autruche rappelle que Dieu veille ___ sur nous.', array['sans cesse']::text[], 'L''autruche garde les yeux fixés sur ses œufs, comme Dieu veille sur nous.', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.oeuf_d_autruche"], "type": "fill_blank", "difficulty": 2, "prompt": "Selon la tradition, l''œuf d''autruche rappelle que Dieu veille ___ sur nous.", "options": ["sans cesse", "rarement", "le soir"], "answer": "sans cesse", "acceptedAnswers": ["sans cesse"], "explanation": "L''autruche garde les yeux fixés sur ses œufs, comme Dieu veille sur nous.", "tip": "Dieu ne dort pas.", "extraExample": {"text": "Dieu veille jour et nuit.", "translation": "L''œuf est suspendu."}, "id": "eg.l79.e13", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e14', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.cene']::text[], 'fill_blank', 'lesson', 'Le dernier repas du Christ avec ses disciples est représenté par l''icône de la ___.', array['Cène']::text[], 'La Cène est placée au-dessus de la porte royale.', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.cene"], "type": "fill_blank", "difficulty": 2, "prompt": "Le dernier repas du Christ avec ses disciples est représenté par l''icône de la ___.", "options": ["Cène", "Pentecôte", "Transfiguration"], "answer": "Cène", "acceptedAnswers": ["Cène"], "explanation": "La Cène est placée au-dessus de la porte royale.", "tip": "Cène = dernier repas.", "extraExample": {"text": "Le Christ y institue l''eucharistie.", "translation": "Les douze sont présents."}, "id": "eg.l79.e14", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e15', 'eg', 'eg.l79', 'eg.v.ciborium', array['eg.v.ciborium']::text[], 'fill_blank', 'lesson', 'Au-dessus de l''autel, quatre piliers portent une coupole : le ___.', array['ciborium']::text[], 'Révision de la leçon 78 : le ciborium couvre l''autel comme le ciel couvre la terre.', 2, '{"unitIds": ["eg.v.ciborium"], "type": "fill_blank", "difficulty": 2, "prompt": "Au-dessus de l''autel, quatre piliers portent une coupole : le ___.", "options": ["ciborium", "narthex", "higab"], "answer": "ciborium", "acceptedAnswers": ["ciborium"], "explanation": "Révision de la leçon 78 : le ciborium couvre l''autel comme le ciel couvre la terre.", "tip": "Ciborium = ciel sur l''autel.", "extraExample": {"text": "Il est peint de l''icône du Christ.", "translation": "Les évangélistes sont sur les piliers."}, "id": "eg.l79.e15", "promptLanguage": "fr", "instruction": "Complète la phrase.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e16', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.porte_royale','eg.v.cene']::text[], 'match', 'lesson', 'Où sont placées les icônes ?', '{}'::text[], 'Les icônes suivent un ordre, même s''il peut varier un peu.', 2, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.porte_royale", "eg.v.cene"], "type": "match", "difficulty": 2, "prompt": "Où sont placées les icônes ?", "pairs": [{"left": "le Christ", "right": "à droite de la porte royale"}, {"left": "la Vierge Marie", "right": "à gauche de la porte royale"}, {"left": "la Cène", "right": "au-dessus de la porte royale"}, {"left": "la croix", "right": "tout en haut de l''iconostase"}], "answer": "le Christ = à droite de la porte royale ; la Vierge Marie = à gauche de la porte royale ; la Cène = au-dessus de la porte royale ; la croix = tout en haut de l''iconostase", "acceptedAnswers": [], "explanation": "Les icônes suivent un ordre, même s''il peut varier un peu.", "tip": "Christ à droite, Marie à gauche, Cène au centre, croix en haut.", "id": "eg.l79.e16", "promptLanguage": "fr", "instruction": "Associe chaque élément de gauche à celui de droite.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e17', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.lampe_a_huile','eg.v.oeuf_d_autruche','eg.v.encens']::text[], 'match', 'lesson', 'Les symboles de l''église et leur sens', '{}'::text[], 'Chaque objet de l''église porte un sens.', 3, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.lampe_a_huile", "eg.v.oeuf_d_autruche", "eg.v.encens"], "type": "match", "difficulty": 3, "prompt": "Les symboles de l''église et leur sens", "pairs": [{"left": "la lampe à huile", "right": "la lumière du Christ"}, {"left": "l''œuf d''autruche", "right": "la résurrection"}, {"left": "la fumée d''encens", "right": "les prières qui montent"}, {"left": "l''icône", "right": "la vénération"}], "answer": "la lampe à huile = la lumière du Christ ; l''œuf d''autruche = la résurrection ; la fumée d''encens = les prières qui montent ; l''icône = la vénération", "acceptedAnswers": [], "explanation": "Chaque objet de l''église porte un sens.", "tip": "Lampe, œuf, fumée, icône.", "id": "eg.l79.e17", "promptLanguage": "fr", "instruction": "Associe chaque élément de gauche à celui de droite.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e18', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.adoration','eg.v.veneration']::text[], 'reorder', 'lesson', 'Phrase-repère : vénérer et adorer.', array['On vénère l''icône mais on adore Dieu seul']::text[], 'Le repère à retenir : vénération pour l''icône, adoration pour Dieu seul.', 3, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.adoration", "eg.v.veneration"], "type": "reorder", "difficulty": 3, "prompt": "Phrase-repère : vénérer et adorer.", "tokens": ["seul", "Dieu", "adore", "on", "mais", "l''icône", "vénère", "On"], "answer": "On vénère l''icône mais on adore Dieu seul", "acceptedAnswers": ["On vénère l''icône mais on adore Dieu seul"], "explanation": "Le repère à retenir : vénération pour l''icône, adoration pour Dieu seul.", "tip": "Vénérer ≠ adorer.", "extraExample": {"text": "On vénère les saints.", "translation": "On adore Dieu."}, "id": "eg.l79.e18", "promptLanguage": "fr", "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "pool": "lesson", "lessonId": "eg.l79", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l79.e19', 'eg', 'eg.l79', 'eg.g79.iconostase_icones', array['eg.g79.iconostase_icones','eg.v.encens']::text[], 'free_answer', 'lesson', 'Quel prophète annonce qu''en tout lieu on offrira de l''encens à Dieu ?', array['Malachie','le prophète Malachie']::text[], 'Le prophète Malachie annonce l''encens offert en tout lieu.', 3, '{"unitIds": ["eg.g79.iconostase_icones", "eg.v.encens"], "type": "free_answer", "difficulty": 3, "prompt": "Quel prophète annonce qu''en tout lieu on offrira de l''encens à Dieu ?", "answer": "Malachie", "acceptedAnswers": ["Malachie", "le prophète Malachie"], "explanation": "Le prophète Malachie annonce l''encens offert en tout lieu.", "tip": "Malachie = encens.", "extraExample": {"text": "Malachie appelle aussi le Christ « soleil de justice ».", "translation": "Un seul prophète."}, "id": "eg.l79.e19", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l79", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
