insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l80.e02', 'eg', 'eg.l80', 'eg.g80.diaconat', array['eg.g80.diaconat','eg.v.psalte']::text[], 'mcq', 'lesson', 'Quel est le premier rang du diaconat, celui qui chante les hymnes ?', array['le psalte']::text[], 'Le psalte (épsaltos) est le chantre, tout en bas de l''échelle.', 1, '{"unitIds": ["eg.g80.diaconat", "eg.v.psalte"], "type": "mcq", "difficulty": 1, "prompt": "Quel est le premier rang du diaconat, celui qui chante les hymnes ?", "options": ["le psalte", "le lecteur", "le sous-diacre", "l''archidiacre"], "answer": "le psalte", "acceptedAnswers": ["le psalte"], "explanation": "Le psalte (épsaltos) est le chantre, tout en bas de l''échelle.", "tip": "Psalte = psaumes.", "extraExample": {"text": "On commence souvent enfant.", "translation": "Il chante avec l''assemblée."}, "id": "eg.l80.e02", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l80", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
