insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e01', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.abouna']::text[], 'mcq', 'lesson', 'Que veut dire « abouna », le nom que l''on donne au prêtre ?', array['notre père']::text[], 'Abouna est l''arabe pour « notre père ».', 1, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.abouna"], "type": "mcq", "difficulty": 1, "prompt": "Que veut dire « abouna », le nom que l''on donne au prêtre ?", "options": ["notre père", "notre frère", "notre berger", "notre maître"], "answer": "notre père", "acceptedAnswers": ["notre père"], "explanation": "Abouna est l''arabe pour « notre père ».", "tip": "Abouna = notre père.", "extraExample": {"text": "Pape vient aussi de « père ».", "translation": "Le prêtre est un père spirituel."}, "id": "eg.l81.e01", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e02', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.pretre_marie']::text[], 'mcq', 'lesson', 'Quand un prêtre copte peut-il se marier ?', array['avant son ordination']::text[], 'Le mariage précède l''ordination ; après, le prêtre ne peut plus se marier.', 2, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.pretre_marie"], "type": "mcq", "difficulty": 2, "prompt": "Quand un prêtre copte peut-il se marier ?", "options": ["avant son ordination", "après son ordination", "jamais", "à tout moment"], "answer": "avant son ordination", "acceptedAnswers": ["avant son ordination"], "explanation": "Le mariage précède l''ordination ; après, le prêtre ne peut plus se marier.", "tip": "Marié avant, pas après.", "extraExample": {"text": "Un prêtre veuf ne se remarie pas.", "translation": "Les moines restent célibataires."}, "errorPatterns": [{"equals": "après son ordination", "category": "word_confusion", "feedback": "C''est l''inverse : après l''ordination, il n''est plus possible de se marier."}], "id": "eg.l81.e02", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
