insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e04', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape']::text[], 'mcq', 'lesson', 'Parmi qui choisit-on les évêques coptes ?', array['les moines']::text[], 'Les évêques coptes sont toujours choisis parmi les moines.', 2, '{"unitIds": ["eg.g81.pretres_eveques_pape"], "type": "mcq", "difficulty": 2, "prompt": "Parmi qui choisit-on les évêques coptes ?", "options": ["les moines", "les prêtres mariés", "les diacres", "les fidèles de chaque ville"], "answer": "les moines", "acceptedAnswers": ["les moines"], "explanation": "Les évêques coptes sont toujours choisis parmi les moines.", "tip": "Évêque = moine.", "extraExample": {"text": "Ils sont célibataires.", "translation": "Ils ont vécu au monastère."}, "id": "eg.l81.e04", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e05', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape']::text[], 'mcq', 'lesson', 'Quel est le pouvoir propre de l''évêque ?', array['ordonner les prêtres et les diacres']::text[], 'Seul l''évêque peut ordonner par imposition des mains.', 2, '{"unitIds": ["eg.g81.pretres_eveques_pape"], "type": "mcq", "difficulty": 2, "prompt": "Quel est le pouvoir propre de l''évêque ?", "options": ["ordonner les prêtres et les diacres", "chanter l''office", "lire l''Évangile", "garder les portes"], "answer": "ordonner les prêtres et les diacres", "acceptedAnswers": ["ordonner les prêtres et les diacres"], "explanation": "Seul l''évêque peut ordonner par imposition des mains.", "tip": "Ordonner = évêque.", "extraExample": {"text": "Le prêtre ne peut pas ordonner.", "translation": "Le patriarche ordonne les évêques."}, "id": "eg.l81.e05", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e06', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.saint_synode']::text[], 'mcq', 'lesson', 'Qui préside le saint-synode ?', array['le pape d''Alexandrie']::text[], 'Le saint-synode réunit les évêques autour du pape.', 2, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.saint_synode"], "type": "mcq", "difficulty": 2, "prompt": "Qui préside le saint-synode ?", "options": ["le pape d''Alexandrie", "le qommos", "le métropolite le plus ancien", "l''archidiacre"], "answer": "le pape d''Alexandrie", "acceptedAnswers": ["le pape d''Alexandrie"], "explanation": "Le saint-synode réunit les évêques autour du pape.", "tip": "Pape = président.", "extraExample": {"text": "Il décide des grandes questions.", "translation": "Comme un concile."}, "id": "eg.l81.e06", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e07', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.metropolite']::text[], 'mcq', 'lesson', 'Comment appelle-t-on un évêque promu à la tête d''un grand diocèse ?', array['le métropolite']::text[], 'Le métropolite est cité avant les évêques dans les prières.', 3, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.metropolite"], "type": "mcq", "difficulty": 3, "prompt": "Comment appelle-t-on un évêque promu à la tête d''un grand diocèse ?", "options": ["le métropolite", "l''archiprêtre", "l''archidiacre", "le confesseur"], "answer": "le métropolite", "acceptedAnswers": ["le métropolite"], "explanation": "Le métropolite est cité avant les évêques dans les prières.", "tip": "Métropolite = grand diocèse.", "extraExample": {"text": "Il reste évêque.", "translation": "C''est une promotion."}, "errorPatterns": [{"equals": "l''archiprêtre", "category": "word_confusion", "feedback": "L''archiprêtre est un prêtre promu, pas un évêque."}], "id": "eg.l81.e07", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e08', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.qora_haykaleya']::text[], 'mcq', 'lesson', 'Qu''est-ce qui désigne finalement le pape ?', array['le tirage au sort sur l''autel']::text[], 'Après le vote qui retient trois noms, le sort désigne le pape pour que Dieu choisisse.', 2, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.qora_haykaleya"], "type": "mcq", "difficulty": 2, "prompt": "Qu''est-ce qui désigne finalement le pape ?", "options": ["le tirage au sort sur l''autel", "l''empereur", "un vote à main levée", "le pape précédent"], "answer": "le tirage au sort sur l''autel", "acceptedAnswers": ["le tirage au sort sur l''autel"], "explanation": "Après le vote qui retient trois noms, le sort désigne le pape pour que Dieu choisisse.", "tip": "Vote puis sort.", "extraExample": {"text": "Les apôtres ont tiré au sort Matthias.", "translation": "Dieu choisit."}, "id": "eg.l81.e08", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e09', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.qora_haykaleya']::text[], 'mcq', 'lesson', 'Qui tire le nom du pape sur l''autel ?', array['un enfant aux yeux bandés']::text[], 'Un enfant aux yeux bandés ne peut pas influencer le choix : c''est Dieu qui décide.', 3, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.qora_haykaleya"], "type": "mcq", "difficulty": 3, "prompt": "Qui tire le nom du pape sur l''autel ?", "options": ["un enfant aux yeux bandés", "le plus ancien évêque", "le patriarche sortant", "un moine du désert"], "answer": "un enfant aux yeux bandés", "acceptedAnswers": ["un enfant aux yeux bandés"], "explanation": "Un enfant aux yeux bandés ne peut pas influencer le choix : c''est Dieu qui décide.", "tip": "Enfant = innocent.", "extraExample": {"text": "Les yeux sont bandés.", "translation": "Un seul nom est tiré."}, "id": "eg.l81.e09", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e10', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.tawadros_ii']::text[], 'mcq', 'lesson', 'Quel numéro porte Tawadros II dans la lignée des successeurs de saint Marc ?', array['118e']::text[], 'Tawadros II est le 118e pape d''Alexandrie, depuis 2012.', 2, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.tawadros_ii"], "type": "mcq", "difficulty": 2, "prompt": "Quel numéro porte Tawadros II dans la lignée des successeurs de saint Marc ?", "options": ["118e", "117e", "100e", "128e"], "answer": "118e", "acceptedAnswers": ["118e"], "explanation": "Tawadros II est le 118e pape d''Alexandrie, depuis 2012.", "tip": "Tawadros = 118.", "extraExample": {"text": "Chenouda III était le 117e.", "translation": "Le 4 novembre 2012."}, "errorPatterns": [{"equals": "117e", "category": "word_confusion", "feedback": "117e est le numéro de Chenouda III, son prédécesseur."}], "id": "eg.l81.e10", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
