insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e16', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.qommos','eg.v.metropolite']::text[], 'match', 'lesson', 'Le clergé : qui est qui ?', '{}'::text[], 'Chaque titre correspond à une charge précise.', 3, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.qommos", "eg.v.metropolite"], "type": "match", "difficulty": 3, "prompt": "Le clergé : qui est qui ?", "pairs": [{"left": "le prêtre", "right": "célèbre les sacrements"}, {"left": "le qommos", "right": "l''archiprêtre"}, {"left": "l''évêque", "right": "ordonne les prêtres et les diacres"}, {"left": "le métropolite", "right": "évêque d''un grand diocèse"}, {"left": "le patriarche", "right": "le pape d''Alexandrie"}], "answer": "le prêtre = célèbre les sacrements ; le qommos = l''archiprêtre ; l''évêque = ordonne les prêtres et les diacres ; le métropolite = évêque d''un grand diocèse ; le patriarche = le pape d''Alexandrie", "acceptedAnswers": [], "explanation": "Chaque titre correspond à une charge précise.", "tip": "Du prêtre au patriarche, on monte en responsabilité.", "id": "eg.l81.e16", "promptLanguage": "fr", "instruction": "Associe chaque élément de gauche à celui de droite.", "pool": "lesson", "lessonId": "eg.l81", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
