insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l81.e19', 'eg', 'eg.l81', 'eg.g81.pretres_eveques_pape', array['eg.g81.pretres_eveques_pape','eg.v.chenouda_iii']::text[], 'free_answer', 'lesson', 'Quel pape a précédé Tawadros II à la tête de l''Église copte ?', array['Chenouda III','Chenouda','Shenouda III','Shenouda','Chenouda 3']::text[], 'Chenouda III, 117e pape, est mort en 2012.', 3, '{"unitIds": ["eg.g81.pretres_eveques_pape", "eg.v.chenouda_iii"], "type": "free_answer", "difficulty": 3, "prompt": "Quel pape a précédé Tawadros II à la tête de l''Église copte ?", "answer": "Chenouda III", "acceptedAnswers": ["Chenouda III", "Chenouda", "Shenouda III", "Shenouda", "Chenouda 3"], "explanation": "Chenouda III, 117e pape, est mort en 2012.", "tip": "117e puis 118e.", "extraExample": {"text": "Il est mort en mars 2012.", "translation": "Tawadros II lui a succédé."}, "id": "eg.l81.e19", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l81", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
