insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l82.e01', 'eg', 'eg.l82', 'eg.g82.monachisme_bilan', array['eg.g82.monachisme_bilan','eg.v.eskime']::text[], 'mcq', 'lesson', 'Comment s''appelle le cordon de cuir orné de croix, habit le plus élevé du moine ?', array['l''eskime']::text[], 'L''eskime est donné aux moines de grande vie spirituelle, souvent ermites.', 2, '{"unitIds": ["eg.g82.monachisme_bilan", "eg.v.eskime"], "type": "mcq", "difficulty": 2, "prompt": "Comment s''appelle le cordon de cuir orné de croix, habit le plus élevé du moine ?", "options": ["l''eskime", "l''étole", "la tunique", "le higab"], "answer": "l''eskime", "acceptedAnswers": ["l''eskime"], "explanation": "L''eskime est donné aux moines de grande vie spirituelle, souvent ermites.", "tip": "Eskime = cuir et croix.", "extraExample": {"text": "L''abbé le revêt.", "translation": "Il se porte sur la poitrine et le dos."}, "errorPatterns": [{"equals": "l''étole", "category": "word_confusion", "feedback": "L''étole est portée par les diacres ordonnés, pas par les moines."}], "id": "eg.l82.e01", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l82", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l82.e02', 'eg', 'eg.l82', 'eg.g82.monachisme_bilan', array['eg.g82.monachisme_bilan','eg.v.moine']::text[], 'mcq', 'lesson', 'Que fait le moine ?', array['prie, travaille et jeûne']::text[], 'Le moine quitte le monde pour se donner à Dieu par la prière, le travail et le jeûne.', 1, '{"unitIds": ["eg.g82.monachisme_bilan", "eg.v.moine"], "type": "mcq", "difficulty": 1, "prompt": "Que fait le moine ?", "options": ["prie, travaille et jeûne", "célèbre l''eucharistie", "dirige un diocèse", "chante à l''église"], "answer": "prie, travaille et jeûne", "acceptedAnswers": ["prie, travaille et jeûne"], "explanation": "Le moine quitte le monde pour se donner à Dieu par la prière, le travail et le jeûne.", "tip": "Moine : prière, travail, jeûne.", "extraExample": {"text": "Il renonce au mariage.", "translation": "Il vit au monastère."}, "id": "eg.l82.e02", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l82", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
