insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l82.e06', 'eg', 'eg.l82', 'eg.g82.monachisme_bilan', array['eg.g82.monachisme_bilan','eg.v.wadi_natroun','eg.v.scete']::text[], 'mcq', 'lesson', 'Quel est l''ancien nom de la vallée de Wadi Natroun ?', array['Scété']::text[], 'Wadi Natroun est l''ancienne Scété de saint Macaire le Grand.', 2, '{"unitIds": ["eg.g82.monachisme_bilan", "eg.v.wadi_natroun", "eg.v.scete"], "type": "mcq", "difficulty": 2, "prompt": "Quel est l''ancien nom de la vallée de Wadi Natroun ?", "options": ["Scété", "Alexandrie", "Antioche", "Éphèse"], "answer": "Scété", "acceptedAnswers": ["Scété"], "explanation": "Wadi Natroun est l''ancienne Scété de saint Macaire le Grand.", "tip": "Scété = Wadi Natroun.", "extraExample": {"text": "Macaire y a vécu.", "translation": "Des centaines de monastères y ont existé."}, "id": "eg.l82.e06", "promptLanguage": "fr", "instruction": "Choisis la bonne réponse.", "pool": "lesson", "lessonId": "eg.l82", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
