insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l82.e18', 'eg', 'eg.l82', 'eg.g82.monachisme_bilan', array['eg.g82.monachisme_bilan','eg.v.wadi_natroun']::text[], 'free_answer', 'lesson', 'Comment s''appelle la vallée, à environ cent kilomètres au nord-ouest du Caire, qui garde quatre monastères anciens ?', array['Wadi Natroun','Wadi Natrun','Wadi El Natrun','Wadi el-Natroun','Wadi el Natroun','Wadi Al Natrun']::text[], 'Wadi Natroun est l''ancienne Scété.', 3, '{"unitIds": ["eg.g82.monachisme_bilan", "eg.v.wadi_natroun"], "type": "free_answer", "difficulty": 3, "prompt": "Comment s''appelle la vallée, à environ cent kilomètres au nord-ouest du Caire, qui garde quatre monastères anciens ?", "answer": "Wadi Natroun", "acceptedAnswers": ["Wadi Natroun", "Wadi Natrun", "Wadi El Natrun", "Wadi el-Natroun", "Wadi el Natroun", "Wadi Al Natrun"], "explanation": "Wadi Natroun est l''ancienne Scété.", "tip": "Wadi Natroun = Scété.", "extraExample": {"text": "Saint Macaire y a vécu.", "translation": "Quatre monastères y survivent."}, "id": "eg.l82.e18", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l82", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l82.e19', 'eg', 'eg.l82', 'eg.g82.monachisme_bilan', array['eg.g82.monachisme_bilan','eg.v.abbe']::text[], 'free_answer', 'lesson', 'Comment appelle-t-on le chef et le père spirituel d''un monastère ?', array['l''abbé','abbé','higoumène','le higoumène','hégoumène','l''hégoumène']::text[], 'L''abbé, ou higoumène, dirige le monastère.', 2, '{"unitIds": ["eg.g82.monachisme_bilan", "eg.v.abbe"], "type": "free_answer", "difficulty": 2, "prompt": "Comment appelle-t-on le chef et le père spirituel d''un monastère ?", "answer": "l''abbé", "acceptedAnswers": ["l''abbé", "abbé", "higoumène", "le higoumène", "hégoumène", "l''hégoumène"], "explanation": "L''abbé, ou higoumène, dirige le monastère.", "tip": "Abbé = père du monastère.", "extraExample": {"text": "Les moines lui obéissent.", "translation": "Il revêt les moines de l''habit."}, "id": "eg.l82.e19", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l82", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l82.e20', 'eg', 'eg.l82', 'eg.v.archidiacre', array['eg.v.archidiacre']::text[], 'free_answer', 'lesson', 'Comment s''appelle le chef de tous les diacres ?', array['l''archidiacre','archidiacre']::text[], 'Révision de la leçon 80 : l''archidiacre dirige tous les diacres.', 2, '{"unitIds": ["eg.v.archidiacre"], "type": "free_answer", "difficulty": 2, "prompt": "Comment s''appelle le chef de tous les diacres ?", "answer": "l''archidiacre", "acceptedAnswers": ["l''archidiacre", "archidiacre"], "explanation": "Révision de la leçon 80 : l''archidiacre dirige tous les diacres.", "tip": "Archi = chef.", "extraExample": {"text": "Dioscore l''a été.", "translation": "Il fait le lien avec l''évêque."}, "id": "eg.l82.e20", "promptLanguage": "fr", "instruction": "Écris ta réponse.", "pool": "lesson", "lessonId": "eg.l82", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e01', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'mcq', 'lesson', 'Que veut dire le mot Agpeya ?', array['le livre des heures']::text[], 'Agpeya vient du copte agp, « heure » : c''est le livre des heures.', 1, '{"id": "eg.l83.e01", "unitIds": ["eg.g83.prier_aux_heures"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le mot Agpeya ?", "promptLanguage": "fr", "options": ["le livre de la messe", "le livre des heures", "le livre des psaumes", "le livre des saints"], "answer": "le livre des heures", "acceptedAnswers": ["le livre des heures"], "explanation": "Agpeya vient du copte agp, « heure » : c''est le livre des heures.", "tip": "Agpeya = heure.", "extraExample": {"text": "Le mot arabe « sa3a » veut aussi dire heure.", "translation": "Même idée."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e02', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures','eg.v.psaume_119_164']::text[], 'mcq', 'lesson', 'Quel verset ouvre l''Agpeya ?', array['Sept fois le jour je te loue']::text[], 'C''est le psaume 119, 164 : il donne l''idée des sept heures de prière.', 1, '{"id": "eg.l83.e02", "unitIds": ["eg.g83.prier_aux_heures", "eg.v.psaume_119_164"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel verset ouvre l''Agpeya ?", "promptLanguage": "fr", "options": ["Le Seigneur est mon berger", "Que ta volonté soit faite", "Sept fois le jour je te loue", "Priez sans cesse"], "answer": "Sept fois le jour je te loue", "acceptedAnswers": ["Sept fois le jour je te loue"], "explanation": "C''est le psaume 119, 164 : il donne l''idée des sept heures de prière.", "tip": "Sept fois = sept heures.", "extraExample": {"text": "Chaque heure est une louange.", "translation": "Sept louanges par jour."}, "errorPatterns": [{"equals": "Priez sans cesse", "category": "word_confusion", "feedback": "« Priez sans cesse » est de saint Paul (1 Th 5, 17), pas le verset d''ouverture de l''Agpeya."}], "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e03', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures','eg.v.sept_heures']::text[], 'mcq', 'lesson', 'Combien d''heures de prière contient l''Agpeya, sans compter la prière du voile ?', array['sept']::text[], 'Sept heures : Prime, Tierce, Sexte, None, Vêpres, Complies et Minuit.', 1, '{"id": "eg.l83.e03", "unitIds": ["eg.g83.prier_aux_heures", "eg.v.sept_heures"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien d''heures de prière contient l''Agpeya, sans compter la prière du voile ?", "promptLanguage": "fr", "options": ["cinq", "douze", "trois", "sept"], "answer": "sept", "acceptedAnswers": ["sept"], "explanation": "Sept heures : Prime, Tierce, Sexte, None, Vêpres, Complies et Minuit.", "tip": "Sept fois le jour.", "extraExample": {"text": "Sept heures, plus la prière du voile.", "translation": "Huit sections en tout."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e04', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures','eg.v.daniel_prophete']::text[], 'mcq', 'lesson', 'Quel prophète prie trois fois par jour, à genoux, tourné vers Jérusalem ?', array['Daniel']::text[], 'Daniel garde ses heures de prière à Babylone, même sous la menace de la fosse aux lions.', 1, '{"id": "eg.l83.e04", "unitIds": ["eg.g83.prier_aux_heures", "eg.v.daniel_prophete"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel prophète prie trois fois par jour, à genoux, tourné vers Jérusalem ?", "promptLanguage": "fr", "options": ["Élie", "Moïse", "Daniel", "Jonas"], "answer": "Daniel", "acceptedAnswers": ["Daniel"], "explanation": "Daniel garde ses heures de prière à Babylone, même sous la menace de la fosse aux lions.", "tip": "Daniel = trois fois par jour.", "extraExample": {"text": "Il est un modèle de fidélité.", "translation": "Il prie malgré l''interdit du roi."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e05', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'mcq', 'lesson', 'À quelle heure l''Esprit descend-il sur les apôtres selon Ac 2, 15 ?', array['la troisième heure']::text[], 'Le jour de la Pentecôte, c''est la troisième heure du jour.', 2, '{"id": "eg.l83.e05", "unitIds": ["eg.g83.prier_aux_heures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "À quelle heure l''Esprit descend-il sur les apôtres selon Ac 2, 15 ?", "promptLanguage": "fr", "options": ["la troisième heure", "la neuvième heure", "la sixième heure", "la première heure"], "answer": "la troisième heure", "acceptedAnswers": ["la troisième heure"], "explanation": "Le jour de la Pentecôte, c''est la troisième heure du jour.", "tip": "Troisième heure = Pentecôte.", "extraExample": {"text": "Troisième heure : 9 h du matin.", "translation": "Tierce vient de là."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e06', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'mcq', 'lesson', 'Que rappelle chaque heure de l''Agpeya ?', array['un moment de la vie du Christ']::text[], 'Chaque heure fait revivre un moment de la vie du Christ, de l''incarnation à sa seconde venue.', 2, '{"id": "eg.l83.e06", "unitIds": ["eg.g83.prier_aux_heures"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que rappelle chaque heure de l''Agpeya ?", "promptLanguage": "fr", "options": ["un saint du calendrier", "un moment de la vie du Christ", "un psaume de David", "une fête de la Vierge"], "answer": "un moment de la vie du Christ", "acceptedAnswers": ["un moment de la vie du Christ"], "explanation": "Chaque heure fait revivre un moment de la vie du Christ, de l''incarnation à sa seconde venue.", "tip": "Une heure = un événement.", "extraExample": {"text": "Midi rappelle la crucifixion.", "translation": "On le voit à la leçon suivante."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e07', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures','eg.v.regle_de_priere']::text[], 'mcq', 'lesson', 'Qui peut prier les heures de l''Agpeya ?', array['tous les fidèles']::text[], 'Le livre est fait pour tous les fidèles, à la maison comme à l''église.', 2, '{"id": "eg.l83.e07", "unitIds": ["eg.g83.prier_aux_heures", "eg.v.regle_de_priere"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui peut prier les heures de l''Agpeya ?", "promptLanguage": "fr", "options": ["les évêques seulement", "les moines seulement", "les diacres seulement", "tous les fidèles"], "answer": "tous les fidèles", "acceptedAnswers": ["tous les fidèles"], "explanation": "Le livre est fait pour tous les fidèles, à la maison comme à l''église.", "tip": "Pas réservé aux moines.", "extraExample": {"text": "Un enfant peut prier une heure.", "translation": "Il suffit de commencer petit."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e08', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'mcq', 'lesson', 'Pour qui la prière du voile est-elle surtout écrite ?', array['les évêques, les prêtres et les moines']::text[], 'Cette prière à part est surtout pour le clergé et les moines.', 3, '{"id": "eg.l83.e08", "unitIds": ["eg.g83.prier_aux_heures"], "type": "mcq", "difficulty": 3, "instruction": "Choisis la bonne réponse.", "prompt": "Pour qui la prière du voile est-elle surtout écrite ?", "promptLanguage": "fr", "options": ["les diacres de chœur", "les catéchumènes", "les évêques, les prêtres et les moines", "tous les enfants"], "answer": "les évêques, les prêtres et les moines", "acceptedAnswers": ["les évêques, les prêtres et les moines"], "explanation": "Cette prière à part est surtout pour le clergé et les moines.", "tip": "Voile = clergé et moines.", "extraExample": {"text": "On la voit à la leçon sur Minuit.", "translation": "Elle ne fait pas partie des sept heures."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
