insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e11', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures','eg.v.prier_sans_cesse']::text[], 'fill_blank', 'lesson', 'Saint Paul demande de prier sans ___.', array['cesse']::text[], '1 Th 5, 17 : « Priez sans cesse ». Les heures en sont les repères.', 2, '{"id": "eg.l83.e11", "unitIds": ["eg.g83.prier_aux_heures", "eg.v.prier_sans_cesse"], "type": "fill_blank", "difficulty": 2, "instruction": "Complète la phrase.", "prompt": "Saint Paul demande de prier sans ___.", "promptLanguage": "fr", "options": ["bruit", "cesse", "pause", "fin"], "answer": "cesse", "acceptedAnswers": ["cesse"], "explanation": "1 Th 5, 17 : « Priez sans cesse ». Les heures en sont les repères.", "tip": "Sans cesse = sans arrêt.", "extraExample": {"text": "Dieu reste présent toute la journée.", "translation": "Les heures aident à ne pas l''oublier."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e12', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'match', 'lesson', 'Associe chaque référence biblique à l''heure.', '{}'::text[], 'Les apôtres prient à la troisième, la sixième et la neuvième heure.', 2, '{"id": "eg.l83.e12", "unitIds": ["eg.g83.prier_aux_heures"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque référence biblique à l''heure.", "promptLanguage": "fr", "pairs": [{"left": "Ac 2, 15", "right": "la troisième heure"}, {"left": "Ac 10, 9", "right": "la sixième heure"}, {"left": "Ac 3, 1", "right": "la neuvième heure"}], "answer": "Ac 2, 15 = la troisième heure ; Ac 10, 9 = la sixième heure ; Ac 3, 1 = la neuvième heure", "acceptedAnswers": [], "explanation": "Les apôtres prient à la troisième, la sixième et la neuvième heure.", "tip": "Relis la carte correspondante.", "extraExample": {"text": "Ac 2, 15", "translation": "la troisième heure"}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e13', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'match', 'lesson', 'Associe chaque notion à sa description.', '{}'::text[], 'Trois notions de la leçon.', 2, '{"id": "eg.l83.e13", "unitIds": ["eg.g83.prier_aux_heures"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque notion à sa description.", "promptLanguage": "fr", "pairs": [{"left": "Agpeya", "right": "le livre des heures"}, {"left": "Daniel", "right": "prie trois fois par jour"}, {"left": "la prière du voile", "right": "les évêques, les prêtres et les moines"}], "answer": "Agpeya = le livre des heures ; Daniel = prie trois fois par jour ; la prière du voile = les évêques, les prêtres et les moines", "acceptedAnswers": [], "explanation": "Trois notions de la leçon.", "tip": "Relis la carte correspondante.", "extraExample": {"text": "Agpeya", "translation": "le livre des heures"}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e14', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'reorder', 'lesson', 'Phrase-repère : le verset des sept heures.', array['Sept fois le jour je te loue']::text[], 'C''est le psaume 119, 164.', 2, '{"id": "eg.l83.e14", "unitIds": ["eg.g83.prier_aux_heures"], "type": "reorder", "difficulty": 2, "instruction": "Remets les mots dans l''ordre pour former la phrase-repère.", "prompt": "Phrase-repère : le verset des sept heures.", "promptLanguage": "fr", "tokens": ["loue", "te", "le", "je", "fois", "jour", "Sept"], "answer": "Sept fois le jour je te loue", "acceptedAnswers": ["Sept fois le jour je te loue"], "explanation": "C''est le psaume 119, 164.", "tip": "Sept louanges.", "extraExample": {"text": "Il ouvre l''Agpeya.", "translation": "Il fonde les sept heures."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e15', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures']::text[], 'free_answer', 'lesson', 'Quel mot copte signifie « heure » ?', array['agp','ⲁⲅⲡ']::text[], 'Agpeya vient de agp, « heure ».', 2, '{"id": "eg.l83.e15", "unitIds": ["eg.g83.prier_aux_heures"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Quel mot copte signifie « heure » ?", "promptLanguage": "fr", "answer": "agp", "acceptedAnswers": ["agp", "ⲁⲅⲡ"], "explanation": "Agpeya vient de agp, « heure ».", "tip": "agp = heure.", "extraExample": {"text": "Agpeya = agp + suffixe.", "translation": "Le livre des heures."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e16', 'eg', 'eg.l83', 'eg.g83.prier_aux_heures', array['eg.g83.prier_aux_heures','eg.v.agpeya']::text[], 'free_answer', 'lesson', 'Comment s''appelle le livre des heures copte ?', array['Agpeya','l''Agpeya']::text[], 'L''Agpeya est le livre des prières des heures.', 2, '{"id": "eg.l83.e16", "unitIds": ["eg.g83.prier_aux_heures", "eg.v.agpeya"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Comment s''appelle le livre des heures copte ?", "promptLanguage": "fr", "answer": "Agpeya", "acceptedAnswers": ["Agpeya", "l''Agpeya"], "explanation": "L''Agpeya est le livre des prières des heures.", "tip": "Retiens le nom.", "extraExample": {"text": "On dit aussi « le livre des heures ».", "translation": "Agpeya = heure."}, "errorPatterns": [{"equals": "Katameros", "category": "word_confusion", "feedback": "Le Katameros est le livre des lectures liturgiques, pas le livre des heures."}], "pool": "lesson", "lessonId": "eg.l83", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e17', 'eg', 'eg.l83', 'eg.v.pentecote', array['eg.v.pentecote']::text[], 'mcq', 'lesson', 'Quel événement a lieu à la troisième heure, le jour de la Pentecôte ?', array['l''Esprit Saint descend sur les apôtres']::text[], 'La Pentecôte, c''est la descente de l''Esprit sur les apôtres, cinquante jours après la Résurrection.', 2, '{"id": "eg.l83.e17", "unitIds": ["eg.v.pentecote"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel événement a lieu à la troisième heure, le jour de la Pentecôte ?", "promptLanguage": "fr", "options": ["Jésus monte au ciel", "les apôtres élisent un évêque", "le Christ est jugé par Pilate", "l''Esprit Saint descend sur les apôtres"], "answer": "l''Esprit Saint descend sur les apôtres", "acceptedAnswers": ["l''Esprit Saint descend sur les apôtres"], "explanation": "La Pentecôte, c''est la descente de l''Esprit sur les apôtres, cinquante jours après la Résurrection.", "tip": "Pentecôte = Esprit.", "extraExample": {"text": "Le mot grec veut dire « cinquantième ».", "translation": "Le jour où l''Église naît."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l83.e18', 'eg', 'eg.l83', 'eg.v.saint_pierre', array['eg.v.saint_pierre']::text[], 'mcq', 'lesson', 'Quel apôtre prie sur le toit à la sixième heure (Ac 10, 9) ?', array['saint Pierre']::text[], 'C''est Pierre, le chef des apôtres, qui prie sur le toit.', 2, '{"id": "eg.l83.e18", "unitIds": ["eg.v.saint_pierre"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel apôtre prie sur le toit à la sixième heure (Ac 10, 9) ?", "promptLanguage": "fr", "options": ["saint André", "saint Paul", "saint Marc", "saint Pierre"], "answer": "saint Pierre", "acceptedAnswers": ["saint Pierre"], "explanation": "C''est Pierre, le chef des apôtres, qui prie sur le toit.", "tip": "Pierre prie à midi.", "extraExample": {"text": "Il est aussi le premier à prêcher à la Pentecôte.", "translation": "Chef des apôtres."}, "pool": "lesson", "lessonId": "eg.l83", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
