insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l84.e01', 'eg', 'eg.l84', 'eg.g84.prime_tierce_sexte', array['eg.g84.prime_tierce_sexte','eg.v.prime_heure']::text[], 'mcq', 'lesson', 'À quelle heure prie-t-on Prime ?', array['6 h']::text[], 'Prime se prie vers 6 h, au lever du jour.', 1, '{"id": "eg.l84.e01", "unitIds": ["eg.g84.prime_tierce_sexte", "eg.v.prime_heure"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "À quelle heure prie-t-on Prime ?", "promptLanguage": "fr", "options": ["6 h", "midi", "9 h", "15 h"], "answer": "6 h", "acceptedAnswers": ["6 h"], "explanation": "Prime se prie vers 6 h, au lever du jour.", "tip": "Prime = première heure.", "extraExample": {"text": "Le soleil se lève vers 6 h.", "translation": "C''est le début du jour biblique."}, "pool": "lesson", "lessonId": "eg.l84", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l84.e02', 'eg', 'eg.l84', 'eg.g84.prime_tierce_sexte', array['eg.g84.prime_tierce_sexte','eg.v.tierce']::text[], 'mcq', 'lesson', 'Quelle heure se prie à 9 h ?', array['Tierce']::text[], 'Tierce est la troisième heure du jour, 9 h.', 1, '{"id": "eg.l84.e02", "unitIds": ["eg.g84.prime_tierce_sexte", "eg.v.tierce"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quelle heure se prie à 9 h ?", "promptLanguage": "fr", "options": ["Tierce", "Sexte", "Complies", "Prime"], "answer": "Tierce", "acceptedAnswers": ["Tierce"], "explanation": "Tierce est la troisième heure du jour, 9 h.", "tip": "Tierce = troisième.", "extraExample": {"text": "Troisième heure : 6 + 3 = 9 h.", "translation": "Même calcul pour Sexte."}, "pool": "lesson", "lessonId": "eg.l84", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
