insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l86.e13', 'eg', 'eg.l86', 'eg.g86.minuit_et_voile', array['eg.g86.minuit_et_voile']::text[], 'match', 'lesson', 'Révision : associe chaque heure à ce qu''elle rappelle.', '{}'::text[], 'De l''aube à la nuit : cinq scènes, cinq heures.', 3, '{"id": "eg.l86.e13", "unitIds": ["eg.g86.minuit_et_voile"], "type": "match", "difficulty": 3, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Révision : associe chaque heure à ce qu''elle rappelle.", "promptLanguage": "fr", "pairs": [{"left": "Prime", "right": "l''incarnation et la Résurrection"}, {"left": "Sexte", "right": "la crucifixion"}, {"left": "la None", "right": "la mort du Christ"}, {"left": "Vêpres", "right": "la descente de la croix"}, {"left": "Minuit", "right": "la seconde venue"}], "answer": "Prime = l''incarnation et la Résurrection ; Sexte = la crucifixion ; la None = la mort du Christ ; Vêpres = la descente de la croix ; Minuit = la seconde venue", "acceptedAnswers": [], "explanation": "De l''aube à la nuit : cinq scènes, cinq heures.", "tip": "Relis la carte correspondante.", "extraExample": {"text": "Prime", "translation": "l''incarnation et la Résurrection"}, "pool": "lesson", "lessonId": "eg.l86", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
