insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l88.e12', 'eg', 'eg.l88', 'eg.g88.prier_vers_l_est', array['eg.g88.prier_vers_l_est']::text[], 'match', 'lesson', 'Associe chaque raison à son texte ou à son témoin.', '{}'::text[], 'Quatre des six raisons.', 2, '{"id": "eg.l88.e12", "unitIds": ["eg.g88.prier_vers_l_est"], "type": "match", "difficulty": 2, "instruction": "Associe chaque élément de gauche à celui de droite.", "prompt": "Associe chaque raison à son texte ou à son témoin.", "promptLanguage": "fr", "pairs": [{"left": "le paradis perdu", "right": "Gn 2, 8"}, {"left": "la seconde venue", "right": "Mt 24, 27"}, {"left": "l''étoile des mages", "right": "Mt 2, 2"}, {"left": "le soleil de justice", "right": "Malachie"}], "answer": "le paradis perdu = Gn 2, 8 ; la seconde venue = Mt 24, 27 ; l''étoile des mages = Mt 2, 2 ; le soleil de justice = Malachie", "acceptedAnswers": [], "explanation": "Quatre des six raisons.", "tip": "Relis la carte correspondante.", "extraExample": {"text": "le paradis perdu", "translation": "Gn 2, 8"}, "pool": "lesson", "lessonId": "eg.l88", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
