insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e01', 'eg', 'eg.l95', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.calendrier_solaire']::text[], 'mcq', 'lesson', 'Sur quoi est réglé le calendrier des anciens Égyptiens ?', array['le soleil']::text[], 'Les Égyptiens ont réglé leur année sur le soleil et sur la crue du Nil : c''est un calendrier solaire.', 1, '{"id": "eg.l95.e01", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.calendrier_solaire"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Sur quoi est réglé le calendrier des anciens Égyptiens ?", "promptLanguage": "fr", "options": ["la lune", "le soleil", "les marées"], "answer": "le soleil", "acceptedAnswers": ["le soleil"], "explanation": "Les Égyptiens ont réglé leur année sur le soleil et sur la crue du Nil : c''est un calendrier solaire.", "tip": "Solaire = le soleil.", "extraExample": {"text": "Le calendrier copte est solaire.", "translation": "Il suit le soleil."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e02', 'eg', 'eg.l95', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.calendrier_solaire']::text[], 'mcq', 'lesson', 'Combien de jours compte un grand mois égyptien ?', array['30']::text[], 'Douze mois de 30 jours font 360 jours ; il reste 5 jours à ajouter.', 1, '{"id": "eg.l95.e02", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.calendrier_solaire"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de jours compte un grand mois égyptien ?", "promptLanguage": "fr", "options": ["28", "30", "31"], "answer": "30", "acceptedAnswers": ["30"], "explanation": "Douze mois de 30 jours font 360 jours ; il reste 5 jours à ajouter.", "tip": "12 × 30 = 360.", "extraExample": {"text": "Tous les grands mois ont le même nombre de jours.", "translation": "C''est facile à retenir."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e03', 'eg', 'eg.l95', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.calendrier_solaire']::text[], 'mcq', 'lesson', 'Combien de jours compte le petit mois de fin d''année ?', array['5']::text[], '12 × 30 = 360 ; le petit mois ajoute 5 jours pour arriver à 365.', 1, '{"id": "eg.l95.e03", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.calendrier_solaire"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Combien de jours compte le petit mois de fin d''année ?", "promptLanguage": "fr", "options": ["5", "10", "15"], "answer": "5", "acceptedAnswers": ["5"], "explanation": "12 × 30 = 360 ; le petit mois ajoute 5 jours pour arriver à 365.", "tip": "360 + 5 = 365.", "extraExample": {"text": "Le petit mois est tout court.", "translation": "Cinq jours seulement."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e04', 'eg', 'eg.l95', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.trois_saisons']::text[], 'mcq', 'lesson', 'Quelles sont les trois saisons de l''Égypte ancienne ?', array['la crue, la croissance, la moisson']::text[], 'Le fleuve monte (la crue), les cultures poussent (la croissance), puis on récolte (la moisson).', 2, '{"id": "eg.l95.e04", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.trois_saisons"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quelles sont les trois saisons de l''Égypte ancienne ?", "promptLanguage": "fr", "options": ["la crue, la croissance, la moisson", "le printemps, l''été, l''hiver", "le froid, le chaud, la pluie"], "answer": "la crue, la croissance, la moisson", "acceptedAnswers": ["la crue, la croissance, la moisson"], "explanation": "Le fleuve monte (la crue), les cultures poussent (la croissance), puis on récolte (la moisson).", "tip": "Le Nil, puis les champs, puis la récolte.", "extraExample": {"text": "Akhet, Peret, Shemu.", "translation": "Ce sont leurs noms égyptiens."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e05', 'eg', 'eg.l95', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.calendrier_alexandrin']::text[], 'mcq', 'lesson', 'Qui introduit à Alexandrie le sixième jour tous les quatre ans ?', array['Auguste']::text[], 'Vers 25 av. J.-C., l''empereur Auguste fait ajouter un sixième jour tous les quatre ans : c''est le calendrier alexandrin.', 2, '{"id": "eg.l95.e05", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.calendrier_alexandrin"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Qui introduit à Alexandrie le sixième jour tous les quatre ans ?", "promptLanguage": "fr", "options": ["Dioclétien", "Constantin", "Auguste"], "answer": "Auguste", "acceptedAnswers": ["Auguste"], "explanation": "Vers 25 av. J.-C., l''empereur Auguste fait ajouter un sixième jour tous les quatre ans : c''est le calendrier alexandrin.", "tip": "Auguste = jour en plus.", "extraExample": {"text": "Le calendrier alexandrin est né à Alexandrie.", "translation": "Les Coptes l''ont gardé."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e06', 'eg', 'eg.l95', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.annee_copte']::text[], 'mcq', 'lesson', 'Quel jour commence l''année copte ?', array['le 1er Tout']::text[], 'L''année copte commence le 1er Tout, le Nayrouz.', 1, '{"id": "eg.l95.e06", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.annee_copte"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "Quel jour commence l''année copte ?", "promptLanguage": "fr", "options": ["le 1er Tout", "le 1er Kiahk", "le 1er Baba"], "answer": "le 1er Tout", "acceptedAnswers": ["le 1er Tout"], "explanation": "L''année copte commence le 1er Tout, le Nayrouz.", "tip": "1er Tout = Nayrouz.", "extraExample": {"text": "Le 1er Tout est le jour de l''an.", "translation": "Il tombe en septembre."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e07', 'eg', 'eg.l95', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.annee_copte','eg.v.nayrouz']::text[], 'mcq', 'lesson', 'Vers quelle date grégorienne tombe le Nayrouz ?', array['11 septembre']::text[], 'Le Nayrouz tombe le 11 septembre, ou le 12 l''année qui précède une année bissextile grégorienne.', 2, '{"id": "eg.l95.e07", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.annee_copte", "eg.v.nayrouz"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Vers quelle date grégorienne tombe le Nayrouz ?", "promptLanguage": "fr", "options": ["1er janvier", "11 septembre", "7 janvier"], "answer": "11 septembre", "acceptedAnswers": ["11 septembre"], "explanation": "Le Nayrouz tombe le 11 septembre, ou le 12 l''année qui précède une année bissextile grégorienne.", "tip": "Septembre, vers le 11.", "extraExample": {"text": "Le Nayrouz est en septembre.", "translation": "C''est le 1er Tout."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e08', 'eg', 'eg.l95', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.ere_des_martyrs']::text[], 'mcq', 'lesson', 'En quelle année commence l''ère des martyrs ?', array['284']::text[], 'L''an 1 de l''ère des martyrs est 284, l''année de l''accession de Dioclétien. Rappel d''une leçon précédente.', 1, '{"id": "eg.l95.e08", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.ere_des_martyrs"], "type": "mcq", "difficulty": 1, "instruction": "Choisis la bonne réponse.", "prompt": "En quelle année commence l''ère des martyrs ?", "promptLanguage": "fr", "options": ["250", "284", "303", "325"], "answer": "284", "acceptedAnswers": ["284"], "explanation": "L''an 1 de l''ère des martyrs est 284, l''année de l''accession de Dioclétien. Rappel d''une leçon précédente.", "tip": "284 = an 1.", "extraExample": {"text": "L''ère des martyrs part de 284.", "translation": "Elle honore leur témoignage."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l95.e09', 'eg', 'eg.l95', 'eg.g19.diocletien_ere_des_martyrs', array['eg.g19.diocletien_ere_des_martyrs','eg.v.diocletien']::text[], 'mcq', 'lesson', 'Quel événement de 284 sert de point de départ à l''ère des martyrs ?', array['l''accession de Dioclétien']::text[], 'Les Coptes comptent depuis l''accession de Dioclétien pour garder la mémoire des martyrs, pas pour l''honorer.', 2, '{"id": "eg.l95.e09", "unitIds": ["eg.g19.diocletien_ere_des_martyrs", "eg.v.diocletien"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Quel événement de 284 sert de point de départ à l''ère des martyrs ?", "promptLanguage": "fr", "options": ["la naissance du Christ", "l''accession de Dioclétien", "le concile de Nicée"], "answer": "l''accession de Dioclétien", "acceptedAnswers": ["l''accession de Dioclétien"], "explanation": "Les Coptes comptent depuis l''accession de Dioclétien pour garder la mémoire des martyrs, pas pour l''honorer.", "tip": "284 = Dioclétien.", "extraExample": {"text": "Dioclétien devient empereur en 284.", "translation": "Sa persécution fera des milliers de martyrs."}, "pool": "lesson", "lessonId": "eg.l95", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
