insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l97.e07', 'eg', 'eg.l97', 'eg.g97.sept_derniers_mois', array['eg.g97.sept_derniers_mois','eg.v.misra','eg.v.crue_du_nil']::text[], 'mcq', 'lesson', 'Que remplit la crue du Nil en Misra ?', array['les canaux']::text[], 'En Misra, le Nil gonfle, remplit les canaux et inonde les champs.', 2, '{"id": "eg.l97.e07", "unitIds": ["eg.g97.sept_derniers_mois", "eg.v.misra", "eg.v.crue_du_nil"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que remplit la crue du Nil en Misra ?", "promptLanguage": "fr", "options": ["les canaux", "les puits", "les greniers"], "answer": "les canaux", "acceptedAnswers": ["les canaux"], "explanation": "En Misra, le Nil gonfle, remplit les canaux et inonde les champs.", "tip": "La crue remplit les canaux.", "extraExample": {"text": "Le fleuve irrigue les terres.", "translation": "C''est la crue du Nil."}, "pool": "lesson", "lessonId": "eg.l97", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l97.e08', 'eg', 'eg.l97', 'eg.g97.sept_derniers_mois', array['eg.g97.sept_derniers_mois','eg.v.bashans']::text[], 'mcq', 'lesson', 'Que veut dire le proverbe « Bashans balaie le champ » ?', array['la récolte est finie']::text[], 'En Bashans, les champs sont vidés : la moisson est terminée.', 2, '{"id": "eg.l97.e08", "unitIds": ["eg.g97.sept_derniers_mois", "eg.v.bashans"], "type": "mcq", "difficulty": 2, "instruction": "Choisis la bonne réponse.", "prompt": "Que veut dire le proverbe « Bashans balaie le champ » ?", "promptLanguage": "fr", "options": ["la récolte est finie", "le froid arrive", "le Nil monte"], "answer": "la récolte est finie", "acceptedAnswers": ["la récolte est finie"], "explanation": "En Bashans, les champs sont vidés : la moisson est terminée.", "tip": "Bashans = champs vides.", "extraExample": {"text": "Les champs sont vidés.", "translation": "C''est la fin de la moisson."}, "pool": "lesson", "lessonId": "eg.l97", "skill": "recognition"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
