insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l98.e19', 'eg', 'eg.l98', 'eg.g98.lire_une_date_copte', array['eg.g98.lire_une_date_copte','eg.v.noel_copte']::text[], 'reorder', 'lesson', 'Phrase-repère : Noël.', array['Noël copte tombe le 29 Kiahk']::text[], 'Le repère à retenir : Noël copte, c''est le 29 Kiahk.', 1, '{"id": "eg.l98.e19", "unitIds": ["eg.g98.lire_une_date_copte", "eg.v.noel_copte"], "type": "reorder", "difficulty": 1, "instruction": "Remets les mots dans l''ordre.", "prompt": "Phrase-repère : Noël.", "promptLanguage": "fr", "answer": "Noël copte tombe le 29 Kiahk", "acceptedAnswers": ["Noël copte tombe le 29 Kiahk"], "tokens": ["Kiahk", "copte", "tombe", "29", "Noël", "le"], "explanation": "Le repère à retenir : Noël copte, c''est le 29 Kiahk.", "tip": "29 Kiahk = Noël.", "extraExample": {"text": "Cela tombe vers le 7 janvier.", "translation": "Le calendrier copte suit le julien."}, "pool": "lesson", "lessonId": "eg.l98", "skill": "recall"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l98.e20', 'eg', 'eg.l98', 'eg.g95.calendrier_solaire', array['eg.g95.calendrier_solaire','eg.v.annee_copte']::text[], 'free_answer', 'lesson', 'Quelle est l''année copte en novembre 2026 ?', array['1743','an 1743','l''an 1743']::text[], 'Novembre est après le Nayrouz : 2026 − 283 = 1743.', 3, '{"id": "eg.l98.e20", "unitIds": ["eg.g95.calendrier_solaire", "eg.v.annee_copte"], "type": "free_answer", "difficulty": 3, "instruction": "Écris ta réponse.", "prompt": "Quelle est l''année copte en novembre 2026 ?", "promptLanguage": "fr", "answer": "1743", "acceptedAnswers": ["1743", "an 1743", "l''an 1743"], "explanation": "Novembre est après le Nayrouz : 2026 − 283 = 1743.", "tip": "Fin d''année : − 283.", "extraExample": {"text": "Octobre 2026 donne aussi 1743.", "translation": "Mars 2027 aussi."}, "pool": "lesson", "lessonId": "eg.l98", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l98.e21', 'eg', 'eg.l98', 'eg.g98.lire_une_date_copte', array['eg.g98.lire_une_date_copte','eg.v.nasie']::text[], 'free_answer', 'lesson', 'Quel est le treizième et dernier mois copte ?', array['Nasie','le petit mois']::text[], 'Le treizième mois est Nasie, le petit mois.', 1, '{"id": "eg.l98.e21", "unitIds": ["eg.g98.lire_une_date_copte", "eg.v.nasie"], "type": "free_answer", "difficulty": 1, "instruction": "Écris ta réponse.", "prompt": "Quel est le treizième et dernier mois copte ?", "promptLanguage": "fr", "answer": "Nasie", "acceptedAnswers": ["Nasie", "le petit mois"], "explanation": "Le treizième mois est Nasie, le petit mois.", "tip": "Nasie.", "extraExample": {"text": "Nasie compte 5 jours.", "translation": "Il précède le Nayrouz."}, "pool": "lesson", "lessonId": "eg.l98", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.exercises (id, language_id, lesson_id, learning_unit_id, unit_ids, exercise_type, pool, question, accepted_answers, explanation, difficulty, data, content_version, deprecated) values ('eg.l98.e22', 'eg', 'eg.l98', 'eg.g98.lire_une_date_copte', array['eg.g98.lire_une_date_copte','eg.v.bashans']::text[], 'free_answer', 'lesson', 'Vers le 20 mai, dans quel mois copte sommes-nous ?', array['Bashans']::text[], 'Bashans commence vers le 9 mai : le 20 mai est dans Bashans.', 2, '{"id": "eg.l98.e22", "unitIds": ["eg.g98.lire_une_date_copte", "eg.v.bashans"], "type": "free_answer", "difficulty": 2, "instruction": "Écris ta réponse.", "prompt": "Vers le 20 mai, dans quel mois copte sommes-nous ?", "promptLanguage": "fr", "answer": "Bashans", "acceptedAnswers": ["Bashans"], "explanation": "Bashans commence vers le 9 mai : le 20 mai est dans Bashans.", "tip": "Bashans : 9 mai - 7 juin.", "extraExample": {"text": "Baramouda se termine vers le 8 mai.", "translation": "Le 20 mai est dans Bashans."}, "pool": "lesson", "lessonId": "eg.l98", "skill": "production"}'::jsonb, '1.0.0', false) on conflict (id) do update set lesson_id = excluded.lesson_id, learning_unit_id = excluded.learning_unit_id, unit_ids = excluded.unit_ids, exercise_type = excluded.exercise_type, pool = excluded.pool, question = excluded.question, accepted_answers = excluded.accepted_answers, explanation = excluded.explanation, difficulty = excluded.difficulty, data = excluded.data, content_version = excluded.content_version, deprecated = excluded.deprecated;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.histoire_ecclesiastique', 'eg', 'l''histoire ecclésiastique', 'l''histoire de l''Église et du christianisme', 'C''est l''histoire de l''Église depuis les apôtres jusqu''à aujourd''hui : ses événements, ses personnes, ses conciles et ses crises.', '[{"text": "L''histoire ecclésiastique explique pourquoi l''Église copte s''est séparée de Rome et de Constantinople.", "translation": "Les événements du passé éclairent la situation d''aujourd''hui."}, {"text": "Eusèbe de Césarée, au IVe siècle, est appelé le père de l''histoire ecclésiastique.", "translation": "Il a écrit la première grande histoire de l''Église."}]'::jsonb, null, '{"id": "eg.d.histoire_ecclesiastique", "word": "l''histoire ecclésiastique", "translation": "l''histoire de l''Église et du christianisme", "partOfSpeech": "concept", "explanation": "C''est l''histoire de l''Église depuis les apôtres jusqu''à aujourd''hui : ses événements, ses personnes, ses conciles et ses crises.", "examples": [{"text": "L''histoire ecclésiastique explique pourquoi l''Église copte s''est séparée de Rome et de Constantinople.", "translation": "Les événements du passé éclairent la situation d''aujourd''hui."}, {"text": "Eusèbe de Césarée, au IVe siècle, est appelé le père de l''histoire ecclésiastique.", "translation": "Il a écrit la première grande histoire de l''Église."}], "unitId": "eg.v.histoire_ecclesiastique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dogme', 'eg', 'le dogme', 'vérité de foi définie et enseignée par l''Église', 'Un dogme est une vérité essentielle de la foi, que l''Église formule clairement, souvent après une crise ou un concile.', '[{"text": "La Trinité est un dogme de la foi chrétienne.", "translation": "Un Dieu en trois personnes : le Père, le Fils et le Saint-Esprit."}, {"text": "Le dogme de l''Incarnation affirme que le Fils de Dieu s''est fait homme.", "translation": "Il a été précisé au fil des conciles."}]'::jsonb, null, '{"id": "eg.d.dogme", "word": "le dogme", "translation": "vérité de foi définie et enseignée par l''Église", "partOfSpeech": "concept", "explanation": "Un dogme est une vérité essentielle de la foi, que l''Église formule clairement, souvent après une crise ou un concile.", "examples": [{"text": "La Trinité est un dogme de la foi chrétienne.", "translation": "Un Dieu en trois personnes : le Père, le Fils et le Saint-Esprit."}, {"text": "Le dogme de l''Incarnation affirme que le Fils de Dieu s''est fait homme.", "translation": "Il a été précisé au fil des conciles."}], "unitId": "eg.v.dogme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.heresie', 'eg', 'l''hérésie', 'enseignement qui s''écarte de la foi reçue des apôtres', 'Le mot grec signifie « choix » : l''hérétique choisit une partie de la doctrine à sa façon. L''Église répond à une hérésie en précisant sa foi.', '[{"text": "Le gnosticisme est une hérésie du premier siècle.", "translation": "Il nie que Jésus se soit vraiment fait homme."}, {"text": "Arius a enseigné une hérésie au IVe siècle.", "translation": "Le concile de Nicée lui a répondu en 325."}]'::jsonb, null, '{"id": "eg.d.heresie", "word": "l''hérésie", "translation": "enseignement qui s''écarte de la foi reçue des apôtres", "partOfSpeech": "concept", "explanation": "Le mot grec signifie « choix » : l''hérétique choisit une partie de la doctrine à sa façon. L''Église répond à une hérésie en précisant sa foi.", "examples": [{"text": "Le gnosticisme est une hérésie du premier siècle.", "translation": "Il nie que Jésus se soit vraiment fait homme."}, {"text": "Arius a enseigné une hérésie au IVe siècle.", "translation": "Le concile de Nicée lui a répondu en 325."}], "unitId": "eg.v.heresie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.schisme', 'eg', 'le schisme', 'rupture de communion entre des Églises', 'Le schisme touche l''unité de l''Église : deux Églises cessent d''être en communion. Il peut venir d''une hérésie, mais aussi de conflits de pouvoir ou de langue.', '[{"text": "Le schisme de 1054 sépare l''Église de Rome et celle de Constantinople.", "translation": "Chacune cesse de reconnaître l''autre."}, {"text": "Après 451, les Églises coptes et les Églises de l''Empire sont séparées.", "translation": "On expliquera plus tard pourquoi et comment."}]'::jsonb, null, '{"id": "eg.d.schisme", "word": "le schisme", "translation": "rupture de communion entre des Églises", "partOfSpeech": "concept", "explanation": "Le schisme touche l''unité de l''Église : deux Églises cessent d''être en communion. Il peut venir d''une hérésie, mais aussi de conflits de pouvoir ou de langue.", "examples": [{"text": "Le schisme de 1054 sépare l''Église de Rome et celle de Constantinople.", "translation": "Chacune cesse de reconnaître l''autre."}, {"text": "Après 451, les Églises coptes et les Églises de l''Empire sont séparées.", "translation": "On expliquera plus tard pourquoi et comment."}], "unitId": "eg.v.schisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.empire_romain', 'eg', 'l''Empire romain', 'puissance qui domine le monde connu au temps de Jésus', 'Au Ier siècle, Rome contrôle toute la Méditerranée, dont la Judée et l''Égypte. Ses routes et sa paix favorisent les voyages, mais ses empereurs persécutent parfois les chrétiens.', '[{"text": "Jérusalem est occupée par les Romains au temps de Jésus.", "translation": "Ponce Pilate y représente l''empereur."}, {"text": "Alexandrie est un grand port de l''Empire romain.", "translation": "Les bateaux y apportent le blé d''Égypte vers Rome."}]'::jsonb, null, '{"id": "eg.d.empire_romain", "word": "l''Empire romain", "translation": "puissance qui domine le monde connu au temps de Jésus", "partOfSpeech": "organization", "explanation": "Au Ier siècle, Rome contrôle toute la Méditerranée, dont la Judée et l''Égypte. Ses routes et sa paix favorisent les voyages, mais ses empereurs persécutent parfois les chrétiens.", "examples": [{"text": "Jérusalem est occupée par les Romains au temps de Jésus.", "translation": "Ponce Pilate y représente l''empereur."}, {"text": "Alexandrie est un grand port de l''Empire romain.", "translation": "Les bateaux y apportent le blé d''Égypte vers Rome."}], "unitId": "eg.v.empire_romain"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ere_chretienne', 'eg', 'l''ère chrétienne', 'calendrier qui compte les années depuis la naissance de Jésus-Christ', 'On dit « avant J.-C. » ou « après J.-C. ». Le monde entier utilise ce repère, preuve que la venue du Christ a partagé l''histoire en deux.', '[{"text": "La naissance de Jésus se situe vers l''an 4 avant J.-C.", "translation": "Le monde compte alors les années à partir de cette naissance, avec une erreur de quelques années."}, {"text": "En 2026 après J.-C., l''ère chrétienne compte plus de deux mille ans.", "translation": "Chaque date que tu écris rappelle le Christ."}]'::jsonb, null, '{"id": "eg.d.ere_chretienne", "word": "l''ère chrétienne", "translation": "calendrier qui compte les années depuis la naissance de Jésus-Christ", "partOfSpeech": "concept", "explanation": "On dit « avant J.-C. » ou « après J.-C. ». Le monde entier utilise ce repère, preuve que la venue du Christ a partagé l''histoire en deux.", "examples": [{"text": "La naissance de Jésus se situe vers l''an 4 avant J.-C.", "translation": "Le monde compte alors les années à partir de cette naissance, avec une erreur de quelques années."}, {"text": "En 2026 après J.-C., l''ère chrétienne compte plus de deux mille ans.", "translation": "Chaque date que tu écris rappelle le Christ."}], "unitId": "eg.v.ere_chretienne"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jesus_christ', 'eg', 'Jésus-Christ', 'Jésus de Nazareth, le Christ, Fils de Dieu fait homme', '« Christ » vient du grec Christos, « oint », qui traduit l''hébreu Messie. Les chrétiens croient qu''il est Dieu fait homme, mort et ressuscité pour nous sauver.', '[{"text": "Jésus-Christ est né à Bethléem, vers l''an 4 avant J.-C.", "translation": "Sa naissance sert de repère au calendrier."}, {"text": "Il est crucifié sous Ponce Pilate, au début des années 30.", "translation": "Il ressuscite le troisième jour."}]'::jsonb, null, '{"id": "eg.d.jesus_christ", "word": "Jésus-Christ", "translation": "Jésus de Nazareth, le Christ, Fils de Dieu fait homme", "partOfSpeech": "person", "explanation": "« Christ » vient du grec Christos, « oint », qui traduit l''hébreu Messie. Les chrétiens croient qu''il est Dieu fait homme, mort et ressuscité pour nous sauver.", "examples": [{"text": "Jésus-Christ est né à Bethléem, vers l''an 4 avant J.-C.", "translation": "Sa naissance sert de repère au calendrier."}, {"text": "Il est crucifié sous Ponce Pilate, au début des années 30.", "translation": "Il ressuscite le troisième jour."}], "unitId": "eg.v.jesus_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jerusalem', 'eg', 'Jérusalem', 'ville sainte où Jésus est crucifié et où naît l''Église', 'Capitale religieuse des Juifs, occupée par les Romains. C''est là que se passent la Passion, la Résurrection et la Pentecôte.', '[{"text": "Les apôtres regagnent Jérusalem après l''Ascension.", "translation": "La ville est le berceau de l''Église."}, {"text": "Jérusalem tombera en l''an 70 devant les armées de Titus.", "translation": "Le Temple sera détruit."}]'::jsonb, null, '{"id": "eg.d.jerusalem", "word": "Jérusalem", "translation": "ville sainte où Jésus est crucifié et où naît l''Église", "partOfSpeech": "place", "explanation": "Capitale religieuse des Juifs, occupée par les Romains. C''est là que se passent la Passion, la Résurrection et la Pentecôte.", "examples": [{"text": "Les apôtres regagnent Jérusalem après l''Ascension.", "translation": "La ville est le berceau de l''Église."}, {"text": "Jérusalem tombera en l''an 70 devant les armées de Titus.", "translation": "Le Temple sera détruit."}], "unitId": "eg.v.jerusalem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ponce_pilate', 'eg', 'Ponce Pilate', 'gouverneur romain de Judée qui condamne Jésus', 'Pilate représente l''empereur en Judée. Il livre Jésus à la crucifixion, vers l''an 30. Son nom reste dans le Credo : « crucifié sous Ponce Pilate ».', '[{"text": "Jésus est crucifié sous Ponce Pilate.", "translation": "Le Credo fixe ainsi l''événement dans l''histoire."}, {"text": "Ponce Pilate gouverne la Judée pour Rome.", "translation": "Il est le représentant de l''Empire romain."}]'::jsonb, null, '{"id": "eg.d.ponce_pilate", "word": "Ponce Pilate", "translation": "gouverneur romain de Judée qui condamne Jésus", "partOfSpeech": "person", "explanation": "Pilate représente l''empereur en Judée. Il livre Jésus à la crucifixion, vers l''an 30. Son nom reste dans le Credo : « crucifié sous Ponce Pilate ».", "examples": [{"text": "Jésus est crucifié sous Ponce Pilate.", "translation": "Le Credo fixe ainsi l''événement dans l''histoire."}, {"text": "Ponce Pilate gouverne la Judée pour Rome.", "translation": "Il est le représentant de l''Empire romain."}], "unitId": "eg.v.ponce_pilate"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apotre', 'eg', 'l''apôtre', '« envoyé » : disciple choisi par Jésus et envoyé en mission', 'Le mot grec apostolos signifie « envoyé ». Jésus choisit douze apôtres, puis les envoie annoncer l''Évangile à toutes les nations.', '[{"text": "Pierre est le premier des douze apôtres.", "translation": "Il prêche le jour de la Pentecôte."}, {"text": "Paul se dit apôtre bien qu''il ne fasse pas partie des Douze.", "translation": "Il est envoyé par le Christ aux nations."}]'::jsonb, null, '{"id": "eg.d.apotre", "word": "l''apôtre", "translation": "« envoyé » : disciple choisi par Jésus et envoyé en mission", "partOfSpeech": "concept", "explanation": "Le mot grec apostolos signifie « envoyé ». Jésus choisit douze apôtres, puis les envoie annoncer l''Évangile à toutes les nations.", "examples": [{"text": "Pierre est le premier des douze apôtres.", "translation": "Il prêche le jour de la Pentecôte."}, {"text": "Paul se dit apôtre bien qu''il ne fasse pas partie des Douze.", "translation": "Il est envoyé par le Christ aux nations."}], "unitId": "eg.v.apotre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ascension', 'eg', 'l''Ascension', 'Jésus monte au ciel quarante jours après la Résurrection', 'Jésus ressuscité se montre à ses disciples, puis monte au ciel. Les apôtres, d''abord tristes, reviennent à Jérusalem remplis de joie et attendent l''Esprit.', '[{"text": "L''Ascension a lieu sur le mont des Oliviers.", "translation": "Les apôtres retournent ensuite à Jérusalem."}, {"text": "Entre l''Ascension et la Pentecôte, les apôtres prient ensemble.", "translation": "Ils attendent la promesse du Saint-Esprit."}]'::jsonb, null, '{"id": "eg.d.ascension", "word": "l''Ascension", "translation": "Jésus monte au ciel quarante jours après la Résurrection", "partOfSpeech": "event", "explanation": "Jésus ressuscité se montre à ses disciples, puis monte au ciel. Les apôtres, d''abord tristes, reviennent à Jérusalem remplis de joie et attendent l''Esprit.", "examples": [{"text": "L''Ascension a lieu sur le mont des Oliviers.", "translation": "Les apôtres retournent ensuite à Jérusalem."}, {"text": "Entre l''Ascension et la Pentecôte, les apôtres prient ensemble.", "translation": "Ils attendent la promesse du Saint-Esprit."}], "unitId": "eg.v.ascension"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chambre_haute', 'eg', 'la chambre haute', 'salle de l''étage où les apôtres se retrouvent à Jérusalem', 'C''est le lieu de prière du petit groupe après l''Ascension. La tradition copte l''associe à la maison de la mère de saint Marc à Jérusalem.', '[{"text": "Pierre, Jean, Jacques et André montent dans la chambre haute.", "translation": "Marie, mère de Jésus, y prie avec eux."}, {"text": "La chambre haute accueille environ cent vingt personnes.", "translation": "Ils y attendent l''Esprit Saint."}]'::jsonb, null, '{"id": "eg.d.chambre_haute", "word": "la chambre haute", "translation": "salle de l''étage où les apôtres se retrouvent à Jérusalem", "partOfSpeech": "place", "explanation": "C''est le lieu de prière du petit groupe après l''Ascension. La tradition copte l''associe à la maison de la mère de saint Marc à Jérusalem.", "examples": [{"text": "Pierre, Jean, Jacques et André montent dans la chambre haute.", "translation": "Marie, mère de Jésus, y prie avec eux."}, {"text": "La chambre haute accueille environ cent vingt personnes.", "translation": "Ils y attendent l''Esprit Saint."}], "unitId": "eg.v.chambre_haute"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pentecote', 'eg', 'la Pentecôte', 'cinquante jours après la Résurrection : l''Esprit Saint descend et l''Église naît', 'Le mot grec veut dire « cinquantième ». Ce jour-là, l''Esprit descend sur les apôtres, Pierre prêche, trois mille personnes se convertissent : la tradition place là les débuts de l''Église.', '[{"text": "À la Pentecôte, Pierre prêche pour la première fois en public.", "translation": "Trois mille personnes se convertissent."}, {"text": "La Pentecôte est appelée l''anniversaire de l''Église.", "translation": "L''Église copte la célèbre cinquante jours après Pâques."}]'::jsonb, null, '{"id": "eg.d.pentecote", "word": "la Pentecôte", "translation": "cinquante jours après la Résurrection : l''Esprit Saint descend et l''Église naît", "partOfSpeech": "event", "explanation": "Le mot grec veut dire « cinquantième ». Ce jour-là, l''Esprit descend sur les apôtres, Pierre prêche, trois mille personnes se convertissent : la tradition place là les débuts de l''Église.", "examples": [{"text": "À la Pentecôte, Pierre prêche pour la première fois en public.", "translation": "Trois mille personnes se convertissent."}, {"text": "La Pentecôte est appelée l''anniversaire de l''Église.", "translation": "L''Église copte la célèbre cinquante jours après Pâques."}], "unitId": "eg.v.pentecote"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_pierre', 'eg', 'saint Pierre', 'chef des apôtres, premier à prêcher le jour de la Pentecôte', 'Pêcheur de Galilée, Simon reçoit de Jésus le nom de Pierre. Après la Résurrection, il est le porte-parole des apôtres.', '[{"text": "Pierre prêche à Jérusalem le jour de la Pentecôte.", "translation": "Trois mille personnes reçoivent l''Évangile."}, {"text": "Pierre sera martyrisé à Rome vers l''an 67.", "translation": "Il meurt pour sa foi comme son maître."}]'::jsonb, null, '{"id": "eg.d.saint_pierre", "word": "saint Pierre", "translation": "chef des apôtres, premier à prêcher le jour de la Pentecôte", "partOfSpeech": "person", "explanation": "Pêcheur de Galilée, Simon reçoit de Jésus le nom de Pierre. Après la Résurrection, il est le porte-parole des apôtres.", "examples": [{"text": "Pierre prêche à Jérusalem le jour de la Pentecôte.", "translation": "Trois mille personnes reçoivent l''Évangile."}, {"text": "Pierre sera martyrisé à Rome vers l''an 67.", "translation": "Il meurt pour sa foi comme son maître."}], "unitId": "eg.v.saint_pierre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.premiere_communaute', 'eg', 'la première communauté', 'premier groupe de croyants de Jérusalem, qui met tout en commun', 'Luc la décrit dans les Actes (chapitre 2) : une communauté priante, unie, où l''on partage les biens. Elle sert de modèle à l''Église.', '[{"text": "Dans la première communauté, personne ne manque du nécessaire.", "translation": "Les croyants mettent leurs biens en commun."}, {"text": "La première communauté se réunit pour prier et rompre le pain.", "translation": "Elle compte environ cinq mille personnes."}]'::jsonb, null, '{"id": "eg.d.premiere_communaute", "word": "la première communauté", "translation": "premier groupe de croyants de Jérusalem, qui met tout en commun", "partOfSpeech": "concept", "explanation": "Luc la décrit dans les Actes (chapitre 2) : une communauté priante, unie, où l''on partage les biens. Elle sert de modèle à l''Église.", "examples": [{"text": "Dans la première communauté, personne ne manque du nécessaire.", "translation": "Les croyants mettent leurs biens en commun."}, {"text": "La première communauté se réunit pour prier et rompre le pain.", "translation": "Elle compte environ cinq mille personnes."}], "unitId": "eg.v.premiere_communaute"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.fraction_du_pain', 'eg', 'la fraction du pain', 'nom donné par les premiers chrétiens au repas eucharistique', 'Rompre le pain, c''est le geste de Jésus à la dernière Cène. Les premiers chrétiens désignent ainsi leur célébration de l''eucharistie.', '[{"text": "Les croyants sont assidus à la fraction du pain.", "translation": "C''est l''ancêtre de notre messe."}, {"text": "Les disciples d''Emmaüs reconnaissent Jésus à la fraction du pain.", "translation": "Le geste est resté au cœur de la messe."}]'::jsonb, null, '{"id": "eg.d.fraction_du_pain", "word": "la fraction du pain", "translation": "nom donné par les premiers chrétiens au repas eucharistique", "partOfSpeech": "concept", "explanation": "Rompre le pain, c''est le geste de Jésus à la dernière Cène. Les premiers chrétiens désignent ainsi leur célébration de l''eucharistie.", "examples": [{"text": "Les croyants sont assidus à la fraction du pain.", "translation": "C''est l''ancêtre de notre messe."}, {"text": "Les disciples d''Emmaüs reconnaissent Jésus à la fraction du pain.", "translation": "Le geste est resté au cœur de la messe."}], "unitId": "eg.v.fraction_du_pain"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.helleniste', 'eg', 'les hellénistes', 'chrétiens de langue grecque de la première communauté', 'Ce sont des Juifs de la diaspora, venus de pays grecs, devenus chrétiens. Face aux « Hébreux », ils sont parfois moins bien servis, d''où le premier conflit interne (Ac 6).', '[{"text": "Les hellénistes se plaignent que leurs veuves soient oubliées.", "translation": "Les apôtres choisissent sept hommes pour le service."}, {"text": "Étienne fait partie des sept choisis pour servir les hellénistes.", "translation": "Il porte un nom grec, comme eux."}]'::jsonb, null, '{"id": "eg.d.helleniste", "word": "les hellénistes", "translation": "chrétiens de langue grecque de la première communauté", "partOfSpeech": "concept", "explanation": "Ce sont des Juifs de la diaspora, venus de pays grecs, devenus chrétiens. Face aux « Hébreux », ils sont parfois moins bien servis, d''où le premier conflit interne (Ac 6).", "examples": [{"text": "Les hellénistes se plaignent que leurs veuves soient oubliées.", "translation": "Les apôtres choisissent sept hommes pour le service."}, {"text": "Étienne fait partie des sept choisis pour servir les hellénistes.", "translation": "Il porte un nom grec, comme eux."}], "unitId": "eg.v.helleniste"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_etienne', 'eg', 'saint Étienne', 'premier martyr chrétien, lapidé vers 35', 'L''un des sept hommes choisis pour le service. Il témoigne devant les autorités et meurt lapidé. L''Église le fête comme premier martyr (« couronne » en grec).', '[{"text": "Étienne est lapidé à Jérusalem.", "translation": "Il prie pour ceux qui le tuent."}, {"text": "Saul approuve la mort d''Étienne.", "translation": "Quelques années plus tard, il deviendra Paul."}]'::jsonb, null, '{"id": "eg.d.saint_etienne", "word": "saint Étienne", "translation": "premier martyr chrétien, lapidé vers 35", "partOfSpeech": "person", "explanation": "L''un des sept hommes choisis pour le service. Il témoigne devant les autorités et meurt lapidé. L''Église le fête comme premier martyr (« couronne » en grec).", "examples": [{"text": "Étienne est lapidé à Jérusalem.", "translation": "Il prie pour ceux qui le tuent."}, {"text": "Saul approuve la mort d''Étienne.", "translation": "Quelques années plus tard, il deviendra Paul."}], "unitId": "eg.v.saint_etienne"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.martyr', 'eg', 'le martyr', 'chrétien qui meurt pour témoigner de sa foi (du grec « témoin »)', 'Le martyr ne cherche pas la mort : il refuse de renier le Christ. L''Église copte vénère des milliers de martyrs, on y reviendra beaucoup.', '[{"text": "Étienne est le premier martyr de l''Église.", "translation": "Son nom grec veut dire « couronne »."}, {"text": "Marc sera martyr à Alexandrie vers 68.", "translation": "Il est mort pour son témoignage."}]'::jsonb, null, '{"id": "eg.d.martyr", "word": "le martyr", "translation": "chrétien qui meurt pour témoigner de sa foi (du grec « témoin »)", "partOfSpeech": "concept", "explanation": "Le martyr ne cherche pas la mort : il refuse de renier le Christ. L''Église copte vénère des milliers de martyrs, on y reviendra beaucoup.", "examples": [{"text": "Étienne est le premier martyr de l''Église.", "translation": "Son nom grec veut dire « couronne »."}, {"text": "Marc sera martyr à Alexandrie vers 68.", "translation": "Il est mort pour son témoignage."}], "unitId": "eg.v.martyr"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_paul', 'eg', 'saint Paul', 'pharisien devenu apôtre des nations, auteur de nombreuses épîtres', 'Juif de Tarse, citoyen romain, pharisien, il persécute l''Église avant de rencontrer le Christ vers 35. Il fonde des communautés dans l''Empire romain.', '[{"text": "Saul devient Paul sur la route de Damas.", "translation": "Il annonce le Christ aux païens."}, {"text": "Paul est martyrisé à Rome vers 67.", "translation": "Il est décapité, car citoyen romain."}]'::jsonb, null, '{"id": "eg.d.saint_paul", "word": "saint Paul", "translation": "pharisien devenu apôtre des nations, auteur de nombreuses épîtres", "partOfSpeech": "person", "explanation": "Juif de Tarse, citoyen romain, pharisien, il persécute l''Église avant de rencontrer le Christ vers 35. Il fonde des communautés dans l''Empire romain.", "examples": [{"text": "Saul devient Paul sur la route de Damas.", "translation": "Il annonce le Christ aux païens."}, {"text": "Paul est martyrisé à Rome vers 67.", "translation": "Il est décapité, car citoyen romain."}], "unitId": "eg.v.saint_paul"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.barnabe', 'eg', 'saint Barnabé', 'compagnon de Paul dans sa première mission', 'Juif de Chypre, il accueille Paul à Jérusalem après sa conversion. Il est cousin de Marc et l''accompagne dans plusieurs voyages.', '[{"text": "Barnabé voyage avec Paul.", "translation": "Ils se rendent d''abord dans les synagogues."}, {"text": "Barnabé est le cousin de saint Marc.", "translation": "Marc les suit lors de la première mission."}]'::jsonb, null, '{"id": "eg.d.barnabe", "word": "saint Barnabé", "translation": "compagnon de Paul dans sa première mission", "partOfSpeech": "person", "explanation": "Juif de Chypre, il accueille Paul à Jérusalem après sa conversion. Il est cousin de Marc et l''accompagne dans plusieurs voyages.", "examples": [{"text": "Barnabé voyage avec Paul.", "translation": "Ils se rendent d''abord dans les synagogues."}, {"text": "Barnabé est le cousin de saint Marc.", "translation": "Marc les suit lors de la première mission."}], "unitId": "eg.v.barnabe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.synagogue', 'eg', 'la synagogue', 'lieu de prière et d''enseignement des Juifs dans chaque ville', 'Dans chaque ville de l''Empire il y a une synagogue : Paul y annonce d''abord l''Évangile, car les Juifs connaissent déjà les Écritures.', '[{"text": "Paul entre dans la synagogue le jour du sabbat.", "translation": "Il explique que le Christ est annoncé par les Écritures."}, {"text": "Beaucoup de synagogues le rejettent.", "translation": "Il se tourne alors vers les païens."}]'::jsonb, null, '{"id": "eg.d.synagogue", "word": "la synagogue", "translation": "lieu de prière et d''enseignement des Juifs dans chaque ville", "partOfSpeech": "place", "explanation": "Dans chaque ville de l''Empire il y a une synagogue : Paul y annonce d''abord l''Évangile, car les Juifs connaissent déjà les Écritures.", "examples": [{"text": "Paul entre dans la synagogue le jour du sabbat.", "translation": "Il explique que le Christ est annoncé par les Écritures."}, {"text": "Beaucoup de synagogues le rejettent.", "translation": "Il se tourne alors vers les païens."}], "unitId": "eg.v.synagogue"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.paiens', 'eg', 'les païens', 'les non-juifs, qui ne connaissent pas le Dieu d''Israël', 'Pour les Juifs, les « nations » sont les non-juifs. L''annonce aux païens est le grand tournant de la mission : ils deviennent chrétiens sans passer par le judaïsme.', '[{"text": "Paul annonce l''Évangile aux païens.", "translation": "Ils l''accueillent avec joie."}, {"text": "Les païens convertis ne sont pas circoncis.", "translation": "Cela posera la question du concile de Jérusalem."}]'::jsonb, null, '{"id": "eg.d.paiens", "word": "les païens", "translation": "les non-juifs, qui ne connaissent pas le Dieu d''Israël", "partOfSpeech": "concept", "explanation": "Pour les Juifs, les « nations » sont les non-juifs. L''annonce aux païens est le grand tournant de la mission : ils deviennent chrétiens sans passer par le judaïsme.", "examples": [{"text": "Paul annonce l''Évangile aux païens.", "translation": "Ils l''accueillent avec joie."}, {"text": "Les païens convertis ne sont pas circoncis.", "translation": "Cela posera la question du concile de Jérusalem."}], "unitId": "eg.v.paiens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.antioche', 'eg', 'Antioche', 'grande ville de Syrie où les disciples sont appelés « chrétiens »', 'Troisième ville de l''Empire, mélange de Juifs et de païens. Les disciples y sont appelés chrétiens pour la première fois ; c''est la base des voyages de Paul.', '[{"text": "À Antioche, les disciples reçoivent le nom de chrétiens.", "translation": "Paul et Barnabé y reviennent après leur mission."}, {"text": "Un conflit sur la circoncision éclate à Antioche.", "translation": "Il sera réglé à Jérusalem."}]'::jsonb, null, '{"id": "eg.d.antioche", "word": "Antioche", "translation": "grande ville de Syrie où les disciples sont appelés « chrétiens »", "partOfSpeech": "place", "explanation": "Troisième ville de l''Empire, mélange de Juifs et de païens. Les disciples y sont appelés chrétiens pour la première fois ; c''est la base des voyages de Paul.", "examples": [{"text": "À Antioche, les disciples reçoivent le nom de chrétiens.", "translation": "Paul et Barnabé y reviennent après leur mission."}, {"text": "Un conflit sur la circoncision éclate à Antioche.", "translation": "Il sera réglé à Jérusalem."}], "unitId": "eg.v.antioche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chretiens', 'eg', 'les chrétiens', 'disciples du Christ, nom reçu à Antioche', 'Le mot vient du grec Christianoi, « partisans du Christ ». Ce nom a d''abord été donné de l''extérieur avant d''être adopté.', '[{"text": "Les disciples sont appelés chrétiens à Antioche.", "translation": "Ce nom vient de « Christ »."}, {"text": "Les premiers chrétiens sont des Juifs.", "translation": "Peu à peu les païens deviennent majoritaires."}]'::jsonb, null, '{"id": "eg.d.chretiens", "word": "les chrétiens", "translation": "disciples du Christ, nom reçu à Antioche", "partOfSpeech": "concept", "explanation": "Le mot vient du grec Christianoi, « partisans du Christ ». Ce nom a d''abord été donné de l''extérieur avant d''être adopté.", "examples": [{"text": "Les disciples sont appelés chrétiens à Antioche.", "translation": "Ce nom vient de « Christ »."}, {"text": "Les premiers chrétiens sont des Juifs.", "translation": "Peu à peu les païens deviennent majoritaires."}], "unitId": "eg.v.chretiens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile', 'eg', 'le concile', 'assemblée de responsables de l''Église qui décident ensemble', 'Du latin concilium, « assemblée ». Les évêques (et, au début, les apôtres) se réunissent pour trancher une question de foi ou de discipline. Il y aura de grands conciles : Nicée, Constantinople, Éphèse.', '[{"text": "Le concile de Jérusalem est le premier de l''histoire.", "translation": "Les apôtres et les anciens y décident ensemble."}, {"text": "Le concile de Nicée, en 325, répond à Arius.", "translation": "Il fixe la foi en un Credo."}]'::jsonb, null, '{"id": "eg.d.concile", "word": "le concile", "translation": "assemblée de responsables de l''Église qui décident ensemble", "partOfSpeech": "concept", "explanation": "Du latin concilium, « assemblée ». Les évêques (et, au début, les apôtres) se réunissent pour trancher une question de foi ou de discipline. Il y aura de grands conciles : Nicée, Constantinople, Éphèse.", "examples": [{"text": "Le concile de Jérusalem est le premier de l''histoire.", "translation": "Les apôtres et les anciens y décident ensemble."}, {"text": "Le concile de Nicée, en 325, répond à Arius.", "translation": "Il fixe la foi en un Credo."}], "unitId": "eg.v.concile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.circoncision', 'eg', 'la circoncision', 'signe de l''alliance de Dieu avec Abraham, exigé par la Loi de Moïse', 'Pour les Juifs, c''est la marque d''appartenance au peuple de Dieu. Les chrétiens venus du paganisme n''en ont pas besoin : le baptême remplace ce signe.', '[{"text": "Les judaïsants exigent la circoncision des païens convertis.", "translation": "Paul s''y oppose."}, {"text": "Jésus a été circoncis le huitième jour.", "translation": "Il accomplit la Loi."}]'::jsonb, null, '{"id": "eg.d.circoncision", "word": "la circoncision", "translation": "signe de l''alliance de Dieu avec Abraham, exigé par la Loi de Moïse", "partOfSpeech": "concept", "explanation": "Pour les Juifs, c''est la marque d''appartenance au peuple de Dieu. Les chrétiens venus du paganisme n''en ont pas besoin : le baptême remplace ce signe.", "examples": [{"text": "Les judaïsants exigent la circoncision des païens convertis.", "translation": "Paul s''y oppose."}, {"text": "Jésus a été circoncis le huitième jour.", "translation": "Il accomplit la Loi."}], "unitId": "eg.v.circoncision"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.judaisants', 'eg', 'les judaïsants', 'chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens', 'Souvent d''anciens pharisiens, ils ont peur de perdre l''identité juive. Leur erreur : faire dépendre le salut de la Loi plutôt que du Christ.', '[{"text": "Les judaïsants arrivent à Antioche.", "translation": "Ils disent qu''il faut être circoncis pour être sauvé."}, {"text": "Paul répond aux judaïsants dans l''épître aux Galates.", "translation": "Le salut est un don du Christ."}]'::jsonb, null, '{"id": "eg.d.judaisants", "word": "les judaïsants", "translation": "chrétiens d''origine juive qui veulent imposer la Loi de Moïse aux païens", "partOfSpeech": "concept", "explanation": "Souvent d''anciens pharisiens, ils ont peur de perdre l''identité juive. Leur erreur : faire dépendre le salut de la Loi plutôt que du Christ.", "examples": [{"text": "Les judaïsants arrivent à Antioche.", "translation": "Ils disent qu''il faut être circoncis pour être sauvé."}, {"text": "Paul répond aux judaïsants dans l''épître aux Galates.", "translation": "Le salut est un don du Christ."}], "unitId": "eg.v.judaisants"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.loi_de_moise', 'eg', 'la Loi de Moïse', 'ensemble des commandements donnés par Dieu à Israël, dont la circoncision', 'Elle contient les dix commandements mais aussi des règles sur la circoncision, le sabbat et les aliments. Le Christ l''accomplit, sans l''imposer aux païens.', '[{"text": "La circoncision fait partie de la Loi de Moïse.", "translation": "Le concile ne l''impose pas aux païens."}, {"text": "Les judaïsants défendent la Loi de Moïse.", "translation": "Ils craignent que le christianisme s''en éloigne."}]'::jsonb, null, '{"id": "eg.d.loi_de_moise", "word": "la Loi de Moïse", "translation": "ensemble des commandements donnés par Dieu à Israël, dont la circoncision", "partOfSpeech": "concept", "explanation": "Elle contient les dix commandements mais aussi des règles sur la circoncision, le sabbat et les aliments. Le Christ l''accomplit, sans l''imposer aux païens.", "examples": [{"text": "La circoncision fait partie de la Loi de Moïse.", "translation": "Le concile ne l''impose pas aux païens."}, {"text": "Les judaïsants défendent la Loi de Moïse.", "translation": "Ils craignent que le christianisme s''en éloigne."}], "unitId": "eg.v.loi_de_moise"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.salut', 'eg', 'le salut', 'libération du péché et de la mort offerte par le Christ', 'Pour un chrétien, le salut est un don de Dieu par le Christ, accueilli dans la foi et le baptême. Il ne s''achète pas par des rites.', '[{"text": "Le salut est offert à tous, juifs et païens.", "translation": "C''est le message de Paul."}, {"text": "Les judaïsants lient le salut à la circoncision.", "translation": "Le concile refuse cette idée."}]'::jsonb, null, '{"id": "eg.d.salut", "word": "le salut", "translation": "libération du péché et de la mort offerte par le Christ", "partOfSpeech": "concept", "explanation": "Pour un chrétien, le salut est un don de Dieu par le Christ, accueilli dans la foi et le baptême. Il ne s''achète pas par des rites.", "examples": [{"text": "Le salut est offert à tous, juifs et païens.", "translation": "C''est le message de Paul."}, {"text": "Les judaïsants lient le salut à la circoncision.", "translation": "Le concile refuse cette idée."}], "unitId": "eg.v.salut"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_de_jerusalem', 'eg', 'le concile de Jérusalem', 'premier concile de l''histoire chrétienne, vers 49', 'Il se tient vers l''an 49 pour régler le conflit d''Antioche. Il décide que la circoncision n''est plus obligatoire pour les païens convertis.', '[{"text": "Paul et Barnabé montent à Jérusalem pour le concile.", "translation": "Les apôtres et les anciens se réunissent."}, {"text": "Le concile envoie une lettre aux Églises d''Antioche.", "translation": "Elle annonce la décision."}]'::jsonb, null, '{"id": "eg.d.concile_de_jerusalem", "word": "le concile de Jérusalem", "translation": "premier concile de l''histoire chrétienne, vers 49", "partOfSpeech": "event", "explanation": "Il se tient vers l''an 49 pour régler le conflit d''Antioche. Il décide que la circoncision n''est plus obligatoire pour les païens convertis.", "examples": [{"text": "Paul et Barnabé montent à Jérusalem pour le concile.", "translation": "Les apôtres et les anciens se réunissent."}, {"text": "Le concile envoie une lettre aux Églises d''Antioche.", "translation": "Elle annonce la décision."}], "unitId": "eg.v.concile_de_jerusalem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jacques_de_jerusalem', 'eg', 'saint Jacques de Jérusalem', 'chef de l''Église de Jérusalem, martyrisé en 62', 'Il dirige la communauté de Jérusalem. Il conclut le débat du concile et sera martyrisé en 62. Il ne faut pas le confondre avec Jacques, frère de Jean, décapité vers 44.', '[{"text": "Jacques conclut le concile de Jérusalem.", "translation": "Il s''appuie sur les prophètes."}, {"text": "Jacques est martyrisé à Jérusalem en 62.", "translation": "Il est le chef de l''Église de Jérusalem."}]'::jsonb, null, '{"id": "eg.d.jacques_de_jerusalem", "word": "saint Jacques de Jérusalem", "translation": "chef de l''Église de Jérusalem, martyrisé en 62", "partOfSpeech": "person", "explanation": "Il dirige la communauté de Jérusalem. Il conclut le débat du concile et sera martyrisé en 62. Il ne faut pas le confondre avec Jacques, frère de Jean, décapité vers 44.", "examples": [{"text": "Jacques conclut le concile de Jérusalem.", "translation": "Il s''appuie sur les prophètes."}, {"text": "Jacques est martyrisé à Jérusalem en 62.", "translation": "Il est le chef de l''Église de Jérusalem."}], "unitId": "eg.v.jacques_de_jerusalem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.herode_agrippa', 'eg', 'Hérode Agrippa', 'roi des Juifs qui fait décapiter Jacques vers 44', 'Petit-fils d''Hérode le Grand, il règne sur la Judée pour Rome. Il persécute des membres de l''Église, tue Jacques et fait arrêter Pierre (Ac 12).', '[{"text": "Hérode Agrippa fait décapiter Jacques, frère de Jean.", "translation": "Il veut plaire aux autorités juives."}, {"text": "Hérode Agrippa fait aussi arrêter Pierre.", "translation": "Pierre est libéré par un ange."}]'::jsonb, null, '{"id": "eg.d.herode_agrippa", "word": "Hérode Agrippa", "translation": "roi des Juifs qui fait décapiter Jacques vers 44", "partOfSpeech": "person", "explanation": "Petit-fils d''Hérode le Grand, il règne sur la Judée pour Rome. Il persécute des membres de l''Église, tue Jacques et fait arrêter Pierre (Ac 12).", "examples": [{"text": "Hérode Agrippa fait décapiter Jacques, frère de Jean.", "translation": "Il veut plaire aux autorités juives."}, {"text": "Hérode Agrippa fait aussi arrêter Pierre.", "translation": "Pierre est libéré par un ange."}], "unitId": "eg.v.herode_agrippa"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jacques_de_zebedee', 'eg', 'Jacques, frère de Jean', 'apôtre décapité vers 44, premier apôtre martyr', 'Fils de Zébédée et frère de l''apôtre Jean, il est le premier des Douze à mourir pour le Christ. Ne le confonds pas avec Jacques de Jérusalem.', '[{"text": "Jacques, frère de Jean, est décapité vers 44.", "translation": "Il est le premier des apôtres martyrs."}, {"text": "Jacques et Jean sont surnommés « fils du tonnerre ».", "translation": "Ils sont parmi les premiers appelés."}]'::jsonb, null, '{"id": "eg.d.jacques_de_zebedee", "word": "Jacques, frère de Jean", "translation": "apôtre décapité vers 44, premier apôtre martyr", "partOfSpeech": "person", "explanation": "Fils de Zébédée et frère de l''apôtre Jean, il est le premier des Douze à mourir pour le Christ. Ne le confonds pas avec Jacques de Jérusalem.", "examples": [{"text": "Jacques, frère de Jean, est décapité vers 44.", "translation": "Il est le premier des apôtres martyrs."}, {"text": "Jacques et Jean sont surnommés « fils du tonnerre ».", "translation": "Ils sont parmi les premiers appelés."}], "unitId": "eg.v.jacques_de_zebedee"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.neron', 'eg', 'Néron', 'empereur romain qui persécute les chrétiens après l''incendie de Rome (64)', 'Empereur de 54 à 68, célèbre pour sa cruauté. Pour détourner les soupçons après l''incendie de Rome, il accuse les chrétiens, qui sont arrêtés et torturés.', '[{"text": "Néron accuse les chrétiens de l''incendie de 64.", "translation": "C''est la première grande persécution romaine."}, {"text": "Pierre et Paul meurent à Rome sous le règne de Néron.", "translation": "Selon la tradition, vers 64-67."}]'::jsonb, null, '{"id": "eg.d.neron", "word": "Néron", "translation": "empereur romain qui persécute les chrétiens après l''incendie de Rome (64)", "partOfSpeech": "person", "explanation": "Empereur de 54 à 68, célèbre pour sa cruauté. Pour détourner les soupçons après l''incendie de Rome, il accuse les chrétiens, qui sont arrêtés et torturés.", "examples": [{"text": "Néron accuse les chrétiens de l''incendie de 64.", "translation": "C''est la première grande persécution romaine."}, {"text": "Pierre et Paul meurent à Rome sous le règne de Néron.", "translation": "Selon la tradition, vers 64-67."}], "unitId": "eg.v.neron"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.incendie_de_rome', 'eg', 'l''incendie de Rome', 'grand incendie de juillet 64, dont Néron accuse les chrétiens', 'L''incendie dure six jours et ravage une grande partie de la ville. La rumeur accuse Néron lui-même ; il détourne les soupçons sur les chrétiens.', '[{"text": "L''incendie de Rome a lieu en 64.", "translation": "Les chrétiens sont pris pour boucs émissaires."}, {"text": "Néron veut reconstruire une Rome plus belle.", "translation": "Les soupçons populaires se tournent vers lui."}]'::jsonb, null, '{"id": "eg.d.incendie_de_rome", "word": "l''incendie de Rome", "translation": "grand incendie de juillet 64, dont Néron accuse les chrétiens", "partOfSpeech": "event", "explanation": "L''incendie dure six jours et ravage une grande partie de la ville. La rumeur accuse Néron lui-même ; il détourne les soupçons sur les chrétiens.", "examples": [{"text": "L''incendie de Rome a lieu en 64.", "translation": "Les chrétiens sont pris pour boucs émissaires."}, {"text": "Néron veut reconstruire une Rome plus belle.", "translation": "Les soupçons populaires se tournent vers lui."}], "unitId": "eg.v.incendie_de_rome"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.revolte_juive', 'eg', 'la révolte juive', 'soulèvement des Juifs contre Rome, en 66', 'En 66, les Juifs de Judée se soulèvent contre l''occupant romain. La guerre durera quatre ans et finira par la destruction de Jérusalem.', '[{"text": "La révolte juive éclate en 66.", "translation": "Rome envoie ses légions."}, {"text": "Les chrétiens ne participent pas à la révolte.", "translation": "Ils quittent Jérusalem."}]'::jsonb, null, '{"id": "eg.d.revolte_juive", "word": "la révolte juive", "translation": "soulèvement des Juifs contre Rome, en 66", "partOfSpeech": "event", "explanation": "En 66, les Juifs de Judée se soulèvent contre l''occupant romain. La guerre durera quatre ans et finira par la destruction de Jérusalem.", "examples": [{"text": "La révolte juive éclate en 66.", "translation": "Rome envoie ses légions."}, {"text": "Les chrétiens ne participent pas à la révolte.", "translation": "Ils quittent Jérusalem."}], "unitId": "eg.v.revolte_juive"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chute_de_jerusalem', 'eg', 'la chute de Jérusalem', 'prise de la ville par Titus en 70, et destruction du Temple', 'En 70, après un siège terrible, les légions de Titus prennent Jérusalem. Le Temple est détruit et les Juifs sont dispersés dans le monde.', '[{"text": "La chute de Jérusalem a lieu en 70.", "translation": "Titus est le général romain."}, {"text": "Les chrétiens de Jérusalem se dispersent.", "translation": "L''Évangile atteint d''autres régions."}]'::jsonb, null, '{"id": "eg.d.chute_de_jerusalem", "word": "la chute de Jérusalem", "translation": "prise de la ville par Titus en 70, et destruction du Temple", "partOfSpeech": "event", "explanation": "En 70, après un siège terrible, les légions de Titus prennent Jérusalem. Le Temple est détruit et les Juifs sont dispersés dans le monde.", "examples": [{"text": "La chute de Jérusalem a lieu en 70.", "translation": "Titus est le général romain."}, {"text": "Les chrétiens de Jérusalem se dispersent.", "translation": "L''Évangile atteint d''autres régions."}], "unitId": "eg.v.chute_de_jerusalem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.temple_de_jerusalem', 'eg', 'le Temple de Jérusalem', 'grand sanctuaire juif, détruit par les Romains en 70', 'C''est le centre du culte juif, où l''on offre des sacrifices. Jésus y enseigne, les premiers chrétiens y prient. Après 70, il n''en reste que des pierres.', '[{"text": "Les premiers chrétiens prient au Temple.", "translation": "Ils y restent fidèles."}, {"text": "Le Temple est détruit en 70 par Titus.", "translation": "Il n''a jamais été reconstruit."}]'::jsonb, null, '{"id": "eg.d.temple_de_jerusalem", "word": "le Temple de Jérusalem", "translation": "grand sanctuaire juif, détruit par les Romains en 70", "partOfSpeech": "place", "explanation": "C''est le centre du culte juif, où l''on offre des sacrifices. Jésus y enseigne, les premiers chrétiens y prient. Après 70, il n''en reste que des pierres.", "examples": [{"text": "Les premiers chrétiens prient au Temple.", "translation": "Ils y restent fidèles."}, {"text": "Le Temple est détruit en 70 par Titus.", "translation": "Il n''a jamais été reconstruit."}], "unitId": "eg.v.temple_de_jerusalem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.domitien', 'eg', 'Domitien', 'empereur romain (81-96) lié à une persécution des chrétiens', 'Empereur de 81 à 96, il se fait appeler « seigneur et dieu ». Les chrétiens qui refusent de l''adorer sont inquiétés, surtout vers la fin de son règne.', '[{"text": "Domitien persécute les chrétiens.", "translation": "La tradition y associe l''exil de saint Jean à Patmos."}, {"text": "Domitien règne de 81 à 96.", "translation": "Il est assassiné en 96."}]'::jsonb, null, '{"id": "eg.d.domitien", "word": "Domitien", "translation": "empereur romain (81-96) lié à une persécution des chrétiens", "partOfSpeech": "person", "explanation": "Empereur de 81 à 96, il se fait appeler « seigneur et dieu ». Les chrétiens qui refusent de l''adorer sont inquiétés, surtout vers la fin de son règne.", "examples": [{"text": "Domitien persécute les chrétiens.", "translation": "La tradition y associe l''exil de saint Jean à Patmos."}, {"text": "Domitien règne de 81 à 96.", "translation": "Il est assassiné en 96."}], "unitId": "eg.v.domitien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tradition_orale', 'eg', 'la tradition orale', 'enseignement transmis de bouche à oreille avant d''être écrit', 'Jésus n''a rien écrit. Pendant une génération, ses paroles et ses actes sont racontés par les témoins, puis mis en forme dans des catéchèses.', '[{"text": "Les disciples racontent ce qu''ils ont vu et entendu.", "translation": "C''est la tradition orale."}, {"text": "Les premières catéchèses sont retenues par cœur.", "translation": "Elles seront ensuite écrites."}]'::jsonb, null, '{"id": "eg.d.tradition_orale", "word": "la tradition orale", "translation": "enseignement transmis de bouche à oreille avant d''être écrit", "partOfSpeech": "concept", "explanation": "Jésus n''a rien écrit. Pendant une génération, ses paroles et ses actes sont racontés par les témoins, puis mis en forme dans des catéchèses.", "examples": [{"text": "Les disciples racontent ce qu''ils ont vu et entendu.", "translation": "C''est la tradition orale."}, {"text": "Les premières catéchèses sont retenues par cœur.", "translation": "Elles seront ensuite écrites."}], "unitId": "eg.v.tradition_orale"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.epitre', 'eg', 'l''épître', 'lettre d''un apôtre à une communauté', 'Du grec epistolè, « lettre ». Paul, Pierre, Jean, Jacques et Jude écrivent des épîtres aux Églises. Ce sont parmi les plus anciens textes du Nouveau Testament.', '[{"text": "Paul écrit une épître aux Romains.", "translation": "Il y explique le salut par la foi."}, {"text": "L''épître aux Hébreux est comptée parmi les quatorze de Paul.", "translation": "La tradition copte la lui attribue."}]'::jsonb, null, '{"id": "eg.d.epitre", "word": "l''épître", "translation": "lettre d''un apôtre à une communauté", "partOfSpeech": "work", "explanation": "Du grec epistolè, « lettre ». Paul, Pierre, Jean, Jacques et Jude écrivent des épîtres aux Églises. Ce sont parmi les plus anciens textes du Nouveau Testament.", "examples": [{"text": "Paul écrit une épître aux Romains.", "translation": "Il y explique le salut par la foi."}, {"text": "L''épître aux Hébreux est comptée parmi les quatorze de Paul.", "translation": "La tradition copte la lui attribue."}], "unitId": "eg.v.epitre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.evangile', 'eg', 'l''Évangile', '« bonne nouvelle » : annonce du salut, et livre qui raconte la vie de Jésus', 'Le mot grec euangelion veut dire « bonne nouvelle ». Il y a quatre évangiles : Matthieu, Marc, Luc et Jean.', '[{"text": "L''Évangile selon Marc est le plus court.", "translation": "Marc y raconte Jésus en action."}, {"text": "L''Évangile selon Jean est écrit à la fin du siècle.", "translation": "Il répond à la gnose."}]'::jsonb, null, '{"id": "eg.d.evangile", "word": "l''Évangile", "translation": "« bonne nouvelle » : annonce du salut, et livre qui raconte la vie de Jésus", "partOfSpeech": "work", "explanation": "Le mot grec euangelion veut dire « bonne nouvelle ». Il y a quatre évangiles : Matthieu, Marc, Luc et Jean.", "examples": [{"text": "L''Évangile selon Marc est le plus court.", "translation": "Marc y raconte Jésus en action."}, {"text": "L''Évangile selon Jean est écrit à la fin du siècle.", "translation": "Il répond à la gnose."}], "unitId": "eg.v.evangile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nouveau_testament', 'eg', 'le Nouveau Testament', 'recueil des évangiles, des Actes, des épîtres et de l''Apocalypse', 'C''est la seconde partie de la Bible. Il est écrit en grec, au cours du premier siècle. Sa composition définitive viendra plus tard.', '[{"text": "Le Nouveau Testament contient les quatre évangiles.", "translation": "Il contient aussi les épîtres."}, {"text": "Luc a écrit un évangile et les Actes des apôtres.", "translation": "Les Actes racontent les débuts de l''Église."}]'::jsonb, null, '{"id": "eg.d.nouveau_testament", "word": "le Nouveau Testament", "translation": "recueil des évangiles, des Actes, des épîtres et de l''Apocalypse", "partOfSpeech": "work", "explanation": "C''est la seconde partie de la Bible. Il est écrit en grec, au cours du premier siècle. Sa composition définitive viendra plus tard.", "examples": [{"text": "Le Nouveau Testament contient les quatre évangiles.", "translation": "Il contient aussi les épîtres."}, {"text": "Luc a écrit un évangile et les Actes des apôtres.", "translation": "Les Actes racontent les débuts de l''Église."}], "unitId": "eg.v.nouveau_testament"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_jean', 'eg', 'saint Jean', 'apôtre et évangéliste, dernier apôtre vivant, mort vers l''an 100', 'Frère de Jacques, il écrit l''Évangile le plus théologique et lutte contre la gnose : « le Verbe s''est fait chair ». Il meurt vers l''an 100.', '[{"text": "Jean écrit son évangile à la fin du siècle.", "translation": "Il combat la gnose."}, {"text": "Jean est le dernier apôtre vivant.", "translation": "Il meurt vers l''an 100."}]'::jsonb, null, '{"id": "eg.d.saint_jean", "word": "saint Jean", "translation": "apôtre et évangéliste, dernier apôtre vivant, mort vers l''an 100", "partOfSpeech": "person", "explanation": "Frère de Jacques, il écrit l''Évangile le plus théologique et lutte contre la gnose : « le Verbe s''est fait chair ». Il meurt vers l''an 100.", "examples": [{"text": "Jean écrit son évangile à la fin du siècle.", "translation": "Il combat la gnose."}, {"text": "Jean est le dernier apôtre vivant.", "translation": "Il meurt vers l''an 100."}], "unitId": "eg.v.saint_jean"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.gnosticisme', 'eg', 'le gnosticisme', 'courant qui prétend sauver par une connaissance secrète et méprise le corps', 'Du grec gnosis, « connaissance ». Il sépare le monde en deux : un Dieu bon, un dieu mauvais créateur. Le corps est une prison dont il faut s''échapper.', '[{"text": "Les gnostiques méprisent le corps.", "translation": "Ils nient que Dieu se soit fait chair."}, {"text": "Le gnosticisme refleurira à Alexandrie au IIe siècle.", "translation": "Il sera combattu par les Pères."}]'::jsonb, null, '{"id": "eg.d.gnosticisme", "word": "le gnosticisme", "translation": "courant qui prétend sauver par une connaissance secrète et méprise le corps", "partOfSpeech": "concept", "explanation": "Du grec gnosis, « connaissance ». Il sépare le monde en deux : un Dieu bon, un dieu mauvais créateur. Le corps est une prison dont il faut s''échapper.", "examples": [{"text": "Les gnostiques méprisent le corps.", "translation": "Ils nient que Dieu se soit fait chair."}, {"text": "Le gnosticisme refleurira à Alexandrie au IIe siècle.", "translation": "Il sera combattu par les Pères."}], "unitId": "eg.v.gnosticisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.docetisme', 'eg', 'le docétisme', 'idée que Jésus n''a eu que l''apparence d''un corps', 'Du grec dokein, « paraître ». Si le corps est mauvais, Dieu ne peut pas s''incarner : Jésus ne serait qu''un fantôme. Cela supprime la croix et la Résurrection réelles.', '[{"text": "Pour les docètes, Jésus n''a pas vraiment souffert.", "translation": "Ce serait seulement une apparence."}, {"text": "Jean combat le docétisme : « le Verbe s''est fait chair ».", "translation": "Il insiste sur le corps de Jésus."}]'::jsonb, null, '{"id": "eg.d.docetisme", "word": "le docétisme", "translation": "idée que Jésus n''a eu que l''apparence d''un corps", "partOfSpeech": "concept", "explanation": "Du grec dokein, « paraître ». Si le corps est mauvais, Dieu ne peut pas s''incarner : Jésus ne serait qu''un fantôme. Cela supprime la croix et la Résurrection réelles.", "examples": [{"text": "Pour les docètes, Jésus n''a pas vraiment souffert.", "translation": "Ce serait seulement une apparence."}, {"text": "Jean combat le docétisme : « le Verbe s''est fait chair ».", "translation": "Il insiste sur le corps de Jésus."}], "unitId": "eg.v.docetisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.simon_le_magicien', 'eg', 'Simon le magicien', 'magicien de Samarie (Ac 8), considéré comme ancêtre des gnostiques', 'Il veut acheter à Pierre le pouvoir de donner l''Esprit. Les Pères le voient comme le premier des hérétiques et l''ancêtre des gnostiques.', '[{"text": "Simon le magicien est cité dans les Actes des apôtres.", "translation": "Il est repris par Pierre."}, {"text": "Le mot « simonie » vient de son nom.", "translation": "Il désigne l''achat des choses saintes."}]'::jsonb, null, '{"id": "eg.d.simon_le_magicien", "word": "Simon le magicien", "translation": "magicien de Samarie (Ac 8), considéré comme ancêtre des gnostiques", "partOfSpeech": "person", "explanation": "Il veut acheter à Pierre le pouvoir de donner l''Esprit. Les Pères le voient comme le premier des hérétiques et l''ancêtre des gnostiques.", "examples": [{"text": "Simon le magicien est cité dans les Actes des apôtres.", "translation": "Il est repris par Pierre."}, {"text": "Le mot « simonie » vient de son nom.", "translation": "Il désigne l''achat des choses saintes."}], "unitId": "eg.v.simon_le_magicien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_andre', 'eg', 'saint André', 'apôtre, frère de Pierre, qui évangélise la Grèce selon la tradition', 'Pêcheur de Galilée, appelé le premier. La tradition le voit prêcher en Grèce et jusque chez les Scythes. Il est martyrisé vers 60, à Patras.', '[{"text": "André évangélise la Grèce.", "translation": "Il est le frère de Pierre."}, {"text": "André est appelé « le premier appelé ».", "translation": "Il amène son frère à Jésus."}]'::jsonb, null, '{"id": "eg.d.saint_andre", "word": "saint André", "translation": "apôtre, frère de Pierre, qui évangélise la Grèce selon la tradition", "partOfSpeech": "person", "explanation": "Pêcheur de Galilée, appelé le premier. La tradition le voit prêcher en Grèce et jusque chez les Scythes. Il est martyrisé vers 60, à Patras.", "examples": [{"text": "André évangélise la Grèce.", "translation": "Il est le frère de Pierre."}, {"text": "André est appelé « le premier appelé ».", "translation": "Il amène son frère à Jésus."}], "unitId": "eg.v.saint_andre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_thomas', 'eg', 'saint Thomas', 'apôtre qui porte l''Évangile jusqu''en Inde, selon la tradition', 'Celui qui a douté avant de dire « Mon Seigneur et mon Dieu ». Les chrétiens de l''Inde l''honorent comme leur fondateur. Il est martyrisé vers 72.', '[{"text": "Thomas est envoyé en Inde.", "translation": "Les chrétiens de Malabar le vénèrent."}, {"text": "Thomas a vu les plaies du Christ ressuscité.", "translation": "Il s''écrie : « Mon Seigneur et mon Dieu ! »"}]'::jsonb, null, '{"id": "eg.d.saint_thomas", "word": "saint Thomas", "translation": "apôtre qui porte l''Évangile jusqu''en Inde, selon la tradition", "partOfSpeech": "person", "explanation": "Celui qui a douté avant de dire « Mon Seigneur et mon Dieu ». Les chrétiens de l''Inde l''honorent comme leur fondateur. Il est martyrisé vers 72.", "examples": [{"text": "Thomas est envoyé en Inde.", "translation": "Les chrétiens de Malabar le vénèrent."}, {"text": "Thomas a vu les plaies du Christ ressuscité.", "translation": "Il s''écrie : « Mon Seigneur et mon Dieu ! »"}], "unitId": "eg.v.saint_thomas"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_matthieu', 'eg', 'saint Matthieu', 'apôtre et évangéliste, associé à l''Éthiopie et à la Perse', 'Ancien collecteur d''impôts, il écrit un évangile tourné vers les prophéties. La tradition le voit prêcher en Éthiopie.', '[{"text": "Matthieu a été collecteur d''impôts.", "translation": "Jésus l''appelle à le suivre."}, {"text": "Matthieu écrit un évangile.", "translation": "Il montre que les prophéties s''accomplissent."}]'::jsonb, null, '{"id": "eg.d.saint_matthieu", "word": "saint Matthieu", "translation": "apôtre et évangéliste, associé à l''Éthiopie et à la Perse", "partOfSpeech": "person", "explanation": "Ancien collecteur d''impôts, il écrit un évangile tourné vers les prophéties. La tradition le voit prêcher en Éthiopie.", "examples": [{"text": "Matthieu a été collecteur d''impôts.", "translation": "Jésus l''appelle à le suivre."}, {"text": "Matthieu écrit un évangile.", "translation": "Il montre que les prophéties s''accomplissent."}], "unitId": "eg.v.saint_matthieu"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_barthelemy', 'eg', 'saint Barthélemy', 'apôtre associé à l''Arménie selon la tradition', 'La tradition le fait prêcher en Arménie, où l''Église arménienne l''honore comme son fondateur avec Thaddée.', '[{"text": "Barthélemy évangélise l''Arménie.", "translation": "L''Église arménienne l''honore."}, {"text": "Barthélemy fait partie des Douze.", "translation": "Les évangiles le citent dans la liste des apôtres."}]'::jsonb, null, '{"id": "eg.d.saint_barthelemy", "word": "saint Barthélemy", "translation": "apôtre associé à l''Arménie selon la tradition", "partOfSpeech": "person", "explanation": "La tradition le fait prêcher en Arménie, où l''Église arménienne l''honore comme son fondateur avec Thaddée.", "examples": [{"text": "Barthélemy évangélise l''Arménie.", "translation": "L''Église arménienne l''honore."}, {"text": "Barthélemy fait partie des Douze.", "translation": "Les évangiles le citent dans la liste des apôtres."}], "unitId": "eg.v.saint_barthelemy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.siege_apostolique', 'eg', 'le siège apostolique', 'Église fondée par un apôtre, dirigée par une chaîne d''évêques', 'Le « siège » est le fauteuil de l''évêque, symbole de son autorité d''enseignement. Jérusalem, Antioche, Rome, Éphèse et Alexandrie sont des sièges apostoliques du Ier siècle.', '[{"text": "Alexandrie est un siège apostolique fondé par Marc.", "translation": "Ses évêques succèdent à Marc."}, {"text": "Rome est un siège apostolique : Pierre et Paul y sont morts.", "translation": "Antioche l''est aussi."}]'::jsonb, null, '{"id": "eg.d.siege_apostolique", "word": "le siège apostolique", "translation": "Église fondée par un apôtre, dirigée par une chaîne d''évêques", "partOfSpeech": "concept", "explanation": "Le « siège » est le fauteuil de l''évêque, symbole de son autorité d''enseignement. Jérusalem, Antioche, Rome, Éphèse et Alexandrie sont des sièges apostoliques du Ier siècle.", "examples": [{"text": "Alexandrie est un siège apostolique fondé par Marc.", "translation": "Ses évêques succèdent à Marc."}, {"text": "Rome est un siège apostolique : Pierre et Paul y sont morts.", "translation": "Antioche l''est aussi."}], "unitId": "eg.v.siege_apostolique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.succession_apostolique', 'eg', 'la succession apostolique', 'chaîne ininterrompue d''évêques qui remonte aux apôtres', 'Les apôtres ont transmis leur mission à des évêques par l''imposition des mains, et ceux-ci l''ont transmise à d''autres. L''Église copte, comme les orthodoxes et les catholiques, y tient fermement.', '[{"text": "Le pape d''Alexandrie est le successeur de saint Marc.", "translation": "La chaîne remonte au Ier siècle."}, {"text": "La succession apostolique garantit la foi des origines.", "translation": "Elle relie chaque évêque aux apôtres."}]'::jsonb, null, '{"id": "eg.d.succession_apostolique", "word": "la succession apostolique", "translation": "chaîne ininterrompue d''évêques qui remonte aux apôtres", "partOfSpeech": "concept", "explanation": "Les apôtres ont transmis leur mission à des évêques par l''imposition des mains, et ceux-ci l''ont transmise à d''autres. L''Église copte, comme les orthodoxes et les catholiques, y tient fermement.", "examples": [{"text": "Le pape d''Alexandrie est le successeur de saint Marc.", "translation": "La chaîne remonte au Ier siècle."}, {"text": "La succession apostolique garantit la foi des origines.", "translation": "Elle relie chaque évêque aux apôtres."}], "unitId": "eg.v.succession_apostolique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.alexandrie', 'eg', 'Alexandrie', 'grande ville grecque d''Égypte, fondée par Alexandre le Grand en 331 av. J.-C.', 'Grand port de la Méditerranée, ville de savants et de bibliothèques, elle compte au Ier siècle une forte communauté juive. C''est le berceau de l''Église copte.', '[{"text": "Marc arrive à Alexandrie vers le milieu du Ier siècle.", "translation": "Il y fonde une Église."}, {"text": "Alexandrie est un carrefour de Juifs, de Grecs et d''Égyptiens.", "translation": "L''Évangile y rencontre toutes les cultures."}]'::jsonb, null, '{"id": "eg.d.alexandrie", "word": "Alexandrie", "translation": "grande ville grecque d''Égypte, fondée par Alexandre le Grand en 331 av. J.-C.", "partOfSpeech": "place", "explanation": "Grand port de la Méditerranée, ville de savants et de bibliothèques, elle compte au Ier siècle une forte communauté juive. C''est le berceau de l''Église copte.", "examples": [{"text": "Marc arrive à Alexandrie vers le milieu du Ier siècle.", "translation": "Il y fonde une Église."}, {"text": "Alexandrie est un carrefour de Juifs, de Grecs et d''Égyptiens.", "translation": "L''Évangile y rencontre toutes les cultures."}], "unitId": "eg.v.alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.septante', 'eg', 'la Septante', 'traduction grecque de la Bible hébraïque, faite à Alexandrie', 'Commencée au IIIe siècle av. J.-C., elle permet aux Juifs de langue grecque de lire l''Écriture. Les premiers chrétiens la citent souvent.', '[{"text": "Les apôtres citent la Septante dans leurs écrits.", "translation": "C''est la Bible des chrétiens de langue grecque."}, {"text": "La Septante est traduite à Alexandrie.", "translation": "Elle prépare le terrain à l''Évangile."}]'::jsonb, null, '{"id": "eg.d.septante", "word": "la Septante", "translation": "traduction grecque de la Bible hébraïque, faite à Alexandrie", "partOfSpeech": "work", "explanation": "Commencée au IIIe siècle av. J.-C., elle permet aux Juifs de langue grecque de lire l''Écriture. Les premiers chrétiens la citent souvent.", "examples": [{"text": "Les apôtres citent la Septante dans leurs écrits.", "translation": "C''est la Bible des chrétiens de langue grecque."}, {"text": "La Septante est traduite à Alexandrie.", "translation": "Elle prépare le terrain à l''Évangile."}], "unitId": "eg.v.septante"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_marc', 'eg', 'saint Marc', 'évangéliste, fondateur de l''Église d''Alexandrie, martyr vers 68', 'De son nom juif Jean, surnommé Marc. Cousin de Barnabé, compagnon de Paul puis de Pierre, il écrit le deuxième évangile. La tradition copte le tient pour le premier évêque d''Alexandrie, et l''Église d''Égypte le vénère comme son fondateur.', '[{"text": "Saint Marc fonde l''Église d''Alexandrie.", "translation": "Il y devient martyr vers 68."}, {"text": "Marc écrit l''évangile le plus court.", "translation": "Pierre l''appelle « mon fils »."}]'::jsonb, null, '{"id": "eg.d.saint_marc", "word": "saint Marc", "translation": "évangéliste, fondateur de l''Église d''Alexandrie, martyr vers 68", "partOfSpeech": "person", "explanation": "De son nom juif Jean, surnommé Marc. Cousin de Barnabé, compagnon de Paul puis de Pierre, il écrit le deuxième évangile. La tradition copte le tient pour le premier évêque d''Alexandrie, et l''Église d''Égypte le vénère comme son fondateur.", "examples": [{"text": "Saint Marc fonde l''Église d''Alexandrie.", "translation": "Il y devient martyr vers 68."}, {"text": "Marc écrit l''évangile le plus court.", "translation": "Pierre l''appelle « mon fils »."}], "unitId": "eg.v.saint_marc"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.anianus', 'eg', 'Anianus', 'cordonnier d''Alexandrie, premier converti de Marc et son successeur', 'Appelé aussi Hananiya en arabe. Guéri par Marc, il devient son premier converti, puis le deuxième évêque d''Alexandrie.', '[{"text": "Anianus accueille Marc chez lui.", "translation": "Il est guéri de sa main blessée."}, {"text": "Anianus est ordonné évêque par Marc.", "translation": "Il lui succède après son martyre."}]'::jsonb, null, '{"id": "eg.d.anianus", "word": "Anianus", "translation": "cordonnier d''Alexandrie, premier converti de Marc et son successeur", "partOfSpeech": "person", "explanation": "Appelé aussi Hananiya en arabe. Guéri par Marc, il devient son premier converti, puis le deuxième évêque d''Alexandrie.", "examples": [{"text": "Anianus accueille Marc chez lui.", "translation": "Il est guéri de sa main blessée."}, {"text": "Anianus est ordonné évêque par Marc.", "translation": "Il lui succède après son martyre."}], "unitId": "eg.v.anianus"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_d_alexandrie', 'eg', 'l''Église d''Alexandrie', 'Église d''Égypte fondée par saint Marc, à l''origine de l''Église copte', 'Un des grands sièges apostoliques du monde chrétien. Elle sera le foyer d''une école de théologie célèbre et la mère de milliers de martyrs et de moines.', '[{"text": "L''Église d''Alexandrie est fondée par Marc.", "translation": "C''est un siège apostolique."}, {"text": "Son chef porte le titre de pape d''Alexandrie.", "translation": "Il est successeur de saint Marc."}]'::jsonb, null, '{"id": "eg.d.eglise_d_alexandrie", "word": "l''Église d''Alexandrie", "translation": "Église d''Égypte fondée par saint Marc, à l''origine de l''Église copte", "partOfSpeech": "organization", "explanation": "Un des grands sièges apostoliques du monde chrétien. Elle sera le foyer d''une école de théologie célèbre et la mère de milliers de martyrs et de moines.", "examples": [{"text": "L''Église d''Alexandrie est fondée par Marc.", "translation": "C''est un siège apostolique."}, {"text": "Son chef porte le titre de pape d''Alexandrie.", "translation": "Il est successeur de saint Marc."}], "unitId": "eg.v.eglise_d_alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.copte', 'eg', 'copte', '« égyptien » : nom de l''Église d''Égypte, du grec Aigyptios', 'Le grec Aigyptios (égyptien) est devenu qibt en arabe, puis « copte ». Au début, copte veut simplement dire égyptien ; il désigne ensuite les chrétiens d''Égypte.', '[{"text": "Être copte, c''est être de l''Église d''Égypte.", "translation": "Le mot veut dire « égyptien »."}, {"text": "La langue copte est la dernière étape de la langue des pharaons.", "translation": "Elle s''écrit avec l''alphabet grec."}]'::jsonb, null, '{"id": "eg.d.copte", "word": "copte", "translation": "« égyptien » : nom de l''Église d''Égypte, du grec Aigyptios", "partOfSpeech": "concept", "explanation": "Le grec Aigyptios (égyptien) est devenu qibt en arabe, puis « copte ». Au début, copte veut simplement dire égyptien ; il désigne ensuite les chrétiens d''Égypte.", "examples": [{"text": "Être copte, c''est être de l''Église d''Égypte.", "translation": "Le mot veut dire « égyptien »."}, {"text": "La langue copte est la dernière étape de la langue des pharaons.", "translation": "Elle s''écrit avec l''alphabet grec."}], "unitId": "eg.v.copte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.reliques_de_saint_marc', 'eg', 'les reliques de saint Marc', 'corps du saint, emporté à Venise en 828, en partie revenu au Caire en 1968', 'En 828, des marchands vénitiens emportent le corps du saint à Venise. En 1968, une partie des reliques est rendue à l''Église copte par le pape de Rome.', '[{"text": "Les reliques de saint Marc sont à Venise depuis 828.", "translation": "On y a bâti la basilique Saint-Marc."}, {"text": "En 1968, une partie des reliques revient en Égypte.", "translation": "Le pape copte les accueille au Caire."}]'::jsonb, null, '{"id": "eg.d.reliques_de_saint_marc", "word": "les reliques de saint Marc", "translation": "corps du saint, emporté à Venise en 828, en partie revenu au Caire en 1968", "partOfSpeech": "event", "explanation": "En 828, des marchands vénitiens emportent le corps du saint à Venise. En 1968, une partie des reliques est rendue à l''Église copte par le pape de Rome.", "examples": [{"text": "Les reliques de saint Marc sont à Venise depuis 828.", "translation": "On y a bâti la basilique Saint-Marc."}, {"text": "En 1968, une partie des reliques revient en Égypte.", "translation": "Le pape copte les accueille au Caire."}], "unitId": "eg.v.reliques_de_saint_marc"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cathedrale_saint_marc', 'eg', 'la cathédrale Saint-Marc du Caire', 'grande cathédrale copte de l''Abbassiya, consacrée en 1968', 'Siège du pape copte au Caire, elle a été consacrée en 1968, au moment du retour des reliques. C''est le centre de l''Église copte orthodoxe.', '[{"text": "La cathédrale Saint-Marc est au Caire.", "translation": "Les reliques du saint y ont été accueillies."}, {"text": "Le pape copte préside les grandes fêtes à la cathédrale.", "translation": "Des milliers de fidèles s''y rassemblent."}]'::jsonb, null, '{"id": "eg.d.cathedrale_saint_marc", "word": "la cathédrale Saint-Marc du Caire", "translation": "grande cathédrale copte de l''Abbassiya, consacrée en 1968", "partOfSpeech": "place", "explanation": "Siège du pape copte au Caire, elle a été consacrée en 1968, au moment du retour des reliques. C''est le centre de l''Église copte orthodoxe.", "examples": [{"text": "La cathédrale Saint-Marc est au Caire.", "translation": "Les reliques du saint y ont été accueillies."}, {"text": "Le pape copte préside les grandes fêtes à la cathédrale.", "translation": "Des milliers de fidèles s''y rassemblent."}], "unitId": "eg.v.cathedrale_saint_marc"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sainte_tradition', 'eg', 'la sainte tradition', 'enseignement transmis par les apôtres de vive voix et par la vie de l''Église', 'La tradition est vivante : prière, enseignement, sacrements. Elle accompagne les Écritures et ne les contredit jamais.', '[{"text": "La façon de baptiser vient de la tradition apostolique.", "translation": "Elle se transmet par l''Église entière."}, {"text": "L''Église lit les Écritures dans la lumière de la tradition.", "translation": "Les deux viennent des apôtres."}]'::jsonb, null, '{"id": "eg.d.sainte_tradition", "word": "la sainte tradition", "translation": "enseignement transmis par les apôtres de vive voix et par la vie de l''Église", "partOfSpeech": "concept", "explanation": "La tradition est vivante : prière, enseignement, sacrements. Elle accompagne les Écritures et ne les contredit jamais.", "examples": [{"text": "La façon de baptiser vient de la tradition apostolique.", "translation": "Elle se transmet par l''Église entière."}, {"text": "L''Église lit les Écritures dans la lumière de la tradition.", "translation": "Les deux viennent des apôtres."}], "unitId": "eg.v.sainte_tradition"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.depot_de_la_foi', 'eg', 'le dépôt de la foi', 'la foi reçue des apôtres, confiée à l''Église pour qu''elle la garde intacte', 'Comme un trésor confié à un gardien, la foi n''est pas à inventer mais à transmettre fidèlement.', '[{"text": "Les évêques sont les gardiens du dépôt de la foi.", "translation": "Leur rôle est de transmettre, pas d''inventer."}, {"text": "Les hérésies altèrent le dépôt de la foi.", "translation": "Elles ajoutent ou retirent des éléments."}]'::jsonb, null, '{"id": "eg.d.depot_de_la_foi", "word": "le dépôt de la foi", "translation": "la foi reçue des apôtres, confiée à l''Église pour qu''elle la garde intacte", "partOfSpeech": "concept", "explanation": "Comme un trésor confié à un gardien, la foi n''est pas à inventer mais à transmettre fidèlement.", "examples": [{"text": "Les évêques sont les gardiens du dépôt de la foi.", "translation": "Leur rôle est de transmettre, pas d''inventer."}, {"text": "Les hérésies altèrent le dépôt de la foi.", "translation": "Elles ajoutent ou retirent des éléments."}], "unitId": "eg.v.depot_de_la_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eveque', 'eg', 'un évêque', 'responsable d''une Église locale, successeur des apôtres', 'Du grec episkopos, « surveillant ». Il enseigne, ordonne les prêtres et garde l''unité de son diocèse.', '[{"text": "Ignace d''Antioche est évêque d''Antioche.", "translation": "Il écrit à d''autres Églises en tant qu''évêque."}, {"text": "Le pape d''Alexandrie est l''évêque d''Alexandrie.", "translation": "Chez les Coptes, il porte le titre de pape."}]'::jsonb, null, '{"id": "eg.d.eveque", "word": "un évêque", "translation": "responsable d''une Église locale, successeur des apôtres", "partOfSpeech": "person", "explanation": "Du grec episkopos, « surveillant ». Il enseigne, ordonne les prêtres et garde l''unité de son diocèse.", "examples": [{"text": "Ignace d''Antioche est évêque d''Antioche.", "translation": "Il écrit à d''autres Églises en tant qu''évêque."}, {"text": "Le pape d''Alexandrie est l''évêque d''Alexandrie.", "translation": "Chez les Coptes, il porte le titre de pape."}], "unitId": "eg.v.eveque"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ecritures', 'eg', 'les Écritures', 'les livres saints reçus par l''Église : Ancien et Nouveau Testament', 'Le premier appui de l''Église pour garder la vérité. On les lit dans les assemblées.', '[{"text": "L''Église lit les Écritures pendant la liturgie.", "translation": "Elles sont lues à haute voix devant tous."}, {"text": "Les hérétiques citent aussi les Écritures.", "translation": "D''où la nécessité de la tradition et des évêques."}]'::jsonb, null, '{"id": "eg.d.ecritures", "word": "les Écritures", "translation": "les livres saints reçus par l''Église : Ancien et Nouveau Testament", "partOfSpeech": "work", "explanation": "Le premier appui de l''Église pour garder la vérité. On les lit dans les assemblées.", "examples": [{"text": "L''Église lit les Écritures pendant la liturgie.", "translation": "Elles sont lues à haute voix devant tous."}, {"text": "Les hérétiques citent aussi les Écritures.", "translation": "D''où la nécessité de la tradition et des évêques."}], "unitId": "eg.v.ecritures"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.doctrine', 'eg', 'une doctrine', 'un enseignement sur la foi', 'Le mot vient du latin doctrina, « enseignement ». La doctrine répond à des questions comme « Qui est le Christ ? ».', '[{"text": "La doctrine de l''Incarnation affirme que Dieu s''est fait homme.", "translation": "C''est un point central de la foi."}, {"text": "Au IIe siècle, la diversité doctrinale inquiète les évêques.", "translation": "Chaque groupe enseigne des choses différentes."}]'::jsonb, null, '{"id": "eg.d.doctrine", "word": "une doctrine", "translation": "un enseignement sur la foi", "partOfSpeech": "concept", "explanation": "Le mot vient du latin doctrina, « enseignement ». La doctrine répond à des questions comme « Qui est le Christ ? ».", "examples": [{"text": "La doctrine de l''Incarnation affirme que Dieu s''est fait homme.", "translation": "C''est un point central de la foi."}, {"text": "Au IIe siècle, la diversité doctrinale inquiète les évêques.", "translation": "Chaque groupe enseigne des choses différentes."}], "unitId": "eg.v.doctrine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.siege_de_rome', 'eg', 'le siège de Rome', 'Église fondée par les apôtres Pierre et Paul', 'Rome est la capitale de l''Empire. Pierre et Paul y sont morts martyrs au temps de Néron.', '[{"text": "Clément, évêque de Rome, écrit aux Corinthiens.", "translation": "C''est un évêque du siège de Rome."}, {"text": "Rome compte une grande communauté chrétienne.", "translation": "Elle attire des fidèles de tout l''Empire."}]'::jsonb, null, '{"id": "eg.d.siege_de_rome", "word": "le siège de Rome", "translation": "Église fondée par les apôtres Pierre et Paul", "partOfSpeech": "organization", "explanation": "Rome est la capitale de l''Empire. Pierre et Paul y sont morts martyrs au temps de Néron.", "examples": [{"text": "Clément, évêque de Rome, écrit aux Corinthiens.", "translation": "C''est un évêque du siège de Rome."}, {"text": "Rome compte une grande communauté chrétienne.", "translation": "Elle attire des fidèles de tout l''Empire."}], "unitId": "eg.v.siege_de_rome"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.siege_d_alexandrie', 'eg', 'le siège d''Alexandrie', 'Église fondée par saint Marc, celle des Coptes', 'Le siège de saint Marc : c''est l''Église copte orthodoxe, dirigée par le pape d''Alexandrie.', '[{"text": "Démétrios est évêque d''Alexandrie dès 189.", "translation": "Il dirige l''Église de saint Marc."}, {"text": "Alexandrie est aussi un centre de philosophie.", "translation": "L''école théologique y brillera."}]'::jsonb, null, '{"id": "eg.d.siege_d_alexandrie", "word": "le siège d''Alexandrie", "translation": "Église fondée par saint Marc, celle des Coptes", "partOfSpeech": "organization", "explanation": "Le siège de saint Marc : c''est l''Église copte orthodoxe, dirigée par le pape d''Alexandrie.", "examples": [{"text": "Démétrios est évêque d''Alexandrie dès 189.", "translation": "Il dirige l''Église de saint Marc."}, {"text": "Alexandrie est aussi un centre de philosophie.", "translation": "L''école théologique y brillera."}], "unitId": "eg.v.siege_d_alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.siege_d_antioche', 'eg', 'le siège d''Antioche', 'Église de Syrie rattachée à l''apôtre Pierre', 'C''est à Antioche que les disciples sont appelés chrétiens pour la première fois.', '[{"text": "Ignace est évêque d''Antioche.", "translation": "Il sera martyr à Rome."}, {"text": "Antioche se trouve en Syrie antique.", "translation": "Aujourd''hui, la ville est en Turquie."}]'::jsonb, null, '{"id": "eg.d.siege_d_antioche", "word": "le siège d''Antioche", "translation": "Église de Syrie rattachée à l''apôtre Pierre", "partOfSpeech": "organization", "explanation": "C''est à Antioche que les disciples sont appelés chrétiens pour la première fois.", "examples": [{"text": "Ignace est évêque d''Antioche.", "translation": "Il sera martyr à Rome."}, {"text": "Antioche se trouve en Syrie antique.", "translation": "Aujourd''hui, la ville est en Turquie."}], "unitId": "eg.v.siege_d_antioche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.siege_de_jerusalem', 'eg', 'le siège de Jérusalem', 'première Église, née autour des apôtres, avec saint Jacques', 'Jérusalem est la mère des Églises : c''est là que les apôtres se sont réunis après la Pentecôte.', '[{"text": "Saint Jacques est le premier évêque de Jérusalem.", "translation": "On l''appelle le frère du Seigneur."}, {"text": "Les apôtres se réunissent à Jérusalem (Actes 15).", "translation": "La première grande assemblée de l''Église."}]'::jsonb, null, '{"id": "eg.d.siege_de_jerusalem", "word": "le siège de Jérusalem", "translation": "première Église, née autour des apôtres, avec saint Jacques", "partOfSpeech": "organization", "explanation": "Jérusalem est la mère des Églises : c''est là que les apôtres se sont réunis après la Pentecôte.", "examples": [{"text": "Saint Jacques est le premier évêque de Jérusalem.", "translation": "On l''appelle le frère du Seigneur."}, {"text": "Les apôtres se réunissent à Jérusalem (Actes 15).", "translation": "La première grande assemblée de l''Église."}], "unitId": "eg.v.siege_de_jerusalem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pape_d_alexandrie', 'eg', 'le pape d''Alexandrie', 'titre de l''évêque d''Alexandrie, chef de l''Église copte', 'Chez les Coptes, l''évêque d''Alexandrie porte le titre de pape (« père ») depuis l''Antiquité.', '[{"text": "Saint Démétrios est le XIIe pape d''Alexandrie.", "translation": "Il succède à saint Marc par une suite de papes."}, {"text": "Le pape d''Alexandrie est le successeur de saint Marc.", "translation": "Il siège sur le trône de saint Marc."}]'::jsonb, null, '{"id": "eg.d.pape_d_alexandrie", "word": "le pape d''Alexandrie", "translation": "titre de l''évêque d''Alexandrie, chef de l''Église copte", "partOfSpeech": "person", "explanation": "Chez les Coptes, l''évêque d''Alexandrie porte le titre de pape (« père ») depuis l''Antiquité.", "examples": [{"text": "Saint Démétrios est le XIIe pape d''Alexandrie.", "translation": "Il succède à saint Marc par une suite de papes."}, {"text": "Le pape d''Alexandrie est le successeur de saint Marc.", "translation": "Il siège sur le trône de saint Marc."}], "unitId": "eg.v.pape_d_alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.peres_apostoliques', 'eg', 'les Pères apostoliques', 'premiers Pères de l''Église, proches des apôtres', 'On les appelle ainsi car ils ont reçu la tradition directement des apôtres ou de leurs disciples.', '[{"text": "Clément, Ignace et Polycarpe sont des Pères apostoliques.", "translation": "Ils écrivent pour les chrétiens."}, {"text": "Les Pères apostoliques combattent les hérésies.", "translation": "Ils rappellent la foi reçue des apôtres."}]'::jsonb, null, '{"id": "eg.d.peres_apostoliques", "word": "les Pères apostoliques", "translation": "premiers Pères de l''Église, proches des apôtres", "partOfSpeech": "concept", "explanation": "On les appelle ainsi car ils ont reçu la tradition directement des apôtres ou de leurs disciples.", "examples": [{"text": "Clément, Ignace et Polycarpe sont des Pères apostoliques.", "translation": "Ils écrivent pour les chrétiens."}, {"text": "Les Pères apostoliques combattent les hérésies.", "translation": "Ils rappellent la foi reçue des apôtres."}], "unitId": "eg.v.peres_apostoliques"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.clement_de_rome', 'eg', 'Clément de Rome', 'évêque de Rome, auteur d''une lettre aux Corinthiens vers 96', 'Pour calmer les divisions de l''Église de Corinthe, il rappelle que les apôtres ont prévu la relève des évêques.', '[{"text": "Clément écrit aux chrétiens de Corinthe.", "translation": "C''est un évêque de Rome."}, {"text": "Sa lettre est lue dans plusieurs Églises.", "translation": "Elle est l''un des plus anciens écrits chrétiens après le Nouveau Testament."}]'::jsonb, null, '{"id": "eg.d.clement_de_rome", "word": "Clément de Rome", "translation": "évêque de Rome, auteur d''une lettre aux Corinthiens vers 96", "partOfSpeech": "person", "explanation": "Pour calmer les divisions de l''Église de Corinthe, il rappelle que les apôtres ont prévu la relève des évêques.", "examples": [{"text": "Clément écrit aux chrétiens de Corinthe.", "translation": "C''est un évêque de Rome."}, {"text": "Sa lettre est lue dans plusieurs Églises.", "translation": "Elle est l''un des plus anciens écrits chrétiens après le Nouveau Testament."}], "unitId": "eg.v.clement_de_rome"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ignace_d_antioche', 'eg', 'Ignace d''Antioche', 'évêque d''Antioche, martyr à Rome vers 110', 'Il écrit sept lettres en route vers le martyre. Il insiste sur l''unité autour de l''évêque et sur le vrai corps du Christ.', '[{"text": "Ignace est arrêté sous Trajan.", "translation": "Il est conduit à Rome pour être livré aux bêtes."}, {"text": "Ignace combat le docétisme.", "translation": "Pour lui, le Christ a réellement souffert."}]'::jsonb, null, '{"id": "eg.d.ignace_d_antioche", "word": "Ignace d''Antioche", "translation": "évêque d''Antioche, martyr à Rome vers 110", "partOfSpeech": "person", "explanation": "Il écrit sept lettres en route vers le martyre. Il insiste sur l''unité autour de l''évêque et sur le vrai corps du Christ.", "examples": [{"text": "Ignace est arrêté sous Trajan.", "translation": "Il est conduit à Rome pour être livré aux bêtes."}, {"text": "Ignace combat le docétisme.", "translation": "Pour lui, le Christ a réellement souffert."}], "unitId": "eg.v.ignace_d_antioche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.polycarpe_de_smyrne', 'eg', 'Polycarpe de Smyrne', 'évêque de Smyrne, disciple de l''apôtre Jean, martyr', 'Il fait le lien entre l''apôtre Jean et Irénée. Sa lettre aux Philippiens est conservée.', '[{"text": "Polycarpe est disciple de Jean.", "translation": "Il est évêque de Smyrne."}, {"text": "Polycarpe combat Marcion.", "translation": "Il refuse toute doctrine qui nie le Dieu créateur."}]'::jsonb, null, '{"id": "eg.d.polycarpe_de_smyrne", "word": "Polycarpe de Smyrne", "translation": "évêque de Smyrne, disciple de l''apôtre Jean, martyr", "partOfSpeech": "person", "explanation": "Il fait le lien entre l''apôtre Jean et Irénée. Sa lettre aux Philippiens est conservée.", "examples": [{"text": "Polycarpe est disciple de Jean.", "translation": "Il est évêque de Smyrne."}, {"text": "Polycarpe combat Marcion.", "translation": "Il refuse toute doctrine qui nie le Dieu créateur."}], "unitId": "eg.v.polycarpe_de_smyrne"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lettre_aux_corinthiens', 'eg', 'la lettre aux Corinthiens', 'lettre de Clément de Rome aux chrétiens de Corinthe, vers 96', 'Elle rappelle l''ordre établi par les apôtres : des responsables, une relève, l''unité de l''Église.', '[{"text": "Clément y défend les responsables chassés de Corinthe.", "translation": "Il invite à la paix."}, {"text": "La lettre est lue pendant des siècles dans certaines Églises.", "translation": "Preuve de son autorité."}]'::jsonb, null, '{"id": "eg.d.lettre_aux_corinthiens", "word": "la lettre aux Corinthiens", "translation": "lettre de Clément de Rome aux chrétiens de Corinthe, vers 96", "partOfSpeech": "work", "explanation": "Elle rappelle l''ordre établi par les apôtres : des responsables, une relève, l''unité de l''Église.", "examples": [{"text": "Clément y défend les responsables chassés de Corinthe.", "translation": "Il invite à la paix."}, {"text": "La lettre est lue pendant des siècles dans certaines Églises.", "translation": "Preuve de son autorité."}], "unitId": "eg.v.lettre_aux_corinthiens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sept_lettres_d_ignace', 'eg', 'les sept lettres d''Ignace', 'lettres écrites par Ignace d''Antioche pendant son voyage vers Rome', 'Elles parlent de l''unité autour de l''évêque et de la réalité de l''Incarnation.', '[{"text": "Ignace écrit aux Éphésiens, aux Romains et à d''autres Églises.", "translation": "Il écrit en route vers Rome."}, {"text": "Ces lettres combattent le docétisme.", "translation": "Pour Ignace, le Christ est vraiment né et mort."}]'::jsonb, null, '{"id": "eg.d.sept_lettres_d_ignace", "word": "les sept lettres d''Ignace", "translation": "lettres écrites par Ignace d''Antioche pendant son voyage vers Rome", "partOfSpeech": "work", "explanation": "Elles parlent de l''unité autour de l''évêque et de la réalité de l''Incarnation.", "examples": [{"text": "Ignace écrit aux Éphésiens, aux Romains et à d''autres Églises.", "translation": "Il écrit en route vers Rome."}, {"text": "Ces lettres combattent le docétisme.", "translation": "Pour Ignace, le Christ est vraiment né et mort."}], "unitId": "eg.v.sept_lettres_d_ignace"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lettre_aux_philippiens', 'eg', 'la lettre aux Philippiens', 'lettre de Polycarpe de Smyrne aux chrétiens de Philippes', 'Elle exhorte à la fidélité à l''enseignement reçu des apôtres. Elle est reconnue dans la tradition de l''Église.', '[{"text": "Polycarpe écrit aux chrétiens de Philippes.", "translation": "Il leur rappelle l''enseignement des apôtres."}, {"text": "La lettre de Polycarpe est très ancienne.", "translation": "Elle date du IIe siècle."}]'::jsonb, null, '{"id": "eg.d.lettre_aux_philippiens", "word": "la lettre aux Philippiens", "translation": "lettre de Polycarpe de Smyrne aux chrétiens de Philippes", "partOfSpeech": "work", "explanation": "Elle exhorte à la fidélité à l''enseignement reçu des apôtres. Elle est reconnue dans la tradition de l''Église.", "examples": [{"text": "Polycarpe écrit aux chrétiens de Philippes.", "translation": "Il leur rappelle l''enseignement des apôtres."}, {"text": "La lettre de Polycarpe est très ancienne.", "translation": "Elle date du IIe siècle."}], "unitId": "eg.v.lettre_aux_philippiens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.catholique_sens', 'eg', '« catholique » au sens premier', 'universelle, qui s''étend à toute la terre', 'Du grec katholikos, « selon le tout ». Ignace l''emploie pour dire que l''Église est universelle, pas locale.', '[{"text": "Ignace parle de l''Église catholique.", "translation": "Il veut dire l''Église universelle."}, {"text": "Le mot catholique n''est pas réservé à une Église.", "translation": "Il décrit d''abord l''universalité de l''Église."}]'::jsonb, null, '{"id": "eg.d.catholique_sens", "word": "« catholique » au sens premier", "translation": "universelle, qui s''étend à toute la terre", "partOfSpeech": "concept", "explanation": "Du grec katholikos, « selon le tout ». Ignace l''emploie pour dire que l''Église est universelle, pas locale.", "examples": [{"text": "Ignace parle de l''Église catholique.", "translation": "Il veut dire l''Église universelle."}, {"text": "Le mot catholique n''est pas réservé à une Église.", "translation": "Il décrit d''abord l''universalité de l''Église."}], "unitId": "eg.v.catholique_sens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.smyrne', 'eg', 'Smyrne', 'ville de Turquie actuelle, aujourd''hui Izmir', 'Smyrne est l''une des sept Églises de l''Apocalypse. Polycarpe y est évêque.', '[{"text": "Polycarpe est évêque de Smyrne.", "translation": "La ville s''appelle aujourd''hui Izmir."}, {"text": "Smyrne est citée dans l''Apocalypse.", "translation": "Elle fait partie des sept Églises d''Asie."}]'::jsonb, null, '{"id": "eg.d.smyrne", "word": "Smyrne", "translation": "ville de Turquie actuelle, aujourd''hui Izmir", "partOfSpeech": "place", "explanation": "Smyrne est l''une des sept Églises de l''Apocalypse. Polycarpe y est évêque.", "examples": [{"text": "Polycarpe est évêque de Smyrne.", "translation": "La ville s''appelle aujourd''hui Izmir."}, {"text": "Smyrne est citée dans l''Apocalypse.", "translation": "Elle fait partie des sept Églises d''Asie."}], "unitId": "eg.v.smyrne"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.persecution_romaine', 'eg', 'une persécution', 'poursuite violente des chrétiens à cause de leur foi', 'L''Empire punit ceux qui refusent le culte de l''empereur. La tradition compte dix grandes persécutions.', '[{"text": "Trajan ordonne la troisième persécution selon la tradition.", "translation": "Elle commence au début du IIe siècle."}, {"text": "Les persécutions durent par vagues.", "translation": "Elles sont locales, puis générales au IIIe siècle."}]'::jsonb, null, '{"id": "eg.d.persecution_romaine", "word": "une persécution", "translation": "poursuite violente des chrétiens à cause de leur foi", "partOfSpeech": "event", "explanation": "L''Empire punit ceux qui refusent le culte de l''empereur. La tradition compte dix grandes persécutions.", "examples": [{"text": "Trajan ordonne la troisième persécution selon la tradition.", "translation": "Elle commence au début du IIe siècle."}, {"text": "Les persécutions durent par vagues.", "translation": "Elles sont locales, puis générales au IIIe siècle."}], "unitId": "eg.v.persecution_romaine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trajan', 'eg', 'Trajan', 'empereur romain au début du IIe siècle, troisième persécution', 'Il répond à Pline de ne pas rechercher les chrétiens mais de punir ceux qui sont dénoncés.', '[{"text": "Ignace est arrêté sous Trajan.", "translation": "Il est conduit à Rome."}, {"text": "Pline écrit à Trajan.", "translation": "Il lui demande comment traiter les chrétiens."}]'::jsonb, null, '{"id": "eg.d.trajan", "word": "Trajan", "translation": "empereur romain au début du IIe siècle, troisième persécution", "partOfSpeech": "person", "explanation": "Il répond à Pline de ne pas rechercher les chrétiens mais de punir ceux qui sont dénoncés.", "examples": [{"text": "Ignace est arrêté sous Trajan.", "translation": "Il est conduit à Rome."}, {"text": "Pline écrit à Trajan.", "translation": "Il lui demande comment traiter les chrétiens."}], "unitId": "eg.v.trajan"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.marc_aurele', 'eg', 'Marc Aurèle', 'empereur philosophe (161-180), quatrième persécution', 'Empereur stoïcien, il considère les chrétiens comme obstinés. Sous son règne, les martyrs de Lyon meurent en 177.', '[{"text": "Justin est martyrisé sous Marc Aurèle.", "translation": "Vers 165, à Rome."}, {"text": "Marc Aurèle écrit ses Pensées en grec.", "translation": "C''est un empereur philosophe."}]'::jsonb, null, '{"id": "eg.d.marc_aurele", "word": "Marc Aurèle", "translation": "empereur philosophe (161-180), quatrième persécution", "partOfSpeech": "person", "explanation": "Empereur stoïcien, il considère les chrétiens comme obstinés. Sous son règne, les martyrs de Lyon meurent en 177.", "examples": [{"text": "Justin est martyrisé sous Marc Aurèle.", "translation": "Vers 165, à Rome."}, {"text": "Marc Aurèle écrit ses Pensées en grec.", "translation": "C''est un empereur philosophe."}], "unitId": "eg.v.marc_aurele"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.septime_severe', 'eg', 'Septime Sévère', 'empereur romain vers 200, cinquième persécution', 'Il interdit les conversions. Alexandrie est durement frappée, notamment la famille d''Origène.', '[{"text": "Léonidas, père d''Origène, meurt martyr vers 202.", "translation": "Sous Septime Sévère."}, {"text": "La cinquième persécution touche l''Égypte.", "translation": "Alexandrie y voit de nombreux martyrs."}]'::jsonb, null, '{"id": "eg.d.septime_severe", "word": "Septime Sévère", "translation": "empereur romain vers 200, cinquième persécution", "partOfSpeech": "person", "explanation": "Il interdit les conversions. Alexandrie est durement frappée, notamment la famille d''Origène.", "examples": [{"text": "Léonidas, père d''Origène, meurt martyr vers 202.", "translation": "Sous Septime Sévère."}, {"text": "La cinquième persécution touche l''Égypte.", "translation": "Alexandrie y voit de nombreux martyrs."}], "unitId": "eg.v.septime_severe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ichthys', 'eg', 'ICHTHYS (le poisson)', 'mot grec qui signifie poisson, sigle de Jésus Christ Fils de Dieu Sauveur', 'Chaque lettre est l''initiale d''un mot grec. Le poisson devient un signe de reconnaissance entre chrétiens.', '[{"text": "Un chrétien trace un arc dans le sable.", "translation": "L''autre complète le poisson."}, {"text": "Le poisson orne des lampes et des tombes chrétiennes.", "translation": "C''est un symbole ancien."}]'::jsonb, null, '{"id": "eg.d.ichthys", "word": "ICHTHYS (le poisson)", "translation": "mot grec qui signifie poisson, sigle de Jésus Christ Fils de Dieu Sauveur", "partOfSpeech": "concept", "explanation": "Chaque lettre est l''initiale d''un mot grec. Le poisson devient un signe de reconnaissance entre chrétiens.", "examples": [{"text": "Un chrétien trace un arc dans le sable.", "translation": "L''autre complète le poisson."}, {"text": "Le poisson orne des lampes et des tombes chrétiennes.", "translation": "C''est un symbole ancien."}], "unitId": "eg.v.ichthys"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.culte_de_l_empereur', 'eg', 'le culte de l''empereur', 'hommage religieux rendu à l''empereur romain', 'Les citoyens offrent de l''encens devant l''empereur. Les chrétiens refusent : on les accuse d''être mauvais citoyens.', '[{"text": "On demande à Polycarpe de sacrifier à l''empereur.", "translation": "Il refuse."}, {"text": "Refuser le culte de l''empereur est un délit.", "translation": "C''est la cause des persécutions."}]'::jsonb, null, '{"id": "eg.d.culte_de_l_empereur", "word": "le culte de l''empereur", "translation": "hommage religieux rendu à l''empereur romain", "partOfSpeech": "concept", "explanation": "Les citoyens offrent de l''encens devant l''empereur. Les chrétiens refusent : on les accuse d''être mauvais citoyens.", "examples": [{"text": "On demande à Polycarpe de sacrifier à l''empereur.", "translation": "Il refuse."}, {"text": "Refuser le culte de l''empereur est un délit.", "translation": "C''est la cause des persécutions."}], "unitId": "eg.v.culte_de_l_empereur"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.martyrs_de_lyon', 'eg', 'les martyrs de Lyon', 'chrétiens de Lyon morts en 177, dont Pothin et Blandine', 'Leur récit, conservé par Eusèbe, est l''un des plus émouvants du IIe siècle.', '[{"text": "Blandine, esclave, est parmi eux.", "translation": "Elle résiste jusqu''au bout."}, {"text": "Pothin, évêque de Lyon, meurt en 177.", "translation": "Irénée lui succède."}]'::jsonb, null, '{"id": "eg.d.martyrs_de_lyon", "word": "les martyrs de Lyon", "translation": "chrétiens de Lyon morts en 177, dont Pothin et Blandine", "partOfSpeech": "event", "explanation": "Leur récit, conservé par Eusèbe, est l''un des plus émouvants du IIe siècle.", "examples": [{"text": "Blandine, esclave, est parmi eux.", "translation": "Elle résiste jusqu''au bout."}, {"text": "Pothin, évêque de Lyon, meurt en 177.", "translation": "Irénée lui succède."}], "unitId": "eg.v.martyrs_de_lyon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pline_le_jeune', 'eg', 'Pline le Jeune', 'gouverneur de Bithynie qui interroge Trajan vers 112', 'Sa lettre est l''un des plus anciens témoignages romains sur les chrétiens.', '[{"text": "Pline écrit à Trajan pour demander conseil.", "translation": "Il se demande comment juger les chrétiens."}, {"text": "Trajan répond à Pline.", "translation": "Il ne faut pas rechercher les chrétiens."}]'::jsonb, null, '{"id": "eg.d.pline_le_jeune", "word": "Pline le Jeune", "translation": "gouverneur de Bithynie qui interroge Trajan vers 112", "partOfSpeech": "person", "explanation": "Sa lettre est l''un des plus anciens témoignages romains sur les chrétiens.", "examples": [{"text": "Pline écrit à Trajan pour demander conseil.", "translation": "Il se demande comment juger les chrétiens."}, {"text": "Trajan répond à Pline.", "translation": "Il ne faut pas rechercher les chrétiens."}], "unitId": "eg.v.pline_le_jeune"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apologiste', 'eg', 'un apologiste', 'écrivain chrétien qui défend la foi devant les non-chrétiens', 'Du grec apologia, « défense ». Il s''adresse aux empereurs, aux magistrats, aux philosophes.', '[{"text": "Justin est un apologiste.", "translation": "Il écrit à l''empereur pour défendre les chrétiens."}, {"text": "Les apologistes répondent aux accusations des païens.", "translation": "Ils parlent à ceux de l''extérieur."}]'::jsonb, null, '{"id": "eg.d.apologiste", "word": "un apologiste", "translation": "écrivain chrétien qui défend la foi devant les non-chrétiens", "partOfSpeech": "person", "explanation": "Du grec apologia, « défense ». Il s''adresse aux empereurs, aux magistrats, aux philosophes.", "examples": [{"text": "Justin est un apologiste.", "translation": "Il écrit à l''empereur pour défendre les chrétiens."}, {"text": "Les apologistes répondent aux accusations des païens.", "translation": "Ils parlent à ceux de l''extérieur."}], "unitId": "eg.v.apologiste"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.paganisme', 'eg', 'le paganisme', 'religion traditionnelle de l''Empire romain, avec de nombreux dieux', 'Temples, sacrifices, culte de l''empereur : les chrétiens ne participent pas à ces rites.', '[{"text": "Les apologistes combattent le paganisme.", "translation": "Ils critiquent les idoles."}, {"text": "Les païens accusent les chrétiens d''athéisme.", "translation": "Car ils n''adorent pas leurs dieux."}]'::jsonb, null, '{"id": "eg.d.paganisme", "word": "le paganisme", "translation": "religion traditionnelle de l''Empire romain, avec de nombreux dieux", "partOfSpeech": "concept", "explanation": "Temples, sacrifices, culte de l''empereur : les chrétiens ne participent pas à ces rites.", "examples": [{"text": "Les apologistes combattent le paganisme.", "translation": "Ils critiquent les idoles."}, {"text": "Les païens accusent les chrétiens d''athéisme.", "translation": "Car ils n''adorent pas leurs dieux."}], "unitId": "eg.v.paganisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.justin_martyr', 'eg', 'Justin Martyr', 'philosophe converti, apologiste, martyr à Rome vers 165', 'Il écrit les Apologies et le Dialogue avec Tryphon. Il est décapité à Rome.', '[{"text": "Justin vient de Naplouse en Palestine.", "translation": "Il enseigne à Rome."}, {"text": "Justin voit dans les philosophes des semences du Verbe.", "translation": "Le Christ est le couronnement de leur quête."}]'::jsonb, null, '{"id": "eg.d.justin_martyr", "word": "Justin Martyr", "translation": "philosophe converti, apologiste, martyr à Rome vers 165", "partOfSpeech": "person", "explanation": "Il écrit les Apologies et le Dialogue avec Tryphon. Il est décapité à Rome.", "examples": [{"text": "Justin vient de Naplouse en Palestine.", "translation": "Il enseigne à Rome."}, {"text": "Justin voit dans les philosophes des semences du Verbe.", "translation": "Le Christ est le couronnement de leur quête."}], "unitId": "eg.v.justin_martyr"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tertullien', 'eg', 'Tertullien', 'premier grand auteur chrétien latin, de Carthage', 'Juriste, auteur de l''Apologétique et de Contre Marcion. Il rejoint plus tard le montanisme.', '[{"text": "Tertullien vit à Carthage.", "translation": "Il écrit en latin."}, {"text": "Tertullien combat Marcion.", "translation": "Il écrit cinq livres contre lui."}]'::jsonb, null, '{"id": "eg.d.tertullien", "word": "Tertullien", "translation": "premier grand auteur chrétien latin, de Carthage", "partOfSpeech": "person", "explanation": "Juriste, auteur de l''Apologétique et de Contre Marcion. Il rejoint plus tard le montanisme.", "examples": [{"text": "Tertullien vit à Carthage.", "translation": "Il écrit en latin."}, {"text": "Tertullien combat Marcion.", "translation": "Il écrit cinq livres contre lui."}], "unitId": "eg.v.tertullien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apologetique', 'eg', 'l''Apologétique', 'œuvre de Tertullien écrite en 197 pour défendre les chrétiens', 'Elle s''adresse aux magistrats romains et contient la phrase sur le sang des martyrs.', '[{"text": "L''Apologétique est écrite en 197.", "translation": "Elle défend les chrétiens devant les magistrats."}, {"text": "Tertullien y écrit une phrase célèbre.", "translation": "Le sang des martyrs est une semence de chrétiens."}]'::jsonb, null, '{"id": "eg.d.apologetique", "word": "l''Apologétique", "translation": "œuvre de Tertullien écrite en 197 pour défendre les chrétiens", "partOfSpeech": "work", "explanation": "Elle s''adresse aux magistrats romains et contient la phrase sur le sang des martyrs.", "examples": [{"text": "L''Apologétique est écrite en 197.", "translation": "Elle défend les chrétiens devant les magistrats."}, {"text": "Tertullien y écrit une phrase célèbre.", "translation": "Le sang des martyrs est une semence de chrétiens."}], "unitId": "eg.v.apologetique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dialogue_avec_tryphon', 'eg', 'le Dialogue avec Tryphon', 'œuvre de Justin : débat avec un Juif sur Jésus et l''Ancien Testament', 'Justin montre que les Écritures annoncent le Christ.', '[{"text": "Tryphon est un Juif.", "translation": "Justin discute avec lui."}, {"text": "Le Dialogue défend la foi devant un Juif.", "translation": "L''Apologie la défend devant un empereur."}]'::jsonb, null, '{"id": "eg.d.dialogue_avec_tryphon", "word": "le Dialogue avec Tryphon", "translation": "œuvre de Justin : débat avec un Juif sur Jésus et l''Ancien Testament", "partOfSpeech": "work", "explanation": "Justin montre que les Écritures annoncent le Christ.", "examples": [{"text": "Tryphon est un Juif.", "translation": "Justin discute avec lui."}, {"text": "Le Dialogue défend la foi devant un Juif.", "translation": "L''Apologie la défend devant un empereur."}], "unitId": "eg.v.dialogue_avec_tryphon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.semences_du_verbe', 'eg', 'les semences du Verbe', 'idée de Justin : les philosophes ont entrevu une part de la vérité du Christ', 'Le Verbe (Logos) éclaire tous les hommes. Le christianisme possède la vérité entière.', '[{"text": "Socrate a entrevu la vérité selon Justin.", "translation": "Comme une graine du Verbe."}, {"text": "Le Christ est le couronnement de la quête des sages.", "translation": "C''est la thèse de Justin."}]'::jsonb, null, '{"id": "eg.d.semences_du_verbe", "word": "les semences du Verbe", "translation": "idée de Justin : les philosophes ont entrevu une part de la vérité du Christ", "partOfSpeech": "concept", "explanation": "Le Verbe (Logos) éclaire tous les hommes. Le christianisme possède la vérité entière.", "examples": [{"text": "Socrate a entrevu la vérité selon Justin.", "translation": "Comme une graine du Verbe."}, {"text": "Le Christ est le couronnement de la quête des sages.", "translation": "C''est la thèse de Justin."}], "unitId": "eg.v.semences_du_verbe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sang_des_martyrs', 'eg', 'le sang des martyrs', 'formule de Tertullien : le courage des martyrs fait naître de nouveaux chrétiens', 'Plus on tue de chrétiens, plus on en voit naître : leur courage interroge les témoins.', '[{"text": "« Le sang des martyrs est une semence de chrétiens. »", "translation": "C''est une phrase de Tertullien."}, {"text": "Le martyre devient un témoignage.", "translation": "Les païens s''interrogent."}]'::jsonb, null, '{"id": "eg.d.sang_des_martyrs", "word": "le sang des martyrs", "translation": "formule de Tertullien : le courage des martyrs fait naître de nouveaux chrétiens", "partOfSpeech": "concept", "explanation": "Plus on tue de chrétiens, plus on en voit naître : leur courage interroge les témoins.", "examples": [{"text": "« Le sang des martyrs est une semence de chrétiens. »", "translation": "C''est une phrase de Tertullien."}, {"text": "Le martyre devient un témoignage.", "translation": "Les païens s''interrogent."}], "unitId": "eg.v.sang_des_martyrs"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.gnose', 'eg', 'la gnose', 'connaissance secrète censée sauver (du grec gnosis)', 'Pour les gnostiques, la connaissance libère l''âme de la matière. Pour l''Église, c''est la foi qui sauve.', '[{"text": "La gnose est réservée à une élite.", "translation": "Les « spirituels » sont sauvés par elle."}, {"text": "Gnosis veut dire connaissance.", "translation": "Le mot a donné gnosticisme."}]'::jsonb, null, '{"id": "eg.d.gnose", "word": "la gnose", "translation": "connaissance secrète censée sauver (du grec gnosis)", "partOfSpeech": "concept", "explanation": "Pour les gnostiques, la connaissance libère l''âme de la matière. Pour l''Église, c''est la foi qui sauve.", "examples": [{"text": "La gnose est réservée à une élite.", "translation": "Les « spirituels » sont sauvés par elle."}, {"text": "Gnosis veut dire connaissance.", "translation": "Le mot a donné gnosticisme."}], "unitId": "eg.v.gnose"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.demiurge', 'eg', 'le démiurge', 'dieu inférieur qui aurait créé le monde matériel selon les gnostiques', 'Du grec demiourgos, « artisan ». Pour les gnostiques, il est distinct du vrai Dieu et le monde est son œuvre imparfaite.', '[{"text": "Le démiurge crée la matière, selon les gnostiques.", "translation": "L''Église répond que le monde vient du Dieu unique."}, {"text": "Le démiurge est un dieu inférieur.", "translation": "Le vrai Dieu reste étranger au monde pour les gnostiques."}]'::jsonb, null, '{"id": "eg.d.demiurge", "word": "le démiurge", "translation": "dieu inférieur qui aurait créé le monde matériel selon les gnostiques", "partOfSpeech": "concept", "explanation": "Du grec demiourgos, « artisan ». Pour les gnostiques, il est distinct du vrai Dieu et le monde est son œuvre imparfaite.", "examples": [{"text": "Le démiurge crée la matière, selon les gnostiques.", "translation": "L''Église répond que le monde vient du Dieu unique."}, {"text": "Le démiurge est un dieu inférieur.", "translation": "Le vrai Dieu reste étranger au monde pour les gnostiques."}], "unitId": "eg.v.demiurge"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.valentin', 'eg', 'Valentin', 'maître gnostique, enseigne à Alexandrie puis à Rome', 'Né en Égypte, il enseigne à Alexandrie puis à Rome au IIe siècle et fonde une grande école gnostique.', '[{"text": "Valentin est un maître gnostique égyptien.", "translation": "Il passe par Alexandrie."}, {"text": "Ses disciples forment l''école valentinienne.", "translation": "Irénée la combat."}]'::jsonb, null, '{"id": "eg.d.valentin", "word": "Valentin", "translation": "maître gnostique, enseigne à Alexandrie puis à Rome", "partOfSpeech": "person", "explanation": "Né en Égypte, il enseigne à Alexandrie puis à Rome au IIe siècle et fonde une grande école gnostique.", "examples": [{"text": "Valentin est un maître gnostique égyptien.", "translation": "Il passe par Alexandrie."}, {"text": "Ses disciples forment l''école valentinienne.", "translation": "Irénée la combat."}], "unitId": "eg.v.valentin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.basilide', 'eg', 'Basilide', 'maître gnostique d''Alexandrie', 'Il enseigne à Alexandrie au IIe siècle ; Irénée lui attribue l''histoire de Simon de Cyrène crucifié à la place du Christ.', '[{"text": "Basilide enseigne à Alexandrie.", "translation": "Il est un docète."}, {"text": "Irénée rapporte ses idées.", "translation": "Pour mieux les réfuter."}]'::jsonb, null, '{"id": "eg.d.basilide", "word": "Basilide", "translation": "maître gnostique d''Alexandrie", "partOfSpeech": "person", "explanation": "Il enseigne à Alexandrie au IIe siècle ; Irénée lui attribue l''histoire de Simon de Cyrène crucifié à la place du Christ.", "examples": [{"text": "Basilide enseigne à Alexandrie.", "translation": "Il est un docète."}, {"text": "Irénée rapporte ses idées.", "translation": "Pour mieux les réfuter."}], "unitId": "eg.v.basilide"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.irenee_de_lyon', 'eg', 'Irénée de Lyon', 'évêque de Lyon, disciple de Polycarpe, auteur de Contre les hérésies', 'Il relie Jean à Lyon par Polycarpe. Il réfute le gnosticisme avec la succession des évêques.', '[{"text": "Irénée est le disciple de Polycarpe.", "translation": "Il devient évêque de Lyon après Pothin."}, {"text": "Irénée écrit vers 180.", "translation": "Son œuvre contre les gnostiques est un classique."}]'::jsonb, null, '{"id": "eg.d.irenee_de_lyon", "word": "Irénée de Lyon", "translation": "évêque de Lyon, disciple de Polycarpe, auteur de Contre les hérésies", "partOfSpeech": "person", "explanation": "Il relie Jean à Lyon par Polycarpe. Il réfute le gnosticisme avec la succession des évêques.", "examples": [{"text": "Irénée est le disciple de Polycarpe.", "translation": "Il devient évêque de Lyon après Pothin."}, {"text": "Irénée écrit vers 180.", "translation": "Son œuvre contre les gnostiques est un classique."}], "unitId": "eg.v.irenee_de_lyon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.contre_les_heresies', 'eg', 'Contre les hérésies', 'œuvre d''Irénée de Lyon (vers 180) qui réfute le gnosticisme', 'Irénée y oppose l''enseignement public des évêques, reçu des apôtres, aux doctrines secrètes des gnostiques.', '[{"text": "Irénée écrit Contre les hérésies vers 180.", "translation": "C''est sa plus grande œuvre."}, {"text": "Le livre expose puis réfute les idées gnostiques.", "translation": "Il reste une source précieuse."}]'::jsonb, null, '{"id": "eg.d.contre_les_heresies", "word": "Contre les hérésies", "translation": "œuvre d''Irénée de Lyon (vers 180) qui réfute le gnosticisme", "partOfSpeech": "work", "explanation": "Irénée y oppose l''enseignement public des évêques, reçu des apôtres, aux doctrines secrètes des gnostiques.", "examples": [{"text": "Irénée écrit Contre les hérésies vers 180.", "translation": "C''est sa plus grande œuvre."}, {"text": "Le livre expose puis réfute les idées gnostiques.", "translation": "Il reste une source précieuse."}], "unitId": "eg.v.contre_les_heresies"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nag_hammadi', 'eg', 'Nag Hammadi', 'lieu de Haute-Égypte où une bibliothèque gnostique est retrouvée en 1945', 'On y a découvert des textes gnostiques en copte, enterrés dans des jarres.', '[{"text": "Nag Hammadi est en Haute-Égypte.", "translation": "On y découvre des manuscrits en 1945."}, {"text": "Les textes de Nag Hammadi sont écrits en copte.", "translation": "Ils montrent la diversité des gnostiques."}]'::jsonb, null, '{"id": "eg.d.nag_hammadi", "word": "Nag Hammadi", "translation": "lieu de Haute-Égypte où une bibliothèque gnostique est retrouvée en 1945", "partOfSpeech": "place", "explanation": "On y a découvert des textes gnostiques en copte, enterrés dans des jarres.", "examples": [{"text": "Nag Hammadi est en Haute-Égypte.", "translation": "On y découvre des manuscrits en 1945."}, {"text": "Les textes de Nag Hammadi sont écrits en copte.", "translation": "Ils montrent la diversité des gnostiques."}], "unitId": "eg.v.nag_hammadi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.marcion', 'eg', 'Marcion', 'armateur de Sinope, exclu de l''Église de Rome vers 144', 'Il rejette l''Ancien Testament et ne garde que Luc et dix lettres de Paul. Polycarpe et Tertullien le combattent.', '[{"text": "Marcion vient de Sinope.", "translation": "Il est exclu à Rome vers 144."}, {"text": "Marcion sépare le Dieu de justice du Dieu d''amour.", "translation": "Il rejette l''Ancien Testament."}]'::jsonb, null, '{"id": "eg.d.marcion", "word": "Marcion", "translation": "armateur de Sinope, exclu de l''Église de Rome vers 144", "partOfSpeech": "person", "explanation": "Il rejette l''Ancien Testament et ne garde que Luc et dix lettres de Paul. Polycarpe et Tertullien le combattent.", "examples": [{"text": "Marcion vient de Sinope.", "translation": "Il est exclu à Rome vers 144."}, {"text": "Marcion sépare le Dieu de justice du Dieu d''amour.", "translation": "Il rejette l''Ancien Testament."}], "unitId": "eg.v.marcion"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.marcionisme', 'eg', 'le marcionisme', 'hérésie qui oppose le Dieu de l''Ancien Testament au Dieu d''amour du Nouveau', 'Il prétend que le Dieu créateur n''est pas le Père de Jésus. Il retire presque toute l''Écriture.', '[{"text": "Le marcionisme rejette l''Ancien Testament.", "translation": "Il ne garde que Luc et Paul."}, {"text": "Tertullien écrit Contre Marcion.", "translation": "Il défend l''unité des deux Testaments."}]'::jsonb, null, '{"id": "eg.d.marcionisme", "word": "le marcionisme", "translation": "hérésie qui oppose le Dieu de l''Ancien Testament au Dieu d''amour du Nouveau", "partOfSpeech": "concept", "explanation": "Il prétend que le Dieu créateur n''est pas le Père de Jésus. Il retire presque toute l''Écriture.", "examples": [{"text": "Le marcionisme rejette l''Ancien Testament.", "translation": "Il ne garde que Luc et Paul."}, {"text": "Tertullien écrit Contre Marcion.", "translation": "Il défend l''unité des deux Testaments."}], "unitId": "eg.v.marcionisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.montanus', 'eg', 'Montanus', 'prophète phrygien qui se dit porte-parole du Paraclet vers 170', 'Il annonce l''âge de l''Esprit et la fin des temps imminente. Ses prophétesses sont Priscilla et Maximilla.', '[{"text": "Montanus vit en Phrygie.", "translation": "Il parle en transe."}, {"text": "Montanus se dit l''organe du Paraclet.", "translation": "L''Église refuse sa prétention."}]'::jsonb, null, '{"id": "eg.d.montanus", "word": "Montanus", "translation": "prophète phrygien qui se dit porte-parole du Paraclet vers 170", "partOfSpeech": "person", "explanation": "Il annonce l''âge de l''Esprit et la fin des temps imminente. Ses prophétesses sont Priscilla et Maximilla.", "examples": [{"text": "Montanus vit en Phrygie.", "translation": "Il parle en transe."}, {"text": "Montanus se dit l''organe du Paraclet.", "translation": "L''Église refuse sa prétention."}], "unitId": "eg.v.montanus"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.montanisme', 'eg', 'le montanisme', 'mouvement de la « nouvelle prophétie », fin des temps et rigueur extrême', 'Il prône la continence parfaite et la recherche du martyre. Il a fini par disparaître.', '[{"text": "Le montanisme annonce l''âge de l''Esprit.", "translation": "Il se veut plus pur que l''Église."}, {"text": "Tertullien a rejoint le montanisme.", "translation": "Il l''a quitté après quelques années."}]'::jsonb, null, '{"id": "eg.d.montanisme", "word": "le montanisme", "translation": "mouvement de la « nouvelle prophétie », fin des temps et rigueur extrême", "partOfSpeech": "concept", "explanation": "Il prône la continence parfaite et la recherche du martyre. Il a fini par disparaître.", "examples": [{"text": "Le montanisme annonce l''âge de l''Esprit.", "translation": "Il se veut plus pur que l''Église."}, {"text": "Tertullien a rejoint le montanisme.", "translation": "Il l''a quitté après quelques années."}], "unitId": "eg.v.montanisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.paraclet', 'eg', 'le Paraclet', 'nom de l''Esprit Saint dans l''Évangile de Jean : le Consolateur, le Défenseur', 'Du grec paraklêtos. Jésus annonce l''envoi du Paraclet (Jean 14, 26). Montanus prétend être son porte-parole.', '[{"text": "Jésus promet le Paraclet à ses disciples.", "translation": "C''est l''Esprit Saint."}, {"text": "Montanus se dit organe du Paraclet.", "translation": "L''Église refuse cette prétention."}]'::jsonb, null, '{"id": "eg.d.paraclet", "word": "le Paraclet", "translation": "nom de l''Esprit Saint dans l''Évangile de Jean : le Consolateur, le Défenseur", "partOfSpeech": "concept", "explanation": "Du grec paraklêtos. Jésus annonce l''envoi du Paraclet (Jean 14, 26). Montanus prétend être son porte-parole.", "examples": [{"text": "Jésus promet le Paraclet à ses disciples.", "translation": "C''est l''Esprit Saint."}, {"text": "Montanus se dit organe du Paraclet.", "translation": "L''Église refuse cette prétention."}], "unitId": "eg.v.paraclet"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.priscilla_et_maximilla', 'eg', 'Priscilla et Maximilla', 'deux prophétesses qui accompagnent Montanus', 'Elles prophétisent en transe, comme Montanus. L''Église ne reconnaît pas leurs oracles.', '[{"text": "Priscilla et Maximilla accompagnent Montanus.", "translation": "Elles sont prophétesses."}, {"text": "Leurs oracles annoncent la fin des temps.", "translation": "L''Église les refuse."}]'::jsonb, null, '{"id": "eg.d.priscilla_et_maximilla", "word": "Priscilla et Maximilla", "translation": "deux prophétesses qui accompagnent Montanus", "partOfSpeech": "person", "explanation": "Elles prophétisent en transe, comme Montanus. L''Église ne reconnaît pas leurs oracles.", "examples": [{"text": "Priscilla et Maximilla accompagnent Montanus.", "translation": "Elles sont prophétesses."}, {"text": "Leurs oracles annoncent la fin des temps.", "translation": "L''Église les refuse."}], "unitId": "eg.v.priscilla_et_maximilla"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.millenarisme', 'eg', 'le millénarisme', 'croyance en un règne du Christ de mille ans avec les élus avant la fin', 'Les montanistes l''enseignent : la fin est proche et la Jérusalem nouvelle va descendre.', '[{"text": "Le millénarisme annonce un règne de mille ans.", "translation": "Il se fonde sur l''Apocalypse."}, {"text": "Les montanistes sont millénaristes.", "translation": "Ils attendent la fin des temps."}]'::jsonb, null, '{"id": "eg.d.millenarisme", "word": "le millénarisme", "translation": "croyance en un règne du Christ de mille ans avec les élus avant la fin", "partOfSpeech": "concept", "explanation": "Les montanistes l''enseignent : la fin est proche et la Jérusalem nouvelle va descendre.", "examples": [{"text": "Le millénarisme annonce un règne de mille ans.", "translation": "Il se fonde sur l''Apocalypse."}, {"text": "Les montanistes sont millénaristes.", "translation": "Ils attendent la fin des temps."}], "unitId": "eg.v.millenarisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.rigorisme', 'eg', 'le rigorisme', 'exigence morale extrême, au-delà de ce que l''Église demande à tous', 'Continence parfaite, jeûnes lourds, recherche du martyre : les montanistes dépassent la mesure.', '[{"text": "Le montanisme prône la continence parfaite.", "translation": "C''est du rigorisme."}, {"text": "L''Église enseigne la mesure.", "translation": "Elle n''impose pas de chercher le martyre."}]'::jsonb, null, '{"id": "eg.d.rigorisme", "word": "le rigorisme", "translation": "exigence morale extrême, au-delà de ce que l''Église demande à tous", "partOfSpeech": "concept", "explanation": "Continence parfaite, jeûnes lourds, recherche du martyre : les montanistes dépassent la mesure.", "examples": [{"text": "Le montanisme prône la continence parfaite.", "translation": "C''est du rigorisme."}, {"text": "L''Église enseigne la mesure.", "translation": "Elle n''impose pas de chercher le martyre."}], "unitId": "eg.v.rigorisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.canon_des_ecritures', 'eg', 'le canon des Écritures', 'liste des livres reconnus par l''Église comme inspirés', 'Du grec kanôn, « règle ». Marcion a poussé l''Église à préciser sa liste.', '[{"text": "Le canon exclut les écrits des hérétiques.", "translation": "Il retient ceux d''origine apostolique."}, {"text": "En 367, Athanase donne la liste des 27 livres du Nouveau Testament.", "translation": "Alexandrie y joue un rôle central."}]'::jsonb, null, '{"id": "eg.d.canon_des_ecritures", "word": "le canon des Écritures", "translation": "liste des livres reconnus par l''Église comme inspirés", "partOfSpeech": "concept", "explanation": "Du grec kanôn, « règle ». Marcion a poussé l''Église à préciser sa liste.", "examples": [{"text": "Le canon exclut les écrits des hérétiques.", "translation": "Il retient ceux d''origine apostolique."}, {"text": "En 367, Athanase donne la liste des 27 livres du Nouveau Testament.", "translation": "Alexandrie y joue un rôle central."}], "unitId": "eg.v.canon_des_ecritures"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.regle_de_foi', 'eg', 'la règle de foi', 'résumé de la foi reçue au baptême, racine du Credo', 'Un seul Dieu, le Christ vraiment homme, mort et ressuscité, l''Esprit. Elle donne la clé de lecture des Écritures.', '[{"text": "La règle de foi précède le Credo.", "translation": "Elle est confessée au baptême."}, {"text": "Irénée la compare au plan de la mosaïque.", "translation": "Les hérétiques déplacent les pierres."}]'::jsonb, null, '{"id": "eg.d.regle_de_foi", "word": "la règle de foi", "translation": "résumé de la foi reçue au baptême, racine du Credo", "partOfSpeech": "concept", "explanation": "Un seul Dieu, le Christ vraiment homme, mort et ressuscité, l''Esprit. Elle donne la clé de lecture des Écritures.", "examples": [{"text": "La règle de foi précède le Credo.", "translation": "Elle est confessée au baptême."}, {"text": "Irénée la compare au plan de la mosaïque.", "translation": "Les hérétiques déplacent les pierres."}], "unitId": "eg.v.regle_de_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.fragment_de_muratori', 'eg', 'le Fragment de Muratori', 'ancienne liste romaine de livres du Nouveau Testament (vers 170-200)', 'Il montre que, dès le IIe siècle, les Évangiles et les lettres de Paul sont reçus à Rome.', '[{"text": "Le Fragment de Muratori date de vers 170-200.", "translation": "Il vient de Rome."}, {"text": "Il cite les quatre Évangiles.", "translation": "C''est une des plus anciennes listes."}]'::jsonb, null, '{"id": "eg.d.fragment_de_muratori", "word": "le Fragment de Muratori", "translation": "ancienne liste romaine de livres du Nouveau Testament (vers 170-200)", "partOfSpeech": "work", "explanation": "Il montre que, dès le IIe siècle, les Évangiles et les lettres de Paul sont reçus à Rome.", "examples": [{"text": "Le Fragment de Muratori date de vers 170-200.", "translation": "Il vient de Rome."}, {"text": "Il cite les quatre Évangiles.", "translation": "C''est une des plus anciennes listes."}], "unitId": "eg.v.fragment_de_muratori"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_demetrios', 'eg', 'saint Démétrios', 'XIIe pape d''Alexandrie, élu en 189, surnommé le vigneron', 'Selon la tradition, un paysan illettré qui reçut la grâce d''apprendre. Il organise le calendrier des fêtes et soutient l''école.', '[{"text": "Démétrios est élu en 189.", "translation": "Il est le XIIe pape d''Alexandrie."}, {"text": "La grappe de raisin lui vaut son surnom.", "translation": "Il est le vigneron."}]'::jsonb, null, '{"id": "eg.d.saint_demetrios", "word": "saint Démétrios", "translation": "XIIe pape d''Alexandrie, élu en 189, surnommé le vigneron", "partOfSpeech": "person", "explanation": "Selon la tradition, un paysan illettré qui reçut la grâce d''apprendre. Il organise le calendrier des fêtes et soutient l''école.", "examples": [{"text": "Démétrios est élu en 189.", "translation": "Il est le XIIe pape d''Alexandrie."}, {"text": "La grappe de raisin lui vaut son surnom.", "translation": "Il est le vigneron."}], "unitId": "eg.v.saint_demetrios"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.date_de_paques', 'eg', 'la date de Pâques', 'controverse du IIe siècle sur le jour où fêter la Résurrection', 'Certains fêtent le 14 Nisan, d''autres le dimanche suivant. Alexandrie fixe des règles de calcul.', '[{"text": "Polycarpe discute de Pâques à Rome vers 155.", "translation": "Sans rupture."}, {"text": "La querelle reprend vers 190.", "translation": "Démétrios y prend part."}]'::jsonb, null, '{"id": "eg.d.date_de_paques", "word": "la date de Pâques", "translation": "controverse du IIe siècle sur le jour où fêter la Résurrection", "partOfSpeech": "event", "explanation": "Certains fêtent le 14 Nisan, d''autres le dimanche suivant. Alexandrie fixe des règles de calcul.", "examples": [{"text": "Polycarpe discute de Pâques à Rome vers 155.", "translation": "Sans rupture."}, {"text": "La querelle reprend vers 190.", "translation": "Démétrios y prend part."}], "unitId": "eg.v.date_de_paques"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.quatorze_nisan', 'eg', 'le 14 Nisan', 'date juive de la Pâque, suivie par certaines Églises d''Asie Mineure', 'Les Églises d''Asie Mineure fêtent Pâques le 14 Nisan, quel que soit le jour de la semaine.', '[{"text": "Polycarpe suit l''usage du 14 Nisan.", "translation": "Il le tient de l''apôtre Jean."}, {"text": "Rome et Alexandrie fêtent le dimanche suivant.", "translation": "Cela évite de célébrer un jour de semaine."}]'::jsonb, null, '{"id": "eg.d.quatorze_nisan", "word": "le 14 Nisan", "translation": "date juive de la Pâque, suivie par certaines Églises d''Asie Mineure", "partOfSpeech": "date", "explanation": "Les Églises d''Asie Mineure fêtent Pâques le 14 Nisan, quel que soit le jour de la semaine.", "examples": [{"text": "Polycarpe suit l''usage du 14 Nisan.", "translation": "Il le tient de l''apôtre Jean."}, {"text": "Rome et Alexandrie fêtent le dimanche suivant.", "translation": "Cela évite de célébrer un jour de semaine."}], "unitId": "eg.v.quatorze_nisan"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.epacte', 'eg', 'l''épacte', 'calcul lunaire utilisé à Alexandrie pour fixer la date de Pâques et du carême', 'Alexandrie, ville d''astronomes, perfectionne ce calcul que Démétrios promeut.', '[{"text": "Démétrios promeut le calcul de l''épacte.", "translation": "Il en fait la base du carême."}, {"text": "L''épacte relie le calendrier solaire au lunaire.", "translation": "C''est un calcul d''astronomes."}]'::jsonb, null, '{"id": "eg.d.epacte", "word": "l''épacte", "translation": "calcul lunaire utilisé à Alexandrie pour fixer la date de Pâques et du carême", "partOfSpeech": "concept", "explanation": "Alexandrie, ville d''astronomes, perfectionne ce calcul que Démétrios promeut.", "examples": [{"text": "Démétrios promeut le calcul de l''épacte.", "translation": "Il en fait la base du carême."}, {"text": "L''épacte relie le calendrier solaire au lunaire.", "translation": "C''est un calcul d''astronomes."}], "unitId": "eg.v.epacte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.edit_imperial', 'eg', 'l''édit impérial', 'ordre officiel de l''empereur, ici d''honorer les dieux et de sacrifier', 'Un édit est une décision publique de l''empereur. Il était plus ou moins appliqué au niveau local.', '[{"text": "Un édit appelle chaque citoyen à sacrifier.", "translation": "Celui qui refuse risque des poursuites."}, {"text": "L''application d''un édit dépend du gouverneur de la ville.", "translation": "D''où des persécutions inégales selon les régions."}]'::jsonb, null, '{"id": "eg.d.edit_imperial", "word": "l''édit impérial", "translation": "ordre officiel de l''empereur, ici d''honorer les dieux et de sacrifier", "partOfSpeech": "concept", "explanation": "Un édit est une décision publique de l''empereur. Il était plus ou moins appliqué au niveau local.", "examples": [{"text": "Un édit appelle chaque citoyen à sacrifier.", "translation": "Celui qui refuse risque des poursuites."}, {"text": "L''application d''un édit dépend du gouverneur de la ville.", "translation": "D''où des persécutions inégales selon les régions."}], "unitId": "eg.v.edit_imperial"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.anthropophagie', 'eg', 'l''anthropophagie', 'accusation de manger de la chair humaine', 'C''est une rumeur fausse contre les chrétiens, née d''un malentendu sur le corps et le sang du Christ.', '[{"text": "Les foules les accusent d''anthropophagie.", "translation": "Le secret nourrit ce genre de rumeur."}, {"text": "Cette accusation est fausse.", "translation": "Elle sert à justifier la colère populaire."}]'::jsonb, null, '{"id": "eg.d.anthropophagie", "word": "l''anthropophagie", "translation": "accusation de manger de la chair humaine", "partOfSpeech": "concept", "explanation": "C''est une rumeur fausse contre les chrétiens, née d''un malentendu sur le corps et le sang du Christ.", "examples": [{"text": "Les foules les accusent d''anthropophagie.", "translation": "Le secret nourrit ce genre de rumeur."}, {"text": "Cette accusation est fausse.", "translation": "Elle sert à justifier la colère populaire."}], "unitId": "eg.v.anthropophagie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.accusation_atheisme', 'eg', 'l''accusation d''athéisme', 'reproche des philosophes : les chrétiens n''adorent aucun des dieux de l''Empire', 'Sans statues ni temples païens, les chrétiens paraissaient sans dieu. D''où le mot « athées ».', '[{"text": "Les philosophes les traitent d''athées.", "translation": "Ils rejettent les dieux de l''Empire."}, {"text": "Le chrétien est accusé de n''avoir aucun dieu.", "translation": "En réalité, il adore le seul vrai Dieu."}]'::jsonb, null, '{"id": "eg.d.accusation_atheisme", "word": "l''accusation d''athéisme", "translation": "reproche des philosophes : les chrétiens n''adorent aucun des dieux de l''Empire", "partOfSpeech": "concept", "explanation": "Sans statues ni temples païens, les chrétiens paraissaient sans dieu. D''où le mot « athées ».", "examples": [{"text": "Les philosophes les traitent d''athées.", "translation": "Ils rejettent les dieux de l''Empire."}, {"text": "Le chrétien est accusé de n''avoir aucun dieu.", "translation": "En réalité, il adore le seul vrai Dieu."}], "unitId": "eg.v.accusation_atheisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.meurtre_rituel', 'eg', 'le meurtre rituel', 'accusation de tuer en secret dans des cérémonies', 'Rumeur fausse qui accompagne l''anthropophagie : on imagine des crimes derrière les portes closes.', '[{"text": "On les accuse de meurtre rituel.", "translation": "C''est une rumeur."}, {"text": "Le secret nourrit l''imagination de la foule.", "translation": "Personne n''a jamais prouvé ces crimes."}]'::jsonb, null, '{"id": "eg.d.meurtre_rituel", "word": "le meurtre rituel", "translation": "accusation de tuer en secret dans des cérémonies", "partOfSpeech": "concept", "explanation": "Rumeur fausse qui accompagne l''anthropophagie : on imagine des crimes derrière les portes closes.", "examples": [{"text": "On les accuse de meurtre rituel.", "translation": "C''est une rumeur."}, {"text": "Le secret nourrit l''imagination de la foule.", "translation": "Personne n''a jamais prouvé ces crimes."}], "unitId": "eg.v.meurtre_rituel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.mauvais_citoyens', 'eg', 'les mauvais citoyens', 'aux yeux de Rome, ceux qui refusent le culte civique et les sacrifices publics', 'Pour l''Empire, être loyal, c''est participer au culte. Les chrétiens qui refusent passent pour déloyaux.', '[{"text": "Les autorités les prennent pour de mauvais citoyens.", "translation": "Ils ne sacrifient pas."}, {"text": "Ce soupçon vise leur loyauté, pas leur morale.", "translation": "Dans l''Empire, religion et politique sont liées."}]'::jsonb, null, '{"id": "eg.d.mauvais_citoyens", "word": "les mauvais citoyens", "translation": "aux yeux de Rome, ceux qui refusent le culte civique et les sacrifices publics", "partOfSpeech": "concept", "explanation": "Pour l''Empire, être loyal, c''est participer au culte. Les chrétiens qui refusent passent pour déloyaux.", "examples": [{"text": "Les autorités les prennent pour de mauvais citoyens.", "translation": "Ils ne sacrifient pas."}, {"text": "Ce soupçon vise leur loyauté, pas leur morale.", "translation": "Dans l''Empire, religion et politique sont liées."}], "unitId": "eg.v.mauvais_citoyens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacrifice_public', 'eg', 'le sacrifice public', 'offrande rituelle aux dieux, faite devant tous en signe de loyauté', 'C''était le test de loyauté de l''Empire. Refuser, c''est s''exposer à la prison, à l''exil ou à la mort.', '[{"text": "Les chrétiens refusent le sacrifice public.", "translation": "Ce refus les met en danger."}, {"text": "Les autorités locales surveillent qui participe aux sacrifices.", "translation": "Ne pas y aller attire les soupçons."}]'::jsonb, null, '{"id": "eg.d.sacrifice_public", "word": "le sacrifice public", "translation": "offrande rituelle aux dieux, faite devant tous en signe de loyauté", "partOfSpeech": "concept", "explanation": "C''était le test de loyauté de l''Empire. Refuser, c''est s''exposer à la prison, à l''exil ou à la mort.", "examples": [{"text": "Les chrétiens refusent le sacrifice public.", "translation": "Ce refus les met en danger."}, {"text": "Les autorités locales surveillent qui participe aux sacrifices.", "translation": "Ne pas y aller attire les soupçons."}], "unitId": "eg.v.sacrifice_public"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.maximin', 'eg', 'Maximin', 'empereur romain, vers 235 : sixième persécution', 'Il s''en prend d''abord aux chefs de l''Église. Avec lui commence la série du IIIe siècle.', '[{"text": "Maximin ordonne la sixième persécution.", "translation": "Vers 235."}, {"text": "Les évêques et prêtres sont visés en premier.", "translation": "Il veut priver la communauté de ses chefs."}]'::jsonb, null, '{"id": "eg.d.maximin", "word": "Maximin", "translation": "empereur romain, vers 235 : sixième persécution", "partOfSpeech": "person", "explanation": "Il s''en prend d''abord aux chefs de l''Église. Avec lui commence la série du IIIe siècle.", "examples": [{"text": "Maximin ordonne la sixième persécution.", "translation": "Vers 235."}, {"text": "Les évêques et prêtres sont visés en premier.", "translation": "Il veut priver la communauté de ses chefs."}], "unitId": "eg.v.maximin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dece', 'eg', 'Dèce', 'empereur romain, vers 249 : septième persécution', 'Il rend le culte impérial obligatoire par un édit en 250, pour souder la population contre les dangers extérieurs.', '[{"text": "Dèce ordonne la septième persécution.", "translation": "Vers 249."}, {"text": "Sous Dèce, tout citoyen doit sacrifier.", "translation": "Les chrétiens qui refusent sont en danger."}]'::jsonb, null, '{"id": "eg.d.dece", "word": "Dèce", "translation": "empereur romain, vers 249 : septième persécution", "partOfSpeech": "person", "explanation": "Il rend le culte impérial obligatoire par un édit en 250, pour souder la population contre les dangers extérieurs.", "examples": [{"text": "Dèce ordonne la septième persécution.", "translation": "Vers 249."}, {"text": "Sous Dèce, tout citoyen doit sacrifier.", "translation": "Les chrétiens qui refusent sont en danger."}], "unitId": "eg.v.dece"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.valerien', 'eg', 'Valérien', 'empereur romain, vers 257 : huitième persécution', 'Il interdit les assemblées chrétiennes et frappe le clergé. Capturé par les Perses en 260.', '[{"text": "Valérien ordonne la huitième persécution.", "translation": "Vers 257."}, {"text": "Saint Cyprien est décapité en 258.", "translation": "Sous Valérien, le clergé est visé en priorité."}]'::jsonb, null, '{"id": "eg.d.valerien", "word": "Valérien", "translation": "empereur romain, vers 257 : huitième persécution", "partOfSpeech": "person", "explanation": "Il interdit les assemblées chrétiennes et frappe le clergé. Capturé par les Perses en 260.", "examples": [{"text": "Valérien ordonne la huitième persécution.", "translation": "Vers 257."}, {"text": "Saint Cyprien est décapité en 258.", "translation": "Sous Valérien, le clergé est visé en priorité."}], "unitId": "eg.v.valerien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.edit_de_dece', 'eg', 'l''édit de 250', 'édit de Dèce qui rend le culte impérial obligatoire pour tous', 'Il vise à souder la population de l''empire contre les dangers extérieurs. Tout citoyen doit sacrifier.', '[{"text": "L''édit de 250 oblige tous les citoyens à sacrifier.", "translation": "C''est un ordre général."}, {"text": "Les chrétiens se retrouvent dans le viseur.", "translation": "Leur refus devient une désobéissance publique."}]'::jsonb, null, '{"id": "eg.d.edit_de_dece", "word": "l''édit de 250", "translation": "édit de Dèce qui rend le culte impérial obligatoire pour tous", "partOfSpeech": "event", "explanation": "Il vise à souder la population de l''empire contre les dangers extérieurs. Tout citoyen doit sacrifier.", "examples": [{"text": "L''édit de 250 oblige tous les citoyens à sacrifier.", "translation": "C''est un ordre général."}, {"text": "Les chrétiens se retrouvent dans le viseur.", "translation": "Leur refus devient une désobéissance publique."}], "unitId": "eg.v.edit_de_dece"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.libellus', 'eg', 'le libellus', 'certificat prouvant qu''on a sacrifié aux dieux sous Dèce', 'On le recevait après avoir sacrifié. Certains s''en procuraient de faux, d''autres cédaient vraiment.', '[{"text": "Le libellus prouve le sacrifice.", "translation": "Les autorités le contrôlent."}, {"text": "Un chrétien peut acheter un faux libellus.", "translation": "Cela pose un problème moral à l''Église."}]'::jsonb, null, '{"id": "eg.d.libellus", "word": "le libellus", "translation": "certificat prouvant qu''on a sacrifié aux dieux sous Dèce", "partOfSpeech": "concept", "explanation": "On le recevait après avoir sacrifié. Certains s''en procuraient de faux, d''autres cédaient vraiment.", "examples": [{"text": "Le libellus prouve le sacrifice.", "translation": "Les autorités le contrôlent."}, {"text": "Un chrétien peut acheter un faux libellus.", "translation": "Cela pose un problème moral à l''Église."}], "unitId": "eg.v.libellus"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.semence_de_chretiens', 'eg', 'la semence de chrétiens', 'formule de Tertullien : le sang des martyrs fait naître de nouveaux chrétiens', 'Les martyrs impressionnent les spectateurs et provoquent des conversions : la persécution fait grandir l''Église.', '[{"text": "Le sang des martyrs est semence de chrétiens.", "translation": "Tertullien le dit avant le IIIe siècle."}, {"text": "Voir un martyr mourir en paix touche les spectateurs.", "translation": "Beaucoup se convertissent ensuite."}]'::jsonb, null, '{"id": "eg.d.semence_de_chretiens", "word": "la semence de chrétiens", "translation": "formule de Tertullien : le sang des martyrs fait naître de nouveaux chrétiens", "partOfSpeech": "concept", "explanation": "Les martyrs impressionnent les spectateurs et provoquent des conversions : la persécution fait grandir l''Église.", "examples": [{"text": "Le sang des martyrs est semence de chrétiens.", "translation": "Tertullien le dit avant le IIIe siècle."}, {"text": "Voir un martyr mourir en paix touche les spectateurs.", "translation": "Beaucoup se convertissent ensuite."}], "unitId": "eg.v.semence_de_chretiens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.diocletien', 'eg', 'Dioclétien', 'empereur romain dès 284 : dixième persécution, début de l''ère des martyrs', 'Il règne à partir de 284. Sous lui, la persécution est généralisée, et son accession devient l''an 1 du calendrier copte.', '[{"text": "Dioclétien devient empereur en 284.", "translation": "Les Coptes en font l''an 1."}, {"text": "Sous Dioclétien, les persécutions touchent tout l''empire.", "translation": "C''est la plus grande épreuve de l''Église ancienne."}]'::jsonb, null, '{"id": "eg.d.diocletien", "word": "Dioclétien", "translation": "empereur romain dès 284 : dixième persécution, début de l''ère des martyrs", "partOfSpeech": "person", "explanation": "Il règne à partir de 284. Sous lui, la persécution est généralisée, et son accession devient l''an 1 du calendrier copte.", "examples": [{"text": "Dioclétien devient empereur en 284.", "translation": "Les Coptes en font l''an 1."}, {"text": "Sous Dioclétien, les persécutions touchent tout l''empire.", "translation": "C''est la plus grande épreuve de l''Église ancienne."}], "unitId": "eg.v.diocletien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.grande_persecution_303', 'eg', 'la grande persécution de 303', 'édits de 303 : églises détruites, livres brûlés, clergé emprisonné', 'C''est le sommet des persécutions de Dioclétien : tous les chrétiens sont visés.', '[{"text": "En 303, les églises sont détruites.", "translation": "Les livres saints sont brûlés."}, {"text": "Les chrétiens doivent sacrifier ou mourir.", "translation": "Beaucoup deviennent martyrs."}]'::jsonb, null, '{"id": "eg.d.grande_persecution_303", "word": "la grande persécution de 303", "translation": "édits de 303 : églises détruites, livres brûlés, clergé emprisonné", "partOfSpeech": "event", "explanation": "C''est le sommet des persécutions de Dioclétien : tous les chrétiens sont visés.", "examples": [{"text": "En 303, les églises sont détruites.", "translation": "Les livres saints sont brûlés."}, {"text": "Les chrétiens doivent sacrifier ou mourir.", "translation": "Beaucoup deviennent martyrs."}], "unitId": "eg.v.grande_persecution_303"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dixieme_persecution', 'eg', 'la dixième persécution', 'dernière persécution de la liste traditionnelle, sous Dioclétien', 'Elle clôt la liste des dix persécutions comptées par la tradition. Elle est la plus générale.', '[{"text": "La dixième persécution est celle de Dioclétien.", "translation": "Elle est généralisée."}, {"text": "Avant elle, neuf vagues avaient frappé l''Église.", "translation": "La neuvième date de 274."}]'::jsonb, null, '{"id": "eg.d.dixieme_persecution", "word": "la dixième persécution", "translation": "dernière persécution de la liste traditionnelle, sous Dioclétien", "partOfSpeech": "event", "explanation": "Elle clôt la liste des dix persécutions comptées par la tradition. Elle est la plus générale.", "examples": [{"text": "La dixième persécution est celle de Dioclétien.", "translation": "Elle est généralisée."}, {"text": "Avant elle, neuf vagues avaient frappé l''Église.", "translation": "La neuvième date de 274."}], "unitId": "eg.v.dixieme_persecution"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.calendrier_copte', 'eg', 'le calendrier copte', 'calendrier dont l''an 1 correspond à l''année 284 de notre ère', 'Il commence avec l''accession de Dioclétien, pour garder la mémoire des martyrs.', '[{"text": "Nous sommes en 1743 en 2026 après le Nayrouz.", "translation": "On retire 283."}, {"text": "Le calendrier copte commence en 284.", "translation": "Il porte la mémoire des martyrs."}]'::jsonb, null, '{"id": "eg.d.calendrier_copte", "word": "le calendrier copte", "translation": "calendrier dont l''an 1 correspond à l''année 284 de notre ère", "partOfSpeech": "concept", "explanation": "Il commence avec l''accession de Dioclétien, pour garder la mémoire des martyrs.", "examples": [{"text": "Nous sommes en 1743 en 2026 après le Nayrouz.", "translation": "On retire 283."}, {"text": "Le calendrier copte commence en 284.", "translation": "Il porte la mémoire des martyrs."}], "unitId": "eg.v.calendrier_copte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ere_des_martyrs', 'eg', 'l''ère des martyrs', 'autre nom du calendrier copte, compté depuis 284', 'Les Coptes datent les années depuis 284, en mémoire des martyrs de Dioclétien.', '[{"text": "On dit : l''an 1743 de l''ère des martyrs.", "translation": "C''est l''année copte."}, {"text": "L''ère des martyrs part de 284.", "translation": "Elle honore leur témoignage."}]'::jsonb, null, '{"id": "eg.d.ere_des_martyrs", "word": "l''ère des martyrs", "translation": "autre nom du calendrier copte, compté depuis 284", "partOfSpeech": "concept", "explanation": "Les Coptes datent les années depuis 284, en mémoire des martyrs de Dioclétien.", "examples": [{"text": "On dit : l''an 1743 de l''ère des martyrs.", "translation": "C''est l''année copte."}, {"text": "L''ère des martyrs part de 284.", "translation": "Elle honore leur témoignage."}], "unitId": "eg.v.ere_des_martyrs"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nayrouz', 'eg', 'le Nayrouz', 'jour de l''an copte, en septembre', 'Le Nayrouz ouvre l''année copte. Il tombe en septembre.', '[{"text": "Le Nayrouz marque le début de l''année copte.", "translation": "Il a lieu en septembre."}, {"text": "Après le Nayrouz, l''année copte change.", "translation": "Il rappelle l''ère des martyrs."}]'::jsonb, null, '{"id": "eg.d.nayrouz", "word": "le Nayrouz", "translation": "jour de l''an copte, en septembre", "partOfSpeech": "event", "explanation": "Le Nayrouz ouvre l''année copte. Il tombe en septembre.", "examples": [{"text": "Le Nayrouz marque le début de l''année copte.", "translation": "Il a lieu en septembre."}, {"text": "Après le Nayrouz, l''année copte change.", "translation": "Il rappelle l''ère des martyrs."}], "unitId": "eg.v.nayrouz"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.paul_de_thebes', 'eg', 'saint Paul de Thèbes', 'le premier des ermites, au désert d''Égypte vers 250', 'Il fuit la persécution de Dèce et vit seul des décennies. La tradition raconte qu''un corbeau lui apporte du pain.', '[{"text": "Saint Paul est le premier des ermites.", "translation": "Il fuit vers 250."}, {"text": "Antoine lui rend visite avant sa mort.", "translation": "Il l''enterre selon la tradition."}]'::jsonb, null, '{"id": "eg.d.paul_de_thebes", "word": "saint Paul de Thèbes", "translation": "le premier des ermites, au désert d''Égypte vers 250", "partOfSpeech": "person", "explanation": "Il fuit la persécution de Dèce et vit seul des décennies. La tradition raconte qu''un corbeau lui apporte du pain.", "examples": [{"text": "Saint Paul est le premier des ermites.", "translation": "Il fuit vers 250."}, {"text": "Antoine lui rend visite avant sa mort.", "translation": "Il l''enterre selon la tradition."}], "unitId": "eg.v.paul_de_thebes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.antoine', 'eg', 'saint Antoine', 'père des moines, parti au désert vers 270', 'Jeune Égyptien riche, il entend Mt 19, 21, donne ses biens et part au désert.', '[{"text": "Saint Antoine part au désert vers 270.", "translation": "On l''appelle le père des moines."}, {"text": "Antoine vit en ermite puis guide des disciples.", "translation": "Son exemple inspire les moines."}]'::jsonb, null, '{"id": "eg.d.antoine", "word": "saint Antoine", "translation": "père des moines, parti au désert vers 270", "partOfSpeech": "person", "explanation": "Jeune Égyptien riche, il entend Mt 19, 21, donne ses biens et part au désert.", "examples": [{"text": "Saint Antoine part au désert vers 270.", "translation": "On l''appelle le père des moines."}, {"text": "Antoine vit en ermite puis guide des disciples.", "translation": "Son exemple inspire les moines."}], "unitId": "eg.v.antoine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ermite', 'eg', 'l''ermite', 'celui qui vit seul au désert', 'Le mot vient du grec « eremos » : désert. L''ermite prie, jeûne et travaille de ses mains.', '[{"text": "Paul est le premier ermite.", "translation": "Il vit seul dans une grotte."}, {"text": "Un ermite cherche Dieu dans la solitude.", "translation": "Il quitte la ville."}]'::jsonb, null, '{"id": "eg.d.ermite", "word": "l''ermite", "translation": "celui qui vit seul au désert", "partOfSpeech": "concept", "explanation": "Le mot vient du grec « eremos » : désert. L''ermite prie, jeûne et travaille de ses mains.", "examples": [{"text": "Paul est le premier ermite.", "translation": "Il vit seul dans une grotte."}, {"text": "Un ermite cherche Dieu dans la solitude.", "translation": "Il quitte la ville."}], "unitId": "eg.v.ermite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.anachorete', 'eg', 'l''anachorète', 'celui qui se retire du monde pour prier', 'Du grec « anachôrein » : se retirer. Antoine est un anachorète.', '[{"text": "Antoine est un anachorète.", "translation": "Il se retire au désert."}, {"text": "Anachorète et ermite sont proches.", "translation": "Tous deux vivent seuls."}]'::jsonb, null, '{"id": "eg.d.anachorete", "word": "l''anachorète", "translation": "celui qui se retire du monde pour prier", "partOfSpeech": "concept", "explanation": "Du grec « anachôrein » : se retirer. Antoine est un anachorète.", "examples": [{"text": "Antoine est un anachorète.", "translation": "Il se retire au désert."}, {"text": "Anachorète et ermite sont proches.", "translation": "Tous deux vivent seuls."}], "unitId": "eg.v.anachorete"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.desert_d_egypte', 'eg', 'le désert d''Égypte', 'terre aride proche du Nil où les premiers ermites se retirent', 'À quelques jours du Nil et des villes, le désert offre le silence. L''Égypte devient la patrie des moines.', '[{"text": "Paul et Antoine vivent dans le désert d''Égypte.", "translation": "Ils s''éloignent des villes."}, {"text": "Le désert est proche du Nil.", "translation": "C''est un refuge pour les persécutés."}]'::jsonb, null, '{"id": "eg.d.desert_d_egypte", "word": "le désert d''Égypte", "translation": "terre aride proche du Nil où les premiers ermites se retirent", "partOfSpeech": "place", "explanation": "À quelques jours du Nil et des villes, le désert offre le silence. L''Égypte devient la patrie des moines.", "examples": [{"text": "Paul et Antoine vivent dans le désert d''Égypte.", "translation": "Ils s''éloignent des villes."}, {"text": "Le désert est proche du Nil.", "translation": "C''est un refuge pour les persécutés."}], "unitId": "eg.v.desert_d_egypte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.fuite_au_desert', 'eg', 'la fuite au désert', 'départ de chrétiens vers le désert pour échapper aux persécutions, vers 250', 'Sous Dèce, certains chrétiens quittent les villes. Paul est le plus célèbre.', '[{"text": "Paul fuit au désert sous Dèce.", "translation": "C''est le début de la vie au désert."}, {"text": "La fuite devient ensuite un choix.", "translation": "On y reste pour prier."}]'::jsonb, null, '{"id": "eg.d.fuite_au_desert", "word": "la fuite au désert", "translation": "départ de chrétiens vers le désert pour échapper aux persécutions, vers 250", "partOfSpeech": "event", "explanation": "Sous Dèce, certains chrétiens quittent les villes. Paul est le plus célèbre.", "examples": [{"text": "Paul fuit au désert sous Dèce.", "translation": "C''est le début de la vie au désert."}, {"text": "La fuite devient ensuite un choix.", "translation": "On y reste pour prier."}], "unitId": "eg.v.fuite_au_desert"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.paul_de_samosate', 'eg', 'Paul de Samosate', 'évêque d''Antioche, excommunié en 269 : pour lui le Christ est un homme ordinaire', 'Il nie la Trinité et la divinité unie au Christ. Un concile le condamne.', '[{"text": "Paul de Samosate est évêque d''Antioche.", "translation": "Il nie la Sainte Trinité."}, {"text": "Il est protégé par la reine Zénobie.", "translation": "Il est exilé de son siège en 269."}]'::jsonb, null, '{"id": "eg.d.paul_de_samosate", "word": "Paul de Samosate", "translation": "évêque d''Antioche, excommunié en 269 : pour lui le Christ est un homme ordinaire", "partOfSpeech": "person", "explanation": "Il nie la Trinité et la divinité unie au Christ. Un concile le condamne.", "examples": [{"text": "Paul de Samosate est évêque d''Antioche.", "translation": "Il nie la Sainte Trinité."}, {"text": "Il est protégé par la reine Zénobie.", "translation": "Il est exilé de son siège en 269."}], "unitId": "eg.v.paul_de_samosate"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.zenobie', 'eg', 'Zénobie', 'reine de Palmyre qui soutient Paul de Samosate', 'Son pouvoir en Orient protège un temps Paul.', '[{"text": "Zénobie soutient Paul de Samosate.", "translation": "Elle règne à Palmyre."}, {"text": "Sa protection est politique.", "translation": "Elle retarde sa condamnation."}]'::jsonb, null, '{"id": "eg.d.zenobie", "word": "Zénobie", "translation": "reine de Palmyre qui soutient Paul de Samosate", "partOfSpeech": "person", "explanation": "Son pouvoir en Orient protège un temps Paul.", "examples": [{"text": "Zénobie soutient Paul de Samosate.", "translation": "Elle règne à Palmyre."}, {"text": "Sa protection est politique.", "translation": "Elle retarde sa condamnation."}], "unitId": "eg.v.zenobie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.denys_d_alexandrie', 'eg', 'Denys d''Alexandrie', '14e patriarche d''Alexandrie, défenseur de la foi trinitaire', 'Trop âgé pour aller à Antioche, il envoie une lettre. Il combat Sabellius et Novatien.', '[{"text": "Denys est le 14e patriarche d''Alexandrie.", "translation": "Il écrit une lettre au concile."}, {"text": "Il combat aussi Sabellius.", "translation": "Il est un défenseur de la Trinité."}]'::jsonb, null, '{"id": "eg.d.denys_d_alexandrie", "word": "Denys d''Alexandrie", "translation": "14e patriarche d''Alexandrie, défenseur de la foi trinitaire", "partOfSpeech": "person", "explanation": "Trop âgé pour aller à Antioche, il envoie une lettre. Il combat Sabellius et Novatien.", "examples": [{"text": "Denys est le 14e patriarche d''Alexandrie.", "translation": "Il écrit une lettre au concile."}, {"text": "Il combat aussi Sabellius.", "translation": "Il est un défenseur de la Trinité."}], "unitId": "eg.v.denys_d_alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_d_antioche_269', 'eg', 'le concile d''Antioche (269)', 'réunion d''évêques qui condamne Paul de Samosate', 'Treize évêques et deux prêtres interrogent Paul, lisent la lettre de Denys et l''excommunient.', '[{"text": "Le concile d''Antioche condamne Paul en 269.", "translation": "Il l''excommunie."}, {"text": "Treize évêques y siègent.", "translation": "Paul est exilé de son siège."}]'::jsonb, null, '{"id": "eg.d.concile_d_antioche_269", "word": "le concile d''Antioche (269)", "translation": "réunion d''évêques qui condamne Paul de Samosate", "partOfSpeech": "event", "explanation": "Treize évêques et deux prêtres interrogent Paul, lisent la lettre de Denys et l''excommunient.", "examples": [{"text": "Le concile d''Antioche condamne Paul en 269.", "translation": "Il l''excommunie."}, {"text": "Treize évêques y siègent.", "translation": "Paul est exilé de son siège."}], "unitId": "eg.v.concile_d_antioche_269"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sabellius', 'eg', 'Sabellius', 'évêque de Ptolémaïs : Père, Fils et Esprit sont un seul Dieu sous trois formes', 'Il confond les trois personnes. Son enseignement s''appelle sabellianisme ou modalisme.', '[{"text": "Sabellius est évêque de Ptolémaïs.", "translation": "Il confond les personnes."}, {"text": "Il est combattu par Denys d''Alexandrie.", "translation": "Hippolyte de Rome l''affronte aussi."}]'::jsonb, null, '{"id": "eg.d.sabellius", "word": "Sabellius", "translation": "évêque de Ptolémaïs : Père, Fils et Esprit sont un seul Dieu sous trois formes", "partOfSpeech": "person", "explanation": "Il confond les trois personnes. Son enseignement s''appelle sabellianisme ou modalisme.", "examples": [{"text": "Sabellius est évêque de Ptolémaïs.", "translation": "Il confond les personnes."}, {"text": "Il est combattu par Denys d''Alexandrie.", "translation": "Hippolyte de Rome l''affronte aussi."}], "unitId": "eg.v.sabellius"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.modalisme', 'eg', 'le modalisme', 'idée que Père, Fils et Esprit sont des « modes » successifs d''un seul Dieu', 'Le mot vient de « mode » : trois façons d''apparaître, non trois personnes.', '[{"text": "Le modalisme réduit la Trinité à trois masques.", "translation": "Sabellius en est le nom."}, {"text": "Le Père serait aussi mort sur la croix.", "translation": "Cela efface la différence entre les personnes."}]'::jsonb, null, '{"id": "eg.d.modalisme", "word": "le modalisme", "translation": "idée que Père, Fils et Esprit sont des « modes » successifs d''un seul Dieu", "partOfSpeech": "concept", "explanation": "Le mot vient de « mode » : trois façons d''apparaître, non trois personnes.", "examples": [{"text": "Le modalisme réduit la Trinité à trois masques.", "translation": "Sabellius en est le nom."}, {"text": "Le Père serait aussi mort sur la croix.", "translation": "Cela efface la différence entre les personnes."}], "unitId": "eg.v.modalisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trinite', 'eg', 'la Sainte Trinité', 'un seul Dieu en trois personnes : le Père, le Fils et le Saint-Esprit', 'C''est le cœur de la foi chrétienne : trois personnes et une seule divinité.', '[{"text": "Paul de Samosate nie la Trinité.", "translation": "Sabellius la confond."}, {"text": "Denys précise : trois personnes, une seule divinité.", "translation": "La foi évite les deux erreurs."}]'::jsonb, null, '{"id": "eg.d.trinite", "word": "la Sainte Trinité", "translation": "un seul Dieu en trois personnes : le Père, le Fils et le Saint-Esprit", "partOfSpeech": "concept", "explanation": "C''est le cœur de la foi chrétienne : trois personnes et une seule divinité.", "examples": [{"text": "Paul de Samosate nie la Trinité.", "translation": "Sabellius la confond."}, {"text": "Denys précise : trois personnes, une seule divinité.", "translation": "La foi évite les deux erreurs."}], "unitId": "eg.v.trinite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.excommunication', 'eg', 'l''excommunication', 'exclusion d''un baptisé de la communion de l''Église', 'C''est la sanction de l''Église contre celui qui s''obstine dans l''erreur.', '[{"text": "Paul est excommunié en 269.", "translation": "Ceux qui le suivent aussi."}, {"text": "L''excommunication ferme la communion.", "translation": "Elle vise à protéger la foi."}]'::jsonb, null, '{"id": "eg.d.excommunication", "word": "l''excommunication", "translation": "exclusion d''un baptisé de la communion de l''Église", "partOfSpeech": "concept", "explanation": "C''est la sanction de l''Église contre celui qui s''obstine dans l''erreur.", "examples": [{"text": "Paul est excommunié en 269.", "translation": "Ceux qui le suivent aussi."}, {"text": "L''excommunication ferme la communion.", "translation": "Elle vise à protéger la foi."}], "unitId": "eg.v.excommunication"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.novatien', 'eg', 'Novatien', 'théologien romain, rival de l''évêque de Rome en 251, qui refuse de pardonner aux tombés', 'Son idée : l''Église doit rester pure. L''Église l''excommunie en 251.', '[{"text": "Novatien est un théologien romain.", "translation": "Il est consacré évêque de Rome en 251."}, {"text": "Novatien refuse le pardon aux tombés.", "translation": "Il est excommunié."}]'::jsonb, null, '{"id": "eg.d.novatien", "word": "Novatien", "translation": "théologien romain, rival de l''évêque de Rome en 251, qui refuse de pardonner aux tombés", "partOfSpeech": "person", "explanation": "Son idée : l''Église doit rester pure. L''Église l''excommunie en 251.", "examples": [{"text": "Novatien est un théologien romain.", "translation": "Il est consacré évêque de Rome en 251."}, {"text": "Novatien refuse le pardon aux tombés.", "translation": "Il est excommunié."}], "unitId": "eg.v.novatien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cyprien', 'eg', 'Cyprien de Carthage', 'évêque de Carthage, défenseur du pardon pour les vrais pénitents', 'Il combat Novatien avec Denys d''Alexandrie. Il est décapité en 258.', '[{"text": "Cyprien combat Novatien.", "translation": "Il est évêque de Carthage."}, {"text": "Cyprien défend le retour des pénitents.", "translation": "Il meurt martyr en 258."}]'::jsonb, null, '{"id": "eg.d.cyprien", "word": "Cyprien de Carthage", "translation": "évêque de Carthage, défenseur du pardon pour les vrais pénitents", "partOfSpeech": "person", "explanation": "Il combat Novatien avec Denys d''Alexandrie. Il est décapité en 258.", "examples": [{"text": "Cyprien combat Novatien.", "translation": "Il est évêque de Carthage."}, {"text": "Cyprien défend le retour des pénitents.", "translation": "Il meurt martyr en 258."}], "unitId": "eg.v.cyprien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tombes', 'eg', 'les « tombés »', 'chrétiens qui ont renié la foi sous la persécution', 'On les appelle aussi les lapsi. L''Église débat de leur réception.', '[{"text": "Les tombés veulent revenir après la persécution.", "translation": "Certains avaient un faux libellus."}, {"text": "Que faire des tombés ?", "translation": "C''est la question du siècle."}]'::jsonb, null, '{"id": "eg.d.tombes", "word": "les « tombés »", "translation": "chrétiens qui ont renié la foi sous la persécution", "partOfSpeech": "concept", "explanation": "On les appelle aussi les lapsi. L''Église débat de leur réception.", "examples": [{"text": "Les tombés veulent revenir après la persécution.", "translation": "Certains avaient un faux libellus."}, {"text": "Que faire des tombés ?", "translation": "C''est la question du siècle."}], "unitId": "eg.v.tombes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.penitence', 'eg', 'la pénitence', 'démarche sincère de repentir pour obtenir le pardon', 'C''est le chemin proposé aux tombés pour revenir à l''Église.', '[{"text": "Les vrais pénitents sont reçus dans l''Église.", "translation": "Le retour est possible après pénitence."}, {"text": "La pénitence demande du temps.", "translation": "L''Église ne ferme jamais la porte."}]'::jsonb, null, '{"id": "eg.d.penitence", "word": "la pénitence", "translation": "démarche sincère de repentir pour obtenir le pardon", "partOfSpeech": "concept", "explanation": "C''est le chemin proposé aux tombés pour revenir à l''Église.", "examples": [{"text": "Les vrais pénitents sont reçus dans l''Église.", "translation": "Le retour est possible après pénitence."}, {"text": "La pénitence demande du temps.", "translation": "L''Église ne ferme jamais la porte."}], "unitId": "eg.v.penitence"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.novatianisme', 'eg', 'le novatianisme', 'hérésie de Novatien : l''Église doit rester pure, sans pardon pour les tombés', 'Ses partisans forment la secte des novatiens, qui dure plusieurs siècles.', '[{"text": "Le novatianisme refuse de pardonner.", "translation": "C''est un rigorisme."}, {"text": "Les novatiens forment une secte.", "translation": "Elle dure des siècles."}]'::jsonb, null, '{"id": "eg.d.novatianisme", "word": "le novatianisme", "translation": "hérésie de Novatien : l''Église doit rester pure, sans pardon pour les tombés", "partOfSpeech": "concept", "explanation": "Ses partisans forment la secte des novatiens, qui dure plusieurs siècles.", "examples": [{"text": "Le novatianisme refuse de pardonner.", "translation": "C''est un rigorisme."}, {"text": "Les novatiens forment une secte.", "translation": "Elle dure des siècles."}], "unitId": "eg.v.novatianisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.mani', 'eg', 'Mani', 'Perse fondateur du manichéisme, au IIIe siècle', 'Il se présente comme le dernier prophète et rassemble des idées de plusieurs religions.', '[{"text": "Mani est un Perse.", "translation": "Il fonde le manichéisme."}, {"text": "Il se compte parmi les prophètes.", "translation": "Il vit au IIIe siècle."}]'::jsonb, null, '{"id": "eg.d.mani", "word": "Mani", "translation": "Perse fondateur du manichéisme, au IIIe siècle", "partOfSpeech": "person", "explanation": "Il se présente comme le dernier prophète et rassemble des idées de plusieurs religions.", "examples": [{"text": "Mani est un Perse.", "translation": "Il fonde le manichéisme."}, {"text": "Il se compte parmi les prophètes.", "translation": "Il vit au IIIe siècle."}], "unitId": "eg.v.mani"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.manicheisme', 'eg', 'le manichéisme', 'doctrine de Mani : un Dieu bon, un démiurge mauvais, toutes les religions valides', 'Il oppose l''esprit (bon) à la matière (mauvaise) et croit à la réincarnation.', '[{"text": "Le manichéisme suppose deux principes.", "translation": "Il est influencé par la gnose."}, {"text": "Tout est lutte du Bien contre le Mal.", "translation": "L''Église le combat."}]'::jsonb, null, '{"id": "eg.d.manicheisme", "word": "le manichéisme", "translation": "doctrine de Mani : un Dieu bon, un démiurge mauvais, toutes les religions valides", "partOfSpeech": "concept", "explanation": "Il oppose l''esprit (bon) à la matière (mauvaise) et croit à la réincarnation.", "examples": [{"text": "Le manichéisme suppose deux principes.", "translation": "Il est influencé par la gnose."}, {"text": "Tout est lutte du Bien contre le Mal.", "translation": "L''Église le combat."}], "unitId": "eg.v.manicheisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.augustin', 'eg', 'saint Augustin', 'grand Père latin, manichéen avant sa conversion', 'Il a adhéré au manichéisme avant de se convertir au christianisme.', '[{"text": "Augustin a été manichéen.", "translation": "Il se convertit ensuite."}, {"text": "Sa conversion répond à ses questions sur le mal.", "translation": "Il devient évêque d''Hippone."}]'::jsonb, null, '{"id": "eg.d.augustin", "word": "saint Augustin", "translation": "grand Père latin, manichéen avant sa conversion", "partOfSpeech": "person", "explanation": "Il a adhéré au manichéisme avant de se convertir au christianisme.", "examples": [{"text": "Augustin a été manichéen.", "translation": "Il se convertit ensuite."}, {"text": "Sa conversion répond à ses questions sur le mal.", "translation": "Il devient évêque d''Hippone."}], "unitId": "eg.v.augustin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tradition_ecrite', 'eg', 'la Tradition écrite', 'l''ensemble des écrits qui transmettent l''enseignement des apôtres, en plus de l''Écriture', 'Elle réunit Didachè, Tradition apostolique, Didascalie, Pères apostoliques.', '[{"text": "La Tradition écrite garde l''enseignement des apôtres.", "translation": "Elle s''ajoute à l''Écriture."}, {"text": "Notre étude porte sur la Tradition écrite.", "translation": "Ses sources se datent du Ier au IVe siècle."}]'::jsonb, null, '{"id": "eg.d.tradition_ecrite", "word": "la Tradition écrite", "translation": "l''ensemble des écrits qui transmettent l''enseignement des apôtres, en plus de l''Écriture", "partOfSpeech": "concept", "explanation": "Elle réunit Didachè, Tradition apostolique, Didascalie, Pères apostoliques.", "examples": [{"text": "La Tradition écrite garde l''enseignement des apôtres.", "translation": "Elle s''ajoute à l''Écriture."}, {"text": "Notre étude porte sur la Tradition écrite.", "translation": "Ses sources se datent du Ier au IVe siècle."}], "unitId": "eg.v.tradition_ecrite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.canon_du_nouveau_testament', 'eg', 'le canon du Nouveau Testament', 'la liste des livres reconnus comme Écriture par l''Église', 'Les critères : apostolicité, valeur spirituelle, conformité, consensus.', '[{"text": "Le canon fixe les livres du Nouveau Testament.", "translation": "Il résulte d''un tri."}, {"text": "Quatre critères ont guidé ce tri.", "translation": "L''Église a écrit puis reconnu ces textes."}]'::jsonb, null, '{"id": "eg.d.canon_du_nouveau_testament", "word": "le canon du Nouveau Testament", "translation": "la liste des livres reconnus comme Écriture par l''Église", "partOfSpeech": "concept", "explanation": "Les critères : apostolicité, valeur spirituelle, conformité, consensus.", "examples": [{"text": "Le canon fixe les livres du Nouveau Testament.", "translation": "Il résulte d''un tri."}, {"text": "Quatre critères ont guidé ce tri.", "translation": "L''Église a écrit puis reconnu ces textes."}], "unitId": "eg.v.canon_du_nouveau_testament"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.approbation_apostolique', 'eg', 'l''approbation apostolique', 'principal test de canonicité : le livre vient des apôtres ou de leur contrôle', 'Les apôtres sont les fondateurs de l''Église : la Parole qui la régit vient d''eux.', '[{"text": "L''approbation apostolique est le principal test.", "translation": "Marc écrit sous le contrôle de Pierre."}, {"text": "Un écrit sans lien avec les apôtres est écarté.", "translation": "C''est le premier critère."}]'::jsonb, null, '{"id": "eg.d.approbation_apostolique", "word": "l''approbation apostolique", "translation": "principal test de canonicité : le livre vient des apôtres ou de leur contrôle", "partOfSpeech": "concept", "explanation": "Les apôtres sont les fondateurs de l''Église : la Parole qui la régit vient d''eux.", "examples": [{"text": "L''approbation apostolique est le principal test.", "translation": "Marc écrit sous le contrôle de Pierre."}, {"text": "Un écrit sans lien avec les apôtres est écarté.", "translation": "C''est le premier critère."}], "unitId": "eg.v.approbation_apostolique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apocryphes', 'eg', 'les apocryphes', 'écrits écartés du canon, faits de légendes éloignées de la foi apostolique', 'Leur Jésus est souvent un faiseur de miracles gratuits.', '[{"text": "Les évangiles apocryphes inventent des miracles.", "translation": "L''Église les écarte."}, {"text": "Ils ne passent pas les critères.", "translation": "Ils ne sont pas inspirés."}]'::jsonb, null, '{"id": "eg.d.apocryphes", "word": "les apocryphes", "translation": "écrits écartés du canon, faits de légendes éloignées de la foi apostolique", "partOfSpeech": "concept", "explanation": "Leur Jésus est souvent un faiseur de miracles gratuits.", "examples": [{"text": "Les évangiles apocryphes inventent des miracles.", "translation": "L''Église les écarte."}, {"text": "Ils ne passent pas les critères.", "translation": "Ils ne sont pas inspirés."}], "unitId": "eg.v.apocryphes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.didache', 'eg', 'la Didachè', 'écrit très ancien, vers 100, sur la vie des communautés', 'Utile mais pas inspirée : elle retombe dans le légalisme.', '[{"text": "La Didachè date d''environ 100.", "translation": "Elle n''est pas dans le canon."}, {"text": "Elle donne des règles pour les communautés.", "translation": "C''est un écrit honorable."}]'::jsonb, null, '{"id": "eg.d.didache", "word": "la Didachè", "translation": "écrit très ancien, vers 100, sur la vie des communautés", "partOfSpeech": "work", "explanation": "Utile mais pas inspirée : elle retombe dans le légalisme.", "examples": [{"text": "La Didachè date d''environ 100.", "translation": "Elle n''est pas dans le canon."}, {"text": "Elle donne des règles pour les communautés.", "translation": "C''est un écrit honorable."}], "unitId": "eg.v.didache"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tradition_apostolique_d_hippolyte', 'eg', 'la Tradition apostolique d''Hippolyte', 'écrit de Rome, vers 215, sur l''organisation et la liturgie', 'Elle décrit les ordinations et le rôle des confesseurs.', '[{"text": "Hippolyte écrit vers 215.", "translation": "Le texte parle des ordinations."}, {"text": "On y lit comment ordonner un évêque.", "translation": "On y lit le rôle des confesseurs."}]'::jsonb, null, '{"id": "eg.d.tradition_apostolique_d_hippolyte", "word": "la Tradition apostolique d''Hippolyte", "translation": "écrit de Rome, vers 215, sur l''organisation et la liturgie", "partOfSpeech": "work", "explanation": "Elle décrit les ordinations et le rôle des confesseurs.", "examples": [{"text": "Hippolyte écrit vers 215.", "translation": "Le texte parle des ordinations."}, {"text": "On y lit comment ordonner un évêque.", "translation": "On y lit le rôle des confesseurs."}], "unitId": "eg.v.tradition_apostolique_d_hippolyte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.didascalie', 'eg', 'la Didascalie syriaque', '« enseignement des douze apôtres », vers 250', 'Source de la Tradition sur la vie des Églises au IIIe siècle.', '[{"text": "La Didascalie date d''environ 250.", "translation": "Son nom veut dire enseignement."}, {"text": "Elle règle la vie des communautés.", "translation": "Elle est aussi appelée enseignement des apôtres."}]'::jsonb, null, '{"id": "eg.d.didascalie", "word": "la Didascalie syriaque", "translation": "« enseignement des douze apôtres », vers 250", "partOfSpeech": "work", "explanation": "Source de la Tradition sur la vie des Églises au IIIe siècle.", "examples": [{"text": "La Didascalie date d''environ 250.", "translation": "Son nom veut dire enseignement."}, {"text": "Elle règle la vie des communautés.", "translation": "Elle est aussi appelée enseignement des apôtres."}], "unitId": "eg.v.didascalie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pasteur_d_hermas', 'eg', 'le Pasteur d''Hermas', 'écrit du IIe siècle fait de visions, jugé trop incontrôlable pour le canon', 'Père apostolique honorable, mais non canonique.', '[{"text": "Hermas raconte des visions.", "translation": "Le canon l''écarte."}, {"text": "Son récit reste vénérable.", "translation": "Ses visions sont incontrôlables."}]'::jsonb, null, '{"id": "eg.d.pasteur_d_hermas", "word": "le Pasteur d''Hermas", "translation": "écrit du IIe siècle fait de visions, jugé trop incontrôlable pour le canon", "partOfSpeech": "work", "explanation": "Père apostolique honorable, mais non canonique.", "examples": [{"text": "Hermas raconte des visions.", "translation": "Le canon l''écarte."}, {"text": "Son récit reste vénérable.", "translation": "Ses visions sont incontrôlables."}], "unitId": "eg.v.pasteur_d_hermas"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.diacre', 'eg', 'le diacre', 'serviteur de l''Église, qui aide l''évêque et sert les pauvres', 'Du grec « diakonos » : serviteur. Ses débuts sont décrits en Ac 6.', '[{"text": "Le diacre sert les pauvres.", "translation": "Il aide l''évêque."}, {"text": "Le diacre est le troisième degré.", "translation": "Il est ordonné."}]'::jsonb, null, '{"id": "eg.d.diacre", "word": "le diacre", "translation": "serviteur de l''Église, qui aide l''évêque et sert les pauvres", "partOfSpeech": "person", "explanation": "Du grec « diakonos » : serviteur. Ses débuts sont décrits en Ac 6.", "examples": [{"text": "Le diacre sert les pauvres.", "translation": "Il aide l''évêque."}, {"text": "Le diacre est le troisième degré.", "translation": "Il est ordonné."}], "unitId": "eg.v.diacre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pretre', 'eg', 'le prêtre', 'ancien de la communauté qui enseigne et prie (presbytre)', 'Du grec « presbyteros » : ancien. Il est le deuxième degré de la hiérarchie.', '[{"text": "Le prêtre conduit la communauté.", "translation": "Il enseigne et prie."}, {"text": "Il est ordonné par l''évêque.", "translation": "Il est l''ancien des premiers temps."}]'::jsonb, null, '{"id": "eg.d.pretre", "word": "le prêtre", "translation": "ancien de la communauté qui enseigne et prie (presbytre)", "partOfSpeech": "person", "explanation": "Du grec « presbyteros » : ancien. Il est le deuxième degré de la hiérarchie.", "examples": [{"text": "Le prêtre conduit la communauté.", "translation": "Il enseigne et prie."}, {"text": "Il est ordonné par l''évêque.", "translation": "Il est l''ancien des premiers temps."}], "unitId": "eg.v.pretre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.clerge', 'eg', 'les clercs et les laïcs', 'les clercs sont ordonnés ; les laïcs sont les autres fidèles', 'Cette distinction apparaît au IIIe siècle.', '[{"text": "Les clercs sont ordonnés.", "translation": "Les laïcs ne le sont pas."}, {"text": "La distinction apparaît au IIIe siècle.", "translation": "Elle structure l''Église."}]'::jsonb, null, '{"id": "eg.d.clerge", "word": "les clercs et les laïcs", "translation": "les clercs sont ordonnés ; les laïcs sont les autres fidèles", "partOfSpeech": "concept", "explanation": "Cette distinction apparaît au IIIe siècle.", "examples": [{"text": "Les clercs sont ordonnés.", "translation": "Les laïcs ne le sont pas."}, {"text": "La distinction apparaît au IIIe siècle.", "translation": "Elle structure l''Église."}], "unitId": "eg.v.clerge"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.hierarchie_a_trois_degres', 'eg', 'la hiérarchie à trois degrés', 'évêque, prêtre, diacre : l''organisation de l''Église dès le IIIe siècle', 'Elle remplace la direction collégiale des premiers temps.', '[{"text": "L''évêque, le prêtre et le diacre forment la hiérarchie.", "translation": "Elle s''affirme au IIIe siècle."}, {"text": "L''évêque est au sommet.", "translation": "Le diacre est au service."}]'::jsonb, null, '{"id": "eg.d.hierarchie_a_trois_degres", "word": "la hiérarchie à trois degrés", "translation": "évêque, prêtre, diacre : l''organisation de l''Église dès le IIIe siècle", "partOfSpeech": "concept", "explanation": "Elle remplace la direction collégiale des premiers temps.", "examples": [{"text": "L''évêque, le prêtre et le diacre forment la hiérarchie.", "translation": "Elle s''affirme au IIIe siècle."}, {"text": "L''évêque est au sommet.", "translation": "Le diacre est au service."}], "unitId": "eg.v.hierarchie_a_trois_degres"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.confesseur', 'eg', 'le confesseur', 'chrétien qui a souffert pour sa foi sans mourir martyr', 'Il jouit d''un statut privilégié et peut diriger les offices, mais doit être ordonné pour devenir évêque.', '[{"text": "Le confesseur survit à la persécution.", "translation": "Il est honoré."}, {"text": "Il dirige parfois les offices.", "translation": "Il n''est pas évêque sans ordination."}]'::jsonb, null, '{"id": "eg.d.confesseur", "word": "le confesseur", "translation": "chrétien qui a souffert pour sa foi sans mourir martyr", "partOfSpeech": "person", "explanation": "Il jouit d''un statut privilégié et peut diriger les offices, mais doit être ordonné pour devenir évêque.", "examples": [{"text": "Le confesseur survit à la persécution.", "translation": "Il est honoré."}, {"text": "Il dirige parfois les offices.", "translation": "Il n''est pas évêque sans ordination."}], "unitId": "eg.v.confesseur"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.prophetes_des_premiers_temps', 'eg', 'les prophètes des premiers temps', 'ministère des temps apostoliques, disparu avec la rédaction des évangiles', 'Ils parlaient au nom de Dieu dans les premières communautés.', '[{"text": "Les prophètes existent au temps des apôtres.", "translation": "Ils ont disparu ensuite."}, {"text": "Agabus est un prophète du Nouveau Testament.", "translation": "Leur rôle est désormais tenu par l''Écriture."}]'::jsonb, null, '{"id": "eg.d.prophetes_des_premiers_temps", "word": "les prophètes des premiers temps", "translation": "ministère des temps apostoliques, disparu avec la rédaction des évangiles", "partOfSpeech": "concept", "explanation": "Ils parlaient au nom de Dieu dans les premières communautés.", "examples": [{"text": "Les prophètes existent au temps des apôtres.", "translation": "Ils ont disparu ensuite."}, {"text": "Agabus est un prophète du Nouveau Testament.", "translation": "Leur rôle est désormais tenu par l''Écriture."}], "unitId": "eg.v.prophetes_des_premiers_temps"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.heraclas', 'eg', 'Héraclas', '13e évêque d''Alexandrie, le premier appelé pape', 'Depuis lui, l''évêque d''Alexandrie porte le titre de pape.', '[{"text": "Héraclas est le premier pape d''Alexandrie.", "translation": "Il est le 13e évêque."}, {"text": "Son successeur est Denys.", "translation": "Denys est le 14e."}]'::jsonb, null, '{"id": "eg.d.heraclas", "word": "Héraclas", "translation": "13e évêque d''Alexandrie, le premier appelé pape", "partOfSpeech": "person", "explanation": "Depuis lui, l''évêque d''Alexandrie porte le titre de pape.", "examples": [{"text": "Héraclas est le premier pape d''Alexandrie.", "translation": "Il est le 13e évêque."}, {"text": "Son successeur est Denys.", "translation": "Denys est le 14e."}], "unitId": "eg.v.heraclas"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.patriarche_a_partir_de_451', 'eg', 'le titre de patriarche', 'titre utilisé à partir de 451, après celui de pape', 'Le mot patriarche s''ajoute au titre de pape pour les grands sièges.', '[{"text": "Le titre de patriarche apparaît en 451.", "translation": "Pape est plus ancien."}, {"text": "Le pape d''Alexandrie est aussi patriarche.", "translation": "Les deux titres coexistent."}]'::jsonb, null, '{"id": "eg.d.patriarche_a_partir_de_451", "word": "le titre de patriarche", "translation": "titre utilisé à partir de 451, après celui de pape", "partOfSpeech": "concept", "explanation": "Le mot patriarche s''ajoute au titre de pape pour les grands sièges.", "examples": [{"text": "Le titre de patriarche apparaît en 451.", "translation": "Pape est plus ancien."}, {"text": "Le pape d''Alexandrie est aussi patriarche.", "translation": "Les deux titres coexistent."}], "unitId": "eg.v.patriarche_a_partir_de_451"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.galere', 'eg', 'Galère', 'second de Dioclétien, empereur après lui (305)', 'Plus cruel encore que Dioclétien, il invente de nouvelles tortures. Gravement malade, il signe l''édit de tolérance de 311.', '[{"text": "Galère succède à Dioclétien en 305.", "translation": "Sa cruauté dépasse celle de ses prédécesseurs."}, {"text": "Galère signe l''édit de tolérance en 311.", "translation": "Il meurt peu après."}]'::jsonb, null, '{"id": "eg.d.galere", "word": "Galère", "translation": "second de Dioclétien, empereur après lui (305)", "partOfSpeech": "person", "explanation": "Plus cruel encore que Dioclétien, il invente de nouvelles tortures. Gravement malade, il signe l''édit de tolérance de 311.", "examples": [{"text": "Galère succède à Dioclétien en 305.", "translation": "Sa cruauté dépasse celle de ses prédécesseurs."}, {"text": "Galère signe l''édit de tolérance en 311.", "translation": "Il meurt peu après."}], "unitId": "eg.v.galere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.quatre_edits', 'eg', 'les quatre édits de 303', 'décrets de Dioclétien pour éradiquer le christianisme', 'Premier : églises rasées et livres brûlés. Deuxième : chefs emprisonnés. Troisième : torture s''ils refusent de sacrifier. Quatrième : extension à tous les chrétiens.', '[{"text": "Les chefs de l''Église sont jetés en prison.", "translation": "C''est le deuxième édit."}, {"text": "Tous les chrétiens sont visés par le quatrième édit.", "translation": "Il élargit à tous les mesures précédentes."}]'::jsonb, null, '{"id": "eg.d.quatre_edits", "word": "les quatre édits de 303", "translation": "décrets de Dioclétien pour éradiquer le christianisme", "partOfSpeech": "concept", "explanation": "Premier : églises rasées et livres brûlés. Deuxième : chefs emprisonnés. Troisième : torture s''ils refusent de sacrifier. Quatrième : extension à tous les chrétiens.", "examples": [{"text": "Les chefs de l''Église sont jetés en prison.", "translation": "C''est le deuxième édit."}, {"text": "Tous les chrétiens sont visés par le quatrième édit.", "translation": "Il élargit à tous les mesures précédentes."}], "unitId": "eg.v.quatre_edits"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.edit_de_tolerance_311', 'eg', 'l''édit de tolérance (311)', 'édit de Galère qui autorise les chrétiens à exister et à prier', 'Signé par Galère en 311, il met fin à la grande persécution. Il précède l''édit de Milan de 313.', '[{"text": "En 311, Galère autorise les chrétiens à prier.", "translation": "Même pour l''empereur."}, {"text": "L''édit de 311 précède celui de Milan.", "translation": "La liberté complète viendra deux ans plus tard."}]'::jsonb, null, '{"id": "eg.d.edit_de_tolerance_311", "word": "l''édit de tolérance (311)", "translation": "édit de Galère qui autorise les chrétiens à exister et à prier", "partOfSpeech": "event", "explanation": "Signé par Galère en 311, il met fin à la grande persécution. Il précède l''édit de Milan de 313.", "examples": [{"text": "En 311, Galère autorise les chrétiens à prier.", "translation": "Même pour l''empereur."}, {"text": "L''édit de 311 précède celui de Milan.", "translation": "La liberté complète viendra deux ans plus tard."}], "unitId": "eg.v.edit_de_tolerance_311"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pierre_sceau_des_martyrs', 'eg', 'le pape Pierre, sceau des martyrs', 'pape d''Alexandrie martyrisé en 311', 'Pape d''Alexandrie, il est martyrisé en 311, à la fin de la grande persécution. On l''appelle « le sceau des martyrs » parce qu''il clôt la liste de cette épreuve.', '[{"text": "Le pape Pierre meurt martyr en 311.", "translation": "Il est le sceau des martyrs."}, {"text": "Pierre avait ordonné Arius diacre en 311.", "translation": "Nous retrouverons Arius très bientôt."}]'::jsonb, null, '{"id": "eg.d.pierre_sceau_des_martyrs", "word": "le pape Pierre, sceau des martyrs", "translation": "pape d''Alexandrie martyrisé en 311", "partOfSpeech": "person", "explanation": "Pape d''Alexandrie, il est martyrisé en 311, à la fin de la grande persécution. On l''appelle « le sceau des martyrs » parce qu''il clôt la liste de cette épreuve.", "examples": [{"text": "Le pape Pierre meurt martyr en 311.", "translation": "Il est le sceau des martyrs."}, {"text": "Pierre avait ordonné Arius diacre en 311.", "translation": "Nous retrouverons Arius très bientôt."}], "unitId": "eg.v.pierre_sceau_des_martyrs"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_georges', 'eg', 'saint Georges', 'martyr de la grande persécution, vers 303', 'Soldat et martyr, il est mis à mort vers 303 pendant la persécution de Dioclétien. Il est très vénéré en Égypte.', '[{"text": "Saint Georges est martyrisé vers 303.", "translation": "C''est le début de la grande persécution."}, {"text": "Beaucoup d''églises coptes portent son nom.", "translation": "Sa fête est très populaire."}]'::jsonb, null, '{"id": "eg.d.saint_georges", "word": "saint Georges", "translation": "martyr de la grande persécution, vers 303", "partOfSpeech": "person", "explanation": "Soldat et martyr, il est mis à mort vers 303 pendant la persécution de Dioclétien. Il est très vénéré en Égypte.", "examples": [{"text": "Saint Georges est martyrisé vers 303.", "translation": "C''est le début de la grande persécution."}, {"text": "Beaucoup d''églises coptes portent son nom.", "translation": "Sa fête est très populaire."}], "unitId": "eg.v.saint_georges"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_mina', 'eg', 'saint Mina', 'martyr de la grande persécution, vers 309', 'Martyr de la fin de la grande persécution, vers 309. Son tombeau, près d''Alexandrie, est devenu un grand lieu de pèlerinage.', '[{"text": "Saint Mina est martyrisé vers 309.", "translation": "Il fait partie des victimes de Galère."}, {"text": "Un grand monastère porte son nom près d''Alexandrie.", "translation": "C''est un lieu de pèlerinage célèbre."}]'::jsonb, null, '{"id": "eg.d.saint_mina", "word": "saint Mina", "translation": "martyr de la grande persécution, vers 309", "partOfSpeech": "person", "explanation": "Martyr de la fin de la grande persécution, vers 309. Son tombeau, près d''Alexandrie, est devenu un grand lieu de pèlerinage.", "examples": [{"text": "Saint Mina est martyrisé vers 309.", "translation": "Il fait partie des victimes de Galère."}, {"text": "Un grand monastère porte son nom près d''Alexandrie.", "translation": "C''est un lieu de pèlerinage célèbre."}], "unitId": "eg.v.saint_mina"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.constantin', 'eg', 'Constantin', 'empereur romain (306-337), protecteur de l''Église', 'Fils d''Hélène, empereur dès 306, il voit la croix en 312, signe l''édit de Milan en 313 et fonde Constantinople en 330.', '[{"text": "Constantin voit la croix avant la bataille de 312.", "translation": "Il fait peindre la croix sur son drapeau."}, {"text": "Constantin convoque le concile de Nicée.", "translation": "Il se présente comme l''évêque du dehors."}]'::jsonb, null, '{"id": "eg.d.constantin", "word": "Constantin", "translation": "empereur romain (306-337), protecteur de l''Église", "partOfSpeech": "person", "explanation": "Fils d''Hélène, empereur dès 306, il voit la croix en 312, signe l''édit de Milan en 313 et fonde Constantinople en 330.", "examples": [{"text": "Constantin voit la croix avant la bataille de 312.", "translation": "Il fait peindre la croix sur son drapeau."}, {"text": "Constantin convoque le concile de Nicée.", "translation": "Il se présente comme l''évêque du dehors."}], "unitId": "eg.v.constantin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.helene', 'eg', 'Hélène', 'mère de Constantin, qui retrouve la Sainte Croix', 'Mère de Constantin, elle part à Jérusalem, retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection et d''autres églises.', '[{"text": "Hélène fait bâtir la basilique de la Résurrection.", "translation": "C''est à Jérusalem."}, {"text": "L''Église copte vénère sainte Hélène.", "translation": "Elle est fêtée avec son fils Constantin."}]'::jsonb, null, '{"id": "eg.d.helene", "word": "Hélène", "translation": "mère de Constantin, qui retrouve la Sainte Croix", "partOfSpeech": "person", "explanation": "Mère de Constantin, elle part à Jérusalem, retrouve la Sainte Croix et fait bâtir la basilique de la Résurrection et d''autres églises.", "examples": [{"text": "Hélène fait bâtir la basilique de la Résurrection.", "translation": "C''est à Jérusalem."}, {"text": "L''Église copte vénère sainte Hélène.", "translation": "Elle est fêtée avec son fils Constantin."}], "unitId": "eg.v.helene"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.maxence', 'eg', 'Maxence', 'rival de Constantin, vaincu à Rome en 312', 'Empereur à Rome, il est battu par Constantin en 312 et meurt quand le pont sur le Tibre s''écroule.', '[{"text": "Maxence se noie dans le Tibre.", "translation": "Le pont s''écroule sous lui."}, {"text": "Constantin marche sur Rome contre Maxence.", "translation": "La bataille se joue en 312."}]'::jsonb, null, '{"id": "eg.d.maxence", "word": "Maxence", "translation": "rival de Constantin, vaincu à Rome en 312", "partOfSpeech": "person", "explanation": "Empereur à Rome, il est battu par Constantin en 312 et meurt quand le pont sur le Tibre s''écroule.", "examples": [{"text": "Maxence se noie dans le Tibre.", "translation": "Le pont s''écroule sous lui."}, {"text": "Constantin marche sur Rome contre Maxence.", "translation": "La bataille se joue en 312."}], "unitId": "eg.v.maxence"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.edit_de_milan', 'eg', 'l''édit de Milan (313)', 'édit de tolérance signé par Constantin et Licinius', 'Signé en 313, il met fin aux persécutions romaines, rend aux chrétiens leurs biens et ouvre un siècle de paix.', '[{"text": "L''édit de Milan date de 313.", "translation": "Il met fin aux persécutions romaines."}, {"text": "Les biens confisqués sont restitués.", "translation": "C''est le résultat de la paix de Constantin."}]'::jsonb, null, '{"id": "eg.d.edit_de_milan", "word": "l''édit de Milan (313)", "translation": "édit de tolérance signé par Constantin et Licinius", "partOfSpeech": "event", "explanation": "Signé en 313, il met fin aux persécutions romaines, rend aux chrétiens leurs biens et ouvre un siècle de paix.", "examples": [{"text": "L''édit de Milan date de 313.", "translation": "Il met fin aux persécutions romaines."}, {"text": "Les biens confisqués sont restitués.", "translation": "C''est le résultat de la paix de Constantin."}], "unitId": "eg.v.edit_de_milan"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.licinius', 'eg', 'Licinius', 'empereur, co-signataire de l''édit de Milan', 'Empereur d''Orient, il signe avec Constantin l''édit de Milan en 313.', '[{"text": "Licinius signe l''édit de Milan avec Constantin.", "translation": "Ils sont alors alliés."}, {"text": "En 313, deux empereurs signent la paix.", "translation": "Constantin et Licinius."}]'::jsonb, null, '{"id": "eg.d.licinius", "word": "Licinius", "translation": "empereur, co-signataire de l''édit de Milan", "partOfSpeech": "person", "explanation": "Empereur d''Orient, il signe avec Constantin l''édit de Milan en 313.", "examples": [{"text": "Licinius signe l''édit de Milan avec Constantin.", "translation": "Ils sont alors alliés."}, {"text": "En 313, deux empereurs signent la paix.", "translation": "Constantin et Licinius."}], "unitId": "eg.v.licinius"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.constantinople', 'eg', 'Constantinople', 'capitale de l''empire d''Orient, fondée en 330', 'Byzance renommée « ville de Constantin » en 330. Elle deviendra un siège majeur de l''Église.', '[{"text": "Constantinople est fondée en 330.", "translation": "Elle remplace Byzance."}, {"text": "Sainte-Sophie est bâtie à Constantinople.", "translation": "C''est la capitale de l''empire d''Orient."}]'::jsonb, null, '{"id": "eg.d.constantinople", "word": "Constantinople", "translation": "capitale de l''empire d''Orient, fondée en 330", "partOfSpeech": "place", "explanation": "Byzance renommée « ville de Constantin » en 330. Elle deviendra un siège majeur de l''Église.", "examples": [{"text": "Constantinople est fondée en 330.", "translation": "Elle remplace Byzance."}, {"text": "Sainte-Sophie est bâtie à Constantinople.", "translation": "C''est la capitale de l''empire d''Orient."}], "unitId": "eg.v.constantinople"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eveque_du_dehors', 'eg', 'l''évêque du dehors', 'titre que l''empereur se donne pour les affaires extérieures de l''Église', 'L''empereur Constantin se dit chargé des affaires extérieures de l''Église. Cela crée un danger : l''État intervient dans les débats de foi.', '[{"text": "Constantin se dit « évêque du dehors ».", "translation": "Il pèse sur les conciles."}, {"text": "L''Église et l''État s''entremêlent.", "translation": "C''est un risque pour la foi."}]'::jsonb, null, '{"id": "eg.d.eveque_du_dehors", "word": "l''évêque du dehors", "translation": "titre que l''empereur se donne pour les affaires extérieures de l''Église", "partOfSpeech": "concept", "explanation": "L''empereur Constantin se dit chargé des affaires extérieures de l''Église. Cela crée un danger : l''État intervient dans les débats de foi.", "examples": [{"text": "Constantin se dit « évêque du dehors ».", "translation": "Il pèse sur les conciles."}, {"text": "L''Église et l''État s''entremêlent.", "translation": "C''est un risque pour la foi."}], "unitId": "eg.v.eveque_du_dehors"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.armenie', 'eg', 'l''Arménie', 'premier pays chrétien, en 301', 'En 301, l''Arménie est le premier pays du monde à adopter le christianisme comme religion d''État.', '[{"text": "L''Arménie devient chrétienne en 301.", "translation": "Avant l''Empire romain."}, {"text": "Elle est le premier État chrétien.", "translation": "Son choix précède Milan de douze ans."}]'::jsonb, null, '{"id": "eg.d.armenie", "word": "l''Arménie", "translation": "premier pays chrétien, en 301", "partOfSpeech": "place", "explanation": "En 301, l''Arménie est le premier pays du monde à adopter le christianisme comme religion d''État.", "examples": [{"text": "L''Arménie devient chrétienne en 301.", "translation": "Avant l''Empire romain."}, {"text": "Elle est le premier État chrétien.", "translation": "Son choix précède Milan de douze ans."}], "unitId": "eg.v.armenie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.arius', 'eg', 'Arius', 'prêtre d''Alexandrie, auteur de l''hérésie arienne', 'Prêtre libyen d''origine berbère, ordonné diacre en 311 par le pape Pierre. Vers 318, il enseigne que le Fils n''est pas de la même essence que le Père.', '[{"text": "Arius enseigne vers 318 à Alexandrie.", "translation": "Il met ses idées en chansons."}, {"text": "Arius est condamné au concile de Nicée.", "translation": "Le concile l''excommunie."}]'::jsonb, null, '{"id": "eg.d.arius", "word": "Arius", "translation": "prêtre d''Alexandrie, auteur de l''hérésie arienne", "partOfSpeech": "person", "explanation": "Prêtre libyen d''origine berbère, ordonné diacre en 311 par le pape Pierre. Vers 318, il enseigne que le Fils n''est pas de la même essence que le Père.", "examples": [{"text": "Arius enseigne vers 318 à Alexandrie.", "translation": "Il met ses idées en chansons."}, {"text": "Arius est condamné au concile de Nicée.", "translation": "Le concile l''excommunie."}], "unitId": "eg.v.arius"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.arianisme', 'eg', 'l''arianisme', 'hérésie qui nie la divinité du Christ', 'Pour l''arianisme, le Fils est créé et n''est pas de la même essence que le Père. Il a continué sous diverses formes à travers les siècles.', '[{"text": "L''arianisme nie la divinité du Christ.", "translation": "Le Fils serait un être créé."}, {"text": "Athanase combat l''arianisme toute sa vie.", "translation": "Il est exilé plusieurs fois."}]'::jsonb, null, '{"id": "eg.d.arianisme", "word": "l''arianisme", "translation": "hérésie qui nie la divinité du Christ", "partOfSpeech": "concept", "explanation": "Pour l''arianisme, le Fils est créé et n''est pas de la même essence que le Père. Il a continué sous diverses formes à travers les siècles.", "examples": [{"text": "L''arianisme nie la divinité du Christ.", "translation": "Le Fils serait un être créé."}, {"text": "Athanase combat l''arianisme toute sa vie.", "translation": "Il est exilé plusieurs fois."}], "unitId": "eg.v.arianisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.alexandre_d_alexandrie', 'eg', 'le pape Alexandre', '19e pape d''Alexandrie, adversaire d''Arius', 'Pape d''Alexandrie au moment où Arius enseigne. Il préside le concile de Nicée, selon la tradition copte, avec son jeune diacre Athanase.', '[{"text": "Le pape Alexandre affronte Arius.", "translation": "Il refuse sa doctrine."}, {"text": "Athanase est son secrétaire.", "translation": "Il lui succédera comme pape."}]'::jsonb, null, '{"id": "eg.d.alexandre_d_alexandrie", "word": "le pape Alexandre", "translation": "19e pape d''Alexandrie, adversaire d''Arius", "partOfSpeech": "person", "explanation": "Pape d''Alexandrie au moment où Arius enseigne. Il préside le concile de Nicée, selon la tradition copte, avec son jeune diacre Athanase.", "examples": [{"text": "Le pape Alexandre affronte Arius.", "translation": "Il refuse sa doctrine."}, {"text": "Athanase est son secrétaire.", "translation": "Il lui succédera comme pape."}], "unitId": "eg.v.alexandre_d_alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eusebe_de_nicomedie', 'eg', 'Eusèbe de Nicomédie', 'évêque séduit par Arius', 'Évêque puissant, proche de la cour impériale, il adopte les thèses d''Arius et devient son grand protecteur.', '[{"text": "Eusèbe de Nicomédie soutient Arius.", "translation": "Il est très influent."}, {"text": "Il signera le credo mais pas les anathèmes.", "translation": "Il aidera à propager l''arianisme."}]'::jsonb, null, '{"id": "eg.d.eusebe_de_nicomedie", "word": "Eusèbe de Nicomédie", "translation": "évêque séduit par Arius", "partOfSpeech": "person", "explanation": "Évêque puissant, proche de la cour impériale, il adopte les thèses d''Arius et devient son grand protecteur.", "examples": [{"text": "Eusèbe de Nicomédie soutient Arius.", "translation": "Il est très influent."}, {"text": "Il signera le credo mais pas les anathèmes.", "translation": "Il aidera à propager l''arianisme."}], "unitId": "eg.v.eusebe_de_nicomedie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.semi_arianisme', 'eg', 'le semi-arianisme', 'position intermédiaire : le Fils aurait une substance similaire', 'Les semi-ariens disent que le Christ a une substance similaire (homoiousios) à celle du Père, mais pas la même. Ton cours associe cette position à Eusèbe de Césarée.', '[{"text": "Le semi-arianisme est une voie du milieu.", "translation": "Le Fils serait seulement semblable au Père."}, {"text": "Un iota sépare les deux mots.", "translation": "Homoiousios, c''est « substance semblable »."}]'::jsonb, null, '{"id": "eg.d.semi_arianisme", "word": "le semi-arianisme", "translation": "position intermédiaire : le Fils aurait une substance similaire", "partOfSpeech": "concept", "explanation": "Les semi-ariens disent que le Christ a une substance similaire (homoiousios) à celle du Père, mais pas la même. Ton cours associe cette position à Eusèbe de Césarée.", "examples": [{"text": "Le semi-arianisme est une voie du milieu.", "translation": "Le Fils serait seulement semblable au Père."}, {"text": "Un iota sépare les deux mots.", "translation": "Homoiousios, c''est « substance semblable »."}], "unitId": "eg.v.semi_arianisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.homoousios', 'eg', 'homoousios', 'mot grec : de même substance que le Père', 'Mot-clé de Nicée : le Fils est consubstantiel au Père, c''est-à-dire de même substance. Les ariens refusent ce mot.', '[{"text": "Le Fils est homoousios au Père.", "translation": "Il est de même substance."}, {"text": "Le credo de Nicée utilise ce mot.", "translation": "Il traduit la foi d''Athanase."}]'::jsonb, null, '{"id": "eg.d.homoousios", "word": "homoousios", "translation": "mot grec : de même substance que le Père", "partOfSpeech": "concept", "explanation": "Mot-clé de Nicée : le Fils est consubstantiel au Père, c''est-à-dire de même substance. Les ariens refusent ce mot.", "examples": [{"text": "Le Fils est homoousios au Père.", "translation": "Il est de même substance."}, {"text": "Le credo de Nicée utilise ce mot.", "translation": "Il traduit la foi d''Athanase."}], "unitId": "eg.v.homoousios"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.divinite_du_christ', 'eg', 'la divinité du Christ', 'vérité centrale : Jésus est Dieu', 'L''Église croit que le Christ est vrai Dieu et vrai homme. Sans sa divinité, il ne pourrait pas sauver l''homme.', '[{"text": "Arius nie la divinité du Christ.", "translation": "L''Église la défend à Nicée."}, {"text": "Seul Dieu peut sauver l''homme.", "translation": "Voilà pourquoi elle est essentielle."}]'::jsonb, null, '{"id": "eg.d.divinite_du_christ", "word": "la divinité du Christ", "translation": "vérité centrale : Jésus est Dieu", "partOfSpeech": "concept", "explanation": "L''Église croit que le Christ est vrai Dieu et vrai homme. Sans sa divinité, il ne pourrait pas sauver l''homme.", "examples": [{"text": "Arius nie la divinité du Christ.", "translation": "L''Église la défend à Nicée."}, {"text": "Seul Dieu peut sauver l''homme.", "translation": "Voilà pourquoi elle est essentielle."}], "unitId": "eg.v.divinite_du_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_de_nicee', 'eg', 'le concile de Nicée', 'premier concile œcuménique (325), contre l''arianisme', 'Convoqué par Constantin, il réunit 318 évêques, condamne Arius, définit le Fils comme homoousios et établit le credo et vingt canons.', '[{"text": "Le concile de Nicée a lieu en 325.", "translation": "318 évêques y participent."}, {"text": "Il condamne Arius et son enseignement.", "translation": "Athanase y joue un rôle clé."}]'::jsonb, null, '{"id": "eg.d.concile_de_nicee", "word": "le concile de Nicée", "translation": "premier concile œcuménique (325), contre l''arianisme", "partOfSpeech": "event", "explanation": "Convoqué par Constantin, il réunit 318 évêques, condamne Arius, définit le Fils comme homoousios et établit le credo et vingt canons.", "examples": [{"text": "Le concile de Nicée a lieu en 325.", "translation": "318 évêques y participent."}, {"text": "Il condamne Arius et son enseignement.", "translation": "Athanase y joue un rôle clé."}], "unitId": "eg.v.concile_de_nicee"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_oecumenique', 'eg', 'le concile œcuménique', 'assemblée d''évêques de toute l''Église', 'Œcuménique veut dire « de toute la terre habitée » : tous les grands sièges sont invités à décider ensemble. Nicée est le premier.', '[{"text": "Nicée est le premier concile œcuménique.", "translation": "Il réunit les évêques de partout."}, {"text": "Constantinople sera le deuxième.", "translation": "Éphèse le troisième."}]'::jsonb, null, '{"id": "eg.d.concile_oecumenique", "word": "le concile œcuménique", "translation": "assemblée d''évêques de toute l''Église", "partOfSpeech": "concept", "explanation": "Œcuménique veut dire « de toute la terre habitée » : tous les grands sièges sont invités à décider ensemble. Nicée est le premier.", "examples": [{"text": "Nicée est le premier concile œcuménique.", "translation": "Il réunit les évêques de partout."}, {"text": "Constantinople sera le deuxième.", "translation": "Éphèse le troisième."}], "unitId": "eg.v.concile_oecumenique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nicee', 'eg', 'Nicée', 'ville de Turquie actuelle où s''est tenu le premier concile', 'Ville proche de Nicomédie, aujourd''hui İznik en Turquie. Elle donne son nom au concile de 325 et au credo.', '[{"text": "Nicée accueille 318 évêques.", "translation": "Constantin les invite."}, {"text": "Le credo prend le nom de Nicée.", "translation": "C''est l''une des grandes villes de l''Orient romain."}]'::jsonb, null, '{"id": "eg.d.nicee", "word": "Nicée", "translation": "ville de Turquie actuelle où s''est tenu le premier concile", "partOfSpeech": "place", "explanation": "Ville proche de Nicomédie, aujourd''hui İznik en Turquie. Elle donne son nom au concile de 325 et au credo.", "examples": [{"text": "Nicée accueille 318 évêques.", "translation": "Constantin les invite."}, {"text": "Le credo prend le nom de Nicée.", "translation": "C''est l''une des grandes villes de l''Orient romain."}], "unitId": "eg.v.nicee"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.credo_de_nicee', 'eg', 'le credo de Nicée', 'texte de foi rédigé en 325, base du Credo', 'Il affirme la divinité du Fils, de même substance que le Père. Complété en 381, il devient le Credo récité à la messe.', '[{"text": "Le credo de Nicée est rédigé en 325.", "translation": "Alexandre et Athanase y participent."}, {"text": "Il dit que le Fils est homoousios.", "translation": "Constantinople le complète en 381."}]'::jsonb, null, '{"id": "eg.d.credo_de_nicee", "word": "le credo de Nicée", "translation": "texte de foi rédigé en 325, base du Credo", "partOfSpeech": "work", "explanation": "Il affirme la divinité du Fils, de même substance que le Père. Complété en 381, il devient le Credo récité à la messe.", "examples": [{"text": "Le credo de Nicée est rédigé en 325.", "translation": "Alexandre et Athanase y participent."}, {"text": "Il dit que le Fils est homoousios.", "translation": "Constantinople le complète en 381."}], "unitId": "eg.v.credo_de_nicee"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.anathemes', 'eg', 'les anathèmes', 'condamnations annexées au credo de Nicée', 'Les anathèmes sont des condamnations : ceux de Nicée visent l''enseignement d''Arius. Trois évêques signent le credo mais refusent d''abord les anathèmes.', '[{"text": "Les anathèmes condamnent Arius.", "translation": "Trois évêques refusent d''abord de les signer."}, {"text": "Ils accompagnent le credo.", "translation": "Ils visent la doctrine arienne."}]'::jsonb, null, '{"id": "eg.d.anathemes", "word": "les anathèmes", "translation": "condamnations annexées au credo de Nicée", "partOfSpeech": "concept", "explanation": "Les anathèmes sont des condamnations : ceux de Nicée visent l''enseignement d''Arius. Trois évêques signent le credo mais refusent d''abord les anathèmes.", "examples": [{"text": "Les anathèmes condamnent Arius.", "translation": "Trois évêques refusent d''abord de les signer."}, {"text": "Ils accompagnent le credo.", "translation": "Ils visent la doctrine arienne."}], "unitId": "eg.v.anathemes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eusebe_de_cesaree', 'eg', 'Eusèbe de Césarée', 'évêque historien, ami de Constantin', 'Évêque de Césarée en Palestine (263-339 environ), il est le père de l''histoire ecclésiastique. Ton cours le range parmi les semi-ariens.', '[{"text": "Eusèbe de Césarée raconte les martyrs.", "translation": "Il est l''ami de Constantin."}, {"text": "Il est un historien précieux.", "translation": "Il est considéré comme semi-arien."}]'::jsonb, null, '{"id": "eg.d.eusebe_de_cesaree", "word": "Eusèbe de Césarée", "translation": "évêque historien, ami de Constantin", "partOfSpeech": "person", "explanation": "Évêque de Césarée en Palestine (263-339 environ), il est le père de l''histoire ecclésiastique. Ton cours le range parmi les semi-ariens.", "examples": [{"text": "Eusèbe de Césarée raconte les martyrs.", "translation": "Il est l''ami de Constantin."}, {"text": "Il est un historien précieux.", "translation": "Il est considéré comme semi-arien."}], "unitId": "eg.v.eusebe_de_cesaree"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.les_318_eveques', 'eg', 'les 318 évêques', 'les évêques de Nicée, selon la tradition', 'La tradition retient le nombre de 318 évêques pour Nicée. On les appelle aussi les 318 Pères.', '[{"text": "318 évêques se réunissent.", "translation": "C''est le nombre traditionnel."}, {"text": "Alexandre est parmi eux.", "translation": "Rome est représentée par deux prêtres."}]'::jsonb, null, '{"id": "eg.d.les_318_eveques", "word": "les 318 évêques", "translation": "les évêques de Nicée, selon la tradition", "partOfSpeech": "concept", "explanation": "La tradition retient le nombre de 318 évêques pour Nicée. On les appelle aussi les 318 Pères.", "examples": [{"text": "318 évêques se réunissent.", "translation": "C''est le nombre traditionnel."}, {"text": "Alexandre est parmi eux.", "translation": "Rome est représentée par deux prêtres."}], "unitId": "eg.v.les_318_eveques"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.athanase', 'eg', 'saint Athanase', 'XXe pape d''Alexandrie (vers 328-373), défenseur de la foi', 'Diacre du pape Alexandre à Nicée, puis patriarche, il combat l''arianisme toute sa vie et subit plusieurs exils.', '[{"text": "Athanase naît vers 298.", "translation": "Il meurt en 373."}, {"text": "Athanase succède à Alexandre.", "translation": "Il devient le XXe pape d''Alexandrie."}]'::jsonb, null, '{"id": "eg.d.athanase", "word": "saint Athanase", "translation": "XXe pape d''Alexandrie (vers 328-373), défenseur de la foi", "partOfSpeech": "person", "explanation": "Diacre du pape Alexandre à Nicée, puis patriarche, il combat l''arianisme toute sa vie et subit plusieurs exils.", "examples": [{"text": "Athanase naît vers 298.", "translation": "Il meurt en 373."}, {"text": "Athanase succède à Alexandre.", "translation": "Il devient le XXe pape d''Alexandrie."}], "unitId": "eg.v.athanase"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.defenseur_de_la_foi', 'eg', 'le défenseur de la foi', 'surnom d''Athanase', 'L''Église appelle Athanase le défenseur de la foi car, sans lui, le monde entier aurait suivi Arius.', '[{"text": "Athanase est le défenseur de la foi.", "translation": "Il tient face au monde entier."}, {"text": "Il a répondu : « et je suis contre le monde ».", "translation": "Il ne cède jamais."}]'::jsonb, null, '{"id": "eg.d.defenseur_de_la_foi", "word": "le défenseur de la foi", "translation": "surnom d''Athanase", "partOfSpeech": "concept", "explanation": "L''Église appelle Athanase le défenseur de la foi car, sans lui, le monde entier aurait suivi Arius.", "examples": [{"text": "Athanase est le défenseur de la foi.", "translation": "Il tient face au monde entier."}, {"text": "Il a répondu : « et je suis contre le monde ».", "translation": "Il ne cède jamais."}], "unitId": "eg.v.defenseur_de_la_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sur_l_incarnation_du_verbe', 'eg', '« Sur l''incarnation du Verbe »', 'livre de jeunesse d''Athanase', 'Écrit avant ses 20 ans, il explique que le Christ est parfaitement Dieu et parfaitement homme, sans division de sa personne.', '[{"text": "Athanase l''écrit très jeune.", "translation": "Le Christ est Dieu et homme."}, {"text": "Cette œuvre est une réponse à Arius.", "translation": "Elle reste lue aujourd''hui."}]'::jsonb, null, '{"id": "eg.d.sur_l_incarnation_du_verbe", "word": "« Sur l''incarnation du Verbe »", "translation": "livre de jeunesse d''Athanase", "partOfSpeech": "work", "explanation": "Écrit avant ses 20 ans, il explique que le Christ est parfaitement Dieu et parfaitement homme, sans division de sa personne.", "examples": [{"text": "Athanase l''écrit très jeune.", "translation": "Le Christ est Dieu et homme."}, {"text": "Cette œuvre est une réponse à Arius.", "translation": "Elle reste lue aujourd''hui."}], "unitId": "eg.v.sur_l_incarnation_du_verbe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.vie_d_antoine', 'eg', 'La Vie d''Antoine', 'livre d''Athanase sur saint Antoine', 'Athanase y raconte la vie de saint Antoine. Envoyé à Rome, le livre fait connaître le monachisme à l''Occident.', '[{"text": "La Vie d''Antoine est un livre d''Athanase.", "translation": "Il raconte la vie du père des moines."}, {"text": "Il est envoyé à Rome.", "translation": "Il diffuse le monachisme."}]'::jsonb, null, '{"id": "eg.d.vie_d_antoine", "word": "La Vie d''Antoine", "translation": "livre d''Athanase sur saint Antoine", "partOfSpeech": "work", "explanation": "Athanase y raconte la vie de saint Antoine. Envoyé à Rome, le livre fait connaître le monachisme à l''Occident.", "examples": [{"text": "La Vie d''Antoine est un livre d''Athanase.", "translation": "Il raconte la vie du père des moines."}, {"text": "Il est envoyé à Rome.", "translation": "Il diffuse le monachisme."}], "unitId": "eg.v.vie_d_antoine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.exils_d_athanase', 'eg', 'les exils d''Athanase', 'expulsions répétées d''Athanase par les ariens', 'Plusieurs fois, Athanase est chassé de son siège. Il se réfugie en Occident ou chez les moines du désert, puis revient.', '[{"text": "Athanase est exilé plusieurs fois.", "translation": "Les ariens ont des appuis impériaux."}, {"text": "Il se cache parfois chez les moines.", "translation": "Il revient toujours à Alexandrie."}]'::jsonb, null, '{"id": "eg.d.exils_d_athanase", "word": "les exils d''Athanase", "translation": "expulsions répétées d''Athanase par les ariens", "partOfSpeech": "event", "explanation": "Plusieurs fois, Athanase est chassé de son siège. Il se réfugie en Occident ou chez les moines du désert, puis revient.", "examples": [{"text": "Athanase est exilé plusieurs fois.", "translation": "Les ariens ont des appuis impériaux."}, {"text": "Il se cache parfois chez les moines.", "translation": "Il revient toujours à Alexandrie."}], "unitId": "eg.v.exils_d_athanase"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.frumentius', 'eg', 'Frumentius', 'premier évêque d''Éthiopie, ordonné par Athanase', 'Athanase l''ordonne premier évêque d''Éthiopie vers 341. L''Église éthiopienne dépendra longtemps d''Alexandrie.', '[{"text": "Frumentius est évêque d''Éthiopie.", "translation": "Athanase l''ordonne."}, {"text": "L''Éthiopie reçoit l''Évangile.", "translation": "Alexandrie la guide."}]'::jsonb, null, '{"id": "eg.d.frumentius", "word": "Frumentius", "translation": "premier évêque d''Éthiopie, ordonné par Athanase", "partOfSpeech": "person", "explanation": "Athanase l''ordonne premier évêque d''Éthiopie vers 341. L''Église éthiopienne dépendra longtemps d''Alexandrie.", "examples": [{"text": "Frumentius est évêque d''Éthiopie.", "translation": "Athanase l''ordonne."}, {"text": "L''Éthiopie reçoit l''Évangile.", "translation": "Alexandrie la guide."}], "unitId": "eg.v.frumentius"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monachisme', 'eg', 'le monachisme', 'vie de solitude, de prière et d''ascèse, née en Égypte', 'Le moine consacre sa vie à connaître Dieu et à faire sa volonté. Trois principes : pauvreté, obéissance, chasteté.', '[{"text": "Le monachisme commence en Égypte.", "translation": "Il attire le cœur de l''Église vers le désert."}, {"text": "Le moine vit de prière et de jeûne.", "translation": "Il fait vœu de pauvreté, d''obéissance et de chasteté."}]'::jsonb, null, '{"id": "eg.d.monachisme", "word": "le monachisme", "translation": "vie de solitude, de prière et d''ascèse, née en Égypte", "partOfSpeech": "concept", "explanation": "Le moine consacre sa vie à connaître Dieu et à faire sa volonté. Trois principes : pauvreté, obéissance, chasteté.", "examples": [{"text": "Le monachisme commence en Égypte.", "translation": "Il attire le cœur de l''Église vers le désert."}, {"text": "Le moine vit de prière et de jeûne.", "translation": "Il fait vœu de pauvreté, d''obéissance et de chasteté."}], "unitId": "eg.v.monachisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_antoine', 'eg', 'saint Antoine le Grand', 'père des moines (251-356)', 'Copte de Haute-Égypte, premier moine du monde. Athanase raconte sa vie.', '[{"text": "Antoine est né en 251.", "translation": "Il meurt en 356."}, {"text": "Il vit seul au désert.", "translation": "Tous les premiers moines sont ses disciples."}]'::jsonb, null, '{"id": "eg.d.saint_antoine", "word": "saint Antoine le Grand", "translation": "père des moines (251-356)", "partOfSpeech": "person", "explanation": "Copte de Haute-Égypte, premier moine du monde. Athanase raconte sa vie.", "examples": [{"text": "Antoine est né en 251.", "translation": "Il meurt en 356."}, {"text": "Il vit seul au désert.", "translation": "Tous les premiers moines sont ses disciples."}], "unitId": "eg.v.saint_antoine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_paul_l_ermite', 'eg', 'saint Paul l''ermite', 'premier ermite, mort vers 342', 'La tradition le tient pour le premier ermite du désert d''Égypte.', '[{"text": "Paul vit seul au désert.", "translation": "Il meurt vers 342."}, {"text": "Antoine suit sa voie.", "translation": "Il est un modèle de solitude."}]'::jsonb, null, '{"id": "eg.d.saint_paul_l_ermite", "word": "saint Paul l''ermite", "translation": "premier ermite, mort vers 342", "partOfSpeech": "person", "explanation": "La tradition le tient pour le premier ermite du désert d''Égypte.", "examples": [{"text": "Paul vit seul au désert.", "translation": "Il meurt vers 342."}, {"text": "Antoine suit sa voie.", "translation": "Il est un modèle de solitude."}], "unitId": "eg.v.saint_paul_l_ermite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_pacome', 'eg', 'saint Pacôme', 'fondateur des premiers monastères communautaires', 'Il fonde en Haute-Égypte les premiers monastères cénobitiques et en écrit les premières règles.', '[{"text": "Pacôme vit en Haute-Égypte.", "translation": "Il fonde la vie en communauté."}, {"text": "Ses règles inspirent l''Europe.", "translation": "Il organise les monastères."}]'::jsonb, null, '{"id": "eg.d.saint_pacome", "word": "saint Pacôme", "translation": "fondateur des premiers monastères communautaires", "partOfSpeech": "person", "explanation": "Il fonde en Haute-Égypte les premiers monastères cénobitiques et en écrit les premières règles.", "examples": [{"text": "Pacôme vit en Haute-Égypte.", "translation": "Il fonde la vie en communauté."}, {"text": "Ses règles inspirent l''Europe.", "translation": "Il organise les monastères."}], "unitId": "eg.v.saint_pacome"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.vie_cenobitique', 'eg', 'la vie cénobitique', 'vie des moines en communauté', 'Cénobitique veut dire vie en communauté, par opposition à la vie d''ermite, solitaire.', '[{"text": "Pacôme invente la vie cénobitique.", "translation": "Les moines vivent ensemble."}, {"text": "Ils suivent une règle.", "translation": "Ils prient et travaillent ensemble."}]'::jsonb, null, '{"id": "eg.d.vie_cenobitique", "word": "la vie cénobitique", "translation": "vie des moines en communauté", "partOfSpeech": "concept", "explanation": "Cénobitique veut dire vie en communauté, par opposition à la vie d''ermite, solitaire.", "examples": [{"text": "Pacôme invente la vie cénobitique.", "translation": "Les moines vivent ensemble."}, {"text": "Ils suivent une règle.", "translation": "Ils prient et travaillent ensemble."}], "unitId": "eg.v.vie_cenobitique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_macaire_le_grand', 'eg', 'saint Macaire le Grand', 'père de Scété (mort en 391)', 'Moine du désert de Scété, il a de nombreux disciples. Il meurt en 391.', '[{"text": "Macaire a de nombreux disciples.", "translation": "Il meurt en 391."}, {"text": "Il vit à Scété.", "translation": "Le monachisme progresse sous lui."}]'::jsonb, null, '{"id": "eg.d.saint_macaire_le_grand", "word": "saint Macaire le Grand", "translation": "père de Scété (mort en 391)", "partOfSpeech": "person", "explanation": "Moine du désert de Scété, il a de nombreux disciples. Il meurt en 391.", "examples": [{"text": "Macaire a de nombreux disciples.", "translation": "Il meurt en 391."}, {"text": "Il vit à Scété.", "translation": "Le monachisme progresse sous lui."}], "unitId": "eg.v.saint_macaire_le_grand"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.scete', 'eg', 'Scété', 'désert de saint Macaire', 'Désert d''Égypte où saint Macaire rassemble des moines. Il accueille encore des monastères aujourd''hui.', '[{"text": "Macaire vit à Scété.", "translation": "Scété est un désert."}, {"text": "Des moines y vivent encore.", "translation": "Il est un lieu saint copte."}]'::jsonb, null, '{"id": "eg.d.scete", "word": "Scété", "translation": "désert de saint Macaire", "partOfSpeech": "place", "explanation": "Désert d''Égypte où saint Macaire rassemble des moines. Il accueille encore des monastères aujourd''hui.", "examples": [{"text": "Macaire vit à Scété.", "translation": "Scété est un désert."}, {"text": "Des moines y vivent encore.", "translation": "Il est un lieu saint copte."}], "unitId": "eg.v.scete"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jean_cassien', 'eg', 'Jean Cassien', 'moine qui fait connaître le monachisme égyptien à l''Occident', 'Il visite l''Égypte et transmet à l''Occident la littérature monastique.', '[{"text": "Jean Cassien écrit pour l''Occident.", "translation": "Il parle du désert d''Égypte."}, {"text": "Il diffuse la littérature monastique.", "translation": "Les Latins le lisent."}]'::jsonb, null, '{"id": "eg.d.jean_cassien", "word": "Jean Cassien", "translation": "moine qui fait connaître le monachisme égyptien à l''Occident", "partOfSpeech": "person", "explanation": "Il visite l''Égypte et transmet à l''Occident la littérature monastique.", "examples": [{"text": "Jean Cassien écrit pour l''Occident.", "translation": "Il parle du désert d''Égypte."}, {"text": "Il diffuse la littérature monastique.", "translation": "Les Latins le lisent."}], "unitId": "eg.v.jean_cassien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chenoute', 'eg', 'saint Chénouté', 'père du troisième système monastique', 'Moine de Haute-Égypte, un peu plus tard (Ve siècle), il impose une discipline communautaire stricte.', '[{"text": "Chénouté vit en Haute-Égypte.", "translation": "Il est le troisième modèle monastique."}, {"text": "Sa discipline est stricte.", "translation": "Il vient après Antoine et Pacôme."}]'::jsonb, null, '{"id": "eg.d.chenoute", "word": "saint Chénouté", "translation": "père du troisième système monastique", "partOfSpeech": "person", "explanation": "Moine de Haute-Égypte, un peu plus tard (Ve siècle), il impose une discipline communautaire stricte.", "examples": [{"text": "Chénouté vit en Haute-Égypte.", "translation": "Il est le troisième modèle monastique."}, {"text": "Sa discipline est stricte.", "translation": "Il vient après Antoine et Pacôme."}], "unitId": "eg.v.chenoute"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_de_constantinople', 'eg', 'le concile de Constantinople', 'deuxième concile œcuménique (381), contre Apollinaire et Macédonius', 'Convoqué par Théodose Ier, il réunit 150 évêques, excommunie Apollinaire et Macédonius, complète le credo et établit sept canons.', '[{"text": "Le concile de Constantinople a lieu en 381.", "translation": "Il réunit 150 évêques."}, {"text": "Il complète le credo de Nicée.", "translation": "Il condamne deux hérésies."}]'::jsonb, null, '{"id": "eg.d.concile_de_constantinople", "word": "le concile de Constantinople", "translation": "deuxième concile œcuménique (381), contre Apollinaire et Macédonius", "partOfSpeech": "event", "explanation": "Convoqué par Théodose Ier, il réunit 150 évêques, excommunie Apollinaire et Macédonius, complète le credo et établit sept canons.", "examples": [{"text": "Le concile de Constantinople a lieu en 381.", "translation": "Il réunit 150 évêques."}, {"text": "Il complète le credo de Nicée.", "translation": "Il condamne deux hérésies."}], "unitId": "eg.v.concile_de_constantinople"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.theodose_ier', 'eg', 'Théodose Ier', 'empereur (379-395) qui convoque le concile de 381', 'Empereur qui proclame le christianisme religion de l''État en 380 et convoque le concile de Constantinople en 381.', '[{"text": "Théodose Ier convoque le concile.", "translation": "Il règne à partir de 379."}, {"text": "Il proclame le christianisme religion de l''État.", "translation": "Théodose II convoquera Éphèse."}]'::jsonb, null, '{"id": "eg.d.theodose_ier", "word": "Théodose Ier", "translation": "empereur (379-395) qui convoque le concile de 381", "partOfSpeech": "person", "explanation": "Empereur qui proclame le christianisme religion de l''État en 380 et convoque le concile de Constantinople en 381.", "examples": [{"text": "Théodose Ier convoque le concile.", "translation": "Il règne à partir de 379."}, {"text": "Il proclame le christianisme religion de l''État.", "translation": "Théodose II convoquera Éphèse."}], "unitId": "eg.v.theodose_ier"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apollinaire', 'eg', 'Apollinaire de Laodicée', 'évêque qui nie l''âme humaine du Christ', 'Évêque de Laodicée, il enseigne que le Fils a un corps humain mais pas d''âme humaine. Il est excommunié en 362 puis en 381.', '[{"text": "Apollinaire est évêque de Laodicée.", "translation": "Il nie l''âme humaine du Christ."}, {"text": "Athanase l''a excommunié en 362.", "translation": "Le concile le condamne en 381."}]'::jsonb, null, '{"id": "eg.d.apollinaire", "word": "Apollinaire de Laodicée", "translation": "évêque qui nie l''âme humaine du Christ", "partOfSpeech": "person", "explanation": "Évêque de Laodicée, il enseigne que le Fils a un corps humain mais pas d''âme humaine. Il est excommunié en 362 puis en 381.", "examples": [{"text": "Apollinaire est évêque de Laodicée.", "translation": "Il nie l''âme humaine du Christ."}, {"text": "Athanase l''a excommunié en 362.", "translation": "Le concile le condamne en 381."}], "unitId": "eg.v.apollinaire"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.macedonius', 'eg', 'Macédonius', 'évêque de Constantinople qui dit que l''Esprit Saint est créé', 'Évêque de Constantinople, il enseigne que le Saint-Esprit est une créature. Le concile le condamne.', '[{"text": "Macédonius nie la divinité de l''Esprit.", "translation": "Il dit que l''Esprit Saint est créé."}, {"text": "Le pape Timothée débat avec lui.", "translation": "Il est destitué."}]'::jsonb, null, '{"id": "eg.d.macedonius", "word": "Macédonius", "translation": "évêque de Constantinople qui dit que l''Esprit Saint est créé", "partOfSpeech": "person", "explanation": "Évêque de Constantinople, il enseigne que le Saint-Esprit est une créature. Le concile le condamne.", "examples": [{"text": "Macédonius nie la divinité de l''Esprit.", "translation": "Il dit que l''Esprit Saint est créé."}, {"text": "Le pape Timothée débat avec lui.", "translation": "Il est destitué."}], "unitId": "eg.v.macedonius"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.credo_de_nicee_constantinople', 'eg', 'le Credo de Nicée-Constantinople', 'credo complété en 381, récité à la messe', 'Il reprend le credo de Nicée et y ajoute toute la suite depuis « Je crois en l''Esprit Saint ».', '[{"text": "Le Credo est complété en 381.", "translation": "Il parle de l''Esprit Saint."}, {"text": "Nous le récitons à la messe.", "translation": "Il unit Nicée et Constantinople."}]'::jsonb, null, '{"id": "eg.d.credo_de_nicee_constantinople", "word": "le Credo de Nicée-Constantinople", "translation": "credo complété en 381, récité à la messe", "partOfSpeech": "work", "explanation": "Il reprend le credo de Nicée et y ajoute toute la suite depuis « Je crois en l''Esprit Saint ».", "examples": [{"text": "Le Credo est complété en 381.", "translation": "Il parle de l''Esprit Saint."}, {"text": "Nous le récitons à la messe.", "translation": "Il unit Nicée et Constantinople."}], "unitId": "eg.v.credo_de_nicee_constantinople"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_gregoire_le_theologien', 'eg', 'saint Grégoire le Théologien', 'évêque de Nazianze (mort en 390)', 'Ami de saint Basile, il défend la foi de Nicée. Il a composé la liturgie grégorienne et de nombreux poèmes.', '[{"text": "Grégoire est évêque de Nazianze.", "translation": "Il meurt en 390."}, {"text": "Il est un ami de Basile.", "translation": "Il a composé la liturgie grégorienne."}]'::jsonb, null, '{"id": "eg.d.saint_gregoire_le_theologien", "word": "saint Grégoire le Théologien", "translation": "évêque de Nazianze (mort en 390)", "partOfSpeech": "person", "explanation": "Ami de saint Basile, il défend la foi de Nicée. Il a composé la liturgie grégorienne et de nombreux poèmes.", "examples": [{"text": "Grégoire est évêque de Nazianze.", "translation": "Il meurt en 390."}, {"text": "Il est un ami de Basile.", "translation": "Il a composé la liturgie grégorienne."}], "unitId": "eg.v.saint_gregoire_le_theologien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_cyrille_de_jerusalem', 'eg', 'saint Cyrille de Jérusalem', 'père des catéchumènes (mort en 386)', 'Évêque de Jérusalem, il enseigne les catéchumènes. Il est exilé seize ans et meurt en 386.', '[{"text": "Cyrille est évêque de Jérusalem.", "translation": "Il est le père des catéchumènes."}, {"text": "Il est exilé seize ans.", "translation": "Il meurt en 386."}]'::jsonb, null, '{"id": "eg.d.saint_cyrille_de_jerusalem", "word": "saint Cyrille de Jérusalem", "translation": "père des catéchumènes (mort en 386)", "partOfSpeech": "person", "explanation": "Évêque de Jérusalem, il enseigne les catéchumènes. Il est exilé seize ans et meurt en 386.", "examples": [{"text": "Cyrille est évêque de Jérusalem.", "translation": "Il est le père des catéchumènes."}, {"text": "Il est exilé seize ans.", "translation": "Il meurt en 386."}], "unitId": "eg.v.saint_cyrille_de_jerusalem"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pape_timothee', 'eg', 'le pape Timothée', 'pape d''Alexandrie présent au concile de 381', 'Le pape d''Alexandrie, selon ton cours, participe au concile et débat avec Apollinaire et Macédonius.', '[{"text": "Timothée d''Alexandrie est au concile.", "translation": "Il répond à Apollinaire."}, {"text": "Il débat avec Macédonius.", "translation": "Il défend la foi orthodoxe."}]'::jsonb, null, '{"id": "eg.d.pape_timothee", "word": "le pape Timothée", "translation": "pape d''Alexandrie présent au concile de 381", "partOfSpeech": "person", "explanation": "Le pape d''Alexandrie, selon ton cours, participe au concile et débat avec Apollinaire et Macédonius.", "examples": [{"text": "Timothée d''Alexandrie est au concile.", "translation": "Il répond à Apollinaire."}, {"text": "Il débat avec Macédonius.", "translation": "Il défend la foi orthodoxe."}], "unitId": "eg.v.pape_timothee"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.religion_d_etat_380', 'eg', '380 : religion de l''État', 'année où le christianisme devient religion de l''État', 'En 380, le christianisme est proclamé religion de l''État dans l''empire romain, sous Théodose Ier.', '[{"text": "380 : religion de l''État.", "translation": "Sous Théodose Ier."}, {"text": "Un an avant Constantinople.", "translation": "L''Église et l''État se rapprochent encore."}]'::jsonb, null, '{"id": "eg.d.religion_d_etat_380", "word": "380 : religion de l''État", "translation": "année où le christianisme devient religion de l''État", "partOfSpeech": "date", "explanation": "En 380, le christianisme est proclamé religion de l''État dans l''empire romain, sous Théodose Ier.", "examples": [{"text": "380 : religion de l''État.", "translation": "Sous Théodose Ier."}, {"text": "Un an avant Constantinople.", "translation": "L''Église et l''État se rapprochent encore."}], "unitId": "eg.v.religion_d_etat_380"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_basile_le_grand', 'eg', 'saint Basile le Grand', 'évêque de Césarée de Cappadoce (mort en 379)', 'Ami de Grégoire de Nazianze, il est l''auteur de la liturgie de saint Basile, très utilisée dans l''Église copte.', '[{"text": "Basile meurt en 379.", "translation": "Il est évêque de Césarée de Cappadoce."}, {"text": "Sa liturgie est célébrée par les Coptes.", "translation": "Il est l''ami de Grégoire de Nazianze."}]'::jsonb, null, '{"id": "eg.d.saint_basile_le_grand", "word": "saint Basile le Grand", "translation": "évêque de Césarée de Cappadoce (mort en 379)", "partOfSpeech": "person", "explanation": "Ami de Grégoire de Nazianze, il est l''auteur de la liturgie de saint Basile, très utilisée dans l''Église copte.", "examples": [{"text": "Basile meurt en 379.", "translation": "Il est évêque de Césarée de Cappadoce."}, {"text": "Sa liturgie est célébrée par les Coptes.", "translation": "Il est l''ami de Grégoire de Nazianze."}], "unitId": "eg.v.saint_basile_le_grand"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_ephrem_le_syrien', 'eg', 'saint Éphrem le Syrien', 'diacre syrien et poète (mort en 373)', 'Diacre et poète syrien, il écrit des hymnes qui nourrissent encore la prière des Églises.', '[{"text": "Éphrem meurt en 373.", "translation": "Il écrit des hymnes."}, {"text": "Il est diacre.", "translation": "Il est syrien."}]'::jsonb, null, '{"id": "eg.d.saint_ephrem_le_syrien", "word": "saint Éphrem le Syrien", "translation": "diacre syrien et poète (mort en 373)", "partOfSpeech": "person", "explanation": "Diacre et poète syrien, il écrit des hymnes qui nourrissent encore la prière des Églises.", "examples": [{"text": "Éphrem meurt en 373.", "translation": "Il écrit des hymnes."}, {"text": "Il est diacre.", "translation": "Il est syrien."}], "unitId": "eg.v.saint_ephrem_le_syrien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_ambroise_de_milan', 'eg', 'saint Ambroise de Milan', 'évêque de Milan (mort en 397)', 'Grand évêque de l''Occident, il baptise saint Augustin. Il meurt en 397.', '[{"text": "Ambroise est évêque de Milan.", "translation": "Il baptise Augustin."}, {"text": "Il meurt en 397.", "translation": "Il est un Père de l''Occident."}]'::jsonb, null, '{"id": "eg.d.saint_ambroise_de_milan", "word": "saint Ambroise de Milan", "translation": "évêque de Milan (mort en 397)", "partOfSpeech": "person", "explanation": "Grand évêque de l''Occident, il baptise saint Augustin. Il meurt en 397.", "examples": [{"text": "Ambroise est évêque de Milan.", "translation": "Il baptise Augustin."}, {"text": "Il meurt en 397.", "translation": "Il est un Père de l''Occident."}], "unitId": "eg.v.saint_ambroise_de_milan"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_jean_chrysostome', 'eg', 'saint Jean Chrysostome', 'patriarche de Constantinople, « bouche d''or » (mort en 407)', 'Chrysostome veut dire « bouche d''or » : il est un prédicateur extraordinaire. Il meurt en 407.', '[{"text": "Chrysostome veut dire « bouche d''or ».", "translation": "Il est patriarche de Constantinople."}, {"text": "Il meurt en 407.", "translation": "Il est un grand prédicateur."}]'::jsonb, null, '{"id": "eg.d.saint_jean_chrysostome", "word": "saint Jean Chrysostome", "translation": "patriarche de Constantinople, « bouche d''or » (mort en 407)", "partOfSpeech": "person", "explanation": "Chrysostome veut dire « bouche d''or » : il est un prédicateur extraordinaire. Il meurt en 407.", "examples": [{"text": "Chrysostome veut dire « bouche d''or ».", "translation": "Il est patriarche de Constantinople."}, {"text": "Il meurt en 407.", "translation": "Il est un grand prédicateur."}], "unitId": "eg.v.saint_jean_chrysostome"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_augustin_d_hippone', 'eg', 'saint Augustin d''Hippone', 'évêque d''Hippone en Afrique du Nord (mort en 430)', 'Évêque d''Hippone, auteur des Confessions. Il meurt en 430.', '[{"text": "Augustin est évêque d''Hippone.", "translation": "Il écrit les Confessions."}, {"text": "Il est baptisé par Ambroise.", "translation": "Il meurt en 430."}]'::jsonb, null, '{"id": "eg.d.saint_augustin_d_hippone", "word": "saint Augustin d''Hippone", "translation": "évêque d''Hippone en Afrique du Nord (mort en 430)", "partOfSpeech": "person", "explanation": "Évêque d''Hippone, auteur des Confessions. Il meurt en 430.", "examples": [{"text": "Augustin est évêque d''Hippone.", "translation": "Il écrit les Confessions."}, {"text": "Il est baptisé par Ambroise.", "translation": "Il meurt en 430."}], "unitId": "eg.v.saint_augustin_d_hippone"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_nicolas_de_myre', 'eg', 'saint Nicolas de Myre', 'évêque de Myre (mort en 343)', 'Évêque de Myre, en Asie Mineure, vénéré comme un saint très aimé. Il meurt en 343.', '[{"text": "Nicolas est évêque de Myre.", "translation": "Il meurt en 343."}, {"text": "Il est très vénéré.", "translation": "Il est un saint du IVe siècle."}]'::jsonb, null, '{"id": "eg.d.saint_nicolas_de_myre", "word": "saint Nicolas de Myre", "translation": "évêque de Myre (mort en 343)", "partOfSpeech": "person", "explanation": "Évêque de Myre, en Asie Mineure, vénéré comme un saint très aimé. Il meurt en 343.", "examples": [{"text": "Nicolas est évêque de Myre.", "translation": "Il meurt en 343."}, {"text": "Il est très vénéré.", "translation": "Il est un saint du IVe siècle."}], "unitId": "eg.v.saint_nicolas_de_myre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.patriarche', 'eg', 'le patriarche', 'évêque d''un grand siège', 'Le patriarche est l''évêque d''un grand siège. À Alexandrie et à Rome, on l''appelle aussi le pape.', '[{"text": "Le patriarche de Constantinople veut jouer un grand rôle.", "translation": "Son siège est proche de l''empereur."}, {"text": "Le pape d''Alexandrie est le patriarche des coptes.", "translation": "C''est le même titre dans la tradition copte."}]'::jsonb, null, '{"id": "eg.d.patriarche", "word": "le patriarche", "translation": "évêque d''un grand siège", "partOfSpeech": "person", "explanation": "Le patriarche est l''évêque d''un grand siège. À Alexandrie et à Rome, on l''appelle aussi le pape.", "examples": [{"text": "Le patriarche de Constantinople veut jouer un grand rôle.", "translation": "Son siège est proche de l''empereur."}, {"text": "Le pape d''Alexandrie est le patriarche des coptes.", "translation": "C''est le même titre dans la tradition copte."}], "unitId": "eg.v.patriarche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.canon_ecclesiastique', 'eg', 'le canon', 'règle d''organisation votée par un concile', 'Un canon est une règle sur la vie de l''Église (rangs des évêques, discipline). Il ne change pas la foi du credo.', '[{"text": "Le canon 3 de 381 parle du rang de Constantinople.", "translation": "C''est une règle d''honneur et d''organisation."}, {"text": "Les conciles votent des canons après avoir fixé la foi.", "translation": "Foi et canons ne sont pas la même chose."}]'::jsonb, null, '{"id": "eg.d.canon_ecclesiastique", "word": "le canon", "translation": "règle d''organisation votée par un concile", "partOfSpeech": "concept", "explanation": "Un canon est une règle sur la vie de l''Église (rangs des évêques, discipline). Il ne change pas la foi du credo.", "examples": [{"text": "Le canon 3 de 381 parle du rang de Constantinople.", "translation": "C''est une règle d''honneur et d''organisation."}, {"text": "Les conciles votent des canons après avoir fixé la foi.", "translation": "Foi et canons ne sont pas la même chose."}], "unitId": "eg.v.canon_ecclesiastique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nouvelle_rome', 'eg', 'la nouvelle Rome', 'nom donné à Constantinople, capitale de l''empereur', 'Constantinople, fondée en 330, est appelée la nouvelle Rome parce que l''empereur y siège comme à Rome autrefois.', '[{"text": "Constantin quitte Rome pour Constantinople.", "translation": "La ville devient capitale impériale."}, {"text": "Les évêques de Constantinople s''appuient sur ce titre.", "translation": "Ils veulent un rang proche de celui de Rome."}]'::jsonb, null, '{"id": "eg.d.nouvelle_rome", "word": "la nouvelle Rome", "translation": "nom donné à Constantinople, capitale de l''empereur", "partOfSpeech": "place", "explanation": "Constantinople, fondée en 330, est appelée la nouvelle Rome parce que l''empereur y siège comme à Rome autrefois.", "examples": [{"text": "Constantin quitte Rome pour Constantinople.", "translation": "La ville devient capitale impériale."}, {"text": "Les évêques de Constantinople s''appuient sur ce titre.", "translation": "Ils veulent un rang proche de celui de Rome."}], "unitId": "eg.v.nouvelle_rome"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.canon_3_de_381', 'eg', 'le canon 3 de 381', 'règle donnant à Constantinople la deuxième place après Rome', 'Voté à Constantinople en 381, il place l''évêque de la nouvelle Rome juste après celui de Rome. Alexandrie refuse ce classement.', '[{"text": "Alexandrie refuse le canon 3 de 381.", "translation": "Pour elle, le rang ne dépend pas de la capitale."}, {"text": "Ce canon nourrit la rivalité entre sièges.", "translation": "Il prépare les conflits du Ve siècle."}]'::jsonb, null, '{"id": "eg.d.canon_3_de_381", "word": "le canon 3 de 381", "translation": "règle donnant à Constantinople la deuxième place après Rome", "partOfSpeech": "event", "explanation": "Voté à Constantinople en 381, il place l''évêque de la nouvelle Rome juste après celui de Rome. Alexandrie refuse ce classement.", "examples": [{"text": "Alexandrie refuse le canon 3 de 381.", "translation": "Pour elle, le rang ne dépend pas de la capitale."}, {"text": "Ce canon nourrit la rivalité entre sièges.", "translation": "Il prépare les conflits du Ve siècle."}], "unitId": "eg.v.canon_3_de_381"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trois_premiers_conciles', 'eg', 'les trois premiers conciles', 'Nicée 325, Constantinople 381, Éphèse 431', 'Ce sont les trois conciles œcuméniques que l''Église copte orthodoxe reconnaît. Elle n''en reconnaît pas d''autres.', '[{"text": "Nicée, Constantinople et Éphèse forment le socle de la foi copte.", "translation": "Le credo vient des deux premiers."}, {"text": "Chalcédoine (451) n''en fait pas partie pour les coptes.", "translation": "Ce sera l''objet des leçons suivantes."}]'::jsonb, null, '{"id": "eg.d.trois_premiers_conciles", "word": "les trois premiers conciles", "translation": "Nicée 325, Constantinople 381, Éphèse 431", "partOfSpeech": "concept", "explanation": "Ce sont les trois conciles œcuméniques que l''Église copte orthodoxe reconnaît. Elle n''en reconnaît pas d''autres.", "examples": [{"text": "Nicée, Constantinople et Éphèse forment le socle de la foi copte.", "translation": "Le credo vient des deux premiers."}, {"text": "Chalcédoine (451) n''en fait pas partie pour les coptes.", "translation": "Ce sera l''objet des leçons suivantes."}], "unitId": "eg.v.trois_premiers_conciles"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nestorius', 'eg', 'Nestorius', 'patriarche de Constantinople (428-431), condamné à Éphèse', 'Moine formé à Antioche, prédicateur célèbre, patriarche de Constantinople à partir de 428. Il refuse le titre Théotokos.', '[{"text": "Nestorius prêche contre le titre Théotokos.", "translation": "Cela choque beaucoup de fidèles."}, {"text": "Il est condamné à Éphèse en 431.", "translation": "Il finit sa vie en exil."}]'::jsonb, null, '{"id": "eg.d.nestorius", "word": "Nestorius", "translation": "patriarche de Constantinople (428-431), condamné à Éphèse", "partOfSpeech": "person", "explanation": "Moine formé à Antioche, prédicateur célèbre, patriarche de Constantinople à partir de 428. Il refuse le titre Théotokos.", "examples": [{"text": "Nestorius prêche contre le titre Théotokos.", "translation": "Cela choque beaucoup de fidèles."}, {"text": "Il est condamné à Éphèse en 431.", "translation": "Il finit sa vie en exil."}], "unitId": "eg.v.nestorius"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nestorianisme', 'eg', 'le nestorianisme', 'doctrine qui sépare le Verbe et l''homme Jésus', 'On appelle ainsi l''enseignement qui sépare le Verbe de l''homme Jésus au point de faire deux personnes. L''Église le rejette.', '[{"text": "Le nestorianisme est condamné en 431.", "translation": "C''est l''hérésie du concile d''Éphèse."}, {"text": "Le nestorianisme sépare trop.", "translation": "Le contraire sera l''erreur d''Eutychès."}]'::jsonb, null, '{"id": "eg.d.nestorianisme", "word": "le nestorianisme", "translation": "doctrine qui sépare le Verbe et l''homme Jésus", "partOfSpeech": "concept", "explanation": "On appelle ainsi l''enseignement qui sépare le Verbe de l''homme Jésus au point de faire deux personnes. L''Église le rejette.", "examples": [{"text": "Le nestorianisme est condamné en 431.", "translation": "C''est l''hérésie du concile d''Éphèse."}, {"text": "Le nestorianisme sépare trop.", "translation": "Le contraire sera l''erreur d''Eutychès."}], "unitId": "eg.v.nestorianisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.theotokos', 'eg', 'Théotokos', '« celle qui enfante Dieu », mère de Dieu', 'Titre donné à la Vierge Marie : celui qu''elle a enfanté est Dieu le Verbe fait chair. Le concile d''Éphèse le confirme en 431.', '[{"text": "Cyrille défend le titre Théotokos.", "translation": "Il protège la foi en un seul Christ."}, {"text": "L''Église copte chante Marie comme Théotokos.", "translation": "Le titre est présent dans la liturgie."}]'::jsonb, null, '{"id": "eg.d.theotokos", "word": "Théotokos", "translation": "« celle qui enfante Dieu », mère de Dieu", "partOfSpeech": "concept", "explanation": "Titre donné à la Vierge Marie : celui qu''elle a enfanté est Dieu le Verbe fait chair. Le concile d''Éphèse le confirme en 431.", "examples": [{"text": "Cyrille défend le titre Théotokos.", "translation": "Il protège la foi en un seul Christ."}, {"text": "L''Église copte chante Marie comme Théotokos.", "translation": "Le titre est présent dans la liturgie."}], "unitId": "eg.v.theotokos"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.christotokos', 'eg', 'Christotokos', '« mère du Christ », titre préféré par Nestorius', 'Nestorius propose ce titre à la place de Théotokos. Il paraît plus prudent, mais il laisse entendre que Marie n''est pas la mère de Dieu.', '[{"text": "Nestorius dit « Christotokos ».", "translation": "Il évite « mère de Dieu »."}, {"text": "Le concile rejette Christotokos comme seul titre.", "translation": "Il garde Théotokos."}]'::jsonb, null, '{"id": "eg.d.christotokos", "word": "Christotokos", "translation": "« mère du Christ », titre préféré par Nestorius", "partOfSpeech": "concept", "explanation": "Nestorius propose ce titre à la place de Théotokos. Il paraît plus prudent, mais il laisse entendre que Marie n''est pas la mère de Dieu.", "examples": [{"text": "Nestorius dit « Christotokos ».", "translation": "Il évite « mère de Dieu »."}, {"text": "Le concile rejette Christotokos comme seul titre.", "translation": "Il garde Théotokos."}], "unitId": "eg.v.christotokos"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.le_verbe', 'eg', 'le Verbe', 'le Fils de Dieu, avant son incarnation', 'Le Verbe (en grec Logos) est le Fils de Dieu, éternel. L''évangile de Jean dit : « Le Verbe s''est fait chair ».', '[{"text": "Le Verbe est Dieu.", "translation": "Il est éternel avec le Père."}, {"text": "Cyrille parle de « Dieu le Verbe incarné ».", "translation": "Un seul sujet : le Verbe."}]'::jsonb, null, '{"id": "eg.d.le_verbe", "word": "le Verbe", "translation": "le Fils de Dieu, avant son incarnation", "partOfSpeech": "concept", "explanation": "Le Verbe (en grec Logos) est le Fils de Dieu, éternel. L''évangile de Jean dit : « Le Verbe s''est fait chair ».", "examples": [{"text": "Le Verbe est Dieu.", "translation": "Il est éternel avec le Père."}, {"text": "Cyrille parle de « Dieu le Verbe incarné ».", "translation": "Un seul sujet : le Verbe."}], "unitId": "eg.v.le_verbe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.incarnation', 'eg', 'l''incarnation', 'moment où le Verbe de Dieu se fait homme', 'L''incarnation est le fait que le Fils de Dieu devient vraiment homme en Marie, sans cesser d''être Dieu.', '[{"text": "L''incarnation a lieu en Marie.", "translation": "C''est le cœur de la dispute."}, {"text": "Après l''incarnation, le Christ est Dieu et homme.", "translation": "Comment l''expliquer ? C''est la question du Ve siècle."}]'::jsonb, null, '{"id": "eg.d.incarnation", "word": "l''incarnation", "translation": "moment où le Verbe de Dieu se fait homme", "partOfSpeech": "concept", "explanation": "L''incarnation est le fait que le Fils de Dieu devient vraiment homme en Marie, sans cesser d''être Dieu.", "examples": [{"text": "L''incarnation a lieu en Marie.", "translation": "C''est le cœur de la dispute."}, {"text": "Après l''incarnation, le Christ est Dieu et homme.", "translation": "Comment l''expliquer ? C''est la question du Ve siècle."}], "unitId": "eg.v.incarnation"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ecole_d_antioche', 'eg', 'l''école d''Antioche', 'courant théologique qui distingue les natures du Christ', 'Cette école insiste sur l''humanité de Jésus et distingue soigneusement ce qui est divin de ce qui est humain.', '[{"text": "Nestorius est formé à Antioche.", "translation": "Il en garde le vocabulaire."}, {"text": "Alexandrie insiste, elle, sur l''unité du Christ.", "translation": "Deux sensibilités s''affrontent."}]'::jsonb, null, '{"id": "eg.d.ecole_d_antioche", "word": "l''école d''Antioche", "translation": "courant théologique qui distingue les natures du Christ", "partOfSpeech": "organization", "explanation": "Cette école insiste sur l''humanité de Jésus et distingue soigneusement ce qui est divin de ce qui est humain.", "examples": [{"text": "Nestorius est formé à Antioche.", "translation": "Il en garde le vocabulaire."}, {"text": "Alexandrie insiste, elle, sur l''unité du Christ.", "translation": "Deux sensibilités s''affrontent."}], "unitId": "eg.v.ecole_d_antioche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cyrille_d_alexandrie', 'eg', 'saint Cyrille d''Alexandrie', '24e pape d''Alexandrie (412-444), Pilier de la foi', 'Théologien et pape d''Alexandrie, il mène le combat contre Nestorius. L''Église copte lui consacre l''une de ses trois liturgies.', '[{"text": "Cyrille préside le concile d''Éphèse.", "translation": "Il y défend Théotokos."}, {"text": "L''Église copte l''appelle le Pilier de la foi.", "translation": "Un titre qui dit son rôle."}]'::jsonb, null, '{"id": "eg.d.cyrille_d_alexandrie", "word": "saint Cyrille d''Alexandrie", "translation": "24e pape d''Alexandrie (412-444), Pilier de la foi", "partOfSpeech": "person", "explanation": "Théologien et pape d''Alexandrie, il mène le combat contre Nestorius. L''Église copte lui consacre l''une de ses trois liturgies.", "examples": [{"text": "Cyrille préside le concile d''Éphèse.", "translation": "Il y défend Théotokos."}, {"text": "L''Église copte l''appelle le Pilier de la foi.", "translation": "Un titre qui dit son rôle."}], "unitId": "eg.v.cyrille_d_alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pilier_de_la_foi', 'eg', 'le Pilier de la foi', 'surnom de saint Cyrille dans la tradition copte', 'Ce surnom exprime que Cyrille a tenu bon pour garder la foi en un seul Christ, Dieu et homme.', '[{"text": "La liturgie copte de Cyrille l''honore comme Pilier de la foi.", "translation": "Un titre aussi liturgique."}, {"text": "Un pilier soutient un édifice.", "translation": "Cyrille soutient la foi."}]'::jsonb, null, '{"id": "eg.d.pilier_de_la_foi", "word": "le Pilier de la foi", "translation": "surnom de saint Cyrille dans la tradition copte", "partOfSpeech": "concept", "explanation": "Ce surnom exprime que Cyrille a tenu bon pour garder la foi en un seul Christ, Dieu et homme.", "examples": [{"text": "La liturgie copte de Cyrille l''honore comme Pilier de la foi.", "translation": "Un titre aussi liturgique."}, {"text": "Un pilier soutient un édifice.", "translation": "Cyrille soutient la foi."}], "unitId": "eg.v.pilier_de_la_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.formule_de_cyrille', 'eg', 'la formule de Cyrille', '« une seule nature du Verbe incarné »', 'En grec, « mia physis tou Theou Logou sesarkomene » : un seul Verbe, qui s''est fait chair. C''est la base de la foi miaphysite.', '[{"text": "« Une seule nature du Verbe incarné » résume sa foi.", "translation": "Un seul sujet : le Verbe."}, {"text": "Cette formule sera au cœur du rejet de Chalcédoine.", "translation": "On y reviendra."}]'::jsonb, null, '{"id": "eg.d.formule_de_cyrille", "word": "la formule de Cyrille", "translation": "« une seule nature du Verbe incarné »", "partOfSpeech": "concept", "explanation": "En grec, « mia physis tou Theou Logou sesarkomene » : un seul Verbe, qui s''est fait chair. C''est la base de la foi miaphysite.", "examples": [{"text": "« Une seule nature du Verbe incarné » résume sa foi.", "translation": "Un seul sujet : le Verbe."}, {"text": "Cette formule sera au cœur du rejet de Chalcédoine.", "translation": "On y reviendra."}], "unitId": "eg.v.formule_de_cyrille"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.douze_anathemes', 'eg', 'les douze anathèmes', 'douze condamnations jointes à la lettre de Cyrille à Nestorius', 'En 430, Cyrille joint à sa troisième lettre à Nestorius douze propositions condamnant les idées nestoriennes.', '[{"text": "Les douze anathèmes rejettent la séparation des natures.", "translation": "Ils défendent Théotokos."}, {"text": "Antioche les trouve trop durs.", "translation": "Un conflit de vocabulaire naît."}]'::jsonb, null, '{"id": "eg.d.douze_anathemes", "word": "les douze anathèmes", "translation": "douze condamnations jointes à la lettre de Cyrille à Nestorius", "partOfSpeech": "event", "explanation": "En 430, Cyrille joint à sa troisième lettre à Nestorius douze propositions condamnant les idées nestoriennes.", "examples": [{"text": "Les douze anathèmes rejettent la séparation des natures.", "translation": "Ils défendent Théotokos."}, {"text": "Antioche les trouve trop durs.", "translation": "Un conflit de vocabulaire naît."}], "unitId": "eg.v.douze_anathemes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.celestin_ier', 'eg', 'Célestin Ier', 'pape de Rome qui soutient Cyrille', 'Évêque de Rome de 422 à 432, il condamne Nestorius et charge Cyrille de faire respecter sa décision.', '[{"text": "Célestin Ier soutient Cyrille.", "translation": "Rome et Alexandrie vont de pair."}, {"text": "Il envoie des légats à Éphèse.", "translation": "Ils représentent Rome."}]'::jsonb, null, '{"id": "eg.d.celestin_ier", "word": "Célestin Ier", "translation": "pape de Rome qui soutient Cyrille", "partOfSpeech": "person", "explanation": "Évêque de Rome de 422 à 432, il condamne Nestorius et charge Cyrille de faire respecter sa décision.", "examples": [{"text": "Célestin Ier soutient Cyrille.", "translation": "Rome et Alexandrie vont de pair."}, {"text": "Il envoie des légats à Éphèse.", "translation": "Ils représentent Rome."}], "unitId": "eg.v.celestin_ier"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.unite_du_christ', 'eg', 'l''unité du Christ', 'un seul Christ, Dieu et homme à la fois', 'Pour Cyrille, le Christ n''est pas deux personnes mais un seul : le Verbe fait chair. C''est le cœur de la foi copte.', '[{"text": "L''unité du Christ s''illustre par l''âme et le corps.", "translation": "Deux réalités, un seul homme."}, {"text": "Théotokos protège l''unité du Christ.", "translation": "Un seul Fils."}]'::jsonb, null, '{"id": "eg.d.unite_du_christ", "word": "l''unité du Christ", "translation": "un seul Christ, Dieu et homme à la fois", "partOfSpeech": "concept", "explanation": "Pour Cyrille, le Christ n''est pas deux personnes mais un seul : le Verbe fait chair. C''est le cœur de la foi copte.", "examples": [{"text": "L''unité du Christ s''illustre par l''âme et le corps.", "translation": "Deux réalités, un seul homme."}, {"text": "Théotokos protège l''unité du Christ.", "translation": "Un seul Fils."}], "unitId": "eg.v.unite_du_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_ephese_431', 'eg', 'le concile d''Éphèse (431)', 'troisième concile œcuménique, qui condamne Nestorius', 'Réuni en 431 par l''empereur Théodose II, il proclame Marie Théotokos et condamne Nestorius. L''Église copte le reconnaît pleinement.', '[{"text": "Le concile d''Éphèse confirme Théotokos.", "translation": "C''est le troisième concile œcuménique."}, {"text": "Cyrille y joue le rôle principal.", "translation": "Il le préside."}]'::jsonb, null, '{"id": "eg.d.concile_ephese_431", "word": "le concile d''Éphèse (431)", "translation": "troisième concile œcuménique, qui condamne Nestorius", "partOfSpeech": "event", "explanation": "Réuni en 431 par l''empereur Théodose II, il proclame Marie Théotokos et condamne Nestorius. L''Église copte le reconnaît pleinement.", "examples": [{"text": "Le concile d''Éphèse confirme Théotokos.", "translation": "C''est le troisième concile œcuménique."}, {"text": "Cyrille y joue le rôle principal.", "translation": "Il le préside."}], "unitId": "eg.v.concile_ephese_431"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.theodose_ii', 'eg', 'Théodose II', 'empereur d''Orient (408-450), petit-fils de Théodose Ier', 'Il convoque les deux conciles d''Éphèse (431 et 449). Il fait confiance aux pères d''Alexandrie.', '[{"text": "Théodose II convoque le concile d''Éphèse.", "translation": "Il veut la paix religieuse."}, {"text": "Il meurt en 450.", "translation": "Son règne ouvre la voie à Marcien."}]'::jsonb, null, '{"id": "eg.d.theodose_ii", "word": "Théodose II", "translation": "empereur d''Orient (408-450), petit-fils de Théodose Ier", "partOfSpeech": "person", "explanation": "Il convoque les deux conciles d''Éphèse (431 et 449). Il fait confiance aux pères d''Alexandrie.", "examples": [{"text": "Théodose II convoque le concile d''Éphèse.", "translation": "Il veut la paix religieuse."}, {"text": "Il meurt en 450.", "translation": "Son règne ouvre la voie à Marcien."}], "unitId": "eg.v.theodose_ii"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ephese', 'eg', 'Éphèse', 'grande ville d''Asie Mineure, lieu de deux conciles', 'Éphèse est une grande ville d''Asie Mineure. Le concile de 431 se réunit dans l''église dédiée à Marie.', '[{"text": "Éphèse accueille le concile de 431.", "translation": "Puis celui de 449."}, {"text": "La ville est liée à la Vierge Marie.", "translation": "Le concile s''y tient en son honneur."}]'::jsonb, null, '{"id": "eg.d.ephese", "word": "Éphèse", "translation": "grande ville d''Asie Mineure, lieu de deux conciles", "partOfSpeech": "place", "explanation": "Éphèse est une grande ville d''Asie Mineure. Le concile de 431 se réunit dans l''église dédiée à Marie.", "examples": [{"text": "Éphèse accueille le concile de 431.", "translation": "Puis celui de 449."}, {"text": "La ville est liée à la Vierge Marie.", "translation": "Le concile s''y tient en son honneur."}], "unitId": "eg.v.ephese"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pelagianisme', 'eg', 'le pélagianisme', 'enseignement de Pélage : l''homme se sauve seul, sans la grâce', 'Pour Pélage, l''homme ne naît pas marqué par le péché originel et peut atteindre la sainteté par ses propres forces, sans la grâce de Dieu. Éphèse le condamne.', '[{"text": "Éphèse condamne aussi le pélagianisme.", "translation": "Une autre erreur."}, {"text": "La grâce de Dieu est nécessaire au salut.", "translation": "C''est la réponse de l''Église."}]'::jsonb, null, '{"id": "eg.d.pelagianisme", "word": "le pélagianisme", "translation": "enseignement de Pélage : l''homme se sauve seul, sans la grâce", "partOfSpeech": "concept", "explanation": "Pour Pélage, l''homme ne naît pas marqué par le péché originel et peut atteindre la sainteté par ses propres forces, sans la grâce de Dieu. Éphèse le condamne.", "examples": [{"text": "Éphèse condamne aussi le pélagianisme.", "translation": "Une autre erreur."}, {"text": "La grâce de Dieu est nécessaire au salut.", "translation": "C''est la réponse de l''Église."}], "unitId": "eg.v.pelagianisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jean_d_antioche', 'eg', 'Jean d''Antioche', 'patriarche d''Antioche, arrivé en retard à Éphèse', 'Il arrive après l''ouverture du concile avec les évêques d''Orient et tient un concile rival avant de se réconcilier avec Cyrille.', '[{"text": "Jean d''Antioche arrive en retard à Éphèse.", "translation": "Le concile est déjà ouvert."}, {"text": "Il se réconciliera avec Cyrille.", "translation": "C''est la formule d''union de 433."}]'::jsonb, null, '{"id": "eg.d.jean_d_antioche", "word": "Jean d''Antioche", "translation": "patriarche d''Antioche, arrivé en retard à Éphèse", "partOfSpeech": "person", "explanation": "Il arrive après l''ouverture du concile avec les évêques d''Orient et tient un concile rival avant de se réconcilier avec Cyrille.", "examples": [{"text": "Jean d''Antioche arrive en retard à Éphèse.", "translation": "Le concile est déjà ouvert."}, {"text": "Il se réconciliera avec Cyrille.", "translation": "C''est la formule d''union de 433."}], "unitId": "eg.v.jean_d_antioche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.formule_d_union', 'eg', 'la formule d''union (433)', 'compromis entre Cyrille et Jean d''Antioche', 'En 433, un texte de compromis réconcilie Alexandrie et Antioche : Jean accepte la déposition de Nestorius et Théotokos, Cyrille accepte un vocabulaire plus nuancé.', '[{"text": "La formule d''union met fin à la rupture.", "translation": "Cyrille et Jean s''entendent."}, {"text": "Elle n''efface pas tout désaccord.", "translation": "La question des natures reste ouverte."}]'::jsonb, null, '{"id": "eg.d.formule_d_union", "word": "la formule d''union (433)", "translation": "compromis entre Cyrille et Jean d''Antioche", "partOfSpeech": "event", "explanation": "En 433, un texte de compromis réconcilie Alexandrie et Antioche : Jean accepte la déposition de Nestorius et Théotokos, Cyrille accepte un vocabulaire plus nuancé.", "examples": [{"text": "La formule d''union met fin à la rupture.", "translation": "Cyrille et Jean s''entendent."}, {"text": "Elle n''efface pas tout désaccord.", "translation": "La question des natures reste ouverte."}], "unitId": "eg.v.formule_d_union"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_de_l_orient', 'eg', 'l''Église de l''Orient', 'Église née en Perse chez les partisans de Nestorius', 'Chassés de l''Empire romain, des partisans de Nestorius gagnent la Perse où naît l''Église de l''Orient, qui existe encore aujourd''hui.', '[{"text": "L''Église de l''Orient naît en Perse.", "translation": "Hors de l''Empire."}, {"text": "Elle ne reconnaît pas Éphèse.", "translation": "Elle n''est pas l''Église copte."}]'::jsonb, null, '{"id": "eg.d.eglise_de_l_orient", "word": "l''Église de l''Orient", "translation": "Église née en Perse chez les partisans de Nestorius", "partOfSpeech": "organization", "explanation": "Chassés de l''Empire romain, des partisans de Nestorius gagnent la Perse où naît l''Église de l''Orient, qui existe encore aujourd''hui.", "examples": [{"text": "L''Église de l''Orient naît en Perse.", "translation": "Hors de l''Empire."}, {"text": "Elle ne reconnaît pas Éphèse.", "translation": "Elle n''est pas l''Église copte."}], "unitId": "eg.v.eglise_de_l_orient"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.perse', 'eg', 'la Perse', 'royaume voisin de l''Empire romain, à l''est', 'La Perse est un grand royaume à l''est de l''Empire romain. Les chrétiens persécutés dans l''Empire y trouvent refuge.', '[{"text": "Les partisans de Nestorius vont en Perse.", "translation": "Là, ils sont hors d''atteinte."}, {"text": "La Perse est hors de l''Empire.", "translation": "L''empereur n''y règne pas."}]'::jsonb, null, '{"id": "eg.d.perse", "word": "la Perse", "translation": "royaume voisin de l''Empire romain, à l''est", "partOfSpeech": "place", "explanation": "La Perse est un grand royaume à l''est de l''Empire romain. Les chrétiens persécutés dans l''Empire y trouvent refuge.", "examples": [{"text": "Les partisans de Nestorius vont en Perse.", "translation": "Là, ils sont hors d''atteinte."}, {"text": "La Perse est hors de l''Empire.", "translation": "L''empereur n''y règne pas."}], "unitId": "eg.v.perse"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.flavien', 'eg', 'Flavien', 'patriarche de Constantinople (446-449)', 'Patriarche de Constantinople en 446, il condamne Eutychès en 448 puis est déposé à Éphèse en 449.', '[{"text": "Flavien devient patriarche en 446.", "translation": "Il veut affirmer son rôle."}, {"text": "Il condamne Eutychès.", "translation": "Cela déclenche la crise."}]'::jsonb, null, '{"id": "eg.d.flavien", "word": "Flavien", "translation": "patriarche de Constantinople (446-449)", "partOfSpeech": "person", "explanation": "Patriarche de Constantinople en 446, il condamne Eutychès en 448 puis est déposé à Éphèse en 449.", "examples": [{"text": "Flavien devient patriarche en 446.", "translation": "Il veut affirmer son rôle."}, {"text": "Il condamne Eutychès.", "translation": "Cela déclenche la crise."}], "unitId": "eg.v.flavien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dioscore', 'eg', 'saint Dioscore', '25e pape d''Alexandrie (444-454)', 'Successeur de Cyrille, il préside le deuxième concile d''Éphèse (449) et refuse Chalcédoine. L''Église copte l''honore comme confesseur.', '[{"text": "Dioscore succède à Cyrille en 444.", "translation": "Il est le 25e pape."}, {"text": "Il préside Éphèse II en 449.", "translation": "Il refuse Chalcédoine en 451."}]'::jsonb, null, '{"id": "eg.d.dioscore", "word": "saint Dioscore", "translation": "25e pape d''Alexandrie (444-454)", "partOfSpeech": "person", "explanation": "Successeur de Cyrille, il préside le deuxième concile d''Éphèse (449) et refuse Chalcédoine. L''Église copte l''honore comme confesseur.", "examples": [{"text": "Dioscore succède à Cyrille en 444.", "translation": "Il est le 25e pape."}, {"text": "Il préside Éphèse II en 449.", "translation": "Il refuse Chalcédoine en 451."}], "unitId": "eg.v.dioscore"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eutyches', 'eg', 'Eutychès', 'archimandrite de Constantinople, condamné en 448', 'Moine âgé et respecté, ardent adversaire de Nestorius, il tombe dans l''erreur inverse en disant que l''humanité du Christ est absorbée.', '[{"text": "Eutychès est condamné par Flavien en 448.", "translation": "Il est excommunié."}, {"text": "Il fait appel à l''empereur.", "translation": "Théodose II le soutient."}]'::jsonb, null, '{"id": "eg.d.eutyches", "word": "Eutychès", "translation": "archimandrite de Constantinople, condamné en 448", "partOfSpeech": "person", "explanation": "Moine âgé et respecté, ardent adversaire de Nestorius, il tombe dans l''erreur inverse en disant que l''humanité du Christ est absorbée.", "examples": [{"text": "Eutychès est condamné par Flavien en 448.", "translation": "Il est excommunié."}, {"text": "Il fait appel à l''empereur.", "translation": "Théodose II le soutient."}], "unitId": "eg.v.eutyches"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monophysisme', 'eg', 'le monophysisme', 'doctrine d''Eutychès : une seule nature, la divine', 'Du grec mono (un seul) et physis (nature) : le Christ n''aurait qu''une nature, divine, qui absorbe l''humanité. L''Église copte condamne aussi cette erreur.', '[{"text": "Le monophysisme est l''erreur d''Eutychès.", "translation": "L''humanité est absorbée."}, {"text": "L''Église copte n''est pas monophysite.", "translation": "Elle est miaphysite."}]'::jsonb, null, '{"id": "eg.d.monophysisme", "word": "le monophysisme", "translation": "doctrine d''Eutychès : une seule nature, la divine", "partOfSpeech": "concept", "explanation": "Du grec mono (un seul) et physis (nature) : le Christ n''aurait qu''une nature, divine, qui absorbe l''humanité. L''Église copte condamne aussi cette erreur.", "examples": [{"text": "Le monophysisme est l''erreur d''Eutychès.", "translation": "L''humanité est absorbée."}, {"text": "L''Église copte n''est pas monophysite.", "translation": "Elle est miaphysite."}], "unitId": "eg.v.monophysisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.archimandrite', 'eg', 'un archimandrite', 'chef d''un monastère', 'Titre donné au supérieur d''un grand monastère, un homme influent. Eutychès l''est près de Constantinople.', '[{"text": "Eutychès est archimandrite.", "translation": "Il dirige un monastère."}, {"text": "Un archimandrite a une grande autorité.", "translation": "Surtout auprès des moines."}]'::jsonb, null, '{"id": "eg.d.archimandrite", "word": "un archimandrite", "translation": "chef d''un monastère", "partOfSpeech": "person", "explanation": "Titre donné au supérieur d''un grand monastère, un homme influent. Eutychès l''est près de Constantinople.", "examples": [{"text": "Eutychès est archimandrite.", "translation": "Il dirige un monastère."}, {"text": "Un archimandrite a une grande autorité.", "translation": "Surtout auprès des moines."}], "unitId": "eg.v.archimandrite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.synode_de_constantinople_448', 'eg', 'le synode de Constantinople (448)', 'concile local qui condamne Eutychès', 'Convoqué par Flavien à Constantinople en 448, il examine la foi d''Eutychès, le condamne, l''excommunie et le dégrade.', '[{"text": "Le synode de 448 condamne Eutychès.", "translation": "Flavien le préside."}, {"text": "Eutychès refuse de se rétracter.", "translation": "Il persiste dans son erreur."}]'::jsonb, null, '{"id": "eg.d.synode_de_constantinople_448", "word": "le synode de Constantinople (448)", "translation": "concile local qui condamne Eutychès", "partOfSpeech": "event", "explanation": "Convoqué par Flavien à Constantinople en 448, il examine la foi d''Eutychès, le condamne, l''excommunie et le dégrade.", "examples": [{"text": "Le synode de 448 condamne Eutychès.", "translation": "Flavien le préside."}, {"text": "Eutychès refuse de se rétracter.", "translation": "Il persiste dans son erreur."}], "unitId": "eg.v.synode_de_constantinople_448"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.humanite_absorbee', 'eg', 'l''humanité absorbée', 'l''humanité du Christ qui disparaît dans la divinité', 'L''image d''Eutychès : la goutte de miel jetée dans la mer disparaît. Pour lui, l''humanité du Christ est absorbée par la divinité.', '[{"text": "La goutte de miel disparaît dans la mer.", "translation": "Il compare ainsi l''humanité."}, {"text": "Cyrille refuse cette image.", "translation": "Il garde la pleine humanité."}]'::jsonb, null, '{"id": "eg.d.humanite_absorbee", "word": "l''humanité absorbée", "translation": "l''humanité du Christ qui disparaît dans la divinité", "partOfSpeech": "concept", "explanation": "L''image d''Eutychès : la goutte de miel jetée dans la mer disparaît. Pour lui, l''humanité du Christ est absorbée par la divinité.", "examples": [{"text": "La goutte de miel disparaît dans la mer.", "translation": "Il compare ainsi l''humanité."}, {"text": "Cyrille refuse cette image.", "translation": "Il garde la pleine humanité."}], "unitId": "eg.v.humanite_absorbee"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_ephese_449', 'eg', 'le deuxième concile d''Éphèse (449)', 'concile présidé par Dioscore qui réhabilite Eutychès', 'Convoqué par Théodose II, il se tient en août 449. Dioscore le préside, réhabilite Eutychès et dépose Flavien.', '[{"text": "Éphèse II se tient en 449.", "translation": "Dioscore le préside."}, {"text": "Ses adversaires le nommeront « brigandage ».", "translation": "Il sera annulé à Chalcédoine."}]'::jsonb, null, '{"id": "eg.d.concile_ephese_449", "word": "le deuxième concile d''Éphèse (449)", "translation": "concile présidé par Dioscore qui réhabilite Eutychès", "partOfSpeech": "event", "explanation": "Convoqué par Théodose II, il se tient en août 449. Dioscore le préside, réhabilite Eutychès et dépose Flavien.", "examples": [{"text": "Éphèse II se tient en 449.", "translation": "Dioscore le préside."}, {"text": "Ses adversaires le nommeront « brigandage ».", "translation": "Il sera annulé à Chalcédoine."}], "unitId": "eg.v.concile_ephese_449"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.leon_ier', 'eg', 'Léon Ier', 'évêque de Rome (440-461)', 'Évêque de Rome, il se sent chef de toute l''Église. Il écrit le Tome de Léon et obtient le concile de Chalcédoine.', '[{"text": "Léon Ier ne peut pas venir à Éphèse.", "translation": "Il envoie des légats."}, {"text": "Il veut un nouveau concile.", "translation": "Marcien le lui accorde."}]'::jsonb, null, '{"id": "eg.d.leon_ier", "word": "Léon Ier", "translation": "évêque de Rome (440-461)", "partOfSpeech": "person", "explanation": "Évêque de Rome, il se sent chef de toute l''Église. Il écrit le Tome de Léon et obtient le concile de Chalcédoine.", "examples": [{"text": "Léon Ier ne peut pas venir à Éphèse.", "translation": "Il envoie des légats."}, {"text": "Il veut un nouveau concile.", "translation": "Marcien le lui accorde."}], "unitId": "eg.v.leon_ier"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tome_de_leon', 'eg', 'le Tome de Léon', 'lettre dogmatique de Léon Ier sur les deux natures', 'Dans cette lettre, Léon affirme les deux natures du Christ. Elle n''est pas lue à Éphèse II, mais elle sera lue et ratifiée à Chalcédoine.', '[{"text": "Le Tome de Léon n''est pas lu en 449.", "translation": "La séance est close."}, {"text": "Il est ratifié en 451.", "translation": "Il parle de deux natures."}]'::jsonb, null, '{"id": "eg.d.tome_de_leon", "word": "le Tome de Léon", "translation": "lettre dogmatique de Léon Ier sur les deux natures", "partOfSpeech": "work", "explanation": "Dans cette lettre, Léon affirme les deux natures du Christ. Elle n''est pas lue à Éphèse II, mais elle sera lue et ratifiée à Chalcédoine.", "examples": [{"text": "Le Tome de Léon n''est pas lu en 449.", "translation": "La séance est close."}, {"text": "Il est ratifié en 451.", "translation": "Il parle de deux natures."}], "unitId": "eg.v.tome_de_leon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.brigandage_d_ephese', 'eg', 'le brigandage d''Éphèse', 'nom donné par Léon à Éphèse II', 'Léon Ier et les chalcédoniens appellent Éphèse II le « brigandage d''Éphèse » (latrocinium). L''Église copte défend Dioscore.', '[{"text": "Léon parle du brigandage d''Éphèse.", "translation": "C''est un jugement sévère."}, {"text": "L''Église copte ne partage pas ce jugement.", "translation": "Elle défend Dioscore."}]'::jsonb, null, '{"id": "eg.d.brigandage_d_ephese", "word": "le brigandage d''Éphèse", "translation": "nom donné par Léon à Éphèse II", "partOfSpeech": "event", "explanation": "Léon Ier et les chalcédoniens appellent Éphèse II le « brigandage d''Éphèse » (latrocinium). L''Église copte défend Dioscore.", "examples": [{"text": "Léon parle du brigandage d''Éphèse.", "translation": "C''est un jugement sévère."}, {"text": "L''Église copte ne partage pas ce jugement.", "translation": "Elle défend Dioscore."}], "unitId": "eg.v.brigandage_d_ephese"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.marcien', 'eg', 'Marcien', 'empereur d''Orient (450-457), qui convoque Chalcédoine', 'Il devient empereur en 450 en épousant Pulchérie. Il accepte de convoquer le concile de Chalcédoine.', '[{"text": "Marcien succède à Théodose II.", "translation": "Grâce à Pulchérie."}, {"text": "Il convoque Chalcédoine.", "translation": "Il appuie Léon."}]'::jsonb, null, '{"id": "eg.d.marcien", "word": "Marcien", "translation": "empereur d''Orient (450-457), qui convoque Chalcédoine", "partOfSpeech": "person", "explanation": "Il devient empereur en 450 en épousant Pulchérie. Il accepte de convoquer le concile de Chalcédoine.", "examples": [{"text": "Marcien succède à Théodose II.", "translation": "Grâce à Pulchérie."}, {"text": "Il convoque Chalcédoine.", "translation": "Il appuie Léon."}], "unitId": "eg.v.marcien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pulcherie', 'eg', 'Pulchérie', 'impératrice, sœur de Théodose II', 'Moniale d''esprit, elle ne peut pas régner seule : elle épouse Marcien et le nomme empereur en 450.', '[{"text": "Pulchérie épouse Marcien.", "translation": "Il devient empereur."}, {"text": "Elle assiste à Chalcédoine.", "translation": "À ses côtés."}]'::jsonb, null, '{"id": "eg.d.pulcherie", "word": "Pulchérie", "translation": "impératrice, sœur de Théodose II", "partOfSpeech": "person", "explanation": "Moniale d''esprit, elle ne peut pas régner seule : elle épouse Marcien et le nomme empereur en 450.", "examples": [{"text": "Pulchérie épouse Marcien.", "translation": "Il devient empereur."}, {"text": "Elle assiste à Chalcédoine.", "translation": "À ses côtés."}], "unitId": "eg.v.pulcherie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_chalcedoine', 'eg', 'le concile de Chalcédoine (451)', 'quatrième concile pour les Églises chalcédoniennes, rejeté par l''Église copte', 'Réuni en 451 par Marcien, il ratifie le Tome de Léon et définit « deux natures ». L''Église copte ne le reconnaît pas.', '[{"text": "Marcien convoque Chalcédoine.", "translation": "À la demande de Léon."}, {"text": "Le concile condamne Dioscore.", "translation": "Et exile l''évêque d''Alexandrie."}]'::jsonb, null, '{"id": "eg.d.concile_chalcedoine", "word": "le concile de Chalcédoine (451)", "translation": "quatrième concile pour les Églises chalcédoniennes, rejeté par l''Église copte", "partOfSpeech": "event", "explanation": "Réuni en 451 par Marcien, il ratifie le Tome de Léon et définit « deux natures ». L''Église copte ne le reconnaît pas.", "examples": [{"text": "Marcien convoque Chalcédoine.", "translation": "À la demande de Léon."}, {"text": "Le concile condamne Dioscore.", "translation": "Et exile l''évêque d''Alexandrie."}], "unitId": "eg.v.concile_chalcedoine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chalcedoine', 'eg', 'Chalcédoine', 'ville d''Asie Mineure, en face de Constantinople', 'Chalcédoine est située sur la rive d''Asie du Bosphore, en face de Constantinople. Le concile de 451 s''y tient.', '[{"text": "Le concile se tient à Chalcédoine.", "translation": "Près de la capitale."}, {"text": "Elle est proche de l''empereur.", "translation": "Facile à surveiller."}]'::jsonb, null, '{"id": "eg.d.chalcedoine", "word": "Chalcédoine", "translation": "ville d''Asie Mineure, en face de Constantinople", "partOfSpeech": "place", "explanation": "Chalcédoine est située sur la rive d''Asie du Bosphore, en face de Constantinople. Le concile de 451 s''y tient.", "examples": [{"text": "Le concile se tient à Chalcédoine.", "translation": "Près de la capitale."}, {"text": "Elle est proche de l''empereur.", "translation": "Facile à surveiller."}], "unitId": "eg.v.chalcedoine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.definition_de_chalcedoine', 'eg', 'la définition de Chalcédoine', 'formule : un seul Christ reconnu en deux natures', 'Le Christ est reconnu « en deux natures », sans confusion, sans changement, sans division, sans séparation.', '[{"text": "La définition parle de deux natures.", "translation": "C''est le point de rupture."}, {"text": "L''Église copte confesse une seule nature du Verbe incarné.", "translation": "Les mots diffèrent."}]'::jsonb, null, '{"id": "eg.d.definition_de_chalcedoine", "word": "la définition de Chalcédoine", "translation": "formule : un seul Christ reconnu en deux natures", "partOfSpeech": "concept", "explanation": "Le Christ est reconnu « en deux natures », sans confusion, sans changement, sans division, sans séparation.", "examples": [{"text": "La définition parle de deux natures.", "translation": "C''est le point de rupture."}, {"text": "L''Église copte confesse une seule nature du Verbe incarné.", "translation": "Les mots diffèrent."}], "unitId": "eg.v.definition_de_chalcedoine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.deux_natures', 'eg', 'les deux natures', 'langage de Chalcédoine : divine et humaine, distinguées après l''union', 'Pour Chalcédoine, après l''union le Christ a deux natures, la divine et l''humaine, chacune gardant ce qui lui est propre.', '[{"text": "Chalcédoine affirme deux natures.", "translation": "Après l''union."}, {"text": "Ce langage rappelle Antioche.", "translation": "Il inquiète Alexandrie."}]'::jsonb, null, '{"id": "eg.d.deux_natures", "word": "les deux natures", "translation": "langage de Chalcédoine : divine et humaine, distinguées après l''union", "partOfSpeech": "concept", "explanation": "Pour Chalcédoine, après l''union le Christ a deux natures, la divine et l''humaine, chacune gardant ce qui lui est propre.", "examples": [{"text": "Chalcédoine affirme deux natures.", "translation": "Après l''union."}, {"text": "Ce langage rappelle Antioche.", "translation": "Il inquiète Alexandrie."}], "unitId": "eg.v.deux_natures"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.canon_28', 'eg', 'le canon 28', 'règle donnant à Constantinople la seconde place après Rome', 'Voté à Chalcédoine, il donne à Constantinople les mêmes privilèges qu''à Rome, juste après elle. Léon refuse ce canon.', '[{"text": "Le canon 28 favorise Constantinople.", "translation": "Alexandrie y perd un rang."}, {"text": "Léon refuse le canon 28.", "translation": "Rome veut la première place."}]'::jsonb, null, '{"id": "eg.d.canon_28", "word": "le canon 28", "translation": "règle donnant à Constantinople la seconde place après Rome", "partOfSpeech": "event", "explanation": "Voté à Chalcédoine, il donne à Constantinople les mêmes privilèges qu''à Rome, juste après elle. Léon refuse ce canon.", "examples": [{"text": "Le canon 28 favorise Constantinople.", "translation": "Alexandrie y perd un rang."}, {"text": "Léon refuse le canon 28.", "translation": "Rome veut la première place."}], "unitId": "eg.v.canon_28"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.premier_schisme', 'eg', 'le premier schisme', 'rupture de l''Église après Chalcédoine', 'Après 451, l''Église se divise entre l''Est non-chalcédonien (Alexandrie, Antioche) et l''Ouest chalcédonien (Rome, Constantinople).', '[{"text": "Le premier schisme suit Chalcédoine.", "translation": "L''unité est brisée."}, {"text": "Il date de 451.", "translation": "Le second schisme est de 1054."}]'::jsonb, null, '{"id": "eg.d.premier_schisme", "word": "le premier schisme", "translation": "rupture de l''Église après Chalcédoine", "partOfSpeech": "event", "explanation": "Après 451, l''Église se divise entre l''Est non-chalcédonien (Alexandrie, Antioche) et l''Ouest chalcédonien (Rome, Constantinople).", "examples": [{"text": "Le premier schisme suit Chalcédoine.", "translation": "L''unité est brisée."}, {"text": "Il date de 451.", "translation": "Le second schisme est de 1054."}], "unitId": "eg.v.premier_schisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.archidiacre', 'eg', 'l''archidiacre', 'premier assistant d''un évêque', 'L''archidiacre est le principal collaborateur d''un évêque. Dioscore l''a été auprès de Cyrille, avant de lui succéder.', '[{"text": "Dioscore est l''archidiacre de Cyrille.", "translation": "Il l''accompagne à Éphèse."}, {"text": "Un archidiacre administre le diocèse.", "translation": "Il prépare souvent la succession."}]'::jsonb, null, '{"id": "eg.d.archidiacre", "word": "l''archidiacre", "translation": "premier assistant d''un évêque", "partOfSpeech": "person", "explanation": "L''archidiacre est le principal collaborateur d''un évêque. Dioscore l''a été auprès de Cyrille, avant de lui succéder.", "examples": [{"text": "Dioscore est l''archidiacre de Cyrille.", "translation": "Il l''accompagne à Éphèse."}, {"text": "Un archidiacre administre le diocèse.", "translation": "Il prépare souvent la succession."}], "unitId": "eg.v.archidiacre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.accusations_contre_dioscore', 'eg', 'les trois accusations contre Dioscore', 'accusations portées contre lui à Chalcédoine', 'On lui reproche d''avoir accepté l''erreur d''Eutychès, condamné Flavien sans raison et refusé de lire le Tome de Léon.', '[{"text": "Les trois accusations visent Dioscore.", "translation": "Elles servent son procès."}, {"text": "La tradition copte les juge politiques.", "translation": "Elle défend Dioscore."}]'::jsonb, null, '{"id": "eg.d.accusations_contre_dioscore", "word": "les trois accusations contre Dioscore", "translation": "accusations portées contre lui à Chalcédoine", "partOfSpeech": "event", "explanation": "On lui reproche d''avoir accepté l''erreur d''Eutychès, condamné Flavien sans raison et refusé de lire le Tome de Léon.", "examples": [{"text": "Les trois accusations visent Dioscore.", "translation": "Elles servent son procès."}, {"text": "La tradition copte les juge politiques.", "translation": "Elle défend Dioscore."}], "unitId": "eg.v.accusations_contre_dioscore"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.gangra', 'eg', 'Gangra', 'ville d''Asie Mineure où Dioscore est exilé', 'Gangra est une ville d''Asie Mineure, au nord de l''actuelle Turquie. L''empereur Marcien y exile Dioscore.', '[{"text": "Dioscore est exilé à Gangra.", "translation": "Il y meurt en 454."}, {"text": "Gangra est loin d''Alexandrie.", "translation": "Un exil qui coupe le pape de son peuple."}]'::jsonb, null, '{"id": "eg.d.gangra", "word": "Gangra", "translation": "ville d''Asie Mineure où Dioscore est exilé", "partOfSpeech": "place", "explanation": "Gangra est une ville d''Asie Mineure, au nord de l''actuelle Turquie. L''empereur Marcien y exile Dioscore.", "examples": [{"text": "Dioscore est exilé à Gangra.", "translation": "Il y meurt en 454."}, {"text": "Gangra est loin d''Alexandrie.", "translation": "Un exil qui coupe le pape de son peuple."}], "unitId": "eg.v.gangra"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.miaphysisme', 'eg', 'le miaphysisme', 'foi en une seule nature du Verbe incarné, humaine et divine', 'Du grec mia (une seule, unie) et physis (nature). L''Église copte confesse le Christ pleinement humain et pleinement divin, sans mélange ni division.', '[{"text": "L''Église copte est miaphysite.", "translation": "Elle suit Cyrille."}, {"text": "Le miaphysisme n''est pas le monophysisme.", "translation": "L''humanité n''est pas absorbée."}]'::jsonb, null, '{"id": "eg.d.miaphysisme", "word": "le miaphysisme", "translation": "foi en une seule nature du Verbe incarné, humaine et divine", "partOfSpeech": "concept", "explanation": "Du grec mia (une seule, unie) et physis (nature). L''Église copte confesse le Christ pleinement humain et pleinement divin, sans mélange ni division.", "examples": [{"text": "L''Église copte est miaphysite.", "translation": "Elle suit Cyrille."}, {"text": "Le miaphysisme n''est pas le monophysisme.", "translation": "L''humanité n''est pas absorbée."}], "unitId": "eg.v.miaphysisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dyophysisme', 'eg', 'le dyophysisme', 'foi en deux natures du Christ, chacune gardant son caractère', 'Du grec dyo (deux) : c''est la position de Chalcédoine, des Églises orthodoxes chalcédoniennes et de l''Église catholique.', '[{"text": "Chalcédoine est dyophysite.", "translation": "Deux natures."}, {"text": "Il distingue les deux natures après l''union.", "translation": "Pour protéger leur réalité."}]'::jsonb, null, '{"id": "eg.d.dyophysisme", "word": "le dyophysisme", "translation": "foi en deux natures du Christ, chacune gardant son caractère", "partOfSpeech": "concept", "explanation": "Du grec dyo (deux) : c''est la position de Chalcédoine, des Églises orthodoxes chalcédoniennes et de l''Église catholique.", "examples": [{"text": "Chalcédoine est dyophysite.", "translation": "Deux natures."}, {"text": "Il distingue les deux natures après l''union.", "translation": "Pour protéger leur réalité."}], "unitId": "eg.v.dyophysisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.physis', 'eg', 'physis', 'mot grec pour « nature »', 'Physis veut dire « nature » en grec. On le retrouve dans mono-physisme, dyo-physisme, mia-physisme.', '[{"text": "Physis = nature.", "translation": "Un mot grec."}, {"text": "Mono, dyo, mia se placent devant physis.", "translation": "Ce sont des nombres."}]'::jsonb, null, '{"id": "eg.d.physis", "word": "physis", "translation": "mot grec pour « nature »", "partOfSpeech": "concept", "explanation": "Physis veut dire « nature » en grec. On le retrouve dans mono-physisme, dyo-physisme, mia-physisme.", "examples": [{"text": "Physis = nature.", "translation": "Un mot grec."}, {"text": "Mono, dyo, mia se placent devant physis.", "translation": "Ce sont des nombres."}], "unitId": "eg.v.physis"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sans_melange_ni_division', 'eg', 'sans mélange ni division', 'le divin et l''humain unis dans le Christ sans se confondre ni se séparer', 'Cette expression résume le miaphysisme : l''union est réelle (pas de division) et l''humanité garde sa réalité (pas de mélange).', '[{"text": "Sans mélange ni division.", "translation": "Union sans confusion."}, {"text": "C''est ce que dit la liturgie.", "translation": "Tu l''entends à la messe."}]'::jsonb, null, '{"id": "eg.d.sans_melange_ni_division", "word": "sans mélange ni division", "translation": "le divin et l''humain unis dans le Christ sans se confondre ni se séparer", "partOfSpeech": "concept", "explanation": "Cette expression résume le miaphysisme : l''union est réelle (pas de division) et l''humanité garde sa réalité (pas de mélange).", "examples": [{"text": "Sans mélange ni division.", "translation": "Union sans confusion."}, {"text": "C''est ce que dit la liturgie.", "translation": "Tu l''entends à la messe."}], "unitId": "eg.v.sans_melange_ni_division"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.henotikon', 'eg', 'l''Hénotikon (482)', 'édit d''union de l''empereur Zénon', 'Texte de 482 qui réaffirme Nicée et Constantinople, condamne Nestorius et Eutychès, mais interdit de soulever la question de la ou des natures du Christ.', '[{"text": "L''Hénotikon veut apaiser la querelle.", "translation": "Il échoue."}, {"text": "Il interdit la discussion.", "translation": "Ce silence ne convainc pas."}]'::jsonb, null, '{"id": "eg.d.henotikon", "word": "l''Hénotikon (482)", "translation": "édit d''union de l''empereur Zénon", "partOfSpeech": "event", "explanation": "Texte de 482 qui réaffirme Nicée et Constantinople, condamne Nestorius et Eutychès, mais interdit de soulever la question de la ou des natures du Christ.", "examples": [{"text": "L''Hénotikon veut apaiser la querelle.", "translation": "Il échoue."}, {"text": "Il interdit la discussion.", "translation": "Ce silence ne convainc pas."}], "unitId": "eg.v.henotikon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.zenon', 'eg', 'Zénon', 'empereur d''Orient (474-491), auteur de l''Hénotikon', 'Il tente de réconcilier chalcédoniens et non-chalcédoniens avec l''appui du patriarche Acace de Constantinople.', '[{"text": "Zénon publie l''Hénotikon.", "translation": "Avec Acace."}, {"text": "Il règne de 474 à 491.", "translation": "À Constantinople."}]'::jsonb, null, '{"id": "eg.d.zenon", "word": "Zénon", "translation": "empereur d''Orient (474-491), auteur de l''Hénotikon", "partOfSpeech": "person", "explanation": "Il tente de réconcilier chalcédoniens et non-chalcédoniens avec l''appui du patriarche Acace de Constantinople.", "examples": [{"text": "Zénon publie l''Hénotikon.", "translation": "Avec Acace."}, {"text": "Il règne de 474 à 491.", "translation": "À Constantinople."}], "unitId": "eg.v.zenon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.justinien', 'eg', 'Justinien', 'empereur romain d''Orient (527-565)', 'Il cherche d''abord un compromis entre les Églises, mais nomme en 538 le premier patriarche chalcédonien d''Alexandrie.', '[{"text": "Justinien nomme un patriarche chalcédonien en 538.", "translation": "L''Égypte a deux patriarches."}, {"text": "Il persécute les non-chalcédoniens.", "translation": "Dès 527."}]'::jsonb, null, '{"id": "eg.d.justinien", "word": "Justinien", "translation": "empereur romain d''Orient (527-565)", "partOfSpeech": "person", "explanation": "Il cherche d''abord un compromis entre les Églises, mais nomme en 538 le premier patriarche chalcédonien d''Alexandrie.", "examples": [{"text": "Justinien nomme un patriarche chalcédonien en 538.", "translation": "L''Égypte a deux patriarches."}, {"text": "Il persécute les non-chalcédoniens.", "translation": "Dès 527."}], "unitId": "eg.v.justinien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.melkites', 'eg', 'les melkites', 'chrétiens fidèles à l''empereur, ayant accepté Chalcédoine', 'Du syriaque malka (roi) : chrétiens de Jérusalem, d''Alexandrie et d''Antioche qui acceptent Chalcédoine et restent fidèles à l''empereur de Constantinople.', '[{"text": "Les melkites suivent l''empereur.", "translation": "Ils acceptent Chalcédoine."}, {"text": "Leur patriarche est ordonné à Constantinople.", "translation": "Puis envoyé à Alexandrie."}]'::jsonb, null, '{"id": "eg.d.melkites", "word": "les melkites", "translation": "chrétiens fidèles à l''empereur, ayant accepté Chalcédoine", "partOfSpeech": "organization", "explanation": "Du syriaque malka (roi) : chrétiens de Jérusalem, d''Alexandrie et d''Antioche qui acceptent Chalcédoine et restent fidèles à l''empereur de Constantinople.", "examples": [{"text": "Les melkites suivent l''empereur.", "translation": "Ils acceptent Chalcédoine."}, {"text": "Leur patriarche est ordonné à Constantinople.", "translation": "Puis envoyé à Alexandrie."}], "unitId": "eg.v.melkites"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.non_chalcedoniens', 'eg', 'les Églises non-chalcédoniennes', 'Églises qui refusent les décisions de Chalcédoine', 'Ce sont les Églises orthodoxes orientales, dont l''Église copte : elles refusent Chalcédoine et ne reconnaissent que trois conciles.', '[{"text": "L''Église copte est non-chalcédonienne.", "translation": "Elle refuse Chalcédoine."}, {"text": "Elles ne reconnaissent que trois conciles.", "translation": "Nicée, Constantinople, Éphèse."}]'::jsonb, null, '{"id": "eg.d.non_chalcedoniens", "word": "les Églises non-chalcédoniennes", "translation": "Églises qui refusent les décisions de Chalcédoine", "partOfSpeech": "concept", "explanation": "Ce sont les Églises orthodoxes orientales, dont l''Église copte : elles refusent Chalcédoine et ne reconnaissent que trois conciles.", "examples": [{"text": "L''Église copte est non-chalcédonienne.", "translation": "Elle refuse Chalcédoine."}, {"text": "Elles ne reconnaissent que trois conciles.", "translation": "Nicée, Constantinople, Éphèse."}], "unitId": "eg.v.non_chalcedoniens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chalcedoniens', 'eg', 'les Églises chalcédoniennes', 'Églises qui acceptent Chalcédoine et reconnaissent sept conciles', 'Ce sont les Églises de Rome et de Constantinople, qui acceptent la foi aux deux natures et reconnaissent sept conciles.', '[{"text": "Rome et Constantinople sont chalcédoniennes.", "translation": "Elles acceptent les deux natures."}, {"text": "Elles reconnaissent sept conciles.", "translation": "Jusqu''à Nicée II (787)."}]'::jsonb, null, '{"id": "eg.d.chalcedoniens", "word": "les Églises chalcédoniennes", "translation": "Églises qui acceptent Chalcédoine et reconnaissent sept conciles", "partOfSpeech": "concept", "explanation": "Ce sont les Églises de Rome et de Constantinople, qui acceptent la foi aux deux natures et reconnaissent sept conciles.", "examples": [{"text": "Rome et Constantinople sont chalcédoniennes.", "translation": "Elles acceptent les deux natures."}, {"text": "Elles reconnaissent sept conciles.", "translation": "Jusqu''à Nicée II (787)."}], "unitId": "eg.v.chalcedoniens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.macaire_d_edkou', 'eg', 'saint Macaire d''Edkou', 'évêque d''Edkou, martyr des persécutions non-chalcédoniennes', 'Évêque d''Edkou, il est l''un des martyrs de la persécution des non-chalcédoniens. L''Église copte le vénère.', '[{"text": "Macaire d''Edkou est martyr.", "translation": "Il reste fidèle à la foi d''Alexandrie."}, {"text": "Il montre le prix de la fidélité.", "translation": "Sous la persécution."}]'::jsonb, null, '{"id": "eg.d.macaire_d_edkou", "word": "saint Macaire d''Edkou", "translation": "évêque d''Edkou, martyr des persécutions non-chalcédoniennes", "partOfSpeech": "person", "explanation": "Évêque d''Edkou, il est l''un des martyrs de la persécution des non-chalcédoniens. L''Église copte le vénère.", "examples": [{"text": "Macaire d''Edkou est martyr.", "translation": "Il reste fidèle à la foi d''Alexandrie."}, {"text": "Il montre le prix de la fidélité.", "translation": "Sous la persécution."}], "unitId": "eg.v.macaire_d_edkou"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglises_soeurs', 'eg', 'les Églises sœurs', 'les six Églises non-chalcédoniennes en intercommunion', 'L''Église copte, la syriaque, l''éthiopienne, l''indienne, l''érythréenne et l''arménienne sont en intercommunion : elles se reconnaissent mutuellement.', '[{"text": "Les six Églises sœurs sont non-chalcédoniennes.", "translation": "Elles pratiquent l''intercommunion."}, {"text": "Le mariage entre leurs fidèles est accepté.", "translation": "Un signe de leur unité."}]'::jsonb, null, '{"id": "eg.d.eglises_soeurs", "word": "les Églises sœurs", "translation": "les six Églises non-chalcédoniennes en intercommunion", "partOfSpeech": "organization", "explanation": "L''Église copte, la syriaque, l''éthiopienne, l''indienne, l''érythréenne et l''arménienne sont en intercommunion : elles se reconnaissent mutuellement.", "examples": [{"text": "Les six Églises sœurs sont non-chalcédoniennes.", "translation": "Elles pratiquent l''intercommunion."}, {"text": "Le mariage entre leurs fidèles est accepté.", "translation": "Un signe de leur unité."}], "unitId": "eg.v.eglises_soeurs"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.intercommunion', 'eg', 'l''intercommunion', 'communion pleine entre Églises, y compris le mariage entre leurs fidèles', 'Deux Églises en intercommunion se reconnaissent mutuellement et partagent la communion et les sacrements.', '[{"text": "L''Église copte est en intercommunion avec cinq Églises.", "translation": "Les six sont sœurs."}, {"text": "Elle n''est pas en intercommunion avec les chalcédoniennes.", "translation": "Pas encore."}]'::jsonb, null, '{"id": "eg.d.intercommunion", "word": "l''intercommunion", "translation": "communion pleine entre Églises, y compris le mariage entre leurs fidèles", "partOfSpeech": "concept", "explanation": "Deux Églises en intercommunion se reconnaissent mutuellement et partagent la communion et les sacrements.", "examples": [{"text": "L''Église copte est en intercommunion avec cinq Églises.", "translation": "Les six sont sœurs."}, {"text": "Elle n''est pas en intercommunion avec les chalcédoniennes.", "translation": "Pas encore."}], "unitId": "eg.v.intercommunion"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.accord_de_1989', 'eg', 'l''accord de 1989 à Amba Bichoï', 'accord de foi entre orthodoxes orientaux et byzantins', 'En 1989, au monastère Amba Bichoï de Scété, des accords de foi ont été signés entre les Églises orthodoxes byzantines et les Églises orientales.', '[{"text": "L''accord de 1989 est signé à Scété.", "translation": "Au monastère Amba Bichoï."}, {"text": "Il constate la même christologie.", "translation": "Les deux familles s''en réjouissent."}]'::jsonb, null, '{"id": "eg.d.accord_de_1989", "word": "l''accord de 1989 à Amba Bichoï", "translation": "accord de foi entre orthodoxes orientaux et byzantins", "partOfSpeech": "event", "explanation": "En 1989, au monastère Amba Bichoï de Scété, des accords de foi ont été signés entre les Églises orthodoxes byzantines et les Églises orientales.", "examples": [{"text": "L''accord de 1989 est signé à Scété.", "translation": "Au monastère Amba Bichoï."}, {"text": "Il constate la même christologie.", "translation": "Les deux familles s''en réjouissent."}], "unitId": "eg.v.accord_de_1989"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.christologie', 'eg', 'la christologie', 'enseignement sur qui est le Christ, sur ses natures', 'La christologie est la partie de la foi qui explique qui est le Christ : Dieu et homme. Chaque Église en donne sa formule.', '[{"text": "La christologie copte est miaphysite.", "translation": "Celle de Chalcédoine est dyophysite."}, {"text": "Les deux familles disent partager la même christologie.", "translation": "Les mots diffèrent, le sens est commun."}]'::jsonb, null, '{"id": "eg.d.christologie", "word": "la christologie", "translation": "enseignement sur qui est le Christ, sur ses natures", "partOfSpeech": "concept", "explanation": "La christologie est la partie de la foi qui explique qui est le Christ : Dieu et homme. Chaque Église en donne sa formule.", "examples": [{"text": "La christologie copte est miaphysite.", "translation": "Celle de Chalcédoine est dyophysite."}, {"text": "Les deux familles disent partager la même christologie.", "translation": "Les mots diffèrent, le sens est commun."}], "unitId": "eg.v.christologie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.synode', 'eg', 'le synode', 'assemblée d''évêques d''une région, concile local', 'Un synode réunit les évêques d''une région pour traiter une question. Il peut préparer un concile, mais ne parle pas au nom de toute l''Église.', '[{"text": "Le synode d''Antioche de 269 juge Paul de Samosate.", "translation": "C''est un concile local."}, {"text": "Le synode de Constantinople de 448 condamne Eutychès.", "translation": "Il n''est pas œcuménique."}]'::jsonb, null, '{"id": "eg.d.synode", "word": "le synode", "translation": "assemblée d''évêques d''une région, concile local", "partOfSpeech": "concept", "explanation": "Un synode réunit les évêques d''une région pour traiter une question. Il peut préparer un concile, mais ne parle pas au nom de toute l''Église.", "examples": [{"text": "Le synode d''Antioche de 269 juge Paul de Samosate.", "translation": "C''est un concile local."}, {"text": "Le synode de Constantinople de 448 condamne Eutychès.", "translation": "Il n''est pas œcuménique."}], "unitId": "eg.v.synode"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.orthodoxie', 'eg', 'l''orthodoxie', 'la foi droite, juste', 'Orthodoxie vient du grec : « droite foi ». Les conciles servent à fixer l''orthodoxie face aux erreurs.', '[{"text": "Nicée fixe l''orthodoxie sur la divinité du Christ.", "translation": "La foi droite s''oppose à l''hérésie."}, {"text": "L''Église copte orthodoxe garde l''orthodoxie reçue des Pères.", "translation": "C''est aussi son nom."}]'::jsonb, null, '{"id": "eg.d.orthodoxie", "word": "l''orthodoxie", "translation": "la foi droite, juste", "partOfSpeech": "concept", "explanation": "Orthodoxie vient du grec : « droite foi ». Les conciles servent à fixer l''orthodoxie face aux erreurs.", "examples": [{"text": "Nicée fixe l''orthodoxie sur la divinité du Christ.", "translation": "La foi droite s''oppose à l''hérésie."}, {"text": "L''Église copte orthodoxe garde l''orthodoxie reçue des Pères.", "translation": "C''est aussi son nom."}], "unitId": "eg.v.orthodoxie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.symbole_de_foi', 'eg', 'le symbole de foi', 'le credo, formule solennelle de la foi', 'Le symbole de foi est le texte court qui résume ce que croit l''Église. Le credo de Nicée-Constantinople en est le plus connu.', '[{"text": "Nicée rédige un symbole de foi.", "translation": "Il dit que le Fils est consubstantiel au Père."}, {"text": "Constantinople complète le symbole de foi.", "translation": "On y ajoute la partie sur l''Esprit Saint."}]'::jsonb, null, '{"id": "eg.d.symbole_de_foi", "word": "le symbole de foi", "translation": "le credo, formule solennelle de la foi", "partOfSpeech": "concept", "explanation": "Le symbole de foi est le texte court qui résume ce que croit l''Église. Le credo de Nicée-Constantinople en est le plus connu.", "examples": [{"text": "Nicée rédige un symbole de foi.", "translation": "Il dit que le Fils est consubstantiel au Père."}, {"text": "Constantinople complète le symbole de foi.", "translation": "On y ajoute la partie sur l''Esprit Saint."}], "unitId": "eg.v.symbole_de_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.reception_d_un_concile', 'eg', 'la réception d''un concile', 'acceptation d''un concile par l''ensemble de l''Église', 'Un concile prend toute sa valeur quand l''Église le reçoit. C''est la réception.', '[{"text": "Nicée est reçu partout en quelques décennies.", "translation": "Son credo devient celui de toute l''Église."}, {"text": "Chalcédoine n''est pas reçu par Alexandrie.", "translation": "C''est la cause du premier schisme."}]'::jsonb, null, '{"id": "eg.d.reception_d_un_concile", "word": "la réception d''un concile", "translation": "acceptation d''un concile par l''ensemble de l''Église", "partOfSpeech": "concept", "explanation": "Un concile prend toute sa valeur quand l''Église le reçoit. C''est la réception.", "examples": [{"text": "Nicée est reçu partout en quelques décennies.", "translation": "Son credo devient celui de toute l''Église."}, {"text": "Chalcédoine n''est pas reçu par Alexandrie.", "translation": "C''est la cause du premier schisme."}], "unitId": "eg.v.reception_d_un_concile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dualisme', 'eg', 'le dualisme', 'croyance en deux principes opposés, un bon et un mauvais', 'Le dualisme sépare le monde en deux principes : un bon et un mauvais. On le trouve chez les gnostiques, chez Marcion et chez Mani.', '[{"text": "Pour les gnostiques, l''esprit est bon et la matière mauvaise.", "translation": "C''est du dualisme."}, {"text": "L''Église répond : un seul Dieu a créé un monde bon.", "translation": "Le dualisme est donc rejeté."}]'::jsonb, null, '{"id": "eg.d.dualisme", "word": "le dualisme", "translation": "croyance en deux principes opposés, un bon et un mauvais", "partOfSpeech": "concept", "explanation": "Le dualisme sépare le monde en deux principes : un bon et un mauvais. On le trouve chez les gnostiques, chez Marcion et chez Mani.", "examples": [{"text": "Pour les gnostiques, l''esprit est bon et la matière mauvaise.", "translation": "C''est du dualisme."}, {"text": "L''Église répond : un seul Dieu a créé un monde bon.", "translation": "Le dualisme est donc rejeté."}], "unitId": "eg.v.dualisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.adoptianisme', 'eg', 'l''adoptianisme', 'erreur : le Christ serait un homme « adopté » par Dieu', 'Dans l''adoptianisme, le Christ n''est pas Dieu par nature : c''est un homme que Dieu choisit et « adopte ». C''est l''erreur de Paul de Samosate.', '[{"text": "Paul de Samosate voit en Jésus un homme ordinaire.", "translation": "Dieu l''aurait seulement choisi."}, {"text": "L''Église répond : le Fils est Dieu de toute éternité.", "translation": "Il n''est pas adopté."}]'::jsonb, null, '{"id": "eg.d.adoptianisme", "word": "l''adoptianisme", "translation": "erreur : le Christ serait un homme « adopté » par Dieu", "partOfSpeech": "concept", "explanation": "Dans l''adoptianisme, le Christ n''est pas Dieu par nature : c''est un homme que Dieu choisit et « adopte ». C''est l''erreur de Paul de Samosate.", "examples": [{"text": "Paul de Samosate voit en Jésus un homme ordinaire.", "translation": "Dieu l''aurait seulement choisi."}, {"text": "L''Église répond : le Fils est Dieu de toute éternité.", "translation": "Il n''est pas adopté."}], "unitId": "eg.v.adoptianisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pneumatomaques', 'eg', 'les pneumatomaques', 'ceux qui combattent l''Esprit, qui nient sa divinité', 'Du grec pneuma (esprit) et machê (combat). Ce nom désigne les disciples de Macédonius, qui disent que l''Esprit Saint est une créature.', '[{"text": "Les pneumatomaques nient la divinité du Saint-Esprit.", "translation": "Constantinople (381) les condamne."}, {"text": "Macédonius est leur chef de file.", "translation": "Il est destitué en 381."}]'::jsonb, null, '{"id": "eg.d.pneumatomaques", "word": "les pneumatomaques", "translation": "ceux qui combattent l''Esprit, qui nient sa divinité", "partOfSpeech": "person", "explanation": "Du grec pneuma (esprit) et machê (combat). Ce nom désigne les disciples de Macédonius, qui disent que l''Esprit Saint est une créature.", "examples": [{"text": "Les pneumatomaques nient la divinité du Saint-Esprit.", "translation": "Constantinople (381) les condamne."}, {"text": "Macédonius est leur chef de file.", "translation": "Il est destitué en 381."}], "unitId": "eg.v.pneumatomaques"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.consubstantiel', 'eg', 'consubstantiel', 'de même substance (essence) que le Père', 'Consubstantiel est la traduction de homoousios : le Fils a la même substance divine que le Père, il est Dieu comme lui.', '[{"text": "Le Fils est consubstantiel au Père.", "translation": "C''est ce que dit le credo de Nicée."}, {"text": "Le Saint-Esprit est aussi consubstantiel au Père et au Fils.", "translation": "C''est ce que confirme Constantinople."}]'::jsonb, null, '{"id": "eg.d.consubstantiel", "word": "consubstantiel", "translation": "de même substance (essence) que le Père", "partOfSpeech": "concept", "explanation": "Consubstantiel est la traduction de homoousios : le Fils a la même substance divine que le Père, il est Dieu comme lui.", "examples": [{"text": "Le Fils est consubstantiel au Père.", "translation": "C''est ce que dit le credo de Nicée."}, {"text": "Le Saint-Esprit est aussi consubstantiel au Père et au Fils.", "translation": "C''est ce que confirme Constantinople."}], "unitId": "eg.v.consubstantiel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apollinarisme', 'eg', 'l''apollinarisme', 'erreur d''Apollinaire : le Christ aurait un corps humain sans âme humaine', 'Apollinaire de Laodicée dit que la divinité du Verbe a pris la place de l''âme humaine du Christ. Le Christ ne serait donc pas homme en entier. Constantinople (381) le condamne.', '[{"text": "L''apollinarisme retire au Christ son âme humaine.", "translation": "Son humanité serait incomplète."}, {"text": "Le pape Timothée le réfute à Constantinople.", "translation": "Il refuse de revenir."}]'::jsonb, null, '{"id": "eg.d.apollinarisme", "word": "l''apollinarisme", "translation": "erreur d''Apollinaire : le Christ aurait un corps humain sans âme humaine", "partOfSpeech": "concept", "explanation": "Apollinaire de Laodicée dit que la divinité du Verbe a pris la place de l''âme humaine du Christ. Le Christ ne serait donc pas homme en entier. Constantinople (381) le condamne.", "examples": [{"text": "L''apollinarisme retire au Christ son âme humaine.", "translation": "Son humanité serait incomplète."}, {"text": "Le pape Timothée le réfute à Constantinople.", "translation": "Il refuse de revenir."}], "unitId": "eg.v.apollinarisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pleine_humanite', 'eg', 'la pleine humanité', 'le fait que le Christ est vraiment homme, avec un corps et une âme', 'Le Christ est pleinement homme : corps, âme, intelligence. Les docètes, Apollinaire et Eutychès la diminuent, chacun à sa façon.', '[{"text": "La pleine humanité du Christ rend le salut possible.", "translation": "Il prend ce qu''il veut sauver."}, {"text": "Saint Cyrille affirme la pleine humanité et la pleine divinité.", "translation": "Rien n''est détruit dans l''union."}]'::jsonb, null, '{"id": "eg.d.pleine_humanite", "word": "la pleine humanité", "translation": "le fait que le Christ est vraiment homme, avec un corps et une âme", "partOfSpeech": "concept", "explanation": "Le Christ est pleinement homme : corps, âme, intelligence. Les docètes, Apollinaire et Eutychès la diminuent, chacun à sa façon.", "examples": [{"text": "La pleine humanité du Christ rend le salut possible.", "translation": "Il prend ce qu''il veut sauver."}, {"text": "Saint Cyrille affirme la pleine humanité et la pleine divinité.", "translation": "Rien n''est détruit dans l''union."}], "unitId": "eg.v.pleine_humanite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eutychianisme', 'eg', 'l''eutychianisme', 'autre nom du monophysisme d''Eutychès', 'L''eutychianisme est le nom donné à l''erreur d''Eutychès : une seule nature, la divine, qui absorberait l''humanité. C''est un synonyme de monophysisme.', '[{"text": "L''eutychianisme est condamné par l''Église copte.", "translation": "Elle n''est pas monophysite."}, {"text": "On dit eutychianisme ou monophysisme.", "translation": "C''est la même erreur."}]'::jsonb, null, '{"id": "eg.d.eutychianisme", "word": "l''eutychianisme", "translation": "autre nom du monophysisme d''Eutychès", "partOfSpeech": "concept", "explanation": "L''eutychianisme est le nom donné à l''erreur d''Eutychès : une seule nature, la divine, qui absorberait l''humanité. C''est un synonyme de monophysisme.", "examples": [{"text": "L''eutychianisme est condamné par l''Église copte.", "translation": "Elle n''est pas monophysite."}, {"text": "On dit eutychianisme ou monophysisme.", "translation": "C''est la même erreur."}], "unitId": "eg.v.eutychianisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.fiche_de_concile', 'eg', 'la fiche d''un concile', 'grille de questions pour retenir un concile', 'Pour retenir un concile, on remplit toujours la même fiche : qui convoque, où, quand, combien d''évêques, contre quelle erreur, quelles décisions, quelles figures, quelle réception.', '[{"text": "La fiche de Nicée : Constantin, 325, Arius.", "translation": "Huit questions suffisent."}, {"text": "La fiche d''Éphèse : Théodose II, 431, Nestorius.", "translation": "Même grille, autres réponses."}]'::jsonb, null, '{"id": "eg.d.fiche_de_concile", "word": "la fiche d''un concile", "translation": "grille de questions pour retenir un concile", "partOfSpeech": "concept", "explanation": "Pour retenir un concile, on remplit toujours la même fiche : qui convoque, où, quand, combien d''évêques, contre quelle erreur, quelles décisions, quelles figures, quelle réception.", "examples": [{"text": "La fiche de Nicée : Constantin, 325, Arius.", "translation": "Huit questions suffisent."}, {"text": "La fiche d''Éphèse : Théodose II, 431, Nestorius.", "translation": "Même grille, autres réponses."}], "unitId": "eg.v.fiche_de_concile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.presidence_du_concile', 'eg', 'la présidence du concile', 'le fait de diriger les débats d''un concile', 'Le président dirige les débats. Selon la tradition copte, les papes d''Alexandrie ont présidé Nicée (Alexandre), Éphèse (Cyrille) et Éphèse II (Dioscore).', '[{"text": "La présidence de Nicée revient, selon la tradition copte, au pape Alexandre.", "translation": "Athanase l''assiste."}, {"text": "Cyrille assure la présidence à Éphèse en 431.", "translation": "Avec l''appui de Rome."}]'::jsonb, null, '{"id": "eg.d.presidence_du_concile", "word": "la présidence du concile", "translation": "le fait de diriger les débats d''un concile", "partOfSpeech": "concept", "explanation": "Le président dirige les débats. Selon la tradition copte, les papes d''Alexandrie ont présidé Nicée (Alexandre), Éphèse (Cyrille) et Éphèse II (Dioscore).", "examples": [{"text": "La présidence de Nicée revient, selon la tradition copte, au pape Alexandre.", "translation": "Athanase l''assiste."}, {"text": "Cyrille assure la présidence à Éphèse en 431.", "translation": "Avec l''appui de Rome."}], "unitId": "eg.v.presidence_du_concile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.legat', 'eg', 'le légat', 'envoyé qui parle au nom d''un évêque absent', 'Quand le pape de Rome ne peut pas venir, il envoie des légats. À Nicée, Rome est représentée par deux prêtres ; à Chalcédoine, par ses légats.', '[{"text": "Deux prêtres représentent Rome à Nicée.", "translation": "Sylvestre est trop âgé."}, {"text": "Les légats de Léon sont à Chalcédoine.", "translation": "Léon est absent."}]'::jsonb, null, '{"id": "eg.d.legat", "word": "le légat", "translation": "envoyé qui parle au nom d''un évêque absent", "partOfSpeech": "person", "explanation": "Quand le pape de Rome ne peut pas venir, il envoie des légats. À Nicée, Rome est représentée par deux prêtres ; à Chalcédoine, par ses légats.", "examples": [{"text": "Deux prêtres représentent Rome à Nicée.", "translation": "Sylvestre est trop âgé."}, {"text": "Les légats de Léon sont à Chalcédoine.", "translation": "Léon est absent."}], "unitId": "eg.v.legat"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.deposition', 'eg', 'la déposition', 'fait de retirer son siège à un évêque', 'La déposition prive un évêque de son siège. Éphèse dépose Nestorius ; Éphèse II dépose Flavien ; Chalcédoine dépose Dioscore.', '[{"text": "Le concile prononce la déposition de Nestorius.", "translation": "Il perd son siège de Constantinople."}, {"text": "Macédonius est destitué en 381.", "translation": "C''est aussi une déposition."}]'::jsonb, null, '{"id": "eg.d.deposition", "word": "la déposition", "translation": "fait de retirer son siège à un évêque", "partOfSpeech": "concept", "explanation": "La déposition prive un évêque de son siège. Éphèse dépose Nestorius ; Éphèse II dépose Flavien ; Chalcédoine dépose Dioscore.", "examples": [{"text": "Le concile prononce la déposition de Nestorius.", "translation": "Il perd son siège de Constantinople."}, {"text": "Macédonius est destitué en 381.", "translation": "C''est aussi une déposition."}], "unitId": "eg.v.deposition"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.concile_rival', 'eg', 'le concile rival', 'assemblée tenue contre le concile officiel', 'À Éphèse, Jean d''Antioche et les évêques d''Orient arrivent en retard et tiennent leur propre concile, qui dépose Cyrille. L''empereur doit trancher.', '[{"text": "Le concile rival de Jean d''Antioche dépose Cyrille.", "translation": "L''empereur tranche."}, {"text": "Un concile rival divise l''Église.", "translation": "Chacun condamne l''autre."}]'::jsonb, null, '{"id": "eg.d.concile_rival", "word": "le concile rival", "translation": "assemblée tenue contre le concile officiel", "partOfSpeech": "event", "explanation": "À Éphèse, Jean d''Antioche et les évêques d''Orient arrivent en retard et tiennent leur propre concile, qui dépose Cyrille. L''empereur doit trancher.", "examples": [{"text": "Le concile rival de Jean d''Antioche dépose Cyrille.", "translation": "L''empereur tranche."}, {"text": "Un concile rival divise l''Église.", "translation": "Chacun condamne l''autre."}], "unitId": "eg.v.concile_rival"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.interdit_de_changer_le_credo', 'eg', 'l''interdiction de changer le credo', 'décision d''Éphèse : ne pas composer d''autre credo', 'Éphèse confirme le credo de Nicée et interdit d''en composer un autre. Plus tard, les coptes rappelleront cette interdiction à propos de la définition de Chalcédoine.', '[{"text": "Éphèse interdit de composer un autre credo.", "translation": "Le credo de Nicée suffit."}, {"text": "Pour les coptes, Chalcédoine ajoute une définition.", "translation": "Il enfreint cette interdiction."}]'::jsonb, null, '{"id": "eg.d.interdit_de_changer_le_credo", "word": "l''interdiction de changer le credo", "translation": "décision d''Éphèse : ne pas composer d''autre credo", "partOfSpeech": "event", "explanation": "Éphèse confirme le credo de Nicée et interdit d''en composer un autre. Plus tard, les coptes rappelleront cette interdiction à propos de la définition de Chalcédoine.", "examples": [{"text": "Éphèse interdit de composer un autre credo.", "translation": "Le credo de Nicée suffit."}, {"text": "Pour les coptes, Chalcédoine ajoute une définition.", "translation": "Il enfreint cette interdiction."}], "unitId": "eg.v.interdit_de_changer_le_credo"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ephese_i_et_ii', 'eg', 'Éphèse I et Éphèse II', 'les deux conciles d''Éphèse : 431 et 449', 'Il y a deux conciles à Éphèse. Celui de 431 est le troisième concile œcuménique, reconnu par tous ; celui de 449 est annulé par Chalcédoine et la tradition copte défend la conduite de Dioscore.', '[{"text": "Éphèse I (431) condamne Nestorius.", "translation": "Cyrille préside."}, {"text": "Éphèse II (449) réhabilite Eutychès et dépose Flavien.", "translation": "Dioscore préside."}]'::jsonb, null, '{"id": "eg.d.ephese_i_et_ii", "word": "Éphèse I et Éphèse II", "translation": "les deux conciles d''Éphèse : 431 et 449", "partOfSpeech": "concept", "explanation": "Il y a deux conciles à Éphèse. Celui de 431 est le troisième concile œcuménique, reconnu par tous ; celui de 449 est annulé par Chalcédoine et la tradition copte défend la conduite de Dioscore.", "examples": [{"text": "Éphèse I (431) condamne Nestorius.", "translation": "Cyrille préside."}, {"text": "Éphèse II (449) réhabilite Eutychès et dépose Flavien.", "translation": "Dioscore préside."}], "unitId": "eg.v.ephese_i_et_ii"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.actes_du_concile', 'eg', 'les actes du concile', 'le compte rendu écrit des séances d''un concile', 'Les actes sont le procès-verbal des séances. Selon les actes de Chalcédoine, Dioscore est déposé pour sa conduite, non pour une hérésie.', '[{"text": "Les actes de Chalcédoine racontent le procès de Dioscore.", "translation": "On y lit les motifs de sa déposition."}, {"text": "Les actes disent qu''il a refusé de comparaître.", "translation": "Ce n''est pas un jugement sur sa foi."}]'::jsonb, null, '{"id": "eg.d.actes_du_concile", "word": "les actes du concile", "translation": "le compte rendu écrit des séances d''un concile", "partOfSpeech": "work", "explanation": "Les actes sont le procès-verbal des séances. Selon les actes de Chalcédoine, Dioscore est déposé pour sa conduite, non pour une hérésie.", "examples": [{"text": "Les actes de Chalcédoine racontent le procès de Dioscore.", "translation": "On y lit les motifs de sa déposition."}, {"text": "Les actes disent qu''il a refusé de comparaître.", "translation": "Ce n''est pas un jugement sur sa foi."}], "unitId": "eg.v.actes_du_concile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.annulation_d_un_concile', 'eg', 'l''annulation d''Éphèse II', 'décision de Chalcédoine : Éphèse II est cassé', 'Léon Ier convainc Marcien de réunir un concile pour annuler Éphèse II. Chalcédoine casse les décisions de 449 et ratifie le Tome de Léon.', '[{"text": "Léon réclame l''annulation d''Éphèse II.", "translation": "Il le nomme brigandage."}, {"text": "Marcien convoque Chalcédoine pour l''obtenir.", "translation": "En 451."}]'::jsonb, null, '{"id": "eg.d.annulation_d_un_concile", "word": "l''annulation d''Éphèse II", "translation": "décision de Chalcédoine : Éphèse II est cassé", "partOfSpeech": "event", "explanation": "Léon Ier convainc Marcien de réunir un concile pour annuler Éphèse II. Chalcédoine casse les décisions de 449 et ratifie le Tome de Léon.", "examples": [{"text": "Léon réclame l''annulation d''Éphèse II.", "translation": "Il le nomme brigandage."}, {"text": "Marcien convoque Chalcédoine pour l''obtenir.", "translation": "En 451."}], "unitId": "eg.v.annulation_d_un_concile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.frise_chronologique', 'eg', 'la frise chronologique', 'ligne du temps qui range les événements dans l''ordre', 'Une frise chronologique range les événements sur une ligne : on voit ce qui vient avant et après, et donc ce qui répond à quoi.', '[{"text": "Sur la frise, Arius vient avant Nicée.", "translation": "L''erreur précède le concile."}, {"text": "Sur la frise, Eutychès vient après Nestorius.", "translation": "L''erreur inverse suit."}]'::jsonb, null, '{"id": "eg.d.frise_chronologique", "word": "la frise chronologique", "translation": "ligne du temps qui range les événements dans l''ordre", "partOfSpeech": "concept", "explanation": "Une frise chronologique range les événements sur une ligne : on voit ce qui vient avant et après, et donc ce qui répond à quoi.", "examples": [{"text": "Sur la frise, Arius vient avant Nicée.", "translation": "L''erreur précède le concile."}, {"text": "Sur la frise, Eutychès vient après Nestorius.", "translation": "L''erreur inverse suit."}], "unitId": "eg.v.frise_chronologique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cycle_heresie_concile', 'eg', 'le cycle hérésie – concile', 'enchaînement : erreur, concile, formule, erreur inverse', 'Souvent, une erreur provoque un concile, qui donne une formule de foi ; cette formule peut elle-même faire naître l''erreur inverse.', '[{"text": "Arius, Nicée, homoousios : un cycle.", "translation": "Puis le semi-arianisme."}, {"text": "Nestorius, Éphèse, Théotokos, puis Eutychès.", "translation": "Un autre cycle."}]'::jsonb, null, '{"id": "eg.d.cycle_heresie_concile", "word": "le cycle hérésie – concile", "translation": "enchaînement : erreur, concile, formule, erreur inverse", "partOfSpeech": "concept", "explanation": "Souvent, une erreur provoque un concile, qui donne une formule de foi ; cette formule peut elle-même faire naître l''erreur inverse.", "examples": [{"text": "Arius, Nicée, homoousios : un cycle.", "translation": "Puis le semi-arianisme."}, {"text": "Nestorius, Éphèse, Théotokos, puis Eutychès.", "translation": "Un autre cycle."}], "unitId": "eg.v.cycle_heresie_concile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.crise_de_discipline', 'eg', 'la crise de discipline', 'désaccord sur la règle de vie de l''Église, non sur la foi', 'Toutes les crises ne sont pas des hérésies. Le novatianisme, la date de Pâques ou les rangs entre sièges sont des questions de discipline ou d''organisation.', '[{"text": "Le pardon des tombés est une crise de discipline.", "translation": "Novatien est pourtant schismatique."}, {"text": "La date de Pâques divise sans rompre.", "translation": "Polycarpe et Rome restent en communion."}]'::jsonb, null, '{"id": "eg.d.crise_de_discipline", "word": "la crise de discipline", "translation": "désaccord sur la règle de vie de l''Église, non sur la foi", "partOfSpeech": "concept", "explanation": "Toutes les crises ne sont pas des hérésies. Le novatianisme, la date de Pâques ou les rangs entre sièges sont des questions de discipline ou d''organisation.", "examples": [{"text": "Le pardon des tombés est une crise de discipline.", "translation": "Novatien est pourtant schismatique."}, {"text": "La date de Pâques divise sans rompre.", "translation": "Polycarpe et Rome restent en communion."}], "unitId": "eg.v.crise_de_discipline"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.formule_de_foi', 'eg', 'la formule de foi', 'phrase courte qui fixe la foi face à une erreur', 'Une formule de foi est une phrase précise qui dit la foi face à une erreur : homoousios à Nicée, Théotokos à Éphèse, « une seule nature du Verbe incarné » chez Cyrille.', '[{"text": "Homoousios est la formule de Nicée.", "translation": "Elle répond à Arius."}, {"text": "Théotokos est la formule d''Éphèse.", "translation": "Elle répond à Nestorius."}]'::jsonb, null, '{"id": "eg.d.formule_de_foi", "word": "la formule de foi", "translation": "phrase courte qui fixe la foi face à une erreur", "partOfSpeech": "concept", "explanation": "Une formule de foi est une phrase précise qui dit la foi face à une erreur : homoousios à Nicée, Théotokos à Éphèse, « une seule nature du Verbe incarné » chez Cyrille.", "examples": [{"text": "Homoousios est la formule de Nicée.", "translation": "Elle répond à Arius."}, {"text": "Théotokos est la formule d''Éphèse.", "translation": "Elle répond à Nestorius."}], "unitId": "eg.v.formule_de_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.les_cinq_dates', 'eg', 'les cinq dates', '325, 381, 431, 449, 451', 'Cinq dates à ne jamais oublier : 325 (Nicée), 381 (Constantinople), 431 (Éphèse), 449 (Éphèse II), 451 (Chalcédoine).', '[{"text": "325, 381, 431 : les trois conciles reconnus.", "translation": "Environ cinquante ans d''écart."}, {"text": "449 et 451 : Éphèse II puis Chalcédoine.", "translation": "Les deux conciles qui divisent."}]'::jsonb, null, '{"id": "eg.d.les_cinq_dates", "word": "les cinq dates", "translation": "325, 381, 431, 449, 451", "partOfSpeech": "date", "explanation": "Cinq dates à ne jamais oublier : 325 (Nicée), 381 (Constantinople), 431 (Éphèse), 449 (Éphèse II), 451 (Chalcédoine).", "examples": [{"text": "325, 381, 431 : les trois conciles reconnus.", "translation": "Environ cinquante ans d''écart."}, {"text": "449 et 451 : Éphèse II puis Chalcédoine.", "translation": "Les deux conciles qui divisent."}], "unitId": "eg.v.les_cinq_dates"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.piege_de_confusion', 'eg', 'le piège de confusion', 'deux noms ou deux dates qu''on mélange facilement', 'Le piège de confusion est un faux ami : monophysisme et miaphysisme, Éphèse I et Éphèse II, le synode de 448 et le concile de 381.', '[{"text": "Monophysisme et miaphysisme sont un piège de confusion.", "translation": "Un seul mot change, le sens aussi."}, {"text": "Éphèse 431 et Éphèse 449 sont un autre piège.", "translation": "Même ville, deux conciles."}]'::jsonb, null, '{"id": "eg.d.piege_de_confusion", "word": "le piège de confusion", "translation": "deux noms ou deux dates qu''on mélange facilement", "partOfSpeech": "concept", "explanation": "Le piège de confusion est un faux ami : monophysisme et miaphysisme, Éphèse I et Éphèse II, le synode de 448 et le concile de 381.", "examples": [{"text": "Monophysisme et miaphysisme sont un piège de confusion.", "translation": "Un seul mot change, le sens aussi."}, {"text": "Éphèse 431 et Éphèse 449 sont un autre piège.", "translation": "Même ville, deux conciles."}], "unitId": "eg.v.piege_de_confusion"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglises_orthodoxes_orientales', 'eg', 'Églises orthodoxes orientales', 'famille d''Églises qui n''ont pas reçu Chalcédoine (copte, syriaque, arménienne, tewahedo, malankare)', 'Elles gardent la foi des trois premiers conciles et ont refusé le concile de Chalcédoine en 451. L''Église copte en fait partie.', '[{"text": "L''Église copte, l''Église arménienne et l''Église éthiopienne sont des Églises orthodoxes orientales.", "translation": "Elles sont sœurs par la foi, même si leurs langues et leurs pays diffèrent."}, {"text": "Le mot « orientales » ne les range pas dans le même groupe que les orthodoxes grecs ou russes.", "translation": "Deux familles orthodoxes existent, séparées depuis 451."}]'::jsonb, null, '{"id": "eg.d.eglises_orthodoxes_orientales", "word": "Églises orthodoxes orientales", "translation": "famille d''Églises qui n''ont pas reçu Chalcédoine (copte, syriaque, arménienne, tewahedo, malankare)", "partOfSpeech": "organization", "explanation": "Elles gardent la foi des trois premiers conciles et ont refusé le concile de Chalcédoine en 451. L''Église copte en fait partie.", "examples": [{"text": "L''Église copte, l''Église arménienne et l''Église éthiopienne sont des Églises orthodoxes orientales.", "translation": "Elles sont sœurs par la foi, même si leurs langues et leurs pays diffèrent."}, {"text": "Le mot « orientales » ne les range pas dans le même groupe que les orthodoxes grecs ou russes.", "translation": "Deux familles orthodoxes existent, séparées depuis 451."}], "unitId": "eg.v.eglises_orthodoxes_orientales"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_orthodoxe_chalcedonienne', 'eg', 'Église orthodoxe chalcédonienne', 'orthodoxes de tradition byzantine (grecque, russe, serbe, roumaine…) qui reçoivent Chalcédoine', 'Elle regroupe des Églises autocéphales (grecque, russe, serbe, roumaine, bulgare, géorgienne…). Elle reçoit sept conciles, dont Chalcédoine, et s''est séparée de Rome en 1054.', '[{"text": "Le patriarche de Constantinople est le premier en honneur de cette famille.", "translation": "Il n''a pourtant pas le pouvoir d''un pape sur les autres Églises."}, {"text": "L''Église orthodoxe russe est la plus nombreuse de cette famille.", "translation": "Elle compte avec les Églises grecque, serbe et roumaine."}]'::jsonb, null, '{"id": "eg.d.eglise_orthodoxe_chalcedonienne", "word": "Église orthodoxe chalcédonienne", "translation": "orthodoxes de tradition byzantine (grecque, russe, serbe, roumaine…) qui reçoivent Chalcédoine", "partOfSpeech": "organization", "explanation": "Elle regroupe des Églises autocéphales (grecque, russe, serbe, roumaine, bulgare, géorgienne…). Elle reçoit sept conciles, dont Chalcédoine, et s''est séparée de Rome en 1054.", "examples": [{"text": "Le patriarche de Constantinople est le premier en honneur de cette famille.", "translation": "Il n''a pourtant pas le pouvoir d''un pape sur les autres Églises."}, {"text": "L''Église orthodoxe russe est la plus nombreuse de cette famille.", "translation": "Elle compte avec les Églises grecque, serbe et roumaine."}], "unitId": "eg.v.eglise_orthodoxe_chalcedonienne"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_catholique', 'eg', 'Église catholique', 'la plus grande Église chrétienne, dirigée par le pape à Rome', 'Elle compte environ 1,4 milliard de fidèles. Elle comprend l''Église latine et 23 Églises catholiques orientales, toutes en communion avec le pape.', '[{"text": "Le pape, évêque de Rome, est le chef de l''Église catholique.", "translation": "C''est le point central qui la distingue des orthodoxes."}, {"text": "L''Église catholique copte garde la liturgie copte mais reconnaît le pape.", "translation": "Elle est copte par le rite et catholique par la communion."}]'::jsonb, null, '{"id": "eg.d.eglise_catholique", "word": "Église catholique", "translation": "la plus grande Église chrétienne, dirigée par le pape à Rome", "partOfSpeech": "organization", "explanation": "Elle compte environ 1,4 milliard de fidèles. Elle comprend l''Église latine et 23 Églises catholiques orientales, toutes en communion avec le pape.", "examples": [{"text": "Le pape, évêque de Rome, est le chef de l''Église catholique.", "translation": "C''est le point central qui la distingue des orthodoxes."}, {"text": "L''Église catholique copte garde la liturgie copte mais reconnaît le pape.", "translation": "Elle est copte par le rite et catholique par la communion."}], "unitId": "eg.v.eglise_catholique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.protestantisme', 'eg', 'protestantisme', 'ensemble d''Églises nées de la Réforme du XVIe siècle', 'Le protestantisme naît en 1517 avec Luther. Il comprend luthériens, réformés, anglicans, baptistes, pentecôtistes, etc., sans chef unique.', '[{"text": "Les luthériens et les presbytériens sont deux familles protestantes.", "translation": "Chacune a sa propre organisation."}, {"text": "L''Église évangélique d''Égypte est née de la mission protestante du XIXe siècle.", "translation": "C''est la forme que le protestantisme a prise sur les bords du Nil."}]'::jsonb, null, '{"id": "eg.d.protestantisme", "word": "protestantisme", "translation": "ensemble d''Églises nées de la Réforme du XVIe siècle", "partOfSpeech": "concept", "explanation": "Le protestantisme naît en 1517 avec Luther. Il comprend luthériens, réformés, anglicans, baptistes, pentecôtistes, etc., sans chef unique.", "examples": [{"text": "Les luthériens et les presbytériens sont deux familles protestantes.", "translation": "Chacune a sa propre organisation."}, {"text": "L''Église évangélique d''Égypte est née de la mission protestante du XIXe siècle.", "translation": "C''est la forme que le protestantisme a prise sur les bords du Nil."}], "unitId": "eg.v.protestantisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_syriaque_orthodoxe', 'eg', 'Église syriaque orthodoxe', 'Église orthodoxe orientale du patriarcat d''Antioche, qui prie en syriaque', 'Son patriarche porte le titre d''Antioche. Elle prie en syriaque, une langue proche de l''araméen que parlait Jésus.', '[{"text": "Antioche est la ville où les disciples ont été appelés chrétiens pour la première fois.", "translation": "Ce prestige explique le titre de son patriarche."}, {"text": "L''Église syriaque orthodoxe est présente en Syrie, en Irak, en Turquie et en Inde.", "translation": "Une partie de ses fidèles ont émigré en Europe."}]'::jsonb, null, '{"id": "eg.d.eglise_syriaque_orthodoxe", "word": "Église syriaque orthodoxe", "translation": "Église orthodoxe orientale du patriarcat d''Antioche, qui prie en syriaque", "partOfSpeech": "organization", "explanation": "Son patriarche porte le titre d''Antioche. Elle prie en syriaque, une langue proche de l''araméen que parlait Jésus.", "examples": [{"text": "Antioche est la ville où les disciples ont été appelés chrétiens pour la première fois.", "translation": "Ce prestige explique le titre de son patriarche."}, {"text": "L''Église syriaque orthodoxe est présente en Syrie, en Irak, en Turquie et en Inde.", "translation": "Une partie de ses fidèles ont émigré en Europe."}], "unitId": "eg.v.eglise_syriaque_orthodoxe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_armenienne_apostolique', 'eg', 'Église arménienne apostolique', 'Église orthodoxe orientale d''Arménie, premier royaume chrétien vers 301', 'L''Arménie devient chrétienne vers 301 grâce à saint Grégoire l''Illuminateur. L''Église arménienne est dite « apostolique » car elle remonte aux apôtres Thaddée et Barthélemy.', '[{"text": "L''Arménie est le premier royaume à adopter le christianisme comme religion d''État.", "translation": "La date traditionnelle est 301."}, {"text": "L''Église arménienne a deux grands sièges, Etchmiadzin et Antélias.", "translation": "Ils partagent la même foi."}]'::jsonb, null, '{"id": "eg.d.eglise_armenienne_apostolique", "word": "Église arménienne apostolique", "translation": "Église orthodoxe orientale d''Arménie, premier royaume chrétien vers 301", "partOfSpeech": "organization", "explanation": "L''Arménie devient chrétienne vers 301 grâce à saint Grégoire l''Illuminateur. L''Église arménienne est dite « apostolique » car elle remonte aux apôtres Thaddée et Barthélemy.", "examples": [{"text": "L''Arménie est le premier royaume à adopter le christianisme comme religion d''État.", "translation": "La date traditionnelle est 301."}, {"text": "L''Église arménienne a deux grands sièges, Etchmiadzin et Antélias.", "translation": "Ils partagent la même foi."}], "unitId": "eg.v.eglise_armenienne_apostolique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_tewahedo', 'eg', 'Église tewahedo', 'Églises orthodoxes d''Éthiopie et d''Érythrée (« rendu un »)', 'Tewahedo veut dire « rendu un » : l''union du divin et de l''humain en Christ. L''abouna d''Éthiopie a été envoyé d''Alexandrie jusqu''en 1959.', '[{"text": "Saint Frumence, premier évêque d''Éthiopie, a été consacré par saint Athanase d''Alexandrie.", "translation": "Le lien avec Alexandrie est donc très ancien."}, {"text": "L''Église éthiopienne est devenue autocéphale en 1959.", "translation": "Elle a alors eu son propre patriarche."}]'::jsonb, null, '{"id": "eg.d.eglise_tewahedo", "word": "Église tewahedo", "translation": "Églises orthodoxes d''Éthiopie et d''Érythrée (« rendu un »)", "partOfSpeech": "organization", "explanation": "Tewahedo veut dire « rendu un » : l''union du divin et de l''humain en Christ. L''abouna d''Éthiopie a été envoyé d''Alexandrie jusqu''en 1959.", "examples": [{"text": "Saint Frumence, premier évêque d''Éthiopie, a été consacré par saint Athanase d''Alexandrie.", "translation": "Le lien avec Alexandrie est donc très ancien."}, {"text": "L''Église éthiopienne est devenue autocéphale en 1959.", "translation": "Elle a alors eu son propre patriarche."}], "unitId": "eg.v.eglise_tewahedo"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_malankare', 'eg', 'Église malankare', 'Église orthodoxe orientale de l''Inde (Kerala), liée à l''apôtre Thomas', 'Les chrétiens du Kerala disent descendre de ceux que l''apôtre Thomas aurait évangélisés. L''Église malankare est aujourd''hui orthodoxe orientale.', '[{"text": "Le Kerala est une région du sud-ouest de l''Inde.", "translation": "Les chrétiens y vivent depuis les premiers siècles."}, {"text": "L''Église malankare est en communion avec le patriarcat syriaque d''Antioche.", "translation": "Elle partage la même foi que l''Église copte."}]'::jsonb, null, '{"id": "eg.d.eglise_malankare", "word": "Église malankare", "translation": "Église orthodoxe orientale de l''Inde (Kerala), liée à l''apôtre Thomas", "partOfSpeech": "organization", "explanation": "Les chrétiens du Kerala disent descendre de ceux que l''apôtre Thomas aurait évangélisés. L''Église malankare est aujourd''hui orthodoxe orientale.", "examples": [{"text": "Le Kerala est une région du sud-ouest de l''Inde.", "translation": "Les chrétiens y vivent depuis les premiers siècles."}, {"text": "L''Église malankare est en communion avec le patriarcat syriaque d''Antioche.", "translation": "Elle partage la même foi que l''Église copte."}], "unitId": "eg.v.eglise_malankare"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sept_conciles', 'eg', 'sept conciles', 'les conciles œcuméniques reçus par les orthodoxes chalcédoniens (jusqu''à Nicée II, 787)', 'Nicée (325), Constantinople (381), Éphèse (431), Chalcédoine (451), puis trois autres jusqu''à Nicée II en 787. Les catholiques en reçoivent encore davantage.', '[{"text": "Le septième concile, en 787, défend la vénération des icônes.", "translation": "Il est reçu par les chalcédoniens."}, {"text": "Pour les chalcédoniens, la liste s''arrête au septième concile.", "translation": "Notre liste s''arrête au troisième."}]'::jsonb, null, '{"id": "eg.d.sept_conciles", "word": "sept conciles", "translation": "les conciles œcuméniques reçus par les orthodoxes chalcédoniens (jusqu''à Nicée II, 787)", "partOfSpeech": "concept", "explanation": "Nicée (325), Constantinople (381), Éphèse (431), Chalcédoine (451), puis trois autres jusqu''à Nicée II en 787. Les catholiques en reçoivent encore davantage.", "examples": [{"text": "Le septième concile, en 787, défend la vénération des icônes.", "translation": "Il est reçu par les chalcédoniens."}, {"text": "Pour les chalcédoniens, la liste s''arrête au septième concile.", "translation": "Notre liste s''arrête au troisième."}], "unitId": "eg.v.sept_conciles"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trois_conciles', 'eg', 'trois conciles', 'les conciles reçus par les orthodoxes orientaux : Nicée, Constantinople, Éphèse', 'Les orthodoxes orientaux reçoivent Nicée (325), Constantinople (381) et Éphèse (431). Ces trois conciles suffisent à fixer la foi sur la Trinité et sur Marie, Mère de Dieu.', '[{"text": "Nicée affirme que le Fils est de même nature que le Père.", "translation": "C''est le premier des trois conciles."}, {"text": "Éphèse, le troisième, proclame Marie « Mère de Dieu ».", "translation": "Il condamne Nestorius."}]'::jsonb, null, '{"id": "eg.d.trois_conciles", "word": "trois conciles", "translation": "les conciles reçus par les orthodoxes orientaux : Nicée, Constantinople, Éphèse", "partOfSpeech": "concept", "explanation": "Les orthodoxes orientaux reçoivent Nicée (325), Constantinople (381) et Éphèse (431). Ces trois conciles suffisent à fixer la foi sur la Trinité et sur Marie, Mère de Dieu.", "examples": [{"text": "Nicée affirme que le Fils est de même nature que le Père.", "translation": "C''est le premier des trois conciles."}, {"text": "Éphèse, le troisième, proclame Marie « Mère de Dieu ».", "translation": "Il condamne Nestorius."}], "unitId": "eg.v.trois_conciles"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.patriarcat_grec_d_alexandrie', 'eg', 'patriarcat grec d''Alexandrie', 'Église orthodoxe chalcédonienne d''Égypte et d''Afrique, distincte de l''Église copte', 'Il descend de la ligne melkite. Il a son patriarche, son église grecque et ses fidèles, en Égypte et en Afrique. Il est en communion avec Constantinople, pas avec notre pape.', '[{"text": "Le patriarche grec orthodoxe d''Alexandrie porte aussi le titre de pape.", "translation": "Mais il ne dirige pas l''Église copte."}, {"text": "En Égypte, il existe donc deux patriarches d''Alexandrie, l''un copte, l''autre grec.", "translation": "Ils sont issus de la rupture de 451."}]'::jsonb, null, '{"id": "eg.d.patriarcat_grec_d_alexandrie", "word": "patriarcat grec d''Alexandrie", "translation": "Église orthodoxe chalcédonienne d''Égypte et d''Afrique, distincte de l''Église copte", "partOfSpeech": "organization", "explanation": "Il descend de la ligne melkite. Il a son patriarche, son église grecque et ses fidèles, en Égypte et en Afrique. Il est en communion avec Constantinople, pas avec notre pape.", "examples": [{"text": "Le patriarche grec orthodoxe d''Alexandrie porte aussi le titre de pape.", "translation": "Mais il ne dirige pas l''Église copte."}, {"text": "En Égypte, il existe donc deux patriarches d''Alexandrie, l''un copte, l''autre grec.", "translation": "Ils sont issus de la rupture de 451."}], "unitId": "eg.v.patriarcat_grec_d_alexandrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dialogue_chambesy', 'eg', 'dialogue de Wadi Natroun et de Chambésy', 'commissions mixtes (1989-1990) entre orthodoxes orientaux et chalcédoniens', 'En 1989 au monastère d''Anba Bishoy (Wadi Natroun), puis en 1990 à Chambésy (Suisse), des théologiens des deux familles ont constaté qu''ils confessent la même foi dans le Christ.', '[{"text": "Les deux familles ont reconnu que leurs formules signifient la même foi.", "translation": "Le désaccord est surtout dans les mots."}, {"text": "Il reste à régler la réception des conciles et le statut des condamnés.", "translation": "Le chemin vers l''unité est long."}]'::jsonb, null, '{"id": "eg.d.dialogue_chambesy", "word": "dialogue de Wadi Natroun et de Chambésy", "translation": "commissions mixtes (1989-1990) entre orthodoxes orientaux et chalcédoniens", "partOfSpeech": "event", "explanation": "En 1989 au monastère d''Anba Bishoy (Wadi Natroun), puis en 1990 à Chambésy (Suisse), des théologiens des deux familles ont constaté qu''ils confessent la même foi dans le Christ.", "examples": [{"text": "Les deux familles ont reconnu que leurs formules signifient la même foi.", "translation": "Le désaccord est surtout dans les mots."}, {"text": "Il reste à régler la réception des conciles et le statut des condamnés.", "translation": "Le chemin vers l''unité est long."}], "unitId": "eg.v.dialogue_chambesy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pape', 'eg', 'pape', 'évêque de Rome pour les catholiques ; évêque d''Alexandrie pour les Coptes', 'Le mot vient de pappas, « père ». Il est porté très tôt par l''évêque d''Alexandrie et ne sera réservé à Rome que plus tard en Occident.', '[{"text": "Notre pape est le successeur de saint Marc.", "translation": "Le pape de Rome se dit successeur de saint Pierre."}, {"text": "Le mot « pape » veut dire « père ».", "translation": "Il a d''abord été un titre de respect pour les évêques."}]'::jsonb, null, '{"id": "eg.d.pape", "word": "pape", "translation": "évêque de Rome pour les catholiques ; évêque d''Alexandrie pour les Coptes", "partOfSpeech": "person", "explanation": "Le mot vient de pappas, « père ». Il est porté très tôt par l''évêque d''Alexandrie et ne sera réservé à Rome que plus tard en Occident.", "examples": [{"text": "Notre pape est le successeur de saint Marc.", "translation": "Le pape de Rome se dit successeur de saint Pierre."}, {"text": "Le mot « pape » veut dire « père ».", "translation": "Il a d''abord été un titre de respect pour les évêques."}], "unitId": "eg.v.pape"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.primaute_du_pape', 'eg', 'primauté du pape', 'autorité que les catholiques reconnaissent au pape sur toute l''Église', 'Pour les catholiques, Jésus a confié à Pierre une mission de premier (Matthieu 16, 18) et le pape, évêque de Rome, en hérite. Les orthodoxes honorent Rome mais refusent un chef sur tous les évêques.', '[{"text": "Selon les catholiques, le pape tranche en dernier ressort.", "translation": "Les orthodoxes préfèrent les décisions en concile."}, {"text": "Les orthodoxes reconnaissaient à Rome une primauté d''honneur.", "translation": "Honneur n''est pas pouvoir."}]'::jsonb, null, '{"id": "eg.d.primaute_du_pape", "word": "primauté du pape", "translation": "autorité que les catholiques reconnaissent au pape sur toute l''Église", "partOfSpeech": "concept", "explanation": "Pour les catholiques, Jésus a confié à Pierre une mission de premier (Matthieu 16, 18) et le pape, évêque de Rome, en hérite. Les orthodoxes honorent Rome mais refusent un chef sur tous les évêques.", "examples": [{"text": "Selon les catholiques, le pape tranche en dernier ressort.", "translation": "Les orthodoxes préfèrent les décisions en concile."}, {"text": "Les orthodoxes reconnaissaient à Rome une primauté d''honneur.", "translation": "Honneur n''est pas pouvoir."}], "unitId": "eg.v.primaute_du_pape"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.infaillibilite_pontificale', 'eg', 'infaillibilité pontificale', 'dogme de 1870 : le pape ne se trompe pas quand il enseigne ex cathedra sur la foi et la morale', 'Elle est définie par Vatican I en 1870. Elle ne concerne pas toutes les paroles du pape, seulement certaines décisions solennelles sur la foi et la morale.', '[{"text": "Le dogme de l''Assomption de Marie (1950) a été défini ainsi par le pape.", "translation": "C''est l''exemple le plus connu."}, {"text": "L''infaillibilité n''est pas l''impeccabilité : un pape peut pécher.", "translation": "C''est une confusion fréquente."}]'::jsonb, null, '{"id": "eg.d.infaillibilite_pontificale", "word": "infaillibilité pontificale", "translation": "dogme de 1870 : le pape ne se trompe pas quand il enseigne ex cathedra sur la foi et la morale", "partOfSpeech": "concept", "explanation": "Elle est définie par Vatican I en 1870. Elle ne concerne pas toutes les paroles du pape, seulement certaines décisions solennelles sur la foi et la morale.", "examples": [{"text": "Le dogme de l''Assomption de Marie (1950) a été défini ainsi par le pape.", "translation": "C''est l''exemple le plus connu."}, {"text": "L''infaillibilité n''est pas l''impeccabilité : un pape peut pécher.", "translation": "C''est une confusion fréquente."}], "unitId": "eg.v.infaillibilite_pontificale"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.vatican_i', 'eg', 'Vatican I', 'concile catholique de 1869-1870 qui définit l''infaillibilité pontificale', 'Réuni par Pie IX à Rome, il définit le 18 juillet 1870 la primauté de juridiction et l''infaillibilité du pape. Il est interrompu par la guerre.', '[{"text": "Les orthodoxes et les protestants ne reconnaissent pas ce concile.", "translation": "Il n''a rien d''œcuménique pour eux."}, {"text": "Vatican II (1962-1965) a ensuite parlé d''ouverture aux autres Églises.", "translation": "Il a changé le ton."}]'::jsonb, null, '{"id": "eg.d.vatican_i", "word": "Vatican I", "translation": "concile catholique de 1869-1870 qui définit l''infaillibilité pontificale", "partOfSpeech": "event", "explanation": "Réuni par Pie IX à Rome, il définit le 18 juillet 1870 la primauté de juridiction et l''infaillibilité du pape. Il est interrompu par la guerre.", "examples": [{"text": "Les orthodoxes et les protestants ne reconnaissent pas ce concile.", "translation": "Il n''a rien d''œcuménique pour eux."}, {"text": "Vatican II (1962-1965) a ensuite parlé d''ouverture aux autres Églises.", "translation": "Il a changé le ton."}], "unitId": "eg.v.vatican_i"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.filioque', 'eg', 'Filioque', 'ajout latin « et du Fils » au Credo de Nicée-Constantinople', 'Le mot latin veut dire « et du Fils ». Le Credo de 381 dit que l''Esprit procède du Père ; l''Occident a ajouté « et du Fils ».', '[{"text": "Le Credo copte dit seulement que l''Esprit procède du Père.", "translation": "Il suit le texte de 381."}, {"text": "Le Filioque est apparu en Espagne avant de gagner Rome.", "translation": "Rome l''a adopté en 1014."}]'::jsonb, null, '{"id": "eg.d.filioque", "word": "Filioque", "translation": "ajout latin « et du Fils » au Credo de Nicée-Constantinople", "partOfSpeech": "concept", "explanation": "Le mot latin veut dire « et du Fils ». Le Credo de 381 dit que l''Esprit procède du Père ; l''Occident a ajouté « et du Fils ».", "examples": [{"text": "Le Credo copte dit seulement que l''Esprit procède du Père.", "translation": "Il suit le texte de 381."}, {"text": "Le Filioque est apparu en Espagne avant de gagner Rome.", "translation": "Rome l''a adopté en 1014."}], "unitId": "eg.v.filioque"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.schisme_de_1054', 'eg', 'schisme de 1054', 'rupture entre l''Église de Rome et celle de Constantinople', 'Le 16 juillet 1054, un légat du pape dépose à Sainte-Sophie une bulle d''excommunication contre le patriarche de Constantinople, qui répond par une excommunication. Elles sont levées en 1965.', '[{"text": "En 1054, les mots « catholique » et « orthodoxe » deviennent deux camps.", "translation": "La rupture était préparée depuis longtemps."}, {"text": "En 1965, Paul VI et Athénagoras lèvent les excommunications de 1054.", "translation": "La communion n''est pas encore rétablie."}]'::jsonb, null, '{"id": "eg.d.schisme_de_1054", "word": "schisme de 1054", "translation": "rupture entre l''Église de Rome et celle de Constantinople", "partOfSpeech": "event", "explanation": "Le 16 juillet 1054, un légat du pape dépose à Sainte-Sophie une bulle d''excommunication contre le patriarche de Constantinople, qui répond par une excommunication. Elles sont levées en 1965.", "examples": [{"text": "En 1054, les mots « catholique » et « orthodoxe » deviennent deux camps.", "translation": "La rupture était préparée depuis longtemps."}, {"text": "En 1965, Paul VI et Athénagoras lèvent les excommunications de 1054.", "translation": "La communion n''est pas encore rétablie."}], "unitId": "eg.v.schisme_de_1054"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ex_cathedra', 'eg', 'ex cathedra', 'expression latine : « depuis la chaire », quand le pape enseigne solennellement', 'Un pape parle ex cathedra quand il définit une vérité de foi ou de morale comme chef de l''Église entière. C''est rare.', '[{"text": "Un discours ou une interview du pape n''est pas ex cathedra.", "translation": "Seules certaines définitions solennelles le sont."}, {"text": "Le mot cathedra a donné cathédrale, l''église de la chaire de l''évêque.", "translation": "La chaire est le symbole de l''enseignement."}]'::jsonb, null, '{"id": "eg.d.ex_cathedra", "word": "ex cathedra", "translation": "expression latine : « depuis la chaire », quand le pape enseigne solennellement", "partOfSpeech": "expression", "explanation": "Un pape parle ex cathedra quand il définit une vérité de foi ou de morale comme chef de l''Église entière. C''est rare.", "examples": [{"text": "Un discours ou une interview du pape n''est pas ex cathedra.", "translation": "Seules certaines définitions solennelles le sont."}, {"text": "Le mot cathedra a donné cathédrale, l''église de la chaire de l''évêque.", "translation": "La chaire est le symbole de l''enseignement."}], "unitId": "eg.v.ex_cathedra"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.purgatoire', 'eg', 'purgatoire', 'dans la foi catholique, purification après la mort avant d''entrer au ciel', 'Les catholiques croient que ceux qui meurent en grâce, mais sans être totalement purifiés, sont purifiés après la mort. La doctrine est précisée à Lyon II (1274). L''Église copte ne l''enseigne pas.', '[{"text": "Selon les catholiques, le purgatoire est un état provisoire, non un lieu de condamnation.", "translation": "Il mène toujours au ciel."}, {"text": "L''Église copte prie pour les défunts sans enseigner le purgatoire.", "translation": "Elle laisse le jugement à Dieu seul."}]'::jsonb, null, '{"id": "eg.d.purgatoire", "word": "purgatoire", "translation": "dans la foi catholique, purification après la mort avant d''entrer au ciel", "partOfSpeech": "concept", "explanation": "Les catholiques croient que ceux qui meurent en grâce, mais sans être totalement purifiés, sont purifiés après la mort. La doctrine est précisée à Lyon II (1274). L''Église copte ne l''enseigne pas.", "examples": [{"text": "Selon les catholiques, le purgatoire est un état provisoire, non un lieu de condamnation.", "translation": "Il mène toujours au ciel."}, {"text": "L''Église copte prie pour les défunts sans enseigner le purgatoire.", "translation": "Elle laisse le jugement à Dieu seul."}], "unitId": "eg.v.purgatoire"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.immaculee_conception', 'eg', 'Immaculée Conception', 'dogme catholique de 1854 : Marie conçue sans péché originel', 'Pie IX la définit le 8 décembre 1854. Elle concerne la conception de Marie, non celle de Jésus. L''Église copte vénère Marie toute pure mais n''enseigne pas ce dogme.', '[{"text": "L''Immaculée Conception est fêtée le 8 décembre par les catholiques.", "translation": "Le 25 mars est l''Annonciation."}, {"text": "Beaucoup confondent l''Immaculée Conception et la naissance virginale de Jésus.", "translation": "Ce sont deux choses différentes."}]'::jsonb, null, '{"id": "eg.d.immaculee_conception", "word": "Immaculée Conception", "translation": "dogme catholique de 1854 : Marie conçue sans péché originel", "partOfSpeech": "concept", "explanation": "Pie IX la définit le 8 décembre 1854. Elle concerne la conception de Marie, non celle de Jésus. L''Église copte vénère Marie toute pure mais n''enseigne pas ce dogme.", "examples": [{"text": "L''Immaculée Conception est fêtée le 8 décembre par les catholiques.", "translation": "Le 25 mars est l''Annonciation."}, {"text": "Beaucoup confondent l''Immaculée Conception et la naissance virginale de Jésus.", "translation": "Ce sont deux choses différentes."}], "unitId": "eg.v.immaculee_conception"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.peche_originel', 'eg', 'péché originel', 'faute d''Adam dont les catholiques disent qu''elle touche chaque homme dès sa conception', 'Saint Augustin parle d''un péché transmis à la naissance. Les orthodoxes parlent plutôt d''un héritage de mortalité et de faiblesse, sans culpabilité héritée.', '[{"text": "Selon les catholiques, le baptême efface le péché originel.", "translation": "Les orthodoxes y voient aussi une guérison."}, {"text": "Le dogme de l''Immaculée Conception s''appuie sur la doctrine du péché originel.", "translation": "Il suppose la lecture d''Augustin."}]'::jsonb, null, '{"id": "eg.d.peche_originel", "word": "péché originel", "translation": "faute d''Adam dont les catholiques disent qu''elle touche chaque homme dès sa conception", "partOfSpeech": "concept", "explanation": "Saint Augustin parle d''un péché transmis à la naissance. Les orthodoxes parlent plutôt d''un héritage de mortalité et de faiblesse, sans culpabilité héritée.", "examples": [{"text": "Selon les catholiques, le baptême efface le péché originel.", "translation": "Les orthodoxes y voient aussi une guérison."}, {"text": "Le dogme de l''Immaculée Conception s''appuie sur la doctrine du péché originel.", "translation": "Il suppose la lecture d''Augustin."}], "unitId": "eg.v.peche_originel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.azymes', 'eg', 'azymes', 'pain sans levain utilisé par l''Église latine pour l''Eucharistie', 'Les catholiques latins consacrent une petite hostie de pain sans levain. Les Arméniens utilisent aussi des azymes. L''Église copte utilise du pain levé.', '[{"text": "L''hostie des messes latines est un pain azyme.", "translation": "Elle est mince, blanche et ronde."}, {"text": "La question du pain a joué dans la rupture de 1054.", "translation": "Les deux camps s''accusaient mutuellement."}]'::jsonb, null, '{"id": "eg.d.azymes", "word": "azymes", "translation": "pain sans levain utilisé par l''Église latine pour l''Eucharistie", "partOfSpeech": "concept", "explanation": "Les catholiques latins consacrent une petite hostie de pain sans levain. Les Arméniens utilisent aussi des azymes. L''Église copte utilise du pain levé.", "examples": [{"text": "L''hostie des messes latines est un pain azyme.", "translation": "Elle est mince, blanche et ronde."}, {"text": "La question du pain a joué dans la rupture de 1054.", "translation": "Les deux camps s''accusaient mutuellement."}], "unitId": "eg.v.azymes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pain_leve', 'eg', 'pain levé', 'pain fait avec du levain, utilisé dans l''Église copte pour l''Eucharistie', 'Le pain de l''offrande copte est un pain levé, qu''on estampille d''une croix. Il est vivant : il évoque la Résurrection.', '[{"text": "Le qorban copte est un pain levé préparé pour la messe.", "translation": "Il porte l''empreinte de la croix."}, {"text": "Les orthodoxes grecs utilisent aussi du pain levé.", "translation": "C''est l''ancien usage de l''Orient."}]'::jsonb, null, '{"id": "eg.d.pain_leve", "word": "pain levé", "translation": "pain fait avec du levain, utilisé dans l''Église copte pour l''Eucharistie", "partOfSpeech": "concept", "explanation": "Le pain de l''offrande copte est un pain levé, qu''on estampille d''une croix. Il est vivant : il évoque la Résurrection.", "examples": [{"text": "Le qorban copte est un pain levé préparé pour la messe.", "translation": "Il porte l''empreinte de la croix."}, {"text": "Les orthodoxes grecs utilisent aussi du pain levé.", "translation": "C''est l''ancien usage de l''Orient."}], "unitId": "eg.v.pain_leve"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.celibat_des_pretres', 'eg', 'célibat des prêtres', 'règle de l''Église latine : les prêtres ne se marient pas', 'Dans l''Église latine, la règle générale du célibat est affermie au XIIe siècle. Chez les Coptes, un homme marié avant l''ordination peut devenir prêtre.', '[{"text": "Le prêtre copte marié est appelé abouna.", "translation": "Sa femme est la khouriya."}, {"text": "Les évêques et les patriarches coptes sont toujours des moines célibataires.", "translation": "Le pape est choisi parmi eux."}]'::jsonb, null, '{"id": "eg.d.celibat_des_pretres", "word": "célibat des prêtres", "translation": "règle de l''Église latine : les prêtres ne se marient pas", "partOfSpeech": "concept", "explanation": "Dans l''Église latine, la règle générale du célibat est affermie au XIIe siècle. Chez les Coptes, un homme marié avant l''ordination peut devenir prêtre.", "examples": [{"text": "Le prêtre copte marié est appelé abouna.", "translation": "Sa femme est la khouriya."}, {"text": "Les évêques et les patriarches coptes sont toujours des moines célibataires.", "translation": "Le pape est choisi parmi eux."}], "unitId": "eg.v.celibat_des_pretres"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.prieres_pour_les_defunts', 'eg', 'prières pour les défunts', 'prières de l''Église pour ceux qui sont morts, aux 3e, 7e et 40e jours', 'L''Église copte prie pour les défunts à l''église, à la messe et lors de commémorations. Elle croit que ces prières les aident, sans décrire un purgatoire.', '[{"text": "La famille fait dire une messe pour le défunt le quarantième jour.", "translation": "C''est un usage ancien."}, {"text": "Les prières pour les défunts figurent dans la liturgie de saint Basile.", "translation": "Elles disent l''unité entre vivants et défunts."}]'::jsonb, null, '{"id": "eg.d.prieres_pour_les_defunts", "word": "prières pour les défunts", "translation": "prières de l''Église pour ceux qui sont morts, aux 3e, 7e et 40e jours", "partOfSpeech": "concept", "explanation": "L''Église copte prie pour les défunts à l''église, à la messe et lors de commémorations. Elle croit que ces prières les aident, sans décrire un purgatoire.", "examples": [{"text": "La famille fait dire une messe pour le défunt le quarantième jour.", "translation": "C''est un usage ancien."}, {"text": "Les prières pour les défunts figurent dans la liturgie de saint Basile.", "translation": "Elles disent l''unité entre vivants et défunts."}], "unitId": "eg.v.prieres_pour_les_defunts"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.martin_luther', 'eg', 'Martin Luther', 'moine allemand à l''origine de la Réforme en 1517', 'Moine augustin et professeur à Wittenberg, il proteste contre la vente des indulgences. Excommunié en 1521, il traduit la Bible en allemand.', '[{"text": "Luther a traduit la Bible en allemand pendant son séjour à la Wartburg.", "translation": "Cela a aidé l''allemand à devenir une langue écrite."}, {"text": "Les luthériens portent son nom.", "translation": "Ils sont nombreux en Allemagne et en Scandinavie."}]'::jsonb, null, '{"id": "eg.d.martin_luther", "word": "Martin Luther", "translation": "moine allemand à l''origine de la Réforme en 1517", "partOfSpeech": "person", "explanation": "Moine augustin et professeur à Wittenberg, il proteste contre la vente des indulgences. Excommunié en 1521, il traduit la Bible en allemand.", "examples": [{"text": "Luther a traduit la Bible en allemand pendant son séjour à la Wartburg.", "translation": "Cela a aidé l''allemand à devenir une langue écrite."}, {"text": "Les luthériens portent son nom.", "translation": "Ils sont nombreux en Allemagne et en Scandinavie."}], "unitId": "eg.v.martin_luther"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.theses_de_wittenberg', 'eg', '95 thèses', 'texte de Luther contre les indulgences, traditionnellement daté du 31 octobre 1517', 'Les 95 thèses discutent la vente des indulgences. Elles circulent très vite grâce à l''imprimerie. Elles marquent le début symbolique de la Réforme.', '[{"text": "Selon la tradition, Luther les affiche à Wittenberg le 31 octobre 1517.", "translation": "Les historiens discutent de la scène exacte."}, {"text": "Les thèses sont écrites en latin pour une discussion entre théologiens.", "translation": "Elles sont ensuite traduites et imprimées."}]'::jsonb, null, '{"id": "eg.d.theses_de_wittenberg", "word": "95 thèses", "translation": "texte de Luther contre les indulgences, traditionnellement daté du 31 octobre 1517", "partOfSpeech": "work", "explanation": "Les 95 thèses discutent la vente des indulgences. Elles circulent très vite grâce à l''imprimerie. Elles marquent le début symbolique de la Réforme.", "examples": [{"text": "Selon la tradition, Luther les affiche à Wittenberg le 31 octobre 1517.", "translation": "Les historiens discutent de la scène exacte."}, {"text": "Les thèses sont écrites en latin pour une discussion entre théologiens.", "translation": "Elles sont ensuite traduites et imprimées."}], "unitId": "eg.v.theses_de_wittenberg"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.reforme', 'eg', 'la Réforme', 'mouvement religieux du XVIe siècle qui crée le protestantisme', 'Commencée en 1517, elle divise l''Europe occidentale entre catholiques et protestants. Elle reproche à l''Église latine des abus et des doctrines sans fondement biblique.', '[{"text": "La Réforme gagne l''Allemagne, la Suisse, la France, l''Angleterre et l''Écosse.", "translation": "Elle prend des formes différentes."}, {"text": "Les protestants tirent leur nom de la « protestation » de Spire, en 1529.", "translation": "Les princes luthériens y protestent contre une décision."}]'::jsonb, null, '{"id": "eg.d.reforme", "word": "la Réforme", "translation": "mouvement religieux du XVIe siècle qui crée le protestantisme", "partOfSpeech": "event", "explanation": "Commencée en 1517, elle divise l''Europe occidentale entre catholiques et protestants. Elle reproche à l''Église latine des abus et des doctrines sans fondement biblique.", "examples": [{"text": "La Réforme gagne l''Allemagne, la Suisse, la France, l''Angleterre et l''Écosse.", "translation": "Elle prend des formes différentes."}, {"text": "Les protestants tirent leur nom de la « protestation » de Spire, en 1529.", "translation": "Les princes luthériens y protestent contre une décision."}], "unitId": "eg.v.reforme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sola_scriptura', 'eg', 'sola scriptura', 'principe protestant : l''Écriture seule est l''autorité de la foi', 'En latin : « l''Écriture seule ». Pour les protestants, la Bible juge la Tradition. Pour l''Église copte, Écriture et Tradition viennent du même Esprit.', '[{"text": "Les réformateurs veulent revenir à la Bible, loin des traditions humaines.", "translation": "C''est le cœur de leur réforme."}, {"text": "L''Église copte répond que la Bible elle-même est née dans l''Église.", "translation": "L''Église a reconnu les livres du Nouveau Testament."}]'::jsonb, null, '{"id": "eg.d.sola_scriptura", "word": "sola scriptura", "translation": "principe protestant : l''Écriture seule est l''autorité de la foi", "partOfSpeech": "concept", "explanation": "En latin : « l''Écriture seule ». Pour les protestants, la Bible juge la Tradition. Pour l''Église copte, Écriture et Tradition viennent du même Esprit.", "examples": [{"text": "Les réformateurs veulent revenir à la Bible, loin des traditions humaines.", "translation": "C''est le cœur de leur réforme."}, {"text": "L''Église copte répond que la Bible elle-même est née dans l''Église.", "translation": "L''Église a reconnu les livres du Nouveau Testament."}], "unitId": "eg.v.sola_scriptura"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sola_fide', 'eg', 'sola fide', 'principe protestant : le salut vient par la foi seule', 'En latin : « par la foi seule ». Luther s''appuie sur Romains 3, 28. L''Église copte unit la foi et les œuvres de l''amour, selon Jacques 2, 24.', '[{"text": "Luther lit dans Romains que l''homme est justifié par la foi.", "translation": "Il rejette l''idée qu''on peut acheter le salut."}, {"text": "Pour les Coptes, la foi est vivante par les œuvres de charité.", "translation": "Jacques 2, 17 dit que la foi sans les œuvres est morte."}]'::jsonb, null, '{"id": "eg.d.sola_fide", "word": "sola fide", "translation": "principe protestant : le salut vient par la foi seule", "partOfSpeech": "concept", "explanation": "En latin : « par la foi seule ». Luther s''appuie sur Romains 3, 28. L''Église copte unit la foi et les œuvres de l''amour, selon Jacques 2, 24.", "examples": [{"text": "Luther lit dans Romains que l''homme est justifié par la foi.", "translation": "Il rejette l''idée qu''on peut acheter le salut."}, {"text": "Pour les Coptes, la foi est vivante par les œuvres de charité.", "translation": "Jacques 2, 17 dit que la foi sans les œuvres est morte."}], "unitId": "eg.v.sola_fide"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jean_calvin', 'eg', 'Jean Calvin', 'réformateur français établi à Genève, auteur de l''Institution de la religion chrétienne', 'Né à Noyon en 1509, il publie en 1536 l''Institution de la religion chrétienne et organise l''Église de Genève. Les Églises réformées et presbytériennes en descendent.', '[{"text": "Calvin insiste sur la souveraineté de Dieu.", "translation": "C''est un trait fort de la tradition réformée."}, {"text": "L''Église évangélique d''Égypte appartient à la famille presbytérienne.", "translation": "Elle descend donc de la tradition de Calvin."}]'::jsonb, null, '{"id": "eg.d.jean_calvin", "word": "Jean Calvin", "translation": "réformateur français établi à Genève, auteur de l''Institution de la religion chrétienne", "partOfSpeech": "person", "explanation": "Né à Noyon en 1509, il publie en 1536 l''Institution de la religion chrétienne et organise l''Église de Genève. Les Églises réformées et presbytériennes en descendent.", "examples": [{"text": "Calvin insiste sur la souveraineté de Dieu.", "translation": "C''est un trait fort de la tradition réformée."}, {"text": "L''Église évangélique d''Égypte appartient à la famille presbytérienne.", "translation": "Elle descend donc de la tradition de Calvin."}], "unitId": "eg.v.jean_calvin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.deuterocanoniques', 'eg', 'livres deutérocanoniques', 'livres de l''Ancien Testament gardés par les Coptes mais absents de la Bible protestante', 'Tobie, Judith, Sagesse, Siracide, Baruch et Maccabées figurent dans la Bible grecque de la Septante. Les protestants les écartent ; les Coptes, les orthodoxes et les catholiques les gardent.', '[{"text": "La Sagesse de Salomon est lue dans l''Église copte.", "translation": "Les protestants ne la reçoivent pas comme Écriture."}, {"text": "Les deutérocanoniques sont dans la Septante, traduite à Alexandrie.", "translation": "L''Égypte a donc joué un rôle dans le canon."}]'::jsonb, null, '{"id": "eg.d.deuterocanoniques", "word": "livres deutérocanoniques", "translation": "livres de l''Ancien Testament gardés par les Coptes mais absents de la Bible protestante", "partOfSpeech": "concept", "explanation": "Tobie, Judith, Sagesse, Siracide, Baruch et Maccabées figurent dans la Bible grecque de la Septante. Les protestants les écartent ; les Coptes, les orthodoxes et les catholiques les gardent.", "examples": [{"text": "La Sagesse de Salomon est lue dans l''Église copte.", "translation": "Les protestants ne la reçoivent pas comme Écriture."}, {"text": "Les deutérocanoniques sont dans la Septante, traduite à Alexandrie.", "translation": "L''Égypte a donc joué un rôle dans le canon."}], "unitId": "eg.v.deuterocanoniques"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sept_sacrements', 'eg', 'sept sacrements', 'baptême, chrismation, eucharistie, confession, onction des malades, mariage, sacerdoce', 'Un sacrement est un signe visible par lequel Dieu donne sa grâce. L''Église copte en compte sept, comme les catholiques et les orthodoxes grecs.', '[{"text": "Le baptême et la chrismation ouvrent la vie chrétienne.", "translation": "L''eucharistie la nourrit."}, {"text": "La confession et l''onction des malades guérissent l''âme et le corps.", "translation": "Le mariage et le sacerdoce consacrent une mission."}]'::jsonb, null, '{"id": "eg.d.sept_sacrements", "word": "sept sacrements", "translation": "baptême, chrismation, eucharistie, confession, onction des malades, mariage, sacerdoce", "partOfSpeech": "concept", "explanation": "Un sacrement est un signe visible par lequel Dieu donne sa grâce. L''Église copte en compte sept, comme les catholiques et les orthodoxes grecs.", "examples": [{"text": "Le baptême et la chrismation ouvrent la vie chrétienne.", "translation": "L''eucharistie la nourrit."}, {"text": "La confession et l''onction des malades guérissent l''âme et le corps.", "translation": "Le mariage et le sacerdoce consacrent une mission."}], "unitId": "eg.v.sept_sacrements"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.deux_sacrements', 'eg', 'deux sacrements', 'baptême et Cène : les seuls sacrements reconnus par la plupart des protestants', 'Les protestants retiennent ce que Jésus a lui-même institué de façon explicite : le baptême et la Cène. Les autres actes ne sont pas des sacrements pour eux.', '[{"text": "Dans beaucoup d''Églises protestantes, la Cène est surtout un mémorial.", "translation": "Luther croit pourtant à la présence réelle du Christ."}, {"text": "Les protestants vivent la confession et le mariage sans les appeler sacrements.", "translation": "Ils les respectent comme des actes de l''Église."}]'::jsonb, null, '{"id": "eg.d.deux_sacrements", "word": "deux sacrements", "translation": "baptême et Cène : les seuls sacrements reconnus par la plupart des protestants", "partOfSpeech": "concept", "explanation": "Les protestants retiennent ce que Jésus a lui-même institué de façon explicite : le baptême et la Cène. Les autres actes ne sont pas des sacrements pour eux.", "examples": [{"text": "Dans beaucoup d''Églises protestantes, la Cène est surtout un mémorial.", "translation": "Luther croit pourtant à la présence réelle du Christ."}, {"text": "Les protestants vivent la confession et le mariage sans les appeler sacrements.", "translation": "Ils les respectent comme des actes de l''Église."}], "unitId": "eg.v.deux_sacrements"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.intercession_des_saints', 'eg', 'intercession des saints', 'prière des saints pour nous, que l''on leur demande comme à des frères', 'Les saints sont vivants en Christ. On leur demande de prier pour nous, comme on demande à un frère de prier. Le Christ reste le seul médiateur.', '[{"text": "Chaque jour, l''Église copte prie la Vierge de prier pour nous.", "translation": "Elle dit : « intercède pour nous »."}, {"text": "Les protestants préfèrent s''adresser directement à Dieu.", "translation": "Ils citent 1 Timothée 2, 5."}]'::jsonb, null, '{"id": "eg.d.intercession_des_saints", "word": "intercession des saints", "translation": "prière des saints pour nous, que l''on leur demande comme à des frères", "partOfSpeech": "concept", "explanation": "Les saints sont vivants en Christ. On leur demande de prier pour nous, comme on demande à un frère de prier. Le Christ reste le seul médiateur.", "examples": [{"text": "Chaque jour, l''Église copte prie la Vierge de prier pour nous.", "translation": "Elle dit : « intercède pour nous »."}, {"text": "Les protestants préfèrent s''adresser directement à Dieu.", "translation": "Ils citent 1 Timothée 2, 5."}], "unitId": "eg.v.intercession_des_saints"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.veneration', 'eg', 'vénération', 'honneur rendu aux saints et aux icônes, différent de l''adoration', 'L''adoration est réservée à Dieu seul. La vénération est l''honneur rendu aux serviteurs de Dieu et aux images qui les représentent.', '[{"text": "On vénère un saint, on adore le Christ.", "translation": "La différence est capitale."}, {"text": "Le mot vient du latin venerari, « honorer ».", "translation": "Il n''implique aucune adoration."}]'::jsonb, null, '{"id": "eg.d.veneration", "word": "vénération", "translation": "honneur rendu aux saints et aux icônes, différent de l''adoration", "partOfSpeech": "concept", "explanation": "L''adoration est réservée à Dieu seul. La vénération est l''honneur rendu aux serviteurs de Dieu et aux images qui les représentent.", "examples": [{"text": "On vénère un saint, on adore le Christ.", "translation": "La différence est capitale."}, {"text": "Le mot vient du latin venerari, « honorer ».", "translation": "Il n''implique aucune adoration."}], "unitId": "eg.v.veneration"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.icone', 'eg', 'icône', 'image sacrée qui représente le Christ, Marie ou un saint', 'Du grec eikon, « image ». L''icône n''est pas adorée : l''honneur passe à celui qu''elle représente. Les Coptes ont une très ancienne tradition d''icônes.', '[{"text": "Les icônes coptes du Fayoum sont parmi les plus anciennes images chrétiennes.", "translation": "Elles datent des premiers siècles."}, {"text": "L''iconostase sépare le chœur de la nef et porte les icônes.", "translation": "Elle est le centre visuel de l''église copte."}]'::jsonb, null, '{"id": "eg.d.icone", "word": "icône", "translation": "image sacrée qui représente le Christ, Marie ou un saint", "partOfSpeech": "concept", "explanation": "Du grec eikon, « image ». L''icône n''est pas adorée : l''honneur passe à celui qu''elle représente. Les Coptes ont une très ancienne tradition d''icônes.", "examples": [{"text": "Les icônes coptes du Fayoum sont parmi les plus anciennes images chrétiennes.", "translation": "Elles datent des premiers siècles."}, {"text": "L''iconostase sépare le chœur de la nef et porte les icônes.", "translation": "Elle est le centre visuel de l''église copte."}], "unitId": "eg.v.icone"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pasteur', 'eg', 'pasteur', 'ministre d''une Église protestante, appelé par la communauté', 'Le pasteur prêche et dirige le culte. Il est ordonné par l''Église, mais n''est pas dans une chaîne d''évêques sur le modèle copte. Il peut être marié.', '[{"text": "Le pasteur protestant est souvent marié.", "translation": "Le prêtre copte peut l''être, avant l''ordination."}, {"text": "Dans l''Église presbytérienne, des anciens aident le pasteur.", "translation": "Presbytre veut dire « ancien »."}]'::jsonb, null, '{"id": "eg.d.pasteur", "word": "pasteur", "translation": "ministre d''une Église protestante, appelé par la communauté", "partOfSpeech": "person", "explanation": "Le pasteur prêche et dirige le culte. Il est ordonné par l''Église, mais n''est pas dans une chaîne d''évêques sur le modèle copte. Il peut être marié.", "examples": [{"text": "Le pasteur protestant est souvent marié.", "translation": "Le prêtre copte peut l''être, avant l''ordination."}, {"text": "Dans l''Église presbytérienne, des anciens aident le pasteur.", "translation": "Presbytre veut dire « ancien »."}], "unitId": "eg.v.pasteur"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_evangelique_d_egypte', 'eg', 'Église évangélique d''Égypte', 'Église presbytérienne d''Égypte (Synode du Nil), née de la mission américaine de 1854', 'Elle naît de la mission presbytérienne américaine arrivée en Égypte en 1854. C''est la plus grande Église protestante du pays. Elle a ouvert des écoles et des hôpitaux.', '[{"text": "Des écoles et des hôpitaux évangéliques existent dans plusieurs villes d''Égypte.", "translation": "Beaucoup d''Égyptiens y ont été soignés ou instruits."}, {"text": "Des coptes orthodoxes et des évangéliques vivent côte à côte en Égypte.", "translation": "Ils partagent la même nation et la foi au Christ."}]'::jsonb, null, '{"id": "eg.d.eglise_evangelique_d_egypte", "word": "Église évangélique d''Égypte", "translation": "Église presbytérienne d''Égypte (Synode du Nil), née de la mission américaine de 1854", "partOfSpeech": "organization", "explanation": "Elle naît de la mission presbytérienne américaine arrivée en Égypte en 1854. C''est la plus grande Église protestante du pays. Elle a ouvert des écoles et des hôpitaux.", "examples": [{"text": "Des écoles et des hôpitaux évangéliques existent dans plusieurs villes d''Égypte.", "translation": "Beaucoup d''Égyptiens y ont été soignés ou instruits."}, {"text": "Des coptes orthodoxes et des évangéliques vivent côte à côte en Égypte.", "translation": "Ils partagent la même nation et la foi au Christ."}], "unitId": "eg.v.eglise_evangelique_d_egypte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.mormons', 'eg', 'mormons', 'membres de l''Église de Jésus-Christ des saints des derniers jours, fondée en 1830', 'L''Église de Jésus-Christ des saints des derniers jours naît en 1830 à New York. Elle compte plus de 15 millions de membres et son siège est à Salt Lake City.', '[{"text": "Les mormons vivent une vie de famille très structurée.", "translation": "Ils s''abstiennent d''alcool, de tabac, de café et de thé."}, {"text": "Ils envoient beaucoup de jeunes en mission pendant environ deux ans.", "translation": "Les missionnaires se reconnaissent à leur tenue sobre."}]'::jsonb, null, '{"id": "eg.d.mormons", "word": "mormons", "translation": "membres de l''Église de Jésus-Christ des saints des derniers jours, fondée en 1830", "partOfSpeech": "organization", "explanation": "L''Église de Jésus-Christ des saints des derniers jours naît en 1830 à New York. Elle compte plus de 15 millions de membres et son siège est à Salt Lake City.", "examples": [{"text": "Les mormons vivent une vie de famille très structurée.", "translation": "Ils s''abstiennent d''alcool, de tabac, de café et de thé."}, {"text": "Ils envoient beaucoup de jeunes en mission pendant environ deux ans.", "translation": "Les missionnaires se reconnaissent à leur tenue sobre."}], "unitId": "eg.v.mormons"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.joseph_smith', 'eg', 'Joseph Smith', 'fondateur de l''Église mormone (1805-1844)', 'Né dans le Vermont, il affirme avoir eu une vision à 14 ans, puis avoir reçu des plaques d''or. Il est tué en 1844 par une foule.', '[{"text": "Joseph Smith a publié le Livre de Mormon en 1830.", "translation": "Il a fondé l''Église la même année."}, {"text": "Après sa mort, Brigham Young conduit les mormons dans l''Utah.", "translation": "Salt Lake City est fondée en 1847."}]'::jsonb, null, '{"id": "eg.d.joseph_smith", "word": "Joseph Smith", "translation": "fondateur de l''Église mormone (1805-1844)", "partOfSpeech": "person", "explanation": "Né dans le Vermont, il affirme avoir eu une vision à 14 ans, puis avoir reçu des plaques d''or. Il est tué en 1844 par une foule.", "examples": [{"text": "Joseph Smith a publié le Livre de Mormon en 1830.", "translation": "Il a fondé l''Église la même année."}, {"text": "Après sa mort, Brigham Young conduit les mormons dans l''Utah.", "translation": "Salt Lake City est fondée en 1847."}], "unitId": "eg.v.joseph_smith"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.livre_de_mormon', 'eg', 'Livre de Mormon', 'livre sacré mormon, présenté comme traduit de plaques d''or', 'Les mormons le considèrent comme une autre Écriture, à côté de la Bible. Il raconte l''histoire de peuples venus en Amérique.', '[{"text": "Le Livre de Mormon est publié en 1830.", "translation": "Il compte plusieurs « livres », comme la Bible."}, {"text": "Les mormons lisent aussi Doctrine et Alliances et la Perle de grand prix.", "translation": "Ce sont d''autres textes sacrés propres à leur Église."}]'::jsonb, null, '{"id": "eg.d.livre_de_mormon", "word": "Livre de Mormon", "translation": "livre sacré mormon, présenté comme traduit de plaques d''or", "partOfSpeech": "work", "explanation": "Les mormons le considèrent comme une autre Écriture, à côté de la Bible. Il raconte l''histoire de peuples venus en Amérique.", "examples": [{"text": "Le Livre de Mormon est publié en 1830.", "translation": "Il compte plusieurs « livres », comme la Bible."}, {"text": "Les mormons lisent aussi Doctrine et Alliances et la Perle de grand prix.", "translation": "Ce sont d''autres textes sacrés propres à leur Église."}], "unitId": "eg.v.livre_de_mormon"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.moroni', 'eg', 'Moroni', 'ange qui aurait révélé les plaques d''or à Joseph Smith', 'Selon Joseph Smith, un ange nommé Moroni lui apparaît en 1823 et lui montre où sont enterrées des plaques d''or.', '[{"text": "Une statue de l''ange Moroni couronne beaucoup de temples mormons.", "translation": "Elle souffle dans une trompette."}, {"text": "Les plaques n''ont jamais été présentées à des historiens.", "translation": "Pour les mormons, c''est une question de foi."}]'::jsonb, null, '{"id": "eg.d.moroni", "word": "Moroni", "translation": "ange qui aurait révélé les plaques d''or à Joseph Smith", "partOfSpeech": "person", "explanation": "Selon Joseph Smith, un ange nommé Moroni lui apparaît en 1823 et lui montre où sont enterrées des plaques d''or.", "examples": [{"text": "Une statue de l''ange Moroni couronne beaucoup de temples mormons.", "translation": "Elle souffle dans une trompette."}, {"text": "Les plaques n''ont jamais été présentées à des historiens.", "translation": "Pour les mormons, c''est une question de foi."}], "unitId": "eg.v.moroni"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.adventistes', 'eg', 'adventistes', 'chrétiens qui attendent le retour (l''avènement) du Christ et observent le samedi', 'Les adventistes du septième jour sont organisés en 1863 à Battle Creek (Michigan). Ils sont environ 22 millions et très actifs dans la santé et l''éducation.', '[{"text": "Les adventistes tiennent des hôpitaux et des écoles dans plus de 200 pays.", "translation": "Leur nom vient du latin adventus : venue."}, {"text": "Ils croient à la Trinité, comme nous.", "translation": "C''est un point commun important."}]'::jsonb, null, '{"id": "eg.d.adventistes", "word": "adventistes", "translation": "chrétiens qui attendent le retour (l''avènement) du Christ et observent le samedi", "partOfSpeech": "organization", "explanation": "Les adventistes du septième jour sont organisés en 1863 à Battle Creek (Michigan). Ils sont environ 22 millions et très actifs dans la santé et l''éducation.", "examples": [{"text": "Les adventistes tiennent des hôpitaux et des écoles dans plus de 200 pays.", "translation": "Leur nom vient du latin adventus : venue."}, {"text": "Ils croient à la Trinité, comme nous.", "translation": "C''est un point commun important."}], "unitId": "eg.v.adventistes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.william_miller', 'eg', 'William Miller', 'pasteur baptiste américain qui annonce le retour du Christ en 1843-1844', 'Après un calcul sur le livre de Daniel, il annonce le retour du Christ en 1843, puis le 22 octobre 1844. Rien ne se passe : c''est la Grande Déception.', '[{"text": "Miller étudie la Bible à la recherche de dates.", "translation": "Jésus avait pourtant dit que nul ne connaît le jour ni l''heure."}, {"text": "Beaucoup de disciples de Miller l''ont quitté après 1844.", "translation": "Un petit groupe est resté fidèle."}]'::jsonb, null, '{"id": "eg.d.william_miller", "word": "William Miller", "translation": "pasteur baptiste américain qui annonce le retour du Christ en 1843-1844", "partOfSpeech": "person", "explanation": "Après un calcul sur le livre de Daniel, il annonce le retour du Christ en 1843, puis le 22 octobre 1844. Rien ne se passe : c''est la Grande Déception.", "examples": [{"text": "Miller étudie la Bible à la recherche de dates.", "translation": "Jésus avait pourtant dit que nul ne connaît le jour ni l''heure."}, {"text": "Beaucoup de disciples de Miller l''ont quitté après 1844.", "translation": "Un petit groupe est resté fidèle."}], "unitId": "eg.v.william_miller"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.grande_deception', 'eg', 'Grande Déception', 'échec de la prédiction du retour du Christ le 22 octobre 1844', 'Le 22 octobre 1844, des milliers d''adventistes attendent le Christ. Il ne vient pas. Beaucoup quittent le mouvement ; d''autres réinterprètent la date.', '[{"text": "Le 22 octobre 1844 est resté dans l''histoire adventiste comme un jour de deuil.", "translation": "On parle de Great Disappointment."}, {"text": "Les adventistes ont ensuite dit que la date marquait un début dans le ciel.", "translation": "Ils parlent d''un jugement d''investigation."}]'::jsonb, null, '{"id": "eg.d.grande_deception", "word": "Grande Déception", "translation": "échec de la prédiction du retour du Christ le 22 octobre 1844", "partOfSpeech": "event", "explanation": "Le 22 octobre 1844, des milliers d''adventistes attendent le Christ. Il ne vient pas. Beaucoup quittent le mouvement ; d''autres réinterprètent la date.", "examples": [{"text": "Le 22 octobre 1844 est resté dans l''histoire adventiste comme un jour de deuil.", "translation": "On parle de Great Disappointment."}, {"text": "Les adventistes ont ensuite dit que la date marquait un début dans le ciel.", "translation": "Ils parlent d''un jugement d''investigation."}], "unitId": "eg.v.grande_deception"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ellen_white', 'eg', 'Ellen White', 'prophétesse et cofondatrice de l''Église adventiste (1827-1915)', 'Elle dit avoir reçu des visions. Ses nombreux écrits guident l''Église adventiste sur la santé, l''éducation et la foi.', '[{"text": "Ellen White encourage une alimentation saine et le repos.", "translation": "L''Église adventiste en a fait un modèle."}, {"text": "Les adventistes la considèrent comme dotée du don de prophétie.", "translation": "L''Église copte ne reconnaît pas de nouvelle révélation après les apôtres."}]'::jsonb, null, '{"id": "eg.d.ellen_white", "word": "Ellen White", "translation": "prophétesse et cofondatrice de l''Église adventiste (1827-1915)", "partOfSpeech": "person", "explanation": "Elle dit avoir reçu des visions. Ses nombreux écrits guident l''Église adventiste sur la santé, l''éducation et la foi.", "examples": [{"text": "Ellen White encourage une alimentation saine et le repos.", "translation": "L''Église adventiste en a fait un modèle."}, {"text": "Les adventistes la considèrent comme dotée du don de prophétie.", "translation": "L''Église copte ne reconnaît pas de nouvelle révélation après les apôtres."}], "unitId": "eg.v.ellen_white"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sabbat_du_samedi', 'eg', 'sabbat du samedi', 'jour de repos observé par les adventistes du septième jour', 'Ils s''appuient sur le quatrième commandement. Pour l''Église copte, le jour du Seigneur est le dimanche, jour de la Résurrection.', '[{"text": "Les adventistes ne travaillent pas le samedi.", "translation": "Ils vont à l''église ce jour-là."}, {"text": "L''Église copte célèbre le jour du Seigneur le dimanche.", "translation": "Les Actes 20, 7 montrent les chrétiens réunis le premier jour de la semaine."}]'::jsonb, null, '{"id": "eg.d.sabbat_du_samedi", "word": "sabbat du samedi", "translation": "jour de repos observé par les adventistes du septième jour", "partOfSpeech": "concept", "explanation": "Ils s''appuient sur le quatrième commandement. Pour l''Église copte, le jour du Seigneur est le dimanche, jour de la Résurrection.", "examples": [{"text": "Les adventistes ne travaillent pas le samedi.", "translation": "Ils vont à l''église ce jour-là."}, {"text": "L''Église copte célèbre le jour du Seigneur le dimanche.", "translation": "Les Actes 20, 7 montrent les chrétiens réunis le premier jour de la semaine."}], "unitId": "eg.v.sabbat_du_samedi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.temoins_de_jehovah', 'eg', 'témoins de Jéhovah', 'mouvement né dans les années 1870 autour de Charles Taze Russell', 'Ils se réunissent dans des salles du Royaume et font du porte-à-porte. Ils sont environ 8 millions. Ils rejettent la Trinité et la divinité de Jésus.', '[{"text": "Les témoins de Jéhovah appellent Dieu « Jéhovah ».", "translation": "Pour eux, le Fils n''est pas Dieu au même titre."}, {"text": "Le nom « témoins de Jéhovah » est adopté en 1931.", "translation": "Auparavant, ils s''appelaient étudiants de la Bible."}]'::jsonb, null, '{"id": "eg.d.temoins_de_jehovah", "word": "témoins de Jéhovah", "translation": "mouvement né dans les années 1870 autour de Charles Taze Russell", "partOfSpeech": "organization", "explanation": "Ils se réunissent dans des salles du Royaume et font du porte-à-porte. Ils sont environ 8 millions. Ils rejettent la Trinité et la divinité de Jésus.", "examples": [{"text": "Les témoins de Jéhovah appellent Dieu « Jéhovah ».", "translation": "Pour eux, le Fils n''est pas Dieu au même titre."}, {"text": "Le nom « témoins de Jéhovah » est adopté en 1931.", "translation": "Auparavant, ils s''appelaient étudiants de la Bible."}], "unitId": "eg.v.temoins_de_jehovah"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.charles_taze_russell', 'eg', 'Charles Taze Russell', 'fondateur de la Watch Tower et des témoins de Jéhovah (1852-1916)', 'Ce marchand de Pittsburgh crée un groupe d''étude biblique dans les années 1870. En 1879, il publie la revue Zion''s Watch Tower.', '[{"text": "Russell n''était pas pasteur de formation.", "translation": "Il lisait la Bible avec un petit cercle à Pittsburgh."}, {"text": "La Watch Tower Society naît en 1884.", "translation": "Elle publie tous les écrits du mouvement."}]'::jsonb, null, '{"id": "eg.d.charles_taze_russell", "word": "Charles Taze Russell", "translation": "fondateur de la Watch Tower et des témoins de Jéhovah (1852-1916)", "partOfSpeech": "person", "explanation": "Ce marchand de Pittsburgh crée un groupe d''étude biblique dans les années 1870. En 1879, il publie la revue Zion''s Watch Tower.", "examples": [{"text": "Russell n''était pas pasteur de formation.", "translation": "Il lisait la Bible avec un petit cercle à Pittsburgh."}, {"text": "La Watch Tower Society naît en 1884.", "translation": "Elle publie tous les écrits du mouvement."}], "unitId": "eg.v.charles_taze_russell"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.traduction_du_monde_nouveau', 'eg', 'Traduction du monde nouveau', 'Bible des témoins de Jéhovah', 'C''est la Bible des témoins de Jéhovah. Elle traduit certains versets de façon à soutenir leurs croyances, comme Jean 1, 1.', '[{"text": "Dans cette traduction, Jean 1, 1 devient « le Verbe était un dieu ».", "translation": "Le grec dit « le Verbe était Dieu »."}, {"text": "La Bible complète est publiée en 1961.", "translation": "Elle est diffusée dans des centaines de langues."}]'::jsonb, null, '{"id": "eg.d.traduction_du_monde_nouveau", "word": "Traduction du monde nouveau", "translation": "Bible des témoins de Jéhovah", "partOfSpeech": "work", "explanation": "C''est la Bible des témoins de Jéhovah. Elle traduit certains versets de façon à soutenir leurs croyances, comme Jean 1, 1.", "examples": [{"text": "Dans cette traduction, Jean 1, 1 devient « le Verbe était un dieu ».", "translation": "Le grec dit « le Verbe était Dieu »."}, {"text": "La Bible complète est publiée en 1961.", "translation": "Elle est diffusée dans des centaines de langues."}], "unitId": "eg.v.traduction_du_monde_nouveau"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cent_quarante_quatre_mille', 'eg', '144 000', 'nombre de ceux qui, selon les témoins de Jéhovah, vivent au ciel avec le Christ', 'Ils lisent Apocalypse 7, 4 au sens propre. Les autres fidèles vivront sur une terre rendue paradisiaque. L''Église copte lit ce chiffre comme un symbole.', '[{"text": "Le chiffre 144 000 vient de Apocalypse 7, 4.", "translation": "Il vient de 12 × 12 × 1000, deux nombres symboliques."}, {"text": "Pour nous, ce nombre exprime la plénitude du peuple de Dieu.", "translation": "Il ne limite pas le salut."}]'::jsonb, null, '{"id": "eg.d.cent_quarante_quatre_mille", "word": "144 000", "translation": "nombre de ceux qui, selon les témoins de Jéhovah, vivent au ciel avec le Christ", "partOfSpeech": "number", "explanation": "Ils lisent Apocalypse 7, 4 au sens propre. Les autres fidèles vivront sur une terre rendue paradisiaque. L''Église copte lit ce chiffre comme un symbole.", "examples": [{"text": "Le chiffre 144 000 vient de Apocalypse 7, 4.", "translation": "Il vient de 12 × 12 × 1000, deux nombres symboliques."}, {"text": "Pour nous, ce nombre exprime la plénitude du peuple de Dieu.", "translation": "Il ne limite pas le salut."}], "unitId": "eg.v.cent_quarante_quatre_mille"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.refus_des_transfusions', 'eg', 'refus des transfusions sanguines', 'pratique des témoins de Jéhovah fondée sur Actes 15, 20', 'Ils lisent « abstenez-vous du sang » (Actes 15, 20) comme interdisant la transfusion. Ils acceptent pourtant les autres soins médicaux. L''Église copte y voit la sauvegarde de la vie comme un devoir.', '[{"text": "Les témoins de Jéhovah acceptent les médecins, mais pas le sang.", "translation": "Le refus concerne la transfusion, non tous les soins."}, {"text": "Pour l''Église copte, sauver une vie est un acte de charité.", "translation": "Le Christ est venu pour que nous ayons la vie."}]'::jsonb, null, '{"id": "eg.d.refus_des_transfusions", "word": "refus des transfusions sanguines", "translation": "pratique des témoins de Jéhovah fondée sur Actes 15, 20", "partOfSpeech": "concept", "explanation": "Ils lisent « abstenez-vous du sang » (Actes 15, 20) comme interdisant la transfusion. Ils acceptent pourtant les autres soins médicaux. L''Église copte y voit la sauvegarde de la vie comme un devoir.", "examples": [{"text": "Les témoins de Jéhovah acceptent les médecins, mais pas le sang.", "translation": "Le refus concerne la transfusion, non tous les soins."}, {"text": "Pour l''Église copte, sauver une vie est un acte de charité.", "translation": "Le Christ est venu pour que nous ayons la vie."}], "unitId": "eg.v.refus_des_transfusions"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.science_chretienne', 'eg', 'Science chrétienne', 'mouvement fondé par Mary Baker Eddy en 1879 à Boston', 'L''Église du Christ, scientiste, soutient que la matière, le péché, la maladie et la mort sont des illusions. Elle ne se confond pas avec la scientologie. Ses fidèles sont peu nombreux.', '[{"text": "La Science chrétienne publie le journal Christian Science Monitor.", "translation": "Il a gagné plusieurs prix de journalisme."}, {"text": "Ses fidèles comptent surtout sur la prière pour guérir.", "translation": "Ils n''ont pas de prêtres, mais des lecteurs."}]'::jsonb, null, '{"id": "eg.d.science_chretienne", "word": "Science chrétienne", "translation": "mouvement fondé par Mary Baker Eddy en 1879 à Boston", "partOfSpeech": "organization", "explanation": "L''Église du Christ, scientiste, soutient que la matière, le péché, la maladie et la mort sont des illusions. Elle ne se confond pas avec la scientologie. Ses fidèles sont peu nombreux.", "examples": [{"text": "La Science chrétienne publie le journal Christian Science Monitor.", "translation": "Il a gagné plusieurs prix de journalisme."}, {"text": "Ses fidèles comptent surtout sur la prière pour guérir.", "translation": "Ils n''ont pas de prêtres, mais des lecteurs."}], "unitId": "eg.v.science_chretienne"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.mary_baker_eddy', 'eg', 'Mary Baker Eddy', 'fondatrice de la Science chrétienne (1821-1910)', 'En 1866, elle fait une chute sur la glace, lit Matthieu 9, 2 et se relève guérie. Elle voit là une loi spirituelle et fonde son mouvement.', '[{"text": "Mary Baker Eddy s''est mariée trois fois.", "translation": "Elle était souvent malade."}, {"text": "Elle publie Science et Santé en 1875.", "translation": "L''Église est fondée à Boston en 1879."}]'::jsonb, null, '{"id": "eg.d.mary_baker_eddy", "word": "Mary Baker Eddy", "translation": "fondatrice de la Science chrétienne (1821-1910)", "partOfSpeech": "person", "explanation": "En 1866, elle fait une chute sur la glace, lit Matthieu 9, 2 et se relève guérie. Elle voit là une loi spirituelle et fonde son mouvement.", "examples": [{"text": "Mary Baker Eddy s''est mariée trois fois.", "translation": "Elle était souvent malade."}, {"text": "Elle publie Science et Santé en 1875.", "translation": "L''Église est fondée à Boston en 1879."}], "unitId": "eg.v.mary_baker_eddy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.science_et_sante', 'eg', 'Science et Santé', 'livre de Mary Baker Eddy publié en 1875, lu à côté de la Bible', 'Son titre complet est Science et Santé avec la clef des Écritures. Dans les églises scientistes, on le lit avec la Bible à chaque office.', '[{"text": "Dans ce livre, la maladie est présentée comme une erreur de l''esprit.", "translation": "La guérison vient d''une juste compréhension de Dieu."}, {"text": "La Bible et Science et Santé sont lues ensemble.", "translation": "C''est un deuxième livre d''autorité."}]'::jsonb, null, '{"id": "eg.d.science_et_sante", "word": "Science et Santé", "translation": "livre de Mary Baker Eddy publié en 1875, lu à côté de la Bible", "partOfSpeech": "work", "explanation": "Son titre complet est Science et Santé avec la clef des Écritures. Dans les églises scientistes, on le lit avec la Bible à chaque office.", "examples": [{"text": "Dans ce livre, la maladie est présentée comme une erreur de l''esprit.", "translation": "La guérison vient d''une juste compréhension de Dieu."}, {"text": "La Bible et Science et Santé sont lues ensemble.", "translation": "C''est un deuxième livre d''autorité."}], "unitId": "eg.v.science_et_sante"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.grande_apostasie', 'eg', 'grande apostasie', 'idée de plusieurs groupes récents : l''Église des apôtres aurait disparu, il faut la restaurer', 'Mormons et témoins de Jéhovah disent que la vraie Église a disparu après les apôtres. L''Église copte répond par la promesse du Christ : « les portes du séjour des morts ne prévaudront point » (Matthieu 16, 18).', '[{"text": "Joseph Smith dit avoir été chargé de restaurer l''Église.", "translation": "C''est le thème de la restauration."}, {"text": "Pour l''Église copte, la chaîne de saint Marc est ininterrompue.", "translation": "Le Christ n''a jamais abandonné son Église."}]'::jsonb, null, '{"id": "eg.d.grande_apostasie", "word": "grande apostasie", "translation": "idée de plusieurs groupes récents : l''Église des apôtres aurait disparu, il faut la restaurer", "partOfSpeech": "concept", "explanation": "Mormons et témoins de Jéhovah disent que la vraie Église a disparu après les apôtres. L''Église copte répond par la promesse du Christ : « les portes du séjour des morts ne prévaudront point » (Matthieu 16, 18).", "examples": [{"text": "Joseph Smith dit avoir été chargé de restaurer l''Église.", "translation": "C''est le thème de la restauration."}, {"text": "Pour l''Église copte, la chaîne de saint Marc est ininterrompue.", "translation": "Le Christ n''a jamais abandonné son Église."}], "unitId": "eg.v.grande_apostasie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.credo', 'eg', 'le Credo', '« je crois » en latin : le résumé de la foi', 'Credo est un mot latin qui veut dire « je crois ». Il désigne le texte court que l''Église récite pour confesser sa foi.', '[{"text": "Nous récitons le Credo debout.", "translation": "C''est la confession de foi de toute l''Église."}, {"text": "Credo vient du latin.", "translation": "Il veut dire « je crois »."}]'::jsonb, null, '{"id": "eg.d.credo", "word": "le Credo", "translation": "« je crois » en latin : le résumé de la foi", "partOfSpeech": "concept", "explanation": "Credo est un mot latin qui veut dire « je crois ». Il désigne le texte court que l''Église récite pour confesser sa foi.", "examples": [{"text": "Nous récitons le Credo debout.", "translation": "C''est la confession de foi de toute l''Église."}, {"text": "Credo vient du latin.", "translation": "Il veut dire « je crois »."}], "unitId": "eg.v.credo"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nous_croyons', 'eg', '« nous croyons »', 'le pluriel du Credo : la foi de toute l''Église', 'Le texte des conciles et la prière copte disent « nous croyons ». La foi est reçue et confessée ensemble.', '[{"text": "Dans l''Église copte, on dit « nous croyons ».", "translation": "Toute l''assemblée confesse la même foi."}, {"text": "En latin, on dit « je crois ».", "translation": "Le pluriel exprime la foi commune."}]'::jsonb, null, '{"id": "eg.d.nous_croyons", "word": "« nous croyons »", "translation": "le pluriel du Credo : la foi de toute l''Église", "partOfSpeech": "concept", "explanation": "Le texte des conciles et la prière copte disent « nous croyons ». La foi est reçue et confessée ensemble.", "examples": [{"text": "Dans l''Église copte, on dit « nous croyons ».", "translation": "Toute l''assemblée confesse la même foi."}, {"text": "En latin, on dit « je crois ».", "translation": "Le pluriel exprime la foi commune."}], "unitId": "eg.v.nous_croyons"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.article_de_foi', 'eg', 'un article de foi', 'une affirmation du Credo, une phrase de la foi', 'On découpe le Credo en articles : un article sur le Père, un sur le Fils, un sur l''Esprit, un sur l''Église.', '[{"text": "« Créateur du ciel et de la terre » est un article de foi.", "translation": "Il porte sur le Père."}, {"text": "Le Credo compte plusieurs articles.", "translation": "Chacun répond à une question de foi."}]'::jsonb, null, '{"id": "eg.d.article_de_foi", "word": "un article de foi", "translation": "une affirmation du Credo, une phrase de la foi", "partOfSpeech": "concept", "explanation": "On découpe le Credo en articles : un article sur le Père, un sur le Fils, un sur l''Esprit, un sur l''Église.", "examples": [{"text": "« Créateur du ciel et de la terre » est un article de foi.", "translation": "Il porte sur le Père."}, {"text": "Le Credo compte plusieurs articles.", "translation": "Chacun répond à une question de foi."}], "unitId": "eg.v.article_de_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.catechumene', 'eg', 'le catéchumène', 'celui qui apprend la foi avant d''être baptisé', 'Le catéchumène est instruit dans la foi avant son baptême et la confesse en répondant à des questions. De ces confessions sont nés les credos.', '[{"text": "Saint Cyrille de Jérusalem est le père des catéchumènes.", "translation": "Il leur expliquait la foi."}, {"text": "Le catéchumène confesse sa foi avant d''être baptisé.", "translation": "C''est l''origine des credos."}]'::jsonb, null, '{"id": "eg.d.catechumene", "word": "le catéchumène", "translation": "celui qui apprend la foi avant d''être baptisé", "partOfSpeech": "person", "explanation": "Le catéchumène est instruit dans la foi avant son baptême et la confesse en répondant à des questions. De ces confessions sont nés les credos.", "examples": [{"text": "Saint Cyrille de Jérusalem est le père des catéchumènes.", "translation": "Il leur expliquait la foi."}, {"text": "Le catéchumène confesse sa foi avant d''être baptisé.", "translation": "C''est l''origine des credos."}], "unitId": "eg.v.catechumene"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.symbole_des_apotres', 'eg', 'le symbole des apôtres', 'un credo court, bien connu en Occident', 'Le symbole des apôtres est un credo plus court que le nôtre, très répandu en Occident. L''Église copte récite le Credo de Nicée-Constantinople.', '[{"text": "En Occident, beaucoup connaissent le symbole des apôtres.", "translation": "C''est un autre credo."}, {"text": "Notre Credo est celui de Nicée-Constantinople.", "translation": "On ne le confond pas avec le symbole des apôtres."}]'::jsonb, null, '{"id": "eg.d.symbole_des_apotres", "word": "le symbole des apôtres", "translation": "un credo court, bien connu en Occident", "partOfSpeech": "work", "explanation": "Le symbole des apôtres est un credo plus court que le nôtre, très répandu en Occident. L''Église copte récite le Credo de Nicée-Constantinople.", "examples": [{"text": "En Occident, beaucoup connaissent le symbole des apôtres.", "translation": "C''est un autre credo."}, {"text": "Notre Credo est celui de Nicée-Constantinople.", "translation": "On ne le confond pas avec le symbole des apôtres."}], "unitId": "eg.v.symbole_des_apotres"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.introduction_du_credo', 'eg', 'l''introduction du Credo', '« Nous t''exaltons, Mère de la vraie lumière »', 'Avant le Credo, l''Église copte prie une introduction à Marie. La tradition l''attribue aux pères du concile d''Éphèse.', '[{"text": "« Nous t''exaltons, Mère de la vraie lumière » ouvre l''introduction.", "translation": "Elle honore Marie avant le Credo."}, {"text": "Elle rappelle le titre de Théotokos.", "translation": "Éphèse l''a proclamé en 431."}]'::jsonb, null, '{"id": "eg.d.introduction_du_credo", "word": "l''introduction du Credo", "translation": "« Nous t''exaltons, Mère de la vraie lumière »", "partOfSpeech": "work", "explanation": "Avant le Credo, l''Église copte prie une introduction à Marie. La tradition l''attribue aux pères du concile d''Éphèse.", "examples": [{"text": "« Nous t''exaltons, Mère de la vraie lumière » ouvre l''introduction.", "translation": "Elle honore Marie avant le Credo."}, {"text": "Elle rappelle le titre de Théotokos.", "translation": "Éphèse l''a proclamé en 431."}], "unitId": "eg.v.introduction_du_credo"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.mere_de_la_vraie_lumiere', 'eg', 'Mère de la vraie lumière', 'titre de Marie : elle a enfanté le Christ, Lumière du monde', 'Marie est appelée Mère de la vraie lumière parce qu''elle a enfanté le Christ, la Lumière venue du Père.', '[{"text": "Nous t''exaltons, Mère de la vraie lumière.", "translation": "C''est un titre de Marie."}, {"text": "Le Credo dira : « Lumière de Lumière ».", "translation": "Le thème de la lumière revient."}]'::jsonb, null, '{"id": "eg.d.mere_de_la_vraie_lumiere", "word": "Mère de la vraie lumière", "translation": "titre de Marie : elle a enfanté le Christ, Lumière du monde", "partOfSpeech": "concept", "explanation": "Marie est appelée Mère de la vraie lumière parce qu''elle a enfanté le Christ, la Lumière venue du Père.", "examples": [{"text": "Nous t''exaltons, Mère de la vraie lumière.", "translation": "C''est un titre de Marie."}, {"text": "Le Credo dira : « Lumière de Lumière ».", "translation": "Le thème de la lumière revient."}], "unitId": "eg.v.mere_de_la_vraie_lumiere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.en_verite_nous_croyons', 'eg', '« En vérité, nous croyons »', 'l''ouverture copte du Credo', 'Dans la liturgie copte, le Credo commence par « En vérité, nous croyons ». On affirme que ce que l''on dit est vrai.', '[{"text": "« En vérité, nous croyons en un seul Dieu. »", "translation": "C''est ainsi que commence la prière."}, {"text": "Ces mots affirment la certitude de la foi.", "translation": "Ce n''est pas une opinion."}]'::jsonb, null, '{"id": "eg.d.en_verite_nous_croyons", "word": "« En vérité, nous croyons »", "translation": "l''ouverture copte du Credo", "partOfSpeech": "concept", "explanation": "Dans la liturgie copte, le Credo commence par « En vérité, nous croyons ». On affirme que ce que l''on dit est vrai.", "examples": [{"text": "« En vérité, nous croyons en un seul Dieu. »", "translation": "C''est ainsi que commence la prière."}, {"text": "Ces mots affirment la certitude de la foi.", "translation": "Ce n''est pas une opinion."}], "unitId": "eg.v.en_verite_nous_croyons"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monotheisme', 'eg', 'le monothéisme', 'la foi en un seul Dieu', 'Le monothéisme est la foi en un seul Dieu. Le Credo l''affirme dès la première phrase.', '[{"text": "Le Credo commence par le monothéisme.", "translation": "« Un seul Dieu »."}, {"text": "Le paganisme croyait à plusieurs dieux.", "translation": "Le Credo les écarte."}]'::jsonb, null, '{"id": "eg.d.monotheisme", "word": "le monothéisme", "translation": "la foi en un seul Dieu", "partOfSpeech": "concept", "explanation": "Le monothéisme est la foi en un seul Dieu. Le Credo l''affirme dès la première phrase.", "examples": [{"text": "Le Credo commence par le monothéisme.", "translation": "« Un seul Dieu »."}, {"text": "Le paganisme croyait à plusieurs dieux.", "translation": "Le Credo les écarte."}], "unitId": "eg.v.monotheisme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dieu_le_pere', 'eg', 'Dieu le Père', 'la première personne de la Trinité, source du Fils et de l''Esprit', 'Dieu est Père d''abord parce qu''il a de toute éternité un Fils. Il est la source dans la Trinité.', '[{"text": "« Dieu le Père, Pantocrator ».", "translation": "Le Credo commence par la source."}, {"text": "Jésus appelle Dieu son Père.", "translation": "Nous le prions aussi comme Père."}]'::jsonb, null, '{"id": "eg.d.dieu_le_pere", "word": "Dieu le Père", "translation": "la première personne de la Trinité, source du Fils et de l''Esprit", "partOfSpeech": "concept", "explanation": "Dieu est Père d''abord parce qu''il a de toute éternité un Fils. Il est la source dans la Trinité.", "examples": [{"text": "« Dieu le Père, Pantocrator ».", "translation": "Le Credo commence par la source."}, {"text": "Jésus appelle Dieu son Père.", "translation": "Nous le prions aussi comme Père."}], "unitId": "eg.v.dieu_le_pere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pantocrator', 'eg', 'Pantocrator', 'mot grec : Tout-Puissant, celui qui tient tout', 'Pantocrator vient du grec pan (tout) et kratos (pouvoir). Il dit que Dieu tient toute chose dans l''être.', '[{"text": "Dieu le Père est Pantocrator.", "translation": "Rien ne lui échappe."}, {"text": "On traduit Pantocrator par Tout-Puissant.", "translation": "Aussi par « celui qui tient tout »."}]'::jsonb, null, '{"id": "eg.d.pantocrator", "word": "Pantocrator", "translation": "mot grec : Tout-Puissant, celui qui tient tout", "partOfSpeech": "concept", "explanation": "Pantocrator vient du grec pan (tout) et kratos (pouvoir). Il dit que Dieu tient toute chose dans l''être.", "examples": [{"text": "Dieu le Père est Pantocrator.", "translation": "Rien ne lui échappe."}, {"text": "On traduit Pantocrator par Tout-Puissant.", "translation": "Aussi par « celui qui tient tout »."}], "unitId": "eg.v.pantocrator"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.creation_a_partir_de_rien', 'eg', 'la création à partir de rien', 'Dieu crée le monde sans matière préexistante', 'Dieu a créé le monde par sa seule parole, sans rien d''avant. Le monde n''est ni éternel ni un morceau de Dieu.', '[{"text": "Dieu a créé le ciel et la terre à partir de rien.", "translation": "Il n''avait besoin d''aucune matière."}, {"text": "Le monde n''est pas Dieu.", "translation": "Il dépend de lui à chaque instant."}]'::jsonb, null, '{"id": "eg.d.creation_a_partir_de_rien", "word": "la création à partir de rien", "translation": "Dieu crée le monde sans matière préexistante", "partOfSpeech": "concept", "explanation": "Dieu a créé le monde par sa seule parole, sans rien d''avant. Le monde n''est ni éternel ni un morceau de Dieu.", "examples": [{"text": "Dieu a créé le ciel et la terre à partir de rien.", "translation": "Il n''avait besoin d''aucune matière."}, {"text": "Le monde n''est pas Dieu.", "translation": "Il dépend de lui à chaque instant."}], "unitId": "eg.v.creation_a_partir_de_rien"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.choses_visibles_et_invisibles', 'eg', 'les choses visibles et invisibles', 'tout ce que Dieu a créé : le monde matériel et le monde spirituel', 'Les choses visibles sont le monde matériel ; les invisibles sont les créatures spirituelles, les anges.', '[{"text": "Dieu a créé les choses visibles et invisibles.", "translation": "Le Credo le dit dans le premier article."}, {"text": "Les anges font partie des invisibles.", "translation": "Ce sont des créatures."}]'::jsonb, null, '{"id": "eg.d.choses_visibles_et_invisibles", "word": "les choses visibles et invisibles", "translation": "tout ce que Dieu a créé : le monde matériel et le monde spirituel", "partOfSpeech": "concept", "explanation": "Les choses visibles sont le monde matériel ; les invisibles sont les créatures spirituelles, les anges.", "examples": [{"text": "Dieu a créé les choses visibles et invisibles.", "translation": "Le Credo le dit dans le premier article."}, {"text": "Les anges font partie des invisibles.", "translation": "Ce sont des créatures."}], "unitId": "eg.v.choses_visibles_et_invisibles"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ange', 'eg', 'un ange', 'créature spirituelle qui sert Dieu', 'Un ange est une créature spirituelle créée par Dieu. Il adore Dieu et sert les hommes. On ne l''adore pas.', '[{"text": "Les anges sont créés par Dieu.", "translation": "Ils font partie des choses invisibles."}, {"text": "L''ange sert Dieu et prie pour nous.", "translation": "On adore Dieu seul."}]'::jsonb, null, '{"id": "eg.d.ange", "word": "un ange", "translation": "créature spirituelle qui sert Dieu", "partOfSpeech": "concept", "explanation": "Un ange est une créature spirituelle créée par Dieu. Il adore Dieu et sert les hommes. On ne l''adore pas.", "examples": [{"text": "Les anges sont créés par Dieu.", "translation": "Ils font partie des choses invisibles."}, {"text": "L''ange sert Dieu et prie pour nous.", "translation": "On adore Dieu seul."}], "unitId": "eg.v.ange"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.source_de_la_trinite', 'eg', 'le Père, source de la Trinité', 'le Père, d''où viennent le Fils (engendré) et l''Esprit (qui procède)', 'Dans la Trinité, le Fils est engendré du Père et l''Esprit procède du Père. Le Père est donc la source, sans être plus Dieu que les autres.', '[{"text": "Le Père est la source de la Trinité.", "translation": "Le Fils est engendré de lui."}, {"text": "L''Esprit procède du Père.", "translation": "C''est ce que dit le Credo."}]'::jsonb, null, '{"id": "eg.d.source_de_la_trinite", "word": "le Père, source de la Trinité", "translation": "le Père, d''où viennent le Fils (engendré) et l''Esprit (qui procède)", "partOfSpeech": "concept", "explanation": "Dans la Trinité, le Fils est engendré du Père et l''Esprit procède du Père. Le Père est donc la source, sans être plus Dieu que les autres.", "examples": [{"text": "Le Père est la source de la Trinité.", "translation": "Le Fils est engendré de lui."}, {"text": "L''Esprit procède du Père.", "translation": "C''est ce que dit le Credo."}], "unitId": "eg.v.source_de_la_trinite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.fils_unique', 'eg', 'le Fils unique', 'le seul qui soit Fils par nature', 'Le Christ est le Fils unique : le seul qui soit Fils de Dieu par nature. Nous sommes fils par grâce.', '[{"text": "« Le Fils unique de Dieu ».", "translation": "Titre du Christ dans le Credo."}, {"text": "Nous devenons fils par le baptême.", "translation": "Lui l''est par nature."}]'::jsonb, null, '{"id": "eg.d.fils_unique", "word": "le Fils unique", "translation": "le seul qui soit Fils par nature", "partOfSpeech": "concept", "explanation": "Le Christ est le Fils unique : le seul qui soit Fils de Dieu par nature. Nous sommes fils par grâce.", "examples": [{"text": "« Le Fils unique de Dieu ».", "translation": "Titre du Christ dans le Credo."}, {"text": "Nous devenons fils par le baptême.", "translation": "Lui l''est par nature."}], "unitId": "eg.v.fils_unique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.kyrios', 'eg', 'Seigneur (Kyrios)', 'mot grec : Seigneur, nom que la Bible grecque donne à Dieu', 'Kyrios veut dire « Seigneur ». La Bible grecque l''emploie pour Dieu. Confesser Jésus Seigneur, c''est confesser qu''il est Dieu.', '[{"text": "« Jésus est Seigneur » est une des plus anciennes confessions de foi.", "translation": "Elle affirme sa divinité."}, {"text": "Le Credo dit : un seul Seigneur Jésus-Christ.", "translation": "Seigneur = Dieu."}]'::jsonb, null, '{"id": "eg.d.kyrios", "word": "Seigneur (Kyrios)", "translation": "mot grec : Seigneur, nom que la Bible grecque donne à Dieu", "partOfSpeech": "concept", "explanation": "Kyrios veut dire « Seigneur ». La Bible grecque l''emploie pour Dieu. Confesser Jésus Seigneur, c''est confesser qu''il est Dieu.", "examples": [{"text": "« Jésus est Seigneur » est une des plus anciennes confessions de foi.", "translation": "Elle affirme sa divinité."}, {"text": "Le Credo dit : un seul Seigneur Jésus-Christ.", "translation": "Seigneur = Dieu."}], "unitId": "eg.v.kyrios"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.avant_tous_les_siecles', 'eg', 'avant tous les siècles', 'hors du temps, de toute éternité', 'Le Fils est engendré avant tous les siècles : il n''a pas de commencement. Le temps vient après lui.', '[{"text": "Le Fils est engendré avant tous les siècles.", "translation": "Il est éternel."}, {"text": "Arius disait : « il fut un temps où il n''était pas ».", "translation": "Le Credo le contredit."}]'::jsonb, null, '{"id": "eg.d.avant_tous_les_siecles", "word": "avant tous les siècles", "translation": "hors du temps, de toute éternité", "partOfSpeech": "concept", "explanation": "Le Fils est engendré avant tous les siècles : il n''a pas de commencement. Le temps vient après lui.", "examples": [{"text": "Le Fils est engendré avant tous les siècles.", "translation": "Il est éternel."}, {"text": "Arius disait : « il fut un temps où il n''était pas ».", "translation": "Le Credo le contredit."}], "unitId": "eg.v.avant_tous_les_siecles"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lumiere_de_lumiere', 'eg', 'Lumière de Lumière', 'le Fils vient du Père comme une lumière d''une lumière, sans division', 'Les Pères comparent le Père et le Fils à une flamme allumée à une autre flamme : même lumière, sans rien perdre.', '[{"text": "Lumière de Lumière.", "translation": "Le Fils vient du Père sans être séparé de lui."}, {"text": "Une flamme allume une autre flamme.", "translation": "Le feu est le même."}]'::jsonb, null, '{"id": "eg.d.lumiere_de_lumiere", "word": "Lumière de Lumière", "translation": "le Fils vient du Père comme une lumière d''une lumière, sans division", "partOfSpeech": "concept", "explanation": "Les Pères comparent le Père et le Fils à une flamme allumée à une autre flamme : même lumière, sans rien perdre.", "examples": [{"text": "Lumière de Lumière.", "translation": "Le Fils vient du Père sans être séparé de lui."}, {"text": "Une flamme allume une autre flamme.", "translation": "Le feu est le même."}], "unitId": "eg.v.lumiere_de_lumiere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.vrai_dieu_de_vrai_dieu', 'eg', 'vrai Dieu de vrai Dieu', 'le Fils est Dieu au même titre que le Père', 'Le Fils n''est pas Dieu par faveur ou à moitié : il est vrai Dieu, comme le Père.', '[{"text": "Vrai Dieu de vrai Dieu.", "translation": "Il est Dieu en vérité."}, {"text": "Il n''est pas un Dieu inférieur.", "translation": "Ce serait l''arianisme."}]'::jsonb, null, '{"id": "eg.d.vrai_dieu_de_vrai_dieu", "word": "vrai Dieu de vrai Dieu", "translation": "le Fils est Dieu au même titre que le Père", "partOfSpeech": "concept", "explanation": "Le Fils n''est pas Dieu par faveur ou à moitié : il est vrai Dieu, comme le Père.", "examples": [{"text": "Vrai Dieu de vrai Dieu.", "translation": "Il est Dieu en vérité."}, {"text": "Il n''est pas un Dieu inférieur.", "translation": "Ce serait l''arianisme."}], "unitId": "eg.v.vrai_dieu_de_vrai_dieu"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.engendre_non_cree', 'eg', 'engendré, non créé', 'le Fils est de la nature du Père ; il n''est pas une créature', 'Ce qui est engendré est de même nature que celui qui engendre. Ce qui est créé est une œuvre. Le Fils est engendré, non créé.', '[{"text": "Engendré, non créé.", "translation": "Le Fils n''est pas une créature."}, {"text": "Un homme engendre un homme.", "translation": "Un menuisier fait une table."}]'::jsonb, null, '{"id": "eg.d.engendre_non_cree", "word": "engendré, non créé", "translation": "le Fils est de la nature du Père ; il n''est pas une créature", "partOfSpeech": "concept", "explanation": "Ce qui est engendré est de même nature que celui qui engendre. Ce qui est créé est une œuvre. Le Fils est engendré, non créé.", "examples": [{"text": "Engendré, non créé.", "translation": "Le Fils n''est pas une créature."}, {"text": "Un homme engendre un homme.", "translation": "Un menuisier fait une table."}], "unitId": "eg.v.engendre_non_cree"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.par_qui_tout_a_ete_fait', 'eg', 'par qui tout a été fait', 'le Fils est le Créateur avec le Père', 'Tout a été fait par le Fils : il est donc Créateur, et non créature (Jean 1, 3).', '[{"text": "Par qui tout a été fait.", "translation": "Le Fils crée avec le Père."}, {"text": "Une créature ne peut pas tout créer.", "translation": "Le Fils est Dieu."}]'::jsonb, null, '{"id": "eg.d.par_qui_tout_a_ete_fait", "word": "par qui tout a été fait", "translation": "le Fils est le Créateur avec le Père", "partOfSpeech": "concept", "explanation": "Tout a été fait par le Fils : il est donc Créateur, et non créature (Jean 1, 3).", "examples": [{"text": "Par qui tout a été fait.", "translation": "Le Fils crée avec le Père."}, {"text": "Une créature ne peut pas tout créer.", "translation": "Le Fils est Dieu."}], "unitId": "eg.v.par_qui_tout_a_ete_fait"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pour_notre_salut', 'eg', 'pour notre salut', 'la raison de l''incarnation : sauver l''homme', 'Le Fils s''incarne pour nous et pour notre salut. Ce n''est ni par curiosité ni par devoir.', '[{"text": "« Pour nous les hommes et pour notre salut ».", "translation": "La raison de l''incarnation."}, {"text": "Dieu vient sauver l''homme.", "translation": "Seul Dieu peut le faire."}]'::jsonb, null, '{"id": "eg.d.pour_notre_salut", "word": "pour notre salut", "translation": "la raison de l''incarnation : sauver l''homme", "partOfSpeech": "concept", "explanation": "Le Fils s''incarne pour nous et pour notre salut. Ce n''est ni par curiosité ni par devoir.", "examples": [{"text": "« Pour nous les hommes et pour notre salut ».", "translation": "La raison de l''incarnation."}, {"text": "Dieu vient sauver l''homme.", "translation": "Seul Dieu peut le faire."}], "unitId": "eg.v.pour_notre_salut"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.descente_du_ciel', 'eg', '« il descendit du ciel »', 'le Fils prend notre condition sans cesser d''être Dieu', 'Descendre ne veut pas dire quitter le ciel comme un lieu : le Fils s''abaisse jusqu''à nous sans cesser d''être Dieu.', '[{"text": "« Il descendit du ciel ».", "translation": "Le Fils s''abaisse."}, {"text": "Il prend ce qu''il n''était pas.", "translation": "Il garde ce qu''il était."}]'::jsonb, null, '{"id": "eg.d.descente_du_ciel", "word": "« il descendit du ciel »", "translation": "le Fils prend notre condition sans cesser d''être Dieu", "partOfSpeech": "concept", "explanation": "Descendre ne veut pas dire quitter le ciel comme un lieu : le Fils s''abaisse jusqu''à nous sans cesser d''être Dieu.", "examples": [{"text": "« Il descendit du ciel ».", "translation": "Le Fils s''abaisse."}, {"text": "Il prend ce qu''il n''était pas.", "translation": "Il garde ce qu''il était."}], "unitId": "eg.v.descente_du_ciel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.vierge_marie', 'eg', 'la Vierge Marie', 'Marie, mère du Christ, Théotokos', 'Marie est la Vierge dont le Fils est né. Le Credo la nomme pour affirmer que l''incarnation est réelle.', '[{"text": "Il s''incarna de la Vierge Marie.", "translation": "Il naît vraiment d''une femme."}, {"text": "Marie est Théotokos.", "translation": "Celle qu''on honore dans l''introduction."}]'::jsonb, null, '{"id": "eg.d.vierge_marie", "word": "la Vierge Marie", "translation": "Marie, mère du Christ, Théotokos", "partOfSpeech": "person", "explanation": "Marie est la Vierge dont le Fils est né. Le Credo la nomme pour affirmer que l''incarnation est réelle.", "examples": [{"text": "Il s''incarna de la Vierge Marie.", "translation": "Il naît vraiment d''une femme."}, {"text": "Marie est Théotokos.", "translation": "Celle qu''on honore dans l''introduction."}], "unitId": "eg.v.vierge_marie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.conception_virginale', 'eg', 'la conception virginale', 'Jésus conçu par l''Esprit Saint, sans père humain', 'Jésus est conçu de l''Esprit Saint, sans père humain, par la Vierge Marie (Luc 1, 35).', '[{"text": "S''incarner de l''Esprit Saint et de la Vierge Marie.", "translation": "C''est la conception virginale."}, {"text": "Le Verbe prend sa chair de Marie.", "translation": "Il a vraiment une mère."}]'::jsonb, null, '{"id": "eg.d.conception_virginale", "word": "la conception virginale", "translation": "Jésus conçu par l''Esprit Saint, sans père humain", "partOfSpeech": "concept", "explanation": "Jésus est conçu de l''Esprit Saint, sans père humain, par la Vierge Marie (Luc 1, 35).", "examples": [{"text": "S''incarner de l''Esprit Saint et de la Vierge Marie.", "translation": "C''est la conception virginale."}, {"text": "Le Verbe prend sa chair de Marie.", "translation": "Il a vraiment une mère."}], "unitId": "eg.v.conception_virginale"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.un_seul_sujet', 'eg', 'un seul sujet', 'le même « Il » : le Verbe descend, naît, souffre', 'Dans le Credo, c''est toujours le Fils qui agit : il descend, s''incarne, souffre. Il n''y a pas deux personnes dans le Christ.', '[{"text": "Le Fils est l''unique sujet des verbes.", "translation": "Un seul « Il »."}, {"text": "Nestorius séparait deux sujets.", "translation": "Cyrille dit : le Verbe incarné."}]'::jsonb, null, '{"id": "eg.d.un_seul_sujet", "word": "un seul sujet", "translation": "le même « Il » : le Verbe descend, naît, souffre", "partOfSpeech": "concept", "explanation": "Dans le Credo, c''est toujours le Fils qui agit : il descend, s''incarne, souffre. Il n''y a pas deux personnes dans le Christ.", "examples": [{"text": "Le Fils est l''unique sujet des verbes.", "translation": "Un seul « Il »."}, {"text": "Nestorius séparait deux sujets.", "translation": "Cyrille dit : le Verbe incarné."}], "unitId": "eg.v.un_seul_sujet"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.divinisation', 'eg', 'la divinisation', 'l''homme participe à la vie divine par le Christ', 'Saint Athanase enseigne que Dieu s''est fait homme pour que l''homme participe à la vie divine, par grâce.', '[{"text": "Dieu s''est fait homme pour que nous devenions participants de sa vie.", "translation": "C''est la divinisation."}, {"text": "La divinisation est un don.", "translation": "Elle est reçue par la grâce."}]'::jsonb, null, '{"id": "eg.d.divinisation", "word": "la divinisation", "translation": "l''homme participe à la vie divine par le Christ", "partOfSpeech": "concept", "explanation": "Saint Athanase enseigne que Dieu s''est fait homme pour que l''homme participe à la vie divine, par grâce.", "examples": [{"text": "Dieu s''est fait homme pour que nous devenions participants de sa vie.", "translation": "C''est la divinisation."}, {"text": "La divinisation est un don.", "translation": "Elle est reçue par la grâce."}], "unitId": "eg.v.divinisation"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.crucifie_pour_nous', 'eg', 'crucifié pour nous', 'le Christ meurt sur la croix pour nous sauver', 'Le Credo dit « crucifié pour nous » : la croix n''est pas un accident, c''est un don pour le salut.', '[{"text": "Il fut crucifié pour nous sous Ponce Pilate.", "translation": "Pour nous sauver."}, {"text": "La croix est le sommet de l''amour.", "translation": "Il meurt librement."}]'::jsonb, null, '{"id": "eg.d.crucifie_pour_nous", "word": "crucifié pour nous", "translation": "le Christ meurt sur la croix pour nous sauver", "partOfSpeech": "concept", "explanation": "Le Credo dit « crucifié pour nous » : la croix n''est pas un accident, c''est un don pour le salut.", "examples": [{"text": "Il fut crucifié pour nous sous Ponce Pilate.", "translation": "Pour nous sauver."}, {"text": "La croix est le sommet de l''amour.", "translation": "Il meurt librement."}], "unitId": "eg.v.crucifie_pour_nous"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.troisieme_jour', 'eg', 'le troisième jour', 'le jour de la résurrection du Christ', 'Le Christ ressuscite le troisième jour après sa mort. C''est la date de Pâques.', '[{"text": "Il ressuscita le troisième jour.", "translation": "Le dimanche matin."}, {"text": "Jonas est resté trois jours dans le poisson.", "translation": "Image annoncée dans les Écritures."}]'::jsonb, null, '{"id": "eg.d.troisieme_jour", "word": "le troisième jour", "translation": "le jour de la résurrection du Christ", "partOfSpeech": "date", "explanation": "Le Christ ressuscite le troisième jour après sa mort. C''est la date de Pâques.", "examples": [{"text": "Il ressuscita le troisième jour.", "translation": "Le dimanche matin."}, {"text": "Jonas est resté trois jours dans le poisson.", "translation": "Image annoncée dans les Écritures."}], "unitId": "eg.v.troisieme_jour"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.selon_les_ecritures', 'eg', 'selon les Écritures', 'la résurrection a été annoncée par les prophètes', 'Les prophètes avaient annoncé la mort et la résurrection du Messie. Rien n''est un hasard.', '[{"text": "Il ressuscita selon les Écritures.", "translation": "C''était prévu par Dieu."}, {"text": "Le Credo cite l''Ancien Testament.", "translation": "Les prophètes avaient annoncé."}]'::jsonb, null, '{"id": "eg.d.selon_les_ecritures", "word": "selon les Écritures", "translation": "la résurrection a été annoncée par les prophètes", "partOfSpeech": "concept", "explanation": "Les prophètes avaient annoncé la mort et la résurrection du Messie. Rien n''est un hasard.", "examples": [{"text": "Il ressuscita selon les Écritures.", "translation": "C''était prévu par Dieu."}, {"text": "Le Credo cite l''Ancien Testament.", "translation": "Les prophètes avaient annoncé."}], "unitId": "eg.v.selon_les_ecritures"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.droite_du_pere', 'eg', 'la droite du Père', 'place d''honneur et de puissance du Christ', 'S''asseoir à la droite du Père veut dire recevoir l''honneur et la puissance. Ce n''est pas un lieu.', '[{"text": "Il s''assit à la droite du Père.", "translation": "Honneur et puissance."}, {"text": "L''humanité du Christ est glorifiée.", "translation": "Notre nature est avec Dieu."}]'::jsonb, null, '{"id": "eg.d.droite_du_pere", "word": "la droite du Père", "translation": "place d''honneur et de puissance du Christ", "partOfSpeech": "concept", "explanation": "S''asseoir à la droite du Père veut dire recevoir l''honneur et la puissance. Ce n''est pas un lieu.", "examples": [{"text": "Il s''assit à la droite du Père.", "translation": "Honneur et puissance."}, {"text": "L''humanité du Christ est glorifiée.", "translation": "Notre nature est avec Dieu."}], "unitId": "eg.v.droite_du_pere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.seconde_venue', 'eg', 'la seconde venue', 'le retour du Christ dans la gloire à la fin des temps', 'Le Christ reviendra à la fin des temps, dans la gloire, alors que la première fois il est venu dans l''humilité.', '[{"text": "Il reviendra dans la gloire.", "translation": "C''est la seconde venue."}, {"text": "Nul ne connaît le jour.", "translation": "Il faut veiller."}]'::jsonb, null, '{"id": "eg.d.seconde_venue", "word": "la seconde venue", "translation": "le retour du Christ dans la gloire à la fin des temps", "partOfSpeech": "event", "explanation": "Le Christ reviendra à la fin des temps, dans la gloire, alors que la première fois il est venu dans l''humilité.", "examples": [{"text": "Il reviendra dans la gloire.", "translation": "C''est la seconde venue."}, {"text": "Nul ne connaît le jour.", "translation": "Il faut veiller."}], "unitId": "eg.v.seconde_venue"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jugement_des_vivants_et_des_morts', 'eg', 'juger les vivants et les morts', 'le Christ jugera tous les hommes', 'À la fin, le Christ jugera tous les hommes, vivants et morts. Le jugement est aussi l''espérance de la justice.', '[{"text": "Il reviendra juger les vivants et les morts.", "translation": "Tous seront jugés."}, {"text": "Matthieu 25 décrit le jugement.", "translation": "Il est fondé sur l''amour."}]'::jsonb, null, '{"id": "eg.d.jugement_des_vivants_et_des_morts", "word": "juger les vivants et les morts", "translation": "le Christ jugera tous les hommes", "partOfSpeech": "concept", "explanation": "À la fin, le Christ jugera tous les hommes, vivants et morts. Le jugement est aussi l''espérance de la justice.", "examples": [{"text": "Il reviendra juger les vivants et les morts.", "translation": "Tous seront jugés."}, {"text": "Matthieu 25 décrit le jugement.", "translation": "Il est fondé sur l''amour."}], "unitId": "eg.v.jugement_des_vivants_et_des_morts"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.regne_sans_fin', 'eg', 'son règne n''aura pas de fin', 'le Christ est Roi pour toujours', 'Le règne du Christ ne finira pas. La phrase répond à ceux qui pensaient qu''il cesserait de régner un jour.', '[{"text": "Son règne n''aura pas de fin.", "translation": "Il est Roi pour toujours."}, {"text": "Le Fils reste Roi.", "translation": "Le règne est éternel."}]'::jsonb, null, '{"id": "eg.d.regne_sans_fin", "word": "son règne n''aura pas de fin", "translation": "le Christ est Roi pour toujours", "partOfSpeech": "concept", "explanation": "Le règne du Christ ne finira pas. La phrase répond à ceux qui pensaient qu''il cesserait de régner un jour.", "examples": [{"text": "Son règne n''aura pas de fin.", "translation": "Il est Roi pour toujours."}, {"text": "Le Fils reste Roi.", "translation": "Le règne est éternel."}], "unitId": "eg.v.regne_sans_fin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.resurrection_du_christ', 'eg', 'la résurrection du Christ', 'le Christ revient vivant de la mort, fondement de la foi', 'Le Christ est ressuscité : c''est le fondement de la foi chrétienne. Sans elle, dit Paul, la foi est vaine.', '[{"text": "Il ressuscita des morts.", "translation": "C''est la fête de Pâques."}, {"text": "Sans résurrection, la foi est vaine.", "translation": "1 Corinthiens 15."}]'::jsonb, null, '{"id": "eg.d.resurrection_du_christ", "word": "la résurrection du Christ", "translation": "le Christ revient vivant de la mort, fondement de la foi", "partOfSpeech": "event", "explanation": "Le Christ est ressuscité : c''est le fondement de la foi chrétienne. Sans elle, dit Paul, la foi est vaine.", "examples": [{"text": "Il ressuscita des morts.", "translation": "C''est la fête de Pâques."}, {"text": "Sans résurrection, la foi est vaine.", "translation": "1 Corinthiens 15."}], "unitId": "eg.v.resurrection_du_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.divinite_de_l_esprit', 'eg', 'la divinité de l''Esprit Saint', 'l''Esprit Saint est Dieu, comme le Père et le Fils', 'L''Esprit Saint n''est pas une créature ni une force : il est Dieu, une des trois personnes de la Trinité.', '[{"text": "Constantinople affirme la divinité de l''Esprit Saint.", "translation": "Contre Macédonius."}, {"text": "L''Esprit est adoré avec le Père et le Fils.", "translation": "Donc il est Dieu."}]'::jsonb, null, '{"id": "eg.d.divinite_de_l_esprit", "word": "la divinité de l''Esprit Saint", "translation": "l''Esprit Saint est Dieu, comme le Père et le Fils", "partOfSpeech": "concept", "explanation": "L''Esprit Saint n''est pas une créature ni une force : il est Dieu, une des trois personnes de la Trinité.", "examples": [{"text": "Constantinople affirme la divinité de l''Esprit Saint.", "translation": "Contre Macédonius."}, {"text": "L''Esprit est adoré avec le Père et le Fils.", "translation": "Donc il est Dieu."}], "unitId": "eg.v.divinite_de_l_esprit"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.vivificateur', 'eg', 'le vivificateur', 'celui qui donne la vie (l''Esprit Saint)', 'Vivificateur veut dire « qui donne la vie ». Seul Dieu donne la vie : l''Esprit est Dieu.', '[{"text": "L''Esprit est Seigneur et vivificateur.", "translation": "Il donne la vie."}, {"text": "Il donne la vie par le baptême.", "translation": "Il fait ressusciter."}]'::jsonb, null, '{"id": "eg.d.vivificateur", "word": "le vivificateur", "translation": "celui qui donne la vie (l''Esprit Saint)", "partOfSpeech": "concept", "explanation": "Vivificateur veut dire « qui donne la vie ». Seul Dieu donne la vie : l''Esprit est Dieu.", "examples": [{"text": "L''Esprit est Seigneur et vivificateur.", "translation": "Il donne la vie."}, {"text": "Il donne la vie par le baptême.", "translation": "Il fait ressusciter."}], "unitId": "eg.v.vivificateur"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.procession_du_pere', 'eg', 'qui procède du Père', 'l''Esprit vient éternellement du Père, seule source', 'Procéder est le mot propre pour l''Esprit, comme engendrer pour le Fils. Il dit que l''Esprit vient du Père (Jean 15, 26).', '[{"text": "L''Esprit procède du Père.", "translation": "Le Père est la source."}, {"text": "Le Fils est engendré, l''Esprit procède.", "translation": "On ne dit pas comment."}]'::jsonb, null, '{"id": "eg.d.procession_du_pere", "word": "qui procède du Père", "translation": "l''Esprit vient éternellement du Père, seule source", "partOfSpeech": "concept", "explanation": "Procéder est le mot propre pour l''Esprit, comme engendrer pour le Fils. Il dit que l''Esprit vient du Père (Jean 15, 26).", "examples": [{"text": "L''Esprit procède du Père.", "translation": "Le Père est la source."}, {"text": "Le Fils est engendré, l''Esprit procède.", "translation": "On ne dit pas comment."}], "unitId": "eg.v.procession_du_pere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.adore_avec_le_pere_et_le_fils', 'eg', 'adoré et glorifié avec le Père et le Fils', 'on adore l''Esprit comme les deux autres : il est Dieu', 'On n''adore que Dieu. Adorer l''Esprit avec le Père et le Fils prouve qu''il est Dieu au même rang.', '[{"text": "Il est adoré et glorifié avec le Père et le Fils.", "translation": "Même gloire."}, {"text": "Nous baptisons au nom des trois.", "translation": "Matthieu 28, 19."}]'::jsonb, null, '{"id": "eg.d.adore_avec_le_pere_et_le_fils", "word": "adoré et glorifié avec le Père et le Fils", "translation": "on adore l''Esprit comme les deux autres : il est Dieu", "partOfSpeech": "concept", "explanation": "On n''adore que Dieu. Adorer l''Esprit avec le Père et le Fils prouve qu''il est Dieu au même rang.", "examples": [{"text": "Il est adoré et glorifié avec le Père et le Fils.", "translation": "Même gloire."}, {"text": "Nous baptisons au nom des trois.", "translation": "Matthieu 28, 19."}], "unitId": "eg.v.adore_avec_le_pere_et_le_fils"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.a_parle_par_les_prophetes', 'eg', 'il a parlé par les prophètes', 'l''Esprit a inspiré les prophètes et l''Écriture', 'L''Esprit qui agit dans l''Église est celui qui a parlé par les prophètes. L''Ancien et le Nouveau Testament viennent du même Esprit.', '[{"text": "Il a parlé par les prophètes.", "translation": "L''Écriture est inspirée."}, {"text": "Marcion rejetait l''Ancien Testament.", "translation": "Le Credo le contredit."}]'::jsonb, null, '{"id": "eg.d.a_parle_par_les_prophetes", "word": "il a parlé par les prophètes", "translation": "l''Esprit a inspiré les prophètes et l''Écriture", "partOfSpeech": "concept", "explanation": "L''Esprit qui agit dans l''Église est celui qui a parlé par les prophètes. L''Ancien et le Nouveau Testament viennent du même Esprit.", "examples": [{"text": "Il a parlé par les prophètes.", "translation": "L''Écriture est inspirée."}, {"text": "Marcion rejetait l''Ancien Testament.", "translation": "Le Credo le contredit."}], "unitId": "eg.v.a_parle_par_les_prophetes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.inspiration', 'eg', 'l''inspiration des Écritures', 'l''Esprit Saint est l''auteur principal de la Bible', 'L''inspiration est l''action de l''Esprit sur les auteurs sacrés : ils écrivent ce que Dieu veut dire (2 Pierre 1, 21).', '[{"text": "L''Esprit inspire les prophètes.", "translation": "Ils parlent de la part de Dieu."}, {"text": "L''inspiration unit l''Ancien et le Nouveau Testament.", "translation": "Même Esprit."}]'::jsonb, null, '{"id": "eg.d.inspiration", "word": "l''inspiration des Écritures", "translation": "l''Esprit Saint est l''auteur principal de la Bible", "partOfSpeech": "concept", "explanation": "L''inspiration est l''action de l''Esprit sur les auteurs sacrés : ils écrivent ce que Dieu veut dire (2 Pierre 1, 21).", "examples": [{"text": "L''Esprit inspire les prophètes.", "translation": "Ils parlent de la part de Dieu."}, {"text": "L''inspiration unit l''Ancien et le Nouveau Testament.", "translation": "Même Esprit."}], "unitId": "eg.v.inspiration"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_une', 'eg', 'l''Église une', 'un seul Corps du Christ, une seule foi', 'L''Église est une : un seul Seigneur, une seule foi, un seul baptême (Éphésiens 4, 5).', '[{"text": "Nous croyons en une seule Église.", "translation": "Un seul Corps du Christ."}, {"text": "L''unité est celle de la foi.", "translation": "On prie pour l''unité des chrétiens."}]'::jsonb, null, '{"id": "eg.d.eglise_une", "word": "l''Église une", "translation": "un seul Corps du Christ, une seule foi", "partOfSpeech": "concept", "explanation": "L''Église est une : un seul Seigneur, une seule foi, un seul baptême (Éphésiens 4, 5).", "examples": [{"text": "Nous croyons en une seule Église.", "translation": "Un seul Corps du Christ."}, {"text": "L''unité est celle de la foi.", "translation": "On prie pour l''unité des chrétiens."}], "unitId": "eg.v.eglise_une"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eglise_sainte', 'eg', 'l''Église sainte', 'sanctifiée par le Christ et l''Esprit, malgré ses membres pécheurs', 'L''Église est sainte parce que le Christ et l''Esprit la sanctifient. Ses membres restent pécheurs et se repentent.', '[{"text": "L''Église est sainte.", "translation": "Elle est sanctifiée par le Christ."}, {"text": "Novatien voulait une Église de purs.", "translation": "L''Église reçoit les pénitents."}]'::jsonb, null, '{"id": "eg.d.eglise_sainte", "word": "l''Église sainte", "translation": "sanctifiée par le Christ et l''Esprit, malgré ses membres pécheurs", "partOfSpeech": "concept", "explanation": "L''Église est sainte parce que le Christ et l''Esprit la sanctifient. Ses membres restent pécheurs et se repentent.", "examples": [{"text": "L''Église est sainte.", "translation": "Elle est sanctifiée par le Christ."}, {"text": "Novatien voulait une Église de purs.", "translation": "L''Église reçoit les pénitents."}], "unitId": "eg.v.eglise_sainte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.apostolicite', 'eg', 'l''apostolicité', 'l''Église est fondée sur les apôtres et garde leur enseignement', 'Apostolique veut dire fondée sur l''enseignement des apôtres, gardé par la succession des évêques.', '[{"text": "L''Église d''Alexandrie est apostolique.", "translation": "Elle a été fondée par saint Marc."}, {"text": "La succession apostolique la garantit.", "translation": "Chaîne d''évêques."}]'::jsonb, null, '{"id": "eg.d.apostolicite", "word": "l''apostolicité", "translation": "l''Église est fondée sur les apôtres et garde leur enseignement", "partOfSpeech": "concept", "explanation": "Apostolique veut dire fondée sur l''enseignement des apôtres, gardé par la succession des évêques.", "examples": [{"text": "L''Église d''Alexandrie est apostolique.", "translation": "Elle a été fondée par saint Marc."}, {"text": "La succession apostolique la garantit.", "translation": "Chaîne d''évêques."}], "unitId": "eg.v.apostolicite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.un_seul_bapteme', 'eg', 'un seul baptême', 'le baptême ne se répète pas', 'Il n''y a qu''un seul baptême : il ne se répète pas, comme on ne naît qu''une fois.', '[{"text": "Nous confessons un seul baptême.", "translation": "On naît une fois."}, {"text": "Éphésiens 4, 5.", "translation": "Un seul Seigneur, une seule foi, un seul baptême."}]'::jsonb, null, '{"id": "eg.d.un_seul_bapteme", "word": "un seul baptême", "translation": "le baptême ne se répète pas", "partOfSpeech": "concept", "explanation": "Il n''y a qu''un seul baptême : il ne se répète pas, comme on ne naît qu''une fois.", "examples": [{"text": "Nous confessons un seul baptême.", "translation": "On naît une fois."}, {"text": "Éphésiens 4, 5.", "translation": "Un seul Seigneur, une seule foi, un seul baptême."}], "unitId": "eg.v.un_seul_bapteme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.remission_des_peches', 'eg', 'la rémission des péchés', 'le pardon des péchés', 'Rémission veut dire pardon. Le baptême efface le péché et donne une vie nouvelle.', '[{"text": "Un seul baptême pour la rémission des péchés.", "translation": "Il pardonne."}, {"text": "Rémission = pardon.", "translation": "Pardon reçu de Dieu."}]'::jsonb, null, '{"id": "eg.d.remission_des_peches", "word": "la rémission des péchés", "translation": "le pardon des péchés", "partOfSpeech": "concept", "explanation": "Rémission veut dire pardon. Le baptême efface le péché et donne une vie nouvelle.", "examples": [{"text": "Un seul baptême pour la rémission des péchés.", "translation": "Il pardonne."}, {"text": "Rémission = pardon.", "translation": "Pardon reçu de Dieu."}], "unitId": "eg.v.remission_des_peches"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.resurrection_des_morts', 'eg', 'la résurrection des morts', 'à la fin, tous ressusciteront avec leur corps', 'À la fin des temps, les morts ressusciteront, corps compris (1 Corinthiens 15). Le Christ est le premier.', '[{"text": "Nous attendons la résurrection des morts.", "translation": "L''homme tout entier."}, {"text": "Les gnostiques méprisaient le corps.", "translation": "L''Église dit : le corps ressuscite."}]'::jsonb, null, '{"id": "eg.d.resurrection_des_morts", "word": "la résurrection des morts", "translation": "à la fin, tous ressusciteront avec leur corps", "partOfSpeech": "concept", "explanation": "À la fin des temps, les morts ressusciteront, corps compris (1 Corinthiens 15). Le Christ est le premier.", "examples": [{"text": "Nous attendons la résurrection des morts.", "translation": "L''homme tout entier."}, {"text": "Les gnostiques méprisaient le corps.", "translation": "L''Église dit : le corps ressuscite."}], "unitId": "eg.v.resurrection_des_morts"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.siecle_a_venir', 'eg', 'la vie du siècle à venir', 'la vie éternelle dans le royaume de Dieu', 'Le siècle à venir est le monde nouveau, après le retour du Christ : la vie éternelle avec Dieu.', '[{"text": "Nous attendons la vie du siècle à venir.", "translation": "Nous l''espérons."}, {"text": "C''est le but de la foi.", "translation": "La joie avec Dieu."}]'::jsonb, null, '{"id": "eg.d.siecle_a_venir", "word": "la vie du siècle à venir", "translation": "la vie éternelle dans le royaume de Dieu", "partOfSpeech": "concept", "explanation": "Le siècle à venir est le monde nouveau, après le retour du Christ : la vie éternelle avec Dieu.", "examples": [{"text": "Nous attendons la vie du siècle à venir.", "translation": "Nous l''espérons."}, {"text": "C''est le but de la foi.", "translation": "La joie avec Dieu."}], "unitId": "eg.v.siecle_a_venir"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.amen', 'eg', 'Amen', 'mot hébreu : c''est vrai, ainsi soit-il', 'Amen veut dire « c''est vrai », « ainsi soit-il ». En le disant, tu signes le Credo.', '[{"text": "Le Credo se termine par Amen.", "translation": "Tu approuves tout."}, {"text": "Amen vient de l''hébreu.", "translation": "Il dit : je confirme."}]'::jsonb, null, '{"id": "eg.d.amen", "word": "Amen", "translation": "mot hébreu : c''est vrai, ainsi soit-il", "partOfSpeech": "concept", "explanation": "Amen veut dire « c''est vrai », « ainsi soit-il ». En le disant, tu signes le Credo.", "examples": [{"text": "Le Credo se termine par Amen.", "translation": "Tu approuves tout."}, {"text": "Amen vient de l''hébreu.", "translation": "Il dit : je confirme."}], "unitId": "eg.v.amen"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.confesser', 'eg', 'confesser la foi', 'proclamer publiquement sa foi', 'Confesser la foi, c''est la proclamer ouvertement. Le Credo est la confession de toute l''Église.', '[{"text": "En récitant le Credo, nous confessons la foi.", "translation": "Debout, ensemble."}, {"text": "Les martyrs ont confessé leur foi.", "translation": "Jusqu''à la mort."}]'::jsonb, null, '{"id": "eg.d.confesser", "word": "confesser la foi", "translation": "proclamer publiquement sa foi", "partOfSpeech": "concept", "explanation": "Confesser la foi, c''est la proclamer ouvertement. Le Credo est la confession de toute l''Église.", "examples": [{"text": "En récitant le Credo, nous confessons la foi.", "translation": "Debout, ensemble."}, {"text": "Les martyrs ont confessé leur foi.", "translation": "Jusqu''à la mort."}], "unitId": "eg.v.confesser"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.personne_divine', 'eg', 'une personne divine', 'le Père, le Fils ou l''Esprit Saint', 'Le Credo nomme trois personnes divines : le Père, le Fils et l''Esprit Saint, un seul Dieu.', '[{"text": "Le Père est une personne divine.", "translation": "Il n''est pas seul."}, {"text": "L''Esprit est une personne divine.", "translation": "Il n''est pas une force."}]'::jsonb, null, '{"id": "eg.d.personne_divine", "word": "une personne divine", "translation": "le Père, le Fils ou l''Esprit Saint", "partOfSpeech": "concept", "explanation": "Le Credo nomme trois personnes divines : le Père, le Fils et l''Esprit Saint, un seul Dieu.", "examples": [{"text": "Le Père est une personne divine.", "translation": "Il n''est pas seul."}, {"text": "L''Esprit est une personne divine.", "translation": "Il n''est pas une force."}], "unitId": "eg.v.personne_divine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trois_blocs_du_credo', 'eg', 'les trois blocs du Credo', 'le Père, le Fils, l''Esprit Saint (puis l''Église)', 'Pour retenir le Credo : un bloc pour le Père, un pour le Fils, un pour l''Esprit Saint, puis l''Église.', '[{"text": "Le bloc du Fils est le plus long.", "translation": "Il raconte l''histoire du salut."}, {"text": "Père, Fils, Esprit.", "translation": "Puis l''Église."}]'::jsonb, null, '{"id": "eg.d.trois_blocs_du_credo", "word": "les trois blocs du Credo", "translation": "le Père, le Fils, l''Esprit Saint (puis l''Église)", "partOfSpeech": "concept", "explanation": "Pour retenir le Credo : un bloc pour le Père, un pour le Fils, un pour l''Esprit Saint, puis l''Église.", "examples": [{"text": "Le bloc du Fils est le plus long.", "translation": "Il raconte l''histoire du salut."}, {"text": "Père, Fils, Esprit.", "translation": "Puis l''Église."}], "unitId": "eg.v.trois_blocs_du_credo"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chaine_des_verbes', 'eg', 'la chaîne des verbes', 'descendit, s''incarna, crucifié, ressuscita, monta, s''assit, reviendra', 'Pour retenir le bloc du Fils, suis ses verbes : descendit, s''incarna, se fit homme, crucifié, ressuscita, monta, s''assit, reviendra.', '[{"text": "Les verbes racontent l''histoire du salut.", "translation": "Dans l''ordre."}, {"text": "Un verbe, une étape.", "translation": "Huit verbes."}]'::jsonb, null, '{"id": "eg.d.chaine_des_verbes", "word": "la chaîne des verbes", "translation": "descendit, s''incarna, crucifié, ressuscita, monta, s''assit, reviendra", "partOfSpeech": "concept", "explanation": "Pour retenir le bloc du Fils, suis ses verbes : descendit, s''incarna, se fit homme, crucifié, ressuscita, monta, s''assit, reviendra.", "examples": [{"text": "Les verbes racontent l''histoire du salut.", "translation": "Dans l''ordre."}, {"text": "Un verbe, une étape.", "translation": "Huit verbes."}], "unitId": "eg.v.chaine_des_verbes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacrement', 'eg', 'le sacrement (le mystère)', 'signe visible par lequel Dieu donne une grâce invisible', 'Dans l''Église copte, on dit aussi « mystère ». Il y en a sept, et chacun a été institué par le Christ ou donné par ses apôtres.', '[{"text": "Le baptême est le premier sacrement.", "translation": "Il ouvre la porte de l''Église."}, {"text": "Le sacrement est un mystère : on ne le voit pas en entier.", "translation": "On voit le signe, Dieu donne la grâce."}]'::jsonb, null, '{"id": "eg.d.sacrement", "word": "le sacrement (le mystère)", "translation": "signe visible par lequel Dieu donne une grâce invisible", "partOfSpeech": "concept", "explanation": "Dans l''Église copte, on dit aussi « mystère ». Il y en a sept, et chacun a été institué par le Christ ou donné par ses apôtres.", "examples": [{"text": "Le baptême est le premier sacrement.", "translation": "Il ouvre la porte de l''Église."}, {"text": "Le sacrement est un mystère : on ne le voit pas en entier.", "translation": "On voit le signe, Dieu donne la grâce."}], "unitId": "eg.v.sacrement"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.grace', 'eg', 'la grâce', 'don gratuit de Dieu : son aide, son pardon, sa vie', 'La grâce ne se gagne pas : elle est donnée. Les sacrements sont les moyens par lesquels l''Église la reçoit.', '[{"text": "Dieu donne sa grâce par le sacrement.", "translation": "Nous la recevons sans l''avoir méritée."}, {"text": "La grâce du baptême est la nouvelle naissance.", "translation": "Elle est donnée une fois pour toutes."}]'::jsonb, null, '{"id": "eg.d.grace", "word": "la grâce", "translation": "don gratuit de Dieu : son aide, son pardon, sa vie", "partOfSpeech": "concept", "explanation": "La grâce ne se gagne pas : elle est donnée. Les sacrements sont les moyens par lesquels l''Église la reçoit.", "examples": [{"text": "Dieu donne sa grâce par le sacrement.", "translation": "Nous la recevons sans l''avoir méritée."}, {"text": "La grâce du baptême est la nouvelle naissance.", "translation": "Elle est donnée une fois pour toutes."}], "unitId": "eg.v.grace"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.signe_visible', 'eg', 'le signe visible', 'la matière et le geste du sacrement : eau, huile, pain, mains', 'Le signe est ce qu''on voit et touche dans le sacrement. Il montre la grâce qui est donnée.', '[{"text": "L''eau est le signe visible du baptême.", "translation": "On la voit, on la touche."}, {"text": "L''huile est le signe visible de l''onction des malades.", "translation": "Elle dit la guérison que Dieu donne."}]'::jsonb, null, '{"id": "eg.d.signe_visible", "word": "le signe visible", "translation": "la matière et le geste du sacrement : eau, huile, pain, mains", "partOfSpeech": "concept", "explanation": "Le signe est ce qu''on voit et touche dans le sacrement. Il montre la grâce qui est donnée.", "examples": [{"text": "L''eau est le signe visible du baptême.", "translation": "On la voit, on la touche."}, {"text": "L''huile est le signe visible de l''onction des malades.", "translation": "Elle dit la guérison que Dieu donne."}], "unitId": "eg.v.signe_visible"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.institution_par_le_christ', 'eg', 'l''institution par le Christ', 'le Christ a lui-même donné le sacrement, ou les apôtres l''ont reçu de lui', 'Aucun sacrement n''a été inventé plus tard : chacun repose sur un geste, une parole du Christ ou la pratique des apôtres.', '[{"text": "Le Christ institue l''eucharistie à la dernière Cène.", "translation": "Il prend le pain et la coupe."}, {"text": "Les apôtres imposent les mains à ceux qui sont baptisés.", "translation": "Ce geste est la source du saint myron."}]'::jsonb, null, '{"id": "eg.d.institution_par_le_christ", "word": "l''institution par le Christ", "translation": "le Christ a lui-même donné le sacrement, ou les apôtres l''ont reçu de lui", "partOfSpeech": "concept", "explanation": "Aucun sacrement n''a été inventé plus tard : chacun repose sur un geste, une parole du Christ ou la pratique des apôtres.", "examples": [{"text": "Le Christ institue l''eucharistie à la dernière Cène.", "translation": "Il prend le pain et la coupe."}, {"text": "Les apôtres imposent les mains à ceux qui sont baptisés.", "translation": "Ce geste est la source du saint myron."}], "unitId": "eg.v.institution_par_le_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ministre_du_sacrement', 'eg', 'le ministre du sacrement', 'celui qui le célèbre : le prêtre ou l''évêque', 'Le ministre agit au nom du Christ et de l''Église, comme un serviteur. La grâce vient de Dieu, pas de lui.', '[{"text": "Le prêtre est le ministre du baptême.", "translation": "Il baptise au nom de la Trinité."}, {"text": "L''évêque est le ministre du sacerdoce.", "translation": "Il ordonne par l''imposition des mains."}]'::jsonb, null, '{"id": "eg.d.ministre_du_sacrement", "word": "le ministre du sacrement", "translation": "celui qui le célèbre : le prêtre ou l''évêque", "partOfSpeech": "person", "explanation": "Le ministre agit au nom du Christ et de l''Église, comme un serviteur. La grâce vient de Dieu, pas de lui.", "examples": [{"text": "Le prêtre est le ministre du baptême.", "translation": "Il baptise au nom de la Trinité."}, {"text": "L''évêque est le ministre du sacerdoce.", "translation": "Il ordonne par l''imposition des mains."}], "unitId": "eg.v.ministre_du_sacrement"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacrements_uniques', 'eg', 'les sacrements qui ne se répètent pas', 'baptême, confirmation (saint myron), sacerdoce : reçus une seule fois', 'Ces trois sacrements impriment une marque qui ne s''efface pas, donc on ne les recommence pas.', '[{"text": "Le baptême est reçu une seule fois.", "translation": "On ne peut pas naître deux fois."}, {"text": "Le saint myron est un sceau unique.", "translation": "Il n''est jamais renouvelé pour la même personne."}]'::jsonb, null, '{"id": "eg.d.sacrements_uniques", "word": "les sacrements qui ne se répètent pas", "translation": "baptême, confirmation (saint myron), sacerdoce : reçus une seule fois", "partOfSpeech": "concept", "explanation": "Ces trois sacrements impriment une marque qui ne s''efface pas, donc on ne les recommence pas.", "examples": [{"text": "Le baptême est reçu une seule fois.", "translation": "On ne peut pas naître deux fois."}, {"text": "Le saint myron est un sceau unique.", "translation": "Il n''est jamais renouvelé pour la même personne."}], "unitId": "eg.v.sacrements_uniques"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacrements_repetables', 'eg', 'les sacrements qui se répètent', 'eucharistie, confession, onction des malades', 'On a besoin de nourriture, de pardon et de guérison tout au long de la vie : ces sacrements reviennent. Le mariage est à part.', '[{"text": "On communie souvent à l''eucharistie.", "translation": "C''est une nourriture pour la vie."}, {"text": "On se confesse régulièrement.", "translation": "Le pardon est renouvelé chaque fois."}]'::jsonb, null, '{"id": "eg.d.sacrements_repetables", "word": "les sacrements qui se répètent", "translation": "eucharistie, confession, onction des malades", "partOfSpeech": "concept", "explanation": "On a besoin de nourriture, de pardon et de guérison tout au long de la vie : ces sacrements reviennent. Le mariage est à part.", "examples": [{"text": "On communie souvent à l''eucharistie.", "translation": "C''est une nourriture pour la vie."}, {"text": "On se confesse régulièrement.", "translation": "Le pardon est renouvelé chaque fois."}], "unitId": "eg.v.sacrements_repetables"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.bapteme', 'eg', 'le baptême', 'premier sacrement : naître d''eau et d''Esprit par la triple immersion', 'Le baptême est la porte de l''Église. Il donne le pardon des péchés et une nouvelle naissance.', '[{"text": "Le baptême se célèbre à l''église.", "translation": "Le prêtre bénit d''abord l''eau."}, {"text": "Le baptême ne se répète jamais.", "translation": "On ne naît qu''une fois."}]'::jsonb, null, '{"id": "eg.d.bapteme", "word": "le baptême", "translation": "premier sacrement : naître d''eau et d''Esprit par la triple immersion", "partOfSpeech": "concept", "explanation": "Le baptême est la porte de l''Église. Il donne le pardon des péchés et une nouvelle naissance.", "examples": [{"text": "Le baptême se célèbre à l''église.", "translation": "Le prêtre bénit d''abord l''eau."}, {"text": "Le baptême ne se répète jamais.", "translation": "On ne naît qu''une fois."}], "unitId": "eg.v.bapteme"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.triple_immersion', 'eg', 'la triple immersion', 'le baptisé est plongé trois fois dans l''eau, au nom de la Trinité', 'Chaque immersion correspond à une Personne de la Trinité et rappelle l''un des trois jours du Christ au tombeau.', '[{"text": "Le prêtre plonge l''enfant trois fois.", "translation": "Il dit le nom de chaque Personne."}, {"text": "La triple immersion rappelle les trois jours au tombeau.", "translation": "On remonte comme le Christ ressuscite."}]'::jsonb, null, '{"id": "eg.d.triple_immersion", "word": "la triple immersion", "translation": "le baptisé est plongé trois fois dans l''eau, au nom de la Trinité", "partOfSpeech": "concept", "explanation": "Chaque immersion correspond à une Personne de la Trinité et rappelle l''un des trois jours du Christ au tombeau.", "examples": [{"text": "Le prêtre plonge l''enfant trois fois.", "translation": "Il dit le nom de chaque Personne."}, {"text": "La triple immersion rappelle les trois jours au tombeau.", "translation": "On remonte comme le Christ ressuscite."}], "unitId": "eg.v.triple_immersion"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.renoncement_a_satan', 'eg', 'le renoncement à Satan', 'promesse de rejeter Satan, faite tourné vers l''ouest', 'Avant d''entrer dans l''eau, le baptisé rejette le mal. Il le fait tourné vers l''ouest, le côté des ténèbres.', '[{"text": "Le parrain renonce à Satan pour l''enfant.", "translation": "Il se tourne vers l''ouest."}, {"text": "Ce renoncement précède la plongée.", "translation": "On rejette avant d''accueillir."}]'::jsonb, null, '{"id": "eg.d.renoncement_a_satan", "word": "le renoncement à Satan", "translation": "promesse de rejeter Satan, faite tourné vers l''ouest", "partOfSpeech": "concept", "explanation": "Avant d''entrer dans l''eau, le baptisé rejette le mal. Il le fait tourné vers l''ouest, le côté des ténèbres.", "examples": [{"text": "Le parrain renonce à Satan pour l''enfant.", "translation": "Il se tourne vers l''ouest."}, {"text": "Ce renoncement précède la plongée.", "translation": "On rejette avant d''accueillir."}], "unitId": "eg.v.renoncement_a_satan"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.profession_de_foi', 'eg', 'la profession de foi', 'confession du Christ et du Credo, faite tourné vers l''est', 'Après avoir renoncé à Satan, le baptisé confesse le Christ. Il le fait tourné vers l''est, là où se lève le soleil.', '[{"text": "Le parrain dit le Credo pour l''enfant.", "translation": "Il se tourne vers l''est."}, {"text": "La profession de foi suit le renoncement.", "translation": "On rejette le mal, puis on choisit le Christ."}]'::jsonb, null, '{"id": "eg.d.profession_de_foi", "word": "la profession de foi", "translation": "confession du Christ et du Credo, faite tourné vers l''est", "partOfSpeech": "concept", "explanation": "Après avoir renoncé à Satan, le baptisé confesse le Christ. Il le fait tourné vers l''est, là où se lève le soleil.", "examples": [{"text": "Le parrain dit le Credo pour l''enfant.", "translation": "Il se tourne vers l''est."}, {"text": "La profession de foi suit le renoncement.", "translation": "On rejette le mal, puis on choisit le Christ."}], "unitId": "eg.v.profession_de_foi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.parrain', 'eg', 'le parrain', 'celui qui répond pour l''enfant et s''engage à l''élever dans la foi', 'Le parrain est un orthodoxe pratiquant. Il tient l''enfant au baptême et l''accompagne ensuite dans la foi.', '[{"text": "Le parrain tient l''enfant dans ses bras.", "translation": "Il répond aux questions du prêtre."}, {"text": "Le parrain aide l''enfant à grandir dans la foi.", "translation": "C''est une vraie responsabilité."}]'::jsonb, null, '{"id": "eg.d.parrain", "word": "le parrain", "translation": "celui qui répond pour l''enfant et s''engage à l''élever dans la foi", "partOfSpeech": "person", "explanation": "Le parrain est un orthodoxe pratiquant. Il tient l''enfant au baptême et l''accompagne ensuite dans la foi.", "examples": [{"text": "Le parrain tient l''enfant dans ses bras.", "translation": "Il répond aux questions du prêtre."}, {"text": "Le parrain aide l''enfant à grandir dans la foi.", "translation": "C''est une vraie responsabilité."}], "unitId": "eg.v.parrain"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.quarante_quatre_vingts_jours', 'eg', 'le 40e et le 80e jour', 'usage : le garçon est baptisé vers le 40e jour, la fille vers le 80e', 'Cet usage vient du Lévitique 12. Si l''enfant est en danger, on ne l''attend pas.', '[{"text": "Le garçon est baptisé vers le 40e jour.", "translation": "C''est l''usage dans l''Église copte."}, {"text": "La fille est baptisée vers le 80e jour.", "translation": "La règle vient du Lévitique 12."}]'::jsonb, null, '{"id": "eg.d.quarante_quatre_vingts_jours", "word": "le 40e et le 80e jour", "translation": "usage : le garçon est baptisé vers le 40e jour, la fille vers le 80e", "partOfSpeech": "date", "explanation": "Cet usage vient du Lévitique 12. Si l''enfant est en danger, on ne l''attend pas.", "examples": [{"text": "Le garçon est baptisé vers le 40e jour.", "translation": "C''est l''usage dans l''Église copte."}, {"text": "La fille est baptisée vers le 80e jour.", "translation": "La règle vient du Lévitique 12."}], "unitId": "eg.v.quarante_quatre_vingts_jours"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nouvelle_naissance', 'eg', 'la nouvelle naissance', 'naître d''eau et d''Esprit (Jn 3, 5), don du baptême', 'Jésus dit à Nicodème qu''il faut naître d''en haut. Le baptême est cette seconde naissance.', '[{"text": "Le baptême est une nouvelle naissance.", "translation": "On y naît d''eau et d''Esprit."}, {"text": "La nouvelle naissance ouvre le royaume de Dieu.", "translation": "C''est la parole de Jésus en Jn 3, 5."}]'::jsonb, null, '{"id": "eg.d.nouvelle_naissance", "word": "la nouvelle naissance", "translation": "naître d''eau et d''Esprit (Jn 3, 5), don du baptême", "partOfSpeech": "concept", "explanation": "Jésus dit à Nicodème qu''il faut naître d''en haut. Le baptême est cette seconde naissance.", "examples": [{"text": "Le baptême est une nouvelle naissance.", "translation": "On y naît d''eau et d''Esprit."}, {"text": "La nouvelle naissance ouvre le royaume de Dieu.", "translation": "C''est la parole de Jésus en Jn 3, 5."}], "unitId": "eg.v.nouvelle_naissance"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.bapteme_des_enfants', 'eg', 'le baptême des enfants', 'l''Église baptise les bébés, avec la foi des parents et du parrain', 'Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés. L''enfant est élevé dans la foi.', '[{"text": "L''Église baptise les bébés.", "translation": "Leurs parents croient pour eux."}, {"text": "Les maisons entières sont baptisées dans les Actes.", "translation": "Cela inclut les enfants."}]'::jsonb, null, '{"id": "eg.d.bapteme_des_enfants", "word": "le baptême des enfants", "translation": "l''Église baptise les bébés, avec la foi des parents et du parrain", "partOfSpeech": "concept", "explanation": "Le baptême prend la place de la circoncision, que l''on faisait aux nouveau-nés. L''enfant est élevé dans la foi.", "examples": [{"text": "L''Église baptise les bébés.", "translation": "Leurs parents croient pour eux."}, {"text": "Les maisons entières sont baptisées dans les Actes.", "translation": "Cela inclut les enfants."}], "unitId": "eg.v.bapteme_des_enfants"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.confirmation', 'eg', 'la confirmation (la chrismation)', 'sacrement du sceau du Saint-Esprit, donné par le saint myron après le baptême', 'Elle suit le baptême immédiatement. Chez les Coptes, c''est le prêtre qui la donne, même aux bébés.', '[{"text": "La confirmation suit le baptême.", "translation": "On reçoit le sceau de l''Esprit."}, {"text": "La confirmation ne se répète pas.", "translation": "C''est un sceau unique."}]'::jsonb, null, '{"id": "eg.d.confirmation", "word": "la confirmation (la chrismation)", "translation": "sacrement du sceau du Saint-Esprit, donné par le saint myron après le baptême", "partOfSpeech": "concept", "explanation": "Elle suit le baptême immédiatement. Chez les Coptes, c''est le prêtre qui la donne, même aux bébés.", "examples": [{"text": "La confirmation suit le baptême.", "translation": "On reçoit le sceau de l''Esprit."}, {"text": "La confirmation ne se répète pas.", "translation": "C''est un sceau unique."}], "unitId": "eg.v.confirmation"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_myron', 'eg', 'le saint myron', 'huile parfumée consacrée par le patriarche pour la confirmation', 'Le mot « myron » est grec et veut dire parfum. Il sert à la confirmation et à bénir l''eau du baptême.', '[{"text": "Le prêtre oint le baptisé avec le saint myron.", "translation": "Il trace une croix à chaque onction."}, {"text": "Le saint myron est préparé par le patriarche.", "translation": "On y ajoute un peu de l''ancien myron."}]'::jsonb, null, '{"id": "eg.d.saint_myron", "word": "le saint myron", "translation": "huile parfumée consacrée par le patriarche pour la confirmation", "partOfSpeech": "concept", "explanation": "Le mot « myron » est grec et veut dire parfum. Il sert à la confirmation et à bénir l''eau du baptême.", "examples": [{"text": "Le prêtre oint le baptisé avec le saint myron.", "translation": "Il trace une croix à chaque onction."}, {"text": "Le saint myron est préparé par le patriarche.", "translation": "On y ajoute un peu de l''ancien myron."}], "unitId": "eg.v.saint_myron"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trente_six_onctions', 'eg', 'les 36 onctions', '36 signes de croix de myron sur les sens et les articulations', 'Le prêtre oint la tête, les sens, la poitrine, le dos et les articulations : tout le corps est consacré.', '[{"text": "Le prêtre fait 36 onctions.", "translation": "Chacune est un signe de croix."}, {"text": "Les 36 onctions consacrent tout le corps.", "translation": "Le baptisé devient temple de l''Esprit."}]'::jsonb, null, '{"id": "eg.d.trente_six_onctions", "word": "les 36 onctions", "translation": "36 signes de croix de myron sur les sens et les articulations", "partOfSpeech": "concept", "explanation": "Le prêtre oint la tête, les sens, la poitrine, le dos et les articulations : tout le corps est consacré.", "examples": [{"text": "Le prêtre fait 36 onctions.", "translation": "Chacune est un signe de croix."}, {"text": "Les 36 onctions consacrent tout le corps.", "translation": "Le baptisé devient temple de l''Esprit."}], "unitId": "eg.v.trente_six_onctions"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sceau_du_saint_esprit', 'eg', 'le sceau du Saint-Esprit', 'marque spirituelle donnée par le myron : l''Esprit habite le baptisé', 'Saint Paul dit que Dieu nous a marqués de son sceau (2 Co 1, 22). Ce sceau ne s''efface pas.', '[{"text": "La confirmation donne le sceau du Saint-Esprit.", "translation": "Il ne se répète pas."}, {"text": "Le sceau marque le corps et l''âme.", "translation": "Le baptisé appartient au Christ."}]'::jsonb, null, '{"id": "eg.d.sceau_du_saint_esprit", "word": "le sceau du Saint-Esprit", "translation": "marque spirituelle donnée par le myron : l''Esprit habite le baptisé", "partOfSpeech": "concept", "explanation": "Saint Paul dit que Dieu nous a marqués de son sceau (2 Co 1, 22). Ce sceau ne s''efface pas.", "examples": [{"text": "La confirmation donne le sceau du Saint-Esprit.", "translation": "Il ne se répète pas."}, {"text": "Le sceau marque le corps et l''âme.", "translation": "Le baptisé appartient au Christ."}], "unitId": "eg.v.sceau_du_saint_esprit"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.preparation_du_myron', 'eg', 'la préparation du myron', 'le patriarche et les évêques préparent et consacrent le saint myron', 'Elle a lieu au monastère Saint-Bishoy du Ouadi Natroun, pendant le Carême, mais pas à date fixe.', '[{"text": "Le pape préside la préparation du myron.", "translation": "Les évêques l''entourent."}, {"text": "On ajoute de l''ancien myron au nouveau.", "translation": "C''est un signe de continuité."}]'::jsonb, null, '{"id": "eg.d.preparation_du_myron", "word": "la préparation du myron", "translation": "le patriarche et les évêques préparent et consacrent le saint myron", "partOfSpeech": "event", "explanation": "Elle a lieu au monastère Saint-Bishoy du Ouadi Natroun, pendant le Carême, mais pas à date fixe.", "examples": [{"text": "Le pape préside la préparation du myron.", "translation": "Les évêques l''entourent."}, {"text": "On ajoute de l''ancien myron au nouveau.", "translation": "C''est un signe de continuité."}], "unitId": "eg.v.preparation_du_myron"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.imposition_des_mains', 'eg', 'l''imposition des mains', 'geste par lequel les apôtres donnaient l''Esprit, puis les évêques ordonnent', 'Les apôtres imposent les mains aux baptisés (Ac 8, 14-17). Le même geste sert à ordonner les clercs.', '[{"text": "Pierre et Jean imposent les mains.", "translation": "Les Samaritains reçoivent l''Esprit."}, {"text": "L''évêque impose les mains au candidat.", "translation": "Il l''ordonne prêtre."}]'::jsonb, null, '{"id": "eg.d.imposition_des_mains", "word": "l''imposition des mains", "translation": "geste par lequel les apôtres donnaient l''Esprit, puis les évêques ordonnent", "partOfSpeech": "concept", "explanation": "Les apôtres imposent les mains aux baptisés (Ac 8, 14-17). Le même geste sert à ordonner les clercs.", "examples": [{"text": "Pierre et Jean imposent les mains.", "translation": "Les Samaritains reçoivent l''Esprit."}, {"text": "L''évêque impose les mains au candidat.", "translation": "Il l''ordonne prêtre."}], "unitId": "eg.v.imposition_des_mains"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.habit_blanc', 'eg', 'l''habit blanc', 'vêtement blanc du nouveau baptisé : l''homme nouveau', 'Le blanc dit la pureté et la vie nouvelle. Le prêtre le marque de la croix.', '[{"text": "Le baptisé reçoit un habit blanc.", "translation": "Il a revêtu l''homme nouveau."}, {"text": "Le blanc dit la pureté.", "translation": "C''est la couleur de la vie nouvelle."}]'::jsonb, null, '{"id": "eg.d.habit_blanc", "word": "l''habit blanc", "translation": "vêtement blanc du nouveau baptisé : l''homme nouveau", "partOfSpeech": "concept", "explanation": "Le blanc dit la pureté et la vie nouvelle. Le prêtre le marque de la croix.", "examples": [{"text": "Le baptisé reçoit un habit blanc.", "translation": "Il a revêtu l''homme nouveau."}, {"text": "Le blanc dit la pureté.", "translation": "C''est la couleur de la vie nouvelle."}], "unitId": "eg.v.habit_blanc"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.zounnar', 'eg', 'le zounnar', 'ceinture ou ruban noué à la taille du nouveau baptisé, selon l''usage', 'Il dit l''appartenance au Christ. Il est dénoué le huitième jour, autrefois à la maison, aujourd''hui souvent à l''église.', '[{"text": "On noue le zounnar autour de la taille.", "translation": "L''enfant appartient au Christ."}, {"text": "On dénoue le zounnar le huitième jour.", "translation": "C''est l''usage."}]'::jsonb, null, '{"id": "eg.d.zounnar", "word": "le zounnar", "translation": "ceinture ou ruban noué à la taille du nouveau baptisé, selon l''usage", "partOfSpeech": "concept", "explanation": "Il dit l''appartenance au Christ. Il est dénoué le huitième jour, autrefois à la maison, aujourd''hui souvent à l''église.", "examples": [{"text": "On noue le zounnar autour de la taille.", "translation": "L''enfant appartient au Christ."}, {"text": "On dénoue le zounnar le huitième jour.", "translation": "C''est l''usage."}], "unitId": "eg.v.zounnar"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eucharistie', 'eg', 'l''eucharistie', 'sacrement du Corps et du Sang du Christ ; mot grec pour « action de grâce »', 'L''eucharistie est célébrée à la messe. Elle se répète : on peut communier souvent.', '[{"text": "L''eucharistie est le centre de la messe.", "translation": "On y remercie Dieu."}, {"text": "L''eucharistie se répète.", "translation": "On peut communier souvent."}]'::jsonb, null, '{"id": "eg.d.eucharistie", "word": "l''eucharistie", "translation": "sacrement du Corps et du Sang du Christ ; mot grec pour « action de grâce »", "partOfSpeech": "concept", "explanation": "L''eucharistie est célébrée à la messe. Elle se répète : on peut communier souvent.", "examples": [{"text": "L''eucharistie est le centre de la messe.", "translation": "On y remercie Dieu."}, {"text": "L''eucharistie se répète.", "translation": "On peut communier souvent."}], "unitId": "eg.v.eucharistie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.derniere_cene', 'eg', 'la dernière Cène', 'repas du Jeudi saint où Jésus institue l''eucharistie', 'C''est le dernier repas de Jésus avec ses apôtres, avant sa Passion. Il y prend le pain et la coupe.', '[{"text": "Jésus institue l''eucharistie à la dernière Cène.", "translation": "C''est le soir du Jeudi saint."}, {"text": "À la dernière Cène, il dit : « Faites ceci en mémoire de moi ».", "translation": "L''Église le répète à chaque messe."}]'::jsonb, null, '{"id": "eg.d.derniere_cene", "word": "la dernière Cène", "translation": "repas du Jeudi saint où Jésus institue l''eucharistie", "partOfSpeech": "event", "explanation": "C''est le dernier repas de Jésus avec ses apôtres, avant sa Passion. Il y prend le pain et la coupe.", "examples": [{"text": "Jésus institue l''eucharistie à la dernière Cène.", "translation": "C''est le soir du Jeudi saint."}, {"text": "À la dernière Cène, il dit : « Faites ceci en mémoire de moi ».", "translation": "L''Église le répète à chaque messe."}], "unitId": "eg.v.derniere_cene"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.presence_reelle', 'eg', 'la présence réelle', 'le pain et le vin deviennent vraiment le Corps et le Sang du Christ', 'Nous croyons que le Christ est réellement présent. Beaucoup de protestants parlent plutôt de mémorial.', '[{"text": "Les Coptes croient à la présence réelle.", "translation": "Ce n''est pas un simple souvenir."}, {"text": "Les catholiques croient aussi à la présence réelle.", "translation": "La plupart des protestants non."}]'::jsonb, null, '{"id": "eg.d.presence_reelle", "word": "la présence réelle", "translation": "le pain et le vin deviennent vraiment le Corps et le Sang du Christ", "partOfSpeech": "concept", "explanation": "Nous croyons que le Christ est réellement présent. Beaucoup de protestants parlent plutôt de mémorial.", "examples": [{"text": "Les Coptes croient à la présence réelle.", "translation": "Ce n''est pas un simple souvenir."}, {"text": "Les catholiques croient aussi à la présence réelle.", "translation": "La plupart des protestants non."}], "unitId": "eg.v.presence_reelle"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.communion', 'eg', 'la communion', 'le moment où le fidèle reçoit le Corps et le Sang du Christ', 'Communier, c''est entrer en union avec le Christ et avec toute l''Église.', '[{"text": "On communie après s''être confessé.", "translation": "On est à jeun."}, {"text": "La communion fait l''unité de l''Église.", "translation": "Un seul pain, un seul corps."}]'::jsonb, null, '{"id": "eg.d.communion", "word": "la communion", "translation": "le moment où le fidèle reçoit le Corps et le Sang du Christ", "partOfSpeech": "concept", "explanation": "Communier, c''est entrer en union avec le Christ et avec toute l''Église.", "examples": [{"text": "On communie après s''être confessé.", "translation": "On est à jeun."}, {"text": "La communion fait l''unité de l''Église.", "translation": "Un seul pain, un seul corps."}], "unitId": "eg.v.communion"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.qorban', 'eg', 'le qorban', 'pain levé de la messe, marqué d''une croix ; veut dire « offrande »', 'Le qorban est préparé spécialement par l''Église. Le levain évoque la vie et la Résurrection.', '[{"text": "Le qorban est un pain levé.", "translation": "Il est marqué d''une croix."}, {"text": "Le qorban est offert à la messe.", "translation": "Il devient le Corps du Christ."}]'::jsonb, null, '{"id": "eg.d.qorban", "word": "le qorban", "translation": "pain levé de la messe, marqué d''une croix ; veut dire « offrande »", "partOfSpeech": "concept", "explanation": "Le qorban est préparé spécialement par l''Église. Le levain évoque la vie et la Résurrection.", "examples": [{"text": "Le qorban est un pain levé.", "translation": "Il est marqué d''une croix."}, {"text": "Le qorban est offert à la messe.", "translation": "Il devient le Corps du Christ."}], "unitId": "eg.v.qorban"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jeune_eucharistique', 'eg', 'le jeûne eucharistique', 'ni nourriture ni boisson avant la communion', 'Il dure au moins neuf heures pour un adulte, selon l''usage. Le prêtre adapte pour les enfants et les malades.', '[{"text": "Le jeûne eucharistique précède la communion.", "translation": "Le Christ est la première nourriture."}, {"text": "Il est adapté pour les enfants.", "translation": "Le prêtre décide."}]'::jsonb, null, '{"id": "eg.d.jeune_eucharistique", "word": "le jeûne eucharistique", "translation": "ni nourriture ni boisson avant la communion", "partOfSpeech": "concept", "explanation": "Il dure au moins neuf heures pour un adulte, selon l''usage. Le prêtre adapte pour les enfants et les malades.", "examples": [{"text": "Le jeûne eucharistique précède la communion.", "translation": "Le Christ est la première nourriture."}, {"text": "Il est adapté pour les enfants.", "translation": "Le prêtre décide."}], "unitId": "eg.v.jeune_eucharistique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pain_de_vie', 'eg', 'le pain de vie', 'titre que Jésus se donne en Jean 6 : il nourrit pour la vie éternelle', 'Jésus dit : « Moi, je suis le pain de vie » (Jn 6, 35). L''eucharistie le rend présent.', '[{"text": "Jésus est le pain de vie.", "translation": "Il nourrit pour l''éternité."}, {"text": "Jean 6 parle du pain de vie.", "translation": "Qui mange ma chair a la vie éternelle."}]'::jsonb, null, '{"id": "eg.d.pain_de_vie", "word": "le pain de vie", "translation": "titre que Jésus se donne en Jean 6 : il nourrit pour la vie éternelle", "partOfSpeech": "concept", "explanation": "Jésus dit : « Moi, je suis le pain de vie » (Jn 6, 35). L''eucharistie le rend présent.", "examples": [{"text": "Jésus est le pain de vie.", "translation": "Il nourrit pour l''éternité."}, {"text": "Jean 6 parle du pain de vie.", "translation": "Qui mange ma chair a la vie éternelle."}], "unitId": "eg.v.pain_de_vie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.confession', 'eg', 'la confession (la pénitence)', 'sacrement du pardon des péchés commis après le baptême', 'On dit ses péchés à un prêtre, qui prie l''absolution. Elle se répète au fil de la vie.', '[{"text": "La confession pardonne les péchés.", "translation": "Elle se répète."}, {"text": "On se confesse avant de communier.", "translation": "C''est une préparation."}]'::jsonb, null, '{"id": "eg.d.confession", "word": "la confession (la pénitence)", "translation": "sacrement du pardon des péchés commis après le baptême", "partOfSpeech": "concept", "explanation": "On dit ses péchés à un prêtre, qui prie l''absolution. Elle se répète au fil de la vie.", "examples": [{"text": "La confession pardonne les péchés.", "translation": "Elle se répète."}, {"text": "On se confesse avant de communier.", "translation": "C''est une préparation."}], "unitId": "eg.v.confession"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pere_de_confession', 'eg', 'le père de confession', 'prêtre qui reçoit nos confessions et nous guide dans la durée', 'On garde le même père de confession : il connaît notre vie et nous guide. Il est tenu au secret.', '[{"text": "Mon père de confession me conseille.", "translation": "Il me connaît bien."}, {"text": "On ne change pas de père de confession sans raison.", "translation": "Il suit notre chemin."}]'::jsonb, null, '{"id": "eg.d.pere_de_confession", "word": "le père de confession", "translation": "prêtre qui reçoit nos confessions et nous guide dans la durée", "partOfSpeech": "person", "explanation": "On garde le même père de confession : il connaît notre vie et nous guide. Il est tenu au secret.", "examples": [{"text": "Mon père de confession me conseille.", "translation": "Il me connaît bien."}, {"text": "On ne change pas de père de confession sans raison.", "translation": "Il suit notre chemin."}], "unitId": "eg.v.pere_de_confession"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.absolution', 'eg', 'l''absolution', 'prière par laquelle le prêtre, avec la croix sur la tête, donne le pardon de Dieu', 'Le prêtre prie, mais c''est Dieu qui pardonne. L''absolution est le cœur du sacrement.', '[{"text": "Le prêtre prie l''absolution.", "translation": "Il pose la croix sur la tête."}, {"text": "L''absolution donne le pardon.", "translation": "Elle précède la communion."}]'::jsonb, null, '{"id": "eg.d.absolution", "word": "l''absolution", "translation": "prière par laquelle le prêtre, avec la croix sur la tête, donne le pardon de Dieu", "partOfSpeech": "concept", "explanation": "Le prêtre prie, mais c''est Dieu qui pardonne. L''absolution est le cœur du sacrement.", "examples": [{"text": "Le prêtre prie l''absolution.", "translation": "Il pose la croix sur la tête."}, {"text": "L''absolution donne le pardon.", "translation": "Elle précède la communion."}], "unitId": "eg.v.absolution"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.repentance', 'eg', 'la repentance', 'changement du cœur : regret sincère et décision de changer', 'La repentance ne se réduit pas à des paroles. Elle suppose un regret, une décision, la confession et la confiance en Dieu.', '[{"text": "Sa repentance est sincère.", "translation": "Il veut changer."}, {"text": "Le fils prodigue se repent.", "translation": "Il revient vers son père."}]'::jsonb, null, '{"id": "eg.d.repentance", "word": "la repentance", "translation": "changement du cœur : regret sincère et décision de changer", "partOfSpeech": "concept", "explanation": "La repentance ne se réduit pas à des paroles. Elle suppose un regret, une décision, la confession et la confiance en Dieu.", "examples": [{"text": "Sa repentance est sincère.", "translation": "Il veut changer."}, {"text": "Le fils prodigue se repent.", "translation": "Il revient vers son père."}], "unitId": "eg.v.repentance"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lier_et_delier', 'eg', 'lier et délier', 'retenir ou remettre les péchés (Mt 18, 18 ; Jn 20, 23)', 'Jésus donne aux apôtres le pouvoir de lier et de délier. C''est la source de la confession.', '[{"text": "Jésus donne le pouvoir de lier et de délier.", "translation": "C''est Mt 18, 18."}, {"text": "Lier et délier suppose de connaître les péchés.", "translation": "On les dit au prêtre."}]'::jsonb, null, '{"id": "eg.d.lier_et_delier", "word": "lier et délier", "translation": "retenir ou remettre les péchés (Mt 18, 18 ; Jn 20, 23)", "partOfSpeech": "expression", "explanation": "Jésus donne aux apôtres le pouvoir de lier et de délier. C''est la source de la confession.", "examples": [{"text": "Jésus donne le pouvoir de lier et de délier.", "translation": "C''est Mt 18, 18."}, {"text": "Lier et délier suppose de connaître les péchés.", "translation": "On les dit au prêtre."}], "unitId": "eg.v.lier_et_delier"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.secret_de_la_confession', 'eg', 'le secret de la confession', 'le prêtre ne révèle jamais ce qu''il entend en confession', 'Ce secret est absolu et l''Église punit le prêtre qui le trahirait. Il permet de se confier sans crainte.', '[{"text": "Le prêtre garde le secret de la confession.", "translation": "Il ne le répète à personne."}, {"text": "Ce secret protège le pénitent.", "translation": "Il donne confiance."}]'::jsonb, null, '{"id": "eg.d.secret_de_la_confession", "word": "le secret de la confession", "translation": "le prêtre ne révèle jamais ce qu''il entend en confession", "partOfSpeech": "concept", "explanation": "Ce secret est absolu et l''Église punit le prêtre qui le trahirait. Il permet de se confier sans crainte.", "examples": [{"text": "Le prêtre garde le secret de la confession.", "translation": "Il ne le répète à personne."}, {"text": "Ce secret protège le pénitent.", "translation": "Il donne confiance."}], "unitId": "eg.v.secret_de_la_confession"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.contrition', 'eg', 'la contrition', 'regret sincère de ses péchés, premier pas de la repentance', 'Le mot veut dire « cœur brisé ». Sans regret sincère, la confession n''est qu''un récit.', '[{"text": "Sa contrition est sincère.", "translation": "Il regrette ses fautes."}, {"text": "La contrition précède la confession.", "translation": "Elle ouvre à la repentance."}]'::jsonb, null, '{"id": "eg.d.contrition", "word": "la contrition", "translation": "regret sincère de ses péchés, premier pas de la repentance", "partOfSpeech": "concept", "explanation": "Le mot veut dire « cœur brisé ». Sans regret sincère, la confession n''est qu''un récit.", "examples": [{"text": "Sa contrition est sincère.", "translation": "Il regrette ses fautes."}, {"text": "La contrition précède la confession.", "translation": "Elle ouvre à la repentance."}], "unitId": "eg.v.contrition"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.onction_des_malades', 'eg', 'l''onction des malades', 'sacrement de l''huile : prière pour la guérison de l''âme et du corps du malade', 'Elle repose sur Jc 5, 14-15. Un prêtre prie et oint le malade d''huile.', '[{"text": "Le prêtre célèbre l''onction des malades.", "translation": "Il oint le front, la poitrine et les mains."}, {"text": "L''onction des malades se répète.", "translation": "À chaque maladie."}]'::jsonb, null, '{"id": "eg.d.onction_des_malades", "word": "l''onction des malades", "translation": "sacrement de l''huile : prière pour la guérison de l''âme et du corps du malade", "partOfSpeech": "concept", "explanation": "Elle repose sur Jc 5, 14-15. Un prêtre prie et oint le malade d''huile.", "examples": [{"text": "Le prêtre célèbre l''onction des malades.", "translation": "Il oint le front, la poitrine et les mains."}, {"text": "L''onction des malades se répète.", "translation": "À chaque maladie."}], "unitId": "eg.v.onction_des_malades"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.qandil', 'eg', 'le qandil', 'nom arabe de l''onction des malades : « la lampe »', 'Le mot vient des sept mèches allumées pendant les sept prières.', '[{"text": "On célèbre le qandil pour le malade.", "translation": "Sept mèches sont allumées."}, {"text": "Le qandil est la lampe des malades.", "translation": "Il prie pour l''âme et le corps."}]'::jsonb, null, '{"id": "eg.d.qandil", "word": "le qandil", "translation": "nom arabe de l''onction des malades : « la lampe »", "partOfSpeech": "concept", "explanation": "Le mot vient des sept mèches allumées pendant les sept prières.", "examples": [{"text": "On célèbre le qandil pour le malade.", "translation": "Sept mèches sont allumées."}, {"text": "Le qandil est la lampe des malades.", "translation": "Il prie pour l''âme et le corps."}], "unitId": "eg.v.qandil"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sept_meches', 'eg', 'les sept mèches', 'sept mèches de coton allumées l''une après l''autre pendant les sept prières', 'Avant chaque prière, on allume une mèche. Sept est le nombre de la plénitude dans la Bible.', '[{"text": "On allume une mèche avant chaque prière.", "translation": "Il y en a sept."}, {"text": "Les sept mèches baignent dans l''huile.", "translation": "Elles donnent son nom au qandil."}]'::jsonb, null, '{"id": "eg.d.sept_meches", "word": "les sept mèches", "translation": "sept mèches de coton allumées l''une après l''autre pendant les sept prières", "partOfSpeech": "concept", "explanation": "Avant chaque prière, on allume une mèche. Sept est le nombre de la plénitude dans la Bible.", "examples": [{"text": "On allume une mèche avant chaque prière.", "translation": "Il y en a sept."}, {"text": "Les sept mèches baignent dans l''huile.", "translation": "Elles donnent son nom au qandil."}], "unitId": "eg.v.sept_meches"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.huile_benie', 'eg', 'l''huile bénie', 'huile pure, de préférence d''olive, dont le prêtre oint le malade', 'L''huile est le signe visible du sacrement. Le prêtre en trace une croix sur le front, la poitrine et les mains.', '[{"text": "Le prêtre oint le malade d''huile bénie.", "translation": "Il trace une croix."}, {"text": "L''huile bénie est le signe visible du qandil.", "translation": "Elle dit la guérison."}]'::jsonb, null, '{"id": "eg.d.huile_benie", "word": "l''huile bénie", "translation": "huile pure, de préférence d''olive, dont le prêtre oint le malade", "partOfSpeech": "concept", "explanation": "L''huile est le signe visible du sacrement. Le prêtre en trace une croix sur le front, la poitrine et les mains.", "examples": [{"text": "Le prêtre oint le malade d''huile bénie.", "translation": "Il trace une croix."}, {"text": "L''huile bénie est le signe visible du qandil.", "translation": "Elle dit la guérison."}], "unitId": "eg.v.huile_benie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.qandil_general', 'eg', 'le qandil général', 'qandil célébré une fois par an pour tous les fidèles, avant la semaine de la Passion', 'Selon l''usage, il a lieu le vendredi qui précède la semaine de la Passion.', '[{"text": "Le qandil général a lieu une fois par an.", "translation": "On y est oint même en bonne santé."}, {"text": "Le qandil général prépare à la semaine sainte.", "translation": "C''est un vendredi de Carême."}]'::jsonb, null, '{"id": "eg.d.qandil_general", "word": "le qandil général", "translation": "qandil célébré une fois par an pour tous les fidèles, avant la semaine de la Passion", "partOfSpeech": "event", "explanation": "Selon l''usage, il a lieu le vendredi qui précède la semaine de la Passion.", "examples": [{"text": "Le qandil général a lieu une fois par an.", "translation": "On y est oint même en bonne santé."}, {"text": "Le qandil général prépare à la semaine sainte.", "translation": "C''est un vendredi de Carême."}], "unitId": "eg.v.qandil_general"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.guerison_de_l_ame_et_du_corps', 'eg', 'la guérison de l''âme et du corps', 'pardon des péchés et soulagement du malade, selon la volonté de Dieu', 'L''âme et le corps sont liés. Le corps n''est pas toujours guéri : Dieu agit comme il veut.', '[{"text": "Le qandil vise la guérison de l''âme et du corps.", "translation": "Jacques parle des deux."}, {"text": "Le malade se confesse avant le qandil.", "translation": "Il communie ensuite."}]'::jsonb, null, '{"id": "eg.d.guerison_de_l_ame_et_du_corps", "word": "la guérison de l''âme et du corps", "translation": "pardon des péchés et soulagement du malade, selon la volonté de Dieu", "partOfSpeech": "concept", "explanation": "L''âme et le corps sont liés. Le corps n''est pas toujours guéri : Dieu agit comme il veut.", "examples": [{"text": "Le qandil vise la guérison de l''âme et du corps.", "translation": "Jacques parle des deux."}, {"text": "Le malade se confesse avant le qandil.", "translation": "Il communie ensuite."}], "unitId": "eg.v.guerison_de_l_ame_et_du_corps"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.anciens_de_l_eglise', 'eg', 'les anciens de l''Église', 'en grec presbyteroi : les prêtres', 'Jacques demande au malade d''appeler les anciens de l''Église. Le mot a donné « prêtre ».', '[{"text": "Le malade appelle les anciens de l''Église.", "translation": "Ce sont des prêtres."}, {"text": "Les anciens prient et oignent d''huile.", "translation": "Au nom du Seigneur."}]'::jsonb, null, '{"id": "eg.d.anciens_de_l_eglise", "word": "les anciens de l''Église", "translation": "en grec presbyteroi : les prêtres", "partOfSpeech": "person", "explanation": "Jacques demande au malade d''appeler les anciens de l''Église. Le mot a donné « prêtre ».", "examples": [{"text": "Le malade appelle les anciens de l''Église.", "translation": "Ce sont des prêtres."}, {"text": "Les anciens prient et oignent d''huile.", "translation": "Au nom du Seigneur."}], "unitId": "eg.v.anciens_de_l_eglise"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.mariage', 'eg', 'le mariage (le couronnement)', 'sacrement où Dieu unit un homme et une femme, avec le rite des couronnes', 'Le mariage est un sacrement, célébré à l''église par un prêtre. On l''appelle aussi le couronnement.', '[{"text": "Le mariage est un sacrement.", "translation": "Dieu unit les époux."}, {"text": "Le mariage se célèbre à l''église.", "translation": "Un prêtre le préside."}]'::jsonb, null, '{"id": "eg.d.mariage", "word": "le mariage (le couronnement)", "translation": "sacrement où Dieu unit un homme et une femme, avec le rite des couronnes", "partOfSpeech": "concept", "explanation": "Le mariage est un sacrement, célébré à l''église par un prêtre. On l''appelle aussi le couronnement.", "examples": [{"text": "Le mariage est un sacrement.", "translation": "Dieu unit les époux."}, {"text": "Le mariage se célèbre à l''église.", "translation": "Un prêtre le préside."}], "unitId": "eg.v.mariage"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.couronnement', 'eg', 'le couronnement', 'rite où le prêtre place des couronnes sur la tête des époux', 'Les couronnes disent que les époux sont roi et reine de leur nouveau foyer. Le rite donne son nom au mariage.', '[{"text": "Le prêtre couronne les époux.", "translation": "Les couronnes sont bénies."}, {"text": "Le couronnement est le cœur du mariage.", "translation": "On l''appelle aussi le sacrement des couronnes."}]'::jsonb, null, '{"id": "eg.d.couronnement", "word": "le couronnement", "translation": "rite où le prêtre place des couronnes sur la tête des époux", "partOfSpeech": "concept", "explanation": "Les couronnes disent que les époux sont roi et reine de leur nouveau foyer. Le rite donne son nom au mariage.", "examples": [{"text": "Le prêtre couronne les époux.", "translation": "Les couronnes sont bénies."}, {"text": "Le couronnement est le cœur du mariage.", "translation": "On l''appelle aussi le sacrement des couronnes."}], "unitId": "eg.v.couronnement"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.indissolubilite', 'eg', 'l''indissolubilité', 'le mariage ne se défait pas : Dieu a uni les époux', 'Mt 19, 6 : « Que l''homme ne le sépare pas ». L''Église n''admet la rupture que dans des cas très graves, d''abord l''adultère.', '[{"text": "Le mariage est indissoluble.", "translation": "Dieu a uni les époux."}, {"text": "L''indissolubilité vient de Mt 19, 6.", "translation": "Ce n''est pas un contrat ordinaire."}]'::jsonb, null, '{"id": "eg.d.indissolubilite", "word": "l''indissolubilité", "translation": "le mariage ne se défait pas : Dieu a uni les époux", "partOfSpeech": "concept", "explanation": "Mt 19, 6 : « Que l''homme ne le sépare pas ». L''Église n''admet la rupture que dans des cas très graves, d''abord l''adultère.", "examples": [{"text": "Le mariage est indissoluble.", "translation": "Dieu a uni les époux."}, {"text": "L''indissolubilité vient de Mt 19, 6.", "translation": "Ce n''est pas un contrat ordinaire."}], "unitId": "eg.v.indissolubilite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.fiancailles', 'eg', 'les fiançailles', 'engagement qui précède le mariage, mais qui n''est pas un sacrement', 'Les fiançailles se font devant le prêtre, avec échange de bagues, avant le mariage.', '[{"text": "Les fiançailles précèdent le mariage.", "translation": "Ce n''est pas un sacrement."}, {"text": "On échange les bagues aux fiançailles.", "translation": "Devant le prêtre."}]'::jsonb, null, '{"id": "eg.d.fiancailles", "word": "les fiançailles", "translation": "engagement qui précède le mariage, mais qui n''est pas un sacrement", "partOfSpeech": "concept", "explanation": "Les fiançailles se font devant le prêtre, avec échange de bagues, avant le mariage.", "examples": [{"text": "Les fiançailles précèdent le mariage.", "translation": "Ce n''est pas un sacrement."}, {"text": "On échange les bagues aux fiançailles.", "translation": "Devant le prêtre."}], "unitId": "eg.v.fiancailles"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.grand_mystere', 'eg', 'le grand mystère', 'parole de saint Paul sur le mariage : « Ce mystère est grand » (Ép 5, 32)', 'Paul compare l''union de l''époux et de l''épouse à celle du Christ et de l''Église.', '[{"text": "Paul parle d''un grand mystère.", "translation": "C''est Éphésiens 5, 32."}, {"text": "Le grand mystère fonde le sacrement du mariage.", "translation": "L''amour des époux est une image."}]'::jsonb, null, '{"id": "eg.d.grand_mystere", "word": "le grand mystère", "translation": "parole de saint Paul sur le mariage : « Ce mystère est grand » (Ép 5, 32)", "partOfSpeech": "concept", "explanation": "Paul compare l''union de l''époux et de l''épouse à celle du Christ et de l''Église.", "examples": [{"text": "Paul parle d''un grand mystère.", "translation": "C''est Éphésiens 5, 32."}, {"text": "Le grand mystère fonde le sacrement du mariage.", "translation": "L''amour des époux est une image."}], "unitId": "eg.v.grand_mystere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.noces_de_cana', 'eg', 'les noces de Cana', 'mariage où Jésus change l''eau en vin (Jn 2)', 'Jésus y assiste et bénit les noces : le mariage est béni par le Christ dès le début de son ministère.', '[{"text": "Jésus assiste aux noces de Cana.", "translation": "Il change l''eau en vin."}, {"text": "Les noces de Cana bénissent le mariage.", "translation": "C''est Jn 2."}]'::jsonb, null, '{"id": "eg.d.noces_de_cana", "word": "les noces de Cana", "translation": "mariage où Jésus change l''eau en vin (Jn 2)", "partOfSpeech": "event", "explanation": "Jésus y assiste et bénit les noces : le mariage est béni par le Christ dès le début de son ministère.", "examples": [{"text": "Jésus assiste aux noces de Cana.", "translation": "Il change l''eau en vin."}, {"text": "Les noces de Cana bénissent le mariage.", "translation": "C''est Jn 2."}], "unitId": "eg.v.noces_de_cana"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacerdoce', 'eg', 'le sacerdoce (l''ordination)', 'sacrement où l''évêque, par l''imposition des mains, ordonne diacres, prêtres et évêques', 'Le sacerdoce est le septième sacrement. Il ne se répète pas pour un même degré.', '[{"text": "Le sacerdoce donne l''autorité de célébrer.", "translation": "L''évêque ordonne."}, {"text": "Le sacerdoce a trois degrés.", "translation": "Diacre, prêtre, évêque."}]'::jsonb, null, '{"id": "eg.d.sacerdoce", "word": "le sacerdoce (l''ordination)", "translation": "sacrement où l''évêque, par l''imposition des mains, ordonne diacres, prêtres et évêques", "partOfSpeech": "concept", "explanation": "Le sacerdoce est le septième sacrement. Il ne se répète pas pour un même degré.", "examples": [{"text": "Le sacerdoce donne l''autorité de célébrer.", "translation": "L''évêque ordonne."}, {"text": "Le sacerdoce a trois degrés.", "translation": "Diacre, prêtre, évêque."}], "unitId": "eg.v.sacerdoce"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ordination', 'eg', 'l''ordination', 'la célébration du sacerdoce : l''évêque impose les mains au candidat', 'Le mot s''emploie pour chaque degré. Seul un évêque peut ordonner.', '[{"text": "L''ordination d''un prêtre se fait par l''évêque.", "translation": "Il impose les mains."}, {"text": "L''ordination d''un évêque se fait par plusieurs évêques.", "translation": "Avec le patriarche."}]'::jsonb, null, '{"id": "eg.d.ordination", "word": "l''ordination", "translation": "la célébration du sacerdoce : l''évêque impose les mains au candidat", "partOfSpeech": "event", "explanation": "Le mot s''emploie pour chaque degré. Seul un évêque peut ordonner.", "examples": [{"text": "L''ordination d''un prêtre se fait par l''évêque.", "translation": "Il impose les mains."}, {"text": "L''ordination d''un évêque se fait par plusieurs évêques.", "translation": "Avec le patriarche."}], "unitId": "eg.v.ordination"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacrements_d_initiation', 'eg', 'les sacrements d''initiation', 'baptême, confirmation et eucharistie : devenir et rester chrétien', 'Pour un enfant, ces trois sacrements se suivent. C''est un regroupement pratique.', '[{"text": "Le baptême ouvre les sacrements d''initiation.", "translation": "Puis viennent la confirmation et l''eucharistie."}, {"text": "Les trois sacrements d''initiation se suivent.", "translation": "L''enfant est plongé, scellé et nourri."}]'::jsonb, null, '{"id": "eg.d.sacrements_d_initiation", "word": "les sacrements d''initiation", "translation": "baptême, confirmation et eucharistie : devenir et rester chrétien", "partOfSpeech": "concept", "explanation": "Pour un enfant, ces trois sacrements se suivent. C''est un regroupement pratique.", "examples": [{"text": "Le baptême ouvre les sacrements d''initiation.", "translation": "Puis viennent la confirmation et l''eucharistie."}, {"text": "Les trois sacrements d''initiation se suivent.", "translation": "L''enfant est plongé, scellé et nourri."}], "unitId": "eg.v.sacrements_d_initiation"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacrements_de_guerison', 'eg', 'les sacrements de guérison', 'confession et onction des malades : le pardon et le soulagement', 'Ces deux sacrements se répètent au fil de la vie. C''est un regroupement pratique.', '[{"text": "La confession est un sacrement de guérison.", "translation": "Elle soigne l''âme."}, {"text": "L''onction des malades est un sacrement de guérison.", "translation": "Elle soigne l''âme et le corps."}]'::jsonb, null, '{"id": "eg.d.sacrements_de_guerison", "word": "les sacrements de guérison", "translation": "confession et onction des malades : le pardon et le soulagement", "partOfSpeech": "concept", "explanation": "Ces deux sacrements se répètent au fil de la vie. C''est un regroupement pratique.", "examples": [{"text": "La confession est un sacrement de guérison.", "translation": "Elle soigne l''âme."}, {"text": "L''onction des malades est un sacrement de guérison.", "translation": "Elle soigne l''âme et le corps."}], "unitId": "eg.v.sacrements_de_guerison"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sacrements_de_vocation', 'eg', 'les sacrements de vocation', 'mariage et sacerdoce : la grâce de servir dans un foyer ou dans l''Église', 'Dans les deux cas, Dieu donne la grâce d''une mission. C''est un regroupement pratique.', '[{"text": "Le mariage est un sacrement de vocation.", "translation": "Il fonde un foyer."}, {"text": "Le sacerdoce est un sacrement de vocation.", "translation": "Il envoie au service de l''Église."}]'::jsonb, null, '{"id": "eg.d.sacrements_de_vocation", "word": "les sacrements de vocation", "translation": "mariage et sacerdoce : la grâce de servir dans un foyer ou dans l''Église", "partOfSpeech": "concept", "explanation": "Dans les deux cas, Dieu donne la grâce d''une mission. C''est un regroupement pratique.", "examples": [{"text": "Le mariage est un sacrement de vocation.", "translation": "Il fonde un foyer."}, {"text": "Le sacerdoce est un sacrement de vocation.", "translation": "Il envoie au service de l''Église."}], "unitId": "eg.v.sacrements_de_vocation"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.orientation_vers_l_est', 'eg', 'l''orientation vers l''est', 'l''église est tournée vers l''est, vers le Christ, soleil de justice', 'Les coptes prient tournés vers l''est, et les églises sont bâties dans cette direction. Le soleil se lève à l''est : il rappelle le Christ.', '[{"text": "Le sanctuaire est à l''extrémité est de l''église.", "translation": "On prie vers l''est."}, {"text": "Le Christ est le soleil de justice.", "translation": "Le soleil se lève à l''est."}]'::jsonb, null, '{"id": "eg.d.orientation_vers_l_est", "word": "l''orientation vers l''est", "translation": "l''église est tournée vers l''est, vers le Christ, soleil de justice", "partOfSpeech": "concept", "explanation": "Les coptes prient tournés vers l''est, et les églises sont bâties dans cette direction. Le soleil se lève à l''est : il rappelle le Christ.", "examples": [{"text": "Le sanctuaire est à l''extrémité est de l''église.", "translation": "On prie vers l''est."}, {"text": "Le Christ est le soleil de justice.", "translation": "Le soleil se lève à l''est."}], "unitId": "eg.v.orientation_vers_l_est"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.arche_de_noe', 'eg', 'l''arche de Noé', 'forme la plus courante d''une église : un navire qui sauve', 'L''arche de Noé a sauvé du déluge ceux qui étaient dedans. L''église, de forme allongée comme un navire, rappelle que le Christ sauve son peuple.', '[{"text": "L''église copte a souvent la forme d''un navire.", "translation": "C''est l''arche de Noé."}, {"text": "Noé a construit l''arche.", "translation": "Elle a sauvé sa famille et les animaux."}]'::jsonb, null, '{"id": "eg.d.arche_de_noe", "word": "l''arche de Noé", "translation": "forme la plus courante d''une église : un navire qui sauve", "partOfSpeech": "concept", "explanation": "L''arche de Noé a sauvé du déluge ceux qui étaient dedans. L''église, de forme allongée comme un navire, rappelle que le Christ sauve son peuple.", "examples": [{"text": "L''église copte a souvent la forme d''un navire.", "translation": "C''est l''arche de Noé."}, {"text": "Noé a construit l''arche.", "translation": "Elle a sauvé sa famille et les animaux."}], "unitId": "eg.v.arche_de_noe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.narthex', 'eg', 'le narthex', 'l''entrée de l''église, à l''ouest, autrefois pour les catéchumènes', 'Le narthex est le vestibule d''entrée. Autrefois, les catéchumènes, qui préparent leur baptême, y restaient pendant la liturgie.', '[{"text": "On passe par le narthex pour entrer dans l''église.", "translation": "C''est la première partie."}, {"text": "Les catéchumènes se tenaient au narthex.", "translation": "Ils n''étaient pas encore baptisés."}]'::jsonb, null, '{"id": "eg.d.narthex", "word": "le narthex", "translation": "l''entrée de l''église, à l''ouest, autrefois pour les catéchumènes", "partOfSpeech": "concept", "explanation": "Le narthex est le vestibule d''entrée. Autrefois, les catéchumènes, qui préparent leur baptême, y restaient pendant la liturgie.", "examples": [{"text": "On passe par le narthex pour entrer dans l''église.", "translation": "C''est la première partie."}, {"text": "Les catéchumènes se tenaient au narthex.", "translation": "Ils n''étaient pas encore baptisés."}], "unitId": "eg.v.narthex"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nef', 'eg', 'la nef', 'la grande salle où se tiennent les fidèles', 'La nef est la partie centrale de l''église. Son nom vient du latin navis, le navire, car l''église est une arche.', '[{"text": "Les fidèles prient dans la nef.", "translation": "Elle est entre l''entrée et le sanctuaire."}, {"text": "Le chœur des diacres est devant la nef.", "translation": "Il touche l''iconostase."}]'::jsonb, null, '{"id": "eg.d.nef", "word": "la nef", "translation": "la grande salle où se tiennent les fidèles", "partOfSpeech": "concept", "explanation": "La nef est la partie centrale de l''église. Son nom vient du latin navis, le navire, car l''église est une arche.", "examples": [{"text": "Les fidèles prient dans la nef.", "translation": "Elle est entre l''entrée et le sanctuaire."}, {"text": "Le chœur des diacres est devant la nef.", "translation": "Il touche l''iconostase."}], "unitId": "eg.v.nef"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tabernacle_de_moise', 'eg', 'le Tabernacle de Moïse', 'la tente de Dieu bâtie au Sinaï sur un modèle montré à Moïse', 'Le Tabernacle est la tente sacrée que Moïse construit au désert. Ses trois espaces ont inspiré le plan de l''église.', '[{"text": "Dieu montre le modèle du Tabernacle à Moïse.", "translation": "Il le dit sur le Sinaï."}, {"text": "Le Tabernacle est une tente.", "translation": "On pouvait la monter et la démonter en voyage."}]'::jsonb, null, '{"id": "eg.d.tabernacle_de_moise", "word": "le Tabernacle de Moïse", "translation": "la tente de Dieu bâtie au Sinaï sur un modèle montré à Moïse", "partOfSpeech": "concept", "explanation": "Le Tabernacle est la tente sacrée que Moïse construit au désert. Ses trois espaces ont inspiré le plan de l''église.", "examples": [{"text": "Dieu montre le modèle du Tabernacle à Moïse.", "translation": "Il le dit sur le Sinaï."}, {"text": "Le Tabernacle est une tente.", "translation": "On pouvait la monter et la démonter en voyage."}], "unitId": "eg.v.tabernacle_de_moise"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.parvis', 'eg', 'le parvis', 'la cour en plein air du Tabernacle ; il correspond au narthex', 'Le parvis est la cour ouverte qui entoure le Tabernacle. C''est le premier espace, où l''on entre.', '[{"text": "Le parvis est en plein air.", "translation": "On y offrait les sacrifices."}, {"text": "Le narthex correspond au parvis.", "translation": "Tous deux sont à l''entrée."}]'::jsonb, null, '{"id": "eg.d.parvis", "word": "le parvis", "translation": "la cour en plein air du Tabernacle ; il correspond au narthex", "partOfSpeech": "concept", "explanation": "Le parvis est la cour ouverte qui entoure le Tabernacle. C''est le premier espace, où l''on entre.", "examples": [{"text": "Le parvis est en plein air.", "translation": "On y offrait les sacrifices."}, {"text": "Le narthex correspond au parvis.", "translation": "Tous deux sont à l''entrée."}], "unitId": "eg.v.parvis"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lieu_saint', 'eg', 'le lieu saint', 'le deuxième espace du Tabernacle ; il correspond à la nef', 'Le lieu saint est la première salle de la tente, où les prêtres servaient. Il correspond à la nef de l''église.', '[{"text": "Les prêtres servaient dans le lieu saint.", "translation": "Ils y entraient chaque jour."}, {"text": "La nef correspond au lieu saint.", "translation": "Les fidèles y prient."}]'::jsonb, null, '{"id": "eg.d.lieu_saint", "word": "le lieu saint", "translation": "le deuxième espace du Tabernacle ; il correspond à la nef", "partOfSpeech": "concept", "explanation": "Le lieu saint est la première salle de la tente, où les prêtres servaient. Il correspond à la nef de l''église.", "examples": [{"text": "Les prêtres servaient dans le lieu saint.", "translation": "Ils y entraient chaque jour."}, {"text": "La nef correspond au lieu saint.", "translation": "Les fidèles y prient."}], "unitId": "eg.v.lieu_saint"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_des_saints', 'eg', 'le saint des saints', 'le dernier espace du Tabernacle ; il correspond au sanctuaire', 'Le saint des saints est le lieu le plus sacré, où se trouvait l''arche de l''alliance. Seul le grand prêtre y entrait, une fois par an.', '[{"text": "Le grand prêtre entre dans le saint des saints.", "translation": "Il y entre une fois par an."}, {"text": "Le sanctuaire correspond au saint des saints.", "translation": "C''est la partie la plus proche de Dieu."}]'::jsonb, null, '{"id": "eg.d.saint_des_saints", "word": "le saint des saints", "translation": "le dernier espace du Tabernacle ; il correspond au sanctuaire", "partOfSpeech": "concept", "explanation": "Le saint des saints est le lieu le plus sacré, où se trouvait l''arche de l''alliance. Seul le grand prêtre y entrait, une fois par an.", "examples": [{"text": "Le grand prêtre entre dans le saint des saints.", "translation": "Il y entre une fois par an."}, {"text": "Le sanctuaire correspond au saint des saints.", "translation": "C''est la partie la plus proche de Dieu."}], "unitId": "eg.v.saint_des_saints"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.haikal', 'eg', 'le haikal', 'le sanctuaire, partie la plus sainte de l''église, à l''est', 'Le haikal est le sanctuaire : on y trouve l''autel. Son nom arabe veut dire « temple ». Il est séparé de la nef par l''iconostase.', '[{"text": "Le prêtre entre dans le haikal.", "translation": "C''est la partie la plus sainte."}, {"text": "L''autel est au centre du haikal.", "translation": "Il est tout à l''est."}]'::jsonb, null, '{"id": "eg.d.haikal", "word": "le haikal", "translation": "le sanctuaire, partie la plus sainte de l''église, à l''est", "partOfSpeech": "place", "explanation": "Le haikal est le sanctuaire : on y trouve l''autel. Son nom arabe veut dire « temple ». Il est séparé de la nef par l''iconostase.", "examples": [{"text": "Le prêtre entre dans le haikal.", "translation": "C''est la partie la plus sainte."}, {"text": "L''autel est au centre du haikal.", "translation": "Il est tout à l''est."}], "unitId": "eg.v.haikal"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.autel', 'eg', 'l''autel', 'cube de pierre ou de bois, qui représente le tombeau du Christ', 'L''autel est la table de la liturgie. Consacré au myron, il représente le tombeau du Christ et la table où Il se donne.', '[{"text": "La liturgie est célébrée sur l''autel.", "translation": "Il est au centre du haikal."}, {"text": "Seuls les clercs touchent l''autel.", "translation": "Il est consacré."}]'::jsonb, null, '{"id": "eg.d.autel", "word": "l''autel", "translation": "cube de pierre ou de bois, qui représente le tombeau du Christ", "partOfSpeech": "concept", "explanation": "L''autel est la table de la liturgie. Consacré au myron, il représente le tombeau du Christ et la table où Il se donne.", "examples": [{"text": "La liturgie est célébrée sur l''autel.", "translation": "Il est au centre du haikal."}, {"text": "Seuls les clercs touchent l''autel.", "translation": "Il est consacré."}], "unitId": "eg.v.autel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.myron', 'eg', 'le myron', 'huile sainte faite par le pape, qui sert à consacrer l''autel', 'Le myron, ou saint chrême, est une huile sainte préparée et consacrée par le pape d''Alexandrie. On l''utilise pour consacrer l''autel et pour certains sacrements.', '[{"text": "L''évêque oint l''autel avec le myron.", "translation": "L''autel est alors consacré."}, {"text": "Le pape fait le myron.", "translation": "Il y en a pour toute l''Église."}]'::jsonb, null, '{"id": "eg.d.myron", "word": "le myron", "translation": "huile sainte faite par le pape, qui sert à consacrer l''autel", "partOfSpeech": "concept", "explanation": "Le myron, ou saint chrême, est une huile sainte préparée et consacrée par le pape d''Alexandrie. On l''utilise pour consacrer l''autel et pour certains sacrements.", "examples": [{"text": "L''évêque oint l''autel avec le myron.", "translation": "L''autel est alors consacré."}, {"text": "Le pape fait le myron.", "translation": "Il y en a pour toute l''Église."}], "unitId": "eg.v.myron"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ciborium', 'eg', 'le ciborium', 'coupole sur quatre piliers au-dessus de l''autel', 'Le ciborium est un petit toit à coupole porté par quatre piliers. Il couvre l''autel comme le ciel couvre la terre.', '[{"text": "Le ciborium est peint de l''icône du Christ.", "translation": "Il rappelle le ciel."}, {"text": "Les quatre piliers portent les évangélistes.", "translation": "Une croix est au sommet."}]'::jsonb, null, '{"id": "eg.d.ciborium", "word": "le ciborium", "translation": "coupole sur quatre piliers au-dessus de l''autel", "partOfSpeech": "concept", "explanation": "Le ciborium est un petit toit à coupole porté par quatre piliers. Il couvre l''autel comme le ciel couvre la terre.", "examples": [{"text": "Le ciborium est peint de l''icône du Christ.", "translation": "Il rappelle le ciel."}, {"text": "Les quatre piliers portent les évangélistes.", "translation": "Une croix est au sommet."}], "unitId": "eg.v.ciborium"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.calice', 'eg', 'le calice', 'la coupe qui contient le vin mêlé d''eau, sang du Christ', 'Le calice est la coupe sacrée de la liturgie. Il contient le vin mêlé d''un peu d''eau, qui devient le sang du Christ.', '[{"text": "Le calice est posé sur l''autel.", "translation": "Il est en argent ou en or."}, {"text": "Le vin est mêlé d''eau.", "translation": "C''est l''usage de l''Église."}]'::jsonb, null, '{"id": "eg.d.calice", "word": "le calice", "translation": "la coupe qui contient le vin mêlé d''eau, sang du Christ", "partOfSpeech": "concept", "explanation": "Le calice est la coupe sacrée de la liturgie. Il contient le vin mêlé d''un peu d''eau, qui devient le sang du Christ.", "examples": [{"text": "Le calice est posé sur l''autel.", "translation": "Il est en argent ou en or."}, {"text": "Le vin est mêlé d''eau.", "translation": "C''est l''usage de l''Église."}], "unitId": "eg.v.calice"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.patene', 'eg', 'la patène', 'petit plateau rond qui porte le pain devenu le corps du Christ', 'La patène est un petit plateau plat et rond. Elle porte le pain de la liturgie. On dit qu''elle rappelle la crèche et le tombeau.', '[{"text": "La patène porte le pain.", "translation": "Elle est ronde."}, {"text": "Le prêtre élève la patène.", "translation": "Elle rappelle la crèche."}]'::jsonb, null, '{"id": "eg.d.patene", "word": "la patène", "translation": "petit plateau rond qui porte le pain devenu le corps du Christ", "partOfSpeech": "concept", "explanation": "La patène est un petit plateau plat et rond. Elle porte le pain de la liturgie. On dit qu''elle rappelle la crèche et le tombeau.", "examples": [{"text": "La patène porte le pain.", "translation": "Elle est ronde."}, {"text": "Le prêtre élève la patène.", "translation": "Elle rappelle la crèche."}], "unitId": "eg.v.patene"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.asterisque', 'eg', 'l''astérisque', 'l''étoile : deux bandes croisées posées sur la patène, en souvenir de l''étoile des mages', 'L''astérisque, ou étoile, est une petite armature de deux bandes croisées. Elle soutient le voile au-dessus du pain et rappelle l''étoile des mages.', '[{"text": "L''astérisque est posé sur la patène.", "translation": "Il a deux bandes croisées."}, {"text": "Il rappelle l''étoile de Bethléem.", "translation": "Les mages l''ont suivie."}]'::jsonb, null, '{"id": "eg.d.asterisque", "word": "l''astérisque", "translation": "l''étoile : deux bandes croisées posées sur la patène, en souvenir de l''étoile des mages", "partOfSpeech": "concept", "explanation": "L''astérisque, ou étoile, est une petite armature de deux bandes croisées. Elle soutient le voile au-dessus du pain et rappelle l''étoile des mages.", "examples": [{"text": "L''astérisque est posé sur la patène.", "translation": "Il a deux bandes croisées."}, {"text": "Il rappelle l''étoile de Bethléem.", "translation": "Les mages l''ont suivie."}], "unitId": "eg.v.asterisque"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cuillere', 'eg', 'la cuillère', 'petite cuillère qui sert à donner le sang du Christ aux fidèles', 'La cuillère de communion permet de donner aux fidèles le sang du Christ, avec un peu de pain. Le prêtre la tient pendant la communion.', '[{"text": "Le prêtre donne la communion avec la cuillère.", "translation": "C''est l''usage copte."}, {"text": "La cuillère est en argent.", "translation": "Elle est petite."}]'::jsonb, null, '{"id": "eg.d.cuillere", "word": "la cuillère", "translation": "petite cuillère qui sert à donner le sang du Christ aux fidèles", "partOfSpeech": "concept", "explanation": "La cuillère de communion permet de donner aux fidèles le sang du Christ, avec un peu de pain. Le prêtre la tient pendant la communion.", "examples": [{"text": "Le prêtre donne la communion avec la cuillère.", "translation": "C''est l''usage copte."}, {"text": "La cuillère est en argent.", "translation": "Elle est petite."}], "unitId": "eg.v.cuillere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.coffret_de_l_autel', 'eg', 'le coffret de l''autel', 'boîte de bois qui sert de support au calice, appelée aussi le trône', 'Le coffret est une petite boîte de bois, souvent décorée de petites icônes, sur laquelle on pose le calice. On l''appelle aussi le trône.', '[{"text": "Le calice repose sur le coffret.", "translation": "Il est décoré d''icônes."}, {"text": "Le coffret est au centre de l''autel.", "translation": "Il rappelle le trône du Christ."}]'::jsonb, null, '{"id": "eg.d.coffret_de_l_autel", "word": "le coffret de l''autel", "translation": "boîte de bois qui sert de support au calice, appelée aussi le trône", "partOfSpeech": "concept", "explanation": "Le coffret est une petite boîte de bois, souvent décorée de petites icônes, sur laquelle on pose le calice. On l''appelle aussi le trône.", "examples": [{"text": "Le calice repose sur le coffret.", "translation": "Il est décoré d''icônes."}, {"text": "Le coffret est au centre de l''autel.", "translation": "Il rappelle le trône du Christ."}], "unitId": "eg.v.coffret_de_l_autel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.entrer_dechausse', 'eg', 'entrer déchaussé', 'ôter ses chaussures pour entrer dans le haikal, comme Moïse', 'Dans le haikal, le clergé et les diacres entrent sans chaussures, comme Moïse devant le buisson ardent. C''est un signe de respect et d''humilité.', '[{"text": "On enlève ses chaussures avant le haikal.", "translation": "C''est une terre sainte."}, {"text": "Moïse enlève ses sandales.", "translation": "Dieu le lui demande."}]'::jsonb, null, '{"id": "eg.d.entrer_dechausse", "word": "entrer déchaussé", "translation": "ôter ses chaussures pour entrer dans le haikal, comme Moïse", "partOfSpeech": "concept", "explanation": "Dans le haikal, le clergé et les diacres entrent sans chaussures, comme Moïse devant le buisson ardent. C''est un signe de respect et d''humilité.", "examples": [{"text": "On enlève ses chaussures avant le haikal.", "translation": "C''est une terre sainte."}, {"text": "Moïse enlève ses sandales.", "translation": "Dieu le lui demande."}], "unitId": "eg.v.entrer_dechausse"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.iconostase', 'eg', 'l''iconostase (higab)', 'cloison couverte d''icônes qui sépare la nef et le haikal', 'L''iconostase est le mur d''icônes entre la nef et le haikal. En arabe, on l''appelle higab, le voile. Elle n''isole pas : elle ouvre sur le ciel.', '[{"text": "L''iconostase est couverte d''icônes.", "translation": "Elle sépare la nef et le haikal."}, {"text": "Le higab a trois portes.", "translation": "La porte centrale est la porte royale."}]'::jsonb, null, '{"id": "eg.d.iconostase", "word": "l''iconostase (higab)", "translation": "cloison couverte d''icônes qui sépare la nef et le haikal", "partOfSpeech": "concept", "explanation": "L''iconostase est le mur d''icônes entre la nef et le haikal. En arabe, on l''appelle higab, le voile. Elle n''isole pas : elle ouvre sur le ciel.", "examples": [{"text": "L''iconostase est couverte d''icônes.", "translation": "Elle sépare la nef et le haikal."}, {"text": "Le higab a trois portes.", "translation": "La porte centrale est la porte royale."}], "unitId": "eg.v.iconostase"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.porte_royale', 'eg', 'la porte royale', 'la grande porte centrale de l''iconostase, qui mène à l''autel', 'La porte royale est l''ouverture principale de l''iconostase. Le Christ, le Roi, vient à nous par elle dans la liturgie.', '[{"text": "La Cène est au-dessus de la porte royale.", "translation": "C''est la plus grande porte."}, {"text": "L''œuf d''autruche est suspendu près de la porte royale.", "translation": "Il reste visible de la nef."}]'::jsonb, null, '{"id": "eg.d.porte_royale", "word": "la porte royale", "translation": "la grande porte centrale de l''iconostase, qui mène à l''autel", "partOfSpeech": "concept", "explanation": "La porte royale est l''ouverture principale de l''iconostase. Le Christ, le Roi, vient à nous par elle dans la liturgie.", "examples": [{"text": "La Cène est au-dessus de la porte royale.", "translation": "C''est la plus grande porte."}, {"text": "L''œuf d''autruche est suspendu près de la porte royale.", "translation": "Il reste visible de la nef."}], "unitId": "eg.v.porte_royale"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.oeuf_d_autruche', 'eg', 'l''œuf d''autruche', 'œuf suspendu devant l''iconostase : Dieu veille sans cesse, et la résurrection', 'L''œuf d''autruche est un objet symbolique suspendu devant l''iconostase. Il rappelle la vigilance de Dieu et la résurrection.', '[{"text": "Un œuf d''autruche est suspendu près de la porte royale.", "translation": "Il attire le regard."}, {"text": "L''autruche veille sur ses œufs.", "translation": "Dieu veille sur nous."}]'::jsonb, null, '{"id": "eg.d.oeuf_d_autruche", "word": "l''œuf d''autruche", "translation": "œuf suspendu devant l''iconostase : Dieu veille sans cesse, et la résurrection", "partOfSpeech": "concept", "explanation": "L''œuf d''autruche est un objet symbolique suspendu devant l''iconostase. Il rappelle la vigilance de Dieu et la résurrection.", "examples": [{"text": "Un œuf d''autruche est suspendu près de la porte royale.", "translation": "Il attire le regard."}, {"text": "L''autruche veille sur ses œufs.", "translation": "Dieu veille sur nous."}], "unitId": "eg.v.oeuf_d_autruche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lampe_a_huile', 'eg', 'la lampe à huile', 'lampe allumée devant les icônes : la lumière du Christ', 'La lampe à huile est une lumière que l''on garde allumée devant les icônes. Elle représente la lumière du Christ.', '[{"text": "Une lampe brûle devant l''icône.", "translation": "Elle veille jour et nuit."}, {"text": "Les vierges sages gardent leur lampe allumée.", "translation": "Elles attendent l''époux."}]'::jsonb, null, '{"id": "eg.d.lampe_a_huile", "word": "la lampe à huile", "translation": "lampe allumée devant les icônes : la lumière du Christ", "partOfSpeech": "concept", "explanation": "La lampe à huile est une lumière que l''on garde allumée devant les icônes. Elle représente la lumière du Christ.", "examples": [{"text": "Une lampe brûle devant l''icône.", "translation": "Elle veille jour et nuit."}, {"text": "Les vierges sages gardent leur lampe allumée.", "translation": "Elles attendent l''époux."}], "unitId": "eg.v.lampe_a_huile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.encens', 'eg', 'l''encens', 'résine parfumée dont la fumée représente les prières qui montent', 'L''encens est une résine odorante que l''on brûle sur du charbon. Sa fumée représente les prières des fidèles qui montent vers Dieu.', '[{"text": "Le prêtre offre l''encens.", "translation": "Il le fait au début de la liturgie."}, {"text": "Malachie annonce l''encens en tout lieu.", "translation": "C''est un acte de louange."}]'::jsonb, null, '{"id": "eg.d.encens", "word": "l''encens", "translation": "résine parfumée dont la fumée représente les prières qui montent", "partOfSpeech": "concept", "explanation": "L''encens est une résine odorante que l''on brûle sur du charbon. Sa fumée représente les prières des fidèles qui montent vers Dieu.", "examples": [{"text": "Le prêtre offre l''encens.", "translation": "Il le fait au début de la liturgie."}, {"text": "Malachie annonce l''encens en tout lieu.", "translation": "C''est un acte de louange."}], "unitId": "eg.v.encens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.encensoir', 'eg', 'l''encensoir', 'récipient suspendu à des chaînes, où l''on brûle l''encens sur du charbon', 'L''encensoir est le récipient à chaînes que le prêtre balance. Il contient le charbon ardent et l''encens.', '[{"text": "Le prêtre balance l''encensoir.", "translation": "Les clochettes tintent."}, {"text": "L''encensoir contient du charbon.", "translation": "On y verse l''encens."}]'::jsonb, null, '{"id": "eg.d.encensoir", "word": "l''encensoir", "translation": "récipient suspendu à des chaînes, où l''on brûle l''encens sur du charbon", "partOfSpeech": "concept", "explanation": "L''encensoir est le récipient à chaînes que le prêtre balance. Il contient le charbon ardent et l''encens.", "examples": [{"text": "Le prêtre balance l''encensoir.", "translation": "Les clochettes tintent."}, {"text": "L''encensoir contient du charbon.", "translation": "On y verse l''encens."}], "unitId": "eg.v.encensoir"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cene', 'eg', 'la Cène', 'le dernier repas du Christ avec ses disciples, quand il institue l''eucharistie', 'La Cène est le repas du Jeudi saint où le Christ donne son corps et son sang. Son icône est au-dessus de la porte royale.', '[{"text": "La Cène est représentée sur l''iconostase.", "translation": "Elle domine la porte royale."}, {"text": "Le Christ institue l''eucharistie à la Cène.", "translation": "Les douze sont présents."}]'::jsonb, null, '{"id": "eg.d.cene", "word": "la Cène", "translation": "le dernier repas du Christ avec ses disciples, quand il institue l''eucharistie", "partOfSpeech": "event", "explanation": "La Cène est le repas du Jeudi saint où le Christ donne son corps et son sang. Son icône est au-dessus de la porte royale.", "examples": [{"text": "La Cène est représentée sur l''iconostase.", "translation": "Elle domine la porte royale."}, {"text": "Le Christ institue l''eucharistie à la Cène.", "translation": "Les douze sont présents."}], "unitId": "eg.v.cene"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_jean_baptiste', 'eg', 'saint Jean-Baptiste', 'le Précurseur, qui a préparé la venue du Christ', 'Jean-Baptiste est le prophète qui annonce le Christ et le baptise au Jourdain. Son icône est souvent à côté de celle du Christ.', '[{"text": "Jean-Baptiste baptise Jésus dans le Jourdain.", "translation": "On l''appelle le Précurseur."}, {"text": "Son icône est près du Christ.", "translation": "Il prépare la voie."}]'::jsonb, null, '{"id": "eg.d.saint_jean_baptiste", "word": "saint Jean-Baptiste", "translation": "le Précurseur, qui a préparé la venue du Christ", "partOfSpeech": "person", "explanation": "Jean-Baptiste est le prophète qui annonce le Christ et le baptise au Jourdain. Son icône est souvent à côté de celle du Christ.", "examples": [{"text": "Jean-Baptiste baptise Jésus dans le Jourdain.", "translation": "On l''appelle le Précurseur."}, {"text": "Son icône est près du Christ.", "translation": "Il prépare la voie."}], "unitId": "eg.v.saint_jean_baptiste"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.adoration', 'eg', 'l''adoration', 'honneur suprême, dû à Dieu seul', 'L''adoration est l''hommage qu''on ne rend qu''à Dieu. Les saints et les icônes reçoivent la vénération, jamais l''adoration.', '[{"text": "L''adoration est due à Dieu seul.", "translation": "On n''adore pas les saints."}, {"text": "On vénère l''icône mais on adore Dieu.", "translation": "La différence est essentielle."}]'::jsonb, null, '{"id": "eg.d.adoration", "word": "l''adoration", "translation": "honneur suprême, dû à Dieu seul", "partOfSpeech": "concept", "explanation": "L''adoration est l''hommage qu''on ne rend qu''à Dieu. Les saints et les icônes reçoivent la vénération, jamais l''adoration.", "examples": [{"text": "L''adoration est due à Dieu seul.", "translation": "On n''adore pas les saints."}, {"text": "On vénère l''icône mais on adore Dieu.", "translation": "La différence est essentielle."}], "unitId": "eg.v.adoration"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.diaconat', 'eg', 'le diaconat', 'le ministère des diacres, en cinq rangs', 'Le diaconat est l''ensemble des services rendus par les diacres, du chantre à l''archidiacre. C''est un ministère de service.', '[{"text": "Le diaconat compte cinq rangs.", "translation": "Du psalte à l''archidiacre."}, {"text": "On entre souvent dans le diaconat enfant.", "translation": "On devient d''abord psalte."}]'::jsonb, null, '{"id": "eg.d.diaconat", "word": "le diaconat", "translation": "le ministère des diacres, en cinq rangs", "partOfSpeech": "concept", "explanation": "Le diaconat est l''ensemble des services rendus par les diacres, du chantre à l''archidiacre. C''est un ministère de service.", "examples": [{"text": "Le diaconat compte cinq rangs.", "translation": "Du psalte à l''archidiacre."}, {"text": "On entre souvent dans le diaconat enfant.", "translation": "On devient d''abord psalte."}], "unitId": "eg.v.diaconat"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.psalte', 'eg', 'le psalte (épsaltos)', 'le chantre, premier rang du diaconat, qui chante les hymnes', 'Le psalte, du grec épsaltos, chante les hymnes et les psaumes. C''est le premier rang du diaconat.', '[{"text": "Le psalte chante pendant l''office.", "translation": "Il connaît les mélodies."}, {"text": "Les enfants deviennent souvent psaltes.", "translation": "C''est la première marche."}]'::jsonb, null, '{"id": "eg.d.psalte", "word": "le psalte (épsaltos)", "translation": "le chantre, premier rang du diaconat, qui chante les hymnes", "partOfSpeech": "person", "explanation": "Le psalte, du grec épsaltos, chante les hymnes et les psaumes. C''est le premier rang du diaconat.", "examples": [{"text": "Le psalte chante pendant l''office.", "translation": "Il connaît les mélodies."}, {"text": "Les enfants deviennent souvent psaltes.", "translation": "C''est la première marche."}], "unitId": "eg.v.psalte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lecteur', 'eg', 'le lecteur (anagnostès)', 'deuxième rang du diaconat : il lit les lectures de la Bible', 'Le lecteur, anagnostès en grec, lit les textes de la Bible à l''assemblée. Il étudie les Écritures et les Pères.', '[{"text": "Le lecteur lit l''Écriture à l''église.", "translation": "Il doit comprendre ce qu''il lit."}, {"text": "L''anagnostès étudie les Pères.", "translation": "Il aide à préparer les vases."}]'::jsonb, null, '{"id": "eg.d.lecteur", "word": "le lecteur (anagnostès)", "translation": "deuxième rang du diaconat : il lit les lectures de la Bible", "partOfSpeech": "person", "explanation": "Le lecteur, anagnostès en grec, lit les textes de la Bible à l''assemblée. Il étudie les Écritures et les Pères.", "examples": [{"text": "Le lecteur lit l''Écriture à l''église.", "translation": "Il doit comprendre ce qu''il lit."}, {"text": "L''anagnostès étudie les Pères.", "translation": "Il aide à préparer les vases."}], "unitId": "eg.v.lecteur"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sous_diacre', 'eg', 'le sous-diacre (hypodiacre)', 'troisième rang du diaconat : il aide les diacres et garde les portes', 'Le sous-diacre, hypodiacre en grec, aide les diacres et veille aux portes de l''église pendant les offices.', '[{"text": "Le sous-diacre garde la porte.", "translation": "Il aide les diacres."}, {"text": "Hypo veut dire « sous ».", "translation": "L''hypodiacre est sous le diacre."}]'::jsonb, null, '{"id": "eg.d.sous_diacre", "word": "le sous-diacre (hypodiacre)", "translation": "troisième rang du diaconat : il aide les diacres et garde les portes", "partOfSpeech": "person", "explanation": "Le sous-diacre, hypodiacre en grec, aide les diacres et veille aux portes de l''église pendant les offices.", "examples": [{"text": "Le sous-diacre garde la porte.", "translation": "Il aide les diacres."}, {"text": "Hypo veut dire « sous ».", "translation": "L''hypodiacre est sous le diacre."}], "unitId": "eg.v.sous_diacre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tunique_blanche', 'eg', 'la tunique blanche', 'vêtement blanc du diacre en service, symbole de pureté', 'La tunique blanche est le vêtement de service des diacres. Le blanc rappelle la pureté et les anges.', '[{"text": "Les diacres portent une tunique blanche.", "translation": "Elle est blanche comme les anges."}, {"text": "Les enfants servent aussi en tunique.", "translation": "Elle varie selon les églises."}]'::jsonb, null, '{"id": "eg.d.tunique_blanche", "word": "la tunique blanche", "translation": "vêtement blanc du diacre en service, symbole de pureté", "partOfSpeech": "concept", "explanation": "La tunique blanche est le vêtement de service des diacres. Le blanc rappelle la pureté et les anges.", "examples": [{"text": "Les diacres portent une tunique blanche.", "translation": "Elle est blanche comme les anges."}, {"text": "Les enfants servent aussi en tunique.", "translation": "Elle varie selon les églises."}], "unitId": "eg.v.tunique_blanche"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.etole', 'eg', 'l''étole', 'bande de tissu portée sur l''épaule par les diacres ordonnés', 'L''étole est une longue bande de tissu que les diacres ordonnés portent sur l''épaule par-dessus la tunique.', '[{"text": "Le diacre porte l''étole sur l''épaule.", "translation": "Elle est souvent brodée de croix."}, {"text": "Le prêtre porte aussi une étole.", "translation": "Elle marque le service de l''autel."}]'::jsonb, null, '{"id": "eg.d.etole", "word": "l''étole", "translation": "bande de tissu portée sur l''épaule par les diacres ordonnés", "partOfSpeech": "concept", "explanation": "L''étole est une longue bande de tissu que les diacres ordonnés portent sur l''épaule par-dessus la tunique.", "examples": [{"text": "Le diacre porte l''étole sur l''épaule.", "translation": "Elle est souvent brodée de croix."}, {"text": "Le prêtre porte aussi une étole.", "translation": "Elle marque le service de l''autel."}], "unitId": "eg.v.etole"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.abouna', 'eg', 'abouna', '« notre père » : nom donné au prêtre en arabe', 'Abouna veut dire « notre père » en arabe. C''est la façon habituelle d''appeler un prêtre copte.', '[{"text": "Les fidèles disent « Abouna » au prêtre.", "translation": "C''est un mot de respect."}, {"text": "Abouna bénit la famille.", "translation": "Il visite les maisons."}]'::jsonb, null, '{"id": "eg.d.abouna", "word": "abouna", "translation": "« notre père » : nom donné au prêtre en arabe", "partOfSpeech": "expression", "explanation": "Abouna veut dire « notre père » en arabe. C''est la façon habituelle d''appeler un prêtre copte.", "examples": [{"text": "Les fidèles disent « Abouna » au prêtre.", "translation": "C''est un mot de respect."}, {"text": "Abouna bénit la famille.", "translation": "Il visite les maisons."}], "unitId": "eg.v.abouna"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pretre_marie', 'eg', 'le prêtre marié', 'prêtre marié avant son ordination', 'L''Église copte peut ordonner des hommes mariés. Ils se marient avant l''ordination, jamais après, et le prêtre veuf ne se remarie pas.', '[{"text": "Beaucoup de prêtres coptes sont mariés.", "translation": "Ils se sont mariés avant l''ordination."}, {"text": "Un prêtre veuf ne se remarie pas.", "translation": "C''est la règle."}]'::jsonb, null, '{"id": "eg.d.pretre_marie", "word": "le prêtre marié", "translation": "prêtre marié avant son ordination", "partOfSpeech": "concept", "explanation": "L''Église copte peut ordonner des hommes mariés. Ils se marient avant l''ordination, jamais après, et le prêtre veuf ne se remarie pas.", "examples": [{"text": "Beaucoup de prêtres coptes sont mariés.", "translation": "Ils se sont mariés avant l''ordination."}, {"text": "Un prêtre veuf ne se remarie pas.", "translation": "C''est la règle."}], "unitId": "eg.v.pretre_marie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.qommos', 'eg', 'le qommos (hégoumène)', 'archiprêtre : prêtre promu à la tête des prêtres d''une église', 'Le qommos, ou hégoumène, est l''archiprêtre. C''est un prêtre à qui l''on confie la direction du groupe de prêtres d''une église.', '[{"text": "Le qommos dirige les prêtres de l''église.", "translation": "C''est un titre de promotion."}, {"text": "Il est souvent le plus ancien.", "translation": "Il n''a pas reçu un nouvel ordre."}]'::jsonb, null, '{"id": "eg.d.qommos", "word": "le qommos (hégoumène)", "translation": "archiprêtre : prêtre promu à la tête des prêtres d''une église", "partOfSpeech": "person", "explanation": "Le qommos, ou hégoumène, est l''archiprêtre. C''est un prêtre à qui l''on confie la direction du groupe de prêtres d''une église.", "examples": [{"text": "Le qommos dirige les prêtres de l''église.", "translation": "C''est un titre de promotion."}, {"text": "Il est souvent le plus ancien.", "translation": "Il n''a pas reçu un nouvel ordre."}], "unitId": "eg.v.qommos"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.metropolite', 'eg', 'le métropolite', 'évêque d''un grand diocèse, promu au-dessus des autres évêques', 'Le métropolite est un évêque promu à la tête d''un grand diocèse. Dans les rites, on le nomme avant les évêques.', '[{"text": "Le métropolite dirige un grand diocèse.", "translation": "Il est évêque."}, {"text": "On le cite avant les évêques.", "translation": "C''est une promotion."}]'::jsonb, null, '{"id": "eg.d.metropolite", "word": "le métropolite", "translation": "évêque d''un grand diocèse, promu au-dessus des autres évêques", "partOfSpeech": "person", "explanation": "Le métropolite est un évêque promu à la tête d''un grand diocèse. Dans les rites, on le nomme avant les évêques.", "examples": [{"text": "Le métropolite dirige un grand diocèse.", "translation": "Il est évêque."}, {"text": "On le cite avant les évêques.", "translation": "C''est une promotion."}], "unitId": "eg.v.metropolite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.saint_synode', 'eg', 'le saint-synode', 'assemblée des évêques de l''Église, présidée par le pape', 'Le saint-synode réunit les évêques autour du pape d''Alexandrie. Il décide des grandes questions de l''Église.', '[{"text": "Le pape préside le saint-synode.", "translation": "Tous les évêques en font partie."}, {"text": "Le saint-synode décide ensemble.", "translation": "Comme les anciens conciles."}]'::jsonb, null, '{"id": "eg.d.saint_synode", "word": "le saint-synode", "translation": "assemblée des évêques de l''Église, présidée par le pape", "partOfSpeech": "organization", "explanation": "Le saint-synode réunit les évêques autour du pape d''Alexandrie. Il décide des grandes questions de l''Église.", "examples": [{"text": "Le pape préside le saint-synode.", "translation": "Tous les évêques en font partie."}, {"text": "Le saint-synode décide ensemble.", "translation": "Comme les anciens conciles."}], "unitId": "eg.v.saint_synode"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.qora_haykaleya', 'eg', 'la qor''a haykaleya', 'tirage au sort sur l''autel, par un enfant, pour désigner le pape', 'La qor''a haykaleya est le tirage au sort devant l''autel pendant la liturgie. Un enfant aux yeux bandés tire un nom parmi trois pour que Dieu choisisse le pape.', '[{"text": "Un enfant tire le nom du pape sur l''autel.", "translation": "Il a les yeux bandés."}, {"text": "La qor''a haykaleya désigne le pape.", "translation": "Dieu choisit."}]'::jsonb, null, '{"id": "eg.d.qora_haykaleya", "word": "la qor''a haykaleya", "translation": "tirage au sort sur l''autel, par un enfant, pour désigner le pape", "partOfSpeech": "event", "explanation": "La qor''a haykaleya est le tirage au sort devant l''autel pendant la liturgie. Un enfant aux yeux bandés tire un nom parmi trois pour que Dieu choisisse le pape.", "examples": [{"text": "Un enfant tire le nom du pape sur l''autel.", "translation": "Il a les yeux bandés."}, {"text": "La qor''a haykaleya désigne le pape.", "translation": "Dieu choisit."}], "unitId": "eg.v.qora_haykaleya"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chenouda_iii', 'eg', 'Chenouda III', '117e pape d''Alexandrie, mort en 2012', 'Chenouda III est le 117e pape d''Alexandrie. Il est mort en mars 2012 ; Tawadros II lui a succédé.', '[{"text": "Chenouda III est le 117e pape.", "translation": "Il a précédé Tawadros II."}, {"text": "Il est mort en 2012.", "translation": "On l''a pleuré dans toute l''Égypte."}]'::jsonb, null, '{"id": "eg.d.chenouda_iii", "word": "Chenouda III", "translation": "117e pape d''Alexandrie, mort en 2012", "partOfSpeech": "person", "explanation": "Chenouda III est le 117e pape d''Alexandrie. Il est mort en mars 2012 ; Tawadros II lui a succédé.", "examples": [{"text": "Chenouda III est le 117e pape.", "translation": "Il a précédé Tawadros II."}, {"text": "Il est mort en 2012.", "translation": "On l''a pleuré dans toute l''Égypte."}], "unitId": "eg.v.chenouda_iii"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tawadros_ii', 'eg', 'Tawadros II', '118e pape d''Alexandrie, choisi par tirage au sort en 2012', 'Tawadros II est le 118e successeur de saint Marc. Évêque, il a été tiré au sort le 4 novembre 2012 et intronisé le 18 novembre.', '[{"text": "Tawadros II est le 118e pape.", "translation": "Il a été choisi par tirage au sort."}, {"text": "Il a succédé à Chenouda III.", "translation": "Il est le successeur de saint Marc."}]'::jsonb, null, '{"id": "eg.d.tawadros_ii", "word": "Tawadros II", "translation": "118e pape d''Alexandrie, choisi par tirage au sort en 2012", "partOfSpeech": "person", "explanation": "Tawadros II est le 118e successeur de saint Marc. Évêque, il a été tiré au sort le 4 novembre 2012 et intronisé le 18 novembre.", "examples": [{"text": "Tawadros II est le 118e pape.", "translation": "Il a été choisi par tirage au sort."}, {"text": "Il a succédé à Chenouda III.", "translation": "Il est le successeur de saint Marc."}], "unitId": "eg.v.tawadros_ii"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.moine', 'eg', 'le moine', 'celui qui quitte le monde pour prier, travailler et jeûner', 'Le moine renonce au mariage, aux biens et à sa propre volonté. Il vit en communauté, dans un monastère, sous la direction de l''abbé.', '[{"text": "Le moine prie, travaille et jeûne.", "translation": "Il vit au monastère."}, {"text": "Les évêques coptes sont d''anciens moines.", "translation": "Le pape est un moine."}]'::jsonb, null, '{"id": "eg.d.moine", "word": "le moine", "translation": "celui qui quitte le monde pour prier, travailler et jeûner", "partOfSpeech": "person", "explanation": "Le moine renonce au mariage, aux biens et à sa propre volonté. Il vit en communauté, dans un monastère, sous la direction de l''abbé.", "examples": [{"text": "Le moine prie, travaille et jeûne.", "translation": "Il vit au monastère."}, {"text": "Les évêques coptes sont d''anciens moines.", "translation": "Le pape est un moine."}], "unitId": "eg.v.moine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.abbe', 'eg', 'l''abbé', 'le père et le chef d''un monastère, aussi appelé higoumène', 'L''abbé dirige le monastère et guide les moines. Il les revêt de l''habit monastique. On l''appelle aussi higoumène.', '[{"text": "L''abbé guide les moines.", "translation": "Il leur donne l''habit."}, {"text": "L''abbé reçoit les moines nouveaux.", "translation": "Les ermites lui rendent visite."}]'::jsonb, null, '{"id": "eg.d.abbe", "word": "l''abbé", "translation": "le père et le chef d''un monastère, aussi appelé higoumène", "partOfSpeech": "person", "explanation": "L''abbé dirige le monastère et guide les moines. Il les revêt de l''habit monastique. On l''appelle aussi higoumène.", "examples": [{"text": "L''abbé guide les moines.", "translation": "Il leur donne l''habit."}, {"text": "L''abbé reçoit les moines nouveaux.", "translation": "Les ermites lui rendent visite."}], "unitId": "eg.v.abbe"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.eskime', 'eg', 'l''eskime (schème)', 'cordon de cuir orné de croix : l''habit des moines les plus avancés', 'L''eskime est un cordon de cuir tressé orné de croix, porté sur la poitrine et le dos. Il est donné à des moines de grande vie spirituelle.', '[{"text": "L''abbé revêt le moine de l''eskime.", "translation": "Il dit : « le saint eskime »."}, {"text": "L''eskime est un cordon orné de croix.", "translation": "Il est en cuir."}]'::jsonb, null, '{"id": "eg.d.eskime", "word": "l''eskime (schème)", "translation": "cordon de cuir orné de croix : l''habit des moines les plus avancés", "partOfSpeech": "concept", "explanation": "L''eskime est un cordon de cuir tressé orné de croix, porté sur la poitrine et le dos. Il est donné à des moines de grande vie spirituelle.", "examples": [{"text": "L''abbé revêt le moine de l''eskime.", "translation": "Il dit : « le saint eskime »."}, {"text": "L''eskime est un cordon orné de croix.", "translation": "Il est en cuir."}], "unitId": "eg.v.eskime"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.wadi_natroun', 'eg', 'Wadi Natroun', 'vallée au nord-ouest du Caire, ancienne Scété, qui garde quatre monastères', 'Wadi Natroun est la vallée de l''ancienne Scété, à environ cent kilomètres au nord-ouest du Caire. Quatre monastères y survivent.', '[{"text": "Wadi Natroun est l''ancienne Scété.", "translation": "Quatre monastères y vivent."}, {"text": "Saint Macaire y a vécu.", "translation": "On y va en pèlerinage."}]'::jsonb, null, '{"id": "eg.d.wadi_natroun", "word": "Wadi Natroun", "translation": "vallée au nord-ouest du Caire, ancienne Scété, qui garde quatre monastères", "partOfSpeech": "place", "explanation": "Wadi Natroun est la vallée de l''ancienne Scété, à environ cent kilomètres au nord-ouest du Caire. Quatre monastères y survivent.", "examples": [{"text": "Wadi Natroun est l''ancienne Scété.", "translation": "Quatre monastères y vivent."}, {"text": "Saint Macaire y a vécu.", "translation": "On y va en pèlerinage."}], "unitId": "eg.v.wadi_natroun"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monastere_saint_antoine', 'eg', 'le monastère Saint-Antoine', 'monastère près de la mer Rouge, autour des lieux de saint Antoine', 'Le monastère Saint-Antoine est dans le désert oriental, près de la mer Rouge, au pied du mont Colzim. On le dit le plus ancien monastère chrétien.', '[{"text": "Saint-Antoine est près de la mer Rouge.", "translation": "Il est au pied du mont Colzim."}, {"text": "Il est le plus ancien monastère.", "translation": "Saint Antoine y a vécu."}]'::jsonb, null, '{"id": "eg.d.monastere_saint_antoine", "word": "le monastère Saint-Antoine", "translation": "monastère près de la mer Rouge, autour des lieux de saint Antoine", "partOfSpeech": "place", "explanation": "Le monastère Saint-Antoine est dans le désert oriental, près de la mer Rouge, au pied du mont Colzim. On le dit le plus ancien monastère chrétien.", "examples": [{"text": "Saint-Antoine est près de la mer Rouge.", "translation": "Il est au pied du mont Colzim."}, {"text": "Il est le plus ancien monastère.", "translation": "Saint Antoine y a vécu."}], "unitId": "eg.v.monastere_saint_antoine"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monastere_saint_paul', 'eg', 'le monastère Saint-Paul', 'monastère près de la mer Rouge, autour de la grotte de Paul l''ermite', 'Le monastère Saint-Paul est près de Saint-Antoine, dans la même montagne. Il s''est formé autour de la grotte de saint Paul l''ermite.', '[{"text": "Saint-Paul est près de Saint-Antoine.", "translation": "Il est dans la même montagne."}, {"text": "Il garde la grotte de Paul.", "translation": "Le premier ermite y a vécu."}]'::jsonb, null, '{"id": "eg.d.monastere_saint_paul", "word": "le monastère Saint-Paul", "translation": "monastère près de la mer Rouge, autour de la grotte de Paul l''ermite", "partOfSpeech": "place", "explanation": "Le monastère Saint-Paul est près de Saint-Antoine, dans la même montagne. Il s''est formé autour de la grotte de saint Paul l''ermite.", "examples": [{"text": "Saint-Paul est près de Saint-Antoine.", "translation": "Il est dans la même montagne."}, {"text": "Il garde la grotte de Paul.", "translation": "Le premier ermite y a vécu."}], "unitId": "eg.v.monastere_saint_paul"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monastere_saint_macaire', 'eg', 'le monastère Saint-Macaire', 'monastère de Wadi Natroun qui garde la mémoire de saint Macaire le Grand', 'Le monastère Saint-Macaire est un des quatre monastères de Wadi Natroun. Il rappelle saint Macaire le Grand, père de Scété.', '[{"text": "Saint-Macaire est à Wadi Natroun.", "translation": "Il est fortifié."}, {"text": "Il garde la mémoire de Macaire.", "translation": "C''est un monastère ancien."}]'::jsonb, null, '{"id": "eg.d.monastere_saint_macaire", "word": "le monastère Saint-Macaire", "translation": "monastère de Wadi Natroun qui garde la mémoire de saint Macaire le Grand", "partOfSpeech": "place", "explanation": "Le monastère Saint-Macaire est un des quatre monastères de Wadi Natroun. Il rappelle saint Macaire le Grand, père de Scété.", "examples": [{"text": "Saint-Macaire est à Wadi Natroun.", "translation": "Il est fortifié."}, {"text": "Il garde la mémoire de Macaire.", "translation": "C''est un monastère ancien."}], "unitId": "eg.v.monastere_saint_macaire"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monastere_baramous', 'eg', 'le monastère de Baramous', 'monastère de Wadi Natroun, dont le nom veut dire « des Romains »', 'Baramous est un monastère de Wadi Natroun. Son nom signifie « des Romains » : une tradition parle de deux princes romains devenus moines.', '[{"text": "Baramous veut dire « des Romains ».", "translation": "Il est à Wadi Natroun."}, {"text": "Deux princes y sont devenus moines.", "translation": "C''est la tradition."}]'::jsonb, null, '{"id": "eg.d.monastere_baramous", "word": "le monastère de Baramous", "translation": "monastère de Wadi Natroun, dont le nom veut dire « des Romains »", "partOfSpeech": "place", "explanation": "Baramous est un monastère de Wadi Natroun. Son nom signifie « des Romains » : une tradition parle de deux princes romains devenus moines.", "examples": [{"text": "Baramous veut dire « des Romains ».", "translation": "Il est à Wadi Natroun."}, {"text": "Deux princes y sont devenus moines.", "translation": "C''est la tradition."}], "unitId": "eg.v.monastere_baramous"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monastere_anba_bishoy', 'eg', 'le monastère Anba Bishoy', 'monastère de Wadi Natroun, où le pape Chenouda III est enterré', 'Anba Bishoy porte le nom de saint Bishoy. C''est un des quatre monastères de Wadi Natroun. Le pape Chenouda III y est enterré.', '[{"text": "Chenouda III est enterré à Anba Bishoy.", "translation": "Le monastère est à Wadi Natroun."}, {"text": "Anba veut dire « père ».", "translation": "C''est un titre de respect."}]'::jsonb, null, '{"id": "eg.d.monastere_anba_bishoy", "word": "le monastère Anba Bishoy", "translation": "monastère de Wadi Natroun, où le pape Chenouda III est enterré", "partOfSpeech": "place", "explanation": "Anba Bishoy porte le nom de saint Bishoy. C''est un des quatre monastères de Wadi Natroun. Le pape Chenouda III y est enterré.", "examples": [{"text": "Chenouda III est enterré à Anba Bishoy.", "translation": "Le monastère est à Wadi Natroun."}, {"text": "Anba veut dire « père ».", "translation": "C''est un titre de respect."}], "unitId": "eg.v.monastere_anba_bishoy"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.monastere_des_syriens', 'eg', 'le monastère des Syriens', 'monastère de Wadi Natroun, nommé d''après des moines venus de Syrie', 'Le monastère des Syriens doit son nom à des moines de Syrie qui l''ont habité au Moyen Âge. Il garde de précieux manuscrits.', '[{"text": "Le monastère des Syriens est à Wadi Natroun.", "translation": "Des moines de Syrie y ont vécu."}, {"text": "Il garde des manuscrits anciens.", "translation": "C''est un quatrième monastère."}]'::jsonb, null, '{"id": "eg.d.monastere_des_syriens", "word": "le monastère des Syriens", "translation": "monastère de Wadi Natroun, nommé d''après des moines venus de Syrie", "partOfSpeech": "place", "explanation": "Le monastère des Syriens doit son nom à des moines de Syrie qui l''ont habité au Moyen Âge. Il garde de précieux manuscrits.", "examples": [{"text": "Le monastère des Syriens est à Wadi Natroun.", "translation": "Des moines de Syrie y ont vécu."}, {"text": "Il garde des manuscrits anciens.", "translation": "C''est un quatrième monastère."}], "unitId": "eg.v.monastere_des_syriens"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.agpeya', 'eg', 'l''Agpeya', 'le livre des heures copte', 'L''Agpeya est le livre des prières de la journée dans l''Église copte. Son nom vient du copte agp, « heure ».', '[{"text": "Ouvre ton Agpeya à la bonne heure.", "translation": "Chaque heure a sa page."}, {"text": "L''Agpeya s''ouvre sur le psaume 119.", "translation": "Le verset des sept louanges."}]'::jsonb, null, '{"id": "eg.d.agpeya", "word": "l''Agpeya", "translation": "le livre des heures copte", "partOfSpeech": "work", "explanation": "L''Agpeya est le livre des prières de la journée dans l''Église copte. Son nom vient du copte agp, « heure ».", "examples": [{"text": "Ouvre ton Agpeya à la bonne heure.", "translation": "Chaque heure a sa page."}, {"text": "L''Agpeya s''ouvre sur le psaume 119.", "translation": "Le verset des sept louanges."}], "unitId": "eg.v.agpeya"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sept_heures', 'eg', 'les sept heures', 'les sept prières de la journée et de la nuit', 'Prime, Tierce, Sexte, None, Vêpres, Complies et Minuit : sept moments répartis sur vingt-quatre heures. On y ajoute la prière du voile.', '[{"text": "Prime ouvre la journée.", "translation": "Minuit la ferme dans la veille."}, {"text": "Sept heures, comme sept louanges.", "translation": "Le chiffre vient du psaume 119."}]'::jsonb, null, '{"id": "eg.d.sept_heures", "word": "les sept heures", "translation": "les sept prières de la journée et de la nuit", "partOfSpeech": "concept", "explanation": "Prime, Tierce, Sexte, None, Vêpres, Complies et Minuit : sept moments répartis sur vingt-quatre heures. On y ajoute la prière du voile.", "examples": [{"text": "Prime ouvre la journée.", "translation": "Minuit la ferme dans la veille."}, {"text": "Sept heures, comme sept louanges.", "translation": "Le chiffre vient du psaume 119."}], "unitId": "eg.v.sept_heures"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.psaume_119_164', 'eg', 'le psaume 119, 164', '« Sept fois le jour je te loue »', 'Verset (118, 164 dans la Septante) qui ouvre l''Agpeya et donne l''idée de louer Dieu sept fois par jour.', '[{"text": "« Sept fois le jour je te loue. »", "translation": "Le verset des sept heures."}, {"text": "L''Agpeya commence par ce verset.", "translation": "Il fonde la règle."}]'::jsonb, null, '{"id": "eg.d.psaume_119_164", "word": "le psaume 119, 164", "translation": "« Sept fois le jour je te loue »", "partOfSpeech": "work", "explanation": "Verset (118, 164 dans la Septante) qui ouvre l''Agpeya et donne l''idée de louer Dieu sept fois par jour.", "examples": [{"text": "« Sept fois le jour je te loue. »", "translation": "Le verset des sept heures."}, {"text": "L''Agpeya commence par ce verset.", "translation": "Il fonde la règle."}], "unitId": "eg.v.psaume_119_164"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.daniel_prophete', 'eg', 'le prophète Daniel', 'prophète qui prie trois fois par jour à Babylone', 'Exilé à Babylone, Daniel continue de prier trois fois par jour à genoux, vers Jérusalem, même quand le roi l''interdit.', '[{"text": "Daniel prie malgré l''interdit.", "translation": "On le jette dans la fosse aux lions."}, {"text": "Daniel est un modèle de fidélité.", "translation": "Sa prière a des heures fixes."}]'::jsonb, null, '{"id": "eg.d.daniel_prophete", "word": "le prophète Daniel", "translation": "prophète qui prie trois fois par jour à Babylone", "partOfSpeech": "person", "explanation": "Exilé à Babylone, Daniel continue de prier trois fois par jour à genoux, vers Jérusalem, même quand le roi l''interdit.", "examples": [{"text": "Daniel prie malgré l''interdit.", "translation": "On le jette dans la fosse aux lions."}, {"text": "Daniel est un modèle de fidélité.", "translation": "Sa prière a des heures fixes."}], "unitId": "eg.v.daniel_prophete"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.prier_sans_cesse', 'eg', 'prier sans cesse', 'conseil de saint Paul (1 Th 5, 17)', 'Prier sans cesse ne veut pas dire réciter toute la journée, mais garder Dieu présent. Les heures de prière en donnent les repères.', '[{"text": "« Priez sans cesse. »", "translation": "Une phrase de saint Paul."}, {"text": "Les heures aident à prier sans cesse.", "translation": "Ce sont des rendez-vous avec Dieu."}]'::jsonb, null, '{"id": "eg.d.prier_sans_cesse", "word": "prier sans cesse", "translation": "conseil de saint Paul (1 Th 5, 17)", "partOfSpeech": "concept", "explanation": "Prier sans cesse ne veut pas dire réciter toute la journée, mais garder Dieu présent. Les heures de prière en donnent les repères.", "examples": [{"text": "« Priez sans cesse. »", "translation": "Une phrase de saint Paul."}, {"text": "Les heures aident à prier sans cesse.", "translation": "Ce sont des rendez-vous avec Dieu."}], "unitId": "eg.v.prier_sans_cesse"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.regle_de_priere', 'eg', 'la règle de prière', 'ensemble des heures que le fidèle s''engage à prier', 'La règle de prière est le programme de prière du fidèle. On la choisit avec son père de confession, et elle peut grandir peu à peu.', '[{"text": "Il commence par une règle de prière simple.", "translation": "Une ou deux heures par jour."}, {"text": "La règle donne des repères.", "translation": "On l''adapte à sa vie."}]'::jsonb, null, '{"id": "eg.d.regle_de_priere", "word": "la règle de prière", "translation": "ensemble des heures que le fidèle s''engage à prier", "partOfSpeech": "concept", "explanation": "La règle de prière est le programme de prière du fidèle. On la choisit avec son père de confession, et elle peut grandir peu à peu.", "examples": [{"text": "Il commence par une règle de prière simple.", "translation": "Une ou deux heures par jour."}, {"text": "La règle donne des repères.", "translation": "On l''adapte à sa vie."}], "unitId": "eg.v.regle_de_priere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.prime_heure', 'eg', 'Prime', 'prière de 6 h : l''incarnation et la Résurrection', 'Prime vient du latin « première ». C''est la première heure de l''Agpeya, au lever du jour, souvent appelée Baker en copte.', '[{"text": "Prime se prie vers 6 h.", "translation": "Le soleil se lève."}, {"text": "Prime remercie pour la nuit.", "translation": "On confie la journée à Dieu."}]'::jsonb, null, '{"id": "eg.d.prime_heure", "word": "Prime", "translation": "prière de 6 h : l''incarnation et la Résurrection", "partOfSpeech": "event", "explanation": "Prime vient du latin « première ». C''est la première heure de l''Agpeya, au lever du jour, souvent appelée Baker en copte.", "examples": [{"text": "Prime se prie vers 6 h.", "translation": "Le soleil se lève."}, {"text": "Prime remercie pour la nuit.", "translation": "On confie la journée à Dieu."}], "unitId": "eg.v.prime_heure"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tierce', 'eg', 'Tierce', 'prière de 9 h : le procès devant Pilate et la Pentecôte', 'Tierce vient du latin « troisième » : c''est la troisième heure du jour, 9 h. Elle est priée avant chaque messe.', '[{"text": "Tierce rappelle le procès devant Pilate.", "translation": "Le Christ est jugé."}, {"text": "Tierce rappelle la Pentecôte.", "translation": "L''Esprit descend sur les apôtres."}]'::jsonb, null, '{"id": "eg.d.tierce", "word": "Tierce", "translation": "prière de 9 h : le procès devant Pilate et la Pentecôte", "partOfSpeech": "event", "explanation": "Tierce vient du latin « troisième » : c''est la troisième heure du jour, 9 h. Elle est priée avant chaque messe.", "examples": [{"text": "Tierce rappelle le procès devant Pilate.", "translation": "Le Christ est jugé."}, {"text": "Tierce rappelle la Pentecôte.", "translation": "L''Esprit descend sur les apôtres."}], "unitId": "eg.v.tierce"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sexte', 'eg', 'Sexte', 'prière de midi : la crucifixion', 'Sexte vient du latin « sixième » : c''est la sixième heure du jour, midi. Elle est priée avant chaque messe, comme Tierce.', '[{"text": "Sexte rappelle la crucifixion.", "translation": "À midi, le Christ est sur la croix."}, {"text": "Pierre prie à la sixième heure.", "translation": "Ac 10, 9."}]'::jsonb, null, '{"id": "eg.d.sexte", "word": "Sexte", "translation": "prière de midi : la crucifixion", "partOfSpeech": "event", "explanation": "Sexte vient du latin « sixième » : c''est la sixième heure du jour, midi. Elle est priée avant chaque messe, comme Tierce.", "examples": [{"text": "Sexte rappelle la crucifixion.", "translation": "À midi, le Christ est sur la croix."}, {"text": "Pierre prie à la sixième heure.", "translation": "Ac 10, 9."}], "unitId": "eg.v.sexte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.heure_biblique', 'eg', 'l''heure biblique', 'manière de compter : le jour commence au lever du soleil, vers 6 h', 'Dans la Bible, la première heure suit le lever du soleil. La troisième heure est donc 9 h, la sixième heure midi et la neuvième heure 15 h.', '[{"text": "La neuvième heure, c''est 15 h.", "translation": "On ajoute 6 au numéro de l''heure."}, {"text": "La sixième heure, c''est midi.", "translation": "6 + 6 = 12."}]'::jsonb, null, '{"id": "eg.d.heure_biblique", "word": "l''heure biblique", "translation": "manière de compter : le jour commence au lever du soleil, vers 6 h", "partOfSpeech": "concept", "explanation": "Dans la Bible, la première heure suit le lever du soleil. La troisième heure est donc 9 h, la sixième heure midi et la neuvième heure 15 h.", "examples": [{"text": "La neuvième heure, c''est 15 h.", "translation": "On ajoute 6 au numéro de l''heure."}, {"text": "La sixième heure, c''est midi.", "translation": "6 + 6 = 12."}], "unitId": "eg.v.heure_biblique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.crucifixion_du_christ', 'eg', 'la crucifixion', 'le Christ est cloué sur la croix, au Golgotha', 'Le Christ est crucifié et meurt sur la croix pour nous sauver. Sexte, à midi, rappelle la crucifixion ; la None, à 15 h, rappelle sa mort.', '[{"text": "À midi, les ténèbres couvrent la terre.", "translation": "Mt 27, 45."}, {"text": "Sexte nous met au pied de la croix.", "translation": "On remercie le Christ."}]'::jsonb, null, '{"id": "eg.d.crucifixion_du_christ", "word": "la crucifixion", "translation": "le Christ est cloué sur la croix, au Golgotha", "partOfSpeech": "event", "explanation": "Le Christ est crucifié et meurt sur la croix pour nous sauver. Sexte, à midi, rappelle la crucifixion ; la None, à 15 h, rappelle sa mort.", "examples": [{"text": "À midi, les ténèbres couvrent la terre.", "translation": "Mt 27, 45."}, {"text": "Sexte nous met au pied de la croix.", "translation": "On remercie le Christ."}], "unitId": "eg.v.crucifixion_du_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.none_heure', 'eg', 'la None', 'prière de 15 h : la mort du Christ sur la croix', 'None vient du latin « neuvième » : c''est la neuvième heure du jour, 15 h. On la prie aussi les jours de jeûne.', '[{"text": "La None se prie à 15 h.", "translation": "Neuvième heure."}, {"text": "La None rappelle la mort du Christ.", "translation": "Mt 27, 46-50."}]'::jsonb, null, '{"id": "eg.d.none_heure", "word": "la None", "translation": "prière de 15 h : la mort du Christ sur la croix", "partOfSpeech": "event", "explanation": "None vient du latin « neuvième » : c''est la neuvième heure du jour, 15 h. On la prie aussi les jours de jeûne.", "examples": [{"text": "La None se prie à 15 h.", "translation": "Neuvième heure."}, {"text": "La None rappelle la mort du Christ.", "translation": "Mt 27, 46-50."}], "unitId": "eg.v.none_heure"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.vepres', 'eg', 'Vêpres', 'prière du coucher du soleil : la descente de la croix', 'Vêpres vient du latin vesper, « soir ». On les prie vers 17-18 h, au coucher du soleil.', '[{"text": "Les Vêpres rappellent la descente de la croix.", "translation": "Joseph d''Arimathie."}, {"text": "On remercie pour la journée.", "translation": "Le soleil se couche."}]'::jsonb, null, '{"id": "eg.d.vepres", "word": "Vêpres", "translation": "prière du coucher du soleil : la descente de la croix", "partOfSpeech": "event", "explanation": "Vêpres vient du latin vesper, « soir ». On les prie vers 17-18 h, au coucher du soleil.", "examples": [{"text": "Les Vêpres rappellent la descente de la croix.", "translation": "Joseph d''Arimathie."}, {"text": "On remercie pour la journée.", "translation": "Le soleil se couche."}], "unitId": "eg.v.vepres"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.complies', 'eg', 'Complies', 'prière de 21 h : l''ensevelissement du Christ', 'Complies vient du latin completorium, « ce qui achève » la journée. C''est la dernière prière avant de dormir.', '[{"text": "Les Complies se prient vers 21 h.", "translation": "Avant le sommeil."}, {"text": "Elles rappellent l''ensevelissement.", "translation": "Le corps du Christ au tombeau."}]'::jsonb, null, '{"id": "eg.d.complies", "word": "Complies", "translation": "prière de 21 h : l''ensevelissement du Christ", "partOfSpeech": "event", "explanation": "Complies vient du latin completorium, « ce qui achève » la journée. C''est la dernière prière avant de dormir.", "examples": [{"text": "Les Complies se prient vers 21 h.", "translation": "Avant le sommeil."}, {"text": "Elles rappellent l''ensevelissement.", "translation": "Le corps du Christ au tombeau."}], "unitId": "eg.v.complies"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.descente_de_la_croix', 'eg', 'la descente de la croix', 'le corps du Christ est descendu de la croix au soir', 'Joseph d''Arimathie demande à Pilate le corps de Jésus et le descend de la croix (Mc 15, 42-46). C''est ce que rappellent les Vêpres.', '[{"text": "Joseph d''Arimathie demande le corps.", "translation": "Il va chez Pilate."}, {"text": "Le soir tombe.", "translation": "Le corps est descendu."}]'::jsonb, null, '{"id": "eg.d.descente_de_la_croix", "word": "la descente de la croix", "translation": "le corps du Christ est descendu de la croix au soir", "partOfSpeech": "event", "explanation": "Joseph d''Arimathie demande à Pilate le corps de Jésus et le descend de la croix (Mc 15, 42-46). C''est ce que rappellent les Vêpres.", "examples": [{"text": "Joseph d''Arimathie demande le corps.", "translation": "Il va chez Pilate."}, {"text": "Le soir tombe.", "translation": "Le corps est descendu."}], "unitId": "eg.v.descente_de_la_croix"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ensevelissement_du_christ', 'eg', 'l''ensevelissement du Christ', 'le corps du Christ est mis au tombeau', 'Après la descente de la croix, le corps du Christ est enveloppé et mis au tombeau. Les Complies rappellent cet ensevelissement.', '[{"text": "Le corps est mis au tombeau.", "translation": "Avant le sabbat."}, {"text": "Complies rappellent ce moment.", "translation": "Et le Jugement dernier."}]'::jsonb, null, '{"id": "eg.d.ensevelissement_du_christ", "word": "l''ensevelissement du Christ", "translation": "le corps du Christ est mis au tombeau", "partOfSpeech": "event", "explanation": "Après la descente de la croix, le corps du Christ est enveloppé et mis au tombeau. Les Complies rappellent cet ensevelissement.", "examples": [{"text": "Le corps est mis au tombeau.", "translation": "Avant le sabbat."}, {"text": "Complies rappellent ce moment.", "translation": "Et le Jugement dernier."}], "unitId": "eg.v.ensevelissement_du_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.bon_larron', 'eg', 'le bon larron', 'malfaiteur crucifié avec Jésus, à qui il promet le paradis', 'Un des deux malfaiteurs crucifiés avec Jésus reconnaît sa faute et demande : « Souviens-toi de moi ». Jésus lui répond : « Aujourd''hui tu seras avec moi dans le paradis » (Lc 23, 43).', '[{"text": "Le bon larron demande le souvenir du Christ.", "translation": "Il croit au dernier moment."}, {"text": "« Aujourd''hui tu seras avec moi dans le paradis. »", "translation": "Lc 23, 43."}]'::jsonb, null, '{"id": "eg.d.bon_larron", "word": "le bon larron", "translation": "malfaiteur crucifié avec Jésus, à qui il promet le paradis", "partOfSpeech": "person", "explanation": "Un des deux malfaiteurs crucifiés avec Jésus reconnaît sa faute et demande : « Souviens-toi de moi ». Jésus lui répond : « Aujourd''hui tu seras avec moi dans le paradis » (Lc 23, 43).", "examples": [{"text": "Le bon larron demande le souvenir du Christ.", "translation": "Il croit au dernier moment."}, {"text": "« Aujourd''hui tu seras avec moi dans le paradis. »", "translation": "Lc 23, 43."}], "unitId": "eg.v.bon_larron"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.minuit_heure', 'eg', 'Minuit', 'prière de la nuit : la seconde venue du Christ', 'Minuit est la dernière heure de l''Agpeya, celle de la veille. C''est aussi la première étape de la tasbeha.', '[{"text": "Minuit rappelle la seconde venue.", "translation": "Il faut veiller."}, {"text": "Minuit se prie en trois veilles.", "translation": "Trois parties."}]'::jsonb, null, '{"id": "eg.d.minuit_heure", "word": "Minuit", "translation": "prière de la nuit : la seconde venue du Christ", "partOfSpeech": "event", "explanation": "Minuit est la dernière heure de l''Agpeya, celle de la veille. C''est aussi la première étape de la tasbeha.", "examples": [{"text": "Minuit rappelle la seconde venue.", "translation": "Il faut veiller."}, {"text": "Minuit se prie en trois veilles.", "translation": "Trois parties."}], "unitId": "eg.v.minuit_heure"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.dix_vierges', 'eg', 'les dix vierges', 'parabole de Mt 25, 1-13 sur l''attente de l''époux', 'Cinq vierges sages ont de l''huile, cinq vierges folles n''en ont pas. À minuit, un cri retentit : « Voici l''époux ! ». Il faut être prêt à tout moment.', '[{"text": "Les vierges sages ont de l''huile.", "translation": "Elles entrent avec l''époux."}, {"text": "Minuit rappelle cette parabole.", "translation": "Veillez, car vous ne savez ni le jour ni l''heure."}]'::jsonb, null, '{"id": "eg.d.dix_vierges", "word": "les dix vierges", "translation": "parabole de Mt 25, 1-13 sur l''attente de l''époux", "partOfSpeech": "work", "explanation": "Cinq vierges sages ont de l''huile, cinq vierges folles n''en ont pas. À minuit, un cri retentit : « Voici l''époux ! ». Il faut être prêt à tout moment.", "examples": [{"text": "Les vierges sages ont de l''huile.", "translation": "Elles entrent avec l''époux."}, {"text": "Minuit rappelle cette parabole.", "translation": "Veillez, car vous ne savez ni le jour ni l''heure."}], "unitId": "eg.v.dix_vierges"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trois_veilles', 'eg', 'les trois veilles', 'les trois parties de la prière de minuit', 'La prière de minuit est divisée en trois veilles, avec leurs psaumes. Elles rappellent les trois prières du Christ à Gethsémani.', '[{"text": "Trois veilles, trois prières.", "translation": "Gethsémani."}, {"text": "Chaque veille a ses psaumes.", "translation": "On veille et on prie."}]'::jsonb, null, '{"id": "eg.d.trois_veilles", "word": "les trois veilles", "translation": "les trois parties de la prière de minuit", "partOfSpeech": "concept", "explanation": "La prière de minuit est divisée en trois veilles, avec leurs psaumes. Elles rappellent les trois prières du Christ à Gethsémani.", "examples": [{"text": "Trois veilles, trois prières.", "translation": "Gethsémani."}, {"text": "Chaque veille a ses psaumes.", "translation": "On veille et on prie."}], "unitId": "eg.v.trois_veilles"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.gethsemani', 'eg', 'Gethsémani', 'jardin où le Christ prie trois fois avant son arrestation', 'Au jardin de Gethsémani, le Christ prie trois fois et demande à ses disciples : « Veillez et priez » (Mt 26, 41). Les disciples s''endorment.', '[{"text": "Le Christ prie trois fois à Gethsémani.", "translation": "Mt 26, 36-46."}, {"text": "Les disciples dorment.", "translation": "« Veillez et priez. »"}]'::jsonb, null, '{"id": "eg.d.gethsemani", "word": "Gethsémani", "translation": "jardin où le Christ prie trois fois avant son arrestation", "partOfSpeech": "place", "explanation": "Au jardin de Gethsémani, le Christ prie trois fois et demande à ses disciples : « Veillez et priez » (Mt 26, 41). Les disciples s''endorment.", "examples": [{"text": "Le Christ prie trois fois à Gethsémani.", "translation": "Mt 26, 36-46."}, {"text": "Les disciples dorment.", "translation": "« Veillez et priez. »"}], "unitId": "eg.v.gethsemani"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.priere_du_voile', 'eg', 'la prière du voile', 'prière à part, en fin d''Agpeya : examen de conscience', 'En arabe setar, « voile ». Ce n''est pas l''une des sept heures. Elle s''adresse surtout aux évêques, aux prêtres et aux moines.', '[{"text": "La prière du voile est un examen de conscience.", "translation": "Elle est à la fin de l''Agpeya."}, {"text": "Elle est surtout pour le clergé et les moines.", "translation": "Hors des sept heures."}]'::jsonb, null, '{"id": "eg.d.priere_du_voile", "word": "la prière du voile", "translation": "prière à part, en fin d''Agpeya : examen de conscience", "partOfSpeech": "event", "explanation": "En arabe setar, « voile ». Ce n''est pas l''une des sept heures. Elle s''adresse surtout aux évêques, aux prêtres et aux moines.", "examples": [{"text": "La prière du voile est un examen de conscience.", "translation": "Elle est à la fin de l''Agpeya."}, {"text": "Elle est surtout pour le clergé et les moines.", "translation": "Hors des sept heures."}], "unitId": "eg.v.priere_du_voile"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.examen_de_conscience', 'eg', 'l''examen de conscience', 'regarder sa journée devant Dieu pour demander pardon', 'Examiner sa conscience, c''est relire sa journée devant Dieu, reconnaître ses fautes et demander pardon.', '[{"text": "Le soir, il fait son examen de conscience.", "translation": "Il relit sa journée."}, {"text": "La prière du voile en est un.", "translation": "Surtout pour le clergé."}]'::jsonb, null, '{"id": "eg.d.examen_de_conscience", "word": "l''examen de conscience", "translation": "regarder sa journée devant Dieu pour demander pardon", "partOfSpeech": "concept", "explanation": "Examiner sa conscience, c''est relire sa journée devant Dieu, reconnaître ses fautes et demander pardon.", "examples": [{"text": "Le soir, il fait son examen de conscience.", "translation": "Il relit sa journée."}, {"text": "La prière du voile en est un.", "translation": "Surtout pour le clergé."}], "unitId": "eg.v.examen_de_conscience"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.seconde_venue_du_christ', 'eg', 'la seconde venue du Christ', 'retour du Christ à la fin des temps', 'Le Christ reviendra à la fin des temps pour juger. L''Église veille en l''attendant, surtout la nuit.', '[{"text": "Minuit rappelle la seconde venue.", "translation": "Veiller."}, {"text": "Le Christ vient de l''orient.", "translation": "Mt 24, 27."}]'::jsonb, null, '{"id": "eg.d.seconde_venue_du_christ", "word": "la seconde venue du Christ", "translation": "retour du Christ à la fin des temps", "partOfSpeech": "event", "explanation": "Le Christ reviendra à la fin des temps pour juger. L''Église veille en l''attendant, surtout la nuit.", "examples": [{"text": "Minuit rappelle la seconde venue.", "translation": "Veiller."}, {"text": "Le Christ vient de l''orient.", "translation": "Mt 24, 27."}], "unitId": "eg.v.seconde_venue_du_christ"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.kyrie_eleison', 'eg', 'Kyrie eleison', '« Seigneur, aie pitié » (grec)', 'Cri de supplication en grec, répété dans la liturgie copte. Dans les heures, on le dit 41 fois.', '[{"text": "Kyrie eleison, Kyrie eleison.", "translation": "Seigneur, aie pitié."}, {"text": "On le dit 41 fois à chaque heure.", "translation": "C''est l''étape 7."}]'::jsonb, null, '{"id": "eg.d.kyrie_eleison", "word": "Kyrie eleison", "translation": "« Seigneur, aie pitié » (grec)", "partOfSpeech": "expression", "explanation": "Cri de supplication en grec, répété dans la liturgie copte. Dans les heures, on le dit 41 fois.", "examples": [{"text": "Kyrie eleison, Kyrie eleison.", "translation": "Seigneur, aie pitié."}, {"text": "On le dit 41 fois à chaque heure.", "translation": "C''est l''étape 7."}], "unitId": "eg.v.kyrie_eleison"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.quarante_et_un_kyrie', 'eg', 'les 41 Kyrie', '39 coups de fouet, la couronne d''épines et la lance', 'Selon la tradition, 41 rappelle 39 coups de fouet, plus la couronne d''épines, plus la lance. À chaque Kyrie, on pense à la souffrance du Christ.', '[{"text": "39 + 1 + 1 = 41.", "translation": "Fouet, couronne, lance."}, {"text": "On compte 41 Kyrie à chaque heure.", "translation": "Debout."}]'::jsonb, null, '{"id": "eg.d.quarante_et_un_kyrie", "word": "les 41 Kyrie", "translation": "39 coups de fouet, la couronne d''épines et la lance", "partOfSpeech": "concept", "explanation": "Selon la tradition, 41 rappelle 39 coups de fouet, plus la couronne d''épines, plus la lance. À chaque Kyrie, on pense à la souffrance du Christ.", "examples": [{"text": "39 + 1 + 1 = 41.", "translation": "Fouet, couronne, lance."}, {"text": "On compte 41 Kyrie à chaque heure.", "translation": "Debout."}], "unitId": "eg.v.quarante_et_un_kyrie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.psaume_50', 'eg', 'le psaume 50', 'prière de repentance de David (51 dans la Bible hébraïque)', '« Aie pitié de moi, ô Dieu, selon ta grande bonté ». David le prie après sa faute. On le dit à chaque heure.', '[{"text": "Le psaume 50 ouvre chaque heure.", "translation": "On demande pardon."}, {"text": "Il est de David.", "translation": "Psaume de repentance."}]'::jsonb, null, '{"id": "eg.d.psaume_50", "word": "le psaume 50", "translation": "prière de repentance de David (51 dans la Bible hébraïque)", "partOfSpeech": "work", "explanation": "« Aie pitié de moi, ô Dieu, selon ta grande bonté ». David le prie après sa faute. On le dit à chaque heure.", "examples": [{"text": "Le psaume 50 ouvre chaque heure.", "translation": "On demande pardon."}, {"text": "Il est de David.", "translation": "Psaume de repentance."}], "unitId": "eg.v.psaume_50"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.metanie', 'eg', 'la métanie', 'prosternation : on s''incline jusqu''à terre', 'Du grec metanoia, « repentir » : la métanie est une prosternation. Dans l''Agpeya, on en fait par exemple au nom de la Trinité.', '[{"text": "Il fait une métanie.", "translation": "Il s''incline jusqu''à terre."}, {"text": "Trois métanies au nom de la Trinité.", "translation": "Père, Fils, Saint-Esprit."}]'::jsonb, null, '{"id": "eg.d.metanie", "word": "la métanie", "translation": "prosternation : on s''incline jusqu''à terre", "partOfSpeech": "concept", "explanation": "Du grec metanoia, « repentir » : la métanie est une prosternation. Dans l''Agpeya, on en fait par exemple au nom de la Trinité.", "examples": [{"text": "Il fait une métanie.", "translation": "Il s''incline jusqu''à terre."}, {"text": "Trois métanies au nom de la Trinité.", "translation": "Père, Fils, Saint-Esprit."}], "unitId": "eg.v.metanie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.signe_de_croix_priere', 'eg', 'le signe de croix', 'geste fait au nom du Père, du Fils et du Saint-Esprit', 'On fait le signe de croix de la main droite, au nom de la Sainte Trinité, pour ouvrir et fermer la prière.', '[{"text": "Il fait le signe de croix avant de prier.", "translation": "Au nom de la Trinité."}, {"text": "La croix ouvre la prière.", "translation": "Et la ferme."}]'::jsonb, null, '{"id": "eg.d.signe_de_croix_priere", "word": "le signe de croix", "translation": "geste fait au nom du Père, du Fils et du Saint-Esprit", "partOfSpeech": "concept", "explanation": "On fait le signe de croix de la main droite, au nom de la Sainte Trinité, pour ouvrir et fermer la prière.", "examples": [{"text": "Il fait le signe de croix avant de prier.", "translation": "Au nom de la Trinité."}, {"text": "La croix ouvre la prière.", "translation": "Et la ferme."}], "unitId": "eg.v.signe_de_croix_priere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.notre_pere', 'eg', 'le Notre Père', 'prière que le Christ a enseignée à ses disciples (Mt 6, 9-13)', 'Le Christ l''enseigne lui-même à ses disciples. Il ouvre chaque heure de l''Agpeya.', '[{"text": "L''heure commence par le Notre Père.", "translation": "Introduction."}, {"text": "C''est la prière du Seigneur.", "translation": "Mt 6, 9-13."}]'::jsonb, null, '{"id": "eg.d.notre_pere", "word": "le Notre Père", "translation": "prière que le Christ a enseignée à ses disciples (Mt 6, 9-13)", "partOfSpeech": "work", "explanation": "Le Christ l''enseigne lui-même à ses disciples. Il ouvre chaque heure de l''Agpeya.", "examples": [{"text": "L''heure commence par le Notre Père.", "translation": "Introduction."}, {"text": "C''est la prière du Seigneur.", "translation": "Mt 6, 9-13."}], "unitId": "eg.v.notre_pere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.litanies_de_l_heure', 'eg', 'les litanies de l''heure', 'tropaires de supplication, dont un à la Vierge', 'Prières courtes de demande, dont un tropaire à la Vierge. Elles précèdent les 41 Kyrie.', '[{"text": "Les litanies précèdent les Kyrie.", "translation": "Étape 6."}, {"text": "Un tropaire s''adresse à la Vierge.", "translation": "Elle prie pour nous."}]'::jsonb, null, '{"id": "eg.d.litanies_de_l_heure", "word": "les litanies de l''heure", "translation": "tropaires de supplication, dont un à la Vierge", "partOfSpeech": "concept", "explanation": "Prières courtes de demande, dont un tropaire à la Vierge. Elles précèdent les 41 Kyrie.", "examples": [{"text": "Les litanies précèdent les Kyrie.", "translation": "Étape 6."}, {"text": "Un tropaire s''adresse à la Vierge.", "translation": "Elle prie pour nous."}], "unitId": "eg.v.litanies_de_l_heure"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.voile_pour_prier', 'eg', 'le voile des femmes', 'les femmes se couvrent la tête pour prier (1 Co 11, 5-6)', 'Saint Paul demande aux femmes de se couvrir la tête quand elles prient. C''est un signe de respect devant Dieu.', '[{"text": "Elle met son voile pour prier.", "translation": "1 Co 11, 5-6."}, {"text": "Dans l''église aussi.", "translation": "Même règle."}]'::jsonb, null, '{"id": "eg.d.voile_pour_prier", "word": "le voile des femmes", "translation": "les femmes se couvrent la tête pour prier (1 Co 11, 5-6)", "partOfSpeech": "concept", "explanation": "Saint Paul demande aux femmes de se couvrir la tête quand elles prient. C''est un signe de respect devant Dieu.", "examples": [{"text": "Elle met son voile pour prier.", "translation": "1 Co 11, 5-6."}, {"text": "Dans l''église aussi.", "translation": "Même règle."}], "unitId": "eg.v.voile_pour_prier"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.est_direction_de_priere', 'eg', 'l''est (l''orient)', 'direction de la prière : côté du paradis, de la lumière et du retour du Christ', 'On prie tourné vers l''est, là où le soleil se lève. Pour six raisons : le paradis perdu, la seconde venue, le soleil de justice, l''étoile des mages, la croix et le baptême.', '[{"text": "Il prie tourné vers l''est.", "translation": "Le soleil se lève."}, {"text": "Les églises sont tournées vers l''est.", "translation": "Le même sens."}]'::jsonb, null, '{"id": "eg.d.est_direction_de_priere", "word": "l''est (l''orient)", "translation": "direction de la prière : côté du paradis, de la lumière et du retour du Christ", "partOfSpeech": "concept", "explanation": "On prie tourné vers l''est, là où le soleil se lève. Pour six raisons : le paradis perdu, la seconde venue, le soleil de justice, l''étoile des mages, la croix et le baptême.", "examples": [{"text": "Il prie tourné vers l''est.", "translation": "Le soleil se lève."}, {"text": "Les églises sont tournées vers l''est.", "translation": "Le même sens."}], "unitId": "eg.v.est_direction_de_priere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.paradis_perdu', 'eg', 'le paradis perdu', 'le jardin d''Éden, à l''orient, que l''homme a quitté par le péché', 'Dieu planta un jardin en Éden, à l''orient (Gn 2, 8). En priant vers l''est, on regarde vers cette patrie perdue et on désire y revenir.', '[{"text": "Le paradis perdu est à l''orient.", "translation": "On veut y revenir."}, {"text": "Saint Basile le Grand donne cette raison.", "translation": "Gn 2, 8."}]'::jsonb, null, '{"id": "eg.d.paradis_perdu", "word": "le paradis perdu", "translation": "le jardin d''Éden, à l''orient, que l''homme a quitté par le péché", "partOfSpeech": "concept", "explanation": "Dieu planta un jardin en Éden, à l''orient (Gn 2, 8). En priant vers l''est, on regarde vers cette patrie perdue et on désire y revenir.", "examples": [{"text": "Le paradis perdu est à l''orient.", "translation": "On veut y revenir."}, {"text": "Saint Basile le Grand donne cette raison.", "translation": "Gn 2, 8."}], "unitId": "eg.v.paradis_perdu"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.soleil_de_justice', 'eg', 'le soleil de justice', 'nom du Christ, lumière du salut, donné par le prophète Malachie', 'Le prophète Malachie annonce le « soleil de justice » (Ml 4, 2). Le Christ est ce soleil : il se lève à l''est comme la lumière du salut.', '[{"text": "Le Christ est le soleil de justice.", "translation": "Ml 4, 2."}, {"text": "Le soleil se lève à l''est.", "translation": "Image du salut."}]'::jsonb, null, '{"id": "eg.d.soleil_de_justice", "word": "le soleil de justice", "translation": "nom du Christ, lumière du salut, donné par le prophète Malachie", "partOfSpeech": "concept", "explanation": "Le prophète Malachie annonce le « soleil de justice » (Ml 4, 2). Le Christ est ce soleil : il se lève à l''est comme la lumière du salut.", "examples": [{"text": "Le Christ est le soleil de justice.", "translation": "Ml 4, 2."}, {"text": "Le soleil se lève à l''est.", "translation": "Image du salut."}], "unitId": "eg.v.soleil_de_justice"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.etoile_des_mages', 'eg', 'l''étoile des mages', 'étoile vue à l''orient qui conduit les mages au Christ (Mt 2, 2)', 'Les mages disent : « Nous avons vu son étoile à l''orient ». Elle les conduit au Christ. Prier vers l''est, c''est suivre la même étoile.', '[{"text": "Les mages ont vu son étoile.", "translation": "À l''orient."}, {"text": "L''étoile les conduit à l''enfant.", "translation": "Mt 2, 1-12."}]'::jsonb, null, '{"id": "eg.d.etoile_des_mages", "word": "l''étoile des mages", "translation": "étoile vue à l''orient qui conduit les mages au Christ (Mt 2, 2)", "partOfSpeech": "event", "explanation": "Les mages disent : « Nous avons vu son étoile à l''orient ». Elle les conduit au Christ. Prier vers l''est, c''est suivre la même étoile.", "examples": [{"text": "Les mages ont vu son étoile.", "translation": "À l''orient."}, {"text": "L''étoile les conduit à l''enfant.", "translation": "Mt 2, 1-12."}], "unitId": "eg.v.etoile_des_mages"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.orientation_des_eglises', 'eg', 'l''orientation des églises', 'les églises sont bâties tournées vers l''est', 'Les églises sont bâties tournées vers l''est, comme dans la prière : on prie dans le même sens que celui du baptême, vers le Christ.', '[{"text": "L''église est tournée vers l''est.", "translation": "Le peuple aussi."}, {"text": "Même sens que la prière.", "translation": "Vers le Christ."}]'::jsonb, null, '{"id": "eg.d.orientation_des_eglises", "word": "l''orientation des églises", "translation": "les églises sont bâties tournées vers l''est", "partOfSpeech": "concept", "explanation": "Les églises sont bâties tournées vers l''est, comme dans la prière : on prie dans le même sens que celui du baptême, vers le Christ.", "examples": [{"text": "L''église est tournée vers l''est.", "translation": "Le peuple aussi."}, {"text": "Même sens que la prière.", "translation": "Vers le Christ."}], "unitId": "eg.v.orientation_des_eglises"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.renoncement_vers_l_ouest', 'eg', 'le renoncement à Satan, vers l''ouest', 'au baptême, on renie Satan tourné vers l''ouest', 'Au baptême, on renie Satan tourné vers l''ouest, côté des ténèbres, puis on confesse le Christ tourné vers l''est.', '[{"text": "Il renie Satan, tourné vers l''ouest.", "translation": "Avant de confesser le Christ."}, {"text": "Puis il se tourne vers l''est.", "translation": "Vers le Christ."}]'::jsonb, null, '{"id": "eg.d.renoncement_vers_l_ouest", "word": "le renoncement à Satan, vers l''ouest", "translation": "au baptême, on renie Satan tourné vers l''ouest", "partOfSpeech": "concept", "explanation": "Au baptême, on renie Satan tourné vers l''ouest, côté des ténèbres, puis on confesse le Christ tourné vers l''est.", "examples": [{"text": "Il renie Satan, tourné vers l''ouest.", "translation": "Avant de confesser le Christ."}, {"text": "Puis il se tourne vers l''est.", "translation": "Vers le Christ."}], "unitId": "eg.v.renoncement_vers_l_ouest"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tasbeha', 'eg', 'la tasbeha', 'la louange de minuit (« louange » en arabe)', 'Tasbeha est un mot arabe qui veut dire « louange ». C''est la psalmodie de minuit, chantée dans les monastères chaque nuit et en paroisse la veille d''une messe.', '[{"text": "La tasbeha commence par l''Agpeya de minuit.", "translation": "Puis Ten thino."}, {"text": "Il va à la tasbeha le samedi soir.", "translation": "Avant la messe du dimanche."}]'::jsonb, null, '{"id": "eg.d.tasbeha", "word": "la tasbeha", "translation": "la louange de minuit (« louange » en arabe)", "partOfSpeech": "work", "explanation": "Tasbeha est un mot arabe qui veut dire « louange ». C''est la psalmodie de minuit, chantée dans les monastères chaque nuit et en paroisse la veille d''une messe.", "examples": [{"text": "La tasbeha commence par l''Agpeya de minuit.", "translation": "Puis Ten thino."}, {"text": "Il va à la tasbeha le samedi soir.", "translation": "Avant la messe du dimanche."}], "unitId": "eg.v.tasbeha"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.ten_thino', 'eg', 'Ten thino', '« Levez-vous, fils de la lumière »', 'Appel en copte qui ouvre la louange : il réveille les fidèles pour louer Dieu. Les fils de la lumière sont les chrétiens (1 Th 5, 5).', '[{"text": "Ten thino réveille l''assemblée.", "translation": "Levez-vous."}, {"text": "Après l''Agpeya de minuit vient Ten thino.", "translation": "Puis les hoos."}]'::jsonb, null, '{"id": "eg.d.ten_thino", "word": "Ten thino", "translation": "« Levez-vous, fils de la lumière »", "partOfSpeech": "expression", "explanation": "Appel en copte qui ouvre la louange : il réveille les fidèles pour louer Dieu. Les fils de la lumière sont les chrétiens (1 Th 5, 5).", "examples": [{"text": "Ten thino réveille l''assemblée.", "translation": "Levez-vous."}, {"text": "Après l''Agpeya de minuit vient Ten thino.", "translation": "Puis les hoos."}], "unitId": "eg.v.ten_thino"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.fils_de_la_lumiere', 'eg', 'les fils de la lumière', 'les chrétiens appelés à veiller (1 Th 5, 5)', 'Saint Paul dit : « Vous êtes tous des fils de la lumière » (1 Th 5, 5). La tasbeha invite à se lever comme eux.', '[{"text": "Nous sommes des fils de la lumière.", "translation": "1 Th 5, 5."}, {"text": "Ten thino les appelle à se lever.", "translation": "Pour louer."}]'::jsonb, null, '{"id": "eg.d.fils_de_la_lumiere", "word": "les fils de la lumière", "translation": "les chrétiens appelés à veiller (1 Th 5, 5)", "partOfSpeech": "concept", "explanation": "Saint Paul dit : « Vous êtes tous des fils de la lumière » (1 Th 5, 5). La tasbeha invite à se lever comme eux.", "examples": [{"text": "Nous sommes des fils de la lumière.", "translation": "1 Th 5, 5."}, {"text": "Ten thino les appelle à se lever.", "translation": "Pour louer."}], "unitId": "eg.v.fils_de_la_lumiere"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.difnar', 'eg', 'le difnar', 'livre (antiphonaire) qui rappelle le saint du jour', 'Le difnar est la lecture de la tasbeha qui rappelle le saint du jour. Il joue le même rôle que le synaxaire.', '[{"text": "On lit le difnar du jour.", "translation": "Il rappelle le saint."}, {"text": "Le difnar suit la théotokie.", "translation": "Avant la conclusion."}]'::jsonb, null, '{"id": "eg.d.difnar", "word": "le difnar", "translation": "livre (antiphonaire) qui rappelle le saint du jour", "partOfSpeech": "work", "explanation": "Le difnar est la lecture de la tasbeha qui rappelle le saint du jour. Il joue le même rôle que le synaxaire.", "examples": [{"text": "On lit le difnar du jour.", "translation": "Il rappelle le saint."}, {"text": "Le difnar suit la théotokie.", "translation": "Avant la conclusion."}], "unitId": "eg.v.difnar"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.synaxaire', 'eg', 'le synaxaire', 'livre de vies de saints, lu jour après jour', 'Le synaxaire est un livre de vies de saints, lu jour après jour. Le difnar a le même rôle dans la tasbeha.', '[{"text": "On lit le synaxaire de la journée.", "translation": "Vie du saint."}, {"text": "Le synaxaire suit le calendrier.", "translation": "Un saint par jour."}]'::jsonb, null, '{"id": "eg.d.synaxaire", "word": "le synaxaire", "translation": "livre de vies de saints, lu jour après jour", "partOfSpeech": "work", "explanation": "Le synaxaire est un livre de vies de saints, lu jour après jour. Le difnar a le même rôle dans la tasbeha.", "examples": [{"text": "On lit le synaxaire de la journée.", "translation": "Vie du saint."}, {"text": "Le synaxaire suit le calendrier.", "translation": "Un saint par jour."}], "unitId": "eg.v.synaxaire"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trisagion', 'eg', 'le Trisagion', '« trois fois saint » : Saint Dieu, Saint Fort, Saint Immortel', 'Du grec « trois fois saint ». Il se dit à la fin de la tasbeha avec le Credo et le Notre Père.', '[{"text": "Le Trisagion clôt la tasbeha.", "translation": "Avec le Credo."}, {"text": "Saint Dieu, Saint Fort, Saint Immortel.", "translation": "Aie pitié de nous."}]'::jsonb, null, '{"id": "eg.d.trisagion", "word": "le Trisagion", "translation": "« trois fois saint » : Saint Dieu, Saint Fort, Saint Immortel", "partOfSpeech": "expression", "explanation": "Du grec « trois fois saint ». Il se dit à la fin de la tasbeha avec le Credo et le Notre Père.", "examples": [{"text": "Le Trisagion clôt la tasbeha.", "translation": "Avec le Credo."}, {"text": "Saint Dieu, Saint Fort, Saint Immortel.", "translation": "Aie pitié de nous."}], "unitId": "eg.v.trisagion"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.hoos', 'eg', 'le hoos', 'cantique de louange tiré de la Bible', 'Hoos est un mot copte qui veut dire « louange ». La tasbeha en compte quatre, chantés dans l''ordre.', '[{"text": "Le 1er hoos est le cantique de Moïse.", "translation": "Ex 15."}, {"text": "Quatre hoos dans la tasbeha.", "translation": "Chacun suivi d''un lobsh."}]'::jsonb, null, '{"id": "eg.d.hoos", "word": "le hoos", "translation": "cantique de louange tiré de la Bible", "partOfSpeech": "work", "explanation": "Hoos est un mot copte qui veut dire « louange ». La tasbeha en compte quatre, chantés dans l''ordre.", "examples": [{"text": "Le 1er hoos est le cantique de Moïse.", "translation": "Ex 15."}, {"text": "Quatre hoos dans la tasbeha.", "translation": "Chacun suivi d''un lobsh."}], "unitId": "eg.v.hoos"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.lobsh', 'eg', 'le lobsh', '« explication » : pièce qui commente le hoos', 'Lobsh est un mot copte qui veut dire « explication ». Il suit chaque hoos et en donne le sens.', '[{"text": "Le lobsh explique le hoos.", "translation": "Il vient juste après."}, {"text": "Quatre hoos, quatre lobsh.", "translation": "Un lobsh par hoos."}]'::jsonb, null, '{"id": "eg.d.lobsh", "word": "le lobsh", "translation": "« explication » : pièce qui commente le hoos", "partOfSpeech": "work", "explanation": "Lobsh est un mot copte qui veut dire « explication ». Il suit chaque hoos et en donne le sens.", "examples": [{"text": "Le lobsh explique le hoos.", "translation": "Il vient juste après."}, {"text": "Quatre hoos, quatre lobsh.", "translation": "Un lobsh par hoos."}], "unitId": "eg.v.lobsh"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cantique_de_moise', 'eg', 'le cantique de Moïse', '1er hoos : chant de Moïse après la traversée de la mer Rouge (Ex 15)', 'Après la traversée de la mer Rouge, Moïse et le peuple chantent leur délivrance. Ce chant est le 1er hoos.', '[{"text": "Moïse chante après la mer Rouge.", "translation": "Le 1er hoos."}, {"text": "Il symbolise la sortie de l''esclavage du péché.", "translation": "Libération."}]'::jsonb, null, '{"id": "eg.d.cantique_de_moise", "word": "le cantique de Moïse", "translation": "1er hoos : chant de Moïse après la traversée de la mer Rouge (Ex 15)", "partOfSpeech": "work", "explanation": "Après la traversée de la mer Rouge, Moïse et le peuple chantent leur délivrance. Ce chant est le 1er hoos.", "examples": [{"text": "Moïse chante après la mer Rouge.", "translation": "Le 1er hoos."}, {"text": "Il symbolise la sortie de l''esclavage du péché.", "translation": "Libération."}], "unitId": "eg.v.cantique_de_moise"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.traversee_de_la_mer_rouge', 'eg', 'la traversée de la mer Rouge', 'délivrance du peuple hébreu, image de la sortie de l''esclavage du péché', 'Le peuple d''Israël traverse la mer Rouge à pied sec et échappe à l''armée de pharaon. Les Pères y voient l''image de la sortie de l''esclavage du péché, par le baptême.', '[{"text": "Israël traverse la mer Rouge.", "translation": "Pharaon est vaincu."}, {"text": "C''est une image du baptême.", "translation": "Sortie de l''esclavage."}]'::jsonb, null, '{"id": "eg.d.traversee_de_la_mer_rouge", "word": "la traversée de la mer Rouge", "translation": "délivrance du peuple hébreu, image de la sortie de l''esclavage du péché", "partOfSpeech": "event", "explanation": "Le peuple d''Israël traverse la mer Rouge à pied sec et échappe à l''armée de pharaon. Les Pères y voient l''image de la sortie de l''esclavage du péché, par le baptême.", "examples": [{"text": "Israël traverse la mer Rouge.", "translation": "Pharaon est vaincu."}, {"text": "C''est une image du baptême.", "translation": "Sortie de l''esclavage."}], "unitId": "eg.v.traversee_de_la_mer_rouge"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.psaume_135', 'eg', 'le psaume 135', '2e hoos : action de grâce, « car son amour est éternel » (136 en hébreu)', 'Un psaume d''action de grâce dont le refrain revient à chaque verset. Il remercie Dieu pour la création et la délivrance.', '[{"text": "Le même refrain à chaque verset.", "translation": "Son amour est éternel."}, {"text": "C''est le 2e hoos.", "translation": "Action de grâce."}]'::jsonb, null, '{"id": "eg.d.psaume_135", "word": "le psaume 135", "translation": "2e hoos : action de grâce, « car son amour est éternel » (136 en hébreu)", "partOfSpeech": "work", "explanation": "Un psaume d''action de grâce dont le refrain revient à chaque verset. Il remercie Dieu pour la création et la délivrance.", "examples": [{"text": "Le même refrain à chaque verset.", "translation": "Son amour est éternel."}, {"text": "C''est le 2e hoos.", "translation": "Action de grâce."}], "unitId": "eg.v.psaume_135"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cantique_des_trois_jeunes', 'eg', 'le cantique des trois jeunes gens', '3e hoos : chant dans la fournaise de Babylone (Dn 3)', 'Jetés dans la fournaise à Babylone, les trois jeunes gens chantent. Ils appellent toute la création à louer Dieu.', '[{"text": "Ils chantent dans la fournaise.", "translation": "Dn 3."}, {"text": "Toute la création est appelée à louer.", "translation": "Soleil, étoiles, montagnes, mers."}]'::jsonb, null, '{"id": "eg.d.cantique_des_trois_jeunes", "word": "le cantique des trois jeunes gens", "translation": "3e hoos : chant dans la fournaise de Babylone (Dn 3)", "partOfSpeech": "work", "explanation": "Jetés dans la fournaise à Babylone, les trois jeunes gens chantent. Ils appellent toute la création à louer Dieu.", "examples": [{"text": "Ils chantent dans la fournaise.", "translation": "Dn 3."}, {"text": "Toute la création est appelée à louer.", "translation": "Soleil, étoiles, montagnes, mers."}], "unitId": "eg.v.cantique_des_trois_jeunes"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.psaumes_148_150', 'eg', 'les psaumes 148 à 150', '4e hoos : psaumes de joie et de victoire', 'Les trois derniers psaumes du psautier : ils appellent tout ce qui respire à louer le Seigneur (Ps 150, 6).', '[{"text": "Le 4e hoos réunit trois psaumes.", "translation": "148, 149 et 150."}, {"text": "Que tout ce qui respire loue le Seigneur.", "translation": "Ps 150, 6."}]'::jsonb, null, '{"id": "eg.d.psaumes_148_150", "word": "les psaumes 148 à 150", "translation": "4e hoos : psaumes de joie et de victoire", "partOfSpeech": "work", "explanation": "Les trois derniers psaumes du psautier : ils appellent tout ce qui respire à louer le Seigneur (Ps 150, 6).", "examples": [{"text": "Le 4e hoos réunit trois psaumes.", "translation": "148, 149 et 150."}, {"text": "Que tout ce qui respire loue le Seigneur.", "translation": "Ps 150, 6."}], "unitId": "eg.v.psaumes_148_150"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.doxologie', 'eg', 'la doxologie', 'chant de gloire', 'Une doxologie est un chant de gloire. Dans la tasbeha, plusieurs doxologies glorifient la Vierge puis les saints.', '[{"text": "La doxologie de la Vierge ouvre la série.", "translation": "Puis les saints."}, {"text": "Les doxologies suivent le 3e hoos.", "translation": "Avant le 4e hoos."}]'::jsonb, null, '{"id": "eg.d.doxologie", "word": "la doxologie", "translation": "chant de gloire", "partOfSpeech": "work", "explanation": "Une doxologie est un chant de gloire. Dans la tasbeha, plusieurs doxologies glorifient la Vierge puis les saints.", "examples": [{"text": "La doxologie de la Vierge ouvre la série.", "translation": "Puis les saints."}, {"text": "Les doxologies suivent le 3e hoos.", "translation": "Avant le 4e hoos."}], "unitId": "eg.v.doxologie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.doxa', 'eg', 'doxa', '« gloire » en grec', 'Doxa est un mot grec qui veut dire « gloire ». On le retrouve dans doxologie.', '[{"text": "Doxa Patri.", "translation": "Gloire au Père."}, {"text": "Doxologie = doxa + logos.", "translation": "Parole de gloire."}]'::jsonb, null, '{"id": "eg.d.doxa", "word": "doxa", "translation": "« gloire » en grec", "partOfSpeech": "expression", "explanation": "Doxa est un mot grec qui veut dire « gloire ». On le retrouve dans doxologie.", "examples": [{"text": "Doxa Patri.", "translation": "Gloire au Père."}, {"text": "Doxologie = doxa + logos.", "translation": "Parole de gloire."}], "unitId": "eg.v.doxa"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.commemoraison_des_saints', 'eg', 'la commémoraison des saints', 'moment où l''on rappelle les saints', 'Entre le 3e et le 4e hoos, l''Église rappelle les noms des saints : elle chante avec eux, vivants en Dieu.', '[{"text": "On rappelle les noms des saints.", "translation": "Entre le 3e et le 4e hoos."}, {"text": "Les saints sont vivants en Christ.", "translation": "Ils prient pour nous."}]'::jsonb, null, '{"id": "eg.d.commemoraison_des_saints", "word": "la commémoraison des saints", "translation": "moment où l''on rappelle les saints", "partOfSpeech": "event", "explanation": "Entre le 3e et le 4e hoos, l''Église rappelle les noms des saints : elle chante avec eux, vivants en Dieu.", "examples": [{"text": "On rappelle les noms des saints.", "translation": "Entre le 3e et le 4e hoos."}, {"text": "Les saints sont vivants en Christ.", "translation": "Ils prient pour nous."}], "unitId": "eg.v.commemoraison_des_saints"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nuee_de_temoins', 'eg', 'la nuée de témoins', 'image des saints qui nous entourent (He 12, 1)', 'La lettre aux Hébreux parle d''une nuée de témoins qui nous entoure : les saints, qui nous encouragent dans notre course.', '[{"text": "Une nuée de témoins nous entoure.", "translation": "He 12, 1."}, {"text": "Les saints nous encouragent.", "translation": "Nous courons avec eux."}]'::jsonb, null, '{"id": "eg.d.nuee_de_temoins", "word": "la nuée de témoins", "translation": "image des saints qui nous entourent (He 12, 1)", "partOfSpeech": "concept", "explanation": "La lettre aux Hébreux parle d''une nuée de témoins qui nous entoure : les saints, qui nous encouragent dans notre course.", "examples": [{"text": "Une nuée de témoins nous entoure.", "translation": "He 12, 1."}, {"text": "Les saints nous encouragent.", "translation": "Nous courons avec eux."}], "unitId": "eg.v.nuee_de_temoins"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.salutation_de_l_ange_gabriel', 'eg', 'la salutation de l''ange Gabriel', '« Réjouis-toi, pleine de grâce » (Lc 1, 28)', 'L''ange Gabriel annonce à Marie qu''elle sera la mère du Sauveur. Les doxologies de la Vierge reprennent cette salutation.', '[{"text": "Gabriel salue Marie.", "translation": "Lc 1, 28."}, {"text": "« Réjouis-toi, pleine de grâce ».", "translation": "Les doxologies la reprennent."}]'::jsonb, null, '{"id": "eg.d.salutation_de_l_ange_gabriel", "word": "la salutation de l''ange Gabriel", "translation": "« Réjouis-toi, pleine de grâce » (Lc 1, 28)", "partOfSpeech": "event", "explanation": "L''ange Gabriel annonce à Marie qu''elle sera la mère du Sauveur. Les doxologies de la Vierge reprennent cette salutation.", "examples": [{"text": "Gabriel salue Marie.", "translation": "Lc 1, 28."}, {"text": "« Réjouis-toi, pleine de grâce ».", "translation": "Les doxologies la reprennent."}], "unitId": "eg.v.salutation_de_l_ange_gabriel"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.sainte_vierge_marie', 'eg', 'la Vierge Marie', 'mère de Dieu, la première glorifiée dans les doxologies', 'Marie est la mère du Christ, la Théotokos. Les doxologies la glorifient avant tous les autres saints.', '[{"text": "La Vierge Marie est la Théotokos.", "translation": "Mère de Dieu."}, {"text": "Elle est glorifiée en premier.", "translation": "Puis les autres saints."}]'::jsonb, null, '{"id": "eg.d.sainte_vierge_marie", "word": "la Vierge Marie", "translation": "mère de Dieu, la première glorifiée dans les doxologies", "partOfSpeech": "person", "explanation": "Marie est la mère du Christ, la Théotokos. Les doxologies la glorifient avant tous les autres saints.", "examples": [{"text": "La Vierge Marie est la Théotokos.", "translation": "Mère de Dieu."}, {"text": "Elle est glorifiée en premier.", "translation": "Puis les autres saints."}], "unitId": "eg.v.sainte_vierge_marie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.psali', 'eg', 'le psali', 'chant de louange au Christ (du grec « chanter des psaumes »)', 'Le psali est un chant de la tasbeha adressé au Christ. Il y en a un par jour, et deux le dimanche.', '[{"text": "Le psali loue le Christ.", "translation": "Un par jour."}, {"text": "Il se chante sur l''air du jour.", "translation": "Adam ou Watos."}]'::jsonb, null, '{"id": "eg.d.psali", "word": "le psali", "translation": "chant de louange au Christ (du grec « chanter des psaumes »)", "partOfSpeech": "work", "explanation": "Le psali est un chant de la tasbeha adressé au Christ. Il y en a un par jour, et deux le dimanche.", "examples": [{"text": "Le psali loue le Christ.", "translation": "Un par jour."}, {"text": "Il se chante sur l''air du jour.", "translation": "Adam ou Watos."}], "unitId": "eg.v.psali"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.theotokie', 'eg', 'la théotokie', 'louange de la Vierge, différente chaque jour de la semaine', 'La théotokie est un chant à la Vierge, la Théotokos. Il y en a sept, une pour chaque jour de la semaine.', '[{"text": "La théotokie loue la Vierge.", "translation": "Sept par semaine."}, {"text": "Elle explique l''incarnation.", "translation": "Par des symboles."}]'::jsonb, null, '{"id": "eg.d.theotokie", "word": "la théotokie", "translation": "louange de la Vierge, différente chaque jour de la semaine", "partOfSpeech": "work", "explanation": "La théotokie est un chant à la Vierge, la Théotokos. Il y en a sept, une pour chaque jour de la semaine.", "examples": [{"text": "La théotokie loue la Vierge.", "translation": "Sept par semaine."}, {"text": "Elle explique l''incarnation.", "translation": "Par des symboles."}], "unitId": "eg.v.theotokie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.buisson_ardent', 'eg', 'le buisson ardent', 'buisson que Moïse voit brûler sans se consumer (Ex 3)', 'Moïse voit un buisson en feu qui ne se consume pas. Les Pères y voient la Vierge, qui porte le feu de la divinité sans être consumée.', '[{"text": "Le buisson brûle sans se consumer.", "translation": "Ex 3."}, {"text": "Image de la Vierge.", "translation": "Le feu de la divinité."}]'::jsonb, null, '{"id": "eg.d.buisson_ardent", "word": "le buisson ardent", "translation": "buisson que Moïse voit brûler sans se consumer (Ex 3)", "partOfSpeech": "event", "explanation": "Moïse voit un buisson en feu qui ne se consume pas. Les Pères y voient la Vierge, qui porte le feu de la divinité sans être consumée.", "examples": [{"text": "Le buisson brûle sans se consumer.", "translation": "Ex 3."}, {"text": "Image de la Vierge.", "translation": "Le feu de la divinité."}], "unitId": "eg.v.buisson_ardent"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.arche_de_l_alliance', 'eg', 'l''arche de l''alliance', 'coffre qui contenait les tables de la Loi', 'L''arche contenait la Loi écrite par Dieu. Pour les Pères, elle annonce Marie, qui porte le Verbe de Dieu fait homme.', '[{"text": "L''arche contient la Loi.", "translation": "Écrite par Dieu."}, {"text": "Marie porte le Verbe.", "translation": "Dieu fait homme."}]'::jsonb, null, '{"id": "eg.d.arche_de_l_alliance", "word": "l''arche de l''alliance", "translation": "coffre qui contenait les tables de la Loi", "partOfSpeech": "concept", "explanation": "L''arche contenait la Loi écrite par Dieu. Pour les Pères, elle annonce Marie, qui porte le Verbe de Dieu fait homme.", "examples": [{"text": "L''arche contient la Loi.", "translation": "Écrite par Dieu."}, {"text": "Marie porte le Verbe.", "translation": "Dieu fait homme."}], "unitId": "eg.v.arche_de_l_alliance"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.cruche_d_or', 'eg', 'la cruche d''or de la manne', 'vase d''or qui contenait la manne, le pain du ciel', 'La cruche d''or contenait la manne, le pain du ciel donné au désert. Elle annonce Marie, qui porte le vrai pain du ciel, le Christ (Jn 6, 35).', '[{"text": "La cruche contient la manne.", "translation": "Le pain du ciel."}, {"text": "Marie porte le vrai pain.", "translation": "Le Christ."}]'::jsonb, null, '{"id": "eg.d.cruche_d_or", "word": "la cruche d''or de la manne", "translation": "vase d''or qui contenait la manne, le pain du ciel", "partOfSpeech": "concept", "explanation": "La cruche d''or contenait la manne, le pain du ciel donné au désert. Elle annonce Marie, qui porte le vrai pain du ciel, le Christ (Jn 6, 35).", "examples": [{"text": "La cruche contient la manne.", "translation": "Le pain du ciel."}, {"text": "Marie porte le vrai pain.", "translation": "Le Christ."}], "unitId": "eg.v.cruche_d_or"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.chandelier_d_or', 'eg', 'le chandelier d''or', 'chandelier du sanctuaire, qui porte la lumière', 'Le chandelier d''or éclairait le sanctuaire. Il annonce Marie, qui porte la vraie lumière, le Christ (Jn 8, 12).', '[{"text": "Le chandelier porte la lumière.", "translation": "Il éclaire le sanctuaire."}, {"text": "Marie porte la vraie lumière.", "translation": "Le Christ."}]'::jsonb, null, '{"id": "eg.d.chandelier_d_or", "word": "le chandelier d''or", "translation": "chandelier du sanctuaire, qui porte la lumière", "partOfSpeech": "concept", "explanation": "Le chandelier d''or éclairait le sanctuaire. Il annonce Marie, qui porte la vraie lumière, le Christ (Jn 8, 12).", "examples": [{"text": "Le chandelier porte la lumière.", "translation": "Il éclaire le sanctuaire."}, {"text": "Marie porte la vraie lumière.", "translation": "Le Christ."}], "unitId": "eg.v.chandelier_d_or"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.figure_de_l_ancien_testament', 'eg', 'la figure de l''Ancien Testament', 'personne ou objet de l''Ancien Testament qui annonce le Christ ou Marie', 'Une figure (ou symbole) est un signe de l''Ancien Testament qui annonce à l''avance une réalité du Nouveau. Les théotokies en sont pleines.', '[{"text": "Le buisson est une figure de Marie.", "translation": "Il annonce l''incarnation."}, {"text": "Chaque figure dit : Marie porte Dieu.", "translation": "Quatre figures à retenir."}]'::jsonb, null, '{"id": "eg.d.figure_de_l_ancien_testament", "word": "la figure de l''Ancien Testament", "translation": "personne ou objet de l''Ancien Testament qui annonce le Christ ou Marie", "partOfSpeech": "concept", "explanation": "Une figure (ou symbole) est un signe de l''Ancien Testament qui annonce à l''avance une réalité du Nouveau. Les théotokies en sont pleines.", "examples": [{"text": "Le buisson est une figure de Marie.", "translation": "Il annonce l''incarnation."}, {"text": "Chaque figure dit : Marie porte Dieu.", "translation": "Quatre figures à retenir."}], "unitId": "eg.v.figure_de_l_ancien_testament"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jours_adam', 'eg', 'les jours Adam', 'dimanche, lundi, mardi : l''air Adam', 'Les trois premiers jours de la semaine chantent la psalmodie sur l''air Adam : dimanche, lundi, mardi.', '[{"text": "Le lundi est un jour Adam.", "translation": "Théotokie « Adam… »."}, {"text": "Dimanche, lundi, mardi : trois jours Adam.", "translation": "Adam ouvre la semaine."}]'::jsonb, null, '{"id": "eg.d.jours_adam", "word": "les jours Adam", "translation": "dimanche, lundi, mardi : l''air Adam", "partOfSpeech": "concept", "explanation": "Les trois premiers jours de la semaine chantent la psalmodie sur l''air Adam : dimanche, lundi, mardi.", "examples": [{"text": "Le lundi est un jour Adam.", "translation": "Théotokie « Adam… »."}, {"text": "Dimanche, lundi, mardi : trois jours Adam.", "translation": "Adam ouvre la semaine."}], "unitId": "eg.v.jours_adam"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jours_watos', 'eg', 'les jours Watos', 'mercredi, jeudi, vendredi, samedi : l''air Watos', 'Les quatre derniers jours de la semaine chantent la psalmodie sur l''air Watos : mercredi, jeudi, vendredi, samedi. On dit aussi Batos.', '[{"text": "Le jeudi est un jour Watos.", "translation": "Théotokie « Pibatos »."}, {"text": "Mercredi à samedi : quatre jours Watos.", "translation": "Watos clôt la semaine."}]'::jsonb, null, '{"id": "eg.d.jours_watos", "word": "les jours Watos", "translation": "mercredi, jeudi, vendredi, samedi : l''air Watos", "partOfSpeech": "concept", "explanation": "Les quatre derniers jours de la semaine chantent la psalmodie sur l''air Watos : mercredi, jeudi, vendredi, samedi. On dit aussi Batos.", "examples": [{"text": "Le jeudi est un jour Watos.", "translation": "Théotokie « Pibatos »."}, {"text": "Mercredi à samedi : quatre jours Watos.", "translation": "Watos clôt la semaine."}], "unitId": "eg.v.jours_watos"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.pibatos', 'eg', 'Pibatos', 'premier mot de la théotokie du jeudi : « le buisson »', 'Pibatos veut dire « le buisson ». C''est le premier mot de la théotokie du jeudi : le buisson que Moïse a vu brûler dans le désert. Le nom Watos en vient.', '[{"text": "Pibatos ouvre la théotokie du jeudi.", "translation": "Le buisson ardent."}, {"text": "Watos vient de Pibatos.", "translation": "Image de la Vierge."}]'::jsonb, null, '{"id": "eg.d.pibatos", "word": "Pibatos", "translation": "premier mot de la théotokie du jeudi : « le buisson »", "partOfSpeech": "expression", "explanation": "Pibatos veut dire « le buisson ». C''est le premier mot de la théotokie du jeudi : le buisson que Moïse a vu brûler dans le désert. Le nom Watos en vient.", "examples": [{"text": "Pibatos ouvre la théotokie du jeudi.", "translation": "Le buisson ardent."}, {"text": "Watos vient de Pibatos.", "translation": "Image de la Vierge."}], "unitId": "eg.v.pibatos"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.theotokie_du_lundi', 'eg', 'la théotokie du lundi', 'théotokie qui commence par « Adam… » et donne son nom à l''air Adam', 'Elle commence par Adam, triste après la chute, consolé par le Sauveur né de la Vierge. Son premier mot donne son nom à l''air Adam.', '[{"text": "La théotokie du lundi commence par Adam.", "translation": "D''où l''air Adam."}, {"text": "Adam est consolé par le Sauveur.", "translation": "Né de la Vierge."}]'::jsonb, null, '{"id": "eg.d.theotokie_du_lundi", "word": "la théotokie du lundi", "translation": "théotokie qui commence par « Adam… » et donne son nom à l''air Adam", "partOfSpeech": "work", "explanation": "Elle commence par Adam, triste après la chute, consolé par le Sauveur né de la Vierge. Son premier mot donne son nom à l''air Adam.", "examples": [{"text": "La théotokie du lundi commence par Adam.", "translation": "D''où l''air Adam."}, {"text": "Adam est consolé par le Sauveur.", "translation": "Né de la Vierge."}], "unitId": "eg.v.theotokie_du_lundi"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jour_liturgique', 'eg', 'le jour liturgique', 'jour de l''Église, qui commence la veille au soir', 'Comme dans la Genèse (« il y eut un soir, il y eut un matin »), le jour liturgique commence la veille au soir, vers 18 h.', '[{"text": "Samedi soir, c''est déjà dimanche.", "translation": "Le jour liturgique a commencé."}, {"text": "Le soir, on prie le lendemain.", "translation": "La règle du soir."}]'::jsonb, null, '{"id": "eg.d.jour_liturgique", "word": "le jour liturgique", "translation": "jour de l''Église, qui commence la veille au soir", "partOfSpeech": "concept", "explanation": "Comme dans la Genèse (« il y eut un soir, il y eut un matin »), le jour liturgique commence la veille au soir, vers 18 h.", "examples": [{"text": "Samedi soir, c''est déjà dimanche.", "translation": "Le jour liturgique a commencé."}, {"text": "Le soir, on prie le lendemain.", "translation": "La règle du soir."}], "unitId": "eg.v.jour_liturgique"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.regle_du_soir', 'eg', 'la règle du soir', 'le soir, on prie déjà la théotokie du lendemain', 'Le soir, on prie la théotokie du lendemain sur l''air du lendemain. L''air ne change qu''à deux soirs : le samedi (vers Adam) et le mardi (vers Watos).', '[{"text": "Mardi soir : théotokie du mercredi.", "translation": "Air Watos."}, {"text": "Samedi soir : théotokie du dimanche.", "translation": "Air Adam."}]'::jsonb, null, '{"id": "eg.d.regle_du_soir", "word": "la règle du soir", "translation": "le soir, on prie déjà la théotokie du lendemain", "partOfSpeech": "concept", "explanation": "Le soir, on prie la théotokie du lendemain sur l''air du lendemain. L''air ne change qu''à deux soirs : le samedi (vers Adam) et le mardi (vers Watos).", "examples": [{"text": "Mardi soir : théotokie du mercredi.", "translation": "Air Watos."}, {"text": "Samedi soir : théotokie du dimanche.", "translation": "Air Adam."}], "unitId": "eg.v.regle_du_soir"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.kiahk', 'eg', 'Kiahk', 'quatrième mois copte, mois marial', 'Kiahk est le quatrième mois du calendrier copte, vers décembre. On y loue la Vierge avec des chants spéciaux.', '[{"text": "Kiahk est le mois de Marie.", "translation": "Avant la Nativité."}, {"text": "Il tombe pendant le jeûne de la Nativité.", "translation": "Préparation à Noël."}]'::jsonb, null, '{"id": "eg.d.kiahk", "word": "Kiahk", "translation": "quatrième mois copte, mois marial", "partOfSpeech": "date", "explanation": "Kiahk est le quatrième mois du calendrier copte, vers décembre. On y loue la Vierge avec des chants spéciaux.", "examples": [{"text": "Kiahk est le mois de Marie.", "translation": "Avant la Nativité."}, {"text": "Il tombe pendant le jeûne de la Nativité.", "translation": "Préparation à Noël."}], "unitId": "eg.v.kiahk"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.mois_marial', 'eg', 'le mois marial', 'mois consacré à la louange de la Vierge', 'Kiahk est appelé le mois marial : toute la tasbeha y loue Marie par ses théotokies.', '[{"text": "Kiahk est le mois marial.", "translation": "Marie est louée."}, {"text": "On prie les sept théotokies.", "translation": "Une par jour."}]'::jsonb, null, '{"id": "eg.d.mois_marial", "word": "le mois marial", "translation": "mois consacré à la louange de la Vierge", "partOfSpeech": "concept", "explanation": "Kiahk est appelé le mois marial : toute la tasbeha y loue Marie par ses théotokies.", "examples": [{"text": "Kiahk est le mois marial.", "translation": "Marie est louée."}, {"text": "On prie les sept théotokies.", "translation": "Une par jour."}], "unitId": "eg.v.mois_marial"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.jeune_de_la_nativite', 'eg', 'le jeûne de la Nativité', 'jeûne qui prépare à Noël, pendant lequel tombe Kiahk', 'Le jeûne de la Nativité prépare la fête de la naissance du Christ. Kiahk tombe pendant ce jeûne.', '[{"text": "Kiahk tombe pendant le jeûne de la Nativité.", "translation": "Avant Noël."}, {"text": "On prépare la naissance du Christ.", "translation": "Par la prière et le jeûne."}]'::jsonb, null, '{"id": "eg.d.jeune_de_la_nativite", "word": "le jeûne de la Nativité", "translation": "jeûne qui prépare à Noël, pendant lequel tombe Kiahk", "partOfSpeech": "event", "explanation": "Le jeûne de la Nativité prépare la fête de la naissance du Christ. Kiahk tombe pendant ce jeûne.", "examples": [{"text": "Kiahk tombe pendant le jeûne de la Nativité.", "translation": "Avant Noël."}, {"text": "On prépare la naissance du Christ.", "translation": "Par la prière et le jeûne."}], "unitId": "eg.v.jeune_de_la_nativite"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tasbeha_sept_et_quatre', 'eg', 'la tasbeha « sept et quatre »', 'grande tasbeha de Kiahk : 7 théotokies et 4 hoos', 'La grande tasbeha de Kiahk réunit les sept théotokies de la semaine et les quatre hoos.', '[{"text": "Sept théotokies et quatre hoos.", "translation": "Une grande tasbeha."}, {"text": "Autrefois toute la nuit.", "translation": "Du samedi au dimanche."}]'::jsonb, null, '{"id": "eg.d.tasbeha_sept_et_quatre", "word": "la tasbeha « sept et quatre »", "translation": "grande tasbeha de Kiahk : 7 théotokies et 4 hoos", "partOfSpeech": "work", "explanation": "La grande tasbeha de Kiahk réunit les sept théotokies de la semaine et les quatre hoos.", "examples": [{"text": "Sept théotokies et quatre hoos.", "translation": "Une grande tasbeha."}, {"text": "Autrefois toute la nuit.", "translation": "Du samedi au dimanche."}], "unitId": "eg.v.tasbeha_sept_et_quatre"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.calendrier_solaire', 'eg', 'le calendrier solaire', 'calendrier réglé sur le soleil : 12 mois de 30 jours plus un petit mois', 'Les anciens Égyptiens ont réglé leur année sur le soleil et la crue du Nil : 12 mois de 30 jours plus 5 jours, soit 365 jours.', '[{"text": "Le calendrier copte est un calendrier solaire.", "translation": "Il suit le soleil, pas la lune."}, {"text": "L''année a 12 mois de 30 jours.", "translation": "Plus un petit mois à la fin."}]'::jsonb, null, '{"id": "eg.d.calendrier_solaire", "word": "le calendrier solaire", "translation": "calendrier réglé sur le soleil : 12 mois de 30 jours plus un petit mois", "partOfSpeech": "concept", "explanation": "Les anciens Égyptiens ont réglé leur année sur le soleil et la crue du Nil : 12 mois de 30 jours plus 5 jours, soit 365 jours.", "examples": [{"text": "Le calendrier copte est un calendrier solaire.", "translation": "Il suit le soleil, pas la lune."}, {"text": "L''année a 12 mois de 30 jours.", "translation": "Plus un petit mois à la fin."}], "unitId": "eg.v.calendrier_solaire"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.calendrier_alexandrin', 'eg', 'le calendrier alexandrin', 'calendrier d''Alexandrie qui ajoute un sixième jour tous les quatre ans', 'Vers 25 av. J.-C., sous Auguste, Alexandrie ajoute un sixième jour tous les quatre ans. Les Coptes ont gardé ce calendrier, avec les noms de mois égyptiens.', '[{"text": "Le calendrier alexandrin ajoute un jour tous les quatre ans.", "translation": "Il corrige le retard sur le soleil."}, {"text": "Le calendrier copte est l''héritier du calendrier alexandrin.", "translation": "Il a gardé les noms de mois de l''Égypte ancienne."}]'::jsonb, null, '{"id": "eg.d.calendrier_alexandrin", "word": "le calendrier alexandrin", "translation": "calendrier d''Alexandrie qui ajoute un sixième jour tous les quatre ans", "partOfSpeech": "concept", "explanation": "Vers 25 av. J.-C., sous Auguste, Alexandrie ajoute un sixième jour tous les quatre ans. Les Coptes ont gardé ce calendrier, avec les noms de mois égyptiens.", "examples": [{"text": "Le calendrier alexandrin ajoute un jour tous les quatre ans.", "translation": "Il corrige le retard sur le soleil."}, {"text": "Le calendrier copte est l''héritier du calendrier alexandrin.", "translation": "Il a gardé les noms de mois de l''Égypte ancienne."}], "unitId": "eg.v.calendrier_alexandrin"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.trois_saisons', 'eg', 'les trois saisons', 'la crue, la croissance, la moisson : trois saisons de quatre mois', 'L''année égyptienne a trois saisons de quatre mois : la crue (Akhet), la croissance (Peret) et la moisson (Shemu).', '[{"text": "Akhet est la saison de la crue.", "translation": "Le Nil monte et couvre les champs."}, {"text": "Shemu est la saison de la moisson.", "translation": "On récolte le blé."}]'::jsonb, null, '{"id": "eg.d.trois_saisons", "word": "les trois saisons", "translation": "la crue, la croissance, la moisson : trois saisons de quatre mois", "partOfSpeech": "concept", "explanation": "L''année égyptienne a trois saisons de quatre mois : la crue (Akhet), la croissance (Peret) et la moisson (Shemu).", "examples": [{"text": "Akhet est la saison de la crue.", "translation": "Le Nil monte et couvre les champs."}, {"text": "Shemu est la saison de la moisson.", "translation": "On récolte le blé."}], "unitId": "eg.v.trois_saisons"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.annee_copte', 'eg', 'l''année copte', 'année comptée depuis 284, qui commence le 1er Tout', 'L''année copte commence le 1er Tout, vers le 11 septembre, et compte depuis 284 : année grégorienne moins 283 ou moins 284.', '[{"text": "Novembre 2026 : l''année copte est 1743.", "translation": "2026 − 283 = 1743."}, {"text": "L''année copte change en septembre.", "translation": "Pas le 1er janvier."}]'::jsonb, null, '{"id": "eg.d.annee_copte", "word": "l''année copte", "translation": "année comptée depuis 284, qui commence le 1er Tout", "partOfSpeech": "concept", "explanation": "L''année copte commence le 1er Tout, vers le 11 septembre, et compte depuis 284 : année grégorienne moins 283 ou moins 284.", "examples": [{"text": "Novembre 2026 : l''année copte est 1743.", "translation": "2026 − 283 = 1743."}, {"text": "L''année copte change en septembre.", "translation": "Pas le 1er janvier."}], "unitId": "eg.v.annee_copte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.tout', 'eg', 'Tout', 'premier mois copte (توت), vers le 11 septembre', 'Tout ouvre l''année copte. Son nom vient du dieu égyptien Thot. Le 1er Tout est le Nayrouz.', '[{"text": "Tout commence vers le 11 septembre.", "translation": "C''est le jour de l''an copte."}, {"text": "Le premier mois s''appelle Tout.", "translation": "Il porte le nom de Thot."}]'::jsonb, null, '{"id": "eg.d.tout", "word": "Tout", "translation": "premier mois copte (توت), vers le 11 septembre", "partOfSpeech": "date", "explanation": "Tout ouvre l''année copte. Son nom vient du dieu égyptien Thot. Le 1er Tout est le Nayrouz.", "examples": [{"text": "Tout commence vers le 11 septembre.", "translation": "C''est le jour de l''an copte."}, {"text": "Le premier mois s''appelle Tout.", "translation": "Il porte le nom de Thot."}], "unitId": "eg.v.tout"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.baba', 'eg', 'Baba', 'deuxième mois copte (بابه), vers le 11 octobre', 'Baba suit Tout. Son nom viendrait de la fête égyptienne d''Opet. Le Nil commence à baisser.', '[{"text": "Baba commence vers le 11 octobre.", "translation": "C''est le deuxième mois."}, {"text": "Après Tout vient Baba.", "translation": "Le fleuve baisse."}]'::jsonb, null, '{"id": "eg.d.baba", "word": "Baba", "translation": "deuxième mois copte (بابه), vers le 11 octobre", "partOfSpeech": "date", "explanation": "Baba suit Tout. Son nom viendrait de la fête égyptienne d''Opet. Le Nil commence à baisser.", "examples": [{"text": "Baba commence vers le 11 octobre.", "translation": "C''est le deuxième mois."}, {"text": "Après Tout vient Baba.", "translation": "Le fleuve baisse."}], "unitId": "eg.v.baba"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.hatour', 'eg', 'Hatour', 'troisième mois copte (هاتور), vers le 10 novembre', 'Hatour porte le nom de la déesse Hathor. C''est le temps des semailles du blé.', '[{"text": "Hatour commence vers le 10 novembre.", "translation": "C''est le troisième mois."}, {"text": "On sème le blé en Hatour.", "translation": "La terre vient de la crue."}]'::jsonb, null, '{"id": "eg.d.hatour", "word": "Hatour", "translation": "troisième mois copte (هاتور), vers le 10 novembre", "partOfSpeech": "date", "explanation": "Hatour porte le nom de la déesse Hathor. C''est le temps des semailles du blé.", "examples": [{"text": "Hatour commence vers le 10 novembre.", "translation": "C''est le troisième mois."}, {"text": "On sème le blé en Hatour.", "translation": "La terre vient de la crue."}], "unitId": "eg.v.hatour"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.touba', 'eg', 'Touba', 'cinquième mois copte (طوبة), vers le 9 janvier', 'Touba est le cœur de l''hiver, le mois le plus froid. Les paysans en ont fait un proverbe.', '[{"text": "Touba commence vers le 9 janvier.", "translation": "C''est le cinquième mois."}, {"text": "Touba est plein hiver.", "translation": "Il fait très froid."}]'::jsonb, null, '{"id": "eg.d.touba", "word": "Touba", "translation": "cinquième mois copte (طوبة), vers le 9 janvier", "partOfSpeech": "date", "explanation": "Touba est le cœur de l''hiver, le mois le plus froid. Les paysans en ont fait un proverbe.", "examples": [{"text": "Touba commence vers le 9 janvier.", "translation": "C''est le cinquième mois."}, {"text": "Touba est plein hiver.", "translation": "Il fait très froid."}], "unitId": "eg.v.touba"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.amshir', 'eg', 'Amshir', 'sixième mois copte (أمشير), vers le 8 février', 'Amshir est le mois des vents. Il se termine vers le 9 mars, avant Baramhat.', '[{"text": "Amshir commence vers le 8 février.", "translation": "C''est le sixième mois."}, {"text": "Amshir est le mois des vents.", "translation": "Le temps change d''un jour à l''autre."}]'::jsonb, null, '{"id": "eg.d.amshir", "word": "Amshir", "translation": "sixième mois copte (أمشير), vers le 8 février", "partOfSpeech": "date", "explanation": "Amshir est le mois des vents. Il se termine vers le 9 mars, avant Baramhat.", "examples": [{"text": "Amshir commence vers le 8 février.", "translation": "C''est le sixième mois."}, {"text": "Amshir est le mois des vents.", "translation": "Le temps change d''un jour à l''autre."}], "unitId": "eg.v.amshir"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.thot', 'eg', 'Thot', 'dieu égyptien de la sagesse et de l''écriture, qui a donné son nom à Tout', 'Thot est un dieu de l''ancienne Égypte, patron de la sagesse et de l''écriture. Le mois de Tout garde son nom.', '[{"text": "Tout vient de Thot.", "translation": "Le nom a traversé les siècles."}, {"text": "Thot est le dieu de l''écriture.", "translation": "Les Égyptiens l''honoraient à Hermopolis."}]'::jsonb, null, '{"id": "eg.d.thot", "word": "Thot", "translation": "dieu égyptien de la sagesse et de l''écriture, qui a donné son nom à Tout", "partOfSpeech": "person", "explanation": "Thot est un dieu de l''ancienne Égypte, patron de la sagesse et de l''écriture. Le mois de Tout garde son nom.", "examples": [{"text": "Tout vient de Thot.", "translation": "Le nom a traversé les siècles."}, {"text": "Thot est le dieu de l''écriture.", "translation": "Les Égyptiens l''honoraient à Hermopolis."}], "unitId": "eg.v.thot"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.hathor', 'eg', 'Hathor', 'déesse égyptienne de la joie et de l''amour, qui a donné son nom à Hatour', 'Hathor est une déesse de l''ancienne Égypte, liée à la joie et à l''amour. Le mois de Hatour garde son nom.', '[{"text": "Hatour vient de Hathor.", "translation": "Le nom a survécu dans le calendrier."}, {"text": "Hathor est la déesse de la joie.", "translation": "Elle était très populaire."}]'::jsonb, null, '{"id": "eg.d.hathor", "word": "Hathor", "translation": "déesse égyptienne de la joie et de l''amour, qui a donné son nom à Hatour", "partOfSpeech": "person", "explanation": "Hathor est une déesse de l''ancienne Égypte, liée à la joie et à l''amour. Le mois de Hatour garde son nom.", "examples": [{"text": "Hatour vient de Hathor.", "translation": "Le nom a survécu dans le calendrier."}, {"text": "Hathor est la déesse de la joie.", "translation": "Elle était très populaire."}], "unitId": "eg.v.hathor"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.baramhat', 'eg', 'Baramhat', 'septième mois copte (برمهات), vers le 10 mars', 'Baramhat est le septième mois, au début de la moisson. Le proverbe dit : va au champ et rapporte.', '[{"text": "Baramhat commence vers le 10 mars.", "translation": "C''est le septième mois."}, {"text": "Baramhat suit Amshir.", "translation": "Les vents s''apaisent."}]'::jsonb, null, '{"id": "eg.d.baramhat", "word": "Baramhat", "translation": "septième mois copte (برمهات), vers le 10 mars", "partOfSpeech": "date", "explanation": "Baramhat est le septième mois, au début de la moisson. Le proverbe dit : va au champ et rapporte.", "examples": [{"text": "Baramhat commence vers le 10 mars.", "translation": "C''est le septième mois."}, {"text": "Baramhat suit Amshir.", "translation": "Les vents s''apaisent."}], "unitId": "eg.v.baramhat"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.baramouda', 'eg', 'Baramouda', 'huitième mois copte (برمودة), vers le 9 avril', 'Baramouda est le huitième mois, en pleine moisson. Le blé mûr est battu.', '[{"text": "Baramouda commence vers le 9 avril.", "translation": "C''est le huitième mois."}, {"text": "Baramouda suit Baramhat.", "translation": "La moisson avance."}]'::jsonb, null, '{"id": "eg.d.baramouda", "word": "Baramouda", "translation": "huitième mois copte (برمودة), vers le 9 avril", "partOfSpeech": "date", "explanation": "Baramouda est le huitième mois, en pleine moisson. Le blé mûr est battu.", "examples": [{"text": "Baramouda commence vers le 9 avril.", "translation": "C''est le huitième mois."}, {"text": "Baramouda suit Baramhat.", "translation": "La moisson avance."}], "unitId": "eg.v.baramouda"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.bashans', 'eg', 'Bashans', 'neuvième mois copte (بشنس), vers le 9 mai', 'Bashans est le neuvième mois. Les champs se vident : Bashans balaie le champ, dit le proverbe.', '[{"text": "Bashans commence vers le 9 mai.", "translation": "C''est le neuvième mois."}, {"text": "Bashans balaie le champ.", "translation": "La moisson est finie."}]'::jsonb, null, '{"id": "eg.d.bashans", "word": "Bashans", "translation": "neuvième mois copte (بشنس), vers le 9 mai", "partOfSpeech": "date", "explanation": "Bashans est le neuvième mois. Les champs se vident : Bashans balaie le champ, dit le proverbe.", "examples": [{"text": "Bashans commence vers le 9 mai.", "translation": "C''est le neuvième mois."}, {"text": "Bashans balaie le champ.", "translation": "La moisson est finie."}], "unitId": "eg.v.bashans"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.baouna', 'eg', 'Baouna', 'dixième mois copte (بؤونة), vers le 8 juin', 'Baouna est le dixième mois, en pleine chaleur. Vers sa fin, le Nil commence à monter.', '[{"text": "Baouna commence vers le 8 juin.", "translation": "C''est le dixième mois."}, {"text": "Il fait très chaud en Baouna.", "translation": "Le Nil commence à monter."}]'::jsonb, null, '{"id": "eg.d.baouna", "word": "Baouna", "translation": "dixième mois copte (بؤونة), vers le 8 juin", "partOfSpeech": "date", "explanation": "Baouna est le dixième mois, en pleine chaleur. Vers sa fin, le Nil commence à monter.", "examples": [{"text": "Baouna commence vers le 8 juin.", "translation": "C''est le dixième mois."}, {"text": "Il fait très chaud en Baouna.", "translation": "Le Nil commence à monter."}], "unitId": "eg.v.baouna"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.abib', 'eg', 'Abib', 'onzième mois copte (أبيب), vers le 8 juillet', 'Abib est le onzième mois, au cœur de l''été. On ne sait pas d''où vient son nom.', '[{"text": "Abib commence vers le 8 juillet.", "translation": "C''est le onzième mois."}, {"text": "Abib suit Baouna.", "translation": "La chaleur est à son comble."}]'::jsonb, null, '{"id": "eg.d.abib", "word": "Abib", "translation": "onzième mois copte (أبيب), vers le 8 juillet", "partOfSpeech": "date", "explanation": "Abib est le onzième mois, au cœur de l''été. On ne sait pas d''où vient son nom.", "examples": [{"text": "Abib commence vers le 8 juillet.", "translation": "C''est le onzième mois."}, {"text": "Abib suit Baouna.", "translation": "La chaleur est à son comble."}], "unitId": "eg.v.abib"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.misra', 'eg', 'Misra', 'douzième mois copte (مسرى), vers le 7 août', 'Misra est le douzième et dernier grand mois. La crue remplit les canaux.', '[{"text": "Misra commence vers le 7 août.", "translation": "C''est le douzième mois."}, {"text": "En Misra, la crue remplit les canaux.", "translation": "Le Nil revient irriguer les terres."}]'::jsonb, null, '{"id": "eg.d.misra", "word": "Misra", "translation": "douzième mois copte (مسرى), vers le 7 août", "partOfSpeech": "date", "explanation": "Misra est le douzième et dernier grand mois. La crue remplit les canaux.", "examples": [{"text": "Misra commence vers le 7 août.", "translation": "C''est le douzième mois."}, {"text": "En Misra, la crue remplit les canaux.", "translation": "Le Nil revient irriguer les terres."}], "unitId": "eg.v.misra"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.nasie', 'eg', 'Nasie', 'treizième mois copte (النسيء), le petit mois de 5 ou 6 jours', 'Nasie est le petit mois, juste avant le Nayrouz. Il compte 5 jours, 6 dans l''année bissextile copte.', '[{"text": "Nasie compte 5 jours.", "translation": "C''est le petit mois."}, {"text": "Nasie a six jours tous les quatre ans.", "translation": "Le Nayrouz tombe alors le 12 septembre."}]'::jsonb, null, '{"id": "eg.d.nasie", "word": "Nasie", "translation": "treizième mois copte (النسيء), le petit mois de 5 ou 6 jours", "partOfSpeech": "date", "explanation": "Nasie est le petit mois, juste avant le Nayrouz. Il compte 5 jours, 6 dans l''année bissextile copte.", "examples": [{"text": "Nasie compte 5 jours.", "translation": "C''est le petit mois."}, {"text": "Nasie a six jours tous les quatre ans.", "translation": "Le Nayrouz tombe alors le 12 septembre."}], "unitId": "eg.v.nasie"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.crue_du_nil', 'eg', 'la crue du Nil', 'montée annuelle des eaux du Nil, qui rythmait la vie des paysans', 'Chaque année, le Nil montait, couvrait les champs puis se retirait en laissant une terre fertile. Le calendrier égyptien est né de ce rythme.', '[{"text": "La crue du Nil remplit les canaux.", "translation": "Elle arrive en Misra."}, {"text": "Après la crue, on sème le blé.", "translation": "C''est le temps de Hatour."}]'::jsonb, null, '{"id": "eg.d.crue_du_nil", "word": "la crue du Nil", "translation": "montée annuelle des eaux du Nil, qui rythmait la vie des paysans", "partOfSpeech": "event", "explanation": "Chaque année, le Nil montait, couvrait les champs puis se retirait en laissant une terre fertile. Le calendrier égyptien est né de ce rythme.", "examples": [{"text": "La crue du Nil remplit les canaux.", "translation": "Elle arrive en Misra."}, {"text": "Après la crue, on sème le blé.", "translation": "C''est le temps de Hatour."}], "unitId": "eg.v.crue_du_nil"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.annee_bissextile_copte', 'eg', 'l''année bissextile copte', 'année copte où Nasie compte six jours, tous les quatre ans', 'Tous les quatre ans, Nasie a six jours. C''est l''année copte dont le numéro, divisé par 4, laisse 3 : 1743 est bissextile.', '[{"text": "1743 est une année bissextile copte.", "translation": "Nasie aura six jours en 2027."}, {"text": "Après elle, le Nayrouz tombe le 12 septembre.", "translation": "Un jour plus tard que d''habitude."}]'::jsonb, null, '{"id": "eg.d.annee_bissextile_copte", "word": "l''année bissextile copte", "translation": "année copte où Nasie compte six jours, tous les quatre ans", "partOfSpeech": "concept", "explanation": "Tous les quatre ans, Nasie a six jours. C''est l''année copte dont le numéro, divisé par 4, laisse 3 : 1743 est bissextile.", "examples": [{"text": "1743 est une année bissextile copte.", "translation": "Nasie aura six jours en 2027."}, {"text": "Après elle, le Nayrouz tombe le 12 septembre.", "translation": "Un jour plus tard que d''habitude."}], "unitId": "eg.v.annee_bissextile_copte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
insert into public.dictionary_items (id, language_id, word, translation, definition, examples, pronunciation, data, content_version) values ('eg.d.noel_copte', 'eg', 'Noël copte (29 Kiahk)', 'la Nativité, fêtée le 29 Kiahk, vers le 7 janvier', 'Les Coptes fêtent Noël le 29 Kiahk, vers le 7 janvier, car leur calendrier suit l''ancien calendrier julien, en retard de 13 jours sur le nôtre.', '[{"text": "Noël copte tombe le 29 Kiahk.", "translation": "C''est vers le 7 janvier."}, {"text": "29 Kiahk, c''est le repère de Noël.", "translation": "Pas besoin de dire le 25 décembre."}]'::jsonb, null, '{"id": "eg.d.noel_copte", "word": "Noël copte (29 Kiahk)", "translation": "la Nativité, fêtée le 29 Kiahk, vers le 7 janvier", "partOfSpeech": "date", "explanation": "Les Coptes fêtent Noël le 29 Kiahk, vers le 7 janvier, car leur calendrier suit l''ancien calendrier julien, en retard de 13 jours sur le nôtre.", "examples": [{"text": "Noël copte tombe le 29 Kiahk.", "translation": "C''est vers le 7 janvier."}, {"text": "29 Kiahk, c''est le repère de Noël.", "translation": "Pas besoin de dire le 25 décembre."}], "unitId": "eg.v.noel_copte"}'::jsonb, '1.0.0') on conflict (id) do update set word = excluded.word, translation = excluded.translation, definition = excluded.definition, examples = excluded.examples, pronunciation = excluded.pronunciation, data = excluded.data, content_version = excluded.content_version;
